(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("plut-lives-4-e", [{"sp": "HDR", "t": "Βίοι Παράλληλοι"}, {"sp": "HDR", "t": "Ἀγησίλαος"}, {"sp": "N", "t": "Ἀρχίδαμος ὁ Ζευξιδάμου βασιλεύσας ἐπιφανῶς Λακεδαιμονίων, κατέλιπεν υἱὸν ἐκ γυναικὸς εὐδοκίμου, Λαμπιδοῦς, Ἆγιν, καί πολὺ νεώτερον ἐξ Εὐπωλίας τῆς Μελησιππίδα θυγατρός, Ἀγησίλαον. ἐπεὶ δὲ τῆς βασιλείας Ἄγιδι προσηκούσης κατὰ τὸν νόμον ἰδιώτης ἐδόκει βιοτεύσειν ὁ Ἀγησίλαος, ἤχθη τὴν λεγομένην ἀγωγὴν ἐν Λακεδαίμονι, σκληρὰν μὲν οὖσαν τῇ διαίτῃ καί πολύπονον, παιδεύουσαν δὲ τοὺς νέους ἄρχεσθαι. διὸ καί φασιν ὑπὸ τοῦ Σιμωνίδου τὴν Σπάρτην προσηγορεῦσθαι δαμασίμβροτον, ὡς μάλιστα διὰ τῶν ἐθῶν τοὺς πολίτας τοῖς νόμοις πειθηνίους καὶ χειροήθεις ποιοῦσαν, ὥσπερ ἵππους εὐθὺς ἐξ ἀρχῆς δαμαζομένους, ταύτης ἀφίησιν ὁ νόμος τῆς ἀνάγκης τοὺς ἐπὶ βασιλείᾳ τρεφομένους παῖδας. Ἀγησιλάῳ δὲ καί τοῦτο ὑπῆρξεν ἴδιον, ἐλθεῖν ἐπὶ τὸ ἄρχειν μὴ ἀπαίδευτον τοῦ ἄρχεσθαι. διὸ καί πολὺ τῶν βασιλέων εὐαρμοστότατον αὑτὸν τοῖς ὑπηκόοις παρέσχε, τῷ φύσει ἡγεμονικῷ καί βασιλικῷ προσκτησάμενος ἀπὸ τῆς ἀγωγῆς τὸ δημοτικὸν καί φιλάνθρωπον.", "st": "Ages. 1.1"}, {"sp": "N", "t": "ἐν δὲ ταῖς καλουμέναις ἀγέλαις τῶν συντρεφομένων παίδων Λύσανδρον ἔσχεν ἐραστήν, ἐκπλαγέντα μάλιστα τῷ κοσμίῳ τῆς φύσεως αὐτοῦ. φιλονεικότατος γὰρ ὢν καὶ θυμοειδέστατος ἐν τοῖς νέοις καὶ πάντα πρωτεύειν βουλόμενος, καὶ τὸ σφοδρὸν ἔχων καὶ ῥαγδαῖον ἄμαχον καὶ δυσεκβίαστον, εὐπειθείᾳ πάλιν αὖ καὶ πρᾳότητι τοιοῦτος ἦν οἷος φόβῳ μηδέν, αἰσχύνῃ δὲ πάντα ποιεῖν τὰ προσταττόμενα, καὶ τοῖς ψόγοις ἀλγύνεσθαι μᾶλλον ἢ τοὺς πόνους βαρύνεσθαι· τὴν δὲ τοῦ σκέλους πήρωσιν ἥ τε ὥρα τοῦ σώματος ἀνθοῦντος ἐπέκρυπτε, καὶ τὸ ῥᾳδίως φέρειν καὶ ἱλαρῶς τὸ τοιοῦτο, παίζοντα καὶ σκώπτοντα πρῶτον ἑαυτόν, οὐ μικρὸν ἦν ἐπανόρθωμα τοῦ πάθους, ἀλλὰ καὶ τὴν φιλοτιμίαν ἐκδηλοτέραν ἐποίει, πρὸς μηδένα πόνον μηδὲ πρᾶξιν ἀπαγορεύοντος αὐτοῦ διὰ τὴν χωλότητα, τῆς δὲ μορφῆς εἰκόνα μὲν οὐκ ἔχομεν αὐτὸς γὰρ οὐκ ἠθέλησεν, ἀλλὰ καὶ ἀποθνήσκων ἀπεῖπε μήτε πλαστὰν μήτε μιμηλάν τινα ποιήσασθαι τοῦ σώματος εἰκόνα, λέγεται δὲ μικρός τε γενέσθαι καὶ τὴν ὄψιν εὐκαταφρόνητος· ἡ δὲ ἱλαρότης καὶ τὸ εὔθυμον ἐν ἅπαντι καιρῷ καὶ παιγνιῶδες, ἀχθεινὸν δὲ καὶ τραχὺ μηδέποτε μήτε φωνῇ μήτε ὄψει, τῶν καλῶν καὶ ὡραίων ἐρασμιώτερον αὐτὸν ἄχρι γήρως παρεῖχεν. ὡς δὲ Θεόφραστος ἱστορεῖ, τὸν Ἀρχίδαμον ἐζημίωσαν οἱ ἔφοροι γήμαντα γυναῖκα μικράν· οὐ γὰρ βασιλεῖς ἔφασαν, ἄμμιν, ἀλλὰ βασιλείδια γεννάσει.", "st": "Ages. 2.1"}, {"sp": "N", "t": "βασιλεύοντος δὲ Ἄγιδος ἧκεν Ἀλκιβιάδης ἐκ Σικελίας φυγὰς εἰς Λακεδαίμονα· καὶ χρόνον οὔπω πολὺν ἐν τῇ πόλει διάγων, αἰ, τίαν ἔσχε τῇ γυναικὶ τὸν βασιλέως, Τιμαίᾳ, συνεῖναι. καὶ τὸ γεννηθὲν ἐξ αὐτῆς παιδάριον οὐκ ἔφη γινώσκειν ὁ Ἆγις, ἀλλ’ ἐξ Ἀλκιβιάδου γεγονέναι. τοῦτο δὲ οὐ πάνυ δυσκόλως τὴν Τιμαίαν ἐνεγκεῖν φησι Δοῦρις, ἀλλὰ καὶ ψιθυρίζουσαν οἴκοι πρὸς τὰς εἱλωτίδας Ἀλκιβιάδην τὸ παιδίον, οὐ Λεωτυχίδην, καλεῖν· καὶ μέντοι καὶ τὸν Ἀλκιβιάδην αὐτὸν οὐ πρὸς ὕβριν τῇ Τιμαίᾳ φάναι πλησιάζειν, ἀλλὰ φιλοτιμούμενον βασιλεύεσθαι Σπαρτιάτας ὑπὸ τῶν ἐξ ἑαυτοῦ γεγονότων. διὰ ταῦτα μὲν τῆς Λακεδαίμονος Ἀλκιβιάδης ὑπεξῆλθε, φοβηθεὶς τὸν Ἆγιν ὁ δὲ παῖς τὸν μὲν ἄλλον χρόνον ὕποπτος ἦν τῷ Ἄγιδι, καὶ γνησίου τιμὴν οὐκ εἶχε παρ’ αὐτῷ, νοσοῦντι δὲ προσπεσὼν καὶ δακρύων ἔπεισεν υἱὸν ἀποφῆναι πολλῶν ἐναντίον.", "st": "Ages. 3.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τελευτήσαντος τοῦ Ἄγιδος ὁ Λύσανδρος, ἤδη κατανεναυμαχηκὼς Ἀθηναίους καὶ μέγιστον ἐν Σπάρτῃ δυνάμενος, τὸν Ἀγησίλαον ἐπὶ τὴν βασιλείαν προῆγεν, ὡς οὐ προσήκουσαν ὄντι νόθῳ τῷ Λεωτυχίδῃ. πολλοὶ δὲ καὶ τῶν ἄλλων πολιτῶν, διὰ τὴν ἀρετὴν τοῦ Ἀγησιλάου καὶ τὸ συντετράφθαι καὶ μετεσχηκέναι τῆς ἀγωγῆς, ἐφιλοτιμοῦντο καὶ συνέπραττον αὐτῷ προθύμως. ἦν δὲ Διοπείθης ἀνὴρ χρησμολόγος ἐν Σπάρτῃ, μαντειῶν τε παλαιῶν ὑπόπλεως καὶ δοκῶν περὶ τὰ θεῖα σοφὸς εἶναι καὶ περιττός. οὗτος οὐκ ἔφη θεμιτὸν εἶναι χωλὸν γενέσθαι τῆς Λακεδαίμονος βασιλέα, καὶ χρησμὸν ἐν τῇ δίκῃ; τοιοῦτον ἀνεγίνωσκε·", "st": "Ages. 3.3"}, {"sp": "N", "t": "φράζεο δή, Σπάρτη, καίπερ μεγάλαυχος ἐοῦσα,<br>μὴ σέθεν ἀρτίποδος βλάστῃ χωλὴ βασιλεία<br>δηρὸν γὰρ νοῦσοί σε κατασχήσουσιν ἄελπτοι<br>φθισιβρότου τ’ ἐπὶ κῦμα κυλινδόμενον πολέμοιο.", "st": "Ages. 3.3b"}, {"sp": "N", "t": "πρὸς ταῦτα Λύσανδρος ἔλεγεν ὡς, εἰ πάνυ φοβοῖντο τὸν χρησμὸν οἱ Σπαρτιᾶται, φυλακτέον αὐτοῖς εἴη τὸν Λεωτυχίδην οὐ γὰρ εἰ προσπταίσας τις τὸν πόδα βασιλεύοι, τῷ θεῷ διαφέρειν, ἀλλ’ εἰ μὴ γνήσιος ὢν μηδὲ Ἡρακλείδης, τοῦτο τὴν χωλὴν εἶναι βασιλείαν. ὁ δὲ Ἀγησίλαος ἔφη καὶ τὸν Ποσειδῶ καταμαρτυρεῖν τοῦ Λεωτυχίδου τὴν νοθείαν, ἐκβαλόντα σεισμῷ τοῦ θαλάμου τὸν Ἆγιν ἀπ’ ἐκείνου δὲ πλέον ἢ δέκα μηνῶν διελθόντων γενέσθαι τὸν Λεωτυχίδην.", "st": "Ages. 3.5"}, {"sp": "N", "t": "οὕτω δὲ καὶ διὰ ταῦτα βασιλεὺς ἀποδειχθεὶς ὁ Ἀγησίλαος εὐθὺς εἶχε καὶ τὰ χρήματα τοῦ Ἄγιδος, ὡς νόθον ἀπελάσας τὸν Λεωτυχίδην. ὁρῶν δέ τοὺς ἀπὸ μητρὸς οἰκείους ἐπιεικεῖς μὲν ὄντας, ἰσχυρῶς δέ πενομένους, ἀπένειμεν αὐτοῖς τὰ ἡμίσεα τῶν χρημάτων, εὔνοιαν ἑαυτῷ καὶ δόξαν ἀντὶ φθόνου καὶ δυσμενείας ἐπὶ τῇ κληρονομίᾳ κατασκευαζόμενος. ὃ δέ φησιν ὁ Ξενοφῶν, ὅτι πάντα τῇ πατρίδι πειθόμενος ἴσχυε πλεῖστον, ὥστε ποιεῖν ὃ βούλοιτο, τοιοῦτόν ἐστι. τῶν ἐφόρων ἦν τότε καὶ τῶν γερόντων τὸ μέγιστον ἐν τῇ πολιτείᾳ κράτος, ὧν οἱ μὲν ἐνιαυτὸν ἄρχουσι μόνον, οἱ δὲ γέροντες διὰ βίου ταύτην ἔχουσι τὴν τιμήν, ἐπὶ τῷ μὴ πάντα τοῖς βασιλεῦσιν ἐξεῖναι συνταχθέντες, ὡς ἐν τοῖς περὶ Λυκούργου γέγραπται· διὸ καὶ πατρικήν τινα πρὸς αὐτοὺς ἀπὸ τοῦ παλαιοῦ διετέλουν εὐθὺς οἱ βασιλεῖς φιλονεικίαν καὶ διαφορὰν παραλαμβάνοντες. ὁ δὲ Ἀγησίλαος ἐπὶ τὴν ἐναντίαν ὁδὸν ἦλθε, καὶ τὸ πολεμεῖν καὶ τὸ προσκρούειν αὐτοῖς ἐάσας ἐθεράπευε, πάσης μὲν ἀπ’ ἐκείνων πράξεως ἀρχόμενος, εἰ δὲ κληθείη, θᾶττον ἢ βάδην ἐπειγόμενος, ὁσάκις δὲ τύχοι καθήμενος ἐν τῷ βασιλικῷ θώκῳ καὶ χρηματίζων, ἐπιοῦσι τοῖς ἐφόροις ὑπεξανίστατο, τῶν δ’ εἰς τὴν γερουσίαν ἀεὶ καταταττομένων ἑκάστῳ χλαῖναν ἔπεμπε καὶ βοῦν ἀριστεῖον. ἐκ δὲ τούτων τιμᾶν δοκῶν καὶ μεγαλύνειν τὸ ἀξίωμα τῆς ἐκείνων ἀρχῆς, ἐλάνθανεν αὔξων τὴν ἑαυτοῦ δύναμιν καὶ τῇ βασιλείᾳ προστιθέμενος μέγεθος ἐκ τῆς πρὸς αὐτὸν εὐνοίας συγχωρούμενον.", "st": "Ages. 4.1"}, {"sp": "N", "t": "ἐν δὲ ταῖς πρὸς τοὺς ἄλλους πολίτας ὁμιλίαις ἐχθρὸς ἦν ἀμεμπτότερος ἢ φίλος, τοὺς μὲν γὰρ ἐχθροὺς ἀδίκως οὐκ ἔβλαπτε, τοῖς δὲ φίλοις καὶ τὰ μὴ δίκαια συνέπραττε. καὶ τοὺς μὲν ἐχθροὺς ᾐσχύνετο μὴ τιμᾶν κατορθοῦντας, τοὺς δὲ φίλους οὐκ ἐδύνατο ψέγειν ἁμαρτάνοντας, ἀλλὰ καὶ βοηθῶν ἠγάλλετο καὶ συνεξαμαρτάνων αὐτοῖς· οὐδὲν γὰρ ᾤετο τῶν φιλικῶν ὑπουργημάτων αἰσχρὸν εἶναι. τοῖς δ’ αὖ διαφόροις πταίσασι πρῶτος συναχθόμενος καὶ δεηθεῖσι συμπράττων προθύμως ἐδημαγώγει καὶ προσήγετο πάντας. ὁρῶντες οὖν οἱ ἔφοροι ταῦτα καὶ φοβούμενοι τὴν δύναμιν ἐζημίωσαν αὐτόν, αἰτίαν ὑπειπόντες ὅτι τοὺς κοινοὺς πολίτας ἰδίους κτᾶται.", "st": "Ages. 5.1"}, {"sp": "N", "t": "καθάπερ γὰρ οἱ φυσικοὶ τὸ νεῖκος οἴονταί καὶ τὴν ἔριν, εἰ τῶν ὅλων ἐξαιρεθείη, στῆναι μὲν ἂν τὰ οὐράνια, παύσασθαι δὲ πάντων τὴν γένεσιν καὶ κίνησιν ὑπὸ τῆς πρὸς πάντα πάντων ἁρμονίας, οὕτως ἔοικεν ὁ Λακωνικὸς νομοθέτης ὑπέκκαυμα τῆς ἀρετῆς ἐμβαλεῖν εἰς τὴν πολιτείαν τὸ φιλότιμον καὶ φιλόνεικον, ἀεί τινα τοῖς ἀγαθοῖς διαφορὰν καὶ ἅμιλλαν εἶναι πρὸς ἀλλήλους βουλόμενος, τὴν δὲ ἀνθυπείκουσαν τῷ ἀνελέγκτῳ χάριν ἀργὴν καὶ ἀναγώνιστον οὖσαν οὐκ ὀρθῶς ὁμόνοιαν λέγεσθαι. τοῦτο δὲ ἀμέλει συνεωρακέναι καὶ τὸν Ὅμηρον οἴονταί τινες· οὐ γὰρ ἂν τὸν Ἀγαμέμνονα ποιῆσαι χαίροντα τοῦ Ὀδυσσέως καὶ τοῦ Ἀχιλλέως εἰς λοιδορίαν προαχθέντων ἐκπάγλοις ἐπέεσσιν, εἰ μὴ μέγα τοῖς κοινοῖς ἀγαθὸν ἐνόμιζεν εἶναι τὸν πρὸς ἀλλήλους ζῆλον καὶ τὴν διαφορὰν τῶν ἀρίστων, ταῦτα μὲν οὖν οὐκ ἂν οὕτως τις ἁπλῶς συγχωρήσειεν αἱ γὰρ ὑπερβολαὶ τῶν φιλονεικιῶν χαλεπαὶ ταῖς πόλεσι καὶ μεγάλους κινδύνους ἔχουσι.", "st": "Ages. 5.3"}, {"sp": "N", "t": "τοῦ δὲ Ἀγησιλάου τὴν βασιλείαν νεωστὶ παρειληφότος, ἀπήγγελλόν τινες ἐξ Ἀσίας ἥκοντες ὡς ὁ Περσῶν βασιλεὺς παρασκευάζοιτο μεγάλῳ στόλῳ Λακεδαιμονίους ἐκβαλεῖν τῆς θαλάσσης. ὁ δὲ Λύσανδρος ἐπιθυμῶν αὖθις εἰς Ἀσίαν ἀποσταλῆναι καὶ βοηθῆσαι τοῖς φίλοις, οὓς αὐτὸς μὲν ἄρχοντας καὶ κυρίους τῶν πόλεων ἀπέλιπε, κακῶς δὲ χρώμενοι καὶ βιαίως τοῖς πράγμασιν ἐξέπιπτον ὑπὸ τῶν πολιτῶν καὶ ἀπέθνησκον, ἀνέπεισε τὸν Ἀγησίλαον ἐπιθέσθαι τῇ στρατείᾳ καὶ προπολεμῆσαι τῆς Ἑλλάδος, ἀπωτάτω διαβάντα καὶ φθάσαντα τὴν τοῦ βαρβάρου παρασκευήν. ἅμα δὲ τοῖς ἐν Ἀσίᾳ φίλοις ἐπέστελλε πέμπειν εἰς Λακεδαίμονα καὶ στρατηγὸν Ἀγησίλαον αἰτεῖσθαι. παρελθὼν οὖν εἰς τὸ πλῆθος Ἀγησίλαος ἀνεδέξατο τὸν πόλεμον, εἰ δοῖεν αὐτῷ τριάκοντα μὲν ἡγεμόνας καὶ συμβούλους Σπαρτιάτας, νεοδαμώδεις δὲ λογάδας δισχιλίους, τὴν δὲ συμμαχικὴν εἰς ἑξακισχιλίους δύναμιν. συμπράττοντος δὲ τοῦ Λυσάνδρου πάντα προθύμως ἐψηφίσαντο, καὶ τὸν Ἀγησίλαον ἐξέπεμπον εὐθὺς ἔχοντα τοὺς τριάκοντα Σπαρτιάτας, ὧν ὁ Λύσανδρος ἦν πρῶτος, οὐ διὰ τὴν ἑαυτοῦ δόξαν καὶ δύναμιν μόνον, ἀλλὰ καὶ διὰ τὴν Ἀγησιλάου φιλίαν, ᾧ μεῖζον ἐδόκει τῆς βασιλείας ἀγαθὸν διαπεπρᾶχθαι τὴν στρατηγίαν ἐκείνην.", "st": "Ages. 6.1"}, {"sp": "N", "t": "ἀθροιζομένης δὲ τῆς δυνάμεως εἰς Γεραιστόν, αὐτὸς εἰς Αὐλίδα κατελθὼν μετὰ τῶν φίλων καὶ νυκτερεύσας ἔδοξε κατὰ τοὺς ὕπνους εἰπεῖν τινα πρὸς αὐτόν· ὦ βασιλεῦ Λακεδαιμονίων, ὅτι μὲν οὐδεὶς τῆς Ἑλλάδος ὁμοῦ συμπάσης ἀπεδείχθη στρατηγὸς ἢ πρότερον Ἀγαμέμνων καὶ σὺ νῦν μετ’ ἐκεῖνον, ἐννοεῖς δήπουθεν ἐπεὶ δὲ τῶν μὲν αὐτῶν ἄρχεις ἐκείνῳ, τοῖς δὲ αὐτοῖς πολεμεῖς, ἀπὸ δὲ τῶν αὐτῶν τόπων ὁρμᾷς ἐπὶ τὸν πόλεμον, εἰκός ἐστι καὶ θῦσαί σε τῇ θεῷ θυσίαν ἣν ἐκεῖνος ἐνταῦθα θύσας ἐξέπλευσεν. ἅμα δέ πως ὑπῆλθε τὸν Ἀγησίλαον ὁ τῆς κόρης σφαγιασμός, ἣν ὁ πατὴρ ἔσφαξε πεισθεὶς τοῖς μάντεσιν. οὐ μὴν διετάραξεν αὐτόν, ἀλλ’ ἀναστὰς καὶ διηγησάμενος τοῖς φίλοις τὰ φανέντα τὴν μὲν θεὸν ἔφη τιμήσειν οἷς εἰκός ἐστι χαίρειν θεὸν οὖσαν, οὐ μιμήσεσθαι δὲ τὴν ἀπάθειαν τοῦ τότε στρατηγοῦ, καὶ καταστέψας ἔλαφον ἐκέλευσεν ἀπάρξασθαι τὸν ἑαυτοῦ μάντιν, οὐχ ὥσπερ εἰώθει τοῦτο ποιεῖν ὁ ὑπὸ τῶν Βοιωτῶν τεταγμένος. ἀκούσαντες οὖν οἱ βοιωτάρχαι πρὸς ὀργὴν κινηθέντες ἔπεμψαν ὑπηρέτας, ἀπαγορεύοντες τῷ Ἀγησιλάῳ μὴ θύειν παρὰ τοὺς νόμους καὶ τὰ πάτρια Βοιωτῶν, οἱ δὲ καὶ ταῦτα ἀπήγγειλαν καὶ τὰ μηρία διέρριψαν ἀπὸ τοῦ βωμοῦ, χαλεπῶς οὖν ἔχων ὁ Ἀγησίλαος ἀπέπλει, τοῖς τε Θηβαίοις διωργισμένος καὶ γεγονὼς δύσελπις διὰ τὸν οἰωνόν, ὡς ἀτελῶν αὐτῷ τῶν πράξεων γενησομένων καὶ τῆς στρατείας ἐπὶ τὸ προσῆκον οὐκ ἀφιξομένης.", "st": "Ages. 6.4"}, {"sp": "N", "t": "ἐπεὶ δὲ ἧκεν εἰς Ἔφεσον, εὐθὺς ἀξίωμα μέγα καὶ δύναμις ἦν ἐπαχθὴς καὶ βαρεῖα περὶ τὸν Λύσανδρον, ὄχλου φοιτῶντος ἐπὶ τὰς θύρας ἑκάστοτε καὶ πάντων παρακολουθούντων καὶ θεραπευόντων ἐκεῖνον, ὡς ὄνομα μὲν καὶ σχῆμα τῆς στρατηγίας τὸν Ἀγησίλαον ἔχοντα, διὰ τὸν νόμον, ἔργῳ δὲ κύριον ὄντα ἁπάντων καὶ δυνάμενον καὶ πράττοντα πάντα τὸν Λύσανδρον. οὐδεὶς γὰρ δεινότερος οὐδὲ φοβερώτερος ἐκείνου τῶν εἰς τὴν Ἀσίαν ἀποσταλέντων ἐγένετο στρατηγῶν, οὐδὲ μείζονα τοὺς φίλους ἀνὴρ ἄλλος εὐεργέτησεν οὐδὲ κακὰ τηλικαῦτα τοὺς ἐχθροὺς ἐποίησεν. ὧν ἔτι προσφάτων ὄντων οἱ ἄνθρωποι μνημονεύοντες, ἄλλως δὲ τὸν μὲν Ἀγησίλαον ἀφελῆ καὶ λιτὸν ἐν ταῖς ὁμιλίαις καὶ δημοτικὸν ὁρῶντες, ἐκείνῳ δὲ τὴν αὐτὴν ὁμοίως σφοδρότητα καὶ τραχύτητα καὶ βραχυλογίαν παροῦσαν, ὑπέπιπτον αὐτῷ παντάπασι καὶ μόνῳ προσεῖχον. ἐκ δὲ τούτου πρῶτον μὲν οἱ λοιποὶ Σπαρτιᾶται χαλεπῶς ἔφερον ὑπηρέται Λυσάνδρου μᾶλλον ἢ σύμβουλοι βασιλέως ὄντες ἔπειτα δ’ αὐτὸς ὁ Ἀγησίλαος, εἰ καὶ μὴ φθονερὸς ἦν μηδὲ ἤχθετο τοῖς τιμωμένοις, ἀλλὰ φιλότιμος ὢν σφόδρα καὶ φιλόνεικος, ἐφοβεῖτο μή, κἂν ἐνέγκωσί τι λαμπρὸν αἱ πράξεις, τοῦτο Λυσάνδρου γένηται διὰ τὴν δόξαν. οὕτως οὖν ἐποίει.", "st": "Ages. 7.1"}, {"sp": "N", "t": "πρῶτον ἀντέκρουε ταῖς συμβουλίαις αὐτοῦ, καὶ πρὸς ἃς ἐκεῖνος ἐσπουδάκει μάλιστα πράξεις ἐῶν χαίρειν καὶ παραμελῶν, ἕτερα πρὸ ἐκείνων ἔπραττεν ἔπειτα τῶν ἐντυγχανόντων καὶ δεομένων οὓς αἴσθοιτο Λυσάνδρῳ μάλιστα πεποιθότας, ἀπράκτους ἀπέπεμπε· καὶ περὶ τὰς κρίσεις ὁμοίως οἷς ἐκεῖνος ἐπηρεάζοι, τούτους ἔδει πλέον ἔχοντας ἀπελθεῖν, καὶ τοὐναντίον οὓς φανερὸς γένοιτο προθυμούμενος ὠφελεῖν, χαλεπὸν ἦν μὴ καὶ ζημιωθῆναι. γινομένων δὲ τούτων οὐ κατὰ τύχην, ἀλλ’ οἷον ἐκ παρασκευῆς καὶ ὁμαλῶς, αἰσθόμενος τὴν αἰτίαν ὁ Λύσανδρος οὐκ ἀπεκρύπτετο πρὸς τοὺς φίλους, ἀλλ’ ἔλεγεν ὡς δι’ αὐτὸν ἀτιμάζοιντο, καὶ παρεκάλει θεραπεύειν ἰόντας τὸν βασιλέα καὶ τοὺς μᾶλλον αὐτοῦ δυναμένους.", "st": "Ages. 7.4"}, {"sp": "N", "t": "ὡς οὖν ταῦτα πράττειν καὶ λέγειν ἐδόκει φθόνον ἐκείνῳ μηχανώμενος, ἔτι μᾶλλον αὐτοῦ καθάψασθαι βουλόμενος Ἀγησίλαος ἀπέδειξε κρεοδαίτην καὶ προσεῖπεν, ὡς λέγεται, πολλῶν ἀκουόντων νῦν οὖν θεραπευέτωσαν οὗτοι ἀπιόντες τὸν ἐμὸν κρεοδαίτην. ἀχθόμενος οὖν ὁ Λύσανδρος λέγει πρὸς αὐτόν· ᾔδεις ἄρα σαφῶς, Ἀγησίλαε, φίλους ἐλαττοῦν. νὴ Δί’, ἔφη, τοὺς ἐμοῦ μεῖζον δύνασθαι βουλομένους. καὶ ὁ Λύσανδρος, ἀλλ’ ἴσως, ἔφη, ταῦτα σοὶ λέλεκται βέλτιον ἢ ἐμοὶ πέπρακται. δὸς δέ μοι τινὰ τάξιν καὶ χώραν ἔνθα μὴ λυπῶν ἔσομαί σοι χρήσιμος. ἐκ τούτου πέμπεται μὲν ἐφ’ Ἑλλήσποντον, καὶ Σπιθριδάτην, ἄνδρα Πέρσην, ἀπὸ τῆς Φαρναβάζου χώρας μετὰ χρημάτων συχνῶν καὶ διακοσίων ἱππέων ἤγαγε πρὸς τὸν Ἀγησίλαον, οὐκ ἔληγε δὲ τῆς ὀργῆς, ἀλλὰ βαρέως φέρων ἤδη τὸν λοιπὸν χρόνον ἐβούλευεν ὅπως τῶν δυεῖν οἴκων τὴν βασιλείαν ἀφελόμενος εἰς μέσον ἅπασιν ἀποδοίη Σπαρτιάταις, καὶ ἐδόκει μεγάλην ἂν ἀπεργάσασθαι κίνησιν ἐκ ταύτης τῆς διαφορᾶς, εἰ μὴ πρότερον ἐτελεύτησεν εἰς Βοιωτίαν στρατεύσας. οὕτως αἱ φιλότιμοι φύσεις ἐν ταῖς πολιτείαις, τὸ ἄγαν μὴ φυλαξάμεναι, τοῦ ἀγαθοῦ μεῖζον τὸ κακὸν ἔχουσι. καὶ γὰρ εἰ Λύσανδρος ἦν φορτικός, ὥσπερ ἦν, ὑπερβάλλων τῇ φιλοτιμίᾳ τὸν καιρόν, οὐκ ἠγνόει δήπουθεν Ἀγησίλαος ἑτέραν ἀμεμπτοτέραν ἐπανόρθωσιν οὖσαν ἀνδρὸς ἐνδόξου καὶ φιλοτίμου πλημμελοῦντος, ἀλλ’ ἔοικε ταὐτῷ πάθει μήτε ἐκεῖνος ἄρχοντος ἐξουσίαν γνῶναι μήτε οὗτος ἄγνοιαν ἐνεγκεῖν συνήθους.", "st": "Ages. 8.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Τισαφέρνης ἐν ἀρχῇ μὲν φοβηθεὶς τὸν Ἀγησίλαον ἐποιήσατο σπονδάς, ὡς τὰς πόλεις αὐτῷ τὰς Ἑλληνίδας ἀφήσοντος αὐτονόμους βασιλέως, ὕστερον δὲ πεισθεὶς ἔχειν δύναμιν ἱκανὴν ἐξήνεγκε τὸν πόλεμον, ἄσμενος ὁ Ἀγησίλαος ἐδέξατο. προσδοκία γὰρ ἦν μεγάλη τῆς στρατείας· καὶ δεινὸν ἡγεῖτο τοὺς μὲν σὺν Ξενοφῶντι μυρίους ἥκειν ἐπὶ θάλατταν, ὁσάκις ἐβουλήθησαν αὐτοὶ τοσαυτάκις βασιλέα νενικηκότας, αὐτοῦ δὲ Λακεδαιμονίων ἄρχοντος ἡγουμένων γῆς καὶ θαλάσσης μηδὲν ἔργον ἄξιον μνήμης φανῆναι πρὸς τοὺς Ἕλληνας, εὐθὺς οὖν ἀμυνόμενος ἀπάτῃ δικαίᾳ τὴν Τισαφέρνους ἐπιορκίαν, ἐπέδειξεν ὡς ἐπὶ Καρίαν προάξων, ἐκεῖ δὲ τὴν δύναμιν τοῦ βαρβάρου συναθροίσαντος ἄρας εἰς Φρυγίαν ἐνέβαλε. καὶ πόλεις μὲν εἷλε συχνὰς καὶ χρημάτων ἀφθόνων ἐκυρίευσεν, ἐπιδεικνύμενος τοῖς φίλοις ὅτι τὸ μὲν σπεισάμενον ἀδικεῖν τῶν θεῶν ἔστι καταφρονεῖν, ἐν δὲ τῷ παραλογίζεσθαι τοὺς πολεμίους οὐ μόνον τὸ δίκαιον, ἀλλὰ καὶ δόξα πολλὴ καὶ τὸ μεθ’ ἡδονῆς κερδαίνειν ἔνεστι. τοῖς δὲ ἱππεῦσιν ἐλαττωθεὶς καὶ τῶν ἱερῶν ἀλόβων φανέντων, ἀναχωρήσας εἰς Ἔφεσον ἱππικὸν συνῆγε, τοῖς εὐπόροις προειπών, εἰ μὴ βούλονται στρατεύεσθαι, παρασχεῖν ἕκαστον ἵππον ἀνθ’ ἑαυτοῦ καὶ ἄνδρα. πολλοὶ δ’ ἦσαν οὗτοι, καὶ συνέβαινε τῷ Ἀγησιλάῳ ταχὺ πολλοὺς καὶ πολεμικοὺς ἔχειν ἱππεῖς ἀντὶ δειλῶν ὁπλιτῶν, ἐμισθοῦντο γὰρ οἱ μὴ βουλόμενοι στρατεύεσθαι τοὺς βουλομένους στρατεύεσθαι, οἱ δὲ μὴ βουλόμενοι ἱππεύειν τοὺς βουλόμενοι ἱππεύειν. καὶ γὰρ τὸν Ἀγαμέμνονα ποιῆσαι καλῶς ὅτι θήλειαν ἵππον ἀγαθὴν λαβὼν κακὸν ἄνδρα καὶ πλούσιον ἀπήλλαξε τῆς στρατείας. ἐπεὶ δὲ κελεύσαντος αὐτοῦ τοὺς αἰχμαλώτους ἀποδύοντες ἐπίπρασκον οἱ λαφυροπῶλαι, καὶ τῆς μὲν ἐσθῆτος ἦσαν ὠνηταὶ πολλοί, τῶν δὲ σωμάτων λευκῶν καὶ ἁπαλῶν παντάπασι διὰ τὰς σκιατραφίας γυμνουμένων κατεγέλων ὡς ἀχρήστων καὶ μηδενὸς ἀξίων, ἐπιστὰς ὁ Ἀγησίλαος, οὗτοι μέν, εἶπεν, οἷς μάχεσθε, ταῦτα δὲ ὑπὲρ ὧν μάχεσθε.", "st": "Ages. 9.1"}, {"sp": "N", "t": "καιροῦ δὲ ὄντος αὖθις ἐμβαλεῖν εἰς τὴν πολεμίαν προεῖπεν εἰς Λυδίαν ἀπάξειν, οὐκέτι ψευδόμενος ἐνταῦθα τὸν Τισαφέρνην· ἀλλ’ ἐκεῖνος ἑαυτὸν ἐξηπάτησε, διὰ τὴν ἔμπροσθεν ἀπάτην ἀπιστῶν τῷ Ἀγησιλάῳ, καὶ νῦν γοῦν αὐτὸν ἅψεσθαι τῆς Καρίας νομίζων οὔσης δυσίππου πολὺ τῷ ἱππικῷ λειπόμενον. ἐπεὶ δέ, ὡς προεῖπεν, ὁ Ἀγησίλαος ἧκεν εἰς τὸ περὶ Σάρδεις πεδίον, ἠναγκάζετο κατὰ σπουδὴν ἐκεῖθεν αὖ βοηθεῖν ὁ Τισαφέρνης· καὶ τῇ ἵππῳ διεξελαύνων διέφθειρε πολλοὺς τῶν ἀτάκτως τὸ πεδίον πορθούντων. ἐννοήσας οὖν ὁ Ἀγησίλαος ὅτι τοῖς πολεμίοις οὔπω πάρεστι τὸ πεζόν, αὐτῷ δὲ τῆς δυνάμεως οὐδὲν ἄπεστιν, ἔσπευσε διαγωνίσασθαι. καὶ τοῖς μὲν ἱππεῦσιν ἀναμίξας τὸ πελταστικόν, ἐλαύνειν ἐκέλευσεν ὡς τάχιστα καὶ προσβάλλειν τοῖς ἐναντίοις, αὐτὸς δὲ εὐθὺς τοὺς ὁπλίτας ἐπῆγε, γενομένης δὲ τροπῆς τῶν βαρβάρων ἐπακολουθήσαντες οἱ Ἕλληνες ἔλαβον τὸ στρατόπεδον καὶ πολλοὺς ἀνεῖλον. ἐκ ταύτης τῆς μάχης οὐ μόνον ὑπῆρξεν αὐτοῖς ἄγειν καὶ φέρειν ἀδεῶς τὴν βασιλέως χώραν, ἀλλὰ καὶ δίκην ἐπιδεῖν Τισαφέρνην διδόντα, μοχθηρὸν ἄνδρα καὶ τῷ γένει τῶν Ἑλλήνων ἀπεχθέστατον. ἔπεμψε γὰρ εὐθέως ὁ βασιλεὺς Τιθραύστην ἐπ’ αὐτόν, ὃς ἐκείνου μὲν τὴν κεφαλὴν ἀπέτεμε, τὸν δὲ Ἀγησίλαον ἠξίου διαλυσάμενον ἀποπλεῖν οἴκαδε, καὶ χρήματα διδοὺς αὐτῷ προσέπεμψεν. ὁ δὲ τῆς μὲν εἰρήνης ἔφη τὴν πόλιν εἶναι κυρίαν, αὐτὸς δὲ πλουτίζων τοὺς στρατιώτας ἥδεσθαι μᾶλλον ἢ πλουτῶν αὐτός· καὶ ἄλλως γε μέντοι νομίζειν Ἕλληνας καλὸν οὐ δῶρα λαμβάνειν, ἀλλὰ λάφυρα παρὰ τῶν πολεμίων. ὅμως δὲ τῷ Τιθραύστῃ χαρίζεσθαι βουλόμενος, ὅτι τὸν κοινὸν ἐχθρὸν Ἑλλήνων ἐτετιμώρητο Τισαφέρνην, ἀπήγαγεν εἰς Φρυγίαν τὸ στράτευμα, λαβὼν ἐφόδιον παρ’ αὐτοῦ τριάκοντα τάλαντα.", "st": "Ages. 10.1"}, {"sp": "N", "t": "καὶ καθ’ ὁδὸν ὢν σκυτάλην δέχεται παρὰ τῶν οἴκοι τελῶν κελεύουσαν αὐτὸν ἄρχειν ἅμα καὶ τοῦ ναυτικοῦ, τοῦτο μόνῳ πάντων ὑπῆρξεν Ἀγησιλάῳ. καὶ μέγιστος μὲν ἦν ὁμολογουμένως καὶ τῶν τότε ζώντων ἐπιφανέστατος, ὡς εἴρηκέ που καὶ Θεόπομπος, ἑαυτῷ γε μὴν ἐδίδου δι’ ἀρετὴν φρονεῖν μεῖζον ἢ διὰ τὴν ἡγεμονίαν. τότε δὲ τοῦ ναυτικοῦ καταστήσας ἄρχοντα Πείσανδρον ἁμαρτεῖν ἔδοξεν, ὅτι πρεσβυτέρων καὶ φρονιμωτέρων παρόντων οὐ σκεψάμενος τὸ τῆς πατρίδος, ἀλλὰ τὴν οἰκειότητα τιμῶν καὶ τῇ γυναικὶ χαριζόμενος, ἧς ἀδελφὸς ἦν ὁ Πείσανδρος, ἐκείνῳ παρέδωκε τὴν ναυαρχίαν·", "st": "Ages. 10.6"}, {"sp": "N", "t": "αὐτὸς δὲ τὸν στρατὸν καταστήσας εἰς τὴν ὑπὸ Φαρναβάζῳ τεταγμένην χώραν οὐ μόνον ἐν ἀφθόνοις διῆγε πᾶσιν, ἀλλὰ καί χρήματα συνῆγε πολλά· καί προελθὼν ἄχρι Παφλαγονίας προσηγάγετο τὸν βασιλέα τῶν Παφλαγόνων, Κότυν, ἐπιθυμήσαντα τῆς φιλίας αὐτὸν δι’ ἀρετὴν καί πίστιν. ὁ δὲ Σπιθριδάτης, ὡς ἀποστὰς τοῦ Φαρναβάζου τὸ πρῶτον ἦλθε πρὸς τὸν Ἀγησίλαον, ἀεὶ συναπεδήμει καί συνεστράτευεν αὐτῷ, κάλλιστον υἱὸν μὲν ἔχων, Μεγαβάτην, οὗ παιδὸς ὄντος ἤρα σφοδρῶς Ἀγησίλαος, καλὴν δὲ καί θυγατέρα παρθένον ἐν ἡλικίᾳ γάμου, ταύτην ἔπεισε γῆμαι τὸν Κότυν ὁ Ἀγησίλαος· καί λαβὼν παρ’ αὐτοῦ χιλίους ἱππεῖς καί δισχιλίους πελταστὰς αὖθις ἀνεχώρησεν εἰς Φρυγίαν, καί κακῶς ἐποίει τὴν Φαρναβάζου χώραν οὐχ ὑπομένοντος οὐδὲ πιστεύοντος τοῖς ἐρύμασιν, ἀλλὰ ἔχων ἀεὶ τὰ πλεῖστα σὺν ἑαυτῷ τῶν τιμίων καί ἀγαπητῶν ἐξεχώρει καί ὑπέφευγεν ἄλλοτε ἀλλαχόσε τῆς χώρας μεθιδρυόμενος, μέχρι οὗ παραφυλάξας αὐτὸν ὁ Σπιθριδάτης καί παραλαβὼν Ἡριππίδαν τὸν Σπαρτιάτην ἔλαβε τὸ στρατόπεδον καί τῶν χρημάτων ἁπάντων ἐκράτησεν. ἔνθα δὴ πικρὸς ὢν ὁ Ἡριππίδας ἐξεταστὴς τῶν κλαπέντων, καί τοὺς βαρβάρους ἀναγκάζων ἀποτίθεσθαι, καί πάντα ἐφορῶν καί διερευνώμενος, παρώξυνε τὸν Σπιθριδάτην, ὥστε ἀπελθεῖν εὐθὺς εἰς Σάρδεις μετὰ τῶν Παφλαγόνων.", "st": "Ages. 11.1"}, {"sp": "N", "t": "τοῦτο λέγεται τῷ Ἀγησιλάῳ γενέσθαι πάντων ἀνιαρότατον. ἤχθετο μὲν γὰρ ἄνδρα γενναῖον ἀποβεβληκὼς τὸν Σπιθριδάτην καί σὺν αὐτῷ δύναμιν οὐκ ὀλίγην, ᾐσχύνετο δὲ τῇ διαβολῇ τῆς μικρολογίας καί ἀνελευθερίας, ἧς οὐ μόνον αὑτόν, ἀλλὰ καί τὴν πατρίδα καθαρεύουσαν ἀεὶ παρέχειν ἐφιλοτιμεῖτο. χωρὶς δὲ τῶν ἐμφανῶν τούτων ἔκνιζεν αὐτὸν οὐ μετρίως ὁ τοῦ παιδὸς ἔρως ἐνεσταγμένος, εἰ καί πάνυ παρόντος αὐτοῦ τῷ φιλονείκῳ χρώμενος ἐπειρᾶτο νεανικῶς ἀπομάχεσθαι πρὸς τὴν ἐπιθυμίαν. καί ποτε τοῦ Μεγαβάτου προσιόντος ὡς ἀσπασομένου καί φιλήσοντος ἐξέκλινεν. ἐπεὶ δὲ ἐκεῖνος αἰσχυνθεὶς ἐπαύσατο καί τὸ λοιπὸν ἄπωθεν ἤδη προσηγόρευεν, ἀχθόμενος αὖ πάλιν καί μεταμελόμενος τῇ φυγῇ τοῦ φιλήματος, ὁ Ἀγησίλαος προσεποιεῖτο θαυμάζειν ὅ τι δὴ παθὼν αὐτὸν ὁ Μεγαβάτης ἀπὸ στόματος οὐ φιλοφρονοῖτο. σὺ γὰρ αἴτιος. οἱ συνήθεις ἔφασαν, οὐχ ὑποστάς, ἀλλὰ τρέσας τὸ φίλημα τοῦ καλοῦ καί φοβηθείς· ἐπεὶ καί νῦν ἂν ἔλθοι σοι πεισθεὶς ἐκεῖνος ἐντὸς φιλήματος· ἀλλ’ ὅπως αὖθις οὐκ ἀποδειλιάσεις. χρόνον οὖν τινα πρὸς ἑαυτῷ γενόμενος ὁ Ἀγησίλαος καὶ διασιωπήσας, οὐδέν ἔφη, δεινὸν πείθειν ὑμᾶς ἐκεῖνον· ἐγὼ γάρ μοι δοκῶ τήναν τὰν μάχαν τὰν περὶ τοῦ φιλάματος ἅδιον ἂν μάχεσθαι πάλιν ἢ πάντα ὅσα τεθέαμαι χρυσία μοι γενέσθαι. τοιοῦτος μὲν ἦν τοῦ Μεγαβάτου παρόντος, ἀπελθόντος γε μὴν οὕτω περικαῶς ἔσχεν ὡς χαλεπὸν εἰπεῖν εἰ πάλιν αὖ μεταβαλομένου καὶ φανέντος ἐνεκαρτέρησε μὴ φιληθῆναι.", "st": "Ages. 11.5"}, {"sp": "N", "t": "μετὰ ταῦτα Φαρνάβαζος εἰς λόγους αὐτῷ συνελθεῖν ἠθέλησε, καὶ συνῆγεν ἀμφοτέρους ὢν ξένος ὁ Κυζικηνὸς Ἀπολλοφάνης. πρότερος δὲ μετὰ τῶν φίλων ὁ Ἀγησίλαος ἐλθὼν εἰς τὸ χωρίον, ὑπὸ σκιᾷ τινι πόας οὔσης βαθείας καταβαλὼν ἑαυτόν, ἐνταῦθα περιέμενε τὸν Φαρνάβαζον. ὁ δὲ ὡς ἐπῆλθεν, ὑποβεβλημένων αὐτῷ κωδίων τε μαλακῶν καὶ ποικίλων δαπίδων, αἰδεσθεὶς τὸν Ἀγησίλαον οὕτω κατακείμενον κατεκλίνη καὶ αὐτός, ὡς ἔτυχεν, ἐπὶ τῆς πόας χαμᾶζε, καίπερ ἐσθῆτα θαυμαστὴν λεπτότητι καὶ βαφαῖς ἐνδεδυκώς. ἀσπασάμενοι δὲ ἀλλήλους ὁ μὲν Φαρνάβαζος οὐκ ἠπόρει λόγων δικαίων, ἅτε δὴ πολλὰ καὶ μεγάλα Λακεδαιμονίοις χρήσιμος γεγονὼς ἐν τῷ πρὸς Ἀθηναίους πολέμῳ, νῦν δὲ πορθούμενος ὑπ’ αὐτῶν· ὁ δὲ Ἀγησίλαος, ὁρῶν τοὺς σὺν αὐτῷ Σπαρτιάτας ὑπ’ αἰσχύνης κύπτοντας εἰς τὴν γῆν καὶ διαποροῦντας ἀδικούμενον γὰρ ἑώρων τὸν Φαρνάβαζον, ἡμεῖς, εἶπεν, ὦ Φαρνάβαζε, καὶ φίλοι ὄντες πρότερον βασιλέως ἐχρώμεθα τοῖς ἐκείνου πράγμασι φιλικῶς καὶ νῦν πολέμιοι γεγονότες πολεμικῶς. ἓν οὖν καὶ σὲ τῶν βασιλέως κτημάτων ὁρῶντες εἶναι βουλόμενον, εἰκότως διὰ σοῦ βλάπτομεν ἐκεῖνον. ἀφ’ ἧς δ’ ἂν ἡμέρας σεαυτὸν ἀξιώσῃς Ἑλλήνων φίλον καὶ σύμμαχον μᾶλλον ἢ δοῦλον λέγεσθαι βασιλέως, ταύτην νόμιζε τὴν φάλαγγα καὶ τὰ ὅπλα καὶ τὰς ναῦς καὶ πάντας ἡμᾶς τῶν σῶν κτημάτων φύλακας εἶναι καὶ τῆς ἐλευθερίας, ἧς ἄνευ καλὸν ἀνθρώποις οὐδὲν οὐδὲ ζηλωτόν ἐστιν. ἐκ τούτου λέγει πρὸς αὐτὸν ὁ Φαρνάβαζος ἣν εἶχε διάνοιαν. ἐγὼ γάρ, εἶπεν, ἐὰν μὲν ἄλλον ἐκπέμψῃ βασιλεὺς στρατηγόν, ἔσομαι μεθ’ ὑμῶν, ἐὰν δ’ ἐμοὶ παραδῷ τὴν ἡγεμονίαν, οὐδὲν ἐλλείψω προθυμίας ἀμυνόμενος ὑμᾶς καὶ κακῶς ποιῶν ὑπὲρ ἐκείνου. ταῦτα δ’ ἀκούσας ὁ Ἀγησίλαος ἥσθη, καὶ τῆς δεξιᾶς αὐτοῦ λαβόμενος καὶ συνεξαναστάς, εἴθε, εἶπεν, ὦ Φαρνάβαζε, τοιοῦτος ὢν φίλος ἡμῖν γένοιο μᾶλλον ἢ πολέμιος.", "st": "Ages. 12.1"}, {"sp": "N", "t": "ἀπιόντος δὲ τοῦ Φαρναβάζου μετὰ τῶν φίλων, ὁ υἱὸς ὑπολειφθεὶς προσέδραμε τῷ Ἀγησιλάῳ καί μειδιῶν εἶπεν· ἐγώ σε ξένον, ὦ Ἀγησίλαε, ποιοῦμαι. καί παλτὸν ἔχων ἐν τῇ χειρὶ δίδωσιν αὐτῷ. δεξάμενος οὖν ὁ Ἀγησίλαος καί ἡσθεὶς τῇ τε ὄψει καί τῇ φιλοφροσύνῃ τοῦ παιδός, ἐπεσκόπει τοὺς παρόντας, εἴ τις ἔχοι τι τοιοῦτον οἷον ἀντιδοῦναι καλῷ καί γενναίῳ δῶρον. ἰδὼν δὲ ἵππον Ἰδαίου τοῦ γραφέως κεκοσμημένον φαλάροις, ταχὺ ταῦτα περισπάσας τῷ μειρακίῳ δίδωσι. καί τὸ λοιπὸν οὐκ ἐπαύετο μεμνημένος, ἀλλὰ καί χρόνῳ περιϊόντι τὸν οἶκον ἀποστερηθέντος αὐτοῦ καί φυγόντος ὑπὸ τῶν ἀδελφῶν εἰς Πελοπόννησον, ἰσχυρῶς ἐπεμελεῖτο. καί τι καί τῶν ἐρωτικῶν αὐτῷ συνέπραξεν. ἠράσθη γὰρ ἀθλητοῦ παιδὸς ἐξ Ἀθηνῶν ἐπεὶ δὲ μέγας ὢν καί σκληρὸς Ὀλυμπίασιν ἐκινδύνευσεν ἐκκριθῆναι, καταφεύγει πρὸς τὸν Ἀγησίλαον ὁ Πέρσης δεόμενος ὑπὲρ τοῦ παιδός· ὁ δὲ καί τοῦτο βουλόμενος αὐτῷ χαρίζεσθαι, μάλα μόλις διεπράξατο σὺν πολλῇ πραγματείᾳ.", "st": "Ages. 13.1"}, {"sp": "N", "t": "τἆλλα μὲν γὰρ ἦν ἀκριβὴς καί νόμιμος, ἐν δὲ τοῖς φιλικοῖς πρόφασιν ἐνόμιζεν εἶναι τὸ λίαν δίκαιον. φέρεται γοῦν ἐπιστόλιον αὐτοῦ πρὸς Ἱδριέα τὸν Κᾶρα τοιοῦτο· Νικίας εἰ μὲν μὴ ἀδικεῖ, ἄφες· εἰ δὲ ἀδικεῖ, ἡμῖν ἄφες· πάντως δὲ ἄφες. ἐν μὲν οὖν τοῖς πλείστοις τοιοῦτος ὑπὲρ τῶν φίλων ὁ Ἀγησίλαος· ἔστι δὲ ὅπου πρὸς τὸ συμφέρον ἐχρῆτο τῷ καιρῷ μᾶλλον, ὡς ἐδήλωσεν, ἀναζυγῆς αὐτῷ θορυβωδεστέρας γενομένης, ἀσθενοῦντα καταλιπὼν τὸν ἐρώμενον. ἐκείνου γὰρ δεομένου καί καλοῦντος αὐτὸν ἀπιόντα, μεταστραφεὶς εἶπεν ὡς χαλεπὸν ἐλεεῖν ἅμα καί φρονεῖν. τουτὶ μὲν Ἱερώνυμος ὁ φιλόσοφος ἱστόρηκεν.", "st": "Ages. 13.4"}, {"sp": "N", "t": "ἤδη δὲ περιϊόντος ἐνιαυτοῦ δευτέρου τῇ στρατηγίᾳ. πολὺς ἄνω λόγος ἐχώρει τοῦ Ἀγησιλάου, καὶ δόξα θαυμαστὴ κατεῖχε τῆς τε σωφροσύνης αὐτοῦ καὶ εὐτελείας καὶ μετριότητος, ἐσκήνου μὲν γὰρ ἀποδημῶν καθ’ αὑτὸν ἐν τοῖς ἁγιωτάτοις ἱεροῖς, ἃ μὴ πολλοὶ καθορῶσιν ἄνθρωποι πράττοντας ἡμᾶς, τούτων τοὺς θεοὺς ποιούμενος ἐπόπτας καὶ μάρτυρας· ἐν δὲ χιλιάσι στρατιωτῶν τοσαύταις οὐ ῥᾳδίως ἄν τις εἶδε φαυλοτέραν στιβάδα τῆς Ἀγησιλάου. πρός τε θάλπος οὕτω καὶ ψῦχος εἶχεν ὥσπερ μόνος ἀεὶ χρῆσθαι ταῖς ὑπὸ τοῦ θεοῦ κεκραμέναις ὥραις πεφυκώς. ἥδιστον δὲ θέαμα τοῖς κατοικοῦσι τὴν Ἀσίαν Ἕλλησιν ἦσαν οἱ πάλαι βαρεῖς καὶ ἀφόρητοι καὶ διαρρέοντες ὑπὸ πλούτου καὶ τρυφῆς ὕπαρχοι καὶ στρατηγοὶ δεδιότες καὶ θεραπεύοντες ἄνθρωπον ἐν τρίβωνι περιϊόντα λιτῷ, καὶ πρὸς ἓν ῥῆμα βραχὺ καὶ Λακωνικὸν ἁρμόζοντες ἑαυτοὺς καὶ μετασχηματίζοντες, ὥστε πολλοῖς ἐπῄει τὰ τοῦ Τιμοθέου λέγειν,", "st": "Ages. 14.1"}, {"sp": "N", "t": "Ἄρης τύραννος· χρυσὸν δὲ Ἕλλας οὐ δέδοικε.", "st": "Ages. 14.1b"}, {"sp": "N", "t": "κινουμένης δὲ τῆς Ἀσίας καὶ πολλαχοῦ πρὸς ἀπόστασιν ὑπεικούσης, ἁρμοσάμενος τὰς αὐτόθι πόλεις, καὶ ταῖς πολιτείαις δίχα φόνου καὶ φυγῆς ἀνθρώπων ἀποδοὺς τὸν προσήκοντα κόσμον, ἐγνώκει πρόσω χωρεῖν, καὶ τὸν πόλεμον διάρας ἀπὸ τῆς Ἑλληνικῆς θαλάττης, περὶ τὸν σώματος βασιλεῖ καὶ τῆς ἐν Ἐκβατάνοις καὶ Σούσοις εὐδαιμονίας διαμάχεσθαι, καὶ περισπάσαι πρῶτον αὐτοῦ τὴν σχολήν, ὡς μὴ καθέζοιτο τοὺς πολέμους βραβεύων τοῖς Ἕλλησι καὶ διαφθείρων τοὺς δημαγωγούς. ἐν τούτῳ δὲ ἀφικνεῖται πρὸς αὐτὸν Ἐπικυδίδας ὁ Σπαρτιάτης, ἀπαγγέλλων ὅτι πολὺς περιέστηκε τὴν Σπάρτην πόλεμος Ἑλληνικός, καὶ καλοῦσιν ἐκεῖνον οἱ ἔφοροι καὶ κελεύουσι τοῖς οἴκοι βοηθεῖν.", "st": "Ages. 15.1"}, {"sp": "N", "t": "ὦ βάρβαρ’ ἐξευρόντες Ἕλληνες κακά·", "st": "Ages. 15.1b"}, {"sp": "N", "t": "τί γὰρ ἄν τις ἄλλο τὸν φθόνον ἐκεῖνον προσείποι καὶ τὴν τότε σύστασιν καὶ σύνταξιν ἐφ’ ἑαυτοὺς τῶν Ἑλλήνων; οἳ τῆς τύχης ἄνω φερομένης ἐπελάβοντο, καὶ τὰ ὅπλα πρὸς τοὺς βαρβάρους βλέποντα καὶ τὸν πόλεμον ἤδη τῆς Ἑλλάδος ἐξῳκισμένον αὖθις εἰς ἑαυτοὺς ἔτρεψαν. οὐ γὰρ ἔγωγε συμφέρομαι τῷ Κορινθίῳ Δημαράτῳ μεγάλης ἡδονῆς ἀπολελεῖφθαι φήσαντι τοὺς μὴ θεασαμένους Ἕλληνας Ἀλέξανδρον ἐν τῷ Δαρείου θρόνῳ καθήμενον, ἀλλ’ εἰκότως ἄν οἶμαι δακρῦσαι, συννοήσαντας ὅτι ταῦτ’ Ἀλεξάνδρῳ καὶ Μακεδόσιν ἀπέλιπον οἳ τότε τοὺς τῶν Ἑλλήνων στρατηγοὺς περὶ Λεῦκτρα καὶ Κορώνειαν καὶ Κόρινθον καὶ Ἀρκαδίαν κατανήλωσαν.", "st": "Ages. 15.3"}, {"sp": "N", "t": "Ἀγησιλάῳ μέντοι οὐδὲν κρεῖσσον ἢ μεῖζόν ἐστι τῆς ἀναχωρήσεως ἐκείνης διαπεπραγμένον, οὐδὲ γέγονε παράδειγμα πειθαρχίας καὶ δικαιοσύνης ἕτερον κάλλιον. ὅπου γὰρ Ἀννίβας ἤδη κακῶς πράττων καὶ περιωθούμενος ἐκ τῆς Ἰταλίας μάλα μόλις ὑπήκουσε τοῖς ἐπὶ τὸν οἴκοι πόλεμον καλοῦσιν, Ἀλέξανδρος δὲ καὶ προσεπέσκωψε πυθόμενος τὴν πρὸς Ἆγιν Ἀντιπάτρου μάχην, εἰπών· ἔοικεν, ὦ ἄνδρες, ὅτε Δαρεῖον ἡμεῖς ἐνικῶμεν μὲν ἐνταῦθα, ἐκεῖ τις ἐν Ἀρκαδίᾳ γεγονέναι μυομαχία· πῶς οὐκ ἦν ἄξιον τὴν Σπάρτην μακαρίσαι τῆς Ἀγησιλάου τιμῆς πρὸς ταύτην καὶ πρὸς τοὺς νόμους τῆς εὐλαβείας; ὃς ἅμα τῷ τὴν σκυτάλην ἐλθεῖν εὐτυχίαν τοσαύτην καὶ δύναμιν παροῦσαν καὶ τηλικαύτας ἐλπίδας ὑφηγουμένας ἀφεὶς καὶ προέμενος εὐθὺς ἀπέπλευσεν ἀτελευτήτῳ ἐπὶ ἔργῳ, πολὺν ἑαυτοῦ πόθον τοῖς συμμάχοις ἀπολιπών, καὶ μάλιστα δὴ τὸν Ἐρασιστράτου τοῦ Φαίακος ἐλέγξας λόγον, εἰπόντος ὡς εἰσὶ δημοσίᾳ μὲν Λακεδαιμόνιοι βελτίονες, ἰδίᾳ δὲ Ἀθηναῖοι. βασιλέα γὰρ ἑαυτὸν καὶ στρατηγὸν ἄριστον ἐπιδειξάμενος, ἔτι βελτίονα καὶ ἡδίονα τοῖς χρωμένοις ἰδίᾳ φίλον καὶ συνήθη παρέσχε, τοῦ δὲ Περσικοῦ νομίσματος χάραγμα τοξότην ἔχοντος, ἀναζευγνύων ἔφη μυρίοις τοξόταις ὑπὸ βασιλέως ἐξελαύνεσθαι τῆς Ἀσίας· τοσούτων γὰρ εἰς Ἀθήνας καὶ Θήβας κομισθέντων καὶ διαδοθέντων τοῖς δημαγωγοῖς, ἐξεπολεμώθησαν οἱ δῆμοι πρὸς τοὺς Σπαρτιάτας.", "st": "Ages. 15.4"}, {"sp": "N", "t": "ὡς δὲ διαβὰς τὸν Ἑλλήσποντον ἐβάδιζε διὰ τῆς Θρᾴκης, ἐδεήθη μὲν οὐδενὸς τῶν βαρβάρων, πέμπων δὲ πρὸς ἑκάστους ἐπυνθάνετο πότερον ὡς φιλίαν ἢ ὡς πολεμίαν διαπορεύηται τὴν χώραν. οἱ μὲν οὖν ἄλλοι πάντες φιλικῶς ἐδέχοντο καὶ παρέπεμπον, ὡς ἕκαστος δυνάμεως εἶχεν οἱ δὲ καλούμενοι Τράλλεις, οἷς καὶ Ξέρξης ἔδωκεν, ὡς λέγεται, δῶρα, τῆς διόδου μισθὸν ᾔτουν τὸν Ἀγησίλαον ἑκατὸν ἀργυρίου τάλαντα καὶ τοσαύτας γυναῖκας. ὁ δὲ κατειρωνευσάμενος αὐτοὺς καὶ φήσας· τί οὖν οὐκ εὐθὺς ἦλθον ληψόμενοι; προῆγε, καὶ συμβαλὼν αὐτοῖς παρατεταγμένοις ἐτρέψατο καὶ διέφθειρε πολλούς, τὸ δ’ αὐτὸ καὶ τῷ βασιλεῖ τῶν Μακεδόνων ἐρώτημα προσέπεμψε· φήσαντος δὲ βουλεύσεσθαι, Βουλευέσθω τοίνυν ἐκεῖνος, εἶπεν, ἡμεῖς δὲ δὴ πορευόμεθα. Θαυμάσας οὖν τὴν τόλμαν αὐτοῦ καὶ δείσας ὁ βασιλεὺς ἐκέλευσεν ὡς φίλον προάγειν. τῶν δὲ Θετταλῶν τοῖς πολεμίοις συμμαχούντων ἐπόρθει τὴν χώραν. εἰς δὲ Λάρισσαν ἔπεμψε Ξενοκλέα καὶ Σκύθην περὶ φιλίας· συλληφθέντων δὲ τούτων καὶ παραφυλασσομένων οἱ μὲν ἄλλοι βαρέως φέροντες ᾤοντο δεῖν τὸν Ἀγησίλαον περιστρατοπεδεύσαντα πολιορκεῖν τὴν Λάρισσαν, ὁ δὲ φήσας οὐκ ἂν ἐθελῆσαι Θεσσαλίαν ὅλην λαβεῖν ἀπολέσας τῶν ἀνδρῶν τὸν ἕτερον, ὑποσπόνδους αὐτοὺς ἀπέλαβε. καὶ τοῦτ’ ἴσως ἐπ’ Ἀγησιλάῳ θαυμαστὸν οὐκ ἦν, ὃς πυθόμενος μάχην μεγάλην γεγονέναι περὶ Κόρινθον, καὶ ἄνδρας τῶν πάνυ ἐνδόξων ὡς ἔνι μάλιστα αἰφνίδιον ἀπολωλέναι, καὶ Σπαρτιατῶν μὲν ὀλίγους παντάπασι τεθνηκέναι, παμπόλλους δὲ τῶν πολεμίων, οὐκ ὤφθη περιχαρὴς οὐδὲ ἐπηρμένος, ἀλλὰ καὶ πάνυ βαρὺ στενάξας, φεῦ τῆς Ἑλλάδος, ἔφη, τοσούτους ἄνδρας ἀπολωλεκυίας ὑφ’ αὑτῆς, ὅσοι ζῶντες ἐδύναντο νικᾶν ὁμοῦ σύμπαντας τοὺς βαρβάρους μαχόμενοι. τῶν δὲ Φαρσαλίων προσκειμένων αὑτῷ καὶ κακούντων τὸ στράτευμα, πεντακοσίοις ἱππεῦσιν ἐμβαλεῖν κελεύσας σὺν αὑτῷ καὶ τρεψάμενος ἔστησε τρόπαιον ὑπὸ τῷ Ναρθακίῳ. καὶ τὴν νίκην ὑπερηγάπησεν ἐκείνην, ὅτι συστησάμενος ἱππικὸν αὐτὸς δι’ ἑαυτοῦ τούτῳ μόνῳ τοὺς μέγιστον ἐφ’ ἱππικῇ φρονοῦντας ἐκράτησεν.", "st": "Ages. 16.1"}, {"sp": "N", "t": "ἐνταῦθα Διφρίδας οἴκοθεν ἔφορος ὢν ἀπήντησεν αὐτῷ κελεύων εὐθὺς ἐμβαλεῖν εἰς τὴν Βοιωτίαν. ὁ δέ, καίπερ ἀπὸ μείζονος παρασκευῆς ὕστερον τοῦτο ποιῆσαι διανοούμενος, οὐδὲν ᾤετο δεῖν ἀπειθεῖν τοῖς ἄρχουσιν, ἀλλὰ τοῖς τε μεθ’ ἑαυτοῦ προεῖπεν ἐγγὺς εἶναι τὴν ἡμέραν ἐφ’ ἣν ἐξ Ἀσίας ἥκουσι, καὶ δύο μόρας μετεπέμψατο τῶν περὶ Κόρινθον στρατευομένων· οἱ δὲ ἐν τῇ πόλει Λακεδαιμόνιοι τιμῶντες αὐτὸν ἐκήρυξαν τῶν νέων ἀπογράφεσθαι τὸν βουλόμενον τῷ βασιλεῖ βοηθεῖν. ἀπογραψαμένων δὲ πάντων προθύμως, οἱ ἄρχοντες πεντήκοντα τοὺς ἀκμαιοτάτους καὶ ῥωμαλεωτάτους ἐκλέξαντες ἀπέστειλαν.", "st": "Ages. 17.1"}, {"sp": "N", "t": "ὁ δὲ Ἀγησίλαος εἴσω Πυλῶν παρελθὼν καὶ διοδεύσας τὴν Φωκίδα φίλην οὖσαν, ἐπεὶ τῆς Βοιωτίας πρῶτον ἐπέβη καὶ περὶ τὴν Χαιρώνειαν κατεστρατοπέδευσεν, ἅμα μὲν τὸν ἥλιον ἐκλείποντα καὶ γινόμενον μηνοειδῆ κατεῖδεν, ἅμα δὲ ἤκουσε τεθνάναι Πείσανδρον ἡττημένον ναυμαχίᾳ περὶ Κνίδον ὑπὸ Φαρναβάζου καὶ Κόνωνος. ἠχθέσθη μὲν οὖν, ὡς εἰκός, ἐπὶ τούτοις καὶ διὰ τὸν ἄνδρα καὶ διὰ τὴν πόλιν, ὅπως δὲ μὴ τοῖς στρατιώταις ἐπὶ μάχην βαδίζουσιν ἀθυμία καὶ φόβος ἐμπέσῃ, τἀναντία λέγειν ἐκέλευσε τοὺς ἀπὸ θαλάττης ἥκοντας, ὅτι νικῶσι τῇ ναυμαχίᾳ· καὶ προελθὼν αὐτὸς ἐστεφανωμένος ἔθυσεν εὐαγγέλια καὶ διέπεμπε μερίδας τοῖς φίλοις ἀπὸ τῶν τεθυμένων.", "st": "Ages. 17.3"}, {"sp": "N", "t": "ἐπεὶ δὲ προϊὼν καὶ γενόμενος ἐν Κορωνείᾳ κατεῖδε τοὺς πολεμίους καὶ κατώφθη, παρετάξατο δοὺς Ὀρχομενίοις τὸ εὐώνυμον κέρας, αὐτὸς δὲ τὸ δεξιὸν ἐπῆγεν. οἱ δὲ Θηβαῖοι τὸ μὲν δεξιὸν εἶχον αὐτοί, τὸ δὲ εὐώνυμον Ἀργεῖοι. λέγει δὲ τὴν μάχην ὁ Ξενοφῶν ἐκείνην οἵαν οὐκ ἄλλην τῶν πώποτε γενέσθαι· καὶ παρῆν αὐτὸς τῷ Ἀγησιλάῳ συναγωνιζόμενος, ἐξ Ἀσίας διαβεβηκώς. ἡ μὲν οὖν πρώτη σύρραξις οὐκ ἔσχεν ὠθισμὸν οὐδὲ ἀγῶνα πολύν, ἀλλὰ οἵ τε Θηβαῖοι ταχὺ τοὺς Ὀρχομενίους ἐτρέψαντο καὶ τοὺς Ἀργείους ὁ Ἀγησίλαος· ἐπεὶ δὲ ἀκούσαντες ἀμφότεροι τὰ εὐώνυμα πιέζεσθαι καὶ φεύγειν ἀνέστρεψαν, ἐνταῦθα τῆς νίκης ἀκινδύνου παρούσης, εἰ τῆς κατὰ στόμα μάχης ὑφέσθαι τοῖς Θηβαίοις ἠθέλησε καὶ παίειν ἑπόμενος παραλλάξαντας, ὑπὸ θυμοῦ καὶ φιλονεικίας ἐναντίος ἐχώρει τοῖς ἀνδράσιν, ὤσασθαι κατὰ κράτος βουλόμενος. οἱ δὲ οὐχ ἧττον ἐρρωμένως ἐδέξαντο, καὶ μάχη γίνεται δι’ ὅλου μὲν ἰσχυρὰ τοῦ στρατεύματος, ἰσχυροτάτη δὲ κατ’ ἐκεῖνον αὐτὸν ἐν τοῖς πεντήκοντα τεταγμένον, ὧν εἰς καιρὸν ἔοικεν ἡ φιλοτιμία τῷ βασιλεῖ γενέσθαι καὶ σωτήριος, ἀγωνιζόμενοι γὰρ ἐκθύμως καὶ προκινδυνεύοντες ἄτρωτον μὲν αὐτὸν οὐκ ἐδυνήθησαν φυλάξαι, πολλὰς δὲ διὰ τῶν ὅπλων δεξάμενον εἰς τὸ σῶμα πληγὰς δόρασι καὶ ξίφεσι μόλις ἀνήρπασαν ζῶντα, καὶ συμφράξαντες πρὸ αὐτοῦ πολλοὺς μὲν ἀνῄρουν, πολλοὶ δὲ ἔπιπτον. ὡς δὲ μέγα ἔργον ἦν ὤσασθαι προτροπάδην τοὺς Θηβαίους, ἠναγκάσθησαν ὅπερ ἐξ ἀρχῆς οὐκ ἐβούλοντο ποιῆσαι. διέστησαν γὰρ αὐτοῖς τὴν φάλαγγα καὶ διέσχον, εἶτα ἀτακτότερον ἤδη πορευομένους, ὡς διεξέπεσον, ἀκολουθοῦντες καὶ παραθέοντες ἐκ πλαγίων ἔπαιον. οὐ μὴν ἐτρέψαντό γε, ἀλλ’ ἀπεχώρησαν οἱ Θηβαῖοι πρὸς τὸν Ἑλικῶνα, μέγα τῇ μάχῃ φρονοῦντες, ὡς ἀήττητοι καθ’ αὑτοὺς γεγονότες.", "st": "Ages. 18.1"}, {"sp": "N", "t": "Ἀγησίλαος δέ, καίπερ ὑπὸ τραυμάτων πολλῶν κακῶς τὸ σῶμα διακείμενος, οὐ πρότερον ἐπὶ σκηνὴν ἀπῆλθεν ἢ φοράδην ἐνεχθῆναι πρὸς τήν φάλαγγα καὶ τοὺς νεκροὺς ἰδεῖν ἐντὸς τῶν ὅπλων συγκεκομισμένους, ὅσοι μέντοι τῶν πολεμίων εἰς τὸ ἱερὸν κατέφυγον, πάντας ἐκέλευσεν ἀφεθῆναι. πλησίον γὰρ ὁ νεώς ἐστιν ὁ τῆς Ἰτωνίας Ἀθηνᾶς, καὶ πρὸ αὐτοῦ τρόπαιον ἕστηκεν, ὃ πάλαι Βοιωτοὶ Σπάρτωνος στρατηγοῦντος ἐνταῦθα νικήσαντες Ἀθηναίους καὶ Τολμίδην ἀποκτείναντες ἔστησαν, ἅμα δ’ ἡμέρᾳ βουλόμενος ἐξελέγξαι τοὺς Θηβαίους ὁ Ἀγησίλαος, εἰ διαμαχοῦνται, στεφανοῦσθαι μὲν ἐκέλευσε τοὺς στρατιώτας, αὐλεῖν δὲ τοὺς αὐλητάς, ἱστάναι δὲ καὶ κοσμεῖν τρόπαιον ὡς νενικηκότας. ὡς δὲ ἔπεμψαν οἱ πολέμιοι νεκρῶν ἀναίρεσιν αἰτοῦντες, ἐσπείσατο, καὶ τήν νίκην οὕτως ἐκβεβαιωσάμενος εἰς Δελφοὺς ἀπεκομίσθη, Πυθίων ἀγομένων, καὶ τήν τε πομπὴν ἐπετέλει τῷ θεῷ καὶ τήν δεκάτην ἀπέθυε τῶν ἐκ τῆς Ἀσίας λαφύρων ἑκατὸν ταλάντων γενομένην.", "st": "Ages. 19.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ἀπενόστησεν οἴκαδε, προσφιλὴς μὲν ἦν εὐθὺς τοῖς πολίταις καὶ περίβλεπτος ἀπὸ τοῦ βίου καὶ τῆς διαίτης· οὐ γάρ, ὥσπερ οἱ πλεῖστοι τῶν στρατηγῶν, καινὸς ἐπανῆλθεν ἀπὸ τῆς ξένης καὶ κεκινημένος ὑπ’ ἀλλοτρίων ἐθῶν, καὶ δυσκολαίνων πρὸς τὰ οἴκοι καὶ ζυγομαχῶν, ἀλλὰ ὁμοίως τοῖς μηδεπώποτε τὸν Εὐρώταν διαβεβηκόσι τὰ παρόντα τιμῶν καὶ στέργων οὐ δεῖπνον ἤλλαξεν, οὐ λουτρόν, οὐ θεραπείαν γυναικός, οὐχ ὅπλων κόσμον, οὐκ οἰκίας κατασκευήν, ἀλλὰ καὶ τὰς θύρας ἀφῆκεν οὕτως οὔσας σφόδρα παλαιάς, ὡς δοκεῖν εἶναι, ταύτας ἐκείνας ἃς ἐπέθηκεν Ἀριστόδημος, καὶ τὸ κάνναθρόν, φησιν ὁ Ξενοφῶν οὐδέν τι σεμνότερον εἶναι τῆς ἐκείνου θυγατρὸς ἢ τῶν ἄλλων. κάνναθρα δὲ καλοῦσιν εἴδωλα γρυπῶν ξύλινα καὶ τραγελάφων ἐν οἷς κομίζουσι τὰς παῖδας ἐν ταῖς πομπαῖς. ὁ μὲν οὖν Ξενοφῶν ὄνομα τῆς Ἀγησιλάου θυγατρὸς οὐ γέγραφε, καὶ ὁ Δικαίαρχος ἐπηγανάκτησεν ὡς μήτε τήν Ἀγησιλάου θυγατέρα μήτε τήν Ἐπαμινώνδου μητέρα γινωσκόντων ἡμῶν ἡμεῖς δὲ εὕρομεν ἐν ταῖς Λακωνικαῖς ἀναγραφαῖς ὀνομαζομένην γυναῖκα μὲν Ἀγησιλάου Κλεόραν, θυγατέρας δὲ Εὐπωλίαν καὶ Πρόαυγαν. ἔστι δὲ καὶ λόγχην ἰδεῖν αὐτοῦ κειμένην ἄχρι νῦν ἐν Λακεδαίμονι, μηδὲν τῶν ἄλλων διαφέρουσαν.", "st": "Ages. 19.4"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ ὁρῶν ἐνίους τῶν πολιτῶν ἀπὸ ἱπποτροφίας δοκοῦντας εἶναι τινας καὶ μέγα φρονοῦντας, ἔπεισε τὴν ἀδελφὴν Κυνίσκαν ἅρμα καθεῖσαν Ὀλυμπίασιν ἀγωνίσασθαι, βουλόμενος ἐνδείξασθαι τοῖς Ἕλλησιν ὡς οὐδεμιᾶς ἐστιν ἀρετῆς, ἀλλὰ πλούτου καὶ δαπάνης ἡ νίκη. Ξενοφῶντα δὲ τὸν σοφὸν ἔχων μεθ’ ἑαυτοῦ σπουδαζόμενον ἐκέλευε τοὺς παῖδας ἐν Λακεδαίμονι τρέφειν μεταπεμψάμενον, ὡς μαθησομένους τῶν μαθημάτων τὸ κάλλιστον, ἄρχεσθαι καὶ ἄρχειν. τοῦ δὲ Λυσάνδρου τετελευτηκότος εὑρὼν ἑταιρείαν πολλὴν συνεστῶσαν, ἣν ἐκεῖνος εὐθὺς ἐπανελθὼν ἀπὸ τῆς Ἀσίας συνέστησεν ἐπὶ τὸν Ἀγησίλαον, ὥρμησεν αὐτὸν ἐξελέγχειν οἷος ἦν ζῶν πολίτης· καὶ λόγον ἀναγνοὺς ἐν βιβλίῳ ἀπολελειμμένον, ὃν ἔγραψε μὲν Κλέων ὁ Ἁλικαρνασσεύς, ἔμελλε δὲ λέγειν ἀναλαβὼν ὁ Λύσανδρος ἐν τῷ δήμῳ περὶ πραγμάτων καινῶν καὶ μεταστάσεως τοῦ πολιτεύματος, ἠθέλησεν εἰς μέσον ἐξενεγκεῖν. ἐπεὶ δέ τις τῶν γερόντων τὸν λόγον ἀναγνοὺς καὶ φοβηθεὶς τὴν δεινότητα συνεβούλευσε μὴ τὸν Λύσανδρον ἀνορύττειν, ἀλλὰ τὸν λόγον μᾶλλον αὐτῷ συγκατορύττειν, ἐπείσθη καὶ καθησύχαζε. τοὺς δὲ ὑπεναντιουμένους αὐτῷ φανερῶς μὲν οὐκ ἔβλαπτε, διαπραττόμενος δὲ πέμπεσθαί τινας ἀεί στρατηγοὺς καὶ ἄρχοντας ἐξ αὐτῶν, ἐπεδείκνυε γενομένους ἐν ταῖς ἐξουσίαις πονηροὺς καὶ πλεονέκτας, εἶτα κρινομένοις πάλιν αὖ βοηθῶν καὶ συναγωνιζόμενος, οἰκείους ἐκ διαφόρων ἐποιεῖτο καὶ μεθίστη πρὸς αὑτόν, ὥστε μηθένα ἀντίπαλον εἶναι.", "st": "Ages. 20.1"}, {"sp": "N", "t": "ὁ γὰρ ἕτερος βασιλεὺς Ἀγησίπολις, ἅτε δὴ πατρὸς μὲν ὢν φυγάδος, ἡλικίᾳ δὲ παντάπασι μειράκιον, φύσει δὲ πρᾷος καὶ κόσμιος, οὐ πολλὰ τῶν πολιτικῶν ἔπραττεν. οὐ μὴν ἀλλὰ καὶ τοῦτον ἐποιεῖτο χειροήθη. συσσιτοῦσι γὰρ οἱ βασιλεῖς εἰς τὸ αὐτὸ φοιτῶντες φιδίτιον, ὅταν ἐπιδημῶσιν. εἰδὼς οὖν ἔνοχον ὄντα τοῖς ἐρωτικοῖς τὸν Ἀγησίπολιν, ὥσπερ ἦν αὐτός, ἀεί τινος ὑπῆρχε λόγου περὶ τῶν ἐν ὥρᾳ· καὶ προῆγε τὸν νεανίσκον εἰς ταὐτὸ καὶ συνήρα καὶ συνέπραττε, τῶν Λακωνικῶν ἐρώτων οὐδὲν αἰσχρόν, αἰδῶ δὲ πολλὴν καὶ φιλοτιμίαν καὶ ζῆλον ἀρετῆς ἐχόντων, ὡς ἐν τοῖς περὶ Λυκούργου γέγραπται.", "st": "Ages. 20.5"}, {"sp": "N", "t": "μέγιστον οὖν δυνάμενος ἐν τῇ πόλει διαπράττεται Τελευτίαν τὸν ὁμομήτριον ἀδελφὸν ἐπὶ τοῦ ναυτικοῦ γενέσθαι, καί στρατευσάμενος εἰς Κόρινθον αὐτὸς μὲν ᾕρει κατὰ γῆν τὰ μακρὰ τείχη, ταῖς δὲ ναυσὶν ὁ Τελευτίας … Ἀργείων δὲ τὴν Κόρινθον ἐχόντων τότε καί τὰ Ἴσθμια συντελούντων, ἐπιφανεὶς ἐκείνους μὲν ἐξήλασεν ἄρτι τῷ θεῷ τεθυκότας, τὴν παρασκευὴν ἅπασαν ἀπολιπόντας· ἐπεὶ δὲ τῶν Κορινθίων ὅσοι φυγάδες ἔτυχον παρόντες ἐδεήθησαν αὐτοῦ τὸν ἀγῶνα διαθεῖναι, τοῦτο μὲν Οὐκ ἐποίησεν, αὐτῶν δὲ ἐκείνων διατιθέντων καί συντελούντων παρέμεινε καί παρέσχεν ἀσφάλειαν. ὕστερον δὲ ἀπελθόντος αὐτοῦ πάλιν ὑπ’ Ἀργείων ἤχθη τὰ Ἴσθμια, καί τινες μὲν ἐνίκησαν πάλιν, εἰσὶ δὲ οἳ νενικηκότες πρότερον, ἡττημένοι δὲ ὕστερον, ἀνεγράφησαν. ἐπὶ τούτῳ δὲ πολλὴν ἀπέφηνε δειλίαν κατηγορεῖν ἑαυτῶν τοὺς Ἀργείους ὁ Ἀγησίλαος, εἰ σεμνὸν οὕτω καί μέγα τὴν ἀγωνοθεσίαν ἡγούμενοι μάχεσθαι περὶ αὐτῆς Οὐκ ἐτόλμησαν. αὐτὸς δὲ πρὸς ταῦτα πάντα μετρίως ᾤετο δεῖν ἔχειν, καί τοὺς μὲν οἴκοι χοροὺς καί ἀγῶνας ἐπεκόσμει καί συμπαρῆν ἀεὶ φιλοτιμίας καί σπουδῆς μεστὸς ὢν καί οὔτε παίδων οὔτε παρθένων ἁμίλλης ἀπολειπόμενος, ἃ δὲ τοὺς ἄλλους ἑώρα θαυμάζοντας ἐδόκει μηδὲ γινώσκειν. καί ποτε Καλλιππίδης ὁ τῶν τραγῳδιῶν ὑποκριτής, ὄνομα καί δόξαν ἔχων ἐν τοῖς Ἕλλησι καὶ σπουδαζόμενος ὑπὸ πάντων, πρῶτον μὲν ἀπήντησεν αὐτῷ καί προσεῖπεν, ἔπειτα σοβαρῶς εἰς τοὺς συμπεριπατοῦντας ἐμβαλὼν ἑαυτὸν ἐπεδείκνυτο νομίζων ἐκεῖνον ἄρξειν τινὸς φιλοφροσύνης, τέλος δὲ εἶπεν· οὐκ ἐπιγινώσκεις με, ὦ βασιλεῦ; κἀκεῖνος ἀποβλέψας πρὸς αὐτὸν εἶπεν, ἀλλὰ οὐ σύγε ἐσσὶ Καλλιππίδας ὁ δεικηλίκτας; οὕτω δὲ Λακεδαιμόνιοι τοὺς μίμους καλοῦσι. παρακαλούμενος δὲ πάλιν ἀκοῦσαι τοῦ τὴν ἀηδόνα μιμουμένου, παρῃτήσατο φήσας, αὐτᾶς ἄκουκα. τοῦ δὲ ἰατροῦ Μενεκράτους, ἐπεὶ κατατυχὼν ἔν τισιν ἀπεγνωσμέναις θεραπείαις Ζεὺς ἐπεκλήθη, φορτικῶς ταύτῃ χρωμένου τῇ προσωνυμίᾳ καί δὴ καί πρὸς ἐκεῖνον ἐπιστεῖλαι τολμήσαντος οὕτως· Μενεκράτης Ζεὺς βασιλεῖ Ἀγησιλάῳ χαίρειν, ἀντέγραψε· βασιλεὺς Ἀγησίλαος Μενεκράτει ὑγιαίνειν.", "st": "Ages. 21.1"}, {"sp": "N", "t": "διατρίβοντος δὲ περὶ τήν Κορινθίων αὐτοῦ καὶ τὸ Ἡραῖον εἰληφότος καὶ τὰ αἰχμάλωτα τοὺς στρατιώτας ἄγοντας καὶ φέροντας ἐπιβλέποντος, ἀφίκοντο πρέσβεις ἐκ Θηβῶν περὶ φιλίας. ὁ δὲ μισῶν μὲν ἀεὶ τήν πόλιν, οἰόμενος δὲ τότε καὶ συμφέρειν ἐνυβρίσαι, προσεποιεῖτο μήτε ὁρᾶν αὐτοὺς μήτε ἀκούειν ἐντυγχανόντων. ἔπαθε δὲ πρᾶγμα νεμεσητόν· οὔπω γὰρ ἀπηλλαγμένων τῶν Θηβαίων ἧκόν τινες ἀπαγγέλλοντες αὐτῷ τήν μόραν ὑπό Ἰφικράτους κατακεκόφθαι. καὶ πάθος τοῦτο μέγα διὰ πολλοῦ χρόνου συνέπεσεν αὐτοῖς πολλοὺς γὰρ ἄνδρας ἀγαθοὺς ἀπέβαλον κρατηθέντας ὑπό τε πελταστῶν ὁπλίτας καὶ μισθοφόρων Λακεδαιμονίους.", "st": "Ages. 22.1"}, {"sp": "N", "t": "ἀνεπήδησε μὲν οὖν εὐθὺς ὁ Ἀγησίλαος ὡς βοηθήσων· ἐπεὶ δὲ ἔγνω διαπεπραγμένους, αὖθις εἰς τὸ Ἡραῖον ἧκε, καὶ τοὺς Βοιωτοὺς τότε προσελθεῖν κελεύσας, ἐχρημάτιζεν. ὡς δὲ ἀνθυβρίζοντες ἐκεῖνοι τῆς μὲν εἰρήνης οὐκ ἐμέμνηντο, παρεθῆναι δὲ ἠξίουν εἰς Κόρινθον, ὀργισθεὶς ὁ Ἀγησίλαος εἶπεν εἴγε βούλεσθε τοὺς φίλους ὑμῶν ἰδεῖν μέγα φρονοῦντας ἐφ’ οἷς εὐτυχοῦσιν, αὔριον ἀσφαλῶς ὑμῖν τοῦτο ὑπάρξει. καὶ παραλαβὼν αὐτοὺς τῇ ὑστεραίᾳ τήν τε χώραν τῶν Κορινθίων ἔκοπτε καὶ πρὸς τήν πόλιν αὐτὴν προσῆλθεν. οὕτω δὲ τοὺς Κορινθίους ἐξελέγξας ἀμύνεσθαι μὴ τολμῶντας, ἀφῆκε τήν πρεσβείαν. αὐτὸς δὲ τοὺς περιλελειμμένους ἄνδρας ἐκ τῆς μόρας ἀναλαβὼν ἀπῆγεν εἰς Λακεδαίμονα, πρὸ ἡμέρας ποιούμενος τὰς ἀναζεύξεις καὶ πάλιν σκοταίους τὰς καταλύσεις, ὅπως οἱ μισοῦντες καὶ βασκαίνοντες τῶν Ἀρκάδων μὴ ἐπιχαίρωσιν·", "st": "Ages. 22.3"}, {"sp": "N", "t": "ἐκ τούτου χαριζόμενος τοῖς Ἀχαιοῖς διέβαινεν εἰς Ἀκαρνανίαν στρατιᾷ μετ’ αὐτῶν, καὶ πολλὴν μὲν ἠλάσατο λείαν, μάχῃ δὲ τοὺς Ἀκαρνᾶνας ἐνίκησε. δεομένων δὲ τῶν Ἀχαιῶν ὅπως τὸν χειμῶνα παραμείνας ἀφέληται τὸν σπόρον τῶν πολεμίων, τοὐναντίον ἔφη ποιήσειν· μᾶλλον γὰρ φοβηθήσεσθαι τὸν πόλεμον αὐτούς, ἐὰν ἐσπαρμένην τήν γῆν εἰς ὥρας ἔχωσιν ὃ καὶ συνέβη, παραγγελλομένης γὰρ αὖθις ἐπ’ αὐτοὺς στρατείας διηλλάγησαν τοῖς Ἀχαιοῖς.", "st": "Ages. 22.5"}, {"sp": "N", "t": "ἐπεὶ δὲ Κόνων καὶ Φαρνάβαζος τῷ βασιλέως ναυτικῷ θαλαττοκρατοῦντες ἐπόρθουν τὰ παράλια τῆς Λακωνικῆς, ἐτειχίσθη δὲ καὶ τὸ ἄστυ τῶν Ἀθηναίων Φαρναβάζου χρήματα δόντος, ἔδοξε τοῖς Λακεδαιμονίοις εἰρήνην ποιεῖσθαι πρὸς βασιλέα· καὶ πέμπουσιν Ἀνταλκίδαν πρὸς Τιρίβαζον, αἴσχιστα καὶ παρανομώτατα τοὺς τὴν Ἀσίαν κατοικοῦντας Ἕλληνας, ὑπὲρ ὧν ἐπολέμησεν Ἀγησίλαος, βασιλεῖ παραδιδόντες. ὅθεν ἥκιστα συνέβη τῆς κακοδοξίας ταύτης Ἀγησιλάῳ μετασχεῖν. ὁ γὰρ Ἀνταλκίδας ἐχθρὸς ἦν αὐτῷ, καὶ τὴν εἰρήνην ἐξ ἅπαντος ἔπραττεν ὡς τοῦ πολέμου τὸν Ἀγησίλαον αὔξοντος καὶ ποιοῦντος ἐνδοξότατον καὶ μέγιστον. οὐ μὴν ἀλλὰ καὶ πρὸς τὸν εἰπόντα τοὺς Λακεδαιμονίους μηδίζειν ὁ Ἀγησίλαος ἀπεκρίνατο μᾶλλον τοὺς Μήδους λακωνίζειν. τοῖς δὲ μὴ βουλομένοις δέχεσθαι τὴν εἰρήνην ἀπειλῶν καὶ καταγγέλλων πόλεμον ἠνάγκασεν ἐμμένειν ἅπαντας οἷς ὁ Πέρσης ἐδικαίωσε, μάλιστα διὰ τοὺς Θηβαίους, ὅπως αὐτόνομον τὴν Βοιωτίαν ἀφέντες ἀσθενέστεροι γένωνται. δῆλον δὲ τοῦτο τοῖς ὕστερον ἐποίησεν, ἐπεὶ γὰρ Φοιβίδας ἔργον εἰργάσατο δεινὸν ἐν σπονδαῖς καὶ εἰρήνῃ τὴν Καδμείαν καταλαβών, καὶ πάντες μὲν ἠγανάκτουν οἱ Ἕλληνες, χαλεπῶς δὲ ἔφερον οἱ Σπαρτιᾶται, καὶ μάλιστα οἱ διαφερόμενοι τῷ Ἀγησιλάῳ μετ’ ὀργῆς ἐπυνθάνοντο τοῦ Φοιβίδου τίνος ταῦτα κελεύσαντος ἔπραξεν, εἰς ἐκεῖνον τὴν ὑπόνοιαν τρέποντες, οὐκ ὤκνησε τῷ Φοιβίδᾳ βοηθῶν λέγειν ἀναφανδὸν ὅτι δεῖ τὴν πρᾶξιν αὐτήν, εἴ τι χρήσιμον ἔχει, σκοπεῖν· τὰ γὰρ συμφέροντα τῇ Λακεδαίμονι καλῶς ἔχειν αὐτοματίζεσθαι, κἂν μηδεὶς κελεύσῃ. καίτοι τῷ λόγῳ πανταχοῦ τὴν δικαιοσύνην ἀπέφαινε πρωτεύειν τῶν ἀρετῶν· ἀνδρείας μὲν γὰρ οὐδὲν ὄφελος εἶναι, μὴ παρούσης δικαιοσύνης, εἰ δὲ δίκαιοι πάντες γένοιντο, μηδὲν ἀνδρείας δεήσεσθαι. πρὸς δὲ τοὺς λέγοντας ὅτι ταῦτα δοκεῖ τῷ μεγάλῳ βασιλεῖ, τί δ’ ἐκεῖνος ἐμοῦ, εἶπε, μείζων, εἰ μὴ καὶ δικαιότερος; ὀρθῶς καὶ καλῶς οἰόμενος δεῖν τῷ δικαίῳ καθάπερ μέτρῳ βασιλικῷ μετρεῖσθαι τὴν ὑπεροχὴν τοῦ μείζονος. ἣν δὲ τῆς εἰρήνης γενομένης ἔπεμψεν αὐτῷ περὶ ξενίας καὶ φιλίας ἐπιστολὴν ὁ βασιλεύς, οὐκ ἔλαβεν, εἰπὼν ἐξαρκεῖν τὴν κοινὴν φιλίαν, καὶ μηδὲν ἰδίας δεήσεσθαι μενούσης ἐκείνης, ἐν δὲ τοῖς ἔργοις οὐκέτι ταύτην διαφυλάττων τὴν δόξαν, ἀλλὰ τῇ φιλοτιμίᾳ καὶ τῇ φιλονεικίᾳ πολλαχοῦ συνεκφερόμενος, καὶ μάλιστα τῇ πρὸς Θηβαίους, οὐ μόνον ἔσωσε τὸν Φοιβίδαν, ἀλλὰ καὶ τὴν πόλιν ἔπεισεν εἰς αὑτὴν ἀναδέξασθαι τὸ ἀδίκημα καὶ κατέχειν τὴν Καδμείαν δι’ ἑαυτῆς, τῶν δὲ πραγμάτων καὶ τῆς πολιτείας Ἀρχίαν καὶ Λεοντίδαν ἀποδεῖξαι κυρίους, δι’ ὧν ὁ Φοιβίδας εἰσῆλθε καὶ κατέλαβε τὴν ἀκρόπολιν.", "st": "Ages. 23.1"}, {"sp": "N", "t": "ἦν μὲν οὖν εὐθὺς ἐκ τούτων ὑπόνοια Φοιβίδου μὲν ἔργον εἶναι, βούλευμα δὲ Ἀγησιλάου τὸ πεπραγμένον· αἱ δὲ ὕστερον πράξεις ὁμολογουμένην ἐποίησαν τὴν αἰτίαν. ὡς γὰρ ἐξέβαλον οἱ Θηβαῖοι τὴν φρουρὰν καί τὴν πόλιν ἠλευθέρωσαν, ἐγκαλῶν αὐτοῖς ὅτι τὸν Ἀρχίαν καὶ τὸν Λεοντίδαν ἀπεκτόνεσαν, ἔργῳ μὲν τυράννους, λόγῳ δὲ πολεμάρχους ὄντας, ἐξήνεγκε πόλεμον πρὸς αὐτούς. καὶ Κλεόμβροτος ἤδη βασιλεύων Ἀγησιπόλιδος τεθνηκότος, εἰς Βοιωτίαν ἐπέμφθη μετὰ δυνάμεως· ὁ γὰρ Ἀγησίλαος, ὡς ἔτη τεσσαράκοντα γεγονὼς ἀφ’ ἥβης καί στρατείας ἔχων ἄφεσιν ὑπὸ τῶν νόμων, ἔφυγε τὴν στρατηγίαν ἐκείνην, αἰσχυνόμενος εἰ Φλιασίοις ὀλίγον ἔμπροσθεν ὑπὲρ φυγάδων πεπολεμηκώς, αὖθις ὀφθήσεται Θηβαίους κακῶς ποιῶν διὰ τοὺς τυράννους.", "st": "Ages. 24.1"}, {"sp": "N", "t": "ἦν δέ τις Λάκων Σφοδρίας ἐκ τῆς ὑπεναντίας στάσεως τῷ Ἀγησιλάῳ τεταγμένος ἐν Θεσπιαῖς ἁρμοστής, οὐκ ἄτολμος μὲν οὐδ’ ἀφιλότιμος ἀνήρ, ἀεὶ δ’· ἐλπίδων μᾶλλον ἢ φρενῶν ἀγαθῶν μεστός, οὗτος ἐπιθυμῶν ὀνόματος μεγάλου, καί τὸν Φοιβίδαν νομίζων ἔνδοξον γεγονέναι καί περιβόητον ἀπὸ τοῦ περὶ Θήβας τολμήματος, ἐπείσθη πολὺ κάλλιον εἶναι καί λαμπρότερον εἰ τὸν Πειραιᾶ καταλάβοι δι’ ἑαυτοῦ καί τῶν Ἀθηναίων ἀφέλοιτο τὴν θάλασσαν, ἐκ γῆς ἀπροσδοκήτως ἐπελθών. λέγουσι δὲ τοῦτο μηχάνημα γενέσθαι τῶν περὶ Πελοπίδαν καί Μέλωνα βοιωταρχῶν. ὑπέπεμψαν γὰρ ἀνθρώπους λακωνίζειν προσποιουμένους, οἳ τὸν Σφοδρίαν ἐπαινοῦντες καί μεγαλύνοντες ὡς ἔργου τηλικούτου μόνον ἄξιον, ἐπῆραν καί παρώρμησεν ἀνελέσθαι πρᾶξιν ἄδικον μὲν ὁμοίως ἐκείνῃ καί παράνομον, τόλμης δὲ καί τύχης ἐνδεᾶ γενομένην. ἡμέρα γὰρ αὐτὸν ἐν τῷ Θριασίῳ πεδίῳ κατέλαβε καί κατέλαμψεν ἐλπίσαντα νυκτὸς προσμίξειν τῷ Πειραιεῖ· καί φῶς ἀφ’ ἱερῶν τινων Ἐλευσινόθεν ἰδόντας λέγουσι φρῖξαι καί περιφόβους γενέσθαι τοὺς στρατιώτας. αὐτὸς δὲ τοῦ θράσους ἐξέπεσεν, ὡς οὐκέτι λαθεῖν ἦν, καί τινα βραχεῖαν ἁρπαγὴν θέμενος αἰσχρῶς ἀνεχώρησε καί ἀδόξως εἰς τὰς Θεσπιάς. ἐκ δὲ τούτου κατήγοροι μὲν ἐπέμφθησαν εἰς Σπάρτην ἐξ Ἀθηνῶν, εὗρον δὲ κατηγορίας μηδὲν ἐπὶ τὸν Σφοδρίαν δεομένους τοὺς ἄρχοντας, ἀλλὰ θανάτου κρίσιν αὐτῷ προειρηκότας, ἣν ἐκεῖνος ὑπομένειν ἀπέγνω, φοβούμενος τὴν ὀργὴν τῶν πολιτῶν αἰσχυνομένων τοὺς Ἀθηναίους καί βουλομένων συναδικεῖσθαι δοκεῖν, ἵνα μὴ συναδικεῖν δοκῶσιν.", "st": "Ages. 24.3"}, {"sp": "N", "t": "εἶχεν οὖν υἱὸν ὁ Σφοδρίας Κλεώνυμον, οὗ παιδὸς ὄντος ἔτι καὶ καλοῦ τὴν ὄψιν Ἀρχίδαμος ὁ Ἀγησιλάου τοῦ βασιλέως υἱὸς ἤρα. καὶ τότε συνηγωνία μὲν ὡς εἰκὸς αὐτῷ κινδυνεύοντι περὶ τὸν πατρός, συμπράττειν δὲ φανερῶς καὶ βοηθεῖν οὐκ εἶχεν ἦν γὰρ ὁ Σφοδρίας ἐκ τῶν διαφόρων τοῦ Ἀγησιλάου. τοῦ δὲ Κλεωνύμου προσελθόντος αὐτῷ καὶ μετὰ δεήσεως καὶ δακρύων ἐντυχόντος, ὅπως τὸν Ἀγησίλαον εὔνουν παράσχῃ, μάλιστα γὰρ ἐκεῖνον αὐτοῖς φοβερὸν εἶναι, τρεῖς μὲν ἢ τέσσαρας ἡμέρας αἰδούμενος τὸν πατέρα καὶ δεδιὼς σιωπῇ παρηκολούθει· τέλος δὲ τῆς κρίσεως ἐγγὺς οὔσης ἐτόλμησεν εἰπεῖν πρὸς τὸν Ἀγησίλαον ὅτι Κλεώνυμος αὐτοῦ δεηθείη περὶ τοῦ πατρός· ὁ δὲ Ἀγησίλαος εἰδὼς ἐρῶντα τὸν Ἀρχίδαμον οὐκ ἔπαυσεν ἦν γὰρ ὁ Κλεώνυμος εὐθὺς ἐκ παίδων ἐπίδοξος, εἴ τις καὶ ἄλλος, ἀνὴρ ἔσεσθαι σπουδαῖος. οὐ μὴν ἐνέδωκέ τι τότε χρηστὸν ἢ φιλάνθρωπον ἐλπίσαι δεομένῳ τῷ παιδί, σκέψεσθαι δὲ φήσας ὅ τι καλῶς ἔχοι καὶ πρεπόντως, ἀπῆλθεν. αἰδούμενος οὖν ὁ Ἀρχίδαμος ἐξέλειπε τὸ προσιέναι τῷ Κλεωνύμῳ, καίπερ εἰωθὼς πολλάκις τοῦτο τῆς ἡμέρας ποιεῖν πρότερον. ἐκ δὲ τούτου κἀκεῖνοι τὰ κατὰ τὸν Σφοδρίαν μᾶλλον ἀπέγνωσαν, ἄχρι οὗ τῶν Ἀγησιλάου φίλων Ἐτυμοκλῆς ἔν τινι κοινολογίᾳ πρὸς αὐτοὺς ἀπεγύμνωσε τὴν γνώμην τοῦ Ἀγησιλάου· τὸ μὲν γὰρ ἔργον ὡς ἔνι μάλιστα ψέγειν αὐτόν, ἄλλως γε μὴν ἄνδρα τὸν Σφοδρίαν ἀγαθὸν ἡγεῖσθαι καὶ τὴν πόλιν ὁρᾶν τοιούτων στρατιωτῶν δεομένην. τούτους γὰρ ὁ Ἀγησίλαος ἑκάστοτε τοὺς λόγους ἐποιεῖτο περὶ τῆς δίκης, τῷ παιδὶ χαρίζεσθαι βουλόμενος, ὥστε καὶ τὸν Κλεώνυμον εὐθὺς αἰσθάνεσθαι τὴν σπουδὴν τοῦ Ἀρχιδάμου καὶ τοὺς φίλους τοὺς τοῦ Σφοδρίου θαρροῦντας ἤδη βοηθεῖν. ἦν δὲ καὶ φιλότεκνος ὁ Ἀγησίλαος διαφερόντως· καὶ περὶ ἐκείνου τὸ τῆς παιδιᾶς λέγουσιν, ὅτι μικροῖς τοῖς παιδίοις οὖσι κάλαμον περιβεβηκὼς ὥσπερ ἵππον οἴκοι συνέπαιζεν, ὀφθεὶς δὲ ὑπό τινος τῶν φίλων παρεκάλει μηδενὶ φράσαι, πρὶν ἂν καὶ αὐτὸς πατὴρ παίδων γένηται.", "st": "Ages. 25.1"}, {"sp": "N", "t": "ἀπολυθέντος δὲ τοῦ Σφοδρίου, καὶ τῶν Ἀθηναίων, ὡς ἐπύθοντο, πρὸς πόλεμον τραπομένων, σφόδρα κακῶς ὁ Ἀγησίλαος ἤκουσε, δι’ ἐπιθυμίαν ἄτοπον καὶ παιδαριώδη δοκῶν ἐμποδὼν γεγονέναι κρίσει δικαίᾳ, καὶ τὴν πόλιν παραίτιον ἀπειργάσθαι παρανομημάτων τηλικούτων εἰς τοὺς Ἕλληνας. ἐπεὶ δὲ τὸν Κλεόμβροτον οὐχ ἑώρα πρόθυμον ὄντα πολεμεῖν τοῖς Θηβαίοις, οὕτω δὴ χαίρειν τὸν νόμον ἐάσας ᾧ πρόσθεν ἐχρῆτο περὶ τῆς στρατείας, αὐτὸς εἰς Βοιωτίαν ἐνέβαλεν ἤδη καὶ κακῶς ἐποίει τοὺς Θηβαίους καὶ πάλιν ἀντέπασχεν, ὥστε καὶ τρωθέντος αὐτοῦ ποτε τὸν Ἀνταλκίδαν εἰπεῖν· ἦ καλὰ τὰ διδασκάλια παρὰ Θηβαίων ἀπολαμβάνεις, μὴ βουλομένους μηδὲ ἐπισταμένους μάχεσθαι διδάξας. τῷ γὰρ ὄντι Θηβαίους αὐτοὺς ἑαυτῶν πολεμικωτάτους τότε γενέσθαι φασί, ταῖς πολλαῖς στρατείαις τῶν Λακεδαιμονίων ἐπ’ αὐτοὺς ὥσπερ ἐγγυμνασαμένους, διὸ καὶ Λυκοῦργος ὁ παλαιὸς ἐν ταῖς καλουμέναις τρισὶ ῥήτραις ἀπεῖπε μὴ πολλάκις ἐπὶ τοὺς αὐτοὺς στρατεύειν, ὅπως μὴ πολεμεῖν μανθάνωσιν.", "st": "Ages. 26.1"}, {"sp": "N", "t": "ἦν δὲ καὶ τοῖς συμμάχοις τῶν Λακεδαιμονίων ἐπαχθὴς ὁ Ἀγησίλαος, ὡς δι’ οὐδὲν ἔγκλημα δημόσιον, ἀλλὰ θυμῷ τινι καὶ φιλονεικίᾳ τοὺς Θηβαίους ἀπολέσαι ζητῶν. οὐδὲν οὖν ἔλεγον δεόμενοι φθείρεσθαι δεῦρο κἀκεῖσε καθ’ ἕκαστον ἐνιαυτόν, ὀλίγοις τοσοῦτοι συνακολουθοῦντες· ἔνθα δὲ δὴ λέγεται τὸν Ἀγησίλαον, ἐξελέγξαι βουλόμενον αὐτῶν τὸ πλῆθος, τόδε μηχανήσασθαι. πάντας ἐκέλευσε καθίσαι τοὺς συμμάχους μετ’ ἀλλήλων ἀναμεμιγμένους, ἰδίᾳ δὲ τοὺς Λακεδαιμονίους ἐφ’ ἑαυτῶν. εἶτα ἐκήρυττε τοὺς κεραμεῖς ἀνίστασθαι πρῶτον ὡς δὲ ἀνέστησαν οὗτοι, δεύτερον ἐκήρυττε τοὺς χαλκεῖς, εἶτα τέκτονας ἐφεξῆς καὶ οἰκοδόμους καὶ τῶν ἄλλων τεχνῶν ἑκάστην. πάντες οὖν ὀλίγου δεῖν ἀνέστησαν οἱ σύμμαχοι, τῶν δὲ Λακεδαιμονίων οὐδείς· ἀπείρητο γὰρ αὐτοῖς τέχνην ἐργάζεσθαι καὶ μανθάνειν βάναυσον. οὕτω δὴ γελάσας ὁ Ἀγησίλαος, ὁρᾶτε, εἶπεν, ὦ ἄνδρες, ὅσῳ πλείονας ὑμῶν στρατιώτας ἐκπέμπομεν ἡμεῖς.", "st": "Ages. 26.4"}, {"sp": "N", "t": "ἐν δὲ Μεγάροις, ὅτε τὴν στρατιὰν ἀπῆγεν ἐκ Θηβῶν, ἀναβαίνοντος αὐτοῦ πρὸς τὸ ἀρχεῖον εἰς τὴν ἀκρόπολιν, σπάσμα καὶ πόνον ἰσχυρὸν ἔλαβε τὸ ὑγιὲς σκέλος· ἐκ δὲ τούτου διογκωθὲν μεστὸν αἵματος ἔδοξε γεγονέναι, καὶ φλεγμονὴν ὑπερβάλλουσαν παρεῖχεν. ἰατροῦ δέ τινος Συρακουσίου τὴν ὑπὸ τῷ σφυρῷ φλέβα σχάσαντος, αἱ μὲν ἀλγηδόνες ἔληξαν, αἵματος δὲ πολλοῦ φερομένου καὶ ῥέοντος ἀνεπισχέτως λιποψυχία πολλὴ καὶ κίνδυνος ὀξὺς ἀπ’ αὐτῆς περιέστη τὸν Ἀγησίλαον. οὐ μὴν ἀλλὰ τότε γε τὴν φορὰν τοῦ αἵματος ἔπαυσε· καὶ κομισθεὶς εἰς Λακεδαίμονα πολὺν χρόνον ἔσχεν ἀρρώστως καὶ πρὸς τὰς στρατείας ἀδυνάτως.", "st": "Ages. 27.1"}, {"sp": "N", "t": "ἐν δὲ τῷ χρόνῳ τούτῳ πολλὰ συνέβη πταίσματα τοῖς Σπαρτιάταις καὶ κατὰ γῆν καὶ κατὰ θάλατταν ὧν ἦν τὸ περὶ Τεγύρας μέγιστον, ὅπου πρῶτον ἐκ παρατάξεως κρατηθέντες ὑπὸ Θηβαίων ἡττήθησαν. ἔδοξεν οὖν πᾶσι θέσθαι πρὸς πάντας εἰρήνην· καὶ συνῆλθον ἀπὸ τῆς Ἑλλάδος πρέσβεις εἰς Λακεδαίμονα ποιησόμενοι τὰς διαλύσεις. ὧν εἷς ἦν Ἐπαμεινώνδας, ἀνὴρ ἔνδοξος ἐπὶ παιδείᾳ καὶ φιλοσοφίᾳ, στρατηγίας δὲ πεῖραν οὔπω δεδωκώς. οὗτος ὁρῶν τοὺς ἄλλους ἅπαντας ὑποκατακλινομένους τῷ Ἀγησιλάῳ, μόνος ἐχρήσατο φρονήματι παρρησίαν ἔχοντι, καὶ διεξῆλθε λόγον, οὐχ ὑπὲρ Θηβαίων, ἀλλὰ ὑπὲρ τῆς Ἑλλάδος ὁμοῦ κοινόν, τὸν μὲν πόλεμον ἀποδεικνύων αὔξοντα τὴν Σπάρτην ἐξ ὧν ἅπαντες οἱ λοιποὶ κακῶς πάσχουσι, τὴν δὲ εἰρήνην ἰσότητι καὶ τῷ δικαίῳ κτᾶσθαι κελεύων οὕτω γὰρ αὐτὴν διαμενεῖν, ἴσων ἁπάντων γενομένων.", "st": "Ages. 27.3"}, {"sp": "N", "t": "ὁρῶν οὖν ὁ Ἀγησίλαος ὑπερφυῶς ἀγαμένους καὶ προσέχοντας αὐτῷ τοὺς Ἕλληνας, ἠρώτησεν εἰ νομίζει δίκαιον εἶναι καὶ ἴσον αὐτονομεῖσθαι τὴν Βοιωτίαν. ἀντερωτήσαντος δὲ τοῦ Ἐπαμεινώνδου ταχὺ καὶ τεθαρρηκότως εἰ κἀκεῖνος οἴεται δίκαιον αὐτονομεῖσθαι τὴν Λακωνικήν, ἀναπηδήσας ὁ Ἀγησίλαος μετ’ ὀργῆς ἐκέλευσε λέγειν σαφῶς αὐτὸν εἰ τὴν Βοιωτίαν ἀφίησιν αὐτόνομον. τὸ δὲ αὐτὸ τοῦτο πάλιν τοῦ Ἐπαμεινώνδου φήσαντος, εἰ τὴν Λακωνικὴν ἀφίησιν αὐτόνομον, οὕτω τραχέως ἔσχεν ὁ Ἀγησίλαος καὶ τὴν πρόφασιν ἠγάπησεν ὡς εὐθὺς ἐξαλεῖψαι τὸ τῶν Θηβαίων ὄνομα τῆς εἰρήνης καὶ προειπεῖν πόλεμον αὐτοῖς τοὺς δὲ ἄλλους Ἕλληνας διαλλαγέντας ἐκέλευσεν ἀπιέναι, τὰ μὲν ἀκεστὰ τῆς εἰρήνης, τὰ δὲ ἀνήκεστα τοῦ πολέμου ποιοῦντας. ἔργον γὰρ ἦν πάσας ἐκκαθᾶραι καὶ διαλῦσαι τὰς ἀμφιλογίας.", "st": "Ages. 28.1"}, {"sp": "N", "t": "ἔτυχε δὲ κατ’ ἐκεῖνον τὸν χρόνον ἐν Φωκεῦσιν ὢν ὁ Κλεόμβροτος μετὰ δυνάμεως, εὐθὺς οὖν ἔπεμπον οἱ ἔφοροι κελεύοντες αὐτὸν ἐπὶ Θηβαίους ἄγειν τὸ στράτευμα· καὶ τοὺς συμμάχους περιπέμποντες ἤθροιζον, ἀπροθύμους μὲν ὄντας καὶ βαρυνομένους τὸν πόλεμον, οὔπω δὲ θαρροῦντας ἀντιλέγειν οὐδὲ ἀπειθεῖν τοῖς Λακεδαιμονίοις. πολλῶν δὲ σημείων μοχθηρῶν γενομένων, ὡς ἐν τῷ περὶ Ἐπαμεινώνδου γέγραπται, καὶ Προθόου τοῦ Λάκωνος ἐναντιουμένου πρὸς τὴν στρατείαν, οὐκ ἀνῆκεν ὁ Ἀγησίλαος, ἀλλ’ ἐξέπραξε τὸν πόλεμον, ἐλπίζων αὐτοῖς μὲν τῆς Ἑλλάδος ὅλης ὑπαρχούσης, ἐκσπόνδων δὲ τῶν Θηβαίων γενομένων, καιρὸν εἶναι δίκην λαβεῖν παρ’ αὐτῶν. δηλοῖ δὲ τὸ σὺν ὀργῇ μᾶλλον ἢ λογισμῷ γενέσθαι τὴν στρατείαν ἐκείνην ὁ καιρός, τῇ γὰρ τετράδι ἐπὶ δέκα τοῦ Σκιροφοριῶνος μηνὸς ἐποιήσαντο τὰς σπονδὰς ἐν Λακεδαίμονι, τῇ δὲ πέμπτῃ τοῦ Ἑκατομβαιῶνος ἡττήθησαν ἐν Λεύκτροις ἡμερῶν εἴκοσι διαγενομένων. ἀπέθανον δὲ χίλιοι Λακεδαιμονίων καὶ Κλεόμβροτος ὁ βασιλεὺς καὶ περὶ αὐτὸν οἱ κράτιστοι τῶν Σπαρτιατῶν. ἐν οἷς καὶ Κλεώνυμόν φασι τὸν Σφοδρίου τὸν καλὸν τρὶς πεσόντα πρὸ τοῦ βασιλέως καὶ τοσαυτάκις ἐξαναστάντα καὶ μαχόμενον τοῖς Θηβαίοις ἀποθανεῖν.", "st": "Ages. 28.3"}, {"sp": "N", "t": "συμβάντος δὲ τοῖς τε Λακεδαιμονίοις πταίσματος ἀπροσδοκήτου καὶ τοῖς Θηβαίοις παρὰ δόξαν εὐτυχήματος οἷον οὐ γέγονεν ἄλλοις Ἕλλησι πρὸς Ἕλληνας ἀγωνισαμένοις, οὐδὲν ἄν τις ἧττον ἐζήλωσε τῆς ἀρετῆς καὶ ἠγάσθη τὴν ἡττημένην πόλιν ἢ τὴν νικῶσαν. ὁ μὲν γὰρ Ξενοφῶν φησι τῶν ἀγαθῶν ἀνδρῶν ἔχειν τι καὶ τὰς ἐν οἴνῳ καὶ παιδιᾷ φωνὰς καὶ διατριβὰς ἀξιομνημόνευτον, ὀρθῶς λέγων· ἔστι δὲ οὐχ ἧττον, ἀλλὰ καὶ μᾶλλον ἄξιον κατανοεῖν καὶ θεᾶσθαι τῶν ἀγαθῶν ἃ παρὰ τὰς τύχας πράττουσι καὶ λέγουσι διευσχημονοῦντες. ἔτυχε μὲν γὰρ ἡ πόλις ἑορτὴν ἄγουσα καὶ ξένων οὖσα μεστή· γυμνοπαιδίαι γὰρ ἦσαν ἀγωνιζομένων χορῶν ἐν τῷ θεάτρῳ· παρῆσαν δ’· ἀπὸ Λεύκτρων οἱ τὴν συμφορὰν ἀπαγγέλλοντες. οἱ δὲ ἔφοροι, καίπερ εὐθὺς ὄντος καταφανοῦς ὅτι διέφθαρται τὰ πράγματα καὶ τὴν ἀρχὴν ἀπολωλέκασιν, οὔτε χορὸν ἐξελθεῖν εἴασαν οὔτε τὸ σχῆμα τῆς ἑορτῆς μεταβαλεῖν τὴν πόλιν, ἀλλὰ κατ’ οἰκίαν τῶν τεθνεώτων τοῖς προσήκουσι τὰ ὀνόματα πέμψαντες, αὐτοὶ τὰ περὶ τὴν θέαν καὶ τὸν ἀγῶνα τῶν χορῶν ἔπραττον. ἅμα δὲ ἡμέρᾳ φανερῶν ἤδη γεγονότων πᾶσι τῶν σωζομένων καὶ τῶν τεθνεώτων, οἱ μὲν τῶν τεθνεώτων πατέρες καὶ κηδεσταὶ καὶ οἰκεῖοι καταβαίνοντες εἰς ἀγορὰν ἀλλήλους ἐδεξιοῦντο λιπαροὶ τὰ πρόσωπα, φρονήματος μεστοὶ καὶ γήθους, οἱ δὲ τῶν σωζομένων, ὥσπερ ἐπὶ πένθει, μετὰ τῶν γυναικῶν οἴκοι διέτριβον, εἰ δέ τις ὑπ’ ἀνάγκης προέλθοι, καὶ σχήματι καὶ φωνῇ καὶ βλέμματι ταπεινὸς ἐφαίνετο καὶ συνεσταλμένος. ἔτι δὲ μᾶλλον τῶν γυναικῶν ἰδεῖν ἦν καὶ πυθέσθαι τὴν μὲν ζῶντα προσδεχομένην υἱὸν ἀπὸ τῆς μάχης κατηφῆ καὶ σιωπηλήν, τὰς δὲ τῶν πεπτωκέναι λεγομένων ἔν τε τοῖς ἱεροῖς εὐθὺς ἀναστρεφομένας, καὶ πρὸς ἀλλήλας ἱλαρῶς καὶ φιλοτίμως βαδιζούσας.", "st": "Ages. 29.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τοῖς πολλοῖς, ὡς ἀφίσταντο μὲν οἱ σύμμαχοι, προσεδοκᾶτο δὲ νενικηκὼς Ἐπαμεινώνδας καὶ μεγαλοφρονῶν ἐμβαλεῖν εἰς Πελοπόννησον, ἔννοια τῶν χρησμῶν ἐνέπεσε τότε, πρὸς τὴν χωλότητα τοῦ Ἀγησιλάου, καὶ δυσθυμία πολλὴ καὶ πτοία πρὸς τὸ θεῖον, ὡς διὰ τοῦτο πραττούσης κακῶς τῆς πόλεως, ὅτι τὸν ἀρτίποδα τῆς βασιλείας ἐκβαλόντες εἵλοντο χωλὸν καὶ πεπηρωμένον· ὃ παντὸς μᾶλλον αὐτοὺς ἐδίδασκε φράζεσθαι καὶ φυλάττεσθαι τὸ δαιμόνιον. διὰ δὲ τὴν ἄλλην δύναμιν αὐτοῦ καὶ ἀρετὴν καὶ δόξαν οὐ μόνον ἐχρῶντο βασιλεῖ καὶ στρατηγῷ τῶν κατὰ πόλεμον, ἀλλὰ καὶ τῶν πολιτικῶν ἀποριῶν ἰατρῷ καὶ διαιτητῇ, τοῖς ἐν τῇ μάχῃ καταδειλιάσασιν, οὓς αὐτοὶ τρέσαντας ὀνομάζουσιν, ὀκνοῦντες τὰς ἐκ τῶν νόμων ἀτιμίας προσάγειν, πολλοῖς οὖσι καὶ δυνατοῖς, φοβούμενοι νεωτερισμὸν ἀπ’ αὐτῶν. οὐ γὰρ μόνον ἀρχῆς ἀπείργονται πάσης, ἀλλὰ καὶ δοῦναί τινι τούτων γυναῖκα καὶ λαβεῖν ἄδοξόν ἐστι· παίει δὲ ὁ βουλόμενος αὐτοὺς τῶν ἐντυγχανόντων. οἱ δὲ καρτεροῦσι περιϊόντες αὐχμηροὶ καὶ ταπεινοί, τρίβωνάς τε προσερραμμένους χρώματος βαπτοῦ φοροῦσι, καὶ ξυρῶνται μέρος τῆς ὑπήνης, μέρος δὲ τρέφουσι. δεινὸν οὖν ἦν τοιούτους ἐν τῇ πόλει περιορᾶν πολλοὺς οὐκ ὀλίγων δεομένῃ στρατιωτῶν, καὶ νομοθέτην αἱροῦνται τὸν Ἀγησίλαον. ὁ δὲ μήτε προσθείς τι μήτε ἀφελὼν μήτε μεταγράψας εἰσῆλθεν εἰς τὸ πλῆθος τῶν Λακεδαιμονίων καὶ φήσας ὅτι τούς νόμους δεῖ σήμερον ἐᾶν καθεύδειν, ἐκ δὲ τῆς σήμερον ἡμέρας κυρίους εἶναι πρὸς τὸ λοιπόν, ἅμα τούς τε νόμους τῇ πόλει καὶ τούς ἄνδρας ἐπιτίμους ἐφύλαξε. βουλόμενος δὲ τὴν παροῦσαν ἀθυμίαν καὶ κατήφειαν ἀφελεῖν τῶν νέων ἐνέβαλεν εἰς Ἀρκαδίαν, καὶ μάχην μὲν ἰσχυρῶς ἐφυλάξατο συνάψαι τοῖς ἐναντίοις, ἑλὼν δὲ πολίχνην τινὰ τῶν Μαντινέων καὶ τὴν χώραν ἐπιδραμών, ἐλαφροτέραν ἐποίησε ταῖς ἐλπίσι καὶ ἡδίω τὴν πόλιν, ὡς οὐ παντάπασιν ἀπεγνωσμένην.", "st": "Ages. 30.1"}, {"sp": "N", "t": "ἐκ δὲ τούτου παρῆν εἰς τὴν Λακωνικὴν ὁ Ἐπαμεινώνδας μετὰ τῶν συμμάχων, οὐκ ἐλάττονας ἔχων τετρακισμυρίων ὁπλιτῶν, πολλοὶ δὲ καὶ ψιλοὶ καὶ ἄνοπλοι πρὸς ἁρπαγὴν συνηκολούθουν, ὥστε μυριάδας ἑπτὰ τοῦ σύμπαντος ὄχλου συνεισβαλεῖν εἰς τὴν Λακωνικήν. ἦν μὲν δὴ χρόνος οὐκ ἐλάττων ἐτῶν ἑξακοσίων ἀφ’ οὗ κατῴκουν τὴν Λακεδαίμονα Δωριεῖς· ἐν δὲ τούτῳ παντὶ τότε πρῶτον ὤφθησαν ἐν τῇ χώρᾳ πολέμιοι, πρότερον δὲ οὐδεὶς ἐτόλμησεν ἀλλὰ ἀδῄωτον καὶ ἄθικτον οὖσαν ἐμβαλόντες ἐπυρπόλουν καὶ διήρπαζον ἄχρι τοῦ ποταμοῦ καὶ τῆς πόλεως, μηδενὸς ἐπεξιόντος γὰρ Ἀγησίλαος οὐκ εἴα πρός τοσοῦτον, ὥς φησι Θεόπομπος, ῥεῦμα καὶ κλύδωνα πολέμου μάχεσθαι τοὺς Λακεδαιμονίους, ἀλλὰ τῆς πόλεως τὰ μέσα καὶ κυριώτατα τοῖς ὁπλίταις περιεσπειραμένος ἐκαρτέρει τὰς ἀπειλὰς καὶ τὰς μεγαλαυχίας τῶν Θηβαίων, προκαλουμένων ἐκεῖνον ὀνομαστὶ καὶ διαμάχεσθαι περὶ τῆς χώρας κελευόντων, ὃς τῶν κακῶν αἴτιός ἐστιν ἐκκαύσας τὸν πόλεμον. οὐχ ἧττον δὲ τούτων ἐλύπουν τὸν Ἀγησίλαον οἱ κατὰ τὴν πόλιν θόρυβοι καὶ κραυγαὶ καὶ διαδρομαὶ τῶν τε πρεσβυτέρων δυσανασχετούντων τὰ γινόμενα καὶ τῶν γυναικῶν οὐ δυναμένων ἡσυχάζειν, ἀλλὰ παντάπασιν ἐκφρόνων οὐσῶν πρός τε τὴν κραυγὴν καὶ τὸ πῦρ τῶν πολεμίων. ἠνία δὲ καὶ τὸ τῆς δόξης αὐτόν, ὅτι τὴν πόλιν μεγίστην παραλαβὼν καὶ δυνατωτάτην, ἑώρα συνεσταλμένον αὐτῆς τὸ ἀξίωμα καὶ τὸ αὔχημα κεκολουμένον, ᾧ καὶ αὐτὸς ἐχρήσατο πολλάκις, εἰπὼν ὅτι γυνὴ Λάκαινα καπνὸν οὐχ ἑώρακε πολέμιον, λέγεται δὲ καὶ Ἀνταλκίδας, Ἀθηναίου τινὸς ἀμφισβητοῦντος ὑπὲρ ἀνδρείας πρός αὐτὸν καὶ εἰπόντος, ἡμεῖς μέντοι πολλάκις ὑμᾶς ἀπὸ τοῦ Κηφισοῦ ἐδιώξαμεν, ὑποτυχεῖν, ἀλλ’ Ἡμεῖς γε οὐδέποτε ὑμᾶς ἀπὸ τοῦ Εὐρώτα. παραπλησίως δὲ καὶ πρός τὸν Ἀργεῖον ἀπεκρίνατο τῶν ἀσημοτέρων τις Σπαρτιατῶν· ὁ μὲν γὰρ εἶπε· πολλοὶ ὑμῶν ἐν τῇ Ἀργολίδι κεῖνται ὁ δὲ ἀπήντησεν ὑμῶν δέ γε οὐδεὶς ἐν τῇ Λακωνικῇ.", "st": "Ages. 31.1"}, {"sp": "N", "t": "τότε μέντοι τὸν Ἀνταλκίδαν φασὶν ἔφορον ὄντα τοὺς παῖδας εἰς Κύθηρα ὑπεκθέσθαι, περίφοβον γενόμενον. ὁ δὲ Ἀγησίλαος, ἐπιχειρούντων διαβαίνειν τὸν ποταμὸν τῶν πολεμίων καὶ βιάζεσθαι πρὸς τὴν πόλιν, ἐκλιπὼν τὰ λοιπὰ παρετάξατο πρὸ τῶν μέσων καὶ ὑψηλῶν. ἐρρύη δὲ πλεῖστος ἑαυτοῦ καὶ μέγιστος τότε ὁ Εὐρώτας, χιόνων γενομένων, καὶ τὸ ῥεῦμα μᾶλλον ὑπὸ ψυχρότητος ἢ τραχύτητος ἐγένετο σκληρὸν καὶ χαλεπὸν τοῖς Θηβαίοις. πορευόμενον δὲ πρῶτον τῆς φάλαγγος τὸν Ἐπαμεινώνδαν ἐδείκνυσάν τινες τῷ Ἀγησιλάῳ· κἀκεῖνος, ὡς λέγεται, πολὺν χρόνον ἐμβλέψας αὐτῷ καὶ συμπαραπέμψας τὴν ὄψιν οὐδὲν ἢ τοσοῦτον μόνον εἶπεν ὢ τοῦ μεγαλοπράγμονος ἀνθρώπου. ἐπεὶ δὲ φιλοτιμούμενος ὁ Ἐπαμεινώνδας ἐν τῇ πόλει μάχην συνάψαι καὶ στῆσαι τρόπαιον οὐκ ἴσχυσεν ἐξαγαγεῖν οὐδὲ προκαλέσασθαι τὸν Ἀγησίλαον, ἐκεῖνος μὲν ἀναζεύξας πάλιν ἐπόρθει τὴν χώραν, ἐν δὲ Λακεδαίμονι τῶν πάλαι τινὲς ὑπούλων καὶ πονηρῶν ὡς διακόσιοι συστραφέντες κατελάβοντο τὸ Ἰσσώριον, οὗ τὸ τῆς Ἀρτέμιδος ἱερόν ἐστιν, εὐερκῆ καὶ δυσεκβίαστον τόπον. ἐφ’ οὓς βουλομένων εὐθὺς ὠθεῖσθαι τῶν Λακεδαιμονίων, φοβηθεὶς τὸν νεωτερισμὸν ὁ Ἀγησίλαος ἐκέλευσε τοὺς μὲν ἄλλους ἡσυχίαν ἄγειν, αὐτὸς δὲ ἐν ἱματίῳ καὶ μεθ’ ἑνὸς οἰκέτου προσῄει, βοῶν ἄλλως ἀκηκοέναι τοῦ προστάγματος αὐτούς· οὐ γὰρ ἐνταῦθα κελεῦσαι συνελθεῖν οὐδὲ πάντας, ἀλλὰ τοὺς μὲν ἐκεῖ (δείξας ἕτερον τόπον), τοὺς δὲ ἀλλαχόσε τῆς πόλεως. οἱ δὲ ἀκούσαντες ἥσθησαν οἰόμενοι λανθάνειν, καὶ διαστάντες ἐπὶ τοὺς τόπους οὓς ἐκεῖνος ἐκέλευσεν ἀπεχώρουν. ὁ δὲ τὸ μὲν Ἰσσώριον εὐθὺς μεταπεμψάμενος ἑτέρους κατέσχε, τῶν δὲ συστάντων ἐκείνων περὶ πεντεκαίδεκά τινας συλλαβὼν νυκτὸς ἀπέκτεινεν. ἄλλη δὲ μείζων ἐμηνύθη συνωμοσία καὶ σύνοδος ἀνδρῶν Σπαρτιατῶν ἐπὶ πράγμασι νεωτέροις εἰς οἰκίαν κρύφα συνερχομένων, οὓς καὶ κρίνειν ἄπορον ἦν ἐν ταραχῇ τοσαύτῃ καὶ περιορᾶν ἐπιβουλεύοντας. ἀπέκτεινεν οὖν καὶ τούτους μετὰ τῶν ἐφόρων βουλευσάμενος ὁ Ἀγησίλαος ἀκρίτους, οὐδενὸς δίχα δίκης τεθανατωμένου πρότερον Σπαρτιατῶν. ἐπεὶ δὲ πολλοὶ τῶν συντεταγμένων εἰς τὰ ὅπλα περιοίκων καὶ εἱλώτων ἀπεδίδρασκον ἐκ τῆς πόλεως πρὸς τοὺς πολεμίους, καὶ τοῦτο πλείστην ἀθυμίαν παρεῖχεν, ἐδίδαξε τοὺς ὑπηρέτας περὶ ὄρθρον ἐπιφοιτᾶν ταῖς στιβάσι καὶ τὰ ὅπλα τῶν ἀποκεχωρηκότων λαμβάνειν καὶ ἀποκρύπτειν, ὅπως ἀγνοῆται τὸ πλῆθος.", "st": "Ages. 32.1"}, {"sp": "N", "t": "ἀναχωρῆσαι δὲ τοὺς Θηβαίους ἐκ τῆς Λακωνικῆς οἱ μὲν ἄλλοι λέγουσι χειμώνων γενομένων καὶ τῶν Ἀρκάδων ἀρξαμένων ἀπιέναι καὶ διαρρεῖν ἀτάκτως, οἱ δὲ τρεῖς μῆνας ἐμμεμενηκότας ὅλους καὶ τὰ πλεῖστα τῆς χώρας διαπεπορθηκότας· Θεόπομπος δέ φησιν, ἤδη τῶν βοιωταρχῶν ἐγνωκότων ἀπαίρειν, ἀφικέσθαι πρὸς αὐτοὺς Φρίξον, ἄνδρα Σπαρτιάτην, παρὰ Ἀγησιλάου δέκα τάλαντα κομίζοντα τῆς ἀναχωρήσεως μισθόν, ὥστε τὰ πάλαι δεδογμένα πράττουσιν αὐτοῖς ἐφόδιον παρὰ τῶν πολεμίων προσπεριγενέσθαι.", "st": "Ages. 32.8"}, {"sp": "N", "t": "τοῦτο μὲν οὖν οὐκ οἶδα ὅπως ἠγνόησαν οἱ ἄλλοι, μόνος δὲ Θεόπομπος ᾔσθετο. τοῦ δὲ σωθῆναι τήν Σπάρτην τότε πάντες αἴτιον ὁμολογοῦσι γενέσθαι τὸν Ἀγησίλαον, ὅτι τῶν ἐμφύτων αὐτῷ παθῶν, φιλονεικίας καὶ φιλοτιμίας, ἀποστάς, ἐχρήσατο τοῖς πράγμασιν ἀσφαλῶς. οὐ μέντοι τήν γε δύναμιν καὶ τήν δόξαν ἐδυνήθη τῆς πόλεως ἀναλαβεῖν ἐκ τοῦ πταίσματος, ἀλλ’ ὥσπερ σώματος ὑγιεινοῦ, λίαν δὲ ἀκριβεῖ καὶ κατησκημένῃ κεχρημένου διαίτῃ παρὰ πάντα τὸν χρόνον, ἁμαρτία μία καὶ ῥοπὴ τήν πᾶσαν ἔκλινεν εὐτυχίαν τῆς πόλεως· οὐκ ἀλόγως. πρὸς γὰρ εἰρήνην καὶ ἀρετὴν καὶ ὁμόνοιαν ἄριστα συντεταγμένῳ· πολιτεύματι προσαγαγόντες ἀρχὰς καὶ δυναστείας βιαίους, ὧν οὐδενὸς ἡγεῖτο δεῖσθαι πόλιν εὐδαιμόνως βιωσομένην ὁ Λυκοῦργος, ἐσφάλησαν.", "st": "Ages. 33.1"}, {"sp": "N", "t": "αὐτὸς μὲν οὖν ὁ Ἀγησίλαος ἤδη πρὸς τάς στρατείας ἀπειρήκει διὰ τὸ γῆρας, Ἀρχίδαμος δὲ ὁ υἱὸς αὐτοῦ, τήν ἐκ Σικελίας ἥκουσαν παρὰ τοῦ τυράννου βοήθειαν ἔχων, ἐνίκησεν Ἀρκάδας τήν λεγομένην ἄδακρυν μάχην οὐδεὶς γὰρ ἔπεσε τῶν μετ’ αὐτοῦ, συχνοὺς δὲ τῶν ἐναντίων ἀνεῖλεν. αὕτη μάλιστα τήν ἀσθένειαν ἤλεγξεν ἡ νίκη τῆς πόλεως. πρότερον μὲν γὰρ οὕτω σύνηθες ἡγοῦντο καὶ προσῆκον ἔργον αὐτοῖς εἶναι τὸ νικᾶν τοὺς πολεμίους, ὥστε μήτε θύειν τοῖς θεοῖς πλὴν ἀλεκτρυόνα νικητήριον ἐν τῇ πόλει, μήτε μεγαληγορεῖν τοὺς ἀγωνισαμένους, μήτε ὑπερχαίρειν τοὺς πυνθανομένους, ἀλλὰ καὶ τῆς ἐν Μαντινείᾳ μάχης γενομένης, ἣν Θουκυδίδης γέγραφε, τῷ πρώτῳ φράσαντι τήν νίκην οἱ ἄρχοντες ἐκ φιδιτίου κρέας ἔπεμψαν εὐαγγέλιον, ἄλλο δὲ οὐδέν· τότε δὲ τῆς μάχης ἀγγελθείσης καὶ τοῦ Ἀρχιδάμου προσιόντος οὐδεὶς ἐκαρτέρησεν, ἀλλὰ πρῶτος ὁ πατὴρ ἀπήντα δακρύων ὑπὸ χαρᾶς καὶ μετ’ ἐκεῖνον τὰ ἀρχεῖα, τῶν δὲ πρεσβυτέρων καὶ τῶν γυναικῶν τὸ πλῆθος ἐπὶ τὸν ποταμὸν κατῄει, τάς τε χεῖρας ὀρεγόντων καὶ θεοκλυτούντων, ὥσπερ ἀπεωσμένης τὰ παρ’ ἀξίαν ὀνείδη τῆς Σπάρτης καὶ λαμπρὸν αὖθις ἐξ ἀρχῆς τὸ φῶς ὁρώσης· ἐπεὶ πρότερόν γέ φασιν οὐδὲ ταῖς γυναιξὶν ἀντιβλέπειν τοὺς ἄνδρας αἰσχυνομένους ἐφ’ οἷς ἔπταισαν.", "st": "Ages. 33.3"}, {"sp": "N", "t": "οἰκιζομένης δὲ Μεσσήνης ὑπὸ τῶν περὶ τὸν Ἐπαμεινώνδαν, καὶ τῶν ἀρχαίων πολιτῶν πανταχόθεν εἰς αὐτὴν συμπορευομένων, διαμάχεσθαι μὲν οὐκ ἐτόλμων οὐδὲ κωλύειν ἐδύναντο, χαλεπῶς δὲ καὶ βαρέως πρὸς τὸν Ἀγησίλαον εἶχον, ὅτι χώραν οὔτε πλήθει τῆς Λακωνικῆς ἐλάττονα καὶ πρωτεύουσαν ἀρετῇ τῆς Ἑλληνικῆς ἔχοντες καὶ καρπούμενοι χρόνον τοσοῦτον ἐπὶ τῆς ἐκείνου βασιλείας ἀπολωλέκασι. διὸ καὶ προτεινομένην ὑπὸ τῶν Θηβαίων τὴν εἰρήνην ὁ Ἀγησίλαος οὐκ ἐδέξατο. μὴ βουλόμενος δὲ τῷ λόγῳ προέσθαι τοῖς ἔργῳ κρατοῦσι τὴν χώραν, ἀλλὰ φιλονεικῶν, ἐκείνην μὲν οὐκ ἀπέλαβε, μικροῦ δὲ τὴν Σπάρτην προσαπέβαλε καταστρατηγηθείς. ἐπεὶ γὰρ οἱ Μαντινεῖς αὖθις ἀπέστησαν τῶν Θηβαίων καὶ μετεπέμποντο τοὺς Λακεδαιμονίους, αἰσθόμενος ὁ Ἐπαμεινώνδας τὸν Ἀγησίλαον ἐξεστρατευμένον μετὰ τῆς δυνάμεως καὶ προσιόντα, λαθὼν τοὺς Μαντινεῖς ἀνέζευξε νυκτὸς ἐκ Τεγέας ἄγων ἐπ’ αὐτὴν τὴν Λακεδαίμονα τὸ στράτευμα, καὶ μικρὸν ἐδέησε παραλλάξας τὸν Ἀγησίλαον ἔρημον ἐξαίφνης καταλαβεῖν τὴν πόλιν.", "st": "Ages. 34.1"}, {"sp": "N", "t": "Εὐθύνου δὲ Θεσπιέως, ὡς Καλλισθένης φησίν, ὡς δὲ Ξενοφῶν, Κρητός τινος, ἐξαγγείλαντος τῷ Ἀγησιλάῳ, ταχὺ προπέμψας ἱππέα τοῖς ἐν τῇ πόλει φράσοντα, μετ’ οὐ πολὺ καὶ αὐτὸς παρῆλθεν εἰς τὴν Σπάρτην. ὀλίγῳ δὲ ὕστερον οἱ Θηβαῖοι διέβαινον τὸν Εὐρώταν καὶ προσέβαλλον τῇ πόλει, μάλα ἐρρωμένως τοῦ Ἀγησιλάου καὶ παρ’ ἡλικίαν ἐπαμύνοντος. οὐ γὰρ, ὡς πρότερον, ἀσφαλείας ἑώρα τὸν καιρὸν ὄντα καὶ φυλακῆς, ἀλλὰ μᾶλλον ἀπονοίας καὶ τόλμης, οἷς τὸν ἄλλον χρόνον οὐδέποτε πιστεύσας οὐδὲ χρησάμενος, τότε μόνοις ἀπεώσατο τὸν κίνδυνον, ἐκ τῶν χειρῶν τοῦ Ἐπαμεινώνδου τὴν πόλιν ἐξαρπάσας, καὶ στήσας τρόπαιον, καὶ τοῖς παισὶ καὶ ταῖς γυναιξὶν ἐπιδείξας τὰ κάλλιστα τροφεῖα τῇ πατρίδι τοὺς Λακεδαιμονίους ἀποδιδόντας, ἐν δὲ πρώτοις τὸν Ἀρχίδαμον ἀγωνιζόμενον ὑπερηφάνως τῇ τε ῥώμῃ τῆς ψυχῆς καὶ τῇ κουφότητι τοῦ σώματος, ὀξέως ἐπὶ τὰ θλιβόμενα τῆς μάχης διαθέοντα διὰ τῶν στενωπῶν καὶ πανταχοῦ μετ’ ὀλίγων ἀντερείδοντα τοῖς πολεμίοις·", "st": "Ages. 34.4"}, {"sp": "N", "t": "Ἰσίδαν δὲ δοκῶ, τὸν Φοιβίδου υἱόν, οὐ τοῖς πολίταις μόνον, ἀλλὰ καὶ τοῖς πολεμίοις θέαμα φανῆναι καινὸν καὶ ἀγαστόν. ἦν μὲν γὰρ ἐκπρεπὴς τὸ εἶδος καὶ τὸ μέγεθος τοῦ σώματος, ὥραν δὲ ἐν ᾗ τὸ ἥδιστον ἀνθοῦσιν ἄνθρωποι παριόντες εἰς ἄνδρας ἐκ παίδων εἶχε, γυμνὸς δὲ καὶ ὅπλων τῶν σκεπὸν τῶν καὶ ἱματίων, λίπα χρισάμενος τὸ σῶμα, καὶ τῇ μὲν ἔχων χειρὶ λόγχην, τῇ δὲ ξίφος, ἐξήλατο τῆς οἰκίας, καὶ διὰ μέσων τῶν μαχομένων ὠσάμενος ἐν τοῖς πολεμίοις ἀνεστρέφετο, παίων τὸν προστυχόντα καὶ καταβάλλων. ἐτρώθη δὲ ὑπ’ οὐδενός, εἴτε θεοῦ δι’ ἀρετὴν φυλάττοντος αὐτόν, εἴτε μεῖζόν τι καὶ κρεῖττον ἀνθρώπου φανεὶς τοῖς ἐναντίοις. ἐπὶ τούτῳ δὲ λέγεται τοὺς ἐφόρους στεφανώσαντας αὐτὸν εἶτα χιλίων δραχμῶν ἐπιβαλεῖν ζημίαν, ὅτι χωρὶς ὅπλων διακινδυνεύειν ἐτόλμησεν.", "st": "Ages. 34.7"}, {"sp": "N", "t": "ὀλίγαις δὲ ὕστερον ἡμέραις περὶ τὴν Μαντίνειαν ἐμαχέσαντο, καὶ τὸν Ἐπαμεινώνδαν ἤδη κρατοῦντα τῶν πρώτων, ἔτι δὲ ἐγκείμενον καὶ κατασπεύδοντα τὴν δίωξιν, Ἀντικράτης Λάκων ὑποστὰς ἔπαισε δόρατι μέν, ὡς Διοσκουρίδης ἱστόρηκε, Λακεδαιμόνιοι δὲ Μαχαιρίωνας ἔτι νῦν τοὺς ἀπογόνους τοῦ Ἀντικράτους καλοῦσιν, ὡς μαχαίρᾳ πατάξαντος. οὕτω γὰρ ἐθαύμασαν καὶ ὑπερηγάπησαν αὐτὸν φόβῳ τοῦ Ἐπαμεινώνδου ζῶντος, ὥστε τιμὰς μὲν ἐκείνῳ καὶ δωρεὰς ψηφίσασθαι, γένει δ’ ἀτέλειαν, ἣν ἔτι καὶ καθ’ ἡμᾶς ἔχει Καλλικράτης, εἷς τῶν Ἀντικράτους ἀπογόνων.", "st": "Ages. 35.1"}, {"sp": "N", "t": "μετὰ δὲ τὴν μάχην καὶ τὸν θάνατον τοῦ Ἐπαμεινώνδου γενομένης εἰρήνης τοῖς Ἕλλησι πρὸς αὑτούς, ἀπήλαυνον οἱ περὶ τὸν Ἀγησίλαον τοῦ ὅρκου τοὺς Μεσσηνίους, ὡς πόλιν οὐκ ἔχοντας. ἐπεὶ δὲ οἱ λοιποὶ πάντες ἐδέχοντο καὶ τοὺς ὅρκους ἐλάμβανον παρ’ αὐτῶν, ἀπέστησαν οἱ Λακεδαιμόνιοι, καὶ μόνοις αὐτοῖς πόλεμος ἦν ἐλπίζουσιν ἀναλήψεσθαι τὴν Μεσσηνίαν. βίαιος οὖν ἐδόκει καὶ ἀτενὴς καὶ πολέμων ἄπληστος ὁ Ἀγησίλαος εἶναι, τὰς μὲν κοινὰς διαλύσεις πάντα τρόπον ὑπορύττων καὶ ἀναβάλλων, πάλιν δὲ ὑπὸ χρημάτων ἀπορίας ἀναγκαζόμενος ἐνοχλεῖν τοῖς κατὰ πόλιν φίλοις καὶ δανείζεσθαι καὶ συνερανίζεσθαι, δέον ἀπηλλάχθαι κακῶν εἰς τοῦτο περιήκοντι τῷ καιρῷ, καὶ μὴ τὴν ἅπασαν ἀρχὴν τοσαύτην γενομένην ἀφεικότα καὶ πόλεις καὶ γῆν καὶ θάλατταν, ὑπὲρ τῶν ἐν Μεσσήνῃ κτημάτων καὶ προσόδων σφαδάζειν.", "st": "Ages. 35.3"}, {"sp": "N", "t": "ἔτι δὲ μᾶλλον ἠδόξησε Τάχῳ τῷ Αἰγυπτίῳ στρατηγὸν ἐπιδοὺς ἑαυτόν· οὐ γὰρ ἠξίουν ἄνδρα τῆς Ἑλλάδος ἄριστον κεκριμένον καὶ δόξης ἐμπεπληκότα τὴν οἰκουμένην, ἀποστάτῃ βασιλέως, ἀνθρώπῳ βαρβάρῳ, χρῆσαι τὸ σῶμα καὶ τοὔνομα καὶ τὴν δόξαν ἀποδόσθαι χρημάτων, ἔργα μισθοφόρου καὶ ξεναγοῦ διαπραττόμενον. κεἰ γὰρ ὑπὲρ ὀγδοήκοντα γεγονὼς ἔτη καὶ πᾶν ὑπὸ τραυμάτων τὸ σῶμα κατακεκομμένος ἐκείνην αὖθις ἀνεδέξατο τὴν καλὴν καὶ περίβλεπτον ἡγεμονίαν ὑπὲρ τῆς τῶν Ἑλλήνων ἐλευθερίας, οὐ πάμπαν ἄμεμπτον εἶναι τὴν φιλοτιμίαν· τοῦ γὰρ καλοῦ καιρὸν οἰκεῖον εἶναι καὶ ὥραν, μᾶλλον δὲ ὅλως τὰ καλὰ τῶν αἰσχρῶν τῷ μετρίῳ διαφέρειν. οὐ μὴν ἐφρόντιζε τούτων ὁ Ἀγησίλαος, οὐδὲ ᾤετο παρ’ ἀξίαν εἶναι λειτούργημα δημόσιον οὐδέν, ἀλλὰ μᾶλλον ἀνάξιον ἑαυτοῦ τὸ ζῆν ἄπρακτον ἐν τῇ πόλει καὶ καθῆσθαι περιμένοντα τὸν θάνατον, ὅθεν ἀθροίσας μισθοφόρους ἀφ’ ὧν ὁ Τάχως αὐτῷ χρημάτων ἔπεμψε, καὶ πλοῖα πληρώσας, ἀνήχθη, τριάκοντα συμβούλους ἔχων μεθ’ ἑαυτοῦ Σπαρτιάτας, ὡς πρότερον.", "st": "Ages. 36.1"}, {"sp": "N", "t": "ἐπεὶ δὲ κατέπλευσεν εἰς τὴν Αἴγυπτον, εὐθὺς οἱ πρῶτοι τῶν βασιλικῶν ἡγεμόνων καὶ διοικητῶν ἐβάδιζον ἐπὶ ναῦν θεραπεύοντες αὐτόν, ἦν δὲ καὶ τῶν ἄλλων Αἰγυπτίων σπουδή τε μεγάλη καὶ προσδοκία διὰ τοὔνομα καὶ τὴν δόξαν τοῦ Ἀγησιλάου, καὶ συνετρόχαζον ἅπαντες ἐπὶ τὴν θέαν. ὡς δὲ ἑώρων λαμπρότητα μὲν καὶ κατασκευὴν οὐδεμίαν, ἄνθρωπον δὲ πρεσβύτην κατακείμενον ἔν τινι πόᾳ παρὰ τὴν θάλασσαν, εὐτελῆ καὶ μικρὸν τὸ σῶμα, τραχὺ καὶ φαῦλον ἱμάτιον ἀμπεχόμενον, σκώπτειν αὐτοῖς καὶ γελωτοποιεῖν ἐπῄει, καὶ λέγειν ὅτι τοῦτο ἦν τὸ μυθολογούμενον ὠδίνειν ὄρος, εἶτα μῦν ἀποτεκεῖν. ἔτι δὲ μᾶλλον αὐτὸν τὴν ἀτοπίαν ἐθαύμασαν, ὅτε ξενίων προσκομισθέντων καὶ προσαχθέντων ἄλευρα μὲν καὶ μόσχους καὶ χῆνας ἔλαβε, τραγήματα δὲ καὶ πέμματα καὶ μύρα διωθεῖτο, καὶ βιαζομένων λαβεῖν καὶ λιπαρούντων ἐκέλευσε τοῖς εἵλωσι διδόναι κομίζοντας. τῇ μέντοι στεφανωτρίδι βύβλῳ φησὶν αὐτὸν ἡσθέντα Θεόφραστος διὰ τὴν λιτότητα καὶ καθαριότητα τῶν στεφάνων αἰτήσασθαι καὶ λαβεῖν, ὅτε ἀπέπλει, παρὰ τοῦ βασιλέως.", "st": "Ages. 36.4"}, {"sp": "N", "t": "τότε δὲ συμμίξας τῷ Τάχῳ παρασκευαζομένῳ πρὸς τὴν στρατείαν, οὐχ, ὥσπερ ἤλπιζεν, ἁπάσης στρατηγὸς ἀπεδείχθη τῆς δυνάμεως, ἀλλὰ τῶν μισθοφόρων μόνων, τὸν δὲ ναυτικοῦ Χαβρίας ὁ Ἀθηναῖος· ἡγεμὼν δὲ συμπάντων αὐτὸς ἦν ὁ Τάχως. καὶ τοῦτο πρῶτον ἠνίασε τὸν Ἀγησίλαον· ἔπειτα τὴν ἄλλην ἀλαζονείαν καὶ κενοφροσύνην τοῦ Αἰγυπτίου βαρυνόμενος ἠναγκάζετο φέρειν καὶ συνεξέπλευσεν ἐπὶ τοὺς Φοίνικας αὐτῷ, παρὰ τὴν ἀξίαν τὴν ἑαυτοῦ καὶ τὴν φύσιν ὑπείκων καὶ καρτερῶν, ἄχρι οὗ καιρὸν ἔλαβε.", "st": "Ages. 37.1"}, {"sp": "N", "t": "Νεκτάναβις γὰρ ἀνεψιὸς ὢν τοῦ Τάχω καὶ μέρος ἔχων ὑφ’ ἑαυτῷ τῆς δυνάμεως ἀπέστη· καὶ βασιλεὺς ὑπὸ τῶν Αἰγυπτίων ἀναγορευθεὶς διεπέμπετο πρὸς τὸν Ἀγησίλαον ἀξιῶν αὐτῷ βοηθεῖν τὰ δ’ αὐτὰ καὶ τὸν Χαβρίαν παρεκάλει, μεγάλας ὑπισχνούμενος ἀμφοτέροις δωρεάς. αἰσθομένου δὲ ταῦτα τοῦ Τάχω καὶ τραπομένου πρὸς δέησιν αὐτῶν, ὁ μὲν Χαβρίας ἐπειρᾶτο καὶ τὸν Ἀγησίλαον ἐν τῇ φιλίᾳ τοῦ Τάχω πείθων καὶ παραμυθούμενος κατέχειν, ὁ δὲ Ἀγησίλαος εἶπεν ὅτι σοὶ μέν, ὦ Χαβρία, κατὰ σεαυτὸν ἀφιγμένῳ χρῆσθαι τοῖς ἑαυτοῦ λογισμοῖς ἔξεστιν, ἐγὼ δὲ ὑπὸ τῆς πατρίδος ἐδόθην Αἰγυπτίοις στρατηγός, οὐκ οὖν ἂν ἔχοι μοι καλῶς οἷς ἐπέμφθην σύμμαχος πολεμεῖν, ἐὰν μὴ πάλιν ἡ πατρὶς κελεύσῃ. ταῦτα δὲ εἰπὼν ἔπεμψεν εἰς Σπάρτην; ἄνδρας, οἳ τοῦ μὲν Τάχω κατηγορήσειν, ἐπαινέσεσθαι δὲ τὸν Νεκτάναβιν ἔμελλον. ἔπεμψαν δὲ κἀκεῖνοι δεόμενοι τῶν Λακεδαιμονίων, ὁ μὲν ὡς πάλαι σύμμαχος γεγονὼς καὶ φίλος, ὁ δὲ ὡς εὔνους καὶ προθυμότερος περὶ τὴν πόλιν ἐσόμενος. ἀκούσαντες οὖν οἱ Λακεδαιμόνιοι τοῖς μὲν Αἰγυπτίοις ἀπεκρίναντο φανερῶς Ἀγησιλάῳ περὶ τούτων μελήσειν, ἐκείνῳ δὲ ἐπέστειλαν ὁρᾶν κελεύοντες ὅπως πράξει τὸ τῇ Σπάρτῃ συμφέρον. οὕτω δὴ λαβὼν τοὺς μισθοφόρους ὁ Ἀγησίλαος ἀπὸ τοῦ Τάχω μετέστη πρὸς τὸν Νεκτάναβιν, ἀτόπου καὶ ἀλλοκότου πράγματος παρακαλύμματι τῷ συμφέροντι τῆς πατρίδος χρησάμενος· ἐπεὶ ταύτης γε τῆς προφάσεως ἀφαιρεθείσης τὸ δικαιότατον ὄνομα τῆς πράξεως ἦν προδοσία. Λακεδαιμόνιοι δὲ τὴν πρώτην τοῦ καλοῦ μερίδα τῷ τῆς πατρίδος συμφέροντι διδόντες οὔτε μανθάνουσιν οὔτε ἐπίστανται δίκαιον ἄλλο πλὴν ὃ τὴν Σπάρτην αὔξειν νομίζουσιν.", "st": "Ages. 37.3"}, {"sp": "N", "t": "ὁ μέν οὖν Τάχως ἐρημωθεὶς τῶν μισθοφόρων ἔφυγεν, ἐκ δὲ Μένδητος ἕτερος ἐπανίσταται τῷ Νεκτανάβιδι βασιλεὺς ἀναγορευθείς· καὶ συναγαγὼν δέκα μυριάδας ἀνθρώπων ἐπῄει. θαρσύνοντος δὲ τοῦ Νεκτανάβιδος τὸν Ἀγησίλαον, καὶ λέγοντος ὅτι πολλοὶ μέν εἰσιν οἱ πολέμιοι, μιγάδες δὲ Καὶ βάναυσοι Καὶ δι’ ἀπειρίαν εὐκαταφρόνητοι, καὶ μὴν οὐ τὸ πλῆθος αὐτῶν, ὁ Ἀγησίλαος εἶπεν, ἀλλὰ τὴν ἀπειρίαν φοβοῦμαι καὶ τὴν ἀμαθίαν ὡς δυσεξαπάτητον. αἱ γὰρ ἀπάται τὸ παράδοξον ἐπάγουσι τοῖς πρὸς ἄμυναν ὑπονοοῦσι Καὶ προσδοκῶσι τρεπομένοις, ὁ δὲ μὴ προσδοκῶν μηδὲ ὑπονοῶν μηδὲν οὐ δίδωσι τῷ παραλογιζομένῳ λαβήν, ὥσπερ οὐδὲ τῷ παλαίοντι ῥοπὴν ὁ μὴ κινούμενος. ἐκ τούτου Καὶ ὁ Μενδήσιος ἔπεμπε πειρῶν τὸν Ἀγησίλαον. ἔδεισεν οὖν ὁ Νεκτάναβις, Καὶ κελεύοντος αὐτοῦ διαμάχεσθαι τὴν ταχίστην Καὶ μὴ χρόνῳ πολεμεῖν πρὸς ἀνθρώπους ἀπείρους ἀγῶνος, πολυχειρίᾳ δὲ περιελθεῖν Καὶ περιταφρεῦσαι Καὶ φθάσαι πολλὰ Καὶ προλαβεῖν δυναμένους, ἔτι μᾶλλον ἐν ὑποψίᾳ Καὶ φόβῳ γενόμενος πρὸς αὐτὸν ἀπεχώρησεν εἰς πόλιν εὐερκῆ Καὶ μέγαν ἔχουσαν περίβολον. ὁ δὲ Ἀγησίλαος ἠγανάκτει μέν ἀπιστούμενος Καὶ βαρέως ἔφερεν, αἰσχυνόμενος δὲ Καὶ πάλιν μεταστῆναι πρὸς τὸν ἕτερον Καὶ τελέως ἀπελθεῖν ἄπρακτος, ἠκολούθησε Καὶ συνεισῆλθεν εἰς τὸ τεῖχος.", "st": "Ages. 38.1"}, {"sp": "N", "t": "ἐπελθόντων δὲ τῶν πολεμίων καὶ περιταφρευόντων τὴν πόλιν, αὖθις αὖ δείσας τὴν πολιορκίαν ὁ Αἰγύπτιος ἐβούλετο μάχεσθαι καὶ τοὺς Ἕλληνας μάλα συμπροθυμουμένους εἶχεν· οὐ γὰρ ἦν ἐν τῷ χωρίῳ σῖτος, ὁ δὲ Ἀγησίλαος οὐκ ἐῶν, ἀλλὰ κωλύων ἤκουε μὲν ἔτι μᾶλλον κακῶς ἢ πρότερον ὑπὸ τῶν Αἰγυπτίων καὶ προδότης ἀπεκαλεῖτο τοῦ βασιλέως, ἔφερε δὲ πρᾳότερον ἤδη τὰς διαβολὰς καὶ προσεῖχε τῷ καιρῷ τοῦ στρατηγήματος.", "st": "Ages. 39.1"}, {"sp": "N", "t": "ἦν δὲ τοιόνδε. τάφρον ἔξωθεν ἦγον οἱ πολέμιοι περὶ τὸ τεῖχος βαθεῖαν ὡς παντάπασιν ἀποκλείσοντες αὐτούς, ὡς οὖν ἐγγὺς ἦσαν αἱ τελευταὶ τοῦ ὀρύγματος ἀπαντῶντος αὑτῷ καὶ περιϊόντος ἐν κύκλῳ τὴν πόλιν, ἑσπέραν ἀναμείνας γενέσθαι καὶ κελεύσας ἐξοπλίζεσθαι τοὺς Ἕλληνας ἔλεγεν ἐλθὼν πρὸς τὸν Αἰγύπτιον· ὁ μὲν τῆς σωτηρίας, ὦ νεανία, καιρὸς οὗτός ἐστιν, ὃν ἐγὼ διαφθεῖραι φοβούμενος οὐκ ἔφραζον πρὶν ἐλθεῖν. ἐπεὶ δὲ ἡμῖν οἱ πολέμιοι τὴν ἀσφάλειαν αὐτοὶ διὰ τῶν χειρῶν παρεσκευάκασι, τοσαύτην ὀρυξάμενοι τάφρον, ἧς τὸ μὲν ἐξειργασμένον ἐκείνοις ἐμποδών ἐστι τοῦ πλήθους, τὸ δὲ διαλεῖπον ἡμῖν δίδωσιν ἴσῳ καὶ δικαίῳ μέτρῳ διαμάχεσθαι πρὸς αὐτούς, φέρε νῦν, προθυμηθεὶς ἀνὴρ ἀγαθὸς γενέσθαι καὶ μεθ’ ἡμῶν ἐπισπόμενος δρόμῳ σῶζε σεαυτὸν ἅμα καὶ τὴν στρατιάν. ἡμᾶς γὰρ οἱ μὲν κατὰ στόμα τῶν πολεμίων οὐχ ὑπομενοῦσιν, οἱ δὲ ἄλλοι διὰ τὴν τάφρον οὐ βλάψουσιν. ἐθαύμασεν οὖν ὁ Νεκτάναβις τοῦ Ἀγησιλάου τὴν δεινότητα, καὶ δοὺς ἑαυτὸν εἰς μέσα τὰ τῶν Ἑλλήνων ὅπλα καὶ προσπεσὼν ἐτρέψατο ῥᾳδίως τοὺς ἀντιστάντας. ὡς δὲ ἅπαξ ἔλαβε πειθόμενον αὑτῷ τὸν Νεκτάναβιν ὁ Ἀγησίλαος, αὖθις ἐπῆγε τὸ αὐτὸ στρατήγημα καθάπερ πάλαισμα τοῖς πολεμίοις. τὰ μὲν γὰρ ὑποφεύγων καὶ ὑπάγων, τὰ δὲ ἀντιπεριχωρῶν, ἐμβάλλει τὸ πλῆθος αὐτῶν εἰς τόπον ἔχοντα διώρυχα βαθεῖαν ἐξ ἑκατέρας πλευρᾶς παραρρέουσαν, ὧν τὸ μέσον ἐμφράξας καὶ καταλαβὼν τῷ μετώπῳ τῆς φάλαγγος ἐξίσωσε πρὸς τοὺς μαχομένους τῶν πολεμίων τὸ πλῆθος, οὐκ ἔχοντας περιδρομὴν καὶ κύκλωσιν. ὅθεν οὐ πολὺν χρόνον ἀντιστάντες ἐτράποντο· καὶ πολλοὶ μὲν ἀνῃρέθησαν, οἱ δὲ φεύγοντες ἐσκεδάσθησαν καὶ διερρύησαν.", "st": "Ages. 39.2"}, {"sp": "N", "t": "ἐκ δὲ τούτου καλῶς μὲν εἶχε τὰ πράγματα καὶ βεβαίως τῷ Αἰγυπτίῳ πρὸς ἀσφάλειαν ἀγαπῶν δὲ καὶ φιλοφρονούμενος ἐδεῖτο μεῖναι καὶ συνδιαχειμάσαι μετ’ αὐτοῦ τὸν Ἀγησίλαον. ὁ δὲ ὥρμητο πρὸς τὸν οἴκοι πόλεμον, εἰδὼς χρημάτων δεομένην τὴν πόλιν καὶ ξενοτροφοῦσαν. προὔπεμψεν οὖν αὐτὸν ἐντίμως καὶ μεγαλοπρεπῶς, ἄλλας τε λαβόντα τιμὰς καὶ δωρεὰς καὶ πρὸς τὸν πόλεμον ἀργυρίου διακόσια καὶ τριάκοντα τάλαντα. χειμῶνος δὲ ὄντος ἤδη τῆς γῆς ἐχόμενος ταῖς ναυσὶ καὶ παρὰ τὴν Λιβύην εἰς χωρίον ἔρημον κομισθείς, ὃ καλοῦσι Μενελάου λιμένα, θνήσκει, βιώσας μὲν ὀγδοήκοντα καὶ τέσσαρα ἔτη, βασιλεύσας δὲ τῆς Σπάρτης ἑνὶ τῶν τεσσαράκοντα πλέον, καὶ τούτων ὑπὲρ τριάκοντα πάντων μέγιστος καὶ δυνατώτατος γενόμενος καὶ σχεδὸν ὅλης τῆς Ἑλλάδος ἡγεμὼν καὶ βασιλεὺς νομισθεὶς ἄχρι τῆς ἐν Λεύκτροις μάχης.", "st": "Ages. 40.1"}, {"sp": "N", "t": "ἔθους δὲ ὄντος Λακωνικοῦ τῶν μὲν ἄλλων ἐπὶ ξένης ἀποθανόντων αὐτοῦ τὰ σώματα κηδεύειν καὶ ἀπολείπειν, τὰ δὲ τῶν βασιλέων οἴκαδε κομίζειν, οἱ παρόντες Σπαρτιᾶται κηρὸν ἐπιτήξαντες τῷ νεκρῷ, μέλιτος οὐ παρόντος, ἀπῆγον εἰς Λακεδαίμονα, τὴν δὲ βασιλείαν Ἀρχίδαμος ὁ υἱὸς αὐτοῦ παρέλαβε, καὶ διέμεινε τῷ γένει μέχρις Ἄγιδος, ὃν ἐπιχειροῦντα τὴν πάτριον ἀναλαβεῖν πολιτείαν ἀπέκτεινε Λεωνίδας πέμπτον ἀπ’ Ἀγησιλάου γεγονότα.", "st": "Ages. 40.3"}, {"sp": "HDR", "t": "Πομπήϊος"}, {"sp": "N", "t": "πρὸς Πομπήϊον ἔοικε τοῦτο παθεῖν ὁ Ῥωμαίων δῆμος εὐθὺς ἐξ ἀρχῆς, ὅπερ ὁ Αἰσχύλου Προμηθεὺς πρὸς τὸν Ἡρακλέα σωθεὶς ὑπ’ αὐτοῦ καὶ λέγων", "st": "Pomp. 1.1"}, {"sp": "N", "t": "ἐχθροῦ πατρός μοι τοῦτο φίλτατον τέκνον.", "st": "Pomp. 1.1b"}, {"sp": "N", "t": "οὔτε γὰρ μῖσος οὕτως ἰσχυρὸν καὶ ἄγριον ἐπεδείξαντο Ῥωμαῖοι πρὸς ἕτερον στρατηγὸν ὡς τὸν Πομπηΐου πατέρα Στράβωνα, ζῶντος μὲν αὐτοῦ φοβούμενοι τὴν ἐν τοῖς ὅπλοις δύναμιν (ἦν γὰρ ἀνὴρ πολεμικώτατος), ἐπεὶ δὲ ἀπέθανε κεραυνωθείς, ἐκκομιζόμενον τὸ σῶμα κατασπάσαντες ἀπὸ τοῦ λέχους καὶ καθυβρίσαντες, οὔτε μὴν εὔνοιαν αὖ πάλιν σφοδροτέραν ἢ θᾶσσον ἀρξαμένην ἢ μᾶλλον εὐτυχοῦντι συνακμάσασαν ἢ πταίσαντι παραμείνασαν βεβαιότερον ἄλλος ἔσχε Ῥωμαίων ἢ Πομπήϊος. αἰτία δὲ τοῦ μὲν μίσους ἐκείνῳ μία, χρημάτων ἄπληστος ἐπιθυμία, τούτῳ δὲ πολλαὶ τοῦ ἀγαπᾶσθαι, σωφροσύνη περὶ δίαιταν, ἄσκησις ἐν ὅπλοις, πιθανότης λόγου, πίστις ἤθους, εὐαρμοστία πρὸς ἔντευξιν, ὡς μηδενὸς ἀλυπότερον δεηθῆναι μηδὲ ἥδιον ὑπουργῆσαι δεομένῳ. προσῆν γὰρ αὐτοῦ ταῖς χάρισι καὶ τὸ ἀνεπαχθὲς διδόντος καὶ τὸ σεμνὸν λαμβάνοντος.", "st": "Pomp. 1.2"}, {"sp": "N", "t": "ἐν ἀρχῇ δὲ καὶ τὴν ὄψιν ἔσχεν οὐ μετρίως συνδημαγωγοῦσαν καὶ προεντυγχάνουσαν αὑτοῦ τῆς φωνῆς, τὸ γὰρ ἐράσμιον ἀξιωματικὸν ἦν φιλανθρώπως, καὶ ἐν τῷ νεαρῷ καὶ ἀνθοῦντι διέφαινεν εὐθὺς ἡ ἀκμὴ τὸ γεραρὸν καὶ τὸ βασιλικὸν τοῦ ἤθους, ἦν δέ τις καὶ ἀναστολὴ τῆς κόμης ἀτρέμα καὶ τῶν περὶ τὰ ὄμματα ῥυθμῶν ὑγρότης τοῦ προσώπου, ποιοῦσα μᾶλλον λεγομένην ἢ φαινομένην ὁμοιότητα πρὸς τὰς Ἀλεξάνδρου τοῦ βασιλέως εἰκόνας. ᾗ καὶ τοὔνομα πολλῶν ἐν ἀρχῇ συνεπιφερόντων οὐκ ἔφευγεν ὁ Πομπήϊος, ὥστε καὶ χλευάζοντας αὐτὸν ἐνίους ἤδη καλεῖν Ἀλέξανδρον. διὸ καὶ Λεύκιος Φίλιππος, ἀνὴρ ὑπατικός, συνηγορῶν αὐτῷ, μηδὲν ἔφη ποιεῖν παράλογον εἰ Φίλιππος ὢν φιλαλέξανδρός ἐστιν.", "st": "Pomp. 2.1"}, {"sp": "N", "t": "Φλώραν δὲ τὴν ἑταίραν ἔφασαν ἤδη πρεσβυτέραν οὖσαν ἐπιεικῶς ἀεὶ μνημονεύειν τῆς γενομένης αὐτῇ πρὸς Πομπήϊον ὁμιλίας, λέγουσαν ὡς οὐκ ἦν ἐκείνῳ συναναπαυσαμένην ἀδήκτως ἀπελθεῖν. πρὸς δὲ τούτοις διηγεῖσθαι τὴν Φλώραν ἐπιθυμῆσαί τινα τῶν Πομπηΐου συνήθων αὐτῆς Γεμίνιον, καὶ πράγματα πολλὰ παρέχειν πειρῶντα· αὐτῆς δὲ φαμένης οὐκ ἂν ἐθελῆσαι διὰ Πομπήϊον, ἐκείνῳ τὸν Γεμίνιον διαλέγεσθαι· τὸν οὖν Πομπήϊον ἐπιτρέψαι μὲν τῷ Γεμινίῳ, μηκέτι δὲ αὐτὸν ἅψασθαι τὸ παράπαν μηδὲ ἐντυχεῖν αὐτῇ, καίπερ ἐρᾶν δοκοῦντα· τοῦτο δὲ αὐτὴν οὐχ ἑταιρικῶς ἐνεγκεῖν, ἀλλὰ πολὺν ὑπὸ λύπης καὶ πόθου χρόνον νοσῆσαι. καίτοι τὴν Φλώραν οὕτω λέγουσιν ἀνθῆσαι καὶ γενέσθαι περιβόητον ὥστε Κεκίλιον Μέτελλον ἀνδριάσι καὶ γραφαῖς κοσμοῦντα τὸν νεὼν τῶν Διοσκούρων, κἀκείνης εἰκόνα γραψάμενον ἀναθεῖναι διὰ τὸ κάλλος. Πομπήϊος δὲ καὶ τῇ Δημητρίου τοῦ ἀπελευθέρου γυναικί, πλεῖστον ἰσχύσαντος παρ’ αὐτῷ καὶ τετρακισχιλίων ταλάντων ἀπολιπόντος οὐσίαν, ἐχρῆτο παρὰ τὸν αὑτοῦ τρόπον οὐκ ἐπιεικῶς οὐδὲ ἐλευθερίως, φοβηθεὶς τὴν εὐμορφίαν αὐτῆς ἄμαχόν τινα καὶ περιβόητον οὖσαν, ὡς μὴ φανείη κεκρατημένος. οὕτω δὲ πάνυ πόρρωθεν εὐλαβὴς ὢν πρὸς τὰ τοιαῦτα καὶ πεφυλαγμένος, ὅμως οὐ διέφυγε τῶν ἐχθρῶν τὸν ἐπὶ τούτῳ ψόγον, ἀλλ’ ἐπὶ ταῖς γαμεταῖς ἐσυκοφαντεῖτο πολλὰ τῶν κοινῶν παριδεῖν καὶ προέσθαι χαριζόμενος ἐκείναις.", "st": "Pomp. 2.3"}, {"sp": "N", "t": "τῆς δὲ περὶ τὴν δίαιταν εὐκολίας καὶ λιτότητος καὶ ἀπομνημόνευμα λέγεται τοιοῦτον. ἰατρὸς αὐτῷ νοσοῦντι καὶ κακῶς ἔχοντι πρὸς τὰ σιτία κίχλην προσέταξε λαβεῖν, ὡς δὲ ζητοῦντες οὐχ εὗρον ὤνιον ἦν γὰρ παρ’ ὥραν, ἔφη δέ τις εὑρεθήσεσθαι παρὰ Λευκόλλῳ δι’ ἔτους τρεφομένας, εἶτα, εἶπεν, εἰ μὴ Λεύκολλος ἐτρύφα, Πομπήϊος οὐκ ἂν ἔζησε; καὶ χαίρειν ἐάσας τὸν ἰατρὸν ἔλαβέ τι τῶν εὐπορίστων. ταῦτα μὲν οὖν ὕστερον.", "st": "Pomp. 2.6"}, {"sp": "N", "t": "ἔτι δὲ μειράκιον ὢν παντάπασι καὶ τῷ πατρὶ συστρατευόμενος ἀντιτεταγμένῳ πρὸς Κίνναν, Λευκιόν τινα Τερέντιον εἶχεν ἑταῖρον καὶ σύσκηνον. οὗτος ὑπὸ Κίννα πεισθεὶς χρήμασιν αὐτὸς μὲν ἔμελλε Πομπήϊον ἀποκτενεῖν, ἕτεροι δὲ τὴν σκηνὴν ἐμπρήσειν τοῦ στρατηγοῦ. μηνύσεως δὲ τῷ Πομπηΐῳ περὶ δεῖπνον ὄντι προσπεσούσης, οὐδὲν διαταραχθείς, ἀλλὰ καὶ πιὼν προθυμότερον καὶ φιλοφρονησάμενος τὸν Τερέντιον, ἅμα τῷ τραπέσθαι πρὸς ἀνάπαυσιν ὑπεκρυεὶς τῆς σκηνῆς ἔλαθε, καὶ τῷ πατρὶ φρουρὰν περιστήσας ἡσύχαζεν. ὁ δὲ Τερέντιος, ὡς ἐνόμιζε καιρὸν εἶναι, σπασάμενος τὸ ξίφος ἀνέστη καὶ τῇ στιβάδι τοῦ Πομπηΐου προσελθὼν ὡς κατακειμένου πολλὰς ἐνεφόρει πληγὰς τοῖς στρώμασι. ἐκ δὲ τούτου γίνεται μέγα κίνημα μίσει τοῦ στρατηγοῦ, καὶ πρὸς ἀπόστασιν ὁρμὴ τῶν στρατιωτῶν, τάς τε σκηνὰς ἀνασπώντων καὶ τὰ ὅπλα λαμβανόντων, ὁ μὲν οὖν στρατηγὸς οὐ προῄει δεδιὼς τὸν θόρυβον, ὁ δὲ Πομπήϊος ἐν μέσοις ἀναστρεφόμενος καὶ δακρύων ἱκέτευε, τέλος δὲ ῥίψας ἑαυτὸν ἐπὶ στόμα πρὸ τῆς πύλης τοῦ χάρακος ἐμποδὼν ἔκειτο κλαίων καὶ πατεῖν κελεύων τοὺς ἐξιόντας, ὥστε ἕκαστον ἀναχωρεῖν ὑπ’ αἰδοῦς καὶ πάντας οὕτω πλὴν ὀκτακοσίων μεταβαλέσθαι καὶ διαλλαγῆναι πρὸς τὸν στρατηγόν.", "st": "Pomp. 3.1"}, {"sp": "N", "t": "ἅμα δὲ τῷ τελευτῆσαι τὸν Στράβωνα, δίκην κλοπῆς ἔσχεν ὑπὲρ αὐτοῦ δημοσίων χρημάτων ὁ Πομπήϊος, καὶ τὰ μὲν πλεῖστα φωράσας ἕνα τῶν ἀπελευθέρων ὁ Πομπήϊος νενοσφισμένον Ἀλέξανδρον, ἀπέδειξε τοῖς ἄρχουσιν, αὐτὸς δὲ λίνα θηρατικὰ καὶ βιβλία τῶν ἐν Ἄσκλῳ ληφθέντων ἔχειν κατηγορεῖτο. ταῦτα δὲ ἔλαβε μὲν παρὰ τοῦ πατρὸς ἑλόντος τὸ Ἄσκλον, ἀπώλεσε δὲ τῶν Κίννα δορυφόρων, ὅτε κατῆλθεν, ὠσαμένων εἰς τὴν οἰκίαν αὐτοῦ καὶ διαρπασάντων. ἐγίνοντο δὲ τῆς δίκης αὐτῷ προαγῶνες οὐκ ὀλίγοι πρὸς τὸν κατήγορον. ἐν οἷς ὀξὺς ἅμα καὶ παρ’ ἡλικίαν εὐσταθὴς φαινόμενος δόξαν ἔσχε μεγάλην καὶ χάριν, ὥστε Ἀντίστιον στρατηγοῦντα καὶ βραβεύοντα τὴν δίκην ἐκείνην ἐρασθῆναι τοῦ Πομπηΐου καὶ γυναῖκα διδόναι τὴν ἑαυτοῦ θυγατέρα καὶ περὶ τούτου τοῖς φίλοις διαλέγεσθαι. δεξαμένου δὲ Πομπηΐου καὶ γενομένων ἐν αὐτοῖς ἀπορρήτων ὁμολογιῶν, ὅμως οὐκ ἔλαθε τοὺς πολλοὺς τὸ πρᾶγμα διὰ τὴν τοῦ Ἀντιστίου σπουδήν. τέλος δὲ τὴν γνώμην ἀναγορεύσαντος αὐτοῦ τῶν δικαστῶν ἀπολύουσαν, ὥσπερ ἐκ παραγγέλματος ὁ δῆμος ἐπεφώνησε τοῦτο δὴ τὸ τοῖς γαμοῦσιν ἐπιφωνούμενον ἐξ ἔθους παλαιοῦ, Ταλασίῳ.", "st": "Pomp. 4.1"}, {"sp": "N", "t": "τὸ δὲ ἔθος ἀρχὴν λαβεῖν φασὶ τοιαύτην. ὅτε τὰς θυγατέρας τῶν Σαβίνων ἐπὶ θέαν ἀγῶνος εἰς Ῥώμην παραγενομένας οἱ πρωτεύοντες ἀρετῇ Ῥωμαίων ἥρπαζον ἑαυτοῖς γυναῖκας, ἄδοξοί τινες πελάται καὶ βοτῆρες ἀράμενοι κόρην καλὴν καὶ μεγάλην ἐκόμιζον. ὅπως οὖν μὴ προστυχών τις ἀφέληται τῶν κρειττόνων, ἐβόων θέοντες ἅμα Ταλασίῳ τῶν δὲ χαριέντων καὶ γνωρίμων τις ἦν ὁ Ταλάσιος, ὥστε τοὺς ἀκούσαντας τοὔνομα κροτεῖν καὶ βοᾶν οἷον συνηδομένους καὶ συνεπαινοῦντας. ἐκ τούτου φασὶ καὶ γὰρ εὐτυχὴς ὁ γάμος ἀπέβη τῷ Ταλασίῳ ταύτην τὴν ἐπιφώνησιν μετὰ παιδιᾶς γενέσθαι τοῖς γαμοῦσιν. οὗτος ὁ λόγος πιθανώτατός ἐστι τῶν περὶ τοῦ Ταλασίου λεγομένων, ὀλίγαις δ’ οὖν ὕστερον ἡμέραις ὁ Πομπήϊος ἠγάγετο τὴν Ἀντιστίαν.", "st": "Pomp. 4.4"}, {"sp": "N", "t": "ἐπεὶ δὲ πρὸς Κίνναν εἰς τὸ στρατόπεδον πορευθεὶς ἐξ αἰτίας τινὸς καὶ διαβολῆς ἔδεισε καὶ ταχὺ λαθὼν ἐκποδὼν ἐποίησεν ἑαυτόν, οὐκ ὄντος ἐμφανοῦς αὐτοῦ θροῦς διῆλθεν ἐν τῷ στρατοπέδῳ καὶ λόγος ὡς ἀνῃρήκοι τὸν νεανίσκον ὁ Κίννας ἐκ δὲ τούτου οἱ πάλαι βαρυνόμενοι καὶ μισοῦντες ὥρμησαν ἐπ’ αὐτόν. ὁ δὲ φεύγων καὶ καταλαμβανόμενος ὑπό τινος τῶν λοχαγῶν γυμνῷ τῷ ξίφει διώκοντος προσέπεσε τοῖς γόνασι καὶ τὴν σφραγῖδα προὔτεινε πολύτιμον οὖσαν. ὁ δὲ καὶ μάλα ὑβριστικῶς εἰπών, ἀλλ’ οὐκ ἐγγύην ἔρχομαι σφραγιούμενος, ἀλλὰ ἀνόσιον καὶ παράνομον τιμωρησόμενος τύραννον. ἀπέκτεινεν αὐτόν. οὕτω δὲ τοῦ Κίννα τελευτήσαντος ἐδέξατο μὲν τὰ πράγματα καὶ συνεῖχε Κάρβων ἐμπληκτότερος ἐκείνου τύραννος, ἐπῄει δὲ Σύλλας τοῖς πλείστοις ποθεινός, ὑπὸ τῶν παρόντων κακῶν οὐδὲ δεσπότου μεταβολὴν μικρὸν ἡγουμένοις ἀγαθόν, εἰς τοῦτο προήγαγον αἱ συμφοραὶ τὴν πόλιν, ὡς δουλείαν ἐπιεικεστέραν ζητεῖν ἀπογνώσει τῆς ἐλευθερίας.", "st": "Pomp. 5.1"}, {"sp": "N", "t": "τότε οὖν ὁ Πομπήϊος ἐν τῇ Πικηνίδι τῆς Ἰταλίας διέτριβεν, ἔχων μὲν αὐτόθι καὶ χωρία, τὸ δέ πλέον ταῖς πόλεσιν ἡδόμενος οἰκείως καὶ φιλικῶς πατρόθεν ἐχούσαις πρὸς αὐτόν, ὁρῶν δὲ τοὺς ἐπιφανεστάτους καὶ βελτίστους τῶν πολιτῶν ἀπολείποντας τὰ οἰκεῖα καὶ πανταχόθεν εἰς τὸ Σύλλα στρατόπεδον ὥσπερ εἰς λιμένα καταθέοντας, αὐτὸς οὐκ ἠξίωσεν ἀποδρὰς οὐδὲ ἀσύμβολος οὐδὲ χρῄζων βοηθείας, ἀλλὰ ὑπάρξας τινος χάριτος ἐνδόξως καὶ μετὰ δυνάμεως ἐλθεῖν πρὸς αὐτόν. ὅθεν ἐκίνει τοὺς Πικηνοὺς ἀποπειρώμενος. οἱ δὲ ὑπήκουον αὐτῷ προθύμως καὶ τοῖς παρὰ Κάρβωνος ἥκουσιν οὐ προσεῖχον. Οὐηδίου δέ τινος εἰπόντος ὅτι δημαγωγὸς αὐτοῖς ἐκ παιδαγωγείου παραπεπήδηκεν ὁ Πομπήϊος, οὕτως ἠγανάκτησαν ὥστε εὐθὺς ἀνελεῖν προσπεσόντες τὸν Οὐήδιον.", "st": "Pomp. 6.1"}, {"sp": "N", "t": "ἐκ τούτου Πομπήϊος ἔτη μὲν τρία καὶ εἴκοσι γεγονώς, ὑπ’ οὐδενὸς δὲ ἀνθρώπων ἀποδεδειγμένος στρατηγός, αὐτὸς ἑαυτῷ δοὺς τὸ ἄρχειν, ἐν Αὐξίμῳ, πόλει μεγάλῃ, βῆμα θεὶς ἐν ἀγορᾷ, καὶ τοὺς πρωτεύοντας αὐτῶν ἀδελφοὺς δύο Οὐεντιδίους ὑπὲρ Κάρβωνος ἀντιπράττοντας διατάγματι μεταστῆναι τῆς πόλεως κελεύσας, στρατιώτας κατέλεγε, καὶ λοχαγοὺς καὶ ταξιάρχους κατὰ κόσμον ἀποδείξας ἑκάστοις τὰς κύκλῳ πόλεις ἐπῄει τὸ αὐτὸ ποιῶν. ἐξανισταμένων δὲ καὶ ὑποχωρούντων ὅσοι τὰ Κάρβωνος ἐφρόνουν, τῶν δὲ ἄλλων ἀσμένως ἐπιδιδόντων αὑτούς, οὕτω κατανείμας ἐν ὀλίγῳ χρόνῳ τρία τάγματα τέλεια, καὶ τροφὴν πορίσας καὶ σκευαγωγὰ καὶ ἁμάξας καὶ τὴν ἄλλην πᾶσαν παρασκευήν, ἦγε πρὸς Σύλλαν, οὐκ ἐπειγόμενος οὐδὲ τὸ λαθεῖν ἀγαπῶν, ἀλλὰ διατρίβων καθ’ ὁδὸν ἐν τῷ κακῶς ποιεῖν τοὺς πολεμίους, καὶ πᾶν ὅσον ἐπῄει τῆς Ἰταλίας πειρώμενος ἀφιστάναι τοῦ Κάρβωνος.", "st": "Pomp. 6.3"}, {"sp": "N", "t": "ἀνέστησαν οὖν ἐπ’ αὐτὸν τρεῖς ἅμα στρατηγοὶ πολέμιοι, Καρίνας καὶ Κλοίλιος καὶ Βροῦτος, οὐκ ἐναντίοι πάντες οὐδὲ ὁμόθεν, ἀλλὰ κύκλῳ τρισὶ στρατοπέδοις περιχωροῦντες ὡς ἀναρπασόμενοι. ὁ δὲ οὐκ ἔδεισεν, ἀλλὰ πᾶσαν εἰς ταὐτὸ τὴν δύναμιν συναγαγὼν ὥρμησεν ἐφ’ ἓν τὸ τοῦ Βρούτου στράτευμα, τοὺς ἱππεῖς, ἐν οἷς ἦν αὐτός, προτάξας. ἐπεὶ δὲ καὶ παρὰ τῶν πολεμίων ἀντεξίππευσαν οἱ Κελτοί, τὸν πρῶτον αὐτῶν καὶ ῥωμαλεώτατον φθάνει παίσας ἐκ χειρὸς δόρατι καὶ καταβαλών. οἱ δὲ ἄλλοι τραπόμενοι καὶ τὸ πεζὸν συνετάραξαν, ὥστε φυγὴν γενέσθαι πάντων, ἐκ δὲ τούτου στασιάσαντες οἱ στρατηγοὶ πρὸς ἀλλήλους ἀνεχώρησαν, ὡς ἕκαστος ἔτυχε, Πομπηΐῳ δὲ προσεχώρουν αἱ πόλεις, ὡς διὰ φόβον ἐσκεδασμένων τῶν πολεμίων. αὖθις δὲ Σκηπίωνος ἐπιόντος αὐτῷ τοῦ ὑπάτου, πρὶν ἐν ἐμβολαῖς ὑσσῶν γενέσθαι τὰς φάλαγγας, οἱ Σκηπίωνος ἀσπασάμενοι τοὺς Πομπηΐου μετεβάλοντο, Σκηπίων δὲ ἔφυγε, τέλος δὲ Κάρβωνος αὐτοῦ περὶ τὸν Ἄρσιν ποταμὸν ἱππέων συχνὰς ἴλας ἐφέντος, εὐρώστως ὑποστὰς καὶ τρεψάμενος εἰς χαλεπὰ καὶ ἄφιππα χωρία πάντας ἐμβάλλει διώκων οἱ δὲ τὴν σωτηρίαν ἀνέλπιστον ὁρῶντες ἐνεχείρισαν αὑτοὺς μετὰ τῶν ὅπλων καὶ τῶν ἵππων.", "st": "Pomp. 7.1"}, {"sp": "N", "t": "οὔπω δὲ ταῦτα Σύλλας ἐπέπυστο, πρὸς δὲ τὰς πρώτας ἀγγελίας καὶ φήμας ὑπὲρ αὐτοῦ δεδοικὼς ἐν τοσούτοις καὶ τηλικούτοις ἀναστρεφομένου στρατηγοῖς πολεμίοις, ἐδίωκε βοηθήσων. γνοὺς δὲ ὁ Πομπήϊος ἐγγὺς ὄντα προσέταξε τοῖς ἡγεμόσιν ἐξοπλίζειν καὶ διακοσμεῖν τὴν δύναμιν, ὡς καλλίστη τῷ αὐτοκράτορι καὶ λαμπροτάτη φανείη μεγάλας γὰρ ἤλπιζε παρ’ αὐτοῦ τιμάς, ἔτυχε δὲ μειζόνων. ὡς γὰρ εἶδεν αὐτὸν ὁ Σύλλας προσιόντα καὶ τὴν στρατιὰν παρεστῶσαν εὐανδρίᾳ τε θαυμαστὴν καὶ διὰ τὰς κατορθώσεις ἐπηρμένην καὶ ἱλαράν, ἀποπηδήσας τοῦ ἵππου καὶ προσαγορευθείς, ὡς εἰκός, αὐτοκράτωρ ἀντιπροσηγόρευσεν αὐτοκράτορα τὸν Πομπήϊον, οὐδενὸς ἂν προσδοκήσαντος ἀνδρὶ νέῳ καὶ μηδέπω βουλῆς μετέχοντι κοινώσασθαι τοὔνομα τοῦτο Σύλλαν, περὶ οὗ Σκηπίωσι καὶ Μαρίοις ἐπολέμει. καὶ τἆλλα δὲ ἦν ὁμολογοῦντα ταῖς πρώταις φιλοφροσύναις, ὑπεξανισταμένου τε προσιόντι τῷ Πομπηΐῳ καὶ τῆς κεφαλῆς ἀπάγοντος τὸ ἱμάτιον, ἃ πρὸς ἄλλον οὐ ῥᾳδίως ἑωρᾶτο ποιῶν, καίπερ ὄντων πολλῶν καὶ ἀγαθῶν περὶ αὐτόν.", "st": "Pomp. 8.1"}, {"sp": "N", "t": "οὐ μὴν ἐκουφίσθη γε τούτοις ὁ Πομπήϊος, ἀλλ’ εὐθὺς εἰς τὴν Κελτικὴν ὑπ’ αὐτοῦ πεμπόμενος, ἣν ἔχων ὁ Μέτελλος ἐδόκει μηδὲν ἄξιον πράττειν τῆς παρασκευῆς, οὐ καλῶς ἔφη ἔχειν πρεσβύτερον καὶ προὔχοντα δόξῃ στρατηγίας ἀφαιρεῖσθαι, βουλομένῳ μέντοι τῷ Μετέλλῳ καὶ κελεύοντι συμπολεμεῖν καὶ βοηθεῖν ἕτοιμος εἶναι. δεξαμένου δὲ τοῦ Μετέλλου καὶ γράψαντος ἥκειν, ἐμβαλὼν εἰς τὴν Κελτικὴν αὐτός τε καθ’ ἑαυτὸν ἔργα θαυμαστὰ διεπράττετο, καὶ τοῦ Μετέλλου τὸ μάχιμον καὶ θαρσαλέον ἤδη σβεννύμενον ὑπὸ γήρως αὖθις ἐξερρίπιζε καὶ συνεξεθέρμαινεν, ὥσπερ ὁ ῥέων καὶ πεπυρωμένος χαλκὸς τῷ πεπηγότι καὶ ψυχρῷ περιχυθεὶς λέγεται τοῦ πυρὸς μᾶλλον ἀνυγραίνειν καὶ συνανατήκειν. ἀλλὰ γάρ, ὥσπερ ἀθλητοῦ πρωτεύσαντος ἐν ἀνδράσι καὶ τοὺς πανταχοῦ καθελόντος ἐνδόξως ἀγῶνας εἰς οὐδένα λόγον τὰς παιδικὰς τίθενται νίκας οὐδ’ ἀναγράφουσιν, οὕτως ἃς ἔπραξε τότε πράξεις ὁ Πομπήϊος, αὐτὰς καθ’ ἑαυτὰς ὑπερφυεῖς οὔσας, πλήθει δὲ καὶ μεγέθει τῶν ὑστέρων ἀγώνων καὶ πολέμων κατακεχωσμένας, ἐδεδίειν κινεῖν, μὴ περὶ τὰ πρῶτα πολλῆς διατριβῆς γενομένης τῶν μεγίστων καὶ μάλιστα δηλούντων τὸ ἦθος ἔργων καὶ παθημάτων τοῦ ἀνδρὸς ἀπολειφθῶμεν.", "st": "Pomp. 8.4"}, {"sp": "N", "t": "ἐπεὶ τοίνυν ἐκράτησε τῆς Ἰταλίας ὁ Σύλλας καὶ δικτάτωρ ἀνηγορεύθη, τοὺς μὲν ἄλλους ἡγεμόνας καὶ στρατηγοὺς ἠμείβετο πλουσίους ποιῶν καὶ προάγων ἐπὶ ἀρχὰς καὶ χαριζόμενος ἀφθόνως καὶ προθύμως ὧν ἕκαστος ἐδεῖτο, Πομπήϊον δὲ θαυμάζων δι’ ἀρετὴν καὶ μέγα νομίζων ὄφελος εἶναι τοῖς ἑαυτοῦ πράγμασιν, ἐσπούδασεν ἁμῶς γέ πως οἰκειότητι προσθέσθαι. συμβουλομένης δὲ τῆς γυναικὸς αὐτοῦ τῆς Μετέλλης, πείθουσι τὸν Πομπήϊον ἀπαλλαγέντα τῆς Ἀντιστίας λαβεῖν γυναῖκα τὴν Σύλλα πρόγονον Αἰμιλίαν, ἐκ Μετέλλης καὶ Σκαύρου γεγενημένην, ἀνδρὶ δὲ συνοικοῦσαν ἤδη καὶ κύουσαν τότε.", "st": "Pomp. 9.1"}, {"sp": "N", "t": "ἦν οὖν τυραννικὰ τὰ τὸν γάμου καὶ τοῖς Σύλλα καιροῖς μᾶλλον ἢ τοῖς Πομπηΐου τρόποις πρέποντα, τῆς μὲν Αἰμιλίας ἀγομένης ἐγκύμονος παρ’ ἑτέρου πρὸς αὐτόν, ἐξελαυνομένης δὲ τῆς Ἀντιστίας ἀτίμως καὶ οἰκτρῶς, ἅτε δὴ καὶ τοῦ πατρὸς ἔναγχος ἐστερημένης διὰ τὸν ἄνδρα· κατεσφάγη γὰρ ὁ Ἀντίστιος ἐν τῷ βουλευτηρίῳ δοκῶν τὰ Σύλλα φρονεῖν διὰ Πομπήϊον ἡ δὲ μήτηρ αὐτῆς ἐπιδοῦσα ταῦτα προήκατο τὸν βίον ἑκουσίως, ὥστε καὶ τοῦτο τὸ πάθος τῇ περὶ τὸν γάμον ἐκεῖνον τραγῳδίᾳ προσγενέσθαι καὶ νὴ Δία τὸ τὴν Αἰμιλίαν εὐθὺς διαφθαρῆναι παρὰ τῷ Πομπηΐῳ τίκτουσαν.", "st": "Pomp. 9.3"}, {"sp": "N", "t": "ἐκ τούτου Σικελίαν ἠγγέλλετο Περπέννας αὑτῷ κρατύνεσθαι καὶ τοῖς περιοῦσιν ἔτι τῆς ἐναντίας στάσεως ὁρμητήριον παρέχειν τὴν νῆσον, αἰωρουμένου καὶ Κάρβωνος αὐτόθι ναυτικῷ καὶ Δομετίου Λιβύῃ προσπεπτωκότος, ἄλλων τε πολλῶν ἐπέκεινα μεγάλων ὠθουμένων φυγάδων, ὅσοι τὰς προγραφὰς ἔφθησαν ἀποδράντες. ἐπὶ τούτους Πομπήϊος ἀπεστάλη μετὰ πολλῆς δυνάμεως. καὶ Περπέννας μὲν εὐθὺς αὐτῷ Σικελίας ἐξέστη, τὰς δὲ πόλεις ἀνελάμβανε τετρυχωμένας καὶ φιλανθρώπως πάσαις ἐχρῆτο πλὴν Μαμερτίνων τῶν ἐν Μεσσήνῃ, παραιτουμένων γὰρ αὐτοῦ τὸ βῆμα καὶ τὴν δικαιοδοσίαν ὡς νόμῳ παλαιῷ Ῥωμαίων ἀπειρημένα, οὐ παύσεσθε, εἶπεν, ἡμῖν ὑπεζωσμένοις ξίφη νόμους ἀναγινώσκοντες; ἔδοξε δὲ καὶ ταῖς Κάρβωνος οὐκ ἀνθρωπίνως ἐνυβρίσαι συμφοραῖς. εἰ γὰρ ἦν ἀναγκαῖον αὐτόν, ὥσπερ ἦν ἴσως, ἀνελεῖν, εὐθὺς ἔδει λαβόντα, καὶ τοῦ κελεύσαντος ἂν ἦν τὸ ἔργον. ὁ δὲ δέσμιον προαγαγὼν ἄνδρα Ῥωμαῖον τρὶς ὑπατεύσαντα καὶ πρὸ τοῦ βήματος στήσας καθεζόμενος αὐτὸς ἀνέκρινεν, ἀχθομένων καὶ βαρυνομένων τῶν παρόντων· εἶτα ἐκέλευσεν ἀπαγαγόντας ἀνελεῖν. ἀπαχθέντα μέντοι φασὶν αὐτόν, ὡς εἶδεν ἑλκόμενον ἤδη τὸ ξίφος, δεῖσθαι τόπον αὑτῷ καὶ χρόνον βραχύν, ὡς ὑπὸ κοιλίας ἐνοχλουμένῳ, παρασχεῖν. Γάϊος δὲ Ὄππιος ὁ Καίσαρος ἑταῖρος ἀπανθρώπως φησὶ καὶ Κοΐντῳ Οὐαλλερίῳ χρήσασθαι τὸν Πομπήϊον. ἐπιστάμενον γὰρ ὡς ἔστι φιλολόγος ἀνὴρ καὶ φιλομαθὴς ἐν ὀλίγοις ὁ Οὐαλλέριος, ὡς ἤχθη πρὸς αὐτόν, ἐπισπασάμενον καὶ συμπεριπατήσαντα καὶ πυθόμενον ὧν ἔχρῃζε καὶ μαθόντα, προστάξαι τοῖς ὑπηρέταις εὐθὺς ἀνελεῖν ἀπαγαγόντας.", "st": "Pomp. 10.1"}, {"sp": "N", "t": "ἀλλ’ Ὀππίῳ μέν, ὅταν περὶ τῶν Καίσαρος πολεμίων ἢ φίλων διαλέγηται, σφόδρα δεῖ πιστεύειν μετὰ εὐλαβείας· Πομπήϊος δὲ τοὺς μὲν ἐν δόξῃ μάλιστα τῶν Σύλλα πολεμίων καὶ φανερῶς ἁλισκομένους ἀναγκαίως ἐκόλαζε, τῶν δ’ ἄλλων ὅσους ἐξῆν περιεώρα λανθάνοντας, ἐνίους δὲ καὶ συνεξέπεμπε. τὴν δὲ Ἱμεραίων πόλιν ἐγνωκότος αὐτοῦ κολάζειν γενομένην μετὰ τῶν πολεμίων, Σθένις ὁ δημαγωγὸς αἰτησάμενος λόγον οὐκ ἔφη δίκαια ποιήσειν τὸν Πομπήϊον, ἐὰν τὸν αἴτιον ἀφεὶς ἀπολέσῃ τοὺς μηδὲν ἀδικοῦντας. ἐρομένου δὲ ἐκείνου τίνα λέγει τὸν αἴτιον, ἑαυτὸν ὁ Σθένις ἔφη, τοὺς μὲν φίλους πείσαντα τῶν πολιτῶν, τοὺς δ’ ἐχθροὺς βιασάμενον. ἀγασθεὶς οὖν τὴν παρρησίαν καὶ τὸ φρόνημα τοῦ ἀνδρὸς ὁ Πομπήϊος ἀφῆκε τῆς αἰτίας πρῶτον ἐκεῖνον, εἶτα τοὺς ἄλλους ἅπαντας, ἀκούων δὲ τοὺς στρατιώτας ἐν ταῖς ὁδοιπορίαις ἀτακτεῖν, σφραγῖδα ταῖς μαχαίραις αὐτῶν ἐπέβαλεν, ἣν ὁ μὴ φυλάξας ἐκολάζετο.", "st": "Pomp. 10.5"}, {"sp": "N", "t": "ταῦτα πράττων ἐν Σικελίᾳ καὶ πολιτευόμενος ἐδέξατο δόγμα συγκλήτου καὶ γράμματα Σύλλα κελεύοντα εἰς Λιβύην πλεῖν καὶ πολεμεῖν Δομετίῳ κατὰ κράτος, ἠθροικότι πολλαπλασίαν δύναμιν ἧς ἔχων Μάριος οὐ πάλαι διεπέρασεν ἐκ Λιβύης εἰς Ἰταλίαν καὶ συνέχει τὰ Ῥωμαίων πράγματα, τύραννος ἐκ φυγάδος καταστάς. ὀξέως οὖν ἅπαντα παρασκευασάμενος ὁ Πομπήϊος Σικελίας μὲν ἄρχοντα Μέμμιον κατέλιπε τὸν ἄνδρα τῆς ἀδελφῆς, αὐτὸς δὲ ἀνήγετο ναυσὶ μὲν μακραῖς ἑκατὸν εἴκοσι, φορτηγοῖς δὲ σῖτον καὶ βέλη καὶ χρήματα καὶ μηχανὰς κομιζούσαις ὀκτακοσίαις. κατασχόντι δὲ αὐτῷ ταῖς μὲν εἰς Ἰτύκην ναυσί, ταῖς δὲ εἰς Καρχηδόνα, τῶν πολεμίων ἀποστάντες ἑπτακισχίλιοι προσεχώρησαν, αὐτὸς δὲ ἦγεν ἓξ ἐντελῆ τάγματα.", "st": "Pomp. 11.1"}, {"sp": "N", "t": "συμβῆναι δὲ αὐτῷ πρᾶγμα γελοῖον ἱστοροῦσι. στρατιῶται γάρ τινες, ὡς ἔοικε, θησαυρῷ περιπεσόντες ἔλαβον συχνὰ χρήματα, τοῦ δὲ πράγματος γενομένου φανεροῦ δόξα τοῖς ἄλλοις παρέστη πᾶσι χρημάτων μεστὸν εἶναι τὸν τόπον ἐν ταῖς ποτε τύχαις τῶν Καρχηδονίων ἀποτεθειμένων. οὐδὲν οὖν ὁ Πομπήϊος εἶχε χρῆσθαι τοῖς στρατιώταις ἐπὶ πολλὰς ἡμέρας θησαυροὺς ζητοῦσιν, ἀλλὰ περιῄει γελῶν καὶ θεώμενος ὁμοῦ μυριάδας τοσαύτας ὀρυσσούσας καὶ στρεφούσας τὸ πεδίον, ἕως ἀπειπόντες ἐκέλευον αὑτοὺς ἄγειν ὅπη βούλεται τὸν Πομπήϊον, ὡς δίκην ἱκανὴν τῆς ἀβελτερίας δεδωκότας.", "st": "Pomp. 11.3"}, {"sp": "N", "t": "Ἀντιτεταγμένου δὲ τοῦ Δομετίου καὶ χαράδραν τινὰ προβεβλημένου χαλεπὴν περᾶσαι καὶ τραχεῖαν, ὄμβρος ἅμα πνεύματι πολὺς ἕωθεν ἀρξάμενος κατεῖχεν, ὥστε ἀπογνόντα τῆς ἡμέρας ἐκείνης μαχέσασθαι τὸν Δομέτιον ἀναζυγὴν παραγγεῖλαι, Πομπήϊος δὲ τοῦτον αὑτοῦ ποιούμενος τὸν καιρὸν ὀξέως ἐπῄει καὶ διέβαινε τὴν χαράδραν. οἱ δὲ ἀτάκτως καὶ θορυβούμενοι καὶ οὐ πάντες οὐδὲ ὁμαλῶς ὑφίσταντο, καὶ τὸ πνεῦμα περιῄει τὴν ζάλην αὐτοῖς προσβάλλον ἐναντίαν. οὐ μὴν ἀλλὰ καὶ τοὺς Ῥωμαίους ὁ χειμὼν ἐτάραξεν οὐ καθορῶντας ἀλλήλους ἀκριβῶς, αὐτός τε Πομπήϊος ἐκινδύνευσεν ἀγνοηθεὶς ἀποθανεῖν, ἐρωτῶντι στρατιώτῃ τὸ σύνθημα βράδιον ἀποκρινάμενος.", "st": "Pomp. 12.1"}, {"sp": "N", "t": "ὠσάμενοι δὲ πολλῷ φόνῳ τοὺς πολεμίους (λέγονται γὰρ ἀπὸ δισμυρίων τρισχίλιοι διαφυγεῖν) αὐτοκράτορα τὸν Πομπήϊον ἠσπάσαντο. φήσαντος δὲ ἐκείνου μὴ δέχεσθαι τὴν τιμὴν ἕως ὀρθὸν ἕστηκε τὸ στρατόπεδον τῶν πολεμίων, εἰ δὲ αὐτὸν ἀξιοῦσι ταύτης τῆς προσηγορίας, ἐκεῖνο χρῆναι πρότερον καταβαλεῖν, ὥρμησαν εὐθὺς ἐπὶ τὸν χάρακα· καὶ Πομπήϊος ἄνευ κράνους ἠγωνίζετο δεδοικὼς τὸ πρότερον πάθος. ἁλίσκεται δὴ τὸ στρατόπεδον καὶ ἀποθνήσκει Δομέτιος. τῶν δὲ πόλεων αἱ μὲν εὐθὺς ὑπήκουον, αἱ δὲ κατὰ κράτος ἐλήφθησαν, εἷλε δὲ καὶ τῶν βασιλέων Ἰάρφαν τὸν συμμαχήσαντα Δομετίῳ, τὴν δὲ βασιλείαν Ἰάμψᾳ παρέδωκε. χρώμενος δὲ τῇ τύχῃ καὶ τῇ ῥύμῃ τοῦ στρατεύματος εἰς τὴν Νομαδικὴν ἐνέβαλε· καὶ πολλῶν ὁδὸν ἡμερῶν ἐλάσας καὶ πάντων κρατήσας οἷς ἐνέτυχε, καὶ τὸ πρὸς Ῥωμαίους δέος ἤδη τῶν βαρβάρων ἐξερρυηκὸς αὖθις ἰσχυρὸν καὶ φοβερὸν ἐγκαταστήσας, οὐδὲ τὰ θηρία δεῖν ἔφη τὰ τὴν Λιβύην κατοικοῦντα τῆς τῶν Ῥωμαίων ἄπειρα ῥώμης καὶ τόλμης ἀπολείπειν. ὅθεν ἐν θήραις λεόντων καὶ ἐλεφάντων ἡμέρας διέτριψεν οὐ πολλάς· ταῖς δὲ πάσαις, ὥς φασι, τεσσαράκοντα τοὺς πολεμίους συνεῖλε καὶ Λιβύην ἐχειρώσατο καὶ διῄτησε τὰ τῶν βασιλέων, ἔτος ἄγων ἐκεῖνο τέταρτον καὶ εἰκοστόν.", "st": "Pomp. 12.3"}, {"sp": "N", "t": "ἐπανελθόντι δὲ εἰς Ἰτύκην αὐτῷ γράμματα κομίζεται Σύλλα προστάττοντος ἀφιέναι μὲν τὴν ἄλλην στρατιάν, αὐτὸν δὲ μεθ’ ἑνὸς τάγματος περιμένειν αὐτόθι τὸν διαδεξόμενον στρατηγόν. ἐπὶ τούτοις ἀδήλως μὲν αὐτὸς ἤχθετο καὶ βαρέως ἔφερεν, ἐμφανῶς δὲ ὁ στρατὸς ἠγανάκτει· καὶ δεηθέντος τοῦ Πομπηΐου προελθεῖν, τόν τε Σύλλαν κακῶς ἔλεγον, κἀκεῖνον οὐκ ἔφασαν προήσεσθαι χωρὶς αὑτῶν, οὐδὲ εἴων πιστεύειν τῷ τυράννῳ. τὸ μὲν οὖν πρῶτον ὁ Πομπήϊος ἐπειρᾶτο πραΰνειν καὶ παρηγορεῖν αὐτούς· ὡς δ’ οὐκ ἔπειθε, καταβὰς ἀπὸ τοῦ βήματος ἐπὶ τὴν σκηνὴν ἀπῄει δεδακρυμένος. οἱ δὲ συλλαβόντες αὐτὸν αὖθις ἐπὶ τοῦ βήματος κατέστησαν· καὶ πολὺ μέρος τῆς ἡμέρας ἀνηλώθη, τῶν μὲν μένειν καὶ ἄρχειν κελευόντων, τοῦ δὲ πείθεσθαι δεομένου καὶ μὴ στασιάζειν, ἄχρι οὗ προσλιπαρούντων καὶ καταβοώντων ὤμοσεν ἀναιρήσειν ἑαυτὸν εἰ βιάζοιντο, καὶ μόλις οὕτως ἐπαύσαντο.", "st": "Pomp. 13.1"}, {"sp": "N", "t": "τῷ δὲ Σύλλᾳ πρώτη μὲν ἦλθεν ἀγγελία τόν Πομπήϊον ἀφεστάναι, καὶ πρὸς τοὺς φίλους εἶπεν ὡς ἄρα πεπρωμένον ἦν αὐτῷ γενομένῳ γέροντι παίδων ἀγῶνας ἀγωνίζεσθαι, διὰ τὸ καὶ Μάριον αὐτῷ νέον ὄντα κομιδῇ πλεῖστα πράγματα παρασχεῖν καὶ εἰς τοὺς ἐσχάτους περιστῆσαι κινδύνους, πυθόμενος δὲ τἀληθῆ, καὶ πάντας ἀνθρώπους αἰσθανόμενος δέχεσθαι καὶ παραπέμπειν τὸν Πομπήϊον ὡρμημένους μετ’ εὐνοίας, ἔσπευδεν ὑπερβαλέσθαι· καὶ προελθὼν ἀπήντησεν αὐτῷ, καὶ δεξιωσάμενος ὡς ἐνῆν προθυμότατα μεγάλῃ φωνῇ Μάγνον ἠσπάσατο, καὶ τοὺς παρόντας οὕτως ἐκέλευσε προσαγορεῦσαι. σημαίνει δὲ τὸν μέγαν ὁ Μάγνος. ἕτεροι δέ φασιν ἐν Λιβύῃ πρῶτον ἀναφώνημα τοῦτο τοῦ στρατοῦ παντὸς γενέσθαι, κράτος δὲ λαβεῖν καὶ δύναμιν ὑπὸ Σύλλα βεβαιωθέν. αὐτὸς μέντοι πάντων ὕστατος καὶ μετὰ πολὺν χρόνον εἰς Ἰβηρίαν ἀνθύπατος ἐκπεμφθεὶς ἐπὶ Σερτώριον ἤρξατο γράφειν ἑαυτὸν ἐν ταῖς ἐπιστολαῖς καὶ τοῖς διατάγμασι Μάγνον Πομπήϊον οὐκέτι γὰρ ἦν ἐπίφθονον τοὔνομα σύνηθες γενόμενον.", "st": "Pomp. 13.3"}, {"sp": "N", "t": "ὅθεν εἰκότως ἀγασθείη καὶ θαυμάσειεν ἄν τις τοὺς πάλαι Ῥωμαίους, οἳ ταῖς τοιαύταις ἐπικλήσεσι καὶ προσωνυμίαις οὐ τὰς πολεμικὰς ἠμείβοντο καὶ στρατιωτικὰς κατορθώσεις μόνον, ἀλλὰ καὶ τὰς πολιτικὰς πράξεις καὶ ἀρετὰς ἐκόσμουν. δύο γοῦν Μαξίμους, ὅπερ ἐστὶ μεγίστους, ἀνηγόρευσεν ὁ δῆμος· Οὐαλλέριον μὲν ἐπὶ τῷ διαλλάξαι στασιάζουσαν αὐτῷ τὴν σύγκλητον, Φάβιον δὲ Ῥοῦλλον, ὅτι πλουσίους τινὰς ἐξ ἀπελευθέρων γεγονότας καὶ καταλελεγμένους εἰς τὴν σύγκλητον ἐξέβαλεν.", "st": "Pomp. 13.6"}, {"sp": "N", "t": "ἐκ τούτου θρίαμβον ᾔτει Πομπήϊος, ἀντέλεγε δὲ Σύλλας. ὑπάτῳ γὰρ ἢ στρατηγῷ μόνον, ἄλλῳ δὲ οὐδενὶ δίδωσιν ὁ νόμος, διὸ καὶ Σκηπίων ὁ πρῶτος ἀπὸ μειζόνων καὶ κρειττόνων ἀγώνων ἐν Ἰβηρίᾳ Καρχηδονίων κρατήσας οὐκ ᾔτησε θρίαμβον ὕπατος γὰρ οὐκ ἦν οὐδὲ στρατηγός. εἰ δὲ Πομπήϊος οὔπω πάνυ γενειῶν εἰσελᾷ θριαμβεύων εἰς τὴν πόλιν, ᾧ βουλῆς διὰ τὴν ἡλικίαν οὐ μέτεστι, παντάπασιν ἐπίφθονον ἔσεσθαι καὶ τὴν ἀρχὴν ἑαυτῷ καὶ τὴν τιμὴν ἐκείνῳ. ταῦτα πρὸς Πομπήϊον ὁ Σύλλας ἔλεγεν, ὡς οὐκ ἐάσων, ἀλλὰ ἐνστησόμενος αὐτῷ καὶ κωλύσων τὸ φιλόνεικον ἀπειθοῦντος.", "st": "Pomp. 14.1"}, {"sp": "N", "t": "ὁ δὲ Πομπήϊος οὐχ ὑπέπτηξεν, ἀλλ’ ἐννοεῖν ἐκέλευσε τὸν Σύλλαν ὅτι τὸν ἥλιον ἀνατέλλοντα πλείονες ἢ δυόμενον προσκυνοῦσιν, ὡς αὐτῷ μὲν αὐξανομένης, μειουμένης δὲ καὶ μαραινομένης ἐκείνῳ τῆς δυνάμεως, ταῦτα ὁ Σύλλας οὐκ ἀκριβῶς ἐξακούσας, ὁρῶν δὲ τοὺς ἀκούσαντας ἀπὸ τοῦ προσώπου καὶ τοῦ σχήματος ἐν θαύματι ποιουμένους, ἤρετο τί τὸ λεχθὲν εἴη. πυθόμενος δὲ καὶ καταπλαγεὶς τοῦ Πομπηΐου τὴν τόλμαν ἀνεβόησε δὶς ἐφεξῆς, Θριαμβευσάτω. πολλῶν δὲ δυσχεραινόντων καὶ ἀγανακτούντων, ἔτι μᾶλλον αὐτούς, ὥς φασι, βουλόμενος ἀνιᾶν ὁ Πομπήϊος, ἐπεχείρησεν ἐλεφάντων ἅρματι τεττάρων ἐπιβὰς εἰσελαύνειν ἤγαγε γὰρ ἐκ Λιβύης τῶν βασιλικῶν συχνοὺς αἰχμαλώτους· ἀλλὰ τῆς πύλης στενωτέρας οὔσης ἀπέστη καὶ μετῆλθεν ἐπὶ τοὺς ἵππους. ἐπεὶ δὲ οἱ στρατιῶται μὴ τυχόντες ἡλίκων προσεδόκησαν ἐνοχλεῖν ἐβούλοντο καὶ θορυβεῖν, οὐδὲν ἔφη φροντίζειν, ἀλλὰ μᾶλλον ἀφήσειν τὸν θρίαμβον ἢ κολακεύσειν ἐκείνους, ὅτε δὴ καὶ Σερουΐλιος, ἀνὴρ ἐπιφανὴς καὶ μάλιστα πρὸς τὸν θρίαμβον ἐνστὰς τοῦ Πομπηΐου, νῦν ἔφη τὸν Πομπήϊον ὁρᾶν καὶ μέγαν ἀληθῶς καὶ ἄξιον τοῦ θριάμβου. δῆλον δ’ ἐστὶν ὅτι καὶ βουλῆς ἂν ἐθελήσας τότε ῥᾳδίως ἔτυχεν. ἀλλ’ οὐκ ἐσπούδασεν, ὡς λέγουσι, τὸ ἔνδοξον ἐκ τοῦ παραδόξου θηρώμενος. οὐ γὰρ ἦν θαυμαστὸν εἰ πρὸ ἡλικίας ἐβούλευε Πομπήϊος, ἀλλ’ ὑπέρλαμπρον ὅτι μηδέπω βουλεύων ἐθριάμβευε. τοῦτο δὲ αὐτῷ καὶ πρὸς εὔνοιαν ὑπῆρχε τῶν πολλῶν οὐ μικρόν ἔχαιρε γὰρ ὁ δῆμος αὐτῷ μετὰ θρίαμβον ἐν τοῖς ἱππικοῖς ἐξεταζομένῳ.", "st": "Pomp. 14.3"}, {"sp": "N", "t": "Σύλλας δὲ ἠνιᾶτο μὲν ὁρῶν εἰς ὅσον δόξης πρόεισι καί δυνάμεως, αἰσχυνόμενος δὲ κωλύειν ἡσυχίαν ἦγε· πλήν, ὅτε βίᾳ καί ἄκοντος αὐτοῦ Λέπιδον εἰς ὑπατείαν κατέστησε, συναρχαιρεσιάσας καί τὸν δῆμον εὐνοίᾳ τῇ πρὸς ἑαυτὸν ἐκείνῳ σπουδάζοντα παρασχών, θεασάμενος αὐτὸν ἀπιόντα μετὰ πλήθους δι’ ἀγορᾶς ὁ Σύλλας, ὁρῶ σε, εἶπεν, ὦ νεανία, χαίροντα τῇ νίκῃ· πῶς γὰρ οὐχὶ γενναῖα ταῦτα καί καλά, Κάτλου τὸν πάντων ἀρίστου Λέπιδον τὸν πάντων κάκιστον ἀποδειχθῆναι πρότερον ὕπατον, σοῦ τὸν δῆμον οὕτω παρασκευάσαντος; ὥρα μέντοι σοι μὴ καθεύδειν, ἀλλὰ προσέχειν τοῖς πράγμασιν· ἰσχυρότερον γὰρ τὸν ἀνταγωνιστὴν σεαυτῷ κατεσκεύακας. ἐδήλωσε δὲ μάλιστα Σύλλας ὅτι πρὸς Πομπήϊον οὐκ εὐμενῶς εἶχε ταῖς διαθήκαις ἃς ἔγραψεν. ἑτέροις γὰρ φίλοις δωρεὰς ἀπολιπών, καί τοῦ παιδὸς ἀποδείξας ἐπιτρόπους, τὸν Πομπήϊον ὅλως παρῆλθεν. ἤνεγκε μέντοι τοῦτο μετρίως πάνυ καί πολιτικῶς ἐκεῖνος, ὥστε Λεπίδου καί τινων ἄλλων ἐνισταμένων μὴ ταφῆναι τὸν νεκρὸν ἐν τῷ πεδίῳ, μηδὲ δημοσίᾳ τὴν ἐκφορὰν γενέσθαι, βοηθῆσαι καί παρασχεῖν δόξαν ἅμα ταῖς ταφαῖς καί ἀσφάλειαν.", "st": "Pomp. 15.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ταχὺ τοῦ Σύλλα τελευτήσαντος εἰς φῶς παρῄει τὰ μαντεύματα, καὶ Λέπιδος εἰσποιῶν ἑαυτὸν εἰς τὴν ἐκείνου δύναμιν οὐ κύκλῳ περιϊὼν οὐδὲ μετὰ σχήματος, ἀλλὰ εὐθὺς ἐν τοῖς ὅπλοις ἦν, τὰ πάλαι νοσοῦντα καὶ διαφυγόντα τὸν Σύλλαν ὑπολείμματα τῶν στάσεων αὖθις ἀνακινῶν καὶ περιβαλλόμενος, ὁ δὲ συνάρχων αὐτοῦ Κάτλος, ᾧ τὸ καθαρὸν καὶ ὑγιαῖνον μάλιστα τῆς βουλῆς καὶ τοῦ δήμου προσεῖχεν, ἦν μὲν ἐν ἀξιώματι σωφροσύνης καὶ δικαιοσύνης μέγιστος τῶν τότε Ῥωμαίων, ἐδόκει δὲ πολιτικῆς ἡγεμονίας μᾶλλον ἢ στρατιωτικῆς οἰκεῖος εἶναι, τῶν πραγμάτων αὐτῶν ποθούντων τὸν Πομπήϊον οὐ διεμέλλησεν ὅπη τράπηται, προσθεὶς δὲ τοῖς ἀρίστοις ἑαυτὸν ἀπεδείχθη στρατεύματος ἡγεμὼν ἐπὶ τὸν Λέπιδον ἤδη πολλὰ τῆς Ἰταλίας κεκινηκότα καὶ τὴν ἐντὸς Ἄλπεων Γαλατίαν κατέχοντα διὰ Βρούτου στρατεύματι.", "st": "Pomp. 16.1"}, {"sp": "N", "t": "τῶν μὲν οὖν ἄλλων ἐκράτησε ῥᾳδίως ἐπελθὼν ὁ Πομπήϊος· ἐν δὲ Μουτίνῃ τῆς Γαλατίας ἀντεκάθητο τῷ Βρούτῳ συχνὸν χρόνον ἐν ᾧ Λέπιδος ἐπὶ τὴν Ῥώμην ῥυεὶς καὶ προσκαθήμενος ἔξωθεν ὑπατείαν ᾔτει δευτέραν, ὄχλῳ πολλῷ δεδιττόμενος τοὺς ἔνδον. ἔλυσε δὲ τὸν φόβον ἐπιστολὴ παρὰ Πομπηΐου κομισθεῖσα κατωρθωκότος ἄνευ μάχης τὸν πόλεμον. ὁ γὰρ Βροῦτος, εἴτε παραδοὺς τὴν δύναμιν αὐτός, εἴτε προδοθεὶς μεταβαλομένης ἐκείνης, ἐνεχείρισε τῷ Πομπηΐῳ τὸ σῶμα, καὶ λαβὼν ἱππεῖς προπομποὺς ἀπεχώρησεν εἰς πολίχνιόν τι τῶν περὶ τὸν Πάδον, ὅπου μεθ’ ἡμέραν μίαν, ἐπιπέμψαντος αὐτῷ τοῦ Πομπηΐου Γεμίνων, ἀνῃρέθη· καὶ πολλὴν ἔσχεν ἀπὸ τούτου Πομπήϊος αἰτίαν. γεγραφὼς γὰρ εὐθὺς ἐν ἀρχῇ τῆς μεταβολῆς πρὸς τὴν σύγκλητον ὡς ἑκὼν αὐτῷ πρόσθοιτο Βροῦτος, ἑτέρας αὖθις ἔπεμψεν ἐπιστολὰς ἀνῃρημένου τοῦ ἀνθρώπου κατηγορούσας. τούτου Βροῦτος ἦν υἱὸς ὁ Καίσαρα σὺν Κασσίῳ κτείνας, ἀνὴρ ὁμοίως τῷ πατρὶ μήτε πολεμήσας μήτε ἀποθανών, ὡς ἐν τοῖς περὶ ἐκείνου γέγραπται. Λέπιδος μὲν οὖν εὐθὺς ἐκπεσὼν τῆς Ἰταλίας ἀπεπέρασεν εἰς Σαρδόνα· κἀκεῖ νοσήσας ἐτελεύτησε δι’ ἀθυμίαν, οὐ τῶν πραγμάτων, ὥς φασιν, ἀλλὰ γραμματίῳ περιπεσὼν ἐξ οὗ μοιχείαν τινὰ τῆς γυναικὸς ἐφώρασε.", "st": "Pomp. 16.3"}, {"sp": "N", "t": "Λεπίδῳ δὲ οὐδὲν ὅμοιος στρατηγὸς Ἰβηρίαν κατέχων Σερτώριος ἐπῃωρεῖτο Ῥωμαίοις φοβερός, ὥσπερ ἐπ’ ἔσχατον νόσημα τῶν ἐμφυλίων πολέμων εἰς τοῦτον τὸν ἄνδρα συνερρυηκότων, πολλοὺς μὲν ἤδη τῶν ἐλαττόνων στρατηγῶν ἀνῃρηκότα, Μετέλλῳ δὲ Πίῳ τότε συμπεπλεγμένον, ἀνδρὶ λαμπρῷ μὲν καί πολεμικῷ, δοκοῦντι δὲ ἀργότερον ὑπὸ γήρως ἕπεσθαι τοῖς καιροῖς τοῦ πολέμου, καί ἀπολείπεσθαι τῶν πραγμάτων ἁρπαζομένων ὀξύτητι καί τάχει, τοῦ Σερτωρίου παραβόλως καί λῃστρικώτερον αὐτῷ προσφερομένου, καί ταράττοντος ἐνέδραις καί περιδρομαῖς ἄνδρα νομίμων ἀθλητὴν ἀγώνων καί δυνάμεως στασίμου καί βαρείας ἡγεμόνα. πρὸς ταῦτα Πομπήϊος ἔχων τὴν στρατιὰν ὑφ’ ἑαυτῷ διεπράττετο Μετέλλῳ πεμφθῆναι βοηθός· καί Κάτλου κελεύοντος οὐ διέλυεν, ἀλλ’ ἐν τοῖς ὅπλοις ἦν περὶ τὴν πόλιν, ἀεί τινας ποιούμενος προφάσεις, ἕως ἔδωκαν αὐτῷ τὴν ἀρχὴν Λευκίου Φιλίππου γνώμην εἰπόντος. ὅτε καί φασιν ἐν συγκλήτῳ πυθομένου τινὸς καί θαυμάζοντος εἰ Πομπήϊον ἀνθύπατον οἴεται δεῖν ἐκπεμφθῆναι Φίλιππος· οὐκ ἔγωγε, φάναι τὸν Φίλιππον, ἀλλ’ ἀνθ’ ὑπάτων, ὡς ἀμφοτέρους τοὺς τότε ὑπατεύοντας οὐδενὸς ἀξίους ὄντας.", "st": "Pomp. 17.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τῆς Ἰβηρίας ἁψάμενος ὁ Πομπήϊος, οἷα φιλεῖ πρὸς νέου δόξαν ἡγεμόνος, ἑτέρους ταῖς ἐλπίσιν ἐποίησε τοὺς ἀνθρώπους καί τὰ μὴ πάνυ βεβαίως τῷ Σερτωρίῳ συνεστῶτα τῶν ἐθνῶν ἐκινεῖτο καί μετεβάλλετο, λόγους ὑπερηφάνους ὁ Σερτώριος κατὰ τοῦ Πομπηΐου διέσπειρε, καί σκώπτων ἔλεγε νάρθηκος ἂν αὐτῷ δεῆσαι καί σκύτους ἐπὶ τὸν παῖδα τοῦτον, εἰ μὴ τὴν γραῦν ἐκείνην ἐφοβεῖτο, λέγων τὸν Μέτελλον. ἔργῳ μέντοι φυλαττόμενος σφόδρα καί δεδοικὼς τὸν Πομπήϊον ἀσφαλέστερον ἐστρατήγει. καί γὰρ ὁ Μέτελλος, ὅπερ οὐκ ἄν τις ᾠήθη, διετέθρυπτο τῷ βίῳ κομιδῆ πρὸς τὰς ἡδονὰς ἐνδεδωκώς, καί μεγάλη τις εἰς ὄγκον καί πολυτέλειαν ἐξαίφνης ἐγεγόνει μεταβολὴ περὶ αὐτόν, ὥστε τῷ Πομπηΐῳ καί τοῦτο θαυμαστὴν εὔνοιαν ἅμα δόξῃ φέρειν, ἐπιτείνοντι τὴν εὐτέλειαν τῆς διαίτης οὐ πολλῆς ἐπιτηδεύσεως δεομένην φύσει γὰρ ἦν σώφρων καί τεταγμένος ἐν ταῖς ἐπιθυμίαις.", "st": "Pomp. 18.1"}, {"sp": "N", "t": "τοῦ δὲ πολέμου πολλὰς ἰδέας ἔχοντος, ἠνίασε μάλιστα τὸν Πομπήϊον ἡ Λαύρωνος ἅλωσις ὑπὸ Σερτωρίου. κυκλοῦσθαι γὰρ αὐτὸν οἰηθεὶς καί τι μεγαληγορήσας, αὐτὸς ἐξαίφνης ἀνεφάνη περιεχόμενος κύκλῳ· καί διὰ τοῦτο κινεῖσθαι δεδιὼς ἐπεῖδε καταπιμπραμένην τὴν πόλιν αὐτοῦ παρόντος. Ἑρέννιον δὲ καί Περπένναν, ἄνδρας ἡγεμονικοὺς τῶν πρὸς Σερτώριον καταπεφευγότων καὶ στρατηγούντων ἐκείνῳ, νικήσας περὶ Οὐαλεντίαν ὑπὲρ μυρίους ἀπέκτεινεν.", "st": "Pomp. 18.3"}, {"sp": "N", "t": "ἐπαρθεὶς δὲ τῇ πράξει καὶ μέγα φρονῶν ἐπ’ αὑτὸν ἔσπευδε Σερτώριον, ὡς μὴ μετάσχοι τῆς νίκης Μέτελλος. περὶ δὲ Σούκρωνι ποταμῷ τῆς ἡμέρας ἤδη τελευτώσης συνέβαλον τὰς δυνάμεις, δεδιότες ἐπελθεῖν τὸν Μέτελλον, ὁ μὲν ὡς μόνος, ὁ δὲ ὡς μόνῳ διαγωνίσαιτο. τὸ μὲν οὖν τέλος ἀμφίδοξον ἔσχεν ὁ ἀγών· ἑκατέρου γὰρ θάτερον κέρας ἐνίκησε· τῶν δὲ στρατηγῶν πλέον ἠνέγκατο Σερτώριος· ἐτρέψατο γὰρ τὸ καθ’ αὑτὸν ἐκεῖνος ἀντιταχθείς. Πομπηΐῳ δὲ ἀνὴρ μέγας ἱππότῃ πεζὸς ἐφώρμησε· συμπεσόντων δ’ εἰς τὸ αὐτὸ καὶ γενομένων ἐν λαβαῖς ἀπέσκηψαν αἱ πληγαὶ τῶν ξιφῶν εἰς τὰς χεῖρας ἀμφοῖν, οὐχ ὁμοίως· ἐτρώθη μὲν γὰρ ὁ Πομπήϊος μόνον, ἐκείνου δὲ ἀπέκοψε τὴν χεῖρα. πλειόνων δὲ συνδραμόντων ἐπ’ αὐτόν, ἤδη τῆς τροπῆς γεγενημένης, ἀνελπίστως διέφυγε, προέμενος τὸν ἵππον τοῖς πολεμίοις φάλαρα χρυσᾶ καὶ κόσμον ἄξιον πολλοῦ περικείμενον. ταῦτα γὰρ διανεμόμενοι καὶ περὶ τούτων μαχόμενοι πρὸς ἀλλήλους ἀπελείφθησαν. ἅμα δὲ ἡμέρᾳ παρετάξαντο μὲν ἀμφότεροι πάλιν ἐκβεβαιούμενοι τὸ νίκημα, Μετέλλου δὲ προσιόντος ἀνεχώρησεν ὁ Σερτώριος σκεδασθέντι τῷ στρατῷ. τοιαῦται γὰρ ἦσαν αἱ διαλύσεις καὶ πάλιν συνδρομαὶ τῶν ἀνθρώπων ὥστε πολλάκις μόνον πλανᾶσθαι τὸν Σερτώριον, πολλάκις δὲ αὖθις ἐπιέναι μυριάσι πεντεκαίδεκα στρατιᾶς, ὥσπερ χειμάρρουν ἐξαίφνης πιμπλάμενον.", "st": "Pomp. 19.1"}, {"sp": "N", "t": "ὁ δ’ οὖν Πομπήϊος, ἐπεὶ μετὰ τὴν μάχην ἀπήντα τῷ Μετέλλῳ καὶ πλησίον ἀλλήλων ἦσαν, ἐκέλευσεν ὑφεῖναι τὰς ῥάβδους, θεραπεύων ὡς προὔχοντα τιμῇ τὸν Μέτελλον. ὁ δὲ καὶ τοῦτο διεκώλυσε καὶ τἆλλα χρηστὸς ἦν ἀνὴρ περὶ αὐτόν, οὐδὲν ὡς ὑπατικῷ καὶ πρεσβυτέρῳ νέμων ἑαυτῷ πλέον, ἀλλ’ ἢ τὸ σύνθημα κοινῇ στρατοπεδευόντων εἰς ἅπαντας ἐξεπέμπετο παρὰ Μετέλλου· τὰ πολλὰ δὲ χωρὶς ἐστρατοπεδεύοντο. διέκοπτε γὰρ αὐτοὺς καὶ διΐστη ποικίλος ὢν ὁ πολέμιος καὶ δεινὸς ἐν βραχεῖ πολλαχοῦ περιφανῆναι καὶ μεταγαγεῖν ἀπ’ ἄλλων εἰς ἄλλους ἀγῶνας, τέλος δὲ περικόπτων μὲν ἀγοράς, ληϊζόμενος δὲ τὴν χώραν, ἐπικρατῶν δὲ τῆς θαλάσσης, ἐξέβαλεν ἀμφοτέρους τῆς ὑφ’ ἑαυτὸν Ἰβηρίας, ἀναγκασθέντας εἰς ἀλλοτρίας καταφυγεῖν ἐπαρχίας ἀπορίᾳ τῶν ἐπιτηδείων.", "st": "Pomp. 19.5"}, {"sp": "N", "t": "Πομπήϊος δὲ τὰ πλεῖστα τῶν ἰδίων ἐξανηλωκὼς καὶ κατακεχρημένος εἰς τόν πόλεμον, ᾔτει χρήματα τὴν σύγκλητον, ὡς ἀφιξόμενος εἰς Ἰταλίαν μετὰ τῆς δυνάμεως εἰ μὴ πέμποιεν. ὑπατεύων δὲ Λεύκολλος τότε καὶ Πομπηΐῳ μὲν ὢν διάφορος, μνώμενος δ’ ἑαυτῷ τόν Μιθριδατικὸν πόλεμον, ἔσπευσεν ἀποσταλῆναι τὰ χρήματα, φοβούμενος αἰτίαν Πομπηΐῳ παρασχεῖν δεομένῳ Σερτώριον ἀφεῖναι καὶ πρὸς Μιθριδάτην τραπέσθαι, λαμπρὸν μὲν εἰς δόξαν, εὐμεταχείριστον δὲ φαινόμενον ἀνταγωνιστήν. ἐν τούτῳ δὲ θνήσκει Σερτώριος ὑπὸ τῶν φίλων δολοφονηθείς· ὧν Περπέννας ὁ κορυφαιότατος ἐπεχείρησεν ἐκείνῳ τὰ αὐτὰ ποιεῖν, ἀπὸ τῶν αὐτῶν μὲν ὁρμώμενος δυνάμεων καὶ παρασκευῶν, τόν δὲ χρώμενον αὐταῖς ὁμοίως οὐκ ἔχων λογισμόν. εὐθὺς οὖν ὁ Πομπήϊος ἐπεξελθὼν καὶ ῥεμβόμενον ἐν τοῖς πράγμασι τόν Περπένναν καταμαθών, δέλεαρ αὐτῷ δέκα σπείρας ὑφῆκεν, εἰς τὸ πεδίον διασπαρῆναι κελεύσας. τραπομένου δὲ πρὸς ταύτας ἐκείνου καὶ διώκοντος, ἄθρους ἐπιφανεὶς καὶ συνάψας μάχην ἐκράτησε πάντων, καὶ διεφθάρησαν οἱ πλεῖστοι τῶν ἡγεμόνων ἐν τῇ μάχῃ· τόν δὲ Περπένναν ἀχθέντα πρὸς αὐτὸν ἀπέκτεινεν, οὐκ ἀχάριστος οὐδ’ ἀμνήμων γενόμενος τῶν περὶ Σικελίαν, ὡς ἐγκαλοῦσιν ἔνιοι, μεγάλῃ δὲ διανοίᾳ καὶ σωτηρίῳ τῶν ὅλων γνώμῃ χρησάμενος. ὁ γὰρ Περπέννας τῶν Σερτωρίου γραμμάτων γεγονὼς κύριος ἐδείκνυεν ἐπιστολὰς τῶν ἐν Ῥώμῃ δυνατωτάτων ἀνδρῶν, οἳ τὰ παρόντα κινῆσαι βουλόμενοι πράγματα καὶ μεταστῆσαι τὴν πολιτείαν ἐκάλουν τόν Σερτώριον εἰς τὴν Ἰταλίαν. φοβηθεὶς οὖν ὁ Πομπήϊος ταῦτα, μὴ μείζονας ἀναστήσῃ τῶν πεπαυμένων πολέμων, τόν τε Περπένναν ἀνεῖλε καὶ τὰς ἐπιστολὰς οὐδ’ ἀναγνοὺς κατέκαυσεν.", "st": "Pomp. 20.1"}, {"sp": "N", "t": "ἐκ δὲ τούτου παραμείνας χρόνον ὅσον τὰς μεγίστας κατασβέσαι ταραχὰς καὶ τὰ φλεγμαίνοντα μάλιστα καταστῆσαι καὶ διαλῦσαι τῶν πραγμάτων, ἀπῆγεν εἰς Ἰταλίαν τὸν στρατόν, ἀκμάζοντι τῷ δουλικῷ πολέμῳ κατὰ τύχην φερόμενος. διὸ καὶ Κράσσος ὁ στρατηγὸς ἤπειξε παραβόλως τὴν μάχην, καὶ κατευτύχησε, δισχιλίους τριακοσίους ἐπὶ μυρίοις κτείνας. οὐ μὴν ἀλλὰ καὶ τούτῳ τὸν Πομπήϊον εἰσποιούσης ἁμῶς γέ πως τῷ κατορθώματι τῆς τύχης, πεντακισχίλιοι φεύγοντες ἐκ τῆς μάχης ἐνέπεσον εἰς αὐτόν, οὓς ἅπαντας διαφθείρας, ἔγραψε πρὸς τὴν σύγκλητον ὑποφθάσας ὡς Κράσσος μὲν ἐκ παρατάξεως νενίκηκε τοὺς μονομάχους, αὐτὸς δὲ τὸν πόλεμον ἐκ ῥιζῶν παντάπασιν ἀνῄρηκε. καὶ ταῦτα βουλομένοις ἦν δι’ εὔνοιαν ἀκροᾶσθαι καὶ λέγειν τοῖς Ῥωμαίοις. Ἰβηρίαν δὲ καὶ Σερτώριον οὐδὲ παίζων ἄν τις εἶπεν ἑτέρου καὶ μὴ Πομπηΐου τὸ πᾶν ἔργον εἶναι.", "st": "Pomp. 21.1"}, {"sp": "N", "t": "ἐν τοσαύτῃ δὲ τιμῇ καὶ προσδοκίᾳ τοῦ ἀνδρὸς ὅμως ἐνῆν καὶ ὑποψία τις καὶ δέος, ὡς οὐ προησομένου τὸ στράτευμα, βαδιουμένου δὲ δι’ ὅπλων καὶ μοναρχίας ἄντικρυς ἐπὶ τὴν Σύλλα πολιτείαν. ὅθεν οὐκ ἐλάττονες ἦσαν τῶν δι’ εὔνοιαν τρεχόντων καὶ φιλοφρονουμένων καθ’ ὁδὸν οἱ φόβῳ ταῦτα ποιοῦντες. ἐπεὶ δὲ καὶ ταύτην ἀνεῖλε τὴν ὑπόνοιαν ὁ Πομπήϊος προειπὼν ἀφήσειν τὸ στράτευμα μετὰ τὸν θρίαμβον, ἓν αἰτιᾶσθαι τοῖς βασκαίνουσι περιῆν ὑπόλοιπον, ὅτι τῷ δήμῳ προσνέμει μᾶλλον ἑαυτὸν ἢ τῇ βουλῇ, καὶ τὸ τῆς δημαρχίας ἀξίωμα, Σύλλα καταβαλόντος, ἔγνωκεν ἀνιστάναι καὶ χαρίζεσθαι τοῖς πολλοῖς, ὅπερ ἦν ἀληθές. οὐ γὰρ ἔστιν οὗτινος ἐμμανέστερον ὁ Ῥωμαίων ἠράσθη δῆμος καὶ μᾶλλον ἐπόθησεν ἢ τὴν ἀρχὴν αὖθις ἐπιδεῖν ἐκείνην, ὥστε καὶ Πομπήϊον εὐτύχημα ποιεῖσθαι μέγα τὸν τοῦ πολιτεύματος καιρόν, ὡς οὐκ ἂν εὑρόντα χάριν ἄλλην ᾗ τὴν εὔνοιαν ἀμείψεται τῶν πολιτῶν, εἰ ταύτην ἕτερος προέλαβε.", "st": "Pomp. 21.3"}, {"sp": "N", "t": "Ψηφισθέντος οὖν αὐτῷ δευτέρου θριάμβου καὶ ὑπατείας οὐ διὰ ταῦτα θαυμαστὸς ἐδόκει καὶ μέγας, ἀλλ’ ἐκεῖνο τεκμήριον ἐποιοῦντο τῆς λαμπρότητος, ὅτι Κράσσος, ἀνὴρ τῶν τότε πολιτευομένων πλουσιώτατος καὶ δεινότατος εἰπεῖν καὶ μέγιστος, αὐτόν τε Πομπήϊον ὑπερφρονῶν καὶ τούς ἄλλους ἅπαντας, οὐκ ἐθάρρησεν ὑπατείαν μετιέναι πρότερον ἢ Πομπηΐου δεηθῆναι. καὶ μέντοι Πομπήϊος ἠγάπησε, πάλαι δεόμενος χρείας τινὸς ὑπάρξαι καὶ φιλανθρωπίας πρὸς αὐτόν· ὥστε καὶ δεξιοῦσθαι προθύμως καὶ παρακαλεῖν τὸν δῆμον, ἐπαγγελλόμενος χάριν ἕξειν οὐκ ἐλάττονα τοῦ συνάρχοντος ἢ τῆς ἀρχῆς. οὐ μὴν ἀλλ’ ἀποδειχθέντες ὕπατοι διεφέροντο πάντα καὶ προσέκρουον ἀλλήλοις· καὶ ἐν μὲν τῇ βουλῇ μᾶλλον ἴσχυεν ὁ Κράσσος, ἐν δὲ τῷ δήμῳ μέγα τὸ Πομπηΐου κράτος ἦν. καὶ γὰρ ἀπέδωκε τὴν δημαρχίαν αὐτῷ, καὶ τὰς δίκας περιεῖδεν αὖθις εἰς τοὺς ἱππέας νόμῳ μεταφερομένας. ἥδιστον δὲ θέαμα τῷ δήμῳ παρέσχεν αὐτὸς ἑαυτὸν τὴν στρατείαν παραιτούμενος.", "st": "Pomp. 22.1"}, {"sp": "N", "t": "ἔθος γάρ ἐστι Ῥωμαίων τοῖς ἱππεῦσιν, ὅταν στρατεύσωνται τὸν νόμιμον χρόνον, ἄγειν εἰς ἀγορὰν τὸν ἵππον ἐπὶ τούς δύο ἄνδρας οὓς τιμητὰς καλοῦσι, καὶ καταριθμησαμένους τῶν στρατηγῶν καὶ αὐτοκρατόρων ἕκαστον ὑφ’ οἷς ἐστρατεύσαντο, καὶ δόντας εὐθύνας τῆς στρατείας ἀφίεσθαι. νέμεται δὲ καὶ τιμὴ καὶ ἀτιμία προσήκουσα τοῖς βίοις ἑκάστων.", "st": "Pomp. 22.4"}, {"sp": "N", "t": "τότε δὴ προεκάθηντο μὲν οἱ τιμηταὶ Γέλλιος καὶ Λέντλος ἐν κόσμῳ, καὶ πάροδος ἦν τῶν ἱππέων ἐξεταζομένων, ὤφθη δὲ Πομπήϊος ἄνωθεν ἐπ’ ἀγορὰν κατερχόμενος, τὰ μὲν ἄλλα παράσημα τῆς ἀρχῆς ἔχων, αὐτὸς δὲ διὰ χειρὸς ἄγων τὸν ἵππον. ὡς δ’ ἐγγὺς ἦν καὶ καταφανὴς ἐγεγόνει, κελεύσας διασχεῖν τοὺς ῥαβδοφόρους τῷ βήματι προσήγαγε τὸν ἵππον. ἦν δὲ τῷ δήμῳ θαῦμα καὶ σιωπὴ πᾶσα, τούς τε ἄρχοντας αἰδὼς ἅμα καὶ χαρὰ πρὸς τὴν ὄψιν ἔσχεν. εἶτα ὁ μὲν πρεσβύτερος ἠρώτησε· πυνθάνομαί σου, ὦ Πομπήϊε Μάγνε, εἰ πάσας ἐστράτευσαι τὰς κατὰ νόμον στρατείας; Πομπήϊος δὲ μεγάλῃ φωνῇ, πάσας, εἶπεν, ἐστράτευμαι, καὶ πάσας ὑπ’ ἐμαυτῷ αὐτοκράτορι. τοῦτο ἀκούσας ὁ δῆμος ἐξέκραγε, καὶ κατασχεῖν οὐκέτι τὴν βοὴν ὑπὸ χαρᾶς ἦν, ἀλλ’ ἀναστάντες οἱ τιμηταὶ προέπεμπον αὐτόν οἴκαδε, χαριζόμενοι τοῖς πολίταις ἑπομένοις καὶ κροτοῦσιν.", "st": "Pomp. 22.5"}, {"sp": "N", "t": "ἤδη δὲ τῆς ἀρχῆς περαινομένης τῷ Πομπηΐῳ, τῆς δὲ πρὸς Κράσσον αὐξομένης διαφορᾶς, Γάϊός τις Αὐρήλιος, ἀξίωμα μὲν ἱππικὸν ἔχων, βίῳ δὲ ἀπράγμονι κεχρημένος, ἐκκλησίας οὔσης ἀναβὰς ἐπὶ τὸ βῆμα καὶ προσελθὼν ἔφη κατὰ τοὺς ὕπνους αὐτῷ τὸν Δία φανῆναι, κελεύοντα τοῖς ὑπάτοις φράσαι μὴ πρότερον ἀποθέσθαι τὴν ἀρχὴν ἢ φίλους ἀλλήλοις γενέσθαι. ῥηθέντων δὲ τούτων ὁ μὲν Πομπήϊος ἡσυχίαν ἦγεν ἑστώς, ὁ δὲ Κράσσος ἀρξάμενος δεξιοῦσθαι καὶ προσαγορεύειν αὐτόν, οὐδέν, εἶπεν, οἶμαι ποιεῖν ἀγεννὲς οὐδὲ ταπεινόν, ὦ πολῖται, Πομπηΐῳ πρότερος ἐνδιδούς, ὃν ὑμεῖς μήπω μὲν γενειῶντα Μέγαν ἠξιώσατε καλεῖν, μήπω δὲ μετέχοντι βουλῆς ἐψηφίσασθε δύο θριάμβους. ἐκ τούτου διαλλαγέντες ἀπέθεντο τὴν ἀρχήν·", "st": "Pomp. 23.1"}, {"sp": "N", "t": "καὶ Κράσσος μὲν ὅνπερ ἐξ ἀρχῆς εἵλετο τρόπον τοῦ βίου διεφύλαττε, Πομπήϊος δὲ τάς τε πολλὰς ἀνεδύετο συνηγορίας καὶ τὴν ἀγορὰν κατὰ μικρὸν ἀπέλειπε καὶ προῄει σπανίως εἰς τὸ δημόσιον, ἀεὶ δὲ μετὰ πλήθους, οὐ γὰρ ἦν ἔτι ῥᾴδιον ὄχλου χωρὶς ἐντυχεῖν οὐδ’ ἰδεῖν αὐτόν, ἀλλ’ ἥδιστος ὁμοῦ πολλοῖς καὶ ἀθρόοις ἐφαίνετο, σεμνότητα περιβαλλόμενος ἐκ τούτου τῇ ὄψει καὶ ὄγκον, ταῖς δὲ τῶν πολλῶν ἐντεύξεσι καὶ συνηθείαις ἄθικτον οἰόμενος δεῖν τὸ ἀξίωμα διατηρεῖν. ὁ γὰρ ἐν ἱματίῳ βίος ἐπισφαλής ἐστι πρὸς ἀδοξίαν τοῖς ἐκ τῶν ὅπλων μεγάλοις καὶ πρὸς ἰσότητα δημοτικὴν ἀσυμμέτροις· αὐτοὶ μὲν γὰρ καὶ ἐνταῦθα πρωτεύειν, ὡς ἐκεῖ, δικαιοῦσι, τοῖς δὲ ἐκεῖ φερομένοις ἔλαττον ἐνταῦθα γοῦν μὴ πλέον ἔχειν οὐκ ἀνεκτόν ἐστι. διὸ τὸν ἐν στρατοπέδοις καὶ θριάμβοις λαμπρόν, ὅταν ἐν ἀγορᾷ λάβωσιν, ὑπὸ χεῖρα ποιοῦνται καὶ καταβάλλουσι, τῷ δὲ ἀπολεγομένῳ καὶ ὑποχωροῦντι τὴν ἐκεῖ τιμὴν καὶ δύναμιν ἀνεπίφθονον φυλάττουσιν. ἐδήλωσε δὲ αὐτὰ τὰ πράγματα μετ’ ὀλίγον χρόνον.", "st": "Pomp. 23.3"}, {"sp": "N", "t": "ἡ γὰρ πειρατικὴ δύναμις ὡρμήθη μὲν ἐκ Κιλικίας τὸ πρῶτον, ἀρχὴν παράβολον λαβοῦσα καὶ λανθάνουσαν, φρόνημα δὲ καὶ τόλμαν ἔσχεν ἐν τῷ Μιθριδατικῷ πολέμῳ, χρήσασα ταῖς βασιλικαῖς ὑπηρεσίαις ἑαυτήν. εἶτα Ῥωμαίων ἐν τοῖς ἐμφυλίοις πολέμοις περὶ θύρας τῆς Ῥώμης συμπεσόντων, ἔρημος οὖσα φρουρᾶς ἡ θάλασσα κατὰ μικρὸν αὐτοὺς ἐφείλκετο καὶ προῆγεν, οὐκέτι τοῖς πλέουσι μόνον ἐπιτιθεμένους, ἀλλὰ καὶ νήσους καὶ πόλεις παραλίους ἐκκόπτοντας. ἤδη δὲ καὶ χρήμασι δυνατοὶ καὶ γένεσι λαμπροὶ καὶ τὸ φρονεῖν ἀξιούμενοι διαφέρειν ἄνδρες ἐνέβαινον εἰς τὰ λῃστρικὰ καὶ μετεῖχον, ὡς καὶ δόξαν τινὰ καὶ φιλοτιμίαν τοῦ ἔργου φέροντος. ἦν δὲ καὶ ναύσταθμα πολλαχόθι πειρατικὰ καὶ φρυκτώρια τετειχισμένα, καὶ στόλοι προσέπιπτον οὐ πληρωμάτων μόνον εὐανδρίαις οὐδὲ τέχναις κυβερνητῶν οὐδὲ τάχεσι νεῶν καὶ κουφότησιν ἐξησκημένοι πρὸς τὸ οἰκεῖον ἔργον, ἀλλὰ τοῦ φοβεροῦ μᾶλλον αὐτῶν τὸ ἐπίφθονον ἐλύπει καὶ ὑπερήφανον, στυλίσι χρυσαῖς καὶ παραπετάσμασιν ἁλουργοῖς καὶ πλάταις ἐπαργύροις, ὥσπερ ἐντρυφώντων τῷ κακουργεῖν καὶ καλλωπιζομένων. αὐλοὶ δὲ καὶ ψαλμοὶ καὶ μέθαι παρὰ πᾶσαν ἀκτὴν καὶ σωμάτων ἡγεμονικῶν ἁρπαγαὶ καὶ πόλεων αἰχμαλώτων ἀπολυτρώσεις ὄνειδος ἦσαν τῆς Ῥωμαίων ἡγεμονίας, ἐγένοντο δ’ οὖν αἱ μὲν λῃστρίδες νῆες ὑπὲρ χιλίας, αἱ δὲ ἁλοῦσαι πόλεις ὑπ’ αὐτῶν τετρακόσιαι. τῶν δὲ ἀσύλων καὶ ἀβάτων πρότερον ἱερῶν ἐξέκοψαν ἐπιόντες τὸ Κλάριον, τὸ Διδυμαῖον, τὸ Σαμοθρᾴκιον, τὸν ἐν Ἑρμιόνῃ τῆς Χθονίας νεὼν καὶ τὸν ἐν Ἐπιδαύρῳ τοῦ Ἀσκληπιοῦ καὶ τὸν Ἰσθμοῖ καὶ Ταινάρῳ καὶ Καλαυρίᾳ τὸν Ποσειδῶνος, τοῦ δὲ Ἀπόλλωνος τὸν ἐν Ἀκτίῳ καὶ Λευκάδι, τῆς δὲ Ἥρας τὸν ἐν Σάμῳ, τὸν ἐν Ἄργει, τὸν ἐπὶ Λακινίῳ. ξένας δὲ θυσίας ἔθυον αὐτοὶ τὰς ἐν Ὀλύμπῳ, καὶ τελετάς τινας ἀπορρήτους ἐτέλουν, ὧν ἡ τοῦ Μίθρου καὶ μέχρι δεῦρο διασώζεται καταδειχθεῖσα πρῶτον ὑπ’ ἐκείνων.", "st": "Pomp. 24.1"}, {"sp": "N", "t": "πλεῖστα δὲ Ῥωμαίοις ἐνυβρίσαντες, ἔτι καὶ τὰς ὁδοὺς αὐτῶν ἀναβαίνοντες ἀπὸ θαλάσσης ἐληΐζοντο καὶ τὰς ἐγγὺς ἐπαύλεις ἐξέκοπτον. ἥρπασαν δέ ποτε καὶ στρατηγοὺς δύο Σεξτίλιον καὶ Βελλῖνον ἐν ταῖς περιπορφύροις, καὶ τούς ὑπηρέτας ἅμα καὶ ῥαβδοφόρους ᾤχοντο σὺν αὐτοῖς ἐκείνοις ἔχοντες. ἥλω δὲ καὶ θυγάτηρ Ἀντωνίου, θριαμβικοῦ ἀνδρός, εἰς ἀγρὸν βαδίζουσα, καὶ πολλῶν χρημάτων ἀπελυτρώθη. ἐκεῖνο δὲ ἦν ὑβριστικώτατον. ὁπότε γάρ τις ἑαλωκὼς ἀναβοήσειε Ῥωμαῖος εἶναι καὶ τοὔνομα φράσειεν, ἐκπεπλῆχθαι προσποιούμενοι καὶ δεδιέναι τούς τε μηροὺς ἐπαίοντο καὶ προσέπιπτον αὐτῷ, συγγνώμην ἔχειν ἀντιβολοῦντες· ὁ δὲ ἐπείθετο ταπεινοὺς ὁρῶν καὶ δεομένους, ἐκ τούτου δὲ οἱ μὲν ὑπέδουν τοῖς καλκίοις αὐτόν, οἱ δὲ τήβεννον περιέβαλλον, ὡς δὴ μὴ πάλιν ἀγνοηθείη. πολὺν δὲ χρόνον οὕτω κατειρωνευσάμενοι καὶ ἀπολαύσαντες τοῦ ἀνθρώπου, τέλος ἐν μέσῳ πελάγει κλίμακα προσβαλόντες ἐκέλευον ἐκβαίνειν καὶ ἀπιέναι χαίροντα, τὸν δὲ μὴ βουλόμενον ὠθοῦντες αὐτοὶ κατέδυον.", "st": "Pomp. 24.6"}, {"sp": "N", "t": "ἐπενείματο δὲ ἡ δύναμις αὕτη πᾶσαν ὁμοῦ τι τὴν καθ’ ἡμᾶς θάλασσαν, ὥστε ἄπλουν καὶ ἄβατον ἐμπορίᾳ πάσῃ γενέσθαι, τοῦτο δὴ μάλιστα Ῥωμαίους ἐπέστρεψε, θλιβομένους τῇ ἀγορᾷ καὶ σπάνιν μεγάλην προσδοκῶντας, ἐκπέμψαι Πομπήϊον ἀφαιρησόμενον τῶν πειρατῶν τὴν θάλασσαν. ἔγραψε δὲ Γαβίνιος, εἷς τῶν Πομπηΐου συνήθων, νόμον οὐ ναυαρχίαν, ἄντικρυς δὲ μοναρχίαν αὐτῷ διδόντα καὶ δύναμιν ἐπὶ πάντας ἀνθρώπους ἀνυπεύθυνον. ἐδίδου γὰρ ἄρχειν ὁ νόμος αὐτῷ τῆς ἐντὸς Ἡρακλείων στηλῶν θαλάσσης, ἠπείρου δὲ πάσης ἐπὶ σταδίους τετρακοσίους ἀπὸ θαλάσσης, τοῦτο δὲ οὐ πάνυ πολλὰ χωρία τῆς ὑπὸ Ῥωμαίων οἰκουμένης τὸ μέτρον ἐξέφυγεν, ἀλλὰ τὰ μέγιστα τῶν ἐθνῶν καὶ τῶν βασιλέων οἱ δυνατώτατοι περιελαμβάνοντο. πρὸς δὲ τούτοις ἑλέσθαι πεντεκαίδεκα πρεσβευτὰς αὐτὸν ἐκ βουλῆς ἐπὶ τὰς κατὰ μέρος ἡγεμονίας, χρήματα δὲ λαμβάνειν ἐκ τῶν ταμιείων καὶ παρὰ τῶν τελωνῶν ὅσα βούλοιτο καὶ ναῦς διακοσίας, κύριον ὄντα πλήθους καὶ καταλόγου στρατιᾶς καὶ πληρωμάτων ἐρετικῶν.", "st": "Pomp. 25.1"}, {"sp": "N", "t": "ἀναγνωσθέντων δὲ τούτων ὁ μὲν δῆμος ὑπερφυῶς ἐδέξατο, τῆς δὲ συγκλήτου τοῖς μεγίστοις καὶ δυνατωτάτοις ἔδοξε μεῖζον μὲν φθόνου, φόβου δὲ ἄξιον εἶναι τὸ τῆς ἐξουσίας ἀπερίληπτον καὶ ἀόριστον. ὅθεν ἐνίσταντο τῷ νόμῳ, πλὴν Καίσαρος οὗτος δὲ συνηγόρει τῷ νόμῳ, Πομπηΐου μὲν ἐλάχιστα φροντίζων, ὑποδυόμενος δὲ τὸν δῆμον ἐξ ἀρχῆς ἑαυτῷ καὶ κτώμενος, οἱ δὲ ἄλλοι τοῦ Πομπηΐου σφοδρῶς καθήπτοντο. καὶ τῶν μὲν ὑπάτων ἅτερος, εἰπὼν πρὸς αὐτὸν ὅτι Ῥωμύλον ζηλῶν οὐ φεύξεται ταὐτὸν ἐκείνῳ τέλος, ἐκινδύνευσεν ὑπὸ τοῦ πλήθους διαφθαρῆναι· Κάτλου δὲ κατὰ τοῦ νόμου προσελθόντος, πολλὴν μὲν αἰδούμενος ὁ δῆμος ἡσυχίαν παρεῖχεν, ἐπεὶ δὲ πολλὰ μετὰ τιμῆς ἀνεπιφθόνως ὑπὲρ τοῦ Πομπηΐου διελθὼν συνεβούλευε φείδεσθαι καὶ μὴ προβάλλειν τοιοῦτον ἄνδρα κινδύνοις ἐπαλλήλοις καὶ πολέμοις, ἢ τίνα εἶπεν, ἕξετε ἄλλον, ἂν ἀπολέσητε τοῦτον; ἐκ μιᾶς γνώμης ὑπεφώνησαν ἅπαντες, σὲ αὐτόν. ὁ μὲν οὖν Κάτλος, ὡς οὐκ ἔπειθεν, ἀπέστη· Ῥωσκίου δὲ προσελθόντος οὐδεὶς ἤκουσεν· ὁ δὲ τοῖς δακτύλοις διεσήμαινε μὴ μόνον, ἀλλὰ δεύτερον αἱρεῖσθαι Πομπήϊον. ἐπὶ τούτῳ λέγεται δυσχεράναντα τὸν δῆμον τηλικοῦτον ἀνακραγεῖν ὥστε ὑπερπετόμενον κόρακα τῆς ἀγορᾶς τυφωθῆναι καὶ καταπεσεῖν εἰς τὸν ὄχλον. ὅθεν οὐ δοκεῖ ῥήξει τοῦ ἀέρος καὶ διασπασμῷ κενὸν πολὺ λαμβάνοντος ἐνολισθαίνειν τὰ πίπτοντα τῶν ὀρνέων, ἀλλὰ τυπτόμενα τῇ πληγῇ τῆς φωνῆς, ὅταν ἐν τῷ ἀέρι σάλον καὶ κῦμα ποιήσῃ πολλὴ καὶ ἰσχυρὰ φερομένη.", "st": "Pomp. 25.4"}, {"sp": "N", "t": "τότε μὲν οὖν διελύθησαν ᾗ δὲ ἡμέρᾳ τὴν ψῆφον ἐποίσειν ἔμελλον, ὑπεξῆλθεν ὁ Πομπήϊος εἰς ἀγρόν. ἀκούσας δὲ κεκυρῶσθαι τὸν νόμον εἰσῆλθε νύκτωρ εἰς τὴν πόλιν, ὡς ἐπιφθόνου τῆς πρὸς αὐτὸν ἀπαντήσεως καὶ συνδρομῆς ἐσομένης. ἅμα δὲ ἡμέρᾳ προελθὼν ἔθυσε· καὶ γενομένης ἐκκλησίας αὐτῷ, διεπράξατο προσλαβεῖν ἕτερα πολλὰ τοῖς ἐψηφισμένοις ἤδη, μικροῦ διπλασιάσας τὴν παρασκευήν. πεντακόσιαι μὲν γὰρ αὑτῷ νῆες ἐπληρώθησαν, ὁπλιτῶν δὲ μυριάδες δώδεκα καὶ πεντακισχίλιοι ἱππεῖς ἠθροίσθησαν. ἡγεμονικοὶ δὲ καὶ στρατηγικοὶ κατελέγησαν ἀπὸ βουλῆς ἄνδρες εἰκοσιτέσσαρες ὑπ’ αὐτοῦ, δύο δὲ ταμίαι παρῆσαν. αἱ δὲ τιμαὶ τῶν ὠνίων εὐθὺς πεσοῦσαι λόγον ἡδομένῳ τῷ δήμῳ παρεῖχον, ὡς αὐτὸ τοὔνομα τὸν Πομπηΐου λέλυκε τὸν πόλεμον.", "st": "Pomp. 26.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ διελὼν τὰ πελάγη καὶ τὸ διάστημα τῆς ἐντὸς θαλάσσης εἰς μέρη τρισκαίδεκα, καὶ νεῶν ἀριθμὸν ἐφ’ ἑκάστῳ καὶ ἄρχοντα τάξας, ἅμα πανταχοῦ τῇ δυνάμει σκεδασθείσῃ τὰ μὲν ἐμπίπτοντα τῶν πειρατικῶν ἀθρόα περιλαμβάνων εὐθὺς ἐξεθηρᾶτο καὶ κατῆγεν οἱ δὲ φθάσαντες διαλυθῆναι καὶ διεκπεσόντες ὥσπερ εἰς σμῆνος ἐδύοντο πανταχόθεν καταφερόμενοι τὴν Κιλικίαν, ἐφ’ οὓς αὐτὸς ἐστέλλετο ναῦς ἔχων ἑξήκοντα τὰς ἀρίστας. οὐ μὴν πρότερον ἐπ’ ἐκείνους ἐξέπλευσεν ἢ παντάπασι καθῆραι τῶν αὐτόθι λῃστηρίων τὸ Τυρρηνικὸν πέλαγος, τὸ Λιβυκόν, τὸ περὶ Σαρδόνα καὶ Κύρνον καὶ Σικελίαν, ἡμέραις τεσσαράκοντα ταῖς πάσαις, αὑτῷ τε χρώμενος ἀτρύτῳ καὶ τοῖς στρατηγοῖς προθύμοις.", "st": "Pomp. 26.3"}, {"sp": "N", "t": "ἐν δὲ Ῥώμῃ τοῦ ὑπάτου Πείσωνος ὀργῇ καὶ φθόνῳ λυμαινομένου τὴν παρασκευὴν καὶ διαλύοντος τὰ πληρώματα, τὸ μὲν ναυτικὸν εἰς Βρεντέσιον περιέπεμψεν, αὐτὸς δὲ διὰ Τυρρηνίας εἰς Ῥώμην ἀνέβαινεν. αἰσθόμενοι δὲ πάντες ἐξεχύθησαν εἰς τὴν ὁδόν, ὥσπερ οὐ πρὸ ἡμερῶν ὀλίγων ἐκπέμψαντες αὐτόν. ἐποίει δὲ τὴν χαρὰν τὸ παρ’ ἐλπίδα τῆς μεταβολῆς τάχος, ὑπερβάλλουσαν ἀφθονίαν τῆς ἀγορᾶς ἐχούσης. ὅθεν ὁ Πείσων ἐκινδύνευσε τὴν ὑπατείαν ἀφαιρεθῆναι, Γαβινίου νόμον ἔχοντος ἤδη συγγεγραμμένον. ἀλλὰ καὶ τοῦτο διεκώλυσεν ὁ Πομπήϊος, καὶ τἆλλα χρηματίσας ἐπιεικῶς καὶ διαπραξάμενος ὧν ἐδεῖτο, καταβὰς εἰς Βρεντέσιον ἐξέπλευσεν. ἐπειγόμενος δὲ τῷ καιρῷ καὶ παραπλέων τὰς πόλεις ὑπὸ σπουδῆς, ὅμως οὐ παρῆλθε τὰς Ἀθήνας, ἀναβὰς δὲ καὶ θύσας τοῖς θεοῖς καὶ προσαγορεύσας τὸν δῆμον εὐθὺς ἀπιὼν ἀνεγίνωσκεν εἰς αὐτὸν ἐπιγεγραμμένα μονόστιχα, τὸ μὲν ἐντὸς τῆς πύλης·", "st": "Pomp. 27.1"}, {"sp": "N", "t": "ἐφ’ ὅσον ὢν ἄνθρωπος οἶδας, ἐπὶ τοσοῦτον εἶ θεός·<br>τὸ δ’ ἐκτός·<br>προσεδοκῶμεν, προσεκυνοῦμεν, εἴδομεν, προπέμπομεν.", "st": "Pomp. 27.1b"}, {"sp": "N", "t": "ἐπεὶ δὲ τῶν συνεστώτων ἔτι καὶ πλανωμένων ἔξω πειρατηρίων ἐνίοις δεηθεῖσιν ἐπιεικῶς ἐχρήσατο καὶ παραλαβὼν τὰ πλοῖα καὶ τὰ σώματα κακὸν οὐδὲν ἐποίησεν, ἐπ’ ἐλπίδος χρηστῆς οἱ λοιποὶ γενόμενοι τοὺς μὲν ἄλλους διέφευγον ἡγεμόνας, Πομπηΐῳ δὲ φέροντες ἑαυτοὺς μετὰ τέκνων καὶ γυναικῶν ἐνεχείριζον. ὁ δὲ πάντων ἐφείδετο, καὶ μάλιστα διὰ τούτων τοὺς ἔτι λανθάνοντας ἐξιχνεύων καὶ λαμβάνων ἐκόλαζεν ὡς αὐτοὺς ἑαυτοῖς ἀνήκεστα συνειδότας.", "st": "Pomp. 27.4"}, {"sp": "N", "t": "οἱ δὲ πλεῖστοι καὶ δυνατώτατοι γενεὰς μὲν αὑτῶν καὶ χρήματα καὶ τὸν ἄχρηστον ὄχλον ἐν φρουρίοις καὶ πολίσμασι καρτεροῖς περὶ τὸν Ταῦρον εἶχον ἀποκείμενα, τὰς δὲ ναῦς πληρώσαντες αὐτοὶ περὶ τὸ Κορακήσιον τῆς Κιλικίας ἐπιπλέοντα τὸν Πομπήϊον ἐδέξαντο· καὶ μάχης γενομένης νικηθέντες ἐπολιορκοῦντο. τέλος δὲ πέμψαντες ἱκετηρίας παρέδωκαν ἑαυτοὺς καὶ πόλεις καὶ νήσους ὧν ἐπεκράτουν ἐντειχισάμενοι, χαλεπὰς βιασθῆναι καὶ δυσπροσπελάστους. κατελύθη μὲν οὖν ὁ πόλεμος καὶ τὰ πανταχοῦ λῃστήρια τῆς θαλάσσης ἐξέπεσεν οὐκ ἐν πλείονι χρόνῳ τριῶν μηνῶν, ναῦς δὲ πολλὰς μὲν ἄλλας, ἐνενήκοντα δὲ χαλκεμβόλους παρέλαβεν. αὐτοὺς δὲ δισμυρίων πλείονας γενομένους ἀνελεῖν μὲν οὐδὲ ἐβουλεύσατο, μεθεῖναι δὲ καὶ περιϊδεῖν σκεδασθέντας ἢ συστάντας αὖθις, ἀπόρους καὶ πολεμικοὺς καὶ πολλοὺς ὄντας, οὐκ ᾤετο καλῶς ἔχειν. ἐννοήσας οὖν ὅτι φύσει μὲν ἄνθρωπος οὔτε γέγονεν οὔτ’ ἔστιν ἀνήμερον ζῷον οὐδ’ ἄμικτον, ἀλλ’ ἐξίσταται τῇ κακίᾳ παρὰ φύσιν χρώμενος, ἔθεσι δὲ καὶ τόπων καὶ βίων μεταβολαῖς ἐξημεροῦται, καὶ θηρία δὲ διαίτης κοινωνοῦντα πρᾳοτέρας ἐκδύεται τὸ ἄγριον καὶ χαλεπόν, ἔγνω τοὺς ἄνδρας εἰς γῆν μεταφέρειν ἐκ τῆς θαλάσσης καὶ βίου γεύειν ἐπιεικοῦς, συνεθισθέντας ἐν πόλεσιν οἰκεῖν καὶ γεωργεῖν. ἐνίους μὲν οὖν αἱ μικραὶ καὶ ὑπέρημοι τῶν Κιλίκων πόλεις ἐδέξαντο καὶ κατέμιξαν ἑαυταῖς χώραν προσλαβοῦσαι, τὴν δὲ Σολίων ἠρημωμένην ἔναγχος ὑπὸ Τιγράνου τοῦ Ἀρμενίων βασιλέως ἀναλαβὼν ἵδρυσε πολλοὺς ἐν αὐτῇ. τοῖς δὲ πολλοῖς οἰκητήριον ἔδωκε Δύμην τὴν Ἀχαΐδα, χηρεύουσαν ἀνδρῶν τότε, γῆν δὲ πολλὴν καὶ ἀγαθὴν ἔχουσαν.", "st": "Pomp. 28.1"}, {"sp": "N", "t": "ταῦτα μὲν οὖν οἱ βασκαίνοντες ἔψεγον· τοῖς δὲ περὶ Κρήτην πραχθεῖσι πρὸς Μέτελλον οὐδ’ οἱ πάνυ φιλοῦντες αὐτὸν ἔχαιρον. ὁ γὰρ Μέτελλος, οἰκεῖος ὢν ἐκείνου τοῦ συνάρξαντος ἐν Ἰβηρίᾳ τῷ Πομπηΐῳ, στρατηγὸς εἰς Κρήτην ἐπέμφθη πρότερον ἢ τὸν Πομπήϊον αἱρεθῆναι· δευτέρα γάρ τις ἦν αὕτη τῶν πειρατηρίων πηγὴ μετὰ τὴν ἐν Κιλικίᾳ· καὶ πολλοὺς ἐγκαταλαβὼν ὁ Μέτελλος ἐξῄρει καὶ διέφθειρεν. οἱ δὲ περιόντες ἔτι καὶ πολιορκούμενοι πέμψαντες ἱκετηρίαν ἐπεκαλοῦντο τὸν Πομπήϊον εἰς τὴν νῆσον, ὡς τῆς ἐκείνου μέρος οὖσαν ἀρχῆς καὶ πανταχόθεν ἐμπίπτουσαν εἰς τὸ μέτρον τὸ ἀπὸ θαλάσσης, ὁ δὲ δεξάμενος ἔγραφε τῷ Μετέλλῳ κωλύων τὸν πόλεμον, ἔγραφε δὲ καὶ ταῖς πόλεσι μὴ προσέχειν Μετέλλῳ, καὶ στρατηγὸν ἔπεμψε τῶν ὑφ’ ἑαυτὸν ἀρχόντων ἕνα Λεύκιον Ὀκταούϊον, ὃς συνεισελθὼν εἰς τὰ τείχη τοῖς πολιορκουμένοις καὶ μαχόμενος μετ’ αὐτῶν, οὐ μόνον ἐπαχθῆ καὶ βαρύν, ἀλλὰ καὶ καταγέλαστον ἐποίει τὸν Πομπήϊον, ἀνθρώποις ἀνοσίοις καὶ ἀθέοις τοὔνομα κιχράντα καὶ περιάπτοντα τὴν αὑτοῦ δόξαν ὥσπερ ἀλεξιφάρμακον ὑπὸ φθόνου καὶ φιλοτιμίας τῆς πρὸς τὸν Μέτελλον, οὐδὲ γὰρ τὸν Ἀχιλλέα ποιεῖν ἀνδρὸς ἔργον, ἀλλὰ μειρακίου παντάπασιν ἐμπλήκτου καὶ σεσοβημένου πρὸς δόξαν, ἀνανεύοντα τοῖς ἄλλοις καὶ διακωλύοντα βάλλειν Ἕκτορα,", "st": "Pomp. 29.1"}, {"sp": "N", "t": "μή τις κῦδος ἄροιτο βαλών, ὁ δὲ δεύτερος ἔλθοι·", "st": "Pomp. 29.1b"}, {"sp": "N", "t": "Πομπήϊον δὲ καὶ σώζειν ὑπερμαχοῦντα τῶν κοινῶν πολεμίων ἐπὶ τῷ τὸν θρίαμβον ἀφελέσθαι στρατηγοῦ πολλὰ πεπονηκότος. οὐ μὴν ἐνέδωκεν ὁ Μέτελλος, ἀλλὰ τούς τε πειρατὰς ἐξελὼν ἐτιμωρήσατο, καὶ τὸν Ὀκταούϊον ἐν τῷ στρατοπέδῳ· καθυβρίσας καὶ λοιδορήσας ἀφῆκεν.", "st": "Pomp. 29.5"}, {"sp": "N", "t": "ἀπαγγελθέντος δὲ εἰς Ῥώμην πέρας ἔχειν τὸν πειρατικὸν πόλεμον καὶ σχολὴν ἄγοντα τὸν Πομπήϊον ἐπέρχεσθαι τὰς πόλεις, γράφει νόμου εἷς τῶν δημάρχων Μάλλιος, ὅσης Λεύκολλος ἄρχει χώρας καὶ δυνάμεως, Πομπήϊον παραλαβόντα πᾶσαν, προσλαβόντα δὲ καὶ Βιθυνίαν, ἣν ἔχει Γλαβρίων, πολεμεῖν Μιθριδάτῃ καὶ Τιγράνῃ τοῖς βασιλεῦσιν, ἔχοντα καὶ τὴν ναυτικὴν δύναμιν καὶ τὸ κράτος τῆς θαλάσσης ἐφ’ οἷς ἔλαβεν ἐξ ἀρχῆς. τοῦτο δ’ ἦν ἐφ’ ἑνὶ συλλήβδην γενέσθαι τὴν Ῥωμαίων ἡγεμονίαν ὧν γὰρ ἐδόκει μόνων ἐπαρχιῶν μὴ ἐφικνεῖσθαι τῷ προτέρῳ νόμῳ, Φρυγίας, Λυκαονίας, Γαλατίας, Καππαδοκίας, Κιλικίας, τῆς ἄνω Κολχίδος, Ἀρμενίας, αὗται προσετίθεντο μετὰ στρατοπέδων καὶ δυνάμεων αἷς Λεύκολλος κατεπολέμησε Μιθριδάτην καὶ Τιγράνην. ἀλλὰ Λευκόλλου μὲν ἀποστερουμένου τὴν δόξαν ὧν κατειργάσατο καὶ θριάμβου μᾶλλον ἢ πολέμου διαδοχὴν λαμβάνοντος, ἥττων λόγος ἦν τοῖς ἀριστοκρατικοῖς, καίπερ οἰομένοις ἄδικα καὶ ἀχάριστα πάσχειν τὸν ἄνδρα, τὴν δὲ δύναμιν τοῦ Πομπηΐου βαρέως φέροντες ὡς τυραννίδα καθισταμένην, ἰδίᾳ παρεκάλουν καὶ παρεθάρρυνον αὑτοὺς ἐπιλαβέσθαι τοῦ νόμου καὶ μὴ προέσθαι τὴν ἐλευθερίαν. ἐνστάντος δὲ τὸν καιροῦ, τὸν δῆμον φοβηθέντες ἐξέλιπον καὶ κατεσιώπησαν οἱ λοιποί, Κάτλος δὲ τὸν νόμου πολλὰ κατηγορήσας καὶ τοῦ δημάρχου, μηδένα δὲ πείθων, ἐκέλευε τὴν βουλὴν ἀπὸ τοῦ βήματος κεκραγὼς πολλάκις ὄρος ζητεῖν, ὥσπερ οἱ πρόγονοι, καὶ κρημνόν, ὅπου καταφυγοῦσα διασώσει τὴν ἐλευθερίαν. ἐκυρώθη δ’ οὖν ὁ νόμος, ὡς λέγουσι, πάσαις ταῖς φυλαῖς, καὶ κύριος ἀποδέδεικτο μὴ παρὼν ὁ Πομπήϊος ἁπάντων σχεδὸν ὧν ὁ Σύλλας ὅπλοις καὶ πολέμῳ τῆς πόλεως κρατήσας. αὐτὸς δὲ δεξάμενος τὰ γράμματα καὶ πυθόμενος τὰ δεδογμένα, τῶν φίλων παρόντων καὶ συνηδομένων, τὰς ὀφρῦς λέγεται συναγαγεῖν καὶ τὸν μηρὸν πατάξαι καὶ εἰπεῖν ὡς ἂν βαρυνόμενος ἤδη καὶ δυσχεραίνων τὸ ἄρχειν φεῦ τῶν ἀνηνύτων ἄθλων, ὡς ἄρα κρεῖττον ἦν ἕνα τῶν ἀδόξων γενέσθαι, εἰ μηδέποτε παύσομαι στρατευόμενος μηδὲ τὸν φθόνον τοῦτον ἐκδὺς ἐν ἀγρῷ διαιτήσομαι μετὰ τῆς γυναικός. ἐφ’ οἷς λεγομένοις οὐδ’ οἱ πάνυ συνήθεις ἔφερον αὐτοῦ τὴν εἰρωνείαν, γινώσκοντες ὅτι τῆς ἐμφύτου φιλοτιμίας καὶ φιλαρχίας ὑπέκκαυμα τὴν πρὸς Λεύκολλον ἔχων διαφορὰν μειζόνως ἔχαιρεν.", "st": "Pomp. 30.1"}, {"sp": "N", "t": "ἀμέλει δὲ καὶ τὰ ἔργα ταχέως αὑτὸν ἀπεκάλυπτε, πανταχοῦ γὰρ ἐκτιθεὶς διαγράμματα τοὺς στρατιώτας ἀνεκαλεῖτο καὶ μετεπέμπετο τοὺς ὑπηκόους δυνάστας καὶ βασιλεῖς ὡς ἑαυτόν, ἐπιών τε τὴν χώραν οὐδὲν ἀκίνητον εἴα τῶν ὑπὸ τοῦ Λευκόλλου γεγονότων, ἀλλὰ καὶ κολάσεις ἀνῆκε πολλοῖς καὶ δωρεὰς ἀφείλετο καὶ πάντα ὅλως ἔπραττεν ἐπιδεῖξαι τὸν ἄνδρα φιλονεικῶν τοῖς θαυμάζουσιν οὐδενὸς ὄντα κύριον. ἐγκαλοῦντος δ’ ἐκεῖνον διὰ τῶν φίλων, ἔδοξε συνελθεῖν εἰς ταὐτό· καὶ συνῆλθον περὶ τὴν Γαλατίαν. οἷα δὲ μεγίστων στρατηγῶν καὶ μέγιστα κατωρθωκότων δάφναις ἀνεστεμμένας ἔχοντες ὁμοῦ καὶ τὰς ῥάβδους οἱ ὑπηρέται ἀπήντων ἀλλὰ Λεύκολλος μὲν ἐκ τόπων χλοερῶν καὶ κατασκίων προσῄει, Πομπήϊος δὲ πολλὴν ἄδενδρον καὶ κατεψυγμένην ἔτυχε διεληλυθώς. ἰδόντες οὖν οἱ τοῦ Λευκόλλου ῥαβδοφόροι τὸν Πομπηΐου τὰς δάφνας ἀθαλλεῖς καὶ μεμαραμμένας παντάπασιν, ἐκ τῶν ἰδίων προσφάτων οὐσῶν μεταδιδόντες ἐπεκόσμησαν καὶ κατέστεψαν τὰς ἐκεῖνον ῥάβδους. ὃ σημεῖον ἔδοξεν εἶναι τοῦ τὰ Λευκόλλου νικητήρια καὶ τὴν δόξαν οἰσόμενον ἔρχεσθαι Πομπήϊον. ἦν δὲ Λεύκολλος μὲν ἐν ὑπατείας τε τάξει καὶ καθ’ ἡλικίαν πρεσβύτερος, τὸ δὲ τὸν Πομπηΐου μεῖζον ἀξίωμα τοῖς δνσὶ θριάμβοις. οὐ μὴν ἀλλὰ τὴν πρώτην ἔντευξιν ὡς ἐνῆν μάλιστα πολιτικῶς καὶ φιλοφρόνως ἐποιήσαντο, μεγαλύνοντες ἀλλήλων τὰ ἔργα καὶ συνηδόμενοι τοῖς κατορθώμασιν ἐν δὲ τοῖς λόγοις πρὸς οὐδὲν ἐπιεικὲς οὐδὲ μέτριον συμβάντες, ἀλλὰ καὶ λοιδορήσαντες, ὁ μὲν εἰς φιλαργυρίαν τὸν Λεύκολλον, ὁ δὲ εἰς φιλαρχίαν ἐκεῖνον, ὑπὸ τῶν φίλων μόλις διελύθησαν.", "st": "Pomp. 31.1"}, {"sp": "N", "t": "καὶ Λεύκολλος μὲν ἐν Γαλατίᾳ διέγραψε χώρας τῆς αἰχμαλώτου καὶ δωρεὰς ἄλλας οἷς ἐβούλετο, Πομπήϊος δὲ μικρὸν ἀπωτέρω στρατοπεδεύσας ἐκώλυε προσέχειν αὐτῷ, καὶ τοὺς στρατιώτας ἅπαντας ἀφείλετο πλὴν χιλίων ἑξακοσίων, οὓς ἐνόμιζεν ὑπ’ αὐθαδείας ἀχρήστους μὲν ἑαυτῷ, τῷ Λευκόλλῳ δὲ δυσμενεῖς εἶναι. πρὸς δὲ τούτοις διασύρων τὰ ἔργα ἐμφανῶς ἔλεγε τραγῳδίαις καὶ σκιαγραφίαις πεπολεμηκέναι βασιλικαῖς τὸν Λεύκολλον, αὑτῷ δὲ πρὸς ἀληθινὴν καὶ σεσωφρονισμένην τὸν ἀγῶνα λείπεσθαι δύναμιν, εἰς θυρεοὺς καὶ ξίφη καὶ ἵππους Μιθριδάτου καταφεύγοντος, ἀμυνόμενος δὲ ὁ Λεύκολλος εἰδώλῳ καὶ σκιᾷ πολέμου τὸν Πομπήϊον ἔφη μαχούμενον βαδίζειν, εἰθισμένον ἀλλοτρίοις νεκροῖς, ὥσπερ ὄρνιν ἀργόν, ἐπικαταίρειν καὶ λείψανα πολέμων σπαράσσειν. οὕτω γὰρ αὑτὸν ἐπιγράψαι Σερτωρίῳ, Λεπίδῳ, τοῖς Σπαρτακείοις, τὰ μὲν Κράσσου, τὰ δὲ Μετέλλου, τὰ δὲ Κάτλου κατωρθωκότος. ὅθεν οὐ θαυμάζειν εἰ τῶν Ἀρμενιακῶν καὶ Ποντικῶν πολέμων ὑποβάλλεται τὴν δόξαν, ἄνθρωπος ἑαυτὸν εἰς δραπετικὸν θρίαμβον ἁμῶς γέ πως ἐμβαλεῖν μηχανησάμενος.", "st": "Pomp. 31.5"}, {"sp": "N", "t": "ἐκ τούτου Λεύκολλος μὲν ἀπῆρε, Πομπήϊος δὲ τῷ στόλῳ παντὶ τὴν μεταξὺ Φοινίκης καὶ Βοσπόρου θάλασσαν ἐπὶ φρουρᾷ διαλαβών, αὐτὸς ἐβάδιζεν ἐπὶ Μιθριδάτην, ἔχοντα τρισμυρίους πεζοὺς ἐν φάλαγγι καὶ δισχιλίους ἱππεῖς, μάχεσθαι δὲ μὴ θαρροῦντα. καὶ πρῶτον μὲν αὐτοῦ καρτερὸν ὄρος καὶ δύσμαχον, ἐν ᾧ στρατοπεδεύων ἔτυχεν, ὡς ἄνυδρον ἐκλιπόντος, αὐτὸ τοῦτο κατασχὼν ὁ Πομπήϊος, καὶ τῇ φύσει τῶν βλαστανόντων καὶ ταῖς συγκλινίαις τῶν τόπων τεκμαιρόμενος ἔχειν πηγὰς τὸ χωρίον, ἐκέλευσεν ἐκβαλεῖν πανταχοῦ φρέατα, καὶ μεστὸν ἦν εὐθὺς ὕδατος ἀφθόνου τὸ στρατόπεδον, ὥστε θαυμάζειν εἰ τῷ παντὶ χρόνῳ τοῦτο Μιθριδάτης ἠγνόησεν. ἔπειτα περιστρατοπεδεύσας περιετείχιζεν αὐτόν.", "st": "Pomp. 32.1"}, {"sp": "N", "t": "ὁ δὲ πέντε καὶ τετταράκοντα πολιορκηθεὶς ἡμέρας ἔλαθεν ἀποδρὰς μετὰ τῆς ἐρρωμενεστάτης δυνάμεως, κτείνας τοὺς ἀχρήστους καὶ νοσοῦντας. εἶτα μέντοι περὶ τὸν Εὐφράτην καταλαβὼν αὐτὸν ὁ Πομπήϊος παρεστρατοπέδευσε· καὶ δεδιὼς μὴ φθάσῃ περάσας τὸν Εὐφράτην, ἐκ μέσων νυκτῶν ἐπῆγεν ὠιτλισμένην τὴν στρατιάν· καθ’ ὃν χρόνον λέγεται τὸν Μιθριδάτην ὄψιν ἐν ὕπνοις ἰδεῖν τὰ μέλλοντα προδηλοῦσαν. ἐδόκει γὰρ οὐρίῳ πνεύματι πλέων τὸ Ποντικὸν πέλαγος ἤδη Βόσπορον καθορᾶν καὶ φιλοφρονεῖσθαι τοὺς συμπλέοντας, ὡς ἄν τις ἐπὶ σωτηρίᾳ σαφεῖ καὶ βεβαίῳ χαίρων ἄφνω δὲ ἀναφανῆναι πάντων ἔρημος ἐπὶ λεπτοῦ ναυαγίου διαφερόμενος. ἐν τοιούτοις δὲ αὐτὸν ὄντα πάθεσι καὶ φάσμασιν ἐπιστάντες ἀνέστησαν οἱ φίλοι, φράζοντες ἐπιέναι Πομπήϊον.", "st": "Pomp. 32.4"}, {"sp": "N", "t": "ἦν οὖν ἐξ ἀνάγκης μαχητέον ὑπὲρ τοῦ χάρακος, καὶ προαγαγόντες οἱ στρατηγοὶ τὴν δύναμιν ἔταξαν, αἰσθόμενος δὲ τὴν παρασκευὴν αὐτῶν ὁ Πομπήϊος ὤκνει κατὰ σκότος εἰς κίνδυνον ἐλθεῖν, καὶ κύκλῳ μόνον ᾤετο δεῖν περιελαύνειν, ὅπως μὴ φεύγοιεν, ἡμέρας δὲ κρείττους ὄντας ἐπιχειρεῖν. οἱ δὲ πρεσβύτατοι τῶν ταξιαρχῶν δεόμενοι καὶ παρακαλοῦντες ἐξώρμησαν αὐτόν οὐδὲ γὰρ σκότος ἦν παντάπασιν, ἀλλὰ ἡ σελήνη καταφερομένη παρεῖχεν ἔτι τῶν σωμάτων ἱκανὴν ἔποψιν. καὶ τοῦτο μάλιστα τοὺς βασιλικοὺς ἔσφηλεν. ἐπῄεσαν μὲν γὰρ οἱ Ῥωμαῖοι κατὰ νώτου τὴν σελήνην ἔχοντες· πεπιεσμένου δὲ περὶ τὰς δύσεις τοῦ φωτός, αἱ σκιαὶ πολὺ τῶν σωμάτων ἔμπροσθεν προϊοῦσαι τοῖς πολεμίοις ἐπέβαλλον, οὐ δυναμένοις τὸ διάστημα συνιδεῖν ἀκριβῶς ἀλλ’ ὡς ἐν χερσὶν ἤδη γεγονότων τοὺς ὑσσοὺς ἀφέντες μάτην οὐδενὸς ἐφίκοντο. τοῦτο συνιδόντες οἱ Ῥωμαῖοι μετὰ κραυγῆς ἐπέδραμον, καὶ μηκέτι μένειν τολμῶντας, ἀλλ’ ἐκπεπληγμένους καὶ φεύγοντας ἔκτεινον, ὥστε πολὺ πλείονας μυρίων ἀποθανεῖν, ἁλῶναι δὲ τὸ στρατόπεδον.", "st": "Pomp. 32.5"}, {"sp": "N", "t": "αὐτὸς δὲ Μιθριδάτης ἐν ἀρχῇ μὲν ὀκτακοσίοις ἱππεῦσι διέκοψε καὶ διεξήλασε τοὺς Ῥωμαίους, ταχὺ δὲ τῶν ἄλλων σκεδασθέντων ἀπελείφθη μετὰ τριῶν. ἐν οἷς ἦν Ὑψικράτεια παλλακίς, ἀεὶ μὲν ἀνδρώδης τις οὖσα καὶ παράτολμος· Ὑψικράτην γοῦν αὐτὴν ὁ βασιλεὺς ἐκάλει· τότε δὲ ἀνδρὸς ἔχουσα Πέρσου στολὴν καὶ ἵππον οὔτε τῷ σώματι πρὸς τὰ μήκη τῶν δρόμων ἀπηγόρευσεν οὔτε θεραπεύουσα τοῦ βασιλέως τὸ σῶμα καὶ τὸν ἵππον ἐξέκαμεν, ἄχρι ἧκον εἰς χωρίον Σίνωρα χρημάτων καὶ κειμηλίων βασιλικῶν μεστόν. ἐξ οὗ λαβὼν ὁ Μιθριδάτης ἐσθῆτας πολυτελεῖς διένειμε τοῖς συνδεδραμηκόσι πρὸς αὐτὸν ἐκ τῆς φυγῆς, ἔδωκε δὲ καὶ τῶν φίλων ἑκάστῳ φορεῖν θανάσιμον φάρμακον, ὅπως ἄκων μηδεὶς ὑποχείριος γένοιτο τοῖς πολεμίοις. ἐντεῦθεν ὥρμητο μὲν ἐπ’ Ἀρμενίας πρὸς Τιγράνην, ἐκείνου δὲ ἀπαγορεύοντος καὶ τάλαντα ἑκατὸν ἐπικηρύξαντος αὐτῷ, παραμειψάμενος τὰς πηγὰς τοῦ Εὐφράτου διὰ τῆς Κολχίδος ἔφευγε.", "st": "Pomp. 32.8"}, {"sp": "N", "t": "Πομπήϊος δὲ εἰς Ἀρμενίαν ἐνέβαλε τοῦ νέου Τιγράνου καλοῦντος αὐτόν ἤδη γὰρ ἀφειστήκει τοῦ πατρός, καὶ συνήντησε τῷ Πομπηΐῳ περὶ τὸν Ἀράξην ποταμόν, ὃς ἀνίσχει μὲν ἐκ τῶν αὐτῶν τῷ Εὐφράτῃ τόπων, ἀποτρεπόμενος δὲ πρὸς τὰς ἀνατολὰς εἰς τὸ Κάσπιον ἐμβάλλει πέλαγος. οὗτοι μὲν οὖν προῆγον ἅμα τὰς πόλεις παραλαμβάνοντες· ὁ δὲ βασιλεὺς Τιγράνης ἔναγχος μὲν ὑπὸ Λευκόλλου συντετριμμένος, ἥμερον δέ τινα τῷ τρόπῳ καὶ πρᾷον πυθόμενος εἶναι τὸν Πομπήϊον, ἐδέξατο μὲν εἰς τὰ βασίλεια φρουράν, ἀναλαβὼν δὲ τοὺς φίλους καὶ συγγενεῖς αὐτὸς ἐπορεύετο παραδώσων ἑαυτόν. ὡς δὲ ἦλθεν ἱππότης ἐπὶ τὸν χάρακα, ῥαβδοῦχοι δύο τοῦ Πομπηΐου προσελθόντες ἐκέλευσαν ἀποβῆναι τοῦ ἵππου καὶ πεζὸν ἐλθεῖν οὐδένα γὰρ ἀνθρώπων ἐφ’ ἵππου καθεζόμενον ἐν Ῥωμαϊκῷ στρατοπέδῳ πώποτε ὀφθῆναι. καὶ ταῦτα οὖν ὁ Τιγράνης ἐπείθετο καὶ τὸ ξίφος αὐτοῖς ἀπολυσάμενος παρεδίδου· καὶ τέλος, ὡς πρὸς αὐτόν ἦλθε τὸν Πομπήϊον, ἀφελόμενος τὴν κίταριν ὥρμησε πρὸ τῶν ποδῶν θεῖναι, καὶ καταβαλὼν ἑαυτόν, αἴσχιστα δὴ πάντων, προσπεσεῖν αὐτοῦ τοῖς γόνασιν. ἀλλ’ ὁ Πομπήϊος ἔφθη τῆς δεξιᾶς αὐτοῦ λαβόμενος προσαγαγέσθαι καὶ πλησίον ἱδρυσάμενος ἑαυτοῦ, τὸν δὲ υ υἱὸν ἐπὶ θάτερα, τῶν μὲν ἄλλων ἔφησε δεῖν αἰτιᾶσθαι Λεύκολλον, ὑπ’ ἐκείνου γὰρ ἀφῃρῆσθαι Συρίαν, Φοινίκην, Κιλικίαν, Γαλατίαν, Σωφηνήν, ἃ δὲ ἄχρι ἑαυτοῦ διατετήρηκεν, ἕξειν ἐκτίσαντα ποινὴν ἑξακισχίλια τάλαντα Ῥωμαίοις τῆς ἀδικίας, Σωφηνῆς δὲ βασιλεύσειν τὸν υἱόν. ἐπὶ τούτοις ὁ μὲν Τιγράνης ἠγάπησε, καὶ τῶν Ῥωμαίων ἀσπασαμένων αὐτόν βασιλέα περιχαρὴς γενόμενος ἐπηγγείλατο στρατιώτῃ μὲν ἡμιμναῖον ἀργυρίου δώσειν, ἑκατοντάρχῃ δὲ μνᾶς δέκα, χιλιάρχῳ δὲ τάλαντον ὁ δ’ υἱὸς ἐδυσφόρει, καὶ κληθεὶς ἐπὶ δεῖπνον οὐκ ἔφη Πομπηΐου δεῖσθαι τοιαῦτα τιμῶντος· καὶ γὰρ αὐτὸς ἄλλον εὑρήσειν Ῥωμαίων. ἐκ τούτου δεθεὶς εἰς τὸν θρίαμβον ἐφυλάττετο. καὶ μετ’ οὐ πολὺν χρόνον ἔπεμψε Φραάτης ὁ Πάρθος ἀπαιτῶν μὲν τὸν νεανίσκον, ὡς αὐτοῦ γαμβρόν, ἀξιῶν δὲ τῶν ἡγεμονιῶν ὅρῳ χρῆσθαι τῷ Εὐφράτῃ. Πομπήϊος δὲ ἀπεκρίνατο τὸν μὲν Τιγράνην τῷ πατρὶ μᾶλλον ἢ τῷ πενθερῷ προσήκειν, ὅρῳ δὲ χρήσεσθαι τῷ δικαίῳ.", "st": "Pomp. 33.1"}, {"sp": "N", "t": "καταλιπὼν δὲ φρουρὸν Ἀρμενίας Ἀφράνιον αὐτὸς ἐβάδιζε διὰ τῶν περιοικούντων τὸν Καύκασον ἐθνῶν ἀναγκαίως ἐπὶ Μιθριδάτην. μέγιστα δὲ αὐτῶν ἐστιν ἔθνη Ἀλβανοὶ καὶ Ἴβηρες, Ἴβηρες μὲν ἐπὶ τὰ Μοσχικὰ ὄρη καὶ τὸν Πόντον καθήκοντες, Ἀλβανοὶ δὲ ἐπὶ τὴν ἕω καὶ τὴν Κασπίαν κεκλιμένοι θάλασσαν. οὗτοι πρῶτον μὲν αἰτοῦντι Πομπηΐῳ δίοδον ἔδοσαν χειμῶνος δὲ τὴν στρατιὰν ἐν τῇ χώρᾳ καταλαβόντος καὶ τῆς Κρονικῆς ἑορτῆς τοῖς Ῥωμαίοις καθηκούσης, γενόμενοι τετρακισμυρίων οὐκ ἐλάττους ἐπεχείρησαν αὐτοῖς, διαβάντες τὸν Κύρνον ποταμόν, ὃς ἐκ τῶν Ἰβηρικῶν ὀρῶν ἀνιστάμενος καὶ δεχόμενος κατιόντα τὸν Ἀράξην ἀπ’ Ἀρμενίας ἐξίησι δώδεκα στόμασιν εἰς τὸ Κάσπιον. οἱ δὲ οὔ φασι τούτῳ συμφέρεσθαι τὸν Ἀράξην, ἀλλὰ καθ’ ἑαυτόν, ἐγγὺς δὲ ποιεῖσθαι τὴν ἐκβολὴν εἰς ταὐτὸ πέλαγος. Πομπήϊος δέ, καίπερ ἐνστῆναι δυνάμενος πρὸς τὴν διάβασιν τοῖς πολεμίοις, περιεῖδε διαβάντας καθ’ ἡσυχίαν εἶτα ἐπαγαγὼν ἐτρέψατο καὶ διέφθειρε παμπληθεῖς. τῷ δὲ βασιλεῖ δεηθέντι καὶ πέμψαντι πρέσβεις ἀφεὶς τὴν ἀδικίαν καὶ σπεισάμενος, ἐπὶ τοὺς Ἴβηρας ἐβάδιζε, πλήθει μὲν οὐκ ἐλάττονας, μαχιμωτέρους δὲ τῶν ἑτέρων ὄντας, ἰσχυρῶς δὲ βουλομένους τῷ Μιθριδάτῃ χαρίζεσθαι καὶ διωθεῖσθαι τὸν Πομπήϊον. οὔτε γὰρ Μήδοις οὔτε Πέρσαις ὑπήκουσαν Ἴβηρες, διέφυγον δὲ καὶ τὴν Μακεδόνων ἀρχήν, Ἀλεξάνδρου διὰ ταχέων ἐκ τῆς Ὑρκανίας ἀπάραντος. οὐ μὴν ἀλλὰ καὶ τούτους μάχῃ μεγάλῃ τρεψάμενος ὁ Πομπήϊος, ὥστε ἀποθανεῖν μὲν ἐνακισχιλίους, ἁλῶναι δὲ πλείους μυρίων, εἰς τὴν Κολχικὴν ἐνέβαλε καὶ πρὸς τὸν Φᾶσιν αὐτῷ Σερουΐλιος ἀπήντησε, τὰς ναῦς ἔχων αἷς ἐφρούρει τὸν Πόντον.", "st": "Pomp. 34.1"}, {"sp": "N", "t": "ἡ μὲν οὖν Μιθριδάτου δίωξις ἐνδεδυκότος εἰς τὰ περὶ Βόσπορον ἔθνη καὶ τὴν Μαιῶτιν ἀπορίας εἶχε μεγάλας· Ἀλβανοὶ δὲ αὖθις ἀφεστῶτες αὐτῷ προσηγγέλθησαν. πρὸς οὓς ὑπ’ ὀργῆς καὶ φιλονεικίας ἐπιστρέψας τόν τε Κύρνον μόλις καὶ παραβόλως πάλιν διεπέρασεν ἐπὶ πολὺ σταυροῖς ὑπὸ τῶν βαρβάρων ἀποκεχαρακωμένον, καὶ μακρᾶς αὐτὸν ἐκδεχομένης ἀνύδρου καὶ ἀργαλέας ὁδοῦ, μυρίους ἀσκοὺς ὕδατος ἐμπλησάμενος ἤλαυνεν ἐπὶ τοὺς πολεμίους, καὶ κατέλαβε πρὸς Ἄβαντι ποταμῷ παρατεταγμένους ἑξακισμυρίους πεζοὺς καὶ δισχιλίους ἱππεῖς ἐπὶ μυρίοις, ὡπλισμένους δὲ φαύλως καὶ δέρμασι θηρίων τοὺς πολλούς, ἡγεῖτο δὲ αὐτῶν βασιλέως ἀδελφὸς ὄνομα Κῶσις. οὗτος ἐν χερσὶ τῆς μάχης γενομένης ἐπὶ τόν Πομπήϊον ὁρμήσας αὐτὸν ἔβαλεν ἐπὶ τὴν τοῦ θώρακος ἐπιπτυχὴν ἀκοντίσματι, Πομπήϊος δὲ ἐκεῖνον ἐκ χειρὸς διελάσας ἀνεῖλεν.", "st": "Pomp. 35.1"}, {"sp": "N", "t": "ἐν ταύτῃ τῇ μάχῃ λέγονται καὶ Ἀμαζόνες συναγωνίσασθαι τοῖς βαρβάροις, ἀπὸ τῶν περὶ τόν Θερμώδοντα ποταμὸν ὀρῶν καταβᾶσαι. μετὰ γὰρ τὴν μάχην σκυλεύοντες οἱ Ῥωμαῖοι τοὺς βαρβάρους πέλταις Ἀμαζονικαῖς καὶ κοθόρνοις ἐνετύγχανον, σῶμα δὲ οὐδὲν ὤφθη γυναικεῖον. νέμονται δὲ τοῦ Καυκάσου τὰ καθήκοντα πρὸς τὴν Ὑρκανίαν θάλασσαν, οὐχ ὁμοροῦσαι τοῖς Ἀλβανοῖς, ἀλλὰ Γέλαι καὶ Λῆγες οἰκοῦσι διὰ μέσου· καὶ τούτοις ἔτους ἑκάστου δύο μῆνας εἰς ταὐτὸ φοιτῶσαι περὶ τόν Θερμώδοντα ποταμὸν ὁμιλοῦσιν, εἶτα καθ’ αὑτὰς ἀπαλλαγεῖσαι βιοτεύουσιν.", "st": "Pomp. 35.4"}, {"sp": "N", "t": "ὁρμήσας δὲ μετὰ τὴν μάχην ὁ Πομπήϊος ἐλαύνειν ἐπὶ τὴν Ὑρκανίαν καὶ Κασπίαν θάλασσαν, ὑπὸ πλήθους ἑρπετῶν θανασίμων ἀπετράπη τριῶν ὁδὸν ἡμερῶν ἀποσχών, εἰς δὲ τὴν μικρὰν Ἀρμενίαν ἀνεχώρησε. καὶ τῷ μὲν Ἐλυμαίων καὶ Μήδων βασιλεῖ πέμψασι πρέσβεις ἀντέγραψε φιλικῶς, τὸν δὲ Πάρθον, εἰς τὴν Γορδυηνὴν ἐμβεβληκότα καὶ περικόπτοντα τοὺς ὑπὸ Τιγράνῃ, πέμψας μετὰ Ἀφρανίου δύναμιν ἐξήλασε διωχθέντα μέχρι τῆς Ἀρβηλίτιδος.", "st": "Pomp. 36.1"}, {"sp": "N", "t": "ὅσαι δὲ τῶν Μιθριδάτου παλλακίδων ἀνήχθησαν, οὐδεμίαν ἔγνω, πάσας δὲ τοῖς γονεῦσι καὶ οἰκείοις ἀνέπεμπεν. ἦσαν γὰρ αἱ πολλαὶ θυγατέρες καὶ γυναῖκες στρατηγῶν καὶ δυναστῶν. Στρατονίκη δέ, ἣ μέγιστον εἶχεν ἀξίωμα καὶ τὸ πολυχρυσότατον τῶν φρουρίων ἐφύλαττεν, ἦν μέν, ὡς ἔοικε, ψάλτου τινὸς οὐχ εὐτυχοῦς τἆλλα, πρεσβύτου δὲ θυγάτηρ, οὕτω δὲ εὐθὺς εἷλε παρὰ πότον ψήλασα τὸν Μιθριδάτην, ὥστε ἐκείνην μὲν ἔχων ἀνεπαύετο, τὸν δὲ πρεσβύτην ἀπέπεμψε δυσφοροῦντα τῷ μηδὲ προσρήσεως τυχεῖν ἐπιεικοῦς. ὡς μέντοι περὶ ὄρθρον ἐγερθεὶς εἶδεν ἔνδον ἐκπωμάτων μὲν ἀργυρῶν καὶ χρυσῶν τραπέζας, ὄχλον δὲ θεραπείας πολύν, εὐνούχους δὲ καὶ παῖδας ἱμάτια τῶν πολυτελῶν προσφέροντας αὐτῷ, καὶ πρὸ τῆς θύρας ἵππον ἑστῶτα κεκοσμημένον ὥσπερ οἱ τῶν φίλων τοῦ βασιλέως, χλευασμὸν εἶναι τὸ χρῆμα καὶ παιδιὰν ἡγούμενος ὥρμησε φεύγειν διὰ θυρῶν. τῶν δὲ θεραπόντων ἀντιλαμβανομένων, καὶ λεγόντων ὅτι πλουσίου τεθνηκότος ἔναγχος οἶκον αὐτῷ μέγαν ὁ βασιλεὺς δεδώρηται, καὶ ταῦτα μικραί τινες ἀπαρχαὶ καὶ δείγματα τῶν ἄλλων χρημάτων καὶ κτημάτων εἰσίν, οὕτω πιστεύσας μόλις καὶ τὴν πορφύραν ἀναλαβὼν καὶ ἀναπηδήσας ἐπὶ τὸν ἵππον ἤλαυνε διὰ τῆς πόλεως βοῶν· ἐμὰ ταῦτα πάντα ἐστί. πρὸς δὲ τοὺς καταγελῶντας οὐ τοῦτο ἔλεγεν εἶναι θαυμαστόν, ἀλλ’ ὅτι μὴ λίθοις βάλλει τοὺς ἀπαντῶντας ὑφ’ ἡδονῆς μαινόμενος, ταύτης μὲν ἦν καὶ γενεᾶς καὶ αἵματος ἡ Στρατονίκη. τῷ δὲ Πομπηΐῳ καὶ τὸ χωρίον παρεδίδου τοῦτο καὶ δῶρα πολλὰ προσήνεγκεν, ὧν ἐκεῖνος ὅσα κόσμον ἱεροῖς καὶ λαμπρότητα τῷ θριάμβῳ παρέξειν ἐφαίνετο λαβὼν μόνα, τὰ λοιπὰ τὴν Στρατονίκην ἐκέλευε κεκτῆσθαι χαίρουσαν. ὁμοίως δὲ καὶ τοῦ βασιλέως τῶν Ἰβήρων κλίνην τε καὶ τράπεζαν καὶ θρόνον, ἅπαντα χρυσᾶ, πέμψαντος αὐτῷ καὶ δεηθέντος λαβεῖν, καὶ ταῦτα τοῖς ταμίαις παρέδωκεν εἰς τὸ δημόσιον.", "st": "Pomp. 36.3"}, {"sp": "N", "t": "ἐν δὲ τῷ Καινῷ φρουρίῳ καὶ γράμμασιν ἀπορρήτοις ὁ Πομπήϊος ἐνέτυχε τοῦ Μιθριδάτου, καὶ διῆλθεν οὐκ ἀηδῶς αὐτὰ πολλὴν ἔχοντα τοῦ ἤθους κατανόησιν. ὑπομνήματα γὰρ ἦν, ἐξ ὧν ἐφωράθη φαρμάκοις ἄλλους τε πολλοὺς καὶ τὸν υἱὸν Ἀριαράθην ἀνῃρηκὼς καὶ τὸν Σαρδιανὸν Ἀλκαῖον, ὅτι παρευδοκίμησεν αὐτὸν ἵππους ἀγωνιστὰς ἐλαύνων. ἦσαν δὲ ἀναγεγραμμέναι καὶ κρίσεις ἐνυπνίων, ὧν τὰ μὲν αὐτὸς ἑωράκει, τὰ δὲ ἔνιαι τῶν γυναικῶν, ἐπιστολαί τε Μονίμης πρὸς αὐτὸν ἀκόλαστοι καὶ πάλιν ἐκείνου πρὸς αὐτήν. Θεοφάνης δὲ καὶ Ῥουτιλίου λόγον εὑρεθῆναί φησι παροξυντικὸν ἐπὶ τὴν ἀναίρεσιν τῶν ἐν Ἀσίᾳ Ῥωμαίων. ὃ καλῶς εἰκάζουσιν οἱ πλεῖστοι κακοήθευμα τοῦ Θεοφάνους εἶναι, τάχα μὲν οὐδὲν αὐτῷ τὸν Ῥουτίλιον ἐοικότα μισοῦντος, εἰκὸς δὲ καὶ διὰ Πομπήϊον, οὗ τὸν πατέρα παμπόνηρον ἀπέδειξεν ὁ Ῥουτίλιος ἐν ταῖς ἱστορίαις.", "st": "Pomp. 37.1"}, {"sp": "N", "t": "ἐντεῦθεν εἰς Ἀμισὸν ἐλθὼν ὁ Πομπήϊος πάθος νεμεσητὸν ὑπὸ φιλοτιμίας ἔπαθε. πολλὰ γὰρ τὸν Λεύκολλον ἐπικερτομήσας, ὅτι τοῦ πολεμίου ζῶντος ἔγραφε διατάξεις καὶ δωρεὰς ἔνεμε καὶ τιμάς, ἃ συνῃρημένου πολέμου καὶ πέρας ἔχοντος εἰώθασι ποιεῖν οἱ νενικηκότες, αὐτὸς ἐν Βοσπόρῳ Μιθριδάτου κρατοῦντος καὶ συνειλοχότος ἀξιόμαχον δύναμιν, ὡς δὴ συντετελεσμένων ἁπάντων, ἔπραττε ταὐτά, διακοσμῶν τὰς ἐπαρχίας καὶ διανέμων δωρεάς, πολλῶν μὲν ἡγεμόνων καὶ δυναστῶν, βασιλέων δὲ δώδεκα βαρβάρων ἀφιγμένων πρὸς αὐτόν, ὅθεν οὐδὲ ἠξίωσε τὸν Πάρθον ἀντιγράφων, ὥσπερ οἱ λοιποί, βασιλέα βασιλέων προσαγορεῦσαι, τοῖς ἄλλοις χαριζόμενος. αὐτὸν δέ τις ἔρως καὶ ζῆλος εἶχε Συρίαν ἀναλαβεῖν καὶ διὰ τῆς Ἀραβίας ἐπὶ τὴν ἐρυθρὰν ἐλάσαι θάλασσαν, ὡς τῷ περιϊόντι τὴν οἰκουμένην πανταχόθεν Ὠκεανῷ προσμίξειε νικῶν· καὶ γὰρ ἐν Λιβύῃ πρῶτος ἄχρι τῆς ἐκτὸς θαλάσσης κρατῶν προῆλθε, καὶ τὴν ἐν Ἰβηρίᾳ, πάλιν ἀρχὴν ὡρίσατο Ῥωμαίοις τῷ Ἀτλαντικῷ πελάγει, καὶ τρίτον ἔναγχος Ἀλβανοὺς διώκων ὀλίγον ἐδέησεν ἐμβαλεῖν εἰς τὴν Ὑρκανίαν θάλασσαν, ὡς οὖν συνάψων τῇ ἐρυθρᾷ τὴν περίοδον τῆς στρατείας ἀνίστατο. καὶ γὰρ ἄλλως τὸν Μιθριδάτην ἑώρα δυσθήρατον ὄντα τοῖς ὅπλοις καὶ φεύγοντα χαλεπώτερον ἢ μαχόμενον.", "st": "Pomp. 38.1"}, {"sp": "N", "t": "διὸ τούτῳ μὲν εἰπὼν ἰσχυρότερον ἑαυτοῦ πολέμιον τὸν λιμὸν ἀπολείψειν, ἐπέστησε φυλακὰς τῶν νεῶν ἐπὶ τοὺς πλέοντας εἰς Βόσπορον ἐμπόρους· καὶ θάνατος ἦν ἡ ζημία τοῖς ἁλισκομένοις. ἀναλαβὼν δὲ τῆς στρατιᾶς τὴν πληθὺν συχνὴν προῆγε· καὶ τῶν μετὰ Τριαρίου πρὸς Μιθριδάτην ἀτυχῶς ἀγωνισαμένων καὶ πεσόντων ἐντυχὼν ἀτάφοις ἔτι τοῖς νεκροῖς, ἔθαψε λαμπρῶς καὶ φιλοτίμως ἅπαντας, ὃ δοκεῖ παραλειφθὲν οὐχ ἥκιστα Λευκόλλῳ μίσους αἴτιον γενέσθαι. χειρωσάμενος δὲ δι’ Ἀφρανίου τοὺς περὶ Ἀμανὸν Ἄραβας καὶ καταβὰς αὐτὸς εἰς Συρίαν, ταύτην μὲν ὡς οὐκ ἔχουσαν γνησίους βασιλεῖς ἐπαρχίαν ἀπέφηνε καὶ κτῆμα τοῦ δήμου Ῥωμαίων, τὴν δὲ Ἰουδαίαν κατεστρέψατο, καὶ συνέλαβεν Ἀριστόβουλον τὸν βασιλέα. πόλεις δὲ τὰς μὲν ἔκτιζε, τὰς δὲ ἠλευθέρου κολάζων τοὺς ἐν αὐταῖς τυράννους. τὴν δὲ πλείστην διατριβὴν ἐν τῷ δικάζειν ἐποιεῖτο, πόλεων καὶ βασιλέων ἀμφισβητήματα διαιτῶν, ἐφ’ ἃ δὲ αὐτὸς οὐκ ἐξικνεῖτο, πέμπων τοὺς φίλους, ὥσπερ Ἀρμενίοις καὶ Πάρθοις περὶ ἧς διεφέροντο χώρας τὴν κρίσιν ποιησαμένοις ἐπ’ αὐτῷ τρεῖς ἀπέστειλε κριτὰς καὶ διαλλακτάς. μέγα μὲν γὰρ ἦν ὄνομα τῆς δυνάμεως, οὐκ ἔλαττον δὲ τῆς ἀρετῆς καὶ πρᾳότητος· ᾧ καὶ τὰ πλεῖστα τῶν περὶ αὐτὸν ἁμαρτήματα φίλων καὶ συνήθων ἀπέκρυπτε, κωλύειν μὲν ἢ κολάζειν τοὺς πονηρευομένους οὐ πεφυκώς, αὑτὸν δὲ παρέχων τοῖς ἐντυγχάνουσι τοιοῦτον ὥστε καὶ τὰς ἐκείνων πλεονεξίας καὶ βαρύτητας εὐκόλως ὑπομένειν.", "st": "Pomp. 39.1"}, {"sp": "N", "t": "ὁ δὲ μέγιστον δυνάμενος παρ’ αὐτῷ Δημήτριος ἦν ἀπελεύθερος, οὐκ ἄφρων εἰς τἆλλα νεανίας, ἄγαν δὲ τῇ τύχῃ χρώμενος· περὶ οὗ καὶ τοιόνδε τι λέγεται, Κάτων ὁ φιλόσοφος ἔτι μὲν ὢν νέος, ἤδη δὲ μεγάλην ἔχων δόξαν καὶ μέγα φρονῶν, ἀνέβαινεν εἰς Ἀντιόχειαν, οὐκ ὄντος αὐτόθι Πομπηΐου, βουλόμενος ἱστορῆσαι τὴν πόλιν. αὐτὸς μὲν οὖν, ὥσπερ ἀεί, πεζὸς ἐβάδιζεν, οἱ δὲ φίλοι συνώδευον ἵπποις χρώμενοι. κατιδὼν δὲ πρὸ τῆς πύλης ὄχλον ἀνδρῶν ἐν ἐσθῆσι λευκαῖς καὶ παρὰ τὴν ὁδὸν ἔνθεν μὲν τοὺς ἐφήβους, ἔνθεν δὲ τοὺς παῖδας διακεκριμένους, ἐδυσχέραινεν οἰόμενος εἰς τιμήν τινα καὶ θεραπείαν ἑαυτοῦ μηδὲν δεομένου ταῦτα γίνεσθαι. τοὺς μέντοι φίλους ἐκέλευσε καταβῆναι καὶ πορεύεσθαι μετ’ αὐτοῦ· γενομένοις δὲ πλησίον ὁ πάντα διακοσμῶν ἐκεῖνα καὶ καθιστὰς ἔχων στέφανον καὶ ῥάβδον ἀπήντησε, πυνθανόμενος παρ’ αὐτῶν ποῦ Δημήτριον ἀπολελοίπασι καὶ πότε ἀφίξεται. τοὺς μὲν οὖν φίλους τοῦ Κάτωνος γέλως ἔλαβεν, ὁ δὲ Κάτων εἰπών, ὢ τῆς ἀθλίας πόλεως, παρῆλθεν, οὐδὲν ἕτερον ἀποκρινάμενος.", "st": "Pomp. 40.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ τοῖς ἄλλοις τοῦτον τὸν Δημήτριον ἧττον ἐπίφθονον ἐποίει αὐτὸς ὁ Πομπήϊος ἐντρυφώμενος ὑπ’ αὐτοῦ καὶ μὴ δυσκολαίνων. λέγεται γάρ, ὅτι πολλάκις ἐν ταῖς ὑποδοχαῖς τοῦ Πομπηΐου προσμένοντος καὶ δεχομένου τοὺς ἄλλους ἐκεῖνος ἤδη κατέκειτο σοβαρός, ἔχων δι’ ὤτων κατὰ τῆς κεφαλῆς τὸ ἱμάτιον. οὔπω δὲ εἰς Ἰταλίαν ἐπανεληλυθὼς ἐκέκτητο τῆς Ῥώμης τὰ ἥδιστα προάστεια καὶ τῶν ἡβητηρίων τὰ κάλλιστα, καὶ κῆποι πολυτελεῖς ἦσαν ὀνομαζόμενοι Δημητρίου· καίτοι Πομπήϊος αὐτὸς ἄχρι τοῦ τρίτου θριάμβου μετρίως καὶ ἀφελῶς ᾤκησεν. ὕστερον δὲ Ῥωμαίοις τοῦτο δὴ τὸ καλὸν καὶ περιβόητον ἀνιστὰς θέατρον, ὥσπερ ἐφόλκιόν τι, παρετεκτήνατο λαμπροτέραν οἰκίαν ἐκείνης, ἀνεπίφθονον δὲ καὶ ταύτην, ὥστε τὸν γενόμενον δεσπότην αὐτῆς μετὰ Πομπήϊον εἰσελθόντα θαυμάζειν καὶ πυνθάνεσθαι ποῦ Πομπήϊος Μάγνος ἐδείπνει. ταῦτα μὲν οὖν οὕτω λέγεται.", "st": "Pomp. 40.4"}, {"sp": "N", "t": "τοῦ δὲ βασιλέως τῶν περὶ τὴν Πέτραν Ἀράβων πρότερον μὲν ἐν οὐδενὶ λόγῳ τὰ Ῥωμαίων τιθεμένου, τότε δὲ δείσαντος ἰσχυρῶς καὶ γράψαντος ὅτι πάντα πείθεσθαι καὶ ποιεῖν ἔγνωκεν, ἐκβεβαιώσασθαι βουλόμενος αὐτοῦ τὴν διάνοιαν ὁ Πομπήϊος ἐστράτευσεν ἐπὶ τὴν Πέτραν οὐ πάνυ τι τοῖς πολλοῖς ἄμεμπτον στρατείαν. ἀπόδρασιν γὰρ ᾤοντο τῆς Μιθριδάτου διώξεως εἶναι, καὶ πρὸς ἐκεῖνον ἠξίουν τρέπεσθαι τὸν ἀρχαῖον ἀνταγωνιστήν, αὖθις ἀναζωπυροῦντα καὶ παρασκευαζόμενον, ὡς ἀπηγγέλλετο, διὰ Σκυθῶν καὶ Παιόνων στρατὸν ἐλαύνειν ἐπὶ τὴν Ἰταλίαν, ὁ δὲ ῥᾷον οἰόμενος αὐτοῦ καταλύσειν τὴν δύναμιν πολεμοῦντος ἢ τὸ σῶμα λήψεσθαι φεύγοντος, οὐκ ἐβούλετο τρίβεσθαι μάτην περὶ τὴν δίωξιν, ἑτέρας δὲ τοῦ πολέμου παρενθήκας ἐποιεῖτο καὶ τὸν χρόνον εἷλκεν.", "st": "Pomp. 41.1"}, {"sp": "N", "t": "ἡ δὲ τύχη τὴν ἀπορίαν ἔλυσεν. οὐκέτι γὰρ αὐτοῦ τῆς Πέτρας πολλὴν ὁδὸν ἀπέχοντος, ἤδη δὲ τῆς ἡμέρας ἐκείνης βεβλημένου χάρακα καὶ γυμνάζοντος ἑαυτὸν ἵππῳ παρὰ τὸ στρατόπεδον, γραμματηφόροι προσήλαυνον ἐκ Πόντου κομίζοντες εὐαγγέλια. δῆλοι δ’ εὐθύς εἰσι ταῖς αἰχμαῖς τῶν δοράτων· δάφναις γὰρ ἀναστέφονται. τούτους ἰδόντες οἱ στρατιῶται συνετρόχαζον πρὸς τὸν Πομπήϊον. ὁ δὲ πρῶτον μὲν ἐβούλετο τὰ γυμνάσια συντελεῖν, βοώντων δὲ καὶ δεομένων καταπηδήσας ἀπὸ τοῦ ἵππου καὶ λαβὼν τὰ γράμματα προῄει. βήματος δὲ οὐκ ὄντος οὐδὲ τοῦ στρατιωτικοῦ γενέσθαι φθάσαντος (ὃ ποιοῦσιν αὐτοὶ τῆς γῆς ἐκτομὰς βαθείας λαμβάνοντες καὶ κατ’ ἀλλήλων συντιθέντες), ὑπὸ τῆς τότε σπουδῆς καὶ προθυμίας τὰ σάγματα τῶν ὑποζυγίων συμφορήσαντες ὕψος ἐξῆραν· ἐπὶ τοῦτο προβὰς ὁ Πομπήϊος ἀπήγγειλεν αὐτοῖς ὅτι Μιθριδάτης τέθνηκε στασιάσαντος Φαρνάκου τοῦ υἱοῦ διαχρησάμενος αὑτόν, τὰ δὲ ἐκεῖ πάντα πράγματα Φαρνάκης κατεκληρώσατο, καὶ ἑαυτῷ καὶ Ῥωμαίοις γέγραφε ποιούμενος.", "st": "Pomp. 41.3"}, {"sp": "N", "t": "ἐκ τούτου τὸ μὲν στράτευμα τῇ χαρᾷ χρώμενον, ὡς εἰκός, ἐν θυσίαις καὶ συνουσίαις διῆγεν, ὡς ἐν τῷ Μιθριδάτου σώματι μυρίων τεθνηκότων πολεμίων. Πομπήϊος δὲ ταῖς πράξεσιν αὐτοῦ καὶ ταῖς στρατείαις κεφαλὴν ἐπιτεθεικὼς οὐ πάνυ ῥᾳδίως οὕτω προσδοκηθεῖσαν, εὐθὺς ἀνέζευξεν ἐκ τῆς Ἀραβίας· καὶ ταχὺ τὰς ἐν μέσῳ διεξελθὼν ἐπαρχίας εἰς Ἀμισὸν ἀφίκετο, καὶ κατέλαβε πολλὰ μὲν δῶρα παρὰ Φαρνάκου κεκομισμένα, πολλὰ δὲ σώματα τῶν βασιλικῶν, αὐτὸν δὲ τὸν Μιθριδάτου νεκρὸν οὐ πάνυ γνώριμον ἀπὸ τοῦ προσώπου τὸν γὰρ ἐγκέφαλον ἔλαθεν ἐκτῆξαι τοὺς θεραπεύοντας· ἀλλὰ ταῖς οὐλαῖς ἐπεγίγνωσκον οἱ δεόμενοι τοῦ θεάματος. οὐ γὰρ αὐτὸς Πομπήϊος ἰδεῖν ὑπέμεινεν, ἀλλ’ ἀφοσιωσάμενος τὸ νεμεσητὸν εἰς Σινώπην ἀπέπεμψε, τῆς δ’ ἐσθῆτος, ἣν ἐφόρει, καὶ τῶν ὅπλων τὸ μέγεθος καὶ τήν λαμπρότητα ἐθαύμασε· καίτοι τὸν μὲν ξιφιστῆρα πεποιημένον ἀπὸ τετρακοσίων ταλάντων Πόπλιος κλέψας ἐπώλησεν Ἀριαράθῃ, τὴν δὲ κίταριν Γάϊος ὁ τοῦ Μιθριδάτου σύντροφος ἔδωκε κρύφα δεηθέντι Φαύστῳ τῷ Σύλλα παιδί, θαυμαστῆς οὖσαν ἐργασίας, ὃ τότε τὸν Πομπήϊον διέλαθε. Φαρνάκης δὲ γνοὺς ὕστερον ἐτιμωρήσατο τοὺς ὑφελομένους.", "st": "Pomp. 42.1"}, {"sp": "N", "t": "διοικήσας δὲ τὰ ἐκεῖ καὶ καταστησάμενος οὕτως ἤδη πανηγυρικώτερον ἐχρῆτο τῇ πορείᾳ, καὶ γὰρ εἰς Μιτυλήνην ἀφικόμενος τήν τε πόλιν ἠλευθέρωσε διὰ Θεοφάνη, καὶ τὸν ἀγῶνα τὸν πάτριον ἐθεάσατο τῶν ποιητῶν, ὑπόθεσιν μίαν ἔχοντα τὰς ἐκείνου πράξεις, ἡσθεὶς δὲ τῷ θεάτρῳ περιεγράψατο τὸ εἶδος αὐτοῦ καὶ τὸν τύπον, ὡς ὅμοιον ἀπεργασόμενος τὸ ἐν Ῥώμῃ, μεῖζον δὲ καὶ σεμνότερον. ἐν δὲ Ῥόδῳ γενόμενος πάντων μὲν ἠκροάσατο τῶν σοφιστῶν, καὶ δωρεὰν ἑκάστῳ τάλαντον ἔδωκε· Ποσειδώνιος δὲ καὶ τήν ἀκρόασιν ἀνέγραψεν ἣν ἔσχεν ἐπ’ αὐτοῦ πρὸς Ἑρμαγόραν τὸν ῥήτορα περὶ τῆς καθόλου ζητήσεως ἀντιταξάμενος. ἐν δὲ Ἀθήναις τὰ μὲν πρὸς τοὺς φιλοσόφους ὅμοια τοῦ Πομπηΐου· τῇ πόλει δὲ ἐπιδοὺς εἰς ἐπισκευὴν πεντήκοντα τάλαντα λαμπρότατος ἀνθρώπων ἤλπιζεν ἐπιβήσεσθαι τῆς Ἰταλίας καὶ ποθῶν ὀφθήσεσθαι τοῖς οἴκοι ποθοῦσιν. ᾧ δ’ ἄρα πρὸς τὰ λαμπρὰ καὶ μεγάλα τῶν ἀπὸ τῆς τύχης ἀγαθῶν ἀεί τινα κεραννύναι κακοῦ μοῖραν ἐπιμελές ἐστι δαιμονίῳ, τοῦτο ὑποικούρει πάλαι παρασκευάζον αὐτῷ λυπηροτέραν τήν ἐπάνοδον. ἐξύβρισε γὰρ ἡ Μουκία παρὰ τήν ἀποδημίαν αὐτοῦ, καὶ πόρρω μὲν ὢν ὁ Πομπήϊος κατεφρόνει τοῦ λόγου· πλησίον δὲ Ἰταλίας γενόμενος καὶ σχολάζοντι τῷ λογισμῷ μᾶλλον, ὡς ἔοικε, τῆς αἰτίας ἁψάμενος, ἔπεμψεν αὐτῇ τήν ἄφεσιν, οὔτε τότε γράψας οὔθ’ ὕστερον ἐφ’ οἷς ἀφῆκεν ἐξειπών ἐν δ’ ἐπιστολαῖς Κικέρωνος ἡ αἰτία γέγραπται.", "st": "Pomp. 42.4"}, {"sp": "N", "t": "λόγοι δὲ παντοδαποὶ περὶ τοῦ Πομπηΐου προκατέπιπτον εἰς τὴν Ῥώμην, καὶ θόρυβος ἦν πολύς, ὡς εὐθὺς ἄξοντος ἐπὶ τὴν πόλιν τὸ στράτευμα καὶ μοναρχίας βεβαίας ἐσομένης. Κράσσος δὲ τοὺς παῖδας καὶ τὰ χρήματα λαβὼν ὑπεξῆλθεν, εἴτε δείσας ἀληθῶς, εἴτε μᾶλλον, ὡς ἐδόκει, πίστιν ἀπολείπων τῇ διαβολῇ καὶ τὸν φθόνον ποιῶν τραχύτερον. εὐθὺς οὖν ἐπιβὰς Ἰταλίας ὁ Πομπήϊος καὶ συναγαγὼν εἰς ἐκκλησίαν τοὺς στρατιώτας καὶ τὰ πρέποντα διαλεχθεὶς καὶ φιλοφρονησάμενος, ἐκέλευσε διαλύεσθαι κατὰ πόλιν ἑκάστους καὶ τρέπεσθαι πρὸς τὰ οἰκεῖα, μεμνημένους αὖθις ἐπὶ τὸν θρίαμβον αὐτῷ συνελθεῖν. οὕτω δὲ τῆς στρατιᾶς σκεδασθείσης καὶ πυνθανομένων ἁπάντων πρᾶγμα συνέβη θαυμαστόν. ὁρῶσαι γὰρ αἱ πόλεις Πομπήϊον Μάγνον ἄνοπλον καὶ μετ’ ὀλίγων τῶν συνήθων ὥσπερ ἐξ ἄλλης ἀποδημίας διαπορευόμενον, ἐκχεόμεναι δι’ εὔνοιαν καὶ προπέμπουσαι μετὰ μείζονος δυνάμεως συγκατῆγον εἰς τὴν Ῥώμην, εἴ τι κινεῖν διενοεῖτο καὶ νεωτερίζειν τότε, μηδὲν ἐκείνου δεόμενον τοῦ στρατεύματος.", "st": "Pomp. 43.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ὁ νόμος οὐκ εἴα πρὸ τοῦ θριάμβου παρελθεῖν εἰς τὴν πόλιν, ἔπεμψεν ἀξιῶν εἰς τὴν βουλὴν ἀναβαλέσθαι τὰς τῶν ὑπάτων ἀρχαιρεσίας, καὶ δοῦναι ταύτην αὐτῷ τὴν χάριν ὅπως παρὼν Πείσωνι συναρχαιρεσιάσῃ. Κάτωνος δὲ πρὸς τὴν ἀξίωσιν ἐνστάντος οὐκ ἔτυχε τοῦ βουλεύματος, θαυμάσας δὲ τὴν παρρησίαν αὐτοῦ καὶ τὸν τόνον ᾧ μόνος ἐχρῆτο φανερῶς ὑπὲρ τῶν δικαίων, ἐπεθύμησεν ἁμῶς γέ πως κτήσασθαι τὸν ἄνδρα· καὶ δυεῖν οὐσῶν ἀδελφιδῶν τῷ Κάτωνι τὴν μὲν αὐτὸς ἐβούλετο λαβεῖν γυναῖκα, τὴν δὲ τῷ παιδὶ συνοικίσαι. τοῦ δὲ Κάτωνος ὑπιδομένου τὴν πεῖραν, ὡς διαφθορὰν οὖσαν αὐτοῦ τρόπον τινὰ δεκαζομένου διὰ τῆς οἰκειότητος, ἥ τε ἀδελφὴ καὶ ἡ γυνὴ χαλεπῶς ἔφερον εἰ Πομπήϊον Μάγνον ἀποτρίψεται κηδεστήν. ἐν τούτῳ δὲ βουλόμενος ὕπατον ἀποδεῖξαι Πομπήϊος Ἀφράνιον ἀργύριον εἰς τὰς φυλὰς ἀνήλισκεν ὑπὲρ αὐτοῦ, καὶ τοῦτο κατιόντες εἰς τοὺς Πομπηΐου κήπους ἐλάμβανον, ὥστε τὸ πρᾶγμα περιβόητον εἶναι καὶ τὸν Πομπήϊον ἀκούειν κακῶς, ἧς αὐτὸς ἀρχῆς ἐφ’ οἷς κατώρθωσεν ὡς μεγίστης ἔτυχε, ταύτην ὤνιον ποιοῦντα τοῖς δι’ ἀρετῆς κτήσασθαι μὴ δυναμένοις. τούτων μέντοι, πρὸς τὰς γυναῖκας ὁ Κάτων ἔφησε, τῶν ὀνειδῶν κοινωνητέον οἰκείοις Πομπηΐου γενομένοις. αἱ δὲ ἀκούσασαι συνέγνωσαν βέλτιον αὐτῶν ἐκεῖνον λογίζεσθαι περὶ τοῦ πρέποντος.", "st": "Pomp. 44.1"}, {"sp": "N", "t": "τοῦ δὲ θριάμβου τῷ μεγέθει, καίπερ εἰς ἡμέρας δύο μερισθέντος, ὁ χρόνος οὐκ ἐξήρκεσεν, ἀλλὰ τῶν παρεσκευασμένων πολλὰ τῆς θέας ἐξέπεσεν, ἑτέρας ἀποχρῶντα πομπῆς ἀξίωμα καὶ κόσμος εἶναι, γράμμασι δὲ προηγουμένοις ἐδηλοῦτο τὰ γένη καθ’ ὧν ἐθριάμβευεν. ἦν δὲ τάδε· πόντος, Ἀρμενία, Καππαδοκία, Παφλαγονία, Μηδία, Κολχίς, Ἴβηρες, Ἀλβανοί, Συρία, Κιλικία, Μεσοποταμία, τὰ περὶ Φοινίκην καὶ Παλαιστίνην. Ἰουδαία, Ἀραβία, τὸ πειρατικὸν ἅπαν ἐν γῇ καὶ θαλάσσῃ καταπεπολεμημένον. ἐν δὲ τούτοις φρούρια μὲν ἡλωκότα χιλίων οὐκ ἐλάττονα, πόλεις δὲ οὐ πολὺ τῶν ἐνακοσίων ἀποδέουσαι, πειρατικαὶ δὲ νῆες ὀκτακόσιαι, κατοικίαι δὲ πόλεων μιᾶς δέουσαι τετταράκοντα. πρὸς δὲ τούτοις ἔφραζε διὰ τῶν γραμμάτων ὅτι πεντακισχίλιαι μὲν μυριάδες ἐκ τῶν τελῶν ὑπῆρχον, ἐκ δὲ ὧν αὐτὸς προσεκτήσατο τῇ πόλει μυριάδας ὀκτακισχιλίας πεντακοσίας λαμβάνουσιν, ἀναφέρεται δὲ εἰς τὸ δημόσιον ταμιεῖον ἐν νομίσματι καὶ κατασκευαῖς ἀργυρίου καὶ χρυσίου δισμύρια τάλαντα, πάρεξ τῶν εἰς τοὺς στρατιώτας δεδομένων, ὧν ὁ τοὐλάχιστον αἴρων κατὰ λόγον δραχμὰς εἴληφε χιλίας πεντακοσίας. αἰχμάλωτοι δ’ ἐπομπεύθησαν, ἄνευ τῶν ἀρχιπειρατῶν, υἱὸς Τιγράνου τοῦ Ἀρμενίου μετὰ γυναικὸς καὶ θυγατρός, αὐτοῦ τε Τιγράνου τοῦ βασιλέως γυνὴ Ζωσίμη, καὶ βασιλεὺς Ἰουδαίων Ἀριστόβουλος, Μιθριδάτου δὲ ἀδελφὴ καὶ πέντε τέκνα, καὶ Σκυθίδες γυναῖκες, Ἀλβανῶν δὲ καὶ Ἰβήρων ὅμηροι καὶ τοῦ Κομμαγηνῶν βασιλέως, καὶ τρόπαια πάμπολλα καὶ ταῖς μάχαις ἰσάριθμα πάσαις ἃς ἢ αὐτὸς ἢ διὰ τῶν στρατηγῶν ἐνίκησε. μέγιστον δὲ ὑπῆρχε πρὸς δόξαν καὶ μηδενὶ τῶν πώποτε Ῥωμαίων γεγονός, ὅτι τὸν τρίτον θρίαμβον ἀπὸ τῆς τρίτης ἠπείρου κατήγαγεν. ἐπεὶ τρίς γε καὶ πρότερον ἦσαν ἕτεροι τεθριαμβευκότες· ἐκεῖνος δὲ τὸν μὲν πρῶτον ἐκ Λιβύης, τὸν δὲ δεύτερον ἐξ Εὐρώπης, τοῦτον δὲ τὸν τελευταῖον ἀπὸ τῆς Ἀσίας εἰσαγαγὼν τρόπον τινὰ τὴν οἰκουμένην ἐδόκει τοῖς τρισὶν ὑπῆχθαι θριάμβοις.", "st": "Pomp. 45.1"}, {"sp": "N", "t": "ἡλικίᾳ δὲ τότε ἦν, ὡς μὲν οἱ κατὰ πάντα τῷ Ἀλεξάνδρῳ παραβάλλοντες αὐτὸν καὶ προσβιβάζοντες ἀξιοῦσι, νεώτερος τῶν τριάκοντα καὶ τεττάρων ἐτῶν, ἀληθείᾳ δὲ τοῖς τετταράκοντα προσῆγεν. ὡς ὤνητό γ’ ἂν ἐνταῦθα τοῦ βίου παυσάμενος, ἄχρι οὗ τὴν Ἀλεξάνδρου τύχην ἔσχεν· ὁ δὲ ἐπέκεινα χρόνος αὐτῷ τὰς μὲν εὐτυχίας ἤνεγκεν ἐπιφθόνους, ἀνηκέστους δὲ τὰς δυστυχίας. ἣν γὰρ ἐκ προσηκόντων αὐτὸς ἐκτήσατο δύναμιν ἐν τῇ πόλει, ταύτῃ χρώμενος ὑπὲρ ἄλλων οὐ δικαίως, ὅσον ἐκείνοις ἰσχύος προσετίθει τῆς ἑαυτοῦ δόξης ἀφαιρῶν, ἔλαθε ῥώμῃ καὶ μεγέθει τῆς αὐτοῦ δυνάμεως καταλυθείς, καὶ καθάπερ τὰ καρτερώτατα μέρη καὶ χωρία τῶν πόλεων, ὅταν δέξηται πολεμίους, ἐκείνοις προστίθησι τὴν αὑτῶν ἰσχύν, οὕτως διὰ τῆς Πομπηΐου δυνάμεως Καῖσαρ ἐξαρθεὶς ἐπὶ τὴν πόλιν κατὰ τῶν ἄλλων ἴσχυσε, τοῦτον ἀνέτρεψε καὶ κατέβαλεν. ἐπράχθη δὲ οὕτως.", "st": "Pomp. 46.1"}, {"sp": "N", "t": "Λεύκολλον, ὡς ἐπανῆλθεν ἐξ Ἀσίας ὑπὸ Πομπηΐου περιϋβρισμένος, αὐτίκα τε λαμπρῶς ἡ σύγκλητος ἐδέξατο, καὶ μᾶλλον ἔτι Πομπηΐου παραγενομένου κολούουσα τὴν δόξαν ἤγειρεν ἐπὶ τὴν πολιτείαν. ὁ δὲ τἆλλα μὲν ἀμβλὺς ἦν ἤδη καὶ κατέψυκτο τὸ πρακτικόν, ἡδονῇ σχολῆς καὶ ταῖς περί τὸν πλοῦτον διατριβαῖς ἑαυτὸν ἐνδεδωκώς, ἐπὶ δὲ Πομπήϊον εὐθὺς ἀΐξας καὶ λαβόμενος ἐντόνως αὐτοῦ περί τε τῶν διατάξεων ἃς ἔλυσεν ἐκράτει, καὶ πλέον εἶχεν ἐν τῇ βουλῇ συναγωνιζομένου Κάτωνος. ἐκπίπτων δὲ καὶ περιωθούμενος ὁ Πομπήϊος ἠναγκάζετο δημαρχοῦσι προσφεύγειν καὶ προσαρτᾶσθαι μειρακίοις· ὧν ὁ βδελυρώτατος καὶ θρασύτατος Κλώδιος ἀναλαβὼν αὐτὸν ὑπέρριψε τῷ δήμῳ, καὶ παρ’ ἀξίαν κυλινδούμενον ἐν ἀγορᾷ ἔχων καὶ περιφέρων ἐχρῆτο τῶν πρὸς χάριν ὄχλου καὶ κολακείαν γραφομένων καὶ λεγομένων βεβαιωτῇ, καὶ προσέτι μισθὸν ᾔτει, ὥσπερ οὐ καταισχύνων, ἀλλὰ εὐεργετῶν, ὃν ὕστερον ἔλαβε παρὰ Πομπηΐου, προέσθαι Κικέρωνα, φίλον ὄντα καὶ πλεῖστα δὴ πεπολιτευμένον ὑπὲρ αὐτοῦ. κινδυνεύοντι γὰρ αὐτῷ καὶ δεομένῳ βοηθείας οὐδὲ εἰς ὄψιν προῆλθεν, ἀλλὰ τοῖς ἥκουσιν ἀποκλείσας τὴν αὔλειον ἑτέραις θύραις ᾤχετο ἀπιών. Κικέρων δὲ φοβηθεὶς τὴν κρίσιν ὑπεξῆλθε τῆς Ῥώμης.", "st": "Pomp. 46.3"}, {"sp": "N", "t": "τότε δὲ Καῖσαρ ἐλθὼν ἀπὸ στρατείας ἥψατο πολιτεύματος ὃ πλείστην μὲν αὐτῷ χάριν ἐν τῷ παρόντι καὶ δύναμιν εἰσαῦθις ἤνεγκε, μέγιστα δὲ Πομπήϊον ἔβλαψε καὶ τὴν πόλιν. ὑπατείαν μὲν γὰρ μετῄει πρώτην ὁρῶν δὲ ὅτι Κράσσου πρὸς Πομπήϊον διαφερομένου θατέρῳ προσθέμενος ἐχθρῷ χρήσεται τῷ ἑτέρῳ, τρέπεται πρὸς διαλλαγὰς ἀμφοῖν, πρᾶγμα καλὸν μὲν ἄλλως καὶ πολιτικόν, αἰτίᾳ δὲ φαύλῃ καὶ μετὰ δεινότητος ὑπ’ ἐκείνου συντεθὲν ἐπιβούλως. ἡ γὰρ ὥσπερ ἓν σκάφει τὰς ἀποκλίσεις ἐπανισοῦσα τῆς πόλεως ἰσχὺς εἰς ἓν συνελθοῦσα καὶ γενομένη μία τὴν πάντα πράγματα καταστασιάσασαν καὶ καταβαλοῦσαν ἀνανταγώνιστον ῥοπὴν ἐποίησεν. ὁ γοῦν Κάτων τοὺς λέγοντας ὑπὸ τῆς ὕστερον γενομένης πρὸς Καίσαρα Πομπηΐῳ διαφορᾶς ἀνατραπῆναι τὴν πόλιν ἁμαρτάνειν ἔλεγεν αἰτιωμένους τὸ τελευταῖον· οὐ γὰρ τὴν στάσιν οὐδὲ τὴν ἔχθραν, ἀλλὰ τὴν σύστασιν καὶ τὴν ὁμόνοιαν αὐτῶν τῇ πόλει κακὸν πρῶτον γενέσθαι καὶ μέγιστον. ᾑρέθη μὲν γὰρ ὕπατος Καῖσαρ· εὐθὺς δὲ θεραπεύων τὸν ἄπορον καὶ πένητα κατοικίας πόλεων καὶ νομὰς ἀγρῶν ἔγραφεν, ἐκβαίνων τὸ τῆς ἀρχῆς ἀξίωμα καὶ τρόπον τινὰ δημαρχίαν τὴν ὑπατείαν καθιστάς. ἐναντιουμένου δὲ τοῦ συνάρχοντος αὐτῷ Βύβλου, καὶ Κάτωνος ἐρρωμενέστατα τῷ Βύβλῳ παρεσκευασμένου βοηθεῖν, προαγαγὼν ὁ Καῖσαρ ἐπὶ τοῦ βήματος Πομπήϊον ἐμφανῆ καὶ προσαγορεύσας ἠρώτησεν εἰ τοὺς νόμους ἐπαινοίη· τοῦ δὲ συμφήσαντος, οὐκοῦν, εἶπεν, ἄν τις τοὺς νόμους βιάζηται, εἰς τὸν δῆμον ἀφίξῃ βοηθῶν; πάνυ μὲν οὖν, ἔφη ὁ Πομπήϊος, ἀφίξομαι, πρὸς τοὺς ἀπειλοῦντας τὰ ξίφη μετὰ ξίφους καὶ θυρεὸν κομίζων. τούτου Πομπήϊος οὐδὲν οὔτε εἰπεῖν οὔτε ποιῆσαι μέχρι τῆς ἡμέρας ἐκείνης φορτικώτερον ἔδοξεν, ὥστε καὶ τοὺς φίλους ἀπολογεῖσθαι φάσκοντας ἐκφυγεῖν αὐτὸν ἐπὶ καιροῦ τὸ ῥῆμα. τοῖς μέντοι μετὰ ταῦτα πραττομένοις φανερὸς ἦν ἤδη παντάπασιν ἑαυτὸν τῷ Καίσαρι χρήσασθαι παραδεδωκώς. Ἰουλίαν γὰρ τὴν Καίσαρος θυγατέρα, Καιπίωνι καθωμολογημένην καὶ γαμεῖσθαι μέλλουσαν ὀλίγων ἡμερῶν, οὐδενὸς ἂν προσδοκήσαντος ἔγημε Πομπήϊος, μείλιγμα Καιπίωνι τῆς ὀργῆς τὴν ἑαυτοῦ θυγατέρα καταινέσας, Φαύστῳ τῷ παιδὶ Σύλλα πρότερον ἐγγεγυημένην. αὐτὸς δὲ Καῖσαρ ἔγημε Καλπουρνίαν τὴν Πείσωνος.", "st": "Pomp. 47.1"}, {"sp": "N", "t": "ἐκ δὲ τούτου Πομπήϊος ἐμπλήσας στρατιωτῶν τὴν πόλιν ἅπαντα τὰ πράγματα βίᾳ κατεῖχε. βύβλῳ τε γὰρ εἰς ἀγορὰν τῷ ὑπάτῳ κατιόντι μετὰ Λευκόλλου καὶ Κάτωνος ἄφνω προσπεσόντες κατέκλασαν τὰς ῥάβδους, αὐτοῦ δέ τις κοπρίων κόφινον ἐκ κεφαλῆς τοῦ Βύβλου κατεσκέδασε, δύο δὲ δήμαρχοι τῶν συμπροπεμπόντων ἐτρώθησαν. οὕτω δὲ τῶν ἐνισταμένων τὴν ἀγορὰν ἐρημώσαντες ἐπεκύρωσαν τὸν περὶ τῆς διανομῆς τῶν χωρίων νόμον δελεασθεὶς ὁ δῆμος εἰς πᾶσαν ἤδη τιθασὸς αὐτοῖς ἐγεγόνει καὶ κατάντης πρᾶξιν, οὐδὲν πολυπραγμονῶν, ἀλλ’ ἐπιφέρων σιωπῇ τοῖς γραφομένοις τὴν ψῆφον. ἐκυρώθησαν οὖν Πομπηΐῳ μὲν αἱ διατάξεις ὑπὲρ ὧν Λεύκολλος ἤριζε, Καίσαρι δὲ τὴν ἐντὸς Ἄλπεων καὶ τὴν ἐκτὸς ἔχειν Γαλατίαν καὶ Ἰλλυριοὺς εἰς πενταετίαν καὶ τέσσαρα τάγματα τέλεια στρατιωτῶν, ὑπάτους δὲ εἰς τὸ μέλλον εἶναι Πείσωνα τὸν Καίσαρος πενθερὸν καὶ Γαβίνιον, ἄνδρα τῶν Πομπηΐου κολάκων ὑπερφυέστατον.", "st": "Pomp. 48.1"}, {"sp": "N", "t": "πραττομένων δὲ τούτων Βύβλος μὲν εἰς τὴν οἰκίαν κατακλεισάμενος ὀκτὼ μηνῶν οὐ προῆλθεν ὑπατεύων, ἀλλ’ ἐξέπεμπε διαγράμματα βλασφημίας ἀμφοῖν ἔχοντα καὶ κατηγορίας, Κάτων δὲ ὥσπερ ἐπίπνους καὶ φοιβόληπτος ἐν τῇ βουλῇ τὰ μέλλοντα τῇ πόλει καὶ τῷ Πομπηΐῳ προηγόρευε, Λεύκολλος δὲ ἀπειπὼν ἡσυχίαν ἦγεν ὡς οὐκέτι πρὸς πολιτείαν ὡραῖος· ὅτε δὴ καὶ Πομπήϊος ἔφη, γέροντι τὸ τρυφᾶν ἀωρότερον εἶναι τοῦ πολιτεύεσθαι. ταχὺ μέντοι καὶ αὐτὸς ἐμαλάσσετο τῷ τῆς κόρης ἔρωτι καὶ προσεῖχεν ἐκείνῃ τὰ πολλὰ καὶ συνδιημέρευεν ἐν ἀγροῖς καὶ κήποις, ἠμέλει δὲ τῶν κατ’ ἀγορὰν πραττομένων, ὥστε καὶ Κλώδιον αὐτοῦ καταφρονῆσαι δημαρχοῦντα τότε καὶ θρασυτάτων ἅψασθαι πραγμάτων. ἐπεὶ γὰρ ἐξέβαλε Κικέρωνα, καὶ Κάτωνα προφάσει στρατηγίας εἰς Κύπρον ἀπέπεμψε, Καίσαρος εἰς Γαλατίαν ἐξεληλακότος, αὑτῷ δὲ προσέχοντα τὸν δῆμον ἑώρα πάντα πράττοντι καὶ πολιτευομένῳ πρός χάριν, εὐθὺς ἐπεχείρει τῶν Πομπηΐου διατάξεων ἐνίας ἀναιρεῖν, καὶ Τιγράνην τὸν αἰχμάλωτον ἀφαρπάσας εἶχε σὺν αὑτῷ, καὶ τοῖς φίλοις δίκας ἐπῆγε, πεῖραν ἐν ἐκείνοις τῆς Πομπηΐου λαμβάνων δυνάμεως. τέλος δέ, προελθόντος αὐτοῦ πρός τινα δίκην, ἔχων ὑφ’ αὑτῷ πλῆθος ἀνθρώπων ἀσελγείας καὶ ὀλιγωρίας μεστὸν αὐτὸς μὲν εἰς ἐπιφανῆ τόπον καταστὰς ἐρωτήματα τοιαῦτα προὔβαλλε· τίς ἐστιν αὐτοκράτωρ ἀκόλαστος; τίς ἀνὴρ ἄνδρα ζητεῖ; τίς ἑνὶ δακτύλῳ κνᾶται τὴν κεφαλήν; οἱ δέ, ὥσπερ χορὸς εἰς ἀμοιβαῖα συγκεκροτημένος, ἐκείνου τὴν τήβεννον ἀνασείοντος ἐφ’ ἑκάστῳ μέγα βοῶντες ἀπεκρίναντο· Πομπήϊος.", "st": "Pomp. 48.4"}, {"sp": "N", "t": "ἠνία μὲν οὖν καί ταῦτα Πομπήϊον ἀήθη τοῦ κακῶς ἀκούειν ὄντα καί μάχης τοιαύτης ἄπειρον ἤχθετο δὲ μᾶλλον αἰσθανόμενος τήν βουλὴν ἐπιχαίρουσαν αὐτῷ προπηλακιζομένῳ καί διδόντι δίκην τῆς Κικέρωνος προδοσίας. ἐπεὶ δὲ καὶ πληγὰς ἐν ἀγορᾷ μέχρι τραυμάτων συνέβη γενέσθαι, καί Κλωδίου τις οἰκέτης παραδυόμενος ἐν ὄχλῳ διὰ τῶν περιεστώτων πρὸς τὸν Πομπήϊον ἠλέγχθη ξίφος ἔχειν, ταῦτα ποιούμενος πρόφασιν, ἄλλως δὲ τοῦ Κλωδίου τήν ἀσέλγειαν καί τὰς βλασφημίας δεδιώς, οὐκέτι προῆλθεν εἰς ἀγορὰν ὅσον ἐκεῖνος ἦρχε χρόνον, ἀλλ’ οἰκουρῶν διετέλει καὶ σκεπτόμενος μετὰ τῶν φίλων ὅπως ἂν ἐξακέσαιτο τῆς βουλῆς καί τῶν ἀρίστων τήν πρὸς αὐτὸν ὀργήν. Κουλλέωνι μὲν οὖν κελεύοντι τήν Ἰουλίαν ἀφεῖναι καί μεταβαλέσθαι πρὸς τήν σύγκλητον ἀπὸ τῆς Καίσαρος φιλίας οὐ προσέσχε, τοῖς δὲ Κικέρωνα καταγαγεῖν ἀξιοῦσιν, ἄνδρα καί Κλωδίῳ πολεμιώτατον καί τῇ βουλῇ προσφιλέστατον, ἐπείσθη· καί προαγαγὼν τὸν ἀδελφὸν αὐτοῦ δεόμενον σὺν χειρὶ πολλῇ, τραυμάτων ἐν ἀγορᾷ γενομένων καί τινων ἀναιρεθέντων, ἐκράτησε τοῦ Κλωδίου. καί νόμῳ κατελθὼν ὁ Κικέρων τήν τε βουλὴν εὐθὺς τῷ Πομπηΐῳ διήλλαττε, καί τῷ σιτικῷ νόμῳ συνηγορῶν τρόπῳ τινὶ πάλιν γῆς καί θαλάττης, ὅσην ἐκέκτηντο Ῥωμαῖοι, κύριον ἐποίει Πομπήϊον.", "st": "Pomp. 49.1"}, {"sp": "N", "t": "ἐπ’ αὐτῷ γὰρ ἐγίνοντο λιμένες, ἐμπόρια, καρπῶν διαθέσεις, ἑνὶ λόγῳ, τὰ τῶν πλεόντων πράγματα, τὰ τῶν γεωργούντων. Κλώδιος δὲ ᾐτιᾶτο μὴ γεγράφθαι τὸν νόμον διὰ τήν σιτοδείαν, ἀλλ’ ὅπως ὁ νόμος γραφείη γεγονέναι τήν σιτοδείαν, ὥσπερ ἐκ λιποθυμίας αὐτοῦ μαραινομένην τήν δύναμιν ἀρχῇ νέᾳ πάλιν ἀναζωπυροῦντος καί ἀναλαμβάνοντος. ἕτεροι δὲ τοῦ ὑπάτου Σπινθῆρος ἀποφαίνουσι τοῦτο σόφισμα, κατακλείσαντος εἰς ἀρχὴν μείζονα Πομπήϊον, ὅπως αὐτὸς ἐκπεμφθῇ Πτολεμαίῳ τῷ βασιλεῖ βοηθῶν. οὐ μὴν ἀλλὰ καί Κανίδιος εἰσήνεγκε δημαρχῶν νόμον, ἄνευ στρατιᾶς Πομπήϊον ἔχοντα ῥαβδούχους δύο διαλλάττειν Ἀλεξανδρεῦσι τὸν βασιλέα, καί Πομπήϊος μὲν ἐδόκει τῷ νόμῳ μὴ δυσχεραίνειν, ἡ δὲ σύγκλητος ἐξέβαλεν, εὐπρεπῶς σκηψαμένη δεδιέναι περὶ τἀνδρός.", "st": "Pomp. 49.5"}, {"sp": "N", "t": "ἦν δὲ γράμμασιν ἐντυχεῖν διερριμμένοις κατ’ ἀγορὰν καί παρὰ τὸ βουλευτήριον ὡς δὴ Πτολεμαίου δεομένου Πομπήϊον αὐτῷ στρατηγὸν ἀντὶ τοῦ Σπινθῆρος δοθῆναι. Τιμαγένης δὲ καί ἄλλως τὸν Πτολεμαῖον οὐκ οὔσης ἀνάγκης ἀπελθεῖν φησι, καί καταλιπεῖν Αἴγυπτον ὑπὸ Θεοφάνους πεισθέντα πράττοντος Πομπηΐῳ χρηματισμοὺς καί στρατηγίας καινῆς ὑπόθεσιν. ἀλλὰ τοῦτο μὲν οὐχ οὕτως ἡ Θεοφάνους μοχθηρία πιθανὸν ὡς ἄπιστον ἡ Πομπηΐου ποιεῖ φύσις, οὐκ ἔχουσα κακόηθες οὐδ’ ἀνελεύθερον οὕτω τὸ φιλότιμον.", "st": "Pomp. 49.7"}, {"sp": "N", "t": "Ἐπισταθεὶς δὲ τῇ περὶ τὸ σιτικὸν οἰκονομίᾳ καὶ πραγματείᾳ, πολλαχοῦ μὲν ἀπέστειλε πρεσβευτὰς καὶ φίλους, αὐτὸς δὲ πλεύσας εἰς Σικελίαν καὶ Σαρδόνα καὶ Λιβύην ἤθροιζε σῖτον· ἀνάγεσθαι δὲ μέλλων πνεύματος μεγάλου κατὰ θάλατταν ὄντος καὶ τῶν κυβερνητῶν ὀκνούντων, πρῶτος ἐμβὰς καὶ κελεύσας τὴν ἄγκυραν αἴρειν ἀνεβόησε· πλεῖν ἀνάγκη, ζῆν οὐκ ἀνάγκη· τοιαύτῃ δὲ τόλμῃ καὶ προθυμίᾳ χρώμενος μετὰ τύχης ἀγαθῆς ἐνέπλησε σίτου τὰ ἐμπόρια καὶ πλοίων τὴν θάλασσαν, ὥστε καὶ τοῖς ἐκτὸς ἀνθρώποις ἐπαρκέσαι τὴν περιουσίαν ἐκείνης τῆς παρασκευῆς, καὶ γενέσθαι καθάπερ ἐκ πηγῆς ἄφθονον ἀπορροὴν εἰς πάντας.", "st": "Pomp. 50.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ τῷ χρόνῳ μέγαν ἦραν οἱ Κελτικοὶ πόλεμοι Καίσαρα· καὶ δοκῶν πορρωτάτω τῆς Ῥώμης ἀπεῖναι καὶ συνηρτῆσθαι Βέλγαις καὶ Σουήβοις καὶ Βρεττανοῖς, ἐλάνθανεν ὑπὸ δεινότητος ἐν μέσῳ τῷ δήμῳ καὶ τοῖς κυριωτάτοις πράγμασι καταπολιτευόμενος τὸν Πομπήϊον. αὐτὸς μὲν γὰρ ὡς σῶμα τὴν στρατιωτικὴν δύναμιν περικείμενος, οὐκ ἐπὶ τοὺς βαρβάρους, ἀλλ’ ὥσπερ ἐν θήραις καὶ κυνηγεσίοις τοῖς πρὸς ἐκείνους ἀγῶσι γυμνάζων, διεπόνει, καὶ κατεσκεύαζεν ἄμαχον καὶ φοβεράν, χρυσὸν δὲ καὶ ἄργυρον καὶ τἆλλα λάφυρα καὶ τὸν ἄλλον πλοῦτον τὸν ἐκ πολέμων τοσούτων περιγινόμενον εἰς τὴν Ῥώμην ἀποστέλλων, καὶ διαπειρῶν ταῖς δωροδοκίαις καὶ συγχορηγῶν ἀγορανόμοις καὶ στρατηγοῖς καὶ ὑπάτοις καὶ γυναιξὶν αὐτῶν, ᾠκειοῦτο πολλούς· ὥστε ὑπερβαλόντος αὐτοῦ τὰς Ἄλπεις καὶ διαχειμάζοντος ἐν Λούκῃ, τῶν μὲν ἄλλων ἀνδρῶν καὶ γυναικῶν ἁμιλλωμένων καὶ φερομένων πολὺ πλῆθος γενέσθαι, συγκλητικοὺς δὲ διακοσίους, ἐν οἷς καὶ Πομπήϊος ἦν καὶ Κράσσος, ἀνθυπάτων δὲ καὶ στρατηγῶν ἑκατὸν εἴκοσι ῥάβδους ἐπὶ ταῖς Καίσαρος θύραις ὀφθῆναι. τοὺς μὲν οὖν ἄλλους ἅπαντας ἐμπλήσας ἐλπίδων καὶ χρημάτων ἀπέστελλε, Κράσσῳ δὲ καὶ Πομπηΐῳ πρὸς αὐτὸν ἐγένοντο συνθῆκαι, μετιέναι μὲν ὑπατείας ἐκείνους καὶ Καίσαρα συλλαμβάνειν αὐτοῖς, πέμποντα τῶν στρατιωτῶν συχνοὺς ἐπὶ τὴν ψῆφον, ἐπὰν δὲ αἱρεθῶσι τάχιστα, πράττειν μὲν ἑαυτοῖς ἐπαρχιῶν καὶ στρατοπέδων ἡγεμονίας, Καίσαρι δὲ τὰς οὔσας βεβαιοῦν εἰς ἄλλην πενταετίαν. ἐπὶ τούτοις ἐξενεχθεῖσιν εἰς τοὺς πολλοὺς χαλεπῶς ἔφερον οἱ πρῶτοι· καὶ Μαρκελλῖνος ἐν τῷ δήμῳ καταστὰς ἀμφοῖν ἐναντίον ἠρώτησεν εἰ μετίασιν ὑπατείαν. καὶ τῶν πολλῶν ἀποκρίνασθαι κελευόντων, πρῶτος Πομπήϊος εἶπεν ὡς τάχα μὲν ἂν μετέλθοι, τάχα δὲ· οὐκ ἂν μετέλθοι· Κράσσος δὲ πολιτικώτερον οὕτω γὰρ ἔφη πράξειν ὁποτέρως ἂν οἴηται τῷ κοινῷ συνοίσειν. ἐπιφυομένου δὲ Πομπηΐῳ Μαρκελλίνου καὶ σφοδρῶς λέγειν δοκοῦντος, ὁ Πομπήϊος ἔφη πάντων ἀδικώτατον εἶναι τὸν Μαρκελλῖνον, ὃς χάριν οὐκ ἔχει λόγιος μὲν ἐξ ἀφώνου δι’ αὐτόν, ἐμετικὸς δὲ ἐκ πεινατικοῦ γενόμενος.", "st": "Pomp. 51.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τῶν ἄλλων ἀποστάντων τοῦ παραγγέλλειν ὑπατείαν, Λεύκιον Δομέτιον Κάτων ἔπεισε καὶ παρεθάρρυνε μὴ ἀπειπεῖν οὐ γὰρ ὑπὲρ ἀρχῆς, ἀλλ’ ὑπὲρ ἐλευθερίας εἶναι τὸν ἀγῶνα πρὸς τοὺς τυράννους, οἱ δὲ περὶ τὸν Πομπήϊον φοβηθέντες τὸν τόνον τοῦ Κάτωνος, μὴ τὴν βουλὴν ἔχων ἅπασαν ἀποσπάσῃ καὶ μεταβάλῃ τοῦ δήμου τὸ ὑγιαῖνον, οὐκ εἴασαν εἰς ἀγορὰν κατελθεῖν τὸν Δομέτιον, ἀλλ’ ἐπιπέμψαντες ἐνόπλους ἄνδρας ἀπέκτειναν μὲν τὸν προηγούμενον λυχνοφόρον, ἐτρέψαντο δὲ τοὺς ἄλλους· ἔσχατος δὲ Κάτων ἀνεχώρησε, τρωθεὶς τὸν δεξιὸν πῆχυν ἀμυνόμενος πρὸ τοῦ Δομετίου.", "st": "Pomp. 52.1"}, {"sp": "N", "t": "τοιαύτῃ δὲ ὁδῷ παρελθόντες ἐπὶ τὴν ἀρχὴν οὐδὲ τἆλλα κοσμιώτερον ἔπραττον. ἀλλὰ πρῶτον μὲν τὸν Κάτωνα τοῦ δήμου στρατηγὸν αἱρουμένου καὶ τὴν ψῆφον ἐπιφέροντος, Πομπήϊος ἔλυσε τὴν ἐκκλησίαν οἰωνοὺς αἰτιώμενος, ἀντὶ δὲ Κάτωνος Βατίνιον ἀνηγόρευσαν, ἀργυρίῳ τὰς φυλὰς διαφθείραντες. ἔπειτα νόμους διὰ Τρεβωνίου δημαρχοῦντος εἰσέφερον, Καίσαρι μέν, ὥσπερ ὡμολόγητο, δευτέραν ἐπιμετροῦντας πενταετίαν, Κράσσῳ δὲ Συρίαν καὶ τὴν ἐπὶ Πάρθους στρατείαν διδόντας, αὐτῷ δὲ Πομπηΐῳ Λιβύην ἅπασαν καὶ Ἰβηρίαν ἑκατέραν καὶ τέσσαρα τάγματα στρατιωτῶν, ὧν ἐπέχρησε δύο Καίσαρι δεηθέντι πρὸς τὸν ἐν Γαλατίᾳ πόλεμον. ἀλλὰ Κράσσος μὲν ἐξῆλθεν εἰς τὴν ἐπαρχίαν ἀπαλλαγεὶς τῆς ὑπατείας, Πομπήϊος δὲ τὸ θέατρον ἀναδείξας ἀγῶνας ἦγε γυμνικοὺς καὶ μουσικοὺς ἐπὶ τῇ καθιερώσει, καὶ θηρῶν ἁμίλλας ἐν οἷς πεντακόσιοι λέοντες ἀνῃρέθησαν, ἐπὶ πᾶσι δὲ τὴν ἐλεφαντομαχίαν, ἐκπληκτικώτατον θέαμα, παρέ", "st": "Pomp. 52.3"}, {"sp": "N", "t": "ἐπὶ τούτοις δὲ θαυμαστωθεὶς καὶ ἀγαπηθείς, αὖθις οὐκ ἐλάττονα φθόνον ἔσχεν, ὅτι πρεσβευταῖς φίλοις παραδοὺς τὰ στρατεύματα καὶ τὰς ἐπαρχίας, αὐτὸς ἐν τοῖς περὶ τὴν Ἰταλίαν ἡβητηρίοις, μετιὼν ἄλλοτε ἀλλαχόσε, μετὰ τῆς γυναικὸς διῆγεν, εἴτε ἐρῶν αὐτῆς, εἴτε ἐρῶσαν οὐχ ὑπομένων ἀπολιπεῖν· καὶ γὰρ καὶ τοῦτο λέγεται. καὶ περιβόητον ἦν τῆς κόρης τὸ φίλανδρον, οὐ καθ’ ὥραν ποθούσης τὸν Πομπήϊον, ἀλλ’ αἴτιον ἔοικεν ἤ τε σωφροσύνη τοῦ ἀνδρὸς εἶναι μόνην γινώσκοντος τὴν γεγαμημένην, ἥ τε σεμνότης οὐκ ἄκρατον, ἀλλ’ εὔχαριν ἔχουσα τὴν ὁμιλίαν καὶ μάλιστα γυναικῶν ἀγωγόν, εἰ δεῖ μηδὲ Φλώραν ἁλῶναι τὴν ἑταίραν ψευδομαρτυριῶν. ἐν δ’ οὖν ἀγορανομικοῖς ἀρχαιρεσίοις εἰς χεῖράς τινων ἐλθόντων καὶ φονευθέντων περὶ αὐτὸν οὐκ ὀλίγων ἀναπλησθεὶς αἵματος ἤλλαξε τὰ ἱμάτια, πολλοῦ δὲ θορύβου καὶ δρόμου πρὸς τὴν οἰκίαν γενομένου τῶν κομιζόντων τὰ ἱμάτια θεραπόντων, ἔτυχε μὲν ἡ κόρη κύουσα, θεασαμένη δὲ καθῃμαγμένην τὴν τήβεννον ἐξέλιπε καὶ μόλις ἀνήνεγκεν, ἐκ δὲ τῆς ταραχῆς ἐκείνης καὶ τοῦ πάθους ἀπήμβλωσεν. ὅθεν οὐδὲ οἱ μάλιστα μεμφόμενοι τὴν πρὸς Καίσαρα Πομπηΐου φιλίαν ᾐτιῶντο τὸν ἔρωτα τῆς γυναικός, αὖθις μέντοι κυήσασα καὶ τεκοῦσα θῆλυ παιδίον ἐκ τῶν ὠδίνων ἐτελεύτησε, καὶ τὸ παιδίον οὐ πολλὰς ἡμέρας ἐπέζησε, παρεσκευασμένου δὲ τοῦ Πομπηΐου τὸ σῶμα θάπτειν ἐν Ἀλβανῷ, βιασάμενος ὁ δῆμος εἰς τὸ Ἄρειον πεδίον κατήνεγκεν, οἴκτῳ τῆς κόρης μᾶλλον ἢ Πομπηΐῳ καὶ Καίσαρι χαριζόμενος. αὐτῶν δὲ ἐκείνων μεῖζον ἐδόκει μέρος ἀπόντι Καίσαρι νέμειν ὁ δῆμος ἢ Πομπηΐῳ παρόντι τῆς τιμῆς, εὐθὺς γὰρ ἐκύμαινεν ἡ πόλις, καὶ πάντα τὰ πράγματα σάλον εἶχε καὶ λόγους διαστατικούς, ὡς ἡ πρότερον παρακαλύπτουσα μᾶλλον ἢ κατείργουσα τῶν ἀνδρῶν τὴν φιλαρχίαν οἰκειότης ἀνῄρηται. μετ’ οὐ πολὺ δὲ καὶ Κράσσος ἐν Πάρθοις ἀπολωλὼς ἠγγέλλετο· καὶ τοῦτο κώλυμα ὂν μέγα τοῦ συμπεσεῖν τὸν ἐμφύλιον πόλεμον ἐκποδὼν ἐγεγόνει· δεδιότες γὰρ ἐκεῖνον ἀμφότεροι τοῖς πρὸς ἀλλήλους ἁμῶς γε πως ἐνέμενον δικαίοις. ἐπεὶ δὲ ἀνεῖλεν ἡ τύχη τὸν ἔφεδρον τοῦ ἀγῶνος, εὐθὺς ἦν εἰπεῖν τὸ κωμικόν, ὡς<br>ἅτερος πρὸς τὸν ἕτερον", "st": "Pomp. 53.1"}, {"sp": "N", "t": "ὑπαλείφεται τὼ χεῖρέ θ’ ὑποκονίεται.", "st": "Pomp. 53.1b"}, {"sp": "N", "t": "οὕτως ἡ τύχη μικρόν ἐστι πρὸς τὴν φύσιν. οὐ γὰρ ἀποπίμπλησιν αὐτῆς τὴν ἐπιθυμίαν, ὅπου τοσοῦτον βάθος ἡγεμονίας καὶ μέγεθος εὐρυχωρίας δυοῖν ἀνδροῖν οὐκ ἐπέσχεν, ἀλλ’ ἀκούοντες καὶ ἀναγινώσκοντες ὅτι τριχθὰ δὲ πάντα δέδασται τοῖς θεοῖς, ἕκαστος δ’ ἔμμορε τιμῆς, ἑαυτοῖς οὐκ ἐνόμιζον ἀρκεῖν δυσὶν οὖσι τὴν Ῥωμαίων ἀρχήν.", "st": "Pomp. 53.7"}, {"sp": "N", "t": "καίτοι Πομπήϊος εἶπέ ποτε δημηγορῶν ὅτι πᾶσαν ἀρχήν λάβοι πρότερον ἢ προσεδόκησε καὶ κατάθοιτο θᾶττον ἢ προσεδοκήθη. καὶ νὴ Δία μαρτυρούσας εἶχεν ἀεὶ τὰς διαλύσεις τῶν στρατοπέδων. τότε δὲ τὸν Καίσαρα δοκῶν οὐ προήσεσθαι τὴν δύναμιν ἐζήτει ταῖς πολιτικαῖς ἀρχαῖς ὀχυρὸς εἶναι πρὸς αὐτόν, ἄλλο δὲ οὐδὲν ἐνεωτέριζεν, οὐδὲ ἐβούλετο δοκεῖν ἀπιστεῖν, ἀλλ’ ὑπερορᾶν μᾶλλον καὶ καταφρονεῖν. ἐπεὶ δὲ τὰς ἀρχὰς οὐ κατὰ γνώμην ἑώρα βραβευομένας, δεκαζομένων τῶν πολιτῶν, ἀναρχίαν ἐν τῇ πόλει περιεῖδε γενομένην καὶ λόγος εὐθὺς ἐχώρει πολὺς ὑπὲρ δικτάτορος, ὃν πρῶτος εἰς μέσον ἐξενεγκεῖν ἐτόλμησε Λουκίλλιος ὁ δήμαρχος, τῷ δήμῳ παραινῶν ἑλέσθαι δικτάτορα Πομπήϊον.", "st": "Pomp. 54.1"}, {"sp": "N", "t": "ἐπιλαβομένου δὲ Κάτωνος οὗτος μὲν ἐκινδύνευσε τὴν δημαρχίαν ἀποβαλεῖν, ὑπὲρ δὲ Πομπηΐου πολλοὶ τῶν φίλων ἀπελογοῦντο παριόντες ὡς οὐ δεομένου τῆς ἀρχῆς ἐκείνης οὐδὲ βουλομένου. Κάτωνος δὲ Πομπήϊον ἐπαινέσαντος καὶ προτρεψαμένου τῆς εὐκοσμίας ἐπιμεληθῆναι, τότε μὲν αἰδεσθεὶς ἐπεμελήθη, καὶ κατεστάθησαν ὕπατοι Δομέτιος καὶ Μεσσάλας, ὕστερον δὲ πάλιν ἀναρχίας γινομένης καὶ πλειόνων ἤδη τὸν περὶ τοῦ δικτάτορος λόγον ἐγειρόντων ἰταμώτερον, φοβηθέντες οἱ περὶ Κάτωνα μὴ βιασθῶσιν, ἔγνωσαν ἀρχήν τινα τῷ Πομπηΐῳ προέμενοι νόμιμον ἀποτρέψαι τῆς ἀκράτου καὶ τυραννικῆς ἐκείνης. καὶ Βύβλος ἐχθρὸς ὢν Πομπηΐῳ πρῶτος ἀπεφήνατο γνώμην ἐν συγκλήτῳ Πομπήϊον μόνον ἑλέσθαι ὕπατον· ἢ γὰρ ἀπαλλαγήσεσθαι τῆς παρούσης τὴν πόλιν ἀκοσμίας, ἢ δουλεύσειν τῷ κρατίστῳ.", "st": "Pomp. 54.3"}, {"sp": "N", "t": "φανέντος δὲ παραδόξου τοῦ λόγου διὰ τὸν εἰπόντα, Κάτων ἀναστὰς καὶ παρασχὼν δόκησιν ὡς ἀντιλέξοι, γενομένης σιωπῆς εἶπε τὴν προκειμένην γνώμην αὐτὸς μὲν οὐκ ἂν εἰσενεγκεῖν, εἰσενηνεγμένῃ δὲ ὑφ’ ἑτέρου πείθεσθαι κελεύειν, πᾶσαν μὲν ἀρχήν μᾶλλον αἱρούμενος ἀναρχίας, Πομπηΐου δὲ μηδένα βέλτιον ἄρξειν ἐν ταραχαῖς τηλικαύταις νομίζων. δεξαμένης δὲ τῆς βουλῆς, καὶ ψηφισαμένης ὅπως ὕπατος αἱρεθεὶς ὁ Πομπήϊος ἄρχοι μόνος, εἰ δὲ αὐτὸς συνάρχοντος δεηθείη, μὴ θᾶττον δυοῖν μηνοῖν δοκιμάσας ἕλοιτο, κατασταθεὶς οὕτως καὶ ἀποδειχθεὶς διὰ Σουλπικίου μεσοβασιλέως ὕπατος ἠσπάζετο φιλοφρόνως τὸν Κάτωνα, πολλὴν ὁμολογῶν χάριν ἔχειν καὶ παρακαλῶν γίνεσθαι σύμβουλον ἰδίᾳ τῆς ἀρχῆς. Κάτων δὲ χάριν μὲν ἔχειν αὐτῷ τὸν Πομπήϊον οὐκ ἠξίου· δι’ ἐκεῖνον γὰρ ὧν εἶπεν οὐδὲν εἰπεῖν, διὰ δὲ τὴν πόλιν ἔσεσθαι δὲ σύμβουλος ἰδίᾳ παρακαλούμενος, ἐὰν δὲ μὴ παρακαλῆται, δημοσίᾳ φράσειν τὸ φαινόμενον. τοιοῦτος μὲν οὖν Κάτων ἐν πᾶσι.", "st": "Pomp. 54.5"}, {"sp": "N", "t": "Πομπήϊος δὲ παρελθὼν εἰς τὴν πόλιν ἔγημε Κορνηλίαν θυγατέρα Μετέλλου Σκηπίωνος, οὐ παρθένον, ἀλλὰ χήραν ἀπολελειμμένην νεωστὶ Ποπλίου τοῦ Κράσσου παιδός, ᾧ συνῴκησεν ἐκ παρθενίας, ἐν Πάρθοις τεθνηκότος. ἐνῆν δὲ τῇ κόρῃ πολλὰ φίλτρα δίχα τῶν ἀφ’ ὥρας. καὶ γὰρ περὶ γράμματα καλῶς ἤσκητο καὶ περὶ λύραν καὶ γεωμετρίαν, καὶ λόγων φιλοσόφων εἴθιστο χρησίμως ἀκούειν. καὶ προσῆν τούτοις ἦθος ἀηδίας καὶ περιεργίας καθαρόν, ἃ δὴ νέαις προστρίβεται γυναιξὶ τὰ τοιαῦτα μαθήματα· πατὴρ δὲ καὶ γένους ἕνεκα καὶ δόξης ἄμεμπτος. ἀλλ’ ὅμως τοῦ γάμου τοῖς μὲν οὐκ ἤρεσκε τὸ μὴ καθ’ ἡλικίαν υἱῷ γὰρ αὐτοῦ συνοικεῖν ὥραν εἶχεν ἡ Κορνηλία μᾶλλον· οἱ δὲ κομψότεροι τὸ τῆς πόλεως ἡγοῦντο παρεωρακέναι τὸν Πομπήϊον ἐν τύχαις οὔσης, ὧν ἐκεῖνον ἰατρὸν ᾕρηται καὶ μόνῳ παραδέδωκεν αὑτήν· ὁ δὲ στεφανοῦται καὶ θύει γάμους, αὐτὴν τὴν ὑπατείαν ὀφείλων ἡγεῖσθαι συμφοράν, οὐκ ἂν οὕτω παρανόμως δοθεῖσαν εὐτυχούσης τῆς πατρίδος. ἐπεὶ δὲ ταῖς δίκαις τῶν δωροδοκιῶν καὶ δεκασμῶν ἐπιστάς, καὶ νόμους γράψας καθ’ οὓς αἱ κρίσεις ἐγίνοντο, τὰ μὲν ἄλλα σεμνῶς ἐβράβευε καὶ καθαρῶς, ἀσφάλειαν ἅμα καὶ κόσμον καὶ ἡσυχίαν αὐτοῦ προσκαθημένου μεθ’ ὅπλων τοῖς δικαστηρίοις παρέχων, Σκηπίωνος δὲ τοῦ πενθεροῦ κρινομένου, μεταπεμψάμενος οἴκαδε τοὺς ἑξήκοντα καὶ τριακοσίους δικαστὰς ἐνέτυχε βοηθεῖν, ὁ δὲ κατήγορος ἀπέστη τῆς δίκης ἰδὼν τὸν Σκηπίωνα προπεμπόμενον ἐξ ἀγορᾶς ὑπὸ τῶν δικαστῶν, πάλιν οὖν ἤκουε κακῶς,", "st": "Pomp. 55.1"}, {"sp": "N", "t": "ἔτι δὲ μᾶλλον ὅτι λύσας νόμῳ τοὺς γινομένους περὶ τῶν κρινομένων ἐπαίνους, αὐτὸς εἰσῆλθε Πλάγκον ἐπαινεσόμενος. καὶ Κάτων (ἔτυχε γὰρ κρίνων) ἐπισχόμενος τὰ ὦτα ταῖς χερσὶν οὐκ ἔφη καλῶς ἔχειν αὐτῷ παρὰ τὸν νόμον ἀκούειν τῶν ἐπαίνων. ὅθεν ὁ μὲν Κάτων ἀπεβλήθη πρὸ τοῦ φέρειν τὴν ψῆφον, ἑάλω δὲ ταῖς ἄλλαις ὁ Πλάγκος σὺν αἰσχύνῃ τοῦ Πομπηΐου, καὶ γὰρ ὀλίγαις ὕστερον ἡμέραις Ὑψαῖος, ἀνὴρ ὑπατικός, δίκην φεύγων καὶ παραφυλάξας τὸν Πομπήϊον ἐπὶ δεῖπνον ἀπιόντα λελουμένον, ἱκέτευε τῶν γονάτων λαβόμενος. ὁ δὲ παρῆλθεν ὑπεροπτικῶς εἰπὼν διαφθείρειν τὸ δεῖπνον αὐτόν. ἄλλο δὲ μηδὲν περαίνειν. οὕτως οὖν ἄνισος εἶναι δοκῶν αἰτίας εἶχε. τὰ δ’ ἄλλα καλῶς ἅπαντα κατέστησεν εἰς τάξιν, καὶ προσείλετο συνάρχοντα τὸν πενθερὸν εἰς τοὺς ὑπολοίπους πέντε μῆνας. ἐψηφίσθη δὲ αὐτῷ τὰς ἐπαρχίας ἔχειν εἰς ἄλλην τετραετίαν, καὶ χίλια τάλαντα λαμβάνειν καθ’ ἕκαστον ἐνιαυτόν, ἀφ’ ὧν θρέψει καὶ διοικήσει τὸ στρατιωτικόν.", "st": "Pomp. 55.5"}, {"sp": "N", "t": "οἱ δὲ Καίσαρος φίλοι ταύτην ἀρχὴν λαβόντες ἠξίουν τινὰ γενέσθαι καὶ Καίσαρος λόγον, ἀγωνιζομένου τοσούτους ἀγῶνας ὑπὲρ τῆς ἡγεμονίας· ἢ γὰρ ὑπατείας ἄξιον εἶναι τυχεῖν ἑτέρας, ἢ προσλαβεῖν τῇ στρατείᾳ χρόνον. ἐν ᾧ τῶν πεπονημένων οὐκ ἄλλος ἐπελθὼν ἀφαιρήσεται τὴν δόξαν, ἀλλ’ αὐτὸς ἄρξει καὶ τιμήσεται καθ’ ἡσυχίαν ὁ κατεργασάμενος. οὔσης δὲ περὶ τούτων ἁμίλλης, ὡς δὴ παραιτούμενος ὑπὲρ τοῦ Καίσαρος ἐπ’ εὐνοίᾳ τὸν φθόνον ὁ Πομπήϊος ἔφη γράμματα Καίσαρος ἔχειν βουλομένου λαβεῖν διάδοχον καὶ παύσασθαι τῆς στρατείας· ὑπατείας μέντοι καὶ μὴ παρόντι καλῶς ἔχειν αἴτησιν αὐτῷ δοθῆναι. πρὸς ταῦτα ἐνισταμένων τῶν περὶ Κάτωνα καὶ κελευόντων ἰδιώτην γενόμενον καὶ τὰ ὅπλα καταθέμενον εὑρίσκεσθαί τι παρὰ τῶν πολιτῶν ἀγαθόν, οὐκ ἐξερίσας, ἀλλ’ οἷον ἡττηθεὶς ὁ Πομπήϊος ὕποπτος ἦν μᾶλλον ὧν ἐφρόνει περὶ Καίσαρος, ἔπεμψε δὲ καὶ τὰς δυνάμεις ἀπαιτῶν ἃς ἔχρησεν αὐτῷ, τὰ Παρθικὰ ποιούμενος πρόφασιν. ὁ δέ, καίπερ εἰδὼς ἐφ’ οἷς ἀπῃτεῖτο τοὺς στρατιώτας, ἀπέπεμψε καλῶς δωρησάμενος.", "st": "Pomp. 56.1"}, {"sp": "N", "t": "ἐκ τούτου δὲ Πομπήϊος ἐν Νεαπόλει νοσήσας ἐπισφαλῶς ἀνέρρωσε, Πραξαγόρου δὲ πείσαντος τοὺς Νεαπολίτας ἔθυσαν ὑπὲρ αὑτοῦ σωτήρια, μιμουμένων δὲ τούτους τῶν προσοίκων καὶ τοῦ πράγματος οὕτω περιϊόντος τὴν Ἰταλίαν πᾶσαν, καὶ μικρὰ καὶ μεγάλη πόλις ἐφ’ ἡμέρας πολλὰς ἑώρταζε. τοὺς δὲ ἀπαντῶντας πανταχόθεν οὐδεὶς ἐχώρει τόπος, ἀλλὰ ὁδοί τε κατεπίμπλαντο καὶ κῶμαι καὶ λιμένες εὐωχουμένων καὶ θυόντων. πολλοὶ δὲ καὶ στεφανηφοροῦντες ὑπὸ λαμπάδων ἐδέχοντο καὶ παρέπεμπον ἀνθοβολούμενον, ὥστε τὴν κομιδὴν αὑτοῦ καὶ πορείαν θέαμα κάλλιστον εἶναι καὶ λαμπρότατον. οὐδενὸς μέντοι τοῦτο λέγεται τῶν ἀπεργασαμένων τὸν πόλεμον αἰτίων ἔλαττον γενέσθαι, φρόνημα γὰρ εἰσῆλθεν ὑπεραῖρον ἅμα τῷ μεγέθει τῆς χαρᾶς τοὺς ἀπὸ τῶν πραγμάτων λογισμούς· καὶ τὴν εἰς ἀσφαλὲς ἀεὶ τὰ εὐτυχήματα καὶ τὰς πράξεις αὑτοῦ θεμένην εὐλάβειαν προέμενος εἰς ἄκρατον ἐξέπεσε θράσος καὶ περιφρόνησιν τῆς Καίσαρος δυνάμεως, ὡς οὔτε ὅπλων ἐπ’ αὐτὸν οὔτε τινὸς ἐργώδους πραγματείας δεησόμενος, ἀλλὰ πολὺ ῥᾷον καθαιρήσων ἢ πρότερον ηὔξησε τὸν ἄνδρα. πρὸς δὲ τούτοις Ἄππιος ἀφίκετο κομίζων ἐκ Γαλατίας ἣν ἔχρησε Πομπήϊος Καίσαρι στρατιάν· καὶ πολλὰ μὲν ἐξεφλαύριζε τὰς ἐκεῖ πράξεις καὶ λόγους ἐξέφερε βλασφήμους περὶ Καίσαρος, αὐτὸν δὲ Πομπήϊον ἀπείρως ἔχειν ἔλεγε τῆς αὑτοῦ δυνάμεως καὶ δόξης, ἑτέροις ὅπλοις πρὸς Καίσαρα φραγνύμενον, ὃν αὐτοῖς κατεργάσεται τοῖς ἐκείνου στρατεύμασιν, ὅταν πρῶτον ὀφθῇ· τοσοῦτον καὶ μίσους πρὸς Καίσαρα καὶ πόθου πρὸς Πομπήϊον ἐνυπάρχειν αὐτοῖς. οὕτω δ’ οὖν ὁ Πομπήϊος ἐπήρθη, καὶ τοιαύτης καὶ τοσαύτης ὀλιγωρίας διὰ τὸ θαρρεῖν ἐγένετο μεστὸς ὥστε καὶ τῶν δεδιότων τὸν πόλεμον κατεγέλα, καὶ τοὺς λέγοντας ἂν ἐλαύνῃ Καῖσαρ ἐπὶ τὴν πόλιν, οὐχ ὁρᾶν δυνάμεις αἷς αὐτὸν ἀμυνοῦνται, μειδιῶν τῷ προσώπῳ καὶ διακεχυμένος ἀμελεῖν ἐκέλευσεν· ὅπου γὰρ ἄν, ἔφη, τῆς Ἰταλίας ἐγὼ κρούσω τῷ ποδὶ τὴν γῆν, ἀναδύσονται καὶ πεζικαὶ καὶ ἱππικαὶ δυνάμεις.", "st": "Pomp. 57.1"}, {"sp": "N", "t": "ἤδη δὲ καὶ Καῖσαρ ἐπεφύετο τοῖς πράγμασιν ἐρρωμενέστερον, αὐτὸς μὲν οὐκέτι μακρὰν τῆς Ἰταλίας ἀπαίρων, εἰς δὲ τὴν πόλιν ἀεὶ τοὺς στρατιώτας ἀποστέλλων ἀρχαιρεσιάσοντας, χρήμασι δὲ πολλοὺς ὑποικουρῶν καὶ διαφθείρων ἄρχοντας· ὧν καὶ Παῦλος ἦν ὁ ὕπατος ἐπὶ χιλίοις καὶ πεντακοσίοις ταλάντοις μεταβαλόμενος, καὶ Κουρίων ὁ δήμαρχος ἀμηχάνων πλήθει δανείων ἐλευθερωθεὶς ὑπ’ αὐτοῦ, καὶ Μάρκος Ἀντώνιος διὰ φιλίαν Κουρίωνος ὧν ὠφελεῖτο μετέχων. ἐλέχθη μὲν οὖν ὅτι τῶν ἀφιγμένων τις ἀπὸ Καίσαρος ταξιαρχῶν ἑστὼς παρὰ τὸ βουλευτήριον, καὶ πυθόμενος ὡς οὐ δίδωσιν ἡ βουλὴ Καίσαρι χρόνον τῆς ἀρχῆς, εἶπεν ἐπικρούων τῇ χειρὶ τὸ ξίφος, ἀλλὰ τοῦτο δώσει. καὶ τὰ πραττόμενα καὶ τὰ παρασκευαζόμενα ταύτην εἶχε τὴν διάνοιαν.", "st": "Pomp. 58.1"}, {"sp": "N", "t": "αἱ μέντοι Κουρίωνος ἀξιώσεις καὶ παρακλήσεις ὑπὲρ Καίσαρος ἐφαίνοντο δημοτικώτεραι. δυεῖν γὰρ ἠξίου θάτερον, ἢ καὶ Πομπήϊον ἀπαιτεῖν ἢ μηδὲ Καίσαρος ἀφαιρεῖσθαι τὸ στρατιωτικόν ἢ γὰρ ἰδιώτας γενομένους ἐπὶ τοῖς δικαίοις ἢ μένοντας ἀντιπάλους ἐφ’ οἷς ἔχουσιν ἀτρεμήσειν ὁ δὲ τὸν ἕτερον ἀσθενῆ ποιῶν ἣν φοβεῖται δύναμιν διπλασιάζει. πρὸς ταῦτα Μαρκέλλου τοῦ ὑπάτου λῃστὴν ἀποκαλοῦντος τὸν Καίσαρα, καὶ ψηφίζεσθαι πολέμιον κελεύοντος εἰ μὴ καταθήσεται τὰ ὅπλα, Κουρίων ὅμως ἴσχυσε μετὰ Ἀντωνίου καὶ Πείσωνος ἐξελέγξαι τὴν σύγκλητον, ἐκέλευσε γὰρ μεταστῆναι τοὺς Καίσαρα μόνον τὰ ὅπλα καταθέσθαι κελεύοντας, Πομπήϊον δὲ ἄρχειν· καὶ μετέστησαν οἱ πλείους. αὖθις δὲ μεταστῆναι κελεύσαντος ὅσοις ἀμφοτέρους ἀρέσκει τὰ ὅπλα καταθέσθαι καὶ μηδέτερον ἄρχειν, Πομπηΐῳ μὲν εἴκοσι καὶ δύο μόνον, Κουρίωνι δὲ πάντες οἱ λοιποὶ προσέθεντο. κἀκεῖνος μὲν ὡς νενικηκὼς λαμπρὸς ὑπὸ χαρᾶς εἰς τὸν δῆμον ἐξήλατο, κρότῳ καὶ βολαῖς στεφάνων καὶ ἀνθῶν δεξιούμενον αὐτόν, ἐν δὲ τῇ βουλῇ Πομπήϊος οὐ παρῆν οἱ γὰρ ἄρχοντες στρατοπέδων εἰς τὴν πόλιν οὐκ εἰσίασι. Μάρκελλος δὲ ἀναστὰς οὐκ ἔφη λόγων ἀκροάσεσθαι καθήμενος, ἀλλ’ ὁρῶν ὑπερφαινόμενα τῶν Ἄλπεων ἤδη δέκα τάγματα βαδίζειν, καὶ αὐτὸς ἐκπέμψειν τὸν ἀντιταξόμενον αὐτοῖς ὑπὲρ τῆς πατρίδος.", "st": "Pomp. 58.3"}, {"sp": "N", "t": "ἐκ τούτου τὰς ἐσθῆτας ὡς ἐπὶ πένθει μετεβάλοντο. Μάρκελλος δὲ πρὸς Πομπήϊον δι’ ἀγορᾶς ἐβάδιζε τῆς βουλῆς ἑπομένης, καὶ καταστὰς ἐναντίος, κελεύω σε, εἶπεν, ὦ Πομπήϊε, βοηθεῖν τῇ πατρίδι καὶ χρῆσθαι ταῖς παρεσκευασμέναις δυνάμεσι καὶ καταλέγειν ἑτέρας. τὰ δ’ αὐτὰ ταῦτα καὶ Λέντλος ἔλεγε, τῶν ἀποδεδειγμένων εἰς τὸ μέλλον ὑπάτων ἅτερος. ἀρξαμένου δὲ τοῦ Πομπηΐου καταλέγειν οἱ μὲν οὐχ ὑπήκουον, ὀλίγοι δὲ γλίσχρως καὶ ἀπροθύμως συνῄεσαν, οἱ δὲ πλείους διαλύσεις ἐβόων. καὶ γὰρ ἀνέγνω τινὰ Καίσαρος ἐπιστολὴν Ἀντώνιος ἐν τῷ δήμῳ, βιασάμενος τὴν βουλήν, ἔχουσαν ἐπαγωγοὺς ὄχλου προκλήσεις, ἠξίου γὰρ ἀμφοτέρους ἐκβάντας τῶν ἐπαρχιῶν καὶ τὰς στρατιωτικὰς δυνάμεις ἀφέντας ἐπὶ τῷ δήμῳ γενέσθαι καὶ τῶν πεπραγμένων εὐθύνας ὑποσχεῖν. οἱ δὲ περὶ Λέντλον ὑπατεύοντες ἤδη βουλὴν οὐ συνῆγον ἄρτι δὲ ἐκ Κιλικίας ἀφιγμένος Κικέρων ἔπραττε διαλλαγάς, ὅπως Καῖσαρ, ἐξελθὼν Γαλατίας καὶ τὴν ἄλλην στρατιὰν ἀφεὶς πᾶσαν, ἐπὶ δυσὶ τάγμασι καὶ τῷ Ἰλλυρικῷ τὴν δευτέραν ὑπατείαν περιμένῃ. Πομπηΐου δὲ δυσκολαίνοντος ἐπείσθησαν οἱ Καίσαρος φίλοι θάτερον ἀφεῖναι· Λέντλου δὲ ἀντικρούσαντος καὶ Κάτωνος αὖθις ἁμαρτάνειν τὸν Πομπήϊον ἐξαπατώμενον βοῶντος οὐκ ἔσχον αἱ διαλύσεις πέρας.", "st": "Pomp. 59.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ ἀπαγγέλλεται Καῖσαρ Ἀρίμινον, πόλιν μεγάλην τῆς Ἰταλίας, κατειληφὼς καὶ βαδίζων ἄντικρυς ἐπὶ τὴν Ῥώμην μετά πάσης τῆς δυνάμεως, τοῦτο δὲ ἦν ψεῦδος, ἐβάδιζε γὰρ οὐ πλείονας ἔχων ἱππέων τριακοσίων καὶ πεντακισχιλίων ὁπλιτῶν· τὴν δὲ ἄλλην δύναμιν ἐπέκεινα τῶν Ἄλπεων οὖσαν οὐ περιέμενεν, ἐμπεσεῖν ἄφνω τεταραγμένοις καὶ μὴ προσδοκῶσι βουλόμενος μᾶλλον ἢ χρόνον δοὺς ἐκ παρασκευῆς μάχεσθαι. καὶ γὰρ ἐπὶ τὸν Ῥουβίκωνα ποταμὸν ἐλθών, ὃς ἀφώριζεν αὐτῷ τὴν δεδομένην ἐπαρχίαν, ἔστη σιωπῇ καὶ διεμέλλησεν, αὐτὸς ἄρα πρὸς ἑαυτὸν συλλογιζόμενος τὸ μέγεθος τοῦ τολμήματος, εἶτα, ὥσπερ οἱ πρὸς βάθος ἀφιέντες ἀχανὲς ἀπὸ κρημνοῦ τινος ἑαυτούς, μύσας τῷ λογισμῷ καὶ παρακαλυψάμενος πρὸς τὸ δεινόν, καὶ τοσοῦτον μόνον Ἑλληνιστὶ πρὸς τοὺς παρόντας ἐκβοήσας, ἀνερρίφθω κύβος, διεβίβαζε τὸν στρατόν.", "st": "Pomp. 60.1"}, {"sp": "N", "t": "ὡς δὲ πρῶτον ἡ φήμη προσέπεσε καὶ κατέσχε τὴν Ῥώμην μετά ἐκπλήξεως θόρυβος καὶ φόβος οἷος οὔπω πρότερον, εὐθὺς μὲν ἡ βουλὴ φερομένη πρὸς τὸν Πομπήϊον συνέτρεχε καὶ παρῆσαν αἱ ἀρχαί, πυθομένου δὲ τοῦ Τύλλου περὶ στρατιᾶς καὶ δυνάμεως καὶ τοῦ Πομπηΐου μετά τινος μελλήσεως ἀθαρσῶς εἰπόντος ὅτι τοὺς παρὰ Καίσαρος ἥκοντας ἑτοίμους ἔχει, νομίζει δὲ καὶ τοὺς κατειλεγμένους πρότερον ἐν τάχει συνάξειν τρισμυρίους ὄντας, ὁ μὲν Τύλλος ἀναβοήσας, Ἐξηπάτηκας ἡμᾶς, ὦ Πομπήϊε, συνεβούλευεν ὡς Καίσαρα πρέσβεις ἀποστέλλειν, Φαώνιος δέ τις, ἀνὴρ τἆλλα μὲν οὐ πονηρός, αὐθαδείᾳ δὲ καὶ ὕβρει πολλάκις τὴν Κάτωνος οἰόμενος ἀπομιμεῖσθαι παρρησίαν, ἐκέλευε τὸν Πομπήϊον τῷ ποδὶ τύπτειν τὴν γῆν, ἃς ὑπισχνεῖτο δυνάμεις ἀνακαλούμενον. ὁ δὲ ταύτην μὲν ἤνεγκε τὴν ἀκαιρίαν πρᾴως· τοῦ δὲ Κάτωνος ὑπομιμνήσκοντος ὧν ἐν ἀρχῇ περὶ Καίσαρος αὐτῷ προεῖπεν, ἀπεκρίνατο μαντικώτερα μὲν εἶναι τὰ Κάτωνι λεχθέντα, φιλικώτερα δὲ ὑπ’ αὐτοῦ πεπρᾶχθαι.", "st": "Pomp. 60.3"}, {"sp": "N", "t": "Κάτων δὲ συνεβούλευεν αἱρεῖσθαι στρατηγὸν αὐτοκράτορα Πομπήϊον, ἐπειπὼν ὅτι τῶν αὐτῶν ἐστι καὶ ποιεῖν τὰ μεγάλα κακὰ καὶ παύειν. οὗτος μὲν οὖν εὐθὺς ἐξῆλθεν εἰς Σικελίαν ἔλαχε γὰρ αὐτὴν τῶν ἐπαρχιῶν καὶ τῶν ἄλλων ἕκαστος εἰς ἃς ἐκληρώθη. τῆς δ’ Ἰταλίας σχεδὸν ὅλης ἀνισταμένης ἀπορίαν εἶχε τὸ γινόμενον. οἱ μὲν γὰρ ἔξωθεν φερόμενοι φυγῇ πανταχόθεν εἰς τὴν Ῥώμην ἐνέπιπτον, οἱ δὲ τὴν Ῥώμην οἰκοῦντες ἐξέπιπτον αὐτοὶ καὶ ἀπέλειπον τὴν πόλιν, ἐν χειμῶνι καὶ ταράχῳ τοσούτῳ τὸ μὲν χρήσιμον ἀσθενὲς ἔχουσαν, τὸ δὲ ἀπειθὲς ἰσχυρὸν καὶ δυσμεταχείριστον τοῖς ἄρχουσιν. οὐ γὰρ ἦν παῦσαι τὸν φόβον, οὐδὲ εἴασέ τις χρῆσθαι τοῖς ἑαυτοῦ λογισμοῖς Πομπήϊον, ἀλλ’ ᾧ τις ἐνετύγχανε πάθει, φοβηθεὶς ἢ λυπηθεὶς ἢ διαπορήσας, τούτῳ φέρων ἐκεῖνον ἀνεπίμπλη· καὶ τἀναντία τῆς αὐτῆς ἡμέρας ἐκράτει βουλεύματα, καὶ πυθέσθαι περὶ τῶν πολεμίων οὐδὲν ἦν ἀληθὲς αὐτῷ διὰ τὸ πολλοὺς ἀπαγγέλλειν ὅ τι τύχοιεν, εἶτα ἀπιστοῦντι χαλεπαίνειν. οὕτω δὴ ψηφισάμενος ταραχὴν ὁρᾶν καὶ κελεύσας ἅπαντας ἕπεσθαι αὐτῷ τοὺς ἀπὸ βουλῆς, καὶ προειπὼν ὅτι Καίσαρος ἡγήσεται τὸν ἀπολειφθέντα, περὶ δείλην ὀψίαν ἀπέλιπε τὴν πόλιν. οἱ δὲ ὕπατοι μηδὲ θύσαντες ἃ νομίζεται πρὸ πολέμων ἔφυγον. ἦν δὲ καὶ παρ’ αὐτὰ τὰ δεινὰ ζηλωτὸς ἀνὴρ τῆς πρὸς αὐτὸν εὐνοίας τῶν ἀνθρώπων, ὅτι πολλῶν τὴν στρατηγίαν μεμφομένων οὐδεὶς ἦν ὁ μισῶν τὸν στρατηγόν, ἀλλὰ πλείονας ἄν τις εὗρε τῶν διὰ τὴν ἐλευθερίαν φευγόντων τοὺς ἀπολιπεῖν Πομπήϊον μὴ δυναμένους.", "st": "Pomp. 61.1"}, {"sp": "N", "t": "ὀλίγαις δὲ ὕστερον ἡμέραις Καῖσαρ εἰσελάσας καὶ κατασχὼν τὴν Ῥώμην τοῖς μὲν ἄλλοις ἐπιεικῶς ἐνέτυχε καὶ κατεπράϋνε, τῶν δὲ δημάρχων ἑνὶ Μετέλλῳ κωλύοντι χρήματα λαβεῖν αὐτὸν ἐκ τοῦ ταμιείου θάνατον ἠπείλησε, καὶ προσέθηκε τῇ ἀπειλῇ τραχύτερον λόγον ἔφη γὰρ ὡς τοῦτο φῆσαι χαλεπὸν ἦν αὐτῷ μᾶλλον ἢ πρᾶξαι. τρεψάμενος δὲ τὸν Μέτελλον οὕτω, καὶ λαβὼν ὧν ἔχρῃζεν, ἐδίωκε Πομπήϊον, ἐκβαλεῖν σπεύδων ἐκ τῆς Ἰταλίας πρὶν ἀφικέσθαι τὴν ἐξ Ἰβηρίας αὐτῷ δύναμιν. ὁ δὲ τὸ Βρεντέσιον κατασχὼν καὶ πλοίων εὐπορήσας τοὺς μὲν ὑπάτους εὐθὺς ἐμβιβάσας καὶ μετ’ αὐτῶν σπείρας τριάκοντα προεξέπεμψεν εἰς Δυρράχιον, Σκηπίωνα δὲ τὸν πενθερὸν καὶ Γναῖον τὸν υἱὸν εἰς Συρίαν ἀπέστειλε ναυτικὸν κατασκευάσοντας. αὐτὸς δὲ φραξάμενος τὰς πύλας καὶ τοῖς τείχεσι τοὺς ἐλαφροτάτους στρατιώτας ἐπιστήσας, τοὺς δὲ Βρεντεσίνους ἀτρεμεῖν κατ’ οἰκίαν κελεύσας. ὅλην ἐντὸς τὴν πόλιν ἀνέσκαψε καὶ διετάφρευσε, καὶ σκολόπων ἐνέπλησε τοὺς στενωποὺς πλὴν δυεῖν, δι’ ὧν ἐπὶ θάλατταν αὐτὸς κατῆλθεν. ἡμέρᾳ δὲ τρίτῃ τὸν μὲν ἄλλον ὄχλον ἐν ταῖς ναυσὶν εἶχεν ἤδη καθ’ ἡσυχίαν ἐμβεβηκότα, τοῖς δὲ τὰ τείχη φυλάττουσιν ἐξαίφνης σημεῖον ἄρας καὶ καταδραμόντας ὀξέως ἀναλαβὼν ἀπεπέρασεν. ὁ δὲ Καῖσαρ, ὡς εἶδεν ἐκλελειμμένα τὰ τείχη, τὴν φυγὴν αἰσθόμενος μικροῦ μὲν ἐδέησε διώκων τοῖς σταυροῖς καὶ τοῖς ὀρύγμασι περιπετὴς γενέσθαι, τῶν δὲ Βρεντεσίνων φρασάντων φυλαττόμενος τὴν πόλιν καὶ κύκλῳ περιϊὼν ἀνηγμένους εὗρε πάντας πλὴν δυεῖν πλοίων στρατιώτας τινὰς οὐ πολλοὺς ἐχόντων.", "st": "Pomp. 62.1"}, {"sp": "N", "t": "οἱ μὲν οὖν ἄλλοι τοῦ Πομπηΐου τὸν ἀπόπλουν ἐν τοῖς ἀρίστοις τίθενται στρατηγήμασιν, αὐτὸς δὲ Καῖσαρ ἐθαύμαζεν ὅτι καὶ πόλιν ἔχων ὀχυρὰν καὶ προσδοκῶν τὰς ἐξ Ἰβηρίας δυνάμεις καὶ θαλασσοκρατῶν ἐξέλιπε καὶ προήκατο τὴν Ἰταλίαν. αἰτιᾶται καὶ Κικέρων ὅτι τὴν Θεμιστοκλέους ἐμιμήσατο στρατηγίαν μᾶλλον ἢ τὴν Περικλέους, τῶν πραγμάτων τούτοις ὁμοίων ὄντων, οὐκ ἐκείνοις. ἐδήλωσε δὲ Καῖσαρ ἔργῳ σφόδρα φοβούμενος τὸν χρόνον· ἔχων γὰρ Νουμέριον Πομπηΐου φίλον ἀπέστειλεν εἰς Βρεντέσιον ἐπὶ τοῖς ἴσοις ἀξιῶν διαλλαγῆναι Νουμέριος δὲ Πομπηΐῳ συνεξέπλευσεν. ἐντεῦθεν ὁ μὲν ἐν ἡμέραις ἑξήκοντα κύριος γεγονὼς ἀναιμωτὶ τῆς Ἰταλίας ὅλης ἐβούλετο μὲν εὐθὺς Πομπήϊον διώκειν, πλοίων δὲ μὴ παρόντων ἀποστρέψας εἰς Ἰβηρίαν ἤλαυνε, τὰς ἐκεῖ δυνάμεις προσαγαγέσθαι βουλόμενος.", "st": "Pomp. 63.1"}, {"sp": "N", "t": "ἐν δὲ τῷ χρόνῳ τούτῳ μεγάλη συνέστη Πομπηΐῳ δύναμις, ἡ μὲν ναυτικὴ καὶ παντελῶς ἀνανταγώνιστος (ἦσαν γὰρ αἱ μάχιμοι πεντακόσιαι, λιβυρνίδων δὲ καὶ κατασκόπων ὑπερβάλλων ἀριθμός), ἱππεῖς δέ, Ῥωμαίων καὶ Ἰταλῶν τὸ ἀνθοῦν, ἑπτακισχίλιοι, γένεσι καὶ πλούτῳ καὶ φρονήμασι διαφέροντες· τὴν δὲ πεζὴν σύμμικτον οὖσαν καὶ μελέτης δεομένην ἐγύμναζεν ἐν Βεροίᾳ καθήμενος οὐκ ἀργός, ἀλλ’ ὥσπερ ἀκμάζοντι χρώμενος αὑτῷ πρὸς τὰ γυμνάσια. μεγάλη γὰρ ἦν ῥοπὴ πρὸς τὸ θαρρεῖν τοῖς ὁρῶσι Πομπήϊον Μάγνον ἑξήκοντα μὲν ἔτη δυεῖν λείποντα γεγενημένον, ἐν δὲ τοῖς ὅπλοις ἁμιλλώμενον πεζόν, εἶτα ἱππότην αὖθις ἑλκόμενόν τε τὸ ξίφος ἀπραγμόνως θέοντι τῷ ἵππῳ καὶ κατακλείοντα πάλιν εὐχερῶς, ἐν δὲ τοῖς ἀκοντισμοῖς οὐ μόνον ἀκρίβειαν, ἀλλὰ καὶ ῥώμην ἐπιδεικνύμενον εἰς μῆκος, ὃ πολλοὶ τῶν νέων οὐχ ὑπερέβαλλον. ἐπεφοίτων δὲ καὶ βασιλεῖς ἐθνῶν καὶ δυνάσται, καὶ τῶν ἀπὸ Ῥώμης ἡγεμονικῶν ἀριθμὸς ἦν ἐντελοῦς βουλῆς περὶ αὐτόν. ἦλθε δὲ καὶ Λαβιηνὸς ἀπολιπὼν Καίσαρα φίλος γεγονὼς καὶ συνεστρατευμένος ἐν Γαλατίᾳ, καὶ Βροῦτος, υἱὸς ὢν Βρούτου τοῦ περὶ Γαλατίαν σφαγέντος, ἀνὴρ μεγαλόφρων καὶ μηδέποτε Πομπήϊον προσειπὼν μηδὲ ἀσπασάμενος πρότερον ὡς φονέα τοῦ πατρός, τότε δὲ ὡς ἐλευθεροῦντι τὴν Ῥώμην ὑπέταξεν ἑαυτόν. Κικέρων δέ, καίπερ ἄλλα γεγραφὼς καὶ βεβουλευμένος, ὅμως κατῃδέσθη μὴ γενέσθαι τοῦ προκινδυνεύοντος ἀριθμοῦ τῆς πατρίδος. ἦλθε δὲ καὶ Τίδιος Σέξτιος, ἐσχατόγηρως ἀνὴρ θάτερον πεπηρωμένος σκέλος, εἰς Μακεδονίαν ὃν τῶν ἄλλων γελώντων καὶ χλευαζόντων, ὁ Πομπήϊος ἰδὼν ἐξανέστη καὶ προσέδραμε, μέγα νομίζων μαρτύριον εἶναι καὶ τοὺς παρ’ ἡλικίαν καὶ παρὰ δύναμιν αἱρουμένους τὸν μετ’ αὐτοῦ κίνδυνον ἀντὶ τῆς ἀσφαλείας.", "st": "Pomp. 64.1"}, {"sp": "N", "t": "ἐπεὶ δὲ βουλῆς γενομένης καὶ γνώμην Κάτωνος εἰπόντος ἐψηφίσαντο μηδένα Ῥωμαίων ἄνευ παρατάξεως ἀναιρεῖν μηδὲ διαρπάζειν πόλιν ὑπήκοον Ῥωμαίοις, ἔτι μᾶλλον ἡ Πομπηΐου μερὶς ἠγαπήθη· καὶ γὰρ οἷς μηδὲν ἦν πρᾶγμα τοῦ πολέμου πόρρω κατοικοῦσιν ἢ δι’ ἀσθένειαν ἀμελουμένοις, τῷ γε βούλεσθαι συγκατετίθεντο καὶ τῷ λόγῳ συνεμάχουν ὑπὲρ τῶν δικαίων, ἡγούμενοι θεοῖς εἶναι καὶ ἀνθρώποις ἐχθρὸν ᾧ μὴ καθ’ ἡδονήν ἐστι νικᾶν Πομπήϊον.", "st": "Pomp. 65.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ Καῖσαρ εὐγνώμονα παρεῖχεν ἑαυτὸν ἐν τῷ κρατεῖν, ὃς καὶ τὰς ἐν Ἰβηρίᾳ τοῦ Πομπηΐου δυνάμεις ἑλὼν καὶ καταπολεμήσας ἀφῆκε τοὺς στρατηγούς, τοῖς δὲ στρατιώταις ἐχρῆτο. καὶ πάλιν ὑπερβαλὼν τὰς Ἄλπεις καὶ διαδραμὼν τὴν Ἰταλίαν εἰς Βρεντέσιον ἧκεν ἐν τροπαῖς ἤδη τοῦ χειμῶνος ὄντος· καὶ διαπεράσας τὸ πέλαγος αὐτὸς μὲν εἰς Ὤρικον παρενέβαλεν, Οὐιβούλλιον δὲ τὸν Πομπηΐου φίλον αἰχμάλωτον ἔχων σὺν ἑαυτῷ πρὸς Πομπήϊον ἀνέστειλε, προκαλούμενος εἰς ἓν συνελθόντας ἀμφοτέρους ἡμέρᾳ τρίτῃ πάντα διαλῦσαι τὰ στρατεύματα καὶ γενομένους φίλους καὶ ὀμόσαντας ἐπανελθεῖν εἰς Ἰταλίαν. ταῦτα Πομπήϊος αὖθις ἐνέδραν ἡγεῖτο· καὶ καταβὰς ὀξέως ἐπὶ θάλατταν κατέλαβε χωρία καὶ τόπους ἕδρας τε τοῖς πεζοῖς στρατοπέδοις ὑπεραλκεῖς ἔχοντα, καὶ ναύλοχα καὶ κατάρσεις ἐπιφόρους τοῖς ἐπιφοιτῶσι διὰ θαλάττης, ὥστε πάντα πνεῖν ἄνεμον Πομπηΐῳ σῖτον ἢ στρατιὰν ἢ χρήματα κομίζοντα, Καίσαρα δὲ δυσχερείαις κατὰ γῆν ὁμοῦ καὶ κατὰ θάλατταν περιεχόμενον ἐξ ἀνάγκης φιλομαχεῖν, καὶ προσβάλλοντα τοῖς ἐρύμασι καὶ προκαλούμενον ἑκάστοτε τὰ μὲν πλεῖστα νικᾶν καὶ κρατεῖν τοῖς ἀκροβολισμοῖς, ἅπαξ δὲ μικροῦ συντριβῆναι καὶ τὴν στρατιὰν ἀποβαλεῖν, τοῦ Πομπηΐου λαμπρῶς ἀγωνισαμένου μέχρι τροπῆς ἁπάντων καὶ φόνου δισχιλίων, βιάσασθαι δὲ καὶ συνεισπεσεῖν μὴ δυνηθέντος ἢ φοβηθέντος, ὥστε εἰπεῖν Καίσαρα πρὸς τοὺς φίλους ὅτι Σήμερον ἂν ἡ νίκη παρὰ τοῖς πολεμίοις ἦν, εἰ τὸν νικῶντα εἶχον.", "st": "Pomp. 65.2"}, {"sp": "N", "t": "ἐπὶ τούτῳ μέγα φρονήσαντες οἱ Πομπηΐου διὰ μάχης ἔσπευδον κριθῆναι. Πομπήϊος δὲ τοῖς μὲν ἔξω βασιλεῦσι καὶ στρατηγοῖς καὶ πόλεσιν ὡς νενικηκὼς ἔγραφε, τὸν δὲ τῆς μάχης κίνδυνον ὠρρώδει, τῷ χρόνῳ καὶ ταῖς ἀπορίαις καταπολεμήσειν νομίζων ἄνδρας ἀμάχους μὲν ἐν τοῖς ὅπλοις καὶ συνειθισμένους νικᾶν μετ’ ἀλλήλων πολὺν ἤδη χρόνον. πρὸς δὲ τὴν ἄλλην στρατείαν καὶ πλάνας καὶ μεταβάσεις καὶ τάφρων ὀρύξεις καὶ τειχῶν οἰκοδομίας ἀπαγορεύοντας ὑπὸ γήρως, καὶ διὰ τοῦτο ταῖς χερσὶν ἐμφῦναι τάχιστα καὶ συμπλακῆναι σπεύδοντας, οὐ μὴν ἀλλὰ πρότερον ἁμῶς γέ πως παρῆγε πείθων τοὺς περὶ αὐτὸν ἀτρεμεῖν ὁ Πομπήϊος· ἐπεὶ δὲ μετὰ τὴν μάχην ὁ Καῖσαρ ὑπὸ τῶν ἀποριῶν ἀναστὰς ἐβάδιζε δι’ Ἀθαμάνων εἰς Θετταλίαν, οὐκέτι καθεκτὸν ἦν τὸ φρόνημα τῶν ἀνδρῶν, ἀλλὰ φεύγειν Καίσαρα βοῶντες οἱ μὲν ἀκολουθεῖν καὶ διώκειν ἐκέλευον, οἱ δὲ διαβαίνειν εἰς Ἰταλίαν, οἱ δὲ θεράποντας εἰς Ῥώμην καὶ φίλους ἔπεμπον οἰκίας προκαταληψομένους ἐγγὺς ἀγορᾶς ὡς αὐτίκα μετιόντες ἀρχάς, ἐθελονταὶ δὲ πολλοὶ πρὸς Κορνηλίαν ἔπλεον εἰς Λέσβον εὐαγγελιζόμενοι πέρας ἔχειν τὸν πόλεμον· ἐκεῖ γὰρ αὐτὴν ὑπεξέπεμψεν ὁ Πομπήϊος.", "st": "Pomp. 66.1"}, {"sp": "N", "t": "ἀθροισθείσης δὲ βουλῆς Ἀφράνιος μὲν ἀπεφαίνετο γνώμην ἔχεσθαι τῆς Ἰταλίας, ταύτην γὰρ εἶναι τοῦ πολέμου τὸ μέγιστον ἆθλον, προστιθέναι δὲ τοῖς κρατοῦσιν εὐθὺς Σικελίαν, Σαρδόνα, Κύρνον, Ἰβηρίαν, Γαλατίαν ἅπασαν ἧς τε δὴ πλεῖστος ὁ λόγος Πομπηΐῳ πατρίδος ὀρεγούσης χεῖρας ἐγγύθεν, οὐ καλῶς ἔχειν περιορᾶν προπηλακιζομένην καὶ δουλεύουσαν οἰκέταις καὶ κόλαξι τυράννων. αὐτὸς δὲ Πομπήϊος οὔτε πρὸς δόξαν ἡγεῖτο καλὸν αὑτῷ δευτέραν φυγὴν φεύγειν Καίσαρα καὶ διώκεσθαι, τῆς τύχης διώκειν διδούσης, οὔτε ὅσιον ἐγκαταλιπεῖν Σκηπίωνα καὶ τοὺς περὶ τὴν Ἑλλάδα καὶ Θετταλίαν ἄνδρας ὑπατικούς, εὐθὺς ὑπὸ Καίσαρι γενησομένους μετὰ χρημάτων καὶ δυνάμεων μεγάλων, τῆς δὲ Ῥώμης μάλιστα κήδεσθαι τὸν ἀπωτάτω πολεμοῦντα περὶ αὐτῆς, ὅπως ἀπαθὴς κακῶν οὖσα καὶ ἀνήκοος περιμένῃ τὸν κρατοῦντα.", "st": "Pomp. 66.4"}, {"sp": "N", "t": "ταῦτα ψηφισάμενος ἐδίωκε Καίσαρα, μάχης μὲν ἐγνωκὼς ἀπέχεσθαι, πολιορκεῖν δὲ καὶ τρίβειν ταῖς ἀπορίαις ἐγγύθεν ἐπακολουθῶν, καὶ γὰρ ἄλλως ταῦτα συμφέρειν ἡγεῖτο, καὶ λόγος τις εἰς αὐτὸν ἧκεν ἐν τοῖς ἱππεῦσι φερόμενος, ὡς χρὴ τάχιστα τρεψαμένους Καίσαρα συγκαταλύειν κἀκεῖνον αὐτόν. ἔνιοι δέ φασι διὰ τοῦτο καὶ Κάτωνι μηδὲν ἄξιον σπουδῆς χρήσασθαι Πομπήϊον, ἀλλὰ καὶ πορευόμενον ἐπὶ Καίσαρα πρὸς θαλάσσῃ καταλιπεῖν ἐπὶ τῆς ἀποσκευῆς, φοβηθέντα μὴ Καίσαρος ἀναιρεθέντος ἀναγκάσῃ κἀκεῖνον εὐθὺς ἀποθέσθαι τὴν ἀρχήν, οὕτω δὲ παρακολουθῶν ἀτρέμα τοῖς πολεμίοις ἐν αἰτίαις ἦν καὶ καταβοήσεσιν ὡς οὐ Καίσαρα καταστρατηγῶν, ἀλλὰ τὴν πατρίδα καὶ τὴν βουλήν, ὅπως διὰ παντὸς ἄρχῃ καὶ μηδέποτε παύσηται τοῖς ἀξιοῦσι τῆς οἰκουμένης ἄρχειν χρώμενος ὑπηρέταις καὶ δορυφόροις. Δομέτιος δὲ αὐτὸν Ἀηνόβαρβος Ἀγαμέμνονα καλῶν καὶ βασιλέα βασιλέων ἐπίφθονον ἐποίει. καὶ Φαώνιος οὐχ ἧττον ἦν ἀηδὴς τῶν παρρησιαζομένων· ἀκαίρως ἐν τῷ σκώπτειν, ἄνθρωποι, βοῶν, οὐδὲ τῆτες ἔσται τῶν ἐν Τουσκλάνῳ σύκων μεταλαβεῖν; Λεύκιος δὲ Ἀφράνιος ὁ τὰς ἐν Ἰβηρίᾳ δυνάμεις ἀποβαλὼν ἐν αἰτίᾳ προδοσίας γεγονώς, τότε δὲ τὸν Πομπήϊον ὁρῶν φυγομαχοῦντα, θαυμάζειν ἔλεγε τοὺς κατηγοροῦντας αὐτοῦ, πῶς πρὸς τὸν ἔμπορον τῶν ἐπαρχιῶν οὐ μάχονται προελθόντες.", "st": "Pomp. 67.1"}, {"sp": "N", "t": "ταῦτα καὶ τὰ τοιαῦτα πολλὰ λέγοντες ἄνδρα δόξης ἥττονα καὶ τῆς πρὸς τοὺς φίλους αἰδοῦς τὸν Πομπήϊον ἐξεβιάσαντο καὶ συνεπεσπάσαντο ταῖς ἑαυτῶν ἐλπίσι καὶ ὁρμαῖς ἐπακολουθῆσαι, προέμενον τοὺς ἀρίστους λογισμούς, ὅπερ οὐδὲ πλοίου κυβερνήτῃ, μήτιγε τοσούτων ἐθνῶν καὶ δυνάμεων αὐτοκράτορι στρατηγῷ παθεῖν ἦν προσῆκον. ὁ δὲ τῶν μὲν ἰατρῶν τοὺς μηδέποτε χαριζομένους ταῖς ἐπιθυμίαις ἐπῄνεσεν, αὐτὸς δὲ τῷ νοσοῦντι τῆς στρατιᾶς ἐνέδωκε, δείσας ἐπὶ σωτηρίᾳ λυπηρὸς γενέσθαι, πῶς γὰρ ἄν τις φήσειεν ὑγιαίνειν ἐκείνους τοὺς ἄνδρας, ὧν οἱ μὲν ὑπατείας ἤδη καὶ στρατηγίας ἐν τῷ στρατοπέδῳ περινοστοῦντες ἐμνῶντο, Σπινθῆρι δὲ καὶ Δομετίῳ καὶ Σκηπίωνι περὶ τῆς Καίσαρος ἀρχιερωσύνης ἔριδες ἦσαν καὶ φιλονεικίαι καὶ δεξιώσεις; ὥσπερ αὐτοῖς Τιγράνου τοῦ Ἀρμενίου παραστρατοπεδεύοντος ἢ τοῦ Ναβαταίων βασιλέως, ἀλλ’ οὐ Καίσαρος ἐκείνου καὶ τῆς δυνάμεως ᾗ χιλίας μὲν ᾑρήκει πόλεις κατὰ κράτος, ἔθνη δὲ πλείονα τριακοσίων ὑπῆκτο, Γερμανοῖς δὲ καὶ Γαλάταις μεμαχημένος ἀήττητος ὅσας οὐκ ἄν τις ἀριθμήσαι μάχας ἑκατὸν μυριάδας αἰχμαλώτων ἔλαβεν, ἑκατὸν δὲ ἀπέκτεινε τρεψάμενος ἐκ παρατάξεως.", "st": "Pomp. 67.4"}, {"sp": "N", "t": "ἀλλ’ ὅμως ἐγκείμενοι καὶ θορυβοῦντες, ἐπεὶ κατέβησαν εἰς τὸ Φαρσάλιον πεδίον, ἠνάγκασαν βουλὴν προθεῖναι τὸν Πομπήϊον, ἐν ᾗ Λαβιηνὸς ὁ τῶν ἱππέων ἄρχων πρῶτος ἀναστὰς ὤμοσε μὴ ἀναχωρήσειν ἐκ τῆς μάχης, εἰ μὴ τρέψαιτο τοὺς πολεμίους· τὰ δὲ αὐτὰ καὶ πάντες ὤμνυσαν. τῆς δὲ νυκτὸς ἔδοξε κατὰ τοὺς ὕπνους Πομπήϊος εἰς τὸ θέατρον εἰσιόντος αὐτόν κροτεῖν τὸν δῆμον, αὐτὸς δὲ κοσμεῖν ἱερὸν Ἀφροδίτης νικηφόρου πολλοῖς λαφύροις. καὶ τὰ μὲν ἐθάρρει, τὰ δὲ ὑπέθραττεν αὐτὸν ἡ ὄψις, δεδοικότα μὴ τῷ γένει τῷ Καίσαρος εἰς Ἀφροδίτην ἀνήκοντι δόξα καὶ λαμπρότης ἀπ’ αὐτοῦ γένηται· καὶ πανικοί τινες θόρυβοι διᾴττοντες ἐξανέστησαν αὐτόν. ἑωθινῆς δὲ φυλακῆς ὑπὲρ τοῦ Καίσαρος στρατοπέδου πολλὴν ἡσυχίαν ἄγοντος ἐξέλαμψε μέγα φῶς, ἐκ δὲ τούτου λαμπὰς ἀρθεῖσα φλογοειδὴς ἐπὶ τὸ Πομπηΐου κατέσκηψε· καὶ τοῦτο ἰδεῖν φησι Καῖσαρ αὐτὸς ἐπιὼν τὰς φυλακάς. ἅμα δὲ ἡμέρᾳ, μέλλοντος αὐτοῦ πρὸς Σκοτοῦσαν ἀναζευγνύειν καὶ τὰς σκηνὰς τῶν στρατιωτῶν καθαιρούντων καὶ προπεμπόντων ὑποζύγια καὶ θεράποντας, ἧκον οἱ σκοποὶ φράζοντες ὅπλα πολλὰ καθορᾶν ἐν τῷ χάρακι τῶν πολεμίων διαφερόμενα, καὶ κίνησιν εἶναι καὶ θόρυβον ἀνδρῶν ἐπὶ μάχην ἐξιόντων. μετὰ δὲ τούτους ἕτεροι παρῆσαν εἰς τάξιν ἤδη καθίστασθαι τοὺς πρώτους λέγοντες, ὁ μὲν οὖν Καῖσαρ εἰπὼν τὴν προσδοκωμένην ἥκειν ἡμέραν, ἐν ᾗ πρὸς ἄνδρας, οὐ πρὸς λιμὸν οὐδὲ πενίαν μαχοῦνται, κατὰ τάχος πρὸ τῆς σκηνῆς ἐκέλευσε προθεῖναι τὸν φοινικοῦν χιτῶνα· τοῦτο γὰρ μάχης Ῥωμαίοις ἐστὶ σύμβολον. οἱ δὲ στρατιῶται θεασάμενοι μετὰ βοῆς καὶ χαρᾶς τὰς σκηνὰς ἀφέντες ἐφέροντο πρὸς τὰ ὅπλα. καὶ τῶν ταξιαρχῶν ἀγόντων εἰς ἣν ἔδει τάξιν, ἕκαστος, ὥσπερ χορός, ἄνευ θορύβου μεμελετημένως εἰς τάξιν καὶ πρᾴως καθίστατο.", "st": "Pomp. 68.1"}, {"sp": "N", "t": "Πομπήϊος δὲ τὸ μὲν δεξιὸν αὐτὸς ἔχων ἔμελλεν ἀνθίστασθαι πρὸς Ἀντώνιον, ἐν δὲ τῷ μέσῳ Σκηπίωνα τὸν πενθερὸν ἀντέταξε Καλβίνῳ Λευκίῳ, τὸ δὲ εὐώνυμον εἶχε μὲν Λεύκιος Δομέτιος, ἐρρώσθη δὲ τῷ πλήθει τῶν ἱππέων. ἐνταῦθα γὰρ ὀλίγου δεῖν ἅπαντες ἐρρύησαν ὡς Καίσαρα βιασόμενοι καὶ τὸ δέκατον τάγμα διακόψοντες, οὗ πλεῖστος ἦν ὁ λόγος ὡς μαχιμωτάτου, καὶ Καῖσαρ ἐν ἐκείνῳ ταττόμενος εἰώθει μάχεσθαι. κατιδὼν δὲ πεφραγμένον ἵππῳ τοσαύτῃ τῶν πολεμίων τὸ εὐώνυμον, καὶ φοβηθεὶς τὴν λαμπρότητα τοῦ ὁπλισμοῦ, μετεπέμψατο σπείρας ἓξ ἀπὸ τῶν ἐπιταγμάτων καὶ κατέστησεν ὄπισθεν τοῦ δεκάτου, κελεύσας ἡσυχίαν ἄγειν ἀδήλους τοῖς πολεμίοις ὄντας· ὅταν δὲ προσελαύνωσιν οἱ ἱππεῖς, διὰ τῶν προμάχων ἐκδραμόντας μὴ προέσθαι τοὺς ὑσσούς, ὥσπερ εἰώθασιν οἱ κράτιστοι σπεύδοντες ἐπὶ τὰς ξιφουλκίας, ἀλλὰ παίειν ἄνω συντιτρώσκοντας ὄμματα καὶ πρόσωπα τῶν πολεμίων οὐ γὰρ μενεῖν τοὺς καλοὺς τούτους καὶ ἀνθηροὺς πυρριχιστὰς διὰ τὸν ὡραϊσμόν, οὐδὲ ἀντιβλέψειν πρὸς τὸν σίδηρον ἐν ὀφθαλμοῖς γινόμενον. ἐν τούτοις μὲν οὖν ὁ Καῖσαρ ἦν.", "st": "Pomp. 69.1"}, {"sp": "N", "t": "ὁ δὲ Πομπήϊος ἀφ’ ἵππου τὴν παράταξιν ἐπισκοπῶν, ὡς ἑώρα τοὺς μὲν ἀντιπάλους μεθ’ ἡσυχίας τὸν καιρὸν ἐν τάξει προσμένοντας, τῆς δ’ ὑφ’ αὑτῷ στρατιᾶς τὸ πλεῖστον οὐκ ἀτρεμοῦν, ἀλλὰ κυμαῖνον ἀπειρίᾳ καὶ θορυβούμενον, ἔδεισε μὴ διασπασθῇ παντάπασιν ἐν ἀρχῇ τῆς μάχης, καὶ παράγγελμα τοῖς προτεταγμένοις ἔδωκεν ἑστῶτας ἐν προβολῇ καὶ μένοντας ἀραρότως δέχεσθαι τοὺς πολεμίους. ὁ δὲ Καῖσαρ αἰτιᾶται τὸ στρατήγημα τοῦτο· τῶν τε γὰρ πληγῶν τὸν ἐξ ἐπιδρομῆς τόνον ἀμαυρῶσαι, καὶ τὴν μάλιστα τοὺς πολλοὺς ἐν τῷ συμφέρεσθαι τοῖς πολεμίοις πληροῦσαν ἐνθουσιασμοῦ καὶ φορᾶς ἀντεξόρμησιν, ἅμα κραυγῇ καὶ δρόμῳ τὸν θυμὸν αὔξουσαν, ἀφελόντα πῆξαι καὶ καταψῦξαι τοὺς ἄνδρας, ἦσαν δὲ οἱ μὲν μετὰ Καίσαρος δισχίλιοι πρὸς δισμυρίοις, οἱ δὲ μετὰ Πομπηΐου βραχεῖ πλείονες ἢ διπλάσιοι τούτων.", "st": "Pomp. 69.4"}, {"sp": "N", "t": "ἤδη δὲ συνθήματος διδομένου παρὰ ἀμφοτέρων καί τῆς σάλπιγγος ἀρχομένης ἐγκελεύεσθαι πρὸς τὴν σύστασιν, τῶν μὲν πολλῶν ἕκαστος ἐσκόπει τὸ καθ’ αὑτόν, ὀλίγοι δὲ Ῥωμαίων οἱ βέλτιστοι καί τινες Ἑλλήνων παρόντες ἔξω τῆς μάχης, ὡς ἐγγὺς ἦν τὸ δεινόν, ἐλογίζοντο τὴν πλεονεξίαν καί φιλονεικίαν, ὅπου φέρουσα τὴν ἡγεμονίαν ἐξέθηκεν. ὅπλα γὰρ συγγενικὰ καί τάξεις ἀδελφαὶ καί κοινὰ σημεῖα καί μιᾶς πόλεως εὐανδρία τοσαύτη καί δύναμις αὐτὴ πρὸς ἑαυτὴν συνέπιπτεν, ἐπιδεικνυμένη τὴν ἀνθρωπίνην φύσιν, ὡς ἐν πάθει γενομένη τυφλόν ἐστι καὶ μανιῶδες, ἦν μὲν γὰρ ἤδη καθ’ ἡσυχίαν χρῄζουσιν ἄρχειν καί ἀπολαύειν τῶν κατειργασμένων τὸ πλεῖστον καί κράτιστον ἀρετῇ γῆς καί θαλάσσης ὑπήκοον, ἦν δ’ ἔτι τροπαίων καί θριάμβων ἔρωτι βουλομένους χαρίζεσθαι καί διψῶντας ἐμπίπλασθαι Παρθικῶν πολέμων ἢ Γερμανικῶν. πολὺ δὲ καί Σκυθία λειπόμενον ἔργον καί Ἰνδοί, καὶ πρόφασις οὐκ ἄδοξος ἐπὶ ταῦτα τῆς πλεονεξίας ἡμερῶσαι τὰ βαρβαρικά, τίς δ’ ἂν ἢ Σκυθῶν ἵππος ἢ τοξεύματα Πάρθων ἢ πλοῦτος Ἰνδῶν ἐπέσχε μυριάδας ἑπτὰ Ῥωμαίων ἐν ὅπλοις ἐπερχομένας Πομπηΐου καί Καίσαρος ἡγουμένων, ὧν ὄνομα πολὺ πρότερον ἤκουσαν ἢ τὸ Ῥωμαίων; οὕτως ἄμικτα καί ποικίλα καί θηριώδη φῦλα νικῶντες ἐπῆλθον. τότε δὲ ἀλλήλοις μαχούμενοι συνῄεσαν, οὐδὲ τὴν δόξαν αὑτῶν, δι’ ἣν τῆς πατρίδος ἠφείδουν, οἰκτείραντες, ἄχρι τῆς ἡμέρας ἐκείνης ἀνικήτων προσαγορευομένων. ἡ μὲν γὰρ γενομένη συγγένεια καί τὰ Ἰουλίας φίλτρα καί γάμος ἐκεῖνος εὐθὺς ἦν ἀπατηλὰ καί ὕποπτα κοινωνίας ἐπὶ χρείᾳ συνισταμένης ὁμηρεύματα, φιλίας δ’ ἀληθινῆς οὐ μετέσχεν.", "st": "Pomp. 70.1"}, {"sp": "N", "t": "ὡς δ’ οὖν τὸ Φαρσάλιον πεδίον ἀνδρῶν καὶ ἵππων καὶ ὅπλων ἀνεπέπληστο καὶ μάχης ἤρθη παρ’ ἀμφοτέρων σημεῖα, πρῶτος ἐκ τῆς Καίσαρος φάλαγγος ἐξέδραμε Γάϊος Κρασσιανός, ἀνδρῶν ἑκατὸν εἴκοσι λοχαγῶν, μεγάλην ἀποδιδοὺς ὑπόσχεσιν Καίσαρι. πρῶτον γὰρ αὐτὸν ἐξιὼν τοῦ χάρακος εἶδε, καὶ προσαγορεύσας ἤρετο πῶς φρονοίη περὶ τῆς μάχης, ὁ δὲ τὴν δεξιὰν προτείνας ἀνεβόησε· νικήσεις λαμπρῶς, ὦ Καῖσαρ· ἐμὲ δὲ ἢ ζῶντα τήμερον ἢ νεκρὸν ἐπαινέσεις. τούτων τῶν λόγων μεμνημένος ἐξώρμησε καὶ συνεπεσπάσατο πολλοὺς καὶ προσέβαλε κατὰ μέσους τοὺς πολεμίους. γενομένου δὲ τοῦ ἀγῶνος εὐθὺς ἐν ξίφεσι καὶ πολλῶν φονευομένων, βιαζόμενον πρόσω καὶ διακόπτοντα τοὺς πρώτους ὑποστάς τις ὠθεῖ διὰ τοῦ στόματος τὸ ξίφος, ὥστε τὴν αἰχμὴν περάσασαν ἀνασχεῖν κατὰ τὸ ἰνίον.", "st": "Pomp. 71.1"}, {"sp": "N", "t": "πεσόντος δὲ τοῦ Κρασσιανοῦ, κατὰ τοῦτο μὲν ἦν ἰσόρροπος ἡ μάχη, τὸ δὲ δεξιὸν ὁ Πομπήϊος οὐ ταχέως ἐπῆγεν, ἀλλὰ παπταίνων ἐπὶ θάτερα καὶ τὸ τῶν ἱππέων ἀναμένων ἔργον ἐνδιέτριβεν. ἤδη δὲ ἐκεῖνοι τοὺς οὐλαμοὺς ἀνῆγον ὡς κυκλωσόμενοι τὸν Καίσαρα, καὶ τοὺς προτεταγμένους ἱππεῖς ὀλίγους ὄντας ἐμβαλοῦντες εἰς τὴν φάλαγγα. Καίσαρος δὲ σημεῖον ἄραντος, οἱ μὲν ἱππεῖς ἐξανεχώρησαν, αἱ δὲ ἐπιτεταγμέναι σπεῖραι πρὸς τὴν κύκλωσιν ἐκδραμοῦσαι, τρισχίλιοι ἄνδρες, ὑπαντιάζουσι τοὺς πολεμίους, καὶ παριστάμενοι καθ’ ἵππων, ὡς ἐδιδάχθησαν, ὑψηλοῖς ἐχρῶντο τοῖς ὑσσοῖς, ἐφιέμενοι τῶν προσώπων. οἱ δέ, ἅτε μάχης πάσης ἄπειροι, τοιαύτην δὲ μὴ προσδοκήσαντες μηδὲ προμαθόντες, οὐκ ἐτόλμων οὐδὲ ἠνείχοντο τὰς πληγὰς ἐν ὄμμασι καὶ στόμασιν οὔσας, ἀλλ’ ἀποστρεφόμενοι καὶ προϊσχόμενοι τῶν ὄψεων τὰς χεῖρας ἀκλεῶς ἐτράποντο. φευγόντων δὲ τούτων ἀμελήσαντες οἱ Καίσαρος ἐχώρουν ἐπὶ τοὺς πεζούς, ᾗ μάλιστα τῶν ἱππέων τὸ κέρας ἐψιλωμένον περιδρομὴν ἐδίδου καὶ κύκλωσιν. ἅμα δὲ τούτων ἐκ πλαγίου προσπεσόντων καὶ κατὰ στόμα τοῦ δεκάτου προσμίξαντος οὐχ ὑπέμειναν οὐδὲ συνέστησαν, ὁρῶντες ἐν ᾧ κυκλώσεσθαι τοὺς πολεμίους ἤλπιζον αὑτοὺς τοῦτο πάσχοντας.", "st": "Pomp. 71.4"}, {"sp": "N", "t": "τραπομένων δὲ τούτων, ὡς κατεῖδε τὸν κονιορτὸν ὁ Πομπήϊος καὶ τὸ περὶ τοὺς ἱππέας πάθος εἴκασεν, ᾧ μὲν ἐχρήσατο λογισμῷ χαλεπὸν εἰπεῖν, μάλιστα δὲ ὅμοιος παράφρονι καὶ παραπλῆγι τὴν διάνοιαν, καὶ μηδ’ ὅτι Μάγνος ἐστὶ Πομπήϊος ἐννοοῦντι, μηδένα προσειπὼν ἀπῄει βάδην εἰς τὸν χάρακα, πάνυ τοῖς ἔπεσι πρέπων ἐκείνοις·", "st": "Pomp. 72.1"}, {"sp": "N", "t": "Ζεὺς δὲ πατὴρ Αἴανθ’ ὑψίζυγος ἐν φόβον ὦρσε·<br>στῆ δὲ ταφών, ὄπιθεν δὲ σάκος βάλεν ἑπταβόειον,<br>τρέσσε δὲ παπτήνας ἐφ’ ὁμίλου.", "st": "Pomp. 72.2"}, {"sp": "N", "t": "τοιοῦτος εἰς τὴν σκηνὴν παρελθὼν ἄφθογγος καθῆστο, μέχρι οὗ τοῖς φεύγουσι πολλοὶ διώκοντες συνεισέπιπτον τότε δὲ φωνὴν μίαν ἀφεὶς ταύτην, οὐκοῦν καὶ ἐπὶ τὴν παρεμβολήν; ἄλλο δὲ μηδὲν εἰπών ἀναστὰς καὶ λαβὼν ἐσθῆτα τῇ παρούσῃ τύχῃ πρέπουσαν ὑπεξῆλθεν. ἔφυγε δὲ καὶ τὰ λοιπὰ τάγματα, καὶ φόνος ἐν τῷ στρατοπέδῳ πολὺς ἐγένετο σκηνοφυλάκων καὶ θεραπόντων στρατιώτας δὲ μόνους ἑξακισχιλίους πεσεῖν φησιν Ἀσίννιος Πολλίων, μεμαχημένος ἐκείνην τὴν μάχην μετὰ Καίσαρος.", "st": "Pomp. 72.3"}, {"sp": "N", "t": "αἱροῦντες δὲ τὸ στρατόπεδον ἐθεῶντο τὴν ἄνοιαν καὶ κουφότητα τῶν πολεμίων, πᾶσα γὰρ σκηνὴ μυρσίναις κατέστεπτο καὶ στρωμναῖς ἀνθιναῖς ἤσκητο καὶ τραπέζαις ἐκπωμάτων μεσταῖς καὶ κρατῆρες οἴνου προὔκειντο, καὶ παρασκευὴ καὶ κόσμος ἦν τεθυκότων καὶ πανηγυριζόντων μᾶλλον ἢ πρὸς μάχην ἐξοπλιζομένων. οὕτω ταῖς ἐλπίσι διεφθαρμένοι καὶ γέμοντες ἀνοήτου θράσους ἐπὶ τὸν πόλεμον ἐχώρουν.", "st": "Pomp. 72.4"}, {"sp": "N", "t": "Πομπήϊος δὲ μικρὸν ἔξω τοῦ χάρακος προελθὼν τὸν μὲν ἵππον ἀφῆκεν, ὀλίγων δὲ κομιδῇ περὶ αὑτὸν ὄντων, ὡς οὐδεὶς ἐδίωκεν, ἀπῄει καθ’ ἡσυχίαν, ἐν διαλογισμοῖς ὢν οἵους εἰκὸς λαμβάνειν ἄνθρωπον ἔτη τέτταρα καὶ τριάκοντα νικᾶν καὶ κρατεῖν ἁπάντων εἰθισμένον, ἥττης δὲ καὶ φυγῆς τότε πρῶτον ἐν γήρᾳ λαμβάνοντα πεῖραν, ἐννοούμενον δὲ ἐξ ὅσων ἀγώνων καὶ πολέμων ηὐξημένην ἀποβαλὼν ὥρᾳ μιᾷ δόξαν καὶ δύναμιν, ὁ πρὸ μικροῦ τοσούτοις ὅπλοις καὶ ἵπποις καὶ στόλοις δορυφορούμενος ἀπέρχεται μικρὸς οὕτω γεγονὼς καὶ συνεσταλμένος ὥστε λανθάνειν ζητοῦντας τοὺς πολεμίους, παραμειψάμενος δὲ Λάρισσαν, ὡς ἦλθεν ἐπὶ τὰ Τέμπη, καταβαλὼν ἑαυτὸν ἐπὶ στόμα δεδιψηκὼς ἔπινε τοῦ ποταμοῦ, καὶ πάλιν ἀναστὰς ἐβάδιζε διὰ τῶν Τεμπῶν, ἄχρι οὗ κατῆλθεν ἐπὶ θάλατταν.", "st": "Pomp. 73.1"}, {"sp": "N", "t": "ἐκεῖ δὲ τῆς νυκτὸς τὸ λοιπὸν ἀναπαυσάμενος ἐν καλυβίῳ τινὶ σαγηνέων, καὶ περὶ τὸν ὄρθρον ἐπιβὰς ποταμίου πλοίου, καὶ τῶν ἑπομένων τοὺς ἐλευθέρους ἀναλαβὼν, τοὺς δὲ θεράποντας ἀπιέναι πρὸς Καίσαρα κελεύσας καὶ μὴ δεδιέναι, παρὰ γῆν κομιζόμενος εἶδεν εὐμεγέθη φορτηγὸν ἀνάγεσθαι μέλλουσαν, ἧς ἐναυκλήρει Ῥωμαῖος ἀνὴρ οὐ πάνυ Πομπηΐῳ συνήθης, γινώσκων δὲ τὴν ὄψιν αὐτοῦ· Πετίκιος ἐπεκαλεῖτο. τούτῳ συνεβεβήκει τῆς παρῳχημένης νυκτὸς ἰδεῖν κατὰ τοὺς ὕπνους Πομπήϊον, οὐχ ὃν ἑωράκει πολλάκις, ἀλλὰ ταπεινὸν καὶ κατηφῆ, προσδιαλεγόμενον αὐτῷ. καὶ ταῦτα τοῖς συμπλέουσιν ἐτύγχανε διηγούμενος, ὡς δὴ φιλεῖ περὶ πραγμάτων τηλικούτων λόγον ἔχειν ἀνθρώπους σχολὴν ἄγοντας. ἐξαίφνης δέ τις τῶν ναυτῶν ἔφρασε κατιδὼν ὅτι πλοῖον ποτάμιον ἀπὸ τῆς γῆς ἐρέσσεται καὶ κατασείουσί τινες ἄνθρωποι τὰ ἱμάτια καὶ τὰς χεῖρας ὀρέγουσι πρὸς αὐτούς, ἐπιστήσας οὖν ὁ Πετίκιος εὐθὺς ἔγνω τὸν Πομπήϊον, οἷον ὄναρ εἶδε· καὶ πληξάμενος τὴν κεφαλὴν ἐκέλευσε τοὺς ναύτας τὸ ἐφόλκιον παραβαλεῖν, καὶ τὴν δεξιὰν ἐξέτεινε καὶ προσεκάλει τὸν Πομπήϊον, ἤδη συμφρονῶν τῷ σχήματι τὴν τύχην καὶ μεταβολὴν τοῦ ἀνδρός. ὅθεν οὔτε παράκλησιν ἀναμείνας οὔτε λόγον, ἀλλ’ ἀναλαβὼν ὅσους ἐκέλευσε μετ’ αὐτοῦ (Λέντουλοι δὲ ἦσαν ἀμφότεροι καὶ Φαώνιος) ἀνήχθη· καὶ μικρὸν ὕστερον ἰδόντες ἀπὸ γῆς ἁμιλλώμενον Δηϊόταρον τὸν βασιλέα προσαναλαμβάνουσιν.", "st": "Pomp. 73.3"}, {"sp": "N", "t": "ἐπεὶ δὲ καιρὸς ἦν δείπνου καὶ παρεσκεύασεν ὁ ναύκληρος ἐκ τῶν παρόντων, ἰδὼν ὁ Φαώνιος οἰκετῶν ἀπορίᾳ τὸν Πομπήϊον ἀρχόμενον αὑτὸν ὑπολύειν προσέδραμε καὶ ὑπέλυσε καὶ συνήλειψε. καὶ τὸ λοιπὸν ἐκ τούτου περιέπων καὶ θεραπεύων ὅσα δεσπότας δοῦλοι, μέχρι νίψεως ποδῶν καὶ δείπνου παρασκευῆς, διετέλεσεν, ὥστε τὴν ἐλευθεριότητα τῆς ὑπουργίας ἐκείνης θεασάμενον ἄν τινα καὶ τὸ ἀφελὲς καὶ ἄπλαστον εἰπεῖν·", "st": "Pomp. 73.7"}, {"sp": "N", "t": "φεῦ τοῖσι γενναίοισιν ὡς ἅπαν καλόν.", "st": "Pomp. 73.7b"}, {"sp": "N", "t": "οὕτω δὲ παραπλεύσας ἐπ’ Ἀμφιπόλεως ἐκεῖθεν εἰς Μιτυλήνην ἐπεραιοῦτο, βουλόμενος τὴν Κορνηλίαν ἀναλαβεῖν καὶ τὸν υἱόν. ἐπεὶ δὲ προσέσχε τῇ νήσῳ κατ’ αἰγιαλόν, ἔπεμψεν εἰς πόλιν ἄγγελον, οὐχ ὡς ἡ Κορνηλία προσεδόκα τοῖς πρὸς χάριν ἀπαγγελλομένοις καὶ γραφομένοις, ἐλπίζουσα τοῦ πολέμου κεκριμένου περὶ Δυρράχιον ἔτι λοιπὸν ἔργον εἶναι Πομπηΐῳ τὴν Καίσαρος δίωξιν. ἐν τούτοις οὖσαν αὑτὴν καταλαβὼν ὁ ἄγγελος ἀσπάσασθαι μὲν οὐχ ὑπέμεινε, τὰ δὲ πλεῖστα καὶ μέγιστα τῶν κακῶν τοῖς δάκρυσι μᾶλλον ἢ τῇ φωνῇ φράσας σπεύδειν ἐκέλευσεν, εἰ βούλεταί πως Πομπήϊον ἰδεῖν ἐπὶ νεὼς μιᾶς καὶ ἀλλοτρίας, ἡ δὲ ἀκούσασα προήκατο μὲν αὑτὴν χαμᾶζε καὶ πολὺν χρόνον ἔκφρων καὶ ἄναυδος ἔκειτο, μόλις δέ πως ἔμφρων γενομένη καὶ συννοήσασα τὸν καιρὸν οὐκ ὄντα θρήνων καὶ δακρύων, ἐξέδραμε διὰ τῆς πόλεως ἐπὶ θάλατταν. ἀπαντήσαντος δὲ τοῦ Πομπηΐου καὶ δεξαμένου ταῖς ἀγκάλαις αὑτὴν ὑπερειπομένην καὶ περιπίπτουσαν, ὁρῶ σε, εἶπεν, ἄνερ, οὐ τῆς σῆς τύχης ἔργον, ἀλλὰ τῆς ἐμῆς, προσερριμμένον ἑνὶ σκάφει τὸν πρὸ τῶν Κορνηλίας γάμων πεντακοσίαις ναυσὶ ταύτην περιπλεύσαντα τὴν θάλασσαν, τί μ’ ἦλθες ἰδεῖν καὶ οὐκ ἀπέλιπες τῷ βαρεῖ δαίμονι τὴν καὶ σὲ δυστυχίας ἀναπλήσασαν τοσαύτης; ὡς εὐτυχὴς μὲν ἂν ἤμην γυνὴ πρὸ τοῦ Πόπλιον ἐν Πάρθοις ἀκοῦσαι τὸν παρθένιον ἄνδρα κείμενον ἀποθανοῦσα, σώφρων δὲ καὶ μετ’ ἐκεῖνον, ὥσπερ ὥρμησα, τὸν ἐμαυτῆς προεμένη βίον ἐσωζόμην δ’ ἄρα καὶ Πομπηΐῳ Μάγνῳ συμφορὰ γενέσθαι.", "st": "Pomp. 74.1"}, {"sp": "N", "t": "ταῦτα εἰπεῖν τὴν Κορνηλίαν λέγουσι, τὸν δὲ Πομπήϊον ἀποκρίνασθαι μίαν ἄρα, Κορνηλία, τύχην ᾔδεις τὴν ἀμείνονα, ἣ καὶ σὲ ἴσως ἐξηπάτησεν, ὅτι μοι χρόνον πλείονα τοῦ συνήθους παρέμεινεν. ἀλλὰ καὶ ταῦτα δεῖ φέρειν γενομένους ἀνθρώπους, καὶ τῆς τύχης ἔτι πειρατέον. οὐ γὰρ ἀνέλπιστον ἐκ τούτων ἀναλαβεῖν ἐκεῖνα τὸν ἐξ ἐκείνων ἐν τούτοις γενόμενον.", "st": "Pomp. 75.1"}, {"sp": "N", "t": "ἡ μὲν οὖν γυνὴ μετεπέμπετο χρήματα καὶ θεράποντας ἐκ πόλεως· τῶν δὲ Μιτυληναίων τὸν Πομπήϊον ἀσπασαμένων καὶ παρακαλούντων εἰσελθεῖν εἰς τὴν πόλιν, οὐκ ἠθέλησεν, ἀλλὰ κἀκείνους ἐκέλευσε τῷ κρατοῦντι πείθεσθαι καὶ θαρρεῖν εὐγνώμονα γὰρ εἶναι Καίσαρα καὶ χρηστόν. αὐτὸς δὲ πρὸς Κράτιππον τραπόμενος τὸν φιλόσοφον κατέβη γὰρ ἐκ τῆς πόλεως ὀψόμενος αὐτόν, ἐμέμψατο καὶ συνδιηπόρησε βραχέα περὶ τῆς προνοίας, ὑποκατακλινομένου τοῦ Κρατίππου καὶ παράγοντος αὐτὸν ἐπὶ τὰς ἀμείνονας ἐλπίδας, ὅπως μὴ λυπηρὸς μηδὲ ἄκαιρος ἀντιλέγων εἴη. ἐπεὶ τὸ μὲν ἐρέσθαι τὸν Πομπήϊον ἦν ὑπὲρ τῆς προνοίας, τὸν δ’ ἀποφαίνεσθαι ὅτι τοῖς πράγμασιν ἤδη μοναρχίας ἔδει διὰ τὴν κακοπολιτείαν ἐρέσθαι δέ· πῶς, ὦ Πομπήϊε, καὶ τίνι τεκμηρίῳ πεισθῶμεν ὅτι βέλτιον ἂν σὺ τῇ τύχῃ Καίσαρος ἐχρήσω κρατήσας; ἀλλὰ ταῦτα μὲν ἐατέον ὥσπερ ἔχει, τὰ τῶν θεῶν.", "st": "Pomp. 75.2"}, {"sp": "N", "t": "ἀναλαβὼν δὲ τὴν γυναῖκα καὶ τοὺς φίλους ἐκομίζετο, προσίσχων ὅρμοις ἀναγκαίοις ὕδωρ ἢ ἀγορὰν ἔχουσιν. εἰς δὲ πόλιν εἰσῆλθε πρώτην Ἀττάλειαν τῆς Παμφυλίας, ἐνταῦθα δὲ αὐτῷ καὶ τριήρεις τινὲς ἀπήντησαν ἐκ Κιλικίας καὶ στρατιῶται συνελέγοντο καὶ τῶν συγκλητικῶν πάλιν ἑξήκοντα περὶ αὐτὸν ἦσαν. ἀκούων δὲ καὶ τὸ ναυτικὸν ἔτι συνεστάναι, καὶ Κάτωνα πολλοὺς στρατιώτας ἀνειληφότα περαιοῦν εἰς Λιβύην, ὠδύρετο πρὸς τοὺς φίλους, καταμεμφόμενος ἑαυτὸν ἐκβιασθέντα τῷ πεζῷ συμβαλεῖν, τῇ δὲ κρείττονι ἀδηρίτως δυνάμει πρὸς μηδὲν ἀποχρήσασθαι μηδὲ περιορμίσαι τὸ ναυτικόν, ὅπου κατὰ γῆν σφαλεὶς εὐθὺς ἂν εἶχεν ἀντίπαλον ἐκ θαλάττης παρεστῶσαν ἀλκὴν καὶ δύναμιν τοσαύτην. οὐδὲν γὰρ ἁμάρτημα Πομπηΐου μεῖζον οὐδὲ δεινότερον στρατήγημα Καίσαρος ἢ τὸ τὴν μάχην οὕτω μακρὰν ἀποσπάσασθαι τῆς ναυτικῆς βοηθείας, οὐ μὴν ἀλλ’ ἐκ τῶν παρόντων κρίνειν τι καὶ πράττειν ἀναγκαζόμενος, ἐπὶ τὰς πόλεις περιέπεμπε τὰς δ’ αὐτὸς περιπλέων ᾔτει χρήματα καὶ ναῦς ἐπλήρου. τὴν δ’ ὀξύτητα τοῦ πολεμίου καὶ τὸ τάχος δεδοικώς, μὴ προαναρπάσῃ τῆς παρασκευῆς αὐτὸν ἐπελθών, ἐσκόπει καταφυγὴν ἐπὶ τῷ παρόντι καὶ ἀναχώρησιν. ἐπαρχία μὲν οὖν οὐδεμία φύξιμος ἐφαίνετο βουλευομένοις αὐτοῖς, τῶν δὲ βασιλειῶν αὐτὸς μὲν ἀπέφαινε τὴν Πάρθων ἱκανωτάτην οὖσαν ἔν τε τῷ παρόντι δέξασθαι καὶ περιβαλεῖν σφᾶς ἀσθενεῖς ὄντας, αὖθίς τε ῥῶσαι καὶ προπέμψαι μετὰ πλείστης δυνάμεως· τῶν δ’ ἄλλων οἱ μὲν εἰς Λιβύην καὶ Ἰόβαν ἔτρεπον τὴν γνώμην, Θεοφάνει δὲ τῷ Λεσβίῳ μανικὸν ἐδόκει τριῶν ἡμερῶν πλοῦν ἀπέχουσαν Αἴγυπτον ἀπολιπόντα καὶ Πτολεμαῖον, ἡλικίαν μὲν ἀντίπαιδα, φιλίας δὲ καὶ χάριτος πατρῴας ὑπόχρεων, Πάρθοις ὑποβαλεῖν ἑαυτόν, ἀπιστοτάτῳ γένει, καὶ Ῥωμαίῳ μὲν ἀνδρὶ κηδεστῇ γενομένῳ τὰ δεύτερα λέγοντα πρῶτον εἶναι τῶν ἄλλων μὴ θέλειν μηδὲ πειρᾶσθαι τῆς ἐκείνου μετριότητος, Ἀρσάκην δὲ ποιεῖσθαι κύριον ἑαυτοῦ τὸν μηδὲ Κράσσου δυνηθέντα ζῶντος· καὶ γυναῖκα νέαν οἴκου τοῦ Σκηπίωνος εἰς βαρβάρους κομίζειν ὕβρει καὶ ἀκολασίᾳ τὴν ἐξουσίαν μετροῦντας, ᾗ, κἂν μὴ πάθῃ, δόξῃ δὲ παθεῖν, δεινόν ἐστιν ἐπὶ τοῖς ποιῆσαι δυναμένοις γενομένῃ, τοῦτο μόνον, ὥς φασιν, ἀπέτρεψε τῆς ἐπὶ τὸν Εὐφράτην ὁδοῦ Πομπήϊον εἰ δή τις ἔτι Πομπηΐου λογισμός, ἀλλ’ οὐχὶ δαίμων ἐκείνην ὑφηγεῖτο τὴν ὁδόν.", "st": "Pomp. 76.1"}, {"sp": "N", "t": "ὡς δ’ οὖν ἐνίκα φεύγειν εἰς τὴν Αἴγυπτον, ἀναχθεὶς ἀπὸ Κύπρου Σελευκίδι τριήρει μετὰ τῆς γυναικός τῶν δ’ ἄλλων οἱ μὲν ἐν μακραῖς ὁμοίως ναυσίν, οἱ δὲ ἐν ὁλκάσιν ἅμα συμπαρέπλεον, τὸ μὲν πέλαγος διεπέρασεν ἀσφαλῶς, πυθόμενος δὲ τὸν Πτολεμαῖον ἐν Πηλουσίῳ καθῆσθαι μετὰ στρατιᾶς, πολεμοῦντα πρὸς τὴν ἀδελφήν, ἐκεῖ κατέσχε, προπέμψας τὸν φράσοντα τῷ βασιλεῖ καὶ δεησόμενον. ὁ μὲν οὖν Πτολεμαῖος ἦν κομιδῇ νέος· ὁ δὲ πάντα διέπων τὰ πράγματα Ποθεινὸς ἤθροισε βουλὴν τῶν δυνατωτάτων ἐδύναντο δὲ μέγιστον οὓς ἐκεῖνος ἐβούλετο· καὶ λέγειν ἐκέλευσεν ἣν ἔχει γνώμην ἕκαστος, ἦν οὖν δεινὸν περὶ Πομπηΐου Μάγνου βουλεύεσθαι Ποθεινὸν τὸν εὐνοῦχον καὶ Θεόδοτον τὸν Χῖον, ἐπὶ μισθῷ ῥητορικῶν λόγων διδάσκαλον ἀνειλημμένον, καὶ τὸν Αἰγύπτιον Ἀχιλλᾶν κορυφαιότατοι γὰρ ἦσαν ἐν κατευνασταῖς καὶ τιθηνοῖς τοῖς ἄλλοις οὗτοι σύμβουλοι. καὶ τοιούτου δικαστηρίου ψῆφον Πομπήϊος ἐπ’ ἀγκυρῶν πρόσω τῆς χώρας ἀποσαλεύων περιέμενεν, ὃν Καίσαρι σωτηρίας χάριν οὐκ ἦν ἄξιον ὀφείλειν.", "st": "Pomp. 77.1"}, {"sp": "N", "t": "τῶν μὲν οὖν ἄλλων τοσοῦτον αἱ γνῶμαι διέστησαν ὅσον οἱ μὲν ἀπελαύνειν ἐκέλευον, οἱ δὲ καλεῖν καὶ δέχεσθαι τὸν ἄνδρα· Θεόδοτος δὲ δεινότητα λόγου καὶ ῥητορείαν ἐπιδεικνύμενος οὐδέτερον ἀπέφηνεν ἀσφαλές, ἀλλὰ δεξαμένους μὲν ἕξειν Καίσαρα πολέμιον καὶ δεσπότην Πομπήϊον, ἀπωσαμένους δὲ καὶ Πομπηΐῳ τῆς ἐκβολῆς ὑπαιτίους ἔσεσθαι καὶ Καίσαρι τῆς διώξεως· κράτιστον οὖν εἶναι μεταπεμψαμένους ἀνελεῖν τὸν ἄνδρα· καὶ γὰρ ἐκείνῳ χαριεῖσθαι καὶ τοῦτον οὐ φοβήσεσθαι. προσεπεῖπε δὲ διαμειδιάσας, ὥς φασιν, ὅτι νεκρὸς οὐ δάκνει.", "st": "Pomp. 77.4"}, {"sp": "N", "t": "ταῦτα κυρώσαντες ἐπ’ Ἀχιλλᾷ ποιοῦνται τὴν πρᾶξιν. ὁ δὲ Σεπτίμιόν τινα πάλαι γεγονότα Πομπηΐου ταξίαρχον παραλαβών, καὶ Σάλβιον ἕτερον ἑκατοντάρχην καὶ τρεῖς ἢ τέτταρας ὑπηρέτας, ἀνήχθη πρὸς τὴν Πομπηΐου ναῦν. ἔτυχον δὲ πάντες εἰς αὐτὴν οἱ δοκιμώτατοι τῶν συμπλεόντων ἐμβεβηκότες, ὅπως εἰδεῖεν τὸ πραττόμενον. ὡς οὖν εἶδον οὐ βασιλικὴν οὐδὲ λαμπρὰν οὐδὲ ταῖς Θεοφάνους ἐλπίσιν ὁμοίαν ὑποδοχήν, ἀλλ’ ἐπὶ μιᾶς ἁλιάδος προσπλέοντας ὀλίγους ἀνθρώπους, ὑπείδοντο τὴν ὀλιγωρίαν καὶ τῷ Πομπηΐῳ παρῄνουν εἰς πέλαγος ἀνακρούεσθαι τὴν ναῦν, ἕως ἔξω βέλους εἰσίν. ἐν τούτῳ δὲ πελαζούσης τῆς ἁλιάδος φθάσας ὁ Σεπτίμιος ἐξανέστη καὶ Ῥωμαϊστὶ τὸν Πομπήϊον αὐτοκράτορα προσηγόρευσεν. ὁ δὲ Ἀχιλλᾶς ἀσπασάμενος αὐτὸν Ἑλληνιστὶ παρεκάλει μετελθεῖν εἰς τὴν ἁλιάδα· τέναγος γὰρ εἶναι πολύ, καὶ βάθος οὐκ ἔχειν πλόϊμον τριήρει τὴν θάλατταν ὑπόψαμμον οὖσαν. ἅμα δὲ καὶ ναῦς τινες ἑωρῶντο τῶν βασιλικῶν πληρούμεναι, καὶ τὸν αἰγιαλὸν ὁπλῖται κατεῖχον, ὥστ’ ἄφυκτα καὶ μεταβαλλομένοις ἐφαίνετο, καὶ προσῆν τὸ διδόναι τοῖς φονεῦσι τὴν ἀπιστίαν αὐτὴν τῆς ἀδικίας ἀπολογίαν. ἀσπασάμενος οὖν τὴν Κορνηλίαν προαποθρηνοῦσαν αὐτὸν τὸ τέλος, καὶ δύο ἑκατοντάρχας προεμβῆναι κελεύσας καὶ τῶν ἀπελευθέρων ἕνα Φίλιππον καὶ θεράποντα Σκύθην ὄνομα, δεξιουμένων αὐτὸν ἤδη τῶν περὶ τὸν Ἀχιλλᾶν ἐκ τῆς ἁλιάδος, μεταστραφεὶς πρὸς τὴν γυναῖκα καὶ τὸν υἱὸν εἶπε Σοφοκλέους ἰαμβεῖα·", "st": "Pomp. 78.1"}, {"sp": "N", "t": "ὅστις δὲ πρὸς τύραννον ἐμπορεύεται,<br>κείνου ’στὶ δοῦλος, κἂν ἐλεύθερος μόλῃ.", "st": "Pomp. 78.1b"}, {"sp": "N", "t": "ταῦτα δ’ ἔσχατα πρὸς τοὺς ἑαυτοῦ φθεγξάμενος ἐνέβη καὶ συχνοῦ διαστήματος ὄντος ἐπὶ τὴν γῆν ἀπὸ τῆς τριήρους, ὡς οὐδεὶς παρὰ τῶν συμπλεόντων ἐγίνετο λόγος φιλάνθρωπος πρὸς αὐτόν, ἀποβλέψας εἰς τὸν Σεπτίμιον, οὐ δή πού σε, εἶπεν, ἐγὼ γεγονότα συστρατιώτην ἐμὸν ἀμφιγνοῶ; κἀκεῖνος ἐπένευσε τῇ κεφαλῇ μόνον, οὐδὲν προσειπὼν οὐδὲ φιλοφρονηθείς, πολλῆς οὖν πάλιν οὔσης σιωπῆς ὁ Πομπήϊος ἔχων ἐν βιβλίῳ μικρῷ γεγραμμένον ὑπ’ αὐτοῦ λόγον Ἑλληνικόν, ᾧ παρεσκεύαστο χρῆσθαι πρὸς τὸν Πτολεμαῖον, ἀνεγίνωσκεν. ὡς δὲ τῇ γῇ προσεπέλαζον, ἡ μὲν Κορνηλία μετὰ τῶν φίλων ἐκ τῆς τριήρους περιπαθὴς οὖσα τὸ μέλλον ἀπεσκοπεῖτο, καὶ θαρρεῖν ἤρχετο πολλοὺς ὁρῶσα πρὸς τὴν ἀπόβασιν τῶν βασιλικῶν οἷον ἐπὶ τιμῇ καὶ δεξιώσει συνερχομένους, ἐν τούτῳ δὲ τὸν Πομπήϊον τῆς τοῦ Φιλίππου λαμβανόμενον χειρός, ὅπως ῥᾷον ἐξανασταίη, Σεπτίμιος ὄπισθεν τῷ ξίφει διελαύνει πρῶτος, εἶτα Σάλβιος μετ’ ἐκεῖνον, εἶτα Ἀχιλλᾶς ἐσπάσαντο τὰς μαχαίρας δὲ ταῖς χερσὶν ἀμφοτέραις τὴν τήβεννον ἐφελκυσάμενος κατὰ τοῦ προσώπου, μηδὲν εἰπὼν ἀνάξιον ἑαυτοῦ μηδὲ ποιήσας, ἀλλὰ στενάξας μόνον, ἐνεκαρτέρησε ταῖς πληγαῖς, ἑξήκοντα μὲν ἑνὸς δέοντα βεβιωκὼς ἔτη, μιᾷ δ’ ὕστερον ἡμέρᾳ τῆς γενεθλίου τελευτήσας τὸν βίον.", "st": "Pomp. 79.1"}, {"sp": "N", "t": "οἱ δ’ ἀπὸ τῶν νεῶν ὡς ἐθεάσαντο τὸν φόνον, οἰμωγὴν ἐξάκουστον ἄχρι τῆς γῆς ἐκχέαντες ἔφυγον, ἀράμενοι τὰς ἀγκύρας κατὰ τάχος, καὶ πνεῦμα λαμπρὸν ἐβοήθει πελαγίοις ὑπεκθέουσιν, ὥστε βουλομένους διώκειν ἀποτραπέσθαι τοὺς Αἰγυπτίους. τοῦ δὲ Πομπηΐου τὴν μὲν κεφαλὴν ἀποτέμνουσι, τὸ δὲ ἄλλο σῶμα γυμνὸν ἐκβαλόντες ἀπὸ τῆς ἁλιάδος τοῖς δεομένοις τοιούτου θεάματος ἀπέλιπον. παρέμεινε δὲ αὐτῷ Φίλιππος, ἕως ἐγένοντο μεστοὶ τῆς ὄψεως· εἶτα περιλούσας τῇ θαλάσσῃ τὸ σῶμα καὶ χιτωνίῳ τινὶ τῶν ἑαυτοῦ περιστείλας, ἄλλο δὲ οὐδὲν ἔχων, ἀλλὰ περισκοπῶν τὸν αἰγιαλὸν εὗρε μικρᾶς ἁλιάδος λείψανα, παλαιὰ μέν, ἀρκοῦντα δὲ νεκρῷ γυμνῷ καὶ οὐδὲ ὅλῳ πυρκαϊὰν ἀναγκαίαν παρασχεῖν. ταῦτα συγκομίζοντος αὐτοῦ καὶ συντιθέντος ἐπιστὰς ἀνὴρ Ῥωμαῖος ἤδη γέρων, τὰς δὲ πρώτας στρατείας ἔτι νέος Πομπηΐῳ συνεστρατευμένος, τίς ὤν, ὦ ἄνθρωπε, ἔφη, θάπτειν διανοῇ Μάγνον Πομπήϊον; ἐκείνου δὲ φήσαντος ὡς ἀπελεύθερος, ἀλλ’ οὐ μόνῳ σοί, ἔφη, τοῦτο τὸ καλὸν ὑπάρξει· κἀμὲ δὲ ὥσπερ εὑρήματος εὐσεβοῦς δέξαι κοινωνόν, ὡς μὴ κατὰ πάντα μέμφωμαι τὴν ἀποξένωσιν, ἀντὶ πολλῶν ἀνιαρῶν τοῦτο γοῦν εὑράμενος, ἅψασθαι καὶ περιστεῖλαι ταῖς ἐμαῖς χερσὶ τὸν μέγιστον αὐτοκράτορα Ῥωμαίων. οὕτω μὲν ἐκηδεύετο Πομπήϊος, τῇ δ’ ὑστεραίᾳ Λεύκιος Λέντλος οὐκ εἰδὼς τὰ πεπραγμένα, πλέων ἀπὸ Κύπρου καὶ παρὰ γῆν κομιζόμενος, ὡς εἶδε νεκροῦ πυρὰν καὶ παρεστῶτα τὸν Φίλιππον, οὔπω καθορώμενος· τίς ἄρα, ἔφη, τὸ πεπρωμένον ἐνταῦθα τελέσας ἀναπέπαυται; καὶ μικρὸν διαλιπὼν καὶ στενάξας, τάχα δέ, εἶπε, σύ, Πομπήϊε Μάγνε. καὶ μετὰ μικρὸν ἀποβὰς καὶ συλληφθεὶς ἀπέθανε.", "st": "Pomp. 80.1"}, {"sp": "N", "t": "τοῦτο Πομπηΐου τέλος, οὐ πολλῷ δὲ ὕστερον Καῖσαρ ἐλθὼν εἰς Αἴγυπτον ἄγους τοσούτου καταπεπλησμένην τὸν μὲν προσφέροντα τὴν κεφαλὴν ὡς παλαμναῖον ἀπεστράφη, τὴν δὲ σφραγῖδα τοῦ Πομπηΐου δεξάμενος ἐδάκρυσεν ἦν δὲ γλυφὴ λέων ξιφήρης. Ἀχιλλᾶν δὲ καὶ Ποθεινὸν ἀπέσφαξεν αὐτὸς δὲ ὁ βασιλεὺς μάχῃ λειφθεὶς περὶ τὸν ποταμὸν ἠφανίσθη. Θεόδοτον δὲ τὸν σοφιστὴν ἡ μὲν ἐκ Καίσαρος δίκη παρῆλθε· φυγὼν γὰρ Αἴγυπτον ἐπλανᾶτο ταπεινὰ πράττων καὶ μισούμενος· Βροῦτος δὲ Μάρκος, ὅτε Καίσαρα κτείνας ἐκράτησεν, ἐξευρὼν αὐτὸν ἐν Ἀσίᾳ καὶ πᾶσαν αἰκίαν αἰκισάμενος ἀπέκτεινεν. τὰ δὲ λείψανα τοῦ Πομπηΐου Κορνηλία δεξαμένη κομισθέντα, περὶ τὸν Ἀλβανὸν ἔθηκεν.", "st": "Pomp. 80.5"}, {"sp": "HDR", "t": "Ἀγησιλάου καὶ Πομπηΐου σύγκρισις"}, {"sp": "N", "t": "ἐκκειμένων οὖν τῶν βίων ἐπιδράμωμεν τῷ λόγῳ ταχέως τὰ ποιοῦντα τὰς διαφοράς, παρ’ ἄλληλα συνάγοντες, ἔστι δὲ ταῦτα· πρῶτον, ὅτι Πομπήϊος ἐκ τοῦ δικαιοτάτου τρόπου παρῆλθεν εἰς δύναμιν καὶ δόξαν, αὐτὸς ὁρμηθεὶς ἀφ’ ἑαυτοῦ καὶ πολλὰ καὶ μεγάλα Σύλλᾳ τὴν Ἰταλίαν ἀπὸ τῶν τυράννων ἐλευθεροῦντι συγκατεργασάμενος, Ἀγησίλαος δὲ τὴν βασιλείαν ἔδοξε λαβεῖν οὔτε τὰ πρὸς θεοὺς ἄμεμπτος οὔτε τὰ πρὸς ἀνθρώπους, κρίνας νοθείας Λεωτυχίδην, ὃν υἱὸν αὑτοῦ ἀπέδειξεν ἀδελφὸς γνήσιον, τὸν δὲ χρησμὸν κατειρωνευσάμενος τὸν περὶ τῆς χωλότητος. δεύτερον, ὅτι Πομπήϊος Σύλλαν καὶ ζῶντα τιμῶν διετέλεσε καὶ τεθνηκότος ἐκήδευσε βιασάμενος Λέπιδον τὸ σῶμα, καὶ τῷ παιδὶ Φαύστῳ τὴν αὑτοῦ θυγατέρα συνῴκισεν, Ἀγησίλαος δὲ Λύσανδρον ἐκ τῆς τυχούσης προφάσεως ὑπεξέρριψε καὶ καθύβρισε. καίτοι Σύλλας μὲν οὐκ ἐλαττόνων ἔτυχεν ἢ Πομπηΐῳ παρέσχεν, Ἀγησίλαον δὲ Λύσανδρος καὶ τῆς Σπάρτης βασιλέα καὶ τῆς Ἑλλάδος στρατηγὸν ἐποίησε. τρίτον δέ, αἱ περὶ τὰ πολιτικὰ τῶν δικαίων παραβάσεις Πομπηΐῳ μὲν δι’ οἰκειότητας ἐγένοντο· τὰ γὰρ πλεῖστα Καίσαρι καὶ Σκηπίωνι συνεξήμαρτε κηδεσταῖς οὖσιν· Ἀγησίλαος δὲ Σφοδρίαν μὲν ἐφ’ οἷς Ἀθηναίους ἠδίκησεν ἀποθανεῖν ὀφείλοντα τῷ τοῦ παιδὸς ἔρωτι χαριζόμενος ἐξήρπασε, Φοιβίδᾳ δὲ Θηβαίους παρασπονδήσαντι δῆλος ἦν δι’ αὐτὸ τὸ ἀδίκημα προθύμως βοηθῶν· καθόλου δὲ ὅσα Ῥωμαίους δι’ αἰδῶ Πομπήϊος ἢ ἄγνοιαν αἰτίαν ἔσχε βλάψαι, ταῦτα θυμῷ καὶ φιλονεικίᾳ Λακεδαιμονίους Ἀγησίλαος ἔβλαψε τὸν Βοιώτιον ἐκκαύσας πόλεμον.", "st": "Comp. Ages.–Pomp. 1.1"}, {"sp": "N", "t": "εἰ δὲ καὶ τύχην τινὰ τῶν ἀνδρῶν ἑκατέρου τοῖς σφάλμασι προσοιστέον, ἀνέλπιστος μὲν ἡ Πομπηΐου Ῥωμαίοις, Ἀγησίλαος δὲ Λακεδαιμονίους ἀκούοντας καὶ προειδότας οὐκ εἴασε φυλάξασθαι τὴν χωλὴν βασιλείαν. καὶ γὰρ εἰ μυριάκις ἠλέγχθη Λεωτυχίδης ἀλλότριος εἶναι καὶ νόθος, οὐκ ἂν ἠπόρησαν Εὐρυπωντίδαι γνήσιον καὶ ἀρτίποδα τῇ Σπάρτῃ βασιλέα παρασχεῖν, εἰ μὴ δι’ Ἀγησίλαον ἐπεσκότησε τῷ χρησμῷ Λύσανδρος.", "st": "Comp. Ages.–Pomp. 2.1"}, {"sp": "N", "t": "οἷον μέντοι τῇ περὶ τῶν τρεσάντων ἀπορίᾳ προσήγαγεν ὁ Ἀγησίλαος ἴαμα μετὰ τὴν ἐν Λεύκτροις ἀτυχίαν, κελεύσας τοὺς νόμους ἐκείνην τὴν ἡμέραν καθεύδειν, οὐ γέγονεν ἄλλο σόφισμα πολιτικόν, οὐδ’ ἔχομέν τι τοῦ Πομπηΐου παραπλήσιον, ἀλλὰ τοὐναντίον οὐδ’ οἷς αὐτὸς ἐτίθει νόμοις ᾤετο δεῖν ἐμμένειν, τὸ δύνασθαι μέγα τοῖς φίλοις ἐνδεικνύμενος, ὁ δὲ εἰς ἀνάγκην καταστὰς τοῦ λῦσαι τοὺς νόμους ἐπὶ τῷ σῶσαι τοὺς πολίτας, ἐξεῦρε τρόπον ᾧ μήτε ἐκείνους βλάψουσι μήτε ὅπως οὐ βλάψωσι λυθήσονται. τίθεμαι δὲ κἀκεῖνο τὸ ἀμίμητον ἔργον εἰς πολιτικὴν ἀρετὴν τοῦ Ἀγησιλάου, τὸ δεξάμενον τὴν σκυτάλην ἀπολιπεῖν τὰς ἐν Ἀσίᾳ πράξεις, οὐ γάρ, ὡς Πομπήϊος, ἀφ’ ὧν ἑαυτὸν ἐποίει μέγαν ὠφέλει τὸ κοινόν, ἀλλὰ τὸ τῆς πατρίδος σκοπῶν τηλικαύτην ἀφῆκε δύναμιν καὶ δόξαν ἡλίκην οὐδεὶς πρότερον οὐδὲ ὕστερον πλὴν Ἀλέξανδρος ἔσχεν.", "st": "Comp. Ages.–Pomp. 2.2"}, {"sp": "N", "t": "ἀπ’ ἄλλης τοίνυν ἀρχῆς, ἐν ταῖς στρατηγίαις καὶ τοῖς πολεμικοῖς, ἀριθμῷ μὲν τροπαίων καὶ μεγέθει δυνάμεων ἃς ἐπηγάγετο Πομπήϊος, καὶ πλήθει παρατάξεων ἃς ἐνίκησεν, οὐδ’ ἂν ὁ Ξενοφῶν μοι δοκεῖ παραβαλεῖν τὰς Ἀγησιλάου νίκας, ᾧ διὰ τἆλλα καλὰ καθάπερ γέρας ἐξαίρετον δέδοται καὶ γράφειν ὃ βούλοιτο καὶ λέγειν περὶ τοῦ ἀνδρός. οἶμαι δὲ καὶ τῇ πρὸς τοὺς πολεμίους ἐπιεικείᾳ διαφέρειν τὸν ἄνδρα τοῦ ἀνδρός. ὁ μὲν γὰρ ἀνδραποδίσασθαι Θήβας καὶ Μεσσήνην ἐξοικίσασθαι βουλόμενος, ἣν μὲν ὁμόκληρον τῆς πατρίδος, ἣν δὲ μητρόπολιν τοῦ γένους, παρ’ οὐδὲν ἦλθε τὴν Σπάρτην ἀποβαλεῖν, ἀπέβαλε δὲ τὴν ἡγεμονίαν ὁ δὲ καὶ τῶν πειρατῶν τοῖς μεταβαλομένοις πόλεις ἔδωκε, καὶ Τιγράνην τὸν Ἀρμενίων βασιλέα γενόμενον ἐφ’ ἑαυτῷ θριαμβεῦσαι σύμμαχον ἐποιήσατο, φήσας ἡμέρας μιᾶς αἰῶνα προτιμᾶν.", "st": "Comp. Ages.–Pomp. 3.1"}, {"sp": "N", "t": "εἰ μέντοι τοῖς μεγίστοις καὶ κυριωτάτοις εἰς τὰ ὅπλα πράγμασι καὶ λογισμοῖς προστίθεται πρωτεῖον ἀρετῆς ἀνδρὸς ἡγεμόνος, οὐ μικρὸν ὁ Λάκων τὸν Ῥωμαῖον ἀπολέλοιπε. πρῶτον μὲν γὰρ οὐ προήκατο τὴν πόλιν οὐδ’ ἐξέλιπεν ἑπτὰ μυριάσι στρατοῦ τῶν πολεμίων ἐμβαλόντων, ὀλίγους ἔχων ὁπλίτας καὶ προνενικημένους ἐν Λεύκτροις· Πομπήϊος δέ, πεντακισχιλίοις μόνοις καὶ τριακοσίοις μίαν Καίσαρος πόλιν Ἰταλικὴν καταλαβόντος, ἐξέπεσε τῆς Ῥώμης ὑπὸ δέους, ἢ τοσούτοις εἴξας ἀγεννῶς ἢ πλείονας ψευδῶς εἰκάσας· καὶ συσκευασάμενος τὰ τέκνα καὶ τὴν γυναῖκα αὑτοῦ, τὰς δὲ τῶν ἄλλων πολιτῶν ἐρήμους ἀπολιπὼν ἔφυγε, δέον ἢ κρατεῖν μαχόμενον ὑπὲρ τῆς πατρίδος ἢ δέχεσθαι διαλύσεις παρὰ τοῦ κρείττονος· ἦν γὰρ πολίτης καὶ οἰκεῖος· νῦν δὲ ᾧ στρατηγίας χρόνον ἐπιμετρῆσαι καὶ ὑπατείαν ψηφίσασθαι δεινὸν ἡγεῖτο, τούτῳ παρέσχε λαβόντι τὴν πόλιν εἰπεῖν πρὸς Μέτελλον ὅτι κἀκεῖνον αἰχμάλωτον αὑτοῦ νομίζει καὶ τοὺς ἄλλους ἅπαντας.", "st": "Comp. Ages.–Pomp. 3.3"}, {"sp": "N", "t": "ὃ τοίνυν ἔργον ἐστὶν ἀγαθοῦ στρατηγοῦ μάλιστα, κρείττονα μὲν ὄντα βιάσασθαι τοὺς πολεμίους μάχεσθαι, λειπόμενον δὲ δυνάμει μὴ βιασθῆναι, τοῦτο ποιῶν Ἀγησίλαος ἀεὶ διεφύλαξεν ἑαυτὸν ἀνίκητον· Πομπήϊον δὲ Καῖσαρ, οὗ μὲν ἦν ἐλάττων, διέφυγε μὴ βλαβῆναι, καθὸ δὲ κρείττων ἦν, ἠνάγκασεν ἀγωνισάμενον τῷ πεζῷ περὶ πάντων σφαλῆναι, καὶ κύριος εὐθὺς ἦν χρημάτων καὶ ἀγορᾶς καὶ θαλάττης, ὑφ’ ὧν διεπέπρακτο ἂν ἄνευ μάχης ἐκείνοις προσόντων. τὸ δ’ ὑπὲρ τούτων ἀπολόγημα μέγιστόν ἐστιν ἔγκλημα στρατηγοῦ τηλικούτου. νέον μὲν γὰρ ἄρχοντα θορύβοις καὶ καταβοήσεσιν εἰς μαλακίαν καὶ δειλίαν ἐπιταραχθέντα τῶν ἀσφαλεστάτων ἐκπεσεῖν λογισμῶν εἰκός ἐστι καὶ συγγνωστόν Πομπήϊον δὲ Μάγνον, οὗ Ῥωμαῖοι τὸ μὲν στρατόπεδον πατρίδα, σύγκλητον δὲ τὴν σκηνήν, ἀποστάτας δὲ καὶ προδότας τοὺς ἐν Ῥώμῃ πολιτευομένους καὶ στρατηγοῦντας καὶ ὑπατεύοντας ἐκάλουν, ἀρχόμενον δὲ ὑπ’ οὐδενὸς ἔγνωσαν, πάσας δὲ αὐτοκράτορα στρατευσάμενον ἄριστα τὰς στρατείας, τίς ἂν ἀνάσχοιτο τοῖς Φαωνίου σκώμμασι καὶ Δομετίου, καὶ ἵνα μὴ Ἀγαμέμνων λέγηται, παρ’ ἐλάχιστον ἐκβιασθέντα τὸν περὶ τῆς ἡγεμονίας καὶ ἐλευθερίας ἀναρρῖψαι κίνδυνον;", "st": "Comp. Ages.–Pomp. 4.1"}, {"sp": "N", "t": "ὃς εἰ μόνον ἐσκόπει τὸ παρ’ ἡμέραν ἄδοξον, ὤφειλεν ἀντιστὰς ἐν ἀρχῇ διαγωνίσασθαι περὶ τῆς Ῥώμης, ἀλλὰ μὴ τὴν φυγὴν ἐκείνην ἀποφαίνων στρατήγημα Θεμιστόκλειον ὕστερον ἐν αἰσχρῷ τίθεσθαι τὴν ἐν Θετταλίᾳ πρὸ μάχης διατριβήν. οὐ γὰρ ἐκεῖνό γε στάδιον αὐτοῖς καὶ θέατρον ἐναγωνίσασθαι περὶ τῆς ἡγεμονίας ὁ θεὸς ἀπέδειξε τὸ Φαρσάλιον πεδίον, οὐδὲ ὑπὸ κήρυκος ἐκαλεῖτο μάχεσθαι κατιὼν ἢ λιπεῖν ἑτέρῳ τὸν στέφανον, ἀλλὰ πολλὰ μὲν πεδία μυρίας δὲ πόλεις καὶ γῆν ἄπλετον ἢ κατὰ θάλατταν εὐπορία παρέσχε βουλομένῳ μιμεῖσθαι Μάξιμον καὶ Μάριον καὶ Λεύκολλον καὶ αὐτὸν Ἀγησίλαον, ὃς οὐκ ἐλάττονας μὲν ἐν Σπάρτῃ θορύβους ὑπέμεινε βουλομένων Θηβαίοις ὑπὲρ τῆς χώρας μάχεσθαι, πολλὰς δ’ ἐν Αἰγύπτῳ διαβολὰς καὶ κατηγορίας καὶ ὑπονοίας τοῦ βασιλέως ἤνεγκεν ἡσυχίαν ἄγειν κελεύων, χρησάμενος δὲ τοῖς ἀρίστοις ὡς ἐβούλετο λογισμοῖς, οὐ μόνον Αἰγυπτίους ἄκοντας ἔσωσεν, οὐδὲ τὴν Σπάρτην ἐν τοσούτῳ σεισμῷ μόνος ὀρθὴν ἀεὶ διεφύλαξεν, ἀλλὰ καὶ τρόπαιον ἔστησε κατὰ Θηβαίων ἐν τῇ πόλει, τὸ νικῆσαι παρασχὼν αὖθις ἐκ τοῦ τότε μὴ προαπολέσθαι βιασαμένους.", "st": "Comp. Ages.–Pomp. 4.4"}, {"sp": "N", "t": "ὅθεν Ἀγησίλαος μὲν ὑπὸ τῶν βιασθέντων ὕστερον ἐπῃνεῖτο σωθέντων, Πομπήϊος δὲ δι’ ἄλλους ἁμαρτών, αὐτοὺς οἷς ἐπείσθη κατηγόρους εἶχε. καίτοι φασί τινες ὡς ὑπὸ τοῦ πενθεροῦ Σκηπίωνος ἐξηπατήθη· τὰ γὰρ πλεῖστα τῶν χρημάτων ὧν ἐκόμιζεν ἐξ Ἀσίας βουλόμενον αὐτὸν νοσφίσασθαι καὶ ἀποκρύψαντα κατεπεῖξαι τὴν μάχην, ὡς οὐκέτι χρημάτων ὄντων, ὃ κἂν ἀληθὲς ἦν, παθεῖν οὐκ ὤφειλεν ὁ στρατηγός, οὐδὲ ῥᾳδίως οὕτω παραλογισθεὶς ἀποκινδυνεῦσαι περὶ τῶν μεγίστων, ἐν μὲν οὖν τούτοις οὕτως ἑκάτερον ἀποθεωροῦμεν.", "st": "Comp. Ages.–Pomp. 4.7"}, {"sp": "N", "t": "εἰς Αἴγυπτον δ’ ὁ μὲν ἐξ ἀνάγκης ἔπλευσε φεύγων, ὁ δὲ οὔτε καλῶς οὔτε ἀναγκαίως ἐπὶ χρήμασιν, ὅπως ἔχῃ τοῖς Ἕλλησι πολεμεῖν ἀφ’ ὧν τοῖς βαρβάροις ἐστρατήγησεν. εἶτα ἃ διὰ Πομπήϊον Αἰγυπτίοις ἐγκαλοῦμεν, ταῦτα Αἰγύπτιοι κατηγοροῦσιν Ἀγησιλάου, ὁ μὲν γὰρ ἠδικήθη πιστεύσας, ὁ δὲ πιστευθεὶς ἐγκατέλιπε καὶ μετέστη πρὸς τοὺς πολεμοῦντας οἷς ἔπλευσε συμμαχήσων.", "st": "Comp. Ages.–Pomp. 5.1"}, {"sp": "HDR", "t": "Ἀλέξανδρος"}, {"sp": "N", "t": "τὸν Ἀλεξάνδρου τοῦ βασιλέως βίον καὶ τοῦ Καίσαρος, ὑφ’ οὗ κατελύθη Πομπήϊος, ἐν τούτῳ τῷ βιβλίῳ γράφοντες, διὰ τὸ πλῆθος τῶν ὑποκειμένων πράξεων οὐδὲν ἄλλο προεροῦμεν ἢ παραιτησόμεθα τοὺς ἀναγινώσκοντας, ἐὰν μὴ πάντα μηδὲ καθ’ ἕκαστον ἐξειργασμένως τι τῶν περιβοήτων ἀπαγγέλλωμεν, ἀλλὰ ἐπιτέμνοντες τὰ πλεῖστα, μὴ συκοφαντεῖν. οὔτε γὰρ ἱστορίας γράφομεν, ἀλλὰ βίους, οὔτε ταῖς ἐπιφανεστάταις πράξεσι πάντως ἔνεστι δήλωσις ἀρετῆς ἢ κακίας, ἀλλὰ πρᾶγμα βραχὺ πολλάκις καὶ ῥῆμα καὶ παιδιά τις ἔμφασιν ἤθους ἐποίησε μᾶλλον ἢ μάχαι μυριόνεκροι καὶ παρατάξεις αἱ μέγισται καὶ πολιορκίαι πόλεων. ὥσπερ οὖν οἱ ζῳγράφοι τὰς ὁμοιότητας ἀπὸ τοῦ προσώπου καὶ τῶν περὶ τὴν ὄψιν εἰδῶν, οἷς ἐμφαίνεται τὸ ἦθος, ἀναλαμβάνουσιν, ἐλάχιστα τῶν λοιπῶν μερῶν φροντίζοντες, οὕτως ἡμῖν δοτέον εἰς τὰ τῆς ψυχῆς σημεῖα μᾶλλον ἐνδύεσθαι καὶ διὰ τούτων εἰδοποιεῖν τὸν ἑκάστου βίον, ἐάσαντας ἑτέροις τὰ μεγέθη καὶ τοὺς ἀγῶνας.", "st": "Alex. 1.1"}, {"sp": "N", "t": "Ἀλέξανδρος ὅτι τῷ γένει πρὸς πατρὸς μὲν ἦν Ἡρακλείδης ἀπὸ Καράνου, πρὸς δὲ μητρὸς Αἰακίδης ἀπὸ Νεοπτολέμου, τῶν πάνυ πεπιστευμένων ἐστί. λέγεται δέ Φίλιππος ἐν θρᾴκῃ τῇ Ὀλυμπιάδι συμμυηθείς αὐτός τε μειράκιον ὢν ἔτι κἀκείνης παιδὸς ὀρφανῆς γονέων ἐρασθῆναι καὶ τὸν γάμον οὕτως ἁρμόσαι, πείσας τὸν ἀδελφὸν αὐτῆς Ἀρύμβαν. ἡ μὲν οὖν νύμφη, πρὸ τῆς νυκτός ᾗ συνείρχθησαν εἰς τὸν θάλαμον, ἔδοξε βροντῆς γενομένης ἐμπεσεῖν αὐτῆς τῇ γαστρὶ κεραυνόν, ἐκ δὲ τῆς πληγῆς πολὺ πῦρ ἀναφθέν, εἶτα ῥηγνύμενον εἰς φλόγας πάντῃ φερομένας διαλυθῆναι. ὁ δὲ Φίλιππος ὑστέρῳ χρόνῳ μετὰ τὸν γάμον εἶδεν ὄναρ αὑτὸν ἐπιβάλλοντα σφραγῖδα τῇ γαστρὶ τῆς γυναικός· ἡ δὲ γλυφὴ τῆς σφραγῖδος, ὡς ᾤετο, λέοντος εἶχεν εἰκόνα. τῶν δὲ ἄλλων μάντεων ὑφορωμένων τὴν ὄψιν, ὡς ἀκριβεστέρας φυλακῆς δεομένων τῷ Φιλίππῳ τῶν περὶ τὸν γάμον, Ἀρίστανδρος ὁ Τελμησσεὺς κύειν ἔφη τὴν ἄνθρωπον, οὐθὲν γὰρ ἀποσφραγίζεσθαι τῶν κενῶν, καὶ κύειν παῖδα θυμοειδῆ καὶ λεοντώδη τὴν φύσιν. ὤφθη δέ ποτε καὶ δράκων κοιμωμένης τῆς Ὀλυμπιάδος παρεκτεταμένος τῷ σώματι· καὶ τοῦτο μάλιστα τοῦ Φιλίππου τὸν ἔρωτα καὶ τὰς φιλοφροσύνας ἀμαυρῶσαι λέγουσιν, ὡς μηδὲ φοιτᾶν ἔτι πολλάκις παρ’ αὐτὴν ἀναπαυσόμενον, εἴτε δείσαντά τινας μαγείας ἐπ’ αὐτῷ καὶ φάρμακα τῆς γυναικός, εἴτε τὴν ὁμιλίαν ὡς κρείττονι συνούσης ἀφοσιούμενον.", "st": "Alex. 2.1"}, {"sp": "N", "t": "ἕτερος δὲ περὶ τούτων ἐστὶ λόγος, ὡς πᾶσαι μὲν αἱ τῇδε γυναῖκες ἔνοχοι τοῖς Ὀρφικοῖς οὖσαι καὶ τοῖς περὶ τὸν Διόνυσον ὀργιασμοῖς ἐκ τοῦ πάνυ παλαιοῦ, Κλώδωνές τε καὶ Μιμαλλόνες ἐπωνυμίαν ἔχουσαι, πολλὰ ταῖς Ἠδωνίσι καὶ ταῖς περὶ τὸν Αἷμον Θρῄσσαις ὅμοια δρῶσιν, ἀφ’ ὧν δοκεῖ καὶ τὸ θρησκεύειν ὄνομα ταῖς κατακόροις γενέσθαι καὶ περιέργοις ἱερουργίαις, ἡ δὲ Ὀλυμπιὰς μᾶλλον ἑτέρων ζηλώσασα τὰς κατοχάς καὶ τοὺς ἐνθουσιασμοὺς ἐξάγουσα βαρβαρικώτερον ὄφεις μεγάλους χειροήθεις ἐφείλκετο τοῖς θιάσοις, οἳ πολλάκις ἐκ τοῦ κιττοῦ καὶ τῶν μυστικῶν λίκνων παραναδυόμενοι καὶ περιελιττόμενοι τοῖς θύρσοις τῶν γυναικῶν καὶ τοῖς στεφάνοις ἐξέπληττον τοὺς ἄνδρας.", "st": "Alex. 2.7"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ Φιλίππῳ μὲν, μετὰ τὸ φάσμα πέμψαντι Χαίρωνα τὸν Μεγαλοπολίτην εἰς Δελφοὺς, χρησμὸν κομισθῆναι λέγουσι παρὰ τοῦ θεοῦ κελεύοντος Ἄμμωνι θύειν καὶ σέβεσθαι μάλιστα τοῦτον τὸν θεόν ἀποβαλεῖν δὲ τῶν ὄψεων αὐτὸν τὴν ἑτέραν, ἣν τῷ τῆς θύρας ἁρμῷ προσβαλών κατώπτευσεν ἐν μορφῇ δράκοντος συνευναζόμενον τῇ γυναικὶ τὸν θεόν. ἡ δὲ Ὀλυμπιάς, ὡς Ἐρατοσθένης φησί, προπέμπουσα τὸν Ἀλέξανδρον ἐπὶ τὴν στρατείαν, καὶ φράσασα μόνῳ τὸ περὶ τὴν τέκνωσιν ἀπόρρητον, ἐκέλευεν ἄξια φρονεῖν τῆς γενέσεως, ἕτεροι δέ φασιν αὐτὴν ἀφοσιοῦσθαι καὶ λέγειν οὐ παύσεταί με διαβάλλων Ἀλέξανδρος πρὸς τὴν Ἥραν;", "st": "Alex. 3.1"}, {"sp": "N", "t": "ἐγεννήθη δ’ οὖν Ἀλέξανδρος ἱσταμένου μηνὸς Ἑκατομβαιῶνος, ὃν Μακεδόνες Λῷον καλοῦσιν, ἕκτῃ, καθ’ ἣν ἡμέραν ὁ τῆς Ἐφεσίας Ἀρτέμιδος ἐνεπρήσθη νεώς ᾧ γ’ Ἡγησίας ὁ Μάγνης ἐπιπεφώνηκεν ἐπιφώνημα κατασβέσαι τὴν πυρκαϊὰν ἐκείνην ὑπὸ ψυχρίας δυνάμενον εἰκότως γὰρ ἔφη καταφλεχθῆναι τὸν νεών τῆς Ἀρτέμιδος ἀσχολουμένης περὶ τὴν Ἀλεξάνδρου μαίωσιν. ὅσοι δὲ τῶν μάγων ἐν Ἐφέσῳ διατρίβοντες ἔτυχον, τὸ περὶ τὸν νεών πάθος ἡγούμενοι πάθους ἑτέρου σημεῖον εἶναι, διέθεον τὰ πρόσωπα τυπτόμενοι καὶ βοῶντες ἄτην ἅμα καὶ συμφορὰν μεγάλην τῇ Ἀσίᾳ τὴν ἡμέραν ἐκείνην τετοκέναι. Φιλίππῳ δὲ ἄρτι Ποτείδαιαν ᾑρηκότι τρεῖς ἧκον ἀγγελίαι κατὰ τὸν αὐτὸν χρόνον· ἡ μὲν Ἰλλυριοὺς ἡττᾶσθαι μάχῃ μεγάλῃ διὰ Παρμενίωνος, ἡ δὲ Ὀλυμπίασιν ἵππῳ κέλητι νενικηκέναι, τρίτη δὲ περὶ τῆς Ἀλεξάνδρου γενέσεως, ἐφ’ οἷς ἡδόμενον, ὡς εἰκὸς, ἔτι μᾶλλον οἱ μάντεις ἐπῆραν ἀποφαινόμενοι τὸν παῖδα τρισὶ νίκαις συγγεγεννημένον ἀνίκητον ἔσεσθαι.", "st": "Alex. 3.5"}, {"sp": "N", "t": "τὴν μὲν οὖν ἰδέαν τοῦ σώματος οἱ Λυσίππειοι μάλιστα τῶν ἀνδριάντων ἐμφαίνουσιν, ὑφ’ οὗ μόνου καὶ αὐτὸς ἠξίου πλάττεσθαι. καὶ γὰρ μάλισθ’ ἃ πολλοὶ τῶν διαδόχων ὕστερον καὶ τῶν φίλων ἀπεμιμοῦντο, τήν τε ἀνάτασιν τοῦ αὐχένος εἰς εὐώνυμον ἡσυχῇ κεκλιμένου καὶ Τὴν ὑγρότητα τῶν ὀμμάτων, διατετήρηκεν ἀκριβῶς ὁ τεχνίτης. Ἀπελλῆς δὲ γράφων τὸν κεραυνοφόρον οὐκ ἐμιμήσατο Τὴν χρόαν, ἀλλὰ φαιότερον καὶ πεπινωμένον ἐποίησεν. ἦν δὲ λευκός, ὥς φασιν ἡ δὲ λευκότης ἐπεφοίνισσεν αὐτοῦ περὶ τὸ στῆθος μάλιστα καὶ τὸ πρόσωπον, ὅτι δὲ τοῦ χρωτὸς ἥδιστον ἀπέπνει καὶ τὸ στόμα κατεῖχεν εὐωδία καὶ Τὴν σάρκα πᾶσαν, ὥστε πληροῦσθαι τοὺς χιτωνίσκους, ἀνέγνωμεν ἐν ὑπομνήμασιν Ἀριστοξενείοις.", "st": "Alex. 4.1"}, {"sp": "N", "t": "αἰτία δὲ ἴσως ἡ τοῦ σώματος κρᾶσις πολύθερμος οὖσα καὶ πυρώδης· ἡ γὰρ εὐωδία γίνεται πέψει τῶν ὑγρῶν ὑπὸ θερμότητος, ὡς οἴεται Θεόφραστος, ὅθεν οἱ ξηροὶ καὶ διάπυροι τόποι τῆς οἰκουμένης τὰ πλεῖστα καὶ κάλλιστα τῶν ἀρωμάτων φέρουσιν ἐξαιρεῖ γὰρ ὁ ἥλιος τὸ ὑγρόν ὥσπερ ὕλην σηπεδόνος ἐπιπολάζον τοῖς σώμασιν. Ἀλέξανδρον δὲ ἡ θερμότης τοῦ σώματος, ὡς ἔοικε, καὶ ποτικὸν καὶ θυμοειδῆ παρεῖχεν.", "st": "Alex. 4.5"}, {"sp": "N", "t": "ἔτι δὲ ὄντος αὐτοῦ παιδὸς ἥ τε σωφροσύνη διεφαίνετο τῷ πρὸς τἆλλα ῥαγδαῖον ὄντα καὶ φερόμενον σφοδρῶς ἐν ταῖς ἡδοναῖς ταῖς περὶ τὸ σῶμα δυσκίνητον εἶναι καὶ μετά πολλῆς πρᾳότητος ἅπτεσθαι τῶν τοιούτων, ἥ τε φιλοτιμία παρ’ ἡλικίαν ἐμβριθὲς εἶχε τὸ φρόνημα καὶ μεγαλόψυχον. οὔτε γὰρ ἀπὸ παντὸς οὔτε πᾶσαν ἠγάπα δόξαν, ὡς Φίλιππος λόγου τε δεινότητι σοφιστικῶς καλλωπιζόμενος καὶ τὰς ἐν Ὀλυμπίᾳ, νίκας τῶν ἁρμάτων ἐγχαράττων τοῖς νομίσμασιν, ἀλλὰ καὶ τῶν περὶ αὐτὸν ἀποπειρωμένων εἰ βούλοιτ’ ἂν Ὀλυμπίασιν ἀγωνίσασθαι στάδιον, ἦν γὰρ ποδώκης, εἴ γε, ἔφη, βασιλεῖς ἔμελλον ἕξειν ἀνταγωνιστάς. φαίνεται δὲ καὶ καθόλου πρὸς τὸ τῶν ἀθλητῶν γένος ἀλλοτρίως ἔχων πλείστους γέ τοι θεὶς ἀγῶνας οὐ μόνον τραγῳδῶν καὶ αὐλητῶν καὶ κιθαρῳδῶν, ἀλλὰ καὶ ῥαψῳδῶν, θήρας τε παντοδαπῆς καὶ ῥαβδομαχίας, οὔτε πυγμῆς οὔτε παγκρατίου μετά τινος σπουδῆς ἔθηκεν ἆθλον.", "st": "Alex. 4.8"}, {"sp": "N", "t": "τοὺς δὲ παρὰ τοῦ Περσῶν βασιλέως πρέσβεις ἥκοντας ἀποδημοῦντος Φιλίππου ξενίζων καὶ γενόμενος συνήθης οὕτως ἐχειρώσατο τῇ φιλοφροσύνῃ καὶ τῷ μηδὲν ἐρώτημα παιδικὸν ἐρωτῆσαι μηδὲ μικρόν, ἀλλ’ ὁδῶν τε μήκη καὶ πορείας τῆς ἄνω τρόπον ἐκπυνθάνεσθαι, καὶ περὶ αὐτοῦ τοῦ βασιλέως, ὁποῖος εἴη πρὸς τοὺς πολέμους, καὶ τίς ἡ Περσῶν ἀλκὴ καὶ δύναμις, ὥστε θαυμάζειν ἐκείνους καὶ τὴν λεγομένην Φιλίππου δεινότητα μηδὲν ἡγεῖσθαι πρὸς τὴν τοῦ παιδὸς ὁρμὴν καὶ μεγαλοπραγμοσύνην. ὁσάκις γοῦν ἀπαγγελθείη Φίλιππος ἢ πόλιν ἔνδοξον ᾑρηκὼς ἢ μάχην τινὰ περιβόητον νενικηκώς, οὐ πάνυ φαιδρὸς ἦν ἀκούων, ἀλλὰ πρὸς τοὺς ἡλικιώτας ἔλεγεν· ὦ παῖδες, πάντα προλήψεται ὁ πατήρ ἐμοὶ δὲ οὐδὲν ἀπολείψει μεθ’ ὑμῶν ἔργον ἀποδείξασθαι μέγα καὶ λαμπρόν. οὐ γὰρ ἡδονὴν ζηλῶν οὐδὲ πλοῦτον, ἀλλ’ ἀρετὴν καὶ δόξαν, ἐνόμιζεν, ὅσῳ πλείονα λήψεται παρὰ τοῦ πατρός, ἐλάττονα κατορθώσειν δι’ ἑαυτοῦ, διὸ τοῖς πράγμασιν αὐξομένοις καταναλίσκεσθαι τὰς πράξεις εἰς ἐκεῖνον ἡγούμενος, ἐβούλετο μὴ χρήματα μηδὲ τρυφὰς καὶ ἀπολαύσεις, ἀλλ’ ἀγῶνας καὶ πολέμους καὶ φιλοτιμίας ἔχουσαν ἀρχὴν παραλαβεῖν.", "st": "Alex. 5.1"}, {"sp": "N", "t": "πολλοὶ μὲν οὖν περὶ τὴν ἐπιμέλειαν, ὡς εἰκός, ἦσαν αὐτοῦ τροφεῖς καὶ παιδαγωγοὶ καὶ διδάσκαλοι λεγόμενοι, πᾶσι δ’ ἐφειστήκει Λεωνίδας, ἀνὴρ τό τε ἦθος αὐστηρὸς καὶ συγγενὴς Ὀλυμπιάδος, αὐτὸς μὲν οὐ φεύγων τὸ τῆς παιδαγωγίας ὄνομα καλὸν ἔργον ἐχούσης καὶ λαμπρόν, ὑπὸ δὲ τῶν ἄλλων διὰ τὸ ἀξίωμα καὶ τὴν οἰκειότητα τροφεὺς Ἀλεξάνδρου καὶ καθηγητὴς καλούμενος. ὁ δὲ τὸ σχῆμα τοῦ παιδαγωγοῦ καὶ τὴν προσηγορίαν ὑποποιούμενος ἦν Λυσίμαχος, τῷ γένει Ἀκαρνάν, ἄλλο μὲν οὐδὲν ἔχων ἀστεῖον, ὅτι δ’ ἑαυτὸν μὲν ὠνόμαζε Φοίνικα, τὸν δὲ Ἀλέξανδρον Ἀχιλλέα, Πηλέα δὲ τὸν Φίλιππον, ἠγαπᾶτο καὶ δευτέραν εἶχε χώραν.", "st": "Alex. 5.7"}, {"sp": "N", "t": "ἐπεὶ δὲ Φιλονίκου τοῦ Θεσσαλοῦ τὸν Βουκεφάλαν ἀγαγόντος ὤνιον τῷ Φιλίππῳ τρισκαίδεκα ταλάντων κατέβησαν εἰς τὸ πεδίον δοκιμάσοντες τὸν ἵππον, ἐδόκει τε χαλεπὸς εἶναι καὶ κομιδῇ δύσχρηστος, οὔτε ἀναβάτην προσιέμενος οὔτε φωνὴν ὑπομένων τινὸς τῶν περὶ τὸν Φίλιππον, ἀλλ’ ἁπάντων κατεξανιστάμενος, δυσχεραίνοντος δὲ τοῦ Φιλίππου καὶ κελεύοντος ἀπάγειν ὡς παντάπασιν ἄγριον καὶ ἀκόλαστον, παρὼν Ἀλέξανδρος εἶπεν· οἷον ἵππον ἀπολλύουσι δι’ ἀπειρίαν καὶ μαλακίαν χρήσασθαι μὴ δυνάμενοι, τὸ μὲν οὖν πρῶτον ὁ Φίλιππος ἐσιώπησε· πολλάκις δὲ αὐτοῦ παραφθεγγομένου καὶ περιπαθοῦντος, ἐπιτιμᾷς σύ, ἔφη, πρεσβυτέροις ὥς τι πλέον αὐτὸς εἰδὼς ἢ μᾶλλον ἵππῳ χρήσασθαι δυνάμενος; τούτῳ γοῦν, ἔφη, χρησαίμην ἂν ἑτέρου βέλτιον. ἂν δὲ μὴ χρήσῃ, τίνα δίκην τῆς προπετείας ὑφέξεις; ἐγὼ, νὴ Δί’, εἶπεν, ἀποτίσω τοῦ ἵππου τὴν τιμήν γενομένου δὲ γέλωτος, εἶτα ὁρισμοῦ πρὸς ἀλλήλους εἰς τὸ ἀργύριον, εὐθὺς προσδραμὼν τῷ ἵππῳ καὶ παραλαβὼν τὴν ἡνίαν ἐπέστρεψε πρὸς τὸν ἥλιον, ὡς ἔοικεν, ἐννοήσας ὅτι τὴν σκιὰν προπίπτουσαν καὶ σαλευομένην ὁρῶν πρὸ αὐτοῦ διαταράττοιτο. μικρὰ δὲ οὕτω παρακαλπάσας καὶ καταψήσας, ὡς ἑώρα πληρούμενον θυμοῦ καὶ πνεύματος, ἀπορρίψας ἡσυχῇ τὴν χλαμύδα καὶ μετεωρίσας αὑτόν ἀσφαλῶς περιέβη. καὶ μικρὰ μὲν περιλαβὼν ταῖς ἡνίαις τὸν χαλινόν ἄνευ πληγῆς καὶ σπαραγμοῦ, προσανέστειλεν ὡς δὲ ἑώρα τὸν ἵππον ἀφεικότα τὴν ἀπειλήν, ὀργῶντα δὲ πρὸς τὸν δρόμον, ἐφεὶς ἐδίωκεν ἤδη φωνῇ θρασυτέρᾳ καὶ ποδὸς κρούσει χρώμενος. τῶν δὲ περὶ τὸν Φίλιππον ἦν ἀγωνία καὶ σιγὴ τὸ πρῶτον ὡς δὲ κάμψας ἐπέστρεψεν ὀρθῶς σοβαρὸς καὶ γεγηθώς, οἱ μὲν ἄλλοι πάντες ἠλάλαξαν, ὁ δὲ πατὴρ καὶ δακρῦσαί τι λέγεται πρὸς τὴν χαράν, καὶ καταβάντος αὐτοῦ τὴν κεφαλὴν φιλήσας, ὦ παῖ, φάναι, ζήτει σεαυτῷ βασιλείαν ἴσην Μακεδονία γάρ σε οὐ χωρεῖ", "st": "Alex. 6.1"}, {"sp": "N", "t": "καθορῶν δὲ τὴν φύσιν αὐτοῦ δυσκίνητον μὲν οὖσαν ἐρίσαντος μὴ βιασθῆναι, ῥᾳδίως δὲ ἀγομένην ὑπὸ λόγου πρὸς τὸ δέον, αὐτός τε πείθειν ἐπειρᾶτο μᾶλλον ἢ προστάττειν, καὶ τοῖς περὶ μουσικὴν καὶ τὰ ἐγκύκλια παιδευταῖς οὐ πάνυ τι πιστεύων τὴν ἐπιστασίαν αὐτοῦ καὶ κατάρτισιν, ὡς μείζονος οὖσαν πραγματείας καὶ κατὰ τὸν Σοφοκλέα", "st": "Alex. 7.1"}, {"sp": "N", "t": "πολλῶν χαλινῶν ἔργον οἰάκων θ’ ἅμα,", "st": "Alex. 7.1b"}, {"sp": "N", "t": "μετεπέμψατο τῶν φιλοσόφων τὸν ἐνδοξότατον καὶ λογιώτατον Ἀριστοτέλην, καλὰ καὶ πρέποντα διδασκάλια τελέσας αὐτῷ. τὴν γὰρ Σταγειριτῶν πόλιν, ἐξ ἧς ἦν Ἀριστοτέλης, ἀνάστατον ὑπ’ αὐτοῦ γεγενημένην συνῴκισε πάλιν, καὶ τοὺς διαφυγόντας ἢ δουλεύοντας τῶν πολιτῶν ἀποκατέστησε.", "st": "Alex. 7.1c"}, {"sp": "N", "t": "σχολὴν μὲν οὖν αὐτοῖς καὶ διατριβὴν τὸ περὶ Μίεζαν Νυμφαῖον ἀπέδειξεν, ὅπου μέχρι νῦν Ἀριστοτέλους ἕδρας τε λιθίνας καὶ ὑποσκίους περιπάτους δεικνύουσιν. ἔοικε δὲ Ἀλέξανδρος οὐ μόνον τὸν ἠθικὸν καὶ πολιτικὸν παραλαβεῖν λόγον, ἀλλὰ καὶ τῶν ἀπορρήτων καὶ βαθυτέρων διδασκαλιῶν, ἃς οἱ ἄνδρες ἰδίως ἀκροαματικὰς καὶ ἐποπτικὰς προσαγορεύοντες οὐκ ἐξέφερον εἰς πολλούς, μετασχεῖν. ἤδη γὰρ εἰς Ἀσίαν διαβεβηκώς, καὶ πυθόμενος λόγους τινὰς ἐν βιβλίοις περὶ τούτων ὑπὸ Ἀριστοτέλους ἐκδεδόσθαι, γράφει πρὸς αὐτὸν ὑπὲρ φιλοσοφίας παρρησιαζόμενος ἐπιστολήν, ἧς ἀντίγραφόν ἐστιν· Ἀλέξανδρος Ἀριστοτέλει εὖ πράττειν. οὐκ ὀρθῶς ἐποίησας ἐκδοὺς τοὺς ἀκροαματικοὺς τῶν λόγων τίνι γὰρ δὴ διοίσομεν ἡμεῖς τῶν ἄλλων, εἰ καθ’ οὓς ἐπαιδεύθημεν λόγους, οὗτοι πάντων ἔσονται κοινοί; ἐγὼ δὲ βουλοίμην ἂν ταῖς περὶ τὰ ἄριστα ἐμπειρίαις ἢ ταῖς δυνάμεσι διαφέρειν. ἔρρωσο. ταύτην μὲν οὖν τὴν φιλοτιμίαν αὐτοῦ παραμυθούμενος Ἀριστοτέλης ἀπολογεῖται περὶ τῶν λόγων ἐκείνων, ὡς καὶ ἐκδεδομένων καὶ μὴ ἐκδεδομένων· ἀληθῶς γὰρ ἡ μετὰ τὰ φυσικὰ πραγματεία πρὸς διδασκαλίαν καὶ μάθησιν οὐδὲν ἔχουσα χρήσιμον ὑπόδειγμα τοῖς πεπαιδευμένοις ἀπ’ ἀρχῆς γέγραπται.", "st": "Alex. 7.4"}, {"sp": "N", "t": "δοκεῖ δέ μοι καὶ τὸ φιλιατρεῖν Ἀλεξάνδρῳ προστρίψασθαι μᾶλλον ἑτέρων Ἀριστοτέλης· οὐ γὰρ μόνον τὴν θεωρίαν ἠγάπησεν, ἀλλὰ καὶ νοσοῦσιν ἐβοήθει τοῖς φίλοις καὶ συνέταττε θεραπείας τινὰς καὶ διαίτας, ὡς ἐκ τῶν ἐπιστολῶν λαβεῖν ἔστιν, ἦν δὲ καὶ φύσει φιλόλογος καὶ φιλαναγνώστης. καὶ τὴν μὲν Ἰλιάδα τῆς πολεμικῆς ἀρετῆς ἐφόδιον καὶ νομίζων καὶ ὀνομάζων, ἔλαβε μὲν Ἀριστοτέλους διορθώσαντος ἣν ἐκ τοῦ νάρθηκος καλοῦσιν, εἶχε δὲ ἀεὶ μετὰ τοῦ ἐγχειριδίου κειμένην ὑπὸ τὸ προσκεφάλαιον, ὡς Ὀνησίκριτος ἱστόρηκε, τῶν δὲ ἄλλων βιβλίων οὐκ εὐπορῶν ἐν τοῖς ἄνω τόποις Ἅρπαλον ἐκέλευσε πέμψαι. κἀκεῖνος ἔπεμψεν αὐτῷ τάς τε Φιλίστου βίβλους καὶ τῶν Εὐριπίδου καὶ Σοφοκλέους καὶ Αἰσχύλου τραγῳδιῶν συχνάς, καὶ Τελέστου καὶ Φιλοξένου διθυράμβους. Ἀριστοτέλην δὲ θαυμάζων ἐν ἀρχῇ καὶ ἀγαπῶν οὐχ ἧττον, ὡς αὐτὸς ἔλεγε, τοῦ πατρός, ὡς δι’ ἐκεῖνον μὲν ζῶν, διὰ τοῦτον δὲ καλῶς ζῶν, ὕστερον ὑποπτότερον ἔσχεν, οὐχ ὥστε ποιῆσαί τι κακόν, ἀλλ’ αἱ φιλοφροσύναι τὸ σφοδρὸν ἐκεῖνο καὶ στερκτικὸν οὐκ ἔχουσαι πρὸς αὐτόν ἀλλοτριότητος ἐγένοντο τεκμήριον. ὁ μέντοι πρὸς φιλοσοφίαν ἐμπεφυκὼς καὶ συντεθραμμένος ἀπ’ ἀρχῆς αὐτῷ ζῆλος καὶ πόθος οὐκ ἐξερρύη τῆς ψυχῆς, ὡς ἡ περὶ Ἀνάξαρχόν τε τιμὴ καὶ τὰ πεμφθέντα Ξενοκράτει πεντήκοντα τάλαντα καὶ Δάνδαμις καὶ Καλανὸς οὕτω σπουδασθέντες μαρτυροῦσι.", "st": "Alex. 8.1"}, {"sp": "N", "t": "Φιλίππου δὲ στρατεύοντος ἐπὶ Βυζαντίους, ἦν μὲν ἑκκαιδεκέτης Ἀλέξανδρος, ἀπολειφθεὶς δὲ κύριος ἐν Μακεδονίᾳ τῶν πραγμάτων καὶ τῆς σφραγῖδος, Μαίδων τε τοὺς ἀφεστῶτας κατεστρέψατο, καὶ πόλιν ἑλὼν αὐτῶν τοὺς μὲν βαρβάρους ἐξήλασε, συμμίκτους δὲ κατοικίσας Ἀλεξανδρόπολιν προσηγόρευσεν. ἐν δὲ Χαιρωνείᾳ τῆς πρὸς τοὺς Ἕλληνας μάχης παρὼν μετέσχε, καὶ λέγεται πρῶτος ἐνσεῖσαι τῷ ἱερῷ λόχῳ τῶν Θηβαίων, ἔτι δὲ καὶ καθ’ ἡμᾶς ἐδείκνυτο παλαιὰ παρὰ τὸν Κηφισὸν Ἀλεξάνδρου καλουμένη δρῦς, πρὸς ἣν τότε κατεσκήνωσε, καὶ τὸ πολυάνδριον οὐ πόρρω τῶν Μακεδόνων ἐστίν.", "st": "Alex. 9.1"}, {"sp": "N", "t": "ἐκ μὲν οὖν τούτων, ὡς εἰκὸς, Φίλιππος ὑπερηγάπα τὸν υἱόν, ὥστε καὶ χαίρειν τῶν Μακεδόνων Ἀλέξανδρον μὲν βασιλέα, Φίλιππον δὲ στρατηγὸν καλούντων, αἱ δὲ περὶ τὴν οἰκίαν ταραχαί, διὰ τοὺς γάμους καὶ τοὺς ἔρωτας αὐτοῦ τρόπον τινὰ τῆς βασιλείας τῇ γυναικωνίτιδι συννοσούσης, πολλὰς αἰτίας καὶ μεγάλας διαφορὰς παρεῖχον, ἃς ἡ τῆς Ὀλυμπιάδος χαλεπότης, δυσζήλου καὶ βαρυθύμου γυναικός, ἔτι μείζονας ἐποίει, παροξυνούσης τὸν Ἀλέξανδρον. ἐκφανεστάτην δὲ Ἄτταλος παρέσχεν ἐν τοῖς Κλεοπάτρας γάμοις, ἣν ὁ Φίλιππος ἠγάγετο παρθένον, ἐρασθεὶς παρ’ ἡλικίαν τῆς κόρης, θεῖος γὰρ ὢν αὐτῆς ὁ Ἄτταλος ἐν τῷ πότῳ μεθύων παρεκάλει τοὺς Μακεδόνας αἰτεῖσθαι παρὰ θεῶν γνήσιον ἐκ Φιλίππου καὶ Κλεοπάτρας γενέσθαι διάδοχον τῆς βασιλείας, ἐπὶ τούτῳ παροξυνθεὶς ὁ Ἀλέξανδρος καὶ εἰπών, ἡμεῖς δὲ σοι, κακὴ κεφαλὴ, νόθοι δοκοῦμεν; ἔβαλε σκύφον ἐπ’ αὐτόν. ὁ δὲ Φίλιππος ἐπ’ ἐκεῖνον ἐξανέστη σπασάμενος τὸ ξίφος, εὐτυχίᾳ δὲ ἑκατέρου διὰ τὸν θυμὸν καὶ τὸν οἶνον ἔπεσε σφαλείς, ὁ δὲ Ἀλέξανδρος ἐφυβρίζων, οὗτος μέντοι, εἶπεν, ἄνδρες, εἰς Ἀσίαν ἐξ Εὐρώπης παρεσκευάζετο διαβαίνειν, ὃς ἐπὶ κλίνην ἀπὸ κλίνης διαβαίνων ἀνατέτραπται. μετὰ ταύτην τὴν παροινίαν ἀναλαβὼν τὴν Ὀλυμπιάδα καὶ καταστήσας εἰς Ἤπειρον αὐτὸς ἐν Ἰλλυριοῖς διέτριβεν.", "st": "Alex. 9.4"}, {"sp": "N", "t": "ἐν τούτῳ δὲ Δημάρατος ὁ Κορίνθιος, ξένος ὢν τῆς οἰκίας καὶ παρρησίας μετέχων, ἀφίκετο πρὸς Φίλιππον. μετὰ δὲ τὰς πρώτας δεξιώσεις καὶ φιλοφροσύνας ἐπερωτῶντος τοῦ Φιλίππου πῶς ἔχουσιν ὁμονοίας πρὸς ἀλλήλους οἱ Ἕλληνες, πάνυ γοῦν, ἔφη, σοι προσήκει, Φίλιππε, κήδεσθαι τῆς Ἑλλάδος, ὃς τὸν οἶκον τὸν σεαυτοῦ στάσεως τοσαύτης καὶ κακῶν ἐμπέπληκας. οὕτω δὴ συμφρονήσας ὁ Φίλιππος ἔπεμψε καὶ κατήγαγε πείσας διὰ τοῦ Δημαράτου τὸν Ἀλέξανδρον.", "st": "Alex. 9.12"}, {"sp": "N", "t": "ἐπεὶ δὲ Πιξόδαρος, ὁ Καρίας σατράπης, ὑποδυόμενος δι’ οἰκειότητος εἰς τὴν Φιλίππου συμμαχίαν, ἐβούλετο τὴν πρεσβυτάτην τῶν θυγατέρων Ἀρριδαίῳ τῷ Φιλίππου γυναῖκα δοῦναι καὶ περὶ τούτων Ἀριστόκριτον εἰς Μακεδονίαν ἀπέστειλεν, αὖθις ἐγίνοντο λόγοι καὶ διαβολαὶ παρὰ τῶν φίλων καὶ τῆς μητρὸς πρὸς Ἀλέξανδρον, ὡς Ἀρριδαῖον ἐπὶ τῇ βασιλείᾳ Φιλίππου γάμοις λαμπροῖς καὶ πράγμασι μεγάλοις εἰσοικειοῦντος. ὑφ’ ὧν διαταραχθεὶς πέμπει Θεσσαλὸν εἰς Καρίαν, τὸν τῶν τραγῳδιῶν ὑποκριτήν, Πιξοδάρῳ διαλεξόμενον ὡς χρὴ τὸν νόθον ἐάσαντα, καὶ οὐ φρενήρη, μεθαρμόσασθαι τὸ κῆδος εἰς Ἀλέξανδρον. καὶ Πιξοδάρῳ μὲν οὐ παρὰ μικρὸν ἤρεσκε ταῦτα τῶν προτέρων μᾶλλον, ὁ δὲ Φίλιππος αἰσθόμενος, ἰὼν εἰς τὸ Ἀλεξάνδρου δωμάτιον, παραλαβὼν τῶν φίλων αὐτοῦ καὶ συνήθων ἕνα, Φιλώταν τὸν Παρμενίωνος, ἐπετίμησεν ἰσχυρῶς, καὶ πικρῶς ἐλοιδόρησεν ὡς ἀγεννῆ καὶ τῶν ὑπαρχόντων περὶ αὐτὸν ἀγαθῶν ἀνάξιον, εἰ Καρὸς ἀνθρώπου καὶ βαρβάρῳ βασιλεῖ δουλεύοντος ἀγαπᾷ γαμβρὸς γενέσθαι. τὸν δὲ Θεσσαλὸν ἔγραψε Κορινθίοις ὅπως ἀναπέμψωσιν ἐν πέδαις δεδεμένον. τῶν δὲ ἄλλων ἑταίρων Ἅρπαλον καὶ Νέαρχον, ἔτι δ’ Ἐρίγυιον καὶ Πτολεμαῖον ἐκ Μακεδονίας μετέστησεν, οὓς ὕστερον Ἀλέξανδρος καταγαγὼν ἐν ταῖς μεγίσταις ἔσχε τιμαῖς.", "st": "Alex. 10.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Παυσανίας Ἀττάλου γνώμῃ καὶ Κλεοπάτρας ὑβρισθεὶς καὶ μὴ τυχὼν δίκης ἀνεῖλε Φίλιππον, τὸ μὲν πλεῖστον εἰς Ὀλυμπιάδα τῆς αἰτίας περιῆλθεν, ὡς θυμουμένῳ τῷ νεανίσκῳ προσεγκελευσαμένην καὶ παροξύνασαν, ἔθιγε δέ τις καὶ Ἀλεξάνδρου διαβολή, λέγεται γὰρ ἐντυχόντος αὐτῷ τοῦ Παυσανίου μετὰ τὴν ὕβριν ἐκείνην καὶ ἀποδυρομένου προενέγκασθαι τὸ τῆς Μηδείας ἰαμβεῖον·", "st": "Alex. 10.6"}, {"sp": "N", "t": "τὸν δόντα καὶ γήμαντα καὶ γαμουμένην,", "st": "Alex. 10.6b"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ τοὺς συναιτίους τῆς ἐπιβουλῆς ἀναζητήσας ἐκόλασε, καὶ τὴν Κλεοπάτραν ἀποδημοῦντος αὐτοῦ τῆς Ὀλυμπιάδος ὠμῶς μεταχειρισαμένης ἠγανάκτησε.", "st": "Alex. 10.8"}, {"sp": "N", "t": "παρέλαβε μὲν οὖν ἔτη γεγονὼς εἴκοσι τὴν βασιλείαν, φθόνους μεγάλους καὶ δεινὰ μίση καὶ κινδύνους πανταχόθεν ἔχουσαν. οὔτε γὰρ τὰ βάρβαρα καὶ πρόσοικα γένη τὴν δούλωσιν ἔφερε, ποθοῦντα τὰς πατρίους βασιλείας, οὔτε τὴν Ἑλλάδα κρατήσας τοῖς ὅπλοις ὁ Φίλιππος οἷον καταζεῦξαι καὶ τιθασεῦσαι χρόνον ἔσχεν, ἀλλὰ μόνον μεταβαλὼν καὶ ταράξας τὰ πράγματα πολὺν σάλον ἔχοντα καὶ κίνησιν ὑπὸ ἀηθείας ἀπέλιπε. φοβουμένων δὲ τῶν Μακεδόνων τὸν καιρόν, καὶ τὰ μὲν Ἑλληνικὰ πάντως ἀφεῖναι καὶ μὴ προσβιάζεσθαι τὸν Ἀλέξανδρον οἰομένων δεῖν, τοὺς δὲ ἀφισταμένους τῶν βαρβάρων ἀνακαλεῖσθαι πρᾴως καὶ θεραπεύειν τὰς ἀρχὰς τῶν νεωτερισμῶν, αὐτὸς ἀπ’ ἐναντίων λογισμῶν ὥρμησε τόλμῃ καὶ μεγαλοφροσύνῃ κτᾶσθαι τὴν ἀσφάλειαν καὶ σωτηρίαν τοῖς πράγμασιν, ὡς, κἂν ὁτιοῦν ὑφιέμενος ὀφθῇ τοῦ φρονήματος, ἐπιβησομένων ἁπάντων. τὰ μὲν οὖν βαρβαρικὰ κινήματα καὶ τοὺς ἐκεῖ πολέμους κατέπαυσεν ὀξέως ἐπιδραμὼν στρατῷ μέχρι πρὸς τὸν Ἴστρον, ᾗ καὶ Σύρμον ἐνίκησε μάχῃ μεγάλῃ, τὸν βασιλέα τῶν Τριβαλλῶν Θηβαίους δὲ ἀφεστάναι πυθόμενος καὶ συμφρονεῖν αὐτοῖς Ἀθηναίους, εὐθὺς ἦγε διὰ Πυλῶν τὴν δύναμιν, εἰπὼν ὅτι Δημοσθένει παῖδα μὲν αὐτὸν, ἕως ἦν ἐν Ἰλλυριοῖς καὶ Τριβαλλοῖς, ἀποκαλοῦντι, μειράκιον δὲ περὶ Θετταλίαν γενόμενον, βούλεται πρὸς τοῖς Ἀθηναίων τείχεσιν ἀνὴρ φανῆναι.", "st": "Alex. 11.1"}, {"sp": "N", "t": "προσμίξας δὲ ταῖς Θήβαις καὶ διδοὺς ἔτι τῶν πεπραγμένων μετάνοιαν ἐξῄτει Φοίνικα καὶ Προθύτην, καὶ τοῖς μεταβαλλομένοις πρὸς αὐτὸν ἄδειαν ἐκήρυττε. τῶν δὲ Θηβαίων ἀντεξαιτούντων μὲν παρ’ αὐτοῦ Φιλώταν καὶ Ἀντίπατρον, κηρυττόντων δὲ τοὺς τὴν Ἑλλάδα βουλομένους συνελευθεροῦν τάττεσθαι μετ’ αὐτῶν, οὕτως ἔτρεψε τοὺς Μακεδόνας πρὸς πόλεμον. ἠγωνίσθη μὲν οὖν ὑπὲρ δύναμιν ἀρετῇ καὶ προθυμίᾳ παρὰ τῶν Θηβαίων πολλαπλασίοις οὖσι τοῖς πολεμίοις ἀντιταχθέντων ἐπεὶ δὲ καὶ τὴν Καδμείαν ἀφέντες οἱ φρουροὶ τῶν Μακεδόνων ἐπέπιπτον αὐτοῖς ἐξόπισθεν, κυκλωθέντες οἱ πλεῖστοι κατὰ τὴν μάχην αὐτὴν ἔπεσον, ἡ δὲ πόλις ἥλω καὶ διαρπασθεῖσα κατεσκάφη, τὸ μὲν ὅλον προσδοκήσαντος αὐτοῦ τοὺς Ἕλληνας ἐκπλαγέντας πάθει τηλικούτῳ καὶ πτήξαντας ἀτρεμήσειν, ἄλλως δὲ καὶ καλλωπισαμένου χαρίζεσθαι τοῖς τῶν συμμάχων ἐγκλήμασι· καὶ γὰρ Φωκεῖς καὶ Πλαταιεῖς τῶν Θηβαίων κατηγόρησαν. ὑπεξελόμενος δὲ τοὺς ἱερεῖς καὶ τοὺς ξένους τῶν Μακεδόνων ἅπαντας καὶ τοὺς ἀπὸ Πινδάρου γεγονότας καὶ τοὺς ὑπεναντιωθέντας τοῖς ψηφισαμένοις τὴν ἀπόστασιν, ἀπέδοτο τοὺς ἄλλους περὶ τρισμυρίους γενομένους· οἱ δὲ ἀποθανόντες ὑπὲρ ἑξακισχιλίους ἦσαν.", "st": "Alex. 11.7"}, {"sp": "N", "t": "ἐν δὲ τοῖς πολλοῖς πάθεσι καὶ χαλεποῖς ἐκείνοις ἃ τὴν πόλιν κατεῖχε, Θρᾷκές τινες ἐκκόψαντες οἰκίαν Τιμοκλείας, γυναικὸς ἐνδόξου καὶ σώφρονος, αὐτοὶ μὲν τὰ χρήματα διήρπαζον, ὁ δὲ ἡγεμὼν τῇ γυναικὶ πρὸς βίαν συγγενόμενος καὶ καταισχύνας, ἀνέκρινεν εἴ που χρυσίον ἔχοι κεκρυμμένον ἢ ἀργύριον. ἡ δὲ ἔχειν ὡμολόγησε, καὶ μόνον εἰς τὸν κῆπον ἀγαγοῦσα καὶ δείξασα φρέαρ, ἐνταῦθα ἔφη τῆς πόλεως ἁλισκομένης καταβαλεῖν αὐτὴ τὰ τιμιώτατα τῶν χρημάτων. ἐγκύπτοντος δὲ τοῦ Θρᾳκὸς καὶ κατασκεπτομένου τὸν τόπον, ἔωσεν αὐτὸν ἐξόπισθεν γενομένη, καὶ τῶν λίθων ἐπεμβαλοῦσα πολλοὺς ἀπέκτεινεν. ὡς δὲ ἀνήχθη πρὸς Ἀλέξανδρον ὑπὸ τῶν Θρᾳκῶν δεδεμένη, πρῶτον μὲν ἀπὸ τῆς ὄψεως καὶ τῆς βαδίσεως ἐφάνη τις ἀξιωματικὴ καὶ μεγαλόφρων, ἀνεκπλήκτως καὶ ἀδεῶς ἑπομένη τοῖς ἄγουσιν ἔπειτα τοῦ βασιλέως ἐρωτήσαντος ἥτις εἴη γυναικῶν, ἀπεκρίνατο Θεαγένους ἀδελφὴ γεγονέναι, τοῦ παραταξαμένου πρὸς Φίλιππον ὑπὲρ τῆς τῶν Ἑλλήνων ἐλευθερίας καὶ πεσόντος ἐν Χαιρωνείᾳ στρατηγοῦντος. θαυμάσας οὖν ὁ Ἀλέξανδρος αὐτῆς καὶ τὴν ἀπόκρισιν καὶ τὴν πρᾶξιν, ἐκέλευσεν ἐλευθέραν ἀπιέναι μετὰ τῶν τέκνων.", "st": "Alex. 12.1"}, {"sp": "N", "t": "Ἀθηναίοις δὲ διηλλάγη, καίπερ οὐ μετρίως ἐνεγκοῦσι τὸ περὶ Θήβας δυστύχημα· καὶ γὰρ τὴν τῶν μυστηρίων ἑορτὴν ἐν χερσὶν ἔχοντες ὑπὸ πένθους ἀφῆκαν, καὶ τοῖς καταφυγοῦσιν ἐπὶ τὴν πόλιν ἁπάντων μετεδίδοσαν τῶν φιλανθρώπων. ἀλλ’ εἴτε μεστὸς ὢν ἤδη τὸν θυμὸν, ὥσπερ οἱ λέοντες, εἴτε ἐπιεικὲς ἔργον ὠμοτάτῳ καὶ σκυθρωποτάτῳ παραβαλεῖν βουλόμενος, οὐ μόνον ἀφῆκεν αἰτίας πάσης, ἀλλὰ καὶ προσέχειν ἐκέλευσε τοῖς πράγμασι τὸν νοῦν τὴν πόλιν, ὡς, εἴ τι συμβαίη περὶ αὐτὸν, ἄρξουσαν τῆς Ἑλλάδος. ὕστερον μέντοι πολλάκις αὐτὸν ἡ Θηβαίων ἀνιᾶσαι συμφορὰ λέγεται καὶ πρᾳότερον οὐκ ὀλίγοις παρασχεῖν. ὅλως δὲ καὶ τὸ περὶ Κλεῖτον ἔργον ἐν οἴνῳ γενόμενον καὶ τὴν πρὸς Ἰνδοὺς τῶν Μακεδόνων ἀποδειλίασιν, ὥσπερ ἀτελῆ τὴν στρατείαν καὶ τὴν δόξαν αὐτοῦ προεμένων, εἰς μῆνιν ἀνῆγε Διονύσου καὶ νέμεσιν. ἦν δὲ Θηβαίων οὐδεὶς τῶν περιγενομένων ὃς ἐντυχών τι καὶ δεηθεὶς ὕστερον οὐ διεπράξατο παρ’ αὐτοῦ, ταῦτα μὲν τὰ περὶ Θήβας.", "st": "Alex. 13.1"}, {"sp": "N", "t": "εἰς δὲ τὸν Ἰσθμὸν τῶν Ἑλλήνων συλλεγέντων καὶ ψηφισαμένων ἐπὶ Πέρσας μετ’ Ἀλεξάνδρου στρατεύειν ἡγεμὼν ἀνηγορεύθη. πολλῶν δὲ καὶ πολιτικῶν ἀνδρῶν καὶ φιλοσόφων ἀπηντηκότων αὐτῷ καὶ συνηδομένων, ἤλπιζε καὶ Διογένην τὸν Σινωπέα ταὐτὸ ποιήσειν, διατρίβοντα περὶ Κόρινθον. ὡς δὲ ἐκεῖνος ἐλάχιστον Ἀλεξάνδρου λόγον ἔχων ἐν τῷ Κρανείῳ σχολὴν ἦγεν, αὐτὸς ἐπορεύετο πρὸς αὐτόν ἔτυχε δὲ κατακείμενος ἐν ἡλίῳ. καὶ μικρὸν μὲν ἀνεκάθισεν, ἀνθρώπων τοσούτων ἐπερχομένων, καὶ διέβλεψεν εἰς τὸν Ἀλέξανδρον. ὡς δὲ ἐκεῖνος ἀσπασάμενος καὶ προσειπὼν αὐτόν ἠρώτησεν εἴ τινος τυγχάνει δεόμενος, μικρὸν εἶπεν, ἀπὸ τοῦ ἡλίου μετάστηθι. πρὸς τοῦτο λέγεται τὸν Ἀλέξανδρον οὕτω διατεθῆναι καὶ θαυμάσαι καταφρονηθέντα τὴν ὑπεροψίαν καὶ τὸ μέγεθος τοῦ ἀνδρός, ὥστε τῶν περὶ αὐτὸν, ὡς ἀπῄεσαν, διαγελώντων καὶ σκωπτόντων, ἀλλὰ μὴν ἐγὼ, εἶπεν, εἰ μὴ Ἀλέξανδρος ἤμην, Διογένης ἂν ἤμην.", "st": "Alex. 14.1"}, {"sp": "N", "t": "βουλόμενος δὲ τῷ θεῷ χρήσασθαι περὶ τῆς στρατείας ἦλθεν εἰς Δελφούς· καὶ κατὰ τύχην ἡμερῶν ἀποφράδων οὐσῶν, ἐν αἷς οὐ νενόμισται θεμιστεύειν, πρῶτον μὲν ἔπεμπε παρακαλῶν τὴν πρόμαντιν. ὡς δὲ ἀρνουμένης καὶ προϊσχομένης τὸν νόμον αὐτὸς ἀναβὰς βίᾳ πρὸς τὸν ναὸν εἷλκεν αὐτήν, ἡ δὲ ὥσπερ ἐξηττημένη τῆς σπουδῆς εἶπεν ἀνίκητος εἶ, ὦ παῖ, τοῦτο ἀκούσας Ἀλέξανδρος οὐκέτι ἔφη χρῄζειν ἑτέρου μαντεύματος, ἀλλ’ ἔχειν ὃν ἐβούλετο παρ’ αὐτῆς χρησμόν.", "st": "Alex. 14.6"}, {"sp": "N", "t": "ἐπεὶ δὲ ὥρμησε πρὸς τὴν στρατείαν, ἄλλα τε δοκεῖ σημεῖα παρὰ τοῦ δαιμονίου γενέσθαι, καὶ τὸ περὶ Λείβηθρα τοῦ Ὀρφέως ξόανον (ἦν δὲ κυπαρίττινον) ἱδρῶτα πολὺν ὑπὸ τὰς ἡμέρας ἐκείνας ἀφῆκε. φοβουμένων δὲ πάντων τὸ σημεῖον, Ἀρίστανδρος ἐκέλευε θαρρεῖν, ὡς ἀοιδίμους καὶ περιβοήτους κατεργασόμενον πράξεις, αἳ πολὺν ἱδρῶτα καὶ πόνον ὑμνοῦσι ποιηταῖς καὶ μουσικοῖς παρέξουσι.", "st": "Alex. 14.8"}, {"sp": "N", "t": "τῆς δὲ στρατιᾶς τὸ πλῆθος οἱ μὲν ἐλάχιστον λέγοντες τρισμυρίους πεζοὺς καὶ τετρακισχιλίους ἱππεῖς, οἱ δὲ πλεῖστον πεζοὺς μὲν τετρακισμυρίους καὶ τρισχιλίους, ἱππέας δὲ πεντακισχιλίους ἀναγράφουσιν. ἐφόδιον δὲ τούτοις οὐ πλέον ἑβδομήκοντα ταλάντων ἔχειν αὐτόν Ἀριστόβουλος ἱστορεῖ, Δοῦρις δὲ τριάκοντα μόνον ἡμερῶν διατροφήν, Ὀνησίκριτος δὲ καὶ διακόσια τάλαντα προσοφείλειν. ἀλλὰ καίπερ ἀπὸ μικρῶν καὶ στενῶν οὕτως ὁρμώμενος, οὐ πρότερον ἐπέβη τῆς νεώς ἢ τὰ τῶν ἑταίρων πράγματα σκεψάμενος ἀπονεῖμαι τῷ μὲν ἀγρόν, τῷ δὲ κώμην, τῷ δὲ συνοικίας πρόσοδον ἢ λιμένος. ἤδη δὲ κατανηλωμένων καὶ διαγεγραμμένων σχεδὸν ἁπάντων τῶν βασιλικῶν ὁ Περδίκκας σεαυτῷ δέ, εἶπεν, ὦ βασιλεῦ, τί καταλείπεις; τοῦ δὲ φήσαντος ὅτι τὰς ἐλπίδας, οὐκοῦν, ἔφη, καὶ ἡμεῖς τούτων κοινωνήσομεν οἱ μετὰ σοῦ στρατευόμενοι. παραιτησαμένου δὲ τοῦ Περδίκκου τὴν διαγεγραμμένην κτῆσιν αὐτῷ, καὶ τῶν ἄλλων φίλων ἔνιοι τὸ αὐτὸ ἐποίησαν, τοῖς δὲ λαμβάνουσι καὶ δεομένοις προθύμως ἐχαρίζετο, καὶ τὰ πλεῖστα τῶν ἐν Μακεδονίᾳ διανέμων οὕτως κατηνάλωσε. τοιαύτῃ μὲν ὁρμῇ καὶ παρασκευῇ διανοίας τὸν Ἑλλήσποντον διεπέρασεν.", "st": "Alex. 15.1"}, {"sp": "N", "t": "ἀναβὰς δὲ εἰς Ἴλιον ἔθυσε τῇ Ἀθηνᾷ καὶ τοῖς ἥρωσιν ἔσπεισε. τὴν δὲ Ἀχιλλέως στήλην ἀλειψάμενος λίπα καὶ μετὰ τῶν ἑταίρων συναναδραμὼν γυμνὸς, ὥσπερ ἔθος ἐστίν, ἐστεφάνωσε, μακαρίσας αὐτόν ὅτι καὶ ζῶν φίλου πιστοῦ καὶ δὲ τελευτήσας μεγάλου κήρυκος ἔτυχεν. ἐν δὲ τῷ περιϊέναι καὶ θεᾶσθαι τὰ κατὰ τὴν πόλιν ἐρομένου τινὸς αὐτόν εἰ βούλεται τὴν Ἀλεξάνδρου λύραν ἰδεῖν, ἐλάχιστα φροντίζειν ἐκείνης ἔφη, τὴν δὲ Ἀχιλλέως ζητεῖν, ᾗ τὰ κλέα καὶ τὰς πράξεις ὕμνει τῶν ἀγαθῶν ἀνδρῶν ἐκεῖνος.", "st": "Alex. 15.1b"}, {"sp": "N", "t": "ἐν δὲ τούτῳ τῶν Δαρείου στρατηγῶν μεγάλην δύναμιν ἡθροικότων καὶ παρατεταγμένων ἐπὶ τῇ διαβάσει τοῦ Γρανικοῦ, μάχεσθαι μὲν ἴσως ἀναγκαῖον ἦν, ὥσπερ ἐν πύλαις τῆς Ἀσίας, περὶ τῆς εἰσόδου καὶ ἀρχῆς· τοῦ δὲ ποταμοῦ τὸ βάθος καὶ τὴν ἀνωμαλίαν καὶ τραχύτητα τῶν πέραν ὄχθων, πρός οὓς ἔδει γίνεσθαι τὴν ἀπόβασιν μετὰ μάχης, τῶν πλείστων δεδιότων, ἐνίων δὲ καὶ τὸ περὶ τόν μῆνα νενομισμένον οἰομένων δεῖν φυλάξασθαι (Δαισίου γὰρ οὐκ εἰώθεισαν οἱ βασιλεῖ τῶν Μακεδόνων ἐξάγειν τὴν στρατιάν), τοῦτο μὲν ἐπηνωρθώσατο κελεύσας δεύτερον Ἀρτεμίσιον ἄγειν, τοῦ δὲ Παρμενίωνος, ὡς ὀψὲ τῆς ὥρας οὔσης, οὐκ ἐῶντος ἀποκινδυνεύειν, εἰπὼν αἰσχύνεσθαι τόν Ἑλλήσποντον εἰ φοβήσεται τόν Γρανικὸν διαβεβηκὼς ἐκεῖνον, ἐμβάλλει τῷ ῥεύματι σὺν ἴλαις ἱππέων τρισκαίδεκα. καὶ πρός ἐναντία βέλη καὶ τόπους ἀπορρῶγας ὅπλοις καταπεφραγμένους καὶ ἵπποις ἐλαύνων, καὶ διὰ ῥεύματος παραφέροντος καὶ περικλύζοντος, ἔδοξε μανικῶς καὶ πρός ἀπόνοιαν μᾶλλον ἢ γνώμῃ στρατηγεῖν. οὐ μὴν ἀλλ’ ἐμφὺς τῇ διαβάσει καὶ κρατήσας τῶν τόπων χαλεπῶς καὶ μόλις, ὑγρῶν καὶ περισφαλῶν γενομένων διὰ τόν πηλόν, εὐθὺς ἠναγκάζετο φύρδην μάχεσθαι καὶ κατ’ ἄνδρα συμπλέκεσθαι τοῖς ἐπιφερομένοις, πρὶν εἰς τάξιν τινὰ καταστῆναι τοὺς διαβαίνοντας. ἐνέκειντο γὰρ κραυγῇ, καὶ τοὺς ἵππους παραβάλλοντες τοῖς ἵπποις ἐχρῶντο δόρασι, καὶ ξίφεσι τῶν δοράτων συντριβέντων. ὠσαμένων δὲ πολλῶν ἐπ’ αὐτὸν ἦν δὲ τῇ πέλτῃ καὶ τοῦ κράνους τῇ χαίτῃ διαπρεπής, ἧς ἑκατέρωθεν εἱστήκει πτερὸν λευκότητι καὶ μεγέθει θαυμαστόν, ἀκοντισθεὶς μὲν ὑπὸ τὴν ὑποπτυχίδα τοῦ θώρακος οὐκ ἐτρώθη, Ῥοισάκου δὲ καὶ Σπιθριδάτου τῶν στρατηγῶν προσφερομένων ἅμα, τόν μὲν ἐκκλίνας, Ῥοισάκῃ δὲ προεμβαλὼν τεθωρακισμένῳ καὶ τὸ δόρυ κατακλάσας ἐπὶ τὸ ἐγχειρίδιον ὥρμησε. συμπεπτωκότων δὲ αὐτῶν ὁ Σπιθριδάτης ὑποστήσας ἐκ πλαγίων τόν ἵππον καὶ μετὰ σπουδῆς συνεξαναστάς κοπίδι βαρβαρικῇ κατήνεγκε· καὶ τόν μὲν λόφον ἀπέρραξε μετὰ θατέρου πτεροῦ, τὸ δὲ κράνος πρὸς τὴν πληγὴν ἀκριβῶς καὶ μόλις ἀντέσχεν, ὥστε τῶν πρώτων ψαῦσαι τριχῶν τὴν πτέρυγα τῆς κοπίδος, ἑτέραν δὲ τόν Σπιθριδάτην πάλιν ἐπαιρόμενον ἔφθασε Κλεῖτος ὁ μέλας τῷ ξυστῷ διελάσας μέσον, ὁμοῦ δὲ καὶ Ῥοισάκης ἔπεσεν ὑπὸ Ἀλεξάνδρου ξίφει πληγείς.", "st": "Alex. 16.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ κινδύνου καὶ ἀγῶνος οὔσης τῆς ἱππομαχίας ἥ τε φάλαγξ διέβαινε τῶν Μακεδόνων καὶ συνῆγον αἱ πεζαὶ δυνάμεις, οὐ μὴν ὑπέστησαν εὐρώστως οὐδὲ πολὺν χρόνον, ἀλλ’ ἔφυγον τραπόμενοι, πλὴν τῶν μισθοφόρων Ἑλλήνων, οὗτοι δὲ πρός τινι λόφῳ συστάντες ᾔτουν τὰ πιστὰ τόν Ἀλέξανδρον. ὁ δὲ θυμῷ μᾶλλον ἢ λογισμῷ πρῶτος ἐμβαλὼν τόν τε ἵππον ἀποβάλλει ξίφει πληγέντα διὰ τῶν πλευρῶν ἦν δὲ ἕτερος, οὐχ ὁ Βουκεφάλας, καὶ τοὺς πλείστους τῶν ἀποθανόντων καὶ τραυματισθέντων ἐκεῖ συνέβη κινδυνεῦσαι καὶ πεσεῖν,’ πρός ἀνθρώπους ἀπεγνωκότας καὶ μαχίμους συμπλεκομένους.", "st": "Alex. 16.12"}, {"sp": "N", "t": "λέγονται δὲ πεζοὶ μὲν δισμύριοι τῶν βαρβάρων, ἱππεῖς δὲ δισχίλιοι πεντακόσιοι πεσεῖν. τῶν δὲ περὶ τόν Ἀλέξανδρον Ἀριστόβουλός φησι τέσσαρας καὶ τριάκοντα νεκροὺς γενέσθαι τοὺς πάντας, ὧν ἐννέα πεζοὺς εἶναι. τούτων μὲν οὖν ἐκέλευσεν εἰκόνας ἀνασταθῆναι χαλκᾶς, ἃς Λύσιππος εἰργάσατο. κοινούμενος δὲ τὴν νίκην τοῖς Ἕλλησιν ἰδίᾳ μὲν τοῖς Ἀθηναίοις ἔπεμψε τῶν αἰχμαλώτων τριακοσίας ἀσπίδας, κοινῇ δὲ τοῖς ἄλλοις λαφύροις ἐκέλευσεν ἐπιγράψαι φιλοτιμοτάτην ἐπιγραφήν Ἀλέξανδρος ὁ Φιλίππου καὶ οἱ Ἕλληνες πλὴν Λακεδαιμονίων ἀπὸ τῶν βαρβάρων τῶν τὴν Ἀσίαν κατοικούντων ἐκπώματα δὲ καὶ πορφύρας, καὶ ὅσα τοιαῦτα τῶν Περσικῶν ἔλαβε, πάντα τῇ μητρὶ πλὴν ὀλίγων ἔπεμψεν.", "st": "Alex. 16.15"}, {"sp": "N", "t": "οὗτος ὁ ἀγὼν μεγάλην εὐθὺς ἐποίησε τῶν πραγμάτων μεταβολὴν πρὸς Ἀλέξανδρον, ὥστε καὶ Σάρδεις, τὸ πρόσχημα τῆς ἐπὶ θαλάσσῃ τῶν βαρβάρων ἡγεμονίας, παραλαβεῖν καὶ τἆλλα προστίθεσθαι. μόνη δὲ Ἁλικαρνασσὸς ἀντέστη καὶ Μίλητος, ἃς ἑλὼν κατὰ κράτος καὶ τὰ περὶ αὐτὰς πάντα χειρωσάμενος ἀμφίβολος ἦν πρὸς τὰ λοιπὰ τῇ γνώμῃ. καὶ πολλάκις μὲν ἔσπευδε Δαρείῳ συμπεσὼν ἀποκινδυνεῦσαι περὶ τῶν ὅλων, πολλάκις δὲ τοῖς ἐπὶ θαλάσσῃ πράγμασι καὶ χρήμασι διενοεῖτο πρῶτον οἷον ἐνασκήσας καὶ ῥώσας αὑτόν οὕτως ἀναβαίνειν ἐπ’ ἐκεῖνον. ἔστι δὲ τῆς Λυκίας κρήνη περὶ τὴν Ξανθίων πόλιν, ἧς τότε λέγουσιν αὐτομάτως περιτραπείσης καὶ ὑπερβαλούσης ἐκ βυθοῦ δέλτον ἐκπεσεῖν χαλκῆν τύπους ἔχουσαν ἀρχαίων γραμμάτων, ἐν οἷς ἐδηλοῦτο παύσεσθαι τὴν Περσῶν ἀρχὴν ὑπὸ Ἑλλήνων καταλυθεῖσαν. τούτοις ἐπαρθείς ἠπείγετο τὴν παραλίαν ἀνακαθήρασθαι μέχρι τῆς Φοινίκης καὶ Κιλικίας, ἡ δὲ τῆς Παμφυλίας παραδρομὴ πολλοῖς γέγονε τῶν ἱστορικῶν ὑπόθεσις γραφικὴ πρὸς ἔκπληξιν καὶ ὄγκον, ὡς θείᾳ τινὶ τύχῃ παραχωρήσασαν Ἀλεξάνδρῳ τὴν θάλασσαν, ἄλλως ἀεὶ τραχεῖαν ἐκ πελάγους προσφερομένην, σπανίως δέ ποτε λεπτοὺς καὶ προσεχεῖς ὑπὸ τὰ κρημνώδη καὶ παρερρωγότα τῆς ὀρεινῆς πάγους διακαλύπτουσαν. δηλοῖ δὲ καὶ Μένανδρος ἐν κωμῳδίᾳ παίζων πρὸς τὸ παράδοξον", "st": "Alex. 17.1"}, {"sp": "N", "t": "ὡς Ἀλεξανδρῶδες ἤδη τοῦτο· κἂν ζητῶ τινα,<br>αὐτόματος οὗτος παρέσται· κἂν διελθεῖν δηλαδή<br>διὰ θαλάσσης δέῃ τόπον τιν’, οὗτος ἔσται μοι βατός.", "st": "Alex. 17.1b"}, {"sp": "N", "t": "αὐτὸς δὲ Ἀλέξανδρος ἐν ταῖς ἐπιστολαῖς οὐδὲν τοιοῦτον τερατευσάμενος ὁδοποιῆσαί φησι τὴν λεγομένην Κλίμακα καὶ διελθεῖν ὁρμήσας ἐκ Φασηλίδος. διὸ καὶ πλείονας ἡμέρας ἐν τῇ πόλει διέτριψεν ἐν αἷς καὶ Θεοδέκτου τεθνηκότος ἦν δὲ Φασηλίτης ἰδὼν εἰκόνα ἀνακειμένην ἐν ἀγορᾷ, μετὰ δεῖπνον ἐπεκώμασε μεθύων καὶ τῶν στεφάνων ἐπέρριψε πολλούς, οὐκ ἄχαριν ἐν παιδιᾷ ἀποδιδοὺς τιμὴν τῇ γενομένῃ δι’ Ἀριστοτέλην καὶ φιλοσοφίαν ὁμιλίᾳ πρὸς τὸν ἄνδρα.", "st": "Alex. 17.8"}, {"sp": "N", "t": "μετὰ ταῦτα Πισιδῶν τε τοὺς ἀντιστάντας ᾕρει καί Φρυγίαν ἐχειροῦτο καί Γόρδιον πόλιν, ἑστίαν Μίδου τοῦ παλαιοῦ γενέσθαι λεγομένην, παραλαβών, τὴν θρυλουμένην ἅμαξαν εἶδε φλοιῷ κρανείας ἐνδεδεμένην, καί λόγον ἐπ’ αὐτῇ πιστευόμενον ὑπὸ τῶν βαρβάρων ἤκουσεν, ὡς τῷ λύσαντι τὸν δεσμὸν εἵμαρται βασιλεῖ γενέσθαι τῆς οἰκουμένης. οἱ μὲν οὖν πολλοί φασι, τῶν δεσμῶν τυφλὰς ἐχόντων τὰς ἀρχὰς καί δι’ ἀλλήλων πολλάκις σκολιοῖς ἑλιγμοῖς ὑποφερομένων, τὸν Ἀλέξανδρον ἀμηχανοῦντα λῦσαι διατεμεῖν τῇ μαχαίρᾳ τὸ σύναμμα, καί πολλὰς ἐξ αὐτοῦ κοπέντος ἀρχὰς φανῆναι. Ἀριστόβουλος δὲ καί πάνυ λέγει ῥᾳδίαν αὐτῷ τὴν λύσιν γενέσθαι, ἐξελόντι τοῦ ῥυμοῦ τὸν ἕστορα καλούμενον, ᾧ συνείχετο τὸ ζυγόδεσμον, εἶθ’ οὕτως ὑφελκύσαντι τὸν ζυγόν.", "st": "Alex. 18.1"}, {"sp": "N", "t": "ἐντεῦθεν Παφλαγόνας τε καί Καππαδόκας προσαγαγόμενος, καὶ τὴν Μέμνονος ἀκούσας τελευτήν, ὃς τῶν ἐπὶ θαλάττῃ Δαρείου στρατηγῶν ἐπίδοξος ἦν Ἀλεξάνδρῳ πολλὰ πράγματα καί μυρίας ἀντιλήψεις καί ἀσχολίας παρέξειν, ἐπερρώσθη πρὸς τὴν ἄνω στρατείαν μᾶλλον. ἤδη δὲ καί Δαρεῖος ἐκ Σούσων κατέβαινεν, ἐπαιρόμενός τε τῷ πλήθει τῆς δυνάμεως ἑξήκοντα γὰρ ἦγε μυριάδας στρατοῦ, καί τινος ὀνείρου θαρρύνοντος αὐτόν, ὃν οἱ μάγοι πρὸς χάριν ἐξηγοῦντο μᾶλλον ἢ κατὰ τὸ εἰκός, ἔδοξε γὰρ πυρὶ νέμεσθαι πολλῷ τὴν Μακεδόνων φάλαγγα, τὸν δὲ Ἀλέξανδρον ἔχοντα στολήν ἣν αὐτὸς ἐφόρει πρότερον ἀστάνδης ὢν βασιλέως, ὑπηρετεῖν αὐτῷ· παρελθόντα δὲ εἰς τὸ τοῦ Βήλου τέμενος ἀφανῆ γενέσθαι. διὰ τούτων, ὡς ἔοικεν, ὑπεδηλοῦτο παρὰ τοῦ θεοῦ λαμπρὰ μὲν γενήσεσθαι καί περιφανῆ τὰ τῶν Μακεδόνων, Ἀλέξανδρον δὲ τῆς μὲν Ἀσίας κρατήσειν, ὥσπερ ἐκράτησε Δαρεῖος ἐξ ἀστάνδου βασιλεὺς γενόμενος, ταχὺ δὲ σὺν δόξῃ τὸν βίον ἀπολείψειν.", "st": "Alex. 18.5"}, {"sp": "N", "t": "ἔτι δὲ μᾶλλον ἐθάρρησε καταγνοὺς δειλίαν Ἀλεξάνδρου πολὺν χρόνον ἐν Κιλικίᾳ διατρίψαντος. ἦν δὲ ἡ διατριβὴ διὰ νόσον, ἣν οἱ μὲν ἐκ κόπων, οἱ δὲ λουσαμένῳ ἐν τῷ τοῦ Κύδνου ῥεύματι καταπαγέντι προσπεσεῖν λέγουσι. τῶν μὲν οὖν ἄλλων ἰατρῶν οὐδεὶς ἐθάρρει βοηθήσειν, ἀλλὰ τὸν κίνδυνον οἰόμενοι πάσης ἰσχυρότερον εἶναι βοηθείας ἐφοβοῦντο τὴν ἐκ τοῦ σφαλῆναι διαβολὴν πρὸς τοὺς Μακεδόνας· Φίλιππος δ’ ὁ Ἀκαρνὰν μοχθηρὰ μὲν ἑώρα τὰ περὶ αὐτὸν ὄντα, τῇ δὲ φιλίᾳ πιστεύων, καὶ δεινὸν ἡγούμενος εἰ κινδυνεύοντι μὴ συγκινδυνεύσει μέχρι τῆς ἐσχάτης πείρας βοηθῶν καὶ παραβαλλόμενος, ἐπεχείρησε φαρμακείᾳ καὶ συνέπεισεν αὐτὸν ὑπομεῖναι καὶ πιεῖν, σπεύδοντα ῥωσθῆναι πρὸς τὸν πόλεμον. ἐν τούτῳ δὲ Παρμενίων ἔπεμψεν ἐπιστολὴν ἀπὸ στρατοπέδου, διακελευόμενος αὐτῷ φυλάξασθαι τὸν Φίλιππον ὡς ὑπὸ Δαρείου πεπεισμένον ἐπὶ δωρεαῖς μεγάλαις καὶ γάμῳ θυγατρὸς ἀνελεῖν Ἀλέξανδρον. ὁ δὲ τὴν ἐπιστολὴν ἀναγνοὺς καὶ μηδενὶ δείξας τῶν φίλων ὑπὸ τὸ προσκεφάλαιον ὑπέθηκεν. ὡς δὲ τοῦ καιροῦ παρόντος εἰσῆλθε μετὰ τῶν ἑταίρων ὁ Φίλιππος τὸ φάρμακον ἐν κύλικι κομίζων, ἐκείνῳ μὲν ἐπέδωκε τὴν ἐπιστολήν, αὐτὸς δὲ τὸ φάρμακον ἐδέξατο προθύμως καὶ ἀνυπόπτως, ὥστε θαυμαστὴν καὶ θεατρικὴν τὴν ὄψιν εἶναι, τοῦ μὲν ἀναγινώσκοντος, τοῦ δὲ πίνοντος, εἶτα ἅμα πρὸς ἀλλήλους ἀποβλεπόντων οὐχ ὁμοίως, ἀλλὰ τοῦ μὲν Ἀλεξάνδρου φαιδρῷ τῷ προσώπῳ καὶ διακεχυμένῳ τὴν πρὸς τὸν Φίλιππον εὐμένειαν καὶ πίστιν ἀποφαίνοντος, ἐκείνου δὲ πρὸς τὴν διαβολὴν ἐξισταμένου καὶ ποτὲ μὲν θεοκλυτοῦντος καὶ πρὸς τὸν οὐρανὸν ἀνατείνοντος τὰς χεῖρας, ποτὲ δὲ τῇ κλίνῃ περιπίπτοντος καὶ παρακαλοῦντος τὸν Ἀλέξανδρον εὐθυμεῖν καὶ προσέχειν αὐτῷ. τὸ γὰρ φάρμακον ἐν ἀρχῇ κρατῆσαν τοῦ σώματος οἷον ἀπέωσε καὶ κατέδυσεν εἰς βάθος τὴν δύναμιν, ὥστε καὶ φωνὴν ἐπιλιπεῖν καὶ τὰ περὶ τὴν αἴσθησιν ἀσαφῆ καὶ μικρὰ κομιδῇ γενέσθαι, λιποθυμίας ἐπιπεσούσης· οὐ μὴν ἀλλὰ ταχέως ἀναληφθεὶς ὑπὸ τοῦ Φιλίππου καὶ ῥαΐσας αὑτὸν ἐπέδειξε τοῖς Μακεδόσιν οὐ γὰρ ἐπαύοντο πρὶν ἰδεῖν τὸν Ἀλέξανδρον ἀθυμοῦντες.", "st": "Alex. 19.1"}, {"sp": "N", "t": "ἦν δέ τις ἐν τῷ Δαρείου στρατῷ πεφευγὼς ἐκ Μακεδονίας ἀνὴρ Μακεδών, Ἀμύντας, οὐκ ἄπειρος τῆς Ἀλεξάνδρου φύσεως, οὗτος ὡρμημένον ἰδὼν Δαρεῖον εἴσω τῶν στενῶν βαδίζειν ἐπ’ Ἀλέξανδρον, ἐδεῖτο κατὰ χώραν ὑπομένειν, ἐν πλάτος ἔχουσι πεδίοις καί ἀναπεπταμένοις πρὸς ἐλάττονας πλήθει τοσούτῳ διαμαχούμενον. ἀποκριναμένου δὲ Δαρείου δεδιέναι μὴ φθάσωσιν αὑτὸν ἀποδράντες οἱ πολέμιοι καί διαφυγὼν Ἀλέξανδρος, ἀλλὰ τούτου γε, εἶπεν, ὦ βασιλεῦ, χάριν θάρρει βαδιεῖται γὰρ ἐκεῖνος ἐπὶ σέ, καί σχεδὸν ἤδη βαδίζει. ταῦτα λέγων Ἀμύντας οὐκ ἔπειθεν, ἀλλ’ ἀναστὰς ἐπορεύετο Δαρεῖος εἰς Κιλικίαν, ἅμα δὲ Ἀλέξανδρος εἰς Συρίαν ἐπ’ ἐκεῖνον. ἐν δὲ τῇ νυκτὶ διαμαρτόντες ἀλλήλων αὖθις ἀνέστρεφον, Ἀλέξανδρος μὲν ἡδόμενός τε τῇ συντυχίᾳ καί σπεύδων ἀπαντῆσαι περὶ τὰ στενά, Δαρεῖος δὲ τὴν προτέραν ἀναλαβεῖν στρατοπεδείαν καί τῶν στενῶν ἐξελίξαι τὴν δύναμιν. ἤδη γὰρ ἐγνώκει παρὰ τὸ συμφέρον ἐμβεβληκὼς ἑαυτὸν εἰς χωρία θαλάττῃ καί ὄρεσι καί ποταμῷ διὰ μέσου ῥέοντι τῷ Πινάρῳ δύσιππα, καί διεσπασμένα πολλαχοῦ, καί πρὸς τῆς ὀλιγότητος τῶν πολεμίων ἔχοντα τὴν θέσιν. Ἀλεξάνδρῳ δὲ τὸν μὲν τόπον ἡ τύχη παρέσχεν, ἐστρατήγησε δὲ τῶν ἀπὸ τῆς τύχης ὑπαρχόντων πρὸς τὸ νικῆσαι βέλτιον, ὅς γε τοσούτῳ πλήθει τῶν βαρβάρων λειπόμενος ἐκείνοις μὲν οὐ παρέσχε κύκλωσιν, αὐτὸς δὲ τῷ δεξιῷ τὸ εὐώνυμον ὑπερβαλὼν καί γενόμενος κατὰ κέρας φυγὴν ἐποίησε τῶν καθ’ αὑτὸν βαρβάρων, ἐν πρώτοις ἀγωνιζόμενος, ὥστε τρωθῆναι ξίφει τὸν μηρόν, ὡς μὲν Χάρης φησίν, ὑπὸ Δαρείου (συμπεσεῖν γὰρ αὐτοὺς εἰς χεῖρας), Ἀλέξανδρος δὲ περὶ τῆς μάχης ἐπιστέλλων τοῖς περὶ τὸν Ἀντίπατρον οὐκ εἴρηκεν ὅστις ἦν ὁ τρώσας, ὅτι δὲ τρωθείη τὸν μηρὸν ἐγχειριδίῳ, δυσχερὲς δ’ οὐδὲν ἀπὸ τοῦ τραύματος συμβαίη γέγραφε.", "st": "Alex. 20.1"}, {"sp": "N", "t": "νικήσας δὲ λαμπρῶς καί καταβαλὼν ὑπὲρ ἕνδεκα μυριάδας τῶν πολεμίων, Δαρεῖον μὲν οὐχ εἷλε τέτταρας σταδίους ἢ πέντε προλαβόντα τῇ φυγῇ, τὸ δὲ ἅρμα καί τὸ τόξον αὐτοῦ λαβὼν ἐπανῆλθε· καί κατέλαβε τοὺς Μακεδόνας τὸν μὲν ἄλλον πλοῦτον ἐκ τοῦ βαρβαρικοῦ στρατοπέδου φέροντας καί ἄγοντας ὑπερβάλλοντα πλήθει, καίπερ εὐζώνων πρὸς τὴν μάχην παραγενομένων καὶ τὰ πλεῖστα τῆς ἀποσκευῆς ἐν Δαμασκῷ καταλιπόντων, τὴν δὲ Δαρείου σκηνὴν ἐξῃρηκότας ἐκείνῳ, θεραπείας τε λαμπρᾶς καί παρασκευῆς καί χρημάτων πολλῶν γέμουσαν. εὐθὺς οὖν ἀποδυσάμενος τὰ ὅπλα πρὸς τὸ λουτρὸν ἐβάδιζεν, εἰπών· ἴωμεν ἀπολουσόμενοι τὸν ἀπὸ τῆς μάχης ἱδρῶτα τῷ Δαρείου λουτρῷ. καί τις τῶν ἑταίρων μὰ τὸν Δία εἶπεν, ἀλλὰ τῷ Ἀλεξάνδρου· τὰ γὰρ τῶν ἡττωμένων εἶναί τε δεῖ καί προσαγορεύεσθαι τοῦ κρατοῦντος. ὡς δὲ εἶδε μὲν ὅλκια καί κρωσσοὺς καί πυέλους καί ἀλαβάστρους, πάντα χρυσοῦ, ἠσκημένα περιττῶς, ὠδώδει δὲ θεσπέσιον οἷον ὑπὸ ἀρωμάτων καί μύρων ὁ οἶκος, ἐκ δὲ τούτου παρῆλθεν εἰς σκηνὴν ὕψει τε καί μεγέθει καί τῷ περὶ τὴν στρωμνὴν καί τραπέζας καί τὸ δεῖπνον αὐτοῦ κόσμῳ θαύματος ἀξίαν, διαβλέψας πρὸς τοὺς ἑταίρους, τοῦτο ἦν, ὡς ἔοικεν, ἔφη, τὸ βασιλεύειν.", "st": "Alex. 20.10"}, {"sp": "N", "t": "τρεπομένῳ δὲ πρὸς τὸ δεῖπνον αὐτῷ φράζει τις ἐν τοῖς αἰχμαλώτοις ἀγομένας μητέρα καὶ γυναῖκα Δαρείου καὶ θυγατέρας δύο παρθένους ἰδούσας τὸ ἅρμα καὶ τὰ τόξα κόπτεσθαι καὶ θρηνεῖν, ὡς ἀπολωλότος ἐκείνου. συχνὸν οὖν ἐπισχὼν χρόνον Ἀλέξανδρος, καὶ ταῖς ἐκείνων τύχαις μᾶλλον ἢ ταῖς ἑαυτοῦ ἐμπαθὴς γενόμενος, πέμπει Λεοννάτον, ἀπαγγεῖλαι κελεύσας ὡς οὔτε Δαρεῖος τέθνηκεν οὔτε Ἀλέξανδρον δεδιέναι χρή· Δαρείῳ γὰρ ὑπὲρ ἡγεμονίας πολεμεῖν, ἐκείναις δὲ πάντα ὑπάρξειν ὧν καὶ Δαρείου βασιλεύοντος ἠξιοῦντο. τοῦ δὲ λόγου ταῖς γυναιξὶν ἡμέρου καὶ χρηστοῦ φανέντος ἔτι μᾶλλον τὰ τῶν ἔργων ἀπήντα φιλάνθρωπα. θάψαι γὰρ ὅσους ἐβούλοντο Περσῶν ἔδωκεν, ἐσθῆτι καὶ κόσμῳ χρησαμέναις ἐκ τῶν λαφύρων, θεραπείας τε καὶ τιμῆς ἦν εἶχον οὐδ’ ὁτιοῦν ἀφεῖλε, συντάξεις δὲ καὶ μείζονας ἐκαρποῦντο τῶν προτέρων. ἡ δὲ καλλίστη καὶ βασιλικωτάτη χάρις ἦν παρ’ αὐτοῦ γυναιξὶ γενναίαις γενομέναις αἰχμαλώτοις καὶ σώφροσι μήτε ἀκοῦσαι τι μήτε ὑπονοῆσαι μήτε προσδοκῆσαι τῶν αἰσχρῶν, ἀλλ’ ὥσπερ οὐκ ἐν στρατοπέδῳ πολεμίων, ἀλλ’ ἐν ἱεροῖς καὶ ἁγίοις φυλαττομένας παρθενῶσιν ἀπόρρητον ἔχειν καὶ ἀόρατον ἑτέροις δίαιταν. καίτοι λέγεταί γε τὴν Δαρείου γυναῖκα πολὺ πασῶν τῶν βασιλίδων εὐπρεπεστάτην γενέσθαι, καθάπερ καὶ αὐτὸς Δαρεῖος ἀνδρῶν κάλλιστος καὶ μέγιστος, τὰς δὲ παῖδας ἐοικέναι τοῖς γονεῦσιν.", "st": "Alex. 21.1"}, {"sp": "N", "t": "ἀλλ’ Ἀλέξανδρος, ὡς ἔοικε, τοῦ νικᾶν τοὺς πολεμίους τὸ κρατεῖν ἑαυτοῦ βασιλικώτερον ἡγούμενος, οὔτε τούτων ἔθιγεν οὔτε ἄλλην ἔγνω γυναῖκα πρὸ γάμου, πλὴν Βαρσίνης. αὕτη δὲ, μετὰ τὴν Μέμνονος τελευτὴν χήρα γενομένη, περὶ Δαμασκὸν ἐλήφθη. πεπαιδευμένη δὲ παιδείαν Ἑλληνικήν καὶ τὸν τρόπον ἐπιεικὴς οὖσα καὶ πατρὸς Ἀρταβάζου γεγονότος ἐκ βασιλέως θυγατρός, ἐγνώσθη, Παρμενίωνος προτρεψαμένου τὸν Ἀλέξανδρον, ὥς φησιν Ἀριστόβουλος, καλῆς καὶ γενναίας ἅψασθαι γυναικός. τὰς δὲ ἄλλας αἰχμαλώτους ὁρῶν ὁ Ἀλέξανδρος κάλλει καὶ μεγέθει διαφερούσας ἔλεγε παίζων ὡς εἰσὶν ἀλγηδόνες ὀμμάτων αἱ Περσίδες, ἀντεπιδεικνύμενος δὲ πρὸς τὴν ἰδέαν τὴν ἐκείνων τὸ τῆς ἰδίας ἐγκρατείας καὶ σωφροσύνης κάλλος, ὥσπερ ἀψύχους εἰκόνας ἀγαλμάτων παρέπεμψεν.", "st": "Alex. 21.7"}, {"sp": "N", "t": "ἐπεὶ δὲ Φιλόξενος ὁ τῶν ἐπὶ θαλάττῃ στρατηγὸς ἔγραψεν εἶναι παρ’ αὐτῷ Θεόδωρόν τινα Ταραντῖνον ἔχοντα παῖδας ὠνίους δύο τὴν ὄψιν ὑπερφυεῖς, καὶ πυνθανόμενος εἰ πρίηται, χαλεπῶς ἐνεγκὼν ἐβόα πολλάκις πρὸς τοὺς φίλους, ἐρωτῶν τί πώποτε Φιλόξενος αἰσχρὸν αὐτῷ συνεγνωκώς τοιαῦτα ὀνείδη προξενῶν κάθηται, τὸν δὲ Φιλόξενον αὐτόν ἐν ἐπιστολῇ πολλὰ λοιδορήσας ἐκέλευσεν αὐτοῖς φορτίοις τὸν Θεόδωρον εἰς τὸν ὄλεθρον ἀποστέλλειν. ἐπέπληξε δὲ καὶ Ἅγνωνι γράψαντι πρὸς αὐτόν ὅτι Κρωβύλον εὐδοκιμοῦντα ἐν Κορίνθῳ βούλεται πριάμενος ἀγαγεῖν πρὸς αὐτόν, πυνθανόμενος δὲ μισθοφόρων τινῶν γύναια διεφθαρκέναι Δάμωνα καὶ Τιμόθεον Μακεδόνας τῶν ὑπὸ Παρμενίωνι στρατευομένων, ἔγραψε Παρμενίωνι κελεύων, ἐὰν ἐλεγχθῶσιν, ὡς θηρία ἐπὶ καταφθορᾷ τῶν ἀνθρώπων γεγονότα τιμωρησάμενον ἀποκτεῖναι. καὶ περὶ ἑαυτοῦ κατὰ λέξιν ἐν ταύτῃ τῇ ἐπιστολῇ γέγραφεν· ἐγὼ γὰρ οὐχ ὅτι ἑωρακὼς ἂν εὑρεθείην τὴν Δαρείου γυναῖκα ἢ βεβουλημένος ἰδεῖν, ἀλλ’ οὐδὲ τῶν λεγόντων περὶ τῆς εὐμορφίας αὐτῆς προσδεδεγμένος τὸν λόγον ἔλεγε δὲ μάλιστα συνιέναι θνητὸς ὢν ἐκ τοῦ καθεύδειν καὶ συνουσιάζειν, ὡς ἀπὸ μιᾶς ἐγγινόμενον ἀσθενείας τῇ φύσει καὶ τὸ πονοῦν καὶ τὸ ἡδόμενον.", "st": "Alex. 22.1"}, {"sp": "N", "t": "ἢν δὲ καὶ γαστρὸς ἐγκρατέστατος, καὶ τοῦτο ἄλλοις τε πολλοῖς ἐδήλωσε καὶ τοῖς πρὸς Ἄδαν λεχθεῖσιν, ἣν ἐποιήσατο μητέρα καὶ Καρίας βασίλισσαν ἀπέδειξεν. ὡς γὰρ ἐκείνη φιλοφρονουμένη πολλὰ μὲν ὄψα καθ’ ἡμέραν ἀπέστελλεν αὐτῷ καὶ πέμματα, τέλος δὲ τοὺς δοκοῦντας εἶναι δεινοτάτους ὀψοποιοὺς καὶ ἀρτοποιούς, ἔφη τούτων μηδενὸς δεῖσθαι· βελτίονας γὰρ ὀψοποιοὺς ἔχειν ὑπὸ τοῦ παιδαγωγοῦ Λεωνίδου δεδομένους αὐτῷ, πρὸς μὲν τὸ ἄριστον, νυκτοπορίαν, πρὸς δὲ τὸ δεῖπνον, ὀλιγαριστίαν. ὁ δ’ αὐτὸς οὗτος ἀνὴρ, ἔφη, καὶ τῶν στρωμάτων ἐπιὼν τὰ ἀγγεῖα καὶ τῶν ἱματίων ἔλυεν, ἐπισκοπῶν μή τί μοι τρυφερὸν ἢ περισσὸν ἡ μήτηρ ἐντέθεικεν.", "st": "Alex. 22.7"}, {"sp": "N", "t": "ἦν δὲ καὶ πρός οἶνον ἧττον ἢ ἐδόκει καταφερής. ἔδοξε δὲ διὰ τὸν χρόνον ὃν οὐ πίνων μᾶλλον ἢ λαλῶν εἷλκεν ἐφ’ ἑκάστης κύλικος, ἀεὶ μακρόν τινα λόγον διατιθέμενος, καὶ ταῦτα πολλῆς σχολῆς οὔσης, ἐπεὶ πρός γε τὰς πράξεις οὐκ οἶνος ἐκεῖνον, οὐχ ὕπνος, οὐ παιδιά τις, οὐ γάμος, οὐ θέα, καθάπερ ἄλλους στρατηγούς, ἐπέσχε. δηλοῖ δὲ ὁ βίος, ὃν βιώσας βραχὺν παντάπασι, πλείστων καὶ μεγίστων πράξεων ἐνέπλησεν. ἐν δὲ ταῖς σχολαῖς πρῶτον μὲν ἀναστὰς καὶ θύσας τοῖς θεοῖς εὐθὺς ἠρίστα καθήμενος· ἔπειτα διημέρευε κυνηγῶν ἢ δικάζων ἢ συντάττων τι τῶν πολεμικῶν ἢ ἀναγινώσκων. εἰ δὲ ὁδὸν βαδίζοι μὴ λίαν ἐπείγουσαν, ἐμάνθανεν ἅμα πορευόμενος ἢ τοξεύειν ἢ ἐπιβαίνειν ἅρματος ἐλαυνομένου καὶ ἀποβαίνειν. πολλάκις δὲ παίζων καὶ ἀλώπεκας ἐθήρευε καὶ ὄρνιθας, ὡς ἔστι λαβεῖν ἐκ τῶν ἐφημερίδων, καταλύσας δὲ καὶ τρεπόμενος πρός λουτρὸν ἢ ἄλειμμα, τοὺς ἐπὶ τῶν σιτοποιῶν καὶ μαγείρων ἀνέκρινεν εἰ τὰ πρός τὸ δεῖπνον εὐτρεπῶς ἔχουσι. καὶ δειπνεῖν μὲν ὀψὲ καὶ σκότους ἤδη κατακλινόμενος ἤρχετο, θαυμαστὴ δὲ ἦν ἡ ἐπιμέλεια καὶ περίβλεψις ἐπὶ τῆς τραπέζης, ὅπως μηδὲν ἀνίσως μηδὲ ὀλιγώρως διανέμοιτο· τὸν δὲ πότον, ὥσπερ εἴρηται, μακρόν ὑπὸ ἀδολεσχίας ἐξέτεινε. καὶ τἆλλα πάντων ἥδιστος ὢν βασιλέων συνεῖναι καὶ χάριτος οὐδεμιᾶς ἀμοιρῶν, τότε ταῖς μεγαλαυχίαις ἀηδὴς ἐγίνετο καὶ λίαν στρατιωτικός, αὐτός τε πρός τὸ κομπῶδες ὑποφερόμενος καὶ τοῖς κόλαξιν ἑαυτὸν ἀνεικὼς ἱππάσιμον, ὑφ’ ὧν οἱ χαριέστεροι τῶν παρόντων ἐπετρίβοντο, μήτε ἁμιλλᾶσθαι τοῖς κόλαζι μήτε λείπεσθαι βουλόμενοι τῶν αὐτῶν ἐπαίνων, τὸ μὲν γὰρ αἰσχρὸν ἐδόκει, τὸ δὲ κίνδυνον ἔφερε. μετὰ δὲ τὸν πότον λουσάμενος ἐκάθευδε πολλάκις μέχρι μέσης ἡμέρας· ἔστι δ’ ὅτε καὶ διημέρευεν ἐν τῷ καθεύδειν.", "st": "Alex. 23.1"}, {"sp": "N", "t": "αὐτὸς μὲν οὖν καὶ ὄψων ἐγκρατὴς ἦν, ὥστε καὶ τὰ σπανιώτατα πολλάκις τῶν ἀπὸ θαλάττης αὐτῷ κομιζομένων ἀκροδρύων καὶ ἰχθύων ἑκάστῳ διαπεμπόμενος τῶν ἑταίρων ἑαυτῷ μόνῳ μηδὲν καταλιπεῖν· τὸ μέντοι δεῖπνον ἦν ἀεὶ μεγαλοπρεπές, καὶ τοῖς εὐτυχήμασι τῆς δαπάνης ἅμα συναυξομένης τέλος εἰς μυρίας δραχμὰς προῆλθεν. ἐνταῦθα δὲ ἔστη, καὶ τοσοῦτον ὡρίσθη τελεῖν τοῖς ὑποδεχομένοις Ἀλέξανδρον.", "st": "Alex. 23.9"}, {"sp": "N", "t": "μετὰ δὲ τὴν μάχην τὴν ἐν Ἰσσῷ πέμψας εἰς Δαμασκόν ἔλαβε τὰ χρήματα καὶ τὰς ἀποσκευὰς καὶ τὰ τέκνα καὶ τὰς γυναῖκας τῶν Περσῶν. καὶ πλεῖστα μὲν ὠφελήθησαν οἱ τῶν Θεσσαλῶν ἱππεῖς· τούτους γὰρ ἄνδρας ἀγαθοὺς διαφερόντως ἐν τῇ μάχῃ γενομένους ἔπεμψεν ἐπίτηδες ὠφεληθῆναι βουλόμενος· ἐνεπλήσθη δὲ καὶ τὸ λοιπὸν εὐπορίας στρατόπεδον. καὶ γευσάμενοι τότε πρῶτον οἱ Μακεδόνες χρυσοῦ καὶ ἀργύρου καὶ γυναικῶν καὶ διαίτης βαρβαρικῆς, ὥσπερ κύνες ἔσπευδον ἁψάμενοι στίβου διώκειν καὶ ἀνιχνεύειν τὸν τῶν Περσῶν πλοῦτον.", "st": "Alex. 24.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ Ἀλεξάνδρῳ πρῶτον ἐδόκει κρατύνεσθαι τὰ πρὸς θαλάσσῃ. Κύπρον μὲν οὖν εὐθὺς οἱ βασιλεῖς ἧκον ἐγχειρίζοντες αὐτῷ, καὶ Φοινίκην πλὴν Τύρου. Τύρον δὲ πολιορκῶν ἑπτὰ μῆνας χώμασι καὶ μηχαναῖς καὶ τριήρεσι διακοσίαις ἐκ θαλάττης, ὄναρ εἶδε τὸν Ἡρακλέα δεξιούμενον αὐτὸν ἀπὸ τοῦ τείχους καὶ καλοῦντα. τῶν δὲ Τυρίων πολλοῖς κατὰ τοὺς ὕπνους ἔδοξεν ὁ Ἀπόλλων λέγειν ὡς ἄπεισι πρὸς Ἀλέξανδρον οὐ γὰρ ἀρέσκειν αὐτῷ τὰ πρασσόμενα κατὰ τὴν πόλιν. ἀλλ’ αὐτοὶ μὲν ὥσπερ ἄνθρωπον αὐτομολοῦντα πρὸς τοὺς πολεμίους ἐπ’ αὐτοφώρῳ τὸν θεὸν εἰληφότες σειράς τε τῷ κολοσσῷ περιέβαλλον αὐτοῦ καὶ καθήλουν πρὸς τὴν βάσιν, Ἀλεξανδριστὴν καλοῦντες. ἑτέραν δὲ ὄψιν Ἀλέξανδρος εἶδε κατὰ τοὺς ὕπνους. σάτυρος αὐτῷ φανεὶς ἐδόκει προσπαίζειν πόρρωθεν, εἶτα βουλομένου λαβεῖν ὑπεξέφευγε· τέλος δὲ πολλὰ λιπαρήσαντος καὶ περιδραμόντος ἦλθεν εἰς χεῖρας. οἱ δὲ μάντεις τοὔνομα διαιροῦντες οὐκ ἀπιθάνως ἔφασαν αὐτῷ· σὴ γενήσεται Τύρος. καὶ κρήνην δέ τινα δεικνύουσι, πρὸς ἣν κατὰ τοὺς ὕπνους ἰδεῖν ἔδοξε τὸν Σάτυρον.", "st": "Alex. 24.4"}, {"sp": "N", "t": "διὰ μέσου δὲ τῆς πολιορκίας ἐπὶ τοὺς Ἄραβας τοὺς προσοικοῦντας τῷ Ἀντιλιβάνῳ στρατεύσας ἐκινδύνευσε διὰ τὸν παιδαγωγὸν Λυσίμαχον· ἐξηκολούθησε γὰρ αὐτῷ λέγων τοῦ Φοίνικος οὐκ εἶναι χείρων οὐδὲ πρεσβύτερος, ἐπεὶ δὲ πλησιάσας τοῖς ὀρεινοῖς καὶ τοὺς ἵππους ἀπολιπὼν πεζὸς ἐβάδιζεν, οἱ μὲν ἄλλοι πολὺ προῆλθον, αὐτὸς δὲ τὸν Λυσίμαχον, ἑσπέρας ἤδη καταλαμβανούσης καὶ τῶν πολεμίων ἐγγὺς ὄντων, ἀπαγορεύοντα καὶ βαρυνόμενον οὐχ ὑπομένων ἀπολιπεῖν, ἀλλ’ ἀνακαλούμενος καὶ παρακομίζων, ἔλαθε τοῦ στρατεύματος ἀποσπασθεὶς μετ’ ὀλίγων καὶ σκότους ἅμα καὶ ῥίγους σφοδροῦ νυκτερεύων ἐν χωρίοις χαλεποῖς. εἶδεν οὖν πόρρω πυρὰ πολλὰ καιόμενα σποράδην τῶν πολεμίων, θαρρῶν δὲ τοῦ σώματος τῇ κουφότητι, καὶ τῷ πονεῖν αὐτὸς ἀεὶ παραμυθούμενος τὴν ἀπορίαν τῶν Μακεδόνων, προσέδραμε τοῖς ἔγγιστα πῦρ καίουσι· καὶ περικαθημένους τῇ πυρᾷ δύο βαρβάρους πατάξας τῷ ἐγχειριδίῳ καὶ δαλὸν ἁρπάσας ἧκε πρὸς τοὺς ἑαυτοῦ κομίζων, ἐγκαύσαντες δὲ πῦρ πολύ τοὺς μὲν εὐθὺς ἐφόβησαν ὥστε φυγεῖν, τοὺς δ’ ἐπιόντας ἐτρέψαντο, καὶ κατηυλίσθησαν ἀκινδύνως, ταῦτα μὲν οὖν Χάρης ἱστόρηκεν.", "st": "Alex. 24.10"}, {"sp": "N", "t": "ἡ δὲ πολιορκία τοιοῦτον ἔσχε πέρας, Ἀλεξάνδρου τὴν μὲν πολλὴν τῆς δυνάμεως ἀναπαύοντος ἀπὸ πολλῶν ἀγώνων τῶν ἔμπροσθεν, ὀλίγους δέ τινας, ὡς μὴ σχολάζοιεν οἱ πολέμιοι, τοῖς τείχεσι προσάγοντος, Ἀρίστανδρος ὁ μάντις ἐσφαγιάζετο καὶ τὰ σημεῖα κατιδὼν θρασύτερον διωρίσατο πρὸς τοὺς παρόντας ἐν ἐκείνῳ τῷ μηνὶ πάντως ἁλώσεσθαι τὴν πόλιν. γενομένου δὲ χλευασμοῦ καὶ γέλωτος ἦν γὰρ ἡ τελευταία τοῦ μηνὸς ἡμέρα, διηπορημένον αὐτόν ἰδὼν ὁ βασιλεύς καὶ συμφιλοτιμούμενος ἀεὶ τοῖς μαντεύμασιν ἐκέλευε μηκέτι τριακάδα τὴν ἡμέραν ἐκείνην, ἀλλὰ τρίτην φθίνοντος ἀριθμεῖν· καὶ τῇ σάλπιγγι σημήνας ἀπεπειρᾶτο τῶν τειχῶν ἐρρωμενέστερον ἤπερ ἐξ ἀρχῆς διενοήθη. γενομένης δὲ λαμπρᾶς ἐπιβολῆς καὶ μηδὲ τῶν ἐπὶ στρατοπέδου καρτερούντων, ἀλλὰ συντρεχόντων καὶ προσβοηθούντων, ἀπεῖπον οἱ Τύριοι· καὶ τὴν πόλιν εἷλε κατ’ ἐκείνην τὴν ἡμέραν.", "st": "Alex. 25.1"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα πολιορκοῦντι Γάζαν αὐτῷ, τῆς Συρίας μεγίστην πόλιν, ἐμπίπτει βῶλος εἰς τὸν ὦμον ἀφεθεὶς ἄνωθεν ὑπὸ ὄρνιθος, ὁ δὲ ὄρνις ἐφ’ ἓν τῶν μηχανημάτων καθίσας ἔλαθεν ἐνσχεθεὶς τοῖς νευρίνοις κεκρυφάλοις, οἷς πρὸς τὰς ἐπιστροφὰς τῶν σχοινίων ἐχρῶντο. καὶ τὸ σημεῖον ἀπέβη κατὰ τὴν Ἀριστάνδρου πρόρρησιν ἐτρώθη μὲν γὰρ Ἀλέξανδρος εἰς τὸν ὦμον, ἔλαβε δὲ τὴν πόλιν. ἀποστέλλων δέ πολλὰ τῶν λαφύρων Ὀλυμπιάδι καὶ Κλεοπάτρᾳ καὶ τοῖς φίλοις, κατέπεμψε καὶ Λεωνίδῃ τῷ παιδαγωγῷ τάλαντα λιβανωτοῦ πεντακόσια καὶ σμύρνης ἑκατόν, ἀναμνησθεὶς παιδικῆς ἐλπίδος. ὁ γὰρ Λεωνίδης, ὡς ἔοικεν, ἐν θυσίᾳ ποτὲ πρὸς τὸν Ἀλέξανδρον ἐπιδραξάμενον ἀμφοτέραις ταῖς χερσὶ καὶ καθαγίσαντα τοῦ θυμιάματος, ὅταν ἔφη, τῆς ἀρωματοφόρου κρατήσῃς, Ἀλέξανδρε, πλουσίως οὕτως ἐπιθυμιάσεις· νῦν δὲ φειδομένως χρῶ τοῖς παροῦσι. τότε οὖν Ἀλέξανδρος ἔγραψε πρὸς αὐτόν ἀπεστάλκαμέν σοι λιβανωτὸν ἄφθονον καὶ σμύρναν, ὅπως παύσῃ πρὸς τοὺς θεοὺς μικρολογούμενος.", "st": "Alex. 25.4"}, {"sp": "N", "t": "κιβωτίου δέ τινος αὐτῷ προσενεχθέντος, οὗ πολυτελέστερον οὐδὲν ἐφάνη τοῖς τὰ Δαρείου χρήματα καὶ τὰς ἀποσκευὰς παραλαμβάνουσιν, ἠρώτα τοὺς φίλους ὅ τι δοκοίη μάλιστα τῶν ἀξίων σπουδῆς εἰς αὐτὸ καταθέσθαι· πολλὰ δὲ πολλῶν λεγόντων αὐτὸς ἔφη τὴν Ἰλιάδα φρουρήσειν ἐνταῦθα καταθέμενος. καὶ ταῦτα μὲν οὐκ ὀλίγοι τῶν ἀξιοπίστων μεμαρτυρήκασιν. εἰ δ’, ὅπερ Ἀλεξανδρεῖς λέγουσιν Ἡρακλείδῃ πιστεύοντες, ἀληθές ἐστιν, οὔκουν ἀργὸς οὐδὲ ἀσύμβολος αὐτῷ συστρατεύειν ἔοικεν Ὅμηρος, λέγουσι γὰρ ὅτι τῆς Αἰγύπτου κρατήσας ἐβούλετο πόλιν μεγάλην καὶ πολυάνθρωπον Ἑλληνίδα συνοικίσας ἐπώνυμον ἑαυτοῦ καταλιπεῖν, καί τινα τόπον γνώμῃ τῶν ἀρχιτεκτόνων ὅσον οὐδέπω διεμετρεῖτο καὶ περιέβαλλεν. εἶτα νύκτωρ κοιμώμενος ὄψιν εἶδε θαυμαστήν ἀνὴρ πολιὸς εὖ μάλα τὴν κόμην καὶ γεραρὸς τὸ εἶδος ἔδοξεν αὐτῷ παραστὰς λέγειν τὰ ἔπη τάδε·", "st": "Alex. 26.1"}, {"sp": "N", "t": "νῆσος ἔπειτά τις ἔστι πολυκλύστῳ ἐνὶ πόντῳ,<br>Αἰγύπτου προπάροιθε· Φάρον δέ ἑ κικλήσκουσιν.", "st": "Alex. 26.1b"}, {"sp": "N", "t": "εὐθὺς οὖν ἐξαναστὰς ἐβάδιζεν ἐπὶ τὴν Φάρον, ἣ τότε μὲν ἔτι νῆσος ἦν, τοῦ Κανωβικοῦ μικρὸν ἀνωτέρω στόματος, νῦν δὲ διὰ χώματος ἀνείληπται πρὸς τὴν ἤπειρον. ὡς οὖν εἶδε τόπον εὐφυΐᾳ διαφέροντα ταινία γάρ ἐστιν ἰσθμῷ πλάτος ἔχοντι σύμμετρον ἐπιεικῶς διείργουσα λίμνην τε πολλὴν καὶ θάλασσαν ἐν λιμένι μεγάλῳ τελευτῶσαν, εἰπὼν ὡς Ὅμηρος ἦν ἄρα τά τε ἄλλα θαυμαστὸς καὶ σοφώτατος ἀρχιτέκτων, ἐκέλευσε διαγράψαι τὸ σχῆμα τῆς πόλεως τῷ τόπῳ συναρμόττοντας. καὶ γῆ μὲν οὐ παρῆν λευκή, τῶν δὲ ἀλφίτων λαμβάνοντες ἐν πεδίῳ μελαγγείῳ κυκλοτερῆ κόλπον ἦγον, οὗ τὴν ἐντὸς περιφέρειαν εὐθεῖαι βάσεις ὥσπερ ἀπὸ κρασπέδων εἰς σχῆμα χλαμύδος ὑπελάμβανον, ἐξ ἴσου συνάγουσαι τὸ μέγεθος, ἡσθέντος δὲ τῇ διαθέσει τοῦ βασιλέως αἰφνίδιον ὄρνιθες ἀπὸ τοῦ ποταμοῦ καὶ τῆς λίμνης, πλήθει τε ἄπειροι καὶ κατὰ γένος παντοδαποὶ καὶ μέγεθος, ἐπὶ τὸν τόπον καταίροντες νέφεσιν ἐοικότες οὐδὲ μικρὸν ὑπέλιπον τῶν ἀλφίτων, ὥστε καὶ τὸν Ἀλέξανδρον διαταραχθῆναι πρὸς τὸν οἰωνόν.", "st": "Alex. 26.6"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τῶν μάντεων θαρρεῖν παραινούντων πολυαρκεστάτην γὰρ οἰκίζεσθαι πόλιν ὑπ’ αὐτοῦ, καὶ παντοδαπῶν ἀνθρώπων ἐσομένην τροφόν ἔργου κελεύσας ἔχεσθαι τοὺς ἐπιμελητάς αὐτὸς ὥρμησεν εἰς Ἄμμωνος, ὁδὸν μακρὰν καὶ πολλὰ μὲν ἔχουσαν ἐργώδη καὶ ταλαίπωρα, κινδύνους δὲ δύο, τὸν μὲν ἀνυδρίας, δι’ ἣν ἔρημός ἐστιν οὐκ ὀλίγων ἡμερῶν, τὸν δέ, εἰ λάβρος ἐν ἄμμῳ βαθείᾳ καὶ ἀχανεῖ πορευομένοις ἐπιπέσοι νότος, ὥς που καὶ πάλαι λέγεται περὶ τὸν Καμβύσου στρατὸν, ἀναστήσας θῖνα μεγάλην καὶ κυματώσας τὸ πεδίον μυριάδας ἀνθρώπων πέντε καταχῶσαι καὶ διαφθεῖραι. ταῦτα πάντα σχεδὸν πάντες ἐλογίζοντο, χαλεπὸν δὲ ἦν Ἀλέξανδρον ἀποτρέψαι πρὸς ὁτιοῦν ὡρμημένον. ἥ τε γὰρ τύχη ταῖς ἐπιβολαῖς ὑπείκουσα τὴν γνώμην ἰσχυρὰν ἐποίει, καὶ τὸ θυμοειδὲς ἄχρι τῶν πραγμάτων ὑπεξέφερε τὴν φιλονεικίαν ἀήττητον, οὐ μόνον πολεμίους, ἀλλὰ καὶ τόπους καὶ καιροὺς καταβιαζομένην.", "st": "Alex. 26.10"}, {"sp": "N", "t": "ἐν γοῦν τῇ τότε πορείᾳ τὰ συντυχόντα ταῖς ἀπορίαις παρὰ τοῦ θεοῦ βοηθήματα τῶν ὑστέρων χρησμῶν ἐπιστεύθη μᾶλλον τρόπον δέ τινα καὶ τοῖς χρησμοῖς ἡ πίστις ἐκ τούτων ὑπῆρξε, πρῶτον μὲν γὰρ ἐκ Διὸς ὕδωρ πολὺ καὶ διαρκεῖς ὑετοὶ γενόμενοι τόν τε τῆς δίψης φόβον ἔλυσαν, καὶ τὴν ξηρότητα κατασβέσαντες τῆς ἄμμου, νοτερᾶς γενομένης καὶ πρὸς αὑτὴν ξυμπεσούσης, εὔπνουν τόν ἀέρα καὶ καθαρώτερον παρέσχον. ἔπειτα τῶν ὅρων, οἵπερ ἦσαν τοῖς ὁδηγοῖς, συγχυθέντων καὶ πλάνης οὔσης καὶ διασπασμοῦ τῶν βαδιζόντων διὰ τὴν ἄγνοιαν, κόρακες ἐκφανέντες ὑπελάμβανον τὴν ἡγεμονίαν τῆς πορείας, ἑπομένων μὲν ἔμπροσθεν πετόμενοι καὶ σπεύδοντες, ὑστεροῦντας δὲ καὶ βραδύνοντας ἀναμένοντες· ὃ δὲ ἦν θαυμασιώτατον, ὡς Καλλισθένης φησί, ταῖς φωναῖς ἀνακαλούμενοι τοὺς πλανωμένους νύκτωρ καὶ κλάζοντες εἰς ἴχνος καθίστασαν τῆς πορείας.", "st": "Alex. 27.1"}, {"sp": "N", "t": "ἐπεὶ δὲ διεξελθὼν τὴν ἔρημον ἧκεν εἰς τόν τόπον, ὁ μὲν προφήτης αὐτὸν ὁ Ἄμμωνος ἀπὸ τοῦ θεοῦ χαίρειν, ὡς ἀπὸ πατρὸς, προσεῖπεν ὁ δὲ ἐπήρετο μή τις αὐτὸν εἴη διαπεφευγὼς τῶν τοῦ πατρὸς φονέων. εὐφημεῖν δὲ τοῦ προφήτου κελεύσαντος, οὐ γὰρ εἶναι πατέρα θνητὸν αὐτῷ, μεταβαλὼν ἐπυνθάνετο, τοὺς Φιλίππου φονεῖς εἰ πάντας εἴη τετιμωρημένος εἶτα περὶ τῆς ἀρχῆς, εἰ πάντων αὐτῷ δίδωσιν ἀνθρώπων κυρίῳ γενέσθαι, χρήσαντος δὲ τοῦ θεοῦ καὶ τοῦτο διδόναι καὶ Φίλιππον ἀπέχειν ἔκπλεω τὴν δίκην, ἐδωρεῖτο τόν θεὸν ἀναθήμασι λαμπροῖς καὶ χρήμασι τοὺς ἀνθρώπους.", "st": "Alex. 27.5"}, {"sp": "N", "t": "ταῦτα περὶ τῶν χρησμῶν οἱ πλεῖστοι γράφουσιν αὐτὸς δὲ Ἀλέξανδρος ἐν ἐπιστολῇ πρὸς τὴν μητέρα φησὶ γεγονέναι τινὰς αὐτῷ μαντείας ἀπορρήτους, ἃς αὐτὸς ἐπανελθὼν φράσει πρὸς μόνην ἐκείνην. ἔνιοι δέ φασι τόν μὲν προφήτην Ἑλληνιστὶ βουλόμενον προσειπεῖν μετά τινος φιλοφροσύνης ὦ παιδίον, ἐν τῷ τελευταίῳ τῶν φθόγγων ὑπὸ βαρβαρισμοῦ πρὸς τὸ σίγμα ἐξενεχθῆναι καὶ εἰπεῖν, ὧ παιδίος, ἀντὶ τοῦ νῦ τῷ σίγμα χρησάμενον, ἀσμένῳ δὲ τῷ Ἀλεξάνδρῳ τὸ σφάλμα τῆς φωνῆς γενέσθαι καὶ διαδοθῆναι λόγον ὡς παῖδα Διὸς αὐτὸν τοῦ θεοῦ προσειπόντος. λέγεται δὲ καὶ Ψάμμωνος ἐν Αἰγύπτῳ τοῦ φιλοσόφου διακούσας ἀποδέξασθαι μάλιστα τῶν λεχθέντων, ὅτι πάντες οἱ ἄνθρωποι βασιλεύονται ὑπὸ θεοῦ· τὸ γὰρ ἄρχον ἐν ἑκάστῳ καὶ κρατοῦν θεῖόν ἐστιν ἔτι δὲ μᾶλλον αὐτὸς περὶ τούτων φιλοσοφώτερον δοξάζειν καὶ λέγειν, ὡς πάντων μὲν ὄντα κοινὸν ἀνθρώπων πατέρα τόν θεόν, ἰδίους δὲ ποιούμενον ἑαυτοῦ τοὺς ἀρίστους.", "st": "Alex. 27.8"}, {"sp": "N", "t": "καθόλου δὲ πρὸς μὲν τοὺς βαρβάρους σοβαρὸς ἦν καὶ σφόδρα πεπεισμένῳ περὶ τῆς ἐκ θεοῦ γενέσεως καὶ τεκνώσεως ὅμοιος, τοῖς δὲ Ἕλλησι μετρίως καὶ ὑποφειδομένως ἑαυτὸν ἐξεθείαζε πλὴν περὶ Σάμου γράφων Ἀθηναίοις, ἐγὼ μὲν οὐκ ἂν, φησὶν, ὑμῖν ἐλευθέραν πόλιν ἔδωκα καὶ ἔνδοξον ἔχετε δὲ αὐτὴν λαβόντες παρὰ τοῦ τότε κυρίου καὶ πατρὸς ἐμοῦ προσαγορευομένου, λέγων τὸν Φίλιππον. ὕστερον δὲ πληγῇ περιπεσὼν ὑπὸ τοξεύματος καὶ περιαλγὴς γενόμενος, τοῦτο μὲν εἶπεν, ὦ φίλοι, τὸ ῥέον αἷμα, καὶ οὐκ", "st": "Alex. 28.1"}, {"sp": "N", "t": "ἰχώρ, οἷός πέρ τε ῥέει μακάρεσσι θεοῖσιν.", "st": "Alex. 28.1b"}, {"sp": "N", "t": "ἐπεὶ δὲ μεγάλης ποτὲ βροντῆς γενομένης καὶ πάντων ἐκπλαγέντων Ἀνάξαρχος ὁ σοφιστὴς παρὼν ἔφη πρὸς αὐτὸν, μή τι σὺ τοιοῦτον ὁ τοῦ Διός; γελάσας ἐκεῖνος, οὐ βούλομαι γὰρ, εἶπε, φοβερὸς εἶναι τοῖς φίλοις, ὥσπερ σύ με κελεύεις ὁ καταφαυλίζων μου τὸ δεῖπνον, ὅτι ταῖς τραπέζαις ἰχθύας ὁρᾷς· ἐπικειμένους, οὐ σατραπῶν κεφαλάς. τῷ γὰρ ὄντι λέγεται τὸν Ἀνάξαρχον ἰχθυδίων Ἡφαιστίωνι πεμφθέντων ὑπὸ τοῦ βασιλέως τὸν προειρημένον ἐπιφθέγξασθαι λόγον, οἷον ἐξευτελίζοντα καὶ κατειρωνευόμενον τοὺς τὰ περίβλεπτα μεγάλοις πόνοις καὶ κινδύνοις διώκοντας, ὡς οὐδὲν ἢ μικρὸν ἐν ἡδοναῖς καὶ ἀπολαύσεσι πλέον ἔχοντας τῶν ἄλλων. ὁ δ’ οὖν Ἀλέξανδρος καὶ ἀπὸ τῶν εἰρημένων δῆλός ἐστιν αὐτὸς οὐδὲν πεπονθὼς οὐδὲ τετυφωμένος, ἀλλὰ τοὺς ἄλλους καταδουλούμενος τῇ δόξῃ τῆς θειότητος.", "st": "Alex. 28.4"}, {"sp": "N", "t": "εἰς δὲ Φοινίκην ἐπανελθὼν ἐξ Αἰγύπτου θυσίας τοῖς θεοῖς καὶ πομπὰς ἐπετέλει καὶ χορῶν κυκλίων καὶ τραγικῶν ἀγῶνας, οὐ μόνον ταῖς παρασκευαῖς, ἀλλὰ καὶ ταῖς ἁμίλλαις λαμπροὺς γενομένους, ἐχορήγουν γὰρ οἱ βασιλεῖς τῶν Κυπρίων, ὥσπερ Ἀθήνησιν οἱ κληρούμενοι τὰς φυλάς, καὶ ἠγωνίζοντο θαυμαστῇ φιλοτιμίᾳ πρὸς ἀλλήλους, μάλιστα δὲ Νικοκρέων ὁ Σαλαμίνιος καὶ Πασικράτης ὁ Σόλιος διεφιλονείκησαν. οὗτοι γὰρ ἔλαχον τοῖς ἐνδοξοτάτοις ὑποκριταῖς χορηγεῖν, Πασικράτης μὲν Ἀθηνοδώρῳ, Νικοκρέων δὲ Θεσσαλῷ, περὶ ὃν ἐσπουδάκει καὶ αὐτὸς Ἀλέξανδρος, οὐ μὴν διέφηνε τὴν σπουδὴν πρότερον ἢ ταῖς ψήφοις ἀναγορευθῆναι νικῶντα τὸν Ἀθηνόδωρον. τότε δέ, ὡς ἔοικεν, ἀπιὼν ἔφη τοὺς μὲν κριτὰς ἐπαινεῖν, αὐτὸς μέντοι μέρος ἂν ἡδέως προέσθαι τῆς βασιλείας ἐπὶ τῷ μὴ Θεσσαλὸν ἰδεῖν νενικημένον. ἐπεὶ δὲ Ἀθηνόδωρος ὑπὸ τῶν Ἀθηναίων ζημιωθείς, ὅτι πρὸς τὸν ἀγῶνα τῶν Διονυσίων οὐκ ἀπήντησεν, ἠξίου γράψαι περὶ αὐτοῦ τὸν βασιλέα, τοῦτο μὲν οὐκ ἐποίησε, τὴν δὲ ζημίαν ἀπέστειλε παρ’ ἑαυτοῦ. Λύκωνος δὲ τοῦ Σκαρφέως εὐημεροῦντος ἐν τῷ θεάτρῳ καὶ στίχον εἰς τὴν κωμῳδίαν ἐμβαλόντος αἴτησιν περιέχοντα δέκα ταλάντων, γελάσας ἔδωκε.", "st": "Alex. 29.1"}, {"sp": "N", "t": "Δαρείου δὲ πέμψαντος ἐπιστολὴν πρὸς αὐτὸν καὶ φίλους δεομένους μύρια μὲν ὑπὲρ τῶν ἑαλωκότων λαβεῖν τάλαντα, τὴν δὲ ἐντὸς Εὐφράτου πᾶσαν ἔχοντα καὶ γήμαντα μίαν τῶν θυγατέρων φίλον εἶναι καὶ σύμμαχον, ἐκοινοῦτο τοῖς ἑταίροις καὶ Παρμενίωνος εἰπόντος ἐγὼ μὲν, εἰ Ἀλέξανδρος ἤμην, ἔλαβον ἂν ταῦτα, κἀγὼ, νὴ Δία, εἶπεν ὁ Ἀλέξανδρος, εἰ Παρμενίων πρὸς δὲ τὸν Δαρεῖον ἔγραψεν, ὡς οὐδενὸς ἀτυχήσει τῶν φιλανθρώπων ἐλθὼν πρὸς αὐτόν, εἰ δὲ μή, αὐτὸς ἐπ’ ἐκεῖνον ἤδη πορεύεσθαι.", "st": "Alex. 29.7"}, {"sp": "N", "t": "ταχὺ μέντοι μετεμελήθη τῆς Δαρείου γυναικὸς ἀποθανούσης ἐν ὠδῖσι καὶ φανερὸς ἦν ἀνιώμενος ὡς ἐπίδειξιν οὐ μικρὰν ἀφῃρημένος χρηστότητος. ἔθαψεν οὖν τὴν ἄνθρωπον οὐδεμιᾶς πολυτελείας φειδόμενος, τῶν δὲ θαλαμηπόλων τις εὐνούχων, οἳ συνεαλώκεισαν ταῖς γυναιξίν, ἀποδρὰς ἐκ τοῦ στρατοπέδου καὶ πρὸς Δαρεῖον ἀφιππασάμενος, Τείρεως ὄνομα, φράζει τὸν θάνατον αὐτῷ τῆς γυναικός. ὡς δὲ πληξάμενος τὴν κεφαλὴν καὶ ἀνακλαύσας φεῦ τοῦ Περσῶν ἔφη δαίμονος, εἰ τὴν βασιλέως γυναῖκα καὶ ἀδελφὴν οὐ μόνον αἰχμάλωτον γενέσθαι ζῶσαν, ἀλλὰ καὶ τελευτήσασαν ἄμοιρον κεῖσθαι ταφῆς βασιλικῆς ὑπολαβὼν ὁ θαλαμηπόλος, ἀλλὰ ταφῆς γε χάριν εἶπεν, ὦ βασιλεῦ, καὶ τιμῆς ἁπάσης καὶ τοῦ πρέποντος οὐδὲν ἔχεις αἰτιάσασθαι τὸν πονηρὸν δαίμονα Περσῶν. οὔτε γάρ ζώσῃ τῇ δεσποίνῃ Στατείρᾳ καὶ μητρὶ σῇ καὶ τέκνοις ἐνέδει τῶν πρόσθεν ἀγαθῶν καὶ καλῶν ἢ τὸ σὸν ὁρᾶν φῶς, ὃ πάλιν ἀναλάμψει λαμπρὸν ὁ κύριος Ὠρομάσδης, οὔτε ἀποθανοῦσα κόσμου τινὸς ἄμοιρος γέγονεν, ἀλλὰ καὶ πολεμίων τετίμηται δάκρυσιν. οὕτω γάρ ἐστι χρηστὸς κρατήσας Ἀλέξανδρος, ὡς δεινὸς μαχόμενος.", "st": "Alex. 30.1"}, {"sp": "N", "t": "ταῦτα ἀκούσαντα Δαρεῖον ἡ ταραχὴ καὶ τὸ πάθος ἐξέφερε πρὸς ὑποψίας ἀτόπους· καὶ τὸν εὐνοῦχον ἐνδοτέρω τῆς σκηνῆς ἀπαγαγών, εἰ μὴ καὶ σὺ μετὰ τῆς Περσῶν, ἔφη, τύχης μακεδονίζεις, ἀλλ’ ἔτι σοι δεσπότης ἐγὼ Δαρεῖος, εἰπέ μοι σεβόμενος Μίθρου τε φῶς μέγα καὶ δεξιὰν βασίλειον, ἄρα μὴ τὰ μικρότατα τῶν Στατείρας κλαίω κακῶν, οἰκτρότερα δὲ ζώσης ἐπάσχομεν, καὶ μᾶλλον ἂν κατ’ ἀξίαν ἐδυστυχοῦμεν ὠμῷ καὶ σκυθρωπῷ περιπεσόντες ἐχθρῷ; τί γὰρ εὐπρεπὲς ἀνδρὶ νέῳ πρὸς ἐχθροῦ γυναῖκα μέχρι τιμῆς τοσαύτης συμβόλαιον; ἔτι λέγοντος αὐτοῦ καταβαλὼν ἐπὶ τοὺς πόδας Τείρεως αὑτὸν ἱκέτευεν εὐφημεῖν καὶ μήτε Ἀλέξανδρον ἀδικεῖν μήτε τὴν τεθνεῶσαν ἀδελφὴν καὶ γυναῖκα καταισχῦναι, μήτε αὑτοῦ τὴν μεγίστην ὧν ἔπταικεν ἀφαιρεῖσθαι παραμυθίαν, τὸ δοκεῖν ὑπ’ ἀνδρὸς ἡττῆσθαι κρείττονος ἢ κατὰ τὴν ἀνθρωπίνην φύσιν, ἀλλὰ καὶ θαυμάζειν Ἀλέξανδρον ὡς πλείονα ταῖς Περσῶν γυναιξὶ σωφροσύνην ἢ Πέρσαις ἀνδρείαν ἐπιδεδειγμένον. ἅμα δὲ ὅρκους τε φρικώδεις τοῦ θαλαμηπόλου κινοῦντος ὑπὲρ τούτων, καὶ περὶ τῆς ἄλλης ἐγκρατείας καὶ μεγαλοψυχίας τῆς Ἀλεξάνδρου λέγοντος, ἐξελθὼν πρὸς τοὺς ἑταίρους ὁ Δαρεῖος καὶ χεῖρας ἀνατείνας πρὸς τὸν οὐρανόν ἐπεύξατο· θεοὶ γενέθλιοι καὶ βασίλειοι, μάλιστα μὲν ἐμοὶ διδοίητε τὴν Περσῶν τύχην εἰς ὀρθὸν αὖθις σταθεῖσαν ἐφ’ οἷς ἐδεξάμην ἀγαθοῖς ἀπολιπεῖν, ἵνα κρατήσας ἀμείψωμαι τὰς Ἀλεξάνδρου χάριτας ὧν εἰς τὰ φίλτατα πταίσας ἔτυχον· εἰ δ’ ἄρα τις οὗτος εἱμαρτὸς ἥκει χρόνος, ὀφειλόμενος νεμέσει καὶ μεταβολῇ, παύσασθαι τὰ Περσῶν, μηδεὶς ἄλλος ἀνθρώπων καθίσειεν εἰς τὸν Κύρου θρόνον πλὴν Ἀλεξάνδρου ταῦτα μὲν οὕτω γενέσθαι τε καὶ λεχθῆναί φασιν οἳ πλεῖστοι τῶν συγγραφέων.", "st": "Alex. 30.7"}, {"sp": "N", "t": "Ἀλέξανδρος δὲ τὴν ἐντὸς τοῦ Εὐφράτου πᾶσαν ὑφ’ ἑαυτῷ ποιησάμενος ἤλαυνεν ἐπὶ Δαρεῖον ἑκατὸν μυριάσι στρατοῦ καταβαίνοντα. καί τις αὐτῷ φράζει τῶν ἑταίρων, ὡς δὴ γέλωτος ἄξιον πρᾶγμα, τοὺς ἀκολούθους παίζοντας εἰς δύο μέρη διῃρηκέναι σφᾶς αὐτούς, ὧν ἑκατέρου στρατηγὸν εἶναι καὶ ἡγεμόνα, τὸν μὲν Ἀλέξανδρον, τὸν δὲ Δαρεῖον ὑπ’ αὐτῶν προσαγορευόμενον· ἀρξαμένους δὲ βώλοις ἀκροβολίζεσθαι πρὸς ἀλλήλους, εἶτα πυγμαῖς, τέλος ἐκκεκαῦσθαι τῇ φιλονεικίᾳ καὶ μέχρι λίθων καὶ ξύλων, πολλοὺς καὶ δυσκαταπαύστους γεγονότας. ταῦτα ἀκούσας ἐκέλευσεν αὐτοὺς μονομαχῆσαι τοὺς ἡγεμόνας καὶ τὸν μὲν Ἀλέξανδρον αὐτὸς ὥπλισε, τὸν δὲ Δαρεῖον Φιλώτας, ἐθεᾶτο δὲ ὁ στρατός, ἐν οἰωνῷ τινι τοῦ μέλλοντος τιθέμενος τὸ γιγνόμενον. ἰσχυρᾶς δὲ τῆς μάχης γενομένης ἐνίκησεν ὁ καλούμενος Ἀλέξανδρος, καὶ δωρεὰν ἔλαβε δώδεκα κώμας καὶ στολῇ Περσικῇ χρῆσθαι. ταῦτα μὲν οὖν Ἐρατοσθένης ἱστόρηκε.", "st": "Alex. 31.1"}, {"sp": "N", "t": "τὴν δὲ μεγάλην μάχην πρὸς Δαρεῖον οὐκ ἐν Ἀρβήλοις, ὥσπερ οἱ πολλοὶ γράφουσιν, ἀλλὰ ἐν Γαυγαμήλοις γενέσθαι συνέπεσε, σημαίνειν δέ φασιν οἶκον καμήλου τὴν διάλεκτον, ἐπεὶ τῶν πάλαι τις βασιλέων ἐκφυγὼν πολεμίους ἐπὶ καμήλου δρομάδος ἐνταῦθα καθίδρυσεν αὐτήν, ἀποτάξας τινὰς κώμας καὶ προσόδους εἰς τὴν ἐπιμέλειαν. ἡ μὲν οὖν σελήνη τοῦ Βοηδρομιῶνος ἐξέλιπε περὶ τὴν τῶν μυστηρίων τῶν Ἀθήνησιν ἀρχήν, ἑνδεκάτῃ δὲ ἀπὸ τῆς ἐκλείψεως νυκτὶ τῶν στρατοπέδων ἐν ὄψει γεγονότων, Δαρεῖος μὲν ἐν ὅπλοις συνεῖχε τὴν δύναμιν, ὑπὸ λαμπάδων ἐπιπορευόμενος τὰς τάξεις, Ἀλέξανδρος δὲ τῶν Μακεδόνων ἀναπαυομένων αὐτὸς πρὸ τῆς σκηνῆς μετὰ τοῦ μάντεως Ἀριστάνδρου διέτριβεν, ἱερουργίας τινὰς ἀπορρήτους ἱερουργούμενος καὶ τῷ Φόβῳ σφαγιαζόμενος. οἱ δὲ πρεσβύτεροι τῶν ἑταίρων, καὶ μάλιστα Παρμενίων, ὡς τὸ μὲν πεδίον τὸ μεταξὺ τοῦ Νιφάτου καὶ τῶν ὀρῶν τῶν Γορδυαίων ἅπαν ἑωρᾶτο καταλαμπόμενον τοῖς βαρβαρικοῖς φέγγεσιν, ἀτέκμαρτος δέ τις φωνὴ συμμεμιγμένη καὶ θόρυβος ἐκ τοῦ στρατοπέδου καθάπερ ἐξ ἀχανοῦς προσήχει πελάγους, θαυμάσαντες τὸ πλῆθος καὶ πρὸς ἀλλήλους διαλεχθέντες ὡς μέγα καὶ χαλεπὸν ἔργον εἴη συμπεσόντας ἐκ προφανοῦς τοσοῦτον ὤσασθαι πόλεμον, ἀπὸ τῶν ἱερῶν γενομένῳ τῷ βασιλεῖ προσελθόντες ἔπειθον αὐτὸν ἐπιχειρῆσαι νύκτωρ τοῖς πολεμίοις καὶ τῷ σκότῳ τὸ φοβερώτατον συγκαλύψαι τοῦ μέλλοντος ἀγῶνος. ὁ δὲ τὸ μνημονευόμενον εἰπὼν, οὐ κλέπτω τὴν νίκην, ἐνίοις μὲν ἔδοξε μειρακιώδη καὶ κενὴν ἀπόκρισιν πεποιῆσθαι, παίζων πρὸς τοσοῦτον κίνδυνον, ἐνίοις δὲ καὶ τῷ παρόντι θαρρεῖν καὶ στοχάζεσθαι τοῦ μέλλοντος ὀρθῶς, μὴ διδοὺς πρόφασιν ἡττηθέντι Δαρείῳ πρὸς ἄλλην αὖθις ἀναθαρρῆσαι πεῖραν, αἰτιωμένῳ τούτων νύκτα καὶ σκότος, ὡς ὄρη καὶ στενὰ καὶ θάλασσαν τῶν προτέρων. οὐ γὰρ ὅπλων οὐδὲ σωμάτων ἀπορίᾳ παύσεσθαι πολεμοῦντα Δαρεῖον ἀπὸ τηλικαύτης δυνάμεως καὶ χώρας τοσαύτης, ἀλλ’ ὅταν ἀφῇ τὸ φρόνημα καὶ τὴν ἐλπίδα, δι’ ἐμφανοῦς ἥττης κατὰ κράτος ἐξελεγχθείς.", "st": "Alex. 31.6"}, {"sp": "N", "t": "ἀπελθόντων δὲ τούτων κατακλιθεὶς ὑπὸ σκηνὴν λέγεται τὸ λοιπὸν μέρος τῆς νυκτὸς ὕπνῳ βαθεῖ κρατηθῆναι παρὰ τὸ εἰωθός, ὥστε θαυμάζειν ἐπελθόντας ὄρθρου τοὺς ἡγεμόνας καὶ παρ’ αὑτῶν ἐξενεγκεῖν παράγγελμα πρῶτον ἀριστοποιεῖσθαι τοὺς στρατιώτας ἔπειτα τοῦ καιροῦ κατεπείγοντος εἰσελθόντα Παρμενίωνα καὶ παραστάντα τῇ κλίνῃ δὶς ἢ τρὶς αὐτοῦ φθέγξασθαι τοὔνομα· καὶ διεγερθέντος οὕτως ἐρωτᾶν ὅ τι δὴ πεπονθὼς ὕπνον καθεύδοι νενικηκότος, οὐχὶ μέλλοντος ἀγωνιεῖσθαι τὸν μέγιστον τῶν ἀγώνων. τὸν γοῦν Ἀλέξανδρον εἰπεῖν διαμειδιάσαντα τί γάρ; οὐκ ἤδη σοι νενικηκέναι δοκοῦμεν ἀπηλλαγμένοι τοῦ πλανᾶσθαι καὶ διώκειν ἐν πολλῇ καὶ κατεφθαρμένῃ φυγομαχοῦντα χώρᾳ, Δαρεῖον; οὐ μόνον δὲ πρὸ τῆς μάχης, ἀλλὰ καὶ παρ’ αὐτὸν τὸν κίνδυνον ἐπεδείξατο μέγαν καὶ συνεστηκότα τῷ λογίζεσθαι καὶ θαρρεῖν ἑαυτόν. ἔσχε γὰρ ὁ ἀγὼν ὑποτροπὴν καὶ σάλον ἐν τῷ εὐωνύμῳ κέρατι κατὰ Παρμενίωνα, τῆς Βακτριανῆς ἵππου ῥόθῳ πολλῷ καὶ μετὰ βίας παρεμπεσούσης εἰς τοὺς Μακεδόνας, Μαζαίου δὲ περιπέμψαντος ἔξω τῆς φάλαγγος ἱππεῖς τοῖς σκευοφυλακοῦσι προσβαλοῦντας. διὸ καὶ θορυβούμενος ὑπ’ ἀμφοτέρων ὁ Παρμενίων ἀπέστειλε πρὸς Ἀλέξανδρον ἀγγέλους φράζοντας οἴχεσθαι τὸν χάρακα καὶ τὰς ἀποσκευάς, εἰ μὴ κατὰ τάχος βοήθειαν ὀχυρὰν ἀπὸ τοῦ στόματος πέμψειε τοῖς ὄπισθεν. ἔτυχε μὲν οὖν κατ’ ἐκεῖνο καιροῦ τοῖς περὶ αὐτὸν ἐφόδου διδοὺς σημεῖον ὡς δὲ ἤκουσε τὰ παρὰ τοῦ Παρμενίωνος, οὐκ ἔφη σωφρονεῖν αὐτὸν οὐδὲ ἐντὸς εἶναι τῶν λογισμῶν, ἀλλ’ ἐπιλελῆσθαι ταραττόμενον ὅτι νικῶντες μὲν προσκτήσονται καὶ τὰ τῶν πολεμίων, ἡττωμένοις δὲ φροντιστέον οὐ χρημάτων οὐδὲ ἀνδραπόδων, ἀλλ’ ὅπως ἀποθανοῦνται καλῶς καὶ λαμπρῶς ἀγωνιζόμενοι.", "st": "Alex. 32.1"}, {"sp": "N", "t": "ταῦτα ἐπιστείλας Παρμενίωνι τὸ κράνος περιέθετο, τὸν δὲ ἄλλον ὁπλισμόν εὐθὺς ἀπὸ σκηνῆς εἶχεν, ὑπένδυμα τῶν Σικελικῶν ζωστόν, ἐπὶ δὲ τούτῳ θώρακα διπλοῦν λινοῦν ἐκ τῶν ληφθέντων ἐν Ἰσσῷ. τὸ δὲ κράνος ἦν μὲν σιδηροῦν, ἔστιλβε δὲ ὥσπερ ἄργυρος καθαρός, ἔργον Θεοφίλου, συνήρμοστο δὲ αὐτῷ περιτραχήλιον ὁμοίως σιδηροῦν λιθοκόλλητον· μάχαιραν δὲ θαυμαστὴν βαφῇ καὶ κουφότητι, δωρησαμένου τοῦ Κιτιέων βασιλέως, εἶχεν, ἠσκημένος τὰ πολλὰ χρῆσθαι μαχαίρᾳ παρὰ τὰς μάχας. ἐπιπόρπωμα δὲ ἐφόρει τῇ μὲν ἐργασίᾳ σοβαρώτερον ἢ κατὰ τὸν ἄλλον ὁπλισμόν ἦν γὰρ ἔργον Ἑλικῶνος τοῦ παλαιοῦ, τιμὴ δὲ τῆς Ῥοδίων πόλεως, ὑφ’ ἧς ἐδόθη δῶρον· ἐχρῆτο δὲ καὶ τούτῳ πρὸς τοὺς ἀγῶνας. ἄχρι μὲν οὖν συντάττων τι τῆς φάλαγγος ἢ παρακελευόμενος ἢ διδάσκων ἢ ἐφορῶν παρεξήλαυνεν, ἄλλον ἵππον εἶχε, τοῦ Βουκεφάλα φειδόμενος ἤδη παρήλικος ὄντος χωροῦντι δὲ πρὸς ἔργον ἐκεῖνος προσήγετο, καὶ μεταβὰς εὐθὺς ἦρχεν ἐφόδου.", "st": "Alex. 32.8"}, {"sp": "N", "t": "τότε δὲ τοῖς Θετταλοῖς πλεῖστα διαλεχθεὶς καὶ τοῖς ἄλλοις Ἕλλησιν, ὡς ἐπέρρωσαν αὐτὸν βοῶντες ἄγειν ἐπὶ τοὺς βαρβάρους, τὸ ξυστὸν εἰς τὴν ἀριστερὰν μεταβαλὼν τῇ δεξιᾷ παρεκάλει τοὺς θεούς, ὡς Καλλισθένης φησίν, ἐπευχόμενος, εἴπερ ὄντως Διόθεν ἐστὶ γεγονώς, ἀμῦναι καὶ συνεπιρρῶσαι τοὺς Ἕλληνας. ὁ δὲ μάντις Ἀρίστανδρος χλανίδα λευκὴν ἔχων καὶ χρυσοῦν στέφανον ἐπεδείκνυτο παριππεύων ἀετὸν ὑπὲρ κεφαλῆς Ἀλεξάνδρου συνεπαιωρούμενον καὶ κατευθύνοντα τῇ πτήσει ὄρθιον ἐπὶ τοὺς πολεμίους, ὥστε πολὺ μὲν θάρσος ἐγγενέσθαι τοῖς ὁρῶσιν, ἐκ δὲ τοῦ θαρρεῖν καὶ παρακαλεῖν ἀλλήλους δρόμῳ τοῖς ἱππεῦσιν ἱεμένοις ἐπὶ τοὺς πολεμίους ἐπικυμαίνειν τὴν φάλαγγα. πρὶν δὲ συμμεμῖξαι τοὺς πρώτους ἐξέκλιναν οἱ βάρβαροι, καὶ διωγμὸς ἦν πολὺς, εἰς τὰ μέσα συνελαύνοντος Ἀλεξάνδρου τὸ νικώμενον, ὅπου Δαρεῖος ἦν. πόρρωθεν γὰρ αὐτὸν κατεῖδε διὰ τῶν προτεταγμένων ἐν βάθει τῆς βασιλικῆς ἴλης ἐκφανέντα, καλὸν ἄνδρα καὶ μέγαν ἐφ’ ἅρματος ὑψηλοῦ βεβῶτα, πολλοῖς ἱππεῦσι καὶ λαμπροῖς καταπεφραγμένον εὖ μάλα συνεσπειραμένοις περὶ τὸ ἅρμα καὶ παρατεταγμένοις δέχεσθαι τοὺς πολεμίους. ἀλλὰ δεινὸς ὀφθεὶς ἐγγύθεν Ἀλέξανδρος καὶ τοὺς φεύγοντας ἐμβαλὼν εἰς τοὺς μένοντας ἐξέπληξε καὶ διεσκέδασε τὸ πλεῖστον, οἱ δὲ ἄριστοι καὶ γενναιότατοι πρὸ τοῦ βασιλέως φονευόμενοι καὶ κατ’ ἀλλήλων πίπτοντες ἐμποδὼν τῆς διώξεως ἦσαν, ἐμπλεκόμενοι καὶ περισπαίροντες αὑτοῖς καὶ ἵπποις.", "st": "Alex. 33.1"}, {"sp": "N", "t": "Δαρεῖος δέ, τῶν δεινῶν ἁπάντων ἐν ὀφθαλμοῖς ὄντων καὶ τῶν προτεταγμένων δυνάμεων ἐρειπομένων εἰς αὐτόν, ὡς οὐκ ἦν ἀποστρέψαι τὸ ἅρμα καὶ διεξελάσαι ῥᾴδιον, ἀλλ’ οἵ τε τροχοὶ συνείχοντο πτώμασι πεφυρμένοι τοσούτοις οἵ τε ἵπποι καταλαμβανόμενοι καὶ ἀποκρυπτόμενοι τῷ πλήθει τῶν νεκρῶν ἐξήλλοντο καὶ συνετάραττον τὸν ἡνίοχον, ἀπολείπει μὲν τὸ ἅρμα καὶ τὰ ὅπλα, θήλειαν δέ, ὥς φασι, νεοτόκον ἵππον περιβὰς ἔφυγεν. οὐ μὴν τότε ἂν ἐδόκει διαφυγεῖν, εἰ μὴ πάλιν ἧκον ἕτεροι παρὰ τοῦ Παρμενίωνος ἱππεῖς μετακαλοῦντες Ἀλέξανδρον, ὡς συνεστώσης ἔτι πολλῆς δυνάμεως ἐκεῖ καὶ τῶν πολεμίων οὐκ ἐνδιδόντων. ὅλως γὰρ αἰτιῶνται Παρμενίωνα κατ’ ἐκείνην τὴν μάχην νωθρὸν γενέσθαι καὶ δύσεργον, εἴτε τοῦ γήρως ἤδη τι παραλύοντος τῆς τόλμης, εἴτε τὴν ἐξουσίαν καὶ τὸν ὄγκον, ὡς Καλλισθένης φησί, τῆς Ἀλεξάνδρου δυνάμεως βαρυνόμενον καὶ προσφθονοῦντα. τότε δ’ οὖν ὁ βασιλεὺς ἀνιαθεὶς τῇ μεταπέμψει τοῖς μὲν στρατιώταις οὐκ ἔφρασε τὸ ἀληθές, ἀλλ’ ὡς ἀνέχων τοῦ φονεύειν καὶ σκότους ὄντος ἀνάκλησιν ἐσήμανεν ἐλαύνων δὲ πρὸς τὸ κινδυνεῦον μέρος ἤκουσε καθ’ ὁδὸν ἡττῆσθαι παντάπασι καὶ φεύγειν τοὺς πολεμίους.", "st": "Alex. 33.8"}, {"sp": "N", "t": "τοῦτο τῆς μάχης ἐκείνης λαβούσης τὸ πέρας, ἡ μὲν ἀρχὴ παντάπασιν ἡ Περσῶν ἐδόκει καταλελύσθαι, βασιλεὺς δὲ τῆς Ἀσίας Ἀλέξανδρος ἀνηγορευμένος ἔθυε τοῖς θεοῖς μεγαλοπρεπῶς καὶ τοῖς φίλοις ἐδωρεῖτο πλούτους καὶ οἴκους καὶ ἡγεμονίας, φιλοτιμούμενος δὲ πρὸς τοὺς Ἕλληνας ἔγραψε τὰς τυραννίδας πάσας καταλυθῆναι καὶ πολιτεύειν αὐτονόμους, ἰδίᾳ δὲ Πλαταιεῦσι τὴν πόλιν ἀνοικοδομεῖν, ὅτι τὴν χώραν οἱ πατέρες αὐτῶν ἐναγωνίσασθαι τοῖς Ἕλλησιν ὑπὲρ τῆς ἐλευθερίας παρέσχον. ἔπεμψε δὲ καὶ Κροτωνιάταις εἰς Ἰταλίαν μέρος τῶν λαφύρων, τὴν Φαΰλλου τοῦ ἀθλητοῦ τιμῶν προθυμίαν καὶ ἀρετήν, ὃς περὶ τὰ Μηδικά τῶν ἄλλων Ἰταλιωτῶν ἀπεγνωκότων τοὺς Ἕλληνας ἰδιόστολον ἔχων ναῦν ἔπλευσεν εἰς Σαλαμῖνα, τοῦ κινδύνου τι μεθέξων. οὕτω τις εὐμενὴς ἦν πρὸς ἅπασαν ἀρετὴν καὶ καλῶν ἔργων φύλαξ καὶ οἰκεῖος.", "st": "Alex. 34.1"}, {"sp": "N", "t": "ἐπιὼν δὲ τὴν Βαβυλωνίαν ἅπασαν εὐθὺς ἐπ’ αὐτῷ γενομένην ἐθαύμασε μάλιστα τό τε χάσμα τὸν πυρὸς ὥσπερ ἐκ πηγῆς συνεχῶς ἀναφερομένου, καὶ τό ῥεῦμα τοῦ νάφθα λιμνάζοντος διὰ τὸ πλῆθος οὐ πόρρω τοῦ χάσματος, ὃς τἆλλα μὲν ἀσφάλτῳ προσέοικεν, οὕτω δὲ εὐπαθὴς πρὸς τὸ πῦρ ἐστιν ὥστε, πρὶν ἢ θιγεῖν τὴν φλόγα, δι’ αὐτῆς τῆς περὶ τὸ φῶς ἐξαπτόμενος αὐγῆς τὸν μεταξὺ πολλάκις ἀέρα συνεκκαίειν. ἐπιδεικνύμενοι δὲ τὴν φύσιν αὐτοῦ καὶ δύναμιν οἱ βάρβαροι τὸν ἄγοντα πρὸς τὴν κατάλυσιν τοῦ βασιλέως στενωπὸν ἐλαφρῶ τῷ φαρμάκῳ κατεψέκασαν εἶτα στάντες ἐπ’ ἄκρῳ τοὺς λαμπτῆρας τοῖς βεβρεγμένοις προσέθηκαν ἤδη γὰρ συνεσκόταζε. τῶν δὲ πρώτων εὐθὺς ἁψαμένων οὐκ ἔσχεν ἡ νομὴ χρόνον αἰσθητόν, ἀλλ’ ἅμα νοήματι διῖκτο πρὸς θάτερον πέρας καὶ πῦρ ἐγεγόνει συνεχὲς ὁ στενωπός. ἦν δέ τις Ἀθηνοφάνης Ἀθηναῖος τῶν περὶ ἄλειμμα καὶ λουτρὸν εἰωθότων τὸ σῶμα θεραπεύειν τοῦ βασιλέως καὶ τὴν διάνοιαν ἐμμελῶς ἀπάγειν ἐπὶ τὸ ῥᾴθυμον. οὗτος ἐν τῷ λουτρῶνι τότε παιδαρίου τῷ Ἀλεξάνδρῳ παρεστῶτος εὐτελοῦς σφόδρα καὶ γελοίου τὴν ὄψιν, ᾄδοντος δὲ χαριέντως, Στέφανος ἐκαλεῖτο, βούλει, φησὶν, ὦ βασιλεῦ, διάπειραν ἐν Στεφάνῳ τοῦ φαρμάκου λάβωμεν; ἂν γὰρ ἅψηται τούτου καὶ μὴ κατασβεσθῇ, παντάπασιν ἂν φαίην ἄμαχον καὶ δεινὴν αὐτοῦ τὴν δύναμιν εἶναι. προθύμως δέ πως καὶ τοῦ παιδαρίου διδόντος ἑαυτὸν πρὸς τὴν πεῖραν, ἅμα τῷ περιαλεῖψαι καὶ θιγεῖν ἐξήνθησε φλόγα τοσαύτην τὸ σῶμα καὶ πυρὶ κατεσχέθη τὸ πᾶν ὥστε τὸν Ἀλέξανδρον εἰς πᾶν ἀπορίας καὶ δέους ἐλθεῖν εἰ δὲ μὴ κατὰ τύχην πολλοὶ παρῆσαν ἀγγεῖα πρὸς τὸ λουτρὸν ὕδατος διὰ χειρῶν ἔχοντες, οὐκ ἂν ἔφθασεν ἡ βοήθεια τὴν ἐπινομήν. ἀλλὰ καὶ τότε μόγις κατέσβεσαν τὸ σῶμα τοῦ παιδὸς δι’ ὅλου πῦρ γενόμενον, καὶ μετὰ ταῦτα χαλεπῶς ἔσχεν.", "st": "Alex. 35.1"}, {"sp": "N", "t": "εἰκότως οὖν ἔνιοι τὸν μῦθον ἀνασῴζοντες πρὸς τὴν ἀλήθειαν τοῦτό φασιν εἶναι τὸ τῆς Μηδείας φάρμακον, ᾧ τὸν τραγῳδούμενον στέφανον καὶ τὸν πέπλον ἔχρισεν. οὐ γὰρ ἐξ αὐτῶν ἐκείνων οὐδὲ ἀπ’ αὐτομάτου λάμψαι τὸ πῦρ, ἀλλὰ φλογὸς ἐγγύθεν παρατεθείσης ὀξεῖαν ὁλκὴν καὶ συναφὴν ἄδηλον αἰσθήσει γενέσθαι. τὰς γὰρ ἀκτῖνας καὶ τὰ ῥεύματα τοῦ πυρὸς ἄπωθεν ἐπερχόμενα τοῖς μὲν ἄλλοις σώμασι φῶς καὶ θερμότητα προσβάλλειν μόνον, ἐν δὲ τοῖς ξηρότητα πνευματικὴν ἢ νοτίδα λιπαρὰν καὶ διαρκῆ κεκτημένοις ἀθροιζόμενα καὶ πυριγονοῦντα μεταβάλλειν ὀξέως τὴν ὕλην. παρεῖχε δὲ ἀπορίαν ἢ γένεσις … εἴτε μᾶλλον ὑπέκκαυμα τῆς φλογὸς ὑπορρεῖ τὸ ὑγρὸν ἐκ τῆς γῆς φύσιν λιπαρὰν καὶ πυριγόνον ἐχούσης. καὶ γάρ ἐστιν ἡ Βαβυλωνία σφόδρα πυρώδης, ὥστε τὰς μὲν κριθὰς χαμόθεν ἐκπηδᾶν καὶ ἀποπάλλεσθαι πολλάκις, οἷον ὑπὸ φλεγμονῆς τῶν τόπων σφυγμοὺς ἐχόντων, τοὺς δὲ ἀνθρώπους ἐν τοῖς καύμασιν ἐπ’ ἀσκῶν πεπληρωμένων ὕδατος καθεύδειν. Ἅρπαλος δὲ τῆς χώρας ἀπολειφθεὶς ἐπιμελητής καὶ φιλοκαλῶν Ἑλληνικαῖς φυτείαις διακοσμῆσαι τὰ βασίλεια καὶ τοὺς περιπάτους, τῶν μὲν ἄλλων ἐκράτησε, τὸν δὲ κιττὸν οὐκ ἔστεξεν ἡ γῆ μόνον, ἀλλ’ ἀεὶ διέφθειρεν οὐ φέροντα τὴν κρᾶσιν ἡ μὲν γὰρ πυρώδης, ὁ δὲ φιλόψυχρος, τῶν μὲν οὖν τοιούτων παρεκβάσεων, ἂν μέτρον ἔχωσιν, ἧττον ἴσως οἱ δύσκολοι κατηγορήσουσιν.", "st": "Alex. 35.10"}, {"sp": "N", "t": "Ἀλέξανδρος δὲ Σούσων κυριεύσας παρέλαβεν ἐν τοῖς βασιλείοις τετρακισμύρια τάλαντα νομίσματος, τὴν δὲ ἄλλην κατασκευὴν καὶ πολυτέλειαν ἀδιήγητον. ὅπου φασὶ καὶ πορφύρας Ἑρμιονικῆς εὑρεθῆναι τάλαντα πεντακισχίλια, συγκειμένης μὲν ἐξ ἐτῶν δέκα δεόντων διακοσίων, πρόσφατον δὲ τὸ ἄνθος ἔτι καὶ νεαρὸν φυλαττούσης. αἴτιον δὲ τούτου φασὶν εἶναι τὸ τὴν βαφὴν διὰ μέλιτος γίνεσθαι τῶν ἁλουργῶν, δι’ ἐλαίου δὲ λευκοῦ τῶν λευκῶν καὶ γὰρ τούτων τὸν ἴσον χρόνον ἐχόντων τὴν λαμπρότητα καθαρὰν καὶ στίλβουσαν ὁρᾶσθαι. Δείνων δέ φησι καὶ ὕδωρ ἀπό τε τοῦ Νείλου καὶ τοῦ Ἴστρου μετὰ τῶν ἄλλων μεταπεμπομένους εἰς τὴν γάζαν ἀποτίθεσθαι τοὺς βασιλεῖς, οἷον ἐκβεβαιουμένους τὸ μέγεθος τῆς ἀρχῆς καὶ τὸ κυριεύειν ἁπάντων.", "st": "Alex. 36.1"}, {"sp": "N", "t": "τῆς δὲ Περσίδος οὔσης διὰ τραχύτητα δυσεμβόλου καὶ φυλαττομένης ὑπὸ γενναιοτάτων Περσῶν (Δαρεῖος μὲν γὰρ ἐπεφεύγει) γίγνεταί τινος περιόδου κύκλον ἐχούσης οὐ πολὺν ἡγεμὼν αὐτῷ δίγλωσσος ἄνθρωπος, ἐκ πατρὸς Λυκίου, μητρὸς δὲ Περσίδος γεγονώς ὅν φασιν, ἔτι παιδὸς ὄντος Ἀλεξάνδρου, τὴν Πυθίαν προειπεῖν, ὡς λύκος ἔσται καθηγεμὼν Ἀλεξάνδρῳ τῆς ἐπὶ Πέρσας πορείας. φόνον μὲν οὖν ἐνταῦθα πολὺν τῶν ἁλισκομένων γενέσθαι συνέπεσε γράφει γὰρ αὐτός ὡς νομίζων αὐτῷ τοῦτο λυσιτελεῖν ἐκέλευεν ἀποσφάττεσθαι τοὺς ἀνθρώπους· νομίσματος δὲ εὑρεῖν πλῆθος, ὅσον ἐν Σούσοις, τὴν δὲ ἄλλην κατασκευὴν καὶ τὸν πλοῦτον ἐκκομισθῆναί φασι μυρίοις ὀρικοῖς ζεύγεσι καὶ πεντακισχιλίαις καμήλοις.", "st": "Alex. 37.1"}, {"sp": "N", "t": "Ξέρξου δὲ ἀνδριάντα μέγαν θεασάμενος ὑπὸ πλήθους τῶν ὠθουμένων εἰς τὰ βασίλεια πλημμελῶς ἀνατετραμμένον ἐπέστη, καὶ καθάπερ ἔμψυχον προσαγορεύσας, πότερόν σε, εἶπε, διὰ τὴν ἐπὶ τοὺς Ἕλληνας στρατείαν κείμενον παρέλθωμεν ἢ διὰ τὴν ἄλλην μεγαλοφροσύνην καὶ ἀρετὴν ἐγείρωμεν; τέλος δὲ πολὺν χρόνον πρὸς ἑαυτῷ γενόμενος καὶ σιωπήσας παρῆλθε, βουλόμενος δὲ τοὺς στρατιώτας ἀναλαβεῖν (καὶ γὰρ ἦν χειμῶνος ὥρα) τέσσαρας μῆνας αὐτόθι διήγαγε. λέγεται δὲ καθίσαντος αὐτοῦ τὸ πρῶτον ὑπὸ τὸν χρυσοῦν οὐρανίσκον ἐν τῷ βασιλικῷ θρόνῳ τὸν Κορίνθιον Δημάρατον εὔνουν ὄντα ἄνδρα καὶ πατρῷον φίλον Ἀλεξάνδρου πρεσβυτικῶς ἐπιδακρῦσαι, καὶ εἰπεῖν ὡς μεγάλης ἡδονῆς στεροῖντο τῶν Ἑλλήνων οἱ τεθνηκότες πρὶν ἰδεῖν Ἀλέξανδρον ἐν τῷ Δαρείου θρόνῳ καθήμενον.", "st": "Alex. 37.5"}, {"sp": "N", "t": "ἐκ τούτου μέλλων ἐξελαύνειν ἐπὶ Δαρεῖον ἔτυχε μὲν εἰς μέθην τινὰ καὶ παιδιὰν τοῖς ἑταίροις ἑαυτὸν δεδωκώς, ὥστε καὶ γύναια συμπίνειν ἐπὶ κῶμον ἥκοντα πρὸς τοὺς ἐραστάς. ἐν δὲ τούτοις εὐδοκιμοῦσα μάλιστα Θαῒς ἡ Πτολεμαίου τοῦ βασιλεύσαντος ὕστερον ἑταίρα, γένος Ἀττική, τὰ μὲν ἐμμελῶς ἐπαινοῦσα, τὰ δὲ παίζουσα πρὸς τὸν Ἀλέξανδρον, ἅμα τῇ μέθῃ λόγον εἰπεῖν προήχθη τῷ μὲν τῆς πατρίδος ἤθει πρέποντα, μείζονα δὲ ἢ κατ’ αὑτήν. ἔφη γάρ ὧν πεπόνηκε πεπλανημένη τὴν Ἀσίαν ἀπολαμβάνειν χάριν ἐκείνης τῆς ἡμέρας ἐντρυφῶσα τοῖς ὑπερηφάνοις Περσῶν βασιλείοις ἔτι δ’ ἂν ἥδιον ὑποπρῆσαι κωμάσασα τὸν Ξέρξου τοῦ κατακαύσαντος τὰς Ἀθήνας οἶκον, αὐτὴ τὸ πῦρ ἅψασα τοῦ βασιλέως ὁρῶντος, ὡς ἂν λόγος ἔχῃ πρὸς ἀνθρώπους ὅτι τῶν ναυμάχων καὶ πεζομάχων ἐκείνων στρατηγῶν τὰ μετὰ Ἀλεξάνδρου γύναια μείζονα δίκην ἐπέθηκε Πέρσαις ὑπὲρ τῆς Ἑλλάδος. ἅμα δὲ τῷ λόγῳ τούτῳ κρότου καὶ θορύβου γενομένου καὶ παρακελεύσεως τῶν ἑταίρων καὶ φιλοτιμίας, ἐπισπασθεὶς ὁ βασιλεὺς καὶ ἀναπηδήσας ἔχων στέφανον καὶ λαμπάδα προῆγεν. οἱ δὲ ἑπόμενοι κώμῳ καὶ βοῇ περιίσταντο τὰ βασίλεια, καὶ τῶν ἄλλων Μακεδόνων οἱ πυνθανόμενοι συνέτρεχον μετὰ λαμπάδων χαίροντες, ἤλπιζον γὰρ ὅτι τοῖς οἴκοι προσέχοντός ἐστι τὸν νοῦν καὶ μὴ μέλλοντος ἐν βαρβάροις οἰκεῖν τὸ πιμπράναι τὰ βασίλεια καὶ διαφθείρειν, οἱ μὲν οὕτω ταῦτα γενέσθαι φασίν, οἱ δὲ ἀπὸ γνώμης· ὅτι δ’ οὖν μετενόησε ταχὺ καὶ κατασβέσαι προσέταξεν ὁμολογεῖται.", "st": "Alex. 38.1"}, {"sp": "N", "t": "φύσει δὲ ὢν μεγαλοδωρότατος ἔτι μᾶλλον ἐπέδωκεν εἰς τοῦτο τῶν πραγμάτων αὐξομένων· καὶ προσῆν ἡ φιλοφροσύνη, μεθ’ ἧς μόνης ὡς ἀληθῶς οἱ διδόντες χαρίζονται, μνησθήσομαι δὲ ὀλίγων. ἀρίστων ὁ τῶν Παιόνων ἡγούμενος ἀποκτείνας πολέμιον ἄνδρα καὶ τὴν κεφαλὴν ἐπιδειξάμενος αὐτῷ, τοῦτο, εἶπεν, ὦ βασιλεῦ, παρ’ ἡμῖν ἐκπώματος χρυσοῦ τιμᾶται τὸ δῶρον. ὁ δὲ Ἀλέξανδρος γελάσας, κενοῦ γε, εἶπεν, ἐγὼ δέ σοι μεστὸν ἀκράτου προπίομαι. τῶν δὲ πολλῶν τις Μακεδόνων ἤλαυνεν ἡμίονον βασιλικὸν χρυσίον κομίζοντα· κάμνοντος δὲ τοῦ κτήνους αὐτὸς ἀράμενος ἐκόμιζε τὸ φορτίον. ἰδὼν οὖν ὁ βασιλεὺς θλιβόμενον αὐτὸν σφόδρα καὶ πυθόμενος τὸ πρᾶγμα, μέλλοντος κατατίθεσθαι, μὴ κάμῃς, εἶπεν, ἀλλὰ πρόσθες ἔτι τὴν λοιπὴν ὁδὸν ἐπὶ τὴν σκηνήν ἑαυτῷ τοῦτο κομίσας. ὅλως δὲ ἤχθετο τοῖς μὴ λαμβάνουσι μᾶλλον ἢ τοῖς αἰτοῦσι.", "st": "Alex. 39.1"}, {"sp": "N", "t": "καὶ Φωκίωνι μὲν ἔγραψεν ἐπιστολήν ὡς οὐ χρησόμενος αὐτῷ φίλῳ τὸ λοιπόν, εἰ διωθοῖτο τὰς χάριτας. Σεραπίωνι δὲ τῶν ἀπὸ σφαίρας τινὶ νεανίσκων οὐδὲν ἐδίδου διὰ τὸ μηδὲν αἰτεῖν. ὡς οὖν εἰς τὸ σφαιρίζειν παραγενόμενος ὁ Σεραπίων ἄλλοις ἔβαλλε τὴν σφαῖραν, εἰπόντος δὲ τοῦ βασιλέως, ἐμοὶ δὲ οὐ δίδως; οὐ γὰρ αἰτεῖς, εἶπε, τούτῳ μὲν δὴ γελάσας πολλὰ ἔδωκε. Πρωτέᾳ δέ τινι τῶν περὶ σκώμματα καὶ πότον οὐκ ἀμούσων ἔδοξε δι’ ὀργῆς γεγονέναι τῶν δὲ φίλων δεομένων κἀκείνου δακρύοντος ἔφη διαλλάττεσθαι κἀκεῖνος, οὐκοῦν, εἶπεν, ὦ βασιλεῦ, δός τί μοι πιστὸν πρῶτον. ἐκέλευσεν οὖν αὐτῷ πέντε τάλαντα δοθῆναι. περὶ δὲ τῶν τοῖς φίλοις καὶ τοῖς σωματοφύλαξι νεμομένων πλούτων, ἡλίκον εἶχον ὄγκον, ἐμφαίνει δι’ ἐπιστολῆς Ὀλυμπιάς, ἣν ἔγραψε πρὸς αὐτόν.", "st": "Alex. 39.1b"}, {"sp": "N", "t": "ἄλλως, φησὶν, εὖ ποίει τοὺς φίλους καὶ ἐνδόξους ἄγε νῦν δ’ ἰσοβασιλέας πάντας ποιεῖς καὶ πολυφιλίας παρασκευάζεις αὐτοῖς, ἑαυτὸν δὲ ἐρημοῖς. πολλάκις δὲ τοιαῦτα τῆς Ὀλυμπιάδος γραφούσης ἐφύλαττεν ἀπόρρητα τὰ γράμματα, πλὴν ἅπαξ Ἡφαιστίωνος, ὥσπερ εἰώθει, λυθεῖσαν ἐπιστολήν αὐτῷ συναναγινώσκοντος οὐκ ἐκώλυσεν, ἀλλὰ τὸν δακτύλιον ἀφελόμενος τὸν αὑτοῦ προσέθηκε τῷ ἐκείνου στόματι τὴν σφραγῖδα. Μαζαίου δὲ τοῦ μεγίστου παρὰ Δαρείῳ γενομένου παιδὶ σατραπείαν ἔχοντι δευτέραν προσετίθει μείζονα, παραιτούμενος δὲ ἐκεῖνος εἶπεν· ὦ βασιλεῦ, τότε μὲν ἦν εἷς Δαρεῖος, νῦν δὲ σὺ πολλοὺς πεποίηκας Ἀλεξάνδρους. Παρμενίωνι μὲν οὖν τὸν Βαγώου ἔδωκεν οἶκον τὸν περὶ Σοῦσα, ἐν ᾧ λέγεται χιλίων ταλάντων εὑρεθῆναι ἱματισμὸν. πρὸς δ’ Ἀντίπατρον ἔγραψε κελεύων ἔχειν φύλακας τοῦ σώματος ὡς ἐπιβουλευόμενον. τῇ δὲ μητρὶ πολλὰ μὲν ἐδωρεῖτο καὶ κατέπεμπεν, οὐκ εἴα δὲ πολυπραγμονεῖν οὐδὲ παραστρατηγεῖν ἐγκαλούσης δὲ πρᾴως ἔφερε τὴν χαλεπότητα. πλὴν ἅπαξ ποτὲ Ἀντιπάτρου μακρὰν κατ’ αὐτῆς γράψαντος ἐπιστολήν ἀναγνοὺς ἀγνοεῖν εἶπεν Ἀντίπατρον ὅτι μυρίας ἐπιστολὰς ἓν δάκρυον ἀπαλείφει μητρός.", "st": "Alex. 39.1c"}, {"sp": "N", "t": "ἐπεὶ δὲ τοὺς περὶ αὑτὸν ἑώρα παντάπασιν ἐκτετρυφηκότας καὶ φορτικοὺς ταῖς διαίταις καὶ πολυτελείαις ὄντας, ὥστε Ἅγνωνα μέν τὸν Τήϊον ἀργυροῦς ἐν ταῖς κρηπῖσιν ἥλους φορεῖν, Λεοννάτῳ δὲ πολλαῖς καμήλοις ἀπ’ Αἰγύπτου κόνιν εἰς τὰ γυμνάσια παρακομίζεσθαι, Φιλώτᾳ δὲ πρὸς θήρας σταδίων ἑκατὸν αὐλαίας γεγονέναι, μύρῳ δὲ χρωμένους ἰέναι πρὸς ἄλειμμα καὶ λουτρὸν ὅσους οὐδὲ ἐλαίῳ, τρίπτας δὲ καὶ κατευναστὰς περιαγομένους, ἐπετίμησε πρᾴως καὶ φιλοσόφως, θαυμάζειν φάμενος εἰ τοσούτους ἠγωνισμένοι καὶ τηλικούτους ἀγῶνας οὐ μνημονεύουσιν ὅτι τῶν καταπονηθέντων οἱ καταπονήσαντες ἥδιον καθεύδουσιν, οὐδὲ ὁρῶσι τοῖς Περσῶν βίοις τοὺς ἑαυτῶν παραβάλλοντες, ὅτι δουλικώτατον μέν ἐστι τὸ τρυφᾶν, βασιλικώτατον δὲ τὸ πονεῖν. καίτοι πῶς ἄν τις, ἔφη, δι’ ἑαυτοῦ θεραπεύσειεν ἵππον ἢ λόγχην ἀσκήσειεν ἢ κράνος, ἀπειθικὼς τοῦ φιλτάτου σώματος ἅπτεσθαι τὰς χεῖρας; οὐκ ἴστε, εἶπεν, ὅτι τοῦ κρατεῖν πέρας ἡμῖν ἐστι τὸ μὴ ταὐτὰ ποιεῖν τοῖς κεκρατημένοις; ἐπέτεινεν οὖν ἔτι μᾶλλον αὐτὸς ἑαυτόν ἐν ταῖς στρατείαις καὶ τοῖς κυνηγεσίοις, κακοπαθῶν καὶ παραβαλλόμενος, ὥστε καὶ Λάκωνα πρεσβευτήν παραγενόμενον αὐτῷ λέοντα καταβάλλοντι μέγαν εἰπεῖν· καλῶς γε, Ἀλέξανδρε, πρὸς τὸν λέοντα ἠγώνισαι περὶ τᾶς βασιλείας. τοῦτο τὸ κυνήγιον Κρατερὸς εἰς Δελφοὺς ἀνέθηκεν, εἰκόνας χαλκᾶς ποιησάμενος τοῦ λέοντος καὶ τῶν κυνῶν καὶ τοῦ βασιλέως τῷ λέοντι συνεστῶτος καὶ αὑτοῦ προσβοηθοῦντος, ὧν τὰ μέν Λύσιππος ἔπλασε, τὰ δὲ Λεωχάρης.", "st": "Alex. 40.1"}, {"sp": "N", "t": "Ἀλέξανδρος μὲν οὖν ἑαυτὸν ἀσκῶν ἅμα καὶ τοὺς ἄλλους παροξύνων πρὸς ἀρετὴν ἐκινδύνευεν· οἱ δὲ φίλοι διὰ πλοῦτον καὶ ὄγκον ἤδη τρυφᾶν βουλόμενοι καὶ σχολάζειν ἐβαρύνοντο τὰς πλάνας καὶ τὰς στρατείας, καὶ κατὰ μικρὸν οὕτω προῆλθον εἰς τὸ βλασφημεῖν καὶ κακῶς λέγειν αὐτόν, ὁ δὲ καὶ πάνυ πρᾴως ἐν ἀρχῇ πρὸς ταῦτα διέκειτο, φάσκων βασιλικὸν εἶναι τὸ κακῶς ἀκούειν εὖ ποιοῦντα. καίτοι τὰ μικρότατα τῶν γενομένων τοῖς συνήθεσι παρ’ αὐτοῦ σημεῖα μεγάλης ὑπῆρχεν εὐνοίας καὶ τιμῆς·", "st": "Alex. 41.1"}, {"sp": "N", "t": "ὧν ὀλίγα παραθήσομαι. Πευκέστᾳ μὲν ἔγραψε μεμφόμενος ὅτι δηχθεὶς ὑπ’ ἄρκτου τοῖς μὲν ἄλλοις ἔγραψεν, αὐτῷ δὲ οὐκ ἐδήλωσεν. ἀλλὰ νῦν γε, φησί, γράψον πῶς ἔχεις, καὶ μή τινές σε τῶν συγκυνηγετούντων ἐγκατέλιπον, ἵνα δίκην δῶσι. τοῖς δὲ περὶ Ἡφαιστίωνα διὰ πράξεις τινὰς ἀποῦσιν ἔγραψεν ὅτι παιζόντων αὐτῶν πρὸς ἰχνεύμονα τῷ Περδίκκου δορατίῳ περιπεσὼν Κρατερὸς τοὺς μηροὺς ἐτρώθη. Πευκέστα δὲ σωθέντος ἔκ τινος ἀσθενείας ἔγραψε πρὸς Ἀλέξιππον τὸν ἰατρὸν εὐχαριστῶν. Κρατεροῦ δὲ νοσοῦντος ὄψιν ἰδὼν καθ’ ὕπνον αὐτός τέ τινας θυσίας ἔθυσεν ὑπὲρ αὐτοῦ κἀκεῖνον θῦσαι ἐκέλευσεν. ἔγραψε δὲ καὶ Παυσανίᾳ τῷ ἰατρῷ βουλομένῳ τὸν Κρατερὸν ἐλλεβορίσαι, τὰ μὲν ἀγωνιῶν, τὰ δὲ παραινῶν ὅπως χρήσεται τῇ φαρμακείᾳ, τοὺς δὲ πρώτους τὴν Ἁρπάλου φυγὴν καὶ ἀπόδρασιν ἀπαγγείλαντας ἔδησεν, Ἐφιάλτην καὶ Κίσσον, ὡς καταψευδομένους τοῦ ἀνδρός. ἐπεὶ δὲ τοὺς ἀσθενοῦντας αὐτοῦ καὶ γέροντας εἰς οἶκον ἀποστέλλοντος Εὐρύλοχος Αἰγαῖος ἐνέγραψεν ἑαυτὸν εἰς τοὺς νοσοῦντας, εἶτα φωραθεὶς ἔχων οὐδὲν κακόν ὡμολόγησε Τελεσίππας ἐρᾶν καὶ συνεπακολουθεῖν ἐπὶ θάλασσαν ἀπιούσης ἐκείνης, ἠρώτησε τίνων ἀνθρώπων ἐστὶ τὸ γύναιον. ἀκούσας δὲ ὅτι τῶν ἐλευθέρων ἑταιρῶν, ἡμᾶς μὲν, εἶπεν, ὦ Εὐρύλοχε, συνερῶντας ἔχεις ὅρα δὲ ὅπως πείθωμεν ἢ λόγοις ἢ δώροις τὴν Τελεσίππαν, ἐπειδήπερ ἐξ ἐλευθέρας ἐστί.", "st": "Alex. 41.1b"}, {"sp": "N", "t": "θαυμάσαι δὲ αὑτὸν ἔστιν ὅτι καὶ μέχρι τοιούτων ἐπιστολῶν τοῖς φίλοις ἐσχόλαζεν, οἷα γράφει παῖδα Σελεύκου εἰς Κιλικίαν ἀποδεδρακότα κελεύων ἀναζητῆσαι, καὶ Πευκέσταν ἐπαινῶν ὅτι Νίκωνα, Κρατεροῦ δοῦλον, συνέλαβε, καὶ Μεγαβύζῳ περὶ τοῦ θεράποντος τοῦ ἐν τῷ ἱερῷ καθεζομένου, κελεύων αὐτὸν, ἂν δύνηται, συλλαβεῖν ἔξω τοῦ ἱεροῦ προκαλεσάμενος, ἐν δὲ τῷ ἱερῷ μὴ προσάπτεσθαι. λέγεται δὲ καὶ τὰς δίκας διακρίνων ἐν ἀρχῇ τὰς θανατικὰς τὴν χεῖρα τῶν ὤτων τῷ ἑτέρῳ προστιθέναι τοῦ κατηγόρου λέγοντος, ὅπως τῷ κινδυνεύοντι καθαρὸν φυλάττηται καὶ ἀδιάβλητον. ἀλλ’ ὕστερόν γε αὑτὸν ἐξετράχυναν αἱ πολλαὶ διαβολαί, διὰ τῶν ἀληθῶν πάροδον ἐπὶ τὰ ψευδῆ λαβοῦσαι. καὶ μάλιστα κακῶς ἀκούων ἐξίστατο τοῦ φρονεῖν καὶ χαλεπὸς ἦν καὶ ἀπαραίτητος, ἅτε δὴ τὴν δόξαν ἀντὶ τοῦ ζῆν καὶ τῆς βασιλείας ἠγαπηκώς.", "st": "Alex. 42.1"}, {"sp": "N", "t": "τότε δὲ ἐξήλαυνεν ἐπὶ Δαρεῖον ὡς πάλιν μαχούμενος ἀκούσας δὲ τὴν ὑπὸ Βήσσου γενομένην αὐτοῦ σύλληψιν ἀπέλυσε τοὺς Θεσσαλοὺς οἴκαδε, δισχίλια τάλαντα δωρεὰν ἐπιμετρήσας ταῖς μισθοφοραῖς. πρὸς δὲ τὴν δίωξιν ἀργαλέαν καὶ μακρὰν γινομένην ἕνδεκα γὰρ ἡμέραις ἱππάσατο τρισχιλίους καὶ τριακοσίους σταδίους ἀπηγόρευσαν μὲν οἱ πλεῖστοι, καὶ μάλιστα κατὰ τὴν ἀνυδρίον. ἔνθα δὴ Μακεδόνες ἀπήντησαν αὐτῷ τινες ὕδωρ ἐν ἀσκοῖς ἐφ’ ἡμιόνων κομίζοντες ἀπὸ τοῦ ποταμοῦ· καὶ θεασάμενοι τὸν Ἀλέξανδρον ἤδη μεσημβρίας οὔσης κακῶς ὑπὸ δίψους ἔχοντα ταχὺ πλησάμενοι κράνος προσήνεγκαν. πυθομένου δὲ αὐτοῦ τίσι κομίζοιεν, υἱοῖς, ἔφασαν, ἰδίοις· ἀλλὰ σοῦ ζῶντος ἑτέρους ποιησόμεθα, κἂν ἐκείνους ἀπολέσωμεν. ταῦτα ἀκούσας ἔλαβεν εἰς τὰς χεῖρας τὸ κράνος· περιβλέψας δὲ καὶ θεασάμενος τοὺς περὶ αὑτὸν ἱππεῖς ἅπαντας ἐγκεκλικότας ταῖς κεφαλαῖς καὶ πρὸς τὸ ποτὸν βλέποντας ἀπέδωκεν οὐ πιών, ἀλλ’ ἐπαινέσας τοὺς ἀνθρώπους, ἄν γὰρ αὐτὸς, ἔφη, πίω μόνος, ἀθυμήσουσιν οὗτοι. θεασάμενοι δὲ τὴν ἐγκράτειαν αὐτοῦ καὶ μεγαλοψυχίαν οἱ ἱππεῖς ἄγειν ἀνέκραγον θαρροῦντα καὶ τοὺς ἵππους ἐμάστιζον· οὔτε γὰρ κάμνειν οὔτε διψᾶν οὔθ’ ὅλως θνητοὺς εἶναι νομίζειν αὑτούς, ἕως ἂν ἔχωσι βασιλέα τοιοῦτον.", "st": "Alex. 42.5"}, {"sp": "N", "t": "ἡ μὲν οὖν προθυμία πάντων ἦν ὁμοία· μόνους δέ φασιν ἑξήκοντα συνεισπεσεῖν εἰς τὰ στρατόπεδα τῶν πολεμίων, ἔνθα δὴ πολὺν μὲν ἄργυρον καὶ χρυσὸν ἐρριμμένον ὑπερβαίνοντες, πολλὰς δὲ παίδων καὶ γυναικῶν ἁρμαμάξας ἡνιόχων ἐρήμους διαφερομένας παρερχόμενοι, τοὺς πρώτους ἐδίωκον, ὡς ἐν ἐκείνοις Δαρεῖον ὄντα. μόλις δὲ εὑρίσκεται πολλῶν ἀκοντισμάτων κατάπλεως τὸ σῶμα κείμενος ἐν ἁρμαμάξῃ, μικρὸν ἀπολείπων τοῦ τελευτᾶν. ὅμως δὲ καὶ πιεῖν ᾔτησε, καὶ πιὼν ὕδωρ ψυχρόν εἶπε πρὸς τὸν δόντα Πολύστρατον· ὦ ἄνθρωπε, τοῦτό μοι πέρας γέγονε δυστυχίας ἁπάσης, εὖ παθεῖν ἀμείψασθαι μὴ δυνάμενον· ἀλλ’ Ἀλέξανδρος ἀποδώσει σοι τὴν χάριν, Ἀλεξάνδρῳ δὲ οἱ θεοὶ τῆς εἰς μητέρα καὶ γυναῖκα καὶ παῖδας τοὺς ἐμοὺς ἐπιεικείας, ᾧ ταύτην δίδωμι τὴν δεξιὰν διὰ σοῦ. ταῦτα εἰπὼν καὶ λαβόμενος τῆς τοῦ Πολυστράτου χειρός ἐξέλιπεν. Ἀλέξανδρος δὲ ὡς ἐπῆλθεν, ἀλγῶν τε τῷ πάθει φανερὸς ἦν καὶ τὴν ἑαυτοῦ χλαμύδα λύσας ἐπέβαλε τῷ σώματι καὶ περιέστειλε, καὶ Βῆσσον μὲν ὕστερον εὑρὼν διεσφενδόνησεν, ὀρθίων δένδρων εἰς ταὐτὸ καμφθέντων ἑκατέρῳ μέρος προσαρτήσας τοῦ σώματος, εἶτα μεθεὶς ἑκάτερον, ὡς ὥρμητο ῥύμῃ φερόμενον, τὸ προσῆκον αὐτῷ μέρος νείμασθαι. τότε δὲ τοῦ Δαρείου τὸ μὲν σῶμα κεκοσμημένον βασιλικῶς πρὸς τὴν μητέρα ἀπέστειλε, τὸν δὲ ἀδελφὸν Ἐξάθρην εἰς τοὺς ἑταίρους ἀνέλαβεν.", "st": "Alex. 43.1"}, {"sp": "N", "t": "αὐτὸς δὲ μετὰ τῆς ἀκμαιοτάτης δυνάμεως εἰς Ὑρκανίαν κατέβαινε· καὶ πελάγους ἰδὼν κόλπον οὐκ ἐλάττονα μὲν τοῦ Πόντου φανέντα, γλυκύτερον δὲ τῆς ἄλλης θαλάττης, σαφὲς μὲν οὐδὲν ἔσχε πυθέσθαι περὶ αὐτοῦ, μάλιστα δὲ εἴκασε τῆς Μαιώτιδος λίμνης ἀνακοπὴν εἶναι. καίτοι τούς γε φυσικοὺς ἄνδρας οὐκ ἔλαθε τἀληθές, ἀλλὰ πολλοῖς ἔτεσιν ἔμπροσθεν τῆς Ἀλεξάνδρου στρατείας ἱστορήκασιν ὅτι τεσσάρων κόλπων εἰσεχόντων ἀπὸ τῆς ἔξω θαλάσσης βορειότατος οὗτός ἐστι, τὸ Ὑρκάνιον πέλαγος καὶ Κάσπιον ὁμοῦ προσαγορευόμενον.", "st": "Alex. 44.1"}, {"sp": "N", "t": "ἐνταῦθα τῶν βαρβάρων τινὲς ἀπροσδοκήτως περιτυχόντες τοῖς ἄγουσι τὸν ἵππον αὐτοῦ τὸν Βουκεφάλαν λαμβάνουσιν. ὁ δὲ ἤνεγκεν οὐ μετρίως, ἀλλὰ κήρυκα πέμψας ἠπείλησε πάντας ἀποκτενεῖν μετὰ τέκνων καὶ γυναικῶν, εἰ τὸν ἵππον αὐτῷ μὴ ἀναπέμψειαν. ἐπεὶ δὲ καὶ τὸν ἵππον ἄγοντες ἧκον καὶ τὰς πόλεις ἐγχειρίζοντες, ἐχρήσατο φιλανθρώπως πᾶσι καὶ τοῦ ἵππου λύτρα τοῖς λαβοῦσιν ἔδωκεν.", "st": "Alex. 44.3"}, {"sp": "N", "t": "ἐντεῦθεν εἰς τήν Παρθικὴν ἀναζεύξας καὶ σχολάζων πρῶτον ἐνεδύσατο τήν βαρβαρικὴν στολὴν, εἴτε βουλόμενος αὑτὸν συνοικειοῦν τοῖς ἐπιχωρίοις νόμοις, ὡς μέγα πρὸς ἐξημέρωσιν ἀνθρώπων τὸ σύνηθες καὶ ὁμόφυλον, εἴτ’ ἀπόπειρά τις ὑφεῖτο τῆς προσκυνήσεως αὕτη τοῖς Μακεδόσι, κατὰ μικρὸν ἀνασχέσθαι τήν ἐκδιαίτησιν αὐτοῦ καὶ μεταβολὴν ἐθιζομένοις, οὐ μὴν τήν γε Μηδικὴν ἐκείνην προσήκατο παντάπασι βαρβαρικὴν καὶ ἀλλόκοτον οὖσαν, οὐδὲ ἀναξυρίδας οὐδὲ κάνδυν οὐδὲ τιάραν ἔλαβεν, ἀλλὰ ἐν μέσῳ τινὰ τῆς Περσικῆς καὶ τῆς Μηδικῆς μιξάμενος εὖ πως, ἀτυφοτέραν μὲν ἐκείνης, ταύτης δὲ σοβαρωτέραν οὖσαν. ἐχρῆτο δὲ τὸ μὲν πρῶτον ἐντυγχάνων τοῖς βαρβάροις καὶ τοῖς ἑταίροις κατ’ οἶκον, εἶτα τοῖς πολλοῖς οὕτως ἐξελαύνων καὶ χρηματίζων ἑωρᾶτο. καὶ λυπηρὸν μὲν ἦν τοῖς Μακεδόσι τὸ θέαμα, τήν δὲ ἄλλην αὐτοῦ θαυμάζοντες ἀρετὴν ᾤοντο δεῖν ἔνια τῶν πρὸς ἡδονὴν αὐτῷ καὶ δόξαν ἐπιχωρεῖν ὅς γε πρὸς ἅπασι τοῖς ἄλλοις ἔναγχος τόξευμα μὲν εἰς τήν κνήμην λαβών, ὑφ’ οὗ τὸ τῆς κερκίδος ὀστέον ἀποθραυσθὲν ἐξέπεσε, λίθῳ δὲ πληγεὶς πάλιν εἰς τὸν τράχηλον ὥστε καὶ ταῖς ὄψεσιν ἀχλὺν ὑποδραμεῖν παραμείνασαν οὐκ ὀλίγον χρόνον, ὅμως οὐκ ἐπαύετο χρώμενος ἑαυτῷ πρὸς τοὺς κινδύνους ἀφειδῶς, ἀλλὰ καὶ τὸν Ὀρεξάρτην διαβὰς ποταμόν, ὃν αὐτὸς ᾤετο Τάναϊν εἶναι, καὶ τοὺς Σκύθας τρεψάμενος ἐδίωξεν ἐπὶ σταδίους ἑκατόν, ἐνοχλούμενος ὑπὸ διαρροίας.", "st": "Alex. 45.1"}, {"sp": "N", "t": "ἐνταῦθα δὲ πρὸς αὐτὸν ἀφικέσθαι τὴν Ἀμαζόνα οἱ πολλοὶ λέγουσιν, ὧν καὶ Κλείταρχός ἐστι καὶ Πολύκλειτος καὶ Ὀνησίκριτος καὶ Ἀντιγένης καὶ Ἴστρος Ἀριστόβουλος δὲ καὶ Χάρης ὁ εἰσαγγελεύς καὶ Πτολεμαῖος καὶ Ἀντικλείδης καὶ Φίλων ὁ Θηβαῖος καὶ Φίλιππος ὁ Θεαγγελεὺς, πρὸς δὲ τούτοις Ἑκαταῖος ὁ Ἐρετριεὺς καὶ Φίλιππος ὁ Χαλκιδεὺς καὶ Δοῦρις ὁ Σάμιος πλάσμα φασὶ γεγονέναι τοῦτο. καὶ μαρτυρεῖν αὐτοῖς ἔοικεν Ἀλέξανδρος. Ἀντιπάτρῳ γὰρ ἅπαντα γράφων ἀκριβῶς τὸν μὲν Σκύθην αὐτῷ φησι διδόναι τὴν θυγατέρα πρὸς γάμον, Ἀμαζόνος δὲ οὐ μνημονεύει, λέγεται δὲ πολλοῖς χρόνοις Ὀνησίκριτος ὕστερον ἤδη βασιλεύοντι Λυσιμάχῳ τῶν βιβλίων τὸ τέταρτον ἀναγινώσκειν, ἐν ᾧ γέγραπται περὶ τῆς Ἀμαζόνος· τὸν οὖν Λυσίμαχον ἀτρέμα μειδιάσαντα καὶ ποῦ, φάναι, τότε ἤμην ἐγώ; ταῦτα μὲν οὖν ἄν τις οὔτε ἀπιστῶν ἧττον οὔτε πιστεύων μᾶλλον Ἀλέξανδρον θαυμάσειε.", "st": "Alex. 46.1"}, {"sp": "N", "t": "φοβούμενος δὲ τοὺς Μακεδόνας, μὴ εἰς τὰ ὑπόλοιπα τῆς στρατείας ἀπαγορεύσωσι, τὸ μὲν ἄλλο πλῆθος εἴασε κατὰ χώραν, τοὺς δὲ ἀρίστους ἔχων ἐν Ὑρκανίᾳ μεθ’ ἑαυτοῦ, δισμυρίους πεζοὺς καὶ τρισχιλίους ἱππεῖς, προσέβαλε, λέγων ὡς νῦν μὲν αὐτοὺς ἐνύπνιον τῶν βαρβάρων ὁρώντων, ἂν δὲ μόνον ταράξαντες τὴν Ἀσίαν ἀπίωσιν, ἐπιθησομένων εὐθὺς ὥσπερ γυναιξίν. οὐ μὴν ἀλλ’ ἀπιέναι γε τοὺς βουλομένους ἐφῆκε, μαρτυράμενος ὅτι τὴν οἰκουμένην τοῖς Μακεδόσι κτώμενος ἐγκαταλέλειπται μετὰ τῶν φίλων καὶ τῶν ἐθελόντων στρατεύειν. ταῦτα σχεδὸν αὐτοῖς ὀνόμασιν ἐν τῇ πρὸς Ἀντίπατρον ἐπιστολῇ γέγραπται, καὶ ὅτι ταῦτα εἰπόντος αὐτοῦ πάντες ἐξέκραγον ὅποι βούλεται τῆς οἰκουμένης ἄγειν· δεξαμένων δὲ τούτων τὴν πεῖραν οὐκέτι ἦν χαλεπὸν προσαχθῆναι τὸ πλῆθος, ἀλλὰ ῥᾳδίως ἐπηκολούθησεν.", "st": "Alex. 47.1"}, {"sp": "N", "t": "οὕτω δὴ καὶ τὴν δίαιταν ἔτι μᾶλλον ὡμοίου τε τοῖς ἐπιχωρίοις ἑαυτόν, ἐκεῖνά τε προσῆγε τοῖς Μακεδονικοῖς ἔθεσιν, ἀνακράσει καὶ κοινωνίᾳ μᾶλλον δι’ εὐνοίας καταστήσεσθαι τὰ πράγματα νομίζων ἢ βίᾳ, μακρὰν ἀπαίροντος αὐτοῦ, διὸ καὶ τρισμυρίους παῖδας ἐπιλεξάμενος ἐκέλευσε γράμματά τε μανθάνειν Ἑλληνικὰ καὶ Μακεδονικοῖς ὅπλοις ἐντρέφεσθαι, πολλοὺς ἐπιστάτας καταστήσας. καὶ τὰ περὶ Ῥωξάνην ἔρωτι μὲν ἐπράχθη, καλὴν καὶ ὡραίαν ἔν τινι χορῷ παρὰ πότον ὀφθεῖσαν, ἔδοξε δὲ οὐκ ἀνάρμοστα τοῖς ὑποκειμένοις εἶναι πράγμασιν. ἐθάρρησαν γὰρ οἱ βάρβαροι τῇ κοινωνίᾳ τοῦ γάμου, καὶ τὸν Ἀλέξανδρον ὑπερηγάπησαν, ὅτι σωφρονέστατος περὶ ταῦτα γεγονὼς οὐδὲ ἧς μόνης ἡττήθη γυναικὸς ἄνευ νόμου θιγεῖν ὑπέμεινεν.", "st": "Alex. 47.5"}, {"sp": "N", "t": "ἐπεὶ δὲ καὶ τῶν φίλων ἑώρα τῶν μεγίστων Ἡφαιστίωνα μὲν ἐπαινοῦντα καὶ συμμετακοσμούμενον αὐτῷ, Κρατερὸν δὲ τοῖς πατρίοις ἐμμένοντα· δι’ ἐκείνου μὲν ἐχρημάτιζε τοῖς βαρβάροις, διὰ τούτου δὲ τοῖς Ἕλλησι καὶ τοῖς Μακεδόσι καὶ ὅλως τὸν μὲν ἐφίλει μάλιστα, τὸν δὲ ἐτίμα, νομίζων καὶ λέγων ἀεί τὸν μὲν Ἡφαιστίωνα φιλαλέξανδρον εἶναι, τὸν δὲ Κρατερὸν φιλοβασιλέα. διὸ καὶ πρὸς ἀλλήλους ὑπούλως ἔχοντες συνέκρουον πολλάκις, ἅπαξ δὲ περὶ τὴν Ἰνδικὴν καὶ εἰς χεῖρας ἦλθον σπασάμενοι τὰ ξίφη, καὶ τῶν φίλων ἑκατέρῳ παραβοηθούντων προσελάσας Ἀλέξανδρος ἐλοιδόρει τὸν Ἡφαιστίωνα φανερῶς, ἔμπληκτον καλῶν καὶ μαινόμενον, εἰ μὴ συνίησιν ὡς, ἐάν τις αὐτοῦ τὸν Ἀλέξανδρον ἀφέληται, μηδέν ἐστιν ἰδίᾳ δὲ καὶ τοῦ Κρατεροῦ πικρῶς καθήψατο. καὶ συναγαγὼν αὐτοὺς καὶ διαλλάξας ἐπώμοσε τὸν Ἄμμωνα καὶ τοὺς ἄλλους θεούς, ἦ μὴν μάλιστα φιλεῖν ἀνθρώπων ἁπάντων ἐκείνους ἂν δὲ πάλιν αἴσθηται διαφερομένους, ἀποκτενεῖν ἀμφοτέρους, ἢ τὸν ἀρξάμενον. ὅθεν ὕστερον οὐδὲ παίζοντες εἰπεῖν τι οὐδὲ πρᾶξαι πρὸς ἀλλήλους λέγονται.", "st": "Alex. 47.9"}, {"sp": "N", "t": "Φιλώτας δὲ ὁ Παρμενίωνος ἀξίωμα μὲν εἶχεν ἐν τοῖς Μακεδόσι μέγα καὶ γὰρ ἀνδρεῖος ἐδόκει καὶ καρτερικὸς εἶναι, φιλόδωρος δὲ οὕτω καὶ φιλέταιρος μετ’ αὐτόν Ἀλέξανδρον οὐδείς, λέγεται γοῦν ὅτι τῶν συνήθων τινὸς αἰτοῦντος ἀργύριον ἐκέλευσε δοῦναι φήσαντος δὲ τοῦ διοικητοῦ μὴ ἔχειν, τί λέγεις; εἶπεν, οὐδὲ ποτήριον ἔχεις οὐδὲ ἱμάτιον; ὄγκῳ δὲ φρονήματος καὶ βάρει πλούτου καὶ τῇ περὶ τὸ σῶμα θεραπείᾳ καὶ διαίτῃ χρώμενος ἐπαχθέστερον ἢ κατ’ ἰδιώτην, καὶ τότε δὴ τὸ σεμνὸν καὶ ὑψηλὸν οὐκ ἐμμελῶς, ἀλλ’ ἄνευ χαρίτων τῷ σολοίκῳ καὶ παρασήμῳ μιμούμενος, ὑποψίαν καὶ φθόνον ἔσχεν, ὥστε καὶ Παρμενίωνά ποτε εἰπεῖν πρός αὐτόν ὦ παῖ, χείρων μοι γίνου. πρός δὲ αὐτόν Ἀλέξανδρον ἐκ πάνυ πολλῶν χρόνων ἐτύγχανε διαβεβλημένος, ὅτε γὰρ τὰ περὶ Δαμασκὸν ἑάλω χρήματα Δαρείου νικηθέντος ἐν Κιλικίᾳ, πολλῶν σωμάτων κομισθέντων εἰς τὸ στρατόπεδον εὑρέθη γύναιον ἐν τοῖς αἰχμαλώτοις, τῷ μὲν γένει Πυδναῖον, εὐπρεπὲς δὲ τὴν ὄψιν ἐκαλεῖτο δὲ Ἀντιγόνη. τοῦτο ἔσχεν ὁ Φιλώτας οἷα δὲ νέος πρός ἐρωμένην καὶ σὺν οἴνῳ πολλὰ φιλότιμα καὶ στρατιωτικὰ παρρησιαζόμενος ἑαυτοῦ τὰ μέγιστα τῶν ἔργων ἀπέφαινε καὶ τοῦ πατρός, Ἀλέξανδρον δὲ μειράκιον ἀπεκάλει δι’ αὐτοὺς τὸ τῆς ἀρχῆς ὄνομα καρπούμενον. ταῦτα τῆς γυναικὸς ἐκφερούσης πρός τινα τῶν συνήθων, ἐκείνου δέ, ὡς εἰκὸς, πρός ἕτερον, περιῆλθεν εἰς Κρατερὸν ὁ λόγος καὶ λαβὼν τὸ γύναιον εἰσήγαγε κρύφα πρός Ἀλέξανδρον. ἀκούσας δὲ ἐκεῖνος ἐκέλευσε φοιτᾶν εἰς ταὐτὸ τῷ Φιλώτᾳ, καὶ πᾶν, ὅ τι ἂν ἐκπύθηται τούτου, πρός αὐτόν ἀπαγγέλλειν βαδίζουσαν.", "st": "Alex. 48.1"}, {"sp": "N", "t": "ὁ μὲν οὖν Φιλώτας ἐπιβουλευόμενος οὕτως ἠγνόει, καὶ συνῆν τῇ Ἀντιγόνῃ πολλὰ καὶ πρὸς ὀργὴν καὶ μεγαλαυχίαν ῥήματα καὶ λόγους κατὰ τοῦ βασιλέως ἀνεπιτηδείους προϊέμενος. ὁ δὲ Ἀλέξανδρος, καίπερ καρτερᾶς ἐνδείξεως κατὰ τοῦ Φιλώτου προσπεσούσης, ἐκαρτέρησε σιωπῇ καί κατέσχεν, εἴτε θαρρῶν τῇ Παρμενίωνος εὐνοίᾳ πρὸς αὑτόν, εἴτε δεδιὼς τὴν δόξαν αὐτῶν καὶ τὴν δύναμιν. ἐν δὲ τῷ τότε χρόνῳ Μακεδὼν ὄνομα Λίμνος, ἐκ Χαλαίστρας, ἐπιβουλεύων Ἀλεξάνδρῳ Νικόμαχόν τινα τῶν νέων, πρὸς ὃν αὐτὸς ἐρωτικῶς εἶχεν, ἐπὶ τὴν κοινωνίαν τῆς πράξεως παρεκάλει. τοῦ δὲ μὴ δεξαμένου, φράσαντος δὲ τἀδελφῷ Κεβαλίνῳ τὴν πεῖραν, ἐλθὼν ἐκεῖνος πρὸς Φιλώταν ἐκέλευσεν εἰσάγειν αὐτοὺς πρὸς Ἀλέξανδρον ὡς περὶ ἀναγκαίων ἔχοντας ἐντυχεῖν καὶ μεγάλων, ὁ δὲ Φιλώτας, ὅ τι δὴ παθὼν (ἄδηλον γὰρ ἐστιν), οὐ παρῆγεν αὐτούς, ὡς πρὸς ἄλλοις μείζοσι γιγνομένου τοῦ βασιλέως, καὶ τοῦτο δὶς ἐποίησεν.", "st": "Alex. 49.1"}, {"sp": "N", "t": "οἱ δὲ καθ’ ὑπεροψίαν ἤδη τοῦ Φιλώτου τραπόμενοι πρὸς ἕτερον καὶ δι’ ἐκείνου τῷ Ἀλεξάνδρῳ προσαχθέντες πρῶτον μὲν τὰ τοῦ Λίμνου κατεῖπον, ἔπειτα παρεδήλωσαν ἡσυχῇ τὸν Φιλώταν, ὡς ἀμελήσειεν αὐτῶν δὶς ἐντυχόντων. καί τοῦτο δὴ σφόδρα παρώξυνε τὸν Ἀλέξανδρον· καὶ τοῦ πεμφθέντος ἐπὶ τὸν Λίμνου, ὡς ἠμύνετο συλλαμβανόμενος, ἀποκτείναντος αὑτόν, ἔτι μᾶλλον διεταράχθη, τὸν ἔλεγχον ἐκπεφευγέναι τῆς ἐπιβουλῆς νομίζων. καὶ πικρῶς ἔχων πρὸς τὸν Φιλώταν ἐπεσπάσατο τοὺς πάλαι μισοῦντας αὑτόν, ἤδη φανερῶς λέγοντας ὡς ῥᾳθυμία τοῦ βασιλέως εἴη Λίμνον οἰομένου, Χαλαιστραῖον ἄνθρωπον, ἐπιχειρῆσαι τολμήματι τοσούτῳ καθ’ αὑτὸν ἀλλὰ τοῦτον μὲν ὑπηρέτην εἶναι, μᾶλλον δὲ ὄργανον ἀπὸ μείζονος ἀρχῆς ἀφιέμενον, ἐν ἐκείνοις δὲ τὴν ἐπιβουλὴν ζητητέον οἷς μάλιστα ταῦτα λανθάνειν συνέφερε. τοιούτοις λόγοις καὶ ὑπονοίαις ἀναπετάσαντος τὰ ὦτα τοῦ βασιλέως ἐπῆγον ἤδη μυρίας κατὰ τοῦ Φιλώτου διαβολάς. ἐκ τούτου δὲ συλληφθεὶς ἀνεκρίνετο, τῶν ἑταίρων ἐφεστώτων ταῖς βασάνοις, Ἀλεξάνδρου δὲ κατακούοντος ἔξωθεν αὐλαίας παρατεταμένης ὅτε δὴ καί φασιν αὑτὸν εἰπεῖν, οἰκτρὰς καὶ ταπεινὰς τοῦ Φιλώτου φωνὰς καὶ δεήσεις τοῖς περὶ τὸν Ἡφαιστίωνα προσφέροντος οὕτω δὴ μαλακὸς ὢν, ὦ Φιλώτα, καὶ ἄνανδρος ἐπεχείρεις πράγμασι τηλικούτοις; ἀποθανόντος δὲ τοῦ Φιλώτου καὶ Παρμενίωνα πέμψας εὐθὺς εἰς Μηδίαν ἀνεῖλεν, ἄνδρα πολλὰ μὲν Φιλίππῳ συγκατεργασάμενον, μόνον δὲ ἢ μάλιστα τῶν πρεσβυτέρων φίλων Ἀλέξανδρον εἰς Ἀσίαν ἐξορμήσαντα διαβῆναι, τριῶν δὲ υἱῶν οὓς ἔσχεν, ἐπὶ τῆς στρατιᾶς δύο μὲν ἐπιδόντα πρότερον ἀποθανόντας, τῷ δὲ τρίτῳ συναναιρεθέντα.", "st": "Alex. 49.1b"}, {"sp": "N", "t": "ταῦτα πραχθέντα πολλοῖς τῶν φίλων φοβερὸν ἐποίησε τὸν Ἀλέξανδρον, μάλιστα δὲ Ἀντιπάτρῳ καὶ πρὸς Αἰτωλοὺς ἔπεμψε κρύφα πίστεις διδοὺς καὶ λαμβάνων. ἐφοβοῦντο γὰρ Ἀλέξανδρον Αἰτωλοὶ διὰ τὴν Οἰνιαδῶν ἀνάστασιν, ἣν πυθόμενος οὐκ Οἰνιαδῶν ἔφη παῖδας, ἀλλ’ αὑτὸν ἐπιθήσειν δίκην Αἰτωλοῖς.", "st": "Alex. 49.14"}, {"sp": "N", "t": "οὐ πολλῷ δὲ ὕστερον συνηνέχθη καὶ τὰ περὶ Κλεῖτον, οὕτω μὲν ἁπλῶς πυθομένοις τῶν κατὰ Φιλώταν ἀγριώτερα λόγῳ μέντοι συντιθέντες ἅμα καὶ τὴν αἰτίαν καὶ τόν καιρόν, οὐκ ἀπὸ γνώμης, ἀλλὰ δυστυχίᾳ τινὶ ταῦτα εὑρίσκομεν πεπραγμένα τοῦ βασιλέως, ὀργὴν καὶ μέθην πρόφασιν τῷ Κλείτου δαίμονι παρασχόντος. ἐπράχθη δὲ οὕτως. ἧκόν τινες ὀπώραν Ἑλληνικὴν ἀπὸ θαλάσσης τῷ βασιλεῖ κομίζοντες, ὁ δὲ θαυμάσας τὴν ἀκμὴν καὶ τὸ κάλλος ἐκάλει τόν Κλεῖτον, ἐπιδεῖξαι καὶ μεταδοῦναι βουλόμενος. ὁ δὲ θύων μὲν ἐτύγχανεν, ἀφεὶς δὲ τὴν θυσίαν ἐβάδιζε καὶ τρία τῶν κατεσπεισμένων προβάτων ἐπηκολούθησεν αὑτῷ. πυθόμενος δὲ ὁ βασιλεὺς ἀνεκοινοῦτο τοῖς μάντεσιν Ἀριστάνδρῳ καὶ Κλεομάντει τῷ Λάκωνι. φησάντων δὲ πονηρὸν εἶναι τὸ σημεῖον, ἐκέλευσεν ἐκθύσασθαι κατὰ τάχος ὑπὲρ τοῦ Κλείτου. καὶ γὰρ αὐτὸς ἡμέρᾳ τρίτῃ κατὰ τοὺς ὕπνους ἰδεῖν ὄψιν ἄτοπον δόξαι γὰρ αὑτῷ τόν Κλεῖτον μετὰ τῶν Παρμενίωνος υἱῶν ἐν μέλασιν ἱματίοις καθέζεσθαι, τεθνηκότων ἁπάντων. οὐ μὴν ἔφθασεν ὁ Κλεῖτος ἐκθυσάμενος, ἀλλ’ εὐθὺς ἐπὶ τὸ δεῖπνον ἧκε, τεθυκότος τοῦ βασιλέως Διοσκούροις. πότου δὲ νεανικοῦ συρραγέντος ᾔδετο ποιήματα Πρανίχου τινός, ὡς δέ φασιν ἔνιοι, Πιερίωνος, εἰς τοὺς στρατηγοὺς πεποιημένα τοὺς ἔναγχος ἡττημένους ὑπὸ τῶν βαρβάρων ἐπ’ αἰσχύνῃ καὶ γέλωτι. τῶν δὲ πρεσβυτέρων δυσχεραινόντων καὶ λοιδορούντων τόν τε ποιητὴν καὶ τόν ᾄδοντα, τοῦ δὲ Ἀλεξάνδρου καὶ τῶν περὶ αὐτὸν ἡδέως ἀκροωμένων καὶ λέγειν κελευόντων, ὁ Κλεῖτος ἤδη μεθύων καὶ φύσει τραχὺς ὢν ὀργὴν καὶ αὐθάδης ἠγανάκτει μάλιστα, φάσκων οὐ καλῶς ἐν βαρβάροις καὶ πολεμίοις ὑβρίζεσθαι Μακεδόνας πολὺ βελτίονας τῶν γελώντων, εἰ καὶ δυστυχίᾳ κέχρηνται. φήσαντος δὲ τοῦ Ἀλεξάνδρου τόν Κλεῖτον αὑτῷ συνηγορεῖν δυστυχίαν ἀποφαίνοντα τὴν δειλίαν, ἐπαναστὰς ὁ Κλεῖτος, αὕτη μέντοι σε, εἶπεν, ἡ δειλία τόν ἐκ θεῶν ἤδη τῷ Σπιθριδάτου ξίφει τόν νῶτον ἐπιτρέποντα περιεποίησε, καὶ τῷ Μακεδόνων αἵματι καὶ τοῖς τραύμασι τούτοις ἐγένου τηλικοῦτος ὥστε Ἄμμωνι σαυτὸν εἰσποιεῖν ἀπειπάμενος Φίλιππον.", "st": "Alex. 50.1"}, {"sp": "N", "t": "παροξυνθεὶς οὖν ὁ Ἀλέξανδρος, ἦ ταῦτα, εἶπεν, ὦ κακὴ κεφαλὴ, σὺ περὶ ἡμῶν ἑκάστοτε λέγων καὶ διαστασιάζων Μακεδόνας χαιρήσειν νομίζεις; ἀλλ’ οὐδὲ νῦν, ἔφη, χαίρομεν, Ἀλέξανδρε, τοιαῦτα τέλη τῶν πόνων κομιζόμενοι, μακαρίζομεν δὲ τοὺς ἤδη τεθνηκότας πρὶν ἐπιδεῖν Μηδικαῖς ῥάβδοις ξαινομένους Μακεδόνας, καὶ Περσῶν δεομένους ἵνα τῷ βασιλεῖ προσέλθωμεν. τοιαῦτα τοῦ Κλείτου παρρησιαζομένου καὶ τῶν περὶ Ἀλέξανδρον ἀντανισταμένων καὶ λοιδορούντων αὐτόν, οἱ πρεσβύτεροι κατέχειν ἐπειρῶντο τὸν θόρυβον. ὁ δὲ Ἀλέξανδρος ἀποστραφεὶς πρὸς Ξενόδοχον τὸν Καρδιανὸν καὶ τὸν Κολοφώνιον Ἀρτέμιον, οὐ δοκοῦσιν, εἶπεν, ὑμῖν οἱ Ἕλληνες ἐν τοῖς Μακεδόσιν ὥσπερ ἐν θηρίοις ἡμίθεοι περιπατεῖν; τοῦ δὲ Κλείτου μὴ εἴκοντος, ἀλλὰ εἰς μέσον ἃ βούλεται λέγειν τὸν Ἀλέξανδρον κελεύοντος, ἢ μὴ καλεῖν ἐπὶ δεῖπνον ἄνδρας ἐλευθέρους καὶ παρρησίαν ἔχοντας, ἀλλὰ μετὰ βαρβάρων ζῆν καὶ ἀνδραπόδων, οἳ τὴν Περσικὴν ζώνην καὶ τὸν διάλευκον αὐτοῦ χιτῶνα προσκυνήσουσιν, οὐκέτι φέρων τὴν ὀργὴν Ἀλέξανδρος μήλων παρακειμένων ἑνὶ βαλὼν ἔπαισεν αὐτὸν καὶ τὸ ἐγχειρίδιον ἐζήτει. τῶν δὲ σωματοφυλάκων ἑνὸς Ἀριστοφάνους φθάσαντος ὑφελέσθαι, καὶ τῶν ἄλλων περιεχόντων καὶ δεομένων, ἀναπηδήσας ἀνεβόα Μακεδονιστὶ καλῶν τοὺς ὑπασπιστάς τοῦτο δὲ ἦν σύμβολον θορύβου μεγάλου, καὶ τὸν σαλπιγκτὴν ἐκέλευσε σημαίνειν, καὶ πὺξ ἔπαισεν ὡς διατρίβοντα καὶ μὴ βουλόμενον. οὗτος μὲν οὖν ὕστερον εὐδοκίμησεν ὡς τοῦ μὴ συνταραχθῆναι τὸ στρατόπεδον αἰτιώτατος γενόμενος, τὸν δὲ Κλεῖτον οὐχ ὑφιέμενον οἱ φίλοι μόλις ἐξέωσαν τοῦ ἀνδρῶνος.", "st": "Alex. 51.1"}, {"sp": "N", "t": "ὁ δὲ κατ’ ἄλλας θύρας αὖθις εἰσῄει, μάλα ὀλιγώρως καὶ θρασέως Εὐριπίδου τὰ ἐξ Ἀνδρομάχης ἰαμβεῖα ταῦτα περαίνων", "st": "Alex. 51.1b"}, {"sp": "N", "t": "οἴμοι, καθ’ Ἑλλάδ’ ὡς κακῶς νομίζεται.", "st": "Alex. 51.1c"}, {"sp": "N", "t": "οὕτω δὴ λαβὼν παρά τινος τῶν δορυφόρων Ἀλέξανδρος αἰχμήν ἀπαντῶντα τὸν Κλεῖτον αὐτῷ καὶ παράγοντα τὸ πρὸ τῆς θύρας παρακάλυμμα διελαύνει. πεσόντος δὲ μετὰ στεναγμοῦ καὶ βρυχήματος εὐθὺς ἀφῆκεν ὁ θυμὸς αὐτόν, καὶ γενόμενος παρ’ ἑαυτῷ καὶ τοὺς φίλους ἰδὼν ἀφώνους ἑστῶτας ἑλκύσασθαι μὲν ἐκ τοῦ νεκροῦ τὴν αἰχμήν ἔφθασε, παῖσαι δ’ ἑαυτὸν ὁρμήσας παρά τὸν τράχηλον ἐπεσχέθη, τῶν σωματοφυλάκων τὰς χεῖρας αὐτοῦ λαβόντων καὶ τὸ σῶμα βίᾳ παρενεγκόντων εἰς τὸν θάλαμον.", "st": "Alex. 51.9"}, {"sp": "N", "t": "ἐπεὶ δὲ τήν τε νύκτα κακῶς κλαίων διήνεγκε καὶ τήν ἐπιοῦσαν ἡμέραν ἤδη τῷ βοᾶν καὶ θρηνεῖν ἀπειρηκὼς ἄναυδος ἔκειτο, βαρεῖς ἀναφέρων στεναγμούς, δείσαντες οἱ φίλοι τήν ἀποσιώπησιν εἰσῆλθον βίᾳ. καὶ τῶν μὲν ἄλλων οὐ προσίετο τοὺς λόγους, Ἀριστάνδρου δὲ τοῦ μάντεως ὑπομιμνῄσκοντος αὑτὸν τήν τε ὄψιν ἣν εἶδε περὶ τοῦ Κλείτου, καὶ τὸ σημεῖον, ὡς δὴ πάλαι καθειμαρμένων τούτων, ἔδοξεν ἐνδιδόναι. διὸ Καλλισθένην τε τὸν φιλόσοφον παρεισήγαγον, Ἀριστοτέλους οἰκεῖον ὄντα, καὶ τὸν Ἀβδηρίτην Ἀνάξαρχον. ὧν Καλλισθένης μὲν ἠθικῶς ἐπειρᾶτο καὶ πρᾴως, ὑποδυόμενος τῷ λόγῳ καὶ περιϊὼν ἀλύπως, λαβέσθαι τοῦ πάθους, ὁ δὲ Ἀνάξαρχος ἰδίαν τινὰ πορευόμενος ἐξ ἀρχῆς ὁδὸν ἐν φιλοσοφίᾳ, καὶ δόξαν εἰληφὼς ὑπεροψίας καὶ ὀλιγωρίας τῶν συνήθων, εὐθὺς εἰσελθὼν ἀνεβόησεν· οὗτός ἐστιν Ἀλέξανδρος, εἰς ὃν ἡ οἰκουμένη νῦν ἀποβλέπει ὁ δὲ ἔρριπται κλαίων ὥσπερ ἀνδράποδον, ἀνθρώπων νόμον καὶ ψόγον δεδοικώς, οἷς αὑτὸν προσήκει νόμον εἶναι καὶ ὅρον τῶν δικαίων, ἐπείπερ ἄρχειν καὶ κρατεῖν νενίκηκεν, ἀλλὰ μὴ δουλεύειν ὑπὸ κενῆς δόξης κεκρατημένον. οὐκ οἶσθα, εἶπεν, ὅτι τήν Δίκην ἔχει πάρεδρον ὁ Ζεὺς καὶ τήν Θέμιν, ἵνα πᾶν τὸ πραχθὲν ὑπὸ τοῦ κρατοῦντος θεμιτὸν ᾖ καὶ δίκαιον; τοιούτοις τισὶ λόγοις χρησάμενος ὁ Ἀνάξαρχος τὸ μὲν πάθος ἐκούφισε τοῦ βασιλέως, τὸ δὲ ἦθος εἰς πολλὰ χαυνότερον καὶ παρανομώτερον ἐποίησεν, αὑτὸν δὲ δαιμονίως ἐνήρμοσε, καὶ τοῦ Καλλισθένους τήν ὁμιλίαν, οὐδὲ ἄλλως ἐπίχαριν διὰ τὸ αὐστηρὸν οὖσαν, προσδιέβαλε.", "st": "Alex. 52.1"}, {"sp": "N", "t": "λέγεται δέ ποτε παρὰ δεῖπνον ὑπὲρ ὡρῶν καὶ κράσεως τοῦ περιέχοντος λόγων ὄντων, τὸν Καλλισθένην, μετέχοντα δόξης τοῖς λέγουσι τἀκεῖ μᾶλλον εἶναι ψυχρὰ καὶ δυσχείμερα τῶν Ἑλληνικῶν, ἐναντιουμένου τοῦ Ἀναξάρχου καὶ φιλονεικοῦντος, εἰπεῖν ἀλλὰ μὴν ἀνάγκη σοὶ ταῦτα ἐκείνων ὁμολογεῖν ψυχρότερα· σὺ γὰρ ἐκεῖ μὲν ἐν τρίβωνι διεχείμαζες, ἐνταῦθα δὲ τρεῖς ἐπιβεβλημένος δάπιδας κατάκεισαι. τὸν μὲν οὖν Ἀνάξαρχον καὶ τοῦτο προσπαρώξυνε.", "st": "Alex. 52.8"}, {"sp": "N", "t": "τοὺς δὲ ἄλλους σοφιστὰς καὶ κόλακας ὁ Καλλισθένης ἐλύπει σπουδαζόμενος μὲν ὑπὸ τῶν νέων διὰ τὸν λόγον, οὐχ ἧττον δὲ τοῖς πρεσβυτέροις ἀρέσκων διὰ τὸν βίον, εὔτακτον ὄντα καὶ σεμνὸν καὶ αὐτάρκη, καὶ βεβαιοῦντα τὴν λεγομένην τῆς ἀποδημίας πρόφασιν, ὅτι τοὺς πολίτας καταγαγεῖν καὶ κατοικίσαι πάλιν τὴν πατρίδα φιλοτιμούμενος ἀνέβη πρὸς Ἀλέξανδρον. φθονούμενος δὲ διὰ τὴν δόξαν ἔστιν ἃ καὶ καθ’ αὑτοῦ τοῖς διαβάλλουσι παρεῖχε, τάς τε κλήσεις τὰ πολλὰ διωθούμενος, ἔν τε τῷ συνεῖναι βαρύτητι καὶ σιωπῇ δοκῶν οὐκ ἐπαινεῖν οὐδὲ ἀρέσκεσθαι τοῖς γινομένοις, ὥστε καὶ τὸν Ἀλέξανδρον εἰπεῖν ἐπ’ αὐτῷ", "st": "Alex. 53.1"}, {"sp": "N", "t": "μισῶ σοφιστήν, ὅστις οὐδ’ αὑτῷ σοφός.", "st": "Alex. 53.1b"}, {"sp": "N", "t": "λέγεται δέ ποτε πολλῶν παρακεκλημένων ἐπὶ τὸ δεῖπνον ἐπαινέσαι κελευσθεὶς ἐπὶ τοῦ ποτηρίου Μακεδόνας ὁ Καλλισθένης οὕτως εὐροῆσαι πρὸς τὴν ὑπόθεσιν ὥστε ἀνισταμένους κροτεῖν καὶ βάλλειν τοὺς στεφάνους ἐπ’ αὐτόν· εἰπεῖν οὖν τὸν Ἀλέξανδρον ὅτι, κατ’ Εὐριπίδην, τὸν λαβόντα τῶν λόγων", "st": "Alex. 53.3"}, {"sp": "N", "t": "καλὰς ἀφορμὰς οὐ μέγ’ ἔργον εὖ λέγειν·", "st": "Alex. 53.3b"}, {"sp": "N", "t": "ἀλλ’ ἔνδειξαι, φάναι, τὴν αὑτοῦ δύναμιν ἡμῖν κατηγορήσας Μακεδόνων, ἵνα καὶ βελτίους γένωνται μαθόντες ἃ πλημμελοῦσιν. οὕτω δὴ τὸν ἄνδρα πρὸς τῆς παλινῳδίαν τραπόμενον πολλὰ παρρησιάσασθαι κατὰ τῶν Μακεδόνων, καὶ τὴν Ἑλληνικὴν στάσιν αἰτίαν ἀποφήναντα τῆς γενομένης περὶ Φίλιππον αὐξήσεως καὶ δυνάμεως εἰπεῖν·", "st": "Alex. 53.3c"}, {"sp": "N", "t": "ἐν δὲ διχοστασίῃ καὶ ὁ πάγκακος ἔλλαχε τιμῆς·", "st": "Alex. 53.3d"}, {"sp": "N", "t": "ἐφ’ ᾧ πικρὸν καὶ βαρὺ ἐγγενέσθαι μῖσος τοῖς Μακεδόσι, καὶ τὸν Ἀλέξανδρον εἰπεῖν ὡς οὐ τῆς δεινότητος ὁ Καλλισθένης, ἀλλὰ τῆς δυσμενείας Μακεδόσιν ἀπόδειξιν δέδωκε.", "st": "Alex. 53.6"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ὁ ‘Ἕρμιππός φησι τὸν ἀναγνώστην τοῦ Καλλισθένους Στροῖβον Ἀριστοτέλει διηγεῖσθαι, τὸν δὲ Καλλισθένη συνέντα τήν ἀλλοτριότητα τοῦ βασιλέως δὶς ἢ τρὶς ἀπιόντα πρὸς αὑτὸν εἰπεῖν", "st": "Alex. 54.1"}, {"sp": "N", "t": "κάτθανε καὶ Πάτροκλος, ὅπερ σέο πολλὸν ἀμείνων.", "st": "Alex. 54.1b"}, {"sp": "N", "t": "οὐ φαύλως οὖν εἰπεῖν ἔοικεν ὁ Ἀριστοτέλης ὅτι Καλλισθένης λόγῳ μὲν ἦν δυνατὸς καὶ μέγας, νοῦν δὲ οὐκ εἶχεν. ἀλλὰ τήν γε προσκύνησιν ἰσχυρῶς ἀπωσάμενος καὶ φιλοσόφως, καὶ μόνος ἐν φανερῷ διελθὼν ἃ κρύφα πάντες οἱ βέλτιστοι καὶ πρεσβύτατοι τῶν Μακεδόνων ἠγανάκτουν, τοὺς μὲν Ἕλληνας αἰσχύνης ἀπήλλαξε μεγάλης, καὶ μείζονος Ἀλέξανδρον, ἀποτρέψας τήν προσκύνησιν, αὑτὸν δὲ ἀπώλεσεν, ἐκβιάσασθαι δοκῶν μᾶλλον ἢ πεῖσαι τὸν βασιλέα.", "st": "Alex. 54.2"}, {"sp": "N", "t": "Χάρης δὲ ὁ Μιτυληναῖός φησι τὸν Ἀλέξανδρον ἐν τῷ συμποσίῳ πιόντα φιάλην προτεῖναί τινι τῶν φίλων· τὸν δὲ δεξάμενον πρὸς ἑστίαν ἀναστῆναι καὶ πιόντα προσκυνῆσαι πρῶτον, εἶτα φιλῆσαι τὸν Ἀλέξανδρον, καὶ κατακλιθῆναι. πάντων δὲ τοῦτο ποιούντων ἐφεξῆς τὸν Καλλισθένην λαβόντα τήν φιάλην, οὐ προσέχοντος τοῦ βασιλέως, Ἀλλὰ Ἡφαιστίωνι προσδιαλεγομένου, πιόντα προσιέναι φιλήσοντα, Δημητρίου δὲ τοῦ προσονομαζομένου Φείδωνος εἰπόντος, ὦ βασιλεῦ, μὴ φιλήσῃς οὗτος γάρ σε μόνος οὐ προσεκύνησε, διακλῖναι τὸ φίλημα τὸν Ἀλέξανδρον, τὸν δὲ Καλλισθένη μέγα φθεγξάμενον εἰπεῖν· φιλήματι τοίνυν ἔλασσον ἔχων ἄπειμι.", "st": "Alex. 54.4"}, {"sp": "N", "t": "τοιαύτης ὑπογινομένης ἀλλοτριότητος πρῶτον μὲν Ἡφαιστίων ἐπιστεύετο λέγων ὅτι συνθέμενος πρὸς αὐτὸν ὁ Καλλισθένης προσκυνῆσαι ψεύσαιτο τὴν ὁμολογίαν ἔπειτα Λυσίμαχοι καὶ Ἅγνωνες ἐπεφύοντο φάσκοντες περιϊέναι τὸν σοφιστὴν ὡς ἐπὶ καταλύσει τυραννίδος μέγα φρονοῦντα, καὶ συντρέχειν πρὸς αὐτὸν τὰ μειράκια καὶ περιέπειν ὡς μόνον ἐλεύθερον ἐν τοσαύταις μυριάσι. διὸ καὶ τῶν περὶ Ἑρμόλαον ἐπιβουλευσάντων τῷ Ἀλεξάνδρῳ καὶ φανερῶν γενομένων ἔδοξαν ἀληθέσιν ὅμοια κατηγορεῖν οἱ διαβάλλοντες, ὡς τῷ μὲν προβαλόντι πῶς ἂν ἐνδοξότατος γένοιτο ἄνθρωπος, εἶπεν, ἄν ἀποκτείνῃ τὸν ἐνδοξότατον, τὸν δὲ Ἑρμόλαον ἐπὶ τὴν πρᾶξιν παροξύνων ἐκέλευε μὴ δεδιέναι τὴν χρυσῆν κλίνην, ἀλλὰ μνημονεύειν ὅτι καὶ νοσοῦντι καὶ τιτρωσκομένῳ πρόσεισιν ἀνθρώπῳ. καίτοι τῶν περὶ Ἑρμόλαον οὐδεὶς οὐδὲ διὰ τῆς ἐσχάτης ἀνάγκης τοῦ Καλλισθένους κατεῖπεν. ἀλλὰ καὶ Ἀλέξανδρος αὐτὸς εὐθὺς Κρατερῷ γράφων καὶ Ἀττάλῳ καὶ Ἀλκέτᾳ φησὶ τοὺς παῖδας βασανιζομένους ὁμολογεῖν ὡς αὐτοὶ ταῦτα πράξειαν, ἄλλος δὲ οὐδεὶς συνειδείη. ὕστερον δὲ γράφων πρὸς Ἀντίπατρον καὶ τὸν Καλλισθένην συνεπαιτιασάμενος, οἱ μὲν παῖδες, φησὶν, ὑπὸ τῶν Μακεδόνων κατελεύσθησαν, τὸν δὲ σοφιστὴν ἐγὼ κολάσω καὶ τοὺς ἐκπέμψαντας αὐτὸν καὶ τοὺς ὑποδεχομένους ταῖς πόλεσι τοὺς ἐμοὶ ἐπιβουλεύοντας, ἄντικρυς ἔν γε τούτοις ἀποκαλυπτόμενος πρὸς Ἀριστοτέλην καὶ γὰρ ἐτέθραπτο Καλλισθένης παρ’ αὐτῷ διὰ τὴν συγγένειαν, ἐξ Ἡροῦς γεγονώς, ἀνεψιᾶς Ἀριστοτέλους. ἀποθανεῖν δὲ αὐτὸν οἱ μὲν ὑπ’ Ἀλεξάνδρου κρεμασθέντα λέγουσιν, οἱ δὲ ἐν πέδαις δεδεμένον καὶ νοσήσαντα, Χάρης δὲ μετὰ τὴν σύλληψιν ἑπτὰ μῆνας φυλάττεσθαι δεδεμένον, ὡς ἐν τῷ συνεδρίῳ κριθείη παρόντος Ἀριστοτέλους, ἐν αἷς δὲ ἡμέραις Ἀλέξανδρος ἐτρώθη περὶ τὴν Ἰνδίαν, ἀποθανεῖν ὑπέρπαχυν γενόμενον καὶ φθειριάσαντα.", "st": "Alex. 55.1"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ὕστερον ἐπράχθη. Δημάρατος δὲ ὁ Κορίνθιος ἤδη πρεσβύτερος ὢν ἐφιλοτιμήθη πρὸς Ἀλέξανδρον ἀναβῆναι καὶ θεασάμενος αὑτὸν εἶπε μεγάλης ἡδονῆς ἐστερῆσθαι τοὺς Ἕλληνας, ὅσοι τεθνήκασι πρὶν ἰδεῖν Ἀλέξανδρον ἐν τῷ Δαρείου θρόνῳ καθήμενον. οὐ μὴν ἐπὶ πλέον γε τῆς πρὸς αὑτὸν εὐνοίας τοῦ βασιλέως ἀπέλαυσεν, ἀλλ’ ἐξ ἀρρωστίας ἀποθανὼν ἐκηδεύθη μεγαλοπρεπῶς, καὶ τάφον ἔχωσεν ὁ στρατὸς ἐπ’ αὐτῷ τῇ περιμέτρῳ μέγαν, ὕψος δὲ πηχῶν ὀγδοήκοντα· τὰ δὲ λείψανα τέθριππον κεκοσμημένον λαμπρῶς ἐπὶ θάλασσαν κατεκόμισε.", "st": "Alex. 56.1"}, {"sp": "N", "t": "μέλλων δὲ ὑπερβάλλειν εἰς τὴν Ἰνδικὴν, ὡς ἑώρα πλήθει λαφύρων τὴν στρατιὰν ἤδη βαρεῖαν καὶ δυσκίνητον οὖσαν, ἅμ’ ἡμέρᾳ συνεσκευασμένων τῶν ἁμαξῶν, πρώτας μὲν ὑπέπρησε τὰς αὐτοῦ καὶ τῶν ἑταίρων, μετὰ δὲ ταύτας ἐκέλευσε καὶ ταῖς τῶν Μακεδόνων ἐνεῖναι πῦρ. καὶ τοῦ πράγματος τὸ βούλευμα μεῖζον ἐφάνη καὶ δεινότερον ἢ τὸ ἔργον. ὀλίγους μὲν γὰρ ἠνίασεν, οἱ δὲ πλεῖστοι βοῇ καὶ ἀλαλαγμῷ μετὰ ἐνθουσιασμοῦ τὰ μὲν ἀναγκαῖα τοῖς δεομένοις μεταδιδόντες, τὰ δὲ περιόντα τῆς χρείας αὐτοὶ κατακαίοντες καὶ διαφθείροντες ὁρμῆς καὶ προθυμίας ἐνεπίμπλασαν τὸν Ἀλέξανδρον. ἤδη δὲ καὶ φοβερὸς ἦν καὶ ἀπαραίτητος κολαστὴς τῶν πλημμελούντων. καὶ γὰρ Μένανδρόν τινα τῶν ἑταίρων ἄρχοντα φρουρίου καταστήσας, ὡς οὐκ ἐβούλετο μένειν, ἀπέκτεινε, καὶ τῶν ἀποστάντων βαρβάρων Ὀρσοδάτην αὐτὸς κατετόξευσε.", "st": "Alex. 57.1"}, {"sp": "N", "t": "προβάτου δὲ τεκόντος ἄρνα περὶ τῇ κεφαλῇ σχῆμα καὶ χρῶμα τιάρας ἔχοντα καὶ διδύμους ἑκατέρωθεν αὐτοῦ, βδελυχθεὶς τὸ σημεῖον ἐκαθάρθη μὲν ὑπὸ τῶν Βαβυλωνίων, οὓς ἐξ ἔθους ἐπήγετο πρὸς τὰ τοιαῦτα· διελέχθη δὲ πρὸς τοὺς φίλους ὡς οὐ δι’ αὑτόν, ἀλλὰ δι’ ἐκείνους ταράττοιτο, μὴ τὸ κράτος εἰς ἀγεννῆ καὶ ἄναλκιν ἄνθρωπον ἐκλιπόντος αὐτοῦ περιστήσῃ τὸ δαιμόνιον. οὐ μὴν ἀλλὰ βέλτιόν τι σημεῖον γενόμενον τὴν ἀθυμίαν ἔλυσεν. ὁ γὰρ ἐπὶ τῶν στρωματοφυλάκων τεταγμένος ἀνὴρ Μακεδὼν, ὄνομα Πρόξενος, τῇ βασιλικῇ σκηνῇ χώραν ὀρύττων παρὰ τὸν Ὦξον ποταμόν ἀνεκάλυψε πηγὴν ὑγροῦ λιπαροῦ καὶ πιμελώδους· ἀπαντλουμένου δὲ τοῦ πρώτου καθαρὸν ἀνέβλυζεν ἤδη καὶ διαυγές ἔλαιον, οὔτε ὀσμῇ δοκοῦν οὔτε γεύσει ἐλαίου διαφέρειν, στιλπνότητά τε καὶ λιπαρότητα παντάπασιν ἀπαράλλακτον, καὶ ταῦτα τῆς χώρας μηδὲ ἐλαίας φερούσης. λέγεται μὲν οὖν καὶ τὸν Ὦξον αὐτὸν εἶναι μαλακώτατον ὕδωρ, ὥστε τὸ δέρμα τοῖς λουομένοις ἐπιλιπαίνειν. οὐ μὴν ἀλλὰ θαυμαστῶς Ἀλέξανδρος ἡσθεὶς δῆλός ἐστιν ἐξ ὧν γράφει πρὸς Ἀντίπατρον, ἐν τοῖς μεγίστοις τοῦτο τῶν ἀπὸ τοῦ θεοῦ γεγονότων αὐτῷ τιθέμενος, οἱ δὲ μάντεις ἐνδόξου μὲν στρατείας, ἐπιπόνου δὲ καὶ χαλεπῆς τὸ σημεῖον ἐποιοῦντο· πόνων γὰρ ἀρωγὴν ἔλαιον ἀνθρώποις ὑπὸ θεοῦ δεδόσθαι.", "st": "Alex. 57.4"}, {"sp": "N", "t": "πολλοὶ μὲν οὖν κατὰ τὰς μάχας αὐτῷ κίνδυνοι συνέπεσον καὶ τραύμασι νεανικοῖς ἀπήντησε, τὴν δὲ πλείστην φθορὰν ἀπορίαι τῶν ἀναγκαίων καὶ δυσκρασίαι τοῦ περιέχοντος ἀπειργάσαντο τῆς στρατιᾶς, αὐτὸς δὲ τόλμῃ τὴν τύχην ὑπερβαλέσθαι καὶ τὴν δύναμιν ἀρετῇ φιλοτιμούμενος, οὐδὲν ᾤετο τοῖς θαρροῦσιν ἀνάλωτον οὐδὲ ὀχυρὸν εἶναι τοῖς ἀτόλμοις. λέγεται δὲ τὴν Σισιμίθρου πολιορκῶν πέτραν ἄβατον οὖσαν καὶ ἀπότομον ἀθυμούντων τῶν στρατιωτῶν ἐρωτῆσαι τὸν Ὀξυάρτην ποῖός τις αὐτὸς εἴη τὴν ψυχὴν ὁ Σισιμίθρης. φήσαντος δὲ τοῦ Ὀξυάρτου δειλότατον ἀνθρώπων, λέγεις σύ γε, φάναι, τὴν πέτραν ἁλώσιμον ἡμῖν εἶναι τὸ γὰρ ἄρχον αὐτῆς οὐκ ὀχυρόν ἐστι. ταύτην μὲν οὖν ἐκφοβήσας τὸν Σισιμίθρην ἔλαβεν. ἑτέρᾳ δὲ ὁμοίως ἀποτόμῳ προσβαλὼν τοὺς νεωτέρους τῶν Μακεδόνων παρώρμα, καὶ Ἀλέξανδρόν τινα καλούμενον μὲν προσαγορεύσας, ἀλλὰ σοί γε, εἶπεν, ἀνδραγαθεῖν προσήκει καὶ διὰ τὴν ἐπωνυμίαν. ἐπεὶ δὲ λαμπρῶς ὁ νεανίας ἀγωνιζόμενος ἔπεσεν, οὐ μετρίως ἐδήχθη. τῇ δὲ καλουμένῃ Νύσῃ τῶν Μακεδόνων ὀκνούντων προσάγειν; καὶ γάρ ποταμὸς ἦν πρὸς αὐτῇ βαθὺς’ ἐπιστὰς, τί γὰρ, εἶπεν, ὁ κάκιστος ἐγὼ νεῖν οὐκ ἔμαθον καὶ ἤδη ἔχων τὴν ἀσπίδα περᾶν ἠθέλησεν. ἐπεὶ δὲ καταπαύσαντος τὴν μάχην αὐτοῦ παρῆσαν ἀπὸ τῶν πολιορκουμένων πόλεων πρέσβεις δεησόμενοι, πρῶτον μὲν ὀφθεὶς ἀθεράπευτος ἐν τοῖς ὅπλοις ἐξέπληξεν αὐτούς· ἔπειτα προσκεφαλαίου τινὸς αὐτῷ κομισθέντος ἐκέλευσε λαβόντα καθίσαι τὸν πρεσβύτατον· Ἄκουφις ἐκαλεῖτο. θαυμάσας οὖν τὴν λαμπρότητα καὶ φιλανθρωπίαν ὁ Ἄκουφις ἠρώτα τί βούλεται ποιοῦντας αὐτοὺς ἔχειν φίλους. φήσαντος δὲ τοῦ Ἀλεξάνδρου, σὲ μὲν ἄρχοντα καταστήσαντας αὑτῶν, πρὸς δὲ ἡμᾶς πέμψαντας ἑκατὸν ἄνδρας τοὺς ἀρίστους, γελάσας ὁ Ἄκουφις, ἀλλὰ βέλτιον, εἶπεν, ἄρξω, βασιλεῦ, τοὺς κακίστους πρὸς σὲ πέμψας μᾶλλον ἢ τοὺς ἀρίστους.", "st": "Alex. 58.1"}, {"sp": "N", "t": "ὁ δὲ Ταξίλης λέγεται μέν τῆς Ἰνδικῆς ἔχειν μοῖραν Οὐκ ἀποδέουσαν Αἰγύπτου τὸ μέγεθος, εὔβοτον δέ καὶ καλλίκαρπον ἔν τοῖς μάλιστα, σοφὸς δέ τις ἀνὴρ εἶναι, καὶ τὸν Ἀλέξανδρον ἀσπασάμενος, τί δεῖ πολέμων, φάναι, καὶ μάχης ἡμῖν, Ἀλέξανδρε, πρὸς ἀλλήλους, εἰ μήτε ὕδωρ ἀφαιρησόμενος ἡμῶν ἀφῖξαι μήτε τροφὴν ἀναγκαίαν, ὑπὲρ ὧν μόνων ἀνάγκη διαμάχεσθαι νοῦν ἔχουσιν ἀνθρώποις; τοῖς δὲ ἄλλοις χρήμασι καὶ κτήμασι λεγομένοις, εἰ μέν εἰμι κρείττων, ἕτοιμος εὖ ποιεῖν, εἰ δὲ ἥττων, οὐ φεύγω χάριν ἔχειν εὖ παθών. ἡσθεὶς οὖν ὁ Ἀλέξανδρος καὶ δεξιωσάμενος αὐτόν, ἦ που νομίζεις, ἔφη, δίχα μάχης ἔσεσθαι τὴν ἔντευξιν ἡμῖν ἀπὸ τοιούτων λόγων καὶ φιλοφροσύνης; ἀλλ’ οὐδέν σοι πλέον ἐγὼ γὰρ ἀγωνιοῦμαι πρὸς σὲ καὶ διαμαχοῦμαι ταῖς χάρισιν, ὥς μου χρηστὸς ὢν μὴ περιγένῃ. λαβὼν δὲ δῶρα πολλὰ καὶ δοὺς πλείονα τέλος χίλια τάλαντα νομίσματος αὐτῷ προέπιεν. ἐφ’ οἷς τούς μέν φίλους ἰσχυρῶς ἐλύπησε, τῶν δὲ βαρβάρων πολλοὺς ἐποίησεν ἡμερωτέρως ἔχειν πρὸς αὐτόν.", "st": "Alex. 59.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τῶν Ἰνδῶν οἱ μαχιμώτατοι μισθοφοροῦντες ἐπεφοίτων ταῖς πόλεσιν ἐρρωμένως ἀμύνοντες καὶ πολλὰ τὸν Ἀλέξανδρον ἐκακοποίουν, σπεισάμενος ἔν τινι πόλει πρὸς αὐτούς ἀπιόντας ἐν ὁδῷ λαβὼν ἅπαντας ἀπέκτεινε. καὶ τοῦτο τοῖς πολεμικοῖς ἔργοις αὐτοῦ, τὰ ἄλλα νομίμως καὶ βασιλικῶς πολεμήσαντος, ὥσπερ κηλὶς πρόσεστιν. οὐκ ἐλάσσονα δὲ τούτων οἱ φιλόσοφοι πράγματα παρέσχον αὐτῷ, τούς τε προστιθεμένους τῶν βασιλέων κακίζοντες καὶ τούς ἐλευθέρους δήμους ἀφιστάντες. διὸ καὶ τούτων πολλοὺς ἐκρέμασε.", "st": "Alex. 59.6"}, {"sp": "N", "t": "τὰ δὲ πρὸς Πῶρον αὐτὸς ἐν ταῖς ἐπιστολαῖς ὡς ἐπράχθη γέγραφε. φησὶ γάρ ἐν μέσῳ τῶν στρατοπέδων τοῦ Ὑδάσπου ῥέοντος ἀντιπόρους ἱστάντα τοὺς ἐλέφαντας ἀεὶ τὸν Πῶρον ἐπιτηρεῖν τὴν διάβασιν. αὐτόν μὲν οὖν καθ’ ἡμέραν ἑκάστην ψόφον ποιεῖν καὶ θόρυβον ἐν τῷ στρατοπέδῳ πολύν, ἐθίζοντα τοὺς βαρβάρους μὴ φοβεῖσθαι· νυκτὸς δὲ χειμερίου καὶ ἀσελήνου λαβόντα τῶν πεζῶν μέρος, ἱππεῖς δὲ τοὺς κρατίστους, καὶ προελθόντα πόρρω τῶν πολεμίων διαπερᾶσαι πρὸς νῆσον οὐ μεγάλην. ἐνταῦθα δὲ ῥαγδαίου μὲν ἐκχυθέντος ὄμβρου, πρηστήρων δὲ πολλῶν καὶ κεραυνῶν εἰς τὸ στρατόπεδον φερομένων, ὅμως ὁρῶν ἀπολλυμένους τινὰς καὶ συμφλεγομένους ὑπὸ τῶν κεραυνῶν ἀπὸ τῆς νησῖδος ἄρας προσφέρεσθαι ταῖς ἀντιπέρας ὄχθαις. τραχὺν δὲ τὸν Ὑδάσπην ὑπὸ τοῦ χειμῶνος ἐπιόντα καὶ μετέωρον, ἔκρηγμα ποιῆσαι μέγα, καὶ πολὺ μέρος ἐκείνῃ φέρεσθαι τοῦ ῥεύματος· αὐτοὺς δὲ δέξασθαι τὸ μέσον οὐ βεβαίως, ἅτε δὴ συνολισθάνον καὶ περιρρηγνύμενον. ἐνταῦθα δὲ εἰπεῖν φασιν αὐτόν· ὦ Ἀθηναῖοι, ἆρά γε πιστεύσαιτε ἂν ἡλίκους ὑπομένω κινδύνους ἕνεκα τῆς παρ’ ὑμῖν εὐδοξίας; ἀλλὰ τοῦτο μὲν Ὀνησίκριτος εἴρηκεν, αὐτὸς δέ φησι τὰς σχεδίας ἀφέντας αὐτοὺς μετὰ τῶν ὅπλων τὸ ἔκρηγμα διαβαίνειν ἄχρι μαστῶν βρεχομένους, διαβὰς δὲ τῶν πεζῶν εἴκοσι σταδίους προϊππεῦσαι, λογιζόμενος, εἰ μὲν οἱ πολέμιοι τοῖς ἵπποις προσβάλοιεν, πολὺ κρατήσειν, εἰ δὲ κινοῖεν τὴν φάλαγγα, φθήσεσθαι τοὺς πεζοὺς αὐτῷ προσγενομένους θάτερον δὲ συμβῆναι. τῶν γάρ ἱππέων χιλίους καὶ τῶν ἁρμάτων ἑξήκοντα συμπεσόντα τρεψάμενος, τὰ μὲν ἅρματα λαβεῖν ἅπαντα, τῶν δ’ ἱππέων ἀνελεῖν τετρακοσίους, οὕτω δὴ συμφρονήσαντα τὸν Πῶρον ὡς αὐτὸς εἴη διαβεβηκὼς Ἀλέξανδρος, ἐπιέναι μετὰ πάσης τῆς δυνάμεως, πλὴν ὅσον ἐμποδὼν εἶναι τοῖς διαβαίνουσι τῶν Μακεδόνων ἀπέλιπε. φοβηθεὶς δὲ τὰ θηρία καὶ τὸ πλῆθος τῶν πολεμίων αὐτὸς μὲν ἐνσεῖσαι κατὰ θάτερον κέρας, Κοῖνον δὲ τῷ δεξιῷ προσβαλεῖν κελεῦσαι, γενομένης δὲ τροπῆς ἑκατέρωθεν ἀναχωρεῖν ἀεὶ πρὸς τὰ θηρία καὶ συνειλεῖσθαι τοὺς ἐκβιαζομένους, ὅθεν ἤδη τὴν μάχην ἀναμεμιγμένην εἶναι, καὶ μόλις ὀγδόης ὥρας ἀπειπεῖν τοὺς πολεμίους, ταῦτα μὲν οὖν ὁ τῆς μάχης ποιητὴς αὐτὸς ἐν ταῖς ἐπιστολαῖς εἴρηκεν.", "st": "Alex. 60.1"}, {"sp": "N", "t": "οἱ δὲ πλεῖστοι τῶν συγγραφέων ὁμολογοῦσι τὸν Πῶρον ὑπεραίροντα τεσσάρων πηχῶν σπιθαμῇ τὸ μῆκος ἱππότου μηδὲν ἀποδεῖν πρὸς τὸν ἐλέφαντα συμμετρίᾳ διὰ τὸ μέγεθος καὶ τὸν ὄγκον τοῦ σώματος· καίτοι μέγιστος ἦν ὁ ἐλέφας σύνεσιν δὲ θαυμαστὴν ἐπεδείξατο καὶ κηδεμονίαν τοῦ βασιλέως, ἐρρωμένου μὲν ἔτι θυμῷ τοὺς προσμαχομένους ἀμυνόμενος καὶ ἀνακόπτων, ὡς δὲ ᾔσθετο βελῶν πλήθει καὶ τραυμάτων κάμνοντα, δείσας μὴ περιρρυῇ, τοῖς μὲν γόνασιν εἰς γῆν ὑφῆκε πρᾴως ἑαυτόν, τῇ δὲ προνομαίᾳ λαμβάνων ἀτρέμα τῶν δορατίων ἕκαστον ἐξῄρει τοῦ σώματος. ἐπεὶ δὲ ληφθέντα τὸν Πῶρον ὁ Ἀλέξανδρος ἠρώτα πῶς αὐτῷ χρήσηται, βασιλικῶς, εἶπε προσπυθομένου δὲ μή τι ἄλλο λέγει, πάντα, εἶπεν, ἐστὶν ἐν τῷ βασιλικῶς. οὐ μόνον οὖν ἀφῆκεν αὐτόν ἄρχειν ὧν ἐβασίλευε, σατράπην καλούμενον, ἀλλὰ καὶ προσέθηκε χώραν τοὺς αὐτονόμους καταστρεψάμενος, ἐν ᾗ πεντεκαίδεκα μὲν ἔθνη, πόλεις δὲ πεντακισχιλίας ἀξιολόγους, κώμας δὲ παμπόλλας εἶναί φασιν ἄλλην δὲ τρὶς τοσαύτην ἧς Φίλιππόν τινα τῶν ἑταίρων σατράπην ἀπέδειξεν.", "st": "Alex. 60.12"}, {"sp": "N", "t": "ἐκ δὲ τῆς πρὸς Πῶρον μάχης καὶ ὁ Βουκεφάλας ἐτελεύτησεν, οὐκ εὐθύς, ἀλλ’ ὕστερον, ὡς οἱ πλεῖστοι λέγουσιν ἀπὸ τραυμάτων θεραπευόμενος, ὡς δὲ Ὀνησίκριτος, διὰ γῆρας ὑπέρπονος γενόμενος· τριάκοντα γὰρ ἐτῶν ἀποθανεῖν αὐτόν, ἐδήχθη δ’ ἰσχυρῶς Ἀλέξανδρος, οὐδὲν ἄλλο ἢ συνήθη καὶ φίλον ἀποβεβληκέναι νομίζων· καὶ πόλιν οἰκίσας ἐπ’ αὐτῷ παρὰ τὸν Ὑδάσπην Βουκεφαλίαν προσηγόρευσε. λέγεται δὲ καὶ κύνα Περίταν ὄνομα τεθραμμένον ὑπ’ αὐτοῦ καὶ στεργόμενον ἀποβαλών κτίσαι πόλιν ἐπώνυμον. τοῦτο δὲ Σωτίων φησὶ Ποτάμωνος ἀκοῦσαι τοῦ Λεσβίου.", "st": "Alex. 61.1"}, {"sp": "N", "t": "τοὺς μέντοι Μακεδόνας ὁ πρὸς Πῶρον ἀγὼν ἀμβλυτέρους ἐποίησε καὶ τοῦ πρόσω τῆς Ἰνδικῆς ἔτι προελθεῖν ἐπέσχε. μόλις γὰρ ἐκεῖνον ὠσάμενοι δισμυρίοις πεζοῖς καὶ δισχιλίοις ἱππεῦσι παραταξάμενον, ἀντέστησαν ἰσχυρῶς Ἀλεξάνδρῳ βιαζομένῳ καὶ τὸν Γάγγην περᾶσαι ποταμόν, εὖρος μὲν αὐτοῦ δύο καὶ τριάκοντα σταδίων εἶναι πυνθανόμενοι καὶ βάθος ὀργυιὰς ἑκατόν, ἀντιπέρας δὲ τὰς ὄχθας ἀποκεκρύφθαι πλήθεσιν ὅπλων καὶ ἵππων καὶ ἐλεφάντων. ἐλέγοντο γὰρ ὀκτὼ μὲν μυριάδας ἱπποτῶν, εἴκοσι δὲ πεζῶν, ἅρματα δὲ ὀκτακισχίλια καὶ μαχίμους ἐλέφαντας ἑξακισχιλίους ἔχοντες οἱ Γανδαριτῶν καὶ Πραισίων βασιλεῖς ὑπομένειν. καὶ κόμπος οὐκ ἦν περὶ ταῦτα. Ἀνδρόκοττος γὰρ ὕστερον οὐ πολλῷ βασιλεύσας Σελεύκῳ πεντακοσίους ἐλέφαντας ἐδωρήσατο, καὶ στρατοῦ μυριάσιν ἑξήκοντα τὴν Ἰνδικὴν ἐπῆλθεν ἅπασαν καταστρεφόμενος.", "st": "Alex. 62.1"}, {"sp": "N", "t": "τὸ μὲν οὖν πρῶτον ὑπὸ δυσθυμίας καὶ ὀργῆς αὐτόν εἰς τὴν σκηνὴν καθείρξας ἔκειτο, χάριν οὐδεμίαν εἰδὼς τοῖς διαπεπραγμένοις εἰ μὴ περάσειε τὸν Γάγγην, ἀλλ’ ἐξομολόγησιν ἥττης τιθέμενος τὴν ἀναχώρησιν. ὡς δὲ οἵ τε φίλοι τὰ εἰκότα παρηγοροῦντες αὐτόν οἵ τε στρατιῶται κλαυθμῷ καὶ βοῇ προσιστάμενοι ταῖς θύραις ἱκέτευον, ἐπικλασθεὶς ἀνεζεύγνυε, πολλὰ πρὸς δόξαν ἀπατηλὰ καὶ σοφιστικὰ μηχανώμενος. καὶ γὰρ ὅπλα μείζονα καὶ φάτνας ἵππων καὶ χαλινοὺς βαρυτέρους κατασκευάσας ἀπέλιπέ τε καὶ διέρριψεν ἱδρύσατο δὲ βωμοὺς θεῶν, οὓς μέχρι νῦν οἱ Πραισίων βασιλεῖς διαβαίνοντες σέβονται καὶ θύουσιν Ἑλληνικὰς θυσίας. Ἀνδρόκοττος δὲ μειράκιον ὢν αὐτόν Ἀλέξανδρον εἶδε, καὶ λέγεται πολλάκις εἰπεῖν ὕστερον ὡς παρ’ οὐδὲν ἦλθε τὰ πράγματα λαβεῖν Ἀλέξανδρος, μισουμένου τε καὶ καταφρονουμένου τοῦ βασιλέως διὰ μοχθηρίαν καὶ δυσγένειαν.", "st": "Alex. 62.5"}, {"sp": "N", "t": "ἐντεῦθεν ὁρμήσας Ἀλέξανδρος τὴν ἔξω θάλασσαν ἐπιδεῖν, καὶ πολλὰ πορθμεῖα κωπήρη καὶ σχεδίας πηξάμενος, ἐκομίζετο τοῖς ποταμοῖς ὑποφερόμενος σχολαίως. ὁ δὲ πλοῦς οὐκ ἀργὸς ἦν οὐδὲ ἀπόλεμος, προσβάλλων δὲ ταῖς πόλεσι καὶ ἀποβαίνων ἐχειροῦτο πάντα, πρὸς δὲ τοῖς καλουμένοις Μαλλοῖς, οὕς φασιν Ἰνδῶν μαχιμωτάτους γενέσθαι, μικρὸν ἐδέησε κατακοπῆναι. τοὺς μὲν γὰρ ἀνθρώπους βέλεσιν ἀπὸ τῶν τειχῶν ἀπεσκέδασε, πρῶτος δὲ διὰ κλίμακος τεθείσης ἀναβὰς ἐπὶ τ ὁ τεῖχος, ὡς ἥ τε κλίμαξ συνετρίβη καὶ τῶν βαρβάρων ὑφισταμένων παρὰ τὸ τεῖχος ἐλάμβανε πληγὰς κάτωθεν, ὀλιγοστὸς ὢν συστρέψας ἑαυτὸν εἷς μέσους ἀφῆκε τοὺς πολεμίους καὶ κατὰ τύχην ὀρθὸς ἔστη. τιναξαμένου δὲ τοῖς ὅπλοις, ἔδοξαν οἱ βάρβαροι σέλας τι καὶ φάσμα πρὸ τοῦ σώματος φέρεσθαι διὸ καὶ τὸ πρῶτον ἔφυγον καὶ διεσκεδάσθησαν· ὡς δὲ εἶδον αὐτὸν μετὰ δυεῖν ὑπασπιστῶν, ἐπιδραμόντες οἱ μὲν ἐκ χειρὸς ξίφεσι καὶ δόρασι διὰ τῶν ὅπλων συνετίτρωσκον ἀμυνόμενον, εἷς δὲ μικρὸν ἀπωτέρω στάς ἐφῆκεν ἀπὸ τόξου βέλος οὕτως εὔτονον καὶ βίαιον ὥστε τὸν θώρακα διακόψαν ἐμπαγῆναι τοῖς περὶ τὸν μασθὸν ὀστέοις. πρὸς δὲ τὴν πληγὴν ἐνδόντος αὐτοῦ καὶ τὸ σῶμα κάμψαντος, ὁ μὲν βαλὼν ἐπέδραμε βαρβαρικὴν μάχαιραν σπασάμενος, Πευκέστας δὲ καὶ Λιμναῖος προέστησαν ὧν πληγέντων ἑκατέρων ὁ μὲν ἀπέθανε, Πευκέστας δὲ ἀντεῖχε, τὸν δὲ βάρβαρον Ἀλέξανδρος ἀπέκτεινεν. αὐτὸς δὲ τραύματα πολλὰ λαβών, τέλος δὲ πληγεὶς ὑπέρῳ κατὰ τοῦ τραχήλου, προσήρεισε τῷ τείχει τὸ σῶμα, βλέπων πρὸς τοὺς πολεμίους. ἐν τούτῳ δὲ τῶν Μακεδόνων περιχυθέντων ἁρπασθεὶς ἀναίσθητος ἤδη τῶν περὶ αὐτὸν ἐπὶ σκηνῆς ἐκομίζετο. καὶ παραυτίκα μὲν ὡς τεθνεῶτος ἦν λόγος ἐν τῷ στρατοπέδῳ χαλεπῶς δὲ καὶ πολυπόνως τὸν ὀϊστὸν ἐκπρισάντων ξύλινον ὄντα, καὶ τοῦ θώρακος οὕτω μόλις ἀπολυθέντος, περὶ τὴν ἐκκοπὴν ἐγίνοντο τῆς ἀκίδος ἐνδεδυκυίας ἑνὶ τῶν ὀστέων. λέγεται δὲ τὸ μὲν πλάτος τριῶν δακτύλων εἶναι, τὸ δὲ μῆκος τεσσάρων. διὸ ταῖς λιποθυμίαις ἔγγιστα θανάτου συνελαυνόμενος ἐξαιρουμένης αὐτῆς, ὅμως ἀνέλαβε, καὶ διαφυγὼν τὸν κίνδυνον, ἔτι δὲ ἀσθενὴς ὢν καὶ πολὺν χρόνον ἐν διαίτῃ καὶ θεραπείαις ἔχων αὑτόν, ἔξω θορυβοῦντας ὡς ᾔσθετο ποθοῦντας αὐτὸν ἰδεῖν τοὺς Μακεδόνας, λαβὼν ἱμάτιον προῆλθε, καὶ θύσας τοῖς θεοῖς αὖθις ἀνήχθη καὶ παρεκομίζετο χώραν τε πολλὴν καὶ πόλεις μεγάλας καταστρεφόμενος.", "st": "Alex. 63.1"}, {"sp": "N", "t": "τῶν δὲ Γυμνοσοφιστῶν τοὺς μάλιστα τὸν Σάββαν ἀναπείσαντας ἀποστῆναι καὶ κακὰ πλεῖστα τοῖς Μακεδόσι παρασχόντας λαβὼν δέκα, δεινοὺς δοκοῦντας εἶναι περὶ τὰς ἀποκρίσεις καὶ βραχυλόγους, ἐρωτήματα προὔβαλεν αὐτοῖς ἄπορα, φήσας ἀποκτενεῖν τὸν μὴ ὀρθῶς ἀποκρινάμενον πρῶτον, εἶτα ἐφεξῆς οὕτω τοὺς ἄλλους ἕνα δὲ τὸν πρεσβύτατον ἐκέλευσε κρίνειν. ὁ μὲν οὖν πρῶτος ἐρωτηθείς πότερον οἴεται τοὺς ζῶντας εἶναι πλείονας ἢ τοὺς τεθνηκότας, ἔφη τοὺς ζῶντας οὐκέτι γὰρ εἶναι τοὺς τεθνηκότας. ὁ δὲ δεύτερος, πότερον τὴν γῆν ἢ τὴν θάλατταν μείζονα τρέφειν θηρία, τὴν γῆν ταύτης γὰρ μέρος εἶναι τὴν θάλατταν. ὁ δὲ τρίτος, ποῖόν ἐστι ζῷον πανουργότατον, ὃ μέχρι νῦν, εἶπεν, ἄνθρωπος οὐκ ἔγνωκεν. ὁ δὲ τέταρτος ἀνακρινόμενος τίνι λογισμῷ τὸν Σάββαν ἀπέστησεν, ἀπεκρίνατο, καλῶς ζῆν βουλόμενος αὐτὸν ἢ καλῶς ἀποθανεῖν. ὁ δὲ πέμπτος ἐρωτηθείς πότερον οἴεται τὴν ἡμέραν ἢ τὴν νύκτα προτέραν γεγονέναι, τὴν ἡμέραν, εἶπεν, ἡμέρᾳ μιᾷ καὶ προσεπεῖπεν οὗτος, θαυμάσαντος τοῦ βασιλέως, ὅτι τῶν ἀπόρων ἐρωτήσεων ἀνάγκη καὶ τὰς ἀποκρίσεις ἀπόρους εἶναι. μεταβαλὼν οὖν τὸν ἕκτον ἠρώτα πῶς ἄν τις φιληθείη μάλιστα· ἂν κράτιστος ὤν, ἔφη, μὴ φοβερὸς ᾖ. τῶν δὲ λοιπῶν τριῶν ὁ μὲν ἐρωτηθείς πῶς ἄν τις ἐξ ἀνθρώπων γένοιτο θεός, εἴ τι πράξειεν, εἶπεν, ὃ πρᾶξαι δυνατὸν ἀνθρώπῳ μὴ ἔστιν ὁ δὲ περὶ ζωῆς καὶ θανάτου, πότερον ἰσχυρότερον, ἀπεκρίνατο τὴν ζωήν τοσαῦτα κακὰ φέρουσαν. ὁ δὲ τελευταῖος, μέχρι τίνος ἀνθρώπῳ καλῶς ἔχον ζῆν, μέχρι οὗ μὴ νομίζει τὸ τεθνάναι τοῦ ζῆν ἄμεινον. οὕτω δὴ τραπόμενος πρὸς τὸν δικαστήν ἐκέλευσεν ἀποφαίνεσθαι. τοῦ δὲ ἕτερον ἑτέρου χεῖρον εἰρηκέναι φήσαντος οὐκοῦν ἔφη, σὺ πρῶτος ἀποθανῇ τοιαῦτα κρίνων οὐκ ἄν γε, εἶπεν, ὦ βασιλεῦ, εἰ μὴ σὺ ψεύδῃ φήσας πρῶτον ἀποκτενεῖν τὸν ἀποκρινάμενον κάκιστα.", "st": "Alex. 64.1"}, {"sp": "N", "t": "τούτους μὲν οὖν ἀφῆκε δωρησάμενος πρὸς δὲ τοὺς ἓν δόξῃ μάλιστα καί καθ’ αὑτοὺς ἐν ἡσυχίᾳ ζῶντας ἔπεμψεν Ὀνησίκριτον, ἀφικέσθαι δεόμενος πρὸς αὐτὸν, ὁ δὲ Ὀνησίκριτος ἦν φιλόσοφος τῶν Διογένει τῷ κυνικῷ συνεσχολακότων. καί φησι τὸν μὲν Καλανὸν ὑβριστικῶς πάνυ καί τραχέως κελεύειν ἀποδύντα τὸν χιτῶνα γυμνὸν ἀκροᾶσθαι τῶν λόγων ἄλλως δὲ οὐ διαλέξεσθαι πρὸς αὐτὸν, οὐδ’ εἰ παρὰ τοῦ Διὸς ἀφῖκται τὸν δὲ Δάνδαμιν πρᾳότερον εἶναι, καί διακούσαντα περὶ Σωκράτους καί Πυθαγόρου καί Διογένους εἰπεῖν ὡς εὐφυεῖς μὲν αὐτῷ γεγονέναι δοκοῦσιν οἱ ἄνδρες, λίαν δὲ τοὺς νόμους αἰσχυνόμενοι βεβιωκέναι. ἄλλοι δέ φασι τὸν Δάνδαμιν οὐδὲν εἰπεῖν ἀλλ’ ἢ τοσοῦτον μόνον τίνος χάριν ὁ Ἀλέξανδρος ὁδὸν τοσαύτην δεῦρ’ ἦλθε; τὸν μέντοι Καλανὸν ἔπεισεν ὁ Ταξίλης ἐλθεῖν πρὸς Ἀλέξανδρον. ἐκαλεῖτο δὲ Σφίνης ἐπεὶ δὲ κατ’ Ἰνδικὴν γλῶτταν τῷ καλὲ προσαγορεύων ἀντὶ τοῦ χαίρειν τοὺς ἐντυγχάνοντας ἠσπάζετο, Καλανὸς ὑπὸ τῶν Ἑλλήνων ὠνομάσθη. τοῦτον δὲ λέγεται καί τὸ παράδειγμα τῆς ἀρχῆς τῷ Ἀλεξάνδρῳ προθέσθαι. καταβαλὼν γὰρ ἐν μέσῳ βύρσαν τινὰ ξηρὰν καί κατεσκληκυῖαν ἐπάτησε τὸ ἄκρον ἡ δὲ εἰς ἓν πιεσθεῖσα τοῖς ἄλλοις ἐπήρθη μέρεσι. καί τοῦτο περιϊὼν ἐν κύκλῳ καί πιέζων καθ’ ἕκαστον ἐδείκνυε γιγνόμενον, ἄχρι οὗ τὸ μέσον ἐπιστὰς κατέσχε καί πάντα οὕτως ἠρέμησεν. ἐβούλετο δὲ ἡ εἰκὼν ἔνδειξις εἶναι τοῦ τὰ μέσα δεῖν μάλιστα τῆς ἀρχῆς πιέζειν καὶ μὴ μακρὰν ἀποπλανᾶσθαι τὸν Ἀλέξανδρον.", "st": "Alex. 65.1"}, {"sp": "N", "t": "ἡ δὲ διὰ τῶν ποταμῶν πρὸς τὴν θάλατταν ὑπαγωγὴ μηνῶν ἑπτὰ χρόνον ἀνάλωσεν. ἐμβαλὼν δὲ ταῖς ναυσὶν εἰς τὸν Ὠκεανόν ἀνέπλευσε πρὸς νῆσον ἣν Σκιλλοῦστιν αὐτὸς ὠνόμασεν, ἕτεροι δὲ Ψιλτοῦκιν. ἐνταῦθα δὲ ἀποβὰς ἔθυε τοῖς θεοῖς, καὶ τὴν φύσιν ἐπεῖδε τοῦ πελάγους καὶ τῆς παραλίας ὅσον ἐφικτὸν ἦν. εἶτα ἐπευξάμενος μηδένα μετ’ αὐτὸν ἀνθρώπων ὑπερβῆναι τοὺς ὅρους τῆς στρατείας ἀνέστρεφε. καὶ τὰς μὲν ναῦς ἐκέλευσε περιπλεῖν ἐν δεξιᾷ τὴν Ἰνδικὴν ἐχούσας, ἡγεμόνα μὲν Νέαρχον ἀποδείξας, ἀρχικυβερνήτην δὲ Ὀνησίκριτον αὐτὸς δὲ πεζῇ δι’ Ὠρειτῶν πορευόμενος εἰς ἐσχάτην ἀπορίαν προήχθη καὶ πλῆθος ἀνθρώπων ἀπώλεσεν, ὥστε τῆς μαχίμου δυνάμεως μηδὲ τὸ τέταρτον ἐκ τῆς Ἰνδικῆς ἀπαγαγεῖν. καίτοι δώδεκα μὲν μυριάδες ἦσαν οἱ πεζοί, τὸ δ’ ἱππικὸν εἰς μυρίους καὶ πεντακισχιλίους. ἀλλὰ καὶ νόσοι χαλεπαὶ καὶ δίαιται πονηραὶ καὶ καύματα ξηρὰ καὶ πλείστους ὁ λιμὸς διέφθειρεν, ἄσπορον χώραν ἐπιόντας ἀνθρώπων κακοβίων, ὀλίγα καὶ ἀγεννῆ πρόβατα κεκτημένων, ἃ τοὺς θαλαττίους ἰχθῦς εἰθισμένα προσφέρεσθαι σάρκα μοχθηρὰν εἶχε καὶ δυσώδη. μόλις οὖν ἐν ἡμέραις ἑξήκοντα ταύτην διελθὼν καὶ τῆς Γεδρωσίας ἁψάμενος εὐθὺς ἐν ἀφθόνοις ἦν πᾶσι, τῶν ἔγγιστα σατραπῶν καὶ βασιλέων παρασκευασάντων.", "st": "Alex. 66.1"}, {"sp": "N", "t": "ἀναλαβὼν οὖν ἐνταῦθα τὴν δύναμιν ἐξώρμησε κώμῳ χρώμενος ἐφ’ ἡμέρας ἑπτὰ διὰ τῆς Καρμανίας, αὐτὸν μὲν οὖν ἵπποι σχέδην ἐκόμιζον ὀκτώ, μετὰ τῶν ἑταίρων ὑπὲρ θυμέλης ἐν ὑψηλῷ καὶ περιφανεῖ πλαισίῳ πεπηγυίας εὐωχούμενον συνεχῶς ἡμέρας καὶ νυκτός· ἅμαξαι δὲ παμπληθεῖς, αἱ μὲν ἁλουργοῖς καὶ ποικίλοις περιβολαίοις, αἱ δ’ ὕλης ἀεὶ προσφάτου καὶ χλωρᾶς σκιαζόμεναι κλάδοις, εἵποντο τοὺς ἄλλους ἄγουσαι φίλους καὶ ἡγεμόνας ἐστεφανωμένους καὶ πίνοντας. εἶδες δ’ ἂν οὐ πέλτην, οὐ κράνος, οὐ σάρισαν, ἀλλὰ φιάλαις καὶ ῥυτοῖς καὶ θηρικλείοις παρὰ τὴν ὁδὸν ἅπασαν οἱ στρατιῶται βαπτίζοντες ἐκ πίθων μεγάλων καὶ κρατήρων ἀλλήλοις προέπινον, οἱ μὲν ἐν τῷ προάγειν ἅμα καὶ βαδίζειν, οἱ δὲ κατακείμενοι. πολλὴ δὲ μοῦσα συρίγγων καὶ αὐλῶν ᾠδῆς τε καὶ ψαλμοῦ καὶ βακχείας γυναικῶν κατεῖχε πάντα τόπον. τῷ δὲ ἀτάκτῳ καὶ πεπλανημένῳ τῆς πορείας παρείπετο καὶ παιδιὰ βακχικῆς ὕβρεως, ὡς τοῦ θεοῦ παρόντος αὐτοῦ καὶ συμπαραπέμποντος τὸν κῶμον. ἐπεὶ δὲ ἧκε τῆς Γεδρωσίας εἰς τὸ βασίλειον, αὖθις ἀνελάμβανε τὴν στρατιὰν πανηγυρίζων. λέγεται δὲ μεθύοντα αὐτὸν θεωρεῖν ἀγῶνας χορῶν, τὸν δὲ ἐρώμενον Βαγώαν χορεύοντα νικῆσαι καὶ κεκοσμημένον διὰ τοῦ θεάτρου παρελθόντα καθίσαι παρ’ αὐτόν· ἰδόντας δὲ τοὺς Μακεδόνας κροτεῖν καὶ βοᾶν φιλῆσαι κελεύοντας, ἄχρι οὗ περιβαλὼν κατεφίλησεν.", "st": "Alex. 67.1"}, {"sp": "N", "t": "ἐνταῦθα τῶν περὶ Νέαρχον ἀναβάντων πρὸς αὐτόν ἡσθεὶς καὶ διακούσας τὰ περὶ τὸν πλοῦν, ὥρμησεν αὐτὸς πλεύσας κατὰ τὸν Εὐφράτην στόλῳ μεγάλῳ, εἶτα περὶ τὴν Ἀραβίαν καὶ τὴν Λιβύην παρακομισθείς διὰ στηλῶν Ἡρακλείων ἐμβαλεῖν εἰς τὴν ἐντὸς θάλασσαν, καὶ πλοῖα παντοδαπὰ περὶ Θάψακον ἐπήγνυτο, καὶ συνήγοντο ναῦται καὶ κυβερνῆται πανταχόθεν. ἡ δὲ ἄνω στρατεία χαλεπὴ γενομένη καὶ τὸ περὶ Μαλλοὺς τραῦμα καὶ ἡ φθορὰ πολλὴ λεχθεῖσα τῆς δυνάμεως ἀπιστίᾳ τῆς σωτηρίας αὐτοῦ τά τε ὑπήκοα πρὸς ἀποστάσεις ἐπῆρε καὶ τοῖς στρατηγοῖς καὶ σατράπαις ἀδικίαν πολλὴν καὶ πλεονεξίαν καὶ ὕβριν ἐνεποίησε καὶ ὅλως διέδραμε σάλος ἁπάντων καὶ νεωτερισμός. ὅπου καὶ πρὸς Ἀντίπατρον Ὀλυμπιὰς καὶ Κλεοπάτρα στασιάσασαι διείλοντο τὴν ἀρχήν, Ὀλυμπιὰς μὲν Ἤπειρον, Κλεοπάτρα δὲ Μακεδονίαν παραλαβοῦσα. καὶ τοῦτο ἀκούσας Ἀλέξανδρος βέλτιον ἔφη βεβουλεῦσθαι τὴν μητέρα· Μακεδόνας γὰρ οὐκ ἂν ὑπομεῖναι βασιλευομένους ὑπὸ γυναικός.", "st": "Alex. 68.1"}, {"sp": "N", "t": "διὰ ταῦτα Νέαρχον μὲν αὖθις ἐπὶ θάλασσαν ἔπεμψεν, ἐμπλῆσαι πολέμων ἅπασαν ἐγνωκὼς τὴν παραλίαν, αὐτὸς δὲ καταβαίνων ἐκόλαζε τοὺς πονηροὺς τῶν στρατηγῶν. τῶν δὲ Ἀβουλήτου παίδων ἕνα μὲν Ὀξυάρτην αὐτὸς ἀπέκτεινε σαρίσῃ διελάσας, Ἀβουλήτου δὲ μηδὲν τῶν ἀναγκαίων παρασκευάσαντος, ἀλλ’ ἢ τρισχίλαι τάλαντα νομίσματος αὐτῷ προσαγαγόντος, ἐκέλευσε τοῖς ἵπποις τὸ ἀργύριον παραβαλεῖν. ὡς δ’ οὐκ ἐγεύοντο, φήσας, τί οὖν ὄφελος ἡμῖν τῆς σῆς παρασκευῆς; καθεῖρξε τὸν Ἀβουλίτην.", "st": "Alex. 68.6"}, {"sp": "N", "t": "ἐν δὲ Πέρσαις ι πρῶτον μὲν ἀπέδωκε τὸ νόμισμα ταῖς γυναιξίν, ὥσπερ εἰώθεισαν οἱ βασιλεῖς, ὁσάκις εἰς Πέρσας ἀφίκοιντο, διδόναι χρυσοῦν ἑκάστῃ, καὶ διὰ τοῦτο φασιν ἐνίους μὴ πολλάκις, Ὦχον δὲ μηδὲ ἅπαξ εἰς Πέρσας παραγενέσθαι, διὰ μικρολογίαν ἀποξενώσαντα τῆς πατρίδος ἑαυτόν. ἔπειτα τὸν Κύρου τάφον εὑρὼν διορωρυγμένον ἀπέκτεινε τὸν ἀδικήσαντα, καίτοι Πελλαῖος ἦν οὐ τῶν ἀσημοτάτων ὁ πλημμελήσας, ὄνομα Πολύμαχος. τὴν δὲ ἐπιγραφὴν ἀναγνούς ἐκέλευσεν Ἑλληνικοῖς ὑποχαράξαι γράμμασιν. εἶχε δὲ οὕτως· ὦ ἄνθρωπε, ὅστις εἶ καὶ ὅθεν ἥκεις, ὅτι μὲν γὰρ ἥξεις, οἶδα, ἐγὼ Κῦρός εἰμι ὁ Πέρσαις κτησάμενος τὴν ἀρχήν, μὴ οὖν τῆς ὀλίγης μοι ταύτης γῆς φθονήσῃς ἣ τοὐμὸν σῶμα περικαλύπτει. ταῦτα μὲν οὖν ἐμπαθῆ σφόδρα τὸν Ἀλέξανδρον ἐποίησεν, ἐν νῷ λαβόντα τὴν ἀδηλότητα καὶ μεταβολήν.", "st": "Alex. 69.1"}, {"sp": "N", "t": "ὁ δὲ Καλανὸς ἐνταῦθα χρόνον οὐ πολὺν ὑπὸ κοιλίας ἐνοχληθείς ᾐτήσατο πυρὰν αὑτῷ γενέσθαι, καὶ κομισθεὶς ἵππῳ πρὸς αὐτήν, ἐπευξάμενος καὶ κατασπείσας ἑαυτοῦ καὶ τῶν τριχῶν ἀπαρξάμενος, ἀναβαίνων ἐδεξιοῦτο τοὺς παρόντας τῶν Μακεδόνων, καὶ παρεκάλει τὴν ἡμέραν ἐκείνην ἡδέως γενέσθαι καὶ μεθυσθῆναι μετὰ τοῦ βασιλέως, αὐτὸν δὲ ἐκεῖνον ἔφη μετ’ ὀλίγον χρόνον ἐν Βαβυλῶνι ὄψεσθαι. ταῦτα δ’ εἰπών κατακλιθεὶς καὶ συγκαλυψάμενος οὐκ ἐκινήθη τοῦ πυρὸς πλησιάζοντος, ἀλλ’ ἐν ᾧ κατεκλίθη σχήματι, τοῦτο διατηρῶν ἐκαλλιέρησεν ἑαυτὸν τῷ πατρίῳ νόμῳ τῶν ἐκεῖ σοφιστῶν, τοῦτο πολλοῖς ἔτεσιν ὕστερον ἄλλος Ἰνδὸς ἐν Ἀθήναις Καίσαρι συνὼν ἐποίησε· καὶ δείκνυται μέχρι νῦν τὸ μνημεῖον Ἰνδοῦ προσαγορευόμενον.", "st": "Alex. 69.6"}, {"sp": "N", "t": "ὁ δὲ Ἀλέξανδρος ἀπὸ τῆς πυρᾶς γενόμενος, καὶ συναγαγὼν πολλοὺς Τῶν φίλων καὶ Τῶν ἡγεμόνων ἐπὶ δεῖπνον, ἀγῶνα προὔθηκε καὶ στέφανον ἀκρατοποσίας. ὁ μὲν οὖν πλεῖστον πιὼν Πρόμαχος ἄχρι χοῶν τεσσάρων προῆλθε· καὶ λαβὼν τὸ νικητήριον, στέφανον ταλαντιαῖον, ἡμέρας τρεῖς ἐπέζησε, Τῶν δὲ ἄλλων, ὡς Χάρης φησί, τετταράκοντα καὶ εἷς ἀπέθανον πιόντες, ἰσχυροῦ τῇ μέθῃ κρύους ἐπιγενομένου.", "st": "Alex. 70.1"}, {"sp": "N", "t": "τῶν δὲ ἑταίρων γάμον ἐν Σούσοις ἐπιτελῶν, καὶ λαμβάνων μὲν αὐτὸς γυναῖκα τὴν Δαρείου θυγατέρα Στάτειραν, διανέμων δὲ τὰς ἀρίστας τοῖς ἀρίστοις, κοινὸν δὲ Τῶν ἤδη προγεγαμηκότων Μακεδόνων γάμον ἄλλον ἑστιάσας, ἐν ᾧ φασιν ἐννακισχιλίων Τῶν παρακεκλημένων ἐπὶ τὸ δεῖπνον ὄντων ἑκάστῳ χρυσῆν φιάλην πρὸς τὰς σπονδὰς δοθῆναι, τά τε ἄλλα θαυμαστῶς ἐλαμπρύνατο καὶ τά χρέα τοῖς δανείσασιν ὑπὲρ Τῶν ὀφειλόντων αὐτὸς διαλύσας, τοῦ παντὸς ἀναλώματος ἐλάσσονος μυρίων ταλάντων ἑκατὸν τριάκοντα ταλάντοις γενομένου. ἐπεὶ δὲ Ἀντιγένης ὁ ἑτερόφθαλμος ὡς ὀφείλων ἀπεγράψατο ψευδῶς, καὶ παραγαγών τινα φάσκοντα δεδανεικέναι πρὸς τὴν τράπεζαν, ἀπέτισε τὸ ἀργύριον, εἶτ’ ἐφωράθη ψευδόμενος, ὀργισθεὶς ὁ βασιλεὺς ἀπήλασε τῆς αὐλῆς αὐτὸν καὶ παρείλετο τὴν ἡγεμονίαν. ἦν δὲ λαμπρὸς ἐν τοῖς πολεμικοῖς ὁ Ἀντιγένης καὶ ἔτι δὲ νέος ὤν, Φιλίππου πολιορκοῦντος Πέρινθον, ἐμπεσόντος αὐτῷ καταπελτικοῦ βέλους εἷς τὸν ὀφθαλμόν, οὐ παρέσχε βουλομένοις ἐξελεῖν τὸ βέλος οὐδὲ ὑφήκατο πρὶν ὤσασθαι προσμαχόμενος καὶ κατακλεῖσαι τοὺς πολεμίους εἷς τὸ τεῖχος. οὐ μετρίως οὖν τότε τὴν ἀτιμίαν ἔφερεν, ἀλλὰ δῆλος ἦν ἑαυτὸν ὑπὸ λύπης καὶ βαρυθυμίας διαχρησόμενος. καὶ τοῦτο δείσας ὁ βασιλεὺς ἀνῆκε τὴν ὀργὴν καὶ τὰ χρήματα ἔχειν ἐκέλευσεν αὐτόν.", "st": "Alex. 70.3"}, {"sp": "N", "t": "τῶν δὲ παίδων Τῶν τρισμυρίων, οὓς ἀσκουμένους καὶ μανθάνοντας ἀπέλιπε, τοῖς τε σώμασιν ἀνδρείων φανέντων καὶ τοῖς εἴδεσιν εὐπρεπῶν, ἔτι δὲ καὶ ταῖς μελέταις εὐχέρειαν καὶ κουφότητα θαυμαστὴν ἐπιδειξαμένων, αὐτὸς μὲν ἥσθη, τοῖς δὲ Μακεδόσι δυσθυμία παρέστη καὶ δέος, ὡς ἧττον αὐτοῖς τοῦ βασιλέως προσέξοντος. διὸ καὶ τοὺς ἀσθενεῖς καὶ πεπηρωμένους αὐτοῦ καταπέμποντος ἐπὶ θάλατταν ὕβριν ἔφασαν εἶναι καὶ προπηλακισμόν, ἀνθρώποις ἀποχρησάμενον εἰς ἅπαντα νῦν ἀποτίθεσθαι σὺν αἰσχύνῃ καὶ προσρίπτειν ταῖς πατρίσι καὶ τοῖς γονεῦσιν, οὐ τοιούτους παραλαβόντα. πάντας οὖν ἐκέλευον ἀφιέναι καὶ πάντας ἀχρήστους νομίζειν Μακεδόνας, ἔχοντα τοὺς νέους τούτους πυρριχιστάς, σὺν οἷς ἐπιὼν κατακτήσεται τὴν οἰκουμένην. πρὸς ταῦτα χαλεπῶς ὁ Ἀλέξανδρος ἔσχε, καὶ πολλὰ μὲν ἐλοιδόρησεν αὐτοὺς πρὸς ὀργήν, ἀπελάσας δὲ τὰς φυλακὰς παρέδωκε Πέρσαις καὶ κατέστησεν ἐκ τούτων δορυφόρους καὶ ῥαβδοφόρους, ὑφ’ ὧν ὁρῶντες αὐτὸν παραπεμπόμενον, αὐτοὺς δὲ ἀπειργομένους καὶ προπηλακιζομένους, ἐταπεινοῦντο καὶ διδόντες λόγον εὕρισκον αὑτοὺς ὀλίγου δεῖν μανέντας ὑπὸ ζηλοτυπίας καὶ ὀργῆς. τέλος δὲ συμφρονήσαντες ἐβάδιζον ἄνοπλοι καὶ μονοχίτωνες ἐπὶ τὴν σκηνήν, μετὰ βοῆς καὶ κλαυθμοῦ παραδιδόντες ἑαυτούς καὶ χρήσασθαι κελεύοντες ὡς κακοῖς καὶ ἀχαρίστοις. ὁ δ’ οὐ προσίετο, καίπερ ἤδη μαλασσόμενος. οἱ δ’ οὐκ ἀπέστησαν, ἀλλ’ ἡμέρας δύο καὶ νύκτας οὕτω προσεστῶτες καὶ ὀλοφυρόμενοι καὶ κοίρανον ἀνακαλοῦντες ἐκαρτέρησαν. τῇ δὲ τρίτῃ προελθὼν καὶ θεασάμενος οἰκτροὺς καὶ τεταπεινωμένους ἐδάκρυε πολὺν χρόνον εἶτα μεμψάμενος μέτρια καὶ προσαγορεύσας φιλανθρώπως ἀπέλυσε τοὺς ἀχρήστους δωρησάμενος μεγαλοπρεπῶς, καὶ γράψας πρὸς Ἀντίπατρον ὅπως ἐν πᾶσι τοῖς ἀγῶσι καὶ τοῖς θεάτροις προεδρίαν ἔχοντες ἐστεφανωμένοι καθέζοιντο. τῶν δὲ τεθνηκότων τοὺς παῖδας ὀρφανοὺς ὄντας ἐμμίσθους ἐποίησεν.", "st": "Alex. 71.1"}, {"sp": "N", "t": "ὡς δὲ ἧκεν εἰς Ἐκβάτανα τῆς Μηδίας καὶ διῴκησε τὰ κατεπείγοντα, πάλιν ἦν ἐν θεάτροις καὶ πανηγύρεσιν, ἅτε δὴ τρισχιλίων αὐτῷ τεχνιτῶν ἀπὸ τῆς Ἑλλάδος ἀφιγμένων. ἔτυχε δὲ περὶ τὰς ἡμέρας ἐκείνας Ἡφαιστίων πυρέσσων· οἷα δὲ νέος καὶ στρατιωτικὸς οὐ φέρων ἀκριβῆ δίαιταν, ἅμα τῷ τὸν ἰατρὸν Γλαῦκον ἀπελθεῖν εἰς τὸ θέατρον περὶ ἄριστον γενόμενος καὶ καταφαγὼν ἀλεκτρυόνα ἑφθὸν καὶ ψυκτῆρα μέγαν ἐκπιὼν οἴνου κακῶς ἔσχε καὶ μικρὸν διαλιπὼν ἀπέθανε. τοῦτο οὐδενὶ λογισμῷ τὸ πάθος Ἀλέξανδρος ἤνεγκεν, ἀλλ’ εὐθὺς μὲν ἵππους τε κεῖραι πάντας ἐπὶ πένθει καὶ ἡμιόνους ἐκέλευσε καὶ τῶν πέριξ πόλεων ἀφεῖλε τὰς ἐπάλξεις, τὸν δὲ ἄθλιον ἰατρὸν ἀνεσταύρωσεν, αὐλοὺς δὲ κατέπαυσε καὶ μουσικὴν πᾶσαν ἐν τῷ στρατοπέδῳ πολὺν χρόνον, ἕως ἐξ Ἄμμωνος ἦλθε μαντεία τιμᾶν Ἡφαιστίωνα καὶ θύειν ὡς ἥρωϊ παρακελεύουσα. τοῦ δὲ πένθους παρηγορίᾳ τῷ πολέμῳ χρώμενος, ὥσπερ ἐπὶ θήραν καὶ κυνηγέσιον ἀνθρώπων ἐξῆλθε καὶ τὸ Κοσσαίων ἔθνος κατεστρέφετο, πάντας ἡβηδὸν ἀποσφάττων· τοῦτο δὲ· Ἡφαιστίωνος ἐναγισμὸς ἐκαλεῖτο. τύμβον δὲ καὶ ταφὴν αὐτοῦ καὶ τὸν περὶ ταῦτα κόσμον ἀπὸ μυρίων ταλάντων ἐπιτελέσαι διανοούμενος, ὑπερβαλέσθαι δὲ τῷ φιλοτέχνῳ καὶ περιττῷ τῆς κατασκευῆς τὴν δαπάνην, ἐπόθησε μάλιστα τῶν τεχνιτῶν Στασικράτην, μεγαλουργίαν τινὰ καὶ τόλμαν καὶ κόμπον ἐν ταῖς καινοτομίαις ἐπαγγελλόμενον. οὗτος γὰρ αὐτῷ πρότερον ἐντυχὼν ἔφη τῶν ὀρῶν μάλιστα τὸν Θρᾴκιον Ἄθων διατύπωσιν ἀνδρείκελον δέχεσθαι καὶ διαμόρφωσιν ἂν οὖν κελεύῃ, μονιμώτατον ἀγαλμάτων αὐτῷ καὶ περιφανέστατον ἐξεργάσεσθαι τὸν Ἄθων, τῇ μὲν ἀριστερᾷ χειρὶ περιλαμβάνοντα μυρίανδρον πόλιν οἰκουμένην, τῇ δὲ δεξιᾷ σπένδοντα ποταμοῦ ῥεῦμα δαψιλὲς εἰς τὴν θάλασσαν ἀπορρέοντος, ταῦτα μὲν οὖν παρῃτήσατο, πολλῷ δὲ ἀτοπώτερα καὶ δαπανηρότερα τούτων σοφιζόμενος τότε καὶ συμμηχανώμενος τοῖς τεχνίταις διέτριβεν.", "st": "Alex. 72.1"}, {"sp": "N", "t": "εἰς δὲ Βαβυλῶνα προάγοντος αὐτοῦ Νέαρχος ἀφίκετο γὰρ αὖθις εἰσπλεύσας Εἰς τὸν Εὐφράτην διὰ τῆς μεγάλης θαλάσσης ἔφη τινὰς ἐντυχεῖν αὐτῷ Χαλδαίους, παραινοῦντας ἀπέχεσθαι Βαβυλῶνος τὸν Ἀλέξανδρον. ὁ δὲ οὐκ ἐφρόντισεν, ἀλλ’ ἐπορεύετο· καὶ πρὸς τοῖς τείχεσι γενόμενος ὁρᾷ κόρακας πολλοὺς διαφερομένους καὶ τύπτοντας ἀλλήλους, ὧν ἔνιοι κατέπεσον παρ’ αὐτόν. ἔπειτα μηνύσεως γενομένης κατὰ Ἀπολλοδώρου τοῦ στρατηγοῦ τῆς Βαβυλῶνος ὡς εἴη περὶ αὐτοῦ τεθυμένος, ἐκάλει Πυθαγόραν τὸν μάντιν. οὐκ ἀρνουμένου δὲ τὴν πρᾶξιν ἠρώτησε τῶν ἱερῶν τὸν τρόπον, φήσαντος δὲ ὅτι τὸ ἧπαρ ἦν ἄλοβον, παπαὶ, εἶπεν, ἰσχυρὸν τὸ σημεῖον καὶ τὸν Πυθαγόραν οὐδὲν ἠδίκησεν. ἤχθετο δὲ μὴ πεισθεὶς τῷ Νεάρχῳ, καὶ τὰ πολλὰ τῆς Βαβυλῶνος ἔξω κατασκηνῶν καὶ περιπλέων τὸν Εὐφράτην διέτριβεν. ἠνώχλει δ’ αὐτὸν σημεῖα πολλά, καὶ γὰρ λέοντα τῶν τρεφομένων μέγιστον καὶ κάλλιστον ἥμερος ὄνος ἐπελθὼν καὶ λακτίσας ἀνεῖλεν. ἀποδυσαμένου δὲ πρὸς ἄλειμμα καὶ σφαῖραν αὐτοῦ παίζοντος οἱ νεανίσκοι οἱ σφαιρίζοντες, ὡς ἔδει πάλιν λαβεῖν τὰ ἱμάτια, καθορῶσιν ἄνθρωπον ἐν τῷ θρόνῳ καθεζόμενον σιωπῇ, τὸ διάδημα καὶ τὴν στολὴν τὴν βασιλικὴν περικείμενον. οὗτος ἀνακρινόμενος ὅστις εἴη, πολὺν χρόνον ἄναυδος ἦν μόλις δὲ συμφρονήσας Διονύσιος μὲν ἔφη καλεῖσθαι, Μεσσήνιος δὲ εἶναι τὸ γένος· ἐκ δέ τινος αἰτίας καὶ κατηγορίας ἐνταῦθα κομισθεὶς ἀπὸ θαλάσσης πολὺν χρόνον γεγονέναι ἐν δεσμοῖς· ἄρτι δὲ αὐτῷ τὸν Σάραπιν ἐπιστάντα τοὺς δεσμοὺς ἀνεῖναι καὶ προαγαγεῖν δεῦρο, καὶ κελεῦσαι λαβόντα τὴν στολὴν καὶ τὸ διάδημα καθίσαι καὶ σιωπᾶν.", "st": "Alex. 73.1"}, {"sp": "N", "t": "ταῦτα ἀκούσας ὁ Ἀλέξανδρος τὸν μὲν ἄνθρωπον, ὥσπερ ἐκέλευον οἱ μάντεις, ἠφάνισεν αὐτὸς δὲ ἠθύμει καὶ δύσελπις ἦν πρὸς τὸ θεῖον ἤδη καὶ πρὸς τοὺς φίλους ὕποπτος, Μάλιστα δὲ Ἀντίπατρον ἐφοβεῖτο καὶ τοὺς παῖδας, ὧν Ἰόλας μὲν ἀρχιοινοχόος ἦν, ὁ δὲ Κάσανδρος ἀφῖκτο μὲν νεωστί, θεασάμενος δὲ βαρβάρους τινὰς προσκυνοῦντας, ἅτε δὴ τεθραμμένος Ἑλληνικῶς καὶ τοιοῦτο πρότερον μηδὲν ἑωρακώς, ἐγέλασε προπετέστερον. ὁ δὲ Ἀλέξανδρος ὠργίσθη, καὶ δραξάμενος αὐτοῦ τῶν τριχῶν σφόδρα ταῖς χερσὶν ἀμφοτέραις ἔπαισε τὴν κεφαλὴν πρὸς τὸν τοῖχον. αὖθις δὲ πρὸς τοὺς κατηγοροῦντας Ἀντιπάτρου λέγειν τι βουλόμενον τὸν Κάσανδρον ἐκκρούων, τί λέγεις; ἔφη, τοσαύτην ὁδὸν ἀνθρώπους μηδὲν ἀδικουμένους, ἀλλὰ συκοφαντοῦντας ἐλθεῖν; φήσαντος δὲ τοῦ Κασάνδρου τοῦτο αὐτὸ σημεῖον εἶναι τοῦ συκοφαντεῖν, ὅτι μακρὰν ἥκουσι τῶν ἐλέγχων, ἀναγελάσας ὁ Ἀλέξανδρος, ταῦτα ἐκεῖνα, ἔφη, σοφίσματα τῶν Ἀριστοτέλους εἰς ἑκάτερον τὸν λόγον οἰμωξομένων, ἂν καὶ μικρὸν ἀδικοῦντες τοὺς ἀνθρώπους φανῆτε. τὸ δὲ ὅλον οὕτω φασὶ δεινὸν ἐνδῦναι καὶ δευσοποιὸν ἐγγενέσθαι τῇ ψυχῇ τοῦ Κασάνδρου τὸ δέος, ὥστε ὕστερον χρόνοις πολλοῖς, ἤδη Μακεδόνων βασιλεύοντα καὶ κρατοῦντα τῆς Ἑλλάδος, ἐν Δελφοῖς περιπατοῦντα καὶ θεώμενον τοὺς ἀνδριάντας, εἰκόνος Ἀλεξάνδρου φανείσης, ἄφνω πληγέντα φρῖξαι καὶ κραδανθῆναι τὸ σῶμα καὶ μόλις ἀναλαβεῖν ἑαυτόν, ἰλιγγιάσαντα πρὸς τὴν ὄψιν.", "st": "Alex. 74.1"}, {"sp": "N", "t": "ὁ δ’ οὖν Ἀλέξανδρος ὡς ἐνέδωκε τότε πρὸς τὰ θεῖα ταραχώδης γενόμενος καὶ περίφοβος τὴν διάνοιαν, οὐδὲν ἦν μικρὸν οὕτως τῶν ἀήθων καὶ ἀτόπων ὃ μὴ τέρας ἐποιεῖτο καὶ σημεῖον ἀλλὰ θυομένων καὶ καθαιρόντων καὶ μαντευόντων μεστὸν ἦν τὸ βασίλειον. οὕτως ἄρα δεινὸν μὲν ἡ ἀπιστία πρὸς τὰ θεῖα καὶ καταφρόνησις αὐτῶν, δεινὴ δὲ αὖθις ἡ δεισιδαιμονία, ἡ, δίκην ὕδατος ἀεὶ πρὸς τὸ ταπεινούμενον καταρρέοντος, ἀνεπλήρου ἀβελτερίας κατάφοβον τὸν Ἀλέξανδρον γενόμενον. οὐ μὴν ἀλλὰ καὶ χρησμῶν γε τῶν περὶ Ἡφαιστίωνος ἐκ θεοῦ κομισθέντων ἀποθέμενος τὸ πένθος αὖθις ἦν ἐν θυσίαις καὶ πότοις. ἑστιάσας δὲ λαμπρῶς τοὺς περὶ Νέαρχον, εἶτα λουσάμενος, ὥσπερ εἰώθει μέλλων καθεύδειν, Μηδίου δεηθέντος ᾤχετο κωμασόμενος πρὸς αὐτόν κἀκεῖ πιὼν ὅλην τὴν ἐπιοῦσαν ἡμέραν ἤρξατο πυρέττειν, οὔτε σκύφον Ἡρακλέους ἐκπιὼν οὔτε ἄφνω διαλγὴς γενόμενος τὸ μετάφρενον ὥσπερ λόγχῃ πεπληγώς, ἀλλὰ ταῦτά τινες ᾤοντο δεῖν γράφειν ὥσπερ δράματος μεγάλου τραγικὸν ἐξόδιον καὶ περιπαθὲς πλάσαντες. Ἀριστόβουλος δέ φησιν αὐτόν πυρέττοντα μανικῶς, διψήσαντα δὲ σφόδρα πιεῖν οἶνον ἐκ τούτου δὲ φρενιτιᾶσαι, καὶ τελευτῆσαι τριακάδι Δαισίου μηνός.", "st": "Alex. 75.1"}, {"sp": "N", "t": "ἐν δὲ ταῖς ἐφημερίσιν οὕτως γέγραπται τὰ περὶ τὴν νόσον. ὀγδόῃ ἐπὶ δεκάτῃ Δαισίου μηνὸς ἐκάθευδεν ἐν τῷ λουτρῶνι διὰ τὸ πυρέξαι. τῇ δὲ ἑξῆς λουσάμενος εἰς τὸν θάλαμον μετῆλθε, καὶ διημέρευε πρὸς Μήδιον κυβεύων. εἶτ’ ὀψὲ λουσάμενος καὶ τὰ ἱερὰ τοῖς θεοῖς ἐπιθείς ἐμφαγὼν διὰ νυκτὸς ἐπύρεξε. τῇ εἰκάδι λουσάμενος πάλιν ἔθυσε τὴν εἰθισμένην θυσίαν καὶ κατακείμενος ἐν τῷ λουτρῶνι τοῖς περὶ Νέαρχον ἐσχόλαζεν, ἀκροώμενος τὰ περὶ τὸν πλοῦν καὶ τὴν μεγάλην θάλατταν. τῇ δεκάτῃ φθίνοντος ταὐτὰ ποιήσας μᾶλλον ἀνεφλέχθη, καὶ τὴν νύκτα βαρέως ἔσχε, καὶ τὴν ἐπιοῦσαν ἡμέραν ἐπύρεττε σφόδρα, καὶ μεταρθεὶς κατέκειτο παρὰ τὴν μεγάλην κολυμβήθραν, ὅτε δὴ τοῖς ἡγεμόσι διελέχθη περὶ τῶν ἐρήμων ἡγεμονίας τάξεων, ὅπως καταστήσωσι δοκιμάσαντες. ἑβδόμῃ σφόδρα πυρέττων ἔθυσεν ἐξαρθεὶς πρὸς τὰ ἱερά τῶν δὲ ἡγεμόνων ἐκέλευε τοὺς μεγίστους διατρίβειν ἐν τῇ αὐλῇ, ταξιάρχους δὲ καὶ πεντακοσιάρχους ἔξω νυκτερεύειν. εἰς δὲ τὰ πέραν βασίλεια διακομισθεὶς τῇ ἕκτῃ μικρὸν ὕπνωσεν, ὁ δὲ πυρετὸς οὐκ ἀνῆκεν. ἐπελθόντων δὲ τῶν ἡγεμόνων ἦν ἄφωνος, ὁμοίως δὲ καὶ τὴν πέμπτην· διὸ καὶ τοῖς Μακεδόσιν ἔδοξε τεθνάναι, καὶ κατεβόων ἐλθόντες ἐπὶ τὰς θύρας, καὶ διηπειλοῦντο τοῖς ἑταίροις ἕως ἐβιάσαντο καὶ τῶν θυρῶν αὐτοῖς ἀνοιχθεισῶν ἐν τοῖς χιτῶσι καθ’ ἕνα πάντες παρὰ τὴν κλίνην παρεξῆλθον. ταύτης δὲ τῆς ἡμέρας οἱ περὶ Πύθωνα καὶ Σέλευκον εἰς τὸ Σεραπεῖον ἀποσταλέντες ἠρώτων εἰ κομίσωσιν ἐκεῖ τὸν Ἀλέξανδρον ὁ δὲ θεὸς κατὰ χώραν ἐᾶν ἀνεῖλε. τῇ δὲ τρίτῃ φθίνοντος πρὸς δείλην ἀπέθανε.", "st": "Alex. 76.1"}, {"sp": "N", "t": "τούτων τὰ πλεῖστα κατὰ λέξιν ἐν ταῖς ἐφημερίσιν οὕτω γέγραπται. φαρμακείας δὲ ὑποψίαν παραυτίκα μὲν οὐδεὶς ἔσχεν, ἕκτῳ δὲ ἔτει φασὶ μηνύσεως γενομένης τὴν Ὀλυμπιάδα πολλοὺς μὲν ἀνελεῖν, ἐκρῖψαι δὲ τὰ λείψανα τοῦ Ἰόλα τεθνηκότος, ὡς τούτου τὸ φάρμακον ἐγχέαντος. οἱ δὲ Ἀριστοτέλην φάσκοντες Ἀντιπάτρῳ σύμβουλον γεγενῆσθαι τῆς πράξεως, καὶ ὅλως δι’ ἐκείνου πορισθῆναι τὸ φάρμακον, Ἁγνόθεμίν τινα διηγεῖσθαι λέγουσιν ὡς Ἀντιγόνου τοῦ βασιλέως ἀκούσαντα τὸ δὲ φάρμακον ὕδωρ εἶναι ψυχρὸν καὶ παγετῶδες ἀπὸ πέτρας τινὸς ἐν Νωνάκριδι οὔσης, ἣν ὥσπερ δρόσον λεπτὴν ἀναλαμβάνοντες εἰς ὄνου χηλὴν ἀποτίθενται τῶν γὰρ ἄλλων οὐδὲν ἀγγεῖον στέγειν, ἀλλὰ διακόπτειν ὑπὸ ψυχρότητος καὶ δριμύτητος. οἱ δὲ πλεῖστοι τὸν λόγον ὅλως οἴονται πεπλάσθαι τὸν περὶ τῆς Φαρμακείας· καὶ τεκμήριον αὐτοῖς ἐστιν οὐ μικρόν ὅτι τῶν ἡγεμόνων στασιασάντων ἐφ’ ἡμέρας πολλὰς ἀθεράπευτον τὸ σῶμα κείμενον ἐν τόποις θερμοῖς καὶ πνιγώδεσιν οὐδὲν ἔσχε τοιαύτης φθορᾶς σημεῖον, ἀλλ’ ἔμεινε καθαρὸν καὶ πρόσφατον.", "st": "Alex. 77.1"}, {"sp": "N", "t": "ἡ δὲ Ῥωξάνη κύουσα μὲν ἐτύγχανε καὶ διὰ τοῦτο τιμωμένη παρὰ τοῖς Μακεδόσι· δυσζήλως δὲ ἔχουσα πρὸς τὴν Στάτειραν ἐξηπάτησεν αὐτὴν ἐπιστολῇ τινι πεπλασμένῃ παραγενέσθαι, καὶ προσαγαγοῦσα μετὰ τῆς ἀδελφῆς ἀπέκτεινε, καὶ τοὺς νεκροὺς εἰς τὸ φρέαρ κατέβαλε καὶ συνέχωσεν, εἰδότος ταῦτα Περδίκκου καὶ συμπράττοντος. ἦν γὰρ ἐκεῖνος εὐθὺς ἐν δυνάμει μεγίστῃ, τὸν Ἀρριδαῖον ὥσπερ δορυφόρημα τῆς βασιλείας ἐφελκόμενος, γεγονότα μὲν ἐκ γυναικὸς ἀδόξου καὶ κοινῆς Φιλίννης, ἀτελῆ δὲ τὸ φρονεῖν ὄντα διὰ σώματος νόσον οὐ φύσει προσπεσοῦσαν οὐδὲ αὐτομάτως, ἀλλὰ καὶ πάνυ φασὶ παιδὸς ὄντος αὐτοῦ διαφαίνεσθαι χάριεν ἦθος καὶ οὐκ ἀγεννές, εἶτα μέντοι φαρμάκοις ὑπὸ Ὀλυμπιάδος κακωθέντα διαφθαρῆναι τὴν διάνοιαν.", "st": "Alex. 77.6"}, {"sp": "HDR", "t": "Γ. Ἰούλιος Καῖσαρ"}, {"sp": "N", "t": "τὴν Κίννα τοῦ μοναρχήσαντος θυγατέρα Κορνηλίαν, ὡς ἐπεκράτησε Σύλλας, οὔτε ἐλπίσιν οὔτε φόβῳ δυνηθεὶς ἀποσπάσαι Καίσαρος, ἐδήμευσε Τὴν φερνὴν αὐτῆς. αἰτία δὲ Καίσαρι τῆς πρὸς Σύλλαν ἀπεχθείας ἡ πρὸς Μάριον οἰκειότης ἦν. Ἰουλίᾳ γὰρ, πατρὸς ἀδελφῇ Καίσαρος, ὁ πρεσβύτερος συνῴκει Μάριος, ἐξ ἧς ἐγεγόνει Μάριος ὁ νεώτερος, ἀνεψιὸς ὢν Καίσαρος. ὡς δὲ ὑπὸ πλήθους φόνων ἐν ἀρχῇ καὶ δι’ ἀσχολίας ὑπὸ Σύλλα παρορώμενος οὐκ ἠγάπησεν, ἀλλὰ μετιὼν ἱερωσύνην εἰς τὸν δῆμον προῆλθεν οὔπω πάνυ μειράκιον ὤν, ταύτης μέν ἐκπεσεῖν αὐτὸν ὑπεναντιωθεὶς Σύλλας παρεσκεύασε, περὶ δὲ ἀναιρέσεως βουλευόμενος, ἐνίων λεγόντων ὡς οὐκ ἔχοι λόγον ἀποκτιννύναι παῖδα τηλικοῦτον, οὐκ ἔφη νοῦν ἔχειν αὐτούς, εἰ μὴ πολλοὺς ἐν τῷ παιδὶ τούτῳ Μαρίους ἐνορῶσι. ταύτης τῆς φωνῆς ἀνενεχθείσης πρὸς Καίσαρα συχνὸν μέν τινα χρόνον πλανώμενος ἐν Σαβίνοις ἔκλεπτεν ἑαυτόν ἔπειτα δι’ ἀρρωστίαν εἰς οἰκίαν ἑτέραν μετακομιζόμενος κατὰ νύκτα περιπίπτει στρατιώταις τοῦ Σύλλα διερευνωμένοις ἐκεῖνα τὰ χωρία καὶ τοὺς κεκρυμμένους συλλαμβάνουσιν. ὧν τὸν ἡγεμόνα Κορνήλιον πείσας δυσὶ ταλάντοις ἀφείθη, καὶ καταβὰς εὐθὺς ἐπὶ θάλατταν ἐξέπλευσεν εἰς Βιθυνίαν πρὸς Νικομήδην τὸν βασιλέα. παρ’ ᾧ διατρίψας χρόνον οὐ πολύν, εἶτα ἀποπλέων ἁλίσκεται περὶ Τὴν Φαρμακοῦσσαν νῆσον ὑπὸ πειρατῶν ἤδη τότε στόλοις μεγάλοις καὶ σκάφεσιν ἀπλέτοις κατεχόντων Τὴν θάλατταν.", "st": "Caes. 1.1"}, {"sp": "N", "t": "πρῶτον μὲν οὖν αἰτηθεὶς ὑπ’ αὐτῶν λύτρα εἴκοσι τάλαντα κατεγέλασεν ὡς οὐκ εἰδότων ὃν ᾑρήκοιεν, αὐτὸς δὲ ὡμολόγησε πεντήκοντα δώσειν ἔπειτα τῶν περὶ αὐτὸν ἄλλον εἰς ἄλλην διαπέμψας πόλιν ἐπὶ τὸν τῶν χρημάτων πορισμόν, ἐν ἀνθρώποις φονικωτάτοις Κίλιξι μεθ’ ἑνὸς φίλου καὶ δυοῖν ἀκολούθοιν ἀπολελειμμένος οὕτω καταφρονητικῶς εἶχεν ὥστε πέμπων ὁσάκις ἀναπαύοιτο προσέταττεν αὐτοῖς σιωπᾶν. ἡμέραις δὲ τεσσαράκοντα δυεῖν δεούσαις, ὥσπερ οὐ φρουρούμενος, ἀλλὰ δορυφορούμενος ὑπ’ αὐτῶν, ἐπὶ πολλῆς ἀδείας συνέπαιζε καὶ συνεγυμνάζετο. καὶ ποιήματα γράφων καὶ λόγους τινὰς ἀκροαταῖς ἐκείνοις ἐχρῆτο, καὶ τοὺς μὴ θαυμάζοντας ἄντικρυς ἀπαιδεύτους καὶ βαρβάρους ἀπεκάλει, καὶ σὺν γέλωτι πολλάκις ἠπείλησε κρεμᾶν αὐτούς. οἱ δὲ ἔχαιρον, ἀφελείᾳ τινὶ καὶ παιδιᾷ τὴν παρρησίαν ταύτην νέμοντες. ὡς δὲ ἧκον ἐκ Μιλήτου τὰ λύτρα καὶ δοὺς ἀφείθη, πλοῖα πληρώσας εὐθὺς ἐκ τοῦ Μιλησίων λιμένος ἐπὶ τοὺς λῃστὰς ἀνήγετο καὶ καταλαβὼν ἔτι πρὸς τῇ νήσῳ ναυλοχοῦντας ἐκράτησε τῶν πλείστων, καὶ τὰ μὲν χρήματα λείαν ἐποιήσατο, τοὺς δὲ ἄνδρας ἐν Περγάμῳ καταθέμενος εἰς τὸ δεσμωτήριον αὐτὸς ἐπορεύθη πρὸς τὸν διέποντα τὴν Ἀσίαν Ἰούνιον, ὡς ἐκείνῳ προσῆκον ὄντι στρατηγῷ κολάσαι τοὺς ἑαλωκότας. ἐκείνου δὲ καὶ τοῖς χρήμασιν ἐποφθαλμιῶντος (ἦν γὰρ οὐκ ὀλίγα) καὶ περὶ τῶν αἰχμαλώτων σκέψεσθαι φάσκοντος ἐπὶ σχολῆς, χαίρειν ἐάσας αὐτὸν ὁ Καῖσαρ εἰς Πέργαμον ᾤχετο, καὶ προαγαγὼν τοὺς λῃστὰς ἅπαντας ἀνεσταύρωσεν, ὥσπερ αὐτοῖς δοκῶν παίζειν ἐν τῇ νήσῳ προειρήκει πολλάκις.", "st": "Caes. 2.1"}, {"sp": "N", "t": "ἐκ δὲ τούτου τῆς Σύλλα δυνάμεως ἤδη μαραινομένης καὶ τῶν οἴκοι καλούντων αὐτόν ἔπλευσεν εἰς Ῥόδον ἐπὶ σχολὴν πρὸς Ἀπολλώνιον τὸν τοῦ Μόλωνος, οὗ καὶ Κικέρων ἠκρόατο, σοφιστεύοντος ἐπιφανῶς καὶ τὸν τρόπον ἐπιεικοῦς εἶναι δοκοῦντος, λέγεται δὲ καὶ φῦναι πρὸς λόγους πολιτικοὺς ὁ Καῖσαρ ἄριστα, καὶ διαπονῆσαι φιλοτιμότατα τὴν φύσιν, ὡς τὰ δευτερεῖα μὲν ἀδηρίτως ἔχειν, τὸ δὲ πρωτεῖον, ὅπως τῇ δυνάμει καὶ τοῖς ὅπλοις πρῶτος εἴη μᾶλλον ἀσχοληθείς, ἀφεῖναι, πρὸς ὅπερ ἡ φύσις ὑφηγεῖτο τῆς ἐν τῷ λέγειν δεινότητος, ὑπὸ στρατειῶν καὶ πολιτείας, ᾗ κατεκτήσατο τὴν ἡγεμονίαν, οὐκ ἐξικόμενος. αὐτὸς δ’ οὖν ὕστερον ἐν τῇ πρὸς Κικέρωνα περὶ Κάτωνος ἀντιγραφῇ παραιτεῖται μὴ στρατιωτικοῦ λόγον ἀνδρὸς ἀντεξετάζειν πρὸς δεινότητα ῥήτορος εὐφυοῦς καὶ σχολὴν ἐπὶ τοῦτο πολλὴν ἄγοντος.", "st": "Caes. 3.1"}, {"sp": "N", "t": "ἐπανελθὼν δ’ εἰς Ῥώμην Δολοβέλλαν ἔκρινε κακώσεως ἐπαρχίας, καὶ πολλαὶ τῶν ἀπὸ τῆς Ἑλλάδος πόλεων μαρτυρίας αὐτῷ παρέσχον, ὁ μὲν οὖν Δολοβέλλας ἀπέφυγε τὴν δίκην, ὁ δὲ Καῖσαρ ἀμειβόμενος τὴν Ἑλλάδα τῆς προθυμίας συνηγόρευσεν αὐτῇ Πόπλιον Ἀντώνιον διωκούσῃ δωροδοκίας ἐπὶ Λευκούλλου τοῦ Μάρκου Μακεδονίας στρατηγοῦ. καὶ τοσοῦτον ἴσχυσεν ὥστε τὸν Ἀντώνιον ἐπικαλέσασθαι τοὺς δημάρχους, σκηψάμενον οὐκ ἔχειν τὸ ἴσον ἐν τῇ Ἑλλάδι πρὸς Ἕλληνας, ἐν δὲ Ῥώμῃ πολλὴ μὲν ἐπὶ τῷ λόγῳ περὶ τὰς συνηγορίας αὐτοῦ χάρις ἐξέλαμπε, πολλὴ δὲ τῆς περὶ τὰς δεξιώσεις καὶ ὁμιλίας φιλοφροσύνης εὔνοια παρὰ τῶν δημοτῶν ἀπήντα, θεραπευτικοῦ παρ’ ἡλικίαν ὄντος. ἦν δέ τις καὶ ἀπὸ δείπνων καὶ τραπέζης καὶ ὅλως τῆς περὶ τὴν δίαιταν λαμπρότητος αὐξανομένη κατὰ μικρὸν αὐτῷ δύναμις εἰς τὴν πολιτείαν. ἣν τὸ πρῶτον οἱ φθονοῦντες οἰόμενοι ταχὺ τῶν ἀναλωμάτων ἐπιλιπόντων ἐξίτηλον ἔσεσθαι, περιεώρων ἀνθοῦσαν ἐν τοῖς πολλοῖς· ὀψὲ δὲ ᾔσθοντο, μεγάλης καὶ δυσανατρέπτου γενομένης καὶ βαδιζούσης ἄντικρυς ἐπὶ τὴν τῶν ὅλων μεταβολήν, ὡς οὐδεμίαν ἀρχὴν πράγματος ἡγητέον μικράν, ἣν οὐ ταχὺ ποιεῖ μεγάλην τὸ ἐνδελεχές ἐκ τοῦ καταφρονηθῆναι τὸ μὴ κωλυθῆναι λαβοῦσαν. ὁ γοῦν πρῶτος ὑπιδέσθαι δοκῶν αὐτοῦ καὶ φοβηθῆναι τῆς πολιτείας ὥσπερ θαλάττης τὰ διαγελῶντα καὶ τὴν ἐν τῷ φιλανθρώπῳ καὶ ἱλαρῷ κεκρυμμένην δεινότητα τοῦ ἤθους καταμαθὼν Κικέρων ἔλεγε τοῖς ἄλλοις ἅπασιν ἐπιβουλεύμασιν αὐτοῦ καὶ πολιτεύμασι τυραννικὴν ἐνορᾶν διάνοιαν, ἀλλ’ ὅταν ἔφη, τὴν κόμην οὕτω διακειμένην περιττῶς ἴδω κἀκεῖνον ἑνὶ δακτύλῳ κνώμενον, οὔ μοι δοκεῖ πάλιν οὗτος ἅνθρωπος εἰς νοῦν ἂν ἐμβαλέσθαι τηλικοῦτον κακόν, ἀναίρεσιν τῆς Ῥωμαίων πολιτείας. ταῦτα μὲν οὖν ὕστερον.", "st": "Caes. 4.1"}, {"sp": "N", "t": "τοῦ δὲ δήμου πρώτην μὲν ἀπόδειξιν τῆς πρὸς αὐτόν εὐνοίας ἔλαβεν ὅτε πρὸς Γάϊον Ποπίλιον ἐρίσας ὑπὲρ χιλιαρχίας πρότερος ἀνηγορεύθη δευτέραν δὲ καὶ καταφανεστέραν ὅτε, τῆς Μαρίου γυναικὸς Ἰουλίας ἀποθανούσης, ἀδελφιδοῦς ὢν αὐτῆς ἐγκώμιόν τε λαμπρὸν ἐν ἀγορᾷ διῆλθε, καὶ περὶ τὴν ἐκφορὰν ἐτόλμησεν εἰκόνας Μαρίου προθέσθαι, τότε πρῶτον ὀφθείσας μετὰ τὴν ἐπὶ Σύλλα πολιτείαν, πολεμίων τῶν ἀνδρῶν κριθέντων. ἐπὶ τούτῳ γὰρ ἐνίων καταβοησάντων τοῦ Καίσαρος ὁ δῆμος ἀντήχησε λαμπρῶς, δεξάμενος κρότῳ καὶ θαυμάσας ὥσπερ ἐξ Ἅιδου διὰ χρόνων πολλῶν ἀνάγοντα τὰς Μαρίου τιμὰς εἰς τὴν πόλιν. τὸ μὲν οὖν ἐπὶ γυναιξὶ πρεσβυτέραις λόγους ἐπιταφίους διεξιέναι πάτριον ἦν Ῥωμαίοις, νέαις δὲ οὐκ ὂν ἐν ἔθει πρῶτος εἶπε Καῖσαρ ἐπὶ τῆς ἑαυτοῦ γυναικὸς ἀποθανούσης· καὶ τοῦτο ἤνεγκεν αὐτῷ χάριν τινα καὶ συνεδημαγώγησε τῷ πάθει τοὺς πολλοὺς ὡς ἥμερον ἄνδρα καὶ περίμεστον ἤθους ἀγαπᾶν.", "st": "Caes. 5.1"}, {"sp": "N", "t": "θάψας δὲ τὴν γυναῖκα ταμίας εἰς Ἰβηρίαν ἑνὶ τῶν στρατηγῶν Βέτερι συνεξῆλθεν, ὃν αὐτόν τε τιμῶν ἀεὶ διετέλεσε καὶ τὸν υἱὸν πάλιν αὐτὸς ἄρχων ταμίαν ἐποίησε. γενόμενος δὲ ἀπὸ τῆς ἀρχῆς ἐκείνης τρίτην ἠγάγετο γυναῖκα Πομπηΐαν, ἔχων ἐκ Κορνηλίας θυγατέρα τὴν ὕστερον Πομπηΐῳ Μάγνῳ γαμηθεῖσαν. χρώμενος δὲ ταῖς δαπάναις ἀφειδῶς, καὶ δοκῶν μὲν ἐφήμερον καὶ βραχεῖαν ἀντικαταλλάττεσθαι μεγάλων ἀναλωμάτων δόξαν, ὠνούμενος δὲ ταῖς ἀληθείαις τὰ μέγιστα μικρῶν, λέγεται πρὶν εἰς ἀρχήν τινα καθίστασθαι χιλίων καὶ τριακοσίων γενέσθαι χρεωφειλέτης ταλάντων. ἐπεὶ δὲ τοῦτο μὲν ὁδοῦ τῆς Ἀππίας ἀποδειχθεὶς ἐπιμελητὴς πάμπολλα χρήματα προσανάλωσε τῶν ἑαυτοῦ, τοῦτο δὲ ἀγορανομῶν ζεύγη μονομάχων τριακόσια καὶ εἴκοσι παρέσχε καὶ ταῖς ἄλλαις περί θέατρα καὶ πομπὰς καὶ δεῖπνα χορηγίαις καὶ πολυτελείαις τὰς πρὸ αὐτοῦ κατέκλυσε φιλοτιμίας, οὕτω διέθηκε τὸν δῆμον ὡς καινὰς μὲν ἀρχάς καινὰς δὲ τιμὰς ζητεῖν ἕκαστον, αἷς αὐτόν ἀμείψαιντο.", "st": "Caes. 5.6"}, {"sp": "N", "t": "δυεῖν δὲ οὐσῶν ἐν τῇ πόλει στάσεων, τῆς μὲν ἀπὸ Σύλλα μέγα δυναμένης, τῆς δὲ Μαριανῆς, ἣ τότε κατεπτήχει καὶ διέσπαστο κομιδῇ ταπεινὰ πράττουσα, ταύτην ἀναρρῶσαι καὶ προσαγαγέσθαι βουλόμενος ἐν ταῖς ἀγορανομικαῖς φιλοτιμίαις ἀκμὴν ἐχούσαις εἰκόνας ἐποιήσατο Μαρίου κρύφα καὶ Νίκας τροπαιοφόρους, ἃς φέρων νυκτὸς εἰς τὸ Καπιτώλιον ἀνέστησεν. ἅμα δὲ ἡμέρᾳ τοὺς θεασαμένους μαρμαίροντα πάντα χρυσῷ καὶ τέχνῃ κατεσκευασμένα περιττῶς διεδήλου δὲ γράμμασι τὰ Κιμβρικὰ κατορθώματα θάμβος ἔσχε τῆς τόλμης τοῦ ἀναθέντος (οὐ γὰρ ἦν. ἄδηλος), ταχὺ δὲ περιϊὼν ὁ λόγος ἤθροιζε πάντας ἀνθρώπους πρὸς τὴν ὄψιν· ἀλλ’ οἱ μὲν ἐβόων τυραννίδα πολιτεύεσθαι Καίσαρα, νόμοις καὶ δόγμασι κατορωρυγμένας ἐπανιστάντα τιμάς, καὶ τοῦτο πεῖραν ἐπὶ τὸν δῆμον εἶναι προμαλαττόμενον, εἰ τετιθάσευται ταῖς φιλοτιμίαις ὑπ’ αὐτοῦ καὶ δίδωσι παίζειν τοιαῦτα καὶ καινοτομεῖν, οἱ δὲ Μαριανοὶ παραθαρρύναντες ἀλλήλους πλήθει τε θαυμαστοὶ ὅσοι διεφάνησαν ἐξαίφνης, καὶ κρότῳ κατεῖχον τὸ Καπιτώλιον· πολλοῖς δὲ καὶ δάκρυα τὴν Μαρίου θεωμένοις ὄψιν ὑφ’ ἡδονῆς ἐχώρει, καὶ μέγας ἦν ὁ Καῖσαρ ἐγκωμίοις αἰρόμενος, ὡς ἀντὶ πάντων ἄξιος εἴη ὁ ἀνὴρ τῆς Μαρίου συγγενείας, συναχθείσης δὲ περὶ τούτων τῆς βουλῆς, Κάτλος Λουτάτιος, ἀνὴρ εὐδοκιμῶν τότε μάλιστα Ῥωμαίων, ἀναστὰς καὶ κατηγορήσας Καίσαρος ἐπεφθέγξατο τὸ μνημονευόμενον· οὐκέτι γὰρ ὑπονόμοις, ἔφη, Καῖσαρ, ἀλλ’ ἤδη μηχαναῖς αἱρεῖ τὴν πολιτείαν. ἐπεὶ δὲ ἀπολογησάμενος πρὸς ταῦτα Καῖσαρ ἔπεισε τὴν σύγκλητον, ἔτι μᾶλλον οἱ θαυμάζοντες αὐτὸν ἐπήρθησαν, καὶ παρεκελεύοντο μηδενὶ τοῦ φρονήματος ὑφίεσθαι πάντων γὰρ ἑκόντι τῷ δήμῳ περιέσεσθαι καὶ πρωτεύσειν.", "st": "Caes. 6.1"}, {"sp": "N", "t": "ἐν δὲ τούτῳ καὶ Μετέλλου τοῦ ἀρχιερέως τελευτήσαντος καὶ τὴν ἱερωσύνην περιμάχητον οὖσαν Ἰσαυρικοῦ καὶ Κάτλου μετιόντων, ἐπιφανεστάτων ἀνδρῶν καὶ μέγιστον ἐν βουλῇ δυναμένων, οὐχ ὑπεῖξεν αὐτοῖς ὁ Καῖσαρ, ἀλλὰ καταβὰς εἰς τὸν δῆμον ἀντιπαρήγγελλεν. ἀγχωμάλου δὲ τῆς σπουδῆς φαινομένης, ὁ Κάτλος, ἀπὸ μείζονος ἀξίας μᾶλλον ὀρρωδῶν τὴν ἀδηλότητα, προσέπεμψε πείθων ἀποστῆναι τὸν Καίσαρα τῆς φιλοτιμίας ἐπὶ πολλοῖς χρήμασιν.", "st": "Caes. 7.1"}, {"sp": "N", "t": "ὁ δὲ καὶ πλείω προσδανεισάμενος ἔφη διαγωνιεῖσθαι.τῆς δ’ ἡμέρας ἐνστάσης καὶ τῆς μητρὸς ἐπὶ τὰς θύρας αὐτὸν οὐκ ἀδακρυτὶ προπεμπούσης, ἀσπασάμενος αὐτήν, ὦ μῆτερ, εἶπε, τήμερον ἢ ἀρχιερέα τὸν υἱὸν ἢ φυγάδα ὄψει. διενεχθείσης δὲ τῆς ψήφου καὶ γενομένης ἁμίλλης ἐκράτησε, καὶ παρέσχε τῇ βουλῇ καὶ τοῖς ἀρίστοις φόβον ὡς ἐπὶ πᾶν θρασύτητος προάξων τὸν δῆμον. ὅθεν οἱ περὶ Πείσωνα καὶ Κάτλον ᾐτιῶντο Κικέρωνα φεισάμενον Καίσαρος ἐν τοῖς περὶ Κατιλίναν λαβὴν παρασχόντος. ὁ γὰρ δὴ Κατιλίνας οὐ μόνον τὴν πολιτείαν μεταβαλεῖν, ἀλλ’ ὅλην ἀνελεῖν τὴν ἡγεμονίαν καὶ πάντα τὰ πράγματα συγχέαι διανοηθείς αὐτὸς μὲν ἐξέπεσε, περιπταίσας ἐλάττοσιν ἐλέγχοις πρὸ τοῦ τὰς ἐσχάτας αὐτοῦ βουλὰς ἀποκαλυφθῆναι, Λέντλον δὲ καὶ Κέθηγον ἐν τῇ πόλει διαδόχους ἀπέλιπε τῆς συνωμοσίας, οἷς εἰ μὲν κρύφα παρεῖχέ τι θάρσους καὶ δυνάμεως ὁ Καῖσαρ ἄδηλόν ἐστιν, ἐν δὲ τῇ βουλῇ κατὰ κράτος ἐξελεγχθέντων καὶ Κικέρωνος τοῦ ὑπάτου γνώμας ἐρωτῶντος περὶ κολάσεως ἕκαστον, οἱ μὲν ἄλλοι μέχρι Καίσαρος θανατοῦν ἐκέλευον, ὁ δὲ Καῖσαρ ἀναστὰς λόγον διῆλθε πεφροντισμένον, ὡς ἀποκτεῖναι μὲν ἀκρίτους ἄνδρας ἀξιώματι καὶ γένει λαμπροὺς οὐ δοκεῖ πάτριον οὐδὲ δίκαιον εἶναι, μὴ μετὰ τῆς ἐσχάτης ἀνάγκης, εἰ δὲ φρουροῖντο δεθέντες ἐν πόλεσι τῆς Ἰταλίας ἃς ἂν αὐτὸς ἕληται Κικέρων, μέχρι οὗ καταπολεμηθῇ Κατιλίνας, ὕστερον ἐν εἰρήνῃ καὶ καθ’ ἡσυχίαν περὶ ἑκάστου τῇ βουλῇ γνῶναι παρέξει.", "st": "Caes. 7.3"}, {"sp": "N", "t": "οὕτω δὲ τῆς γνώμης φιλανθρώπου φανείσης καὶ τοῦ λόγου δυνατῶς ἐπ’ αὐτῇ ῥηθέντος οὕ μόνον οἱ μετὰ τοῦτον ἀνιστάμενοι προσετίθεντο, πολλοὶ δὲ καὶ τῶν πρὸ αὐτοῦ τὰς εἰρημένας γνώμας ἀπειπάμενοι πρὸς τὴν ἐκείνου μετέστησαν, ἕως ἐπὶ Κάτωνα τὸ πρᾶγμα καὶ Κάτλον περιῆλθε, τούτων δὲ νεανικῶς ἐναντιωθέντων, Κάτωνος δὲ καὶ τὴν ὑπόνοιαν ἅμα τῷ λόγῳ συνεπερείσαντος αὐτῷ καὶ συγκατεξαναστάντος ἐρρωμένως, οἱ μὲν ἄνδρες ἀποθανούμενοι παρεδόθησαν, Καίσαρι δὲ τῆς βουλῆς ἐξιόντι πολλοὶ τῶν Κικέρωνα φρουρούντων τότε νέων γυμνὰ τὰ ξίφη συνδραμόντες ἐπέσχον. ἀλλὰ Κουρίων τε λέγεται τῇ τηβέννῳ περιβαλὼν ὑπεξαγαγεῖν, αὐτός τε ὁ Κικέρων, ὡς οἱ νεανίσκοι προσέβλεψαν, ἀνανεῦσαι, φοβηθεὶς τὸν δῆμον, ἢ τὸν φόνον ὅλως ἄδικον καὶ παράνομον ἡγούμενος.", "st": "Caes. 8.1"}, {"sp": "N", "t": "τοῦτο μὲν οὖν οὐκ οἶδα ὅπως ὁ Κικέρων, εἴπερ ἦν ἀληθές, ἐν τῷ περὶ τῆς ὑπατείας οὐκ ἔγραψεν αἰτίαν δὲ εἶχεν ὕστερον ὡς ἄριστα τῷ καιρῷ τότε παρασχόντι κατὰ τοῦ Καίσαρος μὴ χρησάμενος, ἀλλ’ ἀποδειλιάσας τὸν δῆμον ὑπερφυῶς περιεχόμενον τοῦ Καίσαρος, ὅς γε καὶ μετ’ ὀλίγας ἡμέρας εἰς τὴν βουλὴν εἰσελθόντος αὐτοῦ καὶ περὶ ὧν ἐν ὑποψίαις ἦν ἀπολογουμένου καὶ περιπίπτοντος θορύβοις πονηροῖς, ἐπειδὴ πλείων τοῦ συνήθους ἐγίγνετο τῇ βουλῇ καθεζομένῃ χρόνος, ἐπῆλθε μετὰ κραυγῆς καὶ περιέστη τὴν σύγκλητον, ἀπαιτῶν τὸν ἄνδρα καὶ κελεύων ἀφεῖναι. διὸ καὶ Κάτων φοβηθεὶς μάλιστα τὸν ἐκ τῶν ἀπόρων νεωτερισμόν, οἳ τοῦ παντὸς ὑπέκκαυμα πλήθους ἦσαν ἐν τῷ Καίσαρι τὰς ἐλπίδας ἔχοντες, ἔπεισε τὴν σύγκλητον ἀπονεῖμαι σιτηρέσιον αὐτοῖς ἔμμηνον, ἐξ οὗ δαπάνης μὲν ἑπτακόσιαι πεντήκοντα μυριάδες ἐνιαύσιοι προσεγίνοντο τοῖς ἄλλοις ἀναλώμασι, τὸν μέντοι μέγαν ἐν τῷ παρόντι φόβον ἔσβεσε περιφανῶς τὸ πολίτευμα τοῦτο, καὶ τὸ πλεῖστον ἀπέρρηξε τῆς Καίσαρος δυνάμεως καὶ διεσκέδασεν ἐν καιρῷ, στρατηγεῖν μέλλοντος καὶ φοβερωτέρου διὰ τὴν ἀρχὴν ὄντος.", "st": "Caes. 8.4"}, {"sp": "N", "t": "οὐ μὴν ἀπέβη τι ταραχῶδες ἀπ’ αὐτῆς, ἀλλὰ καὶ τύχη τις ἄχαρις τῷ Καίσαρι συνηνέχθη περὶ τὸν οἶκον. Πόπλιος Κλώδιος ἦν ἀνὴρ γένει μὲν εὐπατρίδης καὶ πλούτῳ καὶ λόγῳ λαμπρός, ὕβρει δὲ καὶ θρασύτητι τῶν ἐπὶ βδελυρίᾳ περιβοήτων οὐδενὸς δεύτερος. οὗτος ἤρα Πομπηΐας τῆς Καίσαρος γυναικός οὐδὲ αὐτῆς ἀκούσης, ἀλλὰ φυλακαί τε τῆς γυναικωνίτιδος ἀκριβεῖς ἦσαν, ἥ τε μήτηρ τοῦ Καίσαρος Αὐρηλία, γυνὴ σώφρων, περιέπουσα τὴν νύμφην ἀεὶ χαλεπὴν καὶ παρακεκινδυνευμένην αὐτοῖς ἐποίει τὴν ἔντευξιν.", "st": "Caes. 9.1"}, {"sp": "N", "t": "ἔστι δὲ Ῥωμαίοις θεὸς ἣν Ἀγαθὴν ὀνομάζουσιν, ὥσπερ Ἕλληνες Γυναικείαν. καὶ Φρύγες μὲν οἰκειούμενοι Μίδα μητέρα τοῦ βασιλέως γενέσθαι φασί, Ῥωμαῖοι δὲ νύμφην δρυάδα Φαύνῳ συνοικήσασαν, Ἕλληνες δὲ τῶν Διονύσου μητέρων τὴν ἄρρητον. ὅθεν ἀμπελίνοις τε τὰς σκηνὰς κλήμασιν ἑορτάζουσαι κατερέφουσι, καὶ δράκων ἱερὸς παρακαθίδρυται τῇ θεῷ κατὰ τὸν μῦθον. ἄνδρα δὲ προσελθεῖν οὐ θέμις οὐδ’ ἐπὶ τῆς οἰκίας γενέσθαι τῶν ἱερῶν ὀργιαζομένων αὐταὶ δὲ καθ’ ἑαυτὰς αἱ γυναῖκες πολλὰ τοῖς Ὀρφικοῖς ὁμολογοῦντα δρᾶν λέγονται περὶ τὴν ἱερουργίαν. ὅταν οὖν ὁ τῆς ἑορτῆς καθήκῃ χρόνος, ὑπατεύοντος ἢ στρατηγοῦντος ἀνδρός, αὐτὸς μὲν ἐξίσταται καὶ πᾶν τὸ ἄρρεν, ἡ δὲ γυνὴ τὴν οἰκίαν παραλαβοῦσα διακοσμεῖ, καὶ τὰ μέγιστα νύκτωρ τελεῖται, παιδιᾶς ἀναμεμιγμένης ταῖς παννυχίσι καὶ μουσικῆς ἅμα πολλῆς παρούσης.", "st": "Caes. 9.4"}, {"sp": "N", "t": "ταύτην τότε τὴν ἑορτὴν τῆς Πομπηΐας ἐπιτελούσης, ὁ Κλώδιος οὔπω γενειῶν καὶ διὰ τοῦτο λήσειν οἰόμενος ἐσθῆτα καὶ σκευὴν ψαλτρίας ἀναλαβὼν ἐχώρει, νέᾳ γυναικὶ τὴν ὄψιν ἐοικώς. καὶ ταῖς θύραις ἐπιτυχὼν ἀνεῳγμέναις εἰσήχθη μὲν ἀδεῶς ὑπὸ τῆς συνειδυίας θεραπαινίδος, ἐκείνης δὲ προδραμούσης ὡς τῇ Πομπηΐᾳ φράσειε, καὶ γενομένης διατριβῆς, περιμένειν μὲν ὅπου κατελείφθη τῷ Κλωδίῳ μὴ καρτεροῦντι, πλανωμένῳ δ’ ἐν οἰκίᾳ μεγάλῃ καὶ περιφεύγοντι τὰ φῶτα προσπεσοῦσα τῆς Αὐρηλίας ἀκόλουθος ὡς δὴ γυνὴ γυναῖκα παίζειν προὐκαλεῖτο, καὶ μὴ βουλόμενον εἰς τὸ μέσον εἷλκε, καὶ τίς ἐστι καὶ πόθεν ἐπυνθάνετο. τοῦ δὲ Κλωδίου φήσαντος Ἅβραν περιμένειν Πομπηΐας, αὐτὸ τοῦτο καλουμένην, καὶ τῇ φωνῇ γενομένου καταφανοῦς, ἡ μὲν ἀκόλουθος εὐθὺς ἀπεπήδησε κραυγῇ πρὸς τὰ φῶτα καὶ τὸν ὄχλον, ἄνδρα πεφωρακέναι βοῶσα, τῶν δὲ γυναικῶν διαπτοηθεισῶν ἡ Αὐρηλία τὰ μὲν ὄργια τῆς θεοῦ κατέπαυσε καὶ συνεκάλυψεν, αὐτὴ δὲ τὰς θύρας ἀποκλεῖσαι κελεύσασα περιῄει τὴν οἰκίαν ὑπὸ λαμπάδων, ζητοῦσα τὸν Κλώδιον. εὑρίσκεται δ’ εἰς οἴκημα παιδίσκης ᾗ συνεισῆλθε καταπεφευγώς καὶ γενόμενος φανερὸς ὑπὸ τῶν γυναικῶν ἐξελαύνεται διὰ τῶν θυρῶν, τὸ δὲ πρᾶγμα καὶ νυκτὸς εὐθὺς αἱ γυναῖκες ἀπιοῦσαι τοῖς αὑτῶν ἔφραζον ἀνδράσι, καὶ μεθ’ ἡμέραν ἐχώρει διὰ τῆς πόλεως λόγος ὡς ἀθέσμοις ἐπικεχειρηκότος τοῦ Κλώδιον καὶ δίκην οὐ τοῖς ὑβρισμένοις μόνον, ἀλλὰ καὶ τῇ πόλει καὶ τοῖς θεοῖς ὀφείλοντος. ἐγράψατο μὲν οὖν τὸν Κλώδιον εἷς τῶν δημάρχων ἀσεβείας, καὶ συνέστησαν ἐπ’ αὐτὸν οἱ δυνατώτατοι τῶν ἀπὸ τῆς βουλῆς, ἄλλας τε δεινὰς ἀσελγείας καταμαρτυροῦντες καὶ μοιχείαν ἀδελφῆς, ἣ Λευκούλλῳ συνῳκήκει. πρὸς δὲ τὰς τούτων σπουδὰς ὁ δῆμος ἀντιτάξας ἑαυτὸν ἤμυνε τῷ Κλωδίῳ, καὶ μέγα πρὸς τοὺς δικαστὰς ὄφελος ἦν ἐκπεπληγμένους καὶ δεδοικότας τὸ πλῆθος. ὁ δὲ Καῖσαρ ἀπεπέμψατο μὲν εὐθὺς τὴν Πομπηΐαν, μάρτυς δὲ πρὸς τὴν δίκην κληθείς οὐδὲν ἔφη τῶν λεγομένων κατὰ τοῦ Κλωδίου γιγνώσκειν. ὡς δὲ τοῦ λόγου παραδόξου φανέντος ὁ κατήγορος ἠρώτησε, πῶς οὖν ἀπεπέμψω τὴν γυναῖκα; ὅτι, ἔφη, τὴν ἐμὴν ἠξίουν μηδὲ ὑπονοηθῆναι.", "st": "Caes. 10.1"}, {"sp": "N", "t": "ταῦτα οἱ μὲν οὕτω φρονοῦντα τὸν Καίσαρα λέγουσιν εἰπεῖν, οἱ δὲ τῷ δήμῳ χαριζόμενον ὡρμημένῳ σῴζειν τὸν Κλώδιον. ἀποφεύγει δ’ οὖν τὸ ἔγκλημα τῶν πλείστων δικαστῶν συγκεχυμένοις τοῖς γράμμασι τὰς γνώμας ἀποδόντων, ὅπως μήτε παρακινδυνεύσωσιν ἐν τοῖς πολλοῖς καταψηφισάμενοι μήτε ἀπολύσαντες ἀδοξήσωσι παρὰ τοῖς ἀρίστοις.", "st": "Caes. 10.10"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ εὐθὺς ἀπὸ τῆς στρατηγίας τῶν ἐπαρχιῶν τὴν Ἰβηρίαν λαβών, ὡς ἦν δυσδιάθετον αὐτῷ τὸ περὶ τοὺς δανειστάς ἐνοχλοῦντας ἐξιόντι καὶ καταβοῶντας, ἐπὶ Κράσσον κατέφυγε πλουσιώτατον ὄντα Ῥωμαίων, δεόμενον δὲ τῆς Καίσαρος ἀκμῆς καὶ θερμότητος ἐπὶ τὴν πρὸς Πομπήϊον ἀντιπολιτείαν. ἀναδεξαμένου δὲ τοῦ Κράσσου τοὺς μάλιστα χαλεποὺς καὶ ἀπαραιτήτους τῶν δανειστῶν καὶ διεγγυήσαντος ὀκτακοσίων καὶ τριάκοντα ταλάντων, οὕτως ἐξῆλθεν ἐπὶ τὴν ἐπαρχίαν.", "st": "Caes. 10.11"}, {"sp": "N", "t": "λέγεται δέ, τὰς Ἄλπεις ὑπερβάλλοντος αὐτοῦ καὶ πολίχνιόν τι βαρβαρικόν οἰκούμενον ὑπὸ ἀνθρώπων παντάπασιν ὀλίγων καὶ λυπρόν παρερχομένου, τοὺς ἑταίρους ἅμα γέλωτι καὶ μετὰ παιδιᾶς ἦ που φάναι κἀνταῦθά τινές εἰσιν ὑπὲρ ἀρχῶν φιλοτιμίαι καὶ περὶ πρωτείων ἅμιλλαι καὶ φθόνοι τῶν δυνατῶν πρὸς ἀλλήλους; τὸν δὲ Καίσαρα σπουδάσαντα πρὸς αὐτοὺς εἰπεῖν, ἐγὼ μὲν ἐβουλόμην παρὰ τούτοις εἶναι μᾶλλον πρῶτος ἢ παρὰ Ῥωμαίοις δεύτερος. ὁμοίως δὲ πάλιν ἐν Ἰβηρίᾳ, σχολῆς οὔσης ἀναγινώσκοντά τι τῶν περὶ Ἀλεξάνδρου γεγραμμένων σφόδρα γενέσθαι πρὸς ἑαυτῷ πολὺν χρόνον, εἶτα καὶ δακρῦσαι· τῶν δὲ φίλων θαυμασάντων τὴν αἰτίαν εἰπεῖν οὐ δοκεῖ ὑμῖν ἄξιον εἶναι λύπης, εἰ τηλικοῦτος μὲν ὢν Ἀλέξανδρος ἤδη τοσούτων ἐβασίλευεν, ἐμοὶ δὲ λαμπρὸν οὐδὲν οὔπω πέπρακται;", "st": "Caes. 11"}, {"sp": "N", "t": "τῆς γοῦν Ἰβηρίας ἐπιβὰς εὐθὺς ἦν ἐνεργός, ὥσθ’ ἡμέραις ὀλίγαις δέκα σπείρας συναγαγεῖν πρὸς ταῖς πρότερον οὔσαις εἴκοσι, καὶ στρατεύσας ἐπὶ Καλαϊκοὺς καὶ Λυσιτανοὺς κρατῆσαι καὶ προελθεῖν ἄχρι Τῆς ἔξω θαλάσσης τὰ μὴ πρότερον ὑπακούοντα Ῥωμαίοις ἔθνη καταστρεφόμενος. θέμενος δὲ τὰ τοῦ πολέμου καλῶς, οὐ χεῖρον ἐβράβευε τὰ Τῆς εἰρήνης, ὁμόνοιάν τε ταῖς πόλεσι καθιστὰς, καὶ μάλιστα τὰς τῶν χρεωφειλετῶν καὶ δανειστῶν ἰώμενος διαφοράς. ἔταξε γὰρ τῶν προσιόντων τοῖς ὀφείλουσι καθ’ ἕκαστον ἐνιαυτὸν δύο μὲν μέρη τὸν δανειστὴν ἀναιρεῖσθαι, τῷ δὲ λοιπῷ χρῆσθαι τὸν δεσπότην, ἄχρι ἂν οὕτως ἐκλυθῇ τὸ δάνειον. ἐπὶ τούτοις εὐδοκιμῶν ἀπηλλάγη Τῆς ἐπαρχίας, αὐτός τε πλούσιος γεγονὼς καὶ τοὺς στρατιώτας ὠφεληκὼς ἀπὸ τῶν στρατειῶν, καὶ προσηγορευμένος αὐτοκράτωρ ὑπ’ αὐτῶν.", "st": "Caes. 12.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τοὺς μὲν μνωμένους θρίαμβον ἔξω διατρίβειν ἔδει, τοὺς δὲ μετιόντας ὑπατείαν παρόντας ἐν τῇ πόλει τοῦτο πράττειν, ἐν τοιαύτῃ γεγονὼς ἀντινομίᾳ καὶ πρὸς αὐτὰς τὰς ὑπατικὰς ἀφιγμένος ἀρχαιρεσίας ἔπεμψε πρὸς τὴν σύγκλητον αἰτούμενος αὐτῷ δοθῆναι παραγγέλλειν εἰς ὑπατείαν ἀπόντι διὰ τῶν φίλων. Κάτωνος δὲ πρῶτον μὲν ἰσχυριζομένου τῷ νόμῳ πρὸς τὴν ἀξίωσιν, εἶτα, ὡς ἑώρα πολλοὺς τεθεραπευμένους ὑπὸ τοῦ Καίσαρος, ἐκκρούσαντος τῷ χρόνῳ τὸ πρᾶγμα καὶ τὴν ἡμέραν ἐν τῷ λέγειν κατατρίψαντος, ἔγνω τὸν θρίαμβον ἀφεὶς ὁ Καῖσαρ ἔχεσθαι τῆς ὑπατείας. καὶ παρελθὼν εὐθὺς ὑποδύεται πολίτευμά τι πάντας ἀνθρώπους ἐξαπατῆσαν πλὴν Κάτωνος, ἦν δὲ τοῦτο διαλλαγὴ Πομπηΐου καὶ Κράσσου τῶν μέγιστον ἐν τῇ πόλει δυναμένων οὓς συναγαγὼν ὁ Καῖσαρ εἰς φιλίαν ἐκ διαφορᾶς, καὶ τὴν ἀπ’ ἀμφοῖν συνενεγκάμενος ἰσχὺν εἰς ἑαυτόν, ἔργῳ φιλάνθρωπον ἔχοντι προσηγορίαν ἔλαθε μεταστήσας τὴν πολιτείαν. οὐ γάρ, ὡς οἱ πλεῖστοι νομίζουσιν, ἡ Καίσαρος καὶ Πομπηΐου διαφορὰ τοὺς ἐμφυλίους ἀπειργάσατο πολέμους, ἀλλὰ μᾶλλον ἡ φιλία, συστάντων ἐπὶ καταλύσει τῆς ἀριστοκρατίας τὸ πρῶτον, εἶτα οὕτως καὶ πρὸς ἀλλήλους διαστάντων. Κάτωνι δὲ πολλάκις τὰ μέλλοντα προθεσπίζοντι περιῆν δυσκόλου μὲν ἀνθρώπου τότε καὶ πολυπράγμονος, ὕστερον δὲ φρονίμου μέν, οὐκ εὐτυχοῦς δὲ συμβούλου λαβεῖν δόξαν.", "st": "Caes. 13.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ὁ Καῖσαρ ἐν μέσῳ τῆς Κράσσου καὶ Πομπηΐου φιλίας δορυφορούμενος ἐπὶ τὴν ὑπατείαν κατήχθη· καὶ λαμπρῶς ἀναγορευθεὶς μετὰ Καλπουρνίου Βύβλου καὶ καταστὰς εἰς τὴν ἀρχήν εὐθὺς εἰσέφερε νόμους οὐχ ὑπάτῳ προσήκοντας, ἀλλὰ δημάρχῳ τινὶ θρασυτάτῳ, πρὸς ἡδονὴν τῶν πολλῶν κληρουχίας τινὰς χώρας καὶ διανομὰς εἰσηγούμενος. ἐν δὲ τῇ βουλῇ τῶν καλῶν τε καὶ ἀγαθῶν ἀντικρουσάντων, πάλαι δεόμενος προφάσεως, ἀνακραγὼν καὶ μαρτυράμενος ὡς εἰς τὸν δῆμον ἄκων ἐξελαύνοιτο θεραπεύσων ἐκεῖνον ἐξ ἀνάγκης ὕβρει καὶ χαλεπότητι τῆς βουλῆς, πρὸς αὐτὸν ἐξεπήδησε καὶ περιστησάμενος ἔνθεν μὲν Κράσσον, ἔνθεν δὲ Πομπήϊον, ἠρώτησεν εἰ τοὺς νόμους ἐπαινοῖεν. ἐπαινεῖν δὲ φασκόντων, παρεκάλει βοηθεῖν ἐπὶ τοὺς ἐνίστασθαι μετὰ ξιφῶν ἀπειλοῦντας. ἐκεῖνοι δὲ ὑπισχνοῦντο Πομπήϊος δὲ καὶ προσεπεῖπεν ὡς ἀφίξοιτο πρὸς τὰ ξίφη μετὰ τοῦ ξίφους καὶ θυρεὸν κομίζων, ἐπὶ τούτῳ τοὺς μὲν ἀριστοκρατικοὺς ἠνίασεν, οὐκ ἀξίαν τῆς περὶ αὐτὸν αἰδοῦς, οὐδὲ τῆς πρὸς τὴν σύγκλητον εὐλαβείας πρέπουσαν, ἀλλὰ μανικὴν καὶ μειρακιώδη φωνὴν ἀκούσαντας, ὁ δὲ δῆμος ἥσθη.", "st": "Caes. 14.1"}, {"sp": "N", "t": "Καῖσαρ δὲ μειζόνως ἔτι τῆς Πομπηΐου δυνάμεως ὑποδραττόμενος, ἦν γὰρ αὐτῷ Ἰουλία θυγάτηρ ἐγγεγυημένη Σερουϊλίῳ Καιπίωνι, ταύτην ἐνεγγύησε Πομπηΐῳ, τὴν δὲ Πομπηΐου τῷ Σερουϊλίῳ δώσειν ἔφησεν, οὐδὲ αὐτὴν ἀνέγγυον οὖσαν, ἀλλὰ Φαύστῳ τῷ Σύλλα παιδὶ καθωμολογημένην. ὀλίγῳ δὲ ὕστερον Καῖσαρ ἠγάγετο Καλπουρνίαν θυγατέρα Πείσωνος, τὸν δὲ Πείσωνα κατέστησεν ὕπατον εἰς τὸ μέλλον, ἐνταῦθα δὴ καὶ σφόδρα μαρτυρομένου Κάτωνος καὶ βοῶντος οὐκ ἀνεκτὸν εἶναι, γάμοις διαμαστροπευομένης τῆς ἡγεμονίας καὶ διὰ γυναίων εἰς ἐπαρχίας καὶ στρατεύματα καὶ δυνάμεις ἀλλήλους ἀντεισαγόντων.", "st": "Caes. 14.7"}, {"sp": "N", "t": "ὁ μὲν οὖν συνάρχων τοῦ Καίσαρος Βύβλος, ἐπεὶ κωλύων τοὺς νόμους οὐδὲν ἐπέραινεν, ἀλλὰ πολλάκις ἐκινδύνευε μετὰ Κάτωνος ἐπὶ τῆς ἀγορᾶς ἀποθανεῖν, ἐγκλεισάμενος οἴκοι τὸν τῆς ἀρχῆς χρόνον διετέλεσε. Πομπήϊος δὲ γήμας εὐθὺς ἐνέπλησε τὴν ἀγορὰν ὅπλων καὶ συνεπεκύρου τῷ δήμῳ τοὺς νόμους, Καίσαρι δὲ τὴν ἐντὸς Ἄλπεων καὶ τὴν ἐκτὸς ἅπασαν Κελτικήν, προσθεὶς τὸ Ἰλλυρικόν μετὰ ταγμάτων τεσσάρων εἰς πενταετίαν. Κάτωνα μὲν οὖν ἐπιχειρήσαντα τούτοις ἀντιλέγειν ἀπῆγεν εἰς φυλακὴν ὁ Καῖσαρ, οἰόμενος αὐτὸν ἐπικαλέσεσθαι τοὺς δημάρχους· ἐκείνου δὲ ἀφώνου βαδίζοντος ὁρῶν ὁ Καῖσαρ οὐ μόνον τοὺς κρατίστους δυσφοροῦντας, ἀλλὰ καὶ τὸ δημοτικὸν αἰδοῖ τῆς Κάτωνος ἀρετῆς σιωπῇ καὶ μετὰ κατηφείας ἑπόμενον, αὐτὸς ἐδεήθη κρύφα τῶν δημάρχων ἑνὸς ἀφελέσθαι τὸν Κάτωνα.", "st": "Caes. 14.9"}, {"sp": "N", "t": "τῶν δὲ ἄλλων συγκλητικῶν ὀλίγοι παντάπασιν αὐτῷ συνῄεσαν εἰς βουλήν, οἱ δὲ λοιποὶ δυσχεραίνοντες ἐκποδὼν ἦσαν. εἰπόντος δὲ Κονσιδίου τινὸς τῶν σφόδρα γερόντων ὡς φοβούμενοι τὰ ὅπλα καὶ τοὺς στρατιώτας οὐ συνέρχοιντο, τί οὖν ἔφη ὁ Καῖσαρ, οὐ καὶ σὺ ταῦτα δεδιὼς οἰκουρεῖς; καὶ ὁ Κονσίδιος εἶπεν ὅτι με ποιεῖ μὴ φοβεῖσθαι τὸ γῆρας· ὁ γὰρ ἔτι λειπόμενος βίος οὐ πολλῆς ὀλίγος ὢν δεῖται προνοίας. αἴσχιστον δὲ τῶν τότε πολιτευμάτων ἔδοξεν ἐν τῇ Καίσαρος ὑπατείᾳ δήμαρχον αἱρεθῆναι Κλώδιον ἐκεῖνον, ὑφ’ οὗ τὰ περὶ τὸν γάμον καὶ τὰς ἀπορρήτους παρενομήθη παννυχίδας. ᾑρέθη δὲ ἐπὶ τῇ Κικέρωνος καταλύσει· καὶ Καῖσαρ οὐ πρότερον ἐξῆλθεν ἐπὶ τὴν στρατιάν ἢ καταστασιάσαι Κικέρωνα μετὰ Κλωδίου καὶ συνεκβαλεῖν ἐκ τῆς Ἰταλίας.", "st": "Caes. 14.13"}, {"sp": "N", "t": "τοιαῦτα μὲν οὖν λέγεται γενέσθαι τὰ πρὸ τῶν Γαλατικῶν. ὁ δὲ τῶν πολέμων οὓς ἐπολέμησε μετὰ ταῦτα, καὶ τῶν στρατειῶν αἷς ἡμερώσατο τὴν Κελτικὴν, χρόνος, ὥσπερ ἄλλην ἀρχὴν λαβόντος αὐτοῦ καὶ καταστάντος εἰς ἑτέραν τινὰ βίου καὶ πραγμάτων καινῶν ὁδόν, οὐκ ἔστιν ὅτου τῶν μάλιστα τεθαυμασμένων ἐφ’ ἡγεμονίᾳ καὶ μεγίστων γεγονότων ἀπολείποντα πολεμιστὴν καὶ στρατηλάτην ἀπέδειξεν αὐτόν, ἀλλ’ εἴτε Φαβίους καὶ Σκηπίωνας καὶ Μετέλλους καὶ τοὺς κατ’ αὐτὸν ἢ μικρὸν ἔμπροσθεν αὐτοῦ, Σύλλαν καὶ Μάριον ἀμφοτέρους τε Λευκούλλους ἢ καὶ Πομπήϊον αὐτόν, οὗ κλέος ὑπουράνιον ἤνθει τότε παντοίας περὶ πόλεμον ἀρετῆς, παραβάλοι τις, αἱ Καίσαρος ὑπερβάλλουσι πράξεις τὸν μὲν χαλεπότητι τόπων ἐν οἷς ἐπολέμησε, τὸν δὲ μεγέθει χώρας ἣν προσεκτήσατο, τὸν δὲ πλήθει καὶ βίᾳ πολεμίων οὓς ἐνίκησε, τὸν δὲ ἀτοπίαις καὶ ἀπιστίαις ἠθῶν ἃ καθωμίλησε, τὸν δὲ ἐπιεικείᾳ καὶ πρᾳότητι πρὸς τοὺς ἁλισκομένους, τὸν δὲ δώροις καὶ χάρισι πρὸς τοὺς συστρατευομένους, πάντας δὲ τῷ πλείστας μεμαχῆσθαι μάχας καὶ πλείστους ἀνῃρηκέναι τῶν ἀντιταχθέντων. ἔτη γὰρ οὐδὲ δέκα πολεμήσας περὶ Γαλατίαν πόλεις μὲν ὑπὲρ ὀκτακοσίας κατὰ κράτος εἷλεν, ἔθνη δὲ ἐχειρώσατο τριακόσια, μυριάσι δὲ παραταξάμενος κατὰ μέρος τριακοσίαις ἑκατὸν μὲν ἐν χερσὶ διέφθειρεν, ἄλλας δὲ τοσαύτας ἐζώγρησεν.", "st": "Caes. 15.1"}, {"sp": "N", "t": "εὐνοίᾳ δὲ καὶ προθυμίᾳ στρατιωτῶν ἐχρήσατο τοσαύτῃ περὶ αὑτόν ὥστε τοὺς ἑτέρων μηδὲν ἐν ταῖς ἄλλαις στρατείαις διαφέροντας ἀμάχους καὶ ἀνυποστάτους φέρεσθαι πρὸς πᾶν δεινὸν ὑπὲρ τῆς Καίσαρος δόξης, οἷος ἦν τοῦτο μὲν Ἀκίλιος, ὃς ἐν τῇ περὶ Μασσαλίαν ναυμαχίᾳ νεὼς πολεμίας ἐπιβεβηκώς τὴν μὲν δεξιὰν ἀπεκόπη χεῖρα μαχαίρᾳ, τῇ δὲ ἑτέρα τὸν θυρεὸν οὐκ ἀφῆκεν, ἀλλὰ τύπτων εἰς τὰ πρόσωπα τοὺς πολεμίους ἀπέστρεψε πάντας καὶ τοῦ σκάφους ἐπεκράτησε· τοῦτο δὲ Κάσσιος Σκεύας, ὃς ἐν τῇ περὶ Δυρράχιον μάχῃ τὸν ὀφθαλμὸν ἐκκοπεὶς τοξεύματι, τὸν δὲ ὦμον ὑσσῷ καὶ τὸν μηρὸν ἑτέρῳ διεληλαμένος, τῷ δὲ θυρεῷ βελῶν ἑκατὸν καὶ τριάκοντα πληγὰς ἀναδεδεγμένος, ἐκάλει τοὺς πολεμίους ὡς παραδώσων ἑαυτόν. δυεῖν δὲ προσιόντων, τοῦ μὲν ἀπέκοψε τὸν ὦμον τῇ μαχαίρᾳ, τὸν δὲ κατὰ τοῦ προσώπου πατάξας ἀπέστρεψεν, αὐτὸς δὲ διεσώθη τῶν οἰκείων περισχόντων. ἐν δὲ Βρεττανίᾳ τῶν πολεμίων εἰς τόπον ἑλώδη καὶ μεστὸν ὑδάτων ἐμπεσοῦσι τοῖς πρώτοις ταξιάρχοις ἐπιθεμένων στρατιώτης, Καίσαρος αὐτοῦ τὴν μάχην ἐφορῶντος, ὠσάμενος εἰς μέσους καὶ πολλὰ καὶ περίοπτα τόλμης ἀποδειξάμενος ἔργα τοὺς μὲν ταξιάρχους ἔσωσε, τῶν βαρβάρων φυγόντων, αὐτὸς δὲ χαλεπῶς ἐπὶ πᾶσι διαβαίνων ἔρριψεν ἑαυτὸν εἰς ῥεύματα τελματώδη, καὶ μόλις ἄνευ τοῦ θυρεοῦ, τὰ μὲν νηχόμενος, τὰ δὲ βαδίζων, διεπέρασε. θαυμαζόντων δὲ τῶν περὶ τὸν Καίσαρα καὶ μετὰ χαρᾶς καὶ κραυγῆς ἀπαντώντων, αὐτὸς εὖ μάλα κατηφὴς καὶ δεδακρυμένος προσέπεσε τῷ Καίσαρι, συγγνώμην αἰτούμενος ἐπὶ τῷ προέσθαι τὸν θυρεόν. ἐν δὲ Λιβύῃ ναῦν ἑλόντες οἱ περὶ Σκηπίωνα Καίσαρος, ἐν ᾗ Γράνιος Πέτρων ἐπέπλει ταμίας ἀποδεδειγμένος, τοὺς μὲν ἄλλους ἐποιοῦντο λείαν, τῷ δὲ ταμίᾳ διδόναι τὴν σωτηρίαν ἔφασαν, ὁ δὲ εἰπών ὅτι τοῖς Καίσαρος στρατιώταις οὐ λαμβάνειν, ἀλλὰ διδόναι σωτηρίαν ἔθος ἐστίν, ἑαυτὸν τῷ ξίφει πατάξας ἀνεῖλε.", "st": "Caes. 16.1"}, {"sp": "N", "t": "τὰ δὲ τοιαῦτα λήματα καὶ τὰς φιλοτιμίας αὐτός ἀνέθρεψε καὶ κατεσκεύασε Καῖσαρ, πρῶτον μὲν τῷ χαρίζεσθαι καὶ τιμᾶν ἀφειδῶς ἐνδεικνύμενος ὅτι τὸν πλοῦτον οὐκ εἰς τρυφὴν ἰδίαν οὐδέ τινας ἡδυπαθείας ἐκ τῶν πολέμων ἀθροίζει, κοινὰ δὲ ἆθλα τῆς ἀνδραγαθίας παρ’ αὐτῷ φυλασσόμενα ἀπόκειται, καὶ μέτεστιν ἐκείνῳ τοῦ πλουτεῖν ὅσα τοῖς ἀξίοις τῶν στρατιωτῶν δίδωσιν ἔπειτα τῷ πάντα μὲν κίνδυνον ἑκὼν ὑφίστασθαι, πρὸς μηδένα δὲ τῶν πόνων ἀπαγορεύειν. τὸ μὲν οὖν φιλοκίνδυνον οὐκ ἐθαύμαζον αὐτοῦ διά τὴν φιλοτιμίαν ἡ δὲ τῶν πόνων ὑπομονὴ παρὰ τὴν τοῦ σώματος δύναμιν ἐγκαρτερεῖν δοκοῦντος ἐξέπληττεν, ὅτι καὶ τὴν ἕξιν ὢν ἰσχνός καὶ τὴν σάρκα λευκὸς καὶ ἁπαλός καὶ τὴν κεφαλὴν νοσώδης καὶ τοῖς ἐπὶ τοῖς ἐπιληπτικοῖς ἔνοχος, ἐν Κορδύβῃ πρῶτον αὐτῷ τοῦ πάθους, ὡς λέγεται, τούτου προσπεσόντος, οὐ μαλακίας ἐποιήσατο τὴν ἀρρωστίαν πρόφασιν, ἀλλὰ θεραπείαν τῆς ἀρρωστίας τὴν στρατείαν, ταῖς ἀτρύτοις ὁδοιπορίαις καὶ ταῖς εὐτελέσι διαίταις καὶ τῷ θυραυλεῖν ἐνδελεχῶς καὶ ταλαιπωρεῖν ἀπομαχόμενος τῷ πάθει καὶ τὸ σῶμα τηρῶν δυσάλωτον. ἐκοιμᾶτο μέν γε τοὺς πλείστους ὕπνους ἐν ὀχήμασιν ἢ φορείοις, εἰς πρᾶξιν τὴν ἀνάπαυσιν κατατιθέμενος, ὠχεῖτο δὲ μεθ’ ἡμέραν ἐπὶ τὰ φρούρια καὶ τὰς πόλεις καὶ τοὺς χάρακας, ἑνὸς αὐτῷ συγκαθημένου παιδὸς τῶν ὑπογράφειν ἅμα διώκοντος εἰθισμένων, ἑνὸς δ’ ἐξόπισθεν ἐφεστηκότος στρατιώτου ξίφος ἔχοντος. συντόνως δὲ ἤλαυνεν οὕτως ὥστε τὴν πρώτην ἔξοδον ἀπὸ Ῥώμης ποιησάμενος ὀγδοαῖος ἐπὶ τὸν Ῥοδανὸν ἐλθεῖν.", "st": "Caes. 17.1"}, {"sp": "N", "t": "τὸ μὲν οὖν ἱππεύειν ἐκ παιδὸς ἦν αὐτῷ ῥᾴδιον εἴθιστο γὰρ εἰς τοὐπίσω τὰς χεῖρας ἀπάγων καὶ τῷ νώτῳ περιπλέκων ἀνὰ κράτος ἐλαύνειν τὸν ἵππον. ἐν ἐκείνῃ δὲ τῇ στρατείᾳ προσεξήσκησεν ἱππαζόμενος τὰς ἐπιστολὰς ὑπαγορεύειν καὶ δυσὶν ὁμοῦ γράφουσιν ἐξαρκεῖν, ὡς δὲ Ὄππιός φησι, καὶ πλείοσι. λέγεται δὲ καὶ τὸ διά γραμμάτων τοῖς φίλοις ὁμιλεῖν Καίσαρα πρῶτον μηχανήσασθαι, τὴν κατὰ πρόσωπον ἔντευξιν ὑπὲρ τῶν ἐπειγόντων τοῦ καιροῦ διά τε πλῆθος ἀσχολιῶν καὶ τῆς πόλεως τὸ μέγεθος μὴ περιμένοντος. τῆς δὲ περὶ τὴν δίαιταν εὐκολίας κἀκεῖνο ποιοῦνται σημεῖον, ὅτι τοῦ δειπνίζοντος αὐτὸν ἐν Μεδιολάνῳ ξένου Οὐαλλερίου Λέοντος παραθέντος ἀσπάραγον καὶ μύρον ἀντ’ ἐλαίου καταχέαντος, αὐτὸς μὲν ἀφελῶς ἔφαγε, τοῖς δὲ φίλοις δυσχεραίνουσιν ἐπέπληξεν. ἤρκει γὰρ, ἔφη, τὸ μὴ χρῆσθαι τοῖς ἀπαρέσκουσιν ὁ δὲ τὴν τοιαύτην ἀγροικίαν ἐξελέγχων αὐτός ἐστιν ἄγροικος. ἐν ὁδῷ δέ ποτε συνελασθεὶς ὑπὸ χειμῶνος εἰς ἔπαυλιν ἀνθρώπου πένητος, ὡς οὐδὲν εὗρε πλέον οἰκήματος ἑνὸς γλίσχρως ἕνα δέξασθαι δυναμένου, πρὸς τοὺς φίλους εἰπών ὡς τῶν μὲν ἐντίμων παραχωρητέον εἴη τοῖς κρατίστοις, τῶν δὲ ἀναγκαίων τοῖς ἀσθενεστάτοις, Ὄππιον ἐκέλευσεν ἀναπαύσασθαι· αὐτὸς δὲ μετὰ τῶν ἄλλων ὑπὸ τῷ προστεγίῳ τῆς θύρας ἐκάθευδεν.", "st": "Caes. 17.6"}, {"sp": "N", "t": "ἀλλὰ γὰρ ὁ μὲν πρῶτος αὐτῷ τῶν Κελτικῶν πολέμων πρός Ἑλβηττίους συνέστη καὶ Τιγυρίνους, οἳ τὰς αὑτῶν δώδεκα πόλεις καὶ κώμας τετρακοσίας ἐμπρήσαντες ἐχώρουν πρόσω διὰ τῆς ὑπὸ Ῥωμαίους Γαλατίας, ὥσπερ πάλαι Κίμβροι καὶ Τεύτονες, οὔτε τόλμαν ἐκείνων ὑποδεέστεροι δοκοῦντες εἶναι καὶ πλῆθος ὁμαλῶς τριάκοντα μὲν αἱ πᾶσαι μυριάδες ὄντες, εἴκοσι δὲ αἱ μαχόμεναι μιᾶς δέουσαι. τούτων Τιγυρίνους μὲν οὐκ αὐτός, ἀλλὰ Λαβιηνὸς πεμφθεὶς ὑπ’ αὐτοῦ περὶ τὸν Ἄραρα ποταμὸν συνέτριψεν, Ἑλβηττίων δὲ αὐτῷ πρός τινα πόλιν φίλην ἄγοντι τὴν στρατιὰν καθ’ ὁδὸν ἀπροσδοκήτως ἐπιθεμένων φθάσας ἐπὶ χωρίον καρτερὸν κατέφυγε, κἀκεῖ συναγαγὼν καὶ παρατάξας τὴν δύναμιν, ὡς ἵππος αὐτῷ προσήχθη, τούτῳ μὲν, ἔφη, νικήσας χρήσομαι πρός τὴν δίωξιν, νῦν δὲ ἴωμεν ἐπὶ τοὺς πολεμίους, καὶ πεζὸς ὁρμήσας ἐνέβαλε. χρόνῳ δὲ καὶ χαλεπῶς ὠσάμενος τὸ μάχιμον περὶ ταῖς ἁμάξαις καὶ τῷ χάρακι τὸν πλεῖστον ἔσχε πόνον, οὐκ αὑτῶν μόνων ὑφισταμένων ἐκεῖ καὶ μαχομένων, ἀλλὰ καὶ παῖδες αὑτῶν καὶ γυναῖκες ἀμυνόμενοι μέχρι θανάτου συγκατεκόπησαν, ὥστε τὴν μάχην μόλις εἰς μέσας νύκτας τελευτῆσαι. καλῷ δὲ τῷ τῆς νίκης ἔργῳ κρεῖττον ἐπέθηκε τὸ συνοικίσαι τοὺς διαφυγόντας ἐκ τῆς μάχης τῶν περιόντων βαρβάρων, καὶ καταναγκάσαι τὴν χώραν ἀναλαβεῖν ἣν ἀπέλιπον καὶ τὰς πόλεις ἃς διέφθειραν, ὄντας ὑπὲρ δέκα μυριάδας, ἔπραξε δὲ τοῦτο δεδιὼς μὴ τὴν χώραν ἔρημον γενομένην οἱ Γερμανοὶ διαβάντες κατάσχωσι.", "st": "Caes. 18.1"}, {"sp": "N", "t": "δεύτερον δὲ πρὸς Γερμανοὺς ἄντικρυς ὑπὲρ Κελτῶν ἐπολέμησε, καίτοι τὸν βασιλέα πρότερον αὐτῶν Ἀριόβιστον ἐν Ῥώμῃ σύμμαχον πεποιημένος ἀλλ’ ἦσαν ἀφόρητοι τοῖς ὑπηκόοις αὐτοῦ γείτονες, καὶ καιροῦ παραδόντος οὐκ ἂν ἐδόκουν ἐπὶ τοῖς παροῦσιν ἀτρεμήσειν, ἀλλ’ ἐπινεμήσεσθαι καὶ καθέξειν τὴν Γαλατίαν. ὁρῶν δὲ τοὺς ἡγεμόνας ἀποδειλιῶντας, καὶ μάλιστα ὅσοι τῶν ἐπιφανῶν καὶ νέων αὐτῷ συνεξῆλθον ὡς δὴ τρυφῇ χρησόμενοι καὶ χρηματισμῷ τῇ μετὰ Καίσαρος στρατείᾳ, συναγαγὼν εἰς ἐκκλησίαν ἐκέλευσεν ἀπιέναι καὶ μὴ κινδυνεύειν παρὰ γνώμην οὕτως ἀνάνδρως καὶ μαλακῶς ἔχοντας, αὐτὸς δὲ ἔφη τὸ δέκατον τάγμα μόνον παραλαβὼν ἐπὶ τοὺς βαρβάρους πορεύσεσθαι, μήτε κρείττοσι μέλλων Κίμβρων μάχεσθαι πολεμίοις μήτε αὐτὸς ὢν Μαρίου χείρων στρατηγός. ἐκ τούτου τὸ μὲν δέκατον τάγμα πρεσβευτὰς ἔπεμψε πρὸς αὐτόν χάριν ἔχειν ὁμολογοῦντες, τὰ δὲ ἄλλα τοὺς ἑαυτῶν ἐκάκιζον ἡγεμόνας, ὁρμῆς δὲ καὶ προθυμίας γενόμενοι πλήρεις ἅπαντες ἠκολούθουν ὁδὸν ἡμερῶν πολλῶν, ἕως ἐν διακοσίοις τῶν πολεμίων σταδίοις κατεστρατοπέδευσαν.ἦν μὲν οὖν ὅ τι καὶ πρὸς τὴν ἔφοδον αὐτὴν ἐτέθραυστο τῆς γνώμης τοῦ Ἀριοβίστου.", "st": "Caes. 19.1"}, {"sp": "N", "t": "Γερμανοῖς γὰρ ἐπιθήσεσθαι Ῥωμαίους, ὧν ἐπερχομένων οὐκ ἂν ἐδόκουν ὑποστῆναι, μὴ προσδοκήσας ἐθαύμαζε τὴν Καίσαρος τόλμαν καὶ τὸν στρατὸν ἑώρα τεταραγμένον. ἔτι δὲ μᾶλλον αὐτοὺς ἤμβλυνε τὰ μαντεύματα τῶν ἱερῶν γυναικῶν, αἳ ποταμῶν δίναις προσβλέπουσαι καὶ ῥευμάτων ἑλιγμοῖς καὶ ψόφοις τεκμαιρόμεναι προεθέσπιζον, οὐκ ἐῶσαι μάχην τίθεσθαι πρὶν ἐπιλάμψαι νέαν σελήνην. ταῦτα τῷ Καίσαρι πυνθανομένῳ καὶ τοὺς Γερμανοὺς ἡσυχάζοντας ὁρῶντι καλῶς ἔχειν ἔδοξεν ἀπροθύμοις οὖσιν αὐτοῖς συμβαλεῖν μᾶλλον ἢ τὸν ἐκείνων ἀναμένοντα καιρὸν καθῆσθαι. καὶ προσβολὰς ποιούμενος τοῖς ἐρύμασι καὶ λόφοις ἐφ’ ὧν ἐστρατοπέδευον, ἐξηγρίαινε καὶ παρώξυνε καταβάντας πρὸς ὀργὴν διαγωνίσασθαι. γενομένης δὲ λαμπρᾶς τροπῆς αὐτῶν, ἐπὶ σταδίους τετρακοσίους ἄχρι τοῦ Ῥήνου διώξας κατέπλησε τοῦτο πᾶν νεκρῶν τὸ πεδίον καὶ λαφύρων, Ἀριόβιστος δὲ φθάσας μετ’ ὀλίγων διεπέρασε τὸν Ῥῆνον· ἀριθμὸν δὲ νεκρῶν μυριάδας ὀκτὼ γενέσθαι λέγουσι.", "st": "Caes. 19.6"}, {"sp": "N", "t": "ταῦτα διαπραξάμενος τὴν μὲν δύναμιν ἐν Σηκουανοῖς ἀπέλιπε διαχειμάσουσαν, αὐτὸς δὲ τοῖς ἐν Ῥώμῃ προσέχειν βουλόμενος εἰς τὴν περὶ Πάδον Γαλατίαν κατέβη, τῆς αὐτῷ δεδομένης ἐπαρχίας οὖσαν ὁ γὰρ καλούμενος Ῥουβίκων ποταμὸς ἀπὸ τῆς ὑπὸ ταῖς Ἄλπεσι Κελτικῆς ὁρίζει τὴν ἄλλην Ἰταλίαν. ἐνταῦθα καθήμενος ἐδημαγώγει, πολλῶν πρὸς αὐτὸν ἀφικνουμένων, διδοὺς ὧν ἕκαστος δεηθείη, καὶ πάντας ἀποπέμπων τὰ μὲν ἔχοντας ἤδη παρ’ αὐτοῦ, τὰ δὲ ἐλπίζοντας, καὶ παρὰ τὸν ἄλλον δὲ πάντα τῆς στρατείας χρόνον ἐλάνθανε τὸν Πομπήϊον ἐν μέρει νῦν μὲν τοὺς πολεμίους τοῖς τῶν πολιτῶν ὅπλοις καταστρεφόμενος, νῦν δὲ τοῖς ἀπὸ τῶν πολεμίων χρήμασιν αἱρῶν τοὺς πολίτας καὶ χειρούμενος.", "st": "Caes. 20.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Βέλγας ἤκουσε δυνατωτάτους Κελτῶν καὶ τὴν τρίτην ἁπάσης τῆς Κελτικῆς νεμομένους ἀφεστάναι, πολλὰς δή τινας μυριάδας ἐνόπλων ἀνδρῶν ἠθροικότας, ἐπιστρέψας εὐθὺς ἐχώρει τάχει πολλῷ καὶ πορθοῦσι τοὺς συμμάχους Γαλάτας ἐπιπεσὼν τοῖς πολεμίοις τοὺς μὲν ἀθρουστάτους καὶ πλείστους αἰσχρῶς ἀγωνισαμένους τρεψάμενος διέφθειρεν, ὥστε καὶ λίμνας καὶ ποταμοὺς βαθεῖς τοῖς Ῥωμαίοις νεκρῶν πλήθει περατοὺς γενέσθαι, τῶν δ’ ἀποστάντων οἱ μὲν παρωκεάνιοι πάντες ἀμαχεὶ προσεχώρησαν ἐπὶ δὲ τοὺς ἀγριωτάτους καὶ μαχιμωτάτους τῶν τῇδε, Νερβίους, ἐστράτευσεν, οἵπερ εἰς συμμιγεῖς δρυμοὺς κατῳκημένοι, γενεὰς δὲ καὶ κτήσεις ἔν τινι βυθῷ τῆς ὕλης ἀπωτάτω θέμενοι τῶν πολεμίων, αὐτοὶ τῷ Καίσαρι ποιουμένῳ χάρακα καὶ μὴ προσδεχομένῳ τηνικαῦτα τὴν μάχην ἑξακισμύριοι τὸ πλῆθος ὄντες αἰφνιδίως προσέπεσον, καὶ τοὺς μὲν ἱππεῖς ἐτρέψαντο, τῶν δὲ ταγμάτων τὸ δωδέκατον καὶ τὸ ἕβδομον περισχόντες ἅπαντας ἀπέκτειναν τοὺς ταξιάρχους. εἰ δὲ μὴ Καῖσαρ ἁρπάσας τὸν θυρεὸν καὶ διασχὼν τοὺς πρὸ αὐτοῦ μαχομένους ἐνέβαλε, τοῖς βαρβάροις, καὶ ἀπὸ τῶν ἄκρων τὸ δέκατον κινδυνεύοντος αὐτοῦ κατέδραμε καὶ διέκοψε τὰς τάξεις τῶν πολεμίων, οὐδεὶς ἂν δοκεῖ περιγενέσθαι νῦν δὲ τῇ Καίσαρος τόλμῃ τὴν λεγομένην ὑπὲρ δύναμιν μάχην ἀγωνισάμενοι τρέπονται μὲν οὐδ’ ὣς τοὺς Νερβίους, κατακόπτουσι δὲ ἀμυνομένους· πεντακόσιοι γὰρ ἀπὸ μυριάδων ἓξ σωθῆναι λέγονται, βουλευταὶ δὲ τρεῖς ἀπὸ τετρακοσίων.", "st": "Caes. 20.4"}, {"sp": "N", "t": "ταῦτα ἡ σύγκλητος πυθομένη πεντεκαίδεκα ἡμέρας ἐψηφίσατο θύειν τοῖς θεοῖς καὶ σχολάζειν ἑορτάζοντας, ὅσας ἐπ’ οὐδεμιᾷ νίκῃ πρότερον. καὶ γὰρ ὁ κίνδυνος ἐφάνη μέγας, ἐθνῶν ἅμα τοσούτων ἀναρραγέντων, καὶ τὸ νίκημα λαμπρότερον, ὅτι Καῖσαρ ἦν ὁ νικῶν, ἡ πρὸς ἐκεῖνον εὔνοια τῶν πολλῶν ἐποίει. Καῖσαρ δ’ αὐτὸς εὖ θέμενος τὰ κατὰ τὴν Γαλατίαν πάλιν ἐν τοῖς περὶ Πάδον χωρίοις διεχείμαζε συσκευαζόμενος τὴν πόλιν. οὐ γὰρ μόνον οἱ τὰς ἀρχὰς παραγγέλλοντες ἐκείνῳ χρώμενοι χορηγῷ καὶ τοῖς παρ’ ἐκείνου χρήμασι διαφθείροντες τὸν δῆμον ἀνηγορεύοντο, καὶ πᾶν ἔπραττον ὃ τὴν ἐκείνου δύναμιν αὔξειν ἔμελλεν, ἀλλὰ καὶ τῶν ἐπιφανεστάτων ἀνδρῶν καὶ μεγίστων οἱ πλεῖστοι συνῆλθον πρὸς αὐτὸν εἰς Λοῦκαν, Πομπήϊός τε καὶ Κράσσος καὶ Ἄππιος ὁ τῆς Σαρδόνος ἡγεμών καὶ Νέπως ὁ τῆς Ἰβηρίας ἀνθύπατος, ὥστε ῥαβδούχους μὲν ἑκατὸν εἴκοσι γενέσθαι, συγκλητικοὺς δὲ πλείονας ἢ διακοσίους.", "st": "Caes. 21.1"}, {"sp": "N", "t": "βουλὴν δὲ θέμενοι διεκρίθησαν ἐπὶ τούτοις· ἔδει Πομπήϊον μὲν καὶ Κράσσον ὑπάτους ἀποδειχθῆναι, Καίσαρι δὲ χρήματα καὶ πενταετίαν ἄλλην ἐπιμετρηθῆναι τῆς στρατηγίας, ὃ καὶ παραλογώτατον ἐφαίνετο τοῖς νοῦν ἔχουσιν. οἱ γὰρ τοσαῦτα χρήματα παρὰ Καίσαρος λαμβάνοντες ὡς οὐκ ἔχοντι διδόναι τὴν βουλὴν ἔπειθον, μᾶλλον δὲ ἠνάγκαζον ἐπιστένουσαν οἷς ἐψηφίζοντο, Κάτωνος μὲν οὐ παρόντος, ἐπίτηδες γὰρ αὐτὸν εἰς Κύπρον ἀπεδιοπομπήσαντο, Φαωνίου δέ, ὃς ἦν ζηλωτὴς Κάτωνος, ὡς οὐδὲν ἐπέραινεν ἀντιλέγων, ἐξαλλομένου διὰ θυρῶν καὶ βοῶντος εἰς τὸ πλῆθος. ἀλλὰ προσεῖχεν οὐδείς, τῶν μὲν Πομπήϊον αἰδουμένων καὶ Κράσσον, οἱ δὲ πλεῖστοι Καίσαρι χαριζόμενοι καὶ πρὸς τὰς ἀπ’ ἐκείνου ζῶντες ἐλπίδας ἡσύχαζον.", "st": "Caes. 21.6"}, {"sp": "N", "t": "τραπόμενος δὲ αὖθις ὁ Καῖσαρ ἐπὶ τὰς ἐν τῇ Κελτικῇ δυνάμεις πολὺν καταλαμβάνει πόλεμον ἐν τῇ χώρᾳ, δύο Γερμανικῶν ἐθνῶν μεγάλων ἐπὶ κατακτήσει γῆς ἄρτι τὸν Ῥῆνον διαβεβηκότων· Οὐσίπας καλοῦσι τοὺς ἑτέρους, τοὺς δὲ Τεντερίτας. περὶ δὲ τῆς πρὸς τούτους γενομένης μάχης ὁ μὲν Καῖσαρ ἐν ταῖς ἐφημερίσι γέγραφεν ὡς οἱ βάρβαροι διαπρεσβευόμενοι πρὸς αὐτὸν ἐν σπονδαῖς ἐπιθοῖντο καθ’ ὁδόν, Καὶ διὰ τοῦτο τρέψαιντο τοὺς αὐτοῦ πεντακισχιλίους ὄντας ἱππεῖς ὀκτακοσίοις τοῖς ἐκείνων μὴ προσδοκῶντας· εἶτα πέμψειαν ἑτέρους πρὸς αὐτὸν αὖθις ἐξαπατῶντας, οὓς κατασχὼν ἐπαγάγοι τοῖς βαρβάροις τὸ στράτευμα, τὴν πρὸς οὕτως ἀπίστους καὶ παρασπόνδους πίστιν εὐήθειαν ἡγούμενος. Τανύσιος δὲ λέγει Κάτωνα, τῆς βουλῆς ἐπὶ τῇ νίκῃ ψηφιζομένης ἑορτὰς καὶ θυσίας, ἀποφήνασθαι γνώμην ὡς ἐκδοτέον ἐστὶ τὸν Καίσαρα τοῖς βαρβάροις, ἀφοσιουμένους τὸ παρασπόνδημα ὑπὲρ τῆς πόλεως καὶ τὴν ἀρὰν εἰς τὸν αἴτιον τρέποντας.", "st": "Caes. 22.1"}, {"sp": "N", "t": "τῶν δὲ διαβάντων αἱ μὲν κατακοπεῖσαι τεσσαράκοντα μυριάδες ἦσαν, ὀλίγους δὲ τοὺς ἀποπεράσαντας αὖθις ὑπεδέξαντο Σούγαμβροι, Γερμανικὸν ἔθνος. καὶ ταύτην λαβὼν αἰτίαν ἐπ’ αὐτοὺς ὁ Καῖσαρ, ἄλλως δὲ δόξης ἐφιέμενος καὶ τοῦ πρῶτος ἀνθρώπων στρατῷ διαβῆναι τὸν Ῥῆνον, ἐγεφύρου πλάτος τε πολὺν ὄντα καὶ κατ’ ἐκεῖνο τοῦ πόρου μάλιστα πλημμυροῦντα καὶ τραχὺν καὶ ῥοώδη καὶ τοῖς καταφερομένοις στελέχεσι καὶ ξύλοις πληγὰς καὶ σπαραγμοὺς ἐνδιδόντα κατὰ τῶν ἐρειδόντων τὴν γέφυραν. ἀλλὰ ταῦτα προβόλοις ξύλων μεγάλων διὰ τοῦ πόρου καταπεπηγότων ἀναδεχόμενος, καὶ χαλινώσας τὸ προσπῖπτον ῥεῦμα τῷ ζεύγματι, πίστεως πάσης θέαμα κρεῖττον ἐπεδείξατο τὴν γέφυραν ἡμέραις δέκα συντελεσθεῖσαν.", "st": "Caes. 22.5"}, {"sp": "N", "t": "περαιώσας δὲ τὴν δύναμιν, οὐδενὸς ὑπαντῆσαι τολμήσαντος, ἀλλὰ καὶ τῶν ἡγεμονικωτάτων τοῦ Γερμανικοῦ Σουήβων εἰς βαθεῖς καὶ ὑλώδεις αὐλῶνας ἀνασκευασαμένων, πυρπολήσας μὲν τὴν τῶν πολεμίων, θαρρύνας δὲ τοὺς ἀεὶ τὰ Ῥωμαίων ἀσπαζομένους, ἀνεχώρησεν αὖθις εἰς τὴν Γαλατίαν, εἴκοσι δυεῖν δεούσας ἡμέρας ἐν τῇ Γερμανικῇ διατετριφώς.", "st": "Caes. 23.1"}, {"sp": "N", "t": "ἡ δὲ ἐπὶ τοὺς Βρεττανοὺς στρατεία τὴν μὲν τόλμαν εἶχεν ὀνομαστήν πρῶτος γὰρ εἰς τὸν ἑσπέριον Ὠκεανὸν ἐπέβη στόλῳ, καὶ διὰ τῆς Ἀτλαντικῆς θαλάττης στρατὸν ἐπὶ πόλεμον κομίζων ἔπλευσε· καὶ νῆσον ἀπιστουμένην ὑπὸ μεγέθους καὶ πολλὴν ἔριν παμπόλλοις συγγραφεῦσι παρασχοῦσαν, ὡς ὄνομα καὶ λόγος οὐ γενομένης οὐδὲ οὔσης πέπλασται, κατασχεῖν ἐπιθέμενος προήγαγεν ἔξω τῆς οἰκουμένης τὴν Ῥωμαίων ἡγεμονίαν. δὶς δὲ διαπλεύσας εἰς τὴν νῆσον ἐκ τῆς ἀντιπέρας Γαλατίας, καὶ μάχαις πολλαῖς κακώσας τοὺς πολεμίους μᾶλλον ἢ τοὺς ἰδίους ὠφελήσας, οὐδὲν γὰρ ὅ τι καὶ λαβεῖν ἦν ἄξιον ἀπ’ ἀνθρώπων κακοβίων καὶ πενήτων, οὐχ οἷον ἐβούλετο τῷ πολέμῳ τέλος ἐπέθηκεν, ἀλλ’ ὁμήρους λαβὼν παρὰ τοῦ βασιλέως καὶ ταξάμενος φόρους ἀπῆρεν ἐκ τῆς νήσου.", "st": "Caes. 23.2"}, {"sp": "N", "t": "καὶ καταλαμβάνει γράμματα μέλλοντα διαπλεῖν πρὸς αὐτὸν ἀπὸ τῶν ἐν Ῥώμῃ φίλων, δηλοῦντα τὴν τῆς θυγατρὸς αὐτοῦ τελευτήν τελευτᾷ δὲ τίκτουσα παρὰ Πομπηΐῳ. καὶ μέγα μὲν αὐτὸν ἔσχε Πομπήϊον, μέγα δὲ Καίσαρα πένθος, οἱ δὲ φίλοι συνεταράχθησαν ὡς τῆς ἐν εἰρήνῃ καὶ ὁμονοίᾳ τἆλλα νοσοῦσαν τὴν πολιτείαν φυλαττούσης οἰκειότητος λελυμένης καὶ γὰρ τὸ βρέφος εὐθὺς οὐ πολλὰς ἡμέρας μετὰ τὴν μητέρα διαζῆσαν ἐτελεύτησε. τὴν μὲν οὖν Ἰουλίαν βίᾳ τῶν δημάρχων ἀράμενον τὸ πλῆθος εἰς τὸ Ἄρειον ἤνεγκε πεδίον, κἀκεῖ κηδευθεῖσα κεῖται.", "st": "Caes. 23.5"}, {"sp": "N", "t": "τοῦ δὲ Καίσαρος μεγάλην ἤδη τὴν δύναμιν οὖσαν εἰς πολλὰ κατ’ ἀνάγκην χειμάδια διελόντος, αὐτοῦ δὲ πρὸς τὴν Ἰταλίαν, ὥσπερ εἰώθει, τραπομένου, πάντα μὲν αὖθις ἀνερρήγνυτο τὰ τῶν Γαλατῶν, καὶ στρατοὶ μεγάλοι περιϊόντες ἐξέκοπτον τὰ χειμάδια καὶ προσεμάχοντο τοῖς χαρακώμασι τῶν Ῥωμαίων, οἱ δὲ πλεῖστοι καὶ κράτιστοι τῶν ἀποστάντων μετὰ Ἀβριόριγος Κότταν μὲν αὐτῷ στρατοπέδῳ καὶ Τιτύριον διέφθειραν, τὸ δὲ ὑπὸ Κικέρωνι τάγμα μυριάσιν ἓξ περισχόντες ἐπολιόρκουν καὶ μικρὸν ἀπέλιπον ᾑρηκέναι κατὰ κράτος, συντετρωμένων ἁπάντων καὶ παρὰ δύναμιν ὑπὸ προθυμίας ἀμυνομένων.ὡς δὲ ἠγγέλθη ταῦτα τῷ Καίσαρι μακρὰν ὄντι, ταχέως ἐπιστρέψας καὶ συναγαγὼν ἑπτακισχιλίους τοὺς σύμπαντας ἠπείγετο τὸν Κικέρωνα τῆς πολιορκίας ἐξαιρησόμενος.", "st": "Caes. 24.1"}, {"sp": "N", "t": "τοὺς δὲ πολιορκοῦντας οὐκ ἔλαθεν, ἀλλ’ ἀπήντων ὡς ἀναρπασόμενοι, τῆς ὀλιγότητος καταφρονήσαντες. κἀκεῖνος ἐξαπατῶν ὑπέφευγεν ἀεί, καὶ χωρία λαβὼν ἐπιτηδείως ἔχοντα πρὸς πολλοὺς μαχομένῳ μετ’ ὀλίγων φράγνυται στρατόπεδον, καὶ μάχης ἔσχε τοὺς ἑαυτοῦ πάσης, ἀναγαγεῖν δὲ τὸν χάρακα καὶ τὰς πύλας ἀνοικοδομεῖν ὡς δεδοικότας ἠνάγκαζε, καταφρονηθῆναι στρατηγῶν, μέχρι οὗ σποράδην ὑπὸ θράσους προσβάλλοντας ἐπεξελθὼν ἐτρέψατο καὶ πολλοὺς αὐτῶν διέφθειρε.", "st": "Caes. 24.4"}, {"sp": "N", "t": "τοῦτο τὰς πολλὰς ἀποστάσεις τῶν ἐνταῦθα Γαλατῶν κατεστόρεσε, καὶ τοῦ χειμῶνος αὐτὸς ἐπιφοιτῶν τε πανταχόσε καὶ προσέχων ὀξέως τοῖς νεωτερισμοῖς. καὶ γὰρ ἧκεν ἐξ Ἰταλίας ἀντὶ τῶν ἀπολωλότων αὐτῷ τρία τάγματα, Πομπηΐου μὲν ἐκ τῶν ὑφ’ αὑτῷ δύο χρήσαντος, ἓν δὲ νεοσύλλεκτον ἐκ τῆς περὶ Πάδον Γαλατίας. πόρρω δὲ τούτων αἱ πάλαι καταβεβλημέναι κρύφα καὶ νεμόμεναι διὰ τῶν δυνατωτάτων ἀνδρῶν ἐν τοῖς μαχιμωτάτοις γένεσιν ἀρχαὶ τοῦ μεγίστου καὶ κινδυνωδεστάτου τῶν ἐκεῖ πολέμων ἀνεφαίνοντο, ῥωσθεῖσαι πολλῇ μὲν ἡλικίᾳ καὶ πανταχόθεν ὅπλοις ἀθροισθείσῃ, μεγάλοις δὲ πλούτοις εἰς ταὐτὸ συνενεχθεῖσιν, ἰσχυραῖς δὲ πόλεσι, δυσεμβόλοις δὲ χώραις. τότε δὲ καὶ χειμῶνος ὥρᾳ πάγοι ποταμῶν καὶ νιφετοῖς ἀποκεκρυμμένοι δρυμοί καὶ πεδία χειμάρροις ἐπιλελιμνασμένα, καὶ πῇ μὲν ἀτέκμαρτοι βάθει χιόνος ἀτραποί, πῇ δὲ δι’ ἑλῶν καὶ ῥευμάτων παρατρεπομένων ἀσάφεια πολλὴ τῆς πορείας παντάπασιν ἐδόκουν ἀνεπιχείρητα Καίσαρι τὰ τῶν ἀφισταμένων ποιεῖν. ἀφειστήκει μὲν οὖν πολλὰ φῦλα, πρόσχημα δὲ ἦσαν Ἀρβέρνοι καὶ Καρνουτῖνοι, τὸ δὲ σύμπαν αἱρεθεὶς κράτος εἶχε τοῦ πολέμου Οὐεργεντόριξ, οὗ τὸν πατέρα Γαλάται τυραννίδα δοκοῦντα πράττειν ἀπέκτειναν.", "st": "Caes. 25.1"}, {"sp": "N", "t": "οὗτος οὖν εἰς πολλὰ διελὼν τὴν δύναμιν μέρη καὶ πολλοὺς ἐπιστήσας ἡγεμόνας ᾠκειοῦτο τὴν πέριξ ἅπασαν ἄχρι τῶν πρὸς τὸν Ἄραρα κεκλιμένων, διανοούμενος ἤδη τῶν ἐν Ῥώμῃ συνισταμένων ἐπὶ Καίσαρα σύμπασαν ἐγείρειν τῷ πολέμῳ Γαλατίαν. ὅπερ εἰ μικρὸν ὕστερον ἔπραξε, Καίσαρος εἰς τὸν ἐμφύλιον ἐμπεσόντος πόλεμον, οὐκ ἂν ἐλαφρότεροι τῶν Κιμβρικῶν ἐκείνων φόβοι τὴν Ἰταλίαν κατέσχον. νυνὶ δὲ ὁ πᾶσι μὲν ἄριστα χρῆσθαι τοῖς πρὸς πόλεμον, μάλιστα δὲ καιρῷ πεφυκὼς Καῖσαρ ἅμα τῷ πυθέσθαι τὴν ἀπόστασιν ἄρας ἐχώρει ταῖς αὐταῖς ὁδοῖς ἃς διῆλθε, καὶ βίᾳ καὶ τάχει τῆς πορείας διὰ τοσούτου χειμῶνος ἐπιδειξάμενος τοῖς βαρβάροις ὡς ἄμαχος αὐτοῖς καὶ ἀήττητος ἔπεισι στρατός. ὅπου γὰρ ἄγγελον ἢ γραμματοφόρον διαδῦναι τῶν παρ’ αὐτοῦ χρόνῳ πολλῷ ἦν ἄπιστον, ἐνταῦθα μετὰ πάσης ἑωρᾶτο τῆς στρατιᾶς ἅμα χώρας λυμαινόμενος αὐτῶν καὶ ἐκκόπτων τὰ χωρία, καταστρεφόμενος πόλεις, ἀναλαμβάνων τοὺς μετατιθεμένους, μέχρι καὶ τὸ τῶν Ἐδούων ἔθνος ἐξεπολεμώθη πρὸς αὐτόν, οἳ τὸν ἄλλον χρόνον ἀδελφοὺς ἀναγορεύοντες αὑτοὺς Ῥωμαίων καὶ τιμώμενοι διαπρεπῶς, τότε δὲ τοῖς ἀποστάταις προσγενόμενοι πολλὴν τῇ Καίσαρος στρατιᾷ περιέστησαν ἀθυμίαν. διόπερ καὶ κινήσας ἐκεῖθεν ὑπερέβαλε τὰ Λιγγονικά, βουλόμενος ἅψασθαι τῆς Σηκουανῶν φίλων ὄντων καὶ προκειμένων τῆς Ἰταλίας πρὸς τὴν ἄλλην Γαλατίαν. ἐνταῦθα δὲ αὐτῷ τῶν πολεμίων ἐπιπεσόντων καὶ περισχόντων μυριάσι πολλαῖς, ὁρμήσας διαγωνίσασθαι τοῖς μὲν ὅλοις καταπολεμῶν ἐκράτησε, χρόνῳ πολλῷ καὶ φόνῳ καταβιασάμενος τοὺς βαρβάρους, ἔδοξε δὲ κατ’ ἀρχάς τι καὶ σφαλῆναι, καὶ δεικνύουσιν Ἀρβέρνοι ξιφίδιον πρὸς ἱερῷ κρεμάμενον, ὡς δὴ Καίσαρος λάφυρον. ὃ θεασάμενος αὐτὸς ὕστερον ἐμειδίασε, καὶ τῶν φίλων καθελεῖν κελευόντων οὐκ εἴασεν, ἱερὸν ἡγούμενος.", "st": "Caes. 26.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τότε τῶν διαφυγόντων οἱ πλεῖστοι μετὰ τοῦ βασιλέως εἰς πόλιν Ἀλησίαν συνέφυγον. καὶ πολιορκοῦντι ταύτην Καίσαρι δοκοῦσαν ἀνάλωτον εἶναι μεγέθει τε τειχῶν καὶ πλήθει τῶν ἀπομαχομένων ἐπιπίπτει παντὸς λόγου μείζων κίνδυνος ἔξωθεν. ὃ γὰρ ἦν ἐν Γαλατίᾳ κράτιστον ἀπὸ τῶν ἐθνῶν ἀθροισθὲν, ἐν ὅπλοις ἧκον ἐπὶ τὴν Ἀλησίαν τριάκοντα μυριάδες· αἱ δ’ ἐν αὐτῇ τῶν μαχομένων οὐκ ἐλάττονες ἦσαν ἑπτακαίδεκα μυριάδων, ὥστε ἐν μέσῳ πολέμου τοσούτου τὸν Καίσαρα κατειλημμένον καὶ πολιορκούμενον ἀναγκασθῆναι διττὰ τείχη προβαλέσθαι, τὸ μὲν πρὸς τὴν πόλιν, τὸ δὲ ἀπὸ τῶν ἐπεληλυθότων, ὡς, εἰ συνέλθοιεν αἱ δυνάμεις, κομιδῇ διαπεπραγμένων τῶν καθ’ αὑτόν.", "st": "Caes. 27.1"}, {"sp": "N", "t": "διὰ πολλὰ μὲν οὖν εἰκότως ὁ πρὸς Ἀλησίᾳ κίνδυνος ἔσχε δόξαν, ὡς ἔργα τόλμης καὶ δεινότητος οἷα τῶν ἄλλων ἀγώνων οὐδεὶς παρασχόμενος, μάλιστα δὲ ἄν τις θαυμάσειε τὸ λαθεῖν τοὺς ἐν τῇ πόλει Καίσαρα τοσαύταις μυριάσι ταῖς ἔξω συμβαλόντα καὶ περιγενόμενον, μᾶλλον δὲ καὶ τῶν Ῥωμαίων τοὺς τὸ πρὸς τῇ πόλει τεῖχος φυλάττοντας. οὐ γὰρ πρότερον ᾔσθοντο τὴν νίκην ἢ κλαυθμὸν ἐκ τῆς Ἀλησίας ἀνδρῶν καὶ κοπετὸν γυναικῶν ἀκουσθῆναι, θεασαμένων ἄρα κατὰ θάτερα μέρη πολλοὺς μὲν ἀργύρῳ καὶ χρυσῷ κεκοσμημένους θυρεούς, πολλοὺς δὲ αἵματι πεφυρμένους θώρακας, ἔτι δ’ ἐκπώματα καὶ σκηνὰς Γαλατικὰς ὑπὸ τῶν Ῥωμαίων εἰς τὸ στρατόπεδον κομιζομένας. οὕτως ὀξέως ἢ τοσαύτη δύναμις, ὥσπερ εἴδωλον ἢ ὄνειρον, ἠφάνιστο καὶ διεπεφόρητο, τῶν πλείστων ἐν τῇ μάχῃ πεσόντων. οἱ δὲ τὴν Ἀλησίαν ἔχοντες οὐκ ὀλίγα πράγματα παρασχόντες ἑαυτοῖς καὶ Καίσαρι τέλος παρέδοσαν ἑαυτούς, ὁ δὲ τοῦ σύμπαντος ἡγεμὼν πολέμου Οὐεργεντόριξ ἀναλαβὼν τῶν ὅπλων τὰ κάλλιστα καὶ κοσμήσας τὸν ἵππον ἐξιππάσατο διὰ τῶν πυλῶν καὶ κύκλῳ περὶ τὸν Καίσαρα καθεζόμενον ἐλάσας, εἶτα ἀφαλόμενος τοῦ ἵππου τὴν μὲν πανοπλίαν ἀπέρριψεν, αὐτὸς δὲ καθίσας ὑπὸ πόδας τοῦ Καίσαρος ἡσυχίαν ἦγεν, ἄχρι οὗ παρεδόθη φρουρησόμενος ἐπὶ τὸν θρίαμβον.", "st": "Caes. 27.5"}, {"sp": "N", "t": "Καίσαρι δὲ πάλαι μὲν ἐδέδοκτο καταλύειν Πομπήϊον, ὥσπερ ἀμέλει κἀκείνῳ τοῦτον Κράσσου γὰρ ἐν Πάρθοις ἀπολωλότος, ὃς ἦν ἔφεδρος ἀμφοῖν, ἀπελείπετο τῷ μὲν ὑπὲρ τοῦ γενέσθαι μεγίστῳ τὸν ὄντα καταλύειν, τῷ δέ, ἵνα μὴ πάθῃ τοῦτο, προαναιρεῖν ὃν ἐδεδοίκει. τοῦτο δὲ Πομπηΐῳ μὲν ἐξ ὀλίγου φοβεῖσθαι παρέστη τέως ὑπερορῶντι Καίσαρος, ὡς οὐ χαλεπὸν ἔργον ὃν αὐτὸς ηὔξησε καταλυθῆναι πάλιν ὑπ’ αὐτοῦ, Καῖσαρ δὲ ἀπ’ ἀρχῆς ὑπόθεσιν ταύτην πεποιημένος, ἀπὸ τῶν ἀνταγωνιστῶν ὥσπερ ἀθλητὴς ἑαυτὸν ἀποστήσας μακρὰν καὶ τοῖς Κελτικοῖς ἐγγυμνασάμενος πολέμοις ἐπήσκησε μὲν τὴν δύναμιν, ηὔξησε δὲ τὴν δόξαν, ἀπὸ τῶν ἔργων εἰς ἀντίπαλον ἀρθεὶς τοῖς Πομπηΐου κατορθώμασι, λαμβάνων προφάσεις τὰς μὲν αὐτοῦ Πομπηΐου, τὰς δὲ τῶν καιρῶν ἐνδιδόντων καὶ τῆς ἐν Ῥώμῃ κακοπολιτείας, δι’ ἣν οἱ μὲν ἀρχὰς μετιόντες ἐν μέσῳ θέμενοι τραπέζας ἐδέκαζον ἀναισχύντως τὰ πλήθη, κατῄει δὲ ὁ δῆμος ἔμμισθος, οὐ ψήφοις ὑπὲρ τοῦ δεδωκότος, ἀλλὰ τόξοις καὶ ξίφεσι καὶ σφενδόναις ἁμιλλώμενος. αἵματι δὲ καὶ νεκροῖς πολλάκις αἰσχύναντες τὸ βῆμα διεκρίθησαν, ἀναρχίᾳ τὴν πόλιν ὥσπερ ἀκυβέρνητον ναῦν ὑποφερομένην ἀπολιπόντες, ὥστε τοὺς νοῦν ἔχοντας ἀγαπᾶν εἰ πρὸς μηδὲν αὐτοῖς χεῖρον, ἀλλὰ μοναρχίαν ἐκ τοιαύτης παραφροσύνης καὶ τοσούτου κλύδωνος ἐκπεσεῖται τὰ πράγματα, πολλοὶ δὲ ἦσαν οἱ καὶ λέγειν ἐν μέσῳ τολμῶντες ἤδη πλὴν ὑπὸ μοναρχίας ἀνήκεστον εἶναι τὴν πολιτείαν, καὶ τὸ φάρμακον τοῦτο χρῆναι τοῦ πρᾳοτάτου τῶν ἰατρῶν ἀνασχέσθαι προσφέροντος, ὑποδηλοῦντες τὸν Πομπήϊον. ἐπεὶ δὲ κἀκεῖνος λόγῳ παραιτεῖσθαι καλλωπιζόμενος ἔργῳ παντὸς μᾶλλον ἐπέραινεν ἐξ ὧν ἀναδειχθήσοιτο δικτάτωρ, συμφρονήσαντες οἱ περὶ Κάτωνα πείθουσι τὴν γερουσίαν ὕπατον αὐτὸν ἀποδεῖξαι μόνον, ὡς μὴ βιάσαιτο δικτάτωρ γενέσθαι, νομιμωτέρᾳ μοναρχίᾳ παρηγορηθείς, οἱ δὲ καὶ χρόνον ἐπεψηφίσαντο τῶν ἐπαρχιῶν· δύο δὲ εἶχεν, Ἰβηρίαν καὶ Λιβύην σύμπασαν, ἃς διῴκει πρεσβευτὰς ἀποστέλλων καὶ στρατεύματα τρέφων, οἷς ἐλάμβανεν ἐκ τοῦ δημοσίου ταμιείου χίλια τάλαντα καθ’ ἕκαστον ἐνιαυτόν.", "st": "Caes. 28.1"}, {"sp": "N", "t": "ἐκ τούτου Καῖσαρ ὑπατείαν ἐμνᾶτο πέμπων, καὶ χρόνον ὁμοίως τῶν ἰδίων ἐπαρχιῶν, τὸ μὲν οὖν πρῶτον Πομπηΐου σιωπῶντος οἱ περὶ Μάρκελλον καὶ Λέντλον ἠναντιοῦντο, μισοῦντες ἄλλως Καίσαρα καὶ τοῖς ἀναγκαίοις οὐκ ἀναγκαῖα προστιθέντες εἰς ἀτιμίαν αὐτοῦ καὶ προπηλακισμόν. Νεοκωμίτας γὰρ ἔναγχος ὑπὸ Καίσαρος ἐν Γαλατίᾳ κατῳκισμένους ἀφῃροῦντο τῆς πολιτείας καὶ Μάρκελλος ὑπατεύων ἕνα τῶν ἐκεῖ βουλευτῶν εἰς Ῥώμην ἀφικόμενον ᾔκιστο ῥάβδοις, ἐπιλέγων ὡς ταῦτα τοῦ μὴ Ῥωμαῖον εἶναι παράσημα προστίθησιν αὐτῷ, καὶ δεικνύειν ἀπιόντα Καίσαρι ἐκέλευε. μετὰ δὲ Μάρκελλον, ἤδη Καίσαρος τὸν Γαλατικὸν πλοῦτον ἀρύεσθαι ῥύδην ἀφεικότος πᾶσι τοῖς πολιτευομένοις, καὶ Κουρίωνα μὲν δημαρχοῦντα πολλῶν ἐλευθερώσαντος δανείων, Παύλῳ δὲ ὑπατεύοντι χίλια καὶ πεντακόσια τάλαντα δόντος, ἀφ’ ὧν καὶ τὴν βασιλικὴν ἐκεῖνος, ὀνομαστὸν ἀνάθημα, τῇ ἀγορᾷ προσεκόσμησεν ἀντὶ τῆς Φουλβίας οἰκοδομηθεῖσαν, οὕτω δὴ φοβηθεὶς τὴν σύστασιν ὁ Πομπήϊος ἀναφανδὸν ἤδη δι’ ἑαυτοῦ καὶ τῶν φίλων ἔπραττεν ἀποδειχθῆναι διάδοχον Καίσαρι τῆς ἀρχῆς, καὶ πέμπων ἀπῄτει τοὺς στρατιώτας οὓς ἔχρησεν αὐτῷ πρὸς τοὺς Κελτικοὺς ἀγῶνας, ὁ δὲ ἀποπέμπει, δωρησάμενος ἕκαστον ἄνδρα πεντήκοντα καὶ διακοσίαις δραχμαῖς. οἱ δὲ τούτους Πομπηΐῳ κομίσαντες εἰς μὲν τὸ πλῆθος οὐκ ἐπιεικεῖς οὐδὲ χρηστοὺς κατέσπειραν λόγους ὑπὲρ τοῦ Καίσαρος, αὐτὸν δὲ Πομπήϊον ἐλπίσι κεναῖς διέφθειραν, ὡς ποθούμενον ὑπὸ τῆς Καίσαρος στρατιᾶς καὶ τὰ μὲν ἐνταῦθα διὰ φθόνον πολιτείας ὑπούλου μόλις ἔχοντα, τῆς δὲ ἐκεῖ δυνάμεως ἑτοίμης ὑπαρχούσης αὐτῷ, κἂν μόνον ὑπερβάλωσιν εἰς Ἰταλίαν εὐθὺς ἐσομένης πρὸς ἐκεῖνον οὕτως γεγονέναι τὸν Καίσαρα πλήθει στρατειῶν λυπηρὸν αὐτοῖς καὶ φόβῳ μοναρχίας ὕποπτον. ἐπὶ τούτοις Πομπήϊος ἐχαυνοῦτο καὶ παρασκευῆς μὲν ἠμέλει στρατιωτῶν, ὡς μὴ δεδοικώς, λόγοις δὲ καὶ γνώμαις κατεπολιτεύετο τῷ δοκεῖν Καίσαρα, καταψηφιζόμενος ὧν ἐκεῖνος οὐδὲν ἐφρόντιζεν· ἀλλὰ καὶ λέγεταί τινα τῶν ἀφιγμένων παρ’ αὐτὸν ταξιάρχων ἑστῶτα πρὸ τοῦ βουλευτηρίου καὶ πυθόμενον ὡς οὐ δίδωσιν ἡ γερουσία Καίσαρι χρόνον τῆς ἀρχῆς, ἀλλ’ αὕτη φάναι δώσει, κρούσαντα τῇ χειρὶ τὴν λαβὴν τῆς μαχαίρας.", "st": "Caes. 29.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἥ γε παρὰ Καίσαρος ἀξίωσις τὸ πρόσχημα τῆς δικαιολογίας λαμπρὸν εἶχεν. ἠξίου γὰρ αὐτός τε καταθέσθαι τὰ ὅπλα, καὶ Πομπηΐου ταὐτὸ πράξαντος ἀμφοτέρους ἰδιώτας γενομένους εὑρίσκεσθαί τι παρὰ τῶν πολιτῶν ἀγαθόν, ὡς τοὺς αὐτὸν μὲν ἀφαιρουμένους, ἐκείνῳ δὲ ἣν εἶχε βεβαιοῦντας δύναμιν, ἕτερον διαβάλλοντας ἕτερον κατασκευάζειν τύραννον. ταῦτα προκαλούμενος ἐν τῷ δήμῳ Κουρίων ὑπὲρ Καίσαρος ἐκροτεῖτο λαμπρῶς· οἱ δὲ καὶ στεφάνους ἐπ’ αὐτὸν ὥσπερ ἀθλητὴν ἀνθοβολοῦντες ἠφίεσαν. Ἀντώνιος δὲ δημαρχῶν Καίσαρος ὑπὲρ τούτων ἐπιστολὴν κομισθεῖσαν εἰς τὸ πλῆθος ἐξήνεγκε καὶ ἀνέγνω βίᾳ τῶν ὑπάτων, ἐν δὲ τῇ βουλῇ Σκηπίων μὲν ὁ Πομπηΐου πενθερὸς εἰσηγήσατο γνώμην, ἂν ἐν ἡμέρᾳ ῥητῇ μὴ κατάθηται τὰ ὅπλα Καῖσαρ, ἀποδειχθῆναι πολέμιον αὐτόν. ἐρωτώντων δὲ τῶν ὑπάτων εἰ δοκεῖ Πομπήϊον ἀφεῖναι τοὺς στρατιώτας, καὶ πάλιν, εἰ δοκεῖ Καίσαρα, τῇ μὲν ὀλίγοι παντάπασι, τῇ δὲ πάντες παρ’ ὀλίγους προσέθεντο τῶν δὲ περὶ Ἀντώνιον πάλιν ἀξιούντων ἀμφοτέρους τὴν ἀρχὴν ἀφεῖναι, πάντες ὁμαλῶς προσεχώρησαν. ἀλλὰ ἐκβιαζομένου Σκηπίωνος, καὶ Λέντλου τοῦ ὑπάτου βοῶντος ὅπλων δεῖν πρὸς ἄνδρα λῃστήν, οὐ ψήφων, τότε μὲν διελύθησαν καὶ μετεβάλοντο τὰς ἐσθῆτας ἐπὶ πένθει διὰ τὴν στάσιν.", "st": "Caes. 30.1"}, {"sp": "N", "t": "ἐπεὶ δὲ παρὰ Καίσαρος ἧκον ἐπιστολαὶ μετριάζειν δοκοῦντος ἠξίου γὰρ ἀφεὶς τὰ ἄλλα πάντα τὴν ἐντὸς Ἄλπεων καὶ τὸ Ἰλλυρικὸν μετὰ δυεῖν ταγμάτων αὐτῷ δοθῆναι, μέχρι οὗ τὴν δευτέραν ὑπατείαν μέτεισι, καὶ Κικέρων ὁ ῥήτωρ ἄρτι παρὼν ἐκ Κιλικίας καὶ διαλλαγὰς πράττων ἐμάλαττε τὸν Πομπήϊον, ὁ δὲ τἆλλα συγχωρῶν τοὺς στρατιώτας ἀφῄρει. καὶ Κικέρων μὲν ἔπειθε τοὺς Καίσαρος φίλους συνενδόντας ἐπὶ ταῖς εἰρημέναις ἐπαρχίαις καὶ στρατιώταις μόνοις ἑξακισχιλίοις ποιεῖσθαι τὰς διαλύσεις, Πομπηΐου δὲ καμπτομένου καὶ διδόντος οἱ περὶ Λέντλον οὐκ εἴων ὑπατεύοντες, ἀλλὰ καὶ τῆς βουλῆς Ἀντώνιον καὶ Κουρίωνα προπηλακίσαντες ἐξήλασαν ἀτίμως, τὴν εὐπρεπεστάτην Καίσαρι τῶν προφάσεων αὐτοὶ μηχανησάμενοι, καὶ δι’ ἧς μάλιστα τοὺς στρατιώτας παρώξυνεν, ἐπιδεικνύμενος ἄνδρας ἐλλογίμους καὶ ἄρχοντας ἐπὶ μισθίων ζευγῶν πεφευγότας ἐν ἐσθῆσιν οἰκετικαῖς. οὕτω γὰρ ἀπὸ Ῥώμης σκευάσαντες ἑαυτοὺς διὰ φόβον ὑπεξῄεσαν.", "st": "Caes. 31.1"}, {"sp": "N", "t": "ἦσαν μὲν οὖν περὶ αὐτὸν οὐ πλείους ἱππέων τριακοσίων καὶ πεντακισχιλίων ὁπλιτῶν τὸ γὰρ ἄλλο στράτευμα πέραν Ἄλπεων ἀπολελειμμένον ἔμελλον ἄξειν οἱ πεμφθέντες. ὁρῶν δὲ τὴν ἀρχὴν ὧν ἐνίστατο πραγμάτων καὶ τὴν ἔφοδον οὐ πολυχειρίας δεομένην ἐν τῷ παρόντι μᾶλλον ἢ θάμβει τε τόλμης καὶ τάχει καιροῦ καταληπτέαν οὖσαν, ἐκπλήξειν γὰρ ἀπιστούμενος ῥᾷον ἢ βιάσεσθαι μετὰ παρασκευῆς ἐπελθών, τοὺς μὲν ἡγεμόνας καὶ ταξιάρχους ἐκέλευσε μαχαίρας ἔχοντας ἄνευ τῶν ἄλλων ὅπλων κατασχεῖν Ἀρίμινον τῆς Κελτικῆς μεγάλην πόλιν, ὡς ἐνδέχεται μάλιστα φεισαμένους φόνου καὶ ταραχῆς Ὁρτησίῳ δὲ τὴν δύναμιν παρέδωκεν.", "st": "Caes. 32.1"}, {"sp": "N", "t": "αὐτὸς δὲ τὴν μὲν ἡμέραν διῆγεν ἐν φανερῷ μονομάχοις ἐφεστὼς γυμναζομένοις καὶ θεώμενος μικρὸν δὲ πρὸ ἑσπέρας θεραπεύσας τὸ σῶμα καὶ παρελθὼν εἰς τὸν ἀνδρῶνα καὶ συγγενόμενος βραχέα τοῖς παρακεκλημένοις ἐπὶ τὸ δεῖπνον, ἤδη συσκοτάζοντος ἐξανέστη, τοὺς μὲν ἄλλους φιλοφρονηθεὶς καὶ κελεύσας περιμένειν αὐτὸν ὡς ἐπανελευσόμενον, ὀλίγοις δὲ τῶν φίλων προείρητο μὴ κατὰ τὸ αὐτὸ πάντας, ἄλλον δὲ ἄλλῃ διώκειν. αὐτὸς δὲ τῶν μισθίων ζευγῶν ἐπιβὰς ἑνός ἤλαυνεν ἑτέραν τινὰ πρῶτον ὁδόν, εἶτα πρὸς τὸ Ἀρίμινον ἐπιστρέψας, ὡς ἦλθεν ἐπὶ τὸν διορίζοντα τὴν ἐντὸς Ἄλπεων Γαλατίαν ἀπὸ τῆς ἄλλης Ἰταλίας ποταμὸν (Ῥουβίκων καλεῖται), καὶ λογισμὸς αὐτὸν εἰσῄει μᾶλλον ἐγγίζοντα τῷ δεινῷ καὶ περιφερόμενον τῷ μεγέθει τῶν τολμωμένων, ἔσχετο δρόμου· καὶ τὴν πορείαν ἐπιστήσας πολλὰ μὲν αὐτὸς ἐν ἑαυτῷ διήνεγκε σιγῇ τὴν γνώμην ἐπ’ ἀμφότερα μεταλαμβάνων, καὶ τροπὰς ἔσχεν αὐτῷ τότε τὸ βούλευμα πλείστας πολλὰ δὲ καὶ τῶν φίλων τοῖς παροῦσιν, ὧν ἦν καὶ Πολλίων Ἀσίννιος, συνδιηπόρησεν, ἀναλογιζόμενος ἡλίκων κακῶν ἄρξει πᾶσιν ἀνθρώποις ἡ διάβασις, ὅσον τε λόγον αὐτῆς τοῖς αὖθις ἀπολείψουσι. τέλος δὲ μετὰ θυμοῦ τινος ὥσπερ ἀφεὶς ἑαυτὸν ἐκ τοῦ λογισμοῦ πρὸς τὸ μέλλον, καὶ τοῦτο δὴ τὸ κοινὸν τοῖς εἰς τύχας ἐμβαίνουσιν ἀπόρους καὶ τόλμας προοίμιον ὑπειπὼν, Ἀνερρίφθω κύβος, ὥρμησε πρὸς τὴν διάβασιν καὶ δρόμῳ τὸ λοιπὸν ἤδη χρώμενος εἰσέπεσε πρὸ ἡμέρας εἰς τὸ Ἀρίμινον καὶ κατέσχε. λέγεται δὲ τῇ προτέρᾳ νυκτὶ τῆς διαβάσεως ὄναρ ἰδεῖν ἔκθεσμον ἐδόκει γὰρ αὐτὸς τῇ ἑαυτοῦ μητρὶ μίγνυσθαι τὴν ἄρρητον μῖξιν.", "st": "Caes. 32.4"}, {"sp": "N", "t": "ἐπεὶ δὲ κατελήφθη τὸ Ἀρίμινον, ὥσπερ ἀνεῳγμένου τοῦ πολέμου πλατείαις πύλαις ἐπὶ πᾶσαν ὁμοῦ τὴν γῆν καὶ θάλασσαν, καὶ συγκεχυμένων ἅμα τοῖς ὅροις τῆς ἐπαρχίας τῶν νόμων τῆς πόλεως, οὐκ ἄνδρας ἄν τις ᾠήθη καὶ γυναῖκας, ὥσπερ ἄλλοτε, σὺν ἐκπλήξει διαφοιτᾶν τῆς Ἰταλίας, ἀλλὰ τὰς πόλεις αὐτὰς ἀνισταμένας φυγῇ διαφέρεσθαι δι’ ἀλλήλων, τὴν δὲ Ῥώμην ὥσπερ ὑπὸ ῥευμάτων πιμπλαμένην φυγαῖς τῶν πέριξ δήμων καὶ μεταστάσεσιν, οὔτε ἄρχοντι πεῖσαι ῥᾳδίαν οὖσαν οὔτε λόγῳ καθεκτήν, ἐν πολλῷ κλύδωνι καὶ σάλῳ μικρὸν ἀπολιπεῖν αὐτὴν ὑφ’ αὑτῆς ἀνατετράφθαι. πάθη γὰρ ἀντίπαλα καὶ βίαια κατεῖχε κινήματα πάντα τόπον. οὔτε γὰρ τὸ χαῖρον ἡσυχίαν ἦγεν, ἀλλὰ τῷ δεδοικότι καὶ λυπουμένῳ κατὰ πολλὰ συμπῖπτον ἐν μεγάλῃ πόλει καὶ θρασυνόμενον ὑπὲρ τοῦ μέλλοντος δι’ ἐρίδων ἦν, αὐτόν τε Πομπήϊον ἐκπεπληγμένον ἄλλος ἀλλαχόθεν ἐτάραττε, τοῖς μὲν, ὡς ηὔξησε Καίσαρα καθ’ ἑαυτοῦ καὶ τῆς ἡγεμονίας, εὐθύνας ὑπέχοντα, τῶν δέ, ὅτι παρείκοντα καὶ προτεινόμενον εὐγνώμονας διαλύσεις ἐφῆκε τοῖς περὶ Λέντλον ὑβρίσαι, κατηγορούντων. Φαώνιος δὲ αὐτόν ἐκέλευε τῷ ποδὶ κτυπεῖν τὴν γῆν, ἐπεὶ μεγαληγορῶν ποτε πρὸς τὴν σύγκλητον οὐδὲν εἴα πολυπραγμονεῖν οὐδὲ φροντίζειν ἐκείνους τῆς ἐπὶ τὸν πόλεμον παρασκευῆς· αὐτὸς γὰρ, ὅταν ἐπίῃ, κρούσας τὸ ἔδαφος τῷ ποδὶ στρατευμάτων ἐμπλήσειν τὴν Ἰταλίαν.", "st": "Caes. 33.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ τότε πλήθει δυνάμεως ὑπερέβαλλεν ὁ Πομπήϊος τὴν Καίσαρος· εἴασε δ’ οὐδεὶς τὸν ἄνδρα χρήσασθαι τοῖς ἑαυτοῦ λογισμοῖς, ἀλλὰ ὑπ’ ἀγγελμάτων πολλῶν καὶ ψευδῶν καὶ φόβων, ὡς ἐφεστῶτος ἤδη τοῦ πολέμου καὶ πάντα κατέχοντος, εἴξας καὶ συνεκκρουσθεὶς τῇ πάντων φορᾷ ψηφίζεται ταραχὴν ὁρᾶν, καὶ τὴν πόλιν ἐξέλιπε κελεύσας ἕπεσθαι τὴν γερουσίαν, καὶ μηδένα μένειν τῶν πρὸ τῆς τυραννίδος ᾑρημένων τὴν πατρίδα καὶ τὴν ἐλευθερίαν.", "st": "Caes. 33.6"}, {"sp": "N", "t": "οἱ μὲν οὖν ὕπατοι μηδὲ ἃ νόμος ἐστὶ πρὸ ἐξόδου θύσαντες ἔφυγον ἔφευγον δὲ καί τῶν βουλευτῶν οἱ πλεῖστοι, τρόπον τινὰ δι’ ἁρπαγῆς ἀπὸ τῶν ἰδίων ὅ τι τύχοιεν ὥσπερ ἀλλοτρίων λαμβάνοντες, εἰσὶ δὲ οἳ καί σφόδρα τὰ Καίσαρος ᾑρημένοι πρότερον ἐξέπεσον ὑπὸ θάμβους τότε τῶν λογισμῶν καί συμπαρηνέχθησαν οὐδὲν δεόμενοι τῷ ῥεύματι τῆς φορᾶς ἐκείνης. οἰκτρότατον δὲ τὸ θέαμα τῆς πόλεως ἦν, ἐπιφερομένου τοσούτου χειμῶνος, ὥσπερ νεὼς ὑπὸ κυβερνητῶν ἀπαγορευόντων πρὸς τὸ συντυχὸν ἐκπεσεῖν κομιζομένης. ἀλλὰ καίπερ οὕτω τῆς μεταστάσεως οἰκτρᾶς οὔσης, τὴν μὲν φυγὴν οἱ ἄνθρωποι πατρίδα διὰ Πομπήϊον ἡγοῦντο, τὴν δὲ Ῥώμην ὡς Καίσαρος στρατόπεδον ἐξέλειπον· ὅπου καί Λαβιηνός, ἀνὴρ ἐν τοῖς μάλιστα φίλοις Καίσαρος καί πρεσβευτὴς γεγονὼς καί συνηγωνισμένος ἐν πᾶσι προθυμότατα τοῖς Κελτικοῖς πολέμοις, τότ’ ἐκεῖνον ἀποδρὰς ἀφίκετο πρὸς Πομπήϊον.", "st": "Caes. 34.1"}, {"sp": "N", "t": "ἀλλὰ τούτῳ μὲν καί τὰ χρήματα καί τὰς ἀποσκευὰς ἀπέπεμψεν ὁ Καῖσαρ Δομετίῳ δὲ ἡγουμένῳ σπειρῶν τριάκοντα καί κατέχοντι Κορφίνιον ἐπελθὼν παρεστρατοπέδευσεν. ὁ δὲ ἀπογνοὺς τὰ καθ’ ἑαυτόν ᾔτησε τὸν ἰατρὸν οἰκέτην ὄντα φάρμακον καί λαβὼν τὸ δοθὲν ἔπιεν ὡς τεθνηξόμενος. μετ’ ὀλίγον δὲ ἀκούσας τὸν Καίσαρα θαυμαστῇ τινι φιλανθρωπίᾳ χρῆσθαι πρὸς τοὺς ἑαλωκότας, αὐτὸς αὑτὸν ἀπεθρήνει καί τὴν ὀξύτητα τοῦ βουλεύματος ᾐτιᾶτο. τοῦ δ’ ἰατροῦ θαρρύναντος αὐτόν, ὡς ὑπνωτικόν, οὐ θανάσιμον, πεπωκότα, περιχαρὴς ἀναστὰς ἀπῄει πρὸς Καίσαρα, καί λαβὼν δεξιάν αὖθις διεξέπεσε πρὸς Πομπήϊον. ταῦτα εἰς τὴν Ῥώμην ἀπαγγελλόμενα τοὺς ἀνθρώπους ἡδίους ἐποίει, καί τινες φυγόντες ἀνέστρεψαν.", "st": "Caes. 34.1b"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ τήν τε Τοῦ Δομετίου στρατιὰν παρέλαβε καί τοὺς ἄλλους, ὅσους ἐν ταῖς πόλεσι Πομπηΐῳ στρατολογουμένους ἔφθασε καταλαβών. πολὺς δὲ γεγονὼς ἤδη καί φοβερός ἐπ’ αὐτὸν ἤλαυνε Πομπήϊον. ὁ δὲ οὐκ ἐδέξατο τήν ἔφοδον, ἀλλ’ εἰς Βρεντέσιον φυγών τοὺς μὲν ὑπάτους πρότερον ἔστειλε μετὰ δυνάμεως εἰς Δυρράχιον, αὐτὸς δὲ ὀλίγον ὕστερον ἐπελθόντος Καίσαρος ἐξέπλευσεν, ὡς ἐν τοῖς περὶ ἐκείνου γραφησομένοις τὰ καθ’ ἕκαστον δηλωθήσεται.", "st": "Caes. 35.1"}, {"sp": "N", "t": "Καίσαρι δὲ βουλομένῳ μὲν εὐθὺς διώκειν ἀπορία νεῶν ἦν εἰς δὲ τήν Ῥώμην ἀνέστρεψε, γεγονὼς ἐν ἡμέραις ἑξήκοντα πάσης ἀναιμωτὶ τῆς Ἰταλίας κύριος.ἐπεὶ δὲ καί τήν πόλιν εὗρε μᾶλλον ἢ προσεδόκα καθεστῶσαν καί τῶν ἀπὸ βουλῆς ἐν αὐτῇ συχνούς, τούτοις μὲν ἐπιεικῆ καί δημοτικὰ διελέχθη, παρακαλῶν αὐτοὺς καί πρὸς Πομπήϊον ἀποστέλλειν ἄνδρας ἐπὶ συμβάσεσι πρεπούσαις· ὑπήκουσε δ’ οὐδείς, εἴτε φοβούμενοι Πομπήϊον ἐγκαταλελειμμένον, εἴτε μὴ νομίζοντες οὕτω Καίσαρα φρονεῖν, ἀλλ’ εὐπρεπείᾳ λόγων χρῆσθαι. τοῦ δὲ δημάρχου Μετέλλου κωλύοντος αὐτὸν ἐκ τῶν ἀποθέτων χρήματα λαμβάνειν καί νόμους τινὰς προφέροντος, οὐκ ἔφη τὸν αὐτὸν ὅπλων καί νόμων καιρὸν εἶναι· σὺ δὲ εἰ τοῖς πραττομένοις δυσκολαίνεις, νῦν μὲν ἐκποδὼν ἄπιθι· παρρησίας γὰρ οὐ δεῖται πόλεμος ὅταν δὲ κατάθωμαι τὰ ὅπλα συμβάσεων γενομένων, τότε παριὼν δημαγωγήσεις, καὶ ταῦτα ἔφη, λέγω τῶν ἐμαυτοῦ δικαίων ὑφιέμενος ἐμὸς γὰρ εἰ καί σὺ καί πάντες ὅσους εἴληφα τῶν πρὸς ἐμὲ στασιασάντων. ταῦτα πρὸς τὸν Μέτελλον εἰπών ἐβάδιζε πρὸς τὰς θύρας τοῦ ταμιείου, μὴ φαινομένων δὲ τῶν κλειδῶν χαλκεῖς μεταπεμψάμενος ἐκκόπτειν ἐκέλευεν αὖθις δὲ ἐνισταμένου τοῦ Μετέλλου καί τινων ἐπαινούντων, διατεινάμενος ἠπείλησεν ἀποκτενεῖν αὐτόν, εἰ μὴ παύσαιτο παρενοχλῶν. καί τοῦτο, ἔφη, μειράκιον, οὐκ ἀγνοεῖς ὅτι μοι δυσκολώτερον ἦν εἰπεῖν ἢ πρᾶξαι οὗτος ὁ λόγος τότε καί Μέτελλον ἀπελθεῖν ἐποίησε καταδείσαντα καί τὰ ἄλλα ῥᾳδίως αὐτῷ καί ταχέως ὑπηρετεῖσθαι πρὸς τὸν πόλεμον.", "st": "Caes. 35.4"}, {"sp": "N", "t": "ἐστράτευε δ’ εἰς Ἰβηρίαν πρότερον ἐγνωκὼς τοὺς περὶ Ἀφράνιον καὶ Βάρρωνα Πομπηΐου πρεσβευτὰς ἐκβαλεῖν, καὶ τὰς ἐκεῖ δυνάμεις καὶ τὰς ἐπαρχίας ὑφ’ αὑτῷ ποιησάμενος οὕτως ἐπὶ Πομπήϊον ἐλαύνειν, μηδένα κατὰ νώτου τῶν πολεμίων ὑπολειπόμενος. κινδυνεύσας δὲ καὶ τῷ σώματι πολλάκις κατ’ ἐνέδρας καὶ τῷ στρατῷ μάλιστα διὰ λιμόν, οὐκ ἀνῆκε πρότερον διώκων καὶ προκαλούμενος καὶ περιταφρεύων τοὺς ἄνδρας ἢ κύριος βίᾳ γενέσθαι τῶν στρατοπέδων καὶ τῶν δυνάμεων, οἱ δὲ ἡγεμόνες ᾤχοντο πρὸς Πομπήϊον φεύγοντες.", "st": "Caes. 36.1"}, {"sp": "N", "t": "ἐπανελθόντα δὲ εἰς Ῥώμην Καίσαρα Πείσων μὲν ὁ πενθερὸς παρεκάλει πρὸς Πομπήϊον ἀποστέλλειν ἄνδρας ὑπὲρ διαλύσεως, Ἰσαυρικὸς δὲ Καίσαρι χαριζόμενος ἀντεῖπεν. αἱρεθεὶς δὲ δικτάτωρ ὑπὸ τῆς βουλῆς φυγάδας τε κατήγαγε, καὶ τῶν ἐπὶ Σύλλα δυστυχησάντων τοὺς παῖδας ἐπιτίμους ἐποίησε, καὶ σεισαχθείᾳ τινὶ τόκων ἐκούφιζε τοὺς χρεωφειλέτας, ἄλλων τε τοιούτων ἥψατο πολιτευμάτων οὐ πολλῶν, ἀλλ’ ἐν ἡμέραις ἕνδεκα τὴν μὲν μοναρχίαν ἀπειπάμενος, ὕπατον δὲ ἀναδείξας ἑαυτὸν καὶ Σερουΐλιον Ἰσαυρικόν, εἴχετο τῆς στρατείας.", "st": "Caes. 37.1"}, {"sp": "N", "t": "καὶ τὰς μὲν ἄλλας δυνάμεις καθ’ ὁδὸν ἐπειγόμενος παρῆλθεν, ἱππεῖς δὲ ἔχων λογάδας ἑξακοσίους καὶ πέντε τάγματα, χειμῶνος ἐν τροπαῖς ὄντος, ἱσταμένου Ἰαννουαρίου μηνὸς οὗτος δ’ ἂν εἴη Ποσειδεὼν Ἀθηναίοις ἀφῆκεν εἰς τὸ πέλαγος καὶ διαβαλὼν τὸν Ἰόνιον Ὤρικον καὶ Ἀπολλωνίαν αἱρεῖ, τὰ δὲ πλοῖα πάλιν ἀπέπεμψεν εἰς Βρεντέσιον ἐπὶ τοὺς ὑστερήσαντας τῇ πορείᾳ στρατιώτας. οἱ δὲ ἄχρι μὲν καθ’ ὁδὸν ἦσαν, ἅτε δὴ καὶ παρηκμακότες ἤδη τοῖς σώμασι καὶ πρὸς τὰ πλήθη τῶν πολέμων ἀπειρηκότες, ἐν αἰτίαις εἶχον τὸν Καίσαρα· ποῖ δὴ καὶ πρὸς τί πέρας ἡμᾶς οὗτος ὁ ἀνὴρ καταθήσεται περιφέρων καὶ χρώμενος ὥσπερ ἀτρύτοις καὶ ἀψύχοις ἡμῖν; καὶ σίδηρος ἐξέκαμε πληγαῖς, καὶ θυρεοῦ τίς φειδώ ἐν χρόνῳ τοσούτῳ καὶ θώρακος. οὐδὲ ἀπὸ τῶν τραυμάτων ἄρα λογίζεται Καῖσαρ ὅτι θνητῶν μὲν ἄρχει, θνητὰ δὲ πεφύκαμεν πάσχειν καὶ ἀλγεῖν; ὥραν δὲ χειμῶνος καὶ πνεύματος ἐν θαλάττῃ καιρὸν οὐδὲ θεῷ βιάζεσθαι δυνατόν ἀλλ’ οὗτος παραβάλλεται καθάπερ οὐ διώκων πολεμίους, ἀλλὰ φεύγων. τοιαῦτα λέγοντες ἐπορεύοντο σχολαίως εἰς τὸ Βρεντέσιον. ὡς δὲ ἐλθόντες εὗρον ἀνηγμένον τὸν Καίσαρα, ταχὺ πάλιν αὖ μεταβαλόντες ἐκάκιζον ἑαυτούς προδότας ἀποκαλοῦντες τοῦ αὐτοκράτορος, ἐκάκιζον δὲ καὶ τοὺς ἡγεμόνας οὐκ ἐπιταχύναντας τὴν πορείαν. καθήμενοι δὲ ἐπὶ τῶν ἄκρων πρὸς τὸ πέλαγος καὶ τὴν Ἤπειρον ἀπεσκόπουν τὰς ναῦς ἐφ’ ὧν ἔμελλον περαιοῦσθαι πρὸς ἐκεῖνον.", "st": "Caes. 37.3"}, {"sp": "N", "t": "ἐν δὲ Ἀπολλωνίᾳ Καῖσαρ οὐκ ἔχων ἀξιόμαχον τὴν μεθ’ ἑαυτοῦ δύναμιν, βραδυνούσης δὲ τῆς ἐκεῖθεν, ἀπορούμενος καὶ περιπαθῶν, δεινὸν ἐβούλευσε βούλευμα, κρύφα πάντων εἰς πλοῖον ἐμβὰς τὸ μέγεθος δωδεκάσκαλμον ἀναχθῆναι πρὸς τὸ Βρεντέσιον, τηλικούτοις στόλοις περιεχομένου τοῦ πελάγους ὑπὸ τῶν πολεμίων. νυκτὸς οὖν ἐσθῆτι θεράποντος ἐπικρυψάμενος ἐνέβη, καὶ καταβαλὼν ἑαυτὸν ὥς τινα τῶν παρημελημένων ἡσύχαζε, τοῦ δὲ Ἀῴου ποταμοῦ τὴν ναῦν ὑποφέροντος εἰς τὴν θάλασσαν, τὴν μὲν ἑωθινὴν αὔραν, ἣ παρεῖχε τηνικαῦτα περὶ τὰς ἐκβολὰς γαλήνην ἀπωθοῦσα πόρρω τὸ κῦμα, πολὺς πνεύσας πελάγιος διὰ νυκτὸς ἀπέσβεσε· πρὸς δὲ τὴν πλημμύραν τῆς θαλάττης καὶ τὴν ἀντίβασιν τοῦ κλύδωνος ἀγριαίνων ὁ ποταμός, καὶ τραχὺς ἅμα καὶ κτύπῳ μεγάλῳ καὶ σκληραῖς ἀνακοπτόμενος δίναις, ἄπορος ἦν βιασθῆναι τῷ κυβερνήτῃ καὶ μεταβαλεῖν ἐκέλευσε τοὺς ναύτας ὡς ἀποστρέψων τὸν πλοῦν. αἰσθόμενος δὲ ὁ Καῖσαρ ἀναδείκνυσιν ἑαυτόν, καὶ τοῦ κυβερνήτου λαβόμενος τῆς χειρός ἐκπεπληγμένου πρὸς τὴν ὄψιν, ἴθι, ἔφη, γενναῖε, τόλμα καὶ δέδιθι μηδέν· Καίσαρα φέρεις καὶ τὴν Καίσαρος Τύχην συμπλέουσαν. ἐλάθοντο τοῦ χειμῶνος οἱ ναῦται, καὶ ταῖς κώπαις ἐμφύντες ἐβιάζοντο πάσῃ προθυμίᾳ τὸν ποταμόν. ὡς δὲ ἦν ἄπορα, δεξάμενος πολλὴν θάλατταν καὶ κινδυνεύσας ἐν τῷ στόματι συνεχώρησε μάλα ἄκων τῷ κυβερνήτῃ μεταβαλεῖν. ἀνιόντι δὲ αὐτῷ κατὰ πλῆθος ἀπήντων οἱ στρατιῶται, πολλὰ μεμφόμενοι καὶ δυσπαθοῦντες εἰ μὴ πέπεισται καὶ σὺν αὐτοῖς μόνοις ἱκανὸς εἶναι νικᾶν, ἀλλ’ ἄχθεται καὶ παραβάλλεται διὰ τοὺς ἀπόντας ὡς ἀπιστῶν τοῖς παροῦσιν.", "st": "Caes. 38.1"}, {"sp": "N", "t": "ἐκ τούτου κατέπλευσε μὲν Ἀντώνιος ἀπὸ Βρεντεσίου τὰς δυνάμεις ἄγων θαρρήσας δὲ Καῖσαρ προὐκαλεῖτο Πομπήϊον ἱδρυμένον ἐν καλῷ καί χορηγούμενον ἔκ τε γῆς καί θαλάττης ἀποχρώντως, αὐτὸς ἐν οὐκ ἀφθόνοις διάγων κατ’ ἀρχάς, ὕστερον δὲ καί σφόδρα πιεσθεὶς ἀπορίᾳ τῶν ἀναγκαίων, ἀλλὰ ῥίζαν τινὰ κόπτοντες οἱ στρατιῶται καί γάλακτι φυρῶντες προσεφέροντο. καί ποτε καί διαπλάσαντες ἐξ αὐτῆς ἄρτους καί ταῖς προφυλακαῖς τῶν πολεμίων ἐπιδραμόντες ἔβαλλον εἴσω καί διερρίπτουν, ἐπιλέγοντες ὡς, ἄχρι ἂν ἡ γῆ τοιαύτας ἐκφέρῃ ῥίζας, οὐ παύσονται πολιορκοῦντες Πομπήϊον. ὁ μέντοι Πομπήϊος οὔτε τοὺς ἄρτους οὔτε τοὺς λόγους εἴα τούτους ἐκφέρεσθαι πρὸς τὸ πλῆθος. ἠθύμουν γὰρ οἱ στρατιῶται, τὴν ἀγριότητα καί τὴν ἀπάθειαν τῶν πολεμίων ὥσπερ θηρίων ὀρρωδοῦντες.", "st": "Caes. 39.1"}, {"sp": "N", "t": "ἀεὶ δέ τινες περὶ τοῖς ἐρύμασι τοῖς Πομπηΐου μάχαι σποράδες ἐγίγνοντο καί περιῆν πάσαις ὁ Καῖσαρ πλὴν μιᾶς, ἐν ᾗ τροπῆς μεγάλης γενομένης ἐκινδύνευσεν ἀπολέσαι τὸ στρατόπεδον. Πομπηΐου γὰρ προσβάλλοντος οὐδεὶς ἔμεινεν, ἀλλὰ καί τάφροι κατεπίμπλαντο κτεινομένων, καί περὶ τοῖς αὑτῶν χαρακώμασι καὶ περιτειχίσμασιν ἔπιπτον ἐλαυνόμενοι προτροπάδην. Καῖσαρ δὲ ὑπαντιάζων ἐπειρᾶτο μὲν ἀναστρέφειν τοὺς φεύγοντας, ἐπέραινε δὲ οὐδέν, ἀλλ’ ἐπιλαμβανομένου τῶν σημείων ἀπερρίπτουν οἱ κομίζοντες, ὥστε δύο καί τριάκοντα λαβεῖν τοὺς πολεμίους, αὐτὸς δὲ παρὰ μικρὸν ἦλθεν ἀποθανεῖν. ἀνδρὶ γὰρ μεγάλῳ καὶ ῥωμαλέῳ φεύγοντι παρ’ αὑτόν ἐπιβαλὼν τὴν χεῖρα μένειν ἐκέλευσε καί στρέφεσθαι πρὸς τοὺς πολεμίους ὁ δὲ μεστὸς ὢν ταραχῆς παρὰ τὸ δεινόν ἐπήρατο τὴν μάχαιραν ὡς καθιξόμενος, φθάνει δὲ ὁ τοῦ Καίσαρος ὑπασπιστὴς ἀποκόψας αὐτοῦ τὸν ὦμον. οὕτω δὲ ἀπέγνω τὰ καθ’ αὑτόν ὥστε, ἐπεὶ Πομπήϊος ὑπ’ εὐλαβείας τινὸς ἢ τύχης ἔργῳ μεγάλῳ τέλος οὐκ ἐπέθηκεν, ἀλλὰ καθείρξας εἰς τὸν χάρακα τοὺς φεύγοντας ἀνεχώρησεν, εἶπεν ἄρα πρὸς τοὺς φίλους ἀπιὼν ὁ Καῖσαρ, σήμερον ἂν ἡ νίκη παρὰ τοῖς πολεμίοις ἦν, εἰ τὸν νικῶντα εἶχον. αὐτὸς δὲ παρελθὼν εἰς τὴν σκηνὴν καὶ κατακλιθείς νύκτα πασῶν ἐκείνην ἀνιαροτάτην διήγαγεν ἐν ἀπόροις λογισμοῖς, ὡς κακῶς ἐστρατηγηκώς, ὅτι καί χώρας ἐπικειμένης βαθείας καὶ πόλεων εὐδαιμόνων τῶν Μακεδονικῶν καί Θετταλικῶν, ἐάσας ἐκεῖ περισπάσαι τὸν πόλεμον ἐνταῦθα καθέζοιτο πρὸς θαλάττῃ, ναυκρατούντων τῶν πολεμίων, πολιορκούμενος τοῖς ἀναγκαίοις μᾶλλον ἢ τοῖς ὅπλοις πολιορκῶν. οὕτω δὴ ῥιπτασθεὶς καί ἀδημονήσας πρὸς τὴν ἀπορίαν καί χαλεπότητα τῶν παρόντων ἀνίστη τὸν στρατόν, ἐπὶ Σκηπίωνα προάγειν εἰς Μακεδονίαν ἐγνωκώς ἢ γὰρ ἐπισπάσεσθαι Πομπήϊον ὅπου μαχεῖται μὴ χορηγούμενος ὁμοίως ἀπὸ τῆς θαλάττης, ἢ περιέσεσθαι μεμονωμένου Σκηπίωνος.", "st": "Caes. 39.4"}, {"sp": "N", "t": "τοῦτο τὴν Πομπηΐου στρατιὰν ἐπῆρε καί τοὺς περὶ αὐτὸν ἡγεμόνας ὡς ἡττημένου καί φεύγοντος ἔχεσθαι Καίσαρος. αὐτὸς μὲν γὰρ εὐλαβῶς εἶχε Πομπήϊος ἀναρρῖψαι μάχην περὶ τηλικούτων, καί παρεσκευασμένος ἄριστα πᾶσι πρὸς τὸν χρόνον ἠξίου τρίβειν καί μαραίνειν τὴν τῶν πολεμίων ἀκμήν βραχεῖαν οὖσαν. τὸ γάρ τοι μαχιμώτατον τῆς Καίσαρος δυνάμεως ἐμπειρίαν μὲν εἶχε καί τόλμαν ἀνυπόστατον πρὸς τοὺς ἀγῶνας, ἐν δὲ ταῖς πλάναις καί ταῖς στρατοπεδείαις καί τειχομαχοῦντες καί νυκτεγερτοῦντες ἐξέκαμνον ὑπὸ γήρως, καί βαρεῖς ἦσαν τοῖς σώμασι πρὸς τοὺς πόνους, δι’ ἀσθένειαν ἐγκαταλείποντες τὴν προθυμίαν. τότε δὲ καί τι νόσημα λοιμῶδες ἐλέχθη, τὴν ἀτοπίαν τῆς διαίτης ποιησάμενον ἀρχήν, ἐν τῇ στρατιᾷ περιφέρεσθαι τῇ Καίσαρος, καί τὸ μέγιστον, οὔτε χρήμασιν ἐρρωμένος οὔτε τροφῆς εὐπορῶν χρόνου βραχέος ἐδόκει περὶ αὑτῷ καταλυθήσεσθαι.", "st": "Caes. 40.1"}, {"sp": "N", "t": "διὰ ταῦτα Πομπήϊον μάχεσθαι μὴ βουλόμενον μόνος ἐπῄνει Κάτων φειδοῖ τῶν πολιτῶν ὅς γε καὶ τοὺς πεσόντας ἐν τῇ μάχῃ τῶν πολεμίων εἰς χιλίους τὸ πλῆθος γενομένους ἰδών ἀπῆλθεν ἐγκαλυψάμενος καὶ καταδακρύσας. οἱ δ’ ἄλλοι πάντες ἐκάκιζον τὸν Πομπήϊον φυγομαχοῦντα, καὶ παρώξυνον Ἀγαμέμνονα καὶ βασιλέα βασιλέων ἀποκαλοῦντες, ὡς δὴ μὴ βουλόμενον ἀποθέσθαι τὴν μοναρχίαν, ἀλλ’ ἀγαλλόμενον ἡγεμόνων τοσούτων ἐξηρτημένων αὐτοῦ καὶ φοιτώντων ἐπὶ σκηνήν. Φαώνιος δὲ τὴν Κάτωνος παρρησίαν ὑποποιούμενος, μανικῶς ἐσχετλίαζεν εἰ μηδὲ τῆτες ἔσται τῶν περὶ Τουσκλάνον ἀπολαῦσαι σύκων Διὰ τὴν Πομπηΐου φιλαρχίαν. Ἀφράνιος δὲ (νεωστὶ γὰρ ἐξ Ἰβηρίας ἀφῖκτο κακῶς στρατηγήσας) διαβαλλόμενος ἐπὶ χρήμασι προδοῦναι τὸν στρατόν, ἠρώτα Διὰ τί πρὸς τὸν ἔμπορον οὐ μάχονται τὸν ἐωνημένον παρ’ αὐτοῦ τὰς ἐπαρχίας, ἐκ τούτων ἁπάντων συνελαυνόμενος ἄκων εἰς μάχην ὁ Πομπήϊος ἐχώρει τὸν Καίσαρα διώκων.", "st": "Caes. 41.1"}, {"sp": "N", "t": "ὁ δὲ τὴν μὲν ἄλλην πορείαν χαλεπῶς ἤνυσεν, οὐδενὸς παρέχοντος ἀγοράν, ἀλλὰ πάντων καταφρονούντων Διὰ τὴν ἔναγχος ἧτταν ὡς δὲ εἷλε Γόμφους, Θεσσαλικὴν πόλιν, οὐ μόνον ἔθρεψε τὴν στρατιάν, ἀλλὰ καὶ τοῦ νοσήματος ἀπήλλαξε παραλόγως. ἀφθόνῳ γὰρ ἐνέτυχον οἴνῳ, καὶ πιόντες ἀνέδην, εἶτα χρώμενοι κώμοις καὶ βακχεύοντες ἀνὰ τὴν ὁδὸν, ἐκ μέθης διεκρούσαντο καὶ παρήλλαξαν τὸ πάθος, εἰς ἕξιν ἑτέραν τοῖς σώμασι μεταπεσόντες.", "st": "Caes. 41.6"}, {"sp": "N", "t": "ὡς δὲ εἰς τὴν Φαρσαλίαν ἐμβαλόντες ἀμφότεροι κατεστρατοπέδευσαν, ὁ μὲν Πομπήϊος αὖθις εἰς τὸν ἀρχαῖον ἀνεκρούετο λογισμὸν τὴν γνώμην, ἔτι καὶ φασμάτων οὐκ αἰσίων προσγενομένων καὶ καθ’ ὕπνον ὄψεως, ἐδόκει γὰρ ἑαυτὸν ὁρᾶν ἐν τῷ θεάτρῳ κροτούμενον ὑπὸ Ῥωμαίων, … οἱ δὲ περὶ αὐτὸν οὕτω θρασεῖς ἦσαν καὶ τὸ νίκημα ταῖς ἐλπίσι προειληφότες ὥστε φιλονεικεῖν ὑπὲρ τῆς Καίσαρος ἀρχιερωσύνης Δομίτιον καὶ Σπινθῆρα καὶ Σκηπίωνα διαμιλλωμένους ἀλλήλοις, πέμπειν δὲ πολλοὺς εἰς Ῥώμην μισθουμένους καὶ προκαταλαμβάνοντας οἰκίας ὑπατεύουσι καὶ στρατηγοῦσιν ἐπιτηδείους, ὡς εὐθὺς ἄρξοντες μετὰ τὸν πόλεμον. μάλιστα δὲ ἐσφάδαζον οἱ ἱππεῖς ἐπὶ τὴν μάχην ἠσκημένοι περιττῶς ὅπλων λαμπρότησι καὶ τροφαῖς ἵππων καὶ κάλλει σωμάτων, μέγα φρονοῦντες καὶ διὰ τὸ πλῆθος, ἑπτακισχίλιοι πρὸς χιλίους τοὺς Καίσαρος ὄντες. ἦν δὲ καὶ τὸ τῶν πεζῶν πλῆθος οὐκ ἀγχώμαλον, ἀλλὰ τετρακισμύριοι καὶ πεντακισχίλιοι παρετάττοντο δισμυρίοις καὶ δισχιλίοις.", "st": "Caes. 42.1"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ τοὺς στρατιώτας συναγαγών, καὶ προειπὼν ὡς δύο μὲν αὐτῷ τάγματα Κορφίνιος ἄγων ἐγγύς ἐστιν, ἄλλαι δὲ πεντεκαίδεκα σπεῖραι μετὰ Καληνοῦ κάθηνται περὶ Μέγαρα καὶ Ἀθήνας, ἠρώτησεν εἴτε βούλονται περιμένειν ἐκείνους, εἴτε αὐτοὶ διακινδυνεῦσαι καθ’ ἑαυτούς, οἱ δὲ ἀνεβόησαν δεόμενοι μὴ περιμένειν, ἀλλὰ μᾶλλον, ὅπως τάχιστα συνίασιν εἰς χεῖρας τοῖς πολεμίοις, τεχνάζεσθαι καὶ στρατηγεῖν. ποιουμένῳ δὲ καθαρμὸν αὐτῷ τῆς δυνάμεως καὶ θύσαντι τὸ πρῶτον ἱερεῖον εὐθὺς ὁ μάντις ἔφραζε τριῶν ἡμερῶν μάχῃ κριθήσεσθαι πρὸς τοὺς πολεμίους, ἐρομένου δὲ τοῦ Καίσαρος εἰ καὶ περὶ τοῦ τέλους ἐνορᾷ τι τοῖς ἱεροῖς εὔσημον, αὐτὸς ἄν, ἔφη, σὺ τοῦτο βέλτιον ὑποκρίναιο σαυτῷ. μεγάλην γὰρ οἱ θεοὶ μεταβολὴν καὶ μετάπτωσιν ἐπὶ τὰ ἐναντία τῶν καθεστώτων δηλοῦσιν, ὥστε εἰ μὲν εὖ πράττειν ἡγῇ σεαυτὸν ἐπὶ τῷ παρόντι, τὴν χείρονα προσδόκα τύχην εἰ δὲ κακῶς, τὴν ἀμείνονα. τῇ δὲ πρὸ τῆς μάχης νυκτὶ τὰς φυλακὰς ἐφοδεύοντος αὐτοῦ περὶ τὸ μεσονύκτιον ὤφθη λαμπὰς οὐρανίου πυρός, ἣν ὑπερενεχθεῖσαν τὸ Καίσαρος στρατόπεδον λαμπρὰν καὶ φλογώδη γενομένην ἔδοξεν εἰς τὸ Πομπηΐου καταπεσεῖν. ἑωθινῆς δὲ φυλακῆς καὶ πανικὸν τάραχον ᾔσθοντο γιγνόμενον παρὰ τοῖς πολεμίοις, οὐ μὴν μαχεῖσθαί γε κατ’ ἐκείνην προσεδόκα τὴν ἡμέραν, ἀλλὰ ὡς ἐπὶ Σκοτούσσης ὁδεύων ἀνεζεύγνυεν.", "st": "Caes. 43.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τῶν σκηνῶν ἤδη καταλελυμένων οἱ σκοποὶ προσίππευσαν αὑτῷ τοὺς πολεμίους ἐπὶ μάχῃ καταβαίνειν ἀπαγγέλλοντες περιχαρὴς γενόμενος καὶ προσευξάμενος τοῖς θεοῖς παρέταττε τὴν φάλαγγα, τὴν τάξιν τριπλῆν ποιῶν, καὶ τοῖς μὲν μέσοις ἐπέστησε Καλβῖνον Δομίτιον, τῶν δὲ κεράτων τὸ μὲν εἶχεν Ἀντώνιος, Αὐτὸς δὲ τὸ δεξιόν, ἐν τῷ δεκάτῳ τάγματι μέλλων μάχεσθαι. κατὰ τοῦτο δὲ τοὺς τῶν πολεμίων ἱππεῖς ἀντιπαραταττομένους ὁρῶν, καὶ δεδοικὼς τὴν λαμπρότητα καὶ τὸ πλῆθος αὐτῶν, ἀπὸ τῆς ἐσχάτης τάξεως ἀδήλως ἐκέλευσε περιελθεῖν πρὸς ἑαυτὸν ἓξ σπείρας καὶ κατόπιν ἔστησε τοῦ δεξιοῦ, διδάξας ἃ χρὴ ποιεῖν ὅταν οἱ τῶν πολεμίων ἱππεῖς προσφέρωνται. Πομπήϊος δὲ τὸ μὲν Αὐτὸς εἶχε τῶν κεράτων, τὸ δ’ εὐώνυμον Δομίτιος, τοῦ δὲ μέσου Σκηπίων ἦρχεν ὁ πενθερός. οἱ δὲ ἱππεῖς ἅπαντες ἐπὶ τὸ ἀριστερὸν ἔβρισαν ὡς τὸ δεξιὸν κυκλωσόμενοι τῶν πολεμίων καὶ λαμπρὰν περὶ αὐτὸν τὸν ἡγεμόνα ποιησόμενοι τροπήν οὐδὲν γὰρ ἀνθέξειν βάθος ὁπλιτικῆς φάλαγγος, ἀλλὰ συντρίψεσθαι καὶ καταρράξεσθαι πάντα τοῖς ἐναντίοις ἐπιβολῆς ἅμα τοσούτων ἱππέων γενομένης.", "st": "Caes. 44.1"}, {"sp": "N", "t": "ἐπεὶ δὲ σημαίνειν ἔμελλον ἀμφότεροι τὴν ἔφοδον, Πομπήϊος μὲν ἐκέλευσε τοὺς ὁπλίτας ἑστῶτας ἐν προβολῇ καὶ μένοντας ἀραρότως δέχεσθαι τὴν ἐπιδρομὴν τῶν πολεμίων, μέχρι ἂν ὑσσοῦ βολῆς ἐντὸς γένωνται. Καῖσαρ δὲ καὶ περὶ τοῦτο διαμαρτεῖν φησιν αὐτόν, ἀγνοήσαντα τὴν μετὰ δρόμου καὶ φορᾶς ἐν ἀρχῇ γινομένην σύρραξιν, ὡς ἔν τε ταῖς πληγαῖς βίαν προστίθησι καὶ συνεκκαίει τὸν θυμὸν ἐκ πάντων ἀναρριπιζόμενον. αὐτὸς δὲ κινεῖν τὴν φάλαγγα μέλλων καὶ προϊὼν ἐπ’ ἔργον ἤδη πρῶτον ὁρᾷ τῶν ταξιάρχων ἄνδρα πιστὸν αὐτῷ καὶ πολέμων ἔμπειρον, ἐπιθαρσύνοντα τοὺς ὑφ’ αὑτῷ καὶ προκαλούμενον εἰς ἅμιλλαν ἀλκῆς, τοῦτον ὀνομαστὶ προσαγορεύσας, τί ἐλπίζομεν, εἶπεν, ὦ Γάϊε Κρασσίνιε, καὶ πῶς τι θάρσους ἔχομεν; ὁ δὲ Κρασσίνιος ἐκτείνας τὴν δεξιὰν καὶ μέγα βοήσας, νικήσομεν, ἔφη, λαμπρῶς, ὦ Καῖσαρ ἐμὲ δὲ ἢ ζῶντα τήμερον ἢ τεθνηκότα ἐπαινέσεις. ταῦτα εἰπὼν πρῶτος ἐμβάλλει τοῖς πολεμίοις δρόμῳ, συνεπισπασάμενος τοὺς περὶ ἑαυτὸν ἑκατὸν καὶ εἴκοσι στρατιώτας, διακόψας δὲ τοὺς πρώτους καὶ πρόσω χωρῶν φόνῳ πολλῷ καὶ βιαζόμενος ἀνακόπτεται ξίφει πληγεὶς διὰ τοῦ στόματος, ὥστε καὶ τὴν αἰχμὴν ὑπὲρ τὸ ἰνίον ἀνασχεῖν.", "st": "Caes. 44.7"}, {"sp": "N", "t": "οὕτω δὲ τῶν πεζῶν κατὰ τὸ μέσον συρραγέντων καὶ μαχομένων, ἀπὸ τοῦ κέρατος οἱ Πομπηΐου ἱππεῖς σοβαρῶς ἐπήλαυνον εἰς κύκλωσιν τοῦ δεξιοῦ τὰς ἴλας ἀναχεόμενοι· καὶ πρὶν ἢ προσβαλεῖν αὐτούς ἐκτρέχουσιν αἱ σπεῖραι παρὰ Καίσαρος, οὐχ, ὥσπερ εἰώθεσαν, ἀκοντίσμασι χρώμενοι τοῖς ὑσσοῖς, οὐδὲ μηροὺς παίοντες ἐκ χειρὸς ἢ κνήμας τῶν πολεμίων, ἀλλὰ τῶν ὄψεων ἐφιέμενοι καὶ τὰ πρόσωπα συντιτρώσκοντες, ὑπὸ Καίσαρος δεδιδαγμένοι τοῦτο ποιεῖν, ἐλπίζοντος ἄνδρας οὐ πολλὰ πολέμοις οὐδὲ τραύμασιν ὡμιληκότας, νέους δὲ καὶ κομῶντας ἐπὶ κάλλει καὶ ὥρᾳ, μάλιστα τὰς τοιαύτας πληγὰς ὑπόψεσθαι καὶ μὴ μενεῖν, τὸν ἐν τῷ παρόντι κίνδυνον ἅμα καὶ τὴν αὖθις αἰσχύνην δεδοικότας. ὃ δὴ καὶ συνέβαινεν οὐ γὰρ ἠνείχοντο τῶν ὑσσῶν ἀναφερομένων, οὐδὲ ἐτόλμων ἐν ὀφθαλμοῖς τὸν σίδηρον ὁρῶντες, ἀλλ’ ἀπεστρέφοντο καὶ συνεκαλύπτοντο φειδόμενοι τῶν προσώπων καὶ τέλος οὕτως ταράξαντας ἑαυτοὺς ἐτράποντο φεύγειν αἴσχιστα, λυμηνάμενοι τὸ σύμπαν εὐθὺς γὰρ οἱ μὲν νενικηκότες τούτους ἐκυκλοῦντο τοὺς πεζοὺς καὶ κατὰ νώτου προσπίπτοντες ἔκοπτον.", "st": "Caes. 45.1"}, {"sp": "N", "t": "Πομπήϊος δὲ ὡς κατεῖδεν ἀπὸ θατέρου τοὺς ἱππεῖς φυγῇ σκεδασθέντας, οὐκέτι ἦν ὁ αὐτὸς οὐδ’ ἐμέμνητο Πομπήϊος ὢν Μᾶγνος, ἀλλ’ ὑπὸ θεοῦ μάλιστα βλαπτομένῳ τὴν γνώμην ἐοικώς ἄφθογγος ᾤχετο ἀπιὼν ἐπὶ σκηνήν, καὶ καθεζόμενος ἐκαραδόκει τὸ μέλλον, ἄχρι οὗ τροπῆς ἁπάντων γενομένης ἐπέβαινον οἱ πολέμιοι τοῦ χάρακος καὶ διεμάχοντο πρὸς τοὺς φυλάττοντας. τότε δὲ ὥσπερ ἔννους γενόμενος, καὶ ταύτην μόνην, ὥς φασι, φωνὴν ἀφεὶς, οὐκοῦν καὶ ἐπὶ τὴν παρεμβολήν; ἀπεδύσατο μὲν τὴν ἐναγώνιον καὶ στρατηγικὴν ἐσθῆτα, φεύγοντι δὲ πρέπουσαν μεταλαβὼν ὑπεξῆλθεν. ἀλλ’ οὗτος μὲν οἵαις ὕστερον χρησάμενος τύχαις ὅπως τε παραδοὺς ἑαυτὸν τοῖς Αἰγυπτίοις ἀνδράσιν ἀνῃρέθη, δηλοῦμεν ἐν τοῖς περὶ ἐκείνου γράμμασιν.", "st": "Caes. 45.7"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ ὡς ἐν τῷ χάρακι τοῦ Πομπηΐου γενόμενος τούς τε κειμένους νεκροὺς ἤδη τῶν πολεμίων εἶδε καὶ τούς ἔτι κτεινομένους, εἶπεν ἄρα στενάξας τοῦτο ἐβουλήθησαν, εἰς τοῦτό με ἀνάγκης ὑπηγάγοντο, ἵνα Γάϊος Καῖσαρ ὁ μεγίστους πολέμους κατορθώσας, εἰ προηκάμην τὰ στρατεύματα, κἂν κατεδικάσθην. ταῦτά φησι Πολλίων Ἀσίννιος τὰ ῥήματα Ῥωμαϊστὶ μὲν ἀναφθέγξασθαι τὸν Καίσαρα παρὰ τὸν τότε καιρόν, Ἑλληνιστὶ δ’ ὑπ’ αὑτοῦ γεγράφθαι τῶν δὲ ἀποθανόντων τούς πλείστους οἰκέτας γενέσθαι περὶ τὴν κατάληψιν τοῦ χάρακος ἀναιρεθέντας, στρατιώτας δὲ μὴ πλείους ἑξακισχιλίων πεσεῖν, τῶν δὲ ζώντων ἁλόντων κατέμιξε τούς πλείστους ὁ Καῖσαρ εἰς τὰ τάγματα· πολλοῖς δὲ καὶ τῶν ἐπιφανῶν ἄδειαν ἔδωκεν, ὧν καὶ Βροῦτος ἦν ὁ κτείνας αὐτὸν ὕστερον, ἐφ’ ᾧ λέγεται μὴ φαινομένῳ μὲν ἀγωνιᾶσαι, σωθέντος δὲ καὶ παραγενομένου πρὸς αὐτὸν ἡσθῆναι διαφερόντως.", "st": "Caes. 46.1"}, {"sp": "N", "t": "σημείων δὲ πολλῶν γενομένων τῆς Νίκης ἐπιφανέστατον ἱστορεῖται τὸ περὶ Τράλλεις. ἐν γὰρ ἱερῷ Νίκης ἀνδριὰς εἱστήκει Καίσαρος, καὶ τὸ περὶ αὐτῷ χωρίον αὐτό τε στερεὸν φύσει καὶ λίθῳ σκληρῷ κατεστρωμένον ἦν ἄνωθεν ἐκ τούτου λέγουσιν ἀνατεῖλαι φοίνικα παρὰ τὴν βάσιν τοῦ ἀνδριάντος. ἐν δὲ Παταβίῳ Γάϊος Κορνήλιος, ἀνὴρ εὐδόκιμος ἐπὶ μαντικῇ, Λιβίου τοῦ συγγραφέως πολίτης καὶ γνώριμος, ἐτύγχανεν ἐπ’ οἰωνοῖς καθήμενος ἐκείνην τὴν ἡμέραν. καὶ πρῶτον μέν, ὡς Λίβιός φησι, τὸν καιρὸν ἔγνω τῆς μάχης, καὶ πρὸς τοὺς παρόντας εἶπεν ὅτι καὶ δὴ περαίνεται τὸ χρῆμα καὶ συνίασιν εἰς ἔργον οἱ ἄνδρες, αὖθις δὲ πρὸς τῇ θέᾳ γενόμενος καὶ τὰ σημεῖα κατιδών ἀνήλατο μετ’ ἐνθουσιασμοῦ βοῶν, νικᾷς, ὦ Καῖσαρ ἐκπλαγέντων δὲ τῶν παρατυχόντων περιελὼν τὸν στέφανον ἀπὸ τῆς κεφαλῆς ἐνωμότως ἔφη μὴ πρὶν ἐπιθήσεσθαι πάλιν ἢ τῇ τέχνῃ μαρτυρῆσαι τὸ ἔργον, ταῦτα μὲν οὖν ὁ Λίβιος οὕτως γενέσθαι καταβεβαιοῦται.", "st": "Caes. 47.1"}, {"sp": "N", "t": "Καῖσαρ δὲ τῷ Θετταλῶν ἔθνει τὴν ἐλευθερίαν ἀναθεὶς νικητήριον ἐδίωκε Πομπήϊον· ἁψάμενος δὲ τῆς Ἀσίας Κνιδίους τε Θεοπόμπῳ τῷ συναγαγόντι τοὺς μύθους χαριζόμενος ἠλευθέρωσε, καὶ πᾶσι τοῖς τὴν Ἀσίαν κατοικοῦσι τὸ τρίτον τῶν φόρων ἀνῆκεν. εἴς δὲ Ἀλεξάνδρειαν ἐπὶ Πομπηΐῳ τεθνηκότι καταχθείς Θεόδοτον μὲν ἀπεστράφη τὴν Πομπηΐου κεφαλὴν προσφέροντα, τὴν δὲ σφραγῖδα δεξάμενος τοῦ ἀνδρὸς κατεδάκρυσεν ὅσοι δὲ τῶν ἑταίρων αὐτοῦ καὶ συνήθων πλανώμενοι κατὰ τὴν χώραν ἑαλώκεσαν ὑπὸ τοῦ βασιλέως, πάντας εὐεργέτησε καὶ προσηγάγετο. τοῖς δὲ φίλοις εἴς Ῥώμην ἔγραφεν ὅτι τῆς νίκης ἀπολαύοι τοῦτο μέγιστον καὶ ἥδιστον, τὸ σῴζειν τινὰς ἀεὶ τῶν πεπολεμηκότων πολιτῶν αὐτῷ.", "st": "Caes. 48.1"}, {"sp": "N", "t": "τὸν δὲ αὐτόθι πόλεμον οἱ μὲν οὐκ ἀναγκαῖον. ἀλλ’ ἔρωτι Κλεοπάτρας ἄδοξον αὐτῷ καὶ κινδυνώδη γενέσθαι λέγουσιν, οἱ δὲ τοὺς βασιλικοὺς αἰτιῶνται, καὶ μάλιστα Τὸν εὐνοῦχον Ποθεινόν, ὃς πλεῖστον δυνάμενος καὶ Πομπήϊον μὲν ἀνῃρηκὼς ἔναγχος, ἐκβεβληκὼς δὲ Κλεοπάτραν, κρύφα μὲν ἐπεβούλευε τῷ Καίσαρι· καὶ διὰ τοῦτό φασιν αὐτὸν ἀρξάμενον ἔκτοτε διανυκτερεύειν ἐν τοῖς πότοις ἕνεκα φυλακῆς τοῦ σώματος· φανερῶς δὲ οὐκ ἦν ἀνεκτός ἐπίφθονα πολλὰ καὶ πρὸς ὕβριν εἴς Τὸν Καίσαρα λέγων καὶ πράττων. τοὺς μὲν γὰρ στρατιώτας Τὸν κάκιστον μετρουμένους καὶ παλαιότατον σῖτον ἐκέλευσεν ἀνέχεσθαι καὶ στέργειν, ἐσθίοντας τὰ ἀλλότρια, πρὸς δὲ τὰ δεῖπνα σκεύεσιν ἐχρῆτο ξυλίνοις καὶ κεραμεοῖς, ὡς τὰ χρυσᾶ καὶ ἀργυρᾶ πάντα Καίσαρος ἔχοντος εἴς τι χρέος, ὤφειλε γὰρ ὁ τοῦ βασιλεύοντος τότε πατὴρ Καίσαρι χιλίας ἑπτακοσίας πεντήκοντα μυριάδας, ὧν τὰς μὲν ἄλλας ἀνῆκε τοῖς παισὶν αὐτοῦ πρότερον ὁ Καῖσαρ, τὰς δὲ χιλίας ἠξίου τότε λαβὼν διαθρέψαι τὸ στράτευμα. τοῦ δὲ Ποθεινοῦ νῦν μὲν αὐτὸν ἀπιέναι καὶ τῶν μεγάλων ἔχεσθαι πραγμάτων κελεύοντος, ὕστερον δὲ κομιεῖσθαι μετὰ χάριτος, εἰπὼν ὡς Αἰγυπτίων ἐλάχιστα δέοιτο συμβούλων, κρύφα τὴν Κλεοπάτραν ἀπὸ τῆς χώρας μετεπέμπετο.", "st": "Caes. 48.5"}, {"sp": "N", "t": "κἀκείνη παραλαβοῦσα τῶν φίλων Ἀπολλόδωρον τὸν Σικελιώτην μόνον, εἰς ἀκάτιον μικρὸν ἐμβᾶσα τοῖς μὲν βασιλείοις προσέσχεν ἤδη συσκοτάζοντος· ἀπόρου δὲ τοῦ λαθεῖν ὄντος ἄλλως, ἡ μὲν εἰς στρωματόδεσμον ἐνδῦσα προτείνει μακρὰν ἑαυτήν, ὁ δὲ Ἀπολλόδωρος ἱμάντι συνδήσας τὸν στρωματόδεσμον εἰσκομίζει διὰ θυρῶν πρὸς τὸν Καίσαρα, καὶ τούτῳ τε πρώτῳ λέγεται τῷ τεχνήματι τῆς Κλεοπάτρας ἁλῶναι, λαμυρᾶς φανείσης, καὶ τῆς ἄλλης ὁμιλίας καὶ χάριτος ἥττων γενόμενος διαλλάξαι πρὸς τὸν ἀδελφὸν ὡς συμβασιλεύσουσαν. ἔπειτα δ’ ἐν ταῖς διαλλαγαῖς ἑστιωμένων ἁπάντων οἰκέτης Καίσαρος κουρεύς, διὰ δειλίαν, ᾗ πάντας ἀνθρώπους ὑπερέβαλεν, οὐδὲν ἐῶν ἀνεξέταστον, ἀλλ’ ὠτακουστῶν καὶ πολυπραγμονῶν, συνῆκεν ἐπιβουλὴν Καίσαρι πραττομένην ὑπ’ Ἀχιλλᾶ τοῦ στρατηγοῦ καὶ Ποθεινοῦ τοῦ εὐνούχου. φωράσας δὲ ὁ Καῖσαρ φρουρὰν μὲν περιέστησε τῷ ἀνδρῶνι, τὸν δὲ Ποθεινὸν ἀνεῖλεν ὁ δὲ Ἀχιλλᾶς φυγὼν εἰς τὸ στρατόπεδον περιΐστησιν αὐτῷ βαρὺν καὶ δυσμεταχείριστον πόλεμον, ὀλιγοστῷ τοσαύτην ἀμυνομένῳ πόλιν καὶ δύναμιν. ἐν ᾧ πρῶτον μὲν ἐκινδύνευσεν ὕδατος ἀποκλεισθείς· αἱ γὰρ διώρυχες ἀπῳκοδομήθησαν ὑπὸ τῶν πολεμίων δεύτερον δὲ περικοπτόμενος τὸν στόλον ἠναγκάσθη διὰ πυρὸς ἀπώσασθαι τὸν κίνδυνον, ὃ καὶ τὴν μεγάλην βιβλιοθήκην ἐκ τῶν νεωρίων ἐπινεμόμενον διέφθειρε· τρίτον δὲ περὶ τῇ Φάρῳ μάχης συνεστώσης κατεπήδησε μὲν ἀπὸ τοῦ χώματος εἰς ἀκάτιον καὶ παρεβοήθει τοῖς ἀγωνιζομένοις, ἐπιπλεόντων δὲ πολλαχόθεν αὐτῷ τῶν Αἰγυπτίων ῥίψας ἑαυτὸν εἰς τὴν θάλασσαν ἀπενήξατο μόλις καὶ χαλεπῶς. ὅτε καὶ λέγεται βιβλίδια κρατῶν πολλὰ μὴ προέσθαι βαλλόμενος καὶ βαπτιζόμενος, ἀλλ’ ἀνέχων ὑπὲρ τῆς θαλάσσης τὰ βιβλίδια τῇ ἑτέρᾳ χειρὶ νήχεσθαι τὸ δὲ ἀκάτιον εὐθὺς ἐβυθίσθη. τέλος δέ, τοῦ βασιλέως πρὸς τοὺς πολεμίους ἀποχωρήσαντος, ἐπελθὼν καὶ συνάψας μάχην ἐνίκησε, πολλῶν πεσόντων αὐτοῦ τε τοῦ βασιλέως ἀφανοῦς γενομένου, καταλιπὼν δὲ τὴν Κλεοπάτραν βασιλεύουσαν Αἰγύπτου καὶ μικρὸν ὕστερον ἐξ αὐτοῦ τεκοῦσαν υἱόν, ὃν Ἀλεξανδρεῖς Καισαρίωνα προσηγόρευον, ὥρμησεν ἐπὶ Συρίας.", "st": "Caes. 49.1"}, {"sp": "N", "t": "κἀκεῖθεν ἐπιὼν τὴν Ἀσίαν ἐπυνθάνετο Δομίτιον μὲν ὑπὸ Φαρνάκου τοῦ Μιθριδάτου παιδὸς ἡττημένον ἐκ Πόντου πεφευγέναι σὺν ὀλίγοις, Φαρνάκην δὲ τῇ νίκῃ χρώμενον ἀπλήστως καὶ Βιθυνίαν ἔχοντα καὶ Καππαδοκίαν Ἀρμενίας ἐφίεσθαι τῆς μικρᾶς καλουμένης, καὶ πάντας ἀνιστάναι τοὺς ταύτῃ βασιλεῖς καὶ τετράρχας. εὐθὺς οὖν ἐπὶ τὸν ἄνδρα τρισὶν ἤλαυνε τάγμασι, καὶ περὶ πόλιν Ζῆλαν μάχην μεγάλην συνάψας αὐτὸν μὲν ἐξέβαλε τοῦ Πόντου φεύγοντα, τὴν δὲ στρατιὰν ἄρδην ἀνεῖλε. καὶ τῆς μάχης ταύτης τὴν ὀξύτητα καὶ τὸ τάχος ἀναγγέλλων εἰς Ῥώμην πρός τινα τῶν φίλων Ἀμάντιον ἔγραψε τρεῖς λέξεις ἦλθον, εἶδον, ἐνίκησα. Ῥωμαϊστὶ δὲ αἱ λέξεις εἰς ὅμοιον ἀπολήγουσαι σχῆμα ῥήματος οὐκ ἀπίθανον τὴν βραχυλογίαν ἔχουσιν.", "st": "Caes. 50.1"}, {"sp": "N", "t": "ἐκ τούτου διαβαλὼν εἰς Ἰταλίαν ἀνέβαινεν εἰς Ῥώμην, τοῦ μὲν ἐνιαυτοῦ καταστρέφοντος εἰς ὃν ᾕρητο δικτάτωρ τὸ δεύτερον, οὐδέποτε τῆς ἀρχῆς ἐκείνης πρότερον ἐνιαυσίου γενομένης· εἰς δὲ τοὐπιὸν ὕπατος ἀπεδείχθη, καὶ κακῶς ἤκουσεν ὅτι τῶν στρατιωτῶν στασιασάντων καὶ δύο στρατηγικοὺς ἄνδρας ἀνελόντων, Κοσκώνιον καὶ Γάλβαν, ἐπετίμησε μὲν αὐτοῖς τοσοῦτον ὅσον ἀντὶ στρατιωτῶν πολίτας προσαγορεῦσαι, χιλίας δὲ διένειμεν ἑκάστῳ δραχμὰς καὶ χώραν τῆς Ἰταλίας ἀπεκλήρωσε πολλήν. ἦν δὲ αὐτοῦ διαβολὴ καὶ ἡ Δολοβέλλα μανία καὶ ἡ Ἀμαντίου φιλαργυρία καὶ μεθύων Ἀντώνιος καὶ Κορφίνιος τὴν Πομπηΐου σκευωρούμενος οἰκίαν καὶ μετοικοδομῶν ὡς ἱκανὴν οὐκ οὖσαν. ἐπὶ τούτοις γὰρ ἐδυσφόρουν Ῥωμαῖοι. Καῖσαρ δὲ διὰ τὴν ὑπόθεσιν τῆς πολιτείας οὐκ ἀγνοῶν οὐδὲ βουλόμενος ἠναγκάζετο χρῆσθαι τοῖς ὑπουργοῦσι.", "st": "Caes. 51.1"}, {"sp": "N", "t": "τῶν δὲ περὶ Κάτωνα καὶ Σκηπίωνα μετὰ τὴν ἐν Φαρσάλῳ μάχην εἰς Λιβύην φυγόντων κἀκεῖ, τοῦ βασιλέως Ἰόβα βοηθοῦντος αὐτοῖς, ἠθροικότων δυνάμεις ἀξιολόγους, ἔγνω στρατεύειν ὁ Καῖσαρ ἐπ’ αὐτούς· καὶ περὶ τροπὰς χειμερινὰς διαβὰς εἰς Σικελίαν, καὶ βουλόμενος εὐθὺς ἀποκόψαι Τῶν περὶ αὐτὸν ἡγεμόνων ἅπασαν ἐλπίδα μελλήσεως καὶ διατριβῆς, ἐπὶ τοῦ κλύσματος ἔπηξε τὴν ἑαυτοῦ σκηνήν καὶ γενομένου πνεύματος ἐμβὰς ἀνήχθη μετὰ τρισχιλίων πεζῶν καὶ ἱππέων ὀλίγων. ἀποβιβάσας δὲ τούτους λαθών ἀνήχθη πάλιν, ὑπὲρ τῆς μείζονος ὀρρωδῶν δυνάμεως·", "st": "Caes. 52.1"}, {"sp": "N", "t": "καὶ κατὰ θάλατταν οὖσιν ἤδη προστυχών κατήγαγεν ἅπαντας εἰς τὸ στρατόπεδον.πυνθανόμενος δὲ χρησμῷ τινι παλαιῷ θαρρεῖν τοὺς πολεμίους, ὡς προσῆκον ἀεὶ τῷ Σκηπιώνων γένει κρατεῖν ἐν Λιβύῃ, χαλεπὸν εἰπεῖν εἴτε φλαυρίζων ἐν παιδιᾷ τινι τὸν Σκηπίωνα στρατηγοῦντα τῶν πολεμίων, εἴτε καὶ σπουδῇ τὸν οἰωνὸν οἰκειούμενος, ἦν γὰρ καὶ παρ’ αὐτῷ τις ἄνθρωπος ἄλλως μὲν εὐκαταφρόνητος καὶ παρημελημένος, οἰκίας δὲ τῆς Ἀφρικανῶν Σκηπίων ἐκαλεῖτο Σαλλουστίων, τοῦτον ἐν ταῖς μάχαις προέταττεν ὥσπερ ἡγεμόνα τῆς στρατιᾶς, ἀναγκαζόμενος πολλάκις ἐξάπτεσθαι Τῶν πολεμίων καὶ φιλομαχεῖν. ἦν γὰρ οὔτε σῖτος τοῖς ἀνδράσιν ἄφθονος οὔτε ὑποζυγίοις χιλός, ἀλλὰ βρύοις ἠναγκάζοντο θαλαττίοις, ἀποπλυθείσης τῆς ἁλμυρίδος, ὀλίγην ἄγρωστιν ὥσπερ ἥδυσμα παραμιγνύντες ἐπάγειν τοὺς ἵππους, οἱ γὰρ Νομάδες ἐπιφαινόμενοι πολλοὶ καὶ ταχεῖς ἑκάστοτε κατεῖχον τὴν χώραν καί ποτε τῶν Καίσαρος ἱππέων σχολὴν ἀγόντων (ἔτυχε γὰρ αὐτοῖς ἀνὴρ Λίβυς ἐπιδεικνύμενος ὄρχησιν ἅμα καὶ μοναυλῶν θαύματος ἀξίως, οἱ δὲ τερπόμενοι καθῆντο τοῖς παισὶ τοὺς ἵππους ἐπιτρέψαντες), ἐξαίφνης περιελθόντες ἐμβάλλουσιν οἱ πολέμιοι, καὶ τοὺς μὲν αὐτοῦ κτείνουσι, τοῖς δὲ εἰς τὸ στρατόπεδον προτροπάδην ἐλαυνομένοις συνεισέπεσον. εἰ δὲ μὴ Καῖσαρ αὐτός, ἅμα δὲ Καίσαρι Πολλίων Ἀσίννιος βοηθοῦντες ἐκ τοῦ χάρακος ἔσχον τὴν φυγήν, διεπέπρακτ’ ἂν ὁ πόλεμος, ἔστι δ’ ὅτε καὶ καθ’ ἑτέραν μάχην ἐπλεονέκτησαν οἱ πολέμιοι συμπλοκῆς γενομένης, ἐν ᾗ Καῖσαρ τὸν ἀετοφόρον φεύγοντα λέγεται κατασχὼν ἐκ τοῦ αὐχένος ἀναστρέψαι καὶ εἰπεῖν ἐνταῦθα εἰσιν οἱ πολέμιοι.", "st": "Caes. 52.4"}, {"sp": "N", "t": "τούτοις μέντοι τοῖς προτερήμασιν ἐπήρθη Σκηπίων μάχῃ κριθῆναι καὶ καταλιπὼν χωρὶς μὲν Ἀφράνιον, χωρὶς δὲ Ἰόβαν δι’ ὀλίγου στρατοπεδεύοντας, αὐτὸς ἐτείχιζεν ὑπὲρ λίμνης ἔρυμα τῷ στρατοπέδῳ περὶ πόλιν Θάψον, ὡς εἴη πᾶσιν ἐπὶ τὴν μάχην ὁρμητήριον καὶ καταφυγή. πονουμένῳ δὲ αὐτῷ περὶ ταῦτα Καῖσαρ ὑλώδεις τόπους καὶ προσβολὰς ἀφράστους ἔχοντας ἀμηχάνῳ τάχει διελθὼν τοὺς μὲν ἐκυκλοῦτο, τοῖς δὲ προσέβαλλε κατὰ στόμα, τρεψάμενος δὲ τούτους ἐχρῆτο τῷ καιρῷ καὶ τῇ ῥύμῃ τῆς τύχης, ὑφ’ ἧς αὐτοβοεὶ μὲν ᾕρει τὸ Ἀφρανίου στρατόπεδον, αὐτοβοεὶ δὲ φεύγοντος Ἰόβα διεπόρθει τὸ τῶν Νομάδων ἡμέρας δὲ μιᾶς μέρει μικρῷ τριῶν στρατοπέδων ἐγκρατὴς γεγονὼς καὶ πεντακισμυρίους τῶν πολεμίων ἀνῃρηκώς οὐδὲ πεντήκοντα τῶν ἰδίων ἀπέβαλεν.", "st": "Caes. 53.1"}, {"sp": "N", "t": "οἱ μὲν ταῦτα περὶ τῆς μάχης ἐκείνης ἀναγγέλλουσιν· οἱ δὲ οὔ φασιν αὐτὸν ἐν τῷ ἔργῳ γενέσθαι, συντάττοντος δὲ τὴν στρατιὰν καὶ διακοσμοῦντος ἅψασθαι τὸ σύνηθες νόσημα· τὸν δὲ εὐθὺς αἰσθόμενον ἀρχομένου, πρὶν ἐκταράττεσθαι καὶ καταλαμβάνεσθαι παντάπασιν ὑπὸ τοῦ πάθους τὴν αἴσθησιν ἤδη σειομένην, εἴς τινα, τῶν πλησίον πύργων κομισθῆναι καὶ διαγαγεῖν ἐν ἡσυχίᾳ, τῶν δὲ πεφευγότων ἐκ τῆς μάχης ὑπατικῶν καὶ στρατηγικῶν ἀνδρῶν οἱ μὲν ἑαυτοὺς διέφθειραν ἁλισκόμενοι, συχνοὺς δὲ Καῖσαρ ἔκτεινεν ἁλόντας.", "st": "Caes. 53.5"}, {"sp": "N", "t": "Κάτωνα δὲ λαβεῖν ζῶντα φιλοτιμούμενος ἔσπευδε πρὸς Ἰτύκην ἐκείνην γὰρ παραφυλάττων τὴν πόλιν οὐ μετέσχε τοῦ ἀγῶνος, πυθόμενος δὲ ὡς ἑαυτὸν ὁ ἀνὴρ διεργάσαιτο, δῆλος μὲν ἦν δηχθείς, ἐφ’ ᾧ δὲ ἄδηλον. εἶπε δ’ οὖν ὦ Κάτων, φθονῶ σοι τοῦ θανάτου· καὶ γὰρ σύ μοι τῆς σωτηρίας ἐφθόνησας. ὁ μὲν οὖν μετὰ ταῦτα γραφεὶς ὑπ’ αὑτοῦ πρὸς Κάτωνα τεθνεῶτα λόγος οὐ δοκεῖ πρᾴως ἔχοντος οὐδὲ εὐδιαλλάκτως σημεῖον εἶναι. πῶς γὰρ ἂν ἐφείσατο ζῶντος εἰς ἀναίσθητον ἐκχέας ὀργὴν τοσαύτην; τῇ δὲ πρὸς Κικέρωνα καὶ Βροῦτον αὑτοῦ καὶ μυρίους ἄλλους τῶν πεπολεμηκότων ἐπιεικείᾳ τεκμαίρονται καὶ τὸν λόγον ἐκεῖνον οὐκ ἐξ ἀπεχθείας, ἀλλὰ φιλοτιμίᾳ πολιτικῇ συντετάχθαι διὰ τοιαύτην αἰτίαν. ἔγραψε Κικέρων ἐγκώμιον Κάτωνος, ὄνομα τῷ λόγῳ θέμενος Κάτωνα· καὶ πολλοῖς ὁ λόγος ἦν διὰ σπουδῆς, ὡς εἰκός, ὑπὸ τοῦ δεινοτάτου τῶν ῥητόρων εἰς τὴν καλλίστην πεποιημένος ὑπόθεσιν. τοῦτο ἠνία Καίσαρα, κατηγορίαν αὑτοῦ νομίζοντα τὸν τοῦ τεθνηκότος δι’ αὐτὸν ἔπαινον. ἔγραψεν οὖν πολλάς τινας κατὰ τοῦ Κάτωνος αἰτίας συναγαγών τὸ δὲ βιβλίον Ἀντικάτων ἐπιγέγραπται. καὶ σπουδαστὰς ἔχει τῶν λόγων ἑκάτερος διὰ Καίσαρα καὶ Κάτωνα πολλούς.", "st": "Caes. 54.1"}, {"sp": "N", "t": "ἀλλὰ γὰρ ὡς ἐπανῆλθεν εἰς Ῥώμην ἀπὸ Λιβύης, πρῶτον μὲν ὑπὲρ τῆς νίκης ἐμεγαληγόρησε πρὸς τὸν δῆμον, ὡς τοσαύτην κεχειρωμένος χώραν ὅση παρέξει καθ’ ἕκαστον ἐνιαυτὸν εἰς τὸ δημόσιον σίτου μὲν εἴκοσι μυριάδας Ἀττικῶν μεδίμνων, ἐλαίου δὲ λιτρῶν μυριάδας τριακοσίας. ἔπειτα θριάμβους κατήγαγε τὸν Αἰγυπτιακόν, τὸν Ποντικόν, τὸν Λιβυκόν, οὐκ ἀπὸ Σκηπίωνος, ἀλλ’ ἀπὸ Ἰόβα δῆθεν τοῦ βασιλέως. τότε καὶ Ἰόβας υἱὸς ὢν ἐκείνου κομιδῇ νήπιος ἐν τῷ θριάμβῳ παρήχθη, μακαριωτάτην ἁλοὺς ἅλωσιν, ἐκ βαρβάρου καὶ Νομάδος Ἑλλήνων τοῖς πολυμαθεστάτοις ἐναρίθμιος γενέσθαι συγγραφεῦσι. μετὰ δὲ τοὺς θριάμβους στρατιώταις τε μεγάλας δωρεὰς ἐδίδου καὶ τὸν δῆμον ἀνελάμβανεν ἑστιάσεσι καὶ θέαις, ἑστιάσας μὲν ἐν δισμυρίοις καὶ δισχιλίοις τρικλίνοις ὁμοῦ σύμπαντας, θέας δὲ καὶ μονομάχων καὶ ναυμάχων ἀνδρῶν παρασχὼν ἐπὶ τῇ θυγατρὶ Ἰουλίᾳ, πάλαι τεθνεώσῃ.", "st": "Caes. 55.1"}, {"sp": "N", "t": "μετὰ δὲ τὰς θέας γενομένων τιμήσεων ἀντὶ τῶν προτέρων δυεῖν καὶ τριάκοντα μυριάδων ἐξητάσθησαν αἱ πᾶσαι πεντεκαίδεκα. τηλικαύτην ἡ στάσις ἀπειργάσατο συμφορὰν καὶ τοσοῦτον ἀπανάλωσε τοῦ δήμου μέρος, ἔξω λόγου τιθεμένοις τὰ κατασχόντα τὴν ἄλλην Ἰταλίαν ἀτυχήματα καὶ τὰς ἐπαρχίας.", "st": "Caes. 55.5"}, {"sp": "N", "t": "συντελεσθέντων δὲ τούτων ὕπατος ἀποδειχθεὶς τὸ τέταρτον εἰς Ἰβηρίαν ἐστράτευσεν ἐπὶ τοὺς Πομπηΐου παῖδας, νέους μὲν ὄντας ἔτι, θαυμαστὴν δὲ τῷ πλήθει στρατιὰν συνειλοχότας καὶ τόλμαν ἀποδεικνυμένους ἀξιόχρεων πρὸς ἡγεμονίαν, ὥστε κίνδυνον τῷ Καίσαρι περιστῆσαι τὸν ἔσχατον. ἡ δὲ μεγάλη μάχη περὶ πόλιν συνέστη Μοῦνδαν, ἐν ᾗ Καῖσαρ ἐκθλιβομένους ὁρῶν τοὺς ἑαυτοῦ καὶ κακῶς ἀντέχοντας ἐβόα, διὰ τῶν ὅπλων καὶ τῶν τάξεων διαθέων, εἰ μηδὲν αἰδοῦνται λαβόντες αὐτὸν ἐγχειρίσαι τοῖς παιδαρίοις. μόλις δὲ προθυμίᾳ πολλῇ τοὺς πολεμίους ὠσάμενος ἐκείνων μὲν ὑπὲρ τρισμυρίους διέφθειρε, τῶν δὲ αὐτοῦ χιλίους ἀπώλεσε τοὺς ἀρίστους. ἀπιὼν δὲ μετὰ τὴν μάχην πρὸς τοὺς φίλους εἶπεν ὡς πολλάκις μὲν ἀγωνίσαιτο περὶ νίκης, νῦν δὲ πρῶτον περὶ ψυχῆς. ταύτην τὴν μάχην ἐνίκησε τῇ τῶν Διονυσίων ἑορτῇ, καθ’ ἣν λέγεται καὶ Πομπήϊος Μᾶγνος ἐπὶ τὸν πόλεμον ἐξελθεῖν διὰ μέσου δὲ χρόνος ἐνιαυτῶν τεσσάρων διῆλθε, τῶν δὲ Πομπηΐου παίδων ὁ μὲν νεώτερος διέφυγε, τοῦ δὲ πρεσβυτέρου μεθ’ ἡμέρας ὀλίγας Δείδιος ἀνήνεγκε τὴν κεφαλήν.", "st": "Caes. 56.1"}, {"sp": "N", "t": "τοῦτον ἔσχατον Καῖσαρ ἐπολέμησε τὸν πόλεμον ὁ δὲ ἀπ’ αὐτοῦ καταχθεὶς θρίαμβος ὡς οὐδὲν ἄλλο Ῥωμαίους ἠνίασεν. οὐ γὰρ ἀλλοφύλους ἡγεμόνας οὐδὲ βαρβάρους βασιλεῖς κατηγωνισμένον, ἀνδρὸς δὲ Ῥωμαίων κρατίστου τύχαις κεχρημένου παῖδας καὶ γένος ἄρδην ἀνῃρηκότα ταῖς τῆς πατρίδος ἐπιπομπεύειν συμφοραῖς οὐ καλῶς εἶχεν, ἀγαλλόμενον ἐπὶ τούτοις ὧν μία καὶ πρὸς θεοὺς καὶ πρὸς ἀνθρώπους ἀπολογία τὸ μετ’ ἀνάγκης πεπρᾶχθαι, καὶ ταῦτα πρότερον μήτε ἄγγελον μήτε γράμματα δημοσίᾳ πέμψαντα περὶ νίκης ἀπὸ τῶν ἐμφυλίων πολέμων, ἀλλ’ ἀπωσάμενον αἰσχύνῃ τὴν δόξαν.", "st": "Caes. 56.7"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ πρὸς τὴν τύχην τοῦ ἀνδρὸς ἐγκεκλικότες καὶ δεδεγμένοι τὸν χαλινόν, καὶ τῶν ἐμφυλίων πολέμων καὶ κακῶν ἀναπνοὴν ἡγούμενοι τὴν μοναρχίαν, δικτάτορα μὲν αὐτόν ἀπέδειξαν διὰ βίου τοῦτο δ’ ἦν ὁμολογουμένη τυραννίς, τῷ ἀνυπευθύνῳ τῆς μοναρχίας τὸ ἀκατάπαυστον προσλαβούσης· τιμὰς δὲ τὰς πρώτας Κικέρωνος εἰς τὴν βουλὴν γράψαντος, ὧν ἁμῶς γέ πως ἀνθρώπινον ἦν τὸ μέγεθος, ἕτεροι προστιθέντες ὑπερβολὰς καὶ διαμιλλώμενοι πρὸς ἀλλήλους ἐξειργάσαντο καὶ τοῖς πρᾳοτάτοις ἐπαχθῆ τὸν ἄνδρα καὶ λυπηρὸν γενέσθαι διὰ τὸν ὄγκον καὶ τὴν ἀτοπίαν τῶν ψηφιζομένων, οἷς οὐδὲν ἧττον οἴονται συναγωνίσασθαι τῶν κολακευόντων Καίσαρα τοὺς μισοῦντας, ὅπως ὅτι πλείστας κατ’ αὐτοῦ προφάσεις ἔχωσι καὶ μετὰ μεγίστων ἐγκλημάτων ἐπιχειρεῖν δοκῶσιν. ἐπεὶ τά γε ἄλλα, τῶν ἐμφυλίων αὐτῷ πολέμων πέρας ἐσχηκότων, ἀνέγκλητον ἑαυτὸν παρεῖχε· καὶ τό γε τῆς Ἐπιεικείας ἱερὸν οὐκ ἀπὸ τρόπου δοκοῦσι χαριστήριον ἐπὶ τῇ πρᾳότητι ψηφίσασθαι. καὶ γὰρ ἀφῆκε πολλοὺς τῶν πεπολεμηκότων πρὸς αὐτόν, ἐνίοις δὲ καὶ ἀρχὰς καὶ τιμάς, ὡς Βρούτῳ καὶ Κασσίῳ, προσέθηκεν ἐστρατήγουν γὰρ ἀμφότεροι. καὶ τὰς Πομπηΐου καταβεβλημένας εἰκόνας οὐ περιεῖδεν, ἀλλ’ ἀνέστησεν, ἐφ’ ὧν καὶ Κικέρων εἶπεν ὅτι Καῖσαρ τοὺς Πομπηΐου στήσας ἀνδριάντας τοὺς ἰδίους ἔπηξε, τῶν δὲ φίλων ἀξιούντων αὐτὸν δορυφορεῖσθαι καὶ πολλῶν ἐπὶ τοῦτο παρεχόντων ἑαυτούς οὐχ ὑπέμεινεν, εἰπὼν ὡς βέλτιόν ἐστιν ἅπαξ ἀποθανεῖν ἢ ἀεὶ προσδοκᾶν. τὴν δ’ εὔνοιαν ὡς κάλλιστον ἅμα καὶ βεβαιότατον ἑαυτῷ περιβαλλόμενος φυλακτήριον, αὖθις ἀνελάμβανε τὸν δῆμον ἑστιάσεσι καὶ σιτηρεσίοις, τὸ δὲ στρατιωτικὸν ἀποικίαις, ὧν ἐπιφανέσταται Καρχηδὼν καὶ Κόρινθος ἦσαν, αἷς καὶ πρότερον τὴν ἅλωσιν καὶ τότε τὴν ἀνάληψιν ἅμα καὶ κατὰ τὸν αὐτὸν χρόνον ἀμφοτέραις γενέσθαι συνέτυχε.", "st": "Caes. 57.1"}, {"sp": "N", "t": "τῶν δὲ δυνατῶν τοῖς μὲν ὑπατείας καὶ στρατηγίας εἰς τοὐπιὸν ἐπηγγέλλετο, τοὺς δ’ ἄλλαις τισὶν ἐξουσίαις καὶ τιμαῖς παρεμυθεῖτο, πᾶσι δὲ ἐλπίζειν ἐνεδίδου, μνηστευόμενος ἄρχειν ἑκόντων, ὡς καὶ Μαξίμου τοῦ ὑπάτου τελευτήσαντος εἰς τὴν περιοῦσαν ἔτι τῆς ἀρχῆς μίαν ἡμέραν ὕπατον ἀποδεῖξαι Κανίνιον Ῥεβίλιον. πρὸς ὅν, ὡς ἔοικε, πολλῶν δεξιώσασθαι καὶ προπέμψαι βαδιζόντων ὁ Κικέρων, σπεύδωμεν, ἔφη, πρὶν φθάσῃ τῆς ὑπατείας ἐξελθὼν ὁ ἄνθρωπος.", "st": "Caes. 58.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τὸ φύσει μεγαλουργὸν αὑτοῦ καὶ φιλότιμον αἱ πολλαὶ κατορθώσεις οὐ πρὸς ἀπόλαυσιν ἔτρεπον Τῶν πεπονημένων, ἀλλ’ ὑπέκκαυμα καὶ θάρσος οὖσαι πρὸς τὰ μέλλοντα μειζόνων ἐνέτικτον ἐπινοίας πραγμάτων καὶ καινῆς ἔρωτα δόξης ὡς ἀποκεχρημένῳ τῇ παρούσῃ, τὸ μὲν πάθος οὐδὲν ἦν ἕτερον ἢ ζῆλος αὑτοῦ καθάπερ ἄλλου καὶ φιλονεικία τις ὑπὲρ Τῶν μελλόντων πρὸς τὰ πεπραγμένα, παρασκευὴ δὲ καὶ γνώμη στρατεύειν μὲν ἐπὶ Πάρθους, καταστρεψαμένῳ δὲ τούτους, καὶ δι’ Ὑρκανίας παρὰ τὴν Κασπίαν θάλασσαν καὶ τόν Καύκασον ἐκπεριελθόντι τόν Πόντον, εἰς τὴν Σκυθικὴν ἐμβαλεῖν, καὶ τὰ περίχωρα Γερμανοῖς καὶ Γερμανίαν αὐτὴν ἐπιδραμόντι διὰ Κελτῶν ἐπανελθεῖν εἰς Ἰταλίαν, καὶ συνάψαι τόν κύκλον τοῦτον τῆς ἡγεμονίας τῷ πανταχόθεν Ὠκεανῷ περιορισθείσης. διὰ μέσου δὲ τῆς στρατείας τόν τε Κορίνθιον Ἰσθμὸν ἐπεχείρει διασκάπτειν, Ἀνιηνὸν ἐπὶ τούτῳ προχειρισάμενος, καὶ τόν Τίβεριν εὐθὺς ἀπὸ τῆς πόλεως ὑπολαβὼν διώρυχι βαθείᾳ καὶ περικλάσας ἐπὶ τὸ Κιρκαῖον ἐμβαλεῖν εἰς τὴν πρὸς Ταρρακίνῃ θάλατταν, ἀσφάλειαν ἅμα καὶ ῥᾳστώνην τοῖς δι’ ἐμπορίας φοιτῶσιν εἰς Ῥώμην μηχανώμενος· πρὸς δὲ τούτοις τὰ μὲν ἕλη τὰ περὶ Πωμεντῖνον καὶ Σητίαν ἐκτρέψας πεδίον ἀποδεῖξαι πολλαῖς ἐνεργὸν ἀνθρώπων μυριάσι, τῇ δὲ ἔγγιστα τῆς Ῥώμης θαλάσσῃ κλεῖθρα διὰ χωμάτων ἐπαγαγών, καὶ τὰ τυφλὰ καὶ δύσορμα τῆς Ὠστιανῆς ἠϊόνος ἀνακαθηράμενος, λιμένας ἐμποιήσασθαι καὶ ναύλοχα πρὸς τοσαύτην ἀξιόπιστα ναυτιλίαν. καὶ ταῦτα μὲν ἐν παρασκευαῖς ἦν.", "st": "Caes. 58.4"}, {"sp": "N", "t": "ἡ δὲ τοῦ ἡμερολογίου διάθεσις καὶ διόρθωσις τῆς περὶ τὸν χρόνον ἀνωμαλίας φιλοσοφηθεῖσα χαριέντως ὑπ’ αὐτοῦ καὶ τέλος λαβοῦσα γλαφυρωτάτην παρέσχε χρείαν. οὐ γὰρ μόνον ἐν τοῖς παλαιοῖς πάνυ χρόνοις τεταραγμέναις ἐχρῶντο Ῥωμαῖοι ταῖς τῶν μηνῶν πρὸς τὸν ἐνιαυτὸν περιόδοις, ὥστε τὰς θυσίας καὶ τὰς ἑορτὰς ὑποφερομένας κατὰ μικρὸν εἰς ἐναντίας ἐκπεπτωκέναι τοῖς χρόνοις ὥρας, ἀλλὰ καὶ περὶ τὴν τότε οὖσαν ἡλιακὴν οἱ μὲν ἄλλοι παντάπασι τούτων ἀσυλλογίστως εἶχον, οἱ δὲ ἱερεῖς μόνοι τὸν καιρὸν εἰδότες ἐξαίφνης καὶ προῃσθημένου μηδενὸς τὸν ἐμβόλιμον προσέγραφον μῆνα, Μερκηδόνιον ὀνομάζοντες, ὃν Νομᾶς ὁ βασιλεὺς πρῶτος ἐμβαλεῖν λέγεται, μικρὰν καὶ διατείνουσαν οὐ πόρρω βοήθειαν ἐξευρὼν τῆς περὶ τὰς ἀποκαταστάσεις πλημμελείας, ὡς ἐν τοῖς περὶ ἐκείνου γέγραπται. Καῖσαρ δὲ τοῖς ἀρίστοις τῶν φιλοσόφων καὶ μαθηματικῶν τὸ πρόβλημα προθείς ἐκ τῶν ὑποκειμένων ἤδη μεθόδων ἔμιξεν ἰδίαν τινὰ καὶ διηκριβωμένην μᾶλλον ἐπανόρθωσιν, ᾗ χρώμενοι μέχρι νῦν Ῥωμαῖοι δοκοῦσιν ἧττον ἑτέρων σφάλλεσθαι περὶ τὴν ἀνωμαλίαν. οὐ μὴν ἀλλὰ καὶ τοῦτο τοῖς βασκαίνουσι καὶ βαρυνομένοις τὴν δύναμιν αἰτίας παρεῖχε. Κικέρων γοῦν ὁ ῥήτωρ, ὡς ἔοικε, φήσαντός τινος αὔριον ἐπιτέλλειν Λύραν, ναὶ, εἶπεν, ἐκ διατάγματος. ὡς καὶ τοῦτο πρὸς ἀνάγκην τῶν ἀνθρώπων δεχομένων.", "st": "Caes. 59.1"}, {"sp": "N", "t": "τὸ δὲ ἐμφανὲς μάλιστα μῖσος καὶ θανατηφόρον ἐπ’ αὐτὸν ὁ τῆς βασιλείας ἔρως ἐξειργάσατο, τοῖς μὲν πολλοῖς αἰτία πρώτη, τοῖς δὲ ὑπούλοις πάλαι πρόφασις εὐπρεπεστάτη γενομένη, καίτοι καὶ λόγον τινὰ κατέσπειραν εἰς τὸν δῆμον οἱ ταύτην Καίσαρι τὴν τιμὴν προξενοῦντες, ὡς ἐκ γραμμάτων Σιβυλλείων ἁλώσιμα τὰ Πάρθων φαίνοιτο Ῥωμαίοις σὺν βασιλεῖ στρατευομένοις ἐπ’ αὐτούς, ἄλλως ἀνέφικτα ὄντα· καὶ καταβαίνοντος ἐξ Ἄλβης Καίσαρος εἰς τὴν πόλιν ἐτόλμησαν αὐτὸν ἀσπάσασθαι βασιλέα, τοῦ δὲ δήμου διαταραχθέντος ἀχθεσθεὶς ἐκεῖνος οὐκ ἔφη βασιλεύς, ἀλλὰ Καῖσαρ καλεῖσθαι· καὶ γενομένης πρὸς τοῦτο πάντων σιωπῆς οὐ πάνυ φαιδρὸς οὐδ’ εὐμενὴς παρῆλθεν. ἐν δὲ συγκλήτῳ τιμάς τινας ὑπερφυεῖς αὐτῷ ψηφισαμένων ἔτυχε μὲν ὑπὲρ τῶν ἐμβόλων καθεζόμενος, προσιόντων δὲ τῶν ὑπάτων καὶ τῶν στρατηγῶν, ἅμα δὲ καὶ τῆς βουλῆς ἁπάσης ἑπομένης, οὐχ ὑπεξαναστάς, ἀλλ’ ὥσπερ ἰδιώταις τισὶ χρηματίζων, ἀπεκρίνατο συστολῆς μᾶλλον ἢ προσθέσεως τὰς τιμάς δεῖσθαι. καὶ τοῦτο οὐ μόνον ἠνίασε τὴν βουλήν, ἀλλὰ καὶ τὸν δῆμον, ὡς ἐν τῇ βουλῇ τῆς πόλεως προπηλακιζομένης, καὶ μετὰ δεινῆς κατηφείας ἀπῆλθον εὐθὺς οἷς ἐξῆν μὴ παραμένειν, ὥστε κἀκεῖνον ἐννοήσαντα παραχρῆμα μὲν οἴκαδε τραπέσθαι καὶ βοᾶν πρὸς τοὺς φίλους, ἀπαγαγόντα τοῦ τραχήλου τὸ ἱμάτιον, ὡς ἕτοιμος εἴη τῷ βουλομένῳ τὴν σφαγὴν παρέχειν, ὕστερον δὲ προφασίζεσθαι τὴν νόσον οὐ γὰρ ἐθέλειν τὴν αἴσθησιν ἀτρεμεῖν τῶν οὕτως ἐχόντων, ὅταν ἱστάμενοι διαλέγωνται πρὸς ὄχλον, ἀλλὰ σειομένην ταχὺ καὶ περιφερομένην ἰλίγγους ἐπισπᾶσθαι καὶ καταλαμβάνεσθαι. τὸ δὲ οὐκ εἶχεν οὕτως, ἀλλὰ καὶ πάνυ βουλόμενον αὐτὸν ὑπεξαναστῆναι τῇ βουλῇ λέγουσιν ὑπό τοῦ τῶν φίλων, μᾶλλον δὲ κολάκων, Κορνηλίου Βάλβου, κατασχεθῆναι φήσαντος οὐ μεμνήσῃ Καῖσαρ ὤν, οὐδὲ ἀξιώσεις ὡς κρείττονα θεραπεύεσθαι σεαυτόν; λαμπρῶς, ὦ", "st": "Caes. 60.1"}, {"sp": "N", "t": "ἐπιγίνεται τούτοις τοῖς προσκρούσμασιν ὁ τῶν δημάρχων προπηλακισμός. ἦν μὲν γὰρ ἡ τῶν Λουπερκαλίων ἑορτή, περὶ ἧς πολλοὶ γράφουσιν ὡς ποιμένων τὸ παλαιὸν εἴη, καί τι καί προσήκει τοῖς Ἀρκαδικοῖς Λυκαίοις. τῶν δ’ εὐγενῶν νεανίσκων καί ἀρχόντων πολλοὶ διαθέουσιν ἀνὰ τὴν πόλιν γυμνοί, σκύτεσι λασίοις τοὺς ἐμποδὼν ἐπὶ παιδιᾷ καί γέλωτι παίοντες πολλαὶ δὲ καί τῶν ἐν τέλει γυναικῶν ἐπίτηδες ὑπαντῶσαι παρέχουσιν ὥσπερ ἐν διδασκάλου τὼ χεῖρε ταῖς πληγαῖς, πεπεισμέναι πρὸς εὐτοκίαν κυούσαις, ἀγόνοις δὲ πρὸς κύησιν ἀγαθὸν εἶναι. ταῦτα Καῖσαρ ἐθεᾶτο καθήμενος ἐπὶ τῶν ἐμβόλων ἐπὶ δίφρου χρυσοῦ, θριαμβικῷ κόσμῳ κεκοσμημένος. Ἀντώνιος δὲ τῶν θεόντων τὸν ἱερὸν δρόμον εἷς ἦν καί γὰρ ὑπάτευεν. ὡς οὖν εἰς τὴν ἀγορὰν ἐνέβαλε καί τὸ πλῆθος αὐτῷ διέστη, φέρων διάδημα στεφάνῳ δάφνης περιπεπλεγμένον ὤρεξε τῷ Καίσαρι καί γίνεται κρότος οὐ λαμπρός, ἀλλ’ ὀλίγος ἐκ παρασκευῆς. ἀπωσαμένου δὲ τοῦ Καίσαρος ἅπας ὁ δῆμος ἀνεκρότησεν αὖθις δὲ προσφέροντος ὀλίγοι, καί μὴ δεξαμένου πάλιν ἅπαντες, οὕτω δὲ τῆς πείρας ἐξελεγχομένης Καῖσαρ μὲν ἀνίσταται, τὸν στέφανον εἰς τὸ Καπιτώλιον ἀπενεχθῆναι κελεύσας, ὤφθησαν δὲ ἀνδριάντες αὐτοῦ διαδήμασιν ἀναδεδεμένοι βασιλικοῖς. καί τῶν δημάρχων δύο, Φλάουϊος καί Μάρυλλος, ἐπελθόντες ἀπέσπασαν, καί τοὺς ἀσπασαμένους βασιλέα τὸν Καίσαρα πρώτους ἐξευρόντες ἀπῆγον εἰς τὸ δεσμωτήριον. ὁ δὲ δῆμος εἵπετο κροτῶν, καί Βρούτους ἀπεκάλει τοὺς ἄνδρας, ὅτι Βροῦτος ἦν ὁ καταλύσας τὴν τῶν βασιλέων διαδοχὴν καί τὸ κράτος εἰς βουλὴν καί δῆμον ἐκ μοναρχίας καταστήσας. ἐπὶ τούτῳ Καῖσαρ παροξυνθείς τὴν μὲν ἀρχὴν ἀφείλετο τῶν περὶ τὸν Μάρυλλον, ἐν δὲ τῷ κατηγορεῖν αὐτῶν ἅμα καὶ τὸν δῆμον ἐφυβρίζων πολλάκις Βρούτους τε καὶ Κυμαίους ἀπεκάλει τοὺς ἄνδρας.", "st": "Caes. 61.1"}, {"sp": "N", "t": "οὕτω δὴ τρέπονται πρὸς Μᾶρκον Βροῦτον οἱ πολλοί, γένος μὲν ἐκεῖθεν εἶναι δοκοῦντα πρὸς πατέρων, καὶ τὸ πρὸς μητρὸς δὲ ἀπὸ Σερουιλίων, οἰκίας ἑτέρας ἐπιφανοῦς, γαμβρὸν δὲ καί ἀδελφιδοῦν Κάτωνος. τοῦτον ἐξ ἑαυτοῦ μὲν ὁρμῆσαι πρὸς κατάλυσιν τῆς μοναρχίας ἤμβλυνον αἱ παρὰ Καίσαρος τιμαὶ καὶ χάριτες. οὐ γὰρ μόνον ἐσώθη περὶ Φάρσαλον ἀπὸ τῆς Πομπηΐου φυγῆς, οὐδὲ πολλοὺς τῶν ἐπιτηδείων ἔσωσεν ἐξαιτησάμενος, ἀλλὰ καὶ πίστιν εἶχε μεγάλην παρ’ αὐτῷ. καὶ στρατηγίαν μὲν ἐν τοῖς τότε τὴν ἐπιφανεστάτην ἔλαβεν, ὑπατεύειν δὲ ἔμελλεν εἰς τέταρτον ἔτος, ἐρίσαντος Κασσίου προτιμηθείς· λέγεται γὰρ ὁ Καῖσαρ εἰπεῖν ὡς δικαιότερα μὲν λέγοι Κάσσιος, αὐτὸς μέντοι Βροῦτον οὐκ ἂν παρέλθοι. καί ποτε καί διαβαλλόντων τινῶν τὸν ἄνδρα, πραττομένης ἤδη τῆς συνωμοσίας, οὐ προσέσχεν, ἀλλὰ τοῦ σώματος τῇ χειρὶ θιγὼν ἔφη πρὸς τοὺς διαβάλλοντας Ἀναμενεῖ τοῦτο τὸ δέρμα Βροῦτος, ὡς ἄξιον μὲν ὄντα τῆς ἀρχῆς δι’ ἀρετήν, διὰ δὲ τὴν ἀρχὴν οὐκ ἂν ἀχάριστον καί πονηρὸν γενόμενον. οἱ δὲ τῆς μεταβολῆς ἐφιέμενοι καί πρὸς μόνον ἐκεῖνον ἢ πρῶτον ἀποβλέποντες αὐτῷ μὲν οὐκ ἐτόλμων διαλέγεσθαι, νύκτωρ δὲ κατεπίμπλασαν γραμμάτων τὸ βῆμα καὶ τὸν δίφρον ἐφ’ οὗ στρατηγῶν ἐχρημάτιζεν ὧν ἦν τὰ πολλὰ τοιαῦτα· καθεύδεις, ὦ Βροῦτε, καὶ οὐκ εἶ Βροῦτος. ὑφ’ ὧν ὁ Κάσσιος αἰσθόμενος διακινούμενον ἡσυχῇ τὸ φιλότιμον αὐτοῦ, μᾶλλον ἢ πρότερον ἐνέκειτο καί παρώξυνεν, αὐτὸς ἰδίᾳ τι καί μίσους ἔχων πρὸς τὸν Καίσαρα δι’ αἰτίας ἃς ἐν τοῖς περὶ Βρούτου γεγραμμένοις δεδηλώκαμεν. εἶχε μέντοι καί δι’ ὑποψίας ὁ Καῖσαρ αὐτὸν, ὥστε καί πρὸς τοὺς φίλους εἰπεῖν ποτε· τί φαίνεται βουλόμενος ὑμῖν Κάσσιος; ἐμοὶ μὲν γὰρ οὐ λίαν ἀρέσκει λίαν ὠχρὸς ὤν. πάλιν δὲ λέγεται, περὶ Ἀντωνίου καί Δολοβέλλα διαβολῆς πρὸς αὐτὸν, ὡς νεωτερίζοιεν, ἐλθούσης, οὐ πάνυ, φάναι, τούτους δέδοικα τοὺς παχεῖς καί κομήτας, μᾶλλον δὲ τοὺς ὠχροὺς καί λεπτοὺς ἐκείνους Κάσσιον λέγων καί Βροῦτον.", "st": "Caes. 62.1"}, {"sp": "N", "t": "ἀλλ’ ἔοικεν οὐχ οὕτως ἀπροσδόκητον ὡς ἀφύλακτον εἶναι τὸ πεπρωμένον, ἐπεὶ καὶ σημεῖα θαυμαστὰ καὶ φάσματα φανῆναι λέγουσι. σέλα μὲν οὖν οὐράνια καὶ κτύπους νύκτωρ πολλαχοῦ διαφερομένους καὶ καταίροντας εἰς ἀγορὰν ἐρήμους ὄρνιθας οὐκ ἄξιον ἴσως ἐπὶ πάθει τηλικούτῳ μνημονεῦσαι· Στράβων δὲ ὁ φιλόσοφος ἱστορεῖ πολλοὺς μὲν ἀνθρώπους διαπύρους ἐπιφερομένους φανῆναι, στρατιώτου δὲ ἀνδρὸς οἰκέτην ἐκ τῆς χειρὸς ἐκβαλεῖν πολλὴν φλόγα καὶ δοκεῖν καίεσθαι τοῖς ὁρῶσιν, ὡς δὲ ἐπαύσατο, μηδὲν ἔχειν κακὸν τὸν ἄνθρωπον· αὐτῷ δὲ Καίσαρι θύοντι τὴν καρδίαν ἀφανῆ γενέσθαι τοῦ ἱερείου καὶ δεινὸν εἶναι τὸ τέρας; οὐ γὰρ ἂν φύσει γε συστῆναι ζῷον ἀκάρδιον. ἔστι δὲ καὶ ταῦτα πολλῶν ἀκοῦσαι διεξιόντων, ὥς τις αὐτῷ μάντις ἡμέρᾳ Μαρτίου μηνὸς, ἣν Εἰδοὺς Ῥωμαῖοι καλοῦσι, προείποι μέγαν φυλάττεσθαι κίνδυνον ἐλθούσης δὲ τῆς ἡμέρας προϊὼν ὁ Καῖσαρ εἰς τὴν σύγκλητον ἀσπασάμενος προσπαίξειε τῷ μάντει φάμενος αἱ μὲν δὴ Μάρτιαι Εἰδοὶ πάρεισιν ὁ δὲ ἡσυχῇ πρὸς αὐτόν εἴποι ναί πάρεισιν, ἀλλ’ οὐ παρεληλύθασι. πρὸ μιᾶς δὲ ἡμέρας Μάρκου Λεπίδου δειπνίζοντος αὐτόν ἔτυχε μὲν ἐπιστολαῖς ὑπογράφων, ὥσπερ εἰώθει, κατακείμενος ἐμπεσόντος δὲ λόγου ποῖος ἄρα τῶν θανάτων ἄριστος, ἅπαντας φθάσας ἐξεβόησεν ὁ ἀπροσδόκητος. μετὰ ταῦτα κοιμώμενος, ὥσπερ εἰώθει, παρὰ τῇ γυναικί, πασῶν ἅμα τῶν θυρῶν τοῦ δωματίου καὶ τῶν θυρίδων ἀναπεταννυμένων, διαταραχθεὶς ἅμα τῷ κτύπῳ καὶ τῷ φωτὶ καταλαμπούσης τῆς σελήνης, ᾔσθετο τὴν Καλπουρνίαν βαθέως μὲν καθεύδουσαν, ἀσαφεῖς δὲ φωνὰς καὶ στεναγμοὺς ἀνάρθρους ἀναπέμπουσαν ἐκ τῶν ὕπνων ἐδόκει δὲ ἄρα κλαίειν ἐκεῖνον ἐπὶ ταῖς ἀγκάλαις ἔχουσα κατεσφαγμένον.", "st": "Caes. 63.1"}, {"sp": "N", "t": "οἱ δὲ οὔ φασι τῇ γυναικὶ ταύτην γενέσθαι τὴν ὄψιν ἀλλὰ ἦν γάρ τι τῇ Καίσαρος οἰκίᾳ προσκείμενον οἷόν ἐπὶ κόσμῳ καὶ σεμνότητι τῆς βουλῆς ψηφισαμένης ἀκρωτήριον, ὡς Λίβιος ἱστορεῖ, τοῦτο ὄναρ ἡ Καλπουρνία θεασαμένη καταρρηγνύμενον ἔδοξε ποτνιᾶσθαι καὶ δακρύειν. ἡμέρας δ’ οὖν γενομένης ἐδεῖτο τοῦ Καίσαρος, εἰ μὲν οἷόν τε, μὴ προελθεῖν, Ἀλλ’ ἀναβαλέσθαι τὴν σύγκλητον εἰ δὲ τῶν ἐκείνης ὀνείρων ἐλάχιστα φροντίζει, σκέψασθαι διὰ μαντικῆς ἄλλης καὶ ἱερῶν περὶ τοῦ μέλλοντος. εἶχε δέ τις, ὡς ἔοικε, κἀκεῖνον ὑποψία καὶ φόβος, οὐδένα γὰρ γυναικισμὸν ἐν δεισιδαιμονίᾳ πρότερον κατεγνώκει τῆς Καλπουρνίας, τότε δὲ ἑώρα περιπαθοῦσαν, ὡς δὲ καὶ πολλὰ καταθύσαντες οἱ μάντεις ἔφρασαν αὐτῷ δυσιερεῖν, ἔγνω πέμψας Ἀντώνιον ἀφεῖναι τὴν σύγκλητον,", "st": "Caes. 63.1b"}, {"sp": "N", "t": "ἐν δὲ τούτῳ Δέκιμος Βροῦτος ἐπίκλησιν Ἀλβῖνος, πιστευόμενος μὲν ὑπὸ Καίσαρος, ὥστε καὶ δεύτερος ὑπ’ αὐτοῦ κληρονόμος γεγράφθαι, τοῖς δὲ περὶ Βροῦτον τὸν ἕτερον καὶ Κάσσιον μετέχων τῆς συνωμοσίας, φοβηθεὶς μὴ τὴν ἡμέραν ἐκείνην διακρουσαμένου τοῦ Καίσαρος ἔκπυστος ἡ πρᾶξις γένηται, τούς τε μάντεις ἐχλεύαζε καὶ καθήπτετο τοῦ Καίσαρος, ὡς αἰτίας καὶ διαβολὰς ἑαυτῷ κτωμένου πρὸς τὴν σύγκλητον ἐντρυφᾶσθαι δοκοῦσαν ἥκειν μὲν γὰρ αὐτὴν κελεύσαντος ἐκείνου, καὶ προθύμους εἶναι ψηφίζεσθαι πάντας ὅπως τῶν ἐκτὸς Ἰταλίας ἐπαρχιῶν βασιλεὺς ἀναγορεύοιτο καὶ φοροίη διάδημα τὴν ἄλλην ἐπιὼν γῆν καὶ θάλασσαν· εἰ δὲ φράσει τις αὐτοῖς καθεζομένοις νῦν μὲν ἀπαλλάττεσθαι, παρεῖναι δὲ αὖθις ὅταν ἐντύχῃ βελτίοσιν ὀνείροις Καλπουρνία, τίνας ἔσεσθαι λόγους παρὰ τῶν φθονούντων; ἢ τίνα τῶν φίλων ἀνέξεσθαι διδασκόντων ὡς οὐχὶ δουλεία ταῦτα καὶ τυραννίς ἐστιν; ἀλλ’ εἰ δοκεῖ πάντως, ἔφη, τὴν ἡμέραν ἀφοσιώσασθαι, βέλτιον αὐτὸν παρελθόντα καὶ προσαγορεύσαντα τὴν βουλὴν ὑπερθέσθαι. ταῦθ’ ἅμα λέγων ὁ Βροῦτος ἦγε τῆς χειρὸς λαβόμενος τὸν Καίσαρα, καὶ μικρὸν μὲν αὐτῷ προελθόντι τῶν θυρῶν οἰκέτης ἀλλότριος ἐντυχεῖν προθυμούμενος, ὡς ἡττᾶτο τοῦ περὶ ἐκεῖνον ὠθισμοῦ καὶ πλήθους, βιασάμενος εἰς τὴν οἰκίαν παρέδωκεν ἑαυτὸν τῇ Καλπουρνίᾳ, φυλάττειν κελεύσας ἄχρι ἂν ἐπανέλθῃ Καῖσαρ, ὡς ἔχων μεγάλα πράγματα κατειπεῖν πρὸς αὐτόν.", "st": "Caes. 64.1"}, {"sp": "N", "t": "Ἀρτεμίδωρος δὲ Κνίδιος τὸ γένος, Ἑλληνικῶν λόγων σοφιστὴς καὶ διὰ τοῦτο γεγονὼς ἐνίοις συνήθης τῶν περὶ Βροῦτον, ὥστε καὶ γνῶναι τὰ πλεῖστα τῶν πραττομένων, ἧκε μὲν ἐν βιβλιδίῳ κομίζων ἅπερ ἔμελλε μηνύειν, ὁρῶν δὲ τὸν Καίσαρα τῶν βιβλιδίων ἕκαστον δεχόμενον καὶ παραδιδόντα τοῖς περὶ αὐτὸν ὑπηρέταις, ἐγγὺς σφόδρα προσελθών, τοῦτο, ἔφη, Καῖσαρ, ἀνάγνωθι μόνος καὶ ταχέως· γέγραπται γὰρ ὑπὲρ πραγμάτων μεγάλων καὶ σοὶ διαφερόντων. δεξάμενος οὖν ὁ Καῖσαρ ἀναγνῶναι μὲν ὑπὸ πλήθους τῶν ἐντυγχανόντων ἐκωλύθη, καίπερ ὁρμήσας πολλάκις, ἐν δὲ τῇ χειρὶ κατέχων καὶ φυλάττων μόνον ἐκεῖνο παρῆλθεν εἰς τὴν σύγκλητον ἔνιοι δέ φασιν ἄλλον ἐπιδοῦναι τὸ βιβλίον τοῦτο, τὸν δ’ Ἀρτεμίδωρον οὐδὲ ὅλως προσελθεῖν, ἀλλ’ ἐκθλιβῆναι παρὰ πᾶσαν τὴν ὁδόν.", "st": "Caes. 65.1"}, {"sp": "N", "t": "ἀλλὰ ταῦτα μὲν ἤδη που φέρει καὶ τὸ αὐτόματον· ὁ δὲ δεξάμενος τὸν φόνον ἐκεῖνον καὶ τὸν ἀγῶνα χῶρος, εἰς ὃν ἡ σύγκλητος ἠθροίσθη τότε, Πομπηΐου μὲν εἰκόνα κειμένην ἔχων, Πομπηΐου δὲ ἀνάθημα γεγονὼς τῶν προσκεκοσμημένων τῷ θεάτρῳ, παντάπασιν ἀπέφαινε δαίμονός τινος ὑφηγουμένου καὶ καλοῦντος ἐκεῖ τὴν πρᾶξιν ἔργον γεγονέναι. καὶ γὰρ οὖν καὶ λέγεται Κάσσιος εἰς τὸν ἀνδριάντα τοῦ Πομπηΐου πρὸ τῆς ἐγχειρήσεως ἀποβλέπων ἐπικαλεῖσθαι σιωπῇ, καίπερ οὐκ ἀλλότριος ὢν τῶν Ἐπικούρου λόγων ἀλλ’ ὁ καιρὸς, ὡς ἔοικεν, ἤδη τοῦ δεινοῦ παρεστῶτος ἐνθουσιασμὸν ἐνεποίει καὶ πάθος ἀντὶ τῶν προτέρων λογισμῶν.", "st": "Caes. 66.1"}, {"sp": "N", "t": "Ἀντώνιον μὲν οὖν πιστὸν ὄντα Καίσαρι καὶ ῥωμαλέον ἔξω παρακατεῖχε Βροῦτος Ἀλβῖνος, ἐμβαλὼν ἐπίτηδες ὁμιλίαν μῆκος ἔχουσαν· εἰσιόντος δὲ Καίσαρος ἡ βουλὴ μὲν ὑπεξανέστη θεραπεύουσα, τῶν δὲ περὶ Βροῦτον οἱ μὲν ἐξόπισθεν τὸν δίφρον αὐτοῦ περιέστησαν, οἱ δὲ ἀπήντησαν, ὡς δὴ Τιλλίῳ Κίμβρῳ περὶ ἀδελφοῦ φυγάδος ἐντυχάνοντι συνδεησόμενοι, καὶ συνεδέοντο μέχρι τοῦ δίφρου παρακολουθοῦντες. ὡς δὲ καθίσας διεκρούετο τὰς δεήσεις καὶ προσκειμένων βιαιότερον ἠγανάκτει πρὸς ἕκαστον, ὁ μὲν Τίλλιος τὴν τήβεννον αὐτοῦ ταῖς χερσὶν ἀμφοτέραις συλλαβὼν ἀπὸ τοῦ τραχήλου κατῆγεν ὅπερ ἦν σύνθημα τῆς ἐπιχειρήσεως, πρῶτος δὲ Κάσκας ξίφει παίει παρὰ τὸν αὐχένα πληγὴν οὐ θανατηφόρον οὐδὲ βαθεῖαν, ἀλλ’, ὡς εἰκὸς, ἐν ἀρχῇ τολμήματος μεγάλου ταραχθείς, ὥστε καὶ τὸν Καίσαρα μεταστραφέντα τοῦ ἐγχειριδίου λαβέσθαι καὶ κατασχεῖν. ἅμα δέ πως ἐξεφώνησαν ὁ μὲν πληγεὶς Ῥωμαϊστί μιαρώτατε Κάσκα, τί ποιεῖς; ὁ δὲ πλήξας Ἑλληνιστὶ πρὸς τὸν ἀδελφόν ἀδελφέ, βοήθει.", "st": "Caes. 66.4"}, {"sp": "N", "t": "τοιαύτης δὲ τῆς ἀρχῆς γενομένης τοὺς μὲν οὐδὲν συνειδότας ἔκπληξις εἶχε καὶ φρίκη πρὸς τὰ δρώμενα, μήτε φεύγειν μήτε ἀμύνειν, Ἀλλὰ μηδὲ φωνὴν ἐκβάλλειν τολμῶντας, τῶν δὲ παρεσκευασμένων ἐπὶ τὸν φόνον ἑκάστου γυμνὸν ἀποδείξαντος τὸ ξίφος, ἐν κύκλῳ περιεχόμενος καὶ πρὸς ὅ τι τρέψειε τὴν ὄψιν πληγαῖς ἀπαντῶν καὶ σιδήρῳ φερομένῳ καὶ κατὰ προσώπου καὶ κατ’ ὀφθαλμῶν διελαυνόμενος ὥσπερ θηρίον ἐνειλεῖτο ταῖς πάντων χερσίν ἅπαντας γὰρ ἔδει κατάρξασθαι καὶ γεύσασθαι τοῦ φόνου. διὸ καὶ Βροῦτος αὐτῷ πληγὴν ἐνέβαλε μίαν εἰς τὸν βουβῶνα. λέγεται δὲ ὑπό τινων ὡς ἄρα πρὸς τοὺς ἄλλους ἀπομαχόμενος καὶ διαφέρων δεῦρο κἀκεῖ τὸ σῶμα καὶ κεκραγώς, ὅτε Βροῦτον εἶδεν ἐσπασμένον τὸ ξίφος, ἐφειλκύσατο κατὰ τῆς κεφαλῆς τὸ ἱμάτιον καὶ παρῆκεν ἑαυτόν, εἴτε ἀπὸ τύχης εἴθ’ ὑπὸ τῶν κτεινόντων ἀπωσθεὶς, πρὸς τὴν βάσιν ἐφ’ ἧς ὁ Πομπηΐου βέβηκεν ἀνδριάς. καὶ πολὺ καθῄμαξεν αὐτὴν ὁ φόνος, ὡς δοκεῖν αὐτὸν ἐφεστάναι τῇ τιμωρίᾳ τοῦ πολεμίου Πομπήϊον ὑπὸ πόδας κεκλιμένου καὶ περισπαίροντος ὑπὸ πλήθους τραυμάτων, εἴκοσι γὰρ καὶ τρία λαβεῖν λέγεται καὶ πολλοὶ κατετρώθησαν ὑπ’ ἀλλήλων, εἰς ἓν ἀπερειδόμενοι σῶμα πληγὰς τοσαύτας.", "st": "Caes. 66.9"}, {"sp": "N", "t": "Κατειργασμένου δὲ τοῦ ἀνδρός ἡ μὲν γερουσία, καίπερ εἰς μέσον ἐλθόντος Βρούτου ὥς τι περὶ τῶν πεπραγμένων ἐροῦντος, οὐκ ἀνασχομένη διὰ θυρῶν ἐξέπιπτε καὶ φεύγουσα κατέπλησε ταραχῆς καὶ δέους ἀπόρου τὸν δῆμον, ὥστε τοὺς μὲν οἰκίας κλείειν, τοὺς δὲ ἀπολείπειν τραπέζας καὶ χρηματιστήρια, δρόμῳ δὲ χωρεῖν τοὺς μὲν ἐπὶ τὸν τόπον ὀψομένους τὸ πάθος, τοὺς δὲ ἐκεῖθεν ἑωρακότας. Ἀντώνιος δὲ καὶ Λέπιδος οἱ μάλιστα φίλοι Καίσαρος ὑπεκδύντες εἰς οἰκίας ἑτέρας κατέφυγον. οἱ δὲ περὶ Βροῦτον, ὥσπερ ἦσαν ἔτι θερμοὶ τῷ φόνῳ, γυμνὰ τὰ ξίφη δεικνύντες, ἅμα πάντες ἀπὸ τοῦ βουλευτηρίου συστραφέντες ἐχώρουν εἰς τὸ Καπιτώλιον, οὐ φεύγουσιν ἐοικότες, ἀλλὰ μάλα φαιδροὶ καὶ θαρραλέοι, παρακαλοῦντες ἐπὶ τὴν ἐλευθερίαν τὸ πλῆθος καὶ προσδεχόμενοι τοὺς ἀρίστους τῶν ἐντυγχανόντων. ἔνιοι δὲ καὶ συνανέβαινον αὐτοῖς καὶ κατεμίγνυσαν ἑαυτούς ὡς μετεσχηκότες τοῦ ἔργου καὶ προσεποιοῦντο τὴν δόξαν, ὧν ἦν καὶ Γάϊος Ὀκτάουϊος καὶ Λέντλος Σπινθήρ. οὗτοι μὲν οὖν τῆς ἀλαζονείας δίκην ἔδωκαν ὕστερον ὑπὸ Ἀντωνίου καὶ τοῦ νέου Καίσαρος ἀναιρεθέντες καὶ μηδὲ τῆς δόξης, δι’ ἣν ἀπέθνῃσκον, ἀπολαύσαντες ἀπιστίᾳ τῶν ἄλλων, οὐδὲ γὰρ οἱ κολάζοντες αὐτοὺς τῆς πράξεως, ἀλλὰ τῆς βουλήσεως τὴν δίκην ἔλαβον.", "st": "Caes. 67.1"}, {"sp": "N", "t": "μεθ’ ἡμέραν δὲ τῶν περὶ Βροῦτον κατελθόντων καὶ ποιησαμένων λόγους, ὁ μὲν δῆμος οὔτε δυσχεραίνων οὔτε ὡς ἐπαινῶν τὰ πεπραγμένα τοῖς λεγομένοις προσεῖχεν, ἀλλ’ ὑπεδήλου τῇ πολλῇ σιωπῇ Καίσαρα μὲν οἰκτείρων, αἰδούμενος δὲ Βροῦτον, ἡ δὲ σύγκλητος ἀμνηστίας τινὰς καὶ συμβάσεις πράττουσα πᾶσι Καίσαρα μὲν ὡς θεὸν τιμᾶν ἐψηφίσατο καὶ κινεῖν μηδὲ τὸ μικρότατον ὧν ἐκεῖνος ἄρχων ἐβούλευσε, τοῖς δὲ περὶ Βροῦτον ἐπαρχίας τε διένειμε καὶ τιμὰς ἀπέδωκε πρεπούσας, ὥστε πάντας οἴεσθαι τὰ πράγματα κατάστασιν ἔχειν καὶ σύγκρασιν ἀπειληφέναι τὴν ἀρίστην.", "st": "Caes. 67.7"}, {"sp": "N", "t": "ἐπεὶ δὲ τῶν διαθηκῶν τῶν Καίσαρος ἀνοιχθεισῶν εὑρέθη δεδομένη Ῥωμαίων ἑκάστῳ δόσις ἀξιόλογος, καί τὸ σῶμα κομιζόμενον δι’ ἀγορᾶς ἐθεάσαντο ταῖς πληγαῖς διαλελωβημένον, οὐκέτι κόσμον εἶχεν οὐδὲ τάξιν αὐτῶν τὸ πλῆθος, ἀλλὰ τῷ μὲν νεκρῷ περισωρεύσαντες ἐξ ἀγορᾶς βάθρα καί κιγκλίδας καί τραπέζας ὑφῆψαν αὐτοῦ καὶ κατέκαυσαν, ἀράμενοι δὲ δαλοὺς διαπύρους ἔθεον ἐπὶ τὰς οἰκίας τῶν ἀνῃρηκότων ὡς καταφλέξοντες, ἄλλοι δὲ ἐφοίτων πανταχόσε τῆς πόλεως συλλαβεῖν καί διασπάσασθαι τοὺς ἄνδρας ζητοῦντες. οἷς ἐκείνων μὲν οὐδεὶς ἀπήντησεν, ἀλλὰ εὖ πεφραγμένοι πάντες ἦσαν. Κίννας δέ τις τῶν Καίσαρος ἑταίρων ἔτυχε μὲν, ὥς φασι, τῆς παρῳχημένης νυκτὸς ὄψιν ἑωρακὼς ἄτοπον ἐδόκει γὰρ ὑπὸ Καίσαρος ἐπὶ δεῖπνον καλεῖσθαι, παραιτούμενος δὲ ἄγεσθαι τῆς χειρὸς ὑπ’ αὐτοῦ μὴ βουλόμενος, ἀλλ’ ἀντιτείνων. ὡς δ’ ἤκουσεν ἐν ἀγορᾷ τὸ σῶμα καίεσθαι τοῦ Καίσαρος, ἀναστὰς ἐβάδιζεν ἐπὶ τιμῇ, καίπερ ὑφορώμενός τε τὴν ὄψιν ἅμα καί πυρέττων. καί τις ὀφθέντος αὐτοῦ τῶν πολλῶν ἔφρασεν ἑτέρῳ τοὔνομα πυνθανομένῳ, κἀκεῖνος ἄλλῳ, καί διὰ πάντων εὐθὺς ἦν ὡς οὗτός ἐστιν ὁ ἀνὴρ τῶν ἀνῃρηκότων Καίσαρα καί γὰρ ἦν τις ὁμώνυμος ἐκείνῳ Κίννας ἐν τοῖς συνομοσαμένοις, ὃν τοῦτον εἶναι προλαβόντες ὥρμησαν εὐθὺς καί διέσπασαν ἐν μέσῳ τὸν ἄνθρωπον. τοῦτο μάλιστα δείσαντες οἱ περὶ Βροῦτον καί Κάσσιον οὐ πολλῶν ἡμερῶν διαγενομένων ἀπεχώρησαν ἐκ τῆς πόλεως, ἃ δὲ καί πράξαντες καί παθόντες ἐτελεύτησαν, ἐν τοῖς περὶ Βροῦτον γέγραπται.", "st": "Caes. 68.1"}, {"sp": "N", "t": "θνῄσκει δὲ Καῖσαρ τὰ μὲν πάντα γεγονὼς ἔτη πεντήκοντα καὶ ἕξ, Πομπηΐῳ δ’ ἐπιβιώσας οὐ πολὺ πλέον ἐτῶν τεσσάρων, ἣν δὲ τῷ βίῳ παντὶ ἀρχὴν καὶ δυναστείαν διὰ κινδύνων τοσούτων διώκων μόλις κατειργάσατο, ταύτης οὐδὲν ὅτι μὴ τοὔνομα μόνον καὶ τὴν ἐπίφθονον καρπωσάμενος δόξαν παρὰ τῶν πολιτῶν. ὁ μέντοι μέγας αὐτοῦ δαίμων, ᾧ παρὰ τὸν βίον ἐχρήσατο, καὶ τελευτήσαντος ἐπηκολούθησε τιμωρὸς τοῦ φόνου, διά τε γῆς πάσης καὶ θαλάττης ἐλαύνων καὶ ἀνιχνεύων ἄχρι τοῦ μηδένα λιπεῖν τῶν ἀπεκτονότων, ἀλλὰ καὶ τοὺς καθ’ ὁτιοῦν ἢ χειρὶ τοῦ ἔργου θιγόντας ἢ γνώμης μετασχόντας ἐπεξελθεῖν.", "st": "Caes. 69.1"}, {"sp": "N", "t": "θαυμασιώτατον δὲ τῶν μὲν ἀνθρωπίνων τὸ περὶ Κάσσιον ἡττηθεὶς γὰρ ἐν Φιλίπποις ἐκείνῳ τῷ ξιφιδίῳ διέφθειρεν ἑαυτὸν ᾧ κατὰ Καίσαρος ἐχρήσατο τῶν δὲ θείων ὅ τε μέγας κομήτης ἐφάνη γὰρ ἐπὶ νύκτας ἑπτὰ μετὰ τὴν Καίσαρος σφαγὴν διαπρεπής, εἶτα ἠφανίσθη καὶ τὸ περὶ τὸν ἥλιον ἀμαύρωμα τῆς αὐγῆς. ὅλον γὰρ ἐκεῖνον τὸν ἐνιαυτὸν ὠχρὸς μὲν ὁ κύκλος καὶ μαρμαρυγὰς οὐκ ἔχων ἀνέτελλεν, ἀδρανὲς δὲ καὶ λεπτὸν ἀπ’ αὐτοῦ κατῄει τὸ θερμόν, ὥστε τὸν μὲν ἀέρα δνοφερὸν καὶ βαρὺν ἀσθενείᾳ τῆς διακρινούσης αὐτὸν ἀλέας ἐπιφέρεσθαι, τοὺς δὲ καρποὺς ἡμιπέπτους καὶ ἀτελεῖς ἀπανθῆσαι καὶ παρακμάσαι διά τὴν ψυχρότητα τοῦ περιέχοντος. μάλιστα δὲ τὸ Βρούτῳ γενόμενον φάσμα τὴν Καίσαρος ἐδήλωσε σφαγὴν οὐ γενομένην θεοῖς ἀρεστήν ἦν δὲ τοιόνδε. μέλλων τὸν στρατὸν ἐξ Ἀβύδου διαβιβάζειν εἰς τὴν ἑτέραν ἤπειρον ἀνεπαύετο νυκτὸς, ὥσπερ εἰώθει, κατὰ σκηνήν, οὐ καθεύδων, ἀλλὰ φροντίζων περὶ τοῦ μέλλοντος λέγεται γὰρ οὗτος ἁνὴρ ἥκιστα δὴ τῶν στρατηγῶν ὑπνώδης γενέσθαι καὶ πλεῖστον ἑαυτῷ χρόνον ἐγρηγορότι χρῆσθαι πεφυκώς· ψόφου δέ τινος αἰσθέσθαι περὶ τὴν θύραν ἔδοξε, καὶ πρός τὸ τοῦ λύχνου φῶς ἤδη καταφερομένου σκεψάμενος ὄψιν εἶδε φοβερὰν ἀνδρὸς ἐκφύλου τὸ μέγεθος καὶ χαλεποῦ τὸ εἶδος, ἐκπλαγεὶς δὲ τὸ πρῶτον, ὡς ἑώρα μήτε πράττοντά τι μήτε φθεγγόμενον, ἀλλὰ ἑστῶτα σιγῇ παρὰ τὴν κλίνην, ἠρώτα ὅστις ἐστίν. ἀποκρίνεται δ’ αὐτῷ τὸ φάσμα ὁ σὸς, ὦ Βροῦτε, δαίμων κακός ὄψει δέ με περὶ Φιλίππους. τότε μὲν οὖν ὁ Βροῦτος εὐθαρσῶς, ὄψομαι, εἶπε καὶ τὸ δαιμόνιον εὐθὺς ἐκποδὼν ἀπῄει. τῷ δ’ ἱκνουμένῳ χρόνῳ περὶ τοὺς Φιλίππους ἀντιταχθεὶς Ἀντωνίῳ καὶ Καίσαρι τῇ μὲν πρώτῃ μάχῃ κρατήσας τὸ καθ’ ἑαυτὸν ἐτρέψατο καὶ διεξήλασε πορθῶν τὸ Καίσαρος στρατόπεδον, τὴν δὲ δευτέραν αὐτῷ μάχεσθαι μέλλοντι φοιτᾷ τὸ αὐτὸ φάσμα τῆς νυκτὸς αὖθις, οὐχ ὥστε τι προσειπεῖν, ἀλλὰ συνεὶς ὁ Βροῦτος τὸ πεπρωμένον ἔρριψε φέρων ἑαυτὸν εἰς τὸν κίνδυνον. οὐ μὴν ἔπεσεν ἀγωνιζόμενος, ἀλλὰ τῆς τροπῆς γενομένης ἀναφυγὼν πρός τι κρημνῶδες καὶ τῷ ξίφει γυμνῷ προσβαλὼν τὸ στέρνον, ἅμα καὶ φίλου τινὸς, ὥς φασι, συνεπιρρώσαντος τὴν πληγήν, ἀπέθανεν.", "st": "Caes. 69.3"}, {"sp": "HDR", "t": "Φωκίων"}, {"sp": "N", "t": "Δημάδης ὁ ῥήτωρ ἰσχύων μὲν ἐν ταῖς Ἀθήναις διὰ τὸ πρὸς χάριν πολιτεύεσθαι Μακεδόνων καὶ Ἀντιπάτρου, πολλὰ δὲ γράφειν καὶ λέγειν ἀναγκαζόμενος παρὰ τὸ ἀξίωμα τῆς πόλεως καὶ τὸ ἦθος, ἔλεγε συγγνώμης ἄξιος εἶναι πολιτευόμενος τὰ ναυάγια τῆς πόλεως, τοῦτο δὲ εἰ καὶ τῷ ῥήτορι θρασύτερον εἴρηται, δόξειεν ἂν ἀληθὲς εἶναι μετενεχθὲν ἐπὶ τὴν Φωκίωνος πολιτείαν. Δημάδης μὲν γὰρ αὐτὸς ἦν ναυάγιον τῆς πόλεως, οὕτως ἀσελγῶς βιώσας καὶ πολιτευσάμενος ὥστε Ἀντίπατρον εἰπεῖν ἐπ’ αὐτοῦ, γέροντος ἤδη γεγονότος, ὅτι καθάπερ ἱερείου διαπεπραγμένου γλῶσσα καὶ κοιλία μόνον ἀπολείπεται· τὴν δὲ Φωκίωνος ἀρετήν, ὥσπερ ἀνταγωνιστῇ βαρεῖ καὶ βιαίῳ καιρῷ συλλαχοῦσαν, αἱ τύχαι τῆς Ἑλλάδος ἀμαυρὰν καὶ ἀλαμπῆ πρὸς δόξαν ἐποίησαν. οὐ γὰρ Σοφοκλεῖ γε προσεκτέον ἀσθενῆ ποιοῦντι τὴν ἀρετὴν ἐν οἷς φησιν·", "st": "Phoc. 1.1"}, {"sp": "N", "t": "ἀλλ’ οὐ γὰρ, ὦναξ, οὐδ’ ὃς ἂν βλάστῃ μένει<br>νοῦς τοῖς κακῶς πράξασιν, ἀλλ’ ἐξίσταται·", "st": "Phoc. 1.1b"}, {"sp": "N", "t": "τοσοῦτον δὲ τῇ τύχῃ δοτέον ἀντιταττομένῃ πρὸς τοὺς ἀγαθοὺς ἄνδρας ἰσχύειν, ὅσον ἀντὶ τῆς ἀξίας τιμῆς καὶ χάριτος ἐνίοις ψόγους πονηροὺς καὶ διαβολὰς ἐπιφέρουσαν τὴν πίστιν ἀσθενεστέραν ποιεῖν τῆς ἀρετῆς.", "st": "Phoc. 1.1c"}, {"sp": "N", "t": "καίτοι δοκοῦσιν οἱ δῆμοι μᾶλλον εἰς τοὺς ἀγαθοὺς ἐξυβρίζειν ὅταν εὐτυχῶσιν, ὑπὸ πραγμάτων μεγάλων καὶ δυνάμεως ἐπαιρόμενοι· συμβαίνει δὲ τοὐναντίον, αἱ γὰρ συμφοραὶ πικρὰ μὲν τὰ ἤθη καὶ μικρόλυπα καὶ ἀκροσφαλῆ πρὸς ὀργὰς ποιοῦσι, δύσκολον δὲ τὴν ἀκοὴν καὶ τραχεῖαν, ὑπὸ παντὸς λόγου καὶ ῥήματος τόνον ἔχοντος ἐνοχλουμένην ὁ δὲ ἐπιτιμῶν τοῖς ἐξαμαρτανομένοις ἐξονειδίζειν τὰ δυστυχήματα δοκεῖ, καὶ καταφρονεῖν ὁ παρρησιαζόμενος. καὶ καθάπερ τὸ μέλι λυπεῖ τὰ τετρωμένα καὶ ἡλκωμένα μέρη τοῦ σώματος, οὕτως πολλάκις οἱ ἀληθινοὶ καὶ νοῦν ἔχοντες λόγοι δάκνουσι καὶ παροξύνουσι τοὺς κακῶς πράττοντας, ἐὰν μὴ προσηνεῖς ὦσι καὶ συνείκοντες, ὥσπερ ἀμέλει τὸ ἡδὺ μενοεικὲς ὁ ποιητὴς κέκληκεν, ὡς τῷ ἡδομένῳ τῆς ψυχῆς ὑπεῖκον καὶ μὴ μαχόμενον μηδ’ ἀντιτυποῦν. καὶ γὰρ ὄμμα φλεγμαῖνον ἥδιστα τοῖς σκιεροῖς καὶ ἀλαμπέσιν ἐνδιατρίβει χρώμασι, τὰ δὲ αὐγὴν ἔχοντα καὶ φῶς ἀποστρέφεται, καὶ πόλις ἐν τύχαις ἀβουλήτοις γενομένη ψοφοδεὲς καὶ τρυφερόν ἐστι δι’ ἀσθένειαν ἀνέχεσθαι παρρησίας, ὅτε μάλιστα δεῖται, τῶν πραγμάτων ἀναφορὰν ἁμαρτήματος οὐκ ἐχόντων, διὸ πάντῃ σφαλερὸν ἡ τοιαύτη πολιτεία· συναπόλλυσι γὰρ τὸν πρὸς χάριν λέγοντα καὶ προαπόλλυσι τὸν μὴ χαριζόμενον.", "st": "Phoc. 2.1"}, {"sp": "N", "t": "ὥσπερ οὖν τὸν ἥλιον οἱ μαθηματικοὶ λέγουσι μήτε τὴν αὐτὴν τῷ οὐρανῷ φερόμενον φοράν μήτε ἄντικρυς ἐναντίαν καὶ ἀντιβατικήν, ἀλλὰ λοξῷ καὶ παρεγκεκλιμένῳ πορείας σχήματι χρώμενον ὑγρὰν καὶ εὐκαμπῆ καὶ περιελιττομένην ἕλικα ποιεῖν, ᾗ σῴζεται πάντα καὶ λαμβάνει τὴν ἀρίστην κρᾶσιν, οὕτως ἄρα τῆς πολιτείας ὁ μὲν ὄρθιος ἄγαν καὶ πρὸς ἅπαντα τοῖς δημοσίοις ἀντιβαίνων τόνος ἀπηνὴς καὶ σκληρός, ὥσπερ αὖ πάλιν ἐπισφαλὲς καὶ κάταντες τὸ συνεφελκόμενον οἷς ἁμαρτάνουσιν οἱ πολλοὶ καὶ συνεπιρρέπον, ἡ δὲ ἀνθυπείκουσα πειθομένοις καὶ διδοῦσα τὸ πρὸς χάριν, εἶτα ἀπαιτοῦσα τὸ συμφέρον ἐπιστασία καὶ κυβέρνησις ἀνθρώπων πολλὰ πρᾴως καὶ χρησίμως ὑπουργούντων, εἰ μὴ πάντα δεσποτικῶς καὶ βιαίως ἄγοιντο, σωτήριος, ἐργώδης δὲ καὶ χαλεπὴ καὶ τὸ σεμνὸν ἔχουσα τῷ ἐπιεικεῖ δύσμικτον· ἐὰν δὲ μιχθῇ, τοῦτό ἔστιν ἡ πάντων μὲν ῥυθμῶν, πασῶν δὲ ἁρμονιῶν ἐμμελεστάτη καὶ μουσικωτάτη κρᾶσις, ᾗ καὶ τὸν κόσμον ὁ θεὸς λέγεται διοικεῖν, οὐ βιαζόμενος, ἀλλὰ πειθοῖ καὶ λόγῳ παράγων τὴν ἀνάγκην.", "st": "Phoc. 2.4"}, {"sp": "N", "t": "ταῦτα δὲ καὶ Κάτωνι τῷ νέῳ συνέβη, καὶ γὰρ οὗτος οὐ πιθανὸν ἔσχεν οὐδὲ προσφιλὲς ὄχλῳ τὸ ἦθος, οὐδὲ ἤνθησεν ἐν τῇ πολιτείᾳ πρὸς χάριν· ἀλλ’ ὁ μὲν Κικέρων φησὶν αὐτὸν ὥσπερ ἐν τῇ Πλάτωνος πολιτείᾳ καὶ οὐκ ἐν τῇ Ῥωμύλου πολιτευόμενον ὑποστάθμῃ τῆς ὑπατείας ἐκπεσεῖν, ἐμοὶ δὲ ταὐτὸ δοκεῖ παθεῖν τοῖς μὴ καθ’ ὥραν ἐκφανεῖσι καρποῖς. ὡς γὰρ ἐκείνους ἡδέως ὁρῶντες καὶ θαυμάζοντες οὐ χρῶνται, οὕτως ἡ Κάτωνος ἀρχαιοτροπία διὰ χρόνων πολλῶν ἐπιγενομένη βίοις διεφθορόσι καὶ πονηροῖς ἔθεσι δόξαν μὲν εἶχε μεγάλην καὶ κλέος, οὐκ ἐνήρμοσε δὲ ταῖς χρείαις διὰ βάρος καὶ μέγεθος τῆς ἀρετῆς ἀσύμμετρον τοῖς καθεστῶσι καιροῖς. καὶ γὰρ αὐτὸς οὐ κεκλιμένης μὲν ἤδη τῆς πατρίδος, ὥσπερ ὁ Φωκίων, πολὺν δὲ χειμῶνα καὶ σάλον ἐχούσης, ὅσον ἱστίων καὶ κάλων ἐπιλαβέσθαι καὶ παραστῆναι τοῖς πλέον δυναμένοις πολιτευσάμενος, οἰάκων δὲ καὶ κυβερνήσεως ἀπωσθείς, ὅμως μέγαν ἀγῶνα τῇ τύχῃ περιέστησεν. εἷλε μὲν γὰρ καὶ κατέβαλε τὴν πολιτείαν δι’ ἄλλους, μόλις δὲ καὶ βραδέως καὶ χρόνῳ πολλῷ καὶ παρὰ μικρὸν ἐλθοῦσαν περιγενέσθαι διὰ Κάτωνα καὶ τὴν Κάτωνος ἀρετήν· ᾗ παραβάλλομεν τὴν Φωκίωνος, οὐ κατὰ κοινὰς ὁμοιότητας, ὡς ἀγαθῶν καὶ πολιτικῶν ἀνδρῶν ἔστι γὰρ ἀμέλει καὶ ἀνδρείας διαφορὰ πρὸς ἀνδρείαν, ὡς τῆς Ἀλκιβιάδου πρὸς τὴν Ἐπαμεινώνδου, καὶ φρονήσεως πρὸς φρόνησιν, ὡς τῆς Θεμιστοκλέους πρὸς τὴν Ἀριστείδου, καὶ δικαιοσύνης πρὸς δικαιοσύνην, ὡς τῆς Νομᾶ πρὸς τὴν Ἀγησιλάου. τούτων δὲ τῶν ἀνδρῶν αἱ ἀρεταὶ μέχρι τῶν τελευταίων καὶ ἀτόμων διαφορῶν ἕνα χαρακτῆρα καὶ μορφὴν καὶ χρῶμα κοινὸν ἤθους ἐγκεκραμένον ἐκφέρουσιν, ὥσπερ ἴσῳ μέτρῳ μεμιγμένου πρὸς τὸ αὐστηρὸν τοῦ φιλανθρώπου καὶ πρὸς τὸ ἀσφαλὲς τοῦ ἀνδρείου, καὶ τῆς ὑπὲρ ἄλλων μὲν κηδεμονίας, ὑπὲρ αὐτῶν δὲ ἀφοβίας, καὶ πρὸς μὲν τὸ αἰσχρὸν εὐλαβείας, πρὸς δὲ τὸ δίκαιον εὐτονίας συνηρμοσμένης ὁμοίως· ὥστε λεπτοῦ πάνυ λόγου δεῖσθαι καθάπερ ὀργάνου πρὸς διάκρισιν καὶ ἀνεύρεσιν τῶν διαφερόντων.", "st": "Phoc. 3.1"}, {"sp": "N", "t": "τὸ μὲν οὖν Κάτωνος ὡμολόγηται γένος ἐκ λαμπρῶν ὑπάρχειν, ὡς λεχθήσεται· Φωκίωνα δὲ τεκμαίρομαι μὴ παντάπασιν εἶναι γένους ἀτίμου καὶ καταπεπτωκότος. εἰ γὰρ ἦν, ὥς φησιν Ἰδομενεύς, δοιδυκοποιοῦ πατρός, οὐκ ἂν ἐν τῷ λόγῳ Γλαύκιππος ὁ Ὑπερείδου μυρία συνειλοχὼς καὶ εἰρηκὼς κατ’ αὐτοῦ κακὰ τὴν δυσγένειαν παρῆκεν, οὐδ’ ἂν οὕτως ἐλευθερίου βίου καὶ σώφρονος παιδείας μετέσχεν ὥστε τῆς Πλάτωνος ἔτι μειράκιον ὤν, ὕστερον δὲ τῆς Ξενοκράτους διατριβῆς, ἐν Ἀκαδημείᾳ μετασχεῖν, καὶ τῶν ἀρίστων ἐξ ἀρχῆς ἐπιτηδευμάτων ζηλωτὴς γενέσθαι. Φωκίωνα γὰρ οὔτε γελάσαντά τις οὔτε κλαύσαντα ῥᾳδίως Ἀθηναίων εἶδεν, οὐδ’ ἐν βαλανείῳ δημοσιεύοντι λουσάμενον, ὡς ἱστόρηκε Δοῦρις, οὐδὲ ἐκτὸς ἔχοντα τὴν χεῖρα τῆς περιβολῆς, ὅτε τύχοι περιβεβλημένος, ἐπεὶ κατά γε τὴν χώραν καὶ τὰς στρατείας ἀνυπόδητος ἀεὶ καὶ γυμνὸς ἐβάδιζεν, εἰ μὴ ψῦχος ὑπερβάλλον εἴη καὶ δυσκαρτέρητον, ὥστε καὶ παίζοντας ἤδη τοὺς στρατευομένους σύμβολον μεγάλου ποιεῖσθαι χειμῶνος ἐνδεδυμένον Φωκίωνα.", "st": "Phoc. 4.1"}, {"sp": "N", "t": "τῷ δὲ ἤθει προσηνέστατος ὢν καὶ φιλανθρωπότατος ἀπὸ τοῦ προσώπου δυσξύμβολος ἐφαίνετο καὶ σκυθρωπός, ὥστε μὴ ῥᾳδίως ἄν τινα μόνον ἐντυχεῖν αὐτῷ τῶν ἀσυνήθων, διὸ καὶ Χάρητί ποτε πρὸς τὰς ὀφρῦς αὐτοῦ λέγοντι τῶν Ἀθηναίων ἐπιγελώντων, οὐδὲν, εἶπεν, αὕτη ὑμᾶς λελύπηκεν ἡ ὀφρύς· ὁ δὲ τούτων γέλως πολλὰ κλαῦσαι τὴν πόλιν πεποίηκεν. ὁμοίως δέ πως τοῦ Φωκίωνος καὶ ὁ λόγος ἦν ἐπὶ χρηστοῖς εὐτυχήμασι καὶ διανοήμασι σωτήριος, προστακτικήν τινα καὶ αὐστηρὰν καὶ ἀνήδυντον ἔχων βραχυλογίαν. ὡς γὰρ ὁ Ζήνων ἔλεγεν ὅτι δεῖ τὸν φιλόσοφον εἰς νοῦν ἀποβάπτοντα προφέρεσθαι τὴν λέξιν, οὕτως ὁ Φωκίωνος λόγος πλεῖστον ἐν ἐλαχίστῃ λέξει νοῦν εἶχε. καὶ πρὸς τοῦτο ἔοικεν ἀπιδὼν ὁ Σφήττιος Πολύευκτος εἰπεῖν ὅτι ῥήτωρ μὲν ἄριστος εἴη Δημοσθένης, εἰπεῖν δὲ δεινότατος ὁ Φωκίων. ὡς γὰρ ἡ τοῦ νομίσματος ἀξία πλείστην ἐν ὄγκῳ βραχυτάτῳ δύναμιν ἔχει, οὕτω λόγου δεινότης ἐδόκει πολλὰ σημαίνειν ἀπ’ ὀλίγων, καὶ μέντοι καὶ αὐτόν ποτε τὸν Φωκίωνά φασι πληρουμένου τοῦ θεάτρου περιπατεῖν ὑπὸ σκηνήν αὐτόν ὄντα πρὸς ἑαυτῷ τὴν διάνοιαν εἰπόντος δέ τινος τῶν φίλων, σκεπτομένῳ, Φωκίων, ἔοικας, ναὶ μὰ τὸν Δία, φάναι, σκέπτομαι εἴ τι δύναμαι τοῦ λόγου ἀφελεῖν ὃν μέλλω λέγειν πρὸς Ἀθηναίους. ὁ δὲ Δημοσθένης τῶν μὲν ἄλλων κατεφρόνει πολὺ ῥητόρων, ἀνισταμένου δὲ Φωκίωνος εἰώθει λέγειν ἀτρέμα πρὸς τοὺς φίλους, ἡ τῶν ἐμῶν λόγων κοπὶς πάρεστιν. ἀλλὰ τοῦτο μὲν ἴσως πρὸς τὸ ἦθος ἀνοιστέον ἐπεὶ καὶ ῥῆμα καὶ νεῦμα μόνον ἀνδρὸς ἀγαθοῦ μυρίοις ἐνθυμήμασι καὶ περιόδοις ἀντίρροπον ἔχει πίστιν.", "st": "Phoc. 5.1"}, {"sp": "N", "t": "νέος δὲ ὢν Χαβρίᾳ προσέμιξεν ἑαυτὸν τῷ στρατηγῷ καὶ παρείπετο, πολλὰ μὲν εἰς ἐμπειρίαν τῶν πολεμικῶν ὠφελούμενος, ἔστι δὲ ἐν οἷς ἐπανορθούμενος τήν ἐκείνου φύσιν ἀνώμαλον οὖσαν καὶ ἄκρατον. νωθρὸς γὰρ ὢν ὁ Χαβρίας καὶ δυσκίνητος ἄλλως ἐν αὐτοῖς τοῖς ἀγῶσιν ὤργα καὶ διεπυροῦτο τῷ θυμῷ καὶ συνεξέπιπτε τοῖς θρασυτάτοις παραβολώτερον, ὥσπερ ἀμέλει καὶ κατέστρεψε τόν βίον ἐν Χίῳ πρῶτος εἰσελάσας τῇ τριήρει καὶ βιαζόμενος πρὸς τήν ἀπόβασιν. ἀσφαλὴς οὖν ἅμα καὶ δραστήριος ὁ Φωκίων φαινόμενος τήν τε μέλλησιν ἀνεθέρμαινε τοῦ Χαβρίου, καὶ πάλιν ἀφῄρει τήν ἄκαιρον ὀξύτητα τῆς ὁρμῆς. ὅθεν εὐμενὴς ὢν ὁ Χαβρίας καὶ χρηστός, ἠγάπα καὶ προῆγεν αὐτὸν ἐπὶ πράξεις καὶ ἡγεμονίας, γνώριμον ποιῶν τοῖς Ἕλλησι, καὶ τὰ πλείστης ἄξια σπουδῆς ἐκείνῳ χρώμενος. κἀκ τῆς περὶ Νάξον ναυμαχίας ὄνομα καὶ δόξαν οὐ μικρὰν Φωκίωνι περιεποίησε· τοῦ γὰρ εὐωνύμου κέρως ἀπέδωκεν αὐτῷ τήν ἡγεμονίαν, καθ’ ὃ καὶ τήν μάχην ὀξεῖαν εἶχεν ὁ ἀγὼν καὶ κρίσιν ἐποίησε ταχεῖαν. πρώτην οὖν ἐκείνην ναυμαχίαν ἡ πόλις αὐτὴ δι’ αὑτῆς ἀγωνισαμένη τοῖς Ἕλλησι μετὰ τήν ἅλωσιν, καὶ κατατυχοῦσα, τόν τε Χαβρίαν ὑπερηγάπησε καὶ τοῦ Φωκίωνος ὡς ἀνδρὸς ἡγεμονικοῦ λόγον ἔσχεν. ἐνίκων δὲ μεγάλοις μυστηρίοις· καὶ παρεῖχεν οἰνοχόημα Χαβρίας Ἀθηναίοις καθ’ ἕκαστον ἐνιαυτὸν τῇ ἕκτῃ ἐπὶ δέκα τοῦ Βοηδρομιῶνος.", "st": "Phoc. 6.1"}, {"sp": "N", "t": "ἐκ τούτου λέγεται πέμποντος αὐτὸν ἐπὶ τὰς νησιωτικὰς συντάξεις τοῦ Χαβρίου καὶ ναῦς εἴκοσι διδόντος εἰπεῖν, εἰ μὲν ὡς πολεμήσων πέμποιτο, μείζονος δεῖν δυνάμεως, εἰ δὲ ὡς πρὸς συμμάχους, ἀρκεῖν ναῦν μίαν καὶ πλεύσαντα τῇ αὐτοῦ τριήρει καὶ διαλεχθέντα ταῖς πόλεσι καὶ συγγενόμενον τοῖς ἄρχουσιν ἐπιεικῶς καὶ ἀφελῶς καταπλεῦσαι μετὰ πολλῶν νεῶν, ἃς ἀπέστειλαν οἱ σύμμαχοι τὰ χρήματα τοῖς Ἀθηναίοις κομιζούσας. οὐ μόνον δὲ ζῶντα τὸν Χαβρίαν θεραπεύων διετέλει καὶ τιμῶν, ἀλλὰ καὶ τελευτήσαντος αὐτοῦ τῶν προσηκόντων καλῶς ἐπεμελεῖτο, καὶ τὸν παῖδα Κτήσιππον ἐβούλετο μὲν ἄνδρα ποιεῖν ἀγαθόν, ἔμπληκτον δὲ ὁρῶν καὶ ἀνάγωγον ὅμως οὐκ ἀπεῖπεν ἐπανορθούμενος καὶ ἀποκρύπτων τὰ αἴσχη. πλὴν ἅπαξ λέγεται, παρενοχλοῦντος ἐν στρατείᾳ τινὶ τοῦ νεανίσκου καὶ κόπτοντος αὐτὸν ἐρωτήμασιν ἀκαίροις καὶ συμβουλίαις οἷον ἐπανορθουμένου καὶ παραστρατηγοῦντος, εἰπεῖν· ὦ Χαβρία, Χαβρία, μεγάλην γέ σοι χάριν ἐκτίνω τῆς φιλίας ὑπομένων σου τὸν υἱόν.", "st": "Phoc. 7.1"}, {"sp": "N", "t": "ὁρῶν δὲ τοὺς τὰ κοινὰ πράσσοντας τότε διῃρημένους ὥσπερ ἀπὸ κλήρου τὸ στρατήγιον καὶ τὸ βῆμα, καὶ τοὺς μὲν λέγοντας ἐν τῷ δήμῳ καὶ γράφοντας μόνον, ὧν Εὔβουλος ἦν καὶ Ἀριστοφῶν καὶ Δημοσθένης καὶ Λυκοῦργος καὶ Ὑπερείδης, Διοπείθην δὲ καὶ Μενεσθέα καὶ Λεωσθένην καὶ Χάρητα τῷ στρατηγεῖν καὶ πολεμεῖν αὔξοντας ἑαυτούς, ἐβούλετο τὴν Περικλέους καὶ Ἀριστείδου καὶ Σόλωνος πολιτείαν ὥσπερ ὁλόκληρον καὶ διηρμοσμένην ἐν ἀμφοῖν ἀναλαβεῖν καὶ ἀποδοῦναι. καὶ γὰρ τῶν ἀνδρῶν ἐκείνων ἕκαστος ἐφαίνετο κατὰ τὸν Ἀρχίλοχον,", "st": "Phoc. 7.3"}, {"sp": "N", "t": "ἀμφότερον, θεράπων μὲν Ἐνυαλίοιο θεοῖο,<br>καὶ Μουσέων ἐρατᾶν δῶρον ἐπιστάμενος·", "st": "Phoc. 7.3b"}, {"sp": "N", "t": "καὶ τὴν θεὸν ἑώρα πολεμικήν τε ἅμα καὶ πολιτικὴν οὖσαν καὶ προσαγορευομένην.", "st": "Phoc. 7.3c"}, {"sp": "N", "t": "οὕτω δὲ συντάξας ἑαυτόν ἐπολιτεύετο μὲν ἀεὶ πρὸς εἰρήνην καὶ ἡσυχίαν, ἐστρατήγησε δὲ πλείστας οὐ μόνον τῶν καθ’ ἑαυτόν, ἀλλὰ καὶ τῶν πρὸ αὐτοῦ στρατηγίας, οὐ παραγγέλλων οὐδὲ μετιών, ἀλλ’ οὐδὲ φεύγων οὐδὲ ἀποδιδράσκων τῆς πόλεως καλούσης, ὁμολογεῖται γὰρ ὅτι πέντε καὶ τεσσαράκοντα στρατηγίας ἔλαβεν οὐδ’ ἅπαξ ἀρχαιρεσίοις παρατυχών, ἀλλ’ ἀπόντα μεταπεμπομένων αὐτὸν ἀεὶ καὶ χειροτονούντων, ὥστε θαυμάζειν τοὺς οὐκ εὖ φρονοῦντας τὸν δῆμον ὅτι, πλεῖστα τοῦ Φωκίωνος ἀντικρούοντος αὐτῷ καὶ μηδὲν εἰπόντος πώποτε μηδὲ πράξαντος πρὸς χάριν, ὥσπερ ἀξιοῦσι τοὺς βασιλεῖς τοῖς κόλαξι χρῆσθαι μετὰ τὸ κατὰ χειρὸς ὕδωρ, ἐχρῆτο οὗτος τοῖς μὲν κομψοτέροις; καὶ ἱλαροῖς ἐν παιδιᾶς μέρει δημαγωγοῖς, ἐπὶ δὲ τὰς ἀρχὰς ἀεὶ νήφων καὶ σπουδάζων τὸν αὐστηρότατον καὶ φρονιμώτατον ἐκάλει τῶν πολιτῶν καὶ μόνον ἢ μᾶλλον ταῖς βουλήσεσιν αὐτοῦ καὶ ὁρμαῖς ἀντιτασσόμενον. χρησμοῦ μὲν γὰρ ἐκ Δελφῶν ἀναγνωσθέντος ὅτι, τῶν ἄλλων Ἀθηναίων ὁμοφρονούντων, εἷς ἀνὴρ ἐναντία φρονοίη τῇ πόλει, παρελθὼν ὁ Φωκίων ἀμελεῖν ἐκέλευσεν, ὡς αὐτὸς ὢν ὁ ζητούμενος· μόνῳ γὰρ αὐτῷ μηδὲν ἀρέσκειν τῶν πραττομένων. ἐπεὶ δὲ λέγων ποτὲ γνώμην πρὸς τὸν δῆμον εὐδοκίμει καὶ πάντας ὁμαλῶς ἑώρα τὸν λόγον ἀποδεχομένους, ἐπιστραφεὶς πρὸς τοὺς φίλους εἶπεν· οὐ δή πού τι κακὸν λέγων ἐμαυτὸν λέληθα;", "st": "Phoc. 8.1"}, {"sp": "N", "t": "πρὸς δὲ θυσίαν τινὰ τῶν Ἀθηναίων αἰτούντων ἐπιδόσεις, καὶ τῶν ἄλλων ἐπιδιδόντων, κληθεὶς πολλάκις ἔφη· τούτους αἰτεῖτε τοὺς πλουσίους· ἐγὼ δὲ αἰσχυνοίμην ἄν, εἰ τούτῳ μὴ ἀποδιδοὺς ὑμῖν ἐπιδοίην, δείξας Καλλικλέα τὸν δανειστήν, ὡς δ’ οὐκ ἐπαύοντο κεκραγότες καὶ καταβοῶντες, λόγον εἶπεν αὐτοῖς τοῦτον· ἀνὴρ δειλὸς ἐπὶ πόλεμον ἐξῄει, φθεγξαμένων δὲ κοράκων τὰ ὅπλα θεὶς ἡσύχαζεν· εἶτα ἀναλαβὼν αὖθις ἐξῄει, καὶ φθεγγομένων πάλιν ὑπέστη, καὶ τέλος εἶπεν· Ὑμεῖς κεκράξεσθε μὲν μέγιστον ὡς δυνατόν, ἐμοῦ δὲ οὐ γεύσεσθε. πάλιν δέ ποτε τῶν Ἀθηναίων ἐξαγαγεῖν αὐτὸν ἐπὶ τοὺς πολεμίους κελευόντων, ὡς δ’ οὐκ ἐβούλετο, δειλὸν καὶ ἄνανδρον ἀποκαλούντων, οὔτε ὑμεῖς, εἶπεν, ἐμὲ δύνασθε ποιῆσαι θαρσαλέον οὔτε ἐγὼ ὑμᾶς δειλούς. οὐ μὴν ἀλλ’ ἴσμεν ἀλλήλους. ἐν δὲ καιροῖς ἐπισφαλέσι τραχυνομένου τοῦ δήμου πρὸς αὐτὸν σφόδρα καὶ τῆς στρατηγίας εὐθύνας ἀπαιτοῦντος, σωθείητε, εἶπεν, ὦ μακάριοι, πρῶτον. ἐπεὶ δὲ πολεμοῦντες μὲν ἦσαν ταπεινοὶ καὶ περιδεεῖς, γενομένης δὲ εἰρήνης ἐθρασύνοντο καὶ κατεβόων τοῦ Φωκίωνος ὡς ἀφῃρημένου τὴν νίκην αὐτῶν, εὐτυχεῖτε, εἶπεν, ἔχοντες στρατηγὸν εἰδότα ὑμᾶς· ἐπεὶ πάλαι ἂν ἀπωλώλειτε. τοῖς δὲ Βοιωτοῖς οὐ βουλομένων αὐτῶν δικάζεσθαι περὶ τῆς χώρας, ἀλλὰ πολεμεῖν, συνεβούλευε διὰ τῶν λόγων, ἐν οἷς εἰσι κρείττους, μὴ διὰ τῶν ὅπλων, ἐν οἷς εἰσιν ἥττους, μάχεσθαι. λέγοντα δὲ αὐτὸν οὐ προσιεμένων οὐδὲ ὑπομενόντων ἀκούειν, ἐμέ, εἶπεν, ὑμεῖς ἃ μὴ βούλομαι ποιεῖν βιάσασθαι δύνασθε, λέγειν δὲ ἃ μὴ δεῖ παρὰ γνώμην οὐκ ἀναγκάσετε. τῶν δὲ ἀντιπολιτευομένων αὐτῷ ῥητόρων Δημοσθένους μὲν εἰπόντος, ἀποκτενοῦσί σε Ἀθηναῖοι, Φωκίων, ἂν μανῶσιν, εἶπε· σὲ δέ, ἂν σωφρονῶσι· Πολύευκτον δὲ τὸν Σφήττιον ὁρῶν ἐν καύματι συμβουλεύοντα τοῖς Ἀθηναίοις πολεμεῖν πρὸς Φίλιππον, εἶτα ὑπ’ ἄσθματος πολλοῦ καὶ ἱδρῶτος, ἅτε δὴ καὶ ὑπέρπαχυν ὄντα, πολλάκις ἐπιρροφοῦντα τοῦ ὕδατος. ἄξιον, ἔφη, τούτῳ πιστεύσαντας ὑμᾶς ψηφίσασθαι τὸν πόλεμον, ὃν τί οἴεσθε ποιήσειν ἐν τῷ θώρακι καὶ τῇ ἀσπίδι, τῶν πολεμίων ἐγγὺς ὄντων, ὅτε λέγων πρὸς ὑμᾶς ἃ ἔσκεπται κινδυνεύει πνιγῆναι; τοῦ δὲ Λυκούργου πολλὰ βλάσφημα πρὸς αὐτὸν εἰπόντος ἐν ἐκκλησίᾳ, καὶ πρὸς ἅπασιν ὅτι, δέκα τῶν πολιτῶν ἐξαιτοῦντος Ἀλεξάνδρου, συνεβούλευεν ἐκδοῦναι, εἶπε· πολλὰ ἐγὼ συμβεβούλευκα καλὰ καὶ συμφέροντα τούτοις, ἀλλ’ οὐ πείθονταί μοι.", "st": "Phoc. 9.1"}, {"sp": "N", "t": "ἦν δέ τις Ἀρχιβιάδης ἐπικαλούμενος Λακωνιστής, πώγωνά τε καθειμένος ὑπερφυῆ μεγέθει καὶ τρίβωνα φορῶν ἀεὶ καὶ σκυθρωπάζων τοῦτον ἐν βουλῇ θορυβούμενος ὁ Φωκίων ἐπεκαλεῖτο τῷ λόγῳ μάρτυν ἅμα καὶ βοηθόν, ὡς δὲ ἀναστὰς ἐκεῖνος ἃ πρὸς χάριν ἦν τοῖς Ἀθηναίοις συνεβούλευεν, ἁψάμενος αὐτοῦ τῶν γενείων· ὦ Ἀρχιβιάδη, εἶπε, τί οὖν οὐκ ἀπεκείρω; Ἀριστογείτονος δὲ τοῦ συκοφάντου πολεμικοῦ μὲν ὄντος ἐν ταῖς ἐκκλησίαις καὶ παροξύνοντος ἐπὶ τὰς πράξεις τὸν δῆμον, ἐν δὲ τῷ καταλόγῳ προσελθόντος ἐπὶ βακτηρίᾳ τὼ σκέλη καταδεδεμένου, πόρρωθεν αὐτὸν ἀπὸ τοῦ βήματος ἰδὼν ὁ Φωκίων ἀνέκραγε· γράφε καὶ Ἀριστογείτονα χωλὸν καὶ πονηρόν. ὥστε θαυμάζειν ὅπως καὶ ὁπόθεν τραχὺς οὕτως ἀνὴρ καὶ σκυθρωπὸς ἐκτήσατο τὴν τοῦ χρηστοῦ προσηγορίαν.", "st": "Phoc. 10.1"}, {"sp": "N", "t": "ἔστι δέ, οἶμαι, χαλεπόν, οὐ μὴν ἀδύνατον, ὥσπερ οἶνον, καὶ ἄνθρωπον τὸν αὐτὸν ἡδὺν ἅμα καὶ αὐστηρὸν εἶναι· καθάπερ ἕτεροι πάλιν, φαινόμενοι γλυκεῖς, ἀηδέστατοι τοῖς χρωμένοις εἰσὶ καὶ βλαβερώτατοι. καίτοι φασὶν Ὑπερείδην ποτὲ εἰπεῖν πρὸς τὸν δῆμον, ἄνδρες Ἀθηναῖοι, μὴ σκοπεῖτε μόνον εἰ πικρός, ἀλλ’ εἰ προῖκά εἰμι πικρός, ὥσπερ τῇ πλεονεξίᾳ μόνον ἐπαχθεῖς καὶ λυπηροὺς ὄντας, οὐχὶ μᾶλλον, ὅσοι πρὸς ὕβριν καὶ φθόνον ἢ ὀργὴν ἢ φιλονεικίαν τινὰ χρῶνται τῷ δύνασθαι, τούτους δεδιότων καὶ προβαλλομένων τῶν πολλῶν. Φωκίων τοίνυν ἔχθρᾳ μὲν οὐδένα τῶν πολιτῶν κακῶς ἐποίησεν, οὐδὲ ἐνόμιζεν ἐχθρόν ἀλλ’ ὅσον ἔδει μόνον τῶν ἐνισταμένων οἷς ἔπραττεν ὑπὲρ τῆς πατρίδος κατεξαναστῆναι τραχὺς ὢν καὶ δυσεκβίαστος καὶ ἀπαραίτητος, εἰς τὸν ἄλλον βίον εὐμενῆ πᾶσι καὶ κοινὸν καὶ φιλάνθρωπον ἑαυτὸν παρεῖχεν, ὥστε καὶ πταίσασι βοηθεῖν καὶ κινδυνεύουσι συνεξετάζεσθαι τοῖς διαφόροις. ἐγκαλούντων δὲ τῶν φίλων ὅτι πονηρῷ τινι κρινομένῳ συνεῖπε, τοὺς χρηστοὺς ἔφη μὴ δεῖσθαι βοηθείας. Ἀριστογείτονος δὲ τοῦ συκοφάντου μετὰ τὴν καταδίκην πέμψαντος καὶ δεηθέντος ἐλθεῖν πρὸς αὐτόν, ὑπακούσας ἐβάδιζεν εἰς τὸ δεσμωτήριον· οὐκ ἐώντων δὲ τῶν φίλων, ἐάσατε, εἶπεν, ὦ μακάριοι· ποῦ γὰρ ἄν τις ἥδιον Ἀριστογείτονι συμβάλοι;", "st": "Phoc. 10.3"}, {"sp": "N", "t": "καὶ μὴν οἵ γε σύμμαχοι καὶ οἱ νησιῶται τοὺς Ἀθήνηθεν ἀποστόλους ἑτέρου μὲν ἐκπλέοντος στρατηγοῦ πολεμίους νομίζοντες ἐφράγνυντο τείχη καὶ λιμένας ἀπεχώννυσαν καὶ κατεκόμιζον ἀπὸ τῆς χώρας εἰς τὰς πόλεις βοσκήματα καὶ ἀνδράποδα καὶ γυναῖκας καὶ παῖδας· εἰ δὲ Φωκίων ἡγοῖτο, πόρρω ναυσὶν ἰδίαις ἀπαντῶντες ἐστεφανωμένοι καὶ χαίροντες ὡς αὑτοὺς κατῆγον.", "st": "Phoc. 11.1"}, {"sp": "N", "t": "Παραδυομένου δὲ εἰς τὴν Εὔβοιαν τοῦ Φιλίππου καί δύναμιν ἐκ Μακεδονίας διαβιβάζοντος καὶ τὰς πόλεις οἰκειουμένου διὰ τυράννων, Πλουτάρχου δὲ τοῦ Ἐρετριέως καλοῦντος τοὺς Ἀθηναίους καί δεομένου τὴν νῆσον ἐξελέσθαι καταλαμβανομένην ὑπὸ τοῦ Μακεδόνος, ἀπεστάλη στρατηγὸς ὁ Φωκίων ἔχων δύναμιν οὐ πολλήν, ὡς τῶν ἐκεῖ συστησομένων ἑτοίμως πρὸς αὐτόν. εὑρὼν δὲ προδοτῶν ἅπαντα μεστὰ καί νοσοῦντα καὶ διορωρυγμένα δωροδοκίαις εἰς κίνδυνον μέγαν κατέστη· καί τινα λόφον χαράδρᾳ βαθείᾳ τῶν περὶ τὰς Ταμύνας ἐπιπέδων ἀποκρυπτόμενον καταλαβών συνεῖχεν ἐν τούτῳ καί συνεκράτει τὸ μαχιμώτατον τῆς δυνάμεως. τῶν δὲ ἀτάκτων καί λάλων καί πονηρῶν διαδιδρασκόντων ἐκ τοῦ στρατοπέδου καί ἀποχωρούντων ἐκέλευσεν ἀμελεῖν τοὺς ἡγεμόνας· καί γὰρ ἐνταῦθα δυσχρήστους ὑπὸ ἀταξίας ἔσεσθαι καί βλαβεροὺς τοῖς μαχομένοις, κἀκεῖ τοιαῦτα συνειδότας αὑτοῖς ἧττον αὐτοῦ καταβοήσεσθαι καί μὴ πάνυ συκοφαντήσειν.", "st": "Phoc. 12.1"}, {"sp": "N", "t": "ὡς δὲ ἐπῄεσαν οἱ πολέμιοι, κελεύσας ἐν τοῖς ὅπλοις ἀτρεμεῖν ἄχρι ἂν αὐτὸς σφαγιάσηται, πλείω διέτριβε χρόνον ἢ δυσιερῶν ἢ βουλόμενος ἐγγυτέρω τοὺς πολεμίους ἐπισπάσασθαι. διὸ πρῶτον μὲν ὁ Πλούταρχος οἰόμενος ἀποδειλιᾶν καὶ κατοκνεῖν ἐκεῖνον ἐξέδραμε μετὰ τῶν ξένων ἔπειτα τοῦτον ἰδόντες οἱ ἱππεῖς οὐκ ἐκαρτέρησαν, ἀλλ’ ἤλαυνον εὐθὺς εἰς τοὺς πολεμίους ἀσύντακτοι καὶ σποράδες ἐκ τοῦ στρατοπέδου προσφερόμενοι. νικωμένων δὲ τῶν πρώτων ἅπαντες ἐσκεδάσθησαν καὶ ὁ Πλούταρχος ἔφυγε· καὶ τῷ χάρακι προσμίξαντες ἔνιοι τῶν πολεμίων ἐκκόπτειν ἐπειρῶντο καὶ διασπᾶν ὡς ἁπάντων κεκρατηκότες, ἐν τούτῳ δὲ τῶν ἱερῶν γενομένων, τοὺς μὲν εὐθὺς ἐκ τοῦ στρατοπέδου προσπεσόντες οἱ Ἀθηναῖοι τρέπουσι καὶ καταβάλλουσι τοὺς πλείστους περὶ τοῖς ἐρύμασι φεύγοντας, ὁ δὲ Φωκίων τὴν μὲν φάλαγγα προσέταξεν ἐφεδρεύειν ἀναλαμβάνουσαν ἅμα καὶ προσδεχομένην τοὺς ἐν τῇ φυγῇ πρότερον διασπαρέντας, αὐτὸς δὲ τοὺς ἐπιλέκτους ἔχων ἐνέβαλε τοῖς πολεμίοις. καὶ μάχης καρτερᾶς γενομένης πάντες μὲν ἐκθύμως ἠγωνίσαντο καὶ ἀφειδῶς, Θάλλος δὲ ὁ Κινέου καὶ Γλαῦκος ὁ Πολυμήδους περὶ αὐτὸν τεταγμένοι τόν στρατηγὸν ἠρίστευσαν. οὐ μὴν ἀλλὰ καὶ Κλεοφάνης ἄξιον πλείστου παρέσχεν ἑαυτὸν ἐν ἐκείνῃ τῇ μάχῃ. τοὺς γὰρ ἱππεῖς ἀνακαλούμενος ἐκ τῆς τροπῆς καὶ βοῶν καὶ διακελευόμενος κινδυνεύοντι τῷ στρατηγῷ βοηθεῖν, ἐποίησεν ἀναστρέψαντας ἐπιρρῶσαι τὸ νίκημα τῶν ὁπλιτῶν.", "st": "Phoc. 13.1"}, {"sp": "N", "t": "ἐκ τούτου τόν τε Πλούταρχον ἐξέβαλεν ἐκ τῆς Ἐρετρίας, καὶ Ζάρητρα φρούριον ἑλὼν ἐπικαιρότατον, ᾗ μάλιστα συνελαύνεται τὸ πλάτος εἰς βραχὺ διάζωμα τῆς νήσου σφιγγομένης ἑκατέρωθεν ταῖς θαλάσσαις, ὅσους ἔλαβεν αἰχμαλώτους Ἕλληνας ἀφῆκε, φοβηθεὶς τοὺς ῥήτορας τῶν Ἀθηναίων, μὴ πρὸς ὀργήν τι βιάσωνται τόν δῆμον ἀγνωμονῆσαι περὶ αὐτούς·", "st": "Phoc. 13.4"}, {"sp": "N", "t": "ἐπεὶ δὲ ταῦτα διαπραξάμενος ἀπέπλευσεν ὁ Φωκίων, ταχὺ μὲν ἐπόθησαν οἱ σύμμαχοι τὴν χρηστότητα καὶ δικαιοσύνην αὐτοῦ, ταχὺ δὲ ἔγνωσαν οἱ Ἀθηναῖοι τὴν ἐμπειρίαν καὶ ῥώμην τοῦ ἀνδρός, ὁ γὰρ μετ’ ἐκεῖνον ἐλθὼν ἐπὶ τὰ πράγματα Μολοσσὸς οὕτως ἐπολέμησεν ὥστε καὶ ζῶν αὐτὸς ὑποχείριος γενέσθαι τοῖς πολεμίοις· ἐπεὶ δὲ μεγάλα ταῖς ἐλπίσι περινοῶν ὁ Φίλιππος εἰς Ἑλλήσποντον ἦλθε μετὰ πάσης τῆς δυνάμεως, ὡς Χερρόνησον ἐν ταὐτῷ καὶ Πέρινθον ἕξων καὶ Βυζάντιον, ὡρμημένων δὲ τῶν Ἀθηναίων βοηθεῖν οἱ ῥήτορες ἠγωνίσαντο τὸν Χάρητα στρατηγὸν ἀποσταλῆναι, καὶ πλεύσας ἐκεῖνος οὐδὲν ἄξιον τῆς δυνάμεως ἔπραττεν, οὐδὲ αἱ πόλεις ἐδέχοντο τὸν στόλον, ἀλλ’ ὕποπτος ὢν πᾶσιν ἐπλανᾶτο χρηματιζόμενος ἀπὸ τῶν συμμάχων καὶ καταφρονούμενος ὑπὸ τῶν πολεμίων, ὁ δὲ δῆμος ὑπὸ τῶν ῥητόρων παροξυνόμενος ἠγανάκτει καὶ μετενόει τοῖς Βυζαντίοις πέμψας τὴν βοήθειαν, ἀναστὰς ὁ Φωκίων εἶπεν ὅτι δεῖ μὴ τοῖς ἀπιστοῦσιν ὀργίζεσθαι τῶν συμμάχων, ἀλλὰ τοῖς ἀπιστουμένοις τῶν στρατηγῶν· οὗτοι γὰρ ὑμᾶς ποιοῦσι φοβεροὺς καὶ τοῖς χωρὶς ὑμῶν σώζεσθαι μὴ δυναμένοις.", "st": "Phoc. 14.1"}, {"sp": "N", "t": "κινηθεὶς οὖν ὁ δῆμος ὑπὸ τοῦ λόγου καὶ μεταπεσών ἐκέλευεν αὐτὸν ἐκεῖνον ἑτέραν προσλαβόντα δύναμιν βοηθεῖν τοῖς συμμάχοις εἰς τὸν Ἑλλήσποντον ὃ μεγίστην ῥοπὴν ἐποίησε πρὸς τὸ σωθῆναι τὸ Βυζάντιον. ἦν μὲν γὰρ ἤδη μεγάλη δόξα τοῦ Φωκίωνος· ἐπεὶ δὲ καὶ Λέων, ἀνὴρ Βυζαντίων πρῶτος ἀρετῇ καὶ τῷ Φωκίωνι γεγονὼς ἐν Ἀκαδημείᾳ συνήθης, ἀνεδέξατο τὴν πίστιν ὑπὲρ αὐτοῦ πρὸς τὴν πόλιν, οὐκ εἴασαν ἔξω στρατοπεδεῦσαι βουλόμενον, ἀλλ’ ἀνοίξαντες τὰς πύλας ἐδέξαντο καὶ κατέμιξαν ἑαυτοῖς τοὺς Ἀθηναίους, οὐ μόνον ἀνεγκλήτους ταῖς διαίταις καὶ σώφρονας, ἀλλὰ καὶ προθυμοτάτους ἐν τοῖς ἀγῶσι διὰ τὴν πίστιν γενομένους. οὕτω μὲν ὁ Φίλιππος ἐξέπεσε τοῦ Ἑλλησπόντου τότε καὶ κατεφρονήθη, δοκῶν ἄμαχός τις εἶναι καὶ ἀνανταγώνιστος, ὁ δὲ Φωκίων καὶ ναῦς τινας εἷλεν αὐτοῦ καὶ φρουρουμένας πόλεις ἀνέλαβε, καὶ πολλαχόθι τῆς χώρας ἀποβάσεις ποιούμενος ἐπόρθει καὶ κατέτρεχε, μέχρι οὗ τραύματα λαβὼν ὑπὸ τῶν προσβοηθούντων ἀπέπλευσε.", "st": "Phoc. 14.4"}, {"sp": "N", "t": "τῶν δὲ Μεγαρέων ἐπικαλουμένων κρύφα, φοβούμενος ὁ Φωκίων τοὺς Βοιωτοὺς μὴ προαισθόμενοι φθάσωσι τὴν βοήθειαν, ἐκκλησίαν συνήγαγεν ἕωθεν, καὶ προσαγγείλας τὰ παρὰ τῶν Μεγαρέων τοῖς Ἀθηναίοις, ὡς ἐπεψηφίσαντο, τῇ σάλπιγγι σημήνας εὐθὺς ἀπὸ τῆς ἐκκλησίας ἦγεν αὐτοὺς τὰ ὅπλα λαβόντας. δεξαμένων δὲ τῶν Μεγαρέων προθύμως τήν τε Νίσαιαν ἐτείχισε, καὶ διὰ μέσου σκέλη δύο πρὸς τὸ ἐπίνειον ἀπὸ τοῦ ἄστεος ἐνέβαλε, καὶ συνῆψε τῇ θαλάττῃ τήν πόλιν, ὥστε τῶν κατὰ γῆν πολεμίων ὀλίγον ἤδη φροντίζουσαν ἐξηρτῆσθαι τῶν Ἀθηναίων.", "st": "Phoc. 15.1"}, {"sp": "N", "t": "ἤδη δὲ πρὸς Φίλιππον ἐκπεπολεμωμένων παντάπασι, καί στρατηγῶν αὐτοῦ μὴ παρόντος ἑτέρων ἐπὶ τὸν πόλεμον ᾑρημένων, ὡς κατέπλευσεν ἀπὸ τῶν νήσων, πρῶτον μὲν ἔπειθε τὸν δῆμον εἰρηνικῶς ἔχοντος τοῦ Φιλίππου καί φοβουμένου τὸν κίνδυνον ἰσχυρῶς δέχεσθαι τὰς διαλύσεις· καί τινος ἀντικρούσαντος αὐτῷ τῶν εἰωθότων κυλινδεῖσθαι περὶ τὴν Ἡλιαίαν καί συκοφαντεῖν, καί εἰπόντος, σὺ δὲ τολμᾷς, ὦ Φωκίων, ἀποτρέπειν Ἀθηναίους ἤδη τὰ ὅπλα διὰ χειρῶν ἔχοντας; ἔγωγε, εἶπε, καί ταῦτα εἰδὼς ὅτι πολέμου μὲν ὄντος ἐγὼ σοῦ, εἰρήνης δὲ γενομένης σὺ ἐμοῦ ἄρξεις. ὡς δ’ οὐκ ἔπειθεν, ἀλλ’ ὁ Δημοσθένης ἐκράτει κελεύων ὡς πορρωτάτω τῆς Ἀττικῆς θέσθαι μάχην τοὺς Ἀθηναίους, ὦ τᾶν, ἔφη, μὴ ποῦ μαχώμεθα σκοπῶμεν, ἀλλὰ πῶς νικήσωμεν. οὕτω γὰρ ἔσται μακρὰν ὁ πόλεμος, ἡττωμένοις δὲ πᾶν ἀεὶ δεινὸν ἐγγὺς πάρεστι. γενομένης δὲ τῆς ἥττης καί τῶν θορυβοποιῶν καί νεωτεριστῶν ἐν ἄστει τὸν Χαρίδημον ἑλκόντων ἐπὶ τὸ βῆμα καί στρατηγεῖν ἀξιούντων, ἐφοβήθησαν οἱ βέλτιστοι· καί τὴν ἐξ Ἀρείου πάγου βουλὴν ἔχοντες ἐν τῷ δήμῳ δεόμενοι καί δακρύοντες μόλις ἔπεισαν ἐπιτρέψαι τῷ Φωκίωνι τὴν πόλιν.", "st": "Phoc. 16.1"}, {"sp": "N", "t": "ὁ δὲ τὴν μὲν ἄλλην τοῦ Φιλίππου πολιτείαν καί φιλανθρωπίαν ᾤετο δεῖν προσδέχεσθαι· Δημάδου δὲ γράψαντος ὅπως ἡ πόλις μετέχοι τῆς κοινῆς εἰρήνης καί τοῦ συνεδρίου τοῖς Ἕλλησιν, οὐκ εἴα πρὸ τοῦ γνῶναι τίνα Φίλιππος αὑτῷ γενέσθαι παρὰ τῶν Ἑλλήνων ἀξιώσει· κρατηθεὶς δὲ τῇ γνώμῃ διὰ τὸν καιρόν, ὡς εὐθὺς ἑώρα τοὺς Ἀθηναίους μεταμελομένους, ὅτι καί τριήρεις ἔδει παρέχειν τῷ Φιλίππῳ καί ἱππεῖς, ταῦτα, ἔφη, φοβούμενος ἠναντιούμην· ἐπεὶ δὲ συνέθεσθε, δεῖ μὴ βαρέως φέρειν μηδὲ ἀθυμεῖν, μεμνημένους ὅτι καί οἱ πρόγονοί ποτὲ μὲν ἄρχοντες, ποτὲ δὲ ἀρχόμενοι, καλῶς δὲ ἀμφότερα ταῦτα ποιοῦντες καὶ τὴν πόλιν ἔσωσαν καὶ τοὺς Ἕλληνας. Φιλίππου δὲ ἀποθανόντος εὐαγγέλια θύειν τὸν δῆμον οὐκ εἴα· καί γὰρ ἀγεννὲς εἶναι ἐπιχαίρειν, καί τὴν ἐν Χαιρωνείᾳ, παραταξαμένην πρὸς αὐτοὺς δύναμιν ἑνὶ σώματι μόνον ἐλάττω γενέσθαι.", "st": "Phoc. 16.4"}, {"sp": "N", "t": "Δημοσθένους δὲ λοιδοροῦντος τὸν Ἀλέξανδρον ἤδη προσάγοντα ταῖς Θήβαις ἔφη· σχέτλιε, τίπτ’ ἐθέλεις ἐρεθιζέμεν ἄγριον ἄνδρα καὶ δόξης μεγάλης ὀρεγόμενον; ἢ βούλει πυρκαϊᾶς τηλικαύτης οὔσης ἐγγὺς ῥιπίσαι τὴν πόλιν; ἀλλ’ ἡμεῖς οὐδὲ βουλομένοις ἀπολέσθαι τούτοις ἐπιτρέψομεν, οἱ διὰ τοῦτο στρατηγεῖν ὑπομένοντες. ὡς δὲ ἀπωλώλεισαν αἱ Θῆβαι καὶ ὁ Ἀλέξανδρος ἐξῃτεῖτο τοὺς περὶ Δημοσθένην καὶ Λυκοῦργον καὶ Ὑπερείδην καὶ Χαρίδημον, ἡ δὲ ἐκκλησία πρὸς ἐκεῖνον ἀπέβλεπεν, ὀνομαστὶ πολλάκις καλούμενος ἀνέστη καὶ τῶν φίλων ἕνα παραστησάμενος, ᾧ μάλιστα χρώμενος διετέλει καὶ πιστεύων καὶ ἀγαπῶν, εἰς τοιαῦτα, ἔφη, τὴν πόλιν οὗτοι παραγηόχασιν ὥστ’ ἔγωγε, κἂν Νικοκλέα τις τοῦτον ἐξαιτῇ, διδόναι κελεύσω. τὸ μὲν γὰρ αὐτὸς ὑπὲρ ὑμῶν ἁπάντων ἀποθανεῖν εὐτυχίαν ἂν ἐμαυτοῦ θείμην. ἐλεῶ δέ, εἶπεν, ἄνδρες Ἀθηναῖοι, καὶ τοὺς ἐκ Θηβῶν δεῦρο πεφευγότας, ἀρκεῖ δὲ τὰς Θήβας κλαίειν τοῖς Ἕλλησι. διὸ βέλτιόν ἐστιν ὑπὲρ ἀμφοῖν πείθειν καὶ παραιτεῖσθαι τοὺς κρατοῦντας ἢ μάχεσθαι.", "st": "Phoc. 17.1"}, {"sp": "N", "t": "τὸ μὲν οὖν πρῶτον ψήφισμα λέγεται τὸν Ἀλέξανδρον, ὡς ἔλαβε, ῥῖψαι καὶ φυγεῖν ἀποστραφέντα τοὺς πρέσβεις· τὸ δὲ δεύτερον ἐδέξατο, κομισθὲν ὑπὸ Φωκίωνος, τῶν πρεσβυτέρων ἀκούων ὅτι καὶ Φίλιππος ἐθαύμαζε τὸν ἄνδρα τοῦτον καὶ οὐ μόνον τὴν ἔντευξιν ὑπέμεινεν αὑτοῦ καὶ τὴν δέησιν, ἀλλὰ καὶ συμβουλεύοντος ἤκουσε. συνεβούλευε δ’ ὁ Φωκίων, εἰ μὲν ἡσυχίας ὀρέγεται, θέσθαι τὸν πόλεμον· εἰ δὲ δόξης, μεταθέσθαι, πρὸς τοὺς βαρβάρους ἀπὸ τῶν Ἑλλήνων τραπόμενον. καὶ πολλὰ καὶ πρὸς τὴν Ἀλεξάνδρου φύσιν καὶ βούλησιν εὐστόχως εἰπών οὕτω μετέβαλε καὶ κατεπράϋνεν αὐτόν ὥστε εἰπεῖν ὅπως προσέξουσι τὸν νοῦν Ἀθηναῖοι τοῖς πράγμασιν, ὡς, εἴ τι γένοιτο περὶ αὐτόν, ἐκείνοις ἄρχειν προσῆκον, ἰδίᾳ δὲ τὸν Φωκίωνα ποιησάμενος αὑτοῦ φίλον καὶ ξένον, εἰς τοσαύτην ἔθετο τιμὴν ὅσην εἶχον ὀλίγοι τῶν ἀεὶ συνόντων. ὁ γοῦν Δοῦρις εἴρηκεν ὡς μέγας γενόμενος καὶ Δαρείου κρατήσας ἀφεῖλε τῶν ἐπιστολῶν τὸ χαίρειν πλὴν ἐν ὅσαις ἔγραφε Φωκίωνι· τοῦτον δὲ μόνον, ὥσπερ Ἀντίπατρον, μετὰ τοῦ χαίρειν προσηγόρευε. τοῦτο δὲ καὶ Χάρης ἱστόρηκε.", "st": "Phoc. 17.4"}, {"sp": "N", "t": "τὸ μέντοι περὶ τῶν χρημάτων ὁμολογούμενόν ἐστιν ὅτι δωρεὰν αὐτῷ κατέπεμψεν ἑκατὸν τάλαντα, τούτων κομισθέντων εἰς Ἀθήνας, ἠρώτησεν ὁ Φωκίων τοὺς φέροντας τί δή ποτε πολλῶν ὄντων Ἀθηναίων αὐτῷ μόνῳ τοσαῦτα δίδωσιν Ἀλέξανδρος, εἰπόντων δὲ ἐκείνων, ὅτι σὲ κρίνει μόνον ἄνδρα καλὸν καὶ ἀγαθόν οὐκοῦν, εἶπεν ὁ Φωκίων, ἐασάτω με καὶ δοκεῖν ἀεὶ καὶ εἶναι τοιοῦτον. ὡς δὲ ἀκολουθήσαντες εἰς οἶκον αὐτῷ πολλὴν ἑώρων εὐτέλειαν, τὴν μὲν γυναῖκα μάττουσαν, ὁ δὲ Φωκίων αὐτὸς ἀνιμήσας ὕδωρ ἐκ τοῦ φρέατος ἀπενίπτετο τοὺς πόδας, ἔτι μᾶλλον ἐνέκειντο καὶ ἠγανάκτουν, δεινὸν εἶναι λέγοντες εἰ φίλος ὢν τοῦ βασιλέως οὕτω διαιτήσεται πονηρῶς. ἰδὼν οὖν ὁ Φωκίων πένητα πρεσβύτην ἐν τριβωνίῳ ῥυπαρῷ πορευόμενον, ἠρώτησεν εἰ τούτου χείρονα νομίζουσιν αὐτόν. εὐφημεῖν δὲ ἐκείνων δεομένων, καὶ μὴν οὗτος, εἶπεν, ἀπ’ ἐλαττόνων ἐμοῦ ζῇ καὶ ἀρκεῖται, τὸ δὲ ὅλον ἢ μὴ χρώμενος, ἔφη, μάτην ἕξω τοσοῦτον χρυσίον, ἢ χρώμενος ἐμαυτὸν ἅμα κἀκεῖνον διαβαλῶ πρὸς τὴν πόλιν. οὕτω μὲν ἐπανῆλθε πάλιν τὰ χρήματα ἐξ Ἀθηνῶν, ἐπιδείξαντα τοῖς Ἕλλησι πλουσιώτερον τοῦ διδόντος τοσαῦτα τὸν μὴ δεόμενον. ἐπεὶ δὲ Ἀλέξανδρος ἠγανάκτησε καὶ πάλιν ἔγραψε τῷ Φωκίωνι φίλους μὴ νομίζειν τοὺς μηδὲν αὐτοῦ δεομένους, χρήματα μὲν οὐδ’ ὣς Φωκίων ἔλαβεν, ἀφεθῆναι δὲ ἠξίωσε τὸν σοφιστὴν Ἐχεκρατίδην καὶ τὸν Ἴμβριον Ἀθηνόδωρον καὶ Ῥοδίους δύο, Δημάρατον καὶ Σπάρτωνα, συνειλημμένους ἐπ’ αἰτίαις τισὶ καὶ καθειργμένους ἐν Σάρδεσι. τούτους μὲν οὖν εὐθὺς ἀπέλυσεν ὁ Ἀλέξανδρος, Κρατερὸν δὲ ἀποστέλλων εἰς Μακεδονίαν ἐκέλευσε τεττάρων πόλεων ἐν Ἀσίᾳ, Κίου, Γεργίθου, Μυλάσων, Ἐλαίας, μίαν, ἣν ἂν αἱρῆται, παραδοῦναι τῷ Φωκίωνι, διατεινάμενος ἔτι μᾶλλον ὡς χαλεπανεῖ μὴ λαβόντος. ἀλλ’ οὔτε Φωκίων ἔλαβεν, ὅ τε Ἀλέξανδρος ταχέως ἀπέθανεν. ἡ δὲ οἰκία τοῦ Φωκίωνος ἔτι νῦν ἐν Μελίτῃ δείκνυται, χαλκαῖς λεπίσι κεκοσμημένη, τὰ δὲ ἄλλα λιτὴ καὶ ἀφελής.", "st": "Phoc. 18.1"}, {"sp": "N", "t": "τῶν δὲ γυναικῶν ἃς ἔγημε, περὶ τῆς προτέρας οὐθὲν ἱστορεῖται, πλὴν ὅτι Κηφισόδοτος ἦν ὁ πλάστης ἀδελφὸς αὐτῆς, τῆς δὲ δευτέρας οὐκ ἐλάττων ἐπὶ σωφροσύνῃ καί ἀφελείᾳ λόγος ἦν παρὰ τοῖς Ἀθηναίοις ἢ Φωκίωνος ἐπὶ χρηστότητι. καί ποτε θεωμένων καινοὺς τραγῳδοὺς Ἀθηναίων, ὁ μὲν τραγῳδὸς εἰσιέναι μέλλων βασιλίδος πρόσωπον ᾔτει κεκοσμημένας πολλὰς ὀπαδοὺς πολυτελῶς τὸν χορηγόν καί μὴ παρέχοντος ἠγανάκτει καί κατεῖχε τὸ θέατρον οὐ βουλόμενος προελθεῖν. ὁ δὲ χορηγὸς Μελάνθιος ὠθῶν αὐτὸν εἰς τὸ μέσον ἐβόα· τὴν Φωκίωνος οὐχ ὁρᾷς γυναῖκα προϊοῦσαν ἀεὶ μετὰ μιᾶς θεραπαινίδος, ἀλλ’ ἀλαζονεύῃ καί διαφθείρεις τὴν γυναικωνῖτιν; ἐξακούστου δὲ τῆς φωνῆς γενομένης ἐδέξατο κρότῳ πολλῷ καί θορύβῳ τὸ θέατρον. αὐτὴ δὲ ἡ γυνή, ξένης τινὸς Ἰωνικῆς ἐπιδειξαμένης χρυσοῦν καί λιθοκόλλητον κόσμον ἐν πλοκίοις καί περιδεραίοις, ἐμοὶ δέ, ἔφη, κόσμος ἐστὶ Φωκίων εἰκοστὸν ἔτος ἤδη στρατηγῶν Ἀθηναίων.", "st": "Phoc. 19.1"}, {"sp": "N", "t": "Φώκῳ δὲ τῷ υἱῷ βουλομένῳ ἀγωνίσασθαι Παναθηναίοις ἀποβάτην ἐφῆκεν, οὐχὶ τῆς νίκης ὀρεγόμενος, ἀλλ’ ὅπως ἐπιμεληθεὶς καὶ ἀσκήσας τὸ σῶμα βελτίων ἔσοιτο καὶ γὰρ ἦν ἄλλως φιλοπότης καὶ ἄτακτος ὁ νεανίσκος, νικήσαντος δὲ καὶ πολλῶν αἰτουμένων ἑστιᾶσαι τὰ νικητήρια, τοὺς ἄλλους Φωκίων παραιτησάμενος ἑνὶ τὴν φιλοτιμίαν ταύτην συνεχώρησεν. ὡς δὲ ἐλθὼν ἐπὶ τὸ δεῖπνον ἄλλην τε σοβαρὰν ἑώρα παρασκευὴν καὶ ποδανιπτῆρας οἴνου δι’ ἀρωμάτων προσφερομένους τοῖς εἰσιοῦσι, καλέσας τὸν υἱὸν, οὐ παύσεις ἔφη, τὸν ἑταῖρον, ὦ Φῶκε, διαφθείροντά σου τὴν νίκην; βουλόμενος δὲ καὶ καθόλου μεταστῆσαι τὸ μειράκιον ἐκ τῆς διαίτης ἐκείνης, ἀπήγαγεν εἰς Λακεδαίμονα καὶ κατέμιξε τοῖς ἀγομένοις τὴν λεγομένην ἀγωγὴν νεανίσκοις. καὶ τοῦτο τοὺς Ἀθηναίους ἐλύπησεν, ὡς ὑπερορῶντος καὶ ὑπερφρονοῦντος τὰ οἰκεῖα τοῦ Φωκίωνος· εἰπόντος δὲ τοῦ Δημάδου πρὸς αὐτόν, τί οὐ πείθομεν, ὦ Φωκίων, Ἀθηναίους τὴν Λακωνικὴν προσδέξασθαι πολιτείαν; ἐὰν γὰρ σὺ κελεύῃς, ἐγὼ γράφειν καὶ λέγειν ἕτοιμός εἰμι, πάνυ γοῦν, ἔφη, πρέψειεν ἄν σοι μύρου τοσοῦτον ὄζοντι καὶ χλανίδα τοιαύτην φοροῦντι συμβουλεύειν Ἀθηναίοις περὶ φιλιτίων καὶ τὸν Λυκοῦργον ἐπαινεῖν.", "st": "Phoc. 20.1"}, {"sp": "N", "t": "γράψαντος δὲ τοῦ Ἀλεξάνδρου περὶ τριήρων, ὅπως ἀποστείλωσιν αὐτῷ, καὶ τῶν ῥητόρων ἐνισταμένων, τῆς δὲ βουλῆς τὸν Φωκίωνα λέγειν κελευούσης, λέγω τοίνυν ὑμῖν, εἶπεν, ἢ τοῖς ὅπλοις κρατεῖν ἢ τοῖς κρατοῦσι φίλους εἶναι. Πρὸς δὲ Πυθέαν ἀρχόμενον τότε πρῶτον ἐντυγχάνειν Ἀθηναίοις, ἤδη δὲ λάλον ὄντα καὶ θρασύν, οὐ σιωπήσεις, ἔφη, καὶ ταῦτα νεώνητος ὢν τῷ δήμῳ; ἐπεὶ δὲ Ἅρπαλος μετὰ χρημάτων πολλῶν ἀποδρὰς Ἀλέξανδρον ἐκ τῆς Ἀσίας τῇ Ἀττικῇ προσέβαλε, καὶ τῶν εἰωθότων ἀπὸ τοῦ βήματος χρηματίζεσθαι δρόμος ἦν καὶ ἅμιλλα φθειρομένων πρὸς αὐτόν, τούτοις μὲν ἀπὸ πολλῶν μικρὰ δελεάζων προήκατο καὶ διέρριψε, τῷ δὲ Φωκίωνι προσέπεμψε διδοὺς ἑπτακόσια τάλαντα, καὶ τἆλλα πάντα, καὶ μετὰ πάντων ἑαυτὸν ἐκείνῳ μόνῳ παρακατατιθέμενος. ἀποκριναμένου δὲ τραχέως τοῦ Φωκίωνος οἰμώξεσθαι τὸν Ἅρπαλον, εἰ μὴ παύσεται διαφθείρων τὴν πόλιν, τότε μὲν συσταλεὶς ἀπέστη, μετ’ ὀλίγον δὲ βουλευομένων Ἀθηναίων ἑώρα τοὺς μὲν εἰληφότας τὰ χρήματα παρ’ αὐτοῦ μεταβαλλομένους καὶ κατηγοροῦντας, ἵνα μὴ φανεροὶ γένωνται, Φωκίωνα δὲ τὸν μηδὲν λαβόντα μετὰ τοῦ κοινοῦ συμφέροντος ἅμα καὶ τὴν ἐκείνου σωτηρίαν ἔν τινι λόγῳ τιθέμενον. πάλιν οὖν ἐνεχθεὶς ἐπὶ τὸ θεραπεύειν ἐκεῖνον, αὐτὸν μὲν ὡς ἔρυμα πανταχόθεν ἀνάλωτον ὑπὸ τοῦ χρυσίου περιοδεύων ἑώρα, Χαρικλέα δὲ τὸν γαμβρὸν αὐτοῦ ποιησάμενος συνήθη καὶ φίλον, ἀνέπλησε δόξης πονηρᾶς, πάντα πιστεύων καὶ πάντα χρώμενος ἐκείνῳ.", "st": "Phoc. 21.1"}, {"sp": "N", "t": "καὶ δὴ καὶ Πυθονίκης τῆς ἑταίρας ἀποθανούσης, ἣν εἶχεν ὁ Ἅρπαλος ἐρῶν καὶ θυγατρίου πατὴρ ἐξ αὐτῆς γεγόνει, μνημεῖον ἀπὸ χρημάτων πολλῶν ἐπιτελέσαι θελήσας προσέταξε τῷ Χαρικλεῖ τὴν ἐπιμέλειαν. οὖσαν δὲ τὴν ὑπουργίαν ταύτην ἀγεννῆ προσκατῄσχυνεν ὁ τάφος συντελεσθείς. διαμένει γὰρ ἔτι νῦν ἐν Ἕρμει, ᾗ βαδίζομεν ἐξ ἄστεος εἰς Ἐλευσῖνα, μηδὲν ἔχων τῶν τριάκοντα ταλάντων ἄξιον, ὅσα τῷ Ἁρπάλῳ λογισθῆναί φασιν εἰς τὸ ἔργον ὑπὸ τοῦ Χαρικλέους. καὶ μέντοι καὶ τελευτήσαντος αὐτοῦ τὸ παιδάριον ὑπὸ τοῦ Χαρικλέους καὶ τοῦ Φωκίωνος ἀναληφθὲν ἐτύγχανε πάσης ἐπιμελείας. κρινομένου μέντοι τοῦ Χαρικλέους ἐπὶ τοῖς Ἁρπαλείοις, καὶ δεομένου βοηθεῖν αὐτῷ τὸν Φωκίωνα καὶ συνεισελθεῖν εἰς τὸ δικαστήριον, οὐκ ἠθέλησεν, εἰπών· ἐγώ σε, ὦ Χαρίκλεις, ἐπὶ πᾶσι τοῖς δικαίοις γαμβρὸν ἐποιησάμην.", "st": "Phoc. 22.1"}, {"sp": "N", "t": "πρώτου δὲ Ἀθηναίοις Ἀσκληπιάδου τοῦ Ἱππάρχου τεθνάναι προσαγγείλαντος Ἀλέξανδρον, ὁ μὲν Δημάδης ἐκέλευε μὴ προσέχειν· πάλαι γὰρ ἂν ὅλην ὄζειν νεκροῦ τὴν οἰκουμένην· ὁ δὲ Φωκίων ἐπηρμένον ὁρῶν πρὸς τὸ νεωτερίζειν τὸν δῆμον ἐπειρᾶτο παρηγορεῖν καὶ κατέχειν. ἀναπηδώντων δὲ πολλῶν ἐπὶ τὸ βῆμα, καὶ βοώντων ἀληθῆ τὸν Ἀσκληπιάδην ἀπαγγέλλειν καὶ τεθνάναι τὸν Ἀλέξανδρον, οὐκοῦν, εἶπεν, εἰ σήμερον τέθνηκε, καὶ αὔριον ἔσται καὶ εἰς τρίτην τεθνηκώς, ὥστε ἡμᾶς ἐν ἡσυχίᾳ βουλεύσασθαι, μᾶλλον δὲ μετὰ ἀσφαλείας.", "st": "Phoc. 22.4"}, {"sp": "N", "t": "ὡς δὲ φέρων ἐνέσεισεν ὁ Λεωσθένης τὴν πόλιν εἰς τὸν Λαμιακὸν πόλεμον, καί τοῦ Φωκίωνος δυσχεραίνοντος ἠρώτα καταγελῶν τί πεποίηκεν ἀγαθὸν τὴν πόλιν ἔτη τοσαῦτα στρατηγῶν, οὐ μικρόν, ἔφη, τὸ τοὺς πολίτας ἐν τοῖς ἰδίοις μνήμασι θάπτεσθαι. πολλὰ δὲ θρασυνομένου καὶ κομπάζοντος ἐν τῷ δήμῳ τοῦ Λεωσθένους, ὁ Φωκίων, οἱ λόγοι σου, εἶπεν, ὦ μειράκιον, ἐοίκασι κυπαρίττοις· μεγάλοι γὰρ ὄντες καί ὑψηλοί καρποὺς οὐ φέρουσιν. ὡς δὲ ἐπαναστὰς ὁ Ὑπερείδης ἠρώτησε, πότε οὖν, ὦ Φωκίων, συμβουλεύσεις πολεμεῖν Ἀθηναίοις; ὅταν, εἶπε, τοὺς μὲν νέους ἴδω τὴν τάξιν βουλομένους φυλάττειν, τοὺς δὲ πλουσίους εἰσφέρειν, τοὺς δὲ ῥήτορας ἀπέχεσθαι τοῦ κλέπτειν τὰ δημόσια.", "st": "Phoc. 23.1"}, {"sp": "N", "t": "θαυμαζόντων δὲ πολλῶν τὴν ὑπὸ τοῦ Λεωσθένους συνηγμένην δύναμιν, καί τοῦ Φωκίωνος πυνθανομένων πῶς τι παρεσκευάσθαι δοκοῦσιν αὐτῷ, καλῶς, ἔφη, πρὸς τὸ στάδιον τὸν δὲ δόλιχον τοῦ πολέμου φοβοῦμαι, μήτε χρήματα τῆς πόλεως ἕτερα μήτε ναῦς μήτε ὁπλίτας ἐχούσης. ἐμαρτύρει δὲ αὐτῷ καί τὰ ἔργα. πρῶτον μὲν γὰρ ὁ Λεωσθένης λαμπρὸς ἤρθη ταῖς πράξεσι, τῶν τε Βοιωτῶν μάχῃ κρατήσας καί τὸν Ἀντίπατρον εἰς Λάμιαν συνελάσας· ὅτε καί φασι τὴν μὲν πόλιν ἐλπίδος μεγάλης γενομένην ἑορτάζειν εὐαγγέλια συνεχῶς καί θύειν τοῖς θεοῖς, τὸν δὲ Φωκίωνα πρὸς τοὺς ἐλέγχειν αὐτὸν οἰομένους, καὶ πυνθανομένους εἰ ταῦτα οὐκ ἂν ἤθελεν αὑτῷ πεπρᾶχθαι, πάνυ μὲν οὖν, ἔφη, βεβουλεῦσθαι δὲ ἐκεῖνα. καί πάλιν ἄλλων ἐπ’ ἄλλοις εὐαγγελίων γραφομένων καί φερομένων ἀπὸ στρατοπέδου, Πότα ἄρα, φάναι, παυσόμεθα νικῶντες;", "st": "Phoc. 23.3"}, {"sp": "N", "t": "ἐπεὶ δὲ τοῦ Λεωσθένους ἀποθανόντος οἱ φοβούμενοι τὸν Φωκίωνα, μὴ στρατηγὸς ἐκπεμφθεὶς καταλύσῃ τὸν πόλεμον, ἄνθρωπόν τινα τῶν οὐκ ἐπιφανῶν ἐν ἐκκλησίᾳ παρεσκεύασαν ἀναστάντα λέγειν ὅτι φίλος ὢν τοῦ Φωκίωνος καὶ συμπεφοιτηκὼς παραινεῖ φείδεσθαι τοῦ ἀνδρὸς καὶ φυλάσσειν, ὡς ἄλλον ὅμοιον οὐκ ἔχοντας, ἐκπέμπειν δὲ Ἀντίφιλον ἐπὶ τὸ στράτευμα, καὶ ταῦτα τοῖς Ἀθηναίοις συνεδόκει, παρελθὼν ὁ Φωκίων ἔλεγε μήτε συμπεφοιτηκέναι ποτὲ τῷ ἀνθρώπῳ μήτε ἄλλως γεγονέναι γνώριμος ἢ συνήθης· ἀλλὰ νῦν, εἶπεν, ἀπὸ τῆς σήμερον ἡμέρας καὶ φίλον σε ποιοῦμαι καὶ οἰκεῖον ἃ γὰρ ἦν ἐμοὶ συμφέροντα συμβεβούλευκας.", "st": "Phoc. 24.1"}, {"sp": "N", "t": "ὡρμημένων δὲ τῶν Ἀθηναίων ἐπὶ τοὺς Βοιωτοὺς στρατεύειν πρῶτον μὲν ἀντεῖχε· καὶ τῶν φίλων λεγόντων ὡς ἀποθανεῖται προσκρούων τοῖς Ἀθηναίοις, ἀδίκως, εἶπεν, ἂν ποιῶ τὸ συμφέρον ἂν δὲ παραβαίνω, δικαίως. ἐπεὶ δὲ ὁρῶν οὐκ ἀνιέντας, ἀλλὰ βοῶντας, ἐκέλευσε τὸν κήρυκα ἀνειπεῖν Ἀθηναίων τοὺς ἄχρι ἑξήκοντα ἐτῶν ἀφ’ ἥβης πέντε ἡμερῶν σιτία λαβόντας εὐθὺς ἀκολουθεῖν ἀπὸ τῆς ἐκκλησίας, θορύβου πολλοῦ γενομένου καὶ τῶν πρεσβυτέρων βοώντων καὶ ἀναπηδώντων, οὐδέν, ἔφη, δεινόν ἐγὼ γὰρ ὁ στρατηγὸς ὀγδοηκοστὸν ἔχων ἔτος ἔσομαι μεθ’ ὑμῶν. καὶ τότε μὲν οὕτως κατέπαυσεν αὐτοὺς καὶ μετέβαλε·", "st": "Phoc. 24.3"}, {"sp": "N", "t": "πορθουμένης δὲ τῆς παραλίας ὑπὸ Μικίωνος συχνοῖς Μακεδόσι καὶ μισθοφόροις ἀποβεβηκότος εἷς Ῥαμνοῦντα καὶ κατατρέχοντος τὴν χώραν, ἐξήγαγε τοὺς Ἀθηναίους ἐπ’ αὐτόν, ὡς δὲ προστρέχοντες ἀλλαχόθεν ἄλλος διεστρατήγουν καὶ συνεβούλευον αὐτοῦ τὸν λόφον καταλαβεῖν, ἐκεῖ περιπέμψαι τοὺς ἱππέας, ἐνταῦθα παρεμβαλεῖν, Ὦ Ἡράκλεις, εἶπεν, ὡς πολλοὺς ὁρῶ στρατηγούς, ὀλίγους δὲ στρατιώτας. ἐπεὶ δὲ παρατάξαντος αὐτοῦ τοὺς ὁπλίτας εἷς πολὺ πρὸ τῶν ἄλλων προῆλθεν, εἶτα δείσας ἀντιστάντος ἀνδρὸς πολεμίου πάλιν εἷς τὴν τάξιν ἀνεχώρησεν, ὦ μειράκιον, εἶπεν, οὐκ αἰδῇ δύο τάξεις ἀπολελοιπώς, ἣν ἐτάχθης ὑπὸ τοῦ στρατηγοῦ καὶ πάλιν ἐφ’ ἣν σεαυτὸν ἔταξας; ἐμβαλὼν δὲ τοῖς πολεμίοις καὶ κατὰ κράτος τρεψάμενος, αὐτόν τε τὸν Μικίωνα καὶ πολλοὺς ἄλλους ἀπέκτεινε. τὸ δὲ Ἑλληνικὸν ἐν Θετταλίᾳ στράτευμα, συμμίξαντος Ἀντιπάτρῳ Λεοννάτου καὶ τῶν ἐξ Ἀσίας Μακεδόνων, ἐνίκα μαχόμενον καὶ Λεοννάτος ἔπεσεν, ἡγουμένου τῆς μὲν φάλαγγος Ἀντιφίλου, τῶν δὲ ἱππέων τοῦ Θεσσαλοῦ Μένωνος.", "st": "Phoc. 25.1"}, {"sp": "N", "t": "ὀλίγῳ δὲ ὕστερον χρόνῳ Κρατεροῦ διαβάντος ἐξ Ἀσίας μετὰ πολλῆς δυνάμεως καὶ γενομένης πάλιν ἐν Κραννῶνι παρατάξεως, ἡττήθησαν μὲν οἱ Ἕλληνες οὔτε μεγάλην ἧτταν οὔτε πολλῶν πεσόντων, ἀπειθείᾳ δὲ πρὸς τοὺς ἄρχοντας ἐπιεικεῖς καὶ νέους ὄντας, καὶ ἅμα τὰς πόλεις αὐτῶν πειρῶντος Ἀντιπάτρου, διαρρυέντες αἴσχιστα προήκαντο τὴν ἐλευθερίαν. εὐθὺς οὖν ἐπὶ τὰς Ἀθήνας ἄγοντος τοῦ Ἀντιπάτρου τὴν δύναμιν οἱ μὲν περὶ Δημοσθένην καὶ Ὑπερείδην ἀπηλλάγησαν ἐκ τῆς πόλεως, Δημάδης δέ, μηθὲν μέρος ὧν ὤφειλε χρημάτων ἐπὶ ταῖς καταδίκαις ἐκτῖσαι τῇ πόλει· δυνάμενος ἡλώκει γὰρ ἑπτὰ γραφὰς παρανόμων καὶ γεγονὼς ἄτιμος ἐξείργετο τοῦ λέγειν, ἄδειαν εὑρόμενος τότε, γράφει ψήφισμα ἐκπέμπειν πρὸς Ἀντίπατρον ὑπὲρ εἰρήνης πρέσβεις αὐτοκράτορας. φοβουμένου δὲ τοῦ δήμου καὶ καλοῦντος Φωκίωνα, καὶ μόνῳ πιστεύειν ἐκείνῳ λέγοντος, ἀλλ’ εἴγε ἐπιστευόμην, εἶπεν, ἐγὼ συμβουλεύων ὑμῖν, οὐκ ἂν νῦν ἐβουλευόμεθα περὶ πραγμάτων τοιούτων. οὕτω δὲ τοῦ ψηφίσματος ἐπικυρωθέντος ἀπεστάλη πρὸς Ἀντίπατρον ἐν τῇ Καδμείᾳ στρατοπεδεύοντα καὶ παρασκευαζόμενον εὐθὺς εἰς τὴν Ἀττικὴν βαδίζειν. καὶ τοῦτο πρῶτον ᾔτει, τὸ μένοντα κατὰ χώραν ποιήσασθαι τὰς διαλύσεις. τοῦ δὲ Κρατεροῦ λέγοντος ὡς οὐ δίκαια πείθει Φωκίων ἡμᾶς, τὴν τῶν συμμάχων καὶ φίλων καθημένους χώραν κακῶς ποιεῖν δυναμένους ἐκ τῆς τῶν πολεμίων ὠφελεῖσθαι, λαβόμενος αὐτοῦ τῆς δεξιᾶς Ἀντίπατρος, δοτέον, εἶπε, Φωκίωνι ταύτην τὴν χάριν. περὶ δὲ τῶν ἄλλων ἐκέλευεν αὐτοῖς ἐπιτρέπειν τοὺς Ἀθηναίους, ὥσπερ ἐν Λαμίᾳ Λεωσθένης ἐκεῖνον.", "st": "Phoc. 26.1"}, {"sp": "N", "t": "Ὡς οὖν ἐπανῆλθεν ὁ Φωκίων εἰς τὸ ἄστυ καὶ τοῖς Ἀθηναίοις; ταῦτα ἔδοξεν ὑπ’ ἀνάγκης, αὖθις εἰς Θήβας ἐβάδιζε μετὰ Τῶν ἄλλων πρέσβεων, Ξενοκράτην τὸν φιλόσοφον Τῶν Ἀθηναίων προσελομένων. τοσοῦτον γὰρ ἦν ἀξίωμα τῆς ἀρετῆς τοῦ Ξενοκράτους καὶ δόξα καὶ λόγος παρὰ πᾶσιν ὥστε οἴεσθαι μήτε ὕβριν εἶναι μήτε ὠμότητα μήτε θυμὸν ἐν ἀνθρωπίνῃ ψυχῇ φυόμενον, ᾧ Ξενοκράτους μόνον ὀφθέντος οὐκ ἂν αἰδοῦς τι καὶ τιμῆς ἐγγένοιτο πρὸς αὐτόν. ἀπέβη δὲ τοὐναντίον ἀγνωμοσύνῃ τινὶ καὶ μισαγαθίᾳ τοῦ Ἀντιπάτρου, πρῶτον μὲν γὰρ οὐκ ἠσπάσατο τὸν Ξενοκράτην τοὺς ἄλλους δεξιωσάμενος· ἐφ’ ᾧ φασιν εἰπεῖν ἐκεῖνον ὡς Ἀντίπατρος καλῶς ποιεῖ μόνον αὐτὸν αἰσχυνόμενος ἐφ’ οἷς ἀγνωμονεῖν μέλλει πρὸς τὴν πόλιν ἔπειτα λέγειν ἀρξάμενον οὐχ ὑπομένων, ἀλλ’ ἀντικρούων καὶ δυσκολαίνων ἐποίησεν ἀποσιωπῆσαι. τῶν δὲ περὶ τὸν Φωκίωνα διαλεχθέντων ἀπεκρίνατο φιλίαν ἔσεσθαι τοῖς Ἀθηναίοις καὶ συμμαχίαν ἐκδοῦσι μὲν τοὺς περὶ Δημοσθένην καὶ Ὑπερείδην, πολιτευομένοις δὲ τὴν πάτριον ἀπὸ τιμήματος πολιτείαν, δεξαμένοις δὲ φρουρὰν εἰς τὴν Μουνυχίαν, ἔτι δὲ χρήματα τοῦ πολέμου καὶ ζημίαν προσεκτίσασιν.", "st": "Phoc. 27.1"}, {"sp": "N", "t": "οἱ μὲν οὖν ἄλλοι πρέσβεις ἠγάπησαν ὡς φιλανθρώπους τὰς διαλύσεις, πλὴν τοῦ Ξενοκράτους· ἔφη γὰρ ὡς μὲν δούλοις μετρίως κεχρῆσθαι τὸν Ἀντίπατρον, ὡς δὲ ἐλευθέροις βαρέως, τοῦ δὲ Φωκίωνος παραιτουμένου τὴν φρουρὰν καὶ δεομένου λέγεται τὸν Ἀντίπατρον εἰπεῖν ὦ Φωκίων, ἡμεῖς πάντα σοι χαρίζεσθαι βουλόμεθα πλὴν Τῶν καὶ σὲ ἀπολούντων καὶ ἡμᾶς. οἱ δὲ οὐχ οὕτως φασίν, ἀλλὰ ἐρωτῆσαι τὸν Ἀντίπατρον εἰ τὴν φρουρὰν ἀνέντος αὐτοῦ τοῖς Ἀθηναίοις Φωκίων ἐγγυᾶται τὴν πόλιν ἐμμενεῖν τῇ εἰρήνῃ καὶ μηθὲν πολυπραγμονήσειν· σιωπῶντος δὲ ἐκείνου καὶ διαμέλλοντος, ἀναπηδήσαντα Καλλιμέδοντα τὸν Κάραβον, ἄνδρα θρασὺν καὶ μισόδημον, εἰπεῖν· ἐὰν δὲ οὗτος, ὦ Ἀντίπατρε, φλυαρῇ, σὺ πιστεύσεις καὶ οὐ πράξεις ἃ διέγνωκας;", "st": "Phoc. 27.4"}, {"sp": "N", "t": "οὕτω μὲν ἐδέξαντο φρουρὰν Μακεδόνων Ἀθηναῖοι καὶ Μένυλλον ἡγεμόνα, τῶν ἐπιεικῶν τινα καὶ τοῦ Φωκίωνος ἐπιτηδείων, ἐφάνη δὲ ὑπερήφανον τὸ πρόσταγμα, καὶ μᾶλλον ἐξουσίας ὕβρει χρωμένης ἐπίδειξις ἢ πραγμάτων ἕνεκα γιγνομένη κατάληψις. οὐ μικρὸν δὲ τῷ πάθει προσέθηκεν ὁ καιρός, εἰκάδι γὰρ ἡ φρουρὰ Βοηδρομιῶνος εἰσήχθη, μυστηρίων ὄντων, ᾗ τὸν Ἴακχον ἐξ ἄστεος Ἐλευσινάδε πέμπουσιν, ὥστε τῆς τελετῆς συγχυθείσης ἀναλογίζεσθαι τοὺς πολλοὺς καὶ τὰ πρεσβύτερα τῶν θείων καὶ τὰ πρόσφατα. πάλαι μὲν γὰρ ἐν τοῖς ἀρίστοις εὐτυχήμασι τὰς μυστικὰς ὄψεις καὶ φωνὰς παραγενέσθαι σὺν ἐκπλήξει καὶ θάμβει τῶν πολεμίων, νῦν δὲ τοῖς αὐτοῖς ἱεροῖς τὰ δυσχερέστατα πάθη τῆς Ἑλλάδος ἐπισκοπεῖν τοὺς θεούς, καὶ καθυβρίζεσθαι τὸν ἁγιώτατον τοῦ χρόνου καὶ ἥδιστον αὐτοῖς, ἐπώνυμον τῶν μεγίστων κακῶν γενόμενον. πρότερον μὲν οὖν ὀλίγοις ἔτεσι χρησμὸν ἐξήνεγκαν αἱ Δωδωνίδες τῇ πόλει τὰ ἀκρωτήρια τῆς Ἀρτέμιδος φυλάσσειν, ὅπως ἄλλοι μὴ λάβωσι· τότε δὲ περὶ τὰς ἡμέρας ἐκείνας αἱ ταινίαι μὲν, αἷς περιελίττουσι τὰς μυστικὰς κοίτας, βαπτόμεναι θάψινον ἀντὶ φοινικοῦ χρῶμα καὶ νεκρῶδες ἀνήνεγκαν ὃ δὲ μεῖζον ἦν, τὰ παραβαπτόμενα τῶν ἰδιωτικῶν πάντα τὸ προσῆκον ἄνθος ἔσχε. μύστην δὲ λούοντα χοιρίδιον ἐν Κανθάρῳ λιμένι κῆτος συνέλαβε καὶ τὰ κάτω μέρη τοῦ σώματος ἄχρι τῆς κοιλίας κατέπιε, προδεικνύντος αὐτοῖς τοῦ θεοῦ προφανῶς ὅτι τῶν κάτω καὶ πρὸς θαλάσσῃ στερηθέντες τὴν ἄνω πόλιν διαφυλάξουσιν.", "st": "Phoc. 28.1"}, {"sp": "N", "t": "ἡ μὲν οὖν φρουρὰ διὰ Μένυλλον οὐδὲν ἠνίασε τοὺς ἀνθρώπους· τῶν δὲ ἀποψηφισθέντων τοῦ πολιτεύματος διὰ πενίαν ὑπὲρ μυρίους καὶ δισχιλίους γενομένων οἵ τε μένοντες ἐδόκουν σχέτλια καὶ ἄτιμα πάσχειν, οἵ τε διὰ τοῦτο τὴν πόλιν ἐκλιπόντες καὶ μεταστάντες εἰς Θρᾴκην, Ἀντιπάτρου γῆν καὶ πόλιν αὐτοῖς παρασχόντος, ἐκπεπολιορκημένοις ἐῴκεσαν.", "st": "Phoc. 28.4"}, {"sp": "N", "t": "ὁ δὲ Δημοσθένους ἐν Καλαυρίᾳ καὶ Ὑπερείδου πρὸς Κλεωναῖς θάνατος, περὶ ὧν ἐν ἄλλοις γέγραπται, μονονοὺκ ἔρωτα καὶ πόθον Ἀθηναίοις Ἀλεξάνδρου καὶ Φιλίππου παρίστη. καὶ τοῦτο ὅπερ ὕστερον, ἀναιρεθέντος Ἀντιγόνου καὶ τῶν ἀνελόντων ἐκεῖνον ἀρξαμένων βιάζεσθαι καὶ λυπεῖν τοὺς ἀνθρώπους, ἀνὴρ ἄγροικος ἐν Φρυγίᾳ χωρίον ὀρύττων πυθομένου τινός, τί ποιεῖς; στενάξας, Ἀντίγονον, εἶπε, ζητῶ· τοῦτο πολλοῖς ἐπῄει λέγειν διαμνημονεύουσι τὸν ἐκείνων τῶν βασιλέων θυμόν, ὡς τὸ μέγα καὶ γενναῖον εὐπαραίτητον εἶχον, οὐχ ὥσπερ Ἀντίπατρος ἰδιώτου προσώπῳ καὶ φαυλότητι χλαμυδίου καὶ διαίτης εὐτελείᾳ κατειρωνευόμενος τὴν ἐξουσίαν ἐπαχθέστερος ἦν τοῖς πάσχουσι κακῶς δεσπότης καὶ τύραννος. ὅμως δ’ οὖν ὁ Φωκίων καὶ φυγῆς ἀπήλλαξε πολλούς δεηθεὶς τοῦ Ἀντιπάτρου, καὶ φεύγουσι διεπράξατο μὴ καθάπερ οἱ λοιποὶ τῶν μεθισταμένων ὑπὲρ τὰ Κεραύνια ὄρη καὶ τὸν Ταίναρον ἐκπεσεῖν τῆς Ἑλλάδος, ἀλλὰ ἐν Πελοποννήσῳ κατοικεῖν, ὧν καὶ Ἁγνωνίδης ἦν ὁ συκοφάντης. ἐπιμελόμενος δὲ τῶν κατὰ τὴν πόλιν πρᾴως καὶ νομίμως τοὺς μὲν ἀστείους καὶ χαρίεντας ἐν ταῖς ἀρχαῖς ἀεὶ συνεῖχε, τοὺς δὲ πολυπράγμονας καὶ νεωτεριστάς, αὐτῷ τῷ μὴ ἄρχειν μηδὲ θορυβεῖν ἀπομαραινομένους, ἐδίδαξε φιλοχωρεῖν καὶ ἀγαπᾶν γεωργοῦντας. ὁρῶν δὲ τὸν Ξενοκράτην τελοῦντα τὸ μετοίκιον ἐβούλετο γράψαι πολίτην ὁ δὲ ἀπεῖπε, φήσας οὐκ ἂν μετασχεῖν ταύτης τῆς πολιτείας περὶ ἧς ἐπρέσβευεν ἵνα μὴ γένηται.", "st": "Phoc. 29.1"}, {"sp": "N", "t": "τοῦ δὲ Μενύλλου δωρεὰν αὐτῷ καὶ χρήματα διδόντος, ἀπεκρίνατο μήτ’ ἐκεῖνον Ἀλεξάνδρου βελτίονα εἶναι μήτε κρείττονα τὴν αἰτίαν ἐφ’ ᾗ λήψεται νῦν ὁ τότε μὴ δεξάμενος. ἀλλὰ Φώκῳ γε τῷ παιδὶ λαβεῖν δεομένου τοῦ Μενύλλου, Φώκῳ μὲν, εἶπεν, ἐὰν μὲν σωφρονῇ μεταβαλόμενος, ἀρκέσει τὰ τοῦ πατρός· ὡς δ’ ἔχει νῦν, οὐδὲν ἱκανόν ἐστιν. Ἀντιπάτρῳ δὲ τραχύτερον ἀπεκρίνατο βουλομένῳ τι γενέσθαι δι’ αὐτοῦ τῶν μὴ πρεπόντων οὐ δύναται γὰρ, εἶπεν, Ἀντίπατρος ἅμα μοι καὶ φίλῳ καὶ κόλακι χρῆσθαι. τὸν δὲ Ἀντίπατρον αὐτὸν εἰπεῖν λέγουσιν ὡς δυεῖν αὐτῷ φίλων Ἀθήνησιν ὄντων, Φωκίωνος καὶ Δημάδου, τὸν μὲν λαβεῖν οὐ πέπεικε, τὸν δὲ διδοὺς οὐκ ἐμπέπληκε. καὶ μέντοι Φωκίων μὲν ὡς ἀρετὴν ἐπεδείκνυτο τὴν πενίαν, ἐν ᾗ τοσαυτάκις Ἀθηναίων στρατηγήσας καὶ βασιλεῦσι φίλοις χρησάμενος ἐγκατεγήρασε, Δημάδης δὲ τῷ πλούτῳ καὶ παρανομῶν ἐκαλλωπίζετο. νόμου γὰρ ὄντος Ἀθήνησι τότε μὴ χορεύειν ξένον ἢ χιλίας ἀποτίνειν τὸν χορηγόν, ἅπαντας εἰσαγαγὼν ξένους τοὺς χορεύοντας ἑκατὸν ὄντας ἅμα καὶ τὴν ζημίαν ἀνὰ χιλίας ὑπὲρ ἑκάστου εἰσήνεγκεν εἰς τὸ θέατρον. Δημέᾳ δὲ τῷ υἱῷ νύμφην ἀγόμενος, ἐμοῦ μὲν, εἶπεν, ὦ παῖ, τὴν σὴν μητέρα γαμοῦντος οὐδὲ ὁ γείτων ᾔσθετο τοῖς δὲ σοῖς γάμοις καὶ βασιλεῖς καὶ δυνάσται συγχορηγοῦσιν.", "st": "Phoc. 30.1"}, {"sp": "N", "t": "ἐνοχλούντων δὲ τῷ Φωκίωνι τῶν Ἀθηναίων ὅπως ἀπαλλάξῃ τὴν φρουρὰν πείσας τὸν Ἀντίπατρον, εἴτε μὴ προσδοκῶν πείσειν εἴτε μᾶλλον ὁρῶν σωφρονοῦντα τὸν δῆμον καὶ πολιτευόμενον εὐτάκτως διὰ τὸν φόβον, ἐκείνην μὲν ἀεὶ διωθεῖτο τὴν πρεσβείαν, τὰ δὲ χρήματα μὴ πράττειν, ἀλλὰ μέλλειν καὶ ἀναβάλλεσθαι τὸν Ἀντίπατρον ἔπεισε. μεταβάντες οὖν Δημάδην παρεκάλουν. ὁ δὲ προθύμως ὑπέστη καὶ τὸν υἱὸν ἔχων ἀπῆρεν εἰς Μακεδονίαν, ὑπὸ δαίμονός τινος, ὡς ἔοικεν, εἰς τοῦτο καιροῦ κομισθείς ἐν ᾧ κατείχετο μὲν Ἀντίπατρος ἤδη νόσῳ, Κάσανδρος δὲ τῶν πραγμάτων ἐγκρατὴς γεγονώς εὗρεν ἐπιστολὴν Δημάδου γεγραμμένην πρὸς Ἀντίγονον εἰς Ἀσίαν, παρακαλοῦντος αὐτὸν ἐπιφανῆναι τοῖς περὶ τὴν Ἑλλάδα καὶ Μακεδονίαν, ἐκ παλαιοῦ καὶ σαπροῦ κρεμαμένοις στήμονος, τὸν Ἀντίπατρον οὕτω σκώψαντος. ὡς οὖν εἶδεν αὐτὸν ἀφιγμένον ὁ Κάσανδρος, συνέλαβε, καὶ πρῶτα μὲν τὸν υἱὸν ἐγγὺς προσαγαγὼν ἀπέσφαξεν, ὥστε καταδέξασθαι τοῖς κόλποις τὸ αἷμα τὸν πατέρα καὶ καταπλησθῆναι τοῦ φόνου, μετὰ ταῦτα δὲ εἰς ἀχαριστίαν αὐτὸν καὶ προδοσίαν πολλὰ λοιδορήσας καὶ καθυβρίσας ἀπέκτεινεν.", "st": "Phoc. 30.4"}, {"sp": "N", "t": "ἐπεὶ δὲ Ἀντίπατρος ἀποδείξας Πολυσπέρχοντα στρατηγόν, Κάσανδρον δὲ χιλίαρχον, ἐξέλιπεν, εὐθὺς διαναστὰς ὁ Κάσανδρος καὶ προκαταλαμβάνων τὰ πράγματα πέμπει κατὰ τάχος Νικάνορα τῷ Μενύλλῳ διάδοχον τῆς φρουραρχίας, πρὶν ἔκδηλον τὸν Ἀντιπάτρου θάνατον γενέσθαι κελεύσας τὴν Μουνυχίαν παραλαβεῖν. γενομένου δὲ τούτου, καὶ μεθ’ ἡμέρας ὀλίγας πυθομένων τῶν Ἀθηναίων ὅτι τέθνηκεν ὁ Ἀντίπατρος, ἐν αἰτίαις ὁ Φωκίων ἦν καὶ κακῶς ἤκουεν ὡς προαισθόμενος καὶ κατασιωπήσας χάριτι τοῦ Νικάνορος. ὁ δὲ τούτων μὲν οὐκ ἐφρόντιζεν, ἐντυγχάνων δὲ τῷ Νικάνορι καὶ διαλεγόμενος εἴς τε τἆλλα τοῖς Ἀθηναίοις πρᾷον αὐτὸν καὶ κεχαρισμένον παρεῖχε, καὶ φιλοτιμίας τινὰς ἔπεισε καὶ δαπάνας ὑποστῆναι γενόμενον ἀγωνοθέτην.", "st": "Phoc. 31.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ καὶ Πολυσπέρχων, τὴν τοῦ βασιλέως ἐπιμέλειαν ἔχων ὑφ’ ἑαυτῷ καὶ καταπολιτευόμενος τὸν Κάσανδρον, ἔπεμψεν ἐπιστολὴν τοῖς ἐν ἄστει γεγραμμένην, ὡς τοῦ βασιλέως ἀποδιδόντος αὐτοῖς τὴν δημοκρατίαν καὶ πολιτεύεσθαι κατὰ τὰ πάτρια πάντας Ἀθηναίους κελεύοντος. ἦν δὲ τοῦτο κατὰ τοῦ Φωκίωνος ἐπιβουλή, συσκευαζόμενος γὰρ εἰς ἑαυτόν, ὡς μικρὸν ὕστερον ἔδειξε τοῖς ἔργοις, ὁ Πολυσπέρχων τὴν πόλιν, οὐδὲν ἤλπιζε περαίνειν μὴ τοῦ Φωκίωνος ἐκπεσόντος· ἐκπεσεῖσθαι δὲ ἐκεῖνον ἅμα τῶν ἀπεψηφισμένων ἐπιχυθέντων τῇ πολιτείᾳ καὶ πάλιν τὸ βῆμα δημαγωγῶν κατασχόντων καὶ συκοφαντῶν.", "st": "Phoc. 32.1"}, {"sp": "N", "t": "ὑποκινουμένων δὲ πρὸς ταῦτα τῶν Ἀθηναίων, βουλόμενος ἐντυχεῖν αὐτοῖς ὁ Νικάνωρ, ἐν Πειραιεῖ βουλῆς γενομένης, παρῆλθε, τῷ Φωκίωνι ἐμπιστεύσας τὸ σῶμα. Δερκύλλου δὲ τοῦ ἐπὶ τῆς χώρας στρατηγοῦ συλλαβεῖν αὐτὸν ἐπιχειρήσαντος, ἐκεῖνος μὲν προαισθόμενος ἐξεπήδησε, καὶ φανερὸς ἦν εὐθὺς ἀμυνούμενος τὴν πόλιν, ὁ δὲ Φωκίων ἐπὶ τῷ προέσθαι τὸν ἄνδρα καὶ μὴ κατασχεῖν ἐγκαλούμενος ἔφη πιστεύειν μὲν τῷ Νικάνορι καὶ μηδὲν ἀπ’ αὐτοῦ προσδοκᾶν δεινόν εἰ δὲ μή, μᾶλλον ἐθέλειν ἀδικούμενος ἢ ἀδικῶν φανερὸς γενέσθαι. τοῦτο δὲ ὑπὲρ αὐτοῦ μὲν ἄν τινι σκοποῦντι δοκοίη καλοκαγαθικῶς λελέχθαι καὶ γενναίως· ὁ δὲ εἰς πατρίδος ἀποκινδυνεύων σωτηρίαν, καὶ ταῦτα στρατηγὸς καὶ ἄρχων, οὐκ οἶδα μὴ μεῖζόν τι παραβαίνει καὶ πρεσβύτερον τὸ πρὸς τοὺς πολίτας δίκαιον, οὐδὲ γὰρ ἐκεῖνο ἔστιν εἰπεῖν, ὅτι φοβούμενος μὲν εἰς πόλεμον ἐμβαλεῖν τὴν πόλιν ὁ Φωκίων ἀπέσχετο τοῦ Νι. κάνορος, ἄλλως δὲ προὐβάλλετο τὴν πίστιν καὶ τὸ δίκαιον, ὅπως αἰδούμενος ἐκεῖνος ἡσυχίαν ἄγῃ καὶ μηδὲν ἀδικῇ τοὺς Ἀθηναίους· ἀλλ’ ὄντως ἔοικεν ἰσχυρά τις αὐτῷ περὶ τοῦ Νικάνορος ἐγγενέσθαι πίστις, ὅν γε πολλῶν προδιαβαλλόντων καὶ κατηγορούντων ἐπιτίθεσθαι τῷ Πειραιεῖ καὶ διαβιβάζειν εἰς Σαλαμῖνα ξένους καὶ διαφθείρειν τινὰς τῶν ἐν Πειραιεῖ κατοικούντων, οὐ προσήκατο τὸν λόγον οὐδ’ ἐπίστευσεν, ἀλλὰ καὶ Φιλομήλου τοῦ Λαμπτρέως ψήφισμα γράψαντος Ἀθηναίους ἅπαντας ἐν τοῖς ὅπλοις εἶναι καὶ τῷ στρατηγῷ Φωκίωνι προσέχειν, ἠμέλησεν, ἄχρι οὗ προσάγων ὁ Νικάνωρ ἐκ τῆς Μουνυχίας τὰ ὅπλα τὸν Πειραιᾶ περιετάφρευσε.", "st": "Phoc. 32.3"}, {"sp": "N", "t": "πραττομένων δὲ τούτων ὁ μὲν Φωκίων ἐθορυβεῖτο καὶ κατεφρονεῖτο τοὺς Ἀθηναίους ἐξάγειν βουλόμενος, Ἀλέξανδρος δὲ ὁ Πολυσπέρχοντος υἱὸς ἧκε μετὰ δυνάμεως, λόγῳ μὲν ἐπὶ τὸν Νικάνορα τοῖς ἐν ἄστει βοηθήσων, ἔργῳ δὲ τὴν πόλιν, εἰ δύναιτο, καταληψόμενος αὐτὴν ἑαυτῇ περιπετῆ γενομένην. οἵ τε γὰρ φυγάδες αὐτῷ συνεισβαλόντες εὐθὺς ἦσαν ἐν ἄστει, καὶ τῶν ξένων ἅμα καὶ τῶν ἀτίμων πρὸς αὐτοὺς εἰσδραμόντων ἐκκλησία παμμιγὴς ἠθροίσθη καὶ ἄτακτος, ἐν ᾗ τὸν Φωκίωνα τῆς ἀρχῆς ἀπολύσαντες ἑτέρους εἵλοντο στρατηγούς, εἰ δὲ μὴ συνιὼν εἰς λόγους ὁ Ἀλέξανδρος τῷ Νικάνορι μόνος παρὰ τὸ τεῖχος ὤφθη, καὶ τοῦτο ποιοῦντες πολλάκις ὑποψίαν τοῖς Ἀθηναίοις παρέσχον, οὐκ ἂν ἡ πόλις διέφυγε τὸν κίνδυνον. ἐπεὶ δὲ Ἁγνωνίδης ὁ ῥήτωρ εὐθὺς ἐπεφύετο τοῖς περὶ τὸν Φωκίωνα καὶ κατηγόρει προδοσίας, οἱ μὲν περὶ Καλλιμέδοντα καὶ Χαρικλέα φοβηθέντες ἀπῆλθον ἐκ τῆς πόλεως, ὁ δὲ Φωκίων καὶ μετ’ αὐτοῦ τῶν φίλων οἱ παραμείναντες ᾤχοντο πρὸς Πολυσπέρχοντα. καὶ συνεξῆλθον αὐτοῖς χάριτι τοῦ Φωκίωνος ὁ Πλαταιεὺς Σόλων καὶ Δείναρχος ὁ Κορίνθιος, ἐπιτήδειοι τοῦ Πολυσπέρχοντος εἶναι δοκοῦντες καὶ συνήθεις. ἀρρωστίᾳ δὲ χρησαμένου τοῦ Δεινάρχου συχνὰς ἡμέρας ἐν Ἐλατείᾳ διέτριψαν, ἐν αἷς Ἁγνωνίδου πείσαντος, Ἀρχεστράτου δὲ τὸ ψήφισμα γράψαντος, ἔπεμπε πρεσβείαν ὁ δῆμος κατηγορήσουσαν τοῦ Φωκίωνος, ἅμα δὲ καὶ συνέμιξαν ἀμφότεροι τῷ Πολυσπέρχοντι μετὰ τοῦ βασιλέως πορευομένῳ περὶ κώμην τινὰ τῆς Φωκίδος, Φαρύγας, κειμένην ὑπὸ τὸ Ἀκρούριον ὄρος, ὃ νῦν Γαλάτην καλοῦσιν.", "st": "Phoc. 33.1"}, {"sp": "N", "t": "ἐνταῦθα δὴ θεὶς ὁ Πολυσπέρχων τὸν χρυσοῦν οὐρανίσκον, καὶ καθίσας ὑπ’ αὐτῷ τὸν βασιλέα καὶ τοὺς φίλους, τὸν μὲν Δείναρχον εὐθὺς ἐκ προόδου λαβεῖν ἐκέλευσε καὶ στρεβλώσαντας ἀποκτεῖναι, τοῖς δὲ Ἀθηναίοις ἀπέδωκε λόγον. ὡς δὲ θόρυβον καὶ κραυγὴν ἐποίουν ἀντικατηγοροῦντες ἀλλήλων ἐν τῷ συνεδρίῳ, καὶ προσελθὼν ὁ Ἁγνωνίδης εἶπεν, ἅπαντας ἡμᾶς εἰς μίαν ἐμβαλόντες γαλεάγραν Ἀθηναίοις ἀναπέμψατε λόγον ὑφέξοντας, ὁ μὲν βασιλεὺς ἐγέλασεν, οἱ δὲ περιεστῶτες τῷ συνεδρίῳ Μακεδόνες καὶ ξένοι σχολὴν ἄγοντες ἐπεθύμουν ἀκούειν, καὶ τοὺς πρέσβεις παρεκάλουν ἀπὸ νεύματος ἐνταῦθα ποιεῖσθαι τὴν κατηγορίαν. ἦν δὲ οὐδὲν ἴσον, ἀλλὰ τῷ μὲν Φωκίωνι πολλάκις ἀντέκρουσεν ὁ Πολυσπέρχων λέγοντι, μέχρι οὗ τῇ βακτηρίᾳ πατάξας τὴν γῆν ἀπέστη καὶ κατεσιώπησεν. Ἡγήμονος δὲ φήσαντος ὅτι μάρτυς αὐτῷ τῆς πρὸς τὸν δῆμον εὐνοίας Πολυσπέρχων ἐστί, καὶ τοῦ Πολυσπέρχοντος ἀποκριναμένου πρὸς ὀργὴν, παῦσαί μου πρὸς τὸν βασιλέα καταψευδόμενος, ἀναπηδήσας ὁ βασιλεὺς ὥρμησε λόγχῃ τὸν Ἡγήμονα πατάξαι. ταχὺ δὲ τοῦ Πολυσπέρχοντος περιλαβόντος αὐτόν οὕτω διελύθη τὸ συνέδριον.", "st": "Phoc. 33.5"}, {"sp": "N", "t": "τὸν δὲ Φωκίωνα καὶ τοὺς μετ’ αὐτοῦ φυλακῆς περιεχούσης, ὅσοι τῶν ἑταίρων ἔτυχον οὐκ ἐγγὺς ἑστῶτες, ὡς τοῦτο εἶδον, ἐγκαλυψάμενοι καὶ διαφυγόντες ἐσώθησαν. ἐκείνους δὲ Κλεῖτος εἷς Ἀθήνας ἀνῆγε λόγῳ μὲν κριθησομένους, ἔργῳ δὲ ἀποθανεῖν κατακεκριμένους. καὶ προσῆν τὸ σχῆμα τῇ κομιδῇ λυπηρόν, ἐφ’ ἁμάξαις κομιζομένων αὐτῶν διὰ τοῦ Κεραμεικοῦ πρὸς τὸ θέατρον· ἐκεῖ γὰρ αὐτοὺς προσαγαγὼν ὁ Κλεῖτος συνεῖχεν, ἄχρι οὗ τὴν ἐκκλησίαν ἐπλήρωσαν οἱ ἄρχοντες, οὐ δοῦλον, οὐ ξένον, οὐκ ἄτιμον ἀποκρίναντες, ἀλλὰ πᾶσι καὶ πάσαις ἀναπεπταμένον τὸ βῆμα καὶ τὸ θέατρον παρασχόντες. ἐπεὶ δὲ ἥ τ’ ἐπιστολὴ τοῦ βασιλέως ἀνεγνώσθη, λέγοντος αὐτῷ μὲν ἐγνῶσθαι προδότας γεγονέναι τοὺς ἄνδρας, ἐκείνοις δὲ διδόναι τὴν κρίσιν ἐλευθέροις τε δὴ καὶ αὐτονόμοις οὖσι, καὶ τοὺς ἄνδρας ὁ Κλεῖτος εἰσήγαγεν, οἱ μὲν βέλτιστοι τῶν πολιτῶν ὀφθέντος τοῦ Φωκίωνος ἐνεκαλύψαντο καὶ κάτω κύψαντες ἐδάκρυον, εἷς δὲ ἀναστὰς ἐτόλμησεν εἰπεῖν ὅτι, τηλικαύτην κρίσιν ἐγκεχειρικότος τῷ δήμῳ τοῦ βασιλέως, καλῶς ἔχει τοὺς δούλους καὶ τοὺς ξένους ἀπελθεῖν ἐκ τῆς ἐκκλησίας. οὐκ ἀνασχομένων δὲ τῶν πολλῶν, ἀλλ’ ἀνακραγόντων βάλλειν τοὺς ὀλιγαρχικοὺς καὶ μισοδήμους, ἄλλος μὲν οὐδεὶς ὑπὲρ τοῦ Φωκίωνος ἐπεχείρησεν εἰπεῖν, αὐτὸς δὲ χαλεπῶς καὶ μόλις ἐξακουσθείς, πότερον, εἶπεν, ἀδίκως ἢ δικαίως ἀποκτεῖναι βούλεσθε ἡμᾶς; ἀποκριναμένων δέ τινων ὅτι δικαίως, καὶ τοῦτο, ἔφη, πῶς γνώσεσθε μὴ ἀκούσαντες; ἐπεὶ δὲ οὐθὲν μᾶλλον ἤκουον, ἐγγυτέρω προσελθών, ἐγὼ μὲν, εἶπεν, ἀδικεῖν ὁμολογῶ, καὶ θανάτου τιμῶμαι τὰ πεπολιτευμένα ἐμαυτῷ· τούτους δέ, ἄνδρες Ἀθηναῖοι, διὰ τί ἀποκτενεῖτε μηδὲν ἀδικοῦντας; ἀποκριναμένων δὲ πολλῶν, ὅτι σοὶ φίλοι εἰσίν, ὁ μὲν Φωκίων ἀποστὰς ἡσυχίαν ἦγεν, ὁ δὲ Ἁγνωνίδης ψήφισμα γεγραμμένον ἔχων ἀνέγνω, καθ’ ὃ τὸν δῆμον ἔδει χειροτονεῖν περὶ τῶν ἀνδρῶν εἰ δοκοῦσιν ἀδικεῖν, τοὺς δὲ ἄνδρας, ἂν καταχειροτονηθῶσιν, ἀποθνῄσκειν.", "st": "Phoc. 34.1"}, {"sp": "N", "t": "ἀναγνωσθέντος δὲ τοῦ ψηφίσματος ἠξίουν τινὲς προσγράφειν ὅπως καί στρεβλωθεὶς Φωκίων ἀποθάνοι, καί τὸν τροχὸν εἰσφέρειν καί τοὺς ὑπηρέτας καλεῖν προσέταττον. ὁ δὲ Ἁγνωνίδης καί τὸν Κλεῖτον ὁρῶν δυσχεραίνοντα καί τὸ πρᾶγμα βαρβαρικὸν εἶναι καί μιαρὸν ἡγούμενος, ὅταν, ἔφη, Καλλιμέδοντα τὸν μαστιγίαν λάβωμεν, ὦ ἄνδρες Ἀθηναῖοι, στρεβλώσομεν· περὶ δὲ Φωκίωνος οὐδὲν ἐγὼ γράφω τοιοῦτον. ἐνταῦθα τῶν ἐπιεικῶν τις ὑπεφώνησεν ὀρθῶς γε σὺ ποιῶν ἂν γὰρ Φωκίωνα βασανίσωμεν, σὲ τί ποιήσομεν; ἐπικυρωθέντος δὲ τοῦ ψηφίσματος καί τῆς χειροτονίας ἀποδοθείσης, οὐδεὶς καθήμενος, ἀλλὰ πάντες ἐξαναστάντες, οἱ δὲ πλεῖστοι καί στεφανωσάμενοι, κατεχειροτόνησαν αὐτῶν θάνατον, ἦσαν δὲ σὺν τῷ Φωκίωνι Νικοκλῆς, Θούδιππος, Ἡγήμων, Πυθοκλῆς· Δημητρίου δὲ τοῦ Φαληρέως καί Καλλιμέδοντος καί Χαρικλέους καί τινων ἄλλων ἀπόντων κατεψηφίσθη θάνατος.", "st": "Phoc. 35.1"}, {"sp": "N", "t": "ὡς οὖν διαλύσαντες τὴν ἐκκλησίαν ἦγον εἷς τὸ δεσμωτήριον τοὺς ἄνδρας, οἱ μὲν ἄλλοι, περιπλεκομένων τῶν φίλων αὐτοῖς καὶ οἰκείων, ὀδυρόμενοι καὶ καταθρηνοῦντες ἐβάδιζον, τὸ δὲ Φωκίωνος πρόσωπον οἷον ὅτε στρατηγῶν ἀπ’ ἐκκλησίας προὐπέμπετο βλέποντες, ἐθαύμαζον τὴν ἀπάθειαν καὶ μεγαλοψυχίαν τοῦ ἀνδρός. οἱ δὲ ἐχθροὶ κακῶς ἔλεγον παρατρέχοντες εἷς δὲ καὶ προσέπτυσεν ἐξεναντίας προσελθών. ὅτε καὶ τὸν Φωκίωνα λέγεται βλέψαντα πρὸς τοὺς ἄρχοντας εἰπεῖν οὐ παύσει τις ἀσχημονοῦντα τοῦτον; ἐπεὶ δὲ Θούδιππος ἐν τῷ δεσμωτηρίῳ γενόμενος καὶ τὸ κώνειον ὁρῶν τριβόμενον ἠγανάκτει καὶ κατέκλαιε τὴν συμφοράν, ὡς οὐ προσηκόντως τῷ Φωκίωνι συναπολλύμενος, εἶτα οὐκ ἀγαπᾷς, εἶπεν, ὅτι μετὰ Φωκίωνος ἀποθνῄσκεις; ἐρομένου δέ τινος τῶν φίλων εἴ τι πρὸς Φῶκον λέγει τὸν υἱόν, πάνυ μὲν οὖν, ἔφη· λέγω μὴ μνησικακεῖν Ἀθηναίοις. τοῦ δὲ Νικοκλέους, ὃς ἦν αὐτῷ πιστότατος τῶν φίλων, παρακαλοῦντος ὅπως αὐτὸν ἐάσῃ τὸ φάρμακον πιεῖν πρότερον, βαρὺ μέν, εἶπεν, ὦ Νικόκλεις, ἐμοὶ τὸ αἴτημα καὶ λυπηρόν, ἐπεὶ δὲ οὐδὲ ἄλλο οὐδέποτέ σοι παρὰ τὸν βίον οὐδὲν ἠχαρίστησα, καὶ τοῦτο συγχωρῶ. πεπωκότων δὲ ἤδη πάντων τὸ φάρμακον ἐπέλιπε, καὶ ὁ δημόσιος οὐκ ἔφη τρίψειν ἕτερον, εἰ μὴ λάβοι δώδεκα δραχμάς, ὅσου τὴν ὁλκὴν ὠνεῖται. χρόνου δὲ γενομένου καὶ διατριβῆς ὁ Φωκίων καλέσας τινὰ τῶν φίλων, καὶ εἰπών εἰ μηδὲ ἀποθανεῖν Ἀθήνησι δωρεὰν ἔστιν, ἐκέλευσε τῷ ἀνθρώπῳ δοῦναι τὸ κερμάτιον.", "st": "Phoc. 36.1"}, {"sp": "N", "t": "ἦν δὲ ἡμέρα μηνὸς Μουνυχιῶνος ἐνάτη ἐπὶ δέκα, καὶ τῷ Διῒ τὴν πομπὴν πέμποντες οἱ ἱππεῖς παρεξῄεσαν ὧν οἱ μὲν ἀφείλοντο τοὺς στεφάνους, οἱ δὲ πρὸς τὰς θύρας δεδακρυμένοι τῆς εἱρκτῆς ἀπέβλεψαν. ἐφάνη δὲ τοῖς μὴ παντάπασιν ὠμοῖς καὶ διεφθαρμένοις ὑπ’ ὀργῆς καὶ φθόνου τὴν ψυχὴν, ἀνοσιώτατον γεγονέναι τὸ μηδ’ ἐπισχεῖν τὴν ἡμέραν ἐκείνην, μηδὲ καθαρεῦσαι δημοσίου φόνου τὴν πόλιν ἑορτάζουσαν. οὐ μὴν ἀλλ’ ὥσπερ ἐνδεέστερον ἠγωνισμένοις τοῖς ἐχθροῖς ἔδοξε καὶ τὸ σῶμα τοῦ Φωκίωνος ἐξορίσαι καὶ μηδὲ πῦρ ἐναῦσαι μηδένα πρὸς τὴν ταφὴν Ἀθηναίων, διὸ φίλος μὲν οὐδεὶς ἐτόλμησεν ἅψασθαι τοῦ σώματος, Κωνωπίων δέ τις, ὑπουργεῖν εἰθισμένος τὰ τοιαῦτα μισθοῦ, κομισθέντα τὸν νεκρὸν ὑπὲρ τὴν Ἐλευσῖνα, πῦρ λαβὼν ἐκ τῆς Μεγαρικῆς, ἔκαυσεν. ἡ δὲ γυνὴ παροῦσα μετὰ τῶν θεραπαινίδων ἔχωσε μὲν αὐτόθι χῶμα κενὸν καὶ κατέσπεισεν, ἐνθεμένη δὲ τῷ κόλπῳ τὰ ὀστᾶ καὶ κομίσασα νύκτωρ εἰς τὴν οἰκίαν κατώρυξε παρὰ τὴν ἑστίαν, εἰποῦσα· σοὶ, ὦ φίλη ἑστία, παρακατατίθεμαι ταῦτα ἀνδρὸς ἀγαθοῦ λείψανα· σὺ δὲ αὐτὰ τοῖς πατρῴοις ἀπόδος ἠρίοις, ὅταν Ἀθηναῖοι σωφρονήσωσι.", "st": "Phoc. 37.1"}, {"sp": "N", "t": "καὶ μέντοι χρόνου βραχέος διαγενομένου, καὶ τῶν πραγμάτων διδασκόντων οἷον ἐπιστάτην καὶ φύλακα σωφροσύνης καὶ δικαιοσύνης ὁ δῆμος ἀπώλεσεν, ἀνδριάντα μὲν αὐτοῦ χαλκοῦν ἀνέστησαν, ἔθαψαν δὲ δημοσίοις τέλεσι τὰ ὀστᾶ. τῶν δὲ κατηγόρων Ἁγνωνίδην μὲν αὐτοὶ θάνατον καταχειροτονήσαντες ἀπέκτειναν, Ἐπίκουρον δὲ καὶ Δημόφιλον ἀποδράντας ἐκ τῆς πόλεως ἀνευρὼν ὁ τοῦ Φωκίωνος υἱὸς ἐτιμωρήσατο.", "st": "Phoc. 38.1"}, {"sp": "N", "t": "τοῦτον οὔτε τἆλλα σπουδαῖον ἄνδρα γενέσθαι φασί, καὶ παιδίσκης ἐρῶντα παρὰ πορνοβοσκῷ τρεφομένης κατὰ τύχην Θεοδώρῳ τῷ ἀθέῳ παραγενέσθαι λόγον ἐν Λυκείῳ διαλεγομένῳ τοιοῦτον εἰ τὸ φίλον λύσασθαι μὴ αἰσχρόν ἐστιν, οὐδὲ τὸ φίλην ὁμοίως· εἰ δὲ μὴ τὸ ἑταῖρον, οὐδὲ τὸ ἑταίραν· θέμενον οὖν ἑαυτῷ πρὸς τὴν ἐπιθυμίαν τὸν λόγον ὡς εὖ ἔχοντα, λύσασθαι τὴν ἑταίραν.", "st": "Phoc. 38.2"}, {"sp": "N", "t": "ἀλλὰ τὰ μὲν περὶ Φωκίωνα πραχθέντα τῶν περὶ Σωκράτην πάλιν ἀνέμνησε τοὺς Ἕλληνας, ὡς ὁμοιοτάτης ἐκείνῃ τῆς ἁμαρτίας ταύτης καὶ δυστυχίας τῇ πόλει γενομένης.", "st": "Phoc. 38.2b"}, {"sp": "HDR", "t": "Κάτων"}, {"sp": "N", "t": "Κάτωνι δὲ τὸ μὲν γένος ἀρχὴν ἐπιφανείας ἔλαβε καὶ δόξης ἀπὸ τοῦ προπάππου Κάτωνος, ἀνδρὸς ἐν δόξῃ καὶ δυνάμει μάλιστα Ῥωμαίων γενομένου δι’ ἀρετήν, ὡς ἐν τοῖς περὶ ἐκείνου γέγραπται, κατελείφθη δὲ γονέων ὀρφανὸς μετ’ ἀδελφοῦ Καιπίωνος καὶ Πορκίας ἀδελφῆς. ἦν δὲ καὶ Σερβιλία Κάτωνος ὁμομήτριος ἀδελφή. καὶ πάντες οὗτοι παρὰ Λιβίῳ Δρούσῳ τροφὴν καὶ δίαιταν εἶχον, θείῳ μὲν ὄντι πρὸς μητρός, ἄγοντι δὲ τὴν πολιτείαν τότε· καὶ γὰρ εἰπεῖν δεινότατος ἦν, καὶ τἆλλα σώφρων ἀνὴρ ἐν τοῖς μάλιστα, καὶ φρονήματος οὐδενὶ Ῥωμαίων ὑφιέμενος.", "st": "Cat. Mi. 1.1"}, {"sp": "N", "t": "λέγεται δὲ Κάτων εὐθὺς ἐκ παιδίου τῇ τε φωνῇ καὶ τῷ προσώπῳ καὶ ταῖς περὶ τὰς παιδιὰς διατριβαῖς ἦθος ὑποφαίνειν ἄτρεπτον καὶ ἀπαθὲς καὶ βέβαιον ἐν πᾶσιν. ἰσχύν τε γὰρ εἶχον αὐτοῦ παρ’ ἡλικίαν τελεσιουργὸν αἱ ὁρμαί, καὶ τοῖς κολακεύουσι τραχὺς ὢν καὶ προσάντης, ἔτι μᾶλλον ἐκράτει τῶν ἐκφοβούντων. ἦν δὲ καὶ πρὸς γέλωτα κομιδῇ δυσκίνητος, ἄχρι μειδιάματος σπανίως τῷ προσώπῳ διαχεόμενος, καὶ πρὸς ὀργὴν οὐ ταχὺς οὐδὲ ὀλισθηρός, ὀργισθεὶς δὲ δυσπαραίτητος.", "st": "Cat. Mi. 1.2"}, {"sp": "N", "t": "ὡς οὖν εἰς τὸ μανθάνειν ἧκε, νωθρὸς ἦν ἀναλαβεῖν καὶ βραδύς, ἀναλαβὼν δὲ κάτοχος καὶ μνημονικός, ὃ δὴ καὶ πέφυκεν ἄλλως, τοὺς μὲν εὐφυεῖς ἀναμνηστικοὺς μᾶλλον εἶναι, μνημονικοὺς δὲ τοὺς μετὰ πόνου καὶ πραγματείας παραδεχομένους· γίνεται γὰρ οἷον ἔγκαυμα τῆς ψυχῆς τῶν μαθημάτων ἕκαστον. ἔοικε δὲ καὶ τὸ δύσπειστον τῷ Κάτωνι ποιεῖν ἐργωδεστέραν τὴν μάθησιν· πάσχειν γάρ τι τὸ μανθάνειν ἀτεχνῶς ἐστι, καὶ τὸ πείθεσθαι ταχὺ τοῖς ἧττον ἀντέχειν δυναμένοις συμβέβηκε. διὸ πείθονται μᾶλλον νέοι γερόντων καὶ νοσοῦντες ὑγιαινόντων, καὶ ὅλως ἐν οἷς τὸ ἀποροῦν ἀσθενέστατόν ἐστι, ῥᾷστον τὸ προστιθέμενον. τῷ μέντοι παιδαγωγῷ τὸν Κάτωνα πείθεσθαι μὲν λέγουσι καὶ ποιεῖν ἅπαν τὸ προσταττόμενον, ἑκάστου δὲ τὴν αἰτίαν ἀπαιτεῖν καὶ τὸ διὰ τί πυνθάνεσθαι. καὶ γὰρ ἦν χαρίεις ὁ παιδαγωγὸς αὐτοῦ καὶ λόγον ἔχων τοῦ κονδύλου προχειρότερον, ὄνομα Σαρπηδών.", "st": "Cat. Mi. 1.3"}, {"sp": "N", "t": "ἔτι δὲ παιδὸς τοῦ Κάτωνος ὄντος ἔπραττον οἱ σύμμαχοι τῶν Ῥωμαίων ὅπως μεθέξουσι τῆς ἐν Ῥώμῃ πολιτείας· καί τις Πομπαίδιος Σίλλων, ἀνὴρ πολεμικὸς καί μέγιστον ἔχων ἀξίωμα, τοῦ δὲ Δρούσου φίλος, κατέλυσε παρ’ αὐτῷ πλείονας ἡμέρας, ἐν αἷς γεγονὼς τοῖς παιδίοις συνήθης, ἄγε, εἶπεν, ὅπως ὑπὲρ ἡμῶν δεήσεσθε τοῦ θείου συναγωνίσασθαι περὶ τῆς πολιτείας. ὁ μὲν οὖν Καιπίων διαμειδιάσας ἐπένευσε, τοῦ δὲ Κάτωνος οὐδὲν ἀποκριναμένου καί βλέποντος εἷς τοὺς ξένους ἀτενὲς καί βλοσυρόν, ὁ Πομπαίδιος, σὺ δέ, εἶπεν, ἡμῖν, ὦ νεανία, τί λέγεις; οὐχ οἷος εἶ τοῖς ξένοις συλλαμβάνεσθαι πρὸς τὸν θεῖον, ὥσπερ ὁ ἀδελφός; μὴ φθεγγομένου δὲ τοῦ Κάτωνος, ἀλλὰ τῇ σιωπῇ καί τῷ προσώπῳ δοκοῦντος ἀπολέγεσθαι τὴν δέησιν, ἀράμενος αὐτὸν ὁ Πομπαίδιος ὑπὲρ θυρίδος ὡς ἀφήσων ὁμολογεῖν ἐκέλευεν ἢ ῥίψειν ἔφασκεν, ἅμα τῇ τε φωνῇ τραχυτέρᾳ χρώμενος καί ταῖς χερσὶν ἀπηρτημένον τὸ σῶμα πολλάκις ὑπὲρ τῆς θυρίδος κραδαίνων. ἐπεὶ δὲ πολὺν χρόνον οὕτω διεκαρτέρησεν ὁ Κάτων ἀνέκπληκτος καί ἀδεής, καταθέμενος αὐτὸν Πομπαίδιος ἡσυχῇ πρὸς τοὺς φίλους εἶπεν· οἷον εὐτύχημα τῆς Ἰταλίας ὅτι παῖς οὗτός ἐστιν· εἰ δὲ ἀνὴρ ἦν, μίαν οὐκ ἂν οἶμαι ψῆφον ἡμῖν ἐν τῷ δήμῳ γενέσθαι.", "st": "Cat. Mi. 2.1"}, {"sp": "N", "t": "πάλιν δὲ συγγενοῦς τινος ἐν γενεθλίοις καλέσαντος ἐπὶ δεῖπνον ἄλλους τε παῖδας καί τοὺς περὶ Κάτωνα, σχολὴν ἄγοντες ἔν τινι μέρει τῆς οἰκίας ἔπαιζον αὐτοὶ καθ’ ἑαυτοὺς ἀναμεμιγμένοι νεώτεροι καί πρεσβύτεροι, τὸ δὲ παιζόμενον ἦν δίκαι καί κατηγορίαι καί ἀγωγαὶ τῶν ἁλισκομένων. εἷς οὖν τῶν ἑαλωκότων παίδων εὐπρεπὴς τὴν ὄψιν ὑπὸ πρεσβυτέρου παιδὸς ἀχθεὶς εἴς τι δωμάτιον καί εἱρχθείς ἐπεκαλεῖτο τὸν Κάτωνα, ταχὺ δὴ τὸ γινόμενον συνεὶς ἧκεν ἐπὶ τὰς θύρας ὁ Κάτων, καί διωσάμενος τοὺς προεστῶτας καί διακωλύοντας ἐξήγαγε τὸν παῖδα· καί μετ’ ὀργῆς ἔχων ἀπῆλθεν οἴκαδε, καί παῖδες ἕτεροι συνηκολούθησαν.", "st": "Cat. Mi. 2.5"}, {"sp": "N", "t": "οὕτω δ’ ἦν περιβόητος ὥστ’, ἐπειδὴ Σύλλας τὴν παιδικὴν καὶ ἱερὰν ἱπποδρομίαν, ἣν καλοῦσι Τροίαν, ἐπὶ θέᾳ διδάσκων καὶ συναγαγὼν τοὺς εὐγενεῖς παῖδας ἀπέδειξεν ἡγεμόνας δύο, τὸν μὲν ἕτερον οἱ παῖδες ἐδέξαντο διὰ τὴν μητέρα Μετέλλης γὰρ ἦν υἱός, τῆς Σύλλα γυναικός, τὸν δὲ ἕτερον, ἀδελφιδοῦν ὄντα Πομπηΐου, Σέξτον, οὐκ εἴων οὐδὲ ἐβούλοντο μελετᾶν οὐδὲ ἕπεσθαι, πυνθανομένου δὲ τοῦ Σύλλα τίνα βούλοιντο, πάντες ἐβόησαν Κάτωνα, καὶ ὅ γε Σέξτος αὐτὸς εἴξας παρῆκεν ὡς κρείττονι τὴν φιλοτιμίαν.", "st": "Cat. Mi. 3.1"}, {"sp": "N", "t": "ἔτυχε δὲ καὶ φίλος ὢν ὁ Σύλλας πατρικὸς αὐτοῖς, καί ποτε καὶ προσηγάγετο καὶ προσωμίλησεν, ὀλίγοις πάνυ νέμων τὴν τοιαύτην φιλοφροσύνην, διὰ βάρος καὶ ὄγκον ἧς εἶχεν ἀρχῆς καὶ δυνάμεως, μέγα δὴ ποιούμενος ὁ Σαρπηδὼν τοῦτο πρὸς τιμὴν ἅμα καὶ ἀσφάλειαν, ἦγεν ἀσπασόμενον τὸν Κάτωνα συνεχῶς εἰς τὴν οἰκίαν τοῦ Σύλλα, μηδὲν τότε προσιδεῖν ἀσεβῶν χώρου διαφέρουσαν, ὑπὸ πλήθους τῶν ἀγομένων καὶ στρεβλουμένων. ἦν μὲν οὖν ἔτος ἐκεῖνο τῷ Κάτωνι τεσσαρεσκαιδέκατον ἰδὼν δὲ κεφαλὰς ἐπιφανῶν ἀνδρῶν λεγομένων ἐκκομιζομένας, καὶ κρύφα τοὺς παρόντας ἐπιστένοντας, ἠρώτησε τὸν παιδαγωγόν ὅ τι δὴ τοῦτον τὸν ἄνθρωπον οὐδεὶς ἀποκτίννυσιν. εἰπόντος δὲ ἐκείνου, φοβοῦνται γὰρ αὐτὸν, ὦ παῖ, μᾶλλον, ἢ μισοῦσι, τί οὖν, εἶπεν, οὐκ ἐμοὶ ξίφος ἔδωκας, ἵνα αὐτὸν ἀνελὼν ἀπήλλαξα δουλείας τὴν πατρίδα; τοῦτον τὸν λόγον ἀκούσας ὁ Σαρπηδών, ἅμα δὲ καὶ τὸ βλέμμα καὶ τὸ πρόσωπον αὐτοῦ πιμπλάμενον ὀργῆς καὶ μένους κατιδών, οὕτως ἔδεισεν ὥστε τὸ λοιπὸν ἤδη προσέχειν ἀκριβῶς καὶ παραφυλάττειν, μή τι τολμήσῃ παραβολώτερον.", "st": "Cat. Mi. 3.2"}, {"sp": "N", "t": "ἔτι μὲν οὖν παιδάριον ὢν μικρόν, ἀπεκρίνατο τοῖς ἐρωτῶσι τίνα φιλεῖ μάλιστα, τὸν ἀδελφόν τίνα δεύτερον, ὁμοίως τὸν ἀδελφόν, καὶ τρίτον, ἄχρι οὗ πολλάκις λέγοντος ἀπεῖπεν ὁ ἐρωτῶν, γενόμενος δ’ ἐν ἡλικίᾳ μᾶλλον ἐβεβαίου τὴν πρὸς τὸν ἀδελφόν εὔνοιαν. ἔτη γὰρ εἴκοσι γεγονώς χωρὶς Καιπίωνος οὐκ ἐδείπνησεν, οὐκ ἀπεδήμησεν, εἰς ἀγορὰν οὐ προῆλθε. μύρον δ’ ἐκείνου λαμβάνοντος αὐτὸς παρῃτεῖτο· καὶ τἆλλα τὰ περὶ τὴν δίαιταν ἦν ἀκριβὴς καὶ σύντονος, ὁ γοῦν Καιπίων ἐπὶ σωφροσύνῃ καὶ μετριότητι θαυμαζόμενος ὡμολόγει τοιοῦτος εἶναι πρὸς τοὺς ἄλλους ἐξεταζόμενος, ἀλλ’ ὅταν, ἔφη, παρὰ τὸν Κάτωνος βίον παραβάλλω τὸν ἐμόν, οὐδὲν ἐμαυτῷ φαίνομαι Σιππίου διαφέρειν, τῶν ἐπὶ τρυφῇ τινα καὶ μαλακίᾳ περιβοήτων ὀνομάσας.", "st": "Cat. Mi. 3.5"}, {"sp": "N", "t": "ὁ δὲ Κάτων ἐπειδὴ τὴν ἱερωσύνην ἔλαβε τοῦ Ἀπόλλωνος, μετοικήσας καὶ νειμάμενος μοῖραν τῶν πατρῴων ἑκατὸν εἴκοσι ταλάντων γενομένην, τὴν μὲν δίαιταν ἔτι μᾶλλον συνέστειλεν, Ἀντίπατρον δὲ Τύριον τῶν ἀπὸ τῆς στοᾶς φιλοσόφων προσεταιρισάμενος, τοῖς ἠθικοῖς μάλιστα καὶ πολιτικοῖς ἐνεφύετο δόγμασι, περὶ πᾶσαν μὲν ἀρετὴν ὥσπερ ἐπιπνοίᾳ τινὶ κατάσχετος γεγονώς, διαφόρως δὲ τοῦ καλοῦ τὸ περὶ τὴν δικαιοσύνην ἀτενὲς, καὶ ἄκαμπτον εἰς ἐπιείκειαν ἢ χάριν, ὑπερηγαπηκώς. ἤσκει δὲ καὶ τὸν ὀργανικὸν εἰς πλήθη λόγον, ἀξιῶν ὥσπερ ἐν πόλει μεγάλῃ τῇ πολιτικῇ φιλοσοφίᾳ καὶ μάχιμον εἶναί τι παρατρεφόμενον. οὐ μέντοι μεθ’ ἑτέρων ἐποιεῖτο τὰς μελέτας, οὐδ’ ἠκροάσατο λέγοντος οὐδείς, ἀλλὰ καὶ πρός τινα τῶν ἑταίρων εἰπόντα, μέμφονταί σου, Κάτων, οἱ ἄνθρωποι τὴν σιωπήν, μόνον, ἔφη, μὴ τὸν βίον. ἄρξομαι δὲ λέγειν, ὅταν μὴ μέλλω λέγειν ἄξια σιωπῆς.", "st": "Cat. Mi. 4.1"}, {"sp": "N", "t": "ἡ δὲ καλουμένη Πορκία βασιλικὴ τιμητικὸν ἦν ἀνάθημα τοῦ παλαιοῦ Κάτωνος, εἰωθότες οὖν ἐκεῖ χρηματίζειν οἱ δήμαρχοι, καὶ κίονος τοῖς δίφροις ἐμποδὼν εἶναι δοκοῦντος, ἔγνωσαν ὑφελεῖν αὐτὸν ἢ μεταστῆσαι. τοῦτο Κάτωνα πρῶτον εἰς ἀγορὰν ἄκοντα προήγαγεν· ἀντέστη γὰρ αὐτοῖς, καὶ πεῖραν ἅμα τοῦ λόγου καὶ τοῦ φρονήματος δούς ἐθαυμάσθη. καὶ γὰρ ὁ λόγος νεαρὸν μὲν οὐδὲν οὐδὲ κομψὸν εἶχεν, ἀλλ’ ἦν ὄρθιος καὶ περιπληθὴς καὶ τραχύς, οὐ μὴν ἀλλὰ καὶ χάρις ἀγωγὸς ἀκοῆς ἐπέτρεχε τῇ τραχύτητι τῶν νοημάτων, καὶ τὸ ἦθος αὐτοῦ καταμιγνύμενον ἡδονήν τινα καὶ μειδίαμα τῷ σεμνῷ παρεῖχεν οὐκ ἀπάνθρωπον. ἡ δὲ φωνὴ μεγέθει μὲν ἀποχρῶσα καὶ διαρκὴς εἰς τοσοῦτον ἐξικέσθαι δῆμον, ἰσχὺν δὲ καὶ τόνον ἄρρηκτον εἶχε καὶ ἄτρυτον· ἡμέραν γὰρ ὅλην εἰπὼν πολλάκις οὐκ ἀπηγόρευσε.", "st": "Cat. Mi. 5.1"}, {"sp": "N", "t": "τότε δ’ οὖν κρατήσας τῆς δίκης πάλιν ἑαυτὸν εἰς τὴν σιωπὴν καὶ τὴν ἄσκησιν συνέστειλε· καὶ διεπόνει τὸ σῶμα γυμνασίοις ἐνεργοῖς, ἐθιζόμενος ἀνέχεσθαι καὶ καύματα καὶ νιφετὸν ἀκαλύπτῳ κεφαλῇ, καὶ βαδίζειν ἐν ταῖς ὁδοῖς πᾶσαν ὥραν ἄτερ ὀχήματος, τῶν δὲ φίλων οἱ συνεκδημοῦντες ἵπποις ἐχρῶντο, καὶ πολλάκις ἑκάστῳ παρέβαλλεν ὁ Κάτων ἐν μέρει προσδιαλεγόμενος, περιπατῶν αὐτὸς ὀχουμένων. θαυμαστῇ δὲ καὶ περὶ τὰς νόσους ὑπομονῇ μετ’ ἐγκρατείας ἐχρῆτο· πυρέττων γὰρ μόνος ἐφ’ ἑαυτοῦ διημέρευε μηδένα προσιέμενος, ἄχρι οὗ βέβαιον αἴσθοιτο ῥᾳστώνην καὶ μεταβολὴν τοῦ νοσήματος.", "st": "Cat. Mi. 5.3"}, {"sp": "N", "t": "ἐν δὲ τοῖς δείπνοις ἐκληροῦτο περὶ τῶν μερίδων εἰ δὲ ἀπολάχοι, πρῶτον αἴρειν τῶν φίλων κελευόντων, ἔλεγε μὴ καλῶς ἔχειν, ἀκούσης τῆς Ἀφροδίτης, καὶ κατ’ ἀρχὰς μὲν ἅπαξ ἐπιπιὼν τὸ δεῖπνον ἀνέλυε, προϊόντι δὲ τῷ χρόνῳ μάλιστα προσίετο τὸ πίνειν, ὥστε πολλάκις ἐν οἴνῳ διάγειν εἰς ὄρθρον. αἰτίαν δὲ ἔλεγον οἱ φίλοι τούτου τὴν πολιτείαν καὶ τὰ δημόσια πράγματα, πρὸς οἷς ὅλας τὸν Κάτωνα τὰς ἡμέρας ὄντα, καὶ κωλυόμενον φιλολογεῖν, νύκτωρ καὶ παρὰ πότον συγγίνεσθαι τοῖς φιλοσόφοις. διὸ καὶ Μεμμίου τινὸς ἐν συλλόγῳ φήσαντος ὅλας τὸν Κάτωνα μεθύσκεσθαι τὰς νύκτας, ὑπολαβὼν ὁ Κικέρων, ἐκεῖνο δὲ οὐ λέγεις, εἶπεν, ὅτι καὶ τὰς ἡμέρας ὅλας κυβεύει;", "st": "Cat. Mi. 6.1"}, {"sp": "N", "t": "καθόλου δὲ τοῖς τότε βίοις καὶ τοῖς ἐπιτηδεύμασιν ὁ Κάτων τὴν ἐναντίαν ὁδὸν οἰόμενος δεῖν βαδίζειν, ὡς οὖσι φαύλοις καὶ μεγάλης δεομένοις μεταβολῆς, ἐπεὶ πορφύραν ἑώρα τὴν κατακόρως ἐρυθρὰν καὶ ὀξεῖαν ἀγαπωμένην, αὐτὸς ἐφόρει τὴν μέλαιναν, πολλάκις δ’ ἀνυπόδητος καὶ ἀχίτων εἰς τὸ δημόσιον προῄει μετ’ ἄριστον, οὐ δόξαν ἐκ ταύτης τῆς καινότητος θηρώμενος, ἀλλὰ ἐθίζων ἑαυτὸν ἐπὶ τοῖς αἰσχροῖς αἰσχύνεσθαι μόνοις, τῶν δὲ ἄλλων ἀδόξων καταφρονεῖν. καὶ κληρονομίαν δὲ αὐτῷ προσγενομένην ἀνεψιοῦ Κάτωνος ἑκατὸν ταλάντων εἰς ἀργύριον συναγαγών παρεῖχεν ἄνευ τόκων χρῆσθαι τῷ δεομένῳ τῶν φίλων, ἔνιοι δὲ καὶ χωρία καὶ θεράποντας αὐτοῦ διδόντος καὶ βεβαιοῦντος ὑπέθεντο πρὸς τὸ δημόσιον.", "st": "Cat. Mi. 6.3"}, {"sp": "N", "t": "ἐπεὶ δὲ ὥραν ᾤετο πρὸς γάμον ἔχειν, οὐδεμιᾷ γυναικὶ συνεληλυθώς, ἡρμόσατο Λεπίδαν, πρότερον μὲν ἐγγυηθεῖσαν Σκηπίωνι Μετέλλῳ, τότε δὲ ἀπειπαμένου τοῦ Σκηπίωνος καὶ τῆς ἐγγύης λυθείσης σχολάζουσαν. οὐ μὴν ἀλλὰ πρὸ τοῦ γάμου μεταμεληθεὶς πάλιν ὁ Σκηπίων καὶ πάντα ποιήσας ἔλαβε τὴν κόρην. ὁ δὲ Κάτων σφόδρα παροξυνθεὶς καὶ διακαείς ἐπεχείρησε μὲν ἐπεξελθεῖν διὰ δίκης, ὡς δὲ οἱ φίλοι τοῦτο ἐκώλυσαν, ὀργῇ καὶ νεότητι τρέψας ἑαυτὸν εἰς ἰάμβους πολλὰ τὸν Σκηπίωνα καθύβρισε, τῷ πικρῷ προσχρησάμενος τοῦ Ἀρχιλόχου, τὸ δὲ ἀκόλαστον ἀφεὶς καὶ παιδαριῶδες. ἔγημε δὲ Ἀτιλίαν, Σερρανοῦ θυγατέρα, καὶ ταύτῃ πρῶτον συνῆλθεν, οὐ μόνῃ δέ, καθάπερ Λαίλιος, ὁ Σκηπίωνος ἑταῖρος· ἀλλ’ εὐτυχέστερος ἐκεῖνος, ἐν πολλοῖς οἷς ἐβίωσε χρόνοις μίαν ἣν ἔγημεν ἐξ ἀρχῆς γνοὺς γυναῖκα.", "st": "Cat. Mi. 7.1"}, {"sp": "N", "t": "τοῦ δὲ δουλικοῦ πολέμου συνεστῶτος, ὃν Σπαρτάκειον ἐκάλουν, Γέλλιος μὲν ἐστρατήγει, Κάτων δὲ τῆς στρατείας μετεῖχεν ἐθελοντὴς, διὰ τὸν ἀδελφόν· ἐχιλιάρχει γὰρ ὁ ἀδελφὸς αὐτοῦ Καιπίων. καὶ χρήσασθαι μὲν εἰς ὅσον ἐβούλετο τῇ προθυμίᾳ καὶ ἀσκήσει τῆς ἀρετῆς οὐχ ὑπῆρξεν αὐτῷ, διὰ τὸ μὴ καλῶς στρατηγεῖσθαι τὸν πόλεμον ἄλλως δὲ, παρὰ πολλὴν μαλακίαν καὶ τρυφὴν τῶν ἐκεῖ στρατευομένων ἐπιδεικνύμενος εὐταξίαν καὶ ἐγκράτειαν καὶ τὸ θαρραλέον ἐν πᾶσι καὶ ξυνετόν, ἐδόκει μηθὲν ἀποδεῖν τοῦ παλαιοῦ Κάτωνος. ὁ δὲ Γέλλιος ἀριστεῖα καὶ τιμὰς αὐτῷ διαπρεπεῖς ἔγραψεν, ἃς ἐκεῖνος οὐκ ἔλαβεν οὐδὲ προσήκατο, φήσας ἄξιον μηθὲν εἰργάσθαι τιμῶν, ἔκ τε δὴ τούτων ἀλλόκοτος ἐδόκει, καὶ νόμου γραφέντος ὅπως τοῖς παραγγέλλουσιν εἰς ἀρχὴν ὀνοματολόγοι μὴ παρῶσι, χιλιαρχίαν μετιὼν μόνος ἐπείθετο τῷ νόμῳ καὶ δι’ αὑτοῦ ποιησάμενος ἔργον ἀσπάζεσθαι καὶ προσαγορεύειν τοὺς ἐντυγχάνοντας, οὐδὲ αὐτοῖς ἀνεπαχθὴς ἦν τοῖς ἐπαινοῦσιν, ὅσον μᾶλλον ἐνόουν τὸ καλὸν ὧν ἐπετήδευε, τὸ δυσμίμητον αὐτῶν βαρυνομένοις.", "st": "Cat. Mi. 8.1"}, {"sp": "N", "t": "ἀποδειχθεὶς δὲ χιλίαρχος εἰς Μακεδονίαν ἐπέμπετο πρὸς Ῥούβριον τὸν στρατηγόν. ἔνθα δὴ λέγεται τῆς γυναικὸς ἀχθομένης καὶ δακρυούσης ἕνα τῶν φίλων τοῦ Κάτωνος Μουνάτιον εἰπεῖν· ὦ Ἀτιλία, θάρσει· τοῦτον ἐγώ σοι φυλάξω. πάνυ μὲν οὖν, φάναι τὸν Κάτωνα, καὶ προελθόντων μιᾶς ἡμέρας ὁδόν, εὐθὺς εἰπεῖν μετὰ τὸ δεῖπνον ἄγε, ὅπως, ὦ Μουνάτιε, τῇ Ἀτιλίᾳ τὴν ὑπόσχεσιν ἐμπεδώσεις, μήτε ἡμέρας ἐμοῦ μήτε νυκτὸς ἀφιστάμενος. ἐκ δὲ τούτου δύο κλίνας εἰς ταὐτὸ δωμάτιον ἐκέλευε τίθεσθαι, καὶ τὸν Μουνάτιον οὕτως ἀεὶ καθεύδειν μετὰ παιδιᾶς φυλασσόμενον ὑπὸ τοῦ Κάτωνος.", "st": "Cat. Mi. 9.1"}, {"sp": "N", "t": "εἵποντο δὲ αὐτῷ πεντεκαίδεκα μὲν οἰκέται, δύο δὲ ἀπελεύθεροι, φίλοι δὲ τέσσαρες, ὧν ὀχουμένων ἵπποις αὐτὸς ἀεὶ περιπατῶν ἑκάστῳ παρέβαλλεν ἐν μέρει προσδιαλεγόμενος. ἐπεὶ δὲ ἧκεν εἰς τὸ στρατόπεδον, πλειόνων ταγμάτων ὄντων, ἑνὸς ἄρχων ἀποδειχθεὶς ὑπὸ τοῦ στρατηγοῦ, τῆς μὲν ἰδίας ἀρετῆς, μιᾶς οὔσης, μικρὸν ἔργον ἡγεῖτο καὶ οὐκ ἀνύσιμον τὴν ἐπίδειξιν, αὑτῷ δὲ ποιῆσαι τοὺς ἀρχομένους ὁμοίους μάλιστα φιλοτιμούμενος οὐ τὸν φόβον ἀφεῖλε τῆς ἐξουσίας, ἀλλὰ προσέθηκε τὸν λόγον ᾧ πείθων περὶ ἑκάστου καὶ διδάσκων, ἑπομένης τιμῆς καὶ κολάσεως, χαλεπὸν ἦν εἰπεῖν πότερον εἰρηνικοὺς μᾶλλον ἢ πολεμικούς καὶ προθυμοτέρους ἢ δικαιοτέρους παρεσκεύασε τοὺς ἄνδρας· οὕτως ἐφαίνοντο φοβεροὶ μὲν τοῖς πολεμίοις, ἥμεροι δὲ τοῖς συμμάχοις, ἄτολμοι δὲ πρὸς τὸ ἀδικεῖν, φιλότιμοι δὲ πρὸς τοὺς ἐπαίνους. οὗ δὲ ἥκιστα Κάτων ἐπεμελήθη, τοῦτο πλεῖστον ὑπῆρχεν αὐτῷ, καὶ δόξα καὶ χάρις καὶ ὑπερβάλλουσα τιμὴ καὶ φιλοφροσύνη παρὰ τῶν στρατιωτῶν, ἃ γὰρ ἑτέροις ἐπέταττεν ἑκουσίως διαπονῶν, καὶ στολὴν μὲν καὶ δίαιταν καὶ πορείαν ἐκείνοις μᾶλλον ἢ τοῖς ἄρχουσιν ὁμοιούμενος, ἤθει δὲ καὶ φρονήματι καὶ λόγῳ πάντας ὑπεραίρων τοὺς αὐτοκράτορας καὶ στρατηγοὺς προσαγορευομένους, ἔλαθε διὰ τούτων ἅμα τὴν πρὸς αὑτὸν εὔνοιαν ἐνεργασάμενος τοῖς ἀνδράσιν. ἀρετῆς γὰρ ἀληθινὸς οὐκ ἐγγίνεται ζῆλος ἢ δι’ ἄκρας τοῦ παραδιδόντος εὐνοίας καὶ τιμῆς· οἱ δὲ ἄνευ τοῦ φιλεῖν ἐπαινοῦντες τοὺς ἀγαθοὺς αἰδοῦνται τὴν δόξαν αὐτῶν, οὐ θαυμάζουσι δὲ τὴν ἀρετὴν οὐδὲ μιμοῦνται.", "st": "Cat. Mi. 9.3"}, {"sp": "N", "t": "πυθόμενος δὲ Ἀθηνόδωρον, τὸν ἐπικαλούμενον Κορδυλίωνα, μεγάλην ἕξιν ἐν τοῖς Στωϊκοῖς λόγοις ἔχοντα, διατρίβειν περὶ Πέργαμον, ἤδη γηραιὸν ὄντα καὶ πάσαις ἐρρωμενέστατα ταῖς ἡγεμονικαῖς καὶ βασιλικαῖς συνηθείαις καὶ φιλίαις διαμεμαχημένον, οὐδὲν ᾤετο πέμπων καὶ γράφων περαίνειν πρὸς αὐτόν, ἀλλὰ ἔχων παρὰ τοῦ νόμου δεδομένην ἀποδημίαν δυεῖν μηνῶν ἔπλευσεν εἰς τὴν Ἀσίαν ἐπὶ τὸν ἄνδρα, πιστεύων τοῖς ἐν αὑτῷ καλοῖς μὴ ἀτυχήσειν τῆς ἄγρας. συγγενόμενος δὲ καὶ καταγωνισάμενος καὶ μεταστήσας ἐκ τῆς προαιρέσεως αὐτόν ἧκεν ἄγων εἰς τὸ στρατόπεδον, περιχαρὴς καὶ μεγαλοφρονῶν, ὥς τι κάλλιστον ᾑρηκὼς καὶ λαμπρότερον ὧν Πομπήϊος τότε καὶ Λεύκολλος ἐθνῶν καὶ βασιλειῶν κατεστρέφοντο σὺν ὅπλοις περιϊόντες.", "st": "Cat. Mi. 10.1"}, {"sp": "N", "t": "ἔτι δὲ αὐτοῦ περὶ τὴν στρατείαν ὄντος ὁ ἀδελφὸς εἰς τὴν Ἀσίαν βαδίζων ἐνόσησε περὶ Θρᾴκην ἐν Αἴνῳ. καὶ γράμματα μὲν εὐθὺς ἧκε πρὸς τὸν Κάτωνα· χειμῶνος δὲ πολλοῦ κατέχοντος τὴν θάλατταν καὶ νεὼς ἱκανῆς μεγέθει μὴ παρούσης, εἰς μικρὰν ὁλκάδα μόνον δύο φίλους καὶ τρεῖς οἰκέτας ἀναλαβὼν ἐκ Θεσσαλονίκης ἀνήχθη· καὶ παρ’ οὐδὲν ἐλθὼν καταποντωθῆναι, τύχῃ τινὶ παραλόγῳ σωθεὶς ἄρτι τεθνηκότος τοῦ Καιπίωνος, ἐμπαθέστερον ἔδοξεν ἢ φιλοσοφώτερον ἐνεγκεῖν τὴν συμφοράν, οὐ μόνον κλαυθμοῖς καὶ περιπτύξεσι τοῦ νεκροῦ καὶ βαρύτητι λύπης, ἀλλὰ καὶ δαπάνῃ περὶ τὴν ταφὴν καὶ πραγματείαις θυμιαμάτων καὶ ἱματίων πολυτελῶν συγκατακαέντων καὶ μνήματος ξεστοῦ λίθων Θασίων ἀπὸ ταλάντων ὀκτὼ κατασκευασθέντος ἐν τῇ Αἰνίων ἀγορᾷ. ταῦτα γὰρ ἔνιοι ἐσυκοφάντουν πρὸς τὴν ἄλλην ἀτυφίαν τοῦ Κάτωνος, οὐ καθορῶντες ὅσον ἐν τῷ πρὸς ἡδονὰς καὶ φόβους καὶ δεήσεις ἀναισχύντους ἀγνάμπτῳ καὶ στερρῷ τοῦ ἀνδρὸς τὸ ἥμερον ἐνῆν καὶ φιλόστοργον. εἰς δὲ ταῦτα καὶ πόλεις αὐτῷ καὶ δυνάσται πολλὰ κατὰ τιμὴν τοῦ τεθνεῶτος ἔπεμπον, ὧν ἐκεῖνος χρήματα μὲν παρ’ οὐδενὸς ἐδέξατο, θυμιάματα δὲ καὶ κόσμον ἐλάμβανε, τὴν τιμὴν ἀποδιδοὺς τοῖς πέμπουσι. τῆς δὲ κληρονομίας εἰς αὐτόν τε καὶ θυγάτριον τοῦ Καιπίωνος ἡκούσης, οὐθὲν ὧν ἀνάλωσε περὶ τὸν τάφον ἀπῄτησεν ἐν τῇ νεμήσει. καὶ ταῦτα πράξαντος αὐτοῦ καὶ πράττοντος, ἦν ὁ γράψας ὅτι κοσκίνῳ τὴν τέφραν τοῦ νεκροῦ μετέβαλε καὶ διήθησε, χρυσίον ζητῶν κατακεκαυμένον. οὕτως οὐ τῷ ξίφει μόνον, ἀλλὰ καὶ τῷ γραφείῳ τὸ ἀνυπεύθυνον καὶ τὸ ἀνυπόδικον ἐπίστευσεν.", "st": "Cat. Mi. 11.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τέλος εἶχεν ἡ στρατεία τῷ Κάτωνι, προεπέμφθη, οὐκ εὐχαῖς, ὃ κοινόν ἐστιν, οὐδ’ ἐπαίνοις, ἀλλὰ δάκρυσι καὶ περιβολαῖς ἀπλήστοις, ὑποτιθέντων τὰ ἱμάτια τοῖς ποσὶν ᾗ βαδίζοι καὶ καταφιλούντων τὰς χεῖρας, ἃ τῶν αὐτοκρατόρων ὀλίγοις μόλις ἐποίουν οἱ τότε Ῥωμαῖοι. βουληθεὶς δὲ πρὸ τοῦ πολιτείᾳ προσελθεῖν ἅμα μὲν πλανηθῆναι καθ’ ἱστορίαν τῆς Ἀσίας καὶ γενέσθαι θεατὴς ἠθῶν καὶ βίων καὶ δυνάμεως τῆς περὶ ἑκάστην ἐπαρχίαν, ἅμα δὲ τῷ Γαλάτῃ Δηϊοτάρῳ διὰ ξενίαν καὶ φιλίαν πατρῴαν δεομένῳ πρὸς αὐτὸν ἐλθεῖν μὴ ἀχαριστῆσαι, τοῦτον τὸν τρόπον ἐποιεῖτο τὴν ἀποδημίαν. προὔπεμπεν ἅμ’ ἡμέρᾳ τὸν ἀρτοποιὸν καὶ τὸν μάγειρον ὅπου καταλύσειν ἔμελλεν. οἱ δὲ πάνυ κοσμίως καὶ μεθ’ ἡσυχίας εἰσελθόντες ἂν εἰς τὴν πόλιν, εἰ μηδεὶς τύχοι τῷ Κάτωνι φίλος ὢν αὐτόθι πατρῷος ἢ γνώριμος, ἐν πανδοκείῳ τὴν ὑποδοχὴν αὐτῷ παρεσκεύαζον, ἐνοχλοῦντες οὐδενί· πανδοκείου δὲ μὴ ὄντος, οὕτως πρὶς τοὺς ἄρχοντας τραπόμενοι ξενίαν ἐλάμβανον, ἀγαπῶντες τὴν δοθεῖσαν. πολλάκις δὲ ἀπιστούμενοι καὶ περιορώμενοι διὰ τὸ μὴ θορύβῳ μηδὲ ἀπειλῇ ταῦτα πράσσειν πρὸς τοὺς ἄρχοντας, ὑπὸ τοῦ Κάτωνος ἄπρακτοι κατελαμβάνοντο, καὶ μᾶλλον αὐτὸς ὀφθεὶς ὠλιγωρεῖτο, καὶ παρεῖχεν ἐπὶ τῶν φορτίων σιωπῇ καθεζόμενος ὑπόνοιαν ἀνθρώπου ταπεινοῦ καὶ περιδεοῦς. οὐ μὴν ἀλλὰ καὶ προσκαλούμενος αὐτοὺς εἰώθει λέγειν ὦ μοχθηροί, μεταβάλεσθε ταύτης τῆς κακοξενίας. οὐ πάντες ὑμῖν ἀφίξονται Κάτωνες. ἀμβλύνατε ταῖς φιλοφροσύναις τὴν ἐξουσίαν τῶν δεομένων προφάσεως, ἵνα βίᾳ, λαμβάνωσιν, ὡς παρ’ ἑκόντων μὴ τυγχάνοντες.", "st": "Cat. Mi. 12.1"}, {"sp": "N", "t": "ἐν δὲ Συρίᾳ καὶ γελοῖόν τι λέγεται παθεῖν. βαδίζων γὰρ εἰς Ἀντιόχειαν εἶδε περὶ τὰς πύλας ἔξω πλῆθος ἀνθρώπων ἑκατέρωθεν τῆς ὁδοῦ παρακεκριμένων, ἐν οἷς ἔφηβοι μὲν χωρὶς ἐν χλαμύσι καὶ παῖδες ἑτέρωθεν κοσμίως εἱστήκεσαν, ἐσθῆτας δὲ καθαρὰς ἔνιοι καὶ στεφάνους εἶχον, ἱερεῖς θεῶν ὄντες ἢ ἄρχοντες, πάντων οὖν μᾶλλον οἰηθεὶς ὁ Κάτων αὐτῷ τινα πράττεσθαι τιμὴν καὶ δεξίωσιν ὑπὸ τῆς πόλεως, ὠργίζετο μὲν τοῖς προπεμφθεῖσι τῶν ἰδίων, ὡς μὴ κωλύσασιν, ἐκέλευσε δὲ καταβῆναι τοὺς φίλους, καὶ πεζῇ προῄει μετ’ αὐτῶν. ὡς δ’ ἐγγὺς ἦσαν, ὁ πάντα διακοσμῶν ἐκεῖνα καὶ τὸν ὄχλον εἰς τάξιν καθιστάς, ἀνὴρ πρεσβύτερος ἤδη, ῥάβδον ἐν τῇ χειρὶ καὶ στέφανον κρατῶν, ἀπήντησε τῷ Κάτωνι πρὸ τῶν ἄλλων, καὶ μηδὲ ἀσπασάμενος ἠρώτα ποῦ Δημήτριον ἀπολελοίπασι καὶ πηνίκα παρέσται. Πομπηΐου δὲ ἦν γεγονὼς ὁ Δημήτριος οἰκέτης· τότε δὲ πάντων, ὡς ἔπος εἰπεῖν, ἀνθρώπων εἰς Πομπήϊον ἀποβλεπόντων, ἐθεραπεύετο παρ’ ἀξίαν, μέγα παρ’ αὐτῷ δυνάμενος. τοῖς μὲν οὖν φίλοις τοῦ Κάτωνος γέλως ἐνέπεσε τοσοῦτος ὥστε ἀναλαβεῖν ἑαυτοὺς οὐκ ἐδύναντο διὰ τοῦ πλήθους ἅμα βαδίζοντες, ὁ δὲ Κάτων τότε μὲν ἰσχυρῶς διατραπείς, ὦ τῆς κακοδαίμονος, ἔφη, πόλεως, ἄλλο δὲ οὐδὲν ἐφθέγξατο, χρόνῳ δὲ ὕστερον εἰώθει γελᾶν καὶ αὐτὸς ἐπὶ τούτῳ, καὶ διηγούμενος καὶ μνημονεύων.", "st": "Cat. Mi. 13.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ Πομπήϊος αὐτὸς ἐπέστρεψε τοὺς ἀνθρώπους οὕτω πλημμελοῦντας εἰς τὸν Κάτωνα δι’ ἄγνοιαν. ὡς γὰρ εἰς Ἔφεσον ἐλθὼν ἐπορεύετο πρὸς αὐτόν ἀσπασόμενος πρεσβύτερον ὄντα, καὶ δόξῃ πολὺ προήκοντα, καὶ δυνάμεων τότε μεγίστων ἡγούμενον, ἰδὼν ὁ Πομπήϊος οὐκ ἔμεινεν, οὐδὲ εἴασε καθεζομένῳ προσελθεῖν, ἀλλ’ ὥς τινι τῶν κρειττόνων ἀναθορὼν ἀπήντησε, καὶ τὴν δεξιὰν ἐνέβαλε. καὶ πολλὰ μὲν εὐθὺς ἐν τῷ φιλοφρονεῖσθαι καὶ ἀσπάζεσθαι παρόντα, πλείω δὲ ἔτι μεταστάντος ἐγκώμια διῆλθεν αὐτοῦ τῆς ἀρετῆς, ὥστε πάντας ἐπιστρεφομένους καὶ προσέχοντας ἤδη τῷ Κάτωνι, θαυμάζειν ἐξ ὧν πρότερον κατεφρονεῖτο, καὶ πρᾳότητα καὶ μεγαλοψυχίαν ἀναθεωρεῖν. καὶ γὰρ ἡ Πομπηΐου σπουδὴ περὶ αὐτόν οὐκ ἐλάνθανε θεραπεύοντος οὖσα μᾶλλον ἢ φιλοῦντος, ἀλλ’ ἔγνωσαν ὅτι θαυμάζει μὲν παρόντα, χαίρει δὲ ἀπερχομένῳ. τοὺς γὰρ ἄλλους νέους, ὅσοι παρ’ αὐτόν ἀφικνοῦντο, φιλοτιμούμενος κατεῖχε καὶ ποθῶν αὐτῷ συνεῖναι, τοῦ δὲ Κάτωνος οὐδὲν ἐδεήθη τοιοῦτον, ἀλλ’ ὥσπερ οὐκ ἀνυπεύθυνος ἄρχων ἐκείνου παρόντος ἐξέπεμψεν ἄσμενος, μόνῳ σχεδὸν ἐκείνῳ τῶν εἰς Ῥώμην πλεόντων τὰ τέκνα καὶ τὴν γυναῖκα παρακαταθέμενος, ἄλλως αὐτῷ προσήκοντα καὶ διὰ συγγένειαν.", "st": "Cat. Mi. 14.1"}, {"sp": "N", "t": "ἐκ τούτου δόξα καὶ σπουδὴ καὶ ἅμιλλα περὶ αὐτὸν ἦν τῶν πόλεων καὶ δεῖπνα καὶ κλήσεις, ἐν οἷς τοὺς φίλους ἐκέλευε προσέχειν αὐτῷ, μὴ λάθῃ βεβαιώσας τὸν Κουρίωνος λόγον. ὁ γὰρ Κουρίων ἀχθόμενος τῷ αὐστηρῷ τοῦ Κάτωνος, φίλου καὶ συνήθους ὄντος, ἠρώτησεν αὐτόν εἰ πρόθυμός ἐστι μετὰ τὴν στρατείαν γενέσθαι τῆς Ἀσίας θεατής, τοῦ δὲ καὶ πάνυ φήσαντος, εὖ λέγεις, εἶπεν ὁ Κουρίων, ἡδίων γὰρ ἐπανήξεις ἐκεῖθεν καὶ μᾶλλον ἥμερος οὕτω πως καὶ τῷ ῥήματι χρησάμενος.", "st": "Cat. Mi. 14.4"}, {"sp": "N", "t": "Δηϊόταρος δὲ ὁ Γαλάτης μετεπέμψατο μὲν τὸν Κάτωνα πρεσβύτερος ὢν ἤδη παραθέσθαι τοὺς παῖδας αὐτῷ βουλόμενος καὶ τὸν οἶκον, ἐλθόντι δὲ προσφέρων δῶρα παντοδαπὰ καὶ πειρῶν καὶ δεόμενος πάντα τρόπον οὕτω παρώξυνεν ὥστε, δείλης ἐλθόντα καὶ νυκτερεύσαντα, τῇ ὑστεραίᾳ περὶ τρίτην ὥραν ἀπᾶραι. προελθὼν μέντοι μιᾶς ἡμέρας ὁδόν εὗρεν ἐν Πεσσινοῦντι πλείονα τῶν ἐκεῖ δώρων αὖθις αὐτὸν ὑπομένοντα, καὶ γράμματα τοῦ Γαλάτου δεομένου, λαβεῖν αὐτὸς εἰ μὴ πρόθυμός ἐστιν, ἀλλὰ τοὺς φίλους ἐᾶσαι, πάντως μὲν ἀξίους ὄντας εὖ παθεῖν δι’ ἐκεῖνον οὐκ ὄντων δὲ τῶν ἰδίων τοῦ Κάτωνος τοσούτων. ἀλλ’ οὐδὲ τούτοις ἐνέδωκεν ὁ Κάτων, καίπερ ἐνίους τῶν φίλων μαλασσομένους καὶ ὑπομεμφομένους ὁρῶν, ἀλλὰ φήσας ὅτι πᾶσα δωροδοκία προφάσεως ἂν εὐπορήσειεν, οἱ δὲ φίλοι μεθέξουσιν ὧν ἂν ἔχῃ καλῶς καὶ δικαίως κτησάμενος, ἀπέπεμψε τὰ δῶρα πρὸς τὸν Δηϊόταρον.", "st": "Cat. Mi. 15.1"}, {"sp": "N", "t": "ἐπεὶ δὲ μέλλοντος ἀπαίρειν εἰς τὸ Βρεντέσιον ᾤοντο δεῖν οἱ φίλοι τὰ λείψανα τοῦ Καιπίωνος εἰς ἕτερον θέσθαι πλοῖον, εἰπὼν ὅτι τῆς ψυχῆς μεθήσεται μᾶλλον ἢ τούτων, ἀνήχθη. καὶ μέντοι λέγεται κατὰ τύχην ἐπισφαλέστατα περᾶσαι, τῶν ἄλλων μετρίως κομιζομένων.", "st": "Cat. Mi. 15.4"}, {"sp": "N", "t": "ἐπανελθὼν δὲ εἰς Ῥώμην τὸν μὲν ἄλλον χρόνον κατ’ οἶκον Ἀθηνοδώρῳ συνών, ἢ κατ’ ἀγορὰν τοῖς φίλοις παριστάμενος διετέλεσεν. ἐπιβάλλουσαν δὲ αὐτῷ τὴν ταμιευτικὴν ἀρχὴν οὐ πρότερον μετῆλθεν ἢ τούς τε νόμους ἀναγνῶναι τοὺς ταμιευτικοὺς καὶ διαπυθέσθαι τῶν ἐμπείρων ἕκαστα καὶ τύπῳ τινὶ τῆς ἀρχῆς τὴν δύναμιν περιλαβεῖν. ὅθεν εὐθὺς εἰς τὴν ἀρχὴν καταστάς μεγάλην ἐποίησε μεταβολὴν τῶν περὶ τὸ ταμιεῖον ὑπηρετῶν καὶ γραμματέων, οἳ διὰ χειρὸς ἀεὶ τὰ δημόσια γράμματα καὶ τοὺς νόμους ἔχοντες, εἶτα νέους ἄρχοντας παραλαμβάνοντες δι’ ἀπειρίαν καὶ ἄγνοιαν ἀτεχνῶς διδασκάλων ἑτέρων καὶ παιδαγωγῶν δεομένους, οὐχ ὑφίεντο τῆς ἐξουσίας ἐκείνοις, ἀλλὰ ἦσαν ἄρχοντες αὐτοί, μέχρι οὗ Κάτων ἐπιστὰς τοῖς πράγμασι νεανικῶς, οὐκ ὄνομα καὶ τιμὴν ἔχων ἄρχοντος, ἀλλὰ καὶ νοῦν καὶ φρόνημα καὶ λόγον, ὑπηρέταις, ὅπερ ἦσαν, ἠξίου χρῆσθαι τοῖς γραμματεῦσι, τὰ μὲν ἐξελέγχων κακουργοῦντας αὐτούς, τὰ δὲ ἁμαρτάνοντας ἀπειρίᾳ διδάσκων, ὡς δὲ ἦσαν ἰταμοὶ καὶ τοὺς ἄλλους ἐθώπευον ὑποτρέχοντες, ἐκείνῳ δὲ ἐπολέμουν, τὸν μὲν πρῶτον αὐτῶν καταγνοὺς περὶ πίστιν ἐν κληρονομίᾳ γεγονέναι πονηρόν ἀπήλασε τοῦ ταμιείου, δευτέρῳ δέ τινὶ ῥᾳδιουργίας προὔθηκε κρίσιν. ᾧ Κάτλος Λουτάτιος ὁ τιμητὴς ἀνέβη βοηθήσων, ἀνὴρ μέγα τὸ τῆς ἀρχῆς ἔχων ἀξίωμα, τὸ δὲ τῆς ἀρετῆς ἔχων μέγιστον, ὡς πάντων δικαιοσύνῃ καὶ σωφροσύνῃ Ῥωμαίων διαφέρων ἦν δὲ καὶ τοῦ Κάτωνος ἐπαινέτης καὶ συνήθης διὰ τὸν βίον. ὡς οὖν ἡττώμενος τοῖς δικαίοις ἐξῃτεῖτο φανερῶς τὸν ἄνθρωπον, οὐκ εἴα ταῦτα ποιεῖν αὐτὸν ὁ Κάτων. ἔτι δὲ μᾶλλον προσλιπαροῦντος, αἰσχρόν, εἶπεν, ὦ Κάτλε, σὲ τὸν τιμητὴν καὶ τοὺς ἡμετέρους βίους ὀφείλοντα δοκιμάζειν ὑπὸ τῶν ἡμετέρων ὑπηρετῶν ἐκβάλλεσθαι. ταύτην τὴν φωνὴν ἀφέντος τοῦ Κάτωνος, ὁ Κάτλος προσέβλεψε μὲν αὐτὸν ὡς ἀμειψόμενος, εἶπε δὲ οὐδέν, ἀλλ’,’ εἴτε ὑπ’ ὀργῆς εἴτε ὑπ’ αἰσχύνης ἀπῆλθε σιωπῇ διηπορημένος. οὐ μὴν ἥλω γε ὁ ἄνθρωπος, ἀλλ’ ἐπεὶ μιᾷ ψήφῳ τὰς ἀφιείσας ὑπερέβαλλον αἱ καθαιροῦσαι καὶ Λόλλιος Μᾶρκος εἷς, συνάρχων τοῦ Κάτωνος, ὑπὸ ἀσθενείας ἀπελέλειπτο τῆς δίκης, πέμπει πρὸς τοῦτον ὁ Κάτλος δεόμενος βοηθῆσαι τῷ ἀνθρώπῳ· κἀκεῖνος ἐν φορείῳ κομισθεὶς μετὰ τὴν δίκην ἔθετο τὴν ἀπολύουσαν. οὐ μὴν ἐχρήσατό γε τῷ γραμματεῖ ὁ Κάτων, οὐδὲ τὸν μισθὸν ἀπέδωκεν, οὐδὲ ὅλως ἐνάριθμον τοῦ Λολλίου τὴν ψῆφον ἔσχεν.", "st": "Cat. Mi. 16.1"}, {"sp": "N", "t": "οὕτω δὲ τοὺς γραμματεῖς ταπεινώσας καὶ ποιήσας ὑποχειρίους, καὶ τοῖς πράγμασιν ὡς αὐτὸς ἐβούλετο χρώμενος, ὀλίγῳ χρόνῳ τὸ ταμιεῖον ἀπέδειξε τοῦ βουλευτηρίου σεμνότερον, ὡς καὶ λέγειν καὶ φρονεῖν ἅπαντας ὅτι Κάτων ὑπατείας ἀξίωμα τῇ ταμιείᾳ περιέθηκε. πρῶτον μὲν γὰρ εὑρὼν χρέα παλαιὰ τῷ δημοσίῳ πολλοὺς ὀφείλοντας καὶ πολλοῖς τὸ δημόσιον, ἅμα τὴν πόλιν ἔπαυσεν ἀδικουμένην καὶ ἀδικοῦσαν, τοὺς μὲν εὐτόνως καὶ ἀπαραιτήτως ἀπαιτῶν, τοῖς δὲ ταχέως ἀποδιδοὺς καὶ προθύμως, ὥστε τὸν δῆμον ἥδεσθαι τοὺς μὲν οἰομένους ἀποστερήσειν ἐκτίνοντας ὁρῶντα, τοὺς δὲ ἃ μὴ προσεδόκων ἀπολαμβάνοντας. ἔπειτα γράμματα πολλῶν οὐ προσηκόντως ἀναφερόντων, καὶ δόγματα ψευδῆ παραδέχεσθαι χάριτι καὶ δεήσει τῶν προτέρων εἰωθότων, οὐδὲν αὐτὸν ἔλαθε γινόμενον τοιοῦτον, ἀλλ’ ὑπὲρ ἑνός ποτε δόγματος ἐνδοιάσας εἰ κύριον γέγονε, πολλῶν μαρτυρούντων οὐκ ἐπίστευσεν, οὐδὲ κατέταξε πρότερον ἢ τοὺς ὑπάτους ἐπομόσαι παραγενομένους. ὄντων δὲ πολλῶν οἷς Σύλλας ἐκεῖνος ἀποκτείνασιν ἄνδρας ἐκ προγραφῆς γέρας ἔδωκεν ἀνὰ μυρίας δισχιλίας δραχμάς, ἅπαντες μὲν αὐτοὺς ὡς ἐναγεῖς καὶ μιαροὺς ἐμίσουν, ἀμύνασθαι δὲ οὐδεὶς ἐτόλμα, Κάτων δὲ προσκαλούμενος ἕκαστον ἔχοντα δημόσιον ἀργύριον ἀδίκως ἐξέπραττεν, ἅμα θυμῷ καὶ λόγῳ τὸ τῆς πράξεως ἀνόσιον καὶ παράνομον ἐξονειδίζων. οἱ δὲ τοῦτο παθόντες εὐθὺς ἦσαν ἔνοχοι φόνῳ, καὶ τρόπον τινὰ προηλωκότες ἀπήγοντο πρὸς τοὺς δικαστὰς καὶ δίκας ἔτινον, ἡδομένων πάντων καὶ νομιζόντων συνεξαλείφεσθαι τὴν τότε τυραννίδα καὶ Σύλλαν αὐτὸν ἐφορᾶν κολαζόμενον.", "st": "Cat. Mi. 17.1"}, {"sp": "N", "t": "ἥιρει δὲ τοὺς πολλοὺς καὶ τὸ ἐνδελεχὲς αὐτοῦ τῆς ἐπιμελείας καὶ ἄτρυτον, οὔτε γὰρ πρότερός τις ἀνέβη τῶν συναρχόντων εἰς τὸ ταμιεῖον Κάτωνος οὔτε ὕστερος ἀπῆλθεν, ἐκκλησίαν δὲ καὶ βουλὴν οὐδεμίαν παρῆκε, δεδιὼς καὶ παραφυλάττων τοὺς ἑτοίμως καὶ πρὸς χάριν ὀφλημάτων καὶ τελῶν ἀνέσεις ἢ δόσεις οἷς ἔτυχεν ἐπιψηφιζομένους. ἐπιδεικνύμενος δὲ τὸ ταμιεῖον ἄβατόν τε καὶ καθαρὸν συκοφαντῶν, πλῆρες δὲ χρημάτων, ἐδίδασκεν ὅτι τῇ πόλει πλουτεῖν ἔξεστι μὴ ἀδικούσῃ. κατ’ ἀρχὰς δὲ τῶν συναρχόντων ἐνίοις ἐπαχθὴς καὶ χαλεπὸς φανείς ὕστερον ἠγαπᾶτο, ταῖς ἐκ τοῦ μὴ χαρίζεσθαι τὰ δημόσια μηδὲ κρίνειν κακῶς ἀπεχθείαις ὑποτιθεὶς ἑαυτὸν ἀντὶ πάντων, καὶ παρέχων ἀπολογεῖσθαι πρὸς τοὺς δεομένους καὶ βιαζομένους ἐκείνους, ὡς ἀμήχανόν ἐστιν, ἄκοντος Κάτωνος.", "st": "Cat. Mi. 18.1"}, {"sp": "N", "t": "τῶν δὲ ἡμερῶν τῇ τελευταίᾳ σχεδὸν ὑπὸ πάντων τῶν πολιτῶν προπεμφθεὶς εἰς οἶκον, ἤκουσεν ὅτι Μαρκέλλῳ πολλοὶ συνήθεις καὶ δυνατοὶ προσπεσόντες ἐν τῷ ταμιείῳ καὶ περιέχοντες ἐκβιάζονται γράψαι τινὰ δόσιν χρημάτων ὀφειλομένων, ἦν δὲ ὁ Μάρκελλος ἐκ παίδων φίλος τῷ Κάτωνι, καὶ σὺν ἐκείνῳ βέλτιστος ἄρχων, αὐτὸς δὲ καθ’ αὑτὸν ἀγώγιμος ὑπ’ αἰδοῦς τοῖς δεομένοις, καὶ κατάντης πρὸς πᾶσαν χάριν. εὐθὺς οὖν ὁ Κάτων ἐπιστρέψας καὶ τὸν Μάρκελλον εὑρὼν ἐκβεβιασμένον γράψαι τὴν δόσιν, ᾔτησε τὰς δέλτους καὶ ἀπήλειψεν, αὐτοῦ παρεστῶτος σιωπῇ· καὶ τοῦτο πράξας κατήγαγεν αὑτὸν ἐκ τοῦ ταμιείου καὶ κατέστησεν εἰς οἶκον, οὔτε τότε μεμψάμενον οὔτε ὕστερον, ἀλλ’ ἐμμείναντα τῇ συνηθείᾳ καὶ φιλίᾳ μέχρι παντός.", "st": "Cat. Mi. 18.3"}, {"sp": "N", "t": "οὐ μὴν οὐδὲ ἀπαλλαγεὶς τῆς ταμιείας ἀφῆκε τῆς φρουρᾶς ἔρημον τὸ ταμιεῖον, ἀλλ’ οἰκέται μὲν αὐτοῦ καθ’ ἡμέραν ἀπογραφόμενοι τὰς διοικήσεις παρῆσαν, αὐτὸς δὲ βιβλία λόγους περιέχοντα δημοσίων οἰκονομιῶν ἀπὸ τῶν Σύλλα χρόνων εἰς τὴν ἑαυτοῦ ταμιείαν ὠνησάμενος πέντε ταλάντων ἀεὶ διὰ χειρὸς εἶχεν.", "st": "Cat. Mi. 18.5"}, {"sp": "N", "t": "εἰς δὲ σύγκλητον εἰσῄει τε πρῶτος καὶ τελευταῖος ἀπηλλάττετο· πολλάκις δὲ τῶν ἄλλων σχολῇ συναγομένων καθεζόμενος ἀνεγίνωσκεν ἡσυχῇ, τὸ ἱμάτιον τοῦ βιβλίου προϊσχόμενος. ἀπεδήμησε δὲ οὐδέποτε βουλῆς γενομένης, ἐπεὶ δὲ ὕστερον οἱ περὶ Πομπήϊον ἑώρων αὐτὸν ἐν οἷς ἐσπούδαζον ἀδίκως ἀμετάπειστον καὶ δυσεκβίαστον ἀεί, διεμηχανῶντο φιλικαῖς τισι συνηγορίαις ἢ διαίταις ἢ πραγματείαις ἔξω περισπᾶν. συνεὶς οὖν ταχὺ τὴν ἐπιβουλὴν ἀπεῖπε πᾶσι καὶ παρετάξατο βουλῆς ἀγομένης μηδὲν ἄλλο πράττειν. οὔτε γὰρ δόξης χάριν οὔτε πλεονεξίας οὔτε αὐτομάτως καὶ κατὰ τύχην, ὥσπερ ἕτεροί τινες, ἐμπεσὼν εἰς τὸ πράττειν τὰ τῆς πόλεως, ἀλλ’ ὡς ἴδιον ἔργον ἀνδρὸς ἀγαθοῦ τὴν πολιτείαν ἑλόμενος, μᾶλλον ᾤετο δεῖν προσέχειν τοῖς κοινοῖς ἢ τῷ κηρίῳ τὴν μέλιτταν, ὅς γε καὶ τὰ τῶν ἐπαρχιῶν πράγματα καὶ δόγματα καὶ κρίσεις καὶ πράξεις τὰς μεγίστας ἔργον πεποίητο διὰ τῶν ἑκασταχόθι ξένων καὶ φίλων πέμπεσθαι πρὸς αὐτόν.", "st": "Cat. Mi. 19.1"}, {"sp": "N", "t": "ἐνστὰς δέ ποτε Κλωδίῳ τῷ δημαγωγῷ κινοῦντι καὶ ταράττοντι μεγάλων ἀρχὰς νεωτερισμῶν καὶ διαβάλλοντι πρὸς τὸν δῆμον ἱερεῖς καὶ ἱερείας, ἐν οἷς καὶ Φαβία Τερεντίας ἀδελφὴ, τῆς Κικέρωνος γυναικὸς, ἐκινδύνευσε, τὸν μὲν Κλώδιον αἰσχύνῃ περιβαλὼν ἠνάγκασεν ὑπεκστῆναι τῆς πόλεως, τοῦ δὲ Κικέρωνος εὐχαριστοῦντος, τῇ πόλει δεῖν ἔχειν ἔφη χάριν αὐτόν, ὡς ἐκείνης ἕνεκα πάντα ποιῶν καὶ πολιτευόμενος. ἐκ τούτου μεγάλη δόξα περὶ αὐτὸν ἦν, ὥστε ῥήτορα μὲν, δίκῃ τινὶ μαρτυρίας μιᾶς φερομένης, εἰπεῖν πρὸς τοὺς δικαστάς ὡς ἑνὶ μαρτυροῦντι προσέχειν, οὐδὲ Κάτωνι, καλῶς ἔχει, πολλοὺς δὲ ἤδη περὶ τῶν ἀπίστων καὶ παραδόξων, ὥσπερ ἐν παροιμίᾳ τινὶ, λέγειν ὅτι τοῦτο μὲν οὐδὲ Κάτωνος λέγοντος πιθανόν ἐστι. μοχθηροῦ δὲ ἀνθρώπου καὶ πολυτελοῦς λόγον ἐν συγκλήτῳ διαθεμένου πρὸς εὐτέλειαν καὶ σωφρονισμόν ἐπαναστὰς Ἀμναῖος, ὦ ἄνθρωπε, εἶπε, τίς ἀνέξεταί σου δειπνοῦντος μὲν ὡς Λευκόλλου, οἰκοδομοῦντος δὲ ὡς Κράσσου, δημηγοροῦντος δὲ ἡμῖν ὡς Κάτωνος; καὶ τῶν ἄλλων δὲ τοὺς φαύλους καὶ ἀκολάστους, τοῖς λόγοις δὲ σεμνοὺς καὶ αὐστηρούς χλευάζοντες ἐκάλουν Κάτωνας.", "st": "Cat. Mi. 19.3"}, {"sp": "N", "t": "πολλῶν δὲ αὑτὸν ἐπὶ δημαρχίαν καλούντων οὐκ ᾤετο καλῶς ἔχειν μεγάλης ἐξουσίας καὶ ἀρχῆς, ὥσπερ ἰσχυροῦ φαρμάκου, δύναμιν ἐν πράγμασιν οὐκ ἀναγκαίοις ἐξαναλῶσαι. καὶ ἅμα, σχολῆς οὔσης τῶν δημοσίων, παραλαβὼν βιβλία καὶ φιλοσόφους ἐβάδιζεν εἰς Λευκανίαν, ἀγροὺς αὐτόθι κεκτημένος ἔχοντας οὐκ ἀνελευθέρους διατριβάς· εἶτα καθ’ ὁδὸν πολλοῖς τισιν ὑποζυγίοις καὶ σκεύεσι καὶ ἀκολούθοις ἀπαντήσας καὶ πυθόμενος Νέπωτα Μέτελλον εἰς Ῥώμην ἐπανέρχεσθαι δημαρχίαν μετιέναι παρεσκευασμένον, ἐπέστη σιωπῇ, καὶ διαλιπὼν μικρόν ἐκέλευσεν ἀναστρέφειν ὀπίσω τοὺς ἑαυτοῦ. τῶν δὲ φίλων θαυμασάντων, οὐκ ἴστε, εἶπεν, ὅτι καὶ καθ’ αὑτὸν ὑπὸ ἐμπληξίας φοβερός ἐστι Μέτελλος, καὶ νῦν ἐκ τῆς Πομπηΐου γνώμης ἀφιγμένος εἰς τὴν πολιτείαν ἐμπεσεῖται δίκην σκηπτοῦ πάντα πράγματα ταράττων; οὔκουν σχολῆς οὐδὲ ἀποδημίας καιρός, ἀλλὰ δεῖ κρατῆσαι τοῦ ἀνδρός, ἢ καλῶς ἀποθανεῖν ὑπὲρ τῆς ἐλευθερίας ἀγωνιζόμενον ὅμως δὲ τῶν φίλων παραινεσάντων ἀφίκετο πρῶτον εἰς τὰ χωρία καὶ διέτριψεν οὐ πολὺν χρόνον, εἶτα ἐπανῆκεν εἰς πόλιν. ἑσπέρας δὲ ἐλθών εὐθὺς ἕωθεν εἰς ἀγορὰν κατέβαινε δημαρχίαν μετιών, ὡς ἀντιταξόμενος πρὸς τὸν Μέτελλον. τὸ γὰρ ἰσχυρὸν ἢ ἀρχὴ πρὸς τὸ κωλύειν ἔχει μᾶλλον ἢ πρὸς τὸ πράττειν κἂν πάντες οἱ λοιποὶ παρ’ ἕνα ψηφίσωνται, τοῦ μὴ θέλοντος μηδὲ ἐῶντος τὸ κράτος ἐστί.", "st": "Cat. Mi. 20.1"}, {"sp": "N", "t": "τὸ μὲν οὖν πρῶτον ὀλίγοι περὶ τὸν Κάτωνά τῶν φίλων ἦσαν φανερᾶς δέ τῆς γνώμης αὐτοῦ γενομένης, ὀλίγου χρόνου πάντες οἱ χρηστοὶ καὶ γνώριμοι συνέτρεχον καὶ παρεκάλουν καὶ παρεθάρρυνον αὐτὸν, ὡς οὐ λαμβάνοντα χάριν, ἀλλὰ τὴν μεγίστην διδόντα τῇ πατρίδι καὶ τοῖς ἐπιεικεστάτοις τῶν πολιτῶν, ὅτι πολλάκις ἀπραγμόνως ἄρξαι παρὸν οὐ θελήσας, νῦν ὑπὲρ τῆς ἐλευθερίας καὶ πολιτείας ἀγωνιούμενος οὐκ ἀκινδύνως κάτεισι. λέγεται δέ, πολλῶν ὑπὸ σπουδῆς καὶ φιλοφροσύνης ὠθουμένων πρὸς αὐτὸν, ἐν κινδύνῳ γενόμενος μόλις ἐξικέσθαι διὰ πλῆθος εἰς τὴν ἀγοράν. ἀποδειχθεὶς δὲ δήμαρχος σὺν ἑτέροις, καὶ τῷ Μετέλλῳ, τὰς ὑπατικὰς ἀρχαιρεσίας ὁρῶν ὠνίους οὔσας, ἐπετίμησε τῷ δήμῳ· καὶ καταπαύων τὸν λόγον ἐπώμοσε τοῦ δόντος ἀργύριον, ὅστις ἂν ᾖ, κατηγορήσειν, ἕνα Σιλανὸν ὑπεξελόμενος δι’ οἰκειότητα. Σερβιλίαν γὰρ ἀδελφὴν Κάτωνος ὁ Σιλανὸς εἶχε. διὸ τοῦτον μὲν παρῆκε, Λεύκιον δὲ Μουρήναν ἐδίωκεν ἀργυρίῳ διαπραξάμενον ἄρχοντα μετὰ τοῦ Σιλανοῦ γενέσθαι, νόμῳ δέ τινι τοῦ φεύγοντος ἀεὶ φύλακα τῷ κατηγόρῳ διδόντος, ὥστε μὴ λαθεῖν ἃ συνάγει καὶ παρασκευάζεται πρὸς τὴν κατηγορίαν, ὁ τῷ Κάτωνι δοθεὶς ὑπὸ τοῦ Μουρήνα παρακολουθῶν καὶ παραφυλάττων, ὡς ἑώρα μηθὲν ἐπιβούλως πράττοντα μηδὲ ἀδίκως, ἀλλὰ γενναίως τε καὶ φιλανθρώπως ἁπλῆν τινα τῆς κατηγορίας καὶ δικαίαν ὁδὸν πορευόμενον, οὕτως ἐθαύμαζε τὸ φρόνημα καὶ τὸ ἦθος ὥστε κατ’ ἀγορὰν προσιὼν καὶ φοιτῶν ἐπὶ θύρας πυνθάνεσθαι τοῦ Κάτωνος εἰ μέλλει τι σήμερον πραγματεύσασθαι τῶν περὶ τὴν κατηγορίαν· εἰ δὲ μὴ φαίη, πιστεύων ἀπῄει.", "st": "Cat. Mi. 21.1"}, {"sp": "N", "t": "τῆς δὲ δίκης λεγομένης ὁ Κικέρων, ὕπατος ὢν τότε καὶ τῷ Μουρήνᾳ συνδικῶν, πολλὰ διὰ τὸν Κάτωνά τοὺς Στωϊκοὺς φιλοσόφους καὶ ταῦτα δὴ τὰ παράδοξα καλούμενα δόγματα χλευάζων καὶ παρασκώπτων γέλωτα παρεῖχε τοῖς δικασταῖς. τὸν οὖν Κάτωνά φασι διαμειδιάσαντα πρὸς τοὺς παρόντας εἰπεῖν ὦ ἄνδρες, ὡς γελοῖον ὕπατον ἔχομεν. ἀποφυγὼν δὲ ὁ Μουρήνας οὐ πονηροῦ πάθος οὐδὲ ἄφρονος ἔπαθεν ἀνθρώπου πρὸς τὸν Κάτωνά· καὶ γὰρ ὑπατεύων ἐχρῆτο συμβούλῳ τῶν μεγίστων, καὶ τἆλλα τιμῶν καὶ πιστεύων διετέλεσεν. αἴτιος δὲ ἦν ὁ Κάτων αὐτός, ἐπὶ τοῦ βήματος καὶ τοῦ συνεδρίου χαλεπὸς ὢν καὶ φοβερὸς ὑπὲρ τῶν δικαίων, εἶτα πᾶσιν εὐνοϊκῶς καὶ φιλανθρώπως προσφερόμενος.", "st": "Cat. Mi. 21.5"}, {"sp": "N", "t": "πρὶν δὲ εἰς τὴν δημαρχίαν καθίστασθαι, Κικέρωνος ὑπατεύοντος, ἄλλοις τε πολλοῖς ἀγῶσι τὴν ἀρχὴν ὤρθωσεν αὐτοῦ καὶ ταῖς περὶ Κατιλίναν πράξεσι μεγίσταις καὶ καλλίσταις γενομέναις τέλος ἐπέθηκεν. αὐτὸς μὲν γὰρ ὁ Κατιλίνας ὀλέθριόν τε καὶ παντελῆ μεταβολὴν ἐπάγων τοῖς Ῥωμαίων πράγμασι καὶ στάσεις ὁμοῦ καὶ πολέμους ταράττων ἐξελεγχθεὶς ὑπὸ τοῦ Κικέρωνος ἐξέπεσε τῆς πόλεως, Λέντλος δὲ καὶ Κέθηγος καὶ μετ’ αὐτῶν ἕτεροι συχνοὶ δεξάμενοι τὴν συνωμοσίαν, καὶ τῷ Κατιλίνᾳ δειλίαν καὶ μικρολογίαν τῶν τολμημάτων ἐπικαλοῦντες, αὐτοὶ διενοοῦντο τὴν πόλιν ἄρδην ἀναιρεῖν πυρί καὶ τὴν ἡγεμονίαν ἐθνῶν ἀποστάσεσι καὶ πολέμοις ἀλλοφύλοις ἀνατρέπειν. φανερᾶς δὲ τῆς παρασκευῆς αὐτῶν γενομένης, καὶ Κικέρωνος ἐν βουλῇ γνώμην προθέντος, ὁ μὲν πρῶτος εἰπὼν Σιλανὸς ἀπεφήνατο δοκεῖν αὐτῷ τὰ ἔσχατα παθεῖν χρῆναι τοὺς ἄνδρας, οἱ δὲ μετ’ αὐτὸν ἐφεξῆς ἠκολούθησαν, ἄχρι Καίσαρος. Καῖσαρ δὲ ἀναστάς, ἅτε δὴ καὶ δεινὸς εἰπεῖν καὶ πᾶσαν ἐν τῇ πόλει μεταβολὴν καὶ κίνησιν ὥσπερ ὕλην ὧν αὐτὸς διενοεῖτο βουλόμενος αὔξειν μᾶλλον ἢ σβεννυμένην περιορᾶν, ἐπαγωγὰ πολλὰ καὶ φιλάνθρωπα διαλεχθείς ἀποκτεῖναι μὲν ἀκρίτους οὐκ εἴα τοὺς ἄνδρας, εἱρχθέντας δὲ τηρεῖν ἐκέλευσεν, οὕτω δὲ τὰς γνώμας μετέστησε τῆς βουλῆς, φοβηθείσης τὸν δῆμον, ὥστε καὶ Σιλανὸν ἔξαρνον εἶναι καὶ λέγειν ὡς οὐδ’ αὐτὸς εἴποι θάνατον, ἀλλὰ εἱργμόν· ἔσχατον γὰρ ἀνδρὶ Ῥωμαίῳ τοῦτο κακῶν ἁπάντων.", "st": "Cat. Mi. 22.1"}, {"sp": "N", "t": "γενομένης δὲ τοιαύτης τῆς τροπῆς καὶ ἁπάντων ἐπὶ τὸ πρᾳότερον ῥυέντων καὶ φιλανθρωπότερον, ὁ Κάτων πρὸς τὴν γνώμην ἀναστὰς εὐθὺς ἵετο τῷ λόγῳ μετ’ ὀργῆς καὶ πάθους, τόν τε Σιλανὸν κακίζων τῆς μεταβολῆς, καὶ καθαπτόμενος τοῦ Καίσαρος ὡς σχήματι δημοτικῷ καὶ λόγῳ φιλανθρώπῳ τὴν πόλιν ἀνατρέποντος, καὶ δεδιττομένου τὴν βουλὴν ἐφ’ οἷς αὐτὸν ἔδει δεδιέναι καὶ ἀγαπᾶν εἰ τῶν γεγονότων ἀθῷος ἀπαλλάξει καὶ ἀνύποπτος, οὕτως περιφανῶς καὶ ἰταμῶς τοὺς κοινοὺς ἐξαρπάζων πολεμίους καὶ τὴν παρ’ οὐδὲν ἐλθοῦσαν ἀπολέσθαι πατρίδα τοιαύτην καὶ τοσαύτην ὁμολογῶν μὴ ἐλεεῖν, ἀλλ’ οὓς ἔδει μὴ γενέσθαι μηδὲ φῦναι δακρύων καὶ ἀνακλαιόμενος, εἰ φόνων μεγάλων καὶ κινδύνων ἀπαλλάξουσι τὴν πόλιν ἀποθανόντες.", "st": "Cat. Mi. 23.1"}, {"sp": "N", "t": "τοῦτον μόνον ὧν Κάτων εἶπε διασῴζεσθαί φασι τόν λόγον, Κικέρωνος τοῦ ὑπάτου τοὺς διαφέροντας ὀξύτητι τῶν γραφέων σημεῖα προδιδάξαντος ἐν μικροῖς καὶ βραχέσι τύποις πολλῶν γραμμάτων ἔχοντα δύναμιν, εἶτα ἄλλον ἀλλαχόσε τοῦ βουλευτηρίου σποράδην ἐμβαλόντος. οὔπω γὰρ ἤσκουν οὐδ’ ἐκέκτηντο τοὺς καλουμένους σημειογράφους, ἀλλὰ τότε πρῶτον εἰς ἴχνος τι καταστῆναι λέγουσιν. ἐκράτησε δ’ οὖν ὁ Κάτων καὶ μετέστησε τὰς γνώμας, ὥστε θάνατον καταψηφίσασθαι τῶν ἀνδρῶν.", "st": "Cat. Mi. 23.3"}, {"sp": "N", "t": "εἰ δὲ δεῖ μηδὲ τὰ μικρὰ τῶν ἠθῶν σημεῖα παραλιπεῖν ὥσπερ εἰκόνα ψυχῆς ὑπογραφομένους, λέγεται, τότε πολλὴν ἅμιλλαν καὶ μέγαν ἀγῶνα πρὸς τὸν Κάτωνα τοῦ Καίσαρος ἔχοντος καὶ τῆς βουλῆς εἰς ἐκείνους ἀνηρτημένης, δελτάριόν τι μικρὸν ἔξωθεν εἰσκομισθῆναι τῷ Καίσαρι. τοῦ δὲ Κάτωνος εἰς ὑποψίαν ἄγοντος τὸ πρᾶγμα καὶ διαβάλλοντος εἶναί τινας τοὺς κινουμένους, καὶ κελεύοντος ἀναγινώσκειν τὰ γεγραμμένα, τὸν Καίσαρα τῷ Κάτωνι προσδοῦναι τὸ δελτάριον ἐγγὺς ἑστῶτι. τὸν δὲ ἀναγνόντα Σερβιλίας τῆς ἀδελφῆς ἐπιστόλιον ἀκόλαστον πρὸς τὸν Καίσαρα γεγραμμένον, ἐρώσης καὶ διεφθαρμένης ὑπ’ αὐτοῦ, προσρῖψαί τε τῷ Καίσαρι καὶ εἰπεῖν, κράτει, μέθυσε, καὶ πάλιν οὕτως ἐπὶ τὸν ἐξ ἀρχῆς λόγον τραπέσθαι.", "st": "Cat. Mi. 24.1"}, {"sp": "N", "t": "φαίνεται δὲ ὅλως ἀτύχημα γενέσθαι τοῦ Κάτωνος ἡ γυναικωνῖτις αὕτη μὲν γὰρ ἐπὶ Καίσαρι κακῶς ἤκουσε· τὰ δὲ τῆς ἑτέρας Σερβιλίας, ἀδελφῆς δὲ Κάτωνος, ἀσχημονέστερα. Λευκόλλῳ γὰρ γαμηθεῖσα, πρωτεύσαντι Ῥωμαίων κατὰ δόξαν ἀνδρί, καὶ τεκοῦσα παιδίον ἐξέπεσε τοῦ οἴκου δι’ ἀκολασίαν. τὸ δὲ αἴσχιστον, οὐδ’ ἡ γυνὴ τοῦ Κάτωνος Ἀτιλία τοιούτων ἐκαθάρευσεν ἁμαρτημάτων, ἀλλὰ καίπερ ἐξ αὐτῆς δύο παιδία πεποιημένος ἀνάγκην ἔσχεν ἐκβαλεῖν ἀσχημονοῦσαν.", "st": "Cat. Mi. 24.3"}, {"sp": "N", "t": "εἶτα ἔγημε θυγατέρα Φιλίππου, Μαρκίαν, ἐπιεικῆ δοκοῦσαν εἶναι γυναῖκα, περὶ ἧς ὁ πλεῖστος λόγος· καὶ καθάπερ ἐν δράματι τῷ βίῳ τοῦτο τὸ μέρος προβληματῶδες γέγονε καὶ ἄπορον. ἐπράχθη δὲ τοῦτον τὸν τρόπον, ὡς ἱστορεῖ Θρασέας, εἰς Μουνάτιον, ἄνδρα Κάτωνος ἑταῖρον καὶ συμβιωτήν, ἀναφέρων τήν πίστιν. ἐν πολλοῖς ἐρασταῖς καὶ θαυμασταῖς τοῦ Κάτωνος ἦσαν ἑτέρων ἕτεροι μᾶλλον ἔκδηλοι καὶ διαφανεῖς, ὧν καὶ Κόϊντος Ὁρτήσιος, ἀνὴρ ἀξιώματός τε λαμπροῦ καὶ τὸν τρόπον ἐπιεικής, ἐπιθυμῶν οὖν τῷ Κάτωνι μὴ συνήθης εἶναι μηδὲ ἑταῖρος μόνον, ἀλλ’ ἁμῶς γέ πως εἰς οἰκειότητα καταμίξαι καὶ κοινωνίαν πάντα τὸν οἶκον καὶ τό γένος, ἐπεχείρησε συμπείθειν ὅπως τήν θυγατέρα Πορκίαν, Βύβλῳ συνοικοῦσαν καὶ πεποιημένην ἐκείνῳ δύο παῖδας, αὐτῷ πάλιν ὥσπερ εὐγενῆ χώραν ἐντεκνώσασθαι παράσχῃ. δόξῃ μὲν γὰρ ἀνθρώπων ἄτοπον εἶναι τὸ τοιοῦτον, φύσει δὲ καλὸν καὶ πολιτικόν, ἐν ὥρᾳ καὶ ἀκμῇ γυναῖκα μήτε ἀργεῖν τὸ γόνιμον ἀποσβέσασαν, μήτε πλείονα τῶν ἱκανῶν ἐπιτίκτουσαν, ἐνοχλεῖν καὶ καταπτωχεύειν οὐδὲν δεόμενον, κοινουμένους δὲ τὰς διαδοχὰς ἀξίοις ἀνδράσι τήν τε ἀρετὴν ἄφθονον ποιεῖν καὶ πολύχυτον τοῖς γένεσι, καὶ τήν πόλιν αὑτὴν πρὸς αὑτὴν ἀνακεραννύναι ταῖς οἰκειότησιν. εἰ δὲ πάντως περιέχοιτο τῆς γυναικὸς ὁ Βύβλος, ἀποδώσειν εὐθὺς τεκοῦσαν, οἰκειότερος αὐτῷ τε Βύβλῳ καὶ Κάτωνι ι κοινωνίᾳ παίδων γενόμενος.", "st": "Cat. Mi. 25.1"}, {"sp": "N", "t": "ἀποκριναμένου δὲ τοῦ Κάτωνος ὡς Ὁρτήσιον μὲν ἀγαπᾷ καὶ δοκιμάζει κοινωνὸν οἰκειότητος, ἄτοπον δὲ ἡγεῖται ποιεῖσθαι λόγον περὶ γάμου θυγατρὸς ἑτέρῳ δεδομένης, μεταβαλὼν ἐκεῖνος οὐκ ὤκνησεν ἀποκαλυψάμενος αἰτεῖν τήν αὐτοῦ γυναῖκα Κάτωνος, νέαν μὲν οὖσαν ἔτι πρὸς τὸ τίκτειν, ἔχοντος δὲ τοῦ Κάτωνος ἀποχρῶσαν διαδοχήν. καὶ οὐκ ἔστιν εἰπεῖν ὡς ταῦτα ἔπραττεν εἰδὼς οὐ προσέχοντα τῇ Μαρκίᾳ τὸν Κάτωνα· κύουσαν γὰρ αὑτὴν τότε τυγχάνειν λέγουσιν. ὁ δὲ οὖν Κάτων ὁρῶν τήν τοῦ Ὁρτησίου σπουδὴν καὶ προθυμίαν οὐκ ἀντεῖπεν, ἀλλ’ ἔφη δεῖν καὶ Φιλίππῳ ταῦτα συνδόξαι τῷ πατρὶ τῆς Μαρκίας. ὡς οὖν ὁ Φίλιππος ἐντευχθεὶς ἔγνω τήν συγχώρησιν, οὐκ ἄλλως ἐνεγγύησε τήν Μαρκίαν ἢ παρόντος τοῦ Κάτωνος αὐτοῦ καὶ συνεγγυῶντος. ταῦτα μὲν οὖν, εἰ καὶ χρόνοις ὕστερον ἐπράχθη, μνησθέντι μοι τὸ τῶν γυναικῶν προλαβεῖν ἔδοξε.", "st": "Cat. Mi. 25.4"}, {"sp": "N", "t": "τῶν δὲ περὶ τὸν Λέντλον ἀναιρεθέντων, καὶ τοῦ Καίσαρος περὶ ὧν εἰσηγγέλθη καὶ διεβλήθη πρὸς τὴν σύγκλητον εἰς τὸν δῆμον καταφυγόντος καὶ τὰ πολλὰ νοσοῦντα καὶ διεφθαρμένα τῆς πολιτείας μέρη ταράττοντος καὶ συνάγοντος πρὸς αὑτόν, ὁ Κάτων φοβηθεὶς ἔπεισε τὴν βουλὴν ἀναλαβεῖν τὸν ἄπορον καὶ ἀνέμητον ὄχλον εἰς τὸ σιτηρέσιον, ἀναλώματος μὲν ὄντος ἐνιαυσίου χιλίων καὶ διακοσίων καὶ πεντήκοντα ταλάντων, περιφανῶς δὲ τῇ φιλανθρωπίᾳ ταύτῃ καὶ χάριτι τῆς ἀπειλῆς ἐκείνης διαλυθείσης. ἐντεῦθεν εἰς τὴν δημαρχίαν ἐμπεσὼν ὁ Μέτελλος ἐκκλησίας τε θορυβώδεις συνῆγε, καὶ νόμον ἔγραψε Πομπήϊον Μᾶγνον ἰέναι κατὰ τάχος μετὰ τῶν δυνάμεων εἰς Ἰταλίαν καὶ παραλαβόντα σῴζειν τὴν πόλιν, ὡς ὑπὸ Κατιλίνα κινδυνεύουσαν. ἦν δὲ τοῦτο λόγος εὐπρεπής, ἔργον δὲ τοῦ νόμου καί τέλος ἐγχειρίσαι τὰ πράγματα Πομπηΐῳ καὶ παραδοῦναι τὴν ἡγεμονίαν. γενομένης δὲ βουλῆς καὶ τοῦ Κάτωνος οὐχ, ὥσπερ εἰώθει, τῷ Μετέλλῳ σφοδρῶς ἐμπεσόντος, ἀλλ’ ἐπιεικῆ πολλὰ καὶ μέτρια παραινέσαντος, τέλος δὲ καὶ πρὸς δεήσεις τραπομένου καὶ τὴν Μετέλλων οἰκίαν ἀεὶ γενομένην ἀριστοκρατικὴν ἐπαινέσαντος, ἔτι μᾶλλον ἐξαρθεὶς καὶ καταφρονήσας ὁ Μέτελλος ὡς ἐνδιδόντος αὐτοῦ καὶ πτήσσοντος εἰς ὑπερηφάνους ἀπειλὰς καὶ λόγους θρασεῖς ἐξέπεσεν, ὡς βίᾳ πάντα τῆς βουλῆς διαπραξόμενος. οὕτω δὴ μεταβαλὼν ὁ Κάτων καὶ σχῆμα καὶ φωνὴν καὶ λόγον, ἐπειπὼν δὲ πᾶσι τοῖς ἄλλοις διατεταμένως ὅτι ζῶντος αὐτοῦ Πομπήϊος οὐ παρέσται μεθ’ ὅπλων εἰς τὴν πόλιν, ἐκεῖνο τῇ βουλῇ παρέστησεν, ὡς οὐδέτερος μὲν καθέστηκεν οὐδὲ χρῆται λογισμοῖς ἀσφαλέσιν, ἔστι δὲ ἡ μὲν Μετέλλου πολιτεία μανία δι’ ὑπερβολὴν κακίας φερομένη πρὸς ὄλεθρον καὶ σύγχυσιν ἁπάντων, ἡ δὲ Κάτωνος ἀρετῆς ἐνθουσιασμός ὑπὲρ τῶν καλῶν καὶ δικαίων ἀγωνιζομένης.", "st": "Cat. Mi. 26.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τὴν ψῆφον ὑπὲρ τοῦ νόμου φέρειν ὁ δῆμος ἔμελλε, Μετέλλῳ μὲν ὅπλα καὶ ξένοι καὶ μονομάχοι καὶ θεράποντες ἐπὶ τὴν ἀγορὰν τεταγμένοι παρῆσαν, καὶ τὸ ποθοῦν μεταβολῆς ἐλπίδι Πομπήϊον ὑπῆρχε τοῦ δήμου μέρος οὐκ ὀλίγον, ἦν δὲ μεγάλη καὶ ἀπὸ Καίσαρος ῥώμη στρατηγοῦντος τότε, Κάτωνι δὲ οἱ πρῶτοι τῶν πολιτῶν συνηγανάκτουν καὶ συνηδικοῦντο μᾶλλον ἢ συνηγωνίζοντο, πολλὴ δὲ τὴν οἰκίαν αὐτοῦ κατήφεια καὶ φόβος εἶχεν, ὥστε τῶν φίλων ἐνίους ἀσίτους διαγρυπνῆσαι μετ’ ἀλλήλων ἐν ἀπόροις ὄντας ὑπὲρ αὐτοῦ λογισμοῖς, καὶ γυναῖκα καὶ ἀδελφὰς ποτνιωμένας καὶ δακρυούσας. αὐτὸς δ’ ἀδεῶς καὶ τεθαρρηκότως ἐντυχὼν πᾶσι καὶ παρηγορήσας, καὶ γενόμενος περὶ δεῖπνον, ὥσπερ εἰώθει, καὶ νυκτερεύσας, ὑφ’ ἑνὸς τῶν συναρχόντων, Μινυκίου Θέρμου, βαθέως καθεύδων ἐπηγέρθη· καὶ κατέβησαν εἰς ἀγοράν, ὀλίγων μὲν αὐτοὺς προπεμπόντων, πολλῶν δὲ ἀπαντώντων καὶ φυλάττεσθαι παρακελευομένων. ὡς οὖν ἐπιστὰς ὁ Κάτων κατεῖδε τὸν νεὼν τῶν Διοσκούρων ὅπλοις περιεχόμενον καὶ τὰς ἀναβάσεις φρουρουμένας ὑπὸ μονομάχων, αὐτὸν δὲ καθήμενον ἄνω μετὰ Καίσαρος τὸν Μέτελλον, ἐπιστρέψας πρὸς τοὺς φίλους, ὢ θρασέος, εἶπεν, ἀνθρώπου καὶ δειλοῦ, ὃς καθ’ ἑνὸς ἀνόπλου καὶ γυμνοῦ τοσούτους ἐστρατολόγησεν. ἅμα δ’ εὐθὺς ἐβάδιζε μετὰ τοῦ Θέρμου. καὶ διέστησαν αὐτοῖς οἱ τὰς ἀναβάσεις κατέχοντες, ἄλλον δὲ οὐδένα παρῆκαν, ἢ μόλις ἐπισπάσας τῆς χειρὸς ὁ Κάτων τὸν Μουνάτιον ἀνήγαγε· καὶ βαδίζων εὐθὺς ὡς εἶχε καθίζει μέσον ἐμβαλὼν ἑαυτὸν τοῦ Μετέλλου καὶ τοῦ Καίσαρος, ὥστε διακόψαι τὴν κοινολογίαν. κἀκεῖνοι μὲν διηπόρησαν, οἱ δὲ χαρίεντες θεασάμενοι καὶ θαυμάσαντες τὸ πρόσωπον καὶ τὸ φρόνημα καὶ τὸ θάρσος τοῦ Κάτωνος ἐγγυτέρω προσῆλθον, καὶ βοῇ διεκελεύσαντο τῷ μὲν Κάτωνι θαρρεῖν, μένειν δὲ ἀλλήλοις καὶ συστρέφεσθαι καὶ μὴ προδιδόναι τὴν ἐλευθερίαν καὶ τὸν ὑπὲρ αὐτῆς ἀγωνιζόμενον.", "st": "Cat. Mi. 27.1"}, {"sp": "N", "t": "ἔνθα δὴ τοῦ ὑπηρέτου τὸν νόμον προχειρισαμένου, τοῦ δὲ Κάτωνος οὐκ ἐῶντος ἀναγινώσκειν, τοῦ δὲ Μετέλλου παραλαβόντος αὐτὸν καὶ ἀναγινώσκοντος, ὁ μὲν Κάτων ἐξήρπασε τὸ βιβλίον, ὁ δὲ Θέρμος ἀπὸ στόματος τοῦ Μετέλλου τὸν νόμον ἐπισταμένου καὶ λέγοντος ἐπέσχε τῇ χειρὶ τὸ στόμα καὶ τὴν φωνὴν ἀπέκλεισεν, ἄχρι οὗ, ἄμαχον ὁρῶν ἀγῶνα τοὺς ἄνδρας ὁ Μέτελλος ἀγωνιζομένους, καὶ τὸν δῆμον ἡττώμενον πρὸς τὸ συμφέρον καὶ τρεπόμενον, ἐκέλευσεν ἄποθεν ὁπλίτας μετὰ φόβου καὶ κραυγῆς ἐπιτρέχειν. γενομένου δὲ τούτου καὶ πάντων διασκεδασθέντων ὑποστάντα μόνον τὸν Κάτωνα καὶ βαλλόμενον λίθοις καὶ ξύλοις ἄνωθεν οὐ περιεῖδε Μουρήνας ὁ τὴν δίκην φυγὼν ὑπ’ αὐτοῦ καὶ κατηγορηθείς, ἀλλὰ τὴν τήβεννον προϊσχόμενος καὶ βοῶν ἀνασχεῖν τοῖς βάλλουσι, καὶ τέλος αὐτὸν τὸν Κάτωνα πείθων καὶ περιπτύσσων, εἰς τὸν νεὼν τῶν Διοσκούρων ἀπήγαγεν.", "st": "Cat. Mi. 28.1"}, {"sp": "N", "t": "ἐπεὶ δὲ κατεῖδεν ὁ Μέτελλος ἐρημίαν περὶ τὸ βῆμα καὶ φυγὴν ἀγορᾶς τῶν ἐναντιουμένων, παντάπασι πεισθεὶς κρατεῖν ἐκέλευσεν ἀπιέναι πάλιν τοὺς ὁπλοφόρους, καὶ προσελθὼν κοσμίως αὐτὸς ἐπεχείρει πράττειν τὰ περὶ τὸν νόμον. οἱ δὲ ἐναντίοι ταχέως ἀναλαβόντες ἑαυτοὺς ἐκ τῆς τροπῆς ἐπῄεσαν αὖθις ἐμβοήσαντες μέγα καὶ θαρραλέον, ὥστε τοῖς περὶ τὸν Μέτελλον ἐμπεσεῖν ταραχὴν καὶ δέος οἰομένοις ὅπλων ποθὲν εὐπορήσαντας αὐτοὺς ἐπιφέρεσθαι, καὶ μηθένα μένειν, ἀλλὰ φεύγειν ἅπαντας ἀπὸ τοῦ βήματος, οὕτω δὴ σκεδασθέντων ἐκείνων, τοῦ δὲ Κάτωνος προσελθόντος καὶ τὰ μὲν ἐπαινέσαντος, τὰ δὲ ἐπιρρώσαντος τὸν δῆμον, οἵ τε πολλοὶ παρετάξαντο παντὶ τρόπῳ καταλῦσαι τὸν Μέτελλον, ἥ τε σύγκλητος ἀθροισθεῖσα παρήγγειλεν ἀρχῆθεν βοηθεῖν τῷ Κάτωνι καὶ διαμάχεσθαι πρὸς τὸν νόμον, ὡς στάσιν ἐπεισάγοντα τῇ Ῥώμῃ καὶ πόλεμον ἐμφύλιον.", "st": "Cat. Mi. 28.4"}, {"sp": "N", "t": "ὁ δὲ Μέτελλος αὐτὸς μὲν ἦν ἄτρεπτος καὶ θρασὺς ἔτι, ὁρῶν δὲ τοὺς περὶ αὐτὸν ἐκπεπληγμένους κομιδῆ τὸν Κάτωνα καὶ νομίζοντας ἄμαχον καὶ δυσεκβίαστον, αἰφνίδιον ἐξεπήδησεν εἰς τὴν ἀγοράν, καὶ συναγαγὼν τὸν δῆμον ἄλλα τε πολλὰ περὶ τοῦ Κάτωνος ἐπίφθονα διῆλθε, καὶ φεύγειν τὴν τυραννίδα βοῶν τὴν ἐκεῖνον καὶ τὴν κατὰ Πομπηΐου συνωμοσίαν, ἐφ’ ᾗ μετανοήσειν ταχὺ τὴν πόλιν ἀτιμάζουσαν ἄνδρα τοσοῦτον, ὥρμησεν εὐθὺς εἰς Ἀσίαν, ὡς ταῦτα πρὸς ἐκεῖνον κατηγορήσων. ἦν οὖν δόξα μεγάλη τοῦ Κάτωνος ἄχθος οὐ μικρὸν ἀπεσκευασμένου τῆς δημαρχίας, καὶ τρόπον τινὰ τὴν Πομπηΐου δύναμιν ἐν Μετέλλῳ καθῃρηκότος. ἔτι δὲ μᾶλλον εὐδοκίμησε τὴν σύγκλητον ὡρμημένην ἀτιμοῦν καὶ ἀποψηφίζεσθαι τὸν Μέτελλον οὐκ ἐάσας, ἀλλ’ ἐναντιωθεὶς καὶ παραιτησάμενος. οἵ τε γὰρ πολλοὶ φιλανθρωπίας ἐποιοῦντο καὶ μετριότητος τὸ μὴ ἐπεμβῆναι τῷ ἐχθρῷ μηδὲ ἐνυβρίσαι κατὰ κράτος περιγενόμενον, τοῖς τε φρονίμοις ὀρθῶς ἐφαίνετο καὶ συμφερόντως μὴ παροξῦναι Πομπήϊον.", "st": "Cat. Mi. 29.1"}, {"sp": "N", "t": "ἐκ τούτου Λεύκολλος ἐπανελθὼν ἐκ τῆς στρατείας, ἧς ἔδοξε τό τέλος καὶ τὴν δόξαν ἀφῃρῆσθαι Πομπήϊος, εἰς κίνδυνον ἦλθε τοῦ μὴ θριαμβεῦσαι, Γαΐου Μεμμίου καταστασιάζοντος αὐτὸν ἐν τῷ δήμῳ καὶ δίκας ἐπάγοντος, εἰς τὴν Πομπηΐου χάριν μᾶλλον ἢ κατὰ ἔχθος ἴδιον. ὁ δὲ Κάτων, οἰκειότητός τε πρὸς Λεύκολλον αὐτῷ γεγενημένης, ἔχοντα Σερβιλίαν τὴν ἀδελφὴν αὐτοῦ, καὶ τὸ πρᾶγμα δεινὸν ἡγούμενος, ἀντέστη τῷ Μεμμίῳ, καὶ πολλὰς ὑπέμεινε διαβολὰς καὶ κατηγορίας. τέλος δὲ, τῆς ἀρχῆς ἐκβαλλόμενος ὡς τυραννίδος, τοσοῦτον ἐκράτησεν ὥστε τὸν Μέμμιον αὐτὸν ἀναγκάσαι τῶν δικῶν ἀποστῆναι καὶ φυγεῖν τὸν ἀγῶνα. Λεύκολλος μὲν οὖν θριαμβεύσας ἔτι μᾶλλον ἐνεφύετο τῇ φιλίᾳ τοῦ Κάτωνος, ἔχων ἔρυμα καὶ πρόβλημα μέγα πρὸς τὴν Πομπηΐου δύναμιν.", "st": "Cat. Mi. 29.3"}, {"sp": "N", "t": "Πομπήϊος δὲ μέγας ἀπὸ τῆς στρατείας ἐπανιών, καὶ τῇ λαμπρότητι καὶ προθυμίᾳ τῆς ὑποδοχῆς πεποιθὼς οὐδὲν ἂν δεηθεὶς ἀποτυχεῖν τῶν πολιτῶν, προὔπεμψεν ἀξιῶν τὰς ὑπατικὰς ἀρχαιρεσίας ἀναβαλέσθαι τὴν σύγκλητον, ὡς ἂν αὐτὸς παρὼν Πείσωνι συναρχαιρεσιάσῃ. τῶν δὲ πλείστων ὑπεικόντων, οὐ τὴν ἀναβολὴν μέγιστον ὁ Κάτων ἡγούμενος, ἀλλὰ τὴν πεῖραν ἀποκόψαι καὶ τὴν ἐλπίδα τοῦ Πομπηΐου βουλόμενος, ἀντεῖπε καὶ μετέστησε τὴν βουλήν, ὥστε ἀποψηφίσασθαι. τοῦτο τὸν Πομπήϊον οὐχ ἡσυχῇ διετάραξε· καὶ νομίζων οὐ μικρὰ προσπταίσειν τῷ Κάτωνι μὴ φίλῳ γενομένῳ, μετεπέμψατο Μουνάτιον, ἑταῖρον αὐτοῦ· καὶ δύο τοῦ Κάτωνος ἀδελφιδᾶς ἐπιγάμους ἔχοντος ᾔτει τὴν μὲν πρεσβυτέραν ἑαυτῷ γυναῖκα, τὴν δὲ νεωτέραν τῷ υἱῷ. τινὲς δέ φασιν οὐ τῶν ἀδελφιδῶν, ἀλλὰ τῶν θυγατέρων τὴν μνηστείαν γενέσθαι, τοῦ δὲ Μουνατίου ταῦτα πρὸς τὸν Κάτωνα καὶ τὴν γυναῖκα καὶ τὰς ἀδελφὰς φράσαντος, αἱ μὲν ὑπερηγάπησαν τὴν οἰκειότητα πρὸς τὸ μέγεθος καὶ τὸ ἀξίωμα τοῦ ἀνδρός, ὁ δὲ Κάτων οὔτ’ ἐπισχὼν οὔτε βουλευσάμενος, ἀλλὰ πληγεὶς εὐθὺς εἶπε· βάδιζε, Μουνάτιε, βάδιζε, καὶ λέγε πρὸς Πομπήϊον ὡς Κάτων οὐκ ἔστι διὰ τῆς γυναικωνίτιδος ἁλώσιμος, ἀλλὰ τὴν μὲν εὔνοιαν ἀγαπᾷ, καὶ τὰ δίκαια ποιοῦντι φιλίαν παρέξει πάσης πιστοτέραν οἰκειότητος, ὅμηρα δὲ οὐ προήσεται τῇ Πομπηΐου δόξῃ κατὰ τῆς πατρίδος.", "st": "Cat. Mi. 30.1"}, {"sp": "N", "t": "ἐπὶ τούτοις ἤχθοντο μὲν αἱ γυναῖκες, ᾐτιῶντο δὲ οἱ φίλοι τοῦ Κάτωνος ὡς ἄγροικον ἅμα καὶ ὑπερήφανον τὴν ἀπόκρισιν. εἶτα μέντοι πράττων τινὶ τῶν φίλων ὑπατείαν ὁ Πομπήϊος ἀργύριον εἰς τὰς φυλὰς ἔπεμπε, καὶ περιβόητος ὁ δεκασμὸς ἦν, ἐν κήποις ἐκείνου τῶν χρημάτων ἀριθμουμένων. εἰπόντος οὖν τοῦ Κάτωνος πρὸς τὰς γυναῖκας ὅτι τοιούτων ἦν κοινωνεῖν καὶ ἀναπίμπλασθαι πραγμάτων ἀνάγκη Πομπηΐῳ συναφθέντα δι’ οἰκειότητος, ὡμολόγουν ἐκεῖναι κάλλιον αὐτὸν βεβουλεῦσθαι διακρουσάμενον. εἰ δὲ δεῖ πρὸς τὰ συμβάντα κρίνειν, τοῦ παντὸς ἔοικεν ὁ Κάτων ἁμαρτεῖν τὴν οἰκειότητα μὴ δεξάμενος, ἀλλ’ ἐάσας πρὸς Καίσαρα τραπέσθαι καὶ γῆμαι γάμον ὃς τὴν Πομπηΐου δύναμιν καὶ Καίσαρος εἰς ταὐτὸ συνενεγκών ὀλίγου τὰ μὲν Ῥωμαίων ἀνέτρεψε πράγματα, τὴν δὲ πολιτείαν ἀνεῖλεν, ὧν οὐθὲν ἂν ἴσως συνέπεσεν, εἰ μὴ Κάτων τὰ μικρὰ τοῦ Πομπηΐου φοβηθεὶς ἁμαρτήματα τὸ μέγιστον περιεῖδεν, αὐτὸν ἑτέρῳ δύναμιν προσγενόμενον.", "st": "Cat. Mi. 30.5"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ἔμελλεν ἔτι. Λευκόλλου δὲ περὶ τῶν ἐν Πόντῳ διατάξεων στασιάσαντος πρὸς Πομπήϊον ἠξίουν γὰρ ἰσχύειν ἑκάτερος τὰ ὑφ’ αὐτοῦ γενόμενα, καὶ Λευκόλλῳ Κάτωνος ἀδικουμένῳ περιφανῶς προσαμύνοντος, ἐλαττούμενος ὁ Πομπήϊος ἐν συγκλήτῳ καὶ δημαγωγῶν, ἐπὶ νομὴν χώρας ἐκάλει τὸ στρατιωτικόν. ὡς δὲ κἀνταῦθα Κάτων ἐνιστάμενος ἐξέκρουσε τὸν νόμον, οὕτω Κλωδίου τε περιείχετο, τοῦ τότε θρασυτάτου τῶν δημαγωγῶν, καὶ Καίσαρα προσήγετο, τρόπον τινὰ Κάτωνος αὐτοῦ παρασχόντος ἀρχήν. ὁ γὰρ Καῖσαρ ἀπὸ τῆς ἐν Ἰβηρίᾳ, στρατηγίας ἐπανήκων ἅμα μὲν ὑπατείαν ἐβούλετο παραγγέλλειν, ἅμα δὲ ᾔτει θρίαμβον. ἐπεὶ δὲ κατὰ νόμον ἔδει τοὺς μὲν ἀρχὴν μετιόντας παρεῖναι, τοὺς δὲ μέλλοντας εἰσελαύνειν θρίαμβον ἔξω τείχους ὑπομένειν, ἠξίου παρὰ τῆς βουλῆς αὐτῷ δοθῆναι δι’ ἑτέρων αἰτεῖσθαι τήν ἀρχήν. βουλομένων δὲ πολλῶν ἀντέλεγεν ὁ Κάτων ὡς δὲ ᾔσθετο χαριζομένους τῷ Καίσαρι, λέγων ὅλην κατανάλωσε τήν ἡμέραν καὶ τήν βουλὴν οὕτως ἐξέκρουσε. χαίρειν οὖν ἐάσας τὸν θρίαμβον ὁ Καῖσαρ εἰσελθὼν εὐθὺς εἴχετο Πομπηΐου καὶ τῆς ὑπατείας. ἀποδειχθεὶς δὲ ὕπατος τήν τε Ἰουλίαν ἐνεγγύησεν αὐτῷ, καὶ συστάντες ἤδη μετ’ ἀλλήλων ἐπὶ τήν πόλιν ὁ μὲν εἰσέφερε νόμους τοῖς πένησι κληρουχίαν καὶ νομὴν χώρας διδόντας, ὁ δὲ παρῆν τοῖς νόμοις βοηθῶν. οἱ δὲ περὶ Λεύκολλον καὶ Κικέρωνα Βύβλῳ τῷ ἑτέρῳ τῶν ὑπάτων συντάξαντες ἑαυτοὺς ἀντέπραττον, μάλιστα δὲ Κάτων, ἤδη μὲν ὑφορώμενος τήν Καίσαρος καὶ Πομπηΐου φιλίαν καὶ σύστασιν ἐπ’ οὐδενὶ δικαίῳ γεγενημένην, φοβεῖσθαι δὲ φάσκων οὐ τήν νομὴν τῆς χώρας, ἀλλ’ ὃν ἀντὶ ταύτης ἀπαιτήσουσι μισθὸν οἱ χαριζόμενοι καὶ δελεάζοντες τὸ πλῆθος.", "st": "Cat. Mi. 31.1"}, {"sp": "N", "t": "Ὡς δὲ ταῦτα λέγων τήν τε βουλὴν ὁμόψηφον εἶχε, καὶ τῶν ἐκτὸς ἀνθρώπων οὐκ ὀλίγοι παρίσταντο δυσχεραίνοντες τήν ἀτοπίαν τοῦ Καίσαρος· ἃ γὰρ οἱ θρασύτατοι δήμαρχοι καὶ ὀλιγωρότατοι πρὸς χάριν ἐπολιτεύοντο τῶν πολλῶν, ταῦτα ἀπ’ ἐξουσίας ὑπατικῆς, αἰσχρῶς καὶ ταπεινῶς ὑποδυόμενος τὸν δῆμον, ἔπραττε· φοβηθέντες οὖν ἐχώρουν διὰ βίας, καὶ πρῶτον μὲν αὐτῷ τῷ Βύβλῳ καταβαίνοντι κοπρίων ἐπεσκεδάσθη κόφινος, ἔπειτα τοῖς ῥαβδούχοις προσπεσόντες αὐτοῦ κατέκλασαν τὰς ῥάβδους· τέλος δὲ καὶ βελῶν φερομένων καὶ πολλῶν συντιτρωσκομένων ἔφυγον ἐξ ἀγορᾶς δρόμῳ μὲν οἱ λοιποὶ πάντες, ἔσχατος δὲ Κάτων ἀπῄει βάδην, μεταστρεφόμενος καὶ μαρτυρόμενος τοὺς πολίτας. οὐ μόνον οὖν τήν διανομὴν ἐκύρωσαν, ἀλλὰ καὶ προσεψηφίσαντο τήν σύγκλητον ὀμόσαι πᾶσαν ἦ μὴν ἐπιβεβαιώσειν τὸν νόμον, καὶ βοηθήσειν ἄν τις τἀναντία πράττῃ, μεγάλα τάξαντες ἐπιτίμια κατὰ τῶν μὴ ὀμοσάντων. ὤμνυσαν οὖν ἅπαντες ἐξ ἀνάγκης, τὸ Μετέλλου τοῦ παλαιοῦ πάθος ἐν νῷ λαμβάνοντες, ὃν εἰς νόμον ὅμοιον ὀμόσαι μὴ θελήσαντα περιεῖδεν ὁ δῆμος ἐκπεσόντα φυγῇ τῆς Ἰταλίας. διὸ καὶ τὸν Κάτωνα πολλὰ μὲν αἱ γυναῖκες οἴκοι δακρύουσαι καθικέτευον εἶξαι καὶ ὀμόσαι, πολλὰ δὲ οἱ φίλοι καὶ συνήθεις, ὁ δὲ μάλιστα συμπείσας καὶ ἀγαγὼν ἐπὶ τὸν ὅρκον ἦν Κικέρων ὁ ῥήτωρ, παραινῶν καὶ διδάσκων ὡς τάχα μὲν οὐδὲ δίκαιόν ἐστι τοῖς ἐγνωσμένοις κοινῇ μόνον οἴεσθαι δεῖν ἀπειθεῖν, ἐν δὲ ἀδυνάτῳ τῷ μεταστῆσαί τι τῶν γεγονότων ἀφειδεῖν ἑαυτοῦ παντάπασιν ἀνόητον καὶ μανικόν· ἔσχατον δὲ κακῶν, εἰ δι’ ἣν ἅπαντα πράττει πόλιν ἀφεὶς καὶ προέμενος τοῖς ἐπιβουλεύουσιν ὥσπερ ἄσμενος ἀπαλλάξεται τῶν ὑπὲρ αὐτῆς ἀγώνων καὶ γὰρ εἰ μὴ Κάτων τῆς Ῥώμης, ἀλλ’ ἡ Ῥώμη δεῖται Κάτωνος, δέονται δὲ καὶ οἱ φίλοι πάντες· ὧν αὑτὸν εἶναι πρῶτον ὁ Κικέρων ἔλεγεν, ἐπιβουλευόμενον ὑπὸ Κλωδίου διὰ δημαρχίας ἄντικρυς ἐπ’ αὐτὸν βαδίζοντος. ὑπὸ τούτων φασὶ καὶ τοιούτων τὸν Κάτωνα λόγων καὶ δεήσεων μαλασσόμενον οἴκοι καὶ κατ’ ἀγοράν ἐκβιασθῆναι μόλις, καὶ προσελθεῖν πρὸς τὸν ὅρκον ἔσχατον ἁπάντων πλὴν ἑνὸς Φαωνίου τῶν φίλων καὶ συνήθων.", "st": "Cat. Mi. 32.1"}, {"sp": "N", "t": "ἐπαρθεὶς οὖν ὁ Καῖσαρ ἄλλον εἰσέφερε νόμον, τὴν Καμπανίαν σχεδὸν ὅλην προσκατανέμοντα Τοῖς ἀπόροις καὶ πένησιν. ἀντέλεγε δὲ οὐδεὶς πλὴν τοῦ Κάτωνος, καὶ τοῦτον ἀπὸ τοῦ βήματος ὁ Καῖσαρ εἷλκεν εἰς δεσμωτήριον, οὐδέν τι μᾶλλον ὑφιέμενον τῆς παρρησίας, ἀλλ’ ἐν τῷ βαδίζειν ἅμα περὶ τοῦ νόμου διαλεγόμενον καὶ παραινοῦντα παύσασθαι τοιαῦτα πολιτευομένους. ἐπηκολούθει δὲ ἡ βουλὴ μετὰ κατηφείας, καὶ τοῦ δήμου τὸ βέλτιστον ἀγανακτοῦν σιωπῇ καὶ ἀχθόμενον, ὥστε τὸν Καίσαρα μὴ λανθάνειν βαρέως φέροντας, ἀλλὰ φιλονεικῶν καὶ περιμένων ὑπὸ τοῦ Κάτωνος ἐπίκλησιν γενέσθαι καὶ δέησιν προῆγεν. ἐπεὶ δὲ ἐκεῖνος ἦν δῆλος οὐδὲ μελλήσων τι ποιεῖν, ἡττηθεὶς ὑπὸ αἰσχύνης καὶ ἀδοξίας ὁ Καῖσαρ αὐτός τινα τῶν δημάρχων ὑφῆκε πείσας ἐξελέσθαι τὸν Κάτωνα. τοῖς μέντοι νόμοις ἐκείνοις καὶ ταῖς χάρισι τιθασεύσαντες τὸν ὄχλον, ἐψηφίσαντο Καίσαρι μὲν Ἰλλυριῶν καὶ Γαλατίας ἀρχὴν ἁπάσης καὶ τέσσαρα τάγματα στρατιᾶς εἰς πενταετίαν, προλέγοντος Κάτωνος ὡς εἰς ἀκρόπολιν τὸν τύραννον αὐτοὶ ταῖς ἑαυτῶν ψήφοις ἱδρύουσι, Πόπλιον δὲ Κλώδιον ἐκ πατρικίων εἰς δημοτικοὺς παρανόμως μεταστήσαντες ἀπέδειξαν δήμαρχον, ἐπὶ μισθῷ τῇ Κικέρωνος ἐξελάσει πάντα πρὸς χάριν ἐκείνοις πολιτευόμενον, ὑπάτους δὲ Πείσωνά τε Καλπούρνιον, ὃς ἦν πατὴρ τῆς Καίσαρος γυναικός, καὶ Γαβίνιον Αὖλον, ἐκ τῶν Πομπηΐου κόλπων ἄνθρωπον, ὥς φασιν οἱ τὸν τρόπον αὐτοῦ καὶ τὸν βίον εἰδότες.", "st": "Cat. Mi. 33.1"}, {"sp": "N", "t": "ἀλλὰ καίπερ οὕτως τὰ πράγματα κατειληφότες ἐγκρατῶς, καὶ τὸ μὲν χάριτι τῆς πόλεως, τὸ δὲ φόβῳ μέρος ὑφ’ ἑαυτοὺς ἔχοντες ὅμως ἐφοβοῦντο τὸν Κάτωνα, καὶ γάρ ἐν οἷς περιῆσαν αὐτοῦ τό γε χαλεπῶς καὶ μετὰ πόνων καὶ μὴ χωρὶς αἰσχύνης, ἀλλ’ ἐλεγχομένους βιάζεσθαι μόλις ἀνιαρὸν ἦν καὶ πρόσαντες. ὁ δὲ Κλώδιος οὐδὲ Κικέρωνα καταλύσειν ἤλπιζε Κάτωνος παρόντος, ἀλλὰ τοῦτο διαμηχανώμενος πρῶτον, ὡς εἰς ἀρχὴν κατέστη, μετεπέμψατο τὸν Κάτωνα καὶ λόγους αὐτῷ προσήνεγκεν ὡς πάντων ἐκεῖνον ἡγούμενος ἄνδρα Ῥωμαίων καθαρώτατον ἔργῳ διδόναι πίστιν ἕτοιμός ἐστι· πολλῶν γὰρ αἰτουμένων τὴν ἐπὶ Κύπρον καὶ Πτολεμαῖον ἀρχὴν καὶ δεομένων ἀποσταλῆναι μόνον ἄξιον ἐκεῖνον ἡγεῖσθαι καὶ διδόναι τὴν χάριν ἡδέως. ἀνακραγόντος δὲ τοῦ Κάτωνος ὡς ἐνέδρα τὸ πρᾶγμα καὶ προπηλακισμός, οὐ χάρις ἐστίν, ὑπερηφάνως ὁ Κλώδιος καὶ ὀλιγώρως, οὐκοῦν, εἶπεν, εἰ μὴ χάριν ἔχεις, ἀνιώμενος πλεύσῃ, καὶ προσελθὼν εὐθὺς εἰς τὸν δῆμον ἐκύρωσε νόμῳ τὴν ἔκπεμψιν τοῦ Κάτωνος, ἐξιόντι δὲ οὐ ναῦν, οὐ στρατιώτην, οὐχ ὑπηρέτην ἔδωκε πλὴν ἢ δύο γραμματεῖς μόνον, ὧν ὁ μὲν κλέπτης καὶ παμπόνηρος, ἅτερος δὲ Κλωδίου πελάτης. ὡς δὲ μικρὸν ἔργον αὐτῷ Κύπρον καὶ Πτολεμαῖον ἀναθείς, ἔτι καὶ Βυζαντίων φυγάδας κατάγειν προσέταξε, βουλόμενος ὅτι πλεῖστον χρόνον ἐκποδὼν ἄρχοντος αὐτοῦ γενέσθαι τὸν Κάτωνα.", "st": "Cat. Mi. 34.1"}, {"sp": "N", "t": "τοιαύτῃ δὲ καταληφθεὶς ἀνάγκῃ Κικέρωνι μὲν ἐλαυνομένῳ παρῄνεσε μὴ στασιάσαι μηδὲ εἰς ὅπλα καὶ φόνους τὴν πόλιν ἐμβαλεῖν, ἀλλ’ ὑπεκστάντα τῷ καιρῷ πάλιν γενέσθαι σωτῆρα τῆς πατρίδος, Κανίδιον δέ τινα τῶν φίλων προπέμψας εἰς Κύπρον ἔπειθε τὸν Πτολεμαῖον ἄνευ μάχης εἴκειν, ὡς οὔτε χρημάτων οὔτε τιμῆς ἐνδεᾶ βιωσόμενον· ἱερωσύνην γὰρ αὐτῷ τῆς ἐν Πάφῳ θεοῦ δώσειν τὸν δῆμον. αὐτὸς δὲ διέτριβεν ἐν Ῥόδῳ παρασκευαζόμενος ἅμα καὶ τὰς ἀποκρίσεις ἀναμένων.", "st": "Cat. Mi. 35.1"}, {"sp": "N", "t": "ἐν δὲ τούτῳ Πτολεμαῖος ὁ Αἰγύπτου βασιλεὺς ὑπ’ ὀργῆς τινος καὶ διαφορᾶς πρὸς τοὺς πολίτας ἀπολελοιπὼς μὲν Ἀλεξάνδρειαν, εἰς δὲ Ῥώμην πλέων, ὡς Πομπηΐου καὶ Καίσαρος αὖθις αὑτὸν μετὰ δυνάμεως καταξόντων, ἐντυχεῖν τῷ Κάτωνι βουληθεὶς προσέπεμψεν, ἐλπίζων ἐκεῖνον ὡς αὑτὸν ἥξειν. ὁ δὲ Κάτων ἐτύγχανε μὲν ὢν τότε περὶ κοιλίας κάθαρσιν, ἥκειν δὲ τὸν Πτολεμαῖον, εἰ βούλοιτο, κελεύσας πρὸς αὐτόν, ὡς δὲ ἦλθεν, οὔτε ἀπαντήσας οὔτε ὑπεξαναστάς, ἀλλ’ ὡς ἕνα τῶν ἐπιτυχόντων ἀσπασάμενος καὶ καθίσαι κελεύσας, πρῶτον αὐτοῖς τούτοις διετάραξε, θαυμάζοντα πρὸς τὸ δημοτικὸν καὶ λιτὸν αὑτοῦ τῆς κατασκευῆς τὴν ὑπεροψίαν καὶ βαρύτητα τοῦ ἤθους. ἐπεὶ δὲ καὶ διαλέγεσθαι περὶ τῶν καθ’ αὑτὸν ἀρξάμενος ἠκροάσατο λόγων νοῦν πολὺν ἐχόντων καὶ παρρησίαν, ἐπιτιμῶντος αὐτῷ τοῦ Κάτωνος καὶ διδάσκοντος ὅσην εὐδαιμονίαν ἀπολιπὼν ὅσαις ἑαυτὸν ὑποτίθησι λατρείαις καὶ πόνοις καὶ δωροδοκίαις καὶ πλεονεξίαις τῶν ἐν Ῥώμῃ δυνατῶν, οὓς μόλις ἐξαργυρισθεῖσαν ἐμπλήσειν Αἴγυπτον, συμβουλεύοντος δὲ πλεῖν ὀπίσω καὶ διαλλάττεσθαι τοῖς πολίταις, αὑτοῦ δὲ καὶ συμπλεῖν καὶ συνδιαλλάττειν ἑτοίμως ἔχοντος, οἷον ἐκ μανίας τινὸς ἢ παρακοπῆς ὑπὸ τῶν λόγων ἔμφρων καθιστάμενος, καὶ κατανοῶν τὴν ἀλήθειαν καὶ τὴν σύνεσιν τοῦ ἀνδρός, ὥρμησε μὲν χρῆσθαι τοῖς ἐκείνου λογισμοῖς, ἀνατραπεὶς δὲ ὑπὸ τῶν φίλων αὖθις ἅμα τῷ πρῶτον ἐν Ῥώμῃ γενέσθαι καὶ θύραις ἑνὸς ἄρχοντος προσελθεῖν ἔστενε τὴν αὑτοῦ κακοβουλίαν, ὡς οὐκ ἀνδρὸς ἀγαθοῦ λόγων, θεοῦ δὲ μαντείας καταφρονήσας.", "st": "Cat. Mi. 35.3"}, {"sp": "N", "t": "ι δὲ ἐν Κύπρῳ Πτολεμαῖος εὐτυχίᾳ τινὶ τοῦ Κάτωνος ἑαυτὸν φαρμάκοις ἀπέκτεινε, πολλῶν δὲ χρημάτων ἀπολελεῖφθαι λεγομένων, αὐτὸς μὲν ἔγνω πλεῖν εἰς Βυζαντίους, πρὸς δὲ τὴν Κύπρον ἐξέπεμψε τὸν ἀδελφιδοῦν Βροῦτον, οὐ πάνυ τι πιστεύων τῷ Κανιδίῳ. τοὺς δὲ φυγάδας διαλλάξας καὶ καταλιπὼν ἐν ὁμονοίᾳ τὸ Βυζάντιον, οὕτως εἰς Κύπρον ἔπλευσεν. οὔσης δὲ πολλῆς καὶ βασιλικῆς ἐν ἐκπώμασι καὶ τραπέζαις καὶ λίθοις καὶ πορφύραις κατασκευῆς, ἣν ἔδει πραθεῖσαν ἐξαργυρισθῆναι, πάντα βουλόμενος ἐξακριβοῦν καὶ πάντα κατατείνειν εἰς ἄκραν τιμὴν καὶ πᾶσιν αὐτὸς παρεῖναι καὶ προσάγειν τὸν ἔσχατον ἐκλογισμόν, οὐδὲ τοῖς ἐθάσι τῆς ἀγορᾶς ἐπίστευεν, ἀλλὰ ὑπονοῶν ὁμοῦ πάντας, ὑπηρέτας, κήρυκας, ὠνητάς, φίλους, τέλος αὐτὸς ἰδίᾳ τοῖς ὠνουμένοις διαλεγόμενος καὶ προσβιβάζων ἕκαστον, οὕτω τὰ πλεῖστα τῶν ἀγορασμάτων ἐπώλει. διὸ τοῖς τε ἄλλοις φίλοις ὡς ἀπιστῶν προσέκρουσε, καὶ τὸν συνηθέστατον ἁπάντων Μουνάτιον εἰς ὀργὴν ὀλίγου δεῖν ἀνήκεστον γενομένην ἐνέβαλεν, ὥστε καὶ Καίσαρι γράφοντι λόγον κατὰ τοῦ Κάτωνος πικροτάτην τοῦτο τὸ μέρος τῆς κατηγορίας διατριβὴν παρασχεῖν.", "st": "Cat. Mi. 36.1"}, {"sp": "N", "t": "ὁ μέντοι Μουνάτιος οὐκ ἀπιστίᾳ τοῦ Κάτωνος, ἀλλ’ ἐκείνου μὲν ὀλιγωρίᾳ πρὸς αὐτὸν, αὐτοῦ δέ τινι ζηλοτυπίᾳ πρὸς τὸν Κανίδιον ἱστορεῖ γενέσθαι τὴν ὀργήν. καὶ γὰρ αὐτὸς σύγγραμμα περὶ τοῦ Κάτωνος ἐξέδωκεν, ᾧ μάλιστα Θρασέας ἐπηκολούθησε. λέγει δὲ ὕστερος μὲν εἰς Κύπρον ἀφικέσθαι καὶ λαβεῖν παρημελημένην ξενίαν, ἐλθὼν δὲ ἐπὶ θύρας ἀπωσθῆναι, σκευωρουμένου τι τοῦ Κάτωνος οἴκοι σὺν τῷ Κανιδίῳ, μεμψάμενος δὲ μετρίως οὐ μετρίας τυχεῖν ἀποκρίσεως, ὅτι κινδυνεύει τὸ λίαν φιλεῖν, ὥς φησι Θεόφραστος, αἴτιον τοῦ μισεῖν γίνεσθαι πολλάκις· ἐπεὶ καὶ σύ, φάναι, τῷ μάλιστα φιλεῖν ἧττον οἰόμενος ἢ προσήκει τιμᾶσθαι χαλεπαίνεις. Κανιδίῳ δὲ καὶ δι’ ἐμπειρίαν χρῶμαι καὶ διὰ πίστιν ἑτέρων μᾶλλον, ἐξ ἀρχῆς μὲν ἀφιγμένῳ, καθαρῷ δὲ φαινομένῳ. ταῦτα μέντοι μόνον αὐτῷ μόνῳ διαλεχθέντα τὸν Κάτωνα πρὸς τὸν Κανίδιον ἐξενεγκεῖν. αἰσθόμενος οὖν αὐτὸς οὔτε ἐπὶ δεῖπνον ἔτι φοιτᾶν οὔτε σύμβουλος ὑπακούειν καλούμενος, ἀπειλοῦντος δὲ τοῦ Κάτωνος, ὥσπερ εἰώθασι τῶν ἀπειθούντων, ἐνέχυρα λήψεσθαι, μηδὲν φροντίσας ἐκπλεῦσαι καὶ πολὺν χρόνον ἐν ὀργῇ διατελεῖν· εἶτα τῆς Μαρκίας ἔτι γὰρ συνῴκει τῷ Κάτωνι διαλεχθείσης, τυχεῖν μὲν ὑπὸ Βάρκα κεκλημένους ἐπὶ δεῖπνον, εἰσελθόντα δὲ ὕστερον τὸν Κάτωνα, τῶν ἄλλων κατακειμένων, ἐρωτᾶν ὅπου κατακλιθείη. τοῦ δὲ Βάρκα κελεύσαντος ὅπου βούλεται, περιβλεψάμενον εἰπεῖν ὅτι παρὰ Μουνάτιον καὶ περιελθόντα πλησίον αὐτοῦ κατακλιθῆναι, πλέον δὲ μηθὲν φιλοφρονήσασθαι παρὰ τὸ δεῖπνον. ἀλλὰ πάλιν τῆς Μαρκίας δεομένης τὸν μὲν Κάτωνα γράψαι πρὸς αὐτὸν, ὡς ἐντυχεῖν τι βουλόμενον, αὐτὸς δὲ ἥκειν ἕωθεν εἰς τὴν οἰκίαν καὶ ὑπὸ τῆς Μαρκίας κατασχεθῆναι μέχρι πάντες ἀπηλλάγησαν, οὕτω δὲ εἰσελθόντα τὸν Κάτωνα καὶ περιβαλόντα τὰς χεῖρας ἀμφοτέρας ἀσπάσασθαι καὶ φιλοφρονεῖσθαι. ταῦτα μὲν οὖν οὐχ ἧττον οἰόμενοι τῶν ὑπαίθρων καὶ μεγάλων πράξεων πρὸς ἔνδειξιν ἤθους καὶ κατανόησιν ἔχειν τινὰ σαφήνειαν ἐπὶ πλέον διήλθομεν.", "st": "Cat. Mi. 37.1"}, {"sp": "N", "t": "τῷ δὲ Κάτωνι συνήχθη μὲν ἀργυρίου τάλαντα μικρὸν ἑπτακισχιλίων ἀποδέοντα, δεδιὼς δὲ τοῦ πλοῦ τὸ μῆκος ἀγγεῖα πολλὰ κατασκευάσας, ὧν ἕκαστον ἐχώρει δύο τάλαντα καὶ δραχμὰς πεντακοσίας, καλώδιον ἑκάστῳ μακρὸν προσήρτησεν, οὗ τῇ ἀρχῇ προσείχετο φελλὸς εὐμεγέθης, ὅπως, εἰ ῥαγείη τὸ πλοῖον, ἔχων διὰ βυθοῦ τὸ ἄρτημα σημαίνοι τὸν τόπον. τὰ μὲν οὖν χρήματα πλὴν ὀλίγων τινῶν ἀσφαλῶς διεκομίσθη, λόγους δὲ πάντων ὧν διῴκησε γεγραμμένους ἐπιμελῶς ἔχων ἐν δυσὶ βιβλίοις οὐδέτερον ἔσωσεν, ἀλλὰ τὸ μὲν ἀπελεύθερος αὐτοῦ κομίζων ὄνομα Φιλάργυρος ἐκ Κεγχρεῶν ἀναχθεὶς ἀνετράπη καὶ συναπώλεσε τοῖς φορτίοις, τὸ δὲ αὐτὸς ἄχρι Κερκύρας φυλάξας ἐν ἀγορᾷ κατεσκήνωσε· τῶν δὲ ναυτῶν διὰ τὸ ῥιγοῦν πυρὰ πολλὰ καιόντων τῆς νυκτός ἥφθησαν αἱ σκηναί καὶ τὸ βιβλίον ἠφανίσθη. τοὺς μὲν οὖν ἐχθροὺς καὶ συκοφάντας ἐπιστομιεῖν ἤμελλον οἱ βασιλικοὶ διοικηταὶ παρόντες, ἄλλως δὲ τῷ Κάτωνι τὸ πρᾶγμα δηγμὸν ἤνεγκεν. οὐ γὰρ εἰς πίστιν ὑπὲρ αὑτοῦ τοὺς λόγους, ἀλλὰ παράδειγμα τοῖς ἄλλοις ἀκριβείας ἐξενεγκεῖν φιλοτιμούμενος ἐνεμεσήθη.", "st": "Cat. Mi. 38.1"}, {"sp": "N", "t": "περαιωθεὶς δὲ ταῖς ναυσὶν οὐκ ἔλαθε τοὺς Ῥωμαίους, ἀλλὰ πάντες μὲν ἄρχοντες καὶ ἱερεῖς, πᾶσα δὲ ἡ βουλή, πολὺ δὲ τοῦ δήμου μέρος ἀπήντων πρὸς τὸν ποταμόν, ὥστε τὰς ὄχθας ἀμφοτέρας ἀποκεκρύφθαι καὶ θριάμβου μηδὲν ὄψει καὶ φιλοτιμίᾳ λείπεσθαι τὸν ἀνάπλουν αὐτοῦ. καίτοι σκαιὸν ἐνίοις τοῦτο ἐφαίνετο καὶ αὔθαδες, ὅτι τῶν ὑπάτων καὶ τῶν στρατηγῶν παρόντων οὔτε ἀπέβη πρὸς αὐτούς οὔτε ἐπέσχε τὸν πλοῦν, ἀλλὰ ῥοθίῳ τὴν ὄχθην παρεξελαύνων ἐπὶ νεὼς ἑξήρους βασιλικῆς οὐκ ἀνῆκε πρότερον ἢ καθορμίσαι τὸν στόλον εἰς τὸ νεώριον. οὐ μὴν ἀλλὰ τῶν χρημάτων παρακομιζομένων δι’ ἀγορᾶς ὅ τε δῆμος ἐθαύμαζε τὸ πλῆθος, ἥ τε βουλὴ συναχθεῖσα μετὰ τῶν πρεπόντων ἐπαίνων ἐψηφίσατο τῷ Κάτωνι, στρατηγίαν ἐξαίρετον δοθῆναι καὶ τὰς θέας αὐτὸν ἐν ἐσθῆτι περιπορφύρῳ θεάσασθαι. ταῦτα μὲν οὖν ὁ Κάτων παρῃτήσατο, Νικίαν δὲ τὸν οἰκονόμον τῶν βασιλικῶν ἐλεύθερον ἔπεισε τὴν βουλὴν ἀφεῖναι, μαρτυρήσας ἐπιμέλειαν καὶ πίστιν. ὑπάτευε δὲ Φίλιππος ὁ πατὴρ τῆς Μαρκίας, καὶ τρόπον τινὰ τὸ ἀξίωμα τῆς ἀρχῆς καὶ ἡ δύναμις εἰς Κάτωνα περιῆλθεν, οὐκ ἐλάττονα τοῦ συνάρχοντος δι’ ἀρετὴν ἢ δι’ οἰκειότητα τοῦ Φιλίππου τῷ Κάτωνι τιμὴν προστιθέντος.", "st": "Cat. Mi. 39.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Κικέρων ἐκ τῆς φυγῆς, ἣν ἔφυγεν ὑπὸ Κλωδίου, κατελθών καὶ δυνάμενος μέγα τὰς δημαρχικὰς δέλτους, ἃς ὁ Κλώδιος ἔθηκεν ἀναγράψας εἰς τὸ Καπιτώλιον, ἀπέσπασε βίᾳ καὶ καθεῖλε τοῦ Κλωδίου μὴ παρόντος, ἐπὶ τούτοις δὲ βουλῆς ἀθροισθείσης καὶ τοῦ Κλωδίου κατηγοροῦντος ἔλεγε παρανόμως τῷ Κλωδίῳ τῆς δημαρχίας γενομένης ἀτελῆ καὶ ἄκυρα δεῖν εἶναι τὰ τότε πραχθέντα καὶ γραφέντα, προσέκρουσεν ὁ Κάτων αὐτῷ λέγοντι, καὶ τέλος ἀναστὰς ἔφη τῆς μὲν Κλωδίου πολιτείας μηδὲν ὑγιὲς μηδὲ χρηστὸν ὅλως νομίζειν, εἰ δὲ ἀναιρεῖ τις ὅσα δημαρχῶν ἔπραξεν, ἀναιρεῖσθαι πᾶσαν αὐτοῦ τὴν περὶ Κύπρον πραγματείαν καὶ μὴ γεγονέναι τὴν ἀποστολὴν νόμιμον ἄρχοντος παρανόμου ψηφισαμένου· παρανόμως μὲν οὐ δήμαρχον αἱρεθῆναι τὸν Κλώδιον ἐκ πατρικίων μεταστάντα νόμου διδόντος εἰς δημοτικὸν οἶκον, εἰ δὲ μοχθηρὸς, ὥσπερ ἄλλοι, γέγονεν ἄρχων, αὐτὸν εὐθύνειν τὸν ἀδικήσαντα, μὴ λύειν τὴν συναδικηθεῖσαν ἀρχὴν εἶναι προσῆκον, ἐκ τούτου δι’ ὀργῆς ὁ Κικέρων ἔσχε τὸν Κάτωνα, καὶ φίλῳ χρώμενος ἐπαύσατο χρόνον πολύν εἶτα μέντοι διηλλάγησαν.", "st": "Cat. Mi. 40.1"}, {"sp": "N", "t": "ἐκ τούτου Πομπήϊος καὶ Κράσσος ὑπερβαλόντι τὰς Ἄλπεις Καίσαρι συγγενόμενοι γνώμην ἐποιήσαντο κοινῇ δευτέραν ὑπατείαν μετιέναι, καὶ καταστάντες εἰς αὐτὴν Καίσαρι μὲν τῆς ἀρχῆς ἄλλον τοσοῦτον ἐπιψηφίζεσθαι χρόνον, αὑτοῖς δὲ τῶν ἐπαρχιῶν τὰς μεγίστας καὶ χρήματα καὶ στρατιωτικὰς δυνάμεις, ὅπερ ἦν ἐπὶ νεμήσει τῆς ἡγεμονίας καὶ καταλύσει τῆς πολιτείας συνωμοσία. πολλῶν δὲ καὶ ἀγαθῶν ἀνδρῶν μετιέναι τὴν ἀρχὴν τότε παρασκευαζομένων, τοὺς μὲν ἄλλους ὀφθέντες ἐν ταῖς παραγγελίαις ἀπέτρεψαν, μόνον δὲ Λεύκιον Δομίτιον Πορκίᾳ συνοικοῦντα τῇ ἀδελφῇ Κάτων ἔπεισε μὴ ἐκστῆναι μηδὲ ὑφέσθαι, τοῦ ἀγῶνος οὐ περὶ ἀρχῆς ὄντος, ἀλλὰ περὶ τῆς Ῥωμαίων ἐλευθερίας. καὶ μέντοι καὶ λόγος ἐχώρει διὰ τοῦ σωφρονοῦντος ἔτι τῆς πόλεως μέρους, ὡς οὐ περιοπτέον, εἰς ταὐτὸ τῆς Κράσσου καὶ Πομπηΐου δυνάμεως συνελθούσης, παντάπασιν ὑπέρογκον καὶ βαρεῖαν τὴν ἀρχὴν γενομένην, ἀλλ’ ἀφαιρετέον αὐτῆς τὸν ἕτερον. καὶ συνίσταντο πρὸς τὸν Δομίτιον παρορμῶντες καὶ παραθαρρύνοντες ἀντιλαμβάνεσθαι· πολλοὺς γὰρ αὐτῷ καὶ τῶν σιωπώντων διὰ δέος ἐν ταῖς ψήφοις ὑπάρξειν.", "st": "Cat. Mi. 41.1"}, {"sp": "N", "t": "τοῦτο δὴ δείσαντες οἱ περὶ τὸν Πομπήϊον ὑφεῖσαν ἐνέδραν τῷ Δομιτίῳ καταβαίνοντι ὄρθριον ὑπὸ λαμπάδων εἰς τὸ πεδίον, καὶ πρῶτος μὲν ὁ προφαίνων ἐπιστὰς τῷ Δομιτίῳ πληγεὶς καὶ πεσὼν ἀπέθανε· μετὰ δὲ τοῦτον ἤδη καὶ τῶν ἄλλων συντιτρωσκομένων ἐγίνετο φυγὴ πλὴν Κάτωνος καὶ Δομιτίου. κατεῖχε γὰρ αὐτὸν ὁ Κάτων, καίπερ αὐτὸς εἰς τὸν βραχίονα τετρωμένος, καὶ παρεκελεύετο μένειν καὶ μὴ προλιπεῖν, ἕως ἐμπνέωσι, τὸν ὑπὲρ τῆς ἐλευθερίας ἀγῶνα πρὸς τοὺς τυράννους, οἳ τίνα τρόπον χρήσονται τῇ ἀρχῇ δηλοῦσι διὰ τηλικούτων ἀδικημάτων ἐπ’ αὐτὴν βαδίζοντες.", "st": "Cat. Mi. 41.4"}, {"sp": "N", "t": "οὐχ ὑποστάντος δὲ τοῦ Δομιτίου τὸ δεινόν, ἀλλ’ εἰς τὴν οἰκίαν καταφυγόντος, ᾑρέθησαν μὲν ὕπατοι Πομπήϊος καὶ Κράσσος, οὐκ ἀπέκαμε δὲ ὁ Κάτων, ἀλλ’ αὐτὸς προελθὼν στρατηγίαν μετῄει, βουλόμενος ὁρμητήριον ἔχειν τῶν πρὸς ἐκείνους ἀγώνων καὶ πρὸς ἄρχοντας ἀντικαθίστασθαι μὴ ἰδιώτης, οἱ δὲ καὶ τοῦτο δείσαντες, ὡς τῆς στρατηγίας ἀξιομάχου διὰ Κάτωνα πρὸς τὴν ὑπατείαν γενησομένης, πρῶτον μὲν ἐξαίφνης καὶ τῶν πολλῶν ἀγνοούντων βουλὴν συναγαγόντες ἐψηφίσαντο τοὺς αἱρεθέντας στρατηγοὺς εὐθὺς ἄρχειν καὶ μὴ διαλιπόντας τὸν νόμιμον χρόνον, ἐν ᾧ δίκαι τοῖς δεκάσασι τὸν δῆμον ἦσαν. ἔπειτα διὰ τοῦ ψηφίσματος τὸ διδόναι ἀνυπεύθυνον κατασκευάσαντες ὑπηρέτας αὑτῶν καὶ φίλους ἐπὶ τὴν στρατηγίαν προῆγον, αὐτοὶ μὲν διδόντες ἀργύριον, αὐτοὶ δὲ ταῖς ψήφοις φερομέναις ἐφεστῶτες. ὡς δὲ καὶ τούτων ἡ Κάτωνος ἀρετὴ καὶ δόξα περιῆν, ὑπ’ αἰδοῦς τῶν πολλῶν ἐν δεινῷ πολλῷ τιθεμένων ἀποδόσθαι Κάτωνα ταῖς ψήφοις, ὃν καλῶς εἶχε πρίασθαι τῇ πόλει στρατηγόν, ἥ τε πρώτη κληθεῖσα τῶν φυλῶν ἐκεῖνον ἀπέδειξεν, ἐξαίφνης ὁ Πομπήϊος βροντῆς ἀκηκοέναι ψευσάμενος αἴσχιστα διέλυσε τὴν ἐκκλησίαν, εἰθισμένων ἀφοσιοῦσθαι τὰ τοιαῦτα καὶ μηδὲν ἐπικυροῦν διοσημίας γενομένης. αὖθις δὲ πολλῷ χρησάμενοι τῷ δεκασμῷ, τοὺς βελτίστους ὤσαντες ἐκ τοῦ πεδίου βίᾳ διεπράξαντο Βατίνιον ἀντὶ Κάτωνος αἱρεθῆναι στρατηγόν. ἔνθα δὴ λέγεται τοὺς μὲν οὕτω παρανόμως καὶ ἀδίκως θεμένους τὴν ψῆφον εὐθὺς ὥσπερ ἀποδράντας οἴχεσθαι, τοῖς δὲ ἄλλοις συνισταμένοις καὶ ἀγανακτοῦσι δημάρχου τινὸς αὐτόθι παρασχόντος ἐκκλησίαν καταστάντα τὸν Κάτωνα ἅπαντα μὲν ὥσπερ ἐκ θεῶν ἐπίπνουν τὰ μέλλοντα τῇ πόλει προειπεῖν, παρορμῆσαι δὲ τοὺς πολίτας ἐπὶ Πομπήϊον καὶ Κράσσον ὡς τοιαῦτα συνειδότας αὑτοῖς, καὶ τοιαύτης ἁπτομένους πολιτείας δι’ ἣν ἔδεισαν Κάτωνα, μὴ στρατηγὸς αὑτῶν περιγένηται. τέλος δὲ ἀπιόντα εἰς τὴν οἰκίαν προὔπεμψε πλῆθος τοσοῦτον ὅσον οὐδὲ σύμπαντας ἅμα τοὺς ἀποδεδειγμένους στρατηγούς.", "st": "Cat. Mi. 42.1"}, {"sp": "N", "t": "Γαΐου δὲ Τρεβωνίου γράψαντος νόμον ὑπὲρ νομῆς ἐπαρχιῶν τοῖς ὑπάτοις, ὥστε τὸν μὲν Ἰβηρίαν ἔχοντα καὶ Λιβύην ὑφ’ αὑτῷ, τὸν δὲ Συρίαν καὶ Αἴγυπτον, οἷς βούλοιντο πολεμεῖν καὶ καταστρέφεσθαι ναυτικαῖς καὶ πεζικαῖς δυνάμεσιν ἐπιόντας, οἱ μὲν ἄλλοι τὴν ἀντίπραξιν καὶ κώλυσιν ἀπεγνωκότες ἐξέλιπον καὶ τὸ ἀντειπεῖν, Κάτωνι δὲ ἀναβάντι πρὸ τῆς ψηφοφορίας ἐπὶ τὸ βῆμα καὶ βουλομένῳ λέγειν μόλις ὡρῶν δυεῖν λόγον ἔδωκαν. ὡς δὲ πολλὰ λέγων καὶ διδάσκων καὶ προθεσπίζων κατανάλωσε τὸν χρόνον, οὐκέτι λέγειν αὐτὸν εἴων, ἀλλ’ ἐπιμένοντα κατέσπασεν ὑπηρέτης προσελθών. ὡς δὲ καὶ κάτωθεν ἱστάμενος ἐβόα καὶ τοὺς ἀκούοντας καὶ συναγανακτοῦντας εἶχε, πάλιν ὁ ὑπηρέτης ἐπιλαβόμενος καὶ ἀγαγὼν αὐτὸν ἔξω τῆς ἀγορᾶς κατέστησε. καὶ οὐκ ἔφθη πρῶτον ἀφεθείς, καὶ πάλιν ἀναστρέψας ἵετο πρὸς τὸ βῆμα μετὰ κραυγῆς ἐγκελευόμενος τοῖς πολίταις ἀμύνειν. πολλάκις δὲ τούτου γενομένου περιπαθῶν ὁ Τρεβώνιος ἐκέλευσεν αὐτὸν εἰς τὸ δεσμωτήριον ἄγεσθαι καὶ πλῆθος ἐπηκολούθει λέγοντος ἅμα σὺν τῷ βαδίζειν ἀκροώμενον, ὥστε δείσαντα τὸν Τρεβώνιον ἀφεῖναι.", "st": "Cat. Mi. 43.1"}, {"sp": "N", "t": "κἀκείνην μὲν οὕτω τὴν ἡμέραν ὁ Κάτων κατανάλωσε· ταῖς δ’ ἐφεξῆς οὓς μὲν δεδιξάμενοι τῶν πολιτῶν, οὓς δὲ συσκευασάμενοι χάρισι καὶ δωροδοκίαις, ἕνα δὲ τῶν δημάρχων Ἀκύλλιον ὅπλοις εἴρξαντες ἐκ τοῦ βουλευτηρίου προελθεῖν, αὐτὸν δὲ τὸν Κάτωνα βροντὴν γεγονέναι βοῶντα τῆς ἀγορᾶς ἐκβαλόντες, οὐκ ὀλίγους δὲ τρώσαντες, ἐνίων δὲ καὶ πεσόντων, βίᾳ τὸν νόμον ἐκύρωσαν, ὥστε πολλοὺς συστραφέντας ὀργῇ τοὺς Πομπηΐου βάλλειν ἀνδριάντας. ἀλλὰ τοῦτο μὲν ἐπελθὼν ὁ Κάτων διεκώλυσε· τῷ δὲ Καίσαρι πάλιν νόμου γραφομένου περὶ τῶν ἐπαρχιῶν καὶ τῶν στρατοπέδων, οὐκέτι πρὸς τὸν δῆμον ὁ Κάτων, ἀλλὰ πρὸς αὐτὸν τραπόμενος Πομπήϊον ἐμαρτύρατο καὶ προὔλεγεν ὡς ἐπὶ τὸν αὑτοῦ τράχηλον ἀναλαμβάνων Καίσαρα νῦν μὲν οὐκ οἶδεν, ὅταν δὲ ἄρχηται βαρύνεσθαι καὶ κρατεῖσθαι μήτε ἀποθέσθαι δυνάμενος μήτε φέρειν ὑπομένων, εἰς τὴν πόλιν ἐμπεσεῖται σὺν αὐτῷ, καὶ μεμνήσεται τότε τῶν Κάτωνος παραινέσεων, ὡς οὐδὲν ἧττον ἐν αὐταῖς τὸ Πομπηΐου συμφέρον ἐνῆν ἢ τὸ καλὸν καὶ δίκαιον. ταῦτα πολλάκις ἀκούων ὁ Πομπήϊος ἠμέλει καὶ παρέπεμπεν ἀπιστίᾳ τῆς Καίσαρος μεταβολῆς διὰ πίστιν εὐτυχίας τῆς ἑαυτοῦ καὶ δυνάμεως.", "st": "Cat. Mi. 43.4"}, {"sp": "N", "t": "εἰς δὲ τὸ ἑξῆς ἔτος αἱρεθεὶς ὁ Κάτων στρατηγός οὐδὲν ἔδοξε προστιθέναι τῇ ἀρχῇ τοσοῦτον εἰς σεμνότητα καὶ μέγεθος ἄρχων καλῶς, ὅσον ἀφαιρεῖν καὶ καταισχύνειν ἀνυπόδητος καὶ ἀχίτων πολλάκις ἐπὶ τὸ βῆμα προερχόμενος καὶ θανατικὰς δίκας ἐπιφανῶν ἀνδρῶν οὕτω βραβεύων. ἔνιοι δέ φασι καὶ μετ’ ἄριστον οἶνον πεπωκότα χρηματίζειν ἀλλὰ τοῦτο μὲν οὐκ ἀληθῶς λέγεται. διαφθειρομένου δὲ τοῦ δήμου ταῖς δωροδοκίαις ὑπὸ τῶν φιλαρχούντων καὶ χρωμένων τῷ δεκάζεσθαι καθάπερ ἐργασίᾳ συνήθει τῶν πολλῶν, βουλόμενος ἐκκόψαι παντάπασι τὸ νόσημα τοῦτο τῆς πόλεως, ἔπεισε δόγμα θέσθαι τὴν σύγκλητον ὅπως οἱ κατασταθέντες ἄρχοντες, εἰ μηδένα κατήγορον ἔχοιεν, αὐτοὶ παριόντες ἐξ ἀνάγκης εἰς ἔνορκον δικαστήριον εὐθύνας διδῶσιν. ἐπὶ τούτῳ χαλεπῶς μὲν ἔσχον οἱ μετιόντες ἀρχάς, ἔτι δὲ χαλεπώτερον ὁ μισθαρνῶν ὄχλος, ἕωθεν οὖν ἐπὶ τὸ βῆμα τοῦ Κάτωνος προελθόντος ἀθρόοι προσπεσόντες ἐβόων, ἐβλασφήμουν, ἔβαλλον, ὥστε φεύγειν ἀπὸ τοῦ βήματος ἅπαντας, αὐτὸν δὲ ἐκεῖνον ἐξωσθέντα τῷ πλήθει καὶ παραφερόμενον μόλις ἐπιλαβέσθαι τῶν ἐμβόλων. ἐντεῦθεν ἀναστὰς τῷ μὲν ἰταμῷ καὶ θαρροῦντι τῆς ὄψεως εὐθὺς ἐκράτησε τοῦ θορύβου καὶ τὴν κραυγὴν ἔπαυσεν, εἰπὼν δὲ τὰ πρέποντα καὶ μεθ’ ἡσυχίας ἀκουσθείς παντάπασι διέλυσε τὴν ταραχήν. ἐπαινούσης δὲ τῆς βουλῆς αὐτόν, ἐγὼ δέ, εἶπεν, ὑμᾶς οὐκ ἐπαινῶ κινδυνεύοντα στρατηγὸν ἐγκαταλιπόντας καὶ μὴ προσαμύναντας.", "st": "Cat. Mi. 44.1"}, {"sp": "N", "t": "τῶν δὲ μετιόντων ἀρχὴν ἕκαστος ἀπόρῳ πάθει συνείχετο, φοβούμενος μὲν αὐτὸς δεκάζειν, φοβούμενος δὲ ἑτέρου τοῦτο πράξαντος ἐκπεσεῖν τῆς ἀρχῆς, ἔδοξεν οὖν αὐτοῖς εἰς ταὐτὸ συνελθοῦσι παραβαλέσθαι δραχμῶν ἕκαστον ἀργυρίου δεκαδύο ἥμισυ μυριάδας, εἶτα μετιέναι τὴν ἀρχὴν πάντας ὀρθῶς καὶ δικαίως. τὸν δὲ παραβάντα καὶ χρησάμενον δεκασμῷ στέρεσθαι τοῦ ἀργυρίου. ταῦτα ὁμολογήσαντες αἱροῦνται φύλακα καὶ βραβευτὴν καὶ μάρτυρα τὸν Κάτωνα καὶ τὰ χρήματα φέροντες ἐκείνῳ παρετίθεντο· καὶ τὰς συνθήκας ἐγράψαντο πρὸς ἐκεῖνον, ἀντὶ τῶν χρημάτων ἐγγυητὰς λαβόντα, τὰ δὲ χρήματα μὴ δεξάμενον. ὡς δὲ ἧκεν ἡ κυρία τῆς ἀναδείξεως, παραστὰς ὁ Κάτων τῷ βραβεύοντι δημάρχῳ καὶ παραφυλάξας τὴν ψῆφον, ἕνα τῶν παραβαλομένων ἀπέφηνε κακουργοῦντα καὶ προσέταξεν ἀποδοῦναι τοῖς ἄλλοις τὸ ἀργύριον. ἀλλ’ ἐκεῖνοι μὲν ἐπαινέσαντες αὐτοῦ τὴν ὀρθότητα καὶ θαυμάσαντες ἀνεῖλον τὸ πρόστιμον ὡς ἱκανὴν δίκην ἔχοντες παρὰ τοῦ ἀδικήσαντος· τοὺς δὲ ἄλλους ἐλύπησεν ὁ Κάτων καὶ φθόνον ἔσχεν ἀπὸ τούτου πλεῖστον, ὡς βουλῆς καὶ δικαστηρίων καὶ ἀρχόντων δύναμιν αὑτῷ περιποιησάμενος.", "st": "Cat. Mi. 44.5"}, {"sp": "N", "t": "οὐδεμιᾶς γὰρ ἀρετῆς δόξα καὶ πίστις ἐπιφθόνους ποιεῖ μᾶλλον ἢ τῆς δικαιοσύνης, ὅτι καὶ δύναμις αὐτῇ καὶ πίστις ἕπεται μάλιστα παρὰ τῶν πολλῶν. οὐ γὰρ τιμῶσι μόνον, ὡς τοὺς ἀνδρείους, οὐδὲ θαυμάζουσιν, ὡς τοὺς φρονίμους, ἀλλὰ καὶ φιλοῦσι τοὺς δικαίους καὶ θαρροῦσιν αὐτοῖς καὶ πιστεύουσιν. ἐκείνων δὲ τοὺς μὲν φοβοῦνται, τοῖς δὲ ἀπιστοῦσι· πρὸς δὲ τούτοις ἐκείνους μὲν οἴονται φύσει μᾶλλον ἢ τῷ βούλεσθαι διαφέρειν, ἀνδρείαν καὶ φρόνησιν, τὴν μὲν ὀξύτητά τινα, τὴν δὲ εὐρωστίαν ψυχῆς τιθέμενοι, δικαίῳ δὲ ὑπάρχοντος εὐθὺς εἶναι τῷ βουλομένῳ μάλιστα τὴν ἀδικίαν ὡς κακίαν ἀπροφάσιστον αἰσχύνονται.", "st": "Cat. Mi. 44.8"}, {"sp": "N", "t": "διὸ καὶ τῷ Κάτωνι πάντες οἱ μεγάλοι προσεπολέμουν ὡς ἐλεγχόμενοι· Πομπήϊος δὲ καὶ κατάλυσιν τῆς ἑαυτοῦ δυνάμεως τὴν ἐκείνου δόξαν ἡγούμενος ἀεί τινας προσέβαλλεν αὐτῷ λοιδορησομένους, ὧν καὶ Κλώδιος ἦν ὁ δημαγωγός, αὖθις εἰς Πομπήϊον ὑπορρυεὶς καὶ καταβοῶν τοῦ Κάτωνος, ὡς πολλὰ μὲν ἐκ Κύπρου χρήματα νοσφισαμένου, Πομπηΐῳ δὲ πολεμοῦντος ἀπαξιώσαντι γάμον αὐτοῦ θυγατρός. ὁ δὲ Κάτων ἔλεγεν ὅτι χρήματα μὲν ἐκ Κύπρου τοσαῦτα τῇ πόλει συναγάγοι μήτε ἵππον ἕνα μήτε στρατιώτην λαβών, ὅσα Πομπήϊος ἐκ πολέμων τοσούτων καὶ θριάμβων τὴν οἰκουμένην κυκήσας οὐκ ἀνήνεγκε, κηδεστὴν δὲ μηδέποτε προελέσθαι Πομπήϊον, οὐκ ἀνάξιον ἡγούμενος, ἀλλ’ ὁρῶν τὴν ἐν τῇ πολιτείᾳ διαφοράν. αὐτὸς μὲν γὰρ, ἔφη, διδομένης μοι μετὰ τὴν στρατηγίαν ἐπαρχίας ἀπέστην, οὗτος δὲ τὰς μὲν ἔχει λαβών, τὰς δὲ δίδωσιν ἑτέροις· νυνὶ δὲ καὶ τέλος ἑξακισχιλίων ὁπλιτῶν Καίσαρι κέχρηκεν εἰς Γαλατίαν ὃ οὔτ’ ἐκεῖνος ᾔτησε παρ’ ὑμῶν οὔτε οὗτος ἔδωκε μεθ’ ὑμῶν, ἀλλὰ δυνάμεις τηλικαῦται καὶ ὅπλα καὶ ἵπποι χάριτές εἰσιν ἰδιωτῶν καὶ ἀντιδόσεις. καλούμενος δὲ αὐτοκράτωρ καὶ στρατηγός ἄλλοις τὰ στρατεύματα καὶ τὰς ἐπαρχίας παραδέδωκεν, αὐτὸς δὲ τῇ πόλει παρακάθηται στάσεις ἀγωνοθετῶν ἐν ταῖς παραγγελίαις καὶ θορύβους μηχανώμενος, ἐξ ὧν οὐ λέληθε δι’ ἀναρχίας μοναρχίαν ἑαυτῷ μνηστευόμενος.", "st": "Cat. Mi. 45.1"}, {"sp": "N", "t": "οὕτως μὲν ἠμύνατο τὸν Πομπήϊον. ἦν δὲ Μᾶρκος Φαώνιος ἑταῖρος αὐτοῦ καὶ ζηλωτής, οἷος ὁ Φαληρεὺς Ἀπολλόδωρος ἱστορεῖται περὶ Σωκράτην γενέσθαι τὸν παλαιόν, ἐμπαθὴς καὶ παρακεκινηκὼς πρὸς τὸν λόγον, οὐ σχέδην οὐδὲ πρᾴως, ἀλλ’ ἄκρατον αὐτοῦ καθαψάμενον ὥσπερ οἶνον καὶ μανικώτερον. οὗτος ἀγορανομίαν μετιὼν ἡττᾶτο, συμπαρὼν δὲ ὁ Κάτων προσέσχε ταῖς δέλτοις μιᾷ χειρὶ γεγραμμέναις· καὶ τὴν κακουργίαν ἐξελέγξας τότε μὲν ἐπικλήσει δημάρχων ἔλυσε τὴν ἀνάδειξιν, ὕστερον δὲ τοῦ Φαωνίου κατασταθέντος ἀγορανόμου τά τε ἄλλα τῆς ἀρχῆς ἐπεμελεῖτο καὶ τὰς θέας διεῖπεν ἐν τῷ θεάτρῳ, διδοὺς καὶ τοῖς θυμελικοῖς στεφάνους μὲν οὐ χρυσοῦς, ἀλλ’ ὥσπερ ἐν Ὀλυμπίᾳ κοτίνων, δῶρα δὲ ἀντὶ τῶν πολυτελῶν τοῖς μὲν Ἕλλησι τεῦτλα καὶ θρίδακας καὶ ῥαφανῖδας καὶ ἀπίους, τοῖς δὲ Ῥωμαίοις οἴνου κεράμια καὶ κρέα ὕεια καὶ σῦκα καὶ σικύους καὶ ξύλων ἀγκαλίδας, ὧν τὴν εὐτέλειαν οἱ μὲν ἐγέλων, οἱ δὲ ᾐδοῦντο τοῦ Κάτωνος τὸ αὐστηρὸν καὶ κατεστυμμένον ὁρῶντες ἡσυχῇ μεταβάλλον εἰς διάχυσιν. τέλος δὲ ὁ Φαώνιος εἰς τὸν ὄχλον ἐμβαλὼν ἑαυτὸν καὶ καθεζόμενος ἐν τοῖς θεαταῖς ἐκρότει τὸν Κάτωνα καὶ διδόναι τοῖς εὐημεροῦσι καὶ τιμᾶν ἐβόα, καὶ συμπαρεκάλει τοὺς θεατάς, ὡς ἐκείνῳ τὴν ἐξουσίαν παραδεδωκώς, ἐν δὲ τῷ ἑτέρῳ θεάτρῳ Κουρίων ὁ Φαωνίου συνάρχων ἐχορήγει πολυτελῶς· ἀλλ’ ἐκεῖνον ἀπολείποντες οἱ ἄνθρωποι μετέβαινον ἐνταῦθα, καὶ συνέπαιζον προθύμως ὑποκρινομένῳ τῷ Φαωνίῳ τὸν ἰδιώτην καὶ τῷ Κάτωνι τὸν ἀγωνοθέτην. ἔπραττε δὲ ταῦτα διασύρων τὸ πρᾶγμα, καὶ διδάσκων ὅτι παίζοντα δεῖ τῇ παιδιᾷ χρῆσθαι καὶ χάριτι παραπέμπειν ἀτύφῳ μᾶλλον ἢ παρασκευαῖς καὶ πολυτελείαις, εἰς τὰ μηδενὸς ἄξια φροντίδας μεγάλας καὶ σπουδὰς κατατιθέμενον.", "st": "Cat. Mi. 46.1"}, {"sp": "N", "t": "ἐπεὶ δὲ, Σκηπίωνος καὶ Ὑψαίου καὶ Μίλωνος ὑπατείαν μετερχομένων οὐ μόνον ἐκείνοις τοῖς συντρόφοις ἤδη καὶ συμπολιτευομένοις ἀδικήμασι, δωροδοκίαις καὶ δεκασμοῖς, ἀλλ’ ἄντικρυς δι’ ὅπλων καὶ φόνων εἰς ἐμφύλιον πόλεμον ὠθουμένων τόλμῃ καὶ ἀπονοίᾳ, Πομπήϊόν τινες ἠξίουν ἐπιστῆναι ταῖς ἀρχαιρεσίαις, τὸ μὲν πρῶτον ἀντεῖπεν ὁ Κάτων, οὐ τοῖς νόμοις ἐκ Πομπηΐου φάμενος, ἀλλ’ ἐκ τῶν νόμων Πομπηΐῳ δεῖν ὑπάρχειν τὴν ἀσφάλειαν, ὡς δὲ πολὺν χρόνον ἀναρχίας οὔσης καὶ τριῶν στρατοπέδων τὴν ἀγορὰν ὁσημέραι περιεχόντων ὀλίγον ἀπέλιπεν ἀνεπίσχετον γεγονέναι τὸ κακόν, ἔγνω τὰ πράγματα πρὸ τῆς ἐσχάτης ἀνάγκης εἰς Πομπήϊον ἑκουσίῳ χάριτι τῆς βουλῆς περιστῆσαι, καὶ τῷ μετριωτάτῳ τῶν παρανομημάτων χρησάμενος ἰάματι τῆς τῶν μεγίστων καταστάσεως τὴν μοναρχίαν ἐπαγαγέσθαι μᾶλλον ἢ περιϊδεῖν τὴν στάσιν εἰς μοναρχίαν τελευτῶσαν. εἶπεν οὖν ἐν τῇ βουλῇ γνώμην Βύβλος οἰκεῖος ὢν Κάτωνος, ὡς χρὴ μόνον ἑλέσθαι Πομπήϊον ὕπατον ἢ γὰρ ἕξειν καλῶς τὰ πράγματα ἐκείνου καταστήσαντος, ἢ τῷ κρατίστῳ δουλεύσειν τὴν πόλιν. ἀναστὰς δὲ ὁ Κάτων οὐδενὸς ἂν προσδοκήσαντος ἐπῄνεσε τὴν γνώμην καὶ συνεβούλευσε πᾶσαν ἀρχὴν ὡς ἀναρχίας κρείττονα, Πομπήϊον δὲ καὶ προσδοκᾶν ἄριστα τοῖς παροῦσι χρήσεσθαι πράγμασι καὶ φυλάξειν διαπιστευθέντα τὴν πόλιν.", "st": "Cat. Mi. 47.1"}, {"sp": "N", "t": "οὕτω δ’ ἀποδειχθεὶς ὕπατος ὁ Πομπήϊος ἐδεήθη τοῦ Κάτωνος ἐλθεῖν πρὸς αὐτὸν εἰς τὸ προάστειον. ἐλθόντα δὲ δεξάμενος φιλοφρόνως ἀσπασμοῖς καὶ δεξιώσεσι καὶ χάριν ὁμολογήσας παρεκάλει σύμβουλον αὑτῷ καὶ πάρεδρον εἶναι τῆς ἀρχῆς. ὁ δὲ Κάτων ἀπεκρίνατο μήτε τὰ πρῶτα πρὸς ἀπέχθειαν εἰπεῖν Πομπηΐου μήτε ταῦτα πρὸς χάριν, ἀλλ’ ἐπὶ συμφέροντι πάντα τῆς πόλεως· ἰδίᾳ μὲν οὖν αὐτῷ παρακαλοῦντι σύμβουλος ἔσεσθαι, δημοσίᾳ, δέ, κἂν μὴ παρακαλῆται, πάντως ἐρεῖν τὸ φαινόμενον. καὶ ταῦτα ἔπραττεν ὡς εἶπε. πρῶτον μὲν γὰρ ἐπὶ τοὺς δεκάσαντας ἤδη τὸν δῆμον ἐπιτίμια καινὰ καὶ δίκας μεγάλας τοῦ Πομπηΐου νομοθετοῦντος ἀμελεῖν ἐκέλευσε τῶν γεγονότων καὶ προσέχειν τοῖς μέλλουσιν· οὔτε γὰρ ὅπου στήσεται τὸ τὰ προημαρτημένα ζητεῖν ὁρίσαι ῥᾴδιον, ἐάν τε νεώτερα γράφηται τῶν ἀδικημάτων ἐπιτίμια, δεινὰ πείσεσθαι τοὺς, ὃν οὐ παρέβαινον ὅτ’ ἠδίκουν νόμον, κατὰ τοῦτον κολαζομένους. ἔπειτα πολλῶν κρινομένων ἐπιφανῶν ἀνδρῶν, ἐνίων δὲ καὶ φίλων τοῦ Πομπηΐου καὶ οἰκείων, ὁρῶν αὐτὸν ἐνδιδόντα ἐν πολλοῖς καὶ καμπτόμενον ἐπετίμα σφοδρῶς καὶ διήγειρεν. ἐπεὶ δὲ νόμῳ τοὺς εἰωθότας λέγεσθαι περὶ τῶν κρινομένων ἐπαίνους αὐτὸς ἀφελών, Μουνατίῳ Πλάγκῳ συγγράψας ἔπαινον ἐπὶ τῆς δίκης ἔδωκεν, ἐπισχόμενος ὁ Κάτων τὰ ὦτα ταῖς χερσὶν (ἔτυχε γὰρ δικάζων) ἐκώλυεν ἀναγινώσκεσθαι τὴν μαρτυρίαν. ὁ δὲ Πλάγκος ἀπέλεξεν αὐτὸν ἐκ τῶν δικαστῶν μετὰ τοὺς λόγους, καὶ οὐδὲν ἧττον ἥλω. καὶ ὅλως ἄπορον ἦν πρᾶγμα καὶ δυσμεταχείριστον ὁ Κάτων τοῖς φεύγουσι, μήτε βουλομένοις αὐτὸν ἀπολιπεῖν δικαστήν μήτε ἀπολέγειν τολμῶσιν. ἥλωσαν γὰρ οὐκ ὀλίγοι τῷ Κάτωνα φεύγειν δόξαντες οὐ θαρρεῖν τοῖς δικαίοις· ἐνίοις δὲ καὶ προὔφερον οἱ λοιδοροῦντες ὡς ὄνειδος μέγα τὸ μὴ δέξασθαι κριτὴν Κάτωνα προτεινόμενον.", "st": "Cat. Mi. 48.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Καίσαρος αὑτοῦ μὲν ἐμπεφυκότος τοῖς στρατεύμασιν ἐν Γαλατίᾳ καὶ τῶν ὅπλων ἐχομένου, δώροις δὲ καὶ χρήμασι καὶ φίλοις μάλιστα πρὸς τὴν ἐν τῇ πόλει χρωμένου δύναμιν, ἤδη μὲν αἱ Κάτωνος προαγορεύσεις ἀνέφερον τὸν Πομπήϊον ἐκ πολλῆς ἤδη τῆς πρόσθεν ἀπιστίας ὀνειροπολοῦντα τὸ δεινόν, ἔτι δὲ ἦν ὄκνου καὶ μελλήσεως ἀτόλμου πρὸς τὸ κωλύειν καὶ ἐπιχειρεῖν ὑπόπλεως, ὥρμησεν ὁ Κάτων ὑπατείαν παραγγέλλειν ὡς ἀφαιρησόμενος εὐθὺς τὰ ὅπλα τοῦ Καίσαρος ἢ τὴν ἐπιβουλὴν ἐξελέγξων. οἱ δ’ ἀντιπαραγγέλλοντες αὐτῷ χαρίεντες μὲν ἦσαν ἀμφότεροι, Σουλπίκιος δὲ καὶ πολλὰ τῆς τοῦ Κάτωνος ἐν τῇ πόλει δόξης τε καὶ δυνάμεως ἀπολελαυκώς· οὐ μέτριον οὖν ἐδόκει πρᾶγμα ποιεῖν οὐδ’ εὐχάριστον οὐ μὴν ὅ γε Κάτων ἐνεκάλει· τί γὰρ, ἔφη, θαυμαστόν εἰ ὅ τις νομίζει τῶν ἀγαθῶν μέγιστον ἑτέρῳ μὴ παρίησι; πείσας δὲ τὴν βουλὴν ψηφίσασθαι τοὺς μετιόντας τὴν ἀρχὴν αὐτοὺς δεξιοῦσθαι τὸν δῆμον, δι’ ἑτέρου δὲ μὴ δεῖσθαι μηδὲ ἐντυγχάνειν ὑπὲρ αὐτῶν περιιόντος, ἔτι μᾶλλον ἐξηγρίανε τοὺς ἀνθρώπους, εἰ μὴ μόνον τὸ λαβεῖν μισθόν, ἀλλὰ καὶ τὸ διδόναι χάριν αὐτοὺς ἀφῃρημένος ἄπορον καὶ ἄτιμον ὁμοῦ τὸν δῆμον πεποίηκε. πρὸς δὲ τούτῳ μήτε αὐτὸς ἐντυχεῖν ὑπὲρ αὑτοῦ πιθανὸς ὤν, ἀλλ’ ἐν ἤθει τὸ τοῦ βίου μᾶλλον ἀξίωμα βουλόμενος φυλάσσειν ἢ προσλαβεῖν τὸ τῆς ἀρχῆς ποιούμενος τὰς δεξιώσεις, μήτε τοὺς φίλους ἐάσας οἷς ὄχλος ἁλίσκεται καὶ θεραπεύεται ποιεῖν, ἀπέτυχε τῆς ἀρχῆς.", "st": "Cat. Mi. 49.1"}, {"sp": "N", "t": "φέροντος δὲ τοῦ πράγματος οὐκ αὐτοῖς μόνοις τοῖς ἀποτυχοῦσιν, ἀλλὰ καὶ φίλοις αὐτῶν καὶ οἰκείοις σὺν αἰσχύνῃ τινὶ κατήφειαν καὶ πένθος ἐφ’ ἡμέρας πολλάς, οὕτως ἤνεγκε ῥᾳθύμως τὸ συμβεβηκός ὥστε ἀλειψάμενος μὲν ἐν τῷ πεδίῳ σφαιρίσαι, μετ’ ἄριστον δὲ πάλιν, ὥσπερ εἴθιστο, καταβὰς εἰς ἀγορὰν ἀνυπόδητος καὶ ἀχίτων περιπατῆσαι μετὰ τῶν συνήθων. αἰτιᾶται δὲ Κικέρων ὅτι, τῶν πραγμάτων ἄρχοντος τοιούτου δεομένων, οὐκ ἐποιήσατο σπουδὴν οὐδὲ ὑπῆλθεν ὁμιλίᾳ φιλανθρώπῳ τὸν δῆμον, ἀλλὰ καὶ πρὸς τὸ λοιπὸν ἐξέκαμε καὶ ἀπηγόρευσε, καίτοι τὴν στρατηγίαν αὖθις ἐξ ὑπαρχῆς μετελθών. ἔλεγεν οὖν ὁ Κάτων ὅτι τῆς μὲν στρατηγίας οὐ κατὰ γνώμην ἐξέπεσε τῶν πολλῶν, ἀλλὰ βιασθέντων ἢ διαφθαρέντων, ἐν δὲ ταῖς ὑπατικαῖς ψήφοις μηδεμιᾶς κακουργίας γενομένης ἔγνω καὶ τῷ δήμῳ προσκεκρουκὼς διὰ τὸν αὑτοῦ τρόπον, ὃν οὔτε μεταθέσθαι πρὸς ἑτέρων χάριν οὔτε χρώμενον ὁμοίῳ πάλιν ὅμοια παθεῖν νοῦν ἔχοντος ἀνδρός ἐστι·", "st": "Cat. Mi. 50.1"}, {"sp": "N", "t": "τοῦ δὲ Καίσαρος ἐμβαλόντος εἰς ἔθνη μάχιμα καὶ παραβόλως κρατήσαντος, Γερμανοῖς δὲ καὶ σπονδῶν γενομένων δοκοῦντος ἐπιθέσθαι καὶ καταβαλεῖν τριάκοντα μυριάδας, οἱ μὲν ἄλλοι τὸν δῆμον ἠξίουν εὐαγγέλια θύειν, ὁ δὲ Κάτων ἐκέλευεν ἐκδιδόναι τὸν Καίσαρα τοῖς παρανομηθεῖσι καὶ μὴ τρέπειν εἰς αὑτοὺς μηδὲ ἀναδέχεσθαι τὸ ἄγος εἰς τὴν πόλιν. οὐ μὴν ἀλλὰ καὶ τοῖς θεοῖς, ἔφη, θύωμεν, ὅτι τῆς τοῦ στρατηγοῦ μανίας καὶ ἀπονοίας τὴν δίκην εἰς τοὺς στρατιώτας οὐ τρέπουσιν, ἀλλὰ φείδονται τῆς πόλεως. ἐκ τούτου Καῖσαρ ἐπιστολὴν γράψας ἀπέστειλεν εἰς τὴν σύγκλητον· ὡς δὲ ἀνεγνώσθη βλασφημίας πολλὰς ἔχουσα καὶ κατηγορίας τοῦ Κάτωνος, ἀναστὰς ἐκεῖνος οὐχ ὑπ’ ὀργῆς οὐδὲ φιλονεικίας, ἀλλ’ ὥσπερ ἐκ λογισμοῦ καὶ παρασκευῆς τὰ μὲν εἰς ἑαυτὸν ἐγκλήματα λοιδορίαις καὶ σκώμμασιν ὅμοια καὶ παιδιάν τινα καὶ βωμολοχίαν τοῦ Καίσαρος ἀπέδειξεν, ἁψάμενος δὲ τῶν ἐκείνου βουλευμάτων ἀπ’ ἀρχῆς καὶ πᾶσαν αὐτοῦ τὴν διάνοιαν, ὥσπερ οὐκ ἐχθρός, ἀλλὰ συνωμότης καὶ κοινωνὸς, ἐκκαλύψας, καὶ διδάξας ὡς οὐ Γερμανῶν οὐδὲ Κελτῶν παῖδας, ἀλλ’ ἐκεῖνον αὐτὸν, εἰ σωφρονοῦσι, φοβητέον ἐστὶν αὐτοῖς, οὕτως ἐπέστρεψε καὶ παρώξυνεν ὡς τοὺς φίλους τοῦ Καίσαρος μετανοεῖν, ὅτι τὴν ἐπιστολὴν ἀναγνόντες ἐν τῇ βουλῇ καιρὸν τῷ Κάτωνι λόγων δικαίων καὶ κατηγοριῶν ἀληθῶν παρέσχον, Ἐκυρώθη μὲν οὖν οὐδέν, ἀλλ’ ἐλέχθη μόνον ὅτι καλῶς ἔχει διάδοχον Καίσαρι δοθῆναι. τῶν δὲ φίλων ἀξιούντων καὶ Πομπήϊον ἐξ ἴσου τὰ ὅπλα καταθέσθαι καὶ ἀποδοῦναι τὰς ἐπαρχίας ἢ μηδὲ Καίσαρα, νῦν ἐκεῖνα βοῶν ὁ Κάτων ἃ προὔλεγεν αὐτοῖς ἥκειν, καὶ βιάζεσθαι τὸν ἄνθρωπον ἀναφανδὸν ἤδη τῇ δυνάμει χρώμενον ἣν ἔσχεν ἐξαπατῶν καὶ φενακίζων τὴν πόλιν, ἔξω μὲν οὐδὲν ἐπέραινε, τοῦ δήμου θέλοντος ἀεὶ τὸν Καίσαρα μέγιστον εἶναι, τὴν δὲ σύγκλητον εἶχε πειθομένην καὶ φοβουμένην τὸν δῆμον.", "st": "Cat. Mi. 51.1"}, {"sp": "N", "t": "ὡς δὲ Ἀρίμινον κατείληπτο καὶ Καῖσαρ κατηγγέλλετο μετὰ στρατιᾶς ἐλαύνειν ἐπὶ τὴν πόλιν, ἐνταῦθα δὴ πάντες ἐπ’ ἐκεῖνον ἀφεώρων, οἵ τε πολλοὶ καὶ Πομπήϊος, ὡς μόνον μὲν ἐξ ἀρχῆς προαισθόμενον, πρῶτον δὲ φανερῶς προειπόντα τὴν Καίσαρος γνώμην. εἶπεν οὖν ὁ Κάτων· ἀλλὰ εἴ γε οἷς ἐγὼ προὔλεγον ἀεὶ καὶ συνεβούλευον ἐπείσθη τις ὑμῶν, ἄνδρες, οὔτ’ ἂν ἕνα ἐφοβεῖσθε νῦν οὔτε ἐν ἑνὶ τὰς ἐλπίδας εἴχετε. Πομπηΐου δὲ εἰπόντος μαντικώτερα μὲν εἰρῆσθαι Κάτωνι, φιλικώτερα δὲ αὐτῷ πεπρᾶχθαι, συνεβούλευεν ὁ Κάτων ἑνὶ Πομπηΐῳ τὰ πράγματα τὴν σύγκλητον ἐγχειρίσαι· τῶν γὰρ αὐτῶν εἶναι καὶ ποιεῖν τὰ μεγάλα κακὰ καὶ παύειν. ὁ μὲν οὖν Πομπήϊος οὔτε δύναμιν ἔχων ἑτοίμην οὔτε οὓς κατέλεγε τότε προθύμους ὁρῶν ἐξέλιπε τὴν Ῥώμην, ὁ δὲ Κάτων ἕπεσθαι καὶ συμφεύγειν ἐγνωκώς τὸν μὲν νεώτερον υἱὸν εἰς Βρεττίους ὑπεξέθετο πρὸς Μουνάτιον, τὸν δὲ πρεσβύτερον εἶχε σὺν ἑαυτῷ. τῆς οἰκίας καὶ τῶν θυγατέρων κηδεμόνος δεομένων ἀνέλαβε πάλιν τὴν Μαρκίαν χηρεύουσαν ἐπὶ χρήμασι πολλοῖς· ὁ γὰρ Ὁρτήσιος θνῄσκων ἐκείνην ἀπέλιπε κληρονόμον. εἰς ὃ δὴ μάλιστα λοιδορούμενος ὁ Καῖσαρ τῷ Κάτωνι φιλοπλουτίαν προφέρει καὶ μισθαρνίαν ἐπὶ τῷ γάμῳ. τί γὰρ ἔδει παραχωρεῖν δεόμενον γυναικός ἢ τί μὴ δεόμενον αὖθις ἀναλαμβάνειν, εἰ μὴ δέλεαρ ἐξ ἀρχῆς ὑφείθη τὸ γύναιον Ὁρτησίῳ καὶ νέαν ἔχρησεν, ἵνα πλουσίαν ἀπολάβῃ; πρὸς μὲν οὖν ταῦτα μετρίως ἔχει τὸ Εὐριπίδειον ἐκεῖνο·<br>πρῶτον μὲν οὖν τἄρρητ’· ἐν ἀρρήτοισι γὰρ", "st": "Cat. Mi. 52.1"}, {"sp": "N", "t": "τὴν σὴν νομίζω δειλίαν, ὦ Ἡράκλεις·", "st": "Cat. Mi. 52.1b"}, {"sp": "N", "t": "ὅμοιον γάρ ἐστι τῷ Ἡρακλεῖ μαλακίαν ὀνειδίζειν καὶ κατηγορεῖν αἰσχροκέρδειαν Κάτωνος, εἰ δὲ ἄλλῃ πη μὴ καλῶς πέπρακται τὰ περὶ τὸν γάμον, ἐπισκεπτέον. ἐγγυησάμενος γὰρ τὴν Μαρκίαν ὁ Κάτων, καὶ τὸν οἶκον ἐπιτρέψας ἐκείνῃ καὶ τὰς θυγατέρας, αὐτὸς ἐδίωκε Πομπήϊον.", "st": "Cat. Mi. 52.5"}, {"sp": "N", "t": "ἀπ’ ἐκείνης δὲ λέγεται τῆς ἡμέρας μήτε κεφαλὴν ἔτι κείρασθαι μήτε γένεια μήτε στέφανον ἐπιθέσθαι, πένθους δὲ καὶ κατηφείας καὶ βαρύτητος ἐπὶ ταῖς συμφοραῖς τῆς πατρίδος ἓν σχῆμα νικώντων ὁμοίως καὶ νικωμένων ἄχρι τελευτῆς διαφυλάξαι. τότε δὲ κλήρῳ λαχὼν Σικελίαν διέβη μὲν εἰς Συρακούσας, πυθόμενος δὲ Ἀσίννιον Πολλίωνα παρὰ τῶν πολεμίων ἀφῖχθαι μετὰ δυνάμεως εἰς Μεσσήνην ἔπεμψε, λόγον ἀπαιτῶν παρ’ αὐτοῦ τῆς διαβάσεως. ἀνταπαιτηθεὶς δὲ λόγον ὑπ’ ἐκείνου τῆς τῶν πραγμάτων μεταβολῆς, καὶ Πομπήϊον ἀκούσας ἐκλελοιπότα παντελῶς Ἰταλίαν ἐν Δυρραχίῳ στρατοπεδεύειν, πολὺν ἔφη περὶ τὰ θεῖα πλάνον εἶναι καὶ ἀσάφειαν, εἰ Πομπήϊον ἐν οἷς ὑγιὲς οὐδὲν οὐδὲ δίκαιον ἔπραττεν ἀήττητον γενόμενον νῦν, ὅτε τὴν πατρίδα βούλεται σῴζειν καὶ τῆς ἐλευθερίας ὑπερμάχεται, προλέλοιπε τὸ εὐτυχεῖν. Ἀσίννιον μὲν οὖν ἔφη δυνατὸς εἶναι Σικελίας ἐκβαλεῖν, ἄλλης δὲ μείζονος ἐπερχομένης δυνάμεως οὐ βούλεσθαι τὴν νῆσον ἐμπολεμῶν ἀπολέσαι, χωρεῖν δὲ πρὸς τὸ κρατοῦν καὶ σῴζεσθαι παραινέσας Συρακουσίοις ἐξέπλευσεν.", "st": "Cat. Mi. 53.1"}, {"sp": "N", "t": "ἀφικόμενος δὲ πρὸς Πομπήϊον ἀεὶ μὲν εἴχετο μιᾶς γνώμης, χρονοτριβεῖν τὸν πόλεμον, ἐλπίζων διαλύσεις καὶ μὴ βουλόμενος ἐν ἀγῶνι χείρω γενομένην τὴν πόλιν αὐτὴν ὑφ’ αὑτῆς παθεῖν τὰ ἔσχατα, σιδήρῳ διακριθεῖσαν. ἄλλα δὲ τούτων ἀδελφὰ Πομπήϊον ἔπεισε καὶ τοὺς συνέδρους ψηφίσασθαι, μήτε πόλιν ὑπήκοον Ῥωμαίων διαρπάζειν μήτε ἄνδρα Ῥωμαῖον ἔξω παρατάξεως ἀναιρεῖν ἃ καὶ δόξαν ἤνεγκε καὶ προσηγάγετο πολλοὺς τῇ Πομπηΐου μερίδι, τὴν ἐπιείκειαν αὐτοῦ καὶ τὸ ἥμερον ἀσπασαμένους.", "st": "Cat. Mi. 53.4"}, {"sp": "N", "t": "ἐκπεμφθεὶς δὲ εἰς Ἀσίαν, ὡς τοῖς ἐκεῖ συνάγουσι πλοῖα καὶ στρατιὰν ὠφέλιμος γένοιτο, Σερβιλίαν ἐπηγάγετο τὴν ἀδελφὴν καὶ τὸ Λευκούλλου παιδίον ἐξ ἐκείνης γεγονός, ἠκολούθησε γὰρ αὐτῷ χηρεύουσα, καὶ πολὺ τῶν εἰς τὸ ἀκόλαστον αὐτῆς διαβολῶν ἀφεῖλεν ὑποδῦσα τὴν ὑπὸ Κάτωνι φρουρὰν καὶ πλάνην καὶ δίαιταν ἑκουσίως. ἀλλ’ ὅ γε Καῖσαρ οὐδὲ τῶν ἐπ’ ἐκείνῃ βλασφημιῶν τοῦ Κάτωνος ἐφείσατο.", "st": "Cat. Mi. 54.1"}, {"sp": "N", "t": "πρὸς μὲν οὖν τἆλλα τοῦ Κάτωνος οὐδὲν, ὡς ἔοικεν, ἐδεήθησαν οἱ Πομπηΐου στρατηγοί, Ῥοδίους δὲ πειθοῖ προσαγαγόμενος καὶ τὴν Σερβιλίαν αὐτόθι καὶ τὸ παιδίον ἀπολιπών ἐπανῆλθε πρὸς Πομπήϊον, ἤδη πεζικῆς τε λαμπρᾶς καὶ ναυτικῆς δυνάμεως περὶ αὐτὸν οὔσης. ἔνθα δὴ καὶ μάλιστα τῆς γνώμης κατάφωρος ἔδοξε γεγονέναι Πομπήϊος, ὥρμησε μὲν γὰρ ἐγχειρίσαι τῷ Κάτωνι τὴν τῶν νεῶν ἡγεμονίαν ἦσαν δὲ πεντακοσίων μὲν οὐκ ἐλάττους αἱ μάχιμοι, λιβυρνικὰ δὲ καὶ κατασκοπικὰ καὶ ἄφρακτα παμπληθῆ· ταχὺ δὲ ἐννοήσας ἢ διδαχθεὶς ὑπὸ τῶν φίλων ὡς ἕν ἐστι κεφάλαιον Κάτωνι πάσης πολιτείας ἐλευθερῶσαι τὴν πατρίδα, κἂν γένηται κύριος τηλικαύτης δυνάμεως, ἧς ἂν ἡμέρας καταγωνίσωνται Καίσαρα, τῆς αὐτῆς ἐκείνης ἀξιώσει καὶ Πομπήϊον τὰ ὅπλα καταθέσθαι καὶ τοῖς νόμοις ἕπεσθαι, μετέγνω, καίπερ ἤδη διειλεγμένος αὐτῷ, καὶ Βύβλον ἀπέδειξε ναύαρχον. οὐ μὴν ᾔσθετό γε παρὰ τοῦτο τῆς προθυμίας τοῦ Κάτωνος ἀμβλυτέρας· ἀλλὰ καὶ λέγεται πρός τινα μάχην πρὸ τὸν Δυρραχίου αὐτοῦ τε Πομπηΐου παρορμῶντος τὴν δύναμιν, καὶ τῶν ἄλλων ἕκαστον ἡγεμόνων εἰπεῖν τι καὶ προτρέψασθαι κελεύοντος, ἀργῶς καὶ σιωπῇ τοὺς στρατιώτας ἀκούειν, Κάτωνος δὲ μετὰ πάντας ὅσα καιρὸν εἶχε τῶν ἀπὸ φιλοσοφίας ἀκούειν λεγομένων περὶ ἐλευθερίας καὶ ἀρετῆς καὶ θανάτου καὶ δόξης διελθόντος αὐτοπαθῶς, καὶ τελευτῶντα τρέψαντος τὸν λόγον εἰς θεῶν ἀνάκλησιν, ὡς παρόντων καὶ ἐφορώντων τὸν ὑπὲρ τῆς πατρίδος ἀγῶνα, τηλικοῦτον ἀλαλαγμὸν γενέσθαι καὶ τοσοῦτον κίνημα τῆς στρατιᾶς ἐπαρθείσης ὥστε πάντας ἐλπίδων μεστοὺς ἐπὶ τὸν κίνδυνον ὁρμῆσαι τοὺς ἡγεμόνας, τρεψαμένων δὲ καὶ κρατησάντων ἀφείλετο τὴν παντελῆ νίκην ὁ Καίσαρος δαίμων, τῇ Πομπηΐου χρησάμενος εὐλαβείᾳ καὶ ἀπιστίᾳ περὶ τὸ εὐτύχημα. ταῦτα μὲν οὖν ἐν τοῖς περὶ Πομπηΐου γέγραπται. χαιρόντων δὲ πάντων καὶ μεγαλυνόντων τὸ ἔργον ὁ Κάτων ἀπεδάκρυε τὴν πατρίδα, καὶ τὴν ὀλέθριον καὶ κακοδαίμονα φιλαρχίαν ὠδύρετο, πολλοὺς καὶ ἀγαθοὺς ὁρῶν πολίτας ὑπ’ ἀλλήλων πεπτωκότας.", "st": "Cat. Mi. 54.3"}, {"sp": "N", "t": "ἐπεὶ δὲ Καίσαρα διώκων Πομπήϊος εἰς Θεσσαλίαν ἀνεζεύγνυε πολλὰ καταλιπὼν περὶ Δυρράχιον ὅπλα καὶ χρήματα καὶ σώματα συγγενῆ καὶ οἰκεῖα, πάντων ἀπέδειξεν ἡγεμόνα καὶ φύλακα τὸν Κάτωνα πεντεκαίδεκα σπείρας ἔχοντα στρατιωτῶν διὰ πίστιν ἅμα καὶ φόβον τοῦ ἀνδρός, ἡττωμένῳ μὲν γὰρ πάντων εἶναι βεβαιότατον ἐνόμιζεν, εἰ δὲ νικῴη, μὴ ἐπιτρέψειν παρόντα χρήσασθαι τοῖς πράγμασιν ὡς προῄρηται. πολλοὶ δὲ καὶ τῶν ἐπιφανῶν ἀνδρῶν ἀπερρίφησαν ἐν Δυρραχίῳ μετὰ Κάτωνος.", "st": "Cat. Mi. 55.1"}, {"sp": "N", "t": "γενομένης δὲ τῆς κατὰ Φάρσαλον ἥττης οὕτως ἔστη τοῖς λογισμοῖς ὁ Κάτων ὡς, εἰ μὲν τεθνήκοι Πομπήϊος, εἰς Ἰταλίαν τοὺς σὺν αὐτῷ περαιώσων, αὐτὸς δὲ πορρωτάτω τῆς τυραννίδος ἐπὶ φυγῇ βιωσόμενος. εἰ δὲ σῴζοιτο, πάντως ἐκείνῳ διαφυλάξων τὴν δύναμιν. οὕτω δὴ διαβαλὼν εἰς Κέρκυραν, ὅπου τὸ ναυτικὸν ἦν, ἐξίστατο μὲν Κικέρωνι τῆς ἀρχῆς ὡς ὑπατικῷ στρατηγικός, οὐ δεξαμένου δὲ Κικέρωνος, ἀλλ’ ἀπαίροντος εἰς Ἰταλίαν, ἰδὼν τὸν Πομπήϊον ὑπ’ αὐθαδείας καὶ φρονήματος ἀκαίρου βουλόμενον κολάζειν τοὺς ἀποπλέοντας, πρώτῳ δὲ μέλλοντα τῷ Κικέρωνι προσφέρειν τὰς χεῖρας, ἐνουθέτησεν ἰδίᾳ καὶ κατεπράϋνεν, ὥστε τὸν Κικέρωνα περισῶσαι σαφῶς ἐκ θανάτου καὶ τοῖς ἄλλοις ἄδειαν παρασχεῖν.", "st": "Cat. Mi. 55.3"}, {"sp": "N", "t": "τεκμαιρόμενος δὲ Πομπήϊον Μᾶγνον εἰς Αἴγυπτον ἢ Λιβύην διεκπεσεῖσθαι καὶ σπεύδων πρὸς ἐκεῖνον ἀνήχθη μὲν ἔχων ἅπαντας, ἔπλει δὲ πρῶτον ἀπιέναι διδοὺς καὶ ὑπολείπεσθαι τοὺς οὐ προθύμως συστρατευομένους, ἁψάμενος δὲ Λιβύης καὶ παραπλέων ἐντυγχάνει Σέξτῳ τῷ νεωτέρῳ τῶν Πομπηΐου παίδων ἀγγέλλοντι τὴν ἐπ’ Αἰγύπτου τοῦ πατρὸς τελευτήν. πάντες μὲν οὖν βαρέως ἤνεγκαν, οὐδεὶς δὲ μετὰ Πομπήϊον ἠξίου Κάτωνος παρόντος οὐδὲ ἀκούειν ἄλλον ἡγεμόνα, διὸ καὶ Κάτων αἰδούμενος καὶ οἰκτείρων ἄνδρας ἀγαθοὺς καὶ πίστεως δεδωκότας πεῖραν ἐπὶ ξένης ἐρήμους καὶ ἀπόρους ἀπολιπεῖν, ὑπέστη τε τὴν ἀρχὴν καὶ παρῆλθεν εἰς Κυρήνην· ἐδέξαντο γὰρ ἐκεῖνον, ὀλίγαις ἡμέραις ἔμπροσθεν ἀποκλείσαντες Λαβιηνόν. ἐνταῦθα πυνθανόμενος Σκηπίωνα τὸν Πομπηΐου πενθερὸν ὑπὸ Ἰόβα τοῦ βασιλέως ἀνειλῆφθαι, καὶ Οὔαρον Ἄττιον, ὃς ἦν ὑπὸ Πομπηΐου Λιβύης ἀποδεδειγμένος ἡγεμών, εἶναι σὺν αὐτοῖς μετὰ δυνάμεως, ἐξώρμησε πεζῇ χειμῶνος ὥρᾳ, πολλοὺς μὲν ὄνους ὕδωρ κομίζοντας συναγαγών, πολλὴν δὲ λείαν ἐλαύνων, ἔτι δὲ ἅρματα καὶ τοὺς καλουμένους Ψύλλους ἐπαγόμενος, οἳ τά τε δήγματα τῶν θηρίων ἰῶνται τοῖς στόμασιν ἕλκοντες τὸν ἰόν, αὐτά τε τὰ θηρία κατεπᾴδοντες ἀμβλύνουσι καὶ κηλοῦσιν. ἡμέρας δὲ συνεχῶς ἑπτὰ τῆς πορείας γενομένης πρῶτος ἡγήσατο μήτε ἵππῳ μήτε ὑποζυγίῳ χρησάμενος. ἐδείπνει δὲ καθήμενος ἀφ’ ἧς ἡμέρας τὴν κατὰ Φάρσαλον ἧτταν ἔγνω καὶ τοῦτο τῷ λοιπῷ προσέθηκε πένθει, τὸ μὴ κατακλιθῆναι πλὴν καθεύδων. ἐν δὲ Λιβύῃ διαγαγὼν τοῦ χειμῶνος ἐξήγαγε τὴν στρατιάν ἦσαν δὲ μυρίων ὀλίγον ἀποδέοντες.", "st": "Cat. Mi. 56.1"}, {"sp": "N", "t": "τὰ δὲ πράγματα κακῶς εἶχε τοῖς περὶ Σκηπίωνα καί Οὐᾶρον, ἐκ διαφορᾶς καί στάσεως ὑποδυομένοις καί θεραπεύουσι τὸν Ἰόβαν, οὐκ ἀνεκτὸν ὄντα βαρύτητι φρονήματος καί ὄγκῳ διὰ πλοῦτον καί δύναμιν ὅς γε Κάτωνι πρῶτον ἐντυγχάνειν μέλλων μέσον ἔθηκε τὸν ἑαυτοῦ θρόνον τοῦ Σκηπίωνος καί τοῦ Κάτωνος. ὁ μέντοι Κάτων ὡς εἶδεν, ἄρας τὸν ἑαυτοῦ μετέθηκεν ἐπὶ θάτερα, μέσον λαμβάνων τὸν Σκηπίωνα, καίπερ ἐχθρὸν ὄντα καί τι καί βιβλίον ἐκδεδωκότα βλασφημίας ἔχον τοῦ Κάτωνος, εἶτα τοῦτο μὲν εἰς οὐδένα τίθενται λόγον, εἰ δὲ Φιλόστρατον ἐν Σικελίᾳ μέσον εἶχε περιπατῶν ἐπὶ τιμῇ φιλοσοφίας, ἐγκαλοῦσι. τότε δ’ οὖν καί τὸν Ἰόβαν ἔπαυσε μονονουχὶ σατράπας πεποιημένον ἑαυτοῦ τοὺς περὶ τὸν Σκηπίωνα, κἀκείνους διήλλαξεν. ἀξιούντων δὲ πάντων ἄρχειν αὐτόν, καὶ πρώτων τῶν περὶ Σκηπίωνα καί Οὐᾶρον ἐξισταμένων καί παραδιδόντων τὴν ἡγεμονίαν, οὐκ ἔφη καταλύσειν τοὺς νόμους περὶ ὧν τῷ καταλύοντι πολεμοῦσιν, οὐδὲ ἑαυτὸν ἀντιστράτηγον ὄντα παρόντος ἀνθυπάτου προτάξειν. ἀνθύπατος γὰρ ὁ Σκηπίων ἀπεδέδεικτο, καί θάρσος εἶχον οἱ πολλοὶ διὰ τοὔνομα, κατορθώσειν ἄρχοντος ἐν Λιβύῃ Σκηπίωνος.", "st": "Cat. Mi. 57.1"}, {"sp": "N", "t": "ἐπεὶ μέντοι τὴν ἀρχὴν ὁ Σκηπίων παραλαβὼν εὐθὺς ἐβούλετο Ἰόβᾳ χαριζόμενος Ἰτυκαίους ἡβηδὸν ἀποκτεῖναι καί κατασκάψαι τὴν πόλιν ὡς τὰ Καίσαρος φρονοῦσαν, οὐχ ὑπέμεινεν ὁ Κάτων, ἀλλὰ μαρτυρόμενος καί κεκραγὼς ἐν τῷ συνεδρίῳ καί θεοκλυτῶν μόλις ἐξείλετο τῆς ὠμότητος αὐτῶν τοὺς ἀνθρώπους· καί τὰ μὲν αὐτῶν δεηθέντων, τὰ δὲ τοῦ Σκηπίωνος ἀξιοῦντος, ἀνεδέξατο φρουρήσειν τὴν πόλιν, ὡς μήτε ἄκουσα μήτε ἑκοῦσα Καίσαρι προσγένοιτο. καί γὰρ ἦν εἰς ἅπαντα τὸ χωρίον ὠφέλιμον καί διαρκὲς τοῖς ἔχουσιν ἔτι δὲ μᾶλλον ὑπὸ τοῦ Κάτωνος ἐρρώσθη. καί γὰρ σῖτον εἰσήγαγεν ὑπερβάλλοντα πλήθει καί κατεσκεύαζε τὰ τείχη πύργους ἐπαιρόμενος καί τάφρους ὀχυρὰς καί χαρακώματα πρὸ τῆς πόλεως βαλλόμενος. Ἰτυκαίων δὲ τοὺς μὲν ἡβῶντας ἐν τοῖς χαρακώμασιν ἔταξεν οἰκεῖν, τὰ ὅπλα παραδόντας αὐτῷ, τοὺς δὲ ἄλλους ἐν τῇ πόλει συνεῖχεν, ἰσχυρῶς ἐπιμελόμενος μὴ ἀδικεῖσθαι μηδὲ πάσχειν κακῶς ὑπὸ τῶν Ῥωμαίων. ὅπλα δὲ πολλὰ καί χρήματα καί σῖτον ἐξέπεμψε τοῖς ἐπὶ στρατοπέδου, καί ὅλως εἶχε τοῦ πολέμου τὴν πόλιν ταμιεῖον. ἃ δὲ Πομπηΐῳ συνεβούλευε πρότερον καί τότε Σκηπίωνι, μὴ μάχεσθαι πρὸς ἄνδρα πολεμιστὴν καί δεινόν, ἀλλὰ τῷ χρόνῳ χρῆσθαι πᾶσαν ἀκμὴν ᾗ τυραννὶς ἰσχύει μαραίνοντι, τούτων ὁ Σκηπίων ὑπὸ αὐθαδείας κατεφρόνει· καί ποτε τῷ Κάτωνι δειλίαν ὀνειδίζων ἔγραψεν, εἰ μὴ μόνον αὐτὸς ἀγαπᾷ καθήμενος ἐν πόλει καί τείχεσιν, ἀλλὰ μηδὲ ἑτέρους ἐᾷ πρὸς τὸν καιρὸν εὐθαρσῶς χρῆσθαι τοῖς λογισμοῖς. πρὸς ταῦτα ὁ Κάτων ἀντέγραψεν ὡς ἕτοιμός ἐστιν οὓς ἤγαγεν αὐτὸς εἰς Λιβύην ὁπλίτας καί ἱππεῖς παραλαβὼν εἰς Ἰταλίαν περαιοῦν, καί Καίσαρα μεθιστάναι καί τρέπειν ἀπ’ ἐκείνων πρὸς αὑτόν, ὡς δὲ καί τούτων ὁ Σκηπίων κατεγέλα, πάνυ δῆλος ἦν ἀχθόμενος ὁ Κάτων τῇ παραχωρήσει τῆς ἀρχῆς, ὡς οὔτε τῷ πολέμῳ καλῶς τὸν Σκηπίωνα χρησόμενον, οὔτε, ἂν παραλόγως εὐτυχήσῃ, μέτριον ἐν τῷ κρατεῖν πρὸς τοὺς πολίτας ἐσόμενον. διὸ καὶ γνώμην εἶχεν ὁ Κάτων, καὶ πρὸς τοὺς συνήθεις ἔλεγεν, οὐ χρηστὰς μὲν ἐλπίδας ἔχειν ὑπὲρ τοῦ πολέμου δι’ ἀπειρίαν καί θρασύτητα τῶν ἡγεμόνων, εἰ δ’ οὖν εὐτυχία τις γένοιτο καί καταλυθείη Καῖσαρ, οὐ μενεῖν ἐν Ῥώμῃ, φεύξεσθαι δὲ τὴν χαλεπότητα καί πικρίαν τοῦ Σκηπίωνος, ἤδη τότε δεινὰς καί ὑπερηφάνους ποιουμένου κατὰ πολλῶν ἀπειλάς.", "st": "Cat. Mi. 58.1"}, {"sp": "N", "t": "ἀπέβη δὲ μᾶλλον ἢ προσεδόκα· καί περὶ ἑσπέραν βαθεῖαν ἧκέ τις ἀπὸ στρατοπέδου τριταῖος ἀγγέλλων ὅτι μάχης μεγάλης πρὸς Θάψῳ γενομένης διέφθαρται παντάπασι τὰ πράγματα καὶ κρατεῖ Καῖσαρ τῶν στρατοπέδων, Σκηπίων δὲ καί Ἰόβας σὺν ὀλίγοις ἐκπεφεύγασιν, ἡ δὲ ἄλλη δύναμις ἀπόλωλε.", "st": "Cat. Mi. 58.7"}, {"sp": "N", "t": "τούτων προσπεσόντων ἡ μὲν πόλις, οἷον εἰκὸς ἐν νυκτὶ καὶ πολέμῳ, πρὸς τοιοῦτον ἄγγελμα μικροῦ δεῖν ἔκφρων γενομένη μόλις ἑαυτὴν ἐντὸς τειχῶν κατεῖχεν, ὁ δὲ Κάτων προελθὼν τότε μέν, ὡς ἑκάστοις ἀπήντα διαθέουσι καὶ βοῶσιν, ἐπιλαμβανόμενος καὶ παραμυθούμενος ἀφῄρει τοῦ δέους τὸ περιθαμβὲς καὶ ταραχῶδες, ὡς οὐ τηλικούτων ἴσως γεγονότων, ἀλλὰ ἐπὶ μεῖζον αἰρομένων τῷ λόγῳ, καὶ κατέστησε τὸν θόρυβον· ἅμα δ’ ἡμέρᾳ τοὺς τριακοσίους οἷς ἐχρῆτο βουλῇ, Ῥωμαίους μὲν ὄντας, ἐν δὲ Λιβύῃ πραγματευομένους ἀπὸ ἐμπορίας καὶ δανεισμῶν, εἰς ἱερὸν Διὸς ἐκήρυττε συνιέναι, καὶ ὅσοι παρῆσαν ἀπὸ συγκλήτου, καὶ παῖδας αὑτῶν, ἔτι δὲ συλλεγομένων ἐκείνων προσελθὼν ἀθορύβως καὶ μετὰ εὐσταθείας, ὥσπερ οὐδενὸς καινοῦ γεγονότος, βιβλίον ἔχων ἐν ταῖς χερσὶν ἀνεγίνωσκεν.", "st": "Cat. Mi. 59.1"}, {"sp": "N", "t": "ἦν δὲ ἀναγραφὴ τῶν πρὸς τὸν πόλεμον ὀργάνων, ὅπλων, σίτου, τόξων, ὁπλιτῶν. ἐπεὶ δὲ συνῆλθον, ἀρξάμενος ἀπὸ τῶν τριακοσίων καὶ διελθὼν πολὺν ἔπαινον τῆς προθυμίας αὑτῶν καὶ τῆς πίστεως, ἣν ἐπεδείξαντο καὶ χρήμασι καὶ σώμασι καὶ βουλαῖς ὠφελιμώτατοι γενόμενοι, παρεκάλει μὴ διαλυθῆναι ταῖς ἐλπίσιν ἕκαστον αὑτῷ φυγὴν ἰδίαν ἢ ἀπόδρασίν τινα ποριζόμενον. ἂν γὰρ ἐν ταὐτῷ συμμένωσι, καὶ πολεμούντων ἧττον καταφρονήσειν Καίσαρα, καὶ φείσεσθαι μᾶλλον δεομένων.", "st": "Cat. Mi. 59.3"}, {"sp": "N", "t": "βουλεύεσθαι δ’ ἐκέλευεν αὐτοὺς ὑπὲρ αὑτῶν, οὐδέτερα μεμψόμενος, ἀλλ’ εἰ μὲν τρέποιντο τῇ γνώμῃ πρὸς τὴν τύχην, τῆς ἀνάγκης θησόμενος τὴν μεταβολήν ἱσταμένων δὲ πρὸς τὰ δεινὰ καὶ δεχομένων τὸν ὑπὲρ τῆς ἐλευθερίας κίνδυνον, οὐκ ἐπαινεσόμενος μόνον, ἀλλὰ καὶ θαυμασόμενος τὴν ἀρετὴν, καὶ παρέξων ἑαυτὸν ἄρχοντα καὶ συναγωνιζόμενον, ἄχρι οὗ τὴν ἐσχάτην τύχην τῆς πατρίδος ἐξελέγξωσιν, ἣν οὐκ Ἰτύκην οὐδὲ Ἀδρούμητον οὖσαν, ἀλλὰ Ῥώμην, πολλάκις ἐκ χαλεπωτέρων σφαλμάτων ὑπὸ μεγέθους ἀναφέρεσθαι, πολλῶν δ’ αὐτοῖς εἰς σωτηρίαν καὶ ἀσφάλειαν ὑποκειμένων, καὶ μεγίστου πρὸς ἄνδρα πολεμεῖν ἐπὶ πολλὰ τοῖς καιροῖς ἀνθελκόμενον, Ἰβηρίας τε πρὸς Πομπήϊον ἀφεστώσης τὸν νέον,", "st": "Cat. Mi. 59.4"}, {"sp": "N", "t": "αὐτῆς τε τῆς Ῥώμης οὔπω δι’ ἀήθειαν παντάπασι δεδεγμένης τὸν χαλινόν, ἀλλ’ ἀναξιοπαθούσης καὶ συνεξανισταμένης πρὸς πᾶσαν μεταβολήν, οὐδὲ τὸν κίνδυνον εἶναι φευκτέον, ἀλλὰ ἔχειν διδάσκαλον τὸν πολέμιον ἀφειδοῦντα τῆς ψυχῆς ἐπὶ ταῖς μεγίσταις ἀδικίαις, οὐχ ὥσπερ ἑαυτοῖς εἰς τὸν εὐτυχέστατον βίον κατορθοῦσιν ἢ πταίουσιν εἰς τὸν εὐκλεέστατον θάνατον τὴν ἀδηλότητα τοῦ πολέμου τελευτᾶν. οὐ μὴν ἀλλ’ ἐκείνους γε δεῖν ἔφη βουλεύεσθαι καθ’ ἑαυτούς, συνευχόμενος ἀντὶ τῆς πρόσθεν ἀρετῆς καὶ προθυμίας αὐτοῖς τὰ δόξαντα συνενεγκεῖν.", "st": "Cat. Mi. 59.6"}, {"sp": "N", "t": "τοιαῦτα τοῦ Κάτωνος εἰπόντος, ἦσαν μὲν οἱ καὶ τοῖς λόγοις ἀγόμενοι πρὸς τὸ θαρρεῖν, οἱ δὲ πλεῖστοι πρὸς τὸ ἀδεὲς καὶ γενναῖον αὐτοῦ καὶ φιλάνθρωπον ὀλίγου δεῖν ἐκλαθόμενοι τῶν παρόντων, ὡς μόνον ὄντα τοῦτον ἀήττητον ἡγεμόνα καὶ πάσης κρείττονα τύχης, ἐδέοντο χρῆσθαι καὶ σώμασιν αὐτῶν καὶ χρήμασι καὶ ὅπλοις, ὅπως αὐτὸς ἔγνωκε· κρεῖττον γὰρ ἐκείνῳ πειθομένους ἀποθανεῖν ἢ σώζεσθαι προδόντας ἀρετὴν τοσαύτην.", "st": "Cat. Mi. 60.1"}, {"sp": "N", "t": "εἰπόντος δέ τινος ὡς χρὴ ψηφίσασθαι δούλοις ἐλευθερίαν, καὶ τῶν πλείστων συνεπαινεσάντων, οὐκ ἔφη τοῦτο ποιήσειν ὁ Κάτων οὐ γὰρ εἶναι νόμιμον οὐδὲ δίκαιον, αὐτῶν μέντοι τῶν δεσποτῶν ἀφιέντων τοὺς ἐν ἡλικίᾳ δέχεσθαι. γενομένων δὲ πολλῶν ὑποσχέσεων κελεύσας ἀπογράφεσθαι τὸν βουλόμενον ἀπηλλάττετο. καὶ μετὰ μικρὸν ἧκεν αὐτῷ γράμματα παρὰ Ἰόβα καὶ Σκηπίωνος, Ἰόβα μὲν ἐν ὄρει κεκρυμμένου μετ’ ὀλίγων ἐρωτῶντος ὅ τι πράττειν δέδοκται τῷ Κάτωνι· καὶ γὰρ περιμενεῖν Ἰτύκην ἐκλιπόντα καὶ πολιορκουμένῳ μετὰ στρατιᾶς ἐπιβοηθήσειν, Σκηπίωνος δὲ πρὸς ἄκρᾳ τινὶ ναυλοχοῦντος οὐ πόρρω τῆς Ἰτύκης ἐπὶ τοῖς αὐτοῖς καραδοκοῦντος.", "st": "Cat. Mi. 60.2"}, {"sp": "N", "t": "ἔδοξεν οὖν τῷ Κάτωνι τοὺς γραμματοφόρους ἐπισχεῖν, ἄχρι οὗ βεβαιώσῃ τὰ παρὰ τῶν τριακοσίων, οἱ μὲν γὰρ ἀπὸ βουλῆς ἦσαν πρόθυμοι, καὶ τοὺς οἰκέτας εὐθὺς ἀφιέντες ἐλευθέρους ὥπλιζον τῶν δὲ τριακοσίων, ἅτε δὴ πλωτικῶν καὶ δανειστικῶν ἀνθρώπων καὶ τὸ πλεῖστον ἐν τοῖς οἰκέταις τῆς οὐσίας ἐχόντων, οὐ πολὺν οἱ Κάτωνος λόγοι χρόνον ἐμμείναντες ἐξερρύησαν· καθάπερ γὰρ τῶν σωμάτων τὰ μανὰ δέχεται ῥᾳδίως τὴν θερμότητα καὶ πάλιν μεθίησι, τοῦ πυρὸς ἀπαχθέντος ψυχούμενα, παραπλησίως ἐκείνους ὁ μὲν Κάτων ὁρώμενος ἀνεζωπύρει καὶ διεθέρμαινεν, αὐτοὺς δὲ ἑαυτοῖς λόγον διδόντας ὁ Καίσαρος φόβος ἐξέκρουσε τῆς πρὸς Κάτωνα καὶ τὸ καλὸν αἰδοῦς. τίνες γὰρ, ἔφασαν, ὄντες, τίνι τὸ προστασσόμενον ποιεῖν ἀπαξιοῦμεν; οὐχὶ Καῖσαρ μὲν οὗτος εἰς ὃν ἡ Ῥωμαίων ἅπασα περιέστηκεν ἰσχύς; ἡμῶν δὲ Σκηπίων οὐδεὶς οὐδὲ Πομπήϊος οὐδὲ Κάτων, ἀλλὰ ἐν οἷς καιροῖς πάντες ἄνθρωποι ταπεινότερα τῶν προσηκόντων διὰ φόβον φρονοῦσιν, ἐν τούτοις ἡμεῖς ὑπερμαχοῦντες τῆς Ῥωμαίων ἐλευθερίας πολεμοῦμεν ἐξ Ἰτύκης ᾧ Κάτων μετὰ Πομπηΐου Μάγνου φεύγων ὑφεῖτο τῆς Ἰταλίας; καὶ δούλους ἐλευθεροῦμεν κατὰ Καίσαρος, οἷς αὐτοῖς ἐλευθερίας, ὅσον ἂν ἐκεῖνος θέλῃ, μέτεστιν; ἀλλ’ ἔτι νῦν, ὦ μοχθηροὶ, γνόντες ἑαυτοὺς παραιτώμεθα τὸν κρατοῦντα καὶ πέμψωμεν τοὺς δεησομένους.", "st": "Cat. Mi. 61.1"}, {"sp": "N", "t": "ταῦτα οἱ μετριώτατοι τῶν τριακοσίων παρῄνουν οἱ δὲ πλεῖστοι τοῖς συγκλητικοῖς ἐπεβούλευον, ὡς, εἰ τούτους συλλάβοιεν, ἱλασόμενοι τὴν πρὸς αὐτοὺς ὀργὴν τοῦ Καίσαρος.", "st": "Cat. Mi. 61.4"}, {"sp": "N", "t": "δὲ Κάτων ’ὑπονοῶν τὴν μεταβολὴν οὐκ ἤλεγχε, τῷ μέντοι Σκηπίωνι καὶ τῷ Ἰόβᾳ γράψας ἀπέχεσθαι τῆς Ἰτύκης ἀπιστίᾳ Τῶν τριακοσίων ἐξέπεμψε τοὺς γραμματοφόρους. τῶν δὲ ἱππέων οἱ διαφυγόντες ἀπὸ τῆς μάχης, ἀριθμὸς οὐκ εὐκαταφρόνητος, προσελάσαντες τῇ Ἰτύκῃ πέμπουσι πρὸς τὸν Κάτωνα τρεῖς ἄνδρας οὐ τὴν αὐτὴν γνώμην ἀπὸ πάντων ἔχοντας. οἱ μὲν γὰρ ἀπιέναι πρὸς Ἰόβαν, οἱ δὲ τῷ Κάτωνι προσχωρεῖν ὥρμηντο, τοὺς δὲ καὶ δέος εἶχεν εἰς Ἰτύκην παριέναι. ταῦτα ὁ Κάτων ἀκούσας τοῖς μὲν τριακοσίοις ἐκέλευσε προσέχειν Μᾶρκον Ῥούβριον, ἀτρέμα τὰς ἀπογραφὰς Τῶν ἐλευθερούντων δεχόμενον καὶ μὴ προσβιαζόμενον, αὐτὸς δὲ τοὺς συγκλητικοὺς ἀναλαβὼν προῆλθεν ἔξω τῆς Ἰτύκης, καὶ τοῖς ἱππάρχοις ἐνέτυχε δεόμενος μὴ προέσθαι Ῥωμαίων ἄνδρας ἀπὸ βουλῆς τοσούτους μηδὲ Ἰόβαν ἑλέσθαι στρατηγὸν ἀντὶ Κάτωνος, ἀλλὰ σῴζεσθαι κοινῇ καὶ σῴζειν, παρελθόντας εἰς πόλιν οὔτε κατὰ κράτος ἁλώσιμον εἰς ἔτη τε πάμπολλα σῖτον καὶ τὴν ἄλλην παρασκευὴν ἔχουσαν. ταῦτα δὲ καὶ Τῶν συγκλητικῶν δεομένων καὶ δακρυόντων οἱ μὲν ἵππαρχοι διελέγοντο τοῖς ἱππεῦσιν, ὁ δὲ Κάτων ἐπὶ χώματός τινος καθίσας μετὰ Τῶν συγκλητικῶν ἀνέμενε τὰς ἀποκρίσεις.", "st": "Cat. Mi. 62.1"}, {"sp": "N", "t": "ἐν δὲ τούτῳ παρῆν ὁ Ῥούβριος σὺν ὀργῇ κατηγορῶν τῶν τριακοσίων ἀκοσμίαν πολλὴν καὶ θόρυβον, ὡς ἀφισταμένων καὶ διαταραττόντων τὴν πόλιν. ἐφ’ οἷς οἱ μὲν ἄλλοι παντάπασιν ἀπογνόντες ἑαυτῶν εἰς δάκρυα καὶ ὀδυρμοὺς ἐξέπεσον, ὁ δὲ Κάτων ἐκείνους τε θαρσύνειν ἐπειρᾶτο καὶ πρὸς τοὺς τριακοσίους ἔπεμψεν ἀναμεῖναι κελεύων. οἱ δὲ ἀπὸ τῶν ἱππέων ἧκον οὐ μέτρια προστάττοντες· ἔφασαν γὰρ οὔτε Ἰόβα δεῖσθαι μισθοδοτοῦντος οὔτε Καίσαρα φοβεῖσθαι Κάτωνος αὐτῶν ἄρχοντος, Ἰτυκαίοις δέ, Φοίνιξιν ἀνθρώποις εὐμεταβόλοις, συγκαθείργνυσθαι δεινὸν εἶναι· καὶ γὰρ εἰ νῦν ἀτρεμοῦσιν, ὅταν Καῖσαρ ἐπίῃ, συνεπιθήσεσθαι καὶ προδώσειν. εἴπερ οὖν δεῖταί τις αὐτῶν συμπολεμούντων καὶ συμπαρόντων, ἐκβαλὼν ἅπαντας Ἰτυκαίους ἢ διαφθείρας, οὕτως εἰς πόλιν καθαρὰν πολεμίων καὶ βαρβάρων καλείτω. ταῦτα ὁ Κάτων ἄγρια μὲν δεινῶς ἡγεῖτο καὶ βάρβαρα, πρᾴως δὲ ἀπεκρίνατο βουλεύσεσθαι μετὰ τῶν τριακοσίων.", "st": "Cat. Mi. 63.1"}, {"sp": "N", "t": "καὶ παρελθὼν αὖθις εἰς τὴν πόλιν ἐνετύγχανε τοῖς ἀνδράσιν οὐκέτι σκήψεις οὐδὲ παραγωγὰς πλασσομένοις ὑπ’ αἰδοῦς πρὸς αὐτόν, ἄντικρυς δέ χαλεπαίνουσιν εἴ τις αὐτοὺς βιάζοιτο πολεμεῖν Καίσαρι μὴ δυναμένους μηδὲ βουλομένους· ἔνιοι δὲ καὶ παρεφθέγγοντο περὶ τῶν συγκλητικῶν, ὡς καθεκτέον ἐν τῇ πόλει Καίσαρος προσιόντος. ἀλλὰ τοῦτο μὲν ὡς οὐκ ἀκούσας ὁ Κάτων παρῆκε· καὶ γὰρ ἦν ὑποκωφότερος· ὡς δέ τις αὐτῷ προσελθὼν ἀπήγγειλε τοὺς μὲν ἱππεῖς ἀπιέναι, φοβηθεὶς μὴ παντάπασιν οἱ τριακόσιοι κατὰ τῶν συγκλητικῶν ἀπονοηθῶσιν, ἐβάδιζε μετὰ τῶν φίλων ἐξαναστάς· καὶ θεασάμενος ἤδη προκεχωρηκότας ἵππον λαβὼν ἐδίωκε πρὸς αὐτούς. οἱ δὲ ἰδόντες ἄσμενοι προσελαύνοντα καὶ ἐδέξαντο καὶ παρεκάλουν σῴζεσθαι μετ’ αὐτῶν, τότε καὶ δακρῦσαι τὸν Κάτωνά φασιν ὑπὲρ τῶν συγκλητικῶν δεόμενον καὶ προτείνοντα τὰς χεῖρας, ἐνίων δὲ καὶ τοὺς ἵππους ἀναστρέφοντα καὶ τῶν ὅπλων ἀντιλαμβανόμενον, μέχρι οὗ κατειργάσατο τὴν γοῦν ἡμέραν ἐκείνην ἐπιμείναντας ἀσφαλῆ τοῖς ἀνδράσι φυγὴν παρασχεῖν.", "st": "Cat. Mi. 63.4"}, {"sp": "N", "t": "ὡς οὖν ἔχων αὐτούς ἀφίκετο καὶ τοὺς μὲν ἐπὶ τὰς πύλας κατέστησε, τοῖς δὲ τὴν ἄκραν φυλάττειν παρέδωκεν, ἔδεισαν οἱ τριακόσιοι μὴ δίκην δῶσι τῆς μεταβολῆς· καὶ πρὸς τὸν Κάτωνα πέμποντες ἐδέοντο πάντως ἀφικέσθαι πρὸς αὑτούς, οἱ δὲ συγκλητικοὶ περιχυθέντες οὐκ εἴων, οὐδὲ ἔφασαν προήσεσθαι τὸν κηδεμόνα καὶ σωτῆρα τοῖς ἀπίστοις καὶ προδόταις. σαφεστάτη γὰρ, ὡς ἔοικεν, αἴσθησις τότε παρέστη καὶ πόθος καὶ θαῦμα τῆς τοῦ Κάτωνος ἀρετῆς πᾶσιν ὁμαλῶς τοῖς ἐν τῇ Ἰτύκῃ γενομένοις, ὡς οὐδὲν ἄρα κίβδηλον οὐδὲ ἀπατηλὸν ἐμέμικτο τοῖς πραττομένοις ὑπ’ αὐτοῦ.", "st": "Cat. Mi. 64.1"}, {"sp": "N", "t": "πάλαι δὲ ἅνθρωπος ἑαυτὸν ἐγνωκὼς ἀνελεῖν δεινοὺς πόνους ἐπόνει καὶ φροντίδας καὶ ὠδῖνας εἶχεν ὑπὲρ ἄλλων, ὅπως εἰς ἀσφαλὲς καταστήσας ἅπαντας ἀπαλλάξαιτο τοῦ ζῆν. οὐ γὰρ ἦν ἄδηλος ἡ πρὸς τὸν θάνατον αὐτοῦ φορά, καίπερ οὐ φάσκοντος. ὑπήκουσεν οὖν τότε τοῖς τριακοσίοις παραμυθησάμενος τοὺς συγκλητικούς· καὶ μόνος ἧκε πρὸς αὐτούς χάριν ἔχειν ὁμολογοῦντας καὶ δεομένους τὰ μὲν ἄλλα χρῆσθαι καὶ πιστεύειν, εἰ δὲ Κάτωνες οὐκ εἰσὶν οὐδὲ τὸ Κάτωνος φρόνημα χωροῦσιν, οἰκτείρειν τὴν ἀσθένειαν αὐτῶν· ἐγνωκότες δ’ οὖν Καίσαρος δεῖσθαι καὶ πέμπειν πρὸς αὐτόν, ὑπὲρ ἐκείνου μάλιστα καὶ πρώτου ποιήσεσθαι δέησιν· εἰ δὲ μὴ πείθοιεν, οὐδ’ αὐτοῖς διδομένην δέξεσθαι τὴν χάριν, ἀλλ’ ἄχρι ἂν ἐμπνέωσι πολεμήσειν ὑπὲρ ἐκείνου.", "st": "Cat. Mi. 64.3"}, {"sp": "N", "t": "πρὸς ταῦτα ὁ Κάτων ἐπαινέσας τὴν εὔνοιαν ἔφη χρῆναι τῆς αὐτῶν σωτηρίας ἕνεκα πέμπειν κατὰ τάχος, ὑπὲρ αὐτοῦ δὲ μὴ δεῖσθαι· κεκρατημένων γὰρ εἶναι δέησιν καὶ ἀδικούντων παραίτησιν αὐτὸς δὲ οὐ μόνον ἀήττητος γεγονέναι παρὰ πάντα τὸν βίον, ἀλλὰ καὶ νικᾶν ἐφ’ ὅσον ἐβούλετο καὶ κρατεῖν Καίσαρος τοῖς καλοῖς καὶ δικαίοις· ἐκεῖνον δ’ εἶναι τὸν ἑαλωκότα καὶ νενικημένον ἃ γὰρ ἠρνεῖτο πράττων κατὰ τῆς πατρίδος πάλαι, νῦν ἐξηλέγχθαι καὶ πεφωρᾶσθαι.", "st": "Cat. Mi. 64.5"}, {"sp": "N", "t": "τοιαῦτα διαλεχθεὶς τοῖς τριακοσίοις ἀπηλλάττετο· καὶ πυθόμενος Καίσαρα πᾶσαν ἄγοντα τήν στρατιὰν ἤδη καθ’ ὁδὸν εἶναι, παπαὶ, εἶπεν, ὡς ἐπ’ ἄνδρας ἡμᾶς ἐκεῖνος καὶ τραπόμενος πρὸς τοὺς συγκλητικοὺς ἐκέλευε μὴ μέλλειν, ἀλλ’ ἕως παραμένουσιν οἱ ἱππεῖς σῴζεσθαι. καὶ τὰς μὲν ἄλλας ἀπέκλεισε θύρας, μιᾷ δὲ τῇ πρὸς θάλασσαν φερούσῃ τά τε πλοῖα τοῖς ὑφ’ ἑαυτὸν διένειμε καὶ τάξεως ἐπεμελεῖτο, παύων τὰς ἀδικίας καὶ διαλύων τοὺς θορύβους, καὶ τοὺς ἀπόρως ἔχοντας ἐφοδιάζων. ἐπεὶ δὲ Μᾶρκος Ὀκτάβιος ἄγων δύο τάγματα πλησίον κατεστρατοπέδευσε καὶ πέμπων ἠξίου τὸν Κάτωνα περὶ ἀρχῆς διορίσασθαι πρὸς αὐτόν, ἐκείνῳ μὲν οὐθὲν ἀπεκρίνατο, πρὸς δὲ τοὺς φίλους εἶπεν εἶτα θαυμάζομεν ὅπως ἀπόλωλε τὰ πράγματα, τήν φιλαρχίαν ὁρῶντες ἡμῖν ἐν αὐτῷ τῷ ὀλέθρῳ βεβηκόσι παραμένουσαν;", "st": "Cat. Mi. 65.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ τοὺς ἱππεῖς ἀκούσας ἀπιόντας ἤδη φέρειν καὶ ἄγειν τὰ τῶν Ἰτυκαίων ὥσπερ λάφυρα, δρόμῳ συνέτεινε πρὸς αὐτούς καὶ τοῖς πρώτοις ἐντυχὼν ἀφῃρεῖτο, τῶν δὲ ἄλλων ἕκαστος ἔφθανε ῥίπτων καὶ κατατιθέμενος, πάντες δὲ ὑπ’ αἰσχύνης σιωπῇ καὶ κάτω βλέποντες ἀπῄεσαν. ὁ δὲ Κάτων εἰς τήν πόλιν τοὺς Ἰτυκαίους συναγαγών ἐδεῖτο περὶ τῶν τριακοσίων, μὴ παροξῦναι Καίσαρα κατ’ αὐτῶν, ἀλλὰ καὶ κοινῇ τήν σωτηρίαν πράττειν ἀλλήλοις. εἶτα πάλιν τραπόμενος πρὸς τήν θάλατταν ἐπεσκόπει τοὺς ἐμβαίνοντας, καὶ τῶν φίλων καὶ ξένων ὅσους ἔπεισεν ἠσπάζετο καὶ προὔπεμπε. τὸν δὲ υἱὸν οὐκ ἔπεισε λαβεῖν πλοῖον, οὐδὲ ᾤετο δεῖν ἀποτρέπειν περιεχόμενον τοῦ πατρός, ἦν δέ τις Στατύλλιος, ἀνὴρ τῇ μὲν ἡλικίᾳ, νέος, ἰσχυρὸς δέ τῇ γνώμῃ βουλόμενος εἶναι καὶ τοῦ Κάτωνος ἀπομιμεῖσθαι τὴν ἀπάθειαν. τοῦτον ἠξίου πλεῖν· καὶ γὰρ ἦν καταφανὴς μισοκαῖσαρ· ὡς δὲ οὐκ ἤθελεν, Ἀπολλωνίδῃ τῷ Στωϊκῷ καὶ Δημητρίῳ τῷ Περιπατητικῷ προσβλέψας ὁ Κάτων, ὑμέτερον, εἶπεν, ἔργον οἰδοῦντα τοῦτον μαλάξαι καὶ καταρτίσαι πρὸς τὸ συμφέρον αὐτὸς δὲ τοὺς λοιποὺς συνεκπέμπων καὶ χρηματίζων τοῖς δεομένοις τήν τε νύκτα διέτριβε περὶ ταῦτα καὶ τῆς ἐπιούσης ἡμέρας τὸ πλεῖστον μέρος.", "st": "Cat. Mi. 65.3"}, {"sp": "N", "t": "ἐπεὶ δὲ Λεύκιος Καῖσαρ, οἰκεῖος μὲν ὢν Καίσαρος ἐκείνου, μέλλων δὲ πρεσβεύειν ὑπὲρ τῶν τριακοσίων, παρεκάλει τὸν Κάτωνα λόγον αὐτῷ συνυποθέσθαι πιθανόν ᾧ χρήσεται περὶ ἐκείνων, ὑπὲρ σοῦ μὲν γὰρ αὐτοῦ καὶ χειρῶν ἐμοὶ καλὸν ἅψασθαι καὶ γόνασι προσπεσεῖν Καίσαρος οὐκ εἴα ταῦτά ποιεῖν ὁ Κάτων αὐτόν. ἐμοὶ γὰρ, εἶπεν, εἰ σῴζεσθαι χάριτι Καίσαρος ἐβουλόμην, αὐτῷ βαδιστέον ἦν πρὸς ἐκεῖνον μόνον, οὐ βούλομαι δὲ τῷ τυράννῳ χάριν ἔχειν ὑπὲρ ὧν παρανομεῖ, παρανομεῖ δὲ σῴζων ὡς κύριος ὧν αὐτῷ δεσπόζειν οὐδὲν προσῆκεν. ὅπως μέντοι παραιτήσῃ τοὺς τριακοσίους κοινῇ σκοπῶμεν, εἰ βούλει. γενόμενος δὲ πρὸς τούτῳ μετὰ τοῦ Λευκίου τὸν υἱὸν αὐτῷ συνέστησε καὶ τοὺς ἑταίρους ἀπιόντι· καὶ προπέμψας ἐκεῖνον καὶ δεξιωσάμενος ἐπανῆλθεν οἴκαδε, καὶ τὸν υἱὸν καὶ τοὺς φίλους συναγαγὼν ἄλλα τε πολλὰ διελέχθη καὶ πολιτείας ἀπεῖπεν ἅψασθαι τῷ μειρακίῳ· τὸ μὲν γὰρ ἀξίως Κάτωνος οὐκέτι τὰ πράγματα δέξασθαι, τὸ δὲ ἄλλως αἰσχρὸν εἶναι, καὶ περὶ ἑσπέραν ἤδη τρέπεται πρὸς τὸ βαλανεῖον.", "st": "Cat. Mi. 66.1"}, {"sp": "N", "t": "ἐν δὲ τῷ λούεσθαι τοῦ Στατυλλίου μνησθεὶς καὶ μέγα φθεγξάμενος, ἐξέπεμψας, εἶπεν, ὦ Ἀπολλωνίδη, τὸν Στατύλλιον ἀπὸ τοῦ φρονήματος ἐκείνου καθελών; καὶ πέπλευκεν ὁ ἀνὴρ μηδὲ ἀσπασάμενος ἡμᾶς; πόθεν; εἶπεν ὁ Ἀπολλωνίδης· καίτοι πολλὰ διελέχθημεν· ἀλλὰ ὑψηλός ἐστι καὶ ἄτρεπτος, καὶ μένειν φησὶ καὶ πράττειν ὅ τι ἂν σὺ πράττῃς. πρὸς ταῦτά φασι τὸν Κάτωνα μειδιᾶσαι καὶ εἰπεῖν ἀλλὰ τοῦτο μὲν αὐτίκα φανεῖται.", "st": "Cat. Mi. 66.4"}, {"sp": "N", "t": "λουσάμενος δὲ μετὰ πολλῶν ἐδείπνει καθήμενος, ὥσπερ εἰώθει μετὰ τὴν μάχην οὐ γὰρ κατεκλίθη πλὴν καθεύδων συνεδείπνουν δὲ πάντες οἱ ἑταῖροι καὶ τῶν Ἰτυκαίων οἱ ἄρχοντες, καὶ μετὰ τὸ δεῖπνον ὁ πότος ἔσχε μοῦσαν πολλὴν καὶ χάριν, ἄλλων ἐπ’ ἄλλοις λόγων φιλοσόφων κυκλούντων, ἄχρι οὗ περιῆλθεν ἡ ζήτησις εἰς ταῦτα δὴ τὰ παράδοξα καλούμενα τῶν Στωϊκῶν, τὸ μόνον εἶναι τὸν ἀγαθὸν ἐλεύθερον, δούλους δὲ τοὺς φαύλους ἅπαντας. ἐνταῦθα δή, ὡς εἰκός, ἀντιβάντος τοῦ Περιπατητικοῦ, σφοδρὸς ἐμπεσὼν ὁ Κάτων καὶ τόνον προσθεὶς καὶ τραχύτητα φωνῆς ἀπέτεινε πορρωτάτω τὸν λόγον, ἀγῶνι θαυμαστῷ χρησάμενος, ὥστε μηδένα λαθεῖν ὅτι τῷ βίῳ πέρας ἔγνωκεν ἐπιθεὶς ἀπαλλάττεσθαι τῶν παρόντων, διὸ καὶ μετὰ τὸν λόγον σιωπῆς καὶ κατηφείας γενομένης ἐν πᾶσιν, ἀναλαμβάνων αὐτοὺς καὶ ἀπάγων τῆς ὑποψίας ὁ Κάτων αὖθις ὑπὲρ τῶν παρόντων ἐνέβαλλεν ἐρωτήματα καὶ φροντίδας, ὡς δεδιὼς μὲν ὑπὲρ τῶν πλεόντων, δεδιὼς δὲ ὑπὲρ τῶν ὁδευόντων ἐρημίαν ἄνυδρον καὶ βάρβαρον.", "st": "Cat. Mi. 67.1"}, {"sp": "N", "t": "οὕτω δὲ διαλύσας τὸ σύνδειπνον, καὶ περιπατήσας μετὰ τῶν φίλων τόν συνήθη μετὰ τὸ δεῖπνον περίπατον, καὶ τοῖς ἄρχουσι τῶν φυλάκων ἃ καιρὸς ἦν προστάξας, ἀπιὼν εἰς τὸ δωμάτιον ἤδη, τόν τε παῖδα καὶ τῶν φίλων ἕκαστον μᾶλλον ἢ πρότερον εἰώθει προσαγαγόμενος καὶ φιλοφρονηθείς, πάλιν ὑποψίαν παρέσχε τοῦ μέλλοντος. εἰσελθὼν δὲ καὶ κατακλιθεὶς ἔλαβεν εἰς χεῖρας τῶν Πλάτωνος διαλόγων τόν περὶ ψυχῆς· καὶ διελθὼν τοῦ βιβλίου τὸ πλεῖστον καὶ ἀναβλέψας ὑπὲρ κεφαλῆς, ὡς οὐκ εἶδε κρεμάμενον τὸ ξίφος (ὑφῄρητο γὰρ ὁ παῖς ἔτι δειπνοῦντος αὐτοῦ), καλέσας οἰκέτην ἠρώτησεν ὅστις λάβοι τὸ ἐγχειρίδιον. σιωπῶντος δὲ ἐκείνου πάλιν ἦν πρὸς τῷ βιβλίῳ· καὶ μικρὸν διαλιπών, ὥσπερ οὐ σπεύδων οὐδὲ ἐπειγόμενος, ἄλλως δὲ τὸ ξίφος ἐπιζητῶν, ἐκέλευσε κομίσαι. διατριβῆς δὲ γινομένης καὶ μηδενὸς κομίζοντος, ἐξαναγνοὺς τὸ βιβλίον αὖθις ἐκάλει καθ’ ἕνα τῶν οἰκετῶν καὶ μᾶλλον ἐνέτεινε τὴν φωνὴν τὸ ξίφος ἀπαιτῶν· ἑνὸς δὲ καὶ πὺξ τὸ στόμα πατάξας ᾕμαξε τὴν αὐτοῦ χεῖρα, χαλεπαίνων καὶ βοῶν ἤδη μέγα παραδίδοσθαι τῷ πολεμίῳ γυμνὸς ὑπὸ τοῦ παιδὸς αὐτοῦ καὶ τῶν οἰκετῶν, ἄχρι οὗ κλαίων ὁ υἱὸς εἰσέδραμε μετὰ τῶν φίλων καὶ περιπεσὼν ὠδύρετο καὶ καθικέτευεν. ὁ δὲ Κάτων ἐξαναστὰς ἐνέβλεψέ τε δεινὸν καὶ πότε, εἶπεν, ἐγὼ καὶ ποῦ λέληθα παρανοίας ἡλωκώς, ὅτι διδάσκει μέν οὐδεὶς οὐδεὶς μεταπείθει περὶ ὧν δοκῶ κακῶς βεβουλεῦσθαι, κωλύομαι δὲ χρῆσθαι τοῖς ἐμαυτοῦ λογισμοῖς καὶ παροπλίζομαι; τί δ’ οὐχὶ καὶ συνδεῖς, ὦ γενναῖε, τόν πατέρα καὶ τὰς χεῖρας ἀποστρέφεις, μέχρι ἂν ἐλθὼν Καῖσαρ εὕρῃ με μηδὲ ἀμύνασθαι δυνάμενον; οὐ γὰρ ἐπ’ ἐμαυτόν γε δέομαι ξίφους, ὅπου καὶ τὸ πνεῦμα βραχὺν χρόνον ἐπισχόντα καὶ τὴν κεφαλὴν ἅπαξ πατάξαντα πρὸς τὸν τοῖχον ἀποθανεῖν ἔνεστι.", "st": "Cat. Mi. 68.1"}, {"sp": "N", "t": "ταῦτα λέγοντος αὐτοῦ τὸ μὲν μειράκιον ἐξῆλθε μετὰ κλαυθμοῦ καὶ πάντες οἱ λοιποί· τῷ δὲ Δημητρίῳ καὶ τῷ Ἀπολλωνίδῃ μόνοις ὑπολειφθεῖσι πρᾳότερον ἤδη λαλῶν, ἦ που καὶ ὑμῖν, ἔφη, δέδοκται βίᾳ κατέχειν ἄνδρα τοσοῦτον ἡλικίας ἐν τῷ βίῳ καὶ καθημένους αὐτοῦ σιωπῇ παραφυλάσσειν, ἢ λόγον ἥκετε κομίζοντες ὡς οὐ δεινὸν οὐδὲ αἰσχρόν ἐστιν ἀποροῦντα σωτηρίας ἑτέρας Κάτωνα τὴν ἀπὸ τοῦ πολεμίου περιμένειν; τί οὖν οὐ λέγετε πείθοντες ἡμᾶς ταῦτα καὶ μεταδιδάσκοντες, ἵνα τὰς προτέρας δόξας ἐκείνας καὶ λόγους, οἷς συμβεβιώκαμεν, ἐκβαλόντες καὶ γενόμενοι διὰ Καίσαρα σοφώτεροι μείζονα χάριν εἰδῶμεν αὐτῷ; καίτοι βεβούλευμαι μὲν οὐθὲν ἔγωγε περὶ ἐμαυτοῦ· δεῖ δέ με βουλευσάμενον εἶναι κύριον οἷς ἔγνωκα χρῆσθαι. βουλεύσομαι δὲ τρόπον τινὰ μεθ’ ὑμῶν, βουλευόμενος μετὰ τῶν λόγων οἷς καὶ ὑμεῖς φιλοσοφοῦντες χρῆσθε· θαρροῦντες οὖν ἄπιτε, καὶ κελεύετε τὸν υἱόν ἃ μὴ δύναται τὸν πατέρα πείθειν μὴ βιάζεσθαι.", "st": "Cat. Mi. 69.1"}, {"sp": "N", "t": "πρὸς ταῦτά μηθὲν ἀντειπόντες οἱ περὶ τὸν Δημήτριον, ἀλλὰ δακρύσαντες ὑπεξῆλθον. εἰσπέμπεται δὲ διὰ παιδίου μικροῦ τὸ ἐγχειρίδιον καὶ λαβὼν ἐσπάσατο καὶ κατενόησεν. ὡς δὲ εἶδεν ἑστῶτα τὸν ἀθέρα καὶ τὴν ἀκμὴν διαμένουσαν, εἰπὼν, νῦν ἐμός εἰμι, τὸ μὲν ξίφος ἔθηκε, τὸ δὲ βιβλίον αὖθις ἀνεγίνωσκε, καὶ λέγεται δὶς ὅλον διεξελθεῖν. εἶτα κοιμηθεὶς ὕπνον βαθύν, ὥστε τοὺς ἐκτὸς αἰσθέσθαι, περὶ μέσας νύκτας ἐκάλει τῶν ἀπελευθέρων Κλεάνθην τὸν ἰατρὸν καὶ Βούταν, ᾧ μάλιστα πρὸς τὰς πολιτικὰς πράξεις ἐχρῆτο. καὶ τοῦτον μὲν ἐπὶ θάλατταν ἔπεμψεν, ὅπως σκεψάμενος εἰ πάντες ἀνηγμένοι τυγχάνουσι, φράσοι πρὸς αὐτόν τῷ δὲ ἰατρῷ τὴν χεῖρα φλεγμαίνουσαν ὑπὸ τῆς πληγῆς ἣν ἔπληξε τὸν οἰκέτην, ἐπιδῆσαι παρέσχε. καὶ τοῦτ’ ἐποίησεν ἡδίους ἅπαντας, ὡς ζωτικῶς ἔχοντος αὐτοῦ. μετ’ ὀλίγον δὲ παρῆν ὁ Βούτας ἀπαγγέλλων τοὺς μὲν ἄλλους ἀνῆχθαι, Κράσσον δὲ λείπεσθαι ὑπὸ ἀσχολίας τινός, ὅσον δὲ οὔπω καὶ τοῦτον ἐμβαίνειν, πολὺν δὲ χειμῶνα καὶ μέγα πνεῦμα κατέχειν τὴν θάλατταν. τοῦτο ἀκούσας ὁ Κάτων ἐστέναξεν οἴκτῳ τῶν πλεόντων, καὶ πάλιν ἔπεμψε τὸν Βούταν ἐπὶ θάλατταν, εἴ τις ἄρα παλινδρομήσας δέοιτό τινος τῶν ἀναγκαίων, ἀπαγγελοῦντα πρὸς αὐτόν.", "st": "Cat. Mi. 70.1"}, {"sp": "N", "t": "ἤδη δὲ ὄρνιθες ᾖδον, καὶ μικρὸν αὖθις κατηνέχθη πρὸς ὕπνον. ἐπανελθόντος δὲ τοῦ Βούτα καὶ φράσαντος πολλὴν ἡσυχίαν περὶ τοὺς λιμένας εἶναι, προσέταξεν αὐτῷ τὴν θύραν κλεῖσαι, καὶ καθῆκεν ἑαυτὸν εἰς τὸ κλινίδιον ὡς τὸ λοιπὸν ἔτι τῆς νυκτὸς ἀναπαυσόμενος. ἐξελθόντος δὲ τοῦ Βούτα σπασάμενος τὸ ξίφος ἔωσε μὲν ὑπὸ τὸ στῆθος, τῇ δὲ χειρὶ κουφότερον διὰ τὴν φλεγμονὴν χρησάμενος οὐκ εὐθὺς ἀπήλλαξεν ἑαυτόν, ἀλλὰ δυσθανατῶν ἐξέπεσε τῆς κλίνης καὶ ψόφον ἐποίησε, καταβαλὼν ἀβάκιόν τι τῶν γεωμετρικῶν παρακείμενον, ὥστε τοὺς θεράποντας αἰσθομένους ἀναβοῆσαι καὶ τὸν υἱὸν αὐτίκα καὶ τοὺς φίλους ἐπεισελθεῖν. ἰδόντες δὲ πεφυρμένον αἵματι καὶ τῶν ἐντέρων τὰ πολλὰ προπεπτωκότα, ζῶντα δ’ αὐτόν ἔτι καὶ βλέποντα, δεινῶς μὲν ἅπαντες ἔσχον, ὁ δὲ ἰατρὸς προσελθὼν ἐπειρᾶτο τῶν ἐντέρων ἀτρώτων διαμεινάντων ταῦτά τε καθιστάναι καὶ τὸ τραῦμα διαρράπτειν. ὡς οὖν ἀνήνεγκεν ὁ Κάτων καὶ συνεφρόνησε, τὸν μὲν ἰατρὸν ἀπεώσατο, ταῖς χερσὶ δὲ τὰ ἔντερα σπαράξας καὶ τὸ τραῦμα ἐπαναρρήξας ἀπέθανεν.", "st": "Cat. Mi. 70.4"}, {"sp": "N", "t": "ἐν ᾧ δὲ οὐκ ἄν τις ᾤετο χρόνῳ τοὺς κατὰ τὴν οἰκίαν πάντας ᾐσθῆσθαι τὸ πάθος, ἐπὶ ταῖς θύραις ἦσαν οἱ τριακόσιοι, καὶ μικρὸν ὕστερον ὁ δῆμος ἤθροιστο τῶν Ἰτυκαίων, μιᾷ φωνῇ τὸν εὐεργέτην καὶ σωτῆρα καὶ μόνον ἐλεύθερον καὶ μόνον ἀήττητον καλούντων. καὶ ταῦτα ἔπραττον ἀγγελλομένου προσιέναι Καίσαρος· ἀλλ’ οὔτε φόβος αὐτοὺς οὔτε κολακεία τοῦ κρατοῦντος οὔτε ἡ πρὸς ἀλλήλους διαφορὰ καὶ στάσις ἀμβλυτέρους ἐποίησε τῆς πρὸς Κάτωνα τιμῆς, κοσμήσαντες δὲ τὸ σῶμα λαμπρῶς καὶ πομπὴν ἐπιφανῆ παρασχόντες καὶ θάψαντες παρὰ τὴν θάλασσαν, οὗ νῦν ἀνδριὰς ἐφέστηκεν αὐτοῦ ξιφήρης, οὕτως ἐτράποντο πρὸς τὸ σῴζειν ἑαυτοὺς καὶ τὴν πόλιν.", "st": "Cat. Mi. 71.1"}, {"sp": "N", "t": "Καῖσαρ δὲ πυνθανόμενος παρὰ τῶν ἀφικνουμένων ὑπομένειν ἐν Ἰτύκῃ τὸν Κάτωνα μηδὲ φεύγειν, ἀλλὰ τοὺς ἄλλους προπέμπειν, αὐτὸν δὲ καὶ τοὺς ἑταίρους καὶ τὸν υἱὸν ἀδεῶς ἀναστρέφεσθαι, δυστέκμαρτον ἡγεῖτο τὴν γνώμην τοῦ ἀνδρός, ἅτε δὲ τὸν πλεῖστον λόγον ἔχων ἐκείνου προσῆγε μετὰ τῆς δυνάμεως ἐπειγόμενος. ὡς δὲ ἤκουσε τὸν θάνατον αὐτοῦ, λέγεται τοσοῦτον εἰπεῖν Ὦ Κάτων, φθονῶ σοι τοῦ θανάτου· καὶ γὰρ ἐμοὶ σὺ τῆς σαυτοῦ σωτηρίας ἐφθόνησας. τῷ γὰρ ὄντι σωθῆναι Κάτων ἀνασχόμενος ὑπὸ Καίσαρος οὐκ ἂν οὕτω δοκεῖ καταισχῦναι τὴν αὑτοῦ δόξαν, ὡς κοσμῆσαι τὴν ἐκείνου, τὸ δὲ πραχθὲν ἂν ἄδηλον· εἰκάζεται δὲ τὰ χρηστότερα παρὰ Καίσαρος.", "st": "Cat. Mi. 72.1"}, {"sp": "N", "t": "ἐτελεύτησε δὲ Κάτων ἔτη δυεῖν δέοντα πεντήκοντα βεβιωκώς. ὁ δὲ υἱὸς αὐτοῦ ὑπὸ Καίσαρος μὲν οὐδὲν ἠδικήθη· λέγεται δὲ ῥᾴθυμος γενέσθαι καὶ περὶ γυναῖκας οὐκ ἀνεπίληπτος. ἐν δὲ Καππαδοκίᾳ, ξένῳ τινὶ χρησάμενος Μαρφαδάτῃ τῶν βασιλικῶν ἔχοντι γύναιον εὐπρεπές, καὶ πλείονα παρ’ αὐτοῖς ἢ καλῶς εἶχε διατρίβων χρόνον, ἐσκώπτετο τοιαῦτα γραφόντων εἰς αὐτόν", "st": "Cat. Mi. 73.1"}, {"sp": "N", "t": "αὔριον Κάτων βαδίζει μετὰ τριάκονθ’ ἡμέρας·<br>καὶ,<br>Πόρκιος καὶ Μαρφαδάτης, δύο φίλοι, ψυχὴ μία.", "st": "Cat. Mi. 73.1b"}, {"sp": "N", "t": "Ψυχὴ γὰρ ἐκαλεῖτο τοῦ Μαρφαδάτου τὸ γύναιον, καὶ ἔτι,<br>εὐγενὴς καὶ λαμπρὸς ὁ Κάτων βασιλικὴν ψυχὴν ἔχει.", "st": "Cat. Mi. 73.1c"}, {"sp": "N", "t": "ἀλλὰ πᾶσάν γε τὴν τοιαύτην ἐξήλειψε καὶ ἠφάνισε τῷ θανάτῳ δύσκλειαν. ἀγωνιζόμενος γὰρ ἐν Φιλίπποις πρὸς Καίσαρα καὶ Ἀντώνιον ὑπὲρ τῆς ἐλευθερίας, καὶ κλινομένης τῆς φάλαγγος οὔτε φυγεῖν οὔτε λαθεῖν ἀξιώσας, ἀλλὰ προκαλούμενος τοὺς πολεμίους ἔμπροσθεν ἑαυτὸν ἐμφανίζων καὶ συνεξορμῶν τοὺς συμμένοντας ἔπεσε, θαῦμα τῆς ἀρετῆς τοῖς ἐναντίοις παρασχών.", "st": "Cat. Mi. 73.3"}, {"sp": "N", "t": "ἔτι δὲ μᾶλλον ἡ θυγάτηρ τοῦ Κάτωνος οὔτε σωφροσύνης οὔτε ἀνδρείας ἀπολειφθεῖσα Βρούτῳ γὰρ συνῴκει τῷ κτείναντι Καίσαρα αὐτῆς τε τῆς συνωμοσίας μετέσχε, καὶ προήκατο τὸν βίον ἀξίως τῆς εὐγενείας καὶ ἀρετῆς, ὡς ἐν τοῖς περὶ Βρούτου γέγραπται. Στατύλλιος δὲ φήσας μιμεῖσθαι Κάτωνα τότε μὲν ὑπὸ τῶν φιλοσόφων ἐκωλύθη βουλόμενος ἑαυτὸν ἀνελεῖν, ὕστερον δὲ τῷ Βρούτῳ πιστότατον ἑαυτὸν παρασχὼν καὶ χρησιμώτατον ἐν Φιλίπποις ἀπέθανεν.", "st": "Cat. Mi. 73.4"}, {"sp": "HDR", "t": "Ἄγις"}, {"sp": "N", "t": "οὐκ ἀτόπως τινὲς οὐδὲ φαύλως συγκεῖσθαι πρὸς τοὺς φιλοδόξους ὑπονοοῦσι τὸν ἐπὶ τῷ Ἰξίονι μῦθον, ὡς δὴ λαβόντι τὴν νεφέλην ἀντὶ τῆς Ἥρας καὶ τῶν Κενταύρων οὕτως γενομένων, καὶ γὰρ οὗτοι τῆς ἀρετῆς ὥσπερ εἰδώλῳ τινὶ τῇ δόξῃ συνόντες, οὐδὲν εἰλικρινὲς οὐδ’ ὡμολογημένον, ἀλλὰ νόθα καὶ μικτὰ πολλὰ πράττουσιν, ἄλλας ἄλλας φορὰς φερόμενοι, ζήλοις καὶ πάθεσιν ἐπακολουθοῦντες, ὅπερ οἱ Σοφοκλέους βοτῆρες ἐπὶ τῶν ποιμνίων λέγουσιν", "st": "Agis 1.1"}, {"sp": "N", "t": "τούτοις γὰρ ὄντες δεσπόται δουλεύομεν,<br>καὶ τῶνδ’ ἀνάγκη καὶ σιωπώντων κλύειν.", "st": "Agis 1.1b"}, {"sp": "N", "t": "ὅπερ ἀληθῶς οἱ πρὸς ἐπιθυμίας ὄχλων καὶ ὁρμὰς πολιτευόμενοι πάσχουσι, δουλεύοντες καὶ ἀκολουθοῦντες ἵνα δημαγωγοὶ καὶ ἄρχοντες ὀνομάζωνται. καθάπερ γὰρ οἱ πρωρεῖς τὰ ἔμπροσθεν προορώμενοι τῶν κυβερνητῶν ἀφορῶσι πρὸς ἐκείνους καὶ τὸ προστασσόμενον ὑπ’ ἐκείνων ποιοῦσιν, οὕτως οἱ πολιτευόμενοι καὶ πρὸς δόξαν ὁρῶντες ὑπηρέται μὲν τῶν πολλῶν εἰσιν, ὄνομα δὲ ἀρχόντων ἔχουσιν.", "st": "Agis 1.2"}, {"sp": "N", "t": "ὁ μὲν γὰρ ἀπηκριβωμένος καὶ τελείως ἀγαθὸς οὐδ’ ἂν ὅλως δόξης δέοιτο, πλὴν ὅση πάροδον ἐπὶ τὰς πράξεις διὰ τοῦ πιστεύεσθαι δίδωσι· νέῳ δὲ ἔτι ὄντι καὶ φιλοτίμῳ δοτέον ἀπὸ τῶν καλῶν ἔργων καὶ δόξῃ τι καλλωπίσασθαι καὶ κομπάσαι. φυόμεναι γὰρ ἐν τοῖς τηλικούτοις αἱ ἀρεταὶ καὶ βλαστάνουσαι τό τε κατορθούμενον ὥς φησι Θεόφραστος, ἐκβεβαιοῦνται τοῖς ἐπαίνοις, καὶ τὸ λοιπὸν αὔξονται μετὰ φρονήματος ἐπαιρόμεναι. τὸ δὲ ἄγαν πανταχοῦ μὲν ἐπισφαλές, ἐν δὲ ταῖς πολιτικαῖς φιλοτιμίαις ὀλέθριον ἐκφέρει γὰρ εἰς μανίαν καὶ παραφροσύνην ὕπαιθρον ἐξουσίας μεγάλης ἐπιλαβομένους, ὅταν μὴ τὸ καλὸν ἔνδοξον εἶναι θέλωσιν, ἀλλ’ ἀγαθὸν ἡγῶνται τὸ ἔνδοξον εἶναι. ὅπερ οὖν Φωκίων πρὸς Ἀντίπατρον ἀξιοῦντά τι παρ’ αὐτοῦ τῶν μὴ καλῶν οὐ δύνασαι, εἶπεν, ἅμα καὶ φίλῳ Φωκίωνι χρῆσθαι καὶ κόλακι, τοῦτο λεκτέον ἢ ὅμοιόν τι τούτῳ πρὸς τοὺς πολλούς· οὐ δύνασθε τὸν αὐτὸν ἔχειν καὶ ἄρχοντα καὶ ἀκόλουθον. ἐπεὶ συμβαίνει γε καὶ οὕτως τὸ τοῦ δράκοντος, οὗ φησιν ὁ μῦθος τὴν οὐρὰν τῇ κεφαλῇ στασιάσασαν ἀξιοῦν ἡγεῖσθαι παρὰ μέρος καὶ μὴ διὰ παντὸς ἀκολουθεῖν ἐκείνῃ, λαβοῦσαν δὲ τὴν ἡγεμονίαν αὐτήν τε κακῶς ἀπαλλάττειν ἀνοίᾳ πορευομένην καὶ τὴν κεφαλὴν καταξαίνειν, τυφλοῖς καὶ κωφοῖς μέρεσιν ἀναγκαζομένην παρὰ φύσιν ἕπεσθαι. τοῦτο πολλοὺς τῶν πρὸς χάριν ἅπαντα πεπολιτευμένων ὁρῶμεν πεπονθότας· ἐξαρτήσαντες γὰρ αὑτοὺς ὄχλων εἰκῇ φερομένων οὔτ’ ἀναλαβεῖν ὕστερον οὔτ’ ἐπιστῆσαι τὴν ἀταξίαν ἐδυνήθησαν.", "st": "Agis 2.1"}, {"sp": "N", "t": "ταῦτα δὲ ἡμῖν εἰς τὴν παρὰ τῶν πολλῶν δόξαν ἐπῆλθεν εἰπεῖν ἐννοήσασιν ἡλίκην ἔχει δύναμιν ἐκ τῶν Τιβερίῳ καὶ Γαΐῳ τοῖς Γράγχοις συμπεσόντων, οὓς κάλλιστα μὲν φύντας, κάλλιστα δὲ τραφέντας, καλλίστην δὲ τῆς πολιτείας ὑπόθεσιν λαβόντας, ἀπώλεσεν οὐχ οὕτως ἐπιθυμία δόξης ἄμετρος, ὡς φόβος ἀδοξίας ἐκ προφάσεως οὐκ ἀγεννοῦς πεφυκώς. μεγάλην γὰρ εὔνοιαν προειληφότες παρὰ τῶν πολιτῶν ᾐσχύνθησαν ἐγκαταλιπεῖν ὥσπερ χρέος· ἁμιλλώμενοι δ’ ἀεὶ πολιτεύμασι χρηστοῖς τὰς τιμὰς ὑπερβάλλεσθαι, καὶ τιμώμενοι μᾶλλον ἐξ ὧν ἐπολιτεύοντο κεχαρισμένως, καὶ τοῦτον τὸν τρόπον ἴσῃ φιλοτιμίᾳ πρός τε τὸν δῆμον ἑαυτοὺς καὶ τὸν δῆμον πρὸς ἑαυτοὺς ἐκκαύσαντες, ἔλαθον ἁψάμενοι πραγμάτων ἐν οἷς οὐκέτ’ ἦν τὸ ἐπιμεῖναι καλὸν, αἰσχρὸν δ’ ἤδη τὸ παύσασθαι.", "st": "Agis 2.5"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ἐπικρινεῖς αὐτὸς ἐκ τῆς διηγήσεως παραβάλωμεν δὲ αὐτοῖς Λακωνικὸν ζεῦγος δημαγωγῶν, Ἆγιν καὶ Κλεομένην τοὺς βασιλεῖς, καὶ γὰρ οὗτοι τὸν δῆμον αὔξοντες, ὥσπερ ἐκεῖνοι, καὶ πολιτείαν καλὴν καὶ δικαίαν ἐκλελοιπυῖαν πολὺν χρόνον ἀναλαμβάνοντες, ὁμοίως ἀπηχθάνοντο τοῖς δυνατοῖς μὴ βουλομένοις ἀφεῖναι τὴν συνήθη πλεονεξίαν. ἀδελφοὶ μὲν οὖν οὐκ ἦσαν ἀλλήλων οἱ Λάκωνες, συγγενοῦς δὲ καὶ ἀδελφῆς ἥψαντο πολιτείας, ἀρχὴν τοιαύτην λαβόντες.", "st": "Agis 2.6"}, {"sp": "N", "t": "ἐπεὶ παρεισέδυ πρῶτον εἰς τὴν πόλιν ἀργύρου καὶ χρυσοῦ ζῆλος, καὶ συνηκολούθησε τοῦ πλούτου τῇ μὲν κτήσει πλεονεξία καὶ μικρολογία τῇ δὲ χρήσει καὶ ἀπολαύσει τρυφὴ καὶ μαλακία καὶ πολυτέλεια, τῶν πλείστων ἐξέπεσεν ἡ Σπάρτη καλῶν, καὶ ταπεινὰ πράττουσα παρ’ ἀξίαν διετέλει μέχρι τῶν χρόνων ἐκείνων ἐν οἷς Ἆγις καὶ Λεωνίδας ἐβασίλευον, Ἆγις μὲν Εὐρυπωντίδης καὶ Εὐδαμίδα παῖς, ἕκτος ἀπὸ Ἀγησιλάου τοῦ διαβάντος εἰς τὴν Ἀσίαν καὶ μέγιστον Ἑλλήνων δυνηθέντος· ἦν γὰρ Ἀγησιλάου μὲν Ἀρχίδαμος ὁ περὶ Μανδύριον τῆς Ἰταλίας ὑπὸ Μεσσαπίων ἀποθανών, Ἀρχιδάμου δὲ πρεσβύτερος μὲν υἱὸς Ἆγις, Εὐδαμίδας δὲ νεώτερος, ὅς, Ἄγιδος ὑπὸ Ἀντιπάτρου περὶ Μεγάλην πόλιν ἀναιρεθέντος ἀτέκνου, τὴν βασιλείαν ἔσχε, τούτου δὲ Ἀρχίδαμος, Ἀρχιδάμου δὲ ἕτερος Εὐδαμίδας, Εὐδαμίδα δὲ Ἆγις, περὶ οὗ τάδε γέγραπται· Λεωνίδας δὲ ὁ Κλεωνύμου τῆς μὲν ἑτέρας οἰκίας ἦν Ἀγιάδης, ὄγδοος δὲ ἀπὸ Παυσανίου τοῦ νικήσαντος ἐν Πλαταιαῖς μάχῃ Μαρδόνιον. Παυσανίας γὰρ υἱὸν ἔσχε Πλειστώνακτα, Πλειστῶναξ δὲ Παυσανίαν, οὗ φυγόντος εἰς Τεγέαν ἐκ Λακεδαίμονος ὅ τε πρεσβύτερος υἱὸς Ἀγησίπολις ἐβασίλευσε καὶ τούτου τελευτήσαντος ἀτέκνου Κλεόμβροτος ὁ νεώτερος. ἐκ δὲ Κλεομβρότου πάλιν ἄλλος Ἀγησίπολις ἦν καὶ Κλεομένης, ὧν Ἀγησίπολις μὲν οὔτε ἦρξε πολὺν χρόνον οὔτε παῖδας ἔσχε, Κλεομένης δὲ βασιλεύσας μετὰ Ἀγησίπολιν τὸν μὲν πρεσβύτερον τῶν υἱῶν Ἀκρότατον ἔτι ζῶν ἀπέβαλε, νεώτερον δὲ Κλεώνυμον κατέλιπεν, ὃς οὐκ ἐβασίλευσεν, ἀλλ’ Ἄρευς υἱωνὸς ὢν Κλεομένους, Ἀκροτάτου δ’ υἱός· Ἄρεως δὲ πεσόντος περὶ Κόρινθον υἱὸς ὦν Ἀκρότατος τὴν βασιλείαν κατέσχεν. ἀπέθανε δὲ καὶ οὗτος ἡττηθεὶς μάχῃ περὶ Μεγάλην πόλιν ὑπὸ Ἀριστοδήμου τοῦ τυράννου, καταλιπὼν ἐγκύμονα τὴν γυναῖκα. παιδίου δὲ ἄρρενος γενομένου Λεωνίδας ὁ Κλεωνύμου τὴν ἐπιτροπὴν ἔσχεν, εἶτα πρὶν ἐν ἡλικίᾳ γενέσθαι τελευτήσαντος, οὕτως εἰς αὐτὸν ἡ βασιλεία περιῆλθεν οὐ πάνυ τοῖς πολίταις εὐάρμοστον ὄντα. καίπερ γὰρ ἐγκεκλικότων ἤδη τῇ διαφθορᾷ τοῦ πολιτεύματος ὁμαλῶς ἁπάντων, ἦν τις ἐν τῷ Λεωνίδᾳ τῶν πατρῴων ἐπιφανὴς ἐκδιαίτησις, ἅτε δὴ χρόνον ἠλινδημένῳ πολὺν ἐν αὐλαῖς σατραπικαῖς καὶ τεθεραπευκότι Σέλευκον, εἶτα τὸν ἐκεῖθεν ὄγκον εἰς Ἑλληνικὰ πράγματα καὶ νόμιμον ἀρχὴν οὐκ ἐμμελῶς μεταφέροντι.", "st": "Agis 3.1"}, {"sp": "N", "t": "ὁ δὲ Ἆγις οὕτω πολὺ παρήλλαττεν εὐφυΐᾳ καὶ φρονήματι ψυχῆς οὐ μόνον τοῦτον, ἀλλὰ σχεδὸν ἅπαντας ὅσοι μετ’ Ἀγησίλαον τὸν μέγαν ἐβασίλευσαν, ὥστε μηδέπω γεγονὼς εἰκοστὸν ἔτος, ἐντεθραμμένος δὲ πλούτοις καὶ τρυφαῖς γυναικῶν, τῆς τε μητρὸς Ἀγησιστράτας καὶ τῆς μάμμης Ἀρχιδαμίας, αἳ πλεῖστα χρήματα Λακεδαιμονίων ἐκέκτηντο, πρός τε τὰς ἡδονὰς εὐθὺς ἀπισχυρίσασθαι, καὶ τὸν ἐπιπρέψαι μάλιστα τῇ χάριτι τῆς μορφῆς ὡραϊσμὸν δοκοῦντα περισπάσας τοῦ σώματος, καὶ πᾶσαν ἐκδὺς καὶ διαφυγὼν πολυτέλειαν, ἐγκαλλωπίζεσθαι τῷ τριβωνίῳ, καὶ δεῖπνα καὶ λουτρὰ καὶ διαίτας Λακωνικὰς ζητεῖν, καὶ λέγειν ὡς οὐδὲν δέοιτο τῆς βασιλείας, εἰ μὴ δι’ αὐτὴν ἀναλήψοιτο τοὺς νόμους καὶ τὴν πάτριον ἀγωγήν.", "st": "Agis 4.1"}, {"sp": "N", "t": "ἀρχὴν μὲν οὖν διαφθορᾶς καὶ τοῦ νοσεῖν ἔσχε τὰ πράγματα τῶν Λακεδαιμονίων σχεδὸν ἀφ’ οὗ τὴν Ἀθηναίων καταλύσαντες ἡγεμονίαν χρυσίου τε καὶ ἀργυρίου κατέπλησαν ἑαυτούς· οὐ μὴν ἀλλὰ καὶ τῶν οἴκων ὃν ὁ Λυκοῦργος ὥρισε φυλαττόντων ἀριθμὸν ἐν ταῖς διαδοχαῖς, καὶ πατρὸς παιδὶ τὸν κλῆρον ἀπολείποντος, ἁμῶς γέ πως ἡ τάξις αὕτη καὶ ἰσότης διαμένουσα τὴν πόλιν ἐκ τῶν ἄλλων ἀνέφερεν ἁμαρτημάτων. ἐφορεύσας δέ τις ἀνὴρ δυνατός, αὐθάδης δὲ καὶ χαλεπὸς τὸν τρόπον, Ἐπιτάδευς ὄνομα, πρὸς τὸν υἱὸν αὐτῷ γενομένης διαφορᾶς ῥήτραν ἔγραψεν ἐξεῖναι τὸν οἶκον αὑτοῦ καὶ τὸν κλῆρον ᾧ τις ἐθέλοι καὶ ζῶντα δοῦναι καὶ καταλιπεῖν διατιθέμενον. οὗτος μὲν οὖν αὑτοῦ τινα θυμὸν ἀποπιμπλὰς ἴδιον εἰσήνεγκε τὸν νόμον· οἱ δὲ ἄλλοι πλεονεξίας ἕνεκα δεξάμενοι καὶ κυρώσαντες ἀπώλεσαν τὴν ἀρίστην κατάστασιν. ἐκτῶντο γὰρ ἀφειδῶς ἤδη παρωθοῦντες οἱ δυνατοὶ τοὺς προσήκοντας ἐκ τῶν διαδοχῶν καὶ ταχὺ τῆς εὐπορίας εἰς ὀλίγους συρρυείσης πενία τὴν πόλιν κατέσχεν, ἀσχολίαν τῶν καλῶν καὶ ἀνελευθερίαν ἐπιφέρουσα μετὰ φθόνου καὶ δυσμενείας πρὸς τοὺς ἔχοντας. ἀπελείφθησαν οὖν ἑπτακοσίων οὐ πλείονες Σπαρτιᾶται, καὶ τούτων ἴσως ἑκατὸν ἦσαν οἱ γῆν κεκτημένοι καὶ κλῆρον ὁ δ’ ἄλλος ὄχλος ἄπορος καὶ ἄτιμος ἐν τῇ πόλει παρεκάθητο, τοὺς μὲν ἔξωθεν πολέμους ἀργῶς καὶ ἀπροθύμως ἀμυνόμενος, ἀεὶ δέ τινα καιρὸν ἐπιτηρῶν μεταβολῆς καὶ μεταστάσεως τῶν παρόντων,", "st": "Agis 5.1"}, {"sp": "N", "t": "διὰ ταῦτα δὴ καλὸν ὁ Ἆγις, ὥσπερ ἦν, ποιούμενος ἐξισῶσαι καὶ ἀναπληρῶσαι τὴν πόλιν, ἐπειρᾶτο τῶν ἀνθρώπων, οἱ μὲν οὖν νέοι ταχὺ καὶ παρ’ ἐλπίδας ὑπήκουσαν αὐτῷ, καὶ συναπεδύσαντο πρὸς τὴν ἀρετήν, ὥσπερ ἐσθῆτα τὴν δίαιταν ἐπ’ ἐλευθερίᾳ συμμεταβάλλοντες. τῶν δὲ πρεσβυτέρων, ἅτε δὴ πόρρω διαφθορᾶς γεγονότων, συνέβαινε τοῖς πλείστοις ὥσπερ ἐπὶ δεσπότην ἀγομένους ἐκ δρασμοῦ δεδιέναι καὶ τρέμειν τὸν Λυκοῦργον, καὶ καθήπτοντο τοῦ Ἄγιδος ὀδυρομένου τὰ παρόντα πράγματα καὶ τὸ παλαιὸν ἀξίωμα τῆς Σπάρτης ἐπιποθοῦντος. Λύσανδρος δὲ ὁ Λίβυος καὶ Μανδροκλείδας ὁ Ἐκφάνους, ἔτι δὲ Ἀγησίλαος ἀπεδέξαντο καὶ συμπαρώρμησαν αὐτοῦ τὴν φιλοτιμίαν. ἦν δὲ Λύσανδρος μὲν ἐν δόξῃ μάλιστα τῶν πολιτῶν, Μανδροκλείδας δὲ δεινότατος Ἑλλήνων πράγματα συσκευάσασθαι καὶ τὸ συνετὸν τοῦτο καὶ δολερὸν τόλμῃ μεμιγμένον ἔχων Ἀγησίλαον δὲ θεῖον ὄντα τοῦ βασιλέως καὶ δυνατὸν εἰπεῖν, ἄλλως δὲ μαλακὸν καὶ φιλοχρήματον, ἐμφανῶς μὲν ὁ υἱὸς Ἱππομέδων ἐκίνει καὶ παρεθάρρυνεν, εὐδόκιμος ἐν πολλοῖς πολέμοις ἀνὴρ καὶ μέγα δι’ εὔνοιαν τῶν νέων δυνάμενος· ἡ δὲ ἀληθῶς ἀναπείσασα τὸν Ἀγησίλαον αἰτία τῶν πραττομένων μετασχεῖν ὀφλημάτων πλῆθος ἦν, ὧν ἤλπιζεν ἀπαλλαγήσεσθαι μεταβάλλων τὴν πολιτείαν. ὡς οὖν τάχιστα προσηγάγετο τοῦτον ὁ Ἆγις, εὐθὺς ἐπιχειρεῖ μετ’ αὐτοῦ τὴν μητέρα πείθειν, ἀδελφὴν οὖσαν τοῦ Ἀγησιλάου, πλήθει δὲ πελατῶν καὶ φίλων καὶ χρεωστῶν μέγα δυναμένην ἐν τῇ πόλει καὶ πολλὰ τῶν κοινῶν διαπραττομένην.", "st": "Agis 6.1"}, {"sp": "N", "t": "ἡ δὲ ἀκούσασα τὸ μὲν πρῶτον ἐξεπλάγη καὶ κατέπαυε τὸ μειράκιον ὡς οὔτε δυνατῶν οὔτε λυσιτελῶν ἐφιέμενον· ἐπεὶ δὲ ταῦτα μὲν ὁ Ἀγησίλαος ἐδίδασκεν ὡς καλῶς ἕξει καὶ πραχθήσεται συμφερόντως, αὐτὸς δὲ ὁ βασιλεὺς ἐδεῖτο τῆς μητρὸς ἐπιδοῦναι πρὸς δόξαν αὐτῷ καὶ φιλοτιμίαν τὸν πλοῦτον, ὡς χρήμασι μὲν οὐ δυνάμενος πρὸς τοὺς ἄλλους βασιλεῖς ἐξισωθῆναι (σατραπῶν γὰρ οἰκέτας καὶ δούλους ἐπιτρόπων Πτολεμαίου καὶ Σελεύκου κεκτῆσθαι πλείονα συμπάντων ὁμοῦ τῶν ἐν Σπάρτῃ βασιλέων), ἐὰν δὲ σωφροσύνῃ καὶ λιτότητι καὶ μεγαλοψυχίᾳ τὰς ἐκείνων ὑπερβαλόμενος τρυφὰς ἰσότητα καὶ κοινωνίαν καταστήσῃ τοῖς πολίταις, ὄνομα καὶ δόξαν ὡς ἀληθῶς βασιλέως μεγάλου κτησόμενος, οὕτω μετέπεσον ταῖς γνώμαις αἱ γυναῖκες ὑπὸ τῆς φιλοτιμίας ἐπαρθεῖσαι τοῦ νεανίσκου, καὶ τοσαύτῃ κατεσχέθησαν οἷον ἐπιπνοίᾳ πρὸς τὸ καλόν, ὥστε τὸν μὲν Ἆγιν συνεξορμᾶν καὶ συνεπιταχύνειν, μεταπεμπομένας δὲ τοὺς φίλους παρακαλεῖν καὶ ταῖς ἄλλαις διαλέγεσθαι γυναιξίν, ἅτε δὴ τοὺς Λακεδαιμονίους ἐπισταμένας κατηκόους ὄντας ἀεὶ τῶν γυναικῶν, καὶ πλεῖον ἐκείναις τῶν δημοσίων ἢ τῶν ἰδίων αὑτοῖς πολυπραγμονεῖν διδόντας.", "st": "Agis 7.1"}, {"sp": "N", "t": "ἦν δὲ τότε τῶν Λακωνικῶν πλούτων ἐν ταῖς γυναιξὶ τὸ πλεῖστον, καὶ τοῦτο τὴν πρᾶξιν τῷ Ἄγιδι δύσεργον καὶ χαλεπὴν ἐποίησεν. ἀντέστησαν γὰρ αἱ γυναῖκες οὐ μόνον τρυφῆς ἐκπίπτουσαι δι’ ἀπειροκαλίαν εὐδαιμονιζομένης, ἀλλὰ καὶ τιμὴν καὶ δύναμιν, ἣν ἐκ τοῦ πλουτεῖν ἐκαρποῦντο, περικοπτομένην αὑτῶν ὁρῶσαι. καὶ πρὸς τὸν Λεωνίδαν τραπόμεναι παρεκάλουν ὄντα πρεσβύτερον ἐπιλαμβάνεσθαι τοῦ Ἄγιδος καὶ τὰ πραττόμενα διακωλύειν. ἐβούλετο μὲν οὖν ὁ Λεωνίδας τοῖς πλουσίοις βοηθεῖν, δεδιὼς δὲ τὸν δῆμον ἐπιθυμοῦντα τῆς μεταβολῆς οὐδὲν ἀντέπραττε φανερῶς, λάθρα δὲ τὴν πρᾶξιν ἐζήτει κακουργεῖν καὶ διαφθείρειν ἐντυγχάνων τοῖς ἄρχουσι καὶ διαβάλλων τὸν Ἆγιν ὡς τυραννίδος μισθὸν τοῖς πένησι τὰ τῶν πλουσίων προτείνοντα, καὶ γῆς μεταδόσεσι καὶ χρεῶν ἀφέσεσι πολλοὺς ὠνούμενον ἑαυτῷ δορυφόρους, οὐ τῇ Σπάρτῃ πολίτας.", "st": "Agis 7.4"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ διαπραξάμενος ὁ Ἆγις ἔφορον γενέσθαι τὸν Λύσανδρον, εὐθὺς εἰσέφερε δι’ αὐτοῦ ῥήτραν εἰς τοὺς γέροντας, ἧς ἦν κεφάλαια χρεῶν μὲν ἀφεθῆναι τοὺς ὀφείλοντας, τῆς δὲ γῆς ἀναδασθείσης τὴν μὲν ἀπὸ τοῦ κατὰ Πελλήνην χαράδρου πρὸς τὸ Ταΰγετον καὶ Μαλέαν καὶ Σελασίαν κλήρους γενέσθαι τετρακισχιλίους πεντακοσίους, τὴν δ’ ἔξω μυρίους πεντακισχιλίους· καὶ ταύτην μὲν τοῖς ὅπλα φέρειν δυναμένοις τῶν περιοίκων μερισθῆναι, τὴν δὲ ἐντὸς αὐτοῖς Σπαρτιάταις· ἀναπληρωθῆναι δὲ τούτους ἔκ τε περιοίκων καὶ ξένων, ὅσοι τροφῆς μετεσχηκότες ἐλευθερίου καὶ χαρίεντες ἄλλως τοῖς σώμασι καὶ καθ’ ἡλικίαν ἀκμάζοντες εἶεν σύνταξιν δὲ τούτων εἰς πεντεκαίδεκα γενέσθαι φιδίτια κατὰ τετρακοσίους καὶ διακοσίους, καὶ δίαιταν ἣν εἶχον οἱ πρόγονοι διαιτᾶσθαι.", "st": "Agis 8.1"}, {"sp": "N", "t": "γραφείσης δὲ τῆς ῥήτρας, καὶ τῶν γερόντων εἰς ταὐτὸ ταῖς γνώμαις οὐ συμφερομένων, ἐκκλησίαν συναγαγὼν ὁ Λύσανδρος αὐτός τε διελέχθη τοῖς πολίταις, καὶ Μανδροκλείδας καὶ Ἀγησίλαος ἐδέοντο μὴ δι’ ὀλίγους ἐντρυφῶντας αὐτοῖς περιιδεῖν ἐρριμμένον τὸ ἀξίωμα τῆς Σπάρτης, ἀλλὰ τῶν τε προτέρων χρησμῶν μνημονεῦσαι, τὴν φιλοχρημοσύνην ὡς ὀλέθριον τῇ Σπάρτῃ φυλάττεσθαι διακελευομένων, καὶ τῶν ἔναγχος ἐκ Πασιφάας κεκομισμένων αὐτοῖς.", "st": "Agis 9.1"}, {"sp": "N", "t": "ἱερὸν δὲ Πασιφάας καὶ μαντεῖον ἦν ἐν Θαλάμαις τιμώμενον, ἥν τινὲς μὲν ἱστοροῦσι τῶν Ἀτλαντίδων μίαν οὖσαν ἐκ Διὸς τὸν Ἄμμωνα τεκεῖν, τινὲς δὲ Κασάνδραν τὴν Πριάμου τελευτήσασαν ἐνταῦθα καὶ διὰ τὸ πᾶσι φαίνειν τὰ μαντεῖα Πασιφάαν προσαγορευθεῖσαν. ὁ δὲ Φύλαρχος Ἀμύκλα θυγατέρα, Δάφνην τοὔνομά, φησιν ὑποφεύγουσαν Ἀπόλλωνα βουλόμενον αὐτῇ μιγῆναι, καὶ μεταβαλοῦσαν εἰς τὸ φυτόν, ἐν τιμῇ τοῦ θεοῦ γενέσθαι καὶ μαντικὴν λαβεῖν δύναμιν. ἔφασαν οὖν καὶ τὰ παρὰ ταύτης μαντεῖα προστάττειν τοῖς Σπαρτιάταις ἴσους γενέσθαι πάντας καθ’ ὃν ὁ Λυκοῦργος ἐξ ἀρχῆς ἔταξε νόμον. ἐπὶ πᾶσι δὲ ὁ βασιλεὺς Ἆγις εἰς μέσον παρελθὼν καὶ βραχέα διαλεχθεὶς ἔφη συμβολὰς διδόναι τῇ πολιτείᾳ μεγίστας ἣν καθίστησι· τὴν γὰρ αὑτοῦ πρῶτον οὐσίαν εἰς μέσον τιθέναι, πολλὴν μὲν οὖσαν ἐν τοῖς γεωργουμένοις καὶ νεμομένοις, ἄνευ δὲ τούτων ἑξακόσια τάλαντα νομίσματος ἔχουσαν τὸ δὲ αὐτὸ καὶ τὰς μητέρας ποιεῖν καὶ τοὺς φίλους καὶ οἰκείους, πλουσιωτάτους ὄντας Σπαρτιατῶν.", "st": "Agis 9.2"}, {"sp": "N", "t": "ὁ μὲν οὖν δῆμος ἐξεπλάγη τὴν μεγαλοψυχίαν τοῦ νεανίσκου, καὶ περιχαρὴς ἦν ὡς δι’ ἐτῶν ὁμοῦ τι διακοσίων πεφηνότος ἀξίου τῆς Σπάρτης βασιλέως· ὁ δὲ Λεωνίδας τότε δὴ μάλιστα πρὸς τοὐναντίον ἐφιλονείκησε. λογιζόμενος γάρ ὅτι ταὐτὰ μὲν ἀναγκασθήσεται ποιεῖν, οὐ τὴν αὐτὴν δὲ χάριν ἕξει παρὰ τοῖς πολίταις, ἀλλὰ πάντων ὁμοίως ἃ κέκτηνται κατατιθεμένων μόνῳ τῷ ἀρξαμένῳ προσθήσουσι τὴν τιμήν, ἠρώτα τὸν Ἆγιν εἰ δίκαιον ἄνδρα καὶ σπουδαῖον ἡγεῖται γεγονέναι Λυκοῦργον. ὁμολογήσαντος δ’ ἐκείνου, ποῦ τοίνυν, ἔφη, Λυκοῦργος ἢ χρεῶν ἀποκοπὰς ἔδωκεν ἢ ξένους κατέταξεν εἰς τὴν πολιτείαν, ὃς οὐδὲ ὅλως ἐνόμιζεν ὑγιαίνειν τὴν πόλιν μὴ χρωμένην ξενηλασίαις;", "st": "Agis 10.1"}, {"sp": "N", "t": "ὁ δὲ Ἆγις ἀπεκρίνατο μὴ θαυμάζειν τὸν Λεωνίδαν, εἰ τεθραμμένος ἐν ξένῃ καὶ πεπαιδοποιημένος ἐκ γάμων σατραπικῶν ἀγνοεῖ τὸν Λυκοῦργον, ὅτι τὸ μὲν ὀφείλειν καὶ δανείζειν ἅμα τῷ νομίσματι συνεξέβαλεν ἐκ τῆς πόλεως, τῶν δ’ ἐν ταῖς πόλεσι ξένων τοὺς τοῖς ἐπιτηδεύμασι καὶ ταῖς διαίταις ἀσυμφύλους μᾶλλον ἐδυσχέραινε· καὶ γὰρ ἐκείνους ἤλαυνεν οὐ τοῖς σώμασι πολεμῶν, ἀλλὰ τοὺς βίους αὐτῶν καὶ τοὺς τρόπους δεδιώς, μὴ συναναχρωννύμενοι τοῖς πολίταις τρυφῆς καὶ μαλακίας καὶ πλεονεξίας ἐντέκωσι ζῆλον· ἐπεὶ Τέρπανδρόν γε καὶ Θάλητα καὶ Φερεκύδην ξένους ὄντας, ὅτι τὰ αὐτὰ τῷ Λυκούργῳ διετέλουν ᾄδοντες καὶ φιλοσοφοῦντες, ἐν Σπάρτῃ τιμηθῆναι διαφερόντως. σὺ δὲ Ἐκπρέπη μὲν, ἔφησεν, ἐπαινεῖς, ὃς ἐφορεύων Φρύνιδος τοῦ μουσικοῦ σκεπάρνῳ τὰς δύο τῶν ἐννέα χορδῶν ἐξέτεμε, καὶ τοὺς ἐπὶ Τιμοθέῳ πάλιν τὸ αὐτὸ τοῦτο πράξαντας, ἡμᾶς δὲ μέμφῃ τρυφὴν καὶ πολυτέλειαν καὶ ἀλαζονείαν ἐκ τῆς Σπάρτης ἀναιροῦντας, ὥσπερ οὐχὶ κἀκείνων τὸ ἐν μουσικῇ σοβαρὸν καὶ περιττὸν ὅπως ἐνταῦθα μὴ προέλθῃ φυλαττομένων, ὅπου γενομένων βίων καὶ τρόπων ἀμετρία καὶ πλημμέλεια τὴν πόλιν ἀσύμφωνον καὶ ἀνάρμοστον ἑαυτῇ πεποίηκεν.", "st": "Agis 10.3"}, {"sp": "N", "t": "ἐκ τούτου τῷ μὲν Ἄγιδι τὸ πλῆθος ἐπηκολούθησεν, οἱ δὲ πλούσιοι τόν τε Λεωνίδαν παρεκάλουν μὴ σφᾶς προέσθαι, καὶ τοὺς γέροντας, οἷς τὸ κράτος ἦν ἐν τῷ προβουλεύειν, δεόμενοι καὶ πείθοντες ἴσχυσαν, ὅσον ἑνὶ πλείονας γενέσθαι τοὺς ἀποψηφισαμένους τὴν ῥήτραν. ὁ δὲ Λύσανδρος ἔτι τὴν ἀρχὴν ἔχων ὥρμησε τὸν Λεωνίδαν διώκειν κατὰ δή τινα νόμον παλαιόν, ὃς οὐκ ἐᾷ τὸν Ἡρακλείδην ἐκ γυναικὸς ἀλλοδαπῆς τεκνοῦσθαι, τὸν δὲ ἀπελθόντα τῆς Σπάρτης ἐπὶ μετοικισμῷ πρὸς ἑτέρους ἀποθνῄσκειν κελεύει, ταῦτα κατὰ τοῦ Λεωνίδᾳ λέγειν ἑτέρους διδάξας, αὐτὸς παρεφύλαττε μετὰ τῶν συναρχόντων τὸ σημεῖον.", "st": "Agis 11.1"}, {"sp": "N", "t": "ἔστι δὲ τοιόνδε· δι’ ἐτῶν ἐννέα λαβόντες οἱ ἔφοροι νύκτα καθαρὰν καὶ ἀσέληνον, σιωπῇ καθέζονται πρὸς οὐρανὸν ἀποβλέποντες. ἐὰν οὖν ἐκ μέρους τινὸς εἰς ἕτερον μέρος ἀστὴρ διᾴξῃ, κρίνουσι τοὺς βασιλεῖς ὡς περὶ τὸ θεῖον ἐξαμαρτάνοντας, καὶ καταπαύουσι τῆς ἀρχῆς, μέχρι ἂν ἐκ Δελφῶν ἢ Ὀλυμπίας χρησμὸς ἔλθῃ τοῖς ἡλωκόσι τῶν βασιλέων βοηθῶν.", "st": "Agis 11.3"}, {"sp": "N", "t": "τοῦτο δὴ τὸ σημεῖον αὐτῷ γεγονέναι λέγων ὁ Λύσανδρος κρίσιν τῷ Λεωνίδᾳ προὔθηκε, καὶ μάρτυρας παρεῖχεν ὡς ἐκ γυναικὸς Ἀσιανῆς, ἣν τῶν Σελεύκου τινὸς ὑπάρχων αὐτῷ συνοικίσαντος ἔσχε, τεκνώσαιτο δύο παιδία, δυσχεραινόμενος δὲ καὶ μισούμενος ὑπὸ τῆς γυναικὸς ἐπανέλθοι παρὰ γνώμην οἴκαδε, καὶ διαδοχῆς ἔρημον ἀνέλοιτο τὸ βασίλειον. ἅμα δὲ τῇ δίκῃ Κλεόμβροτον ἔπειθε τῆς βασιλείας ἀντιποιεῖσθαι, γαμβρὸν ὄντα τοῦ Λεωνίδᾳ, γένους δὲ τοῦ βασιλικοῦ, φοβηθεὶς οὖν ὁ Λεωνίδας ἱκέτης γίνεται τῆς Χαλκιοίκου, καὶ συνικέτευεν ἡ θυγάτηρ τῷ πατρί, τὸν Κλεόμβροτον ἀπολιποῦσα. καλουμένου δὲ πρὸς τὴν δίκην αὐτοῦ καὶ μὴ καταβαίνοντος, ἐκεῖνον ἀποψηφισάμενοι τὴν βασιλείαν τῷ Κλεομβρότῳ παρέδωκαν.", "st": "Agis 11.4"}, {"sp": "N", "t": "ἐν τούτῳ δὲ τῆς ἀρχῆς ὁ Λύσανδρος ἀπηλλάγη τὸν χρόνου διελθόντος. οἱ δὲ κατασταθέντες ἔφοροι τὸν μὲν Λεωνίδαν ἀνέστησαν ἱκετεύοντα, τῷ δὲ Λυσάνδρῳ καὶ τῷ Μανδροκλείδᾳ δίκην ἐπῆγον ὡς παρὰ τὸν νόμον χρεῶν ἀποκοπὰς καὶ γῆν ἀναδάσασθαι ψηφισαμένοις. κινδυνεύοντες οὖν ἐκεῖνοι πείθουσι τοὺς βασιλεῖς ὁμοῦ γενομένους χαίρειν ἐᾶν τὰ τῶν ἐφόρων βουλεύματα· τοῦτο γὰρ τὸ ἀρχεῖον ἰσχύειν ἐκ διαφορᾶς τῶν βασιλέων, τῷ τὰ βελτίονα λέγοντι προστιθέμενον τὴν ψῆφον, ὅταν ἅτερος ἐρίζῃ πρὸς τὸ συμφέρον· ἀμφοῖν δὲ ταὐτὰ βουλευομένων ἄλυτον εἶναι τὴν ἐξουσίαν, καὶ παρανόμως μαχεῖσθαι πρὸς τοὺς βασιλεῖς, ὧν μαχομένων διαιτᾶν καὶ βραβεύειν αὐτοῖς εἶναι προσῆκον, οὐχὶ πολυπραγμονεῖν ὁμοφρονούντων. οὕτω δὴ πεισθέντες ἀμφότεροι καὶ μετὰ τῶν φίλων εἷς ἀγορὰν καταβάντες ἀνέστησαν μὲν ἐκ τῶν δίφρων τοὺς ἐφόρους, ἄλλους δ’ ἀντ’ αὐτῶν ἀπέδειξαν, ὧν εἷς ἦν Ἀγησίλαος, ὁπλίσαντες δὲ τῶν νέων πολλοὺς καὶ λύσαντες τοὺς δεδεμένους ἐγένοντο φοβεροὶ τοῖς ὑπεναντίοις ὡς πολλοὺς ἀποκτενοῦντες. ἀπέθανε δὲ οὐδεὶς ὑπ’ αὐτῶν, ἀλλὰ καὶ Λεωνίδαν εἷς Τεγέαν ὑπεξιόντα βουληθέντος διαφθεῖραι τοῦ Ἀγησιλάου, καὶ πέμψαντος ἐπ’ αὐτὸν εἷς τὴν ὁδὸν ἄνδρας, πυθόμενος ὁ Ἆγις ἑτέρους ἀπέστειλε πιστούς, οἳ τὸν Λεωνίδαν περισχόντες ἀσφαλῶς εἷς Τεγέαν κατέστησαν.", "st": "Agis 12.1"}, {"sp": "N", "t": "οὕτω δὲ τῆς πράξεως αὐτοῖς ὁδῷ βαδιζούσης καὶ μηδενὸς ἐνισταμένου μηδὲ διακωλύοντος, εἷς ἀνὴρ, Ἀγησίλαος, ἀνέτρεψε πάντα καὶ διελυμήνατο, κάλλιστον διανόημα καὶ Λακωνικώτατον αἰσχίστῳ νοσήματι τῇ φιλοπλουτίᾳ διαφθείρας. ἐπειδὴ γὰρ ἐκέκτητο μὲν ἐν τοῖς μάλιστα πολλὴν καὶ ἀγαθὴν χώραν, ὤφειλε δὲ πάμπολλα, μήτε διαλῦσαι δυνάμενος τὰ χρέα μήτε τὴν χώραν προέσθαι βουλόμενος ἔπεισε τὸν Ἆγιν ὡς ἀμφοτέρων μὲν ἅμα πραττομένων μέγας ἔσοιτο περὶ τὴν πόλιν ὁ νεωτερισμός, εἰ δὲ τῇ τῶν χρεῶν ἀφέσει θεραπευθεῖεν οἱ κτηματικοὶ πρότερον, εὐκόλως ἂν αὐτῶν καὶ καθ’ ἡσυχίαν ὕστερον ἐνδεξομένων τὸν ἀναδασμόν. ταῦτα δὲ καὶ τοῖς περὶ Λύσανδρον ἐδόκει, συνεξαπατωμένοις ὑπὸ τοῦ Ἀγησιλάου, καὶ τὰ παρὰ τῶν χρεωστῶν γραμματεῖα συνενέγκαντες εἰς ἀγοράν, ἃ κλάρια καλοῦσι, καὶ πάντα συνθέντες εἰς ἓν συνέπρησαν. ἀρθείσης δὲ φλογός οἱ μὲν πλούσιοι καὶ δανειστικοὶ περιπαθοῦντες ἀπῆλθον, ὁ δὲ Ἀγησίλαος ὥσπερ ἐφυβρίζων οὐκ ἔφη λαμπρότερον ἑωρακέναι φῶς οὐδὲ πῦρ ἐκείνου καθαρώτερον.", "st": "Agis 13.1"}, {"sp": "N", "t": "ἀξιούντων δὲ τῶν πολλῶν καὶ τὴν γῆν εὐθὺς νέμεσθαι καὶ τῶν βασιλέων οὕτω ποιεῖν κελευόντων, ἀσχολίας τινὰς ἐμβάλλων ὁ Ἀγησίλαος ἀεὶ καὶ προφάσεις λέγων παρῆγε τὸν χρόνον, ἄχρι οὗ στρατεία συνέβη τῷ Ἄγιδι, μεταπεμπομένων τῶν Ἀχαιῶν συμμάχων ὄντων βοήθειαν ἐκ Λακεδαίμονος. Αἰτωλοὶ γὰρ ἦσαν ἐπίδοξοι διὰ τῆς Μεγαρικῆς ἐμβαλοῦντες εἰς Πελοπόννησον καὶ τοῦτο κωλύσων Ἄρατος ὁ τῶν Ἀχαιῶν στρατηγὸς ἤθροιζε δύναμιν καὶ τοῖς ἐφόροις ἔγραφεν.", "st": "Agis 13.4"}, {"sp": "N", "t": "οἱ δὲ τὸν Ἆγιν εὐθὺς ἐξέπεμπον ἐπηρμένον τῇ φιλοτιμίᾳ καὶ προθυμίᾳ τῶν συστρατευομένων, νέοι γὰρ ὄντες οἱ πλεῖστοι καὶ πένητες, καὶ τὴν μὲν ἀπὸ τῶν χρεῶν ἄδειαν ἔχοντες ἤδη καὶ λελυμένοι, τοὺς δὲ ἀγροὺς ἐλπίζοντες, ἂν ἐπανέλθωσιν ἐκ τῆς στρατείας, νεμηθήσεσθαι, θαυμαστοὺς τῷ Ἄγιδι παρεῖχον ἑαυτούς· καὶ θέαμα ταῖς πόλεσιν ἦσαν ἀβλαβῶς καὶ πράως καὶ μονονοὺκ ἀψοφητὶ διαπορευόμενοι τὴν Πελοπόννησον, ὥστε θαυμάζειν καὶ διαλογίζεσθαι τοὺς Ἕλληνας οἷος ἦν ἄρα κόσμος Λακωνικοῦ στρατεύματος Ἀγησίλαον ἔχοντος ἢ Λύσανδρον ἐκεῖνον ἢ Λεωνίδαν τὸν παλαιὸν ἡγούμενον, ὅπου πρὸς μειράκιον ὀλίγου δεῖν νεώτατον ἁπάντων αἰδὼς τοσαύτη καὶ φόβος ἐστὶ τῶν συστρατευομένων. καὶ μέντοι καὶ αὐτὸς ὁ νεανίσκος εὐτελείᾳ καὶ φιλοπονίᾳ, καὶ τῷ μηδὲν ἰδιώτου λαμπρότερον ἠμφιέσθαι καὶ ὡπλίσθαι σεμνυνόμενος ἀξιοθέατος ἦν καὶ ζηλωτὸς ὑπὸ τῶν πολλῶν ἐπεὶ τοῖς γε πλουσίοις οὐκ ἤρεσκεν ὁ νεωτερισμὸς αὐτοῦ, δεδιόσι μὴ κίνημα καὶ παράδειγμα τοῖς πανταχόσε δήμοις γένηται.", "st": "Agis 14.1"}, {"sp": "N", "t": "συμμίξας δὲ τῷ Ἀράτῳ περὶ Κόρινθον ὁ Ἆγις ἔτι βουλευομένῳ περὶ μάχης καὶ παρατάξεως πρὸς τοὺς πολεμίους, ἐπεδείξατο καὶ προθυμίαν πολλὴν καὶ τόλμαν οὐ μανικὴν οὐδὲ ἀλόγιστον. ἔφη γὰρ αὐτῷ μὲν δοκεῖν διαμάχεσθαι καὶ μὴ παριέναι τὸν πόλεμον εἴσω, τὰς πύλας τῆς Πελοποννήσου προεμένους, ποιήσειν δὲ τὸ δοκοῦν Ἀράτῳ· καὶ γὰρ πρεσβύτερόν τε εἶναι καὶ στρατηγεῖν Ἀχαιῶν, οἷς οὐχὶ προστάξων οὐδὲ ἡγησόμενος, ἀλλὰ συστρατευσόμενος ἥκοι καὶ βοηθήσων.", "st": "Agis 15.1"}, {"sp": "N", "t": "ὁ δὲ Σινωπεὺς Βάτων αὐτὸν οὐκ ἐθέλειν μάχεσθαί φησι τὸν Ἆγιν Ἀράτου κελεύοντος, οὐκ ἐντετυχηκὼς οἷς Ἄρατος γέγραφε περὶ τούτων, ἀπολογιζόμενος ὅτι βέλτιον ἡγεῖτο, τοὺς καρποὺς σχεδὸν ἅπαντας συγκεκομισμένων ἤδη τῶν γεωργῶν, παρελθεῖν τοὺς πολεμίους ἢ μάχῃ διακινδυνεῦσαι περὶ τῶν ὅλων.", "st": "Agis 15.2"}, {"sp": "N", "t": "ἐπεὶ δ’ οὖν Ἄρατος ἀπέγνω μάχεσθαι καὶ τοὺς συμμάχους ἐπαινέσας διαφῆκε, θαυμασθεὶς ὁ Ἆγις ἀνεζεύγνυεν, ἤδη τῶν ἔνδον ἐν Σπάρτῃ θόρυβον πολὺν ἐχόντων καὶ μεταβολήν.", "st": "Agis 15.3"}, {"sp": "N", "t": "ὁ γὰρ Ἀγησίλαος ἐφορεύων, ἀπηλλαγμένος οἷς ταπεινὸς ἦν πρότερον, οὐδενὸς ἐφείδετο φέροντος ἀργύριον ἀδικήματος, ἀλλὰ μῆνα τρισκαιδέκατον, οὐκ ἀπαιτούσης τότε τῆς περιόδου, παρὰ τὴν νενομισμένην τάξιν τῶν χρόνων ἐνέβαλε τοῖς τέλεσι καὶ παρέπραττε, δεδιὼς δὲ τοὺς ἀδικουμένους καὶ μισούμενος ὑπὸ πάντων ἔτρεφε μαχαιροφόρους, καὶ φυλαττόμενος ὑπὸ τούτων κατέβαινεν εἰς τὸ ἀρχεῖον. καὶ τῶν βασιλέων τοῦ μὲν ὅλως καταφρονεῖν, τὸν δὲ Ἆγιν ἐβούλετο δοκεῖν διὰ τὴν συγγένειαν μᾶλλον ἢ διὰ τὴν βασιλείαν ἔν τινι τιμῇ τίθεσθαι. διέδωκε δὲ λόγον ὡς καὶ αὖθις ἐφορεύσων.", "st": "Agis 16.1"}, {"sp": "N", "t": "διὸ καὶ θᾶσσον ἀποκινδυνεύσαντες οἱ ἐχθροὶ καὶ συστάντες ἐκ Τεγέας ἀναφανδὸν τὸν Λεωνίδαν ἐπὶ τὴν ἀρχὴν κατήγαγον, ἡδέως καὶ τῶν πολλῶν θεασαμένων· ὠργίζοντο γὰρ πεφενακισμένοι τῆς χώρας μὴ νεμηθείσης. τὸν μὲν οὖν Ἀγησίλαον ὁ υἱὸς Ἱππομέδων, δεόμενος τῶν πολιτῶν καὶ πᾶσι προσφιλὴς ὢν δι’ ἀνδραγαθίαν, ὑπεξήγαγε καὶ διέσωσε· τῶν δὲ βασιλέων ὁ μὲν Ἆγις ἐπὶ τὴν Χαλκίοικον κατέφυγεν, ὁ δὲ Κλεόμβροτος εἰς τὸ τοῦ Ποσειδῶνος ἱερὸν ἐλθὼν ἱκέτευε· καὶ γὰρ ἐδόκει τούτῳ μᾶλλον ὁ Λεωνίδας χαλεπὸς εἶναι, καὶ παρεὶς τὸν Ἆγιν ἐπὶ τοῦτον ἀνέβη στρατιώτας ἔχων καὶ κατηγόρει μετ’ ὀργῆς ὅτι γαμβρὸς ὢν ἐπεβούλευσεν αὐτῷ καὶ τὴν βασιλείαν ἀφείλετο καὶ συνεξέβαλε τῆς πατρίδος.", "st": "Agis 16.3"}, {"sp": "N", "t": "ὁ μὲν οὖν Κλεόμβροτος οὐδὲν εἶχεν εἰπεῖν, ἀλλ’ ἠπορημένος ἐκάθητο καί σιωπῶν ἡ δὲ Χιλωνίς, ἡ τοῦ Λεωνίδου θυγάτηρ, πρότερον μὲν ἀδικουμένῳ τῷ πατρὶ συνηδικεῖτο, καί τοῦ Κλεομβρότου τὴν βασιλείαν παραλαβόντος ἀποστᾶσα τὴν τοῦ πατρὸς συμφορὰν ἐθεράπευε, καί παρόντι μὲν συνικέτευε, φεύγοντος δὲ πενθοῦσα καὶ χαλεπῶς ἔχουσα πρὸς τὸν Κλεόμβροτον διετέλει, τότε δὲ αὖ πάλιν ταῖς τύχαις συμμεταβάλλουσα μετὰ τοῦ ἀνδρὸς ἱκέτις ὤφθη καθεζομένη, περιβεβληκυῖα τὰς χεῖρας ἐκείνῳ καί τῶν παιδίων τὸ μὲν ἔνθεν, τὸ δ’ ἔνθεν ὑφ’ αὑτὴν ἔχουσα. θαυμαζόντων δὲ πάντων καί δακρυόντων ἐπὶ τῇ χρηστότητι καί φιλοστοργίᾳ τῆς γυναικός, ἁψαμένη τῶν πέπλων καί τῆς κόμης ἀτημελῶς ἐχόντων, τοῦτο, εἶπεν, ὦ πάτερ, ἐμοὶ τὸ σχῆμα καί τὴν ὄψιν οὐχ ὁ Κλεομβρότου περιτέθεικεν ἔλεος, ἀλλ’ ἀπὸ τῶν σῶν κακῶν καί τῆς σῆς φυγῆς μεμένηκέ μοι σύντροφον καί σύνοικον τὸ πένθος, πότερον οὖν δεῖ με σοῦ βασιλεύοντος ἐν Σπάρτῃ καί νικῶντος ἐγκαταβιῶναι ταύταις ταῖς συμφοραῖς, ἢ λαβεῖν ἐσθῆτα λαμπρὰν καί βασιλικήν, ἐπιδοῦσαν ὑπὸ σοῦ τὸν παρθένιον ἄνδρα φονευόμενον; ὃς εἰ μὴ παραιτεῖταί σε μηδὲ πείθει τέκνων καί γυναικὸς δάκρυσι, χαλεπωτέραν ἢ σὺ βούλει δίκην ὑφέξει τῆς κακοβουλίας ἐπιδὼν ἐμὲ τὴν φιλτάτην αὐτῷ προαποθανοῦσαν. τίνι γὰρ ἐμὲ δεῖ ζῆν παρρησίᾳ πρὸς τὰς ἄλλας γυναῖκας, ᾗ μήτε παρ’ ἀνδρὸς δεομένῃ μήτε παρὰ πατρὸς ἔλεός ἐστιν; ἀλλὰ καί γυνὴ καί θυγάτηρ συνατυχεῖν καί συνατιμάζεσθαι τοῖς ἐμαυτῆς ἐγενόμην. τούτῳ μὲν οὖν εἰ καί τις ἦν λόγος εὐπρεπής, ἐγὼ τοῦτον ἀφειλόμην τότε σοὶ συνεξετασθεῖσα καὶ καταμαρτυρήσασα τῶν ὑπὸ τούτου γενομένων σὺ δὲ αὐτῷ τὸ ἀδίκημα ποιεῖς εὐαπολόγητον, οὕτω μέγα καί περιμάχητον ἀποφαίνων τὸ βασιλεύειν ὥστε δι’ αὐτὸ καί γαμβροὺς φονεύειν καί τέκνων ἀμελεῖν εἶναι δίκαιον.", "st": "Agis 17.1"}, {"sp": "N", "t": "ἡ μὲν Χιλωνὶς τοιαῦτα ποτνιωμένη τό τε πρόσωπον ἐπὶ τὴν κεφαλὴν ἐπέθηκε τοῦ Κλεομβρότου, καί τὸ βλέμμα διεφθαρμένον καί συντετηκὸς ὑπὸ λύπης περιήνεγκεν εἷς τοὺς παρόντας. ὁ δὲ Λεωνίδας διαλεχθεὶς τοῖς φίλοις τὸν μὲν Κλεόμβροτον ἐκέλευσεν ἀναστάντα φεύγειν, τῆς δὲ παιδὸς μένειν ἐδεῖτο καί μὴ καταλιπεῖν ἑαυτόν οὕτω φιλοῦντα καί δεδωκότα χάριν τὴν τοῦ ἀνδρὸς αὐτῇ σωτηρίαν. οὐ μὴν ἔπεισεν, ἀλλ’ ἀνισταμένῳ τῷ ἀνδρὶ θάτερον τῶν παιδίων ἐγχειρίσασα, θάτερον δ’ Ἀναλαβοῦσα καί προσκυνήσασα τὸν βωμὸν τοῦ θεοῦ συνεξῆλθεν, ὥστε εἰ μὴ πάνυ διεφθαρμένος ἦν ὑπὸ κενῆς δόξης ὁ Κλεόμβροτος, εὐτύχημα ἂν ἡγήσατο τὴν φυγὴν αὑτῷ τῆς βασιλείας μεῖζον εἶναι διὰ τὴν γυναῖκα.", "st": "Agis 18.1"}, {"sp": "N", "t": "μεταστησάμενος δὲ τὸν Κλεόμβροτον ὁ Λεωνίδας καὶ τοὺς πρώτους ἐφόρους ἐκβαλὼν τῆς ἀρχῆς, ἑτέρους δὲ ποιησάμενος, εὐθὺς ἐπεβούλευε τῷ Ἄγιδι. καί πρῶτον μὲν ἔπειθεν αὐτὸν ἀναστῆναι καὶ συμβασιλεύειν, ὡς δεδωκότων συγγνώμην τῶν πολιτῶν συνεξηπατῆσθαι γὰρ ὑπὸ τοῦ Ἀγησιλάου νέον ὄντα καί φιλότιμον. ἐκείνου δὲ ὑφορωμένου καί κατὰ χώραν μένοντος αὐτὸς μὲν ἐπαύσατο φενακίζων καί κατειρωνευόμενος, Ἀμφάρης δὲ καί Δαμοχάρης καί Ἀρκεσίλαος ἀναβαίνοντες εἰώθεσαν αὐτῷ διαλέγεσθαι· καί ποτε καί παραλαβόντες ἐπὶ λουτρὸν ἀπὸ τοῦ ἱεροῦ κατήγαγον καί λουσάμενον πάλιν εἷς τὸ ἱερὸν κατέστησαν. καί ἦσαν πάντες μὲν αὐτῷ συνήθεις, ὁ δὲ Ἀμφάρης καί κεχρημένος ἔναγχος ἱμάτια καί ποτήρια τῶν πολυτελῶν παρὰ τῆς Ἀγησιστράτας ἐπεβούλευε διὰ ταῦτα τῷ βασιλεῖ καί ταῖς γυναιξὶν ὡς ἀποστερήσων. καί μάλιστά γε αὐτὸς ὑπακοῦσαι τῷ Λεωνίδᾳ λέγεται καί παροξῦναι τοὺς ἐφόρους, ὧν καί αὐτὸς εἷς ἦν.", "st": "Agis 18.3"}, {"sp": "N", "t": "ἐπεὶ δὲ ὁ Ἆγις τὸν μὲν ἄλλον ἐν τῷ ἱερῷ διέτριβε χρόνον, εἰώθει δὲ καταβαίνειν ὅτε τύχοι πρὸς τὸ λουτρόν, ἐκεῖ συλλαβεῖν αὑτὸν ἔγνωσαν, ὅταν ἔξω τοῦ ἱεροῦ γένηται. καὶ παραφυλάξαντες λελουμένον ἀπήντησαν καὶ ἠσπάσαντο, καὶ συμπροῆγον ἅμα διαλεγόμενοι καὶ παίζοντες ὡς πρὸς συνήθη καὶ νέον. ἐκτροπὴν δέ τινα τῆς ὁδοῦ πλαγίαν πρὸς τὸ δεσμωτήριον ἐχούσης, ὡς ἐγένοντο κατ’ αὐτὴν βαδίζοντες, ὁ μὲν Ἀμφάρης διὰ τὸ ἄρχειν ἁψάμενος τοῦ Ἄγιδος, ἄγω σε, εἶπεν, ἐπὶ τοὺς ἐφόρους, ὦ Ἆγι, λόγον ὑφέξοντα τῶν πεπολιτευμένων· ὁ δὲ Δαμοχάρης, εὔρωστος ὢν καὶ μέγας, τὸ ἱμάτιον περιβαλὼν περὶ τὸν τράχηλον εἷλκεν. ἄλλων δὲ ἐπωθούντων ὄπισθεν ἐκ παρασκευῆς, οὐδενὸς βοηθοῦντος, ἀλλ’ ἐρημίας οὔσης, ἐμβάλλουσιν αὑτὸν εἰς τὸ δεσμωτήριον. εὐθὺς δὲ παρῆν ὁ μὲν Λεωνίδας μισθοφόρους ἔχων πολλοὺς, καὶ τὸ οἴκημα περιέσχεν ἔξωθεν, οἱ δὲ ἔφοροι πρὸς τὸν Ἆγιν εἰσῆλθον, καὶ τῶν γερόντων εἰς τὸ οἴκημα μεταπεμψάμενοι τοὺς ταὐτὰ βουλομένους, ὡς δὴ κρίσεως αὐτῷ γινομένης, ἐκέλευον ὑπὲρ τῶν πεπραγμένων ἀπολογεῖσθαι. γελάσαντος δὲ τοῦ νεανίσκου πρὸς τὴν εἰρωνείαν αὐτῶν, ὁ μὲν Ἀμφάρης οἰμωξόμενον ἐκάλει καὶ δίκην ὑφέξοντα τῆς ἰταμότητος· ἄλλος δὲ τῶν ἐφόρων, οἷον ἐνδιδοὺς τῷ Ἄγιδι καὶ δεικνύων ἀποφυγὴν τῆς αἰτίας, ἠρώτησεν εἰ ταῦτα ἔπραξεν ὑπὸ Λυσάνδρου καὶ Ἀγησιλάου βιασθείς. ἀποκριναμένου δὲ τοῦ Ἄγιδος ὡς βιασθεὶς μὲν ὑπ’ οὐδενός, ζηλῶν δὲ καὶ μιμούμενος τὸν Λυκοῦργον ἐπὶ τὴν αὐτὴν ἔλθοι πολιτείαν, πάλιν ὁ αὐτὸς ἠρώτησεν εἰ μετανοεῖ τοῖς πεπραγμένοις. φήσαντος δὲ τοῦ νεανίσκου μὴ μετανοεῖν ἐπὶ τοῖς κάλλιστα βεβουλευμένοις, κἂν τὰ ἔσχατα πεισόμενον αὑτὸν ἴδῃ, θάνατον αὐτοῦ κατεψηφίσαντο, καὶ τοὺς ὑπηρέτας ἐκέλευον ἄγειν εἰς τὴν καλουμένην Δεχάδα. τοῦτο δέ ἐστὶν οἴκημα τῆς εἱρκτῆς ἐν ᾧ θανατοῦσι τοὺς καταδίκους ἀποπνίγοντες. ὁρῶν δὲ τοὺς ὑπηρέτας ὁ Δαμοχάρης οὐ τολμῶντας ἅψασθαι τοῦ Ἄγιδος, ὁμοίως δὲ καὶ τῶν μισθοφόρων τοὺς παρεστῶτας ἀποστρεφομένους καὶ φεύγοντας τὸ ἔργον, ὡς οὐ θεμιτὸν οὐδὲ νενομισμένον βασιλέως σώματι τὰς χεῖρας προσφέρειν, διαπειλησάμενος αὐτοῖς καὶ λοιδορηθεὶς εἷλκεν αὐτὸς εἰς τὸ οἴκημα τὸν Ἆγιν. ἤδη γὰρ ᾔσθηντο πολλοὶ τὴν σύλληψιν, καὶ θόρυβος ἦν ἐπὶ ταῖς θύραις καὶ φῶτα πολλά, καὶ παρῆσαν ἥ τε μήτηρ τοῦ Ἄγιδος καὶ ἡ μάμμη βοῶσαι καὶ δεόμεναι τὸν βασιλέα τῶν Σπαρτιατῶν λόγου καὶ κρίσεως τυχεῖν ἐν τοῖς πολίταις. διὸ καὶ μάλιστα κατήπειξαν τὴν ἀναίρεσιν, ὡς ἐξαρπαγησομένου νυκτὸς ἂν πλείονες ἐπέλθωσιν.", "st": "Agis 19.1"}, {"sp": "N", "t": "ὁ μὲν οὖν Ἆγις ἐπὶ τὴν στραγγάλην πορευόμενος, ὡς εἶδέ τινα τῶν ὑπηρετῶν δακρύοντα καὶ περιπαθοῦντα, παῦσαί με, εἶπεν, ὦ ἄνθρωπε, κλαίων καὶ γὰρ οὕτως παρανόμως καὶ ἀδίκως ἀπολλύμενος κρείττων εἰμὶ τῶν ἀναιρούντων καὶ ταῦτ’ εἰπὼν παρέδωκε τῷ βρόχῳ τόν τράχηλον ἑκουσίως. ὁ δὲ Ἀμφάρης προελθὼν ἐπὶ τὰς θύρας, καὶ τὴν Ἀγησιστράταν προσπεσοῦσαν αὐτῷ διὰ συνήθειαν καὶ φιλίαν ἀναστήσας, οὐδὲν ἔφη περὶ τόν Ἆγιν ἔσεσθαι βίαιον οὐδὲ ἀνήκεστον ἐκέλευε δὲ κἀκείνην, εἰ βούλοιτο, πρὸς τόν υἱὸν εἰσελθεῖν. ἐκείνης δὲ καὶ τὴν μητέρα μετ’ αὐτῆς παρεῖναι δεομένης οὐδὲν ἔφη κωλύειν ὁ Ἀμφάρης· καὶ δεξάμενος ἀμφοτέρας, καὶ πάλιν κλεῖσαι τὰς θύρας τοῦ δεσμωτηρίου κελεύσας, προτέραν μὲν τὴν Ἀρχιδαμίαν παρέδωκεν, ἤδη σφόδρα πρεσβῦτιν οὖσαν καὶ καταγεγηρακυῖαν ἐν ἀξιώματι μεγίστῳ τῶν πολιτίδων, ἀποθανούσης δὲ ἐκείνης ἐκέλευσε τὴν Ἀγησιστράταν ἔσω βαδίζειν. ὡς δὲ εἰσελθοῦσα τόν τε υἱὸν ἐθεάσατο χαμαὶ κείμενον καὶ τὴν μητέρα νεκρὰν ἐκ τοῦ βρόχου κρεμαμένην, ἐκείνην μὲν αὐτὴ τοῖς ὑπηρέταις συγκαθεῖλε καὶ παρεκτείνασα τῷ Ἄγιδι τὸ σῶμα περιέστειλε καὶ κατεκάλυψε· τῷ δὲ υἱῷ προσπεσοῦσα καὶ φιλήσασα τὸ πρόσωπον, ἡ πολλή σε, εἶπεν, ὦ παῖ, εὐλάβεια καὶ τὸ πρᾶον καὶ φιλάνθρωπον ἀπώλεσε μεθ’ ἡμῶν. ὁ δὲ Ἀμφάρης ἀπὸ τῆς θύρας ὁρῶν τὰ γινόμενα καὶ τὰς φωνὰς ἀκούων ἐπεισῆλθε, καὶ πρὸς τὴν Ἀγησιστράταν μετ’ ὀργῆς εἶπεν εἰ τοίνυν, ἔφη, ταὐτὰ ἐδοκίμαζες τῷ υἱῷ, ταὐτὰ καὶ πείσῃ. καὶ ἡ Ἀγησιστράτα πρὸς τόν βρόχον ἀνισταμένη, μόνον, ἔφη, συνενέγκαι ταῦτα τῇ Σπάρτῃ.", "st": "Agis 20.1"}, {"sp": "N", "t": "τοῦ δὲ πάθους εἰς τὴν πόλιν ἐξαγγελθέντος καὶ τῶν τριῶν σωμάτων ἐκκομιζομένων οὐκ ἦν ὁ φόβος οὕτω μέγας, ὥστε μὴ καταφανεῖς εἶναι τοὺς πολίτας ἀλγοῦντας μὲν ἐπὶ τοῖς γεγονόσι, μισοῦντας δὲ τὸν Λεωνίδαν καὶ τὸν Ἀμφάρην, μηδὲν δεινότερον μηδὲ ἀνοσιώτερον ἐξ οὗ Δωριεῖς Πελοπόννησον οἰκοῦσιν οἰομένους ἐν Σπάρτῃ πεπρᾶχθαι. βασιλεῖ γὰρ, ὡς ἔοικε, Λακεδαιμονίων οὐδὲ οἱ πολέμιοι ῥᾳδίως ἐν ταῖς μάχαις ἀπαντῶντες προσέφερον τὰς χεῖρας, ἀλλ’ ἀπετρέποντο δεδιότες καὶ σεβόμενοι τὸ ἀξίωμα, διὸ καὶ πολλῶν γεγονότων Λακεδαιμονίοις ἀγώνων πρὸς Ἕλληνας εἷς μόνος ἀνῃρέθη πρὸ τῶν Φιλιππικῶν δόρατι πληγεὶς περὶ Λεῦκτρα Κλεόμβροτος. Μεσσηνίων δὲ καὶ Θεόπομπον ὑπ’ Ἀριστομένους πεσεῖν λεγόντων οὔ φασι Λακεδαιμόνιοι, πληγῆναι δὲ μόνον. ἀλλὰ ταῦτα μὲν ἔχει τινὰς ἀμφιλογίας, ἐν δὲ Λακεδαίμονι πρῶτος Ἆγις βασιλεύων ὑπὸ τῶν ἐφόρων ἀπέθανε, καλὰ μὲν ἔργα καὶ πρέποντα τῇ Σπάρτῃ προελόμενος, ἡλικίας δὲ γεγονὼς ἐν ᾗ ἁμαρτάνοντες ἄνθρωποι συγγνώμης τυγχάνουσι, μεμφθεὶς δὲ ὑπὸ τῶν φίλων δικαιότερον ἢ τῶν ἐχθρῶν, ὅτι καὶ Λεωνίδαν περιέσωσε καὶ τοῖς ἄλλοις ἐπίστευσεν, ἡμερώτατος καὶ πραότατος γενόμενος.", "st": "Agis 21.1"}, {"sp": "HDR", "t": "Κλεομένης"}, {"sp": "N", "t": "ἀποθανόντος δὲ αὐτοῦ τὸν μὲν ἀδελφὸν Ἀρχίδαμον οὐκ ἔφθη συλλαβεῖν ὁ Λεωνίδας εὐθὺς ἐκφυγόντα, τὴν δὲ γυναῖκα παιδίον ἔχουσαν νεογνὸν ἐκ τῆς οἰκίας ἀπαγαγὼν βίᾳ Κλεομένει τῷ υἱῷ συνῴκισεν οὐ πάνυ γάμων ὥραν ἔχοντι, τὴν δὲ ἄνθρωπον ἄλλῳ δοθῆναι μὴ βουλόμενος. ἦν γὰρ οὐσίας τε μεγάλης ἐπίκληρος ἡ Ἀγιᾶτις Γυλίππου τοῦ πατρός, ὥρᾳ τε καὶ κάλλει πολὺ τῶν Ἑλληνίδων διαφέρουσα καὶ τὸν τρόπον ἐπιεικής. διὸ πολλὰ μὲν ἐποίησεν, ὥς φασι, μὴ βιασθῆναι δεομένη, συνελθοῦσα δὲ εἰς ταὐτὸ τῷ Κλεομένει τὸν μὲν Λεωνίδαν ἐμίσει, περὶ δὲ αὐτὸν τὸν νεανίσκον ἦν ἀγαθὴ γυνὴ καὶ φιλόστοργος, ἐρωτικῶς ἅμα τῷ λαβεῖν πρὸς αὐτὴν διατεθέντα καί τινα τρόπον συμπαθοῦντα τῇ πρὸς τὸν Ἆγιν εὐνοίᾳ καὶ μνήμῃ τῆς γυναικός, ὥστε καὶ πυνθάνεσθαι πολλάκις περὶ τῶν γεγονότων καὶ προσέχειν ἐπιμελῶς διηγουμένης ἐκείνης ἣν ὁ Ἆγις ἔσχε διάνοιαν καὶ προαίρεσιν.", "st": "Cleom. 1.1"}, {"sp": "N", "t": "ἦν δὲ καὶ φιλότιμος μὲν καὶ μεγαλόφρων ὁ Κλεομένης καὶ πρὸς ἐγκράτειαν καὶ ἀφέλειαν οὐχ ἧττον τοῦ Ἄγιδος εὖ πεφυκώς, τὸ δὲ εὐλαβὲς ἄγαν ἐκεῖνο καὶ πρᾶον οὐκ εἶχεν, ἀλλὰ κέντρον τι θυμοῦ τῇ φύσει προσέκειτο καὶ μετὰ σφοδρότητος ὁρμὴ πρὸς τὸ φαινόμενον ἀεὶ καλόν, ἐφαίνετο δὲ κάλλιστον μὲν αὐτῷ κρατεῖν ἑκόντων, καλὸν δὲ καὶ μὴ πειθομένων περιεῖναι πρὸς τὸ βέλτιον ἐκβιαζόμενον.", "st": "Cleom. 1.3"}, {"sp": "N", "t": "οὐκ ἤρεσκε μὲν οὖν αὐτῷ τὰ κατὰ τὴν πόλιν, ἀπραγμοσύνῃ καὶ ἡδονῇ κατακεκηλημένων τῶν πολιτῶν καὶ τοῦ βασιλέως πάντα τὰ πράγματα χαίρειν ἐῶντος, εἰ μηδεὶς αὑτὸν ἐνοχλοίη σχολάζειν ἐν ἀφθόνοις καὶ τρυφᾶν βουλόμενον, ἀμελουμένων δὲ τῶν κοινῶν, κατ’ οἰκίαν ἑκάστου πρὸς αὑτὸν ἕλκοντος τὸ κερδαλέον· ἀσκήσεως δὲ καὶ σωφροσύνης νέων καὶ καρτερίας καὶ ἰσότητος οὐδὲ ἀσφαλὲς ἦν τούτων τῶν περὶ Ἆγιν ἀπολωλότων μνημονεύειν.", "st": "Cleom. 2.1"}, {"sp": "N", "t": "λέγεται δὲ καὶ λόγων φιλοσόφων τὸν Κλεομένη μετασχεῖν ἔτι μειράκιον ὄντα, Σφαίρου τοῦ Βορυσθενίτου παραβαλόντος εἰς τὴν Λακεδαίμονα καὶ περὶ τοὺς νέους καὶ τοὺς ἐφήβους οὐκ ἀμελῶς διατρίβοντος. ὁ δὲ Σφαῖρος ἐν τοῖς πρώτοις ἐγεγόνει τῶν Ζήνωνος τοῦ Κιτιέως μαθητῶν, καὶ τοῦ Κλεομένους ἔοικε τῆς φύσεως τὸ ἀνδρῶδες ἀγαπῆσαί τε καὶ προσεκκαῦσαι τὴν φιλοτιμίαν. Λεωνίδαν μὲν γὰρ τὸν παλαιὸν λέγουσιν, ἐπερωτηθέντα ποῖός τις αὐτῷ φαίνεται ποιητὴς γεγονέναι Τυρταῖος, εἰπεῖν ἀγαθὸς νέων ψυχὰς κακκανῆν. ἐμπιπλάμενοι γὰρ ὑπὸ τῶν ποιημάτων ἐνθουσιασμοῦ παρὰ τὰς μάχας ἠφείδουν ἑαυτῶν ὁ δὲ Στωϊκὸς λόγος ἔχει τι πρὸς τὰς μεγάλας φύσεις καὶ ὀξείας ἐπισφαλὲς καὶ παράβολον, βαθεῖ δὲ καὶ πράῳ κεραννύμενος ἤθει μάλιστα εἰς τὸ οἰκεῖον ἀγαθὸν ἐπιδίδωσιν.", "st": "Cleom. 2.2"}, {"sp": "N", "t": "ἐπεὶ δὲ τελευτήσαντος τοῦ Λεωνίδου τὴν βασιλείαν παρέλαβε καὶ τοὺς πολίτας τότε δὴ παντάπασιν ἐκλελυμένους ἑώρα, τῶν μὲν πλουσίων καθ’ ἡδονὰς ἰδίας καὶ πλεονεξίας παρορώντων τὰ κοινά, τῶν δὲ πολλῶν διὰ τὸ πράττειν κακῶς περὶ τὰ οἰκεῖα καὶ πρὸς τὸν πόλεμον ἀπροθύμων καὶ πρὸς τὴν ἀγωγὴν ἀφιλοτίμων γεγονότων, αὐτοῦ δὲ ὄνομα βασιλεύοντος ἦν μόνον, ἡ δὲ ἀρχὴ πᾶσα τῶν ἐφόρων, εὐθὺς μὲν εἰς νοῦν ἔθετο τὰ παρόντα μεθιστάναι καὶ κινεῖν, ὄντος δὲ αὐτῷ φίλου Ξενάρους, ἐραστοῦ γεγονότος τοῦτο δὲ ἐμπνεῖσθαι Λακεδαιμόνιοι καλοῦσιν, ἀπεπειρᾶτο τούτου διαπυνθανόμενος τὸν Ἆγιν, ὁποῖος γένοιτο βασιλεὺς καὶ τίνι τρόπῳ καὶ μετὰ τίνων ἐπὶ ταύτην ἔλθοι τὴν ὁδόν. ὁ δὲ Ξενάρης τὸ μὲν πρῶτον οὐκ ἀηδῶς ἐμέμνητο τῶν πραγμάτων ἐκείνων, ὡς ἐπράχθη καθ’ ἕκαστα μυθολογῶν καὶ διηγούμενος· ὡς δὲ ἦν καταφανὴς ὁ Κλεομένης ἐμπαθέστερον προσέχων καὶ κινούμενος ὑπερφυῶς πρὸς τὴν καινοτομίαν τοῦ Ἄγιδος καὶ ταὐτὰ πολλάκις ἀκούειν βουλόμενος, ἐπέπληξεν αὐτῷ πρὸς ὀργὴν ὁ Ξενάρης ὡς οὐχ ὑγιαίνοντι, καὶ τέλος ἀπέστη τοῦ διαλέγεσθαι καὶ φοιτᾶν πρὸς αὐτόν, οὐδενὶ μέντοι τὴν αἰτίαν ἔφρασε τῆς διαφορᾶς, ἀλλ’ αὐτὸν ἔφη γινώσκειν ἐκεῖνον.", "st": "Cleom. 3.1"}, {"sp": "N", "t": "οὕτω δὲ τοῦ Ξενάρους ἀντικρούσαντος ὁ Κλεομένης καὶ τοὺς ἄλλους ὁμοίως ἔχειν ἡγούμενος, αὐτὸς ἐν ἑαυτῷ συνετίθει τὴν πρᾶξιν. οἰόμενος δ’ ἂν ἐν πολέμῳ μᾶλλον ἢ κατ’ εἰρήνην μεταστῆσαι τὰ παρόντα, συνέκρουσε πρὸς τοὺς Ἀχαιοὺς τὴν πόλιν, αὐτοὺς διδόντας ἐγκλημάτων προφάσεις, ὁ γὰρ Ἄρατος ἰσχύων μέγιστον ἐν τοῖς Ἀχαιοῖς ἐβούλετο μὲν ἐξ ἀρχῆς εἰς μίαν σύνταξιν ἀγαγεῖν Πελοποννησίους, καὶ τοῦτο τῶν πολλῶν στρατηγιῶν αὐτῷ καὶ τῆς μακρᾶς πολιτείας ἦν τέλος, ἡγουμένῳ μόνως ἂν οὕτως ἀνεπιχειρήτους ἔσεσθαι τοῖς ἐκτὸς πολεμίοις. ἐπεὶ δὲ τῶν ἄλλων σχεδὸν ἁπάντων αὐτῷ προσγεγονότων ἀπελείποντο Λακεδαιμόνιοι καὶ Ἠλεῖοι καὶ ὅσοι Λακεδαιμονίοις Ἀρκάδων προσεῖχον, ἅμα τῷ τὸν Λεωνίδαν ἀποθανεῖν παρηνώχλει τοῖς Ἀρκάσι καὶ περιέκοπτεν αὐτῶν μάλιστα τοὺς τοῖς Ἀχαιοῖς ὁμοροῦντας, ἀποπειρώμενος τῶν Λακεδαιμονίων, καὶ τοῦ Κλεομένους ὡς νέου καὶ ἀπείρου καταφρονῶν.", "st": "Cleom. 3.4"}, {"sp": "N", "t": "ἐκ τούτου Κλεομένη πρῶτον οἱ ἔφοροι πέμπουσι καταληψόμενον τὸ περὶ τὴν Βέλβιναν Ἀθήναιον, ἐμβολὴ δὲ τῆς Λακωνικῆς τὸ χωρίον ἐστί, καὶ τότε πρὸς τοὺς Μεγαλοπολίτας ἦν ἐπίδικον. καταλαβόντος δὲ τοῦτο καὶ τειχίσαντος τοῦ Κλεομένους ὁ Ἄρατος οὐθὲν ἐγκαλέσας, ἀλλὰ νυκτὸς ἐκστρατεύσας ἐπεχείρησε Τεγεάταις καὶ Ὀρχομενίοις. τῶν δὲ προδοτῶν ἀποδειλιασάντων ὁ μὲν Ἄρατος ἀνεχώρησε λεληθέναι νομίζων, ὁ δὲ Κλεομένης εἰρωνείᾳ χρώμενος ἔγραψε πρὸς αὐτόν, ὡς δὴ παρὰ φίλου πυνθανόμενος ποῦ τῆς νυκτὸς ἐξέλθοι. τοῦ δὲ ἀντιγράψαντος ὡς ἐκεῖνον Βέλβιναν μέλλειν τειχίζειν ἀκούσας καταβαίη τοῦτο κωλύσων, πάλιν ὁ Κλεομένης ἀποστείλας τοῦτο μὲν οὕτως ἔχειν ἔφη πεπεῖσθαι· τοὺς δὲ φανοὺς καὶ τὰς κλίμακας, εἶπεν, εἰ μή τί σοι διαφέρει, γράψον ἡμῖν, ἐπὶ τί σοι παρηκολούθουν. τοῦ δὲ Ἀράτου πρὸς τὸ σκῶμμα γελάσαντος καὶ πυνθανομένου ποῖός τις ὁ νεανίσκος εἴη, Δαμοκράτης ὁ Λακεδαιμόνιος φυγάς, εἴ τι πράττεις, ἔφη, πρὸς Λακεδαιμονίους, ὥρα σοι ταχύνειν πρὸ τοῦ κέντρα φῦσαι τοῦτον τὸν νεοσσόν.", "st": "Cleom. 4.1"}, {"sp": "N", "t": "ἐκ τούτου Κλεομένει μετὰ ἱππέων ὀλίγων καὶ πεζῶν τριακοσίων ἐν Ἀρκαδίᾳ στρατοπεδευομένῳ προσέταξαν ἀναχωρεῖν οἱ ἔφοροι, φοβούμενοι τὸν πόλεμον. ἐπεὶ δὲ ἀναχωρήσαντος αὐτοῦ Καφύας ἔλαβεν ὁ Ἄρατος, αὖθις ἐξέπεμπον τὸν Κλεομένη, λαβόντος δὲ αὐτοῦ Μεθύδριον καὶ τὴν Ἀργολικὴν καταδραμόντος, ἐξεστράτευσαν οἱ Ἀχαιοὶ δισμυρίοις πεζοῖς καὶ χιλίοις ἱππεῦσιν Ἀριστομάχου στρατηγοῦντος. ἀπαντήσαντος δὲ περὶ Παλλάντιον Κλεομένους καὶ βουλομένου μάχεσθαι. φοβηθεὶς τὴν τόλμαν ὁ Ἄρατος οὐκ εἴασε διακινδυνεῦσαι τὸν στρατηγόν, ἀλλ’ ἀπῆλθε λοιδορούμενος μὲν ὑπὸ τῶν Ἀχαιῶν, χλευαζόμενος δὲ καὶ καταφρονούμενος ὑπὸ τῶν Λακεδαιμονίων, οὐδὲ πεντακισχιλίων τὸ πλῆθος ὄντων, μέγας οὖν τῷ φρονήματι γεγονὼς ὁ Κλεομένης ἐθρασύνετο πρὸς τοὺς πολίτας, καὶ τῶν παλαιῶν τινος αὐτοὺς ἀνεμίμνῃσκε βασιλέων εἰπόντος οὐ μάτην ὅτι Λακεδαιμόνιοι πυνθάνονται περὶ τῶν πολεμίων, οὐ πόσοι εἰσίν, ἀλλὰ ποῦ εἰσιν.", "st": "Cleom. 4.4"}, {"sp": "N", "t": "ἐπεὶ δὲ τοῖς Ἠλείοις πολεμουμένοις ὑπὸ τῶν Ἀχαιῶν βοηθήσας, καὶ περὶ τὸ Λύκαιον ἀπιοῦσιν ἤδη τοῖς Ἀχαιοῖς ἐπιβαλών, ἅπαν μὲν ἐτρέψατο καὶ διεπτόησεν αὐτῶν τὸ στράτευμα, συχνοὺς δὲ ἀνεῖλε καὶ ζῶντας ἔλαβεν, ὥστε καὶ περὶ Ἀράτου φήμην ἐκπεσεῖν εἰς τοὺς Ἕλληνας ὡς τεθνηκότος, ὁ μὲν Ἄρατος ἄριστα τῷ καιρῷ χρησάμενος ἐκ τῆς τροπῆς ἐκείνης εὐθὺς ἐπὶ Μαντίνειαν ἦλθε καὶ μηδενὸς ἂν προσδοκήσαντος εἷλε τὴν πόλιν καὶ κατέσχε, τῶν δὲ Λακεδαιμονίων παντάπασι ταῖς γνώμαις ἀναπεσόντων καὶ τῷ Κλεομένει πρὸς τὰς στρατείας ἐνισταμένων, ὥρμησε μεταπέμπεσθαι τὸν Ἄγιδος ἀδελφὸν Ἀρχίδαμον ἐκ Μεσσήνης, ᾧ βασιλεύειν ἀπὸ τῆς ἑτέρας οἰκίας ἦν προσῆκον, οἰόμενος ἀμβλυτέραν τὴν τῶν ἐφόρων ἀρχὴν ἔσεσθαι τῆς βασιλείας ἰσορρόπου καὶ ὁλοκλήρου γενομένης. οἱ δὲ ἀνῃρηκότες πρότερον τὸν Ἆγιν αἰσθόμενοι τοῦτο, καὶ φοβηθέντες μὴ δίκην δῶσι τοῦ Ἀρχιδάμου κατελθόντος, ἐδέξαντο μὲν αὐτὸν εἰς τὴν πόλιν παραγενόμενον κρύφα καὶ συγκατῆγον, εὐθὺς δὲ ἀπέκτειναν, εἴτε ἄκοντος τοῦ Κλεομένους, ὡς οἴεται Φύλαρχος, εἴτε πεισθέντος ὑπὸ τῶν φίλων καὶ προεμένου τὸν ἄνθρωπον αὐτοῖς. τῆς γὰρ αἰτίας τὸ πλεῖστον ἐπ’ ἐκείνους ἦλθε βεβιάσθαι τὸν Κλεομένη δοκοῦντας.", "st": "Cleom. 5.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ κινεῖν εὐθὺς ἐγνωκὼς τὰ κατὰ τὴν πόλιν, ἔπεισε τοὺς ἐφόρους χρήμασιν ὅπως αὐτῷ ψηφίσωνται στρατείαν. ἐθεράπευσε δὲ καὶ τῶν ἄλλων συχνοὺς διὰ τῆς μητρὸς Κρατησικλείας ἀφειδῶς συγχορηγούσης καὶ συμφιλοτιμουμένης, ἥ γε καὶ γάμου μὴ δεομένη λέγεται διὰ τὸν υἱὸν ἄνδρα λαβεῖν πρωτεύοντα δόξῃ καὶ δυνάμει τῶν πολιτῶν. ἐξαγαγὼν δὲ τὴν στρατείαν καταλαμβάνει τῆς Μεγαλοπολίτιδος χωρίον Λεῦκτρα· καὶ γενομένης πρὸς αὑτὸν ὀξείας τῶν Ἀχαιῶν βοηθείας Ἀράτου στρατηγοῦντος, ὑπὸ τὴν πόλιν αὐτὴν παραταξάμενος ἡττήθη μέρει τινὶ τοῦ στρατεύματος, ἐπεὶ δὲ χαράδραν τινὰ βαθεῖαν οὐκ εἴασε διαβῆναι τοὺς Ἀχαιοὺς ὁ Ἄρατος, ἀλλ’ ἐπέστησε τὴν δίωξιν, ἀγανακτῶν δὲ Λυδιάδας ὁ Μεγαλοπολίτης συνεξώρμησε τοὺς περὶ αὑτὸν ἱππεῖς καὶ διώκων εἰς χωρίον ἀμπέλων καὶ τάφρων καὶ τειχῶν μεστὸν ἐνσείσας καὶ διασπασθεὶς περὶ ταῦτα κακῶς ἀπήλλαττε, κατιδὼν ὁ Κλεομένης ἀνῆκε τοὺς Ταραντίνους καὶ τοὺς Κρῆτας ἐπ’ αὐτόν, ὑφ’ ὧν ὁ Λυδιάδας ἀμυνόμενος εὐρώστως ἔπεσε, πρὸς τοῦτο θαρρήσαντες οἱ Λακεδαιμόνιοι μετὰ βοῆς ἐνέβαλον τοῖς Ἀχαιοῖς, καὶ τροπὴν ὅλου τοῦ στρατεύματος ἐποίησαν. ἀποθανόντων δὲ συχνῶν τοὺς μὲν ἄλλους ὑποσπόνδους ὁ Κλεομένης ἀπέδωκε, τὸν δὲ Λυδιάδαν νεκρὸν ἀχθῆναι πρὸς αὑτὸν κελεύσας, κοσμήσας πορφυρίδι καὶ στέφανον ἐπιθεὶς, πρὸς τὰς πύλας τῶν Μεγαλοπολιτῶν ἀπέστειλεν. οὗτος ἦν Λυδιάδας ὁ καταθέμενος τὴν τυραννίδα καὶ τοῖς πολίταις ἀποδοὺς τὴν ἐλευθερίαν καὶ τὴν πόλιν προσκομίσας Ἀχαιοῖς.", "st": "Cleom. 6.1"}, {"sp": "N", "t": "ἐκ τούτου Κλεομένης μέγα φρονῶν ἤδη, καὶ πεπεισμένος ἂν ὡς βούλεται τοῖς πράγμασι χρώμενος πολεμῇ πρὸς τοὺς Ἀχαιούς, ῥᾳδίως ἐπικρατήσειν, ἐδίδασκε τὸν τῆς μητρὸς ἄνδρα Μεγιστόνουν ὡς χρὴ τῶν ἐφόρων ἀπαλλαγέντας εἰς μέσον θεῖναι τὰ κτήματα τοῖς πολίταις καὶ τὴν Σπάρτην ἴσην γενομένην ἐγείρειν καὶ προάγειν ἐπὶ τὴν τῆς Ἑλλάδος ἡγεμονίαν. πεισθέντος δ’ ἐκείνου δύο τῶν ἄλλων φίλων ἢ τρεῖς προσέλαβε.", "st": "Cleom. 7.1"}, {"sp": "N", "t": "συνέβη δὲ περὶ τὰς ἡμέρας ἐκείνας καὶ τῶν ἐφόρων ἕνα κοιμώμενον ἐν Πασιφάας ὄναρ ἰδεῖν θαυμαστόν· ἐδόκει γάρ ἐν ᾧ τόπῳ τοῖς ἐφόροις ἔθος ἐστὶ καθεζομένοις χρηματίζειν ἕνα δίφρον κεῖσθαι, τοὺς δὲ τέτταρας ἀνῃρῆσθαι, καὶ θαυμάζοντος αὐτοῦ φωνὴν ἐκ τοῦ ἱεροῦ γενέσθαι φράζουσαν ὡς τοῦτο τῇ Σπάρτῃ λῷόν ἐστι. ταύτην τὴν ὄψιν διηγουμένου τοῦ ἐφόρου πρὸς τὸν Κλεομένη, τὸ μὲν πρῶτον διεταράχθη καθ’ ὑποψίαν τινὰ πειράζεσθαι δοκῶν, ὡς δὲ ἐπείσθη μὴ ψεύδεσθαι τὸν διηγούμενον, ἐθάρρησε. καὶ λαβὼν ὅσους ὑπώπτευε μάλιστα τῶν πολιτῶν ἐναντιώσεσθαι πρὸς τὴν πρᾶξιν, Ἡραίαν καὶ Ἀλσαίαν τὰς πόλεις ταττομένας ὑπὸ τοῖς Ἀχαιοῖς εἷλε, καὶ σῖτον εἰσήγαγεν Ὀρχομενίοις, καὶ Μαντινείᾳ παρεστρατοπέδευσε, καὶ ὅλως ἄνω καὶ κάτω μακραῖς πορείαις ἀποτρύσας τοὺς Λακεδαιμονίους ἀπέλιπεν αὐτῶν δεηθέντων τοὺς πολλοὺς ἐν Ἀρκαδίᾳ, τοὺς δὲ μισθοφόρους ἔχων αὐτὸς ἐπὶ τὴν Σπάρτην ἐχώρει. καὶ καθ’ ὁδὸν οἷς ἐπίστευε μάλιστα καλῶς πρὸς αὐτὸν ἔχειν ἀνεκοινοῦτο τὴν γνώμην, καὶ προῄει σχέδην, ὡς περὶ τὸ δεῖπνον οὖσι τοῖς ἐφόροις ἐπιπέσοι.", "st": "Cleom. 7.2"}, {"sp": "N", "t": "γενόμενος δὲ τῆς πόλεως ἐγγύς, Εὐρυκλείδαν μὲν εἰς τὸ τῶν ἐφόρων συσσίτιον ἀπέστειλεν ὥς τινα παρ’ αὐτοῦ λόγον ἀπὸ στρατιᾶς κομίζοντα, Θηρυκίων δὲ καὶ Φοῖβις καὶ δύο τῶν συντρόφων τοῦ Κλεομένους, οὓς μόθακας καλοῦσιν, ἐπηκολούθουν στρατιώτας ὀλίγους ἔχοντες. ἔτι δὲ τοῦ Εὐρυκλείδα διαλεγομένου τοῖς ἐφόροις ἐπιδραμόντες ἐσπασμέναις ταῖς μαχαίραις ἔπαιον αὐτούς. ὁ μὲν οὖν πρῶτος Ἀγύλαιος, ὡς ἐπλήγη, πεσὼν καὶ τεθνάναι δόξας ἀτρέμα συναγαγὼν καὶ παρέλκων ἑαυτὸν ἐκ τοῦ οἰκήματος ἔλαθεν εἴς τι δωμάτιον εἰσερπύσας μικρόν, ὃ Φόβου μὲν ἦν ἱερόν, ἄλλως δὲ κεκλεισμένον ἀεὶ, τότε ἐκ τύχης ἀνεῳγμένον ἐτύγχανεν. εἰς τοῦτο συνεισενεγκὼν ἑαυτὸν ἀπέκλεισε τὸ θύριον. οἱ δὲ τέσσαρες ἀνῃρέθησαν, καὶ τῶν ἐπιβοηθούντων αὐτοῖς οὐ πλείονες ἢ δέκα. τοὺς γὰρ ἡσυχίαν ἄγοντας οὐκ ἔκτειναν, οὐδὲ τοὺς ἀπιόντας ἐκ τῆς πόλεως ἐκώλυον. ἐφείσαντο δὲ καὶ τοῦ Ἀγυλαίου μεθ’ ἡμέραν ἐκ τοῦ ἱεροῦ προελθόντος.", "st": "Cleom. 8.1"}, {"sp": "N", "t": "ἔστι δὲ Λακεδαιμονίοις οὐ Φόβου μόνον, ἀλλὰ καί Θανάτου καί Γέλωτος καί τοιούτων ἄλλων παθημάτων ἱερά. τιμῶσι δὲ τὸν Φόβον οὐχ ὥσπερ οὓς ἀποτρέπονται δαίμονας, ἡγούμενοι βλαβερόν, ἀλλὰ τὴν πολιτείαν μάλιστα συνέχεσθαι φόβῳ νομίζοντες. διὸ καί προεκήρυττον οἱ ἔφοροι τοῖς πολίταις εἰς τὴν ἀρχὴν εἰσιόντες, ὡς Ἀριστοτέλης φησί, κείρεσθαι τὸν μύστακα καὶ προσέχειν τοῖς νόμοις, ἵνα μὴ χαλεποὶ ὦσιν αὐτοῖς· τὸ τοῦ μύστακος, οἶμαι, προτείνοντες, ὅπως καί περὶ τὰ μικρότατα τοὺς νέους πειθαρχεῖν ἐθίζωσι. καί τὴν ἀνδρείαν δέ μοι δοκοῦσιν οὐκ ἀφοβίαν, ἀλλὰ Φόβον ψόγου καί δέος ἀδοξίας οἱ παλαιοὶ νομίζειν. οἱ γὰρ δειλότατοι πρὸς τοὺς νόμους θαρραλεώτατοι πρὸς τοὺς πολεμίους εἰσί καὶ τὸ παθεῖν ἥκιστα δεδίασιν οἱ μάλιστα φοβούμενοι τὸ κακῶς ἀκοῦσαι. διὸ καί καλῶς ὁ εἰπών·", "st": "Cleom. 9.1"}, {"sp": "N", "t": "ἵνα γὰρ δέος, ἔνθα καί αἰδώς.", "st": "Cleom. 9.1b"}, {"sp": "N", "t": "καί Ὅμηρος,<br>αἰδοῖός τέ μοί ἐσσι, φίλε ἑκυρὲ, δεινός τε·<br>καί<br>σιγῇ δειδιότες σημάντορας.", "st": "Cleom. 9.1c"}, {"sp": "N", "t": "τὸ γὰρ αἰσχύνεσθαι μάλιστα συμβαίνει πρὸς οὓς καί τὸ δεδοικέναι τοῖς πολλοῖς, διὸ καί παρὰ τὸ τῶν ἐφόρων συσσίτιον τὸν Φόβον ἵδρυνται Λακεδαιμόνιοι, μοναρχίας ἐγγυτάτω κατασκευασάμενοι τὸ ἀρχεῖον.", "st": "Cleom. 9.1d"}, {"sp": "N", "t": "ὁ δ’ οὖν Κλεομένης ἡμέρας γενομένης προέγραψεν ὀγδοήκοντα τῶν πολιτῶν οὓς ἔδει μεταστῆναι, καὶ τοὺς δίφρους ἀνεῖλε τῶν ἐφόρων πλὴν ἑνός, ἐν ᾧ καθήμενος ἔμελλεν αὐτὸς χρηματίζειν. ἐκκλησίαν δέ ποιήσας ἀπελογεῖτο περὶ τῶν πεπραγμένων, ἔφη γὰρ ὑπὸ τοῦ Λυκούργου τοῖς βασιλεῦσι συμμιχθῆναι τοὺς γέροντας, καὶ πολὺν χρόνον οὕτω διοικεῖσθαι τήν πόλιν οὐδὲν ἑτέρας ἀρχῆς δεομένην, ὕστερον δὲ τοῦ πρὸς Μεσσηνίους πολέμου μακροῦ γενομένου τοὺς βασιλεῖς, διὰ τὰς στρατείας ἀσχόλους ὄντας αὐτούς πρὸς τὸ κρίνειν, αἱρεῖσθαί τινας ἐκ τῶν φίλων καὶ ἀπολείπειν τοῖς πολίταις ἀνθ’ ἑαυτῶν, ἐφόρους προσαγορευθέντας, καὶ διατελεῖν γε τούτους τὸ πρῶτον ὑπηρέτας τῶν βασιλέων ὄντας, εἶτα κατὰ μικρὸν εἰς ἑαυτοὺς τήν ἐξουσίαν ἐπιστρέφοντας οὕτως λαθεῖν ἴδιον ἀρχεῖον κατασκευασαμένους. σημεῖον δὲ τούτου τὸ μέχρι νῦν μεταπεμπομένων τὸν βασιλέα τῶν ἐφόρων τὸ πρῶτον ἀντιλέγειν καὶ τὸ δεύτερον, τὸ δὲ τρίτον καλούντων ἀναστάντα βαδίζειν πρὸς αὐτούς καὶ τὸν πρῶτον ἐπισφοδρύναντα τήν ἀρχὴν καὶ ἀνατεινάμενον Ἀστερωπὸν ἡλικίαις ὕστερον πολλαῖς ἔφορον γενέσθαι.", "st": "Cleom. 10.1"}, {"sp": "N", "t": "μετριάζοντας μὲν οὖν αὐτούς, ἔφη, κρεῖττον ἦν ὑπομένειν, ἐξουσίᾳ δὲ ἐπιθέτῳ τήν πάτριον καταλύοντας ἀρχήν, ὥστε τῶν βασιλέων τοὺς μὲν ἐξελαύνειν, τοὺς δὲ ἀποκτιννύειν ἀκρίτους, ἀπειλεῖν δὲ τοῖς ποθοῦσιν αὖθις ἐπιδεῖν τήν καλλίστην καὶ θειοτάτην ἐν Σπάρτῃ κατάστασιν, οὐκ ἀνεκτόν. εἰ μὲν οὖν δυνατὸν ἦν ἄνευ σφαγῆς ἀπαλλάξαι τὰς ἐπεισάκτους τῆς Λακεδαίμονος κῆρας, τρυφὰς καὶ πολυτελείας καὶ χρέα καὶ δανεισμοὺς καὶ τὰ πρεσβύτερα τούτων κακά, πενίαν καὶ πλοῦτον, εὐτυχέστατον ἂν ἡγεῖσθαι πάντων βασιλέων ἑαυτόν ὥσπερ ἰατρὸν ἀνωδύνως ἰασάμενον τήν πατρίδα· νῦν δὲ τῆς ἀνάγκης ἔχειν συγγνώμονα τὸν Λυκοῦργον, ὃς οὔτε βασιλεὺς ὢν οὔτε ἄρχων, ἰδιώτης δὲ βασιλεύειν ἐπιχειρῶν ἐν τοῖς ὅπλοις προῆλθεν εἰς ἀγοράν, ὥστε δείσαντα τὸν βασιλέα Χάριλλον ἐπὶ βωμὸν καταφυγεῖν. ἀλλ’ ἐκεῖνον μὲν ὄντα χρηστὸν καὶ φιλόπατριν ταχὺ τῷ Λυκούργῳ τῶν πραττομένων μετασχεῖν καὶ τήν μεταβολὴν δέξασθαι τῆς πολιτείας, ἔργῳ δὲ μαρτυρῆσαι τὸν Λυκοῦργον ὅτι πολιτείαν μεταβαλεῖν ἄνευ βίας καὶ φόβου χαλεπόν ἐστιν, οἷς αὑτὸν ἔφη μετριώτατα κεχρῆσθαι, τοὺς ἐνισταμένους τῇ σωτηρίᾳ τῆς Λακεδαίμονος ἐκποδὼν ποιησάμενον.", "st": "Cleom. 10.4"}, {"sp": "N", "t": "τοῖς δὲ ἄλλοις ἔφη πᾶσι τήν τε γῆν ἅπασαν εἰς μέσον τιθέναι, καὶ χρεῶν τοὺς ὀφείλοντας ἀπαλλάττειν, καὶ τῶν ξένων κρίσιν ποιεῖν καὶ δοκιμασίαν, ὅπως οἱ κράτιστοι γενόμενοι Σπαρτιᾶται σῴζωσι τήν πόλιν τοῖς ὅπλοις, καὶ παυσώμεθα τήν Λακωνικὴν Αἰτωλῶν καὶ Ἰλλυριῶν λείαν οὖσαν ἐρημίᾳ τῶν ἀμυνόντων ἐφορῶντες.", "st": "Cleom. 10.6"}, {"sp": "N", "t": "ἐκ τούτου πρῶτον μὲν αὐτὸς εἰς μέσον τὴν οὐσίαν ἔθηκε καὶ Μεγιστόνους ὁ πατρῳὸς αὐτοῦ καὶ τῶν ἄλλων φίλων ἕκαστος, ἔπειτα καὶ οἱ λοιποὶ πολῖται πάντες, ἡ δὲ χώρα διενεμήθη. κλῆρον δὲ καὶ τῶν ὑπ’ αὐτοῦ γεγονότων φυγάδων ἀπένειμεν ἑκάστῳ, καὶ κατάξειν ἅπαντας ὡμολόγησε τῶν πραγμάτων ἐν ἡσυχίᾳ γενομένων. ἀναπληρώσας δὲ τὸ πολίτευμα τοῖς χαριεστάτοις τῶν περιοίκων ὁπλίτας τετρακισχιλίους ἐποίησε, καὶ διδάξας αὐτοὺς ἀντὶ δόρατος χρῆσθαι σαρίσῃ δι’ ἀμφοτέρων καὶ τὴν ἀσπίδα φορεῖν δι’ ὀχάνης, μὴ διὰ πόρπακος, ἐπὶ τὴν παιδείαν τῶν νέων ἐτράπη καὶ τὴν λεγομένην ἀγωγήν, ἧς τὰ πλεῖστα παρὼν ὁ Σφαῖρος αὐτῷ συγκαθίστη, ταχὺ τὸν προσήκοντα τῶν τε γυμνασίων καὶ τῶν συσσιτίων κόσμον ἀναλαμβανόντων, καὶ συστελλομένων ὀλίγων μὲν ὑπ’ ἀνάγκης, ἑκουσίως δὲ τῶν πλείστων εἰς τὴν εὐτελῆ καὶ Λακωνικὴν ἐκείνην δίαιταν. ὅμως δὲ τὸ τῆς μοναρχίας ὄνομα παραμυθούμενος ἀπέδειξε μεθ’ ἑαυτοῦ βασιλέα τὸν ἀδελφὸν Εὐκλείδαν. καὶ τότε μόνον Σπαρτιάταις ἐκ μιᾶς οἰκίας συνέβη δύο σχεῖν βασιλέας.", "st": "Cleom. 11.1"}, {"sp": "N", "t": "αἰσθόμενος δὲ τοὺς Ἀχαιοὺς καὶ τὸν Ἄρατον, ὡς ἐπισφαλῶς αὐτῷ τῶν πραγμάτων ἐχόντων διὰ τὸν νεωτερισμόν, οὐκ ἂν οἰομένους προελθεῖν ἔξω τῆς Λακεδαίμονος οὐδὲ ἀπολιπεῖν μετέωρον ἐν κινήματι τηλικούτῳ τὴν πόλιν, οὐκ ἀγεννὲς οὐδὲ ἄχρηστον ἡγήσατο τὴν προθυμίαν τοῦ στρατεύματος ἐπιδεῖξαι τοῖς πολεμίοις. ἐμβαλὼν οὖν εἰς τὴν Μεγαλοπολιτικήν ὠφελείας τε μεγάλας ἤθροισε καὶ φθορὰν πολλὴν ἀπειργάσατο τῆς χώρας, τέλος δὲ τοὺς περὶ τὸν Διόνυσον τεχνίτας ἐκ Μεσσήνης διαπορευομένους λαβών, καὶ πηξάμενος θέατρον ἐν τῇ πολεμίᾳ, καὶ προθεὶς ἀπὸ τετταράκοντα μνῶν ἀγῶνα, μίαν ἡμέραν ἐθεᾶτο καθήμενος, οὐ δεόμενος θέας, ἀλλ’ οἷον ἐντρυφῶν τοῖς πολεμίοις καὶ περιουσίαν τινὰ τοῦ κρατεῖν πολὺ τῷ καταφρονεῖν ἐπιδεικνύμενος. ἐπεὶ ἄλλως γε τῶν Ἑλληνικῶν καὶ βασιλικῶν στρατευμάτων ἐκεῖνο μόνον οὐ μίμους παρακολουθοῦντας εἶχεν, οὐ θαυματοποιούς, οὐκ ὀρχηστρίδας, οὐ ψαλτρίας, ἀλλὰ πάσης ἀκολασίας καὶ βωμολοχίας καὶ πανηγυρισμοῦ καθαρὸν ἦν, τὰ μὲν πολλὰ μελετώντων τῶν νέων καὶ τῶν πρεσβυτέρων διδασκόντων, τὰς δὲ παιδιὰς, ὁπότε σχολάζοιεν, ταῖς συνήθεσιν εὐτραπελίαις καὶ τῷ λέγειν τι χαρίεν καὶ Λακωνικὸν πρὸς ἀλλήλους διατιθεμένων, ἣν δὲ ἔχει τὸ τοιοῦτον τῆς παιδιᾶς εἶδος ὠφέλειαν, ἐν τῷ Λυκούργου βίῳ γέγραπται.", "st": "Cleom. 12.1"}, {"sp": "N", "t": "πάντων δ’ αὐτὸς ἐγίγνετο διδάσκαλος, εὐτελῆ καὶ ἀφελῆ καὶ φορτικὸν οὐδὲν οὐδὲ ὑπὲρ τοὺς πολλοὺς ἔχοντα τὸν ἑαυτοῦ βίον ὥσπερ παράδειγμα σωφροσύνης ἐν μέσῳ θέμενος· ὃ καὶ πρὸς τὰς Ἑλληνικὰς πράξεις ῥοπήν τινα παρέσχεν αὐτῷ. τοῖς μὲν γὰρ ἄλλοις ἐντυγχάνοντες οἱ ἄνθρωποι βασιλεῦσιν οὐχ οὕτω κατεπλήττοντο τοὺς πλούτους καὶ τὰς πολυτελείας, ὡς ἐβδελύττοντο τήν ὑπεροψίαν αὐτῶν καὶ τὸν ὄγκον ἐπαχθῶς καὶ τραχέως προσφερομένων τοῖς ἐντυγχάνουσι· πρὸς δὲ Κλεομένη βαδίζοντες, ὄντα τε δὴ βασιλέα καὶ καλούμενον, εἶτα ὁρῶντες οὐ πορφύρας τινὰς οὐ χλαίνας περὶ αὐτὸν οὐδὲ κλινιδίων καὶ φορείων κατασκευάς, οὐδ’ ὑπ’ ἀγγέλων ὄχλου καὶ θυρωρῶν ἢ διὰ γραμματείων χρηματίζοντα χαλεπῶς καὶ μόλις, ἀλλ’ αὐτὸν ἐν ἱματίῳ τῷ τυχόντι πρὸς τὰς δεξιώσεις ἀπαντῶντα καὶ διαλεγόμενον καὶ σχολάζοντα τοῖς χρῄζουσιν ἱλαρῶς καὶ φιλανθρώπως, ἐκηλοῦντο καὶ κατεδημαγωγοῦντο, καὶ μόνον ἀφ’ Ἡρακλέους ἐκεῖνον ἔφασαν γεγονέναι.", "st": "Cleom. 13.1"}, {"sp": "N", "t": "τῶν δὲ δείπνων αὐτοῦ τὸ μὲν καθημερινὸν ἦν ἐν τρικλίνῳ σφόδρα συνεσταλμένον καὶ Λακωνικόν, εἰ δὲ πρέσβεις ἢ ξένους δέχοιτο, δύο μὲν ἄλλαι προσπαρεβάλλοντο κλῖναι, μικρῷ δὲ μᾶλλον οἱ ὑπηρέται τὴν τράπεζαν ἐπελάμπρυνον, οὐ καρυκείαις τισὶν οὐδὲ πέμμασιν, ἀλλ’ ὥστε ἀφθονωτέρας εἶναι τὰς παραθέσεις καὶ φιλανθρωπότερον τὸν οἶνον. καὶ γὰρ ἐπετίμησέ τινα τῶν φίλων ἀκούσας ὅτι ξένους ἑστιῶν ζωμὸν αὐτοῖς μέλανα καὶ μάζαν, ὥσπερ ἔθος ἦν ἐν τοῖς φιδιτίοις, παρέθηκεν· οὐ γὰρ ἔφη δεῖν ἐν τούτοις οὐδὲ πρὸς τοὺς ξένους λίαν ἀκριβῶς λακωνίζειν. ἀπαρθείσης δὲ τῆς τραπέζης εἰσεκομίζετο τρίπους κρατῆρα χαλκοῦν ἔχων οἴνου μεστὸν καὶ φιάλας ἀργυρᾶς δικοτύλους δύο καὶ ποτήρια τῶν ἀργυρῶν ὀλίγα παντάπασιν, ἐξ ὧν ἔπινεν ὁ βουλόμενος, ἄκοντι δὲ οὐδεὶς ποτήριον προσέφερεν. ἀκρόαμα δὲ οὔτ’ ἦν οὔτ’ ἐπεζητεῖτο· ἐπαιδαγώγει γὰρ αὐτὸς ὁμιλίᾳ τὸν πότον, τὰ μὲν ἐρωτῶν, τὰ δὲ διηγούμενος, οὔτε τήν σπουδὴν ἀηδῆ τῶν λόγων τήν τε παιδιὰν ἐπίχαριν καὶ ἀσόλοικον ἐχόντων. ἃς μὲν γὰρ οἱ λοιποὶ τῶν βασιλέων ἐπὶ τοὺς ἀνθρώπους θήρας ἐποιοῦντο, χρήμασι καὶ δωρεαῖς δελεάζοντες αὐτοὺς καὶ διαφθείροντες, ἀτέχνους καὶ ἀδίκους ἐνόμιζεν εἶναι· τὸ δὲ ὁμιλίᾳ καὶ λόγῳ χάριν ἔχοντι καὶ πίστιν οἰκειοῦσθαι καὶ προσάγεσθαι τοὺς ἐντυγχάνοντας ἐφαίνετο κάλλιστον αὐτῷ καὶ βασιλικώτατον, ὡς οὐδενὶ φίλου διαφέροντα μισθωτὸν ἢ τῷ τὸν μὲν ἤθει καὶ λόγῳ, τὸν δὲ ὑπὸ χρημάτων ἁλίσκεσθαι.", "st": "Cleom. 13.3"}, {"sp": "N", "t": "πρῶτον μὲν οὖν οἱ Μαντινεῖς αὐτὸν ἐπηγάγοντο, καὶ νύκτωρ εἰς τὴν πόλιν παρεισπεσόντι τὴν φρουρὰν τὴν Ἀχαιῶν συνεκβαλόντες ἐνεχείρισαν αὑτούς, ὁ δὲ καὶ τοὺς νόμους αὐτοῖς καὶ τὴν πολιτείαν ἀποδούς αὐθημερὸν ἀπῆλθεν εἰς Τεγέαν. ὀλίγῳ δ’ ὕστερον ἐκπεριελθὼν δι’ Ἀρκαδίας κατέβαινεν ἐπὶ τὰς Ἀχαϊκὰς Φεράς, βουλόμενος ἢ μάχην θέσθαι πρὸς τοὺς Ἀχαιοὺς ἢ διαβάλλειν τὸν Ἄρατον ὡς ἀποδιδράσκοντα καὶ προϊέμενον αὐτῷ τὴν χώραν. ἐστρατήγει μὲν γὰρ Ὑπερβατᾶς τότε, τοῦ δὲ Ἀράτου τὸ πᾶν ἦν κράτος ἐν τοῖς Ἀχαιοῖς. ἐξελθόντων δὲ πανδημεὶ τῶν Ἀχαιῶν καὶ στρατοπεδευσαμένων ἐν Δύμαις περὶ τὸ Ἑκατόμβαιον, ἐπελθὼν ὁ Κλεομένης ἔδοξε μὲν οὐ καλῶς ἐν μέσῳ τῆς τε Δυμαίων πόλεως, πολεμίας οὔσης, καὶ τοῦ στρατεύματος τῶν Ἀχαιῶν αὐλίσασθαι, τολμηρῶς δὲ προκαλούμενος τοὺς Ἀχαιοὺς ἠνάγκασε συμβαλεῖν, καὶ νικήσας κατὰ κράτος καὶ τρεψάμενος τὴν φάλαγγα πολλοὺς μὲν ἐν τῇ μάχῃ διέφθειρεν αὐτῶν, πολλῶν δὲ καὶ ζώντων ἐκυρίευσεν. ἐπελθὼν δὲ Λάγγωνι καὶ τῶν Ἀχαιῶν τοὺς φρουροῦντας ἐξελάσας ἀπέδωκεν Ἠλείοις τὴν πόλιν.", "st": "Cleom. 14.1"}, {"sp": "N", "t": "οὕτω δὲ συντετριμμένοις τοῖς Ἀχαιοῖς ὁ μὲν Ἄρατος, εἰωθὼς παρ’ ἐνιαυτὸν ἀεὶ στρατηγεῖν, ἀπείπατο τὴν ἀρχὴν καὶ παρῃτήσατο καλούντων καὶ δεομένων οὐ καλῶς, οἷον ἐν χειμῶνι πραγμάτων μείζονι, μεθεὶς ἑτέρῳ τὸν οἴακα καὶ προέμενος τὴν ἐξουσίαν. ὁ δὲ Κλεομένης πρῶτον μὲν μέτρια τοῖς Ἀχαιοῖς ἐδόκει πρέσβεσιν ἐπιτάττειν, ἑτέρους δὲ πέμπων ἐκέλευεν αὐτῷ παραδιδόναι τὴν ἡγεμονίαν, ὡς τἆλλα μὴ διοισόμενος πρὸς αὐτούς, ἀλλὰ καὶ τοὺς αἰχμαλώτους εὐθὺς ἀποδώσων καὶ τὰ χωρία. βουλομένων δὲ τῶν Ἀχαιῶν ἐπὶ τούτοις δέχεσθαι τὰς διαλύσεις καὶ τὸν Κλεομένη καλούντων εἰς Λέρναν, ὅπου τὴν ἐκκλησίαν ἔμελλον ἔχειν, ἔτυχε τὸν Κλεομένη συντόνως ὁδεύσαντα καὶ χρησάμενον παρὰ καιρὸν ὑδροποσίᾳ αἵματος πλῆθος ἀνενεγκεῖν καὶ τὴν φωνὴν ἀποκοπῆναι. διὸ τῶν μὲν αἰχμαλώτων ἀπέπεμψε τοῖς Ἀχαιοῖς τοὺς ἐπιφανεστάτους, τὸν δὲ σύλλογον ὑπερθέμενος ἀνεχώρησεν εἰς Λακεδαίμονα.", "st": "Cleom. 15.1"}, {"sp": "N", "t": "τοῦτο διελυμήνατο τὰ πράγματα τῆς Ἑλλάδος, ἁμῶς γέ πως ἐκ τῶν παρόντων ἀναλαβεῖν αὑτὴν ἔτι καὶ διαφυγεῖν τὴν Μακεδόνων ὕβριν καὶ πλεονεξίαν δυναμένης, ὁ γὰρ Ἄρατος, εἴτε ἀπιστίᾳ καὶ φόβῳ τοῦ Κλεομένους, εἴτε φθονῶν εὐτυχοῦντι παρ’ ἐλπίδα καὶ νομίζων ἔτη τρία καὶ τριάκοντα πρωτεύοντος αὐτοῦ δεινὸν εἶναι τὴν δόξαν ἅμα καὶ τὴν δύναμιν ἐπιφύντα νέον ἄνδρα καθελεῖν, καὶ παραλαβεῖν πραγμάτων ηὐξημένων ὑπ’ αὐτοῦ καὶ κεκρατημένων χρόνον τοσοῦτον ἀρχήν, πρῶτον μὲν ἐπειρᾶτο τοὺς Ἀχαιοὺς παραβιάζεσθαι καὶ διακωλύειν ὡς δὲ οὐ προσεῖχον αὐτῷ τοῦ Κλεομένους ἐκπεπληγμένοι τὸ θράσος, ἀλλὰ καὶ δικαίαν ἐποιοῦντο τὴν ἀξίωσιν τῶν Λακεδαιμονίων, εἰς τὸ πάτριον σχῆμα κοσμούντων τὴν Πελοπόννησον, τρέπεται πρὸς ἔργον οὐδενὶ μὲν τῶν Ἑλλήνων προσῆκον, αἴσχιστον δ’ ἐκείνῳ καὶ τῶν πεπραγμένων ὑπ’ αὐτοῦ καὶ πεπολιτευμένων ἀναξιώτατον, Ἀντίγονον ἐπὶ τὴν Ἑλλάδα καλεῖν καὶ Μακεδόνων ἐμπιπλάναι τὴν Πελοποννήσου, οὓς αὐτὸς ἐκ Πελοποννήσου μειράκιον ὢν ἐξήλασεν ἐλευθερώσας τὸν Ἀκροκόρινθον, καὶ πᾶσι μὲν τοῖς βασιλεῦσιν ὕποπτος καὶ διάφορος γενόμενος, τουτονὶ δὲ αὐτὸν Ἀντίγονον εἰρηκὼς κακὰ μυρία δι’ ὧν ἀπολέλοιπεν ὑπομνημάτων. καίτοι πολλὰ παθεῖν καὶ παραβαλέσθαι φησὶν αὐτὸς ὑπὲρ Ἀθηναίων, ὅπως ἡ πόλις ἀπαλλαγείη φρουρᾶς καὶ Μακεδόνων εἶτα τούτους ἐπὶ τὴν πατρίδα καὶ τὴν ἑστίαν τὴν ἑαυτοῦ μεθ’ ὅπλων εἰσήγαγεν ἄχρι τῆς γυναικωνίτιδος τὸν δὲ ἀφ’ Ἡρακλέους γεγονότα καὶ βασιλεύοντα Σπαρτιατῶν, καὶ τὴν πάτριον πολιτείαν, ὥσπερ ἁρμονίαν ἐκλελυμένην, ἀνακρουόμενον αὖθις ἐπὶ τὸν σώφρονα καὶ Δώριον ἐκεῖνον τοῦ Λυκούργου νόμον καὶ βίον, οὐκ ἠξίου Σικυωνίων ἡγεμόνα καὶ Τριταιέων γράφεσθαι, φεύγων δὲ τὴν μάζαν καὶ τὸν τρίβωνα, καὶ τὸ δεινότατον ὧν κατηγόρει Κλεομένους, ἀναίρεσιν πλούτου καὶ πενίας ἐπανόρθωσιν, διαδήματι καὶ πορφύρᾳ καὶ Μακεδονικοῖς καὶ σατραπικοῖς προστάγμασιν ὑπέρριψε μετὰ τῆς Ἀχαΐας αὑτόν, ἵνα μὴ Κλεομένει ποιεῖν δοκῇ τὸ προσταττόμενον, Ἀντιγόνεια θύων καὶ παιᾶνας ᾄδων αὐτὸς ἐστεφανωμένος εἰς ἄνθρωπον ὑπὸ φθόης κατασηπόμενον.", "st": "Cleom. 16.1"}, {"sp": "N", "t": "ἀλλὰ ταῦτα μὲν οὐκ Ἀράτου βουλόμενοι κατηγορεῖν γράφομεν ἐν πολλοῖς γὰρ ὁ ἀνὴρ οὗτος Ἑλληνικὸς γέγονε καὶ μέγας, οἰκτείροντες δὲ τῆς ἀνθρωπίνης φύσεως τὴν ἀσθένειαν, εἰ μηδὲ ἐν ἤθεσιν οὕτως ἀξιολόγοις καὶ διαφόροις πρὸς ἀρετὴν ἐκφέρειν δύναται τὸ καλὸν ἀνεμέσητον.", "st": "Cleom. 16.6"}, {"sp": "N", "t": "ἐλθόντων δὲ Ἀχαιῶν εἰς Ἄργος αὖθις ἐπὶ τὸν σύλλογον καὶ τοῦ Κλεομένους ἐκ Τεγέας καταβεβηκότος ἐλπὶς ἦν πολλὴ τῶν ἀνθρώπων ἔσεσθαι τὴν διάλυσιν. ὁ δὲ Ἄρατος, ἤδη διωμολογημένων αὐτῷ πρὸς τὸν Ἀντίγονον τῶν μεγίστων, φοβούμενος τὸν Κλεομένη μὴ πάντα διαπράξηται καθομιλήσας τὸ πλῆθος ἢ καὶ βιασάμενος, ἠξίου λαβόντα τριακοσίους ὁμήρους μόνον εἰσιέναι πρὸς αὐτούς, ἢ κατὰ γυμνάσιον ἔξωθεν τὸ Κυλλαράβιον προσελθόντα μετὰ τῆς δυνάμεως διαλέγεσθαι. ταῦτ’ ἀκούσας ὁ Κλεομένης ἄδικα πάσχειν ἔφασκε· δεῖν γὰρ εὐθὺς αὐτῷ τότε προειπεῖν, οὐ νῦν, ἥκοντος ἐπὶ τὰς θύρας τὰς ἐκείνων, ἀπιστεῖν καὶ ἀπελαύνειν. γράψας δὲ περὶ τούτων ἐπιστολὴν πρὸς τοὺς Ἀχαιούς, ἧς ἦν τὸ πλεῖστον Ἀράτου κατηγορία, πολλὰ δὲ καὶ τοῦ Ἀράτου λοιδορήσαντος αὐτὸν πρὸς τὸ πλῆθος, ἀνέζευξε διὰ ταχέων καὶ κήρυκα πόλεμον προεροῦντα τοῖς Ἀχαιοῖς ἔπεμψεν, οὐκ εἰς Ἄργος, ἀλλ’ εἰς Αἴγιον, ὥς φησιν Ἄργος, ὅπως φθάσῃ τὴν παρασκευὴν αὐτῶν.", "st": "Cleom. 17.1"}, {"sp": "N", "t": "ἐγεγόνει δὲ κίνημα τῶν Ἀχαιῶν, καὶ πρὸς ἀπόστασιν ὥρμησαν αἱ πόλεις, τῶν μὲν δήμων νομήν τε χώρας καὶ χρεῶν ἀποκοπὰς ἐλπισάντων, τῶν δὲ πρώτων πολλαχοῦ βαρυνομένων τὸν Ἄρατον, ἐνίων δὲ καὶ δι’ ὀργῆς ἐχόντων ὡς ἐπάγοντα τῇ Πελοποννήσῳ Μακεδόνας, διὸ τούτοις ἐπαρθεὶς ὁ Κλεομένης εἰς Ἀχαΐαν ἐνέβαλε· καὶ πρῶτον μὲν εἷλε Πελλήνην ἐξαπίνης ἐπιπεσὼν, καὶ τοὺς φρουροῦντας ἐξέβαλε τῶν Ἀχαιῶν μετὰ δὲ ταῦτα Φενεὸν προσηγάγετο καὶ Πεντέλειον. ἐπεὶ δὲ φοβηθέντες οἱ Ἀχαιοὶ προδοσίαν τινὰ πραττομένην ἐν Κορίνθῳ καὶ Σικυῶνι τοὺς ἱππεῖς καὶ τοὺς ξένους ἀπέστειλαν ἐξ Ἄργους ἐκεῖ παραφυλάξοντας, αὐτοὶ δὲ τὰ Νέμεια καταβάντες εἰς Ἄργος ἦγον, ἐλπίσας, ὅπερ ἦν, ὁ Κλεομένης, ὄχλου πανηγυρικοῦ καὶ θεατῶν τὴν πόλιν γέμουσαν ἀπροσδοκήτως ἐπελθὼν μᾶλλον ταράξειν, νυκτὸς ἦγε πρὸς τὰ τείχη τὸ στράτευμα, καὶ τὸν περὶ τὴν Ἀσπίδα τόπον καταλαβὼν ὑπὲρ τοῦ θεάτρου χαλεπὸν ὄντα καὶ δυσπρόσοδον οὕτως τοὺς ἀνθρώπους ἐξέπληξεν ὥστε μηδένα τραπέσθαι πρὸς ἀλκήν, ἀλλὰ καὶ φρουρὰν λαβεῖν, καὶ δοῦναι τῶν πολιτῶν ὁμήρους εἴκοσι, καὶ γενέσθαι συμμάχους Λακεδαιμονίων, ἔχοντος ἐκείνου τὴν ἡγεμονίαν.", "st": "Cleom. 17.3"}, {"sp": "N", "t": "οὐ μικρὸν οὖν τοῦτο καὶ πρὸς δόξαν αὐτῷ καὶ δύναμιν ὑπῆρχεν. οὔτε γὰρ οἱ πάλαι βασιλεῖς Λακεδαιμονίων πολλὰ πραγματευσάμενοι προσαγαγέσθαι τὸ Ἄργος βεβαίως ἠδυνήθησαν, τε δεινότατος τῶν στρατηγῶν Πύρρος εἰσελθὼν καὶ βιασάμενος οὐ κατέσχε τὴν πόλιν, ἀλλ’ ἀπέθανε καὶ πολὺ συνδιεφθάρη μέρος αὐτῷ τῆς δυνάμεως. ὅθεν ἐθαύμαζον τὴν ὀξύτητα καὶ διάνοιαν τοῦ Κλεομένους· καὶ οἱ πρότερον αὐτοῦ τὸν Σόλωνα καὶ τὸν Λυκοῦργον ἀπομιμήσασθαι φάσκοντες ἐν τῇ τῶν χρεῶν ἀφέσει καὶ τῇ τῶν κτημάτων ἐξισώσει καταγελῶντες, τότε παντελῶς ἐπείθοντο τοῦτο αἴτιον γεγονέναι τῆς περὶ τοὺς Σπαρτιάτας μεταβολῆς. οὕτω γὰρ ἔπραττον τὸ πρὶν ταπεινὰ καὶ βοηθεῖν αὑτοῖς ἀδυνάτως εἶχον, ὥστε πέντε μυριάδας ἀνδραπόδων ἐμβαλόντας εἰς τὴν Λακωνικὴν Αἰτωλοὺς ἀπαγαγεῖν, ὅτε φασὶν εἰπεῖν τινα τῶν πρεσβυτέρων Σπαρτιατῶν ὡς ὤνησαν οἱ πολέμιοι τὴν Λακωνικὴν ἀποκουφίσαντες. ὀλίγου δὲ χρόνου διελθόντος ἁψάμενοι μόνον τῶν πατρίων ἐθῶν καὶ καταστάντες εἰς ἴχνος ἐκείνης τῆς ἀγωγῆς, ὥσπερ παρόντι καὶ συμπολιτευομένῳ τῷ Λυκούργῳ πολλὴν ἐπίδειξιν ἀνδρείας ἐποιοῦντο καὶ πειθαρχίας, τὴν τῆς Ἑλλάδος ἀναλαμβάνοντες ἡγεμονίαν τῇ Λακεδαίμονι καὶ ἀνακτώμενοι τὴν Πελοπόννησον.", "st": "Cleom. 18.1"}, {"sp": "N", "t": "ἑαλωκότος δὲ Ἄργους καὶ κατόπιν εὐθὺς προσθεμένων τῷ Κλεομένει Κλεωνῶν καὶ Φλιοῦντος, ἐτύγχανε μὲν ὁ Ἄρατος ἐν Κορίνθῳ ποιούμενός τινα τῶν λεγομένων λακωνίζειν ἐξέτασιν ἀγγελίας δὲ περὶ τούτων προσπεσούσης διαταραχθεὶς καὶ τήν πόλιν ἀποκλίνουσαν αἰσθόμενος πρὸς τόν Κλεομένη καὶ τῶν Ἀχαιῶν ἀπαλλαγῆναι βουλομένην, ἐκάλει μὲν εἰς τὸ βουλευτήριον τοὺς πολίτας, ἔλαθε δὲ διολισθὼν ἄχρι τῆς πύλης, ἐκεῖ δὲ τοῦ ἵππου προσαχθέντος ἀναβὰς ἔφυγεν εἰς Σικυῶνα. τῶν δὲ Κορινθίων ἁμιλλωμένων εἰς Ἄργος πρὸς τόν Κλεομένη φησὶν ὁ Ἄρατος τοὺς ἵππους πάντας ῥαγῆναι, τόν δὲ Κλεομένη μέμφεσθαι τοὺς Κορινθίους μὴ συλλαβόντας αὐτόν, ἀλλ’ ἐάσαντας διαφυγεῖν οὐ μὴν ἀλλὰ καὶ πρὸς αὐτόν ἐλθεῖν Μεγιστόνουν παρὰ τοῦ Κλεομένους δεομένου παραλαβεῖν τὸν Ἀκροκόρινθον εἶχε γὰρ φρουρὰν Ἀχαιῶν καὶ πολλὰ χρήματα διδόντος· ἀποκρίνασθαι δὲ αὐτόν ὡς οὐκ ἔχει τὰ πράγματα, μᾶλλον δὲ ὑπὸ τῶν πραγμάτων αὐτὸς ἔχεται· ταῦτα μὲν ὁ Ἄρατος γέγραφεν.", "st": "Cleom. 19.1"}, {"sp": "N", "t": "ὁ δὲ Κλεομένης ἐκ τοῦ Ἄργους ἐπελθὼν καὶ προσαγαγόμενος Τροιζηνίους, Ἐπιδαυρίους, Ἑρμιονέας, ἧκεν εἰς Κόρινθον καὶ τήν μὲν ἄκραν περιεχαράκωσε, τῶν Ἀχαιῶν οὐ βουλομένων ἐκλιπεῖν, τοῦ δὲ Ἀράτου τοὺς φίλους καὶ τοὺς ἐπιτρόπους μεταπεμψάμενος ἐκέλευσε τήν οἰκίαν καὶ τὰ χρήματα λαβόντας φυλάττειν καὶ διοικεῖν. Τριτύμαλλον δὲ πάλιν τόν Μεσσήνιον ἀπέστειλε πρὸς αὐτόν, ἀξιῶν ὑπὸ τῶν Ἀχαιῶν καὶ τῶν Λακεδαιμονίων ὁμοῦ φυλάττεσθαι τόν Ἀκροκόρινθον, ἰδίᾳ δὲ τῷ Ἀράτῳ διπλῆν ἐπαγγελλόμενος τήν σύνταξιν ἧς ἐλάμβανε παρὰ Πτολεμαίου τοῦ βασιλέως, ἐπεὶ δὲ ὁ Ἄρατος οὐχ ὑπήκουσεν, ἀλλὰ τόν τε υἱὸν ἔπεμψε πρὸς τόν Ἀντίγονον μετὰ τῶν ἄλλων ὁμήρων καὶ ψηφίσασθαι τοὺς Ἀχαιοὺς ἔπεισεν Ἀντιγόνῳ παραδιδόναι τόν Ἀκροκόρινθον, οὕτως ὁ Κλεομένης τήν τε Σικυωνίαν ἐμβαλὼν ἐπόρθησε, καὶ τὰ χρήματα τοῦ Ἀράτου, τῶν Κορινθίων αὐτῷ ψηφισαμένων, δωρεὰν ἔλαβε.", "st": "Cleom. 19.3"}, {"sp": "N", "t": "τοῦ δὲ Ἀντιγόνου μετὰ πολλῆς δυνάμεως τὴν Γεράνειαν ὑπερβάλλοντος οὐκ ᾤετο δεῖν τὸν Ἰσθμόν, ἀλλὰ τὰ Ὄνεια χαρακώσας καί τειχίσας φυλάττειν, καί τοπομαχῶν ἀποτρίβεσθαι τοὺς Μακεδόνας μᾶλλον ἢ συμπλέκεσθαι πρὸς φάλαγγα συνησκημένην. καί τούτοις χρώμενος τοῖς λογισμοῖς εἰς ἀπορίαν καθίστη τὸν Ἀντίγονον. οὔτε γὰρ σῖτον εἶχεν ἐκ παρασκευῆς ἱκανόν, οὔτε βιάσασθαι τὴν πάροδον, καθημένου τοῦ Κλεομένους, ἦν ῥᾴδιον ἐπιχειρήσας δὲ παραδύεσθαι διὰ τοῦ Λεχαίου νυκτός ἐξέπεσε καί τινας ἀπέβαλε τῶν στρατιωτῶν, ὥστε παντάπασι θαρρῆσαι τὸν Κλεομένη καί τοὺς περὶ αὐτὸν ἐπηρμένους τῇ νίκῃ τραπέσθαι πρὸς τὸ δεῖπνον, ἀθυμεῖν δὲ τὸν Ἀντίγονον εἰς οὐκ εὐπόρους κατακλειόμενον ὑπὸ τῆς ἀνάγκης λογισμούς. ἐβουλεύετο γὰρ ἐπὶ τὴν ἄκραν ἀναζευγνύναι τὸ Ἡραῖον κἀκεῖθεν εἰς Σικυῶνα πλοίοις περαιῶσαι τὴν δύναμιν ὃ καί χρόνου πολλοῦ καί παρασκευῆς ἦν οὐ τῆς τυχούσης, ἤδη δὲ πρὸς ἑσπέραν ἧκον ἐξ Ἄργους κατὰ θάλατταν ἄνδρες Ἀράτου φίλοι, καλοῦντες αὐτὸν ὡς ἀφισταμένων τῶν Ἀργείων τοῦ Κλεομένους, ὁ δὲ πράττων ἦν τὴν ἀπόστασιν Ἀριστοτέλης· καὶ τὸ πλῆθος οὐ χαλεπῶς ἔπεισεν, ἀγανακτοῦν ὅτι χρεῶν ἀποκοπὰς οὐκ ἐποίησεν αὐτοῖς ὁ Κλεομένης ἐλπίσασι. λαβὼν οὖν ὁ Ἄρατος παρ’ Ἀντιγόνου στρατιώτας χιλίους καί πεντακοσίους παρέπλευσεν εἰς Ἐπίδαυρον. ὁ δὲ Ἀριστοτέλης ἐκεῖνον οὐ περιέμενεν, ἀλλὰ τοὺς πολίτας παραλαβὼν προσεμάχετο τοῖς φρουροῦσι τὴν ἀκρόπολιν καί παρῆν αὐτῷ Τιμόξενος μετὰ τῶν Ἀχαιῶν ἐκ Σικυῶνος βοηθῶν.", "st": "Cleom. 20.1"}, {"sp": "N", "t": "ταῦτα περὶ δευτέραν φυλακὴν τῆς νυκτὸς ἀκούσας ὁ Κλεομένης μετεπέμψατο Μεγιστόνουν, καὶ πρὸς ὀργὴν ἐκέλευσεν εὐθὺς εἰς Ἄργος βοηθεῖν ὁ γὰρ ὑπὲρ τῶν Ἀργείων μάλιστα καταπιστωσάμενος πρὸς αὑτόν ἐκεῖνος ἦν, καὶ διεκώλυσεν ἐκβαλεῖν τοὺς ὑπόπτους, ἀπολύσας οὖν τὸν Μεγιστόνουν μετὰ δισχιλίων στρατιωτῶν αὐτὸς προσεῖχε τῷ Ἀντιγόνῳ, καὶ τοὺς Κορινθίους παρεθάρρυνεν ὡς οὐδενὸς μεγάλου περὶ τὸ Ἄργος, ἀλλὰ ταραχῆς τινος ἀπ’ ἀνθρώπων ὀλίγων γεγενημένης. ἐπεὶ δὲ ὁ Μεγιστόνους τε παρεισπεσὼν εἰς τὸ Ἄργος ἀνῃρέθη μαχόμενος καὶ μόγις ἀντεῖχον οἱ φρουροὶ καὶ διεπέμποντο συχνοὺς πρὸς τὸν Κλεομένη, φοβηθεὶς μὴ τοῦ Ἄργους οἱ πολέμιοι κρατήσαντες καὶ τὰς παρόδους ἀποκλείσαντες αὐτοὶ πορθῶσιν ἀδεῶς τὴν Λακωνικὴν καὶ πολιορκῶσι τὴν Σπάρτην ἔρημον οὖσαν, ἀπῆγεν ἐκ Κορίνθου τὸ στράτευμα. καὶ ταύτης μὲν εὐθὺς ἐστέρητο τῆς πόλεως εἰσελθόντος Ἀντιγόνου καὶ φρουρὰν καταστήσαντος· ἐπιβαλὼν δὲ τῷ Ἄργει κατὰ τὸ τεῖχος ἐπεχείρησε μὲν εἰσαλέσθαι καὶ συνέστρεψεν ἐκ τῆς πορείας τὴν δύναμιν, ἐκκόψας δὲ τὰς ὑπὸ τὴν Ἀσπίδα ψαλίδας ἀνέβη καὶ συνέμιξε τοῖς ἔνδον ἔτι πρὸς τοὺς Ἀχαιοὺς ἀντέχουσι, καὶ τῶν ἐντὸς ἔνια κλίμακας προσθεὶς κατέλαβε, καὶ τοὺς στενωποὺς ἐρήμους πολεμίων ἐποίησε, τοῖς βέλεσι χρήσασθαι προστάξας τοὺς Κρῆτας. ὡς δὲ κατεῖδε τὸν Ἀντίγονον ἀπὸ τῶν ἄκρων εἰς τὸ πεδίον καταβαίνοντα μετὰ τῆς φάλαγγος, τοὺς δὲ ἱππεῖς ἤδη ῥύδην ἐλαύνοντας εἰς τὴν πόλιν, ἀπέγνω κρατήσειν καὶ συναγαγὼν ἅπαντας πρὸς αὑτόν ἀσφαλῶς κατέβη καὶ παρὰ τὸ τεῖχος ἀπηλλάττετο, μεγίστων μὲν ἐν ἐλαχίστῳ χρόνῳ πραγμάτων ἐπικρατήσας, καὶ μετὰ μικρὸν ὅλης ὁμοῦ τι μιᾷ περιόδῳ Πελοποννήσου κύριος γενέσθαι δεήσας, ταχὺ δ’ αὖθις ἐκπεσὼν ἁπάντων, οἱ μὲν γὰρ εὐθὺς ἀπεχώρησαν αὐτοῦ τῶν στρατευομένων, οἱ δὲ ὀλίγον ὕστερον τῷ Ἀντιγόνῳ τὰς πόλεις παρέδωκαν.", "st": "Cleom. 21.1"}, {"sp": "N", "t": "οὕτω δ’ αὐτῷ πεπραχότι κατὰ τὴν στρατείαν καὶ ἀπαγαγόντι τὴν δύναμιν, ἑσπέρας ἤδη περὶ Τεγέαν ἀφίκοντό τινες ἐκ Λακεδαίμονος οὐκ ἐλάττονα τῆς ἐν χερσὶ δυστυχίαν ἀπαγγέλλοντες, τεθνάναι τὴν γυναῖκα, δι’ ἣν οὐδὲ ταῖς πάνυ κατορθουμέναις ἐκεῖνος ἐνεκαρτέρει στρατείαις, ἀλλὰ συνεχῶς κατέβαινεν εἰς Σπάρτην, ἐρῶν τῆς Ἀγιάτιδος καὶ περὶ πλείστου ποιούμενος ἐκείνην. ἐπλήγη μὲν οὖν καὶ ἤλγησεν, ὡς εἰκὸς ἦν νέον ἄνδρα καλλίστης καὶ σωφρονεστάτης ἀφῃρημένον γυναικός· οὐ μὴν κατῄσχυνεν οὐδὲ προήκατο τῷ πάθει τὸ φρόνημα καὶ τὸ μέγεθος τῆς ψυχῆς, ἀλλὰ καὶ φωνὴν καὶ σχῆμα καὶ μορφὴν ἐν ᾧ πρότερον εἶχεν ἤθει διαφυλάττων τά τε προστάγματα τοῖς ἡγεμόσιν ἐδίδου καὶ περὶ τῆς ἀσφαλείας τῶν Τεγεατῶν ἐφρόντιζεν. ἅμα δὲ ἡμέρᾳ κατέβαινεν εἰς Λακεδαίμονα, καὶ μετὰ τῆς μητρὸς οἴκοι καὶ τῶν παίδων ἀπαλγήσας τὸ πένθος εὐθὺς ἦν ἐν τοῖς περὶ τῶν ὅλων λογισμοῖς.", "st": "Cleom. 22.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Πτολεμαῖος ὁ τῆς Αἰγύπτου βασιλεὺς ἐπαγγελλόμενος αὐτῷ βοήθειαν ἠξίου λαβεῖν ὅμηρα τοὺς παῖδας καὶ τὴν μητέρα, χρόνον μὲν συχνὸν ᾐσχύνετο φράσαι τῇ μητρί, καὶ πολλάκις εἰσελθὼν καὶ πρὸς αὐτῷ γενόμενος τῷ λόγῳ κατεσιώπησεν, ὥστε κἀκείνην ὑπονοεῖν καὶ παρὰ τῶν φίλων αὐτοῦ διαπυνθάνεσθαι μή τι κατοκνεῖ βουλόμενος ἐντυχεῖν αὐτῇ. τέλος δὲ τοῦ Κλεομένους ἀποτολμήσαντος εἰπεῖν, ἐξεγέλασέ τε μέγα καὶ, τοῦτο ἦν, εἶπεν, ὃ πολλάκις ὁρμήσας λέγειν ἀπεδειλίασας; οὐ θᾶττον ἡμᾶς ἐνθέμενος εἰς πλοῖον ἀποστελεῖς, ὅπου ποτὲ τῇ Σπάρτῃ νομίζεις τὸ σῶμα τοῦτο χρησιμώτατον ἔσεσθαι, πρὶν ὑπὸ γήρως αὐτοῦ καθήμενον διαλυθῆναι;", "st": "Cleom. 22.4"}, {"sp": "N", "t": "πάντων οὖν ἑτοίμων γενομένων ἀφίκοντο μὲν εἰς Ταίναρον πεζῇ καὶ προὔπεμψεν ἡ δύναμις αὐτοὺς ἐν τοῖς ὅπλοις· μέλλουσα δὲ τῆς νεὼς ἐπιβαίνειν ἡ Κρατησίκλεια τὸν Κλεομένη μόνον εἰς τὸν νεὼν τοῦ Ποσειδῶνος ἀπήγαγε, καὶ περιβαλοῦσα καὶ κατασπασαμένη διαλγοῦντα καὶ συντεταραγμένον, ἄγε, εἶπεν, ὦ βασιλεῦ Λακεδαιμονίων, ὅπως, ἐπὰν ἔξω γενώμεθα, μηδεὶς ἴδῃ δακρύοντας ἡμᾶς μηδὲ ἀνάξιόν τι τῆς Σπάρτης ποιοῦντας. τοῦτο γὰρ ἐφ’ ἡμῖν μόνον αἱ τύχαι δέ, ὅπως ἂν ὁ δαίμων διδῷ, πάρεισι. ταῦτα δ’ εἰποῦσα καὶ καταστήσασα τὸ πρόσωπον, ἐπὶ τὴν ναῦν ἐχώρει τὸ παιδίον ἔχουσα, καὶ διὰ τάχους ἐκέλευσεν ἀπαίρειν τὸν κυβερνήτην. ἐπεὶ δὲ εἰς Αἴγυπτον ἀφίκετο καὶ τὸν Πτολεμαῖον ἐπύθετο λόγους παρ’ Ἀντιγόνου καὶ πρεσβείας δεχόμενον, περὶ δὲ τοῦ Κλεομένους ἤκουσεν ὅτι, τῶν Ἀχαιῶν προκαλουμένων αὐτὸν εἰς διαλύσεις, φοβοῖτο δι’ ἐκείνην ἄνευ Πτολεμαίου καταθέσθαι τὸν πόλεμον, ἐπέστειλεν αὐτῷ τὰ τῇ Σπάρτῃ πρέποντα καὶ συμφέροντα πράττειν καὶ μὴ διὰ μίαν γραῦν καὶ παιδάριον ἀεὶ δεδιέναι Πτολεμαῖον. αὕτη μὲν οὖν παρὰ τὰς τύχας τοιαύτη λέγεται γεγενῆσθαι.", "st": "Cleom. 22.5"}, {"sp": "N", "t": "τοῦ δὲ Ἀντιγόνου Τεγέαν μὲν παραλαβόντος, Ὀρχομενὸν δὲ καὶ Μαντίνειαν διαρπάσαντος, εἰς αὐτὴν τὴν Λακωνικὴν συνεσταλμένος ὁ Κλεομένης τῶν μὲν εἱλώτων τοὺς πέντε μνᾶς Ἀττικὰς καταβαλόντας ἐλευθέρους ἐποίει καὶ τάλαντα πεντακόσια συνέλεξε, δισχιλίους δὲ προσκαθοπλίσας Μακεδονικῶς ἀντίταγμα τοῖς παρ’ Ἀντιγόνου λευκάσπισιν, ἔργον ἐπὶ νοῦν βάλλεται μέγα καὶ πᾶσιν ἀπροσδόκητον. ἡ Μεγάλη πόλις ἦν μὲν τότε καὶ καθ’ ἑαυτὴν οὐδέν τι μείων οὐδὲ ἀσθενεστέρα τῆς Λακεδαίμονος, εἶχε δὲ τὴν ἀπὸ τῶν Ἀχαιῶν καὶ τοῦ Ἀντιγόνου βοήθειαν, ἐν πλευραῖς καθεζομένου καὶ δοκοῦντος ὑπὸ τῶν Ἀχαιῶν ἐπικεκλῆσθαι μάλιστα τῶν Μεγαλοπολιτῶν σπουδασάντων. ταύτην διαρπάσαι διανοηθεὶς ὁ Κλεομένης οὐ γὰρ ἔστιν ᾧ μᾶλλον ἔοικε τὸ ταχὺ καὶ ἀπροσδόκητον ἐκείνης τῆς πράξεως, ἡμερῶν πέντε σιτία λαβεῖν κελεύσας ἐξῆγε τὴν δύναμιν ἐπὶ τὴν Σελασίαν ὡς τὴν Ἀργολικὴν κακουργήσων· ἐκεῖθεν δὲ καταβὰς ἐπὶ τὴν Μεγαλοπολιτικὴν καὶ δειπνοποιησάμενος περὶ τὸ Ῥοίτειον εὐθὺς ἐπορεύετο τὴν δι’ Ἑλικοῦντος ἐπὶ τὴν πόλιν· ἀποσχὼν δ’ οὐ πολὺ Παντέα μὲν ἔχοντα δύο τάγματα τῶν Λακεδαιμονίων ἀπέστειλε, καταλαβέσθαι κελεύσας μεσοπύργιον ὃ τῶν τειχῶν ἐρημότατον εἶναι τοῖς Μεγαλοπολίταις ἐπυνθάνετο, τῇ δὲ ἄλλῃ δυνάμει σχολαίως ἐπηκολούθει. τοῦ δὲ Παντέως οὐ μόνον ἐκεῖνον τὸν τόπον, ἀλλὰ καὶ πολὺ μέρος Τοῦ τείχους ἀφύλακτον εὑρόντος, καὶ τὰ μὲν καθαιροῦντος εὐθύς, τὰ δὲ διασκάπτοντος, τῶν δὲ φρουρῶν οἷς ἐνέτυχε πάντας ἀποκτείναντος, ἔφθασε προσμίξας ὁ Κλεομένης, καὶ πρὶν αἰσθέσθαι τοὺς Μεγαλοπολίτας ἔνδον ἦν μετὰ τῆς δυνάμεως.", "st": "Cleom. 23.1"}, {"sp": "N", "t": "φανεροῦ δὲ μόλις τοῦ κακοῦ γενομένου τοῖς κατὰ τὴν πόλιν, οἱ μὲν εὐθὺς ἐξέπιπτον ὅσα τυγχάνοι τῶν χρημάτων λαμβάνοντες, οἱ δὲ συνεστρέφοντο μετὰ τῶν ὅπλων, καὶ τοῖς πολεμίοις ἐνιστάμενοι καὶ προσβάλλοντες ἐκείνους μὲν οὐκ ἴσχυσαν ἐκκροῦσαι, τοῖς δὲ φεύγουσι τῶν πολιτῶν ἀσφαλῶς ἀπελθεῖν παρέσχον, ὥστε μὴ πλείονα τῶν χιλίων ἐγκαταληφθῆναι σώματα, τοὺς δὲ ἄλλους ἅπαντας ὁμοῦ μετὰ τέκνων καὶ γυναικῶν φθάσαι διαφυγόντας εἰς Μεσσήνην. ἐσώθη δὲ καὶ τῶν προσβοηθούντων καὶ μαχομένων τὸ πλῆθος· ὀλίγοι δὲ παντάπασιν ἥλωσαν, ὧν ἦν Λυσανδρίδας τε καὶ Θεαρίδας, ἄνδρες ἔνδοξοι καὶ δυνατοὶ μάλιστα τῶν Μεγαλοπολιτῶν. διὸ καὶ λαβόντες αὐτοὺς εὐθὺς οἱ στρατιῶται τῷ Κλεομένει προσῆγον. ὁ δὲ Λυσανδρίδας ὡς εἶδε τὸν Κλεομένη πόρρωθεν, ἀναβοήσας, ἔξεστί σοι νῦν, εἶπεν, ὦ βασιλεῦ Λακεδαιμονίων, ἔργον ἀποδειξαμένῳ τοῦ πεπραγμένου κάλλιον καὶ βασιλικώτατον ἐνδοξοτάτῳ γενέσθαι. ὁ Κλεομένης δὲ ὑποτοπήσας αὐτοῦ τὴν ἔντευξιν, εἶπεν, ὦ Λυσανδρίδα, λέγεις; οὐ γὰρ δή πού με τὴν πόλιν ὑμῖν ἀποδοῦναι κελεύεις; καὶ ὁ Λυσανδρίδας, αὐτό μὲν οὖν, ἔφη, λέγω καὶ συμβουλεύω μὴ διαφθεῖραι πόλιν τηλικαύτην, ἀλλ’ ἐμπλῆσαι φίλων καὶ συμμάχων πιστῶν καὶ βεβαίων, ἀποδόντα Μεγαλοπολίταις τὴν πατρίδα καὶ σωτῆρα δήμου τοσούτου γενόμενον. μικρὸν οὖν ὁ Κλεομένης διασιωπήσας, χαλεπὸν, ἔφη, τὸ πιστεῦσαι ταῦτα, νικάτω δὲ τὸ πρὸς δόξαν ἀεὶ μᾶλλον ἢ τὸ λυσιτελὲς παρ’ ἡμῖν, καὶ ταῦτα εἰπὼν ἀπέστειλε τοὺς ἄνδρας εἰς Μεσσήνην καὶ κήρυκα παρ’ ἑαυτοῦ, τοῖς Μεγαλοπολίταις ἀποδιδοὺς τὴν πόλιν ἐπὶ τῷ συμμάχους εἶναι καὶ φίλους ἀποστάντας Ἀχαιῶν.", "st": "Cleom. 24.1"}, {"sp": "N", "t": "οὕτω δὲ τοῦ Κλεομένους εὐγνώμονα καὶ φιλάνθρωπα προτείναντος οὐκ εἴασε τοὺς Μεγαλοπολίτας Φιλοποίμην ἐγκαταλιπεῖν τὴν πρὸς τοὺς Ἀχαιοὺς πίστιν, ἀλλὰ κατηγορῶν τοῦ Κλεομένους ὡς οὐ ζητοῦντος ἀποδοῦναι τὴν πόλιν, ἀλλὰ προσλαβεῖν τοὺς πολίτας, ἐξέβαλε τὸν Θεαρίδαν καὶ τὸν Λυσανδρίδαν ἐκ τῆς Μεσσήνης. οὗτος ἦν Φιλοποίμην ὁ πρωτεύσας ὕστερον Ἀχαιῶν καὶ μεγίστην κτησάμενος ἐν τοῖς Ἕλλησι δόξαν, ὡς ἰδίᾳ περὶ αὐτοῦ γέγραπται.", "st": "Cleom. 24.5"}, {"sp": "N", "t": "τούτων δὲ ἀπαγγελθέντων τῷ Κλεομένει, τετηρηκὼς τὴν πόλιν ἄθικτον καὶ ἀκέραιον, ὥστε μηδένα λαθεῖν μηδὲ τοὐλάχιστον λαβόντα, τότε παντάπασι τραχυνθεὶς καὶ ἀγανακτήσας τὰ μὲν χρήματα διήρπασεν, ἀνδριάντας δὲ καὶ γραφὰς ἀπέστειλεν εἰς Σπάρτην, τῆς δὲ πόλεως τὰ πλεῖστα καὶ μέγιστα μέρη κατασκάψας καὶ διαφθείρας ἀνέζευξεν ἐπ’ οἴκου, φοβούμενος τὸν Ἀντίγονον καὶ τοὺς Ἀχαιούς. ἐπράχθη δὲ οὐδὲν ἀπ’ αὐτῶν, ἐτύγχανον μὲν γὰρ ἐν Αἰγίῳ βουλὴν ἔχοντες ἐπεὶ δὲ Ἄρατος ἀναβὰς ἐπὶ τὸ βῆμα πολὺν μὲν χρόνον ἔκλαιε τὴν χλαμύδα θέμενος πρὸ τοῦ προσώπου, θαυμαζόντων δὲ καὶ λέγειν κελευόντων εἶπεν ὅτι Μεγάλη πόλις ἀπόλωλεν ὑπὸ Κλεομένους, ἡ μὲν σύνοδος εὐθὺς διελύθη τῶν Ἀχαιῶν καταπλαγέντων τὴν ὀξύτητα καὶ τὸ μέγεθος τοῦ πάθους, ὁ δὲ Ἀντίγονος ἐπιχειρήσας βοηθεῖν, εἶτα βραδέως αὐτῷ τῆς δυνάμεως ἐκ τῶν χειμαδίων ἀνισταμένης, ταύτην μὲν αὖθις ἐκέλευσε κατὰ χώραν μένειν, αὐτὸς δὲ παρῆλθεν εἰς Ἄργος, οὐ πολλοὺς ἔχων στρατιώτας μεθ’ ἑαυτοῦ.", "st": "Cleom. 25.1"}, {"sp": "N", "t": "διὸ καὶ τὸ δεύτερον ἐγχείρημα τοῦ Κλεομένους ἔδοξε μὲν τετολμῆσθαι παραβόλως καὶ μανικῶς, ἐπράχθη δὲ μετὰ πολλῆς προνοίας, ὥς φησι Πολύβιος. εἰδὼς γὰρ εἰς τὰ χειμάδια διεσπαρμένους κατὰ πόλιν τοὺς Μακεδόνας, καὶ τὸν Ἀντίγονον οὐ πολλοὺς ἔχοντα μισθοφόρους ἐν Ἄργει διαχειμάζοντα μετὰ τῶν φίλων, ἐνέβαλεν εἰς τὴν Ἀργείαν, λογιζόμενος ἢ δι’ αἰσχύνην τοῦ Ἀντιγόνου παροξυνθέντος ἐπικρατήσειν ἢ μὴ τολμήσαντα μάχεσθαι διαβαλεῖν πρὸς τοὺς Ἀργείους. ὃ καὶ συνέβη, διαφθειρομένης γὰρ τῆς χώρας ὑπ’ αὑτοῦ καὶ πάντων ἀγομένων καὶ φερομένων, οἱ μὲν Ἀργεῖοι δυσανασχετοῦντες ἐπὶ τὰς θύρας συνεστρέφοντο τοῦ βασιλέως καὶ κατεβόων, μάχεσθαι κελεύοντες ἢ τοῖς κρείττοσιν ἐξίστασθαι τῆς ἡγεμονίας· ὁ δὲ Ἀντίγονος, ὡς ἔδει στρατηγὸν ἔμφρονα, τὸ κινδυνεῦσαι παραλόγως καὶ προέσθαι τὴν ἀσφάλειαν αἰσχρόν, οὐ τὸ κακῶς ἀκοῦσαι παρὰ τοῖς ἐκτὸς ἡγούμενος, οὐ προῆλθεν, ἀλλ’ ἐνέμενε τοῖς αὑτοῦ λογισμοῖς. ὁ δὲ Κλεομένης ἄχρι τῶν τειχῶν τῷ στρατῷ προσελθὼν καὶ καθυβρίσας καὶ διαλυμηνάμενος ἀδεῶς ἀνεχώρησεν.", "st": "Cleom. 25.4"}, {"sp": "N", "t": "ὀλίγῳ δὲ ὕστερον αὖθις, εἰς Τεγέαν ἀκούσας προϊέναι τὸν Ἀντίγονον ὡς ἐκεῖθεν εἰς τὴν Λακωνικὴν ἐμβαλοῦντα, ταχὺ τοὺς στρατιώτας ἀναλαβὼν καὶ καθ’ ἑτέρας ὁδοὺς παραλλάξας ἅμ’ ἡμέρᾳ πρὸς τῇ πόλει τῶν Ἀργείων ἀνεφάνη, πορθῶν τὸ πεδίον καὶ τὸν σῖτον οὐ κείρων, ὥσπερ οἱ λοιποί, δρεπάναις καὶ μαχαίραις, ἀλλὰ κόπτων ξύλοις μεγάλοις εἰς σχῆμα ῥομφαίας ἀπειργασμένοις, ὡς ἐπὶ παιδιᾷ χρωμένους ἐν τῷ πορεύεσθαι σὺν μηδενὶ πόνῳ πάντα συγκατατρῖψαι καὶ διαφθεῖραι τὸν καρπόν. ὡς μέντοι κατὰ τὴν Κυλλάραβιν γενόμενοι τὸ γυμνάσιον ἐπεχείρουν προσφέρειν πῦρ, ἐκώλυσεν, ὡς καὶ τῶν περὶ Μεγάλην πόλιν ὑπ’ ὀργῆς μᾶλλον ἢ καλῶς αὐτῷ πεπραγμένων.", "st": "Cleom. 26.1"}, {"sp": "N", "t": "τοῦ δὲ Ἀντιγόνου πρῶτον μὲν εὐθὺς εἰς Ἄργος ἀναχωρήσαντος, ἔπειτα τὰ ὄρη καὶ τὰς ὑπερβολὰς πάσας φυλακαῖς καταλαβόντος, ἀμελεῖν καὶ καταφρονεῖν προσποιούμενος ἔπεμψε κήρυκας τὰς κλεῖς ἀξιῶν τοῦ Ἡραίου λαβεῖν, ὅπως ἀπαλλάττοιτο τῇ θεῷ θύσας. οὕτω δὲ παίξας καὶ κατειρωνευσάμενος, καὶ τῇ θεῷ θύσας ὑπὸ τὸν νεὼν κεκλεισμένον, ἀπήγαγεν εἰς Φλιοῦντα τὸν στρατόν ἐκεῖθεν δὲ τοὺς φρουροῦντας τὸν Ὀλίγυρτον ἐξελάσας κατέβη παρὰ τὸν Ὀρχομενόν, οὐ μόνον τοῖς πολίταις φρόνημα καὶ θάρσος ἐμπεποιηκώς, ἀλλὰ καὶ τοῖς πολεμίοις ἀνὴρ ἡγεμονικὸς δοκῶν εἶναι καὶ πραγμάτων μεγάλων ἄξιος. τὸ γὰρ ἐκ μιᾶς πόλεως ὁρμώμενον ὁμοῦ τῇ Μακεδόνων δυνάμει καὶ Πελοποννησίοις ἅπασι καὶ χορηγίᾳ βασιλικῇ πολεμεῖν, καὶ μὴ μόνον ἄθικτον διαφυλάττοντα τὴν Λακωνικήν, ἀλλὰ καὶ χώραν κακῶς ποιοῦντα τὴν ἐκείνων καὶ πόλεις αἱροῦντα τηλικαύτας, οὐ τῆς τυχούσης ἐδόκει δεινότητος εἶναι καὶ μεγαλοφροσύνης.", "st": "Cleom. 26.3"}, {"sp": "N", "t": "ἀλλ’ ὁ πρῶτος τὰ χρήματα νεῦρα τῶν πραγμάτων προσειπὼν εἰς τὰ τοῦ πολέμου πράγματα μάλιστα βλέψας τοῦτ’ εἰπεῖν ἔοικε. καὶ Δημάδης, τὰς τριήρεις μὲν καθέλκειν καὶ πληροῦν ποτε τῶν Ἀθηναίων κελευόντων, χρήματα δ’ οὐκ ἐχόντων πρότερόν ἐστιν, ἔφη, τὸ προδεῦσαι τοῦ φυρᾶσαι. λέγεται δὲ καὶ Ἀρχίδαμος ὁ παλαιὸς ὑπὸ τὴν ἀρχὴν τοῦ Πελοποννησιακοῦ πολέμου, κελευόντων εἰσφορὰς τάξαι τῶν συμμάχων αὐτόν, εἰπεῖν ὡς ὁ πόλεμος οὐ τεταγμένα σιτεῖται. καθάπερ γὰρ οἱ σεσωμασκηκότες ἀθληταὶ τῷ χρόνῳ καταβαροῦσι καὶ καταγωνίζονται τοὺς εὐρύθμους καὶ τεχνίτας, οὕτως καὶ ὁ Ἀντίγονος ἐκ πολλῆς ἀναφέρων δυνάμεως πρὸς τὸν πόλεμον ἐξεπόνει καὶ κατήθλει τὸν Κλεομένη γλίσχρως καὶ μόλις πορίζοντα τοῖς ξένοις μισθὸν καὶ τροφὴν τοῖς πολίταις. ἐπεὶ τἆλλά γε πρὸς τοῦ Κλεομένους ὁ χρόνος ἦν, τῶν οἴκοι πραγμάτων ἀνιστάντων τὸν Ἀντίγονον. βάρβαροι γὰρ περιέκοπτον ἀπόντος καὶ κατέτρεχον τὴν Μακεδονίαν, καὶ τότε δὴ πολὺς ἄνωθεν Ἰλλυριῶν ἐμβεβλήκει στρατός, ὑφ’ οὗ πορθούμενοι μετεπέμποντο τὸν Ἀντίγονον οἱ Μακεδόνες, καὶ παρ’ ὀλίγον πρὸ τῆς μάχης συνέτυχε ταῦτα τὰ γράμματα κομισθῆναι πρὸς αὐτόν· ὧν κομισθέντων εὐθὺς ἂν ἀπῆλθε μακρὰ χαίρειν φράσας Ἀχαιοῖς. ἀλλ’ ἡ τὰ μέγιστα τῶν πραγμάτων κρίνουσα τῷ παρὰ μικρὸν τύχη τηλικαύτην ἀπεδείξατο ῥοπὴν καιροῦ καὶ δύναμιν, ὥστε, τῆς μάχης ἐν Σελασίᾳ γενομένης καὶ τοῦ Κλεομένους ἀποβεβληκότος τὴν δύναμιν καὶ τὴν πόλιν, εὐθὺς παρεῖναι τοὺς καλοῦντας τὸν Ἀντίγονον. ὃ καὶ μάλιστα τὴν δυστυχίαν τοῦ Κλεομένους οἰκτροτέραν ἐποίησεν. εἰ γὰρ ἡμέρας δύο μόνας ἐπέσχε καὶ παρήγαγε φυγομαχῶν, οὐκ ἂν ἐδέησεν αὐτῷ μάχης, ἀλλ’ ἐφ’ οἷς ἐβούλετο διηλλάγη πρὸς τοὺς Ἀχαιοὺς ἀπελθόντων τῶν Μακεδόνων νῦν δέ, ὥσπερ εἴρηται, διὰ τὴν ἀχρηματίαν ἐν τοῖς ὅπλοις τὸ πᾶν θέμενος ἠναγκάσθη δισμυρίοις, ὡς Πολύβιός φησι, πρὸς τρισμυρίους ἀντιπαρατάξασθαι.", "st": "Cleom. 27.1"}, {"sp": "N", "t": "καὶ θαυμαστὸν μὲν ἐν τῷ κινδύνῳ παρασχὼν ἑαυτὸν στρατηγόν, ἐκθύμοις δὲ χρησάμενος τοῖς πολίταις, οὐ μὴν οὐδὲ τῶν ξένων μεμπτῶς ἀγωνισαμένων, τῷ τρόπῳ τῆς ὁπλίσεως καὶ τῷ βάρει τῆς ὁπλιτικῆς φάλαγγος ἐξεθλίβη. Φύλαρχος δὲ καὶ προδοσίαν γενέσθαι φησὶ τὴν μάλιστα τῷ Κλεομένει τὰ πράγματα διεργασαμένην. τοῦ γὰρ Ἀντιγόνου τοὺς Ἰλλυριοὺς καὶ τοὺς Ἀκαρνᾶνας ἐκπεριελθεῖν κρύφα κελεύσαντος καὶ κυκλώσασθαι θάτερον κέρας, ἐφ’ οὗ τεταγμένος ἦν Εὐκλείδας ὁ τοῦ Κλεομένους ἀδελφός, εἶτα τὴν ἄλλην ἐπὶ μάχῃ δύναμιν ἐκτάττοντος, ἀπὸ σκοπῆς θεωρῶν ὁ Κλεομένης, ὡς οὐδαμοῦ τὰ ὅπλα τῶν Ἰλλυριῶν καὶ τῶν Ἀκαρνάνων κατεῖδεν, ἐφοβήθη μὴ πρός τι τοιοῦτον αὐτοῖς ὁ ’ Ἀντίγονος κέχρηται. καλέσας δὲ Δαμοτέλη τὸν ἐπὶ τῆς κρυπτείας τεταγμένον, ὁρᾶν ἐκέλευσε καὶ ζητεῖν ὅπως ἔχει τὰ κατὰ νώτου καὶ κύκλῳ τῆς παρατάξεως, τοῦ δὲ Δαμοτέλους (ἦν γὰρ, ὡς λέγεται, χρήμασιν πρότερον ὑπ’ Ἀντιγόνου διεφθαρμένος ἀμελεῖν) ἐκείνων εἰπόντος ὡς καλῶς ἐχόντων, τοῖς δὲ συνάπτουσιν ἐξ ἐναντίας προσέχειν καὶ τούτους ἀμύνεσθαι, πιστεύσας ἐπὶ τὸν Ἀντίγονον ἐχώρει, καὶ τῇ ῥύμῃ τῶν περὶ αὐτὸν Σπαρτιατῶν ὠσάμενος τὴν φάλαγγα τῶν Μακεδόνων ἐπὶ πέντε που σταδίους ὑποχωρούντων ἐκβιαζόμενος καὶ κρατῶν ἠκολούθησεν. εἶτα τῶν περὶ τὸν Εὐκλείδαν ἀπὸ θατέρου κυκλωθέντων ἐπιστὰς καὶ κατιδὼν τὸν κίνδυνον, οἴχῃ; μοι, φίλτατε ἀδελφέ, εἶπεν, οἴχῃ, γενναῖος ὢν καὶ παισὶ ζηλωτὸς Σπαρτιατῶν καὶ γυναιξὶν ἀοίδιμος. οὕτω δὲ τῶν περὶ τὸν Εὐκλείδαν ἀναιρεθέντων, καὶ τῶν ἐκεῖθεν, ὡς ἐκράτουν, ἐπιφερομένων ταραττομένους ὁρῶν τοὺς στρατιώτας καὶ μένειν οὐκέτι τολμῶντας, ἔσῳζεν ἑαυτόν, ἀποθανεῖν δὲ καὶ τῶν ξένων πολλοὺς λέγουσι καὶ Λακεδαιμονίους ἅπαντας πλὴν διακοσίων, ἑξακισχιλίους ὄντας.", "st": "Cleom. 28.1"}, {"sp": "N", "t": "ἐπεὶ δὲ εἰς τὴν πόλιν ἀφίκετο, τοῖς μὲν ἀπαντήσασι τῶν πολιτῶν παρῄνει δέχεσθαι τὸν Ἀντίγονον, αὐτὸς δὲ εἶπεν εἴτε ζῶν εἴτε ἀποθανών, ὃ μέλλοι τῇ Σπάρτῃ συνοίσειν, τοῦτο πράξειν. ὁρῶν δὲ τὰς γυναῖκας τοῖς μετ’ αὐτοῦ πεφευγόσι προστρεχούσας καὶ δεχομένας τὰ ὅπλα καὶ ποτὸν προσφερούσας, αὐτὸς εἰσῆλθε μὲν εἰς τὴν οἰκίαν τὴν ἑαυτοῦ, τῆς δὲ παιδίσκης, ἣν εἶχεν, ἐλευθέραν οὖσαν ἐκ Μεγάλης πόλεως ἀνειληφὼς μετὰ τὴν τῆς γυναικὸς τελευτήν, ὡς εἴθιστο, προσιούσης καὶ βουλομένης ἀπὸ στρατείας ἥκοντα θεραπεύειν, οὔτε πιεῖν ἐκδεδιψηκὼς ὑπέμεινεν οὔτε καθίσαι κεκμηκώς, ἀλλ’ ὥσπερ ἐτύγχανε τεθωρακισμένος τῶν κιόνων τινὶ τὴν χεῖρα προσβαλὼν πλαγίαν καὶ τὸ πρόσωπον ἐπὶ τὸν πῆχυν ἐπιθείς, καὶ χρόνον οὐ πολὺν οὕτω διαναπαύσας τὸ σῶμα καὶ τῇ διανοίᾳ περιδραμὼν ἅπαντας τοὺς λογισμούς, ὥρμησε μετὰ τῶν φίλων εἰς τὸ Γύθιον. κἀκεῖθεν ἐπιβάντες ἐπ’ αὐτὸ τοῦτο παρεσκευασμένων πλοίων ἀνήχθησαν.", "st": "Cleom. 29.1"}, {"sp": "N", "t": "ὁ δὲ Ἀντίγονος ἐξ ἐφόδου παραλαβὼν τὴν πόλιν, καὶ χρησάμενος τοῖς Λακεδαιμονίοις φιλανθρώπως, καὶ τὸ ἀξίωμα τῆς Σπάρτης οὐ προπηλακίσας οὐδ’ ἐνυβρίσας, ἀλλὰ καὶ νόμους καὶ πολιτείαν ἀποδοὺς καὶ τοῖς θεοῖς θύσας, ἀνεχώρησεν ἡμέρᾳ τρίτῃ, πυθόμενος ἐν Μακεδονίᾳ πολὺν πόλεμον εἶναι καὶ πορθεῖσθαι τὴν χώραν ὑπὸ τῶν βαρβάρων, ἤδη δὲ καὶ τὸ νόσημα κατεῖχεν αὐτόν, εἰς φθίσιν ἐκβεβηκὸς ἰσχυρὰν καὶ κατάρρουν σύντονον. οὐ μὴν ἀπεῖπεν, ἀλλ’ ἀντήρκεσε πρὸς τοὺς οἰκείους ἀγῶνας ὅσον ἐπὶ νίκῃ μεγίστῃ καὶ φόνῳ πλείστῳ τῶν βαρβάρων εὐκλεέστερον ἀποθανεῖν, ὡς μὲν εἰκός ἐστι καὶ λέγουσιν οἱ περὶ Φύλαρχον, αὐτῇ τῇ περὶ τὸν ἀγῶνα κραυγῇ τὸ σῶμα προσαναρρήξας ἐν δὲ ταῖς σχολαῖς ἦν ἀκούειν ὅτι βοῶν μετὰ τὴν νίκην ὑπὸ χαρᾶς, ὦ καλῆς ἡμέρας, πλῆθος αἵματος ἀνήγαγε καὶ πυρέξας συντόνως ἐτελεύτησε. ταῦτα μὲν τὰ περὶ Ἀντίγονον.", "st": "Cleom. 30.1"}, {"sp": "N", "t": "Κλεομένης δὲ πλέων ἀπὸ Κυθήρων εἰς νῆσον ἑτέραν, Αἰγιαλίαν, κατέσχεν. ὅθεν εἰς Κυρήνην περαιοῦσθαι μέλλοντος αὐτοῦ, τῶν φίλων εἷς ὄνομα Θηρυκίων, ἀνὴρ πρός τε τὰς πράξεις φρονήματι κεχρημένος μεγάλῳ καὶ τοῖς λόγοις γεγονώς τις ὑψηλὸς ἀεὶ καὶ μεγάλαυχος, ἐντυχὼν αὐτῷ κατ’ ἰδίαν, τὸν μὲν κάλλιστον, εἶπεν, ὦ βασιλεῦ, θάνατον τὸν ἐν τῇ μάχῃ προηκάμεθα. καίτοι πάντες ἤκουσαν ἡμῶν λεγόντων ὡς οὐχ ὑπερβήσεται τὸν βασιλέα τῶν Σπαρτιατῶν Ἀντίγονος εἰ μὴ νεκρόν. ὁ δὲ δεύτερος δόξῃ καὶ ἀρετῇ νῦν ἔτι πάρεστιν ἡμῖν. ποῖ πλέομεν ἀλογίστως, ἀποφεύγοντες ἐγγὺς ὂν κακὸν καὶ μακρὰν διώκοντες; εἰ γὰρ οὐκ αἰσχρόν ἐστι δουλεύειν τοῖς ἀπὸ Φιλίππου καὶ Ἀλεξάνδρου τοὺς ἀφ’ Ἡρακλέους, πλοῦν πολὺν κερδανοῦμεν Ἀντιγόνῳ παραδόντες ἑαυτούς, ὃν εἰκός ἐστι Πτολεμαίου διαφέρειν ὅσον Αἰγυπτίων Μακεδόνας, εἰ δὲ ὑφ’ ὧν κεκρατήμεθα τοῖς ὅπλοις οὐκ ἀξιοῦμεν ἄρχεσθαι, τί τὸν μὴ νενικηκότα δεσπότην ποιοῦμεν αὑτῶν, ἵνα ἀνθ’ ἑνὸς δυεῖν κακίους φανῶμεν, Ἀντίγονον μὲν φεύγοντες, Πτολεμαῖον δὲ κολακεύοντες; ἢ διὰ τὴν μητέρα φήσομεν εἰς Αἴγυπτον ἥκειν; καλὸν μεντἂν αὐτῇ θέαμα γένοιο καὶ ζηλωτόν ἐπιδεικνυμένῃ ταῖς Πτολεμαίου γυναιξὶν αἰχμάλωτον ἐκ βασιλέως καὶ φυγάδα τὸν υἱόν. οὐχ ἕως ἔτι τῶν ἰδίων ξιφῶν ἄρχομεν καὶ τὴν Λακωνικὴν ἀφορῶμεν, ἐνταῦθα τῆς τύχης ἀπαλλάξαντες ἑαυτοὺς ἀπολογησόμεθα τοῖς ἐν Σελασίᾳ κειμένοις ὑπὲρ τῆς Σπάρτης, ἀλλ’ ἐν Αἰγύπτῳ καθεδούμεθα πυνθανόμενοι τίνα τῆς Λακεδαίμονος σατράπην Ἀντίγονος ἀπολέλοιπε;", "st": "Cleom. 31.1"}, {"sp": "N", "t": "τοιαῦτα τοῦ Θηρυκίωνος εἰπόντος ὁ Κλεομένης ἀπεκρίνατο, τῶν ἀνθρωπίνων τὸ ῥᾷστον, ὦ πόνηρε, καὶ πᾶσιν ἐν ἑτοίμῳ διώκων, ἀποθανεῖν, ἀνδρεῖος εἶναι δοκεῖς, φεύγων αἰσχίονα φυγὴν τῆς πρότερον; πολεμίοις μὲν γὰρ ἐν ἐνέδωκαν ἤδη καὶ κρείττονες ἡμῶν, ἢ τύχῃ σφαλέντες ἢ βιασθέντες ὑπὸ πλήθους· ὁ δὲ πρὸς πόνους καὶ ταλαιπωρίας ἢ ψόγους καὶ δόξας ἀνθρώπων ἀπαγορεύων ἡττᾶται τῆς αὑτοῦ μαλακίας, δεῖ γὰρ τὸν αὐθαίρετον θάνατον οὐ φυγὴν εἶναι πράξεων, ἀλλὰ πρᾶξιν. αἰσχρόν γὰρ καὶ ζῆν μόνοις ἑαυτοῖς καὶ ἀποθνῄσκειν· ἐφ’ ὃ νῦν σὺ παρακαλεῖς ἡμᾶς, σπεύδων ἀπαλλαγῆναι τῶν παρόντων, καλὸν δὲ οὐδὲν οὐδὲ χρήσιμον ἄλλο διαπραττόμενος, ἐγὼ δὲ καὶ σὲ καὶ ἐμαυτὸν οἴομαι δεῖν τὰς ὑπὲρ τῆς πατρίδος ἐλπίδας μὴ καταλιπεῖν ὅπου δ’ ἂν ἡμᾶς ἐκεῖναι καταλίπωσι, ῥᾷστα βουλομένοις ἀποθανεῖν ὑπάρξει.", "st": "Cleom. 31.5"}, {"sp": "N", "t": "πρὸς ταῦτα Θηρυκίων οὐδὲν ἀντειπών, ὅτε πρῶτον ἔσχε καιρὸν ἀποστῆναι τοῦ Κλεομένους, ἐκτραπόμενος παρὰ τὸν αἰγιαλὸν ἔσφαξεν ἑαυτόν.", "st": "Cleom. 31.5b"}, {"sp": "N", "t": "ὁ δὲ Κλεομένης ἀπὸ τῶν Αἰγιαλῶν ἀναχθεὶς τῇ Λιβύῃ προσέβαλε, καὶ διὰ τῶν βασιλικῶν παραπεμπόμενος ἧκεν εἰς Ἀλεξάνδρειαν ι. ὀφθεὶς δὲ τῷ Πτολεμαίῳ, κατ’ ἀρχὰς μὲν ἐτύγχανε κοινῶς φιλανθρώπου καὶ μετρίου πρὸς αὐτόν· ἐπεὶ δὲ γνώμης διδοὺς πεῖραν ἀνὴρ ἐφαίνετ’ ἔμφρων, καὶ τῆς καθ’ ἡμέραν ὁμιλίας αὐτοῦ τὸ Λακωνικὸν καὶ ἀφελὲς τὴν χάριν ἐλευθέριον εἶχε, καὶ τὴν εὐγένειαν οὐδαμῇ καταισχύνων οὐδὲ καμπτόμενος ὑπὸ τῆς τύχης, τῶν πρὸς ἡδονὴν καὶ κολακείαν διαλεγομένων πιθανώτερος ἐφαίνετο, πολλὴ μὲν αἰδὼς καὶ μετάνοια τὸν Πτολεμαῖον εἶχεν ἀνδρὸς ἀμελήσαντα τοιούτου καὶ προέμενον τῷ Ἀντιγόνῳ, δόξαν ἅμα κεκτημένῳ τηλικαύτην καὶ δύναμιν, ἀναλαμβάνων δὲ τιμαῖς καὶ φιλοφροσύναις τὸν Κλεομένη παρεθάρρυνεν ὡς μετὰ νεῶν καὶ χρημάτων ἀποστελῶν αὑτὸν εἰς τὴν Ἑλλάδα καὶ καταστήσων εἰς τὴν βασιλείαν. ἐδίδου δὲ καὶ σύνταξιν αὐτῷ τέσσαρα καὶ εἴκοσι τάλαντα καθ’ ἕκαστον ἐνιαυτόν. ἀφ’ ὧν ἐκεῖνος αὑτὸν καὶ τοὺς φίλους εὐτελῶς καὶ σωφρόνως διοικῶν, τὰ πλεῖστα κατανήλισκεν εἰς φιλανθρωπίας καὶ μεταδόσεις τῶν ἀπὸ τῆς Ἑλλάδος εἰς Αἴγυπτον ἐκπεπτωκότων.", "st": "Cleom. 32.1"}, {"sp": "N", "t": "ὁ μὲν οὖν πρεσβύτερος Πτολεμαῖος πρὶν ἐκτελέσαι τῷ Κλεομένει τὴν ἔκπεμψιν ἐτελεύτησε τῆς δὲ βασιλείας εὐθὺς εἰς πολλὴν ἀσέλγειαν καὶ παροινίαν καὶ γυναικοκρατίαν ἐμπεσούσης ἠμελεῖτο καὶ τὰ τοῦ Κλεομένους. ὁ μὲν γὰρ βασιλεὺς αὐτὸς οὕτω διέφθαρτο τὴν ψυχὴν ὑπὸ γυναικῶν καὶ πότων ὥστε, ὁπότε νήφοι μάλιστα καὶ σπουδαιότατος αὑτοῦ γένοιτο, τελετὰς τελεῖν καὶ τύμπανον ἔχων ἐν τοῖς βασιλείοις ἀγείρειν, τὰ δὲ μέγιστα τῆς ἀρχῆς πράγματα διοικεῖν Ἀγαθόκλειαν τὴν ἐρωμένην τοῦ βασιλέως καὶ τὴν ταύτης μητέρα καὶ πορνοβοσκὸν Οἰνάνθην. ὅμως δ’ οὖν ἔδοξέ τις ἐν ἀρχῇ καὶ τοῦ Κλεομένους χρεία γεγονέναι. δεδιὼς γὰρ Μάγαν τὸν ἀδελφὸν Πτολεμαῖος, ὡς ἰσχύοντα διὰ τῆς μητρὸς ἐν τῷ στρατιωτικῷ, τὸν Κλεομένη προσελάμβανε καὶ μετεδίδου τῶν ἀπορρήτων συνεδρίων, βουλευόμενος ἀνελεῖν τὸν ἀδελφόν. ὁ δέ, καίπερ ἁπάντων τοῦτο πράττειν κελευόντων, μόνος ἀπηγόρευσεν, εἰπὼν ὡς μᾶλλον, εἰ δυνατὸν ἦν, ἔδει φῦσαι τῷ βασιλεῖ πλείονας ἀδελφοὺς πρὸς ἀσφάλειαν καὶ διαμονὴν τῶν πραγμάτων. Σωσιβίου δὲ τοῦ πλεῖστον ἐν τοῖς φίλοις δυναμένου φήσαντος οὐκ εἶναι τὰ τῶν μισθοφόρων αὐτοῖς βέβαια τοῦ Μάγα ζῶντος, ἀμελεῖν ἐκέλευσεν ὁ Κλεομένης ἕνεκά γε τούτου· πλείους γὰρ ἢ τρισχιλίους τῶν ξένων εἶναι Πελοποννησίους προσέχοντας αὐτῷ, κἂν μόνον νεύσῃ, προθύμως μετὰ τῶν ὅπλων παρεσομένους. οὗτος ὁ λόγος τότε μὲν οὐ μικρὰν τῷ Κλεομένει καὶ πίστιν εὐνοίας καὶ δόκησιν ἰσχύος προσέθηκεν, ὕστερον δέ, τοῦ Πτολεμαίου τῆς ἀσθενείας ἐπιτεινούσης τὴν δειλίαν, καὶ καθάπερ εἴωθεν ἐν τῷ μηδὲν φρονεῖν, τοῦ πάντα δεδοικέναι καὶ πᾶσιν ἀπιστεῖν ἀσφαλεστάτου δοκοῦντος εἶναι, φοβερὸν ἐποίει τὸν Κλεομένη τοῖς αὐλικοῖς, ὡς ἰσχύοντα παρὰ τοῖς ξένοις· καὶ πολλῶν ἦν ἀκούειν λεγόντων ὅτι οὗτος ὁ λέων ἐν τούτοις τοῖς προβάτοις ἀναστρέφεται. τῷ γὰρ ὄντι τοιοῦτον διέφαινεν ἦθος ἐν τοῖς βασιλικοῖς, ὑποβλέπων ἀτρέμα καὶ παρεπισκοπῶν τὰ πραττόμενα.", "st": "Cleom. 33.1"}, {"sp": "N", "t": "ναῦς μὲν οὖν αἰτῶν καὶ στρατιὰν ἀπεῖπε· πυνθανόμενος δὲ τεθνάναι τὸν Ἀντίγονον, Αἰτωλικῷ δὲ πολέμῳ συμπεπλέχθαι τοὺς Ἀχαιούς, τὰ δὲ πράγματα ποθεῖν αὐτὸν καὶ παρακαλεῖν, ἐν ταραχῇ καὶ διασπασμῷ τῆς Πελοποννήσου γεγενημένης, ἠξίου μὲν μόνος ἀποσταλῆναι μετὰ τῶν φίλων, ἔπειθε δὲ οὐδένα, τοῦ μὲν βασιλέως οὐκ εἰσακούοντος, ἀλλ’ ἐν γυναιξὶ καὶ θιάσοις καὶ κώμοις συνέχοντος ἑαυτόν, ὁ δὲ τῶν ὅλων προεστηκὼς καὶ προβουλεύων Σωσίβιος μένοντα μὲν τὸν Κλεομένη παρὰ γνώμην ἡγεῖτο δυσμεταχείριστον εἶναι καὶ φοβερόν, ἀφεθέντα δὲ τολμηρὸν, ἄνδρα καὶ μεγαλοπράγμονα καὶ τῆς βασιλείας νοσούσης θεατὴν γεγενημένον. οὐδὲ γὰρ αἱ δωρεαὶ κατεπράυνον αὐτόν, ἀλλ’ ὥσπερ τὸν Ἆπιν ἐν ἀφθόνοις διαιτώμενον καὶ τρυφᾶν δοκοῦντα τοῦ κατὰ φύσιν βίου καὶ δρόμων ἀφέτων καὶ σκιρτήσεων ἵμερος ἔχει, καὶ δῆλός ἐστι δυσανασχετῶν τὴν ἐν ταῖς χερσὶ τῶν ἱερέων διατριβήν, οὕτως ἐκεῖνον οὐδὲν ἤρεσκε τῶν μαλθακῶν,", "st": "Cleom. 34.1"}, {"sp": "N", "t": "ἀλλὰ φθινύθεσκε φίλον κῆρ,<br>ὥσπερ Ἀχιλλεύς,<br>αὖθι μένων, ποθέεσκε δ’ ἀυτήν τε πτόλεμόν τε.", "st": "Cleom. 34.1b"}, {"sp": "N", "t": "τοιούτων δὲ τῶν κατ’ αὐτὸν ὄντων πραγμάτων ἀφικνεῖται Νικαγόρας ὁ Μεσσήνιος εἰς Ἀλεξάνδρειαν, ἀνὴρ μισῶν μὲν τὸν Κλεομένη, προσποιούμενος δὲ φίλος εἶναι· χωρίον δέ ποτε καλὸν αὐτῷ πεπρακώς καὶ δι’ ἀσχολίαν, ὡς ἔοικε, διὰ πολέμους οὐκ ἀπειληφὼς τὸ ἀργύριον. τοῦτον οὖν ἐκβαίνοντα τότε τῆς ὁλκάδος ἰδὼν ὁ Κλεομένης ἔτυχε γὰρ ἐν τῇ κρηπῖδι τοῦ λιμένος περιπατῶν ἠσπάζετο προθύμως καὶ τίς αὐτὸν εἰς Αἴγυπτον ἄγοι πρόφασις ἠρώτα. τοῦ δὲ Νικαγόρου φιλοφρόνως ἀντασπαζομένου καὶ φήσαντος ἵππους ἄγειν τῷ βασιλεῖ καλοὺς τῶν πολεμιστηρίων, γελάσας ὁ Κλεομένης, ἐβουλόμην ἄν, ἔφη, σε μᾶλλον ἥκειν ἄγοντα σαμβυκιστρίας καὶ κιναίδους· ταῦτα γὰρ νῦν μάλιστα κατεπείγει τὸν βασιλέα. καὶ ὁ Νικαγόρας τότε μὲν ἐμειδίασεν ἡμέραις δὲ ὕστερον ὀλίγαις ὑπομνήσας τοῦ χωρίου τὸν Κλεομένην νῦν γοῦν ἐδεῖτο τὴν τιμὴν ἀπολαβεῖν, ὡς οὐκ ἂν ἐνοχλήσας, εἰ μὴ περὶ τὴν τῶν φορτίων διάθεσιν μετρίως ἐζημιοῦτο. τοῦ δὲ Κλεομένους φήσαντος οὐδὲν αὐτῷ περιεῖναι τῶν δεδομένων, λυπηθεὶς ὁ Νικαγόρας ἐκφέρει τῷ Σωσιβίῳ τὸ σκῶμμα τοῦ Κλεομένους, ὁ δὲ καὶ τοῦτο μὲν ἀσμένως ἔλαβεν, ἐκ δὲ μείζονος αἰτίας τὸν βασιλέα παροξῦναι ζητῶν ἔπεισε τὸν Νικαγόραν ἐπιστολὴν γράψαντα κατὰ τοῦ Κλεομένους ἀπολιπεῖν, ὡς ἐγνωκότος, εἰ λάβοι τριήρεις καὶ στρατιώτας παρ’ αὐτοῦ, Κυρήνην κατασχεῖν. ὁ μὲν οὖν Νικαγόρας ταῦτα γράψας ἀπέπλευσε· τοῦ δὲ Σωσιβίου μετὰ τέσσαρας ἡμέρας τὴν ἐπιστολὴν πρὸς τὸν Πτολεμαῖον ἀνενεγκόντος ὡς ἀρτίως αὐτῷ δεδομένην καὶ παροξύναντος τὸ μειράκιον, ἔδοξεν εἰς οἰκίαν μεγάλην εἰσαγαγεῖν τὸν Κλεομένην, καὶ τὴν ἄλλην ὁμοίως παρέχοντας δίαιταν ἐξόδων εἴργειν.", "st": "Cleom. 35.1"}, {"sp": "N", "t": "ἦν μὲν οὖν καὶ ταῦτα λυπηρὰ τῷ Κλεομένει, μοχθηροτέρας δὲ τὰς περὶ τοῦ μέλλοντος ἐλπίδας ἔσχεν ἐκ τοιαύτης συντυχίας. Πτολεμαῖος ὁ Χρυσέρμου φίλος ὢν τοῦ βασιλέως πάντα τὸν χρόνον ἐπιεικῶς διείλεκτο τῷ Κλεομένει, καὶ συνήθειά τις ὑπῆρχεν αὐτοῖς καὶ παρρησία πρὸς ἀλλήλους. οὗτος οὖν τότε, τοῦ Κλεομένους δεηθέντος ἐλθεῖν πρὸς αὐτόν, ἦλθε μὲν καὶ διελέχθη μέτρια, τὸ ὕποπτον ἐξαιρῶν καὶ περὶ τοῦ βασιλέως ἀπολογούμενος· ἀπιὼν δὲ πάλιν ἐκ τῆς οἰκίας, καὶ μὴ προνοήσας ἐξόπισθεν ἄχρι τῶν θυρῶν ἐπακολουθοῦντα τὸν Κλεομένη, πικρῶς ἐπετίμησε τοῖς φύλαξιν ὡς δὴ μέγα θηρίον καὶ δυστήρητον ἀμελῶς φυλάττουσι καὶ ῥᾳθύμως. τούτων ὁ Κλεομένης αὐτήκοος γενόμενος, καὶ πρὶν αἰσθέσθαι τὸν Πτολεμαῖον ἀναχωρήσας ἔφρασε τοῖς φίλοις. εὐθὺς οὖν πάντες ἃς πρότερον εἶχον ἐλπίδας ἐκβαλόντες, πρὸς ὀργὴν ἐβουλεύσαντο τοῦ Πτολεμαίου τὴν ἀδικίαν ἀμυνάμενοι καὶ τὴν ὕβριν ἀξίως τῆς Σπάρτης ἀποθανεῖν, καὶ μὴ περιμένειν ὥσπερ ἱερεῖα πιανθέντας κατακοπῆναι· δεινὸν γάρ, εἰ τὰς πρὸς Ἀντίγονον, ἄνδρα πολεμιστὴν καὶ δραστήριον, διαλύσεις ὑπεριδὼν Κλεομένης κάθηται μητραγύρτου βασιλέως σχολὴν ἀναμένων, ὅταν πρῶτον ἀπόθηται τὸ τύμπανον καὶ καταπαύσῃ τὸν θίασον, ἀποκτενοῦντος αὐτόν.", "st": "Cleom. 36.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ἔδοξε ταῦτα καὶ κατὰ τύχην ὁ Πτολεμαῖος εἰς Κάνωβον ἐξώρμησε, πρῶτον μὲν διέδωκαν λόγον ὡς παραλύοιτο τῆς φυλακῆς ὑπὸ τοῦ βασιλέως· ἔπειτα ἔκ τινος ἔθους βασιλικοῦ τοῖς μέλλουσιν ἐξ εἱρκτῆς ἀπολύεσθαι δείπνου τε πεμπομένου καὶ ξενίων, οἱ φίλοι πολλὰ τοιαῦτα τῷ Κλεομένει παρασκευάσαντες ἔξωθεν εἰσέπεμψαν, ἐξαπατῶντες τοὺς φύλακας οἰομένους ὑπὸ τοῦ βασιλέως ἀπεστάλθαι. καὶ γὰρ ἔθυε καὶ μετεδίδου τούτων ἀφθόνως αὐτοῖς, καὶ ἐπιτιθεὶς στεφάνους καὶ κατακλιθεὶς εἱστιᾶτο μετὰ τῶν φίλων, λέγεται δὲ τάχιον ἢ διεγνώκει πρὸς τὴν πρᾶξιν ὁρμῆσαι, συναισθόμενος οἰκέτην ἕνα τῶν συνειδότων τὴν πρᾶξιν ἔξω παρὰ γυναικὶ κεκοιμημένον ἧς ἤρα. καὶ φοβηθεὶς μήνυσιν, ἐπειδὴ μέσον ἡμέρας ἦν καὶ τοὺς φύλακας ᾔσθετο καθεύδοντας ὑπὸ τῆς μέθης, ἐνδυσάμενος τὸν χιτῶνα καὶ τὴν ῥαφὴν ἐκ τοῦ δεξιοῦ παραλυσάμενος ὤμου, γυμνῷ τῷ ξίφει μετὰ τῶν φίλων ἐξεπήδησεν ἐνεσκευασμένων ὁμοίως, δεκατριῶν ὄντων. Ἱππίτας δὲ χωλὸς ὢν τῇ μὲν πρώτῃ συνεξέπεσεν ὁρμῇ προθύμως, ὡς δὲ ἑώρα σχολαίτερον πορευομένους δι’ αὐτόν, ἐκέλευσεν ἀνελεῖν καὶ μὴ διαφθείρειν τὴν πρᾶξιν, ἄχρηστον ἄνθρωπον περιμένοντας, ἔτυχε δὲ τῶν Ἀλεξανδρέων τις ἵππον ἄγων παρὰ τὰς θύρας· τοῦτον ἀφελόμενοι καὶ τὸν Ἱππίταν ἀναβαλόντες, ἐφέροντο δρόμῳ διὰ τῶν στενωπῶν καὶ παρεκάλουν τὸν ὄχλον ἐπὶ τὴν ἐλευθερίαν. τοῖς δὲ τοσοῦτον, ὡς ἔοικεν, ἀλκῆς μετῆν ὅσον ἐπαινεῖν καὶ θαυμάζειν τὴν τοῦ Κλεομένους τόλμαν, ἀκολουθεῖν δὲ καὶ βοηθεῖν οὐδεὶς ἐθάρρει.", "st": "Cleom. 37.1"}, {"sp": "N", "t": "τὸν μὲν οὖν τοῦ Χρυσέρμου Πτολεμαῖον ἐκ τῆς αὐλῆς ἐξιόντα τρεῖς εὐθὺς προσπεσόντες ἀπέκτειναν ἑτέρου δὲ Πτολεμαίου τοῦ φυλάσσοντος τὴν πόλιν ἐλαύνοντος ἅρματι πρὸς αὐτούς, ὁρμήσαντες ἐναντίοι τοὺς μὲν ὑπηρέτας καὶ δορυφόρους διεσκέδασαν, αὐτόν δὲ κατασπάσαντες ἀπὸ τοῦ ἅρματος ἀπέκτειναν. εἶτα πρὸς τὴν ἄκραν ἐχώρουν, ἀναρρῆξαι διανοούμενοι τὸ δεσμωτήριον καὶ χρήσασθαι τῷ πλήθει τῶν δεδεμένων. ἔφθασαν δὲ φραξάμενοι καλῶς οἱ φύλακες, ὥστε καὶ ταύτης ἀποκρουσθέντα τῆς πείρας τὸν Κλεομένη διαφέρεσθαι καὶ πλανᾶσθαι κατὰ τὴν πόλιν, οὐδενὸς αὐτῷ προσχωροῦντος, ἀλλὰ φευγόντων καὶ φοβουμένων ἁπάντων. οὕτως οὖν ἀποστὰς καὶ πρὸς τοὺς φίλους εἰπών, οὐδὲν ἦν ἄρα θαυμαστὸν ἄρχειν γυναῖκας ἀνθρώπων φευγόντων τὴν ἐλευθερίαν, παρεκάλεσε πάντας ἀξίως αὐτοῦ καὶ τῶν πεπραγμένων τελευτᾶν. καὶ πρῶτος μὲν Ἱππίτας ὑπὸ τῶν νεωτέρων τινὸς ἐπλήγη δεηθείς, ἔπειτα τῶν ἄλλων ἕκαστος εὐκόλως καὶ ἀδεῶς ἑαυτὸν ἀποσφάττει, πλὴν Παντέως τοῦ πρώτου Μεγάλην πόλιν καταλαβόντος. τοῦτον δὲ κάλλιστον ὥρᾳ καὶ πρὸς τὴν ἀγωγὴν εὐφυέστατον τῶν νέων γενόμενον ἐρώμενον ἐσχηκὼς ὁ βασιλεὺς ἐκέλευσεν, ὅταν αὐτόν τε καὶ τοὺς ἄλλους ἴδῃ πεπτωκότας, οὕτω τελευτᾶν. ἤδη δὲ κειμένων ἁπάντων ἐπιπορευόμενος ὁ Παντεὺς καὶ τῷ ξιφιδίῳ παραπτόμενος καθ’ ἕκαστον ἀπεπειρᾶτο μή τις διαλανθάνοι ζῶν. ἐπεὶ δὲ καὶ τὸν Κλεομένη νύξας παρὰ τὸ σφυρὸν εἶδε συστρέψαντα τὸ πρόσωπον, ἐφίλησεν αὐτόν, εἶτα παρεκάθισε· καὶ τέλος ἔχοντος ἤδη περιβαλὼν τὸν νεκρὸν ἑαυτὸν ἐπικατέσφαξε.", "st": "Cleom. 37.5"}, {"sp": "N", "t": "Κλεομένης μὲν οὖν ἑκκαίδεκα τῆς Σπάρτης βασιλεύσας ἔτη καὶ τοιοῦτος ἀνὴρ γενόμενος οὕτω κατέστρεψε, Τῆς δὲ φήμης εἰς τὴν πόλιν ὅλην σκεδασθείσης ἡ μὲν Κρατησίκλεια, καίπερ οὖσα γενναία γυνὴ, προὔδωκε τὸ φρόνημα πρὸς τὸ τῆς συμφορᾶς μέγεθος, καὶ περιβαλοῦσα τὰ παιδία τοῦ Κλεομένους ὠλοφύρετο. τῶν δὲ παιδίων τὸ πρεσβύτερον ἀποπηδῆσαν, οὐδενὸς ἂν προσδοκήσαντος, ἀπὸ τοῦ τέγους ἐπὶ κεφαλὴν ἔρριψεν ἑαυτό καὶ κακῶς μὲν ἔσχεν, οὐ μὴν ἀπέθανεν, ἀλλ’ ἤρθη βοῶν καὶ ἀγανακτοῦν ἐπὶ τῷ διακωλύεσθαι τελευτᾶν.", "st": "Cleom. 38.1"}, {"sp": "N", "t": "ὁ δὲ Πτολεμαῖος, ὡς ἔγνω ταῦτα, προσέταξε τὸ μὲν σῶμα τοῦ Κλεομένους κρεμάσαι καταβυρσώσαντας, ἀποκτεῖναι δὲ τὰ παιδία καὶ τὴν μητέρα καὶ τὰς περὶ αὐτὴν γυναῖκας. ἐν δὲ ταύταις ἦν καὶ Παντέως γυνή καλλίστη καὶ γενναιοτάτη τὸ εἶδος. ἔτι δὲ αὐτοῖς νεογάμοις οὖσιν ἐν ἀκμαῖς ἐρώτων αἱ τύχαι συνέβησαν, εὐθὺς μὲν οὖν συνεκπλεῦσαι τῷ Παντεῖ βουλομένην αὐτὴν οὐκ εἴασαν οἱ γονεῖς, ἀλλὰ βίᾳ κατακλείσαντες ἐφύλαττον· ὀλίγῳ δὲ ὕστερον ἵππον ἑαυτῇ παρασκευάσασα καὶ χρυσίδιον οὐ πολὺ νυκτὸς ἀπέδρα, καὶ διώξασα συντόνως ἐπὶ Ταίναρον, ἐκεῖθεν ἐπέβη νεὼς εἰς Αἴγυπτον πλεούσης· καὶ διεκομίσθη πρὸς τόν ἄνδρα καὶ συνδιήνεγκεν αὐτῷ τόν ἐπὶ ξένης βίον ἀλύπως καὶ ἱλαρῶς. αὕτη τότε τὴν Κρατησίκλειαν ὑπὸ τῶν στρατιωτῶν ἐξαγομένην ἐχειραγώγει, τόν τε πέπλον αὐτῆς ὑπολαμβάνουσα, καὶ θαρρεῖν παρακαλοῦσα μηδέν τι μηδ’ αὐτὴν ἐκπεπληγμένην τόν θάνατον, ἀλλ’ ἓν μόνον αἰτουμένην, πρὸ τῶν παιδίων ἀποθανεῖν. ἐπεὶ δὲ ἦλθον εἰς τόν τόπον ἐν ᾧ ταῦτα δρᾶν εἰώθεσαν οἱ ὑπηρέται, πρῶτον μὲν τὰ παιδία, τῆς Κρατησικλείας ὁρώσης, ἔσφαττον, εἶτα ἐκείνην, ἓν τοῦτο μόνον ἐπὶ τηλικούτοις φθεγξαμένην πάθεσιν, ὦ τέκνα, ποῖ ἐμόλετε; ἡ δὲ Παντέως γυνὴ, περιζωσαμένη τὸ ἱμάτιον, εὔρωστος οὖσα καὶ μεγάλη τῶν ἀποθνῃσκουσῶν ἑκάστην σιωπῇ καὶ μεθ’ ἡσυχίας ἐθεράπευε καὶ περιέστελλεν ἐκ τῶν ἐνδεχομένων. τέλος δὲ μετὰ πάσας ἑαυτὴν κοσμήσασα, καὶ καταγαγοῦσα τὴν περιβολήν, καὶ μηδένα προσελθεῖν ἐάσασα μηδὲ ἰδεῖν ἄλλον ἢ τόν ἐπὶ τῆς σφαγῆς τεταγμένον, ἡρωικῶς κατέστρεψεν, οὐδενὸς δεηθεῖσα κοσμοῦντος καὶ περικαλύπτοντος μετὰ τὴν τελευτήν. οὕτω παρέμεινε τῷ θανάτῳ τὸ κόσμιον τῆς ψυχῆς, καὶ διεφύλαξεν ἣν ζῶσα φρουρὰν τῷ σώματι περιέθηκεν.", "st": "Cleom. 38.3"}, {"sp": "N", "t": "ἡ μὲν οὖν Λακεδαίμων, ἐφαμίλλως ἀγωνισαμένη τῷ γυναικείῳ δράματι πρὸς τὸ ἀνδρεῖον, ἐν τοῖς ἐσχάτοις καιροῖς ἐπέδειξε τὴν ἀρετὴν ὑβρισθῆναι μὴ δυναμένην ὑπὸ τῆς τύχης, ὀλίγαις δὲ ὕστερον ἡμέραις οἱ τὸ σῶμα τοῦ Κλεομένους ἀνεσταυρωμένον παραφυλάττοντες εἶδον εὐμεγέθη δράκοντα τῇ κεφαλῇ περιπεπλεγμένον καὶ ἀποκρύπτοντα τὸ πρόσωπον, ὥστε μηδὲν ὄρνεον ἐφίπτασθαι σαρκοφάγον. ἐκ δὲ τούτου δεισιδαιμονία προσέπεσε τῷ βασιλεῖ καὶ φόβος, ἄλλων καθαρμῶν ταῖς γυναιξὶν ἀρχὴν παρασχών, ὡς ἀνδρὸς ἀνῃρημένου θεοφιλοῦς καὶ κρείττονος τὴν φύσιν. οἱ δὲ Ἀλεξανδρεῖς καὶ προσετρέποντο φοιτῶντες ἐπὶ τὸν τόπον, ἥρωα τὸν Κλεομένη καὶ θεῶν παῖδα προσαγορεύοντες, ἄχρι οὗ κατέπαυσαν αὐτοὺς οἱ σοφώτεροι, διδόντες λόγον ὡς μελίττας μὲν βόες, σφῆκας δὲ ἵπποι κατασαπέντες ἐξανθοῦσι, κάνθαροι δὲ ὄνων τὸ αὐτὸ παθόντων ζῳογονοῦνται, τὰ δὲ ἀνθρώπινα σώματα, τῶν περὶ τὸν μυελὸν ἰχώρων συρροήν τινα καὶ σύστασιν ἐν ἑαυτοῖς λαβόντων, ὄφεις ἀναδίδωσι. καὶ τοῦτο κατιδόντες οἱ παλαιοὶ μάλιστα τῶν ζῴων τὸν δράκοντα τοῖς ἥρωσι συνῳκείωσαν.", "st": "Cleom. 39.1"}, {"sp": "HDR", "t": "Τιβέριος Γράγχος"}, {"sp": "N", "t": "ἡμεῖς δὲ τὴν πρώτην ἱστορίαν ἀποδεδωκότες ἔχομεν οὐκ ἐλάττονα πάθη τούτων ἐν τῇ Ῥωμαϊκῇ συζυγίᾳ θεωρῆσαι, τὸν Τιβερίου καὶ Γαΐου βίον ἀντιπαραβάλλοντες. οὗτοι Τιβερίου Γράγχου παῖδες ἦσαν, ᾧ τιμητῇ τε Ῥωμαίων γενομένῳ καὶ δὶς ὑπατεύσαντι καὶ θριάμβους δύο καταγαγόντι λαμπρότερον ἦν τὸ ἀπὸ τῆς ἀρετῆς ἀξίωμα· διὸ καὶ τὴν Σκηπίωνος τοῦ καταπολεμήσαντος Ἀννίβαν θυγατέρα Κορνηλίαν, οὐκ ὢν φίλος, ἀλλὰ καὶ διάφορος τῷ ἀνδρὶ γεγονώς, λαβεῖν ἠξιώθη μετὰ τὴν ἐκείνου τελευτήν. λέγεται δέ ποτε συλλαβεῖν αὐτὸν ἐπὶ τῆς κλίνης ζεῦγος δρακόντων, τοὺς δὲ μάντεις σκεψαμένους τὸ τέρας ἄμφω μὲν οὐκ ἐᾶν ἀνελεῖν οὐδὲ ἀφεῖναι, περὶ δὲ θατέρου διαιρεῖν, ὡς ὁ μὲν ἄρρην τῷ Τιβερίῳ φέροι θάνατον ἀναιρεθείς, ἡ δὲ θήλεια τῇ Κορνηλίᾳ. τὸν οὖν Τιβέριον καὶ φιλοῦντα τὴν γυναῖκα, καὶ μᾶλλον αὐτῷ προσήκειν ὄντι πρεσβυτέρῳ τελευτᾶν ἡγούμενον ἔτι νέας οὔσης ἐκείνης, τὸν μὲν ἄρρενα κτεῖναι τῶν δρακόντων, ἀφεῖναι δὲ τὴν θήλειαν εἶτα ὕστερον οὐ πολλῷ χρόνῳ τελευτῆσαι, δεκαδύο παῖδας ἐκ τῆς Κορνηλίας αὐτῷ γεγονότας καταλιπόντα.", "st": "TG 1.1"}, {"sp": "N", "t": "Κορνηλία δὲ ἀναλαβοῦσα τοὺς παῖδας καὶ τὸν οἶκον, οὕτω σώφρονα καὶ φιλότεκνον καὶ μεγαλόψυχον αὑτὴν παρέσχεν ὥστε μὴ κακῶς δόξαι βεβουλεῦσθαι τὸν Τιβέριον ἀντὶ τοιαύτης γυναικὸς ἀποθανεῖν ἑλόμενον, ἥ γε καὶ Πτολεμαίου τοῦ βασιλέως κοινουμένου τὸ διάδημα καὶ μνωμένου τὸν γάμον αὐτῆς ἠρνήσατο, καὶ χηρεύουσα τοὺς μὲν ἄλλους ἀπέβαλε παῖδας, μίαν δέ τῶν θυγατέρων, ἢ Σκηπίωνι τῷ νεωτέρῳ συνῴκησε, καὶ δύο υἱοὺς, περὶ ὧν τάδε γέγραπται, Τιβέριον καὶ Γάϊον, διαγενομένους οὕτω φιλοτίμως ἐξέθρεψεν ὥστε πάντων εὐφυεστάτους Ῥωμαίων ὁμολογουμένως γεγονότας πεπαιδεῦσθαι δοκεῖν βέλτιον ἢ πεφυκέναι πρὸς ἀρετήν.", "st": "TG 1.4"}, {"sp": "N", "t": "ἐπεὶ δέ, ὥσπερ ἡ τῶν πλασσομένων καὶ γραφομένων Διοσκούρων ὁμοιότης ἔχει τινὰ τοῦ πυκτικοῦ πρὸς τὸν δρομικὸν ἐπὶ τῆς μορφῆς διαφοράν, οὕτω τῶν νεανίσκων ἐκείνων ἐν πολλῇ τῇ πρὸς ἀνδρείαν καὶ σωφροσύνην, ἔτι δὲ ἐλευθεριότητα καὶ λογιότητα καὶ μεγαλοψυχίαν ἐμφερείᾳ μεγάλαι περὶ τὰ ἔργα καὶ τὰς πολιτείας οἷον ἐξήνθησαν καὶ διεφάνησαν ἀνομοιότητες, οὐ χεῖρον εἶναί μοι δοκεῖ ταύτας προεκθέσθαι.", "st": "TG 2.1"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ἰδέᾳ προσώπου καὶ βλέμματι καὶ κινήματι πρᾶος καὶ καταστηματικὸς ἦν ὁ Τιβέριος, ἔντονος δὲ καὶ σφοδρὸς ὁ Γάϊος, ὥστε καὶ δημηγορεῖν τὸν μὲν ἐν μιᾷ χώρᾳ βεβηκότα κοσμίως, τὸν δὲ Ῥωμαίων πρῶτον ἐπὶ τοῦ βήματος περιπάτῳ τε χρήσασθαι καὶ περισπάσαι τήν τήβεννον ἐξ ὤμου λέγοντα, καθάπερ Κλέωνα τὸν Ἀθηναῖον ἱστόρηται περισπάσαι τε τήν περιβολὴν καὶ τὸν μηρὸν ἀλοῆσαι πρῶτον τῶν δημηγορούντων. ἔπειτα ὁ λόγος τοῦ μὲν Γαΐου φοβερὸς καὶ περιπαθὴς εἰς δείνωσιν, ἡδίων δὲ ὁ τοῦ Τιβερίου καὶ μᾶλλον ἐπαγωγὸς οἴκτου· τῇ δὲ λέξει καθαρὸς καὶ διαπεπονημένος ἀκριβῶς ἐκεῖνος, ὁ δὲ Γαΐου πιθανὸς καὶ γεγανωμένος. οὕτω δὲ καὶ περὶ δίαιταν καὶ τράπεζαν εὐτελὴς καὶ ἀφελὴς ὁ Τιβέριος, ὁ δὲ Γάιος τοῖς μὲν ἄλλοις παραβαλεῖν σώφρων καὶ αὐστηρός, τῇ δὲ πρὸς τὸν ἀδελφὸν διαφορᾷ νεοπρεπὴς καὶ περίεργος, ὡς οἱ περὶ Δροῦσον ἤλεγχον ὅτι δελφῖνας ἀργυροῦς ἐπρίατο τιμῆς εἰς ἑκάστην λίτραν δραχμῶν χιλίων καὶ διακοσίων πεντήκοντα, τῷ δὲ ἤθει κατὰ τήν τοῦ λόγου διαφορὰν ὁ μὲν ἐπιεικὴς καὶ πρᾶος, ὁ δὲ τραχὺς καὶ θυμοειδής, ὥστε καὶ παρὰ γνώμην ἐν τῷ λέγειν ἐκφερόμενον πολλάκις ὑπ’ ὀργῆς τήν τε φωνὴν ἀποξύνειν καὶ βλασφημεῖν καὶ συνταράττειν τὸν λόγον. ὅθεν καὶ βοήθημα τῆς ἐκτροπῆς ἐποιήσατο ταύτης τὸν Λικίννιον, οἰκέτην οὐκ ἀνόητον, ὃς ἔχων φωνασκικὸν ὄργανον, ᾧ τοὺς φθόγγους ἀναβιβάζουσιν, ὄπισθεν ἑστὼς τοῦ Γαΐου λέγοντος, ὁπηνίκα τραχυνόμενον αἴσθοιτο τῇ φωνῇ καὶ παραρρηγνύμενον δι’ ὀργήν, ἐνεδίδου τόνον μαλακόν, ᾧ τὸ σφοδρὸν εὐθὺς ἐκεῖνος ἅμα τοῦ πάθους καὶ τῆς φωνῆς ἀνιεὶς ἐπραΰνετο καὶ παρεῖχεν ἑαυτὸν εὐανάκλητον.", "st": "TG 2.2"}, {"sp": "N", "t": "αἱ μὲν οὖν διαφοραὶ τοιαῦταί τινες ἦσαν αὐτῶν· ἀνδραγαθία δὲ πρὸς τοὺς πολεμίους καὶ πρὸς τοὺς ὑπηκόους δικαιοσύνη καὶ πρὸς τὰς ἀρχὰς ἐπιμέλεια καὶ πρὸς τὰς ἡδονὰς ἐγκράτεια, ἀπαράλλακτος, ἦν δὲ πρεσβύτερος ἐνιαυτοῖς ἐννέα ὁ Τιβέριος· καὶ τοῦτο τὴν ἑκατέρου πολιτείαν ἀπηρτημένην τοῖς χρόνοις ἐποίησε καὶ τὰς πράξεις οὐχ ἥκιστα διελυμήνατο, μὴ συνακμασάντων μηδὲ συμβαλόντων εἰς τὸ αὐτὸ τὴν δύναμιν, μεγάλην ἂν ἐξ ἀμφοῖν ὁμοῦ καὶ ἀνυπέρβλητον γενομένην. λεκτέον οὖν ἰδίᾳ περὶ ἑκατέρου καὶ περὶ τοῦ πρεσβυτέρου πρότερον.", "st": "TG 3.1"}, {"sp": "N", "t": "ἐκεῖνος τοίνυν εὐθὺς ἐκ παίδων γενόμενος οὕτως ἦν περιβόητος ὥστε τῆς τῶν αὐγούρων λεγομένης ἱερωσύνης ἀξιωθῆναι δι’ ἀρετὴν μᾶλλον ἢ διὰ τὴν εὐγένειαν. ἐδήλωσε δὲ Ἄππιος Κλαύδιος, ἀνὴρ ὑπατικὸς καὶ τιμητικὸς καὶ προγεγραμμένος κατ’ ἀξίωμα τῆς Ῥωμαίων βουλῆς καὶ πολὺ φρονήματι τοὺς καθ’ αὑτὸν ὑπεραίρων. ἑστιωμένων γὰρ ἐν ταὐτῷ τῶν ἱερέων, προσαγορεύσας τὸν Τιβέριον καὶ φιλοφρονηθεὶς, αὐτὸς ἐμνᾶτο τῇ θυγατρὶ νυμφίον. δεξαμένου δὲ ἀσμένως ἐκείνου καὶ τῆς καταινέσεως οὕτω γενομένης, εἰσιὼν ὁ Ἄππιος οἴκαδε πρὸς αὑτὸν ἀπὸ τῆς θύρας εὐθὺς ἐκάλει τὴν γυναῖκα μεγάλῃ τῇ φωνῇ βοῶν, ὦ Ἀντιστία, τὴν Κλαυδίαν ἡμῶν ἀνδρὶ καθωμολόγηκα. κἀκείνη θαυμάσασα, τίς, εἶπεν, ἡ σπουδή ἢ τί τὸ τάχος; εἰ δὲ Τιβέριον αὐτῇ Γράγχον εὑρήκεις νυμφίον. οὐκ ἀγνοῶ δὲ ὅτι τοῦτό τινες ἐπὶ τὸν πατέρα τῶν Γράγχων Τιβέριον καὶ Σκηπίωνα τὸν Ἀφρικανὸν ἀναφέρουσιν, ἀλλ’ οἱ πλείους ὡς ἡμεῖς γράφομεν ἱστοροῦσι, καὶ Πολύβιος μετὰ τὴν Σκηπίωνος Ἀφρικανοῦ τελευτὴν τοὺς οἰκείους φησὶν ἐκ πάντων προκρίναντας τὸν Τιβέριον δοῦναι τὴν Κορνηλίαν, ὡς ὑπὸ τοῦ πατρὸς ἀνέκδοτον καὶ ἀνέγγυον ἀπολειφθεῖσαν.", "st": "TG 4.1"}, {"sp": "N", "t": "ὁ δ’ οὖν νεώτερος Τιβέριος στρατευόμενος ἐν Λιβύῃ μετὰ τοῦ δευτέρου Σκηπίωνος, ἔχοντος αὑτοῦ τὴν ἀδελφήν, ὁμοῦ συνδιαιτώμενος ὑπὸ σκηνὴν τῷ στρατηγῷ ταχὺ μὲν αὐτοῦ τὴν φύσιν κατέμαθε, πολλὰ καὶ μεγάλα πρὸς ζῆλον ἀρετῆς καὶ μίμησιν ἐπὶ τῶν πράξεων ἐκφέρουσαν, ταχὺ δὲ τῶν νέων πάντων ἐπρώτευεν εὐταξίᾳ καὶ ἀνδρείᾳ· καὶ τοῦ γε τείχους ἐπέβη τῶν πολεμίων πρῶτος, ὥς φησι Φάννιος, λέγων καὶ αὐτὸς τῷ Τιβερίῳ συνεπιβῆναι καὶ συμμετασχεῖν ἐκείνης τῆς ἀριστείας. πολλὴν δὲ καὶ παρὼν εὔνοιαν εἶχεν ἐν τῷ στρατοπέδῳ καὶ πόθον ἀπαλλαττόμενος αὑτοῦ κατέλιπε.", "st": "TG 4.4"}, {"sp": "N", "t": "μετὰ δὲ τὴν στρατείαν ἐκείνην αἱρεθεὶς ταμίας ἔλαχε τῶν ὑπάτων Γαΐῳ Μαγκίνῳ συστρατεύειν ἐπὶ Νομαντίνους, ἀνθρώπῳ μὲν οὐ πονηρῷ, βαρυποτμοτάτῳ δὲ Ῥωμαίων στρατηγῷ, διὸ καὶ μᾶλλον ἐν τύχαις παραλόγοις καὶ πράγμασιν ἐναντίοις τοῦ Τιβερίου διέλαμψεν οὐ μόνον τὸ συνετὸν καὶ ἀνδρεῖον, ἀλλ’, ὃ θαυμάσιον ἦν, αἰδώς τε πολλὴ καὶ τιμὴ τοῦ ἄρχοντος, ὑπὸ τῶν κακῶν οὐδ’ ἑαυτὸν, εἰ στρατηγός ἐστιν, ἐπιγινώσκοντος. ἡττηθεὶς γὰρ μάχαις μεγάλαις ἐπεχείρησε μὲν ἀναζευγνύναι νυκτὸς, ἐκλιπὼν τὸ στρατόπεδον αἰσθομένων δὲ τῶν Νομαντίνων καὶ τὸ μὲν στρατόπεδον εὐθὺς λαβόντων, τοῖς δὲ ἀνθρώποις ἐπιπεσόντων φεύγουσι καὶ τοὺς ἐσχάτους φονευόντων, τὸ δὲ πᾶν ἐγκυκλουμένων στράτευμα καὶ συνωθούντων εἰς τόπους χαλεποὺς καὶ διάφευξιν οὐκ ἔχοντας, ἀπογνοὺς τὴν ἐκ τοῦ βιάζεσθαι σωτηρίαν ὁ Μαγκῖνος ἐπεκηρυκεύετο περὶ σπονδῶν καὶ διαλύσεων πρὸς αὐτούς· οἱ δὲ πιστεύειν ἔφασαν οὐδενὶ πλὴν μόνῳ Τιβερίῳ, καὶ τοῦτον ἐκέλευον ἀποστέλλειν πρὸς αὐτούς, ἐπεπόνθεσαν δὲ τοῦτο καὶ δι’ αὐτὸν τὸν νεανίσκον ἦν γὰρ αὐτοῦ πλεῖστος λόγος ἐπὶ στρατιᾶς, καὶ μεμνημένοι τοῦ πατρὸς Τιβερίου, ὃς πολεμήσας Ἴβηρσι καὶ πολλοὺς καταστρεψάμενος εἰρήνην ἔθετο πρὸς τοὺς Νομαντίνους καὶ ταύτην ἐμπεδοῦντα τὸν δῆμον ὀρθῶς καὶ δικαίως ἀεὶ παρέσχεν. οὕτω δὴ πεμφθεὶς ὁ Τιβέριος καὶ συγγενόμενος τοῖς ἀνδράσι, καὶ τὰ μὲν πείσας, τὰ δὲ δεξάμενος ἐσπείσατο, καὶ δισμυρίους ἔσωσε περιφανῶς ’ Ῥωμαίων πολίτας, ἄνευ θεραπείας καὶ τῶν ἔξω τάξεως ἑπομένων.", "st": "TG 5.1"}, {"sp": "N", "t": "τὰ δὲ ἐν τῷ χάρακι ληφθέντα χρήματα πάντα κατέσχον οἱ Νομαντῖνοι καὶ διεπόρθησαν. ἐν δὲ τούτοις καὶ πινακίδες ἦσαν τοῦ Τιβερίου, γράμματα καὶ λόγους ἔχουσαι τῆς ταμιευτικῆς ἀρχῆς, ἃς περὶ πολλοῦ ποιούμενος ἀπολαβεῖν, ἤδη τοῦ στρατοῦ προκεχωρηκότος ἀνέστρεψε πρὸς τὴν πόλιν, ἔχων μεθ’ ἑαυτοῦ τρεῖς ἢ τέτταρας ἑταίρους. ἐκκαλέσας δὲ τῶν Νομαντίνων τοὺς ἄρχοντας ἠξίου κομίσασθαι τὰς δέλτους, ὡς μὴ παράσχοι τοῖς ἐχθροῖς διαβολήν οὐκ ἔχων ἀπολογίσασθαι περὶ τῶν ᾠκονομημένων. ἡσθέντες οὖν οἱ Νομαντῖνοι τῇ συντυχίᾳ τῆς χρείας παρεκάλουν αὐτὸν εἰσελθεῖν εἰς τὴν πόλιν· ὡς δὲ εἱστήκει βουλευόμενος, ἐγγὺς προσελθόντες ἐνεφύοντο ταῖς χερσὶ, καὶ λιπαρεῖς ἦσαν δεόμενοι μηκέτι νομίζειν αὐτοὺς πολεμίους, ἀλλ’ ὡς φίλοις χρῆσθαι καὶ πιστεύειν. ἔδοξεν οὖν τῷ Τιβερίῳ ταῦτα ποιεῖν, τῶν τε δέλτων περιεχομένῳ καὶ δεδοικότι παροξύνειν ὡς ἀπιστουμένους τοὺς Νομαντίνους. εἰσελθόντι δὲ εἰς τὴν πόλιν πρῶτον μὲν ἄριστον παρέθεσαν, καὶ πᾶσαν ἐποιήσαντο δέησιν ἐμφαγεῖν τι κοινῇ μετ’ αὐτῶν καθήμενον ἔπειτα τὰς δέλτους ἀπέδοσαν, καὶ τῶν ἄλλων ἃ βούλοιτο χρημάτων λαβεῖν ἐκέλευον. ὁ δ’ οὐδὲν ἢ τὸν λιβανωτὸν ᾧ πρὸς τὰς δημοσίας ἐχρῆτο θυσίας λαβών, ἀπῆλθεν ἀσπασάμενος καὶ φιλοφρονηθεὶς τοὺς ἄνδρας.", "st": "TG 6.1"}, {"sp": "N", "t": "ἐπεὶ δὲ εἰς Ῥώμην ἐπανῆλθεν, ἡ μὲν ὅλη πρᾶξις ὡς δεινὴ καὶ καταισχύνουσα τὴν Ῥώμην αἰτίαν εἶχε καὶ κατηγορίαν, οἱ δὲ τῶν στρατιωτῶν οἰκεῖοι καὶ φίλοι μέγα μέρος ὄντες τοῦ δήμου συνέτρεχον πρὸς τὸν Τιβέριον, τὰ μὲν αἰσχρὰ τῶν γεγονότων ἀναφέροντες εἰς τὸν ἄρχοντα, δι’ αὐτὸν δὲ σῴζεσθαι τοσούτους πολίτας φάσκοντες. οἱ μέντοι δυσχεραίνοντες τὰ πεπραγμένα μιμεῖσθαι τοὺς προγόνους ἐκέλευον καὶ γὰρ ἐκεῖνοι τοὺς ἀγαπήσαντας ὑπὸ Σαυνιτῶν ἀφεθῆναι στρατηγοὺς αὐτούς τε τοῖς πολεμίοις γυμνοὺς προσέρριψαν, καὶ τοὺς ἐφαψαμένους καὶ μετασχόντας τῶν σπονδῶν, οἷον ταμίας καὶ χιλιάρχους, ὁμοίως προὔβαλον, εἰς ἐκείνους τὴν ἐπιορκίαν καὶ τὴν διάλυσιν τῶν ὡμολογημένων τρέποντες. ἔνθα δὴ καὶ μάλιστα τὴν πρὸς τὸν Τιβέριον εὔνοιαν καὶ σπουδὴν ἐξέφηνεν ὁ δῆμος. τὸν μὲν γὰρ ὕπατον ἐψηφίσαντο γυμνὸν καὶ δεδεμένον παραδοῦναι τοῖς Νομαντίνοις, τῶν δὲ ἄλλων ἐφείσαντο πάντων διὰ Τιβέριον. δοκεῖ δὲ καὶ Σκηπίων βοηθῆσαι, μέγιστος ὢν τότε καὶ πλεῖστον δυνάμενος Ῥωμαίων ἀλλ’ οὐδὲν ἧττον ἐν αἰτίαις ἦν ὅτι τὸν Μαγκῖνον οὐ περιέσωσεν, οὐδὲ τὰς σπονδὰς ἐμπεδωθῆναι τοῖς Νομαντίνοις ἐσπούδασε δι’ ἀνδρὸς οἰκείου καὶ φίλου τοῦ Τιβερίου γενομένας. τὸ δὲ πλεῖστον ἔοικεν ἐκ φιλοτιμίας καὶ τῶν ἐπαιρόντων τὸν Τιβέριον φίλων καὶ σοφιστῶν ἐκγενέσθαι τὰ τῆς διαφορᾶς, ἀλλ’ αὕτη γε πρὸς οὐδὲν ἀνήκεστον οὐδὲ φαῦλον ἐξέπεσε, δοκεῖ δ’ ἄν μοι μηδαμῶς περιπεσεῖν ὁ Τιβέριος οἷς ἔπαθεν, εἰ παρῆν αὐτοῦ τοῖς πολιτεύμασι Σκηπίων ὁ Ἀφρικανός· νῦν δὲ ἐκείνου περὶ Νομαντίαν ὄντος ἤδη καὶ πολεμοῦντος ἥψατο τῆς περὶ τοὺς νόμους πολιτείας ἐκ τοιαύτης αἰτίας.", "st": "TG 7.1"}, {"sp": "N", "t": "Ῥωμαῖοι τῆς τῶν ἀστυγειτόνων χώρας ὅσην ἀπετέμοντο πολέμῳ, τὴν μὲν ἐπίπρασκον, τὴν δὲ ποιούμενοι δημοσίαν ἐδίδοσαν νέμεσθαι τοῖς ἀκτήμοσι καὶ ἀπόροις τῶν πολιτῶν, ἀποφορὰν οὐ πολλὴν εἰς τὸ δημόσιον τελοῦσιν. ἀρξαμένων δὲ τῶν πλουσίων ὑπερβάλλειν τὰς ἀποφορὰς καὶ τοὺς πένητας ἐξελαυνόντων, ἐγράφη νόμος οὐκ ἐῶν πλέθρα γῆς ἔχειν πλείονα τῶν πεντακοσίων, καὶ βραχὺν μὲν χρόνον ἐπέσχε τὴν πλεονεξίαν τὸ γράμμα τοῦτο, καὶ τοῖς πένησιν ἐβοήθησε κατὰ χώραν μένουσιν ἐπὶ τῶν μεμισθωμένων καὶ νεμομένοις ἣν ἕκαστος ἐξ ἀρχῆς εἶχε μοῖραν. ὕστερον δὲ τῶν γειτνιώντων πλουσίων ὑποβλήτοις προσώποις μεταφερόντων τὰς μισθώσεις εἰς ἑαυτούς, τέλος δὲ φανερῶς ἤδη δι’ ἑαυτῶν τὰ πλεῖστα κατεχόντων, ἐξωσθέντες οἱ πένητες οὔτε ταῖς στρατείαις ἔτι προθύμους παρεῖχον ἑαυτούς, ἠμέλουν τε παίδων ἀνατροφῆς, ὥστε ταχὺ τὴν Ἰταλίαν ἅπασαν ὀλιγανδρίας ἐλευθέρων αἰσθέσθαι, δεσμωτηρίων δὲ βαρβαρικῶν ἐμπεπλῆσθαι, δι’ ὧν ἐγεώργουν οἱ πλούσιοι τὰ χωρία, τοὺς πολίτας ἐξελάσαντες. ἐπεχείρησε μὲν οὖν τῇ διορθώσει Γάιος Λαίλιος ὁ Σκηπίωνος ἑταῖρος ἀντικρουσάντων δὲ τῶν δυνατῶν φοβηθεὶς τὸν θόρυβον καὶ παυσάμενος ἐπεκλήθη σοφὸς ἢ φρόνιμος·", "st": "TG 8.1"}, {"sp": "N", "t": "ἑκάτερον γὰρ ἐδόκει σημαίνειν ὁ σαπίηνς ὁ Τιβέριος δὲ δήμαρχος ἀποδειχθεὶς εὐθὺς ἐπ’ αὐτὴν ὥρμησε τὴν πρᾶξιν, ὡς μὲν οἱ πλεῖστοι λέγουσι, Διοφάνους τοῦ ῥήτορος καὶ Βλοσσίου τοῦ φιλοσόφου παρορμησάντων αὐτόν, ὧν ὁ μὲν Διοφάνης φυγὰς ἦν Μιτυληναῖος, ὁ δὲ αὐτόθεν ἐξ Ἰταλίας Κυμαῖος, Ἀντιπάτρου τοῦ Ταρσέως γεγονὼς ἐν ἄστει συνήθης καὶ τετιμημένος ὑπ’ αὐτοῦ προσφωνήσεσι γραμμάτων φιλοσόφων· ἔνιοι δὲ καὶ Κορνηλίαν συνεπαιτιῶνται τὴν μητέρα πολλάκις τοὺς υἱοὺς ὀνειδίζουσαν ὅτι Ῥωμαῖοι Σκηπίωνος αὐτὴν ἔτι πενθεράν, οὔπω δὲ μητέρα Γράγχων προσαγορεύουσιν. ἄλλοι δὲ Σπόριόν τινα Ποστούμιον αἴτιον γενέσθαι λέγουσιν, ἡλικιώτην τοῦ Τιβερίου καὶ πρὸς δόξαν ἐφάμιλλον αὐτῷ περὶ τὰς συνηγορίας, ὃν, ὡς ἐπανῆλθεν ἀπὸ τῆς στρατιᾶς, εὑρὼν πολὺ τῇ δόξῃ καὶ τῇ δυνάμει παρηλλαχότα καὶ θαυμαζόμενον, ἠθέλησεν, ὡς ἔοικεν, ὑπερβαλέσθαι πολιτεύματος παραβόλου καὶ μεγάλην προσδοκίαν ἔχοντος ἁψάμενος. ὁ δ’ ἀδελφὸς αὐτοῦ Γάιος ἔν τινι βιβλίῳ γέγραφεν εἰς Νομαντίαν πορευόμενον διὰ τῆς Τυρρηνίας τὸν Τιβέριον, καὶ τὴν ἐρημίαν τῆς χώρας ὁρῶντα καὶ τοὺς γεωργοῦντας ἢ νέμοντας οἰκέτας ἐπεισάκτους καὶ βαρβάρους, τότε πρῶτον ἐπὶ νοῦν βαλέσθαι τὴν μυρίων κακῶν ἄρξασαν αὐτοῖς πολιτείαν. τὴν δὲ πλείστην αὐτὸς ὁ δῆμος ὁρμὴν καὶ φιλοτιμίαν ἐξῆψε, προκαλούμενος διὰ γραμμάτων αὐτὸν ἐν στοαῖς καὶ τοίχοις καὶ μνήμασι καταγραφομένων ἀναλαβεῖν τοῖς πένησι τὴν δημοσίαν χώραν.", "st": "TG 8.5"}, {"sp": "N", "t": "οὐ μὴν ἐφ’ αὑτοῦ γε συνέθηκε τὸν νόμον, τοῖς δὲ πρωτεύουσιν ἀρετῇ καὶ δόξῃ τῶν πολιτῶν συμβούλοις χρησάμενος, ὧν καὶ Κράσσος ἦν ὁ ἀρχιερεὺς καὶ Μούκιος Σκαιβόλας ὁ νομοδείκτης ὑπατεύων τότε καὶ Κλαύδιος Ἄππιος ὁ κηδεστὴς τοῦ Τιβερίου. καὶ δοκεῖ νόμος εἰς ἀδικίαν καὶ πλεονεξίαν τοσαύτην μηδέποτε πραότερος γραφῆναι καὶ μαλακώτερος. οὓς γὰρ ἔδει δίκην τῆς ἀπειθείας δοῦναι καὶ μετὰ ζημίας ἦν παρὰ τοὺς νόμους ἐκαρποῦντο χώραν ἀφεῖναι, τούτους ἐκέλευσε τιμὴν προσλαμβάνοντας ἐκβαίνειν ὧν ἀδίκως ἐκέκτηντο, καὶ παραδέχεσθαι τοὺς βοηθείας δεομένους τῶν πολιτῶν. ἀλλὰ καίπερ οὕτω τῆς ἐπανορθώσεως οὔσης εὐγνώμονος, ὁ μὲν δῆμος ἠγάπα, παρεὶς τὰ γεγενημένα, παύσασθαι τὸ λοιπὸν ἀδικούμενος, οἱ δὲ πλούσιοι καὶ κτηματικοὶ πλεονεξίᾳ μὲν τὸν νόμον, ὀργῇ δὲ καὶ φιλονεικίᾳ τὸν νομοθέτην δι’ ἔχθους ἔχοντες, ἐπεχείρουν ἀποτρέπειν τὸν δῆμον, ὡς γῆς ἀναδασμὸν ἐπὶ συγχύσει τῆς πολιτείας εἰσάγοντος τοῦ Τιβερίου καὶ πάντα πράγματα κινοῦντος.", "st": "TG 9.1"}, {"sp": "N", "t": "ἀλλ’ οὐδὲν ἐπέραινον ὁ γὰρ Τιβέριος πρὸς καλὴν ὑπόθεσιν καὶ δικαίαν ἀγωνιζόμενος λόγῳ καὶ φαυλότερα κοσμῆσαι δυναμένῳ πράγματα δεινὸς ἦν καὶ ἄμαχος, ὁπότε τοῦ δήμου τῷ βήματι περικεχυμένου καταστὰς λέγοι περὶ τῶν πενήτων, ὡς τὰ μὲν θηρία τὰ τὴν Ἰταλίαν νεμόμενα καὶ φωλεὸν ἔχει καὶ κοιταῖόν ἐστιν αὐτῶν ἑκάστῳ καὶ καταδύσεις, τοῖς δὲ ὑπὲρ τῆς Ἰταλίας μαχομένοις καὶ ἀποθνῄσκουσιν ἀέρος καὶ φωτός, ἄλλου δὲ οὐδενὸς μέτεστιν, ἀλλ’ ἄοικοι καὶ ἀνίδρυτοι μετὰ τέκνων πλανῶνται καὶ γυναικῶν, οἱ δὲ αὐτοκράτορες ψεύδονται τοὺς στρατιώτας ἐν ταῖς μάχαις παρακαλοῦντες ὑπὲρ τάφων καὶ ἱερῶν ἀμύνεσθαι τοὺς πολεμίους· οὐδενὶ γάρ ἐστιν οὐ βωμὸς πατρῷος, οὐκ ἠρίον προγονικὸν τῶν τοσούτων ’ Ῥωμαίων, ἀλλ’ ὑπὲρ ἀλλοτρίας τρυφῆς καὶ πλούτου πολεμοῦσι καὶ ἀποθνῄσκουσι, κύριοι τῆς οἰκουμένης εἶναι λεγόμενοι, μίαν δὲ βῶλον ἰδίαν οὐκ ἔχοντες.", "st": "TG 9.4"}, {"sp": "N", "t": "τούτους ἀπὸ φρονήματος μεγάλου καὶ πάθους ἀληθινοῦ τοὺς λόγους κατιόντας εἰς τὸν δῆμον ἐνθουσιῶντα καὶ συνεξανιστάμενον οὐδεὶς ὑφίστατο τῶν ἐναντίων, ἐάσαντες οὖν τὸ ἀντιλέγειν ἐπὶ Μᾶρκον Ὀκτάβιον τρέπονται τῶν δημάρχων ἕνα, νεανίαν ἐμβριθῆ τὸ ἦθος καὶ κόσμιον, ἑταῖρον δὲ τοῦ Τιβερίου καὶ συνήθη, διὸ τὸ μὲν πρῶτον αἰδούμενος ἐκεῖνον ἀνεδύετο· πολλῶν δὲ καὶ δυνατῶν δεομένων καὶ λιπαρούντων ὥσπερ ἐκβιασθεὶς ἀντικαθίστατο τῷ Τιβερίῳ καὶ διεκρούετο τὸν νόμον. ἔστι δὲ τοῦ κωλύοντος ἐν τοῖς δημάρχοις τὸ κράτος· οὐδὲν γὰρ οἱ πολλοὶ κελεύοντες περαίνουσιν ἑνὸς ἐνισταμένου. πρὸς τοῦτο παροξυνθεὶς ὁ Τιβέριος τὸν μὲν φιλάνθρωπον ἐπανείλετο νόμον, τὸν δὲ ἡδίω τε τοῖς πολλοῖς καὶ σφοδρότερον ἐπὶ τοὺς ἀδικοῦντας εἰσέφερεν ἤδη, κελεύων ἐξίστασθαι τῆς χώρας ἣν ἐκέκτηντο παρὰ τοὺς προτέρους νόμους.", "st": "TG 10.1"}, {"sp": "N", "t": "ἦσαν οὖν ὁμοῦ τι καθ’ ἑκάστην ἡμέραν ἀγῶνες αὐτῷ πρὸς τὸν Ὀκτάβιον ἐπὶ τοῦ βήματος, ἐν οἷς, καίπερ ἐξ ἄκρας σπουδῆς καὶ φιλονεικίας ἀντερείδοντες, οὐδὲν εἰπεῖν λέγονται περὶ ἀλλήλων φαῦλον, οὐδὲ ῥῆμα προπεσεῖν θατέρου πρὸς τὸν ἕτερον δι’ ὀργὴν ἀνεπιτήδειον. οὐ γὰρ μόνον ἐν βακχεύμασιν, ὡς ἔοικεν, ἀλλὰ καὶ ἐν φιλοτιμίαις καὶ ὀργαῖς τὸ πεφυκέναι καλῶς καὶ πεπαιδεῦσθαι σωφρόνως ἐφίστησι καὶ κατακοσμεῖ τὴν διάνοιαν. ἐπεὶ δὲ ἑώρα τὸν Ὀκτάβιον ἐνεχόμενον τῷ νόμῳ καὶ κατέχοντα τῆς δημοσίας χώρας συχνὴν ὁ Τιβέριος, ἐδεῖτο παρεῖναι τὴν φιλονεικίαν, ὑφιστάμενος αὐτῷ τὴν τιμὴν ἀποδώσειν ἐκ τῶν ἰδίων, καίπερ οὐ λαμπρῶν ὄντων, οὐκ ἀνασχομένου δὲ τοῦ Ὀκταβίου, διαγράμματι τὰς ἄλλας ἀρχὰς ἁπάσας ἐκώλυσε χρηματίζειν, ἄχρι ἂν ἡ περὶ τοῦ νόμου διενεχθῇ ψῆφος· τῷ δὲ τοῦ Κρόνου ναῷ σφραγῖδας ἰδίας ἐπέβαλεν, ὅπως οἱ ταμίαι μηδὲν ἐξ αὐτοῦ λαμβάνοιεν μηδ’ εἰσφέροιεν, καὶ τοῖς ἀπειθήσασι τῶν στρατηγῶν ζημίαν ἐπεκήρυξεν, ὥστε πάντας ὑποδείσαντας ἀφεῖναι τὴν ἑκάστῳ προσήκουσαν οἰκονομίαν. ἐντεῦθεν οἱ κτηματικοὶ τὰς μὲν ἐσθῆτας μετέβαλον καὶ περιῄεσαν οἰκτροὶ καὶ ταπεινοὶ κατὰ τὴν ἀγοράν, ἐπεβούλευον δὲ τῷ Τιβερίῳ κρύφα καὶ συνίστασαν ἐπ’ αὐτὸν τοὺς ἀναιρήσοντας, ὥστε κἀκεῖνον οὐδενὸς ἀγνοοῦντος ὑποζώννυσθαι ξιφίδιον λῃστρικόν, ὃ δόλωνα καλοῦσιν.", "st": "TG 10.4"}, {"sp": "N", "t": "ἐνστάσης δὲ τῆς ἡμέρας καὶ τὸν δῆμον αὐτοῦ καλοῦντος ἐπὶ τὴν ψῆφον, ἡρπάσθησαν ὑπὸ τῶν πλουσίων αἱ ὑδρίαι, καὶ τὰ γινόμενα πολλὴν εἶχε σύγχυσιν. οὐ μὴν ἀλλὰ τῶν περὶ Τιβέριον πλήθει βιάσασθαι δυναμένων καὶ συστρεφομένων ἐπὶ τοῦτο, Μάλλιος καὶ Φούλβιος, ἄνδρες ὑπατικοὶ, προσπεσόντες τῷ Τιβερίῳ καὶ χειρῶν ἁπτόμενοι καὶ δακρύοντες ἐδέοντο παύσασθαι. τοῦ δὲ καὶ τὸ μέλλον ὅσον οὔπω δεινὸν ἤδη συμφρονοῦντος, καὶ δι’ αἰδῶ τῶν ἀνδρῶν πυθομένου τί κελεύουσι πράττειν αὐτόν, οὐκ ἔφασαν ἀξιόχρεῳ εἶναι πρὸς τηλικαύτην συμβουλίαν, ἐπιτρέψαι δὲ τῇ βουλῇ κελεύοντες καὶ δεόμενοι συνέπεισαν.", "st": "TG 11.1"}, {"sp": "N", "t": "ὡς δὲ οὐδὲν ἐπέραινεν ἡ βουλὴ συνελθοῦσα διὰ τοὺς πλουσίους ἰσχύοντας ἐν αὐτῇ, τρέπεται πρὸς ἔργον οὐ νόμιμον οὐδὲ ἐπιεικές, ἀφελέσθαι τῆς ἀρχῆς τὸν Ὀκτάβιον, ἀμηχανῶν ἄλλως ἐπαγαγεῖν τῷ νόμῳ τὴν ψῆφον. καὶ πρῶτον μὲν ἐδεῖτο φανερῶς αὐτοῦ, λόγους τε προσφέρων φιλανθρώπους καὶ χειρῶν ἁπτόμενος, ἐνδοῦναι καὶ χαρίσασθαι τῷ δήμῳ δίκαια μὲν ἀξιοῦντι, μικρὰ δὲ ἀντὶ μεγάλων πόνων καὶ κινδύνων ληψομένῳ. διωθουμένου δὲ τοῦ Ὀκταβίου τὴν ἔντευξιν ὑπειπὼν ὁ Τιβέριος ὡς οὐκ ἔστιν ἄρχοντας ἀμφοτέρους καὶ περὶ πραγμάτων μεγάλων ἀπ’ ἴσης ἐξουσίας διαφερομένους ἄνευ πολέμου διεξελθεῖν τὸν χρόνον, ἓν ἴαμα τούτου μόνον ὁρᾶν ἔφη τὸ παύσασθαι τῆς ἀρχῆς τὸν ἕτερον. καὶ περὶ αὐτοῦ γε προτέρου τὸν Ὀκτάβιον ἐκέλευσε τῷ δήμῳ ψῆφον ἀναδοῦναι καταβήσεσθαι γὰρ εὐθὺς ἰδιώτης γενόμενος, ἂν τοῦτο δόξῃ τοῖς πολίταις. τοῦ δὲ Ὀκταβίου μὴ θέλοντος αὐτὸς ἔφη περὶ ἐκείνου ψῆφον ἀναδώσειν, ἐὰν μὴ μεταγνῷ βουλευσάμενος.", "st": "TG 11.3"}, {"sp": "N", "t": "καὶ τότε μὲν ἐπὶ τούτοις διέλυσε τὴν ἐκκλησίαν τῇ δ’ ὑστεραίᾳ τοῦ δήμου συνελθόντος ἀναβὰς ἐπὶ τὸ βῆμα πάλιν ἐπειρᾶτο πείθειν τὸν Ὀκτάβιον ὡς δὲ ἦν ἀμετάπειστος, εἰσήνεγκε νόμον ἀφαιρούμενον αὐτοῦ τὴν δημαρχίαν, καὶ τοὺς πολίτας εὐθὺς ἐκάλει τὴν ψῆφον ἐπιφέροντας. οὐσῶν δὲ πέντε καὶ τριάκοντα φυλῶν, ὡς αἱ δεκαεπτὰ τὴν ψῆφον ἐπενηνόχεισαν καὶ μιᾶς ἔτι προσγενομένης ἔδει τὸν Ὀκτάβιον ἰδιώτην γενέσθαι, κελεύσας ἐπισχεῖν αὖθις ἐδεῖτο τοῦ Ὀκταβίου καὶ περιέβαλεν αὐτὸν ἐν ὄψει τοῦ δήμου καὶ κατησπάζετο, λιπαρῶν καὶ δεόμενος μήθ’ ἑαυτὸν ἄτιμον περιιδεῖν γενόμενον μήτ’ ἐκείνῳ βαρέος οὕτω καὶ σκυθρωποῦ πολιτεύματος αἰτίαν προσάψαι.", "st": "TG 12.1"}, {"sp": "N", "t": "τούτων τῶν δεήσεων οὐ παντελῶς ἄτεγκτον οὐδ’ ἀτενῆ λέγουσιν ἀκροᾶσθαι τὸν Ὀκτάβιον, ἀλλὰ καὶ δακρύων ὑποπίμπλασθαι τὰ ὄμματα καὶ σιωπᾶν ἐπὶ πολὺν χρόνον, ὡς μέντοι πρὸς τοὺς πλουσίους καὶ τοὺς κτηματικοὺς συνεστῶτας ἀπέβλεψεν, αἰδεσθεὶς δοκεῖ καὶ φοβηθεὶς τὴν παρ’ ἐκείνοις ἀδοξίαν ὑποστῆναι πᾶν δεινὸν οὐκ ἀγεννῶς καὶ κελεῦσαι πράττειν ὃ βούλεται τὸν Τιβέριον. οὕτω δὴ τοῦ νόμου κυρωθέντος ὁ μὲν Τιβέριος τῶν ἀπελευθέρων τινὶ προσέταξεν ἀπὸ τοῦ βήματος ἑλκύσαι τὸν Ὀκτάβιον· ἐχρῆτο δὲ ὑπηρέταις ἀπελευθέροις ἰδίοις, καὶ τοῦτο τὴν ὄψιν οἰκτροτέραν τοῦ Ὀκταβίου παρέσχεν ἑλκομένου πρὸς ὕβριν. ὁ δὲ δῆμος ἐφώρμησεν αὐτῷ, καὶ τῶν πλουσίων συνδραμόντων καὶ διασχόντων τὰς χεῖρας, ὁ μὲν Ὀκτάβιος ἐσώθη μόλις ἐξαρπαγεὶς καὶ διαφυγὼν τὸν ὄχλον, οἰκέτην δὲ αὐτοῦ πιστὸν ἔμπροσθεν ἑστῶτα καὶ προτεταγμένον ἐξετύφλωσαν, ἄκοντος τὸν Τιβερίου, καὶ πρὸς τὸν θόρυβον, ὡς ᾔσθετο τὰ γινόμενα, πολλῇ σπουδῇ καταδραμόντος.", "st": "TG 12.3"}, {"sp": "N", "t": "ἐκ τούτου κυροῦται μὲν ὁ περὶ τῆς χώρας νόμος, αἱροῦνται δὲ τρεῖς ἄνδρες ἐπὶ τὴν διάκρισιν καὶ διανομήν, αὐτὸς Τιβέριος καὶ Κλαύδιος Ἄππιος ὁ πενθερὸς καὶ Γάιος Γράγχος ὁ ἀδελφός, οὐ παρὼν οὗτος, ἀλλὰ ὑπὸ Σκηπίωνι πρὸς Νομαντίαν στρατευόμενος. ταῦτα τοῦ Τιβερίου διαπραξαμένου καθ’ ἡσυχίαν μηδενὸς ἐνισταμένου, καὶ πρὸς τούτοις δήμαρχον ἀντικαταστήσαντος οὐδένα τῶν ἐπιφανῶν, ἀλλὰ Μούκιόν τινα, πελάτην αὐτοῦ, πρὸς πάντα δυσχεραίνοντες οἱ δυνατοὶ καὶ φοβούμενοι τοῦ Τιβερίου τὴν αὔξησιν ἐν τῇ βουλῇ προεπηλάκιζον αὐτόν, αἰτουμένῳ μὲν, ὡς ἔθος ἐστὶν, ἐκ δημοσίου σκηνήν, ὅπως ἔχοι διανέμων τὴν χώραν, οὐ δόντες, ἑτέρων ἐπ’ ἐλάττοσι χρείαις πολλάκις λαβόντων, ἀνάλωμα δὲ εἰς ἑκάστην ἡμέραν ἐννέα ὀβολοὺς τάξαντες, εἰσηγουμένου ταῦτα Ποπλίου Νασικᾶ καὶ δεδωκότος ἑαυτὸν εἰς τὴν πρὸς ἐκεῖνον ἔχθραν ἀφειδῶς· πλείστην γὰρ ἐκέκτητο γῆν δημοσίαν, καὶ χαλεπῶς ἔφερεν ἐκβαίνειν αὐτῆς ἀναγκαζόμενος.", "st": "TG 13.1"}, {"sp": "N", "t": "ὁ δὲ δῆμος ἔτι μᾶλλον ἐξεκᾴετο καὶ φίλου τινὸς τῷ Τιβερίῳ τελευτήσαντος αἰφνιδίως καὶ σημείων τῷ νεκρῷ μοχθηρῶν ἐπιδραμόντων, βοῶντες ὑπὸ φαρμάκων ἀνῃρῆσθαι τὸν ἄνθρωπον ἐπὶ τὴν ἐκφορὰν συνέδραμον καὶ τὸ λέχος ἤραντο καὶ θαπτομένῳ παρέστησαν, οὐ φαύλως ὑπονοῆσαι τὴν φαρμακείαν δόξαντες. ἐρράγη γὰρ ὁ νεκρὸς καὶ διεφθορότων ὑγρῶν πλῆθος ἐξέβλυσεν, ὥστε ἀποσβέσαι τὴν φλόγα· καὶ φερόντων ἄλλην αὖθις οὐκ ἐκᾴετο πρὶν εἰς ἕτερον τόπον μετακομισθῆναι, καὶ πολλὰ πραγματευσαμένων μόλις ἥψατο τὸ πῦρ αὐτοῦ, πρὸς ταῦτα τοὺς πολλοὺς ἔτι μᾶλλον ὁ Τιβέριος παροξύνων μετέβαλε τὴν ἐσθῆτα, καὶ τοὺς παῖδας προαγαγὼν ἐδεῖτο τοῦ δήμου τούτων κήδεσθαι καὶ τῆς μητρός, ὡς αὐτὸς ἀπεγνωκὼς ἑαυτόν.", "st": "TG 13.4"}, {"sp": "N", "t": "ἐπεὶ δὲ τοῦ Φιλομήτορος Ἀττάλου τελευτήσαντος Εὔδημος ὁ Περγαμηνὸς ἀνήνεγκε διαθήκην ἐν ᾗ κληρονόμος ἐγέγραπτο τοῦ βασιλέως ὁ Ῥωμαίων δῆμος, εὐθὺς ὁ Τιβέριος δημαγωγῶν εἰσήνεγκε νόμον ὅπως τὰ βασιλικὰ χρήματα κομισθέντα τοῖς τὴν χώραν διαλαγχάνουσι τῶν πολιτῶν ὑπάρχοι πρὸς κατασκευὴν καὶ γεωργίας ἀφορμήν. περὶ δὲ τῶν πόλεων, ὅσαι τῆς Ἀττάλου βασιλείας ἦσαν, οὐδὲν ἔφη τῇ συγκλήτῳ βουλεύεσθαι προσήκειν, ἀλλὰ τῷ δήμῳ γνώμην αὐτὸς προθήσειν. ἐκ τούτου μάλιστα προσέκρουσε τῇ βουλῇ· καὶ Πομπήιος μὲν ἀναστὰς ἔφη γειτνιᾶν τῷ Τιβερίῳ καὶ διὰ τοῦτο γινώσκειν Εὔδημον αὐτῷ τόν Περγαμηνὸν τῶν βασιλικῶν διάδημα δεδωκότα καὶ πορφύραν, ὡς μέλλοντι βασιλεύειν ἐν Ῥώμῃ, Κόιντος δὲ Μέτελλος ὠνείδισε τόν Τιβέριον ὅτι τοῦ μὲν πατρὸς αὐτοῦ τιμητεύοντος, ὁσάκις ἀναλύοι μετὰ δεῖπνον οἴκαδε, τὰ φῶτα κατεσβέννυσαν οἱ πολῖται, φοβούμενοι μὴ πορρωτέρω τοῦ μετρίου δόξωσιν ἐν συνουσίαις εἶναι καὶ πότοις, τούτῳ δὲ προφαίνουσι νυκτὸς οἱ θρασύτατοι καὶ ἀπορώτατοι τῶν δημοτῶν· Τίτος δ’ Ἄννιος, οὐκ ἐπιεικὴς μὲν οὐδὲ σώφρων ἄνθρωπος, ἐν δὲ λόγοις πρὸς τὰς ἐρωτήσεις καὶ τὰς ἀποκρίσεις ἄμαχος εἶναι δοκῶν, εἰς ὁρισμόν τινα προὐκαλεῖτο τόν Τιβέριον, ἦ μὴν ἱερὸν ὄντα καὶ ἄσυλον ἐκ τῶν νόμων ἠτιμωκέναι τόν συνάρχοντα. θορυβούντων δὲ πολλῶν ἐκπηδήσας ὁ Τιβέριος τόν τε δῆμον συνεκάλει καὶ τόν Ἄννιον ἀχθῆναι κελεύσας ἐβούλετο κατηγορεῖν. ὁ δὲ καὶ τῷ λόγῳ καὶ τῇ δόξῃ πολὺ λειπόμενος εἰς τὴν ἑαυτοῦ δεινότητα κατεδύετο, καὶ παρεκάλει μικρὰ πρὸ τῶν λόγων ἀποκρίνασθαι τόν Τιβέριον. συγχωροῦντος δὲ ἐρωτᾶν ἐκείνου καὶ σιωπῆς γενομένης εἶπεν ὁ Ἄννιος, ἂν σύ μὲν ἀτιμοῦν με βούλῃ καὶ προπηλακίζειν, ἐγὼ δέ τινα τῶν σῶν ἐπικαλέσωμαι συναρχόντων, ὁ δὲ ἀναβῇ βοηθήσων, σὺ δὲ ὀργισθῇς, ἆρά γε αὐτοῦ τὴν ἀρχὴν ἀφαιρήσῃ; πρὸς ταύτην λέγεται τὴν ἐρώτησιν οὕτω διαπορηθῆναι τόν Τιβέριον ὥστε πάντων ὄντα καὶ τὸ λέγειν ἑτοιμότατον καὶ τὸ θαρρεῖν ἰταμώτατον ἀποσιωπῆσαι.", "st": "TG 14.1"}, {"sp": "N", "t": "τότε μὲν οὖν διέλυσε τὴν ἐκκλησίαν αἰσθανόμενος δὲ τῶν πολιτευμάτων τὸ περὶ τὸν Ὀκτάβιον οὐ τοῖς δυνατοῖς μόνον, ἀλλὰ καὶ τοῖς πολλοῖς ἐκπαθέστερον μέγα γάρ τι καὶ καλὸν ἐδόκει τὸ τῶν δημάρχων ἀξίωμα μέχρι τῆς ἡμέρας ἐκείνης διατετηρημένον ἀνῃρῆσθαι καὶ καθυβρίσθαι, λόγον ἐν τῷ δήμῳ διεξῆλθεν, οὗ μικρὰ παραθέσθαι τῶν ἐπιχειρημάτων οὐκ ἄτοπον ἦν, ὥστε ὑπονοηθῆναι τὴν πιθανότητα καὶ πυκνότητα τοῦ ἀνδρός. ἔφη γὰρ ἱερὸν τὸν δήμαρχον εἶναι καὶ ἄσυλον, ὅτι τῷ δήμῳ καθωσίωται καὶ τοῦ δήμου προέστηκεν. ἂν οὖν μεταβαλόμενος τὸν δῆμον ἀδικῇ καὶ τὴν ἰσχὺν κολούῃ καὶ παραιρῆται τὴν ψῆφον, αὐτὸς ἑαυτὸν ἀπεστέρηκε τῆς τιμῆς ἐφ’ οἷς ἔλαβεν οὐ ποιῶν· ἐπεὶ καὶ τὸ Καπετώλιον κατασκάπτοντα καὶ τὸ νεώριον ἐμπιπράντα δήμαρχον ἐὰν δεήσει, καὶ ταῦτα μὲν ποιῶν δήμαρχός ἐστι πονηρός·", "st": "TG 15.1"}, {"sp": "N", "t": "ἐὰν δὲ καταλύῃ τὸν δῆμον, οὐ δήμαρχός ἐστι. πῶς οὖν οὐ δεινόν εἰ τὸν μὲν ὕπατον ὁ δήμαρχός ἄξει, τὸν δὲ δήμαρχον οὐκ ἀφαιρήσεται τὴν ἐξουσίαν ὁ δῆμος ὅταν αὐτῇ κατὰ τοῦ δεδωκότος χρῆται; καὶ γὰρ ὕπατον καὶ δήμαρχον ὁμοίως ὁ δῆμος αἱρεῖται. καὶ μὴν ἥ γε βασιλεία πρὸς τῷ πᾶσαν ἀρχήν ἔχειν ἐν ἑαυτῇ συλλαβοῦσα καὶ ταῖς μεγίσταις ἱερουργίαις καθωσίωται πρὸς τὸ θεῖον ἀλλὰ Ταρκύνιον ἐξέβαλεν ἡ πόλις ἀδικοῦντα, καὶ δι’ ἑνὸς ἀνδρὸς ὕβριν ἡ πάτριος ἀρχὴ καὶ κτίσασα τὴν Ῥώμην κατελύθη. τί δὲ οὕτως ἅγιον ἐν Ῥώμῃ καὶ σεμνόν ὡς αἱ περιέπουσαι παρθένοι καὶ φυλάττουσαι τὸ ἄφθιτον πῦρ;", "st": "TG 15.4"}, {"sp": "N", "t": "ἀλλ’ εἴ τις ἂν ἁμάρτῃ αὑτῶν, ζῶσα κατορύσσεται· τὸ γὰρ ἄσυλον οὐ φυλάττουσιν ἀσεβοῦσαι εἰς τοὺς θεούς, ὃ διὰ τοὺς θεοὺς ἔχουσιν. οὔκουν οὐδὲ δήμαρχός ἀδικῶν τὸν δῆμον ἔχειν τὴν διὰ τὸν δῆμον ἀσυλίαν δίκαιός ἐστιν ᾗ γὰρ ἰσχύει δυνάμει, ταύτην ἀναιρεῖ, καὶ μὴν εἰ δικαίως ἔλαβε τὴν δημαρχίαν, τῶν πλείστων φυλῶν ψηφισαμένων, πῶς οὐχὶ κἂν ἀφαιρεθείη δικαιότερον πασῶν ἀποψηφισαμένων; ἱερὸν δὲ καὶ ἄσυλον οὐδὲν οὕτως ἐστίν ὡς τὰ τῶν θεῶν ἀναθήματα· χρῆσθαι δὲ τούτοις καὶ κινεῖν καὶ μεταφέρειν ὡς βούλεται, τὸν δῆμον οὐδεὶς κεκώλυκεν. ἐξῆν οὖν αὐτῷ καὶ τὴν δημαρχίαν ὡς ἀνάθημα μετενεγκεῖν εἰς ἕτερον, ὅτι δὲ οὐκ ἄσυλον οὐδὲ ἀναφαίρετον ἡ ἀρχή, δῆλόν ἐστι τῷ πολλάκις ἔχοντας ἀρχήν τινας ἐξόμνυσθαι καὶ παραιτεῖσθαι δι’ αὑτῶν.", "st": "TG 15.5"}, {"sp": "N", "t": "τοιαῦτα μὲν ἦν τὰ κεφάλαια τῆς τοῦ Τιβερίου δικαιολογίας, Ἐπεὶ δὲ συνορῶντες οἱ φίλοι τὰς ἀπειλὰς καὶ τὴν σύστασιν ᾤοντο δεῖν ἑτέρας περιέχεσθαι δημαρχίας εἰς τὸ μέλλον αὖθις ἄλλοις νόμοις ἀνελάμβανε τὸ πλῆθος, τοῦ τε χρόνου τῶν στρατειῶν ἀφαιρῶν, καὶ διδοὺς ἐπικαλεῖσθαι τὸν δῆμον ἀπὸ τῶν δικαστῶν, καὶ τοῖς κρίνουσι τότε, συγκλητικοῖς οὖσι, καταμιγνὺς ἐκ τῶν ἱππέων τὸν ἴσον ἀριθμόν, καὶ πάντα τρόπον ἤδη τῆς βουλῆς τὴν ἰσχὺν κολούων πρὸς ὀργὴν καὶ φιλονεικίαν μᾶλλον ἢ τὸν τοῦ δικαίου καὶ συμφέροντος λογισμόν. ἐπεὶ δὲ τῆς ψήφου φερομένης ᾔσθοντο τοὺς ἐναντίους κρατοῦντας οὐ γὰρ παρῆν ἅπας ὁ δῆμος, πρῶτον μὲν εἰς βλασφημίας τραπόμενοι τῶν συναρχόντων εἷλκον τὸν χρόνον ἔπειτα τὴν ἐκκλησίαν ἀφῆκαν, εἰς τὴν ὑστεραίαν ἀπαντᾶν κελεύσαντες. καὶ πρῶτον μὲν εἰς τὴν ἀγορὰν καταβὰς ὁ Τιβέριος ἱκέτευε τοὺς ἀνθρώπους ταπεινὸς καὶ δεδακρυμένος, ἔπειτα δεδοικέναι φήσας μὴ νυκτὸς ἐκκόψωσι τὴν οἰκίαν οἱ ἐχθροὶ καὶ διαφθείρωσιν αὐτόν, οὕτω τοὺς ἀνθρώπους διέθηκεν ὥστε περὶ τὴν οἰκίαν αὐτοῦ παμπόλλους τινὰς αὐλίσασθαι καὶ διανυκτερεῦσαι παραφυλάττοντας.", "st": "TG 16.1"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ παρῆν ὁ τὰς ὄρνιθας αἷς διαμαντεύονται κομίζων, καὶ προέβαλλε τροφὴν αὐταῖς. αἱ δ’ οὐ προῆλθον, εἰ μὴ μία μόνη, διασείσαντος εὖ μάλα τοῦ ἀνθρώπου τὸ ἀγγεῖον· οὐδὲ αὕτη δὲ τῆς τροφῆς ἔθιγεν, ἀλλ’ ἐπάρασα τὴν ἀριστερὰν πτέρυγα καὶ παρατείνασα τὸ σκέλος πάλιν εἰς τὸ ἀγγεῖον κατέφυγε, τοῦτο καὶ τοῦ προτέρου σημείου τὸν Τιβέριον ἀνέμνησεν. ἦν γὰρ αὐτῷ κράνος ᾧ πρὸς τὰς μάχας ἐχρῆτο, κεκοσμημένον ἐκπρεπῶς καὶ διάσημον εἰς τοῦτο καταδύντες ὄφεις ἔλαθον ἐντεκόντες ὠά, καὶ ταῦτα ἐξεγλύψαντο. διὸ καὶ μᾶλλον ὁ Τιβέριος τοῖς περὶ τὰς ὄρνιθας ἐταράττετο. προῄει δὲ ὅμως, ἄνω τὸν δῆμον ἠθροῖσθαι περὶ τὸ Καπετώλιον πυνθανόμενος· καὶ πρὶν ἐξελθεῖν προσέπταισε πρὸς τὸν οὐδόν, σφοδρᾶς οὕτω πληγῆς γενομένης ὥστε τὸν μὲν ὄνυχα τοῦ μεγάλου δακτύλου ῥαγῆναι, τὸ δὲ αἷμα διὰ τοῦ ὑποδήματος ἔξω φέρεσθαι. μικρὸν δὲ αὐτοῦ προελθόντος ὤφθησαν ὑπὲρ κεράμου μαχόμενοι κόρακες ἐν ἀριστερᾷ· καὶ πολλῶν, ὡς εἰκὸς, ἀνθρώπων παρερχομένων, κατ’ αὐτὸν τὸν Τιβέριον λίθος ἀπωσθεὶς ὑπὸ θατέρου τῶν κοράκων ἔπεσε παρὰ τὸν πόδα. τοῦτο καὶ τοὺς θρασυτάτους τῶν περὶ αὐτὸν ἐπέστησεν· ἀλλὰ Βλόσσιος ὁ Κυμαῖος παρὼν αἰσχύνην ἔφη καὶ κατήφειαν ἂν εἶναι πολλήν εἰ Τιβέριος, Γράγχου μὲν υἱός, Ἀφρικανοῦ δὲ Σκηπίωνος θυγατριδοῦς, προστάτης δὲ τοῦ Ῥωμαίων δήμου, κόρακα δείσας οὐχ ὑπακούσειε τοῖς πολίταις καλοῦσι· τοῦτο μέντοι τὸ αἰσχρὸν οὐκ ἐν γέλωτι θήσεσθαι τοὺς ἐχθρούς, ἀλλ’ ὡς τυραννοῦντος καὶ τρυφῶντος ἤδη καταβοήσεσθαι πρὸς τὸν δῆμον. ἅμα δὲ καὶ προσέθεον πολλοὶ τῷ Τιβερίῳ παρὰ τῶν ἐν Καπετωλίῳ φίλων, ἐπείγεσθαι κελεύοντες, ὡς τῶν ἐκεῖ καλῶς ἐχόντων, καὶ τά γε πρῶτα λαμπρῶς ἀπήντα τῷ Τιβερίῳ, φανέντι μὲν εὐθὺς ἀραμένων βοὴν φίλιον, ἀναβαίνοντα δὲ προθύμως δεχομένων καὶ περὶ αὐτὸν, ὡς μηδεὶς πελάσειεν ἀγνὼς, παραταττομένων.", "st": "TG 17.1"}, {"sp": "N", "t": "ἀρξαμένου δὲ πάλιν τοῦ Μουκίου τὰς φυλὰς ἀναγορεύειν, οὐδὲν ἐπεραίνετο τῶν εἰωθότων διὰ τὸν ἀπὸ τῶν ἐσχάτων θόρυβον, ὠθουμένων καὶ ὠθούντων τοὺς ἐναντίους εἰσβιαζομένους καὶ ἀναμιγνυμένους. ἐν δὲ τούτῳ Φούλβιος Φλάκκος ἀπὸ βουλῆς ἀνὴρ εἰς ἐμφανὲς καταστάς, ὡς οὐκ ἦν φθεγγόμενον ἐφικέσθαι διεσήμηνε τῇ χειρὶ φράσαι τι βουλόμενος αὑτὸν ἰδίᾳ τῷ Τιβερίῳ. καὶ κελεύσαντος ἐκείνου διασχεῖν τὸ πλῆθος, ἀναβὰς μόλις καὶ προσελθὼν ἀπήγγειλεν ὅτι τῆς βουλῆς συγκαθεζομένης οἱ πλούσιοι, τὸν ὕπατον μὴ πείθοντες, αὐτοὶ διανοοῦνται καθ’ αὑτοὺς ἀποκτιννύναι τὸν Τιβέριον, πολλοὺς ἐπὶ τοῦτο δούλους καὶ φίλους ὡπλισμένους ἔχοντες.", "st": "TG 18.1"}, {"sp": "N", "t": "ὡς οὖν ταῦτα τοῖς περί αὑτὸν ἐξήγγειλεν ὁ Τιβέριος, οὗτοι μὲν εὐθὺς τάς τε τηβέννους περιεζώννυντο, καὶ τὰ τῶν ὑπηρετῶν δόρατα συγκλῶντες οἷς ἀνείργουσι τὸν ὄχλον, διελάμβανον ὡς ἀμυνούμενοι τοῖς κλάσμασι τοὺς ἐπερχομένους. τῶν δὲ ἀπωτέρω θαυμαζόντων τὰ γινόμενα καὶ πυνθανομένων, ὁ Τιβέριος ἥψατο τῇ χειρὶ τῆς κεφαλῆς, ἐνδεικνύμενος τῇ ὄψει τὸν κίνδυνον, ἐπεὶ τῆς φωνῆς οὐκ ἐπήκουον. οἱ δὲ ἐναντίοι τοῦτο ἰδόντες ἔθεον πρὸς τὴν βουλὴν, ἀπαγγέλλοντες αἰτεῖν διάδημα τὸν Τιβέριον καὶ τούτου σημεῖον εἶναι τὸ τῆς κεφαλῆς ἐπιθιγγάνειν. πάντες μὲν οὖν ἐθορυβήθησαν ὁ δὲ Νασικᾶς ἠξίου τὸν ὕπατον τῇ πόλει βοηθεῖν καὶ καταλύειν τὸν τύραννον. ἀποκριναμένου δὲ πράως ἐκείνου βίας μὲν οὐδεμιᾶς ὑπάρξειν οὐδὲ ἀναιρήσειν οὐδένα τῶν πολιτῶν ἄκριτον, εἰ μέντοι ψηφίσαιτό τι τῶν παρανόμων ὁ δῆμος ὑπὸ τοῦ Τιβερίου πεισθεὶς ἢ βιασθείς, τοῦτο κύριον μὴ φυλάξειν, ἀναπηδήσας ὁ Νασικᾶς, ἐπεὶ τοίνυν, ἔφη, προδίδωσιν ὁ ἄρχων τὴν πόλιν, οἱ βουλόμενοι τοῖς νόμοις βοηθεῖν ἀκολουθεῖτε. καὶ ταῦτα λέγων ἅμα καὶ τὸ κράσπεδον τοῦ ἱματίου θέμενος ἐπὶ τῆς κεφαλῆς, ἐχώρει πρὸς τὸ Καπετώλιον. ἕκαστος δὲ τῶν ἑπομένων αὐτῷ τῇ χειρὶ τὴν τήβεννον περιελίξας ἐώθει τοὺς ἐμποδών, οὐδενὸς ἐνισταμένου πρὸς τὸ ἀξίωμα τῶν ἀνδρῶν, ἀλλὰ φευγόντων καὶ πατούντων ἀλλήλους.", "st": "TG 19.1"}, {"sp": "N", "t": "οἱ μὲν οὖν περί αὐτοὺς ῥόπαλα καὶ σκυτάλας ἐκόμιζον οἴκοθεν αὐτοὶ δὲ τῶν δίφρων καταγνυμένων ὑπὸ τοῦ φεύγοντος ὄχλου τὰ κλάσματα καὶ τοὺς πόδας λαμβάνοντες ἀνέβαινον ἐπὶ τὸν Τιβέριον, ἅμα παίοντες τοὺς προτεταγμένους καὶ τούτων μὲν ἦν τροπὴ καὶ φόνος· αὐτοῦ δὲ τοῦ Τιβερίου φεύγοντος ἀντελάβετό τις τῶν ἱματίων. ὁ δὲ τὴν τήβεννον ἀφεὶς καὶ φεύγων ἐν τοῖς χιτῶσιν ἐσφάλη καὶ κατηνέχθη περί τινας τῶν πρὸ αὐτοῦ πεπτωκότας. ἀνιστάμενον δὲ αὑτὸν μὲν ἐμφανῶς καὶ πρῶτος εἷς τὴν κεφαλὴν πατάξας ποδὶ δίφρου Πόπλιος ἦν Σατυρήϊος εἷς τῶν συναρχόντων τῆς δὲ δευτέρας ἀντεποιεῖτο πληγῆς Λεύκιος Ῥοῦφος, ὡς ἐπὶ καλῷ τινι σεμνυνόμενος. τῶν δὲ ἄλλων ἀπέθανον ὑπὲρ τριακοσίους ξύλοις καὶ λίθοις συγκοπέντες, σιδήρῳ δὲ οὐδείς.", "st": "TG 19.5"}, {"sp": "N", "t": "ταύτην πρώτην ἱστοροῦσιν ἐν Ῥώμῃ στάσιν, ἀφ’ οὗ τὸ βασιλεύεσθαι κατέλυσαν, αἵματι καὶ φόνῳ πολιτῶν διακριθῆναι· τὰς δὲ ἄλλας οὔτε μικρὰς οὔτε περὶ μικρῶν γενομένας ἀνθυπείκοντες ἀλλήλοις, φόβῳ μὲν οἱ δυνατοὶ τῶν πολλῶν, αἰδούμενοι δὲ τὴν βουλὴν ὁ δῆμος, ἔπαυον. ἐδόκει δὲ καὶ τότε μὴ χαλεπῶς ἂν ἐνδοῦναι παρηγορηθεὶς ὁ Τιβέριος, ἔτι δὲ ῥᾷον εἶξαι δίχα φόνου καὶ τραυμάτων ἐπιοῦσιν· οὐ γὰρ πλείονες ἢ τρισχίλιοι περὶ αὐτὸν ἦσαν. ἀλλ’ ἔοικεν ὀργῇ τῶν πλουσίων καὶ μίσει πλέον ἢ δι’ ἃς ἐσκήπτοντο προφάσεις ἡ σύστασις ἐπ’ αὐτὸν γενέσθαι· καὶ τούτου μέγα τεκμήριον ὠμῶς καὶ παρανόμως ὑβρισθεὶς ὁ νεκρός, οὐ γὰρ ἐπέτρεψαν ἀνελέσθαι τὸ σῶμα τῷ ἀδελφῷ δεομένῳ καὶ θάψαι νυκτός, ἀλλὰ μετὰ τῶν ἄλλων νεκρῶν εἰς τὸν ποταμὸν ἔρριψαν. καὶ τοῦτο πέρας οὐκ ἦν, ἀλλὰ καὶ τῶν φίλων αὐτοῦ τοὺς μὲν ἐξεκήρυττον ἀκρίτους, τοὺς δὲ συλλαμβάνοντες ἀπεκτίννυσαν ἐν οἷς καὶ Διοφάνης ὁ ῥήτωρ ἀπώλετο. Γάϊον δέ τινα Βίλλιον εἰς ἀγγεῖον καθείρξαντες καὶ συνεμβαλόντες ἐχίδνας καὶ δράκοντας οὕτω διέφθειραν. ὁ δὲ Κυμαῖος Βλόσσιος ἀνήχθη μὲν ἐπὶ τοὺς ὑπάτους, ἐρωτώμενος δὲ περὶ τῶν γεγονότων ὡμολόγει πεποιηκέναι πάντα Τιβερίου κελεύοντος. εἰπόντος δὲ τοῦ Νασικᾶ πρὸς αὐτόν, τί οὖν, εἴ σε Τιβέριος ἐκέλευσεν ἐμπρῆσαι τὸ Καπετώλιον; τὸ μὲν πρῶτον ἀντέλεγεν ὡς οὐκ ἂν τοῦτο Τιβερίου κελεύσαντος· πολλάκις δὲ καὶ πολλῶν τὸ αὐτὸ πυνθανομένων, ἀλλ’ ἐκείνου γε προστάσσοντος, ἔφη, κἀμοὶ τοῦτο πρᾶξαι καλῶς εἶχεν· οὐ γὰρ ἂν Τιβέριος τοῦτο προσέταξεν, εἰ μὴ τῷ δήμῳ συνέφερεν, οὗτος μὲν οὖν διαφυγὼν ὕστερον ᾤχετο πρὸς Ἀριστόνικον εἰς Ἀσίαν, καὶ τῶν ἐκείνου πραγμάτων διαφθαρέντων ἑαυτὸν ἀνεῖλεν.", "st": "TG 20.1"}, {"sp": "N", "t": "ἡ δὲ βουλὴ θεραπεύουσα τὸν δῆμον ἐκ τῶν παρόντων οὔτε πρὸς τὴν διανομὴν ἔτι τῆς χώρας ἠναντιοῦτο, καὶ ἀντὶ τοῦ Τιβερίου προὔθηκε τοῖς πολλοῖς ὁριστὴν ἑλέσθαι. λαβόντες δὲ τὰς ψήφους εἵλοντο Πόπλιον Κράσσον, οἰκεῖον ὄντα Γράγχῳ· θυγάτηρ γὰρ αὐτοῦ Λικιννία Γαΐῳ Γράγχῳ συνῴκει. καίτοι Νέπως ὁ Κορνήλιός φησιν οὐ Κράσσου, Βρούτου δὲ τοῦ θριαμβεύσαντος ἀπὸ Λυσιτανῶν θυγατέρα γῆμαι Γάιον· ἀλλὰ οἱ πλείους ὡς ἡμεῖς γράφομεν ἱστοροῦσιν. ἐπεὶ δὲ χαλεπῶς μὲν ὁ δῆμος εἶχε τῷ θανάτῳ τοῦ Τιβερίου καὶ φανερὸς ἦν ἀμύνης περιμένων καιρόν, ἤδη δὲ καὶ δίκαι τῷ Νασικᾷ προανεσείοντο, δείσασα περὶ τοῦ ἀνδρὸς ἡ βουλὴ ψηφίζεται μηδὲν δεομένη πέμπειν αὐτὸν εἰς Ἀσίαν. οὐ γὰρ ἀπεκρύπτοντο κατὰ τὰς ἀπαντήσεις οἱ ἄνθρωποι τὴν δυσμένειαν, ἀλλ’ ἐξηγριαίνοντο καὶ κατεβόων ὅπου προστύχοιεν, ἐναγῆ καὶ τύραννον καὶ μεμιαγκότα φόνῳ σώματος ἀσύλου καὶ ἱεροῦ τὸ ἁγιώτατον καὶ φρικωδέστατον ἐν τῇ πόλει τῶν ἱερῶν ἀποκαλοῦντες. οὕτω μὲν ὑπεξῆλθε τῆς Ἰταλίας ὁ Νασικᾶς, καίπερ ἐνδεδεμένος ταῖς μεγίσταις ἱερουργίαις· ἦν γὰρ ὁ μέγιστος καὶ πρῶτος τῶν ἱερέων, ἔξω δὲ ἀλύων καὶ πλανώμενος ἀδόξως οὐ μετὰ πολὺν χρόνον κατέστρεψε περὶ Πέργαμον. οὐ δεῖ δὲ θαυμάζειν εἰ Νασικᾶν μεμίσηκεν οὕτως ὁ δῆμος, ὅπου καὶ Σκηπίων ὁ Ἀφρικανός, οὗ δοκοῦσι Ῥωμαῖοι μηδένα δικαιότερον μηδὲ μᾶλλον ἀγαπῆσαι, παρὰ μικρὸν ἦλθεν ἐκπεσεῖν καὶ στέρεσθαι τῆς πρὸς τὸν δῆμον εὐνοίας, ὅτι πρῶτον μὲν ἐν Νομαντίᾳ τὴν τελευτὴν τοῦ Τιβερίου πυθόμενος ἀνεφώνησεν ἐκ τῶν Ὁμηρικῶν", "st": "TG 21.1"}, {"sp": "N", "t": "ὣς ἀπόλοιτο καὶ ἄλλος ὅτις τοιαῦτά γε ῥέζοι,", "st": "TG 21.1b"}, {"sp": "N", "t": "ἔπειτα τῶν περὶ Γάϊον καὶ Φούλβιον αὐτοῦ δι’ ἐκκλησίας πυνθανομένων τί φρονοίη περὶ τῆς Τιβερίου τελευτῆς, οὐκ ἀρεσκομένην τοῖς ὑπ’ ἐκείνου πεπολιτευμένοις ἀπόκρισιν ἔδωκεν. ἐκ τούτου γὰρ ὁ μὲν δῆμος ἀντέκρουσεν αὐτῷ λέγοντι, μηδέπω τοῦτο ποιήσας πρότερον, αὐτὸς δὲ τὸν δῆμον εἰπεῖν κακῶς προήχθη, περὶ μὲν τούτων ἐν τῷ Σκηπίωνος βίῳ τὰ καθ’ ἕκαστα γέγραπται.", "st": "TG 21.5"}, {"sp": "HDR", "t": "Γάϊος Γράγχος"}, {"sp": "N", "t": "Γάιος δὲ Γράγχος ἐν ἀρχῇ μὲν ἢ δεδιὼς τοὺς ἐχθροὺς ἢ φθόνον συνάγων ἐπ’ αὐτούς ὑπεξέστη τε τῆς ἀγορᾶς καὶ καθ’ ἑαυτὸν ἡσυχίαν ἔχων διέτριβεν, ὡς ἄν τις ἔν τε τῷ παρόντι ταπεινὰ πράττων καὶ τὸ λοιπὸν οὕτως ἀπραγμόνως βιωσόμενος, ὥστε καὶ λόγον τισὶ καθ’ αὑτοῦ παρασχεῖν ὡς δυσχεραίνοντος καὶ προβεβλημένου τὴν τοῦ Τιβερίου πολιτείαν. ἦν δὲ καὶ μειράκιον παντάπασιν· ἐννέα γὰρ ἐνιαυτοῖς ἐλείπετο τἀδελφοῦ καθ’ ἡλικίαν, ἐκεῖνος δὲ οὔπω τριάκοντα γεγονὼς ἀπέθανεν. ἐπεὶ δὲ προϊόντος τοῦ χρόνου τόν τε τρόπον ἡσυχῇ διέφαινεν ἀργίας καὶ μαλακίας καὶ πότων καὶ χρηματισμῶν ἀλλότριον ὄντα, καὶ τόν λόγον ὥσπερ ὠκύπτερα κατασκευαζόμενος ἐπὶ τὴν πολιτείαν δῆλος ἦν οὐκ ἠρεμήσων, δίκην τέ τινι τῶν φίλων φεύγοντι Βεττίῳ συνειπών, τοῦ δήμου συνενθουσιῶντος ὑφ’ ἡδονῆς καὶ βακχεύοντος περὶ αὐτόν, ἀπέδειξε τοὺς ἄλλους ῥήτορας παίδων μηδὲν διαφέροντας, εἰς φόβον αὖθις οἱ δυνατοὶ καθίσταντο, καὶ πολὺς ἦν ἐν αὐτοῖς λόγος ὡς οὐκ ἐάσουσιν ἐπὶ δημαρχίαν τόν Γάϊον προελθεῖν.", "st": "CG 1.1"}, {"sp": "N", "t": "συντυγχάνει δὲ ἀπὸ ταὐτομάτου λαχεῖν αὐτὸν εἰς Σαρδὼ ταμίαν Ὀρέστῃ τῷ ὑπάτῳ· καὶ τοῦτο τοῖς μὲν ἐχθροῖς καθ’ ἡδονὴν ἐγεγόνει, τόν δὲ Γάϊον οὐκ ἐλύπησεν. ἅτε γὰρ ὢν πολεμικὸς καὶ χεῖρον οὐδὲν πρὸς στρατείας ἠσκημένος ἢ δίκας, ἔτι δὲ τὴν πολιτείαν καὶ τὸ βῆμα φρίττων, ἀντέχειν δὲ καλοῦντι τῷ δήμῳ καὶ τοῖς φίλοις οὐ δυνάμενος, παντάπασι τὴν ἀποδημίαν ἐκείνην ἠγάπησε. καίτοι κρατεῖ δόξα πολλὴ τοῦτον ἄκρατον γενέσθαι δημαγωγὸν, καὶ πολὺ τοῦ Τιβερίου λαμπρότερον πρὸς τὴν ἀπὸ τῶν ὄχλων δόξαν. οὐκ ἔχει δὲ οὕτω τὸ ἀληθές· ἀλλ’ ἔοικεν ὑπ’ ἀνάγκης τινὸς μᾶλλον οὗτος ἢ προαιρέσεως ἐμπεσεῖν εἰς τὴν πολιτείαν. ἱστορεῖ δὲ καὶ Κικέρων ὁ ῥήτωρ ὡς ἄρα φεύγοντι πᾶσαν ἀρχὴν τῷ Γαΐῳ καὶ μεθ’ ἡσυχίας ᾑρημένῳ ζῆν ὁ ἀδελφὸς ὄναρ φανεὶς καὶ προσαγορεύσας, τί δῆτα, φαίη, Γάιε, βραδύνεις; οὐκ ἔστιν ἀπόδρασις, ἀλλ’ εἷς μὲν ἡμῖν ἀμφοτέροις βίος, εἷς δὲ θάνατος ὑπὲρ τοῦ δήμου πολιτευομένοις πέπρωται", "st": "CG 1.4"}, {"sp": "N", "t": "γενόμενος οὖν ὁ Γάιος ἐν Σαρδόνι πᾶσαν ἀρετῆς ἀπόδειξιν ἐδίδου, καὶ πολὺ πάντων διέφερε τῶν νέων ἐν τοῖς πρὸς τοὺς πολεμίους ἀγῶσι καὶ ἐν τοῖς πρὸς τοὺς ὑπηκόους δικαίοις καὶ ἐν τῇ πρὸς τὸν στρατηγὸν εὐνοίᾳ καὶ τιμῇ, σωφροσύνῃ δὲ καὶ λιτότητι καὶ φιλοπονίᾳ παρήλλαττε καὶ τοὺς πρεσβυτέρους. ἰσχυροῦ δὲ καὶ νοσώδους ἅμα χειμῶνος ἐν Σαρδόνι γενομένου καὶ τοῦ στρατηγοῦ τὰς πόλεις ἐσθῆτα τοῖς στρατιώταις αἰτοῦντος, ἔπεμψαν εἰς Ῥώμην παραιτούμενοι. δεξαμένης δὲ τῆς βουλῆς τὴν παραίτησιν αὐτῶν καὶ τὸν στρατηγὸν ἄλλοθεν ἀμφιέζειν τοὺς στρατιώτας κελευούσης, ἀποροῦντος δὲ ἐκείνου καὶ τῶν στρατιωτῶν κακοπαθούντων, ἐπελθὼν τὰς πόλεις ὁ Γάιος αὐτοὺς ἀφ’ ἑαυτῶν ἐποίησεν ἐσθῆτα πέμψαι καὶ βοηθῆσαι τοῖς Ῥωμαίοις. ταῦτα πάλιν εἰς Ῥώμην ἀπαγγελλόμενα καὶ δοκοῦντα δημαγωγίας προάγωνες εἶναι διετάραττε τὴν βουλήν. καὶ πρῶτον μὲν ἐκ Λιβύης παρὰ Μικίψα τοῦ βασιλέως πρέσβεις παραγενομένους, καὶ λέγοντας ὡς ὁ βασιλεὺς χάριτι Γαΐου Γράγχου πέμψειεν εἰς Σαρδόνα σῖτον τῷ στρατηγῷ, δυσχεραίνοντες ἐξέβαλον· ἔπειτα δόγμα ποιοῦνται τοῖς μὲν στρατιώταις διαδοχὴν ἀποσταλῆναι, τὸν δὲ Ὀρέστην ἐπιμένειν, ὡς δὴ καὶ τοῦ Γαΐου διὰ τὴν ἀρχὴν παραμενοῦντος. ὁ δὲ τούτων αὐτῷ προσπεσόντων εὐθὺς ἐξέπλευσε πρὸς ὀργήν, καὶ φανεὶς ἐν Ῥώμῃ παρ’ ἐλπίδας οὐ μόνον ὑπὸ τῶν ἐχθρῶν αἰτίαν εἶχεν, ἀλλὰ καὶ τοῖς πολλοῖς ἀλλόκοτον ἐδόκει τὸ ταμίαν ὄντα προαποστῆναι τοῦ ἄρχοντος, οὐ μὴν ἀλλὰ κατηγορίας αὐτῷ γενομένης ἐπὶ τῶν τιμητῶν, αἰτησάμενος λόγον οὕτω μετέστησε τὰς γνώμας τῶν ἀκουσάντων ὡς ἀπελθεῖν ἠδικῆσθαι τὰ μέγιστα δόξας. ἐστρατεῦσθαι μὲν γὰρ ἔφη δώδεκα ἔτη, τῶν ἄλλων δέκα στρατευομένων ἐν ἀνάγκαις, ταμιεύων δὲ τῷ στρατηγῷ παραμεμενηκέναι τριετίαν, τοῦ νόμου μετ’ ἐνιαυτὸν ἐπανελθεῖν διδόντος· μόνος δὲ τῶν στρατευσαμένων πλῆρες τὸ βαλάντιον εἰσενηνοχὼς κενὸν ἐξενηνοχέναι, τοὺς δὲ ἄλλους ἐκπιόντας ὃν εἰσήνεγκαν οἶνον, ἀργυρίου καὶ χρυσίου μεστοὺς δεῦρο τοὺς ἀμφορεῖς ἥκειν κομίζοντας.", "st": "CG 2.1"}, {"sp": "N", "t": "ἐκ τούτου πάλιν ἄλλας αἰτίας αὐτῷ καὶ δίκας ἐπῆγον ὡς τοὺς συμμάχους ἀφιστάντι καὶ κεκοινωνηκότι τῆς περὶ Φρέγελλαν ἐνδειχθείσης συνωμοσίας, ὁ δὲ πᾶσαν ὑποψίαν ἀπολυσάμενος καὶ φανεὶς καθαρὸς εὐθὺς ἐπὶ δημαρχίαν ὥρμησε, τῶν μὲν γνωρίμων ἀνδρῶν ὁμαλῶς ἁπάντων ἐναντιουμένων πρὸς αὐτόν, ὄχλου δὲ τοσούτου συρρέοντος εἰς τὴν πόλιν ἐκ τῆς Ἰταλίας καὶ συναρχαιρεσιάζοντος ὡς πολλοῖς μὲν οἰκήσεις ἐπιλιπεῖν, τοῦ δὲ πεδίου μὴ δεξαμένου τὸ πλῆθος ἀπὸ τῶν τεγῶν καὶ τῶν κεράμων τὰς φωνὰς συνηχεῖν. τοσοῦτον δ’ οὖν ἐξεβιάσαντο τὸν δῆμον οἱ δυνατοὶ καὶ τῆς ἐλπίδος τοῦ Γαΐου καθεῖλον, ὅσον οὐχ, ὡς προσεδόκησε, πρῶτον, ἀλλά τέταρτον ἀναγορευθῆναι. παραλαβὼν δὲ τὴν ἀρχὴν εὐθὺς ἦν ἁπάντων πρῶτος, ἰσχύων τε τῷ λέγειν, ὡς ἄλλος οὐδείς, καὶ τοῦ πάθους αὐτῷ παρρησίαν πολλὴν διδόντος ἀνακλαιομένῳ τὸν ἀδελφόν. ἐνταῦθα γὰρ ἐξ ἁπάσης προφάσεως περιῆγε τὸν δῆμον, ἀναμιμνῄσκων τῶν γεγονότων καὶ παρατιθεὶς τὰ τῶν προγόνων, ὡς ἐκεῖνοι μὲν καὶ Φαλίσκοις ἐπολέμησαν ὑπὲρ Γενυκίου τινὸς δημάρχου λοιδορηθέντος, καὶ Γαΐου Βετουρίου θάνατον κατέγνωσαν, ὅτι δημάρχῳ πορευομένῳ δι’ ἀγορᾶς οὐχ ὑπεξέστη μόνος· ὑμῶν δὲ ὁρώντων, ἔφη, Τιβέριον ξύλοις συνέκοπτον οὗτοι, καὶ διὰ μέσης τῆς πόλεως ἐσύρετο νεκρὸς ἐκ Καπετωλίου ῥιφησόμενος εἰς τὸν ποταμόν· οἱ δὲ ἁλισκόμενοι τῶν φίλων ἀπέθνῃσκον ἄκριτοι, καίτοι πάτριόν ἐστιν ἡμῖν, εἴ τις ἔχων δίκην θανατικὴν μὴ ὑπακούει, τούτου πρὸς τὰς θύρας ἕωθεν ἐλθόντα σαλπιγκτὴν ἀνακαλεῖσθαι τῇ σάλπιγγι, καὶ μὴ πρότερον ἐπιφέρειν ψῆφον αὐτῷ τοὺς δικαστάς. οὕτως εὐλαβεῖς καὶ πεφυλαγμένοι περὶ τὰς κρίσεις ἦσαν.", "st": "CG 3.1"}, {"sp": "N", "t": "τοιούτοις λόγοις προανασείσας τὸν δῆμον ἦν δὲ καὶ μεγαλοφωνότατος, καὶ ῥωμαλεώτατος ἐν τῷ λέγειν, δύο νόμους εἰσέφερε, τὸν μέν, εἴ τινος ἄρχοντος ἀφῃρῇτο τὴν ἀρχὴν ὁ δῆμος, οὐκ ἐῶντα τούτῳ δευτέρας ἀρχῆς μετουσίαν εἶναι· τὸν δ’, εἴ τις ἄρχων ἄκριτον ἐκκεκηρύχοι πολίτην, κατ’ αὐτοῦ διδόντα κρίσιν τῷ δήμῳ. τούτων τῶν νόμων ἄντικρυς ὁ μὲν Μᾶρκον Ὀκτάβιον ἠτίμου τὸν ὑπὸ Τιβερίου τῆς δημαρχίας ἐκπεσόντα, τῷ δ’ ἐνείχετο Ποπίλλιος· οὗτος γὰρ στρατηγῶν τοὺς τοῦ Τιβερίου φίλους ἐξεκήρυξε. καὶ Ποπίλλιος μὲν οὐχ ὑποστὰς τὴν κρίσιν ἔφυγεν ἐξ Ἰταλίας· τὸν δὲ ἕτερον νόμον Γάιος αὐτὸς ἐπανείλετο, φήσας τῇ μητρὶ Κορνηλίᾳ δεηθείσῃ χαρίζεσθαι τὸν Ὀκτάβιον. καὶ ὁ δῆμος ἠγάσθη καὶ συνεχώρησε, τιμῶν τὴν Κορνηλίαν οὐδὲν ἧττον ἀπὸ τῶν παίδων ἢ τοῦ πατρός, ἧς γε καὶ χαλκῆν εἰκόνα στήσας ὕστερον ἐπέγραψε Κορνηλίαν μητέρα Γράγχων. ἀπομνημονεύεται δὲ καὶ τοῦ Γαΐου πολλὰ ῥητορικῶς καὶ ἀγοραίως ὑπὲρ αὐτῆς εἰρημένα πρός τινα τῶν ἐχθρῶν σύ γάρ ἔφη, Κορνηλίαν λοιδορεῖς τὴν Τιβέριον τεκοῦσαν; ἐπεὶ δὲ διαβεβλημένος ἦν εἰς μαλακίαν ὁ λοιδορηθείς· τίνα δέ, εἶπεν, ἔχων παρρησίαν συγκρίνεις Κορνηλίᾳ σεαυτόν; ἔτεκες γὰρ ὡς ἐκείνη; καὶ μὴν πάντες ἴσασι Ῥωμαῖοι πλείω χρόνον ἐκείνην ἀπ’ ἀνδρὸς οὖσαν ἢ σὲ τὸν ἄνδρα τοιαύτη μὲν ἡ πικρία τῶν λόγων ἦν αὐτοῦ, καὶ πολλὰ λαβεῖν ἐκ τῶν γεγραμμένων ἔστιν ὅμοια.", "st": "CG 4.1"}, {"sp": "N", "t": "τῶν δὲ νόμων οὓς εἰσέφερε τῷ δήμῳ χαριζόμενος καὶ καταλύων τὴν σύγκλητον, ὁ μὲν ἦν κληρουχικὸς ἀνανέμων τοῖς πένησι τὴν δημοσίαν, ὁ δὲ στρατιωτικός ἐσθῆτά τε κελεύων δημοσίᾳ χορηγεῖσθαι καὶ μηδὲν εἰς τοῦτο τῆς μισθοφορᾶς ὑφαιρεῖσθαι τῶν στρατευομένων, καὶ νεώτερον ἐτῶν ἑπτακαίδεκα μὴ καταλέγεσθαι στρατιώτην δὲ συμμαχικός ἰσοψήφους ποιῶν τοῖς πολίταις τοὺς Ἰταλιώτας. ὁ δὲ σιτικός ἐπευωνίζων τοῖς πένησι τὴν ἀγοράν. ὁ δὲ δικαστικός, ᾧ τὸ πλεῖστον ἀπέκοψε τῆς τῶν συγκλητικῶν δυνάμεως, μόνοι γὰρ ἔκρινον τὰς δίκας, καὶ διὰ τοῦτο φοβεροὶ τῷ τε δήμῳ καὶ τοῖς ἱππεῦσιν ἦσαν, ὁ δὲ τριακοσίους τῶν ἱππέων προσκατέλεξεν αὐτοῖς οὖσι τριακοσίοις, καὶ τὰς κρίσεις κοινὰς τῶν ἑξακοσίων ἐποίησε. τοῦτον τὸν νόμον εἰσφέρων τά τε ἄλλα λέγεται σπουδάσαι διαφερόντως, καὶ τῶν πρὸ αὐτοῦ πάντων δημαγωγῶν πρὸς τὴν σύγκλητον ἀφορώντων καὶ τὸ καλούμενον κομίτιον, πρῶτος τότε στραφεὶς ἔξω πρὸς τὴν ἀγορὰν δημηγορῆσαι, καὶ τὸ λοιπὸν οὕτω ποιεῖν ἐξ ἐκείνου, μικρᾷ παρεγκλίσει καὶ μεταθέσει σχήματος μέγα πρᾶγμα κινήσας καὶ μετενεγκὼν τρόπον τινὰ τὴν πολιτείαν ἐκ τῆς ἀριστοκρατίας εἰς τὴν δημοκρατίαν, ὡς τῶν πολλῶν δέον, οὐ τῆς βουλῆς, στοχάζεσθαι τοὺς λέγοντας.", "st": "CG 5.1"}, {"sp": "N", "t": "ἐπεὶ δὲ οὐ μόνον ἐδέξατο τὸν νόμον τοῦτον ὁ δῆμος, ἀλλὰ κἀκείνῳ τοὺς κρίνοντας ἐκ τῶν ἱππέων ἔδωκε καταλέξαι, μοναρχική τις ἰσχὺς ἐγεγόνει περὶ αὐτόν, ὥστε καὶ τὴν σύγκλητον ἀνέχεσθαι συμβουλεύοντος αὐτοῦ. συνεβούλευε δὲ ἀεί τι τῶν ἐκείνῃ πρεπόντων εἰσηγούμενος· οἷον ἦν καὶ τὸ περὶ τοῦ σίτου δόγμα μετριώτατον καὶ κάλλιστον, ὃν ἔπεμψε μὲν ἐξ Ἰβηρίας Φάβιος ἀντιστράτηγος, ἐκεῖνος δ’ ἔπεισε τὴν βουλὴν ἀποδομένην τὸν σῖτον ἀναπέμψαι ταῖς πόλεσι τὸ ἀργύριον, καὶ προσεπαιτιάσασθαι τὸν Φάβιον ὡς ἐπαχθῆ καὶ ἀφόρητον ποιοῦντα τὴν ἀρχὴν τοῖς ἀνθρώποις ἐφ’ ᾧ μεγάλην ἔσχε δόξαν μετὰ εὐνοίας ἐν ταῖς ἐπαρχίαις.", "st": "CG 6.1"}, {"sp": "N", "t": "ἔγραψε δὲ καὶ πόλεις ἀποικίδας ἐκπέμπεσθαι καὶ τὰς ὁδοὺς ποιεῖσθαι καὶ κατασκευάζεσθαι σιτοβόλια, τούτοις ἅπασι πραττομένοις αὑτὸν ἄρχοντα καὶ διοικητὴν ἐφιστάς, καὶ πρὸς οὐδὲν ἀποτρυόμενος τῶν τοσούτων καὶ τηλικούτων, ἀλλὰ καὶ θαυμαστῷ τινι τάχει καὶ πόνῳ τῶν γινομένων ὡς μόνον ἕκαστον ἐξεργαζόμενος, ὥστε καὶ τοὺς πάνυ μισοῦντας αὑτὸν καὶ δεδοικότας ἐκπλήττεσθαι τὸ διὰ πάντων ἀνύσιμον καὶ τελεσιουργόν. οἱ δὲ πολλοὶ καὶ τὴν ὄψιν αὐτὴν ἐθαύμαζον, ἐξηρτημένον ὁρῶντες αὐτοῦ πλῆθος ἐργολάβων, τεχνιτῶν, πρεσβευτῶν, ἀρχόντων, στρατιωτῶν, φιλολόγων, οἷς πᾶσιν ἐντυγχάνων μετὰ εὐκολίας καὶ τὸ σεμνὸν ἐν τῷ φιλανθρώπῳ διαφυλάττων, καὶ νέμων αὐτοῦ τὸ ἁρμόττον οἰκείως ἑκάστῳ, χαλεποὺς ἀπεδείκνυε συκοφάντας τοὺς φοβερὸν αὑτὸν ἢ φορτικὸν ὅλως ἢ βίαιον ἀποκαλοῦντας. οὕτω δεινότερος ἦν ἐν ταῖς ὁμιλίαις καὶ ταῖς πράξεσιν ἢ τοῖς ἀπὸ τοῦ βήματος λόγοις δημαγωγός.", "st": "CG 6.3"}, {"sp": "N", "t": "ἐσπούδασε δὲ μάλιστα περὶ τὴν ὁδοποιΐαν, τῆς τε χρείας ἅμα καὶ τοῦ πρὸς χάριν καὶ κάλλος ἐπιμεληθείς, εὐθεῖαι γὰρ ἤγοντο διὰ τῶν χωρίων ἀτρεμεῖς, καὶ τὸ μὲν ἐστόρνυτο πέτρᾳ ξεστῇ, τὸ ἄμμου χώμασι νακτῆς ἐπυκνοῦτο. πιμπλαμένων δὲ τῶν κοίλων καὶ ζευγνυμένων γεφύραις ὅσα χείμαρροι διέκοπτον ἢ φάραγγες, ὕψος τε τῶν ἑκατέρωθεν ἴσον καὶ παράλληλον λαμβανόντων, ὁμαλὴν καὶ καλὴν ὄψιν εἶχε δι’ ὅλου τὸ ἔργον. πρὸς δὲ τούτοις διαμετρήσας κατὰ μίλιον ὁδὸν πᾶσαν τὸ δὲ μίλιον ὀκτὼ σταδίων ὀλίγον ἀποδεῖ κίονας λιθίνους σημεῖα τοῦ μέτρου κατέστησεν. ἄλλους δὲ λίθους ἔλαττον ἀπέχοντας ἀλλήλων ἑκατέρωθεν τῆς ὁδοῦ διέθηκεν, ὡς εἴη ῥᾳδίως τοῖς ἵππους ἔχουσιν ἐπιβαίνειν ἀπ’ αὐτῶν ἀναβολέως μὴ δεομένοις.", "st": "CG 7.1"}, {"sp": "N", "t": "ἐπὶ τούτοις τοῦ δήμου μεγαλύνοντος αὐτὸν καὶ πᾶν ὁτιοῦν ἑτοίμως ἔχοντος ἐνδείκνυσθαι πρὸς εὔνοιαν, ἔφη ποτὲ δημηγορῶν αὐτὸς αἰτήσειν χάριν, ἣν λαβὼν μὲν ἀντὶ παντὸς ἕξειν, εἰ δὲ ἀποτύχοι, μηδὲν ἐκείνοις μεμψιμοιρήσειν. τοῦτο ῥηθὲν ἔδοξεν αἴτησις ὑπατείας εἶναι, καὶ προσδοκίαν πᾶσιν ὡς ἅμα μὲν ὑπατείαν, ἅμα δὲ δημαρχίαν μετιὼν παρέσχεν. ἐνστάντων δὲ τῶν ὑπατικῶν ἀρχαιρεσιῶν καὶ μετεώρων ὄντων ἁπάντων ὤφθη Γάϊον Φάννιον κατάγων εἰς τὸ πεδίον καὶ συναρχαιρεσιάζων ἐκείνῳ μετὰ τῶν φίλων, τοῦτο ῥοπὴν ἤνεγκε τῷ Φαννίῳ μεγάλην. κἀκεῖνος μὲν ὕπατος, Γάιος δὲ δήμαρχος ἀπεδείχθη τὸ δεύτερον, οὐ παραγγέλλων οὐδὲ μετιών, ἀλλὰ τοῦ δήμου σπουδάσαντος.", "st": "CG 8.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ἑώρα τὴν μὲν σύγκλητον ἐχθρὰν ἄντικρυς, ἀμβλὺν δὲ τῇ πρὸς αὐτὸν εὐνοίᾳ τὸν Φάννιον, αὖθις ἑτέροις νόμοις ἀπηρτήσατο τὸ πλῆθος, ἀποικίας μὲν εἷς Τάραντα καὶ Καπύην πέμπεσθαι γράφων, καλῶν δὲ ἐπὶ κοινωνίᾳ πολιτείας τοὺς Λατίνους, ἡ δὲ βουλὴ δείσασα μὴ παντάπασιν ἄμαχος γένηται, καινὴν καὶ ἀσυνήθη πεῖραν ἐπῆγε τοῖς πολλοῖς ἀποτροπῆς, ἀντιδημαγωγοῦσα καὶ χαριζομένη παρὰ τὸ βέλτιστον. ἦν γὰρ εἷς τῶν τοῦ Γαΐου συναρχόντων Λίβιος Δροῦσος, ἀνὴρ οὔτε γεγονώς τινος Ῥωμαίων οὔτε τεθραμμένος χεῖρον, ἤθει δὲ καὶ λόγῳ καὶ πλούτῳ τοῖς μάλιστα τιμωμένοις καὶ δυναμένοις ἀπὸ τούτων ἐνάμιλλος. ἐπὶ τοῦτον οὖν οἱ γνωριμώτατοι τρέπονται, καὶ παρεκάλουν αὐτὸν ἅψασθαι τοῦ Γαΐου καὶ μετ’ αὐτῶν ἐπὶ τὸν ἄνδρα συστῆναι, μὴ βιαζόμενον μηδὲ ἀντικρούοντα τοῖς πολλοῖς, ἀλλὰ πρὸς ἡδονὴν ἄρχοντα καὶ χαριζόμενον ὑπέρ ὧν καὶ ἀπεχθάνεσθαι καλῶς εἶχεν.", "st": "CG 8.3"}, {"sp": "N", "t": "ἐπιδοὺς οὖν ὁ Λίβιος εἰς ταῦτα τῇ βουλῇ τὴν ἑαυτοῦ δημαρχίαν νόμους ἔγραψεν οὔτε τῶν καλῶν τινος οὔτε τῶν λυσιτελῶν ἐχομένους, ἀλλὰ ἓν μόνον, ὑπερβαλέσθαι τὸν Γάϊον ἡδονῇ καὶ χάριτι τῶν πολλῶν, ὥσπερ ἐν κωμῳδίᾳ, σπεύδων καὶ διαμιλλώμενος. ᾧ καὶ καταφανεστάτην ἐποίησεν ἑαυτὴν ἡ σύγκλητος οὐ δυσχεραίνουσαν τοῖς τοῦ Γαΐου πολιτεύμασιν, ἀλλὰ αὐτὸν ἐκεῖνον ἀνελεῖν ἢ ταπεινῶσαι παντάπασι βουλομένην. τὸν μὲν γὰρ ἀποικίας δύο γράψαντα καὶ τοὺς χαριεστάτους τῶν πολιτῶν εἰσάγοντα δημοκοπεῖν ᾐτιῶντο, Λιβίῳ δὲ δώδεκα κατοικίζοντι καὶ τρισχιλίους εἰς ἑκάστην ἀποστέλλοντι τῶν ἀπόρων συνελαμβάνοντο. κἀκείνῳ μὲν, ὅτι χώραν διένειμε τοῖς πένησι προστάξας ἑκάστῳ τελεῖν ἀποφορὰν εἰς τὸ δημόσιον, ὡς κολακεύοντι τοὺς πολλοὺς ἀπηχθάνοντο, Λίβιος δὲ καὶ τὴν ἀποφορὰν ταύτην τῶν νειμαμένων ἀφαιρῶν ἤρεσκεν αὐτοῖς. ἔτι δὲ ὁ μὲν τοῖς Λατίνοις ἰσοψηφίαν διδοὺς ἐλύπει, τοῦ δέ, ὅπως μηδὲ ἐπὶ στρατείας ἐξῇ τινα Λατίνων ῥάβδοις αἰκίσασθαι γράψαντος ἐβοήθουν τῷ νόμῳ. καὶ μέντοι καὶ αὐτὸς ὁ Λίβιος ἀεὶ δημηγορῶν ἔλεγεν ὡς γράφοι ταῦτα τῇ βουλῇ δοκοῦντα κηδομένῃ τῶν πολλῶν· ὃ δὴ καὶ μόνον ἀπὸ τῶν πολιτευμάτων αὐτοῦ χρήσιμον ὑπῆρχεν. ἡμερώτερον γὰρ ἔσχε πρὸς τὴν βουλὴν ὁ δῆμος· καὶ τοὺς γνωριμωτάτους αὐτοῦ πρότερον ὑφορωμένου καὶ μισοῦντος ἐξέλυσε καὶ κατεπράυνε τὴν μνησικακίαν καὶ χαλεπότητα ταύτην ὁ Λίβιος, ὡς ἐκ τῆς ἐκείνων ὁρμώμενος γνώμης ἐπὶ τὸ δημαγωγεῖν καὶ χαρίζεσθαι τοῖς πολλοῖς.", "st": "CG 9.1"}, {"sp": "N", "t": "μεγίστη δὲ τῷ Δρούσῳ πίστις εὐνοίας πρὸς τὸν δῆμον ἐγίνετο καὶ δικαιοσύνης τὸ μηδὲν αὑτῷ μηδ’ ὑπὲρ ἑαυτοῦ φαίνεσθαι γράφοντα, καὶ γὰρ οἰκιστὰς ἑτέρους ἐξέπεμπε τῶν πόλεων καὶ διοικήσεσι χρημάτων οὐ προσῄει, τοῦ Γαΐου τὰ πλεῖστα καὶ μέγιστα τῶν τοιούτων αὑτῷ προστιθέντος. ἐπεὶ δὲ Ῥουβρίου τῶν συναρχόντων ἑνὸς οἰκίζεσθαι Καρχηδόνα γράψαντος ἀνῃρημένην ὑπὸ Σκηπίωνος, κλήρῳ λαχὼν ὁ Γάιος ἐξέπλευσεν εἰς Λιβύην ἐπὶ τὸν κατοικισμόν, ἔτι μᾶλλον ἐπιβὰς ὁ Δροῦσος ἀπόντος αὐτοῦ τὸν δῆμον ὑπελάμβανε καὶ προσήγετο, μάλιστα ταῖς κατὰ τοῦ Φουλβίου διαβολαῖς. ὁ δὲ Φούλβιος οὗτος ἦν τοῦ Γαΐου φίλος, καὶ συνάρχων ἐπὶ τὴν διανομὴν τῆς χώρας ᾑρημένος· ἦν δὲ θορυβώδης, καὶ μισούμενος μὲν ὑπὸ τῆς βουλῆς ἄντικρυς, ὕποπτος δὲ καὶ τοῖς ἄλλοις ὡς τὰ συμμαχικὰ διακινῶν καὶ παροξύνων κρύφα τοὺς Ἰταλιώτας πρὸς ἀπόστασιν. οἷς ἀναποδείκτως καὶ ἀνελέγκτως λεγομένοις αὐτὸς προσετίθει πίστιν ὁ Φούλβιος οὐχ ὑγιαινούσης οὐδὲ εἰρηνικῆς ὢν προαιρέσεως. τοῦτο μάλιστα κατέλυε τὸν Γάϊον ἀπολαύοντα τοῦ μίσους, καὶ ὅτε Σκηπίων ὁ Ἀφρικανὸς ἐξ οὐδενὸς αἰτίου προφανοῦς ἐτελεύτησε καὶ σημεῖά τινα τῷ νεκρῷ πληγῶν καὶ βίας ἐπιδραμεῖν ἔδοξεν, ὡς ἐν τοῖς περὶ ἐκείνου γέγραπται, τὸ μὲν πλεῖστον ἐπὶ τὸν Φούλβιον ἦλθε τῆς διαβολῆς, ἐχθρὸν ὄντα καὶ τὴν ἡμέραν ἐκείνην ἐπὶ τοῦ βήματος τῷ Σκηπίωνι λελοιδορημένον, ἥψατο δὲ καὶ τοῦ Γαΐου ὑπόνοια. καὶ δεινὸν οὕτως ἔργον ἐπ’ ἀνδρὶ τῷ πρώτῳ καὶ μεγίστῳ Ῥωμαίων τολμηθὲν οὐκ ἔτυχε δίκης οὐδὲ εἰς ἔλεγχον προῆλθεν· ἐνέστησαν γὰρ οἱ πολλοὶ καὶ κατέλυσαν τὴν κρίσιν ὑπὲρ τοῦ Γαΐου φοβηθέντες, μὴ περιπετὴς τῇ αἰτίᾳ τοῦ φόνου ζητουμένου γένηται· ταῦτα μὲν οὖν ἐγεγόνει πρότερον.", "st": "CG 10.1"}, {"sp": "N", "t": "ἐν δὲ τῇ Λιβύῃ περὶ τὸν τῆς Καρχηδόνος κατοικισμόν, ἣν ὁ Γάιος Ἰουνωνίαν, ὅπερ ἐστὶν Ἡραίαν, ὠνόμασε, πολλὰ κωλύματα γενέσθαι παρὰ τοῦ δαιμονίου λέγουσιν. ἥ τε γὰρ πρώτη σημαία, πνεύματος ἀφαρπάζοντος αὐτήν, τοῦ δὲ φέροντος ἐγκρατῶς ἀντεχομένου, συνετρίβη, καὶ τὰ ἱερὰ τοῖς βωμοῖς ἐπικείμενα διεσκέδασεν ἀνέμου θύελλα καὶ διέρριψεν ὑπὲρ τοὺς ὅρους τῆς γεγενημένης ὑπογραφῆς, αὐτοὺς δὲ τοὺς ὅρους ἀνέσπασαν ἐπελθόντες λύκοι καὶ μακρὰν ᾤχοντο φέροντες. οὐ μὴν ἀλλὰ πάντα συντάξας καὶ διακοσμήσας ὁ Γάϊος ἡμέραις ἑβδομήκοντα ταῖς πάσαις ἐπανῆλθεν εἰς Ῥώμην, πιέζεσθαι τὸν Φούλβιον ὑπὸ τοῦ Δρούσου πυνθανόμενος, καὶ τῶν πραγμάτων τῆς αὐτοῦ παρουσίας δεομένων· Λεύκιος γὰρ Ὀπίμιος, ἀνὴρ ὀλιγαρχικὸς καὶ δυνατὸς ἐν τῇ βουλῇ, πρότερον μὲν ἐξέπεσεν ὑπατείαν παραγγέλλων, τοῦ Γαΐου τὸν Φάννιον προαγαγόντος, ἐκεῖνον δὲ καταρχαιρεσιάσαντος· τότε δὲ πολλῶν βοηθούντων ἐπίδοξος ἦν ὑπατεύσειν, ὑπατεύων δὲ καταλύσειν τὸν Γάιον, ἤδη τρόπον τινὰ τῆς δυνάμεως αὐτοῦ μαραινομένης καὶ τοῦ δήμου μεστοῦ γεγονότος τῶν τοιούτων πολιτευμάτων διὰ τὸ πολλοὺς τοὺς πρὸς χάριν δημαγωγοῦντας εἶναι καὶ τὴν βουλὴν ὑπείκειν ἑκοῦσαν.", "st": "CG 11.1"}, {"sp": "N", "t": "ἐπανελθὼν δὲ πρῶτον μὲν ἐκ τοῦ Παλατίου μετῴκησεν εἰς τὸν ὑπὸ τὴν ἀγορὰν τόπον ὡς δημοτικώτερον, ὅπου πλείστους τῶν ταπεινῶν καὶ πενήτων συνέβαινεν οἰκεῖν ἔπειτα τῶν νόμων ἐξέθηκε τοὺς λοιπούς ὡς ἐπάξων τὴν ψῆφον αὐτοῖς. ὄχλου δὲ πανταχόθεν αὐτῷ συνιόντος ἔπεισεν ἡ βουλὴ τὸν ὕπατον Φάννιον ἐκβαλεῖν τοὺς ἄλλους πλὴν Ῥωμαίων ἅπαντας. γενομένου δὲ κηρύγματος ἀήθους καὶ ἀλλοκότου, μηδένα τῶν συμμάχων μηδὲ τῶν φίλων ἐν Ῥώμῃ φανῆναι περὶ τὰς ἡμέρας ἐκείνας, ἀντεξέθηκεν ὁ Γάϊος διάγραμμα κατηγορῶν τοῦ ὑπάτου, καὶ τοῖς συμμάχοις, ἂν μένωσι, βοηθήσειν ἐπαγγελλόμενος, οὐ μὴν ἐβοήθησεν, ἀλλὰ ὁρῶν ἕνα τῶν ξένων αὐτοῦ καὶ συνήθων ἑλκόμενον ὑπὸ τῶν ὑπηρετῶν τῶν τοῦ Φαννίου, παρῆλθε καὶ οὐ προσήμυνεν, εἴτε τὴν ἰσχὺν ἐπιλείπουσαν ἤδη δεδιὼς ἐλέγχειν, εἴτε μὴ βουλόμενος, ὡς ἔλεγεν, ἁψιμαχίας αὐτὸς καὶ συμπλοκῆς ἀρχὰς ζητοῦσι τοῖς ἐχθροῖς παρασχεῖν.", "st": "CG 12.1"}, {"sp": "N", "t": "συνέτυχε δὲ αὐτῷ καὶ πρός τοὺς συνάρχοντας ἐν ὀργῇ γενέσθαι διὰ τοιαύτην αἰτίαν. ἔμελλεν ὁ δῆμος θεᾶσθαι μονομάχους ἐν ἀγορᾷ, καὶ τῶν ἀρχόντων οἱ πλεῖστοι θεωρητήρια κύκλῳ κατασκευάσαντες ἐξεμίσθουν. ταῦτα ὁ Γάιος ἐκέλευεν αὐτοὺς καθαιρεῖν, ὅπως οἱ πένητες ἐκ τῶν τόπων ἐκείνων ἀμισθὶ θεάσασθαι δύνωνται. μηδενὸς δὲ προσέχοντος ἀναμείνας τὴν πρὸ τῆς θέας νύκτα, καὶ τῶν τεχνιτῶν ὅσους εἶχεν ἐργολάβους ὑφ’ ἑαυτῷ παραλαβών, τὰ θεωρητήρια καθεῖλε καὶ τῷ δήμῳ σχολάζοντα μεθ’ ἡμέραν ἀπέδειξε τὸν τόπον ἐφ’ ᾧ τοῖς μὲν πολλοῖς ἀνὴρ ἔδοξεν εἶναι, τοὺς δὲ συνάρχοντας ὡς ἰταμὸς καὶ βίαιος ἐλύπησεν. ἐκ τούτου καὶ τὴν τρίτην ἔδοξε δημαρχίαν ἀφῃρῆσθαι, ψήφων μὲν αὐτῷ πλείστων γενομένων, ἀδίκως δὲ καὶ κακούργως τῶν συναρχόντων ποιησαμένων τὴν ἀναγόρευσιν καὶ ἀνάδειξιν. ἀλλὰ ταῦτα μὲν ἀμφισβήτησιν εἶχεν. ἤνεγκε δὲ οὐ μετρίως ἀποτυχών, καὶ πρός γε τοὺς ἐχθροὺς ἐπεγγελῶντας αὐτῷ λέγεται θρασύτερον τοῦ δέοντος εἰπεῖν ὡς Σαρδόνιον γέλωτα γελῶσιν, οὐ γιγνώσκοντες ὅσον αὐτοῖς σκότος ἐκ τῶν αὐτοῦ περικέχυται πολιτευμάτων.", "st": "CG 12.3"}, {"sp": "N", "t": "ἐπεὶ δὲ καὶ τὸν Ὀπίμιον καταστήσαντες ὕπατον τῶν νόμων πολλοὺς διέγραφον καὶ τὴν Καρχηδόνος ἐκίνουν διάταξιν, ἐρεθίζοντες τὸν Γάϊον, ὡς ἂν αἰτίαν ὀργῆς παρασχὼν ἀναιρεθείη, τὸν μὲν πρῶτον χρόνον ἐκαρτέρει, τῶν δὲ φίλων καὶ μάλιστα τοῦ Φουλβίου παροξύνοντος ὥρμησε πάλιν συνάγειν τοὺς ἀντιταξομένους πρὸς τὸν ὕπατον. ἐνταῦθα καὶ τὴν μητέρα λέγουσιν αὐτῷ συστασιάσαι, μισθουμένην ἀπὸ τῆς ξένης κρύφα καὶ πέμπουσαν εἰς ’ Ῥώμην ἄνδρας, ὡς δὴ θεριστάς ταῦτα γὰρ ἐν τοῖς ἐπιστολίοις αὐτῆς ᾐνιγμένα γεγράφθαι πρὸς τὸν υἱόν. ἕτεροι δὲ καὶ πάνυ τῆς Κορνηλίας δυσχεραινούσης ταῦτα πράττεσθαι λέγουσιν.", "st": "CG 13.1"}, {"sp": "N", "t": "ἧι δ’ οὖν ἔμελλον ἡμέρᾳ τοὺς νόμους λύσειν οἱ περὶ τὸν Ὀπίμιον, κατείληπτο μὲν ὑπὸ ἀμφοτέρων ἕωθεν εὐθὺς τὸ Καπετώλιον, θύσαντος δὲ τοῦ ὑπάτου τῶν ὑπηρετῶν τις αὐτοῦ Κόιντος Ἀντύλλιος διαφέρων ἑτέρωσε τὰ σπλάγχνα πρὸς τοὺς περὶ τὸν Φούλβιον εἶπε· δότε τόπον ἀγαθοῖς, κακοὶ πολῖται. τινὲς δέ φασιν ἅμα τῇ φωνῇ ταύτῃ καὶ τὸν βραχίονα γυμνὸν οἷον ἐφ’ ὕβρει σχηματίζοντα παρενεγκεῖν. ἀποθνῄσκει γοῦν εὐθὺς ὁ Ἀντύλλιος ἐκεῖ μεγάλοις γραφείοις κεντούμενος, ἐπ’ αὐτῷ τούτῳ πεποιῆσθαι λεγομένοις. καὶ τὸ μὲν πλῆθος διεταράχθη πρὸς τὸν φόνον, ἐναντία δὲ τοὺς ἡγεμόνας ἔσχε διάθεσις. ὁ μὲν γὰρ Γάιος ἤχθετο καὶ κακῶς ἔλεγε τοὺς περὶ αὑτόν ὡς αἰτίαν δεομένοις πάλαι καθ’ ἑαυτῶν τοῖς ἐχθροῖς δεδωκότας, ὁ δὲ Ὀπίμιος ὥσπερ ἐνδόσιμον λαβὼν ἐπῆρτο καὶ παρώξυνε τὸν δῆμον ἐπὶ τὴν ἄμυναν.", "st": "CG 13.3"}, {"sp": "N", "t": "καὶ τότε μὲν ὄμβρου γενομένου διελύθησαν ἅμα δὲ ἡμέρᾳ τὴν μὲν βουλὴν ὁ ὕπατος συναγαγὼν ἔνδον ἐχρημάτιζεν, ἕτεροι δὲ τὸ τοῦ Ἀντυλλίου σῶμα γυμνὸν ἐπὶ κλίνης προθέμενοι δι’ ἀγορᾶς παρὰ τὸ βουλευτήριον ἐπίτηδες παρεκόμιζον, οἰμωγῇ χρώμενοι καὶ θρήνῳ, γιγνώσκοντος μὲν τοῦ Ὀπιμίου τὰ πραττόμενα, προσποιουμένου δὲ θαυμάζειν, ὥστε καὶ τοὺς βουλευτὰς προελθεῖν. κατατεθείσης δὲ τῆς κλίνης εἰς μέσον οἱ μὲν ἐσχετλίαζον ὡς ἐπὶ δεινῷ καὶ μεγάλῳ πάθει, τοῖς δὲ πολλοῖς ἐπῄει μισεῖν καὶ προβάλλεσθαι τοὺς ὀλιγαρχικούς, ὡς Τιβέριον μὲν Γράγχον ἐν Καπετωλίῳ φονεύσαντες αὐτοὶ δήμαρχον ὄντα καὶ τὸν νεκρὸν προσεξέβαλον, ὁ δ’ ὑπηρέτης Ἀντύλλιος, οὐ δίκαια μὲν ἴσως πεπονθώς, τὴν δὲ πλείστην αἰτίαν εἰς τὸ παθεῖν αὑτῷ παρασχών, ἐν ἀγορᾷ πρόκειται, καὶ περιέστηκεν ἡ Ῥωμαίων βουλή θρηνοῦσα καὶ συνεκκομίζουσα μισθωτὸν ἄνθρωπον, ἐπὶ τῷ τὸν ἔτι λειπόμενον ἀνελεῖν τῶν τοῦ δήμου κηδομένων. ἐκ τούτου πάλιν εἰς τὸ βουλευτήριον ἀπελθόντες ἐψηφίσαντο καὶ προσέταξαν Ὀπιμίῳ τῷ ὑπάτῳ σῴζειν τὴν πόλιν ὅπως δύναιτο, καὶ καταλύειν τοὺς τυράννους.", "st": "CG 14.1"}, {"sp": "N", "t": "ἐκείνου δὲ προειπόντος ἐπὶ τὰ ὅπλα χωρεῖν τοὺς συγκλητικούς, καὶ τῶν ἱππέων ἑκάστῳ παράγγελμα δόντος ἄγειν ἕωθεν οἰκέτας δύο καθωπλισμένους, ὁ μὲν Φούλβιος ἀντιπαρεσκευάζετο καὶ συνῆγεν ὄχλον, ὁ δὲ Γάιος ἐκ τῆς ἀγορᾶς ἀπερχόμενος ἔστη κατὰ τὸν τοῦ πατρὸς ἀνδριάντα, καὶ πολὺν χρόνον ἐμβλέψας εἰς αὐτὸν οὐδὲν ἐφθέγξατο, δακρύσας δὲ καὶ στενάξας ἀπῄει. τοῦτο πολλοῖς τῶν ἰδόντων οἰκτεῖραι τὸν Γάιον ἐπῆλθε· καὶ κακίσαντες αὑτοὺς ὡς ἐγκαταλείποντες τὸν ἄνδρα καὶ προδιδόντες ἧκον ἐπὶ τὴν οἰκίαν καὶ παρενυκτέρευον ἐπὶ τῶν θυρῶν, οὐχ ὁμοίως τοῖς τὸν Φούλβιον φυλάττουσιν. ἐκεῖνοι μὲν γὰρ ἐν κρότοις καὶ ἀλαλαγμοῖς πίνοντες καὶ θρασυνόμενοι διετέλεσαν, αὐτοῦ τοῦ Φουλβίου πρώτου μεθυσκομένου καὶ πολλὰ φορτικῶς παρ’ ἡλικίαν φθεγγομένου καὶ πράττοντος· οἱ δὲ περὶ τὸν Γάϊον, ὡς ἐπὶ συμφορᾷ κοινῇ τῆς πατρίδος ἡσυχίαν ἄγοντες καὶ περισκοπούμενοι τὸ μέλλον, ἐν μέρει φυλάττοντες καὶ ἀναπαυόμενοι διῆγον.", "st": "CG 14.4"}, {"sp": "N", "t": "ἅμα δὲ ἡμέρᾳ τὸν μὲν Φούλβιον ἐκ τοῦ πότου καθεύδοντα μόλις ἐπεγείραντες ὡπλίζοντο τοῖς περὶ τὴν οἰκίαν αὐτοῦ λαφύροις, ἃ Γαλάτας νενικηκὼς ὅτε ὑπάτευεν εἰλήφει, καὶ μετὰ πολλῆς ἀπειλῆς καὶ κραυγῆς ἐχώρουν καταληψόμενοι τὸν Ἀβεντῖνον λόφον. ὁ δὲ Γάιος ὁπλίσασθαι μὲν οὐκ ἠθέλησεν, ἀλλ’ ὥσπερ εἰς ἀγορὰν ἐν τηβέννῳ προῄει, μικρὸν ὑπεζωσμένος ἐγχειρίδιον, ἐξιόντι δὲ αὐτῷ περὶ τὰς θύρας ἡ γυνὴ προσπεσοῦσα καὶ περιπτύξασα τῶν χειρῶν τῇ μὲν αὐτὸν ἐκεῖνον, τῇ δὲ τὸ παιδίον, οὐκ ἐπὶ τὸ βῆμά σε, εἶπεν, ὦ Γάιε, προπέμπω δήμαρχον, ὡς πρότερον, καὶ νομοθέτην, οὐδ’ ἐπὶ πόλεμον ἔνδοξον, ἵνα μοι καὶ παθών τι τῶν κοινῶν ἀπολίπῃς τιμώμενον γοῦν πένθος, ἀλλὰ τοῖς Τιβερίου φονεῦσιν ὑποβάλλεις ἑαυτόν, ἄνοπλον μὲν καλῶς, ἵνα πάθῃς τι μᾶλλον ἢ δράσῃς, πρὸς οὐδὲν δὲ τοῖς κοινοῖς ὄφελος ἀπολεῖ. κεκράτηκεν ἤδη τὰ χείρω· βίᾳ καὶ σιδήρῳ τὰς δίκας πράττουσιν. εἰ περὶ Νομαντίαν ὁ σὸς ἀδελφὸς ἔπεσεν, ὑπόσπονδος ἂν ἡμῖν ἀπεδόθη νεκρός· νῦν δὲ ἴσως κἀγὼ ποταμοῦ τινος ἢ θαλάττης ἱκέτις ἔσομαι φῆναί ποτε τὸ σὸν σῶμα φρουρούμενον. τί γὰρ ἢ νόμοις ἔτι πιστὸν ἢ θεοῖς μετὰ τὸν Τιβερίου φόνον; τοιαῦτα τῆς Λικιννίας ὀδυρομένης, ἀτρέμα τὰς περιβολὰς ἀπολυσάμενος αὐτῆς ὁ Γάϊος ἐχώρει σιωπῇ μετὰ τῶν φίλων, ἡ δὲ τοῦ ἱματίου λαβέσθαι γλιχομένη καταρρυεῖσα πρὸς τοὔδαφος ἔκειτο πολὺν χρόνον ἄναυδος, μέχρι οὗ λιποθυμήσασαν αὐτὴν οἱ θεράποντες ἀράμενοι πρὸς Κράσσον ᾤχοντο τὸν ἀδελφὸν κομίζοντες.", "st": "CG 15.1"}, {"sp": "N", "t": "ὁ δὲ Φούλβιος, ὡς ἐγένοντο πάντες ἀθρόοι, πεισθεὶς ὑπὸ τοῦ Γαΐου πέμπει τῶν υἱῶν τὸν νεώτερον ἔχοντα κηρύκειον εἴς ἀγοράν. ἦν δὲ κάλλιστος ὁ νεανίσκος ὀφθῆναι· καὶ τότε καταστὰς κοσμίως καὶ μετ’ αἰδοῦς δεδακρυμένος ἐποιήσατο συμβατικοὺς λόγους πρὸς τὸν ὕπατον καὶ τὴν σύγκλητον. οἱ μὲν οὖν πολλοὶ τῶν παρόντων οὐκ ἀηδῶς πρὸς τὰς διαλύσεις εἶχον· ὁ δὲ Ὀπίμιος οὐ δι’ ἀγγέλων ἔφη χρῆναι πείθειν τὴν σύγκλητον, ἀλλὰ καταβάντας ὡς ὑπευθύνους πολίτας ἐπὶ κρίσιν καὶ παραδόντας αὑτούς οὕτως παραιτεῖσθαι τὴν ὀργήν τῷ δὲ μειρακίῳ καὶ διηγόρευσεν ἐπὶ τούτοις κατιέναι πάλιν ἢ μὴ κατιέναι. Γάιος μὲν οὖν, ὥς φασιν, ἐβούλετο βαδίζειν καὶ πείθειν τὴν σύγκλητον οὐδενὸς δὲ τῶν ἄλλων συγχωροῦντος, αὖθις ἔπεμψεν ὁ Φούλβιος τὸν παῖδα διαλεξόμενον ὑπὲρ αὐτῶν ὅμοια τοῖς προτέροις. ὁ δὲ Ὀπίμιος σπεύδων μάχην συνάψαι τὸ μὲν μειράκιον εὐθὺς συνέλαβε καὶ παρέδωκεν εἴς φυλακήν, τοῖς δὲ περὶ τὸν Φούλβιον ἐπῄει μετὰ πολλῶν ὁπλιτῶν καὶ τοξοτῶν Κρητῶν, οἳ μάλιστα βάλλοντες αὑτούς καὶ κατατραυματίζοντες συνετάραξαν. γενομένης δὲ τῆς τροπῆς ὁ μὲν Φούλβιος εἴς τι βαλανεῖον ἠμελημένον καταφυγὼν καὶ μετὰ μικρὸν ἀνευρεθεὶς κατεσφάγη μετὰ τοῦ πρεσβυτέρου παιδός, ὁ δὲ Γάιος ὤφθη μὲν ὑπ’ οὐδενὸς μαχόμενος, ἀλλὰ δυσανασχετῶν τοῖς γινομένοις ἀνεχώρησεν εἴς τὸ τῆς Ἀρτέμιδος ἱερόν ἐκεῖ δὲ βουλόμενος ἑαυτὸν ἀνελεῖν ὑπὸ τῶν πιστοτάτων ἑταίρων ἐκωλύθη, Πομπωνίου καὶ Λικιννίου· παρόντες γὰρ οὗτοι τό τε ξίφος ἀφείλοντο καὶ πάλιν φεύγειν ἐπῆραν αὐτόν. ἔνθα δὴ λέγεται καθεσθεὶς εἴς γόνυ καὶ τὰς χεῖρας ἀνατείνας πρὸς τὴν θεὸν ἐπεύξασθαι τὸν Ῥωμαίων δῆμον ἀντὶ τῆς ἀχαριστίας ἐκείνης καὶ προδοσίας μηδέποτε παύσασθαι δουλεύοντα· φανερῶς γὰρ οἱ πλεῖστοι μετεβάλλοντο κηρύγματι δοθείσης ἀδείας.", "st": "CG 16.1"}, {"sp": "N", "t": "φεύγοντι δ’ οὖν τῷ Γαΐῳ τῶν ἐχθρῶν ἐπιφερομένων καὶ καταλαμβανόντων περὶ τὴν ξυλίνην γέφυραν, οἱ μὲν δύο φίλοι προχωρεῖν ἐκεῖνον κελεύσαντες αὐτοὶ τοὺς διώκοντας ὑπέστησαν καὶ μαχόμενοι πρὸ τῆς γεφύρας οὐδένα παρῆκαν ἕως ἀπέθανον. τῷ δὲ Γαΐῳ συνέφευγεν εἷς οἰκέτης ὄνομα Φιλοκράτης, πάντων μὲν, ὥσπερ ἐν ἁμίλλῃ, παρακελευομένων, οὐδενὸς δὲ βοηθοῦντος, οὐδὲ ἵππον αἰτουμένῳ παρασχεῖν ἐθελήσαντος ἐπέκειντο γὰρ ἐγγὺς οἱ διώκοντες. ὁ δὲ φθάνει μικρὸν εἰς ἱερὸν ἄλσος Ἐριννύων καταφυγών, κἀκεῖ διαφθείρεται, τοῦ Φιλοκράτους ἀνελόντος ἐκεῖνον, εἶτα ἑαυτὸν ἐπισφάξαντος. ὡς δὲ ἔνιοί φασιν, ἀμφότεροι μὲν ὑπὸ τῶν πολεμίων κατελήφθησαν ζῶντες, τοῦ δὲ θεράποντος τὸν δεσπότην περιβαλόντος οὐδεὶς ἐκεῖνον ἠδυνήθη πατάξαι πρότερον ἢ τοῦτον ὑπὸ πολλῶν παιόμενον ἀναιρεθῆναι. τὴν δὲ κεφαλὴν τοῦ Γαΐου λέγουσιν ἄλλον μὲν ἀποκόψαι καὶ κομίζειν, ἀφελέσθαι δὲ τούτου φίλον Ὀπιμίου τινὰ, Σεπτουμουλήιον ἦν γὰρ προκεκηρυγμένον ἐν ἀρχῇ τῆς μάχης ἰσοστάσιον χρυσίον τοῖς ἀνενεγκοῦσι τὴν Γαΐου καὶ Φουλβίου κεφαλήν. ἀνηνέχθη δὲ ὑπὸ τοῦ Σεπτουμουληΐου περιπεπαρμένη δόρατι πρὸς τὸν Ὀπίμιον, καὶ ζυγοῦ κομισθέντος ἐντεθεῖσα λίτρας ἑπτακαίδεκα καὶ δίμοιρον εἵλκυσε, τοῦ Σεπτουμουληίου καὶ περὶ τοῦτο μιαροῦ γενομένου καὶ κακουργήσαντος ἐξελὼν γὰρ τὸν ἐγκέφαλον ἐνέτηξε μόλυβδον. οἱ δὲ τοῦ Φουλβίου τὴν κεφαλὴν κομίσαντες ἦσαν γὰρ τῶν ἀσημοτέρων οὐδὲν ἔλαβον. τὰ δὲ σώματα καὶ τούτων καὶ τῶν ἄλλων εἰς τὸν ποταμὸν ἐρρίφη, τρισχιλίων ἀναιρεθέντων· καὶ τὰς οὐσίας αὐτῶν ἀπέδοντο πρὸς τὸ δημόσιον. ἀπεῖπαν δὲ πενθεῖν ταῖς γυναιξί, τὴν δὲ Γαΐου Λικιννίαν καὶ τῆς προικὸς ἀπεστέρησαν. ὠμότατον δὲ προσειργάσαντο τοῦ Φουλβίου τὸν νεώτερον υἱόν, οὔτε χεῖρας ἀνταράμενον οὔτ’ ἐν τοῖς μαχομένοις γενόμενον, ἀλλὰ ἐπὶ σπονδὰς ἐλθόντα πρὸ τῆς μάχης συλλαβόντες καὶ μετὰ τὴν μάχην ἀνελόντες. οὐ μὴν ἀλλὰ καὶ τούτου καὶ τῶν ἄλλων ἁπάντων μᾶλλον ἠνίασε τοὺς πολλοὺς τὸ κατασκευασθὲν Ὁμονοίας ἱερὸν ὑπὸ τοῦ Ὀπιμίου· σεμνύνεσθαι γὰρ ἐδόκει καὶ μέγα φρονεῖν καὶ τρόπον τινὰ θριαμβεύειν ἐπὶ φόνοις τοσούτοις πολιτῶν, διὸ καὶ νυκτὸς ὑπὸ τὴν ἐπιγραφὴν τοῦ νεὼ παρενέγραψάν τινες τὸν στίχον τοῦτον· ἔργον ἀπονοίας ναὸν ὁμονοίας ποιεῖ.", "st": "CG 17.1"}, {"sp": "N", "t": "οὗτος μέντοι πρῶτος ἐξουσίᾳ δικτάτορος ἐν ὑπατείᾳ χρησάμενος καὶ κατακτείνας ἀκρίτους ἐπὶ τρισχιλίοις πολίταις Γάιον Γράγχον καὶ Φούλβιον Φλάκκον, ὧν ὁ μὲν ἦν ὑπατικὸς καὶ θριαμβικός, ὁ δὲ τῆς καθ’ αὑτὸν ἡλικίας ἀρετῇ καὶ δόξῃ πεπρωτευκώς, οὐκ ἀπέσχετο κλοπῆς, ἀλλὰ πεμφθεὶς ὡς Ἰουγούρθαν τὸν Νομάδα πρεσβευτής διεφθάρη χρήμασιν ὑπ’ αὐτοῦ· καὶ δίκην ὀφλὼν αἰσχίστην δωροδοκίας ἐν ἀτιμίᾳ κατεγήρασε μισούμενος καὶ προπηλακιζόμενος ὑπὸ τοῦ δήμου, παρ’ αὐτὰ μὲν τὰ πραχθέντα ταπεινοῦ γενομένου καὶ συσταλέντος, ὀλίγῳ δὲ ὕστερον ἐκφήναντος ὅσον εἶχεν ἱμέρου καὶ πόθου τῶν Γράγχων. εἰκόνας τε γὰρ αὐτῶν ἀναδείξαντες ἐν φανερῷ προὐτίθεντο, καὶ τοὺς τόπους ἐν οἷς ἐφονεύθησαν ἀφιερώσαντες ἀπήρχοντο μὲν ὧν ὧραι φέρουσι πάντων, ἔθυον δὲ καὶ καθ’ ἡμέραν πολλοὶ καὶ προσέπιπτον, ὥσπερ θεῶν ἱεροῖς ἐπιφοιτῶντες.", "st": "CG 18.1"}, {"sp": "N", "t": "καὶ μέντοι καὶ ἡ Κορνηλία λέγεται τά τε ἄλλα τῆς συμφορᾶς εὐγενῶς καὶ μεγαλοψύχως ἐνεγκεῖν, καὶ περὶ τῶν ἱερῶν ἐν οἷς ἀνῃρέθησαν εἰπεῖν ὡς ἀξίους οἱ νεκροὶ τάφους ἔχουσιν, αὕτη δὲ περὶ τοὺς καλουμένους Μισηνοὺς διέτριβεν, οὐδὲν μεταλλάξασα τῆς συνήθους διαίτης. ἦν δὲ πολύφιλος καὶ διὰ φιλοξενίαν εὐτράπεζος, ἀεὶ μὲν Ἑλλήνων καὶ φιλολόγων περὶ αὐτὴν ὄντων, ἁπάντων δὲ τῶν βασιλέων καὶ δεχομένων παρ’ αὐτῆς δῶρα καὶ πεμπόντων, ἡδίστη μὲν οὖν ἦν αὕτη τοῖς ἀφικνουμένοις καὶ συνοῦσι διηγουμένη τὸν τοῦ πατρὸς Ἀφρικανοῦ βίον καὶ δίαιταν, θαυμασιωτάτη δὲ τῶν παίδων ἀπενθὴς καὶ ἀδάκρυτος μνημονεύουσα, καὶ πάθη καὶ πράξεις αὐτῶν, ὥσπερ ἀρχαίων τινῶν, ἐξηγουμένη τοῖς πυνθανομένοις. ὅθεν ἔδοξεν ἐνίοις ἔκνους ὑπὸ γήρως ἢ μεγέθους κακῶν γεγονέναι καὶ τῶν ἀτυχημάτων ἀναίσθητος, αὐτοῖς ὡς ἀληθῶς ἀναισθήτοις οὖσιν ὅσον ἐξ εὐφυΐας καὶ τοῦ γεγονέναι καὶ τετράφθαι καλῶς ὄφελός ἐστι πρὸς ἀλυπίαν ἀνθρώποις, καὶ ὅτι τῆς ἀρετῆς ἡ τύχη φυλαττομένης μὲν τὰ κακὰ πολλάκις περίεστιν, ἐν δὲ τῷ πταῖσαι τὸ φέρειν εὐλογίστως οὐ παραιρεῖται.", "st": "CG 19.1"}, {"sp": "HDR", "t": "Ἄγιδος καὶ Κλεομένους καὶ Γράγχων σύγκρισις"}, {"sp": "N", "t": "ἡμῖν δὲ καὶ ταύτης πέρας ἐχούσης τῆς διηγήσεως ὑπολείπεται λαβεῖν ἐκ παραλλήλου τῶν βίων τὴν ἀποθεώρησιν, τοὺς μὲν οὖν Γράγχους οὐδ’ οἱ πάνυ τἆλλα κακῶς λέγοντες καὶ μισοῦντες ἐτόλμησαν εἰπεῖν ὡς οὐκ εὐφυέστατοι πρὸς ἀρετὴν ἐγένοντο Ῥωμαίων ἁπάντων, καὶ τροφῆς τε καὶ παιδεύσεως ἐκπρεποῦς ἔτυχον· ἡ δὲ Ἄγιδος καὶ Κλεομένους φύσις ἐρρωμενεστέρα φαίνεται τῆς ἐκείνων γενομένη, παρ’ ὅσον οὔτε παιδείας μεταλαβόντες ὀρθῆς, ἔθεσί τε καὶ διαίταις ἐντραφέντες ὑφ’ ὧν οἱ πρεσβύτεροι πάλαι διεφθόρεισαν, αὑτοὺς ἡγεμόνας εὐτελείας καὶ σωφροσύνης παρέσχον. ἔτι δὲ οἱ μέν, ὅτε λαμπρότατον εἶχεν ἡ Ῥώμη καὶ μέγιστόν ἀξίωμα καὶ καλῶν ἔργων ζῆλον, ὥσπερ διαδοχὴν ἀρετῆς πατρῴας καὶ προγονικῆς ᾐσχύνθησαν ἐγκαταλιπεῖν οἱ δὲ καὶ πατέρων τἀναντία προῃρημένων γεγονότες, καὶ τὴν πατρίδα μοχθηρὰ πράττουσαν καὶ νοσοῦσαν παραλαβόντες, οὐδέν τι διὰ ταῦτα τὴν πρὸς τὸ καλὸν ἀπήμβλυναν ὁρμήν. καὶ μὴν τῆς γε Γράγχων ἀφιλοχρηματίας καὶ πρὸς ἀργύριον ἐγκρατείας μέγιστόν ἐστιν ὅτι λημμάτων ἀδίκων καθαροὺς ἐν ἀρχαῖς καὶ πολιτείαις διεφύλαξαν ἑαυτούς· Ἆγις δὲ κἂν διηγανάκτησεν ἐπὶ τῷ μηδὲν ἀλλότριον λαβεῖν ἐπαινούμενος, ὃς τὴν οὐσίαν τὴν ἑαυτοῦ τοῖς πολίταις ἐπέδωκεν, ἄνευ τῶν ἄλλων κτημάτων ἑξακόσια τάλαντα νομίσματος ἔχουσαν. πηλίκον οὖν ἐνόμιζε κακὸν εἶναι τὸ κερδαίνειν ἀδίκως ὁ καὶ δικαίως πλέον ἔχειν ἑτέρου πλεονεξίαν ἡγούμενος;", "st": "Comp. Ag.–Cleom.–Gracch. 1.1"}, {"sp": "N", "t": "ἥ γε μὴν ἐπιβουλὴ καὶ τόλμα τῶν καινοτομουμένων πολὺ τῷ μεγέθει παρήλλαττεν. ἐπολιτεύοντο γὰρ ὁ μὲν ὁδῶν κατασκευὰς καὶ πόλεων κτίσεις, καὶ τὸ πάντων νεανικώτατον ἦν Τιβερίῳ μὲν ἀνασῶσαι δημοσίους ἀγρούς, Γαΐῳ δὲ μῖξαι τὰ δικαστήρια προσεμβαλόντι τῶν ἱππικῶν τριακοσίους· ὁ δὲ Ἄγιδος καὶ Κλεομένους νεωτερισμός, τὸ μικρὰ καὶ κατὰ μέρος τῶν ἡμαρτημένων ἰᾶσθαι καὶ ἀποκόπτειν ὕδραν τινὰ τέμνοντος, ὥς φησιν ὁ Πλάτων, ἡγησάμενος εἶναι, τὴν ἅμα πάντα ἀπαλλάξαι κακὰ καὶ μετασκευάσαι δυναμένην μεταβολὴν ἐπῆγε τοῖς πράγμασιν. ἀληθέστερον δ’ ἴσως εἰπεῖν ἐστιν ὅτι τὴν πάντα ἀπεργασαμένην κακὰ μεταβολὴν ἐξήλαυνεν, ἀπάγων καὶ καθιστὰς εἰς τὸ οἰκεῖον σχῆμα τὴν πόλιν. ἐπεὶ καὶ τοῦτο ἄν τις εἴποι, τῇ μὲν Γράγχων πολιτείᾳ τοὺς μεγίστους ἐνίστασθαι Ῥωμαίων, οἷς δὲ Ἆγις ἐνεχείρησε, Κλεομένης δὲ τὸ ἔργον ἐπέθηκε, τῶν παραδειγμάτων τὸ κάλλιστον ὑπέκειτο καὶ μεγαλοπρεπέστατον, αἱ πάτριοι ῥῆτραι περὶ σωφροσύνης καὶ ἰσότητος, ὧν τούτοις μὲν ὁ Λυκοῦργος, ἐκείνῳ δὲ ὁ Πύθιος βεβαιωτής. ὃ δὲ μέγιστον, ὅτι τοῖς μὲν ἐκείνων πολιτεύμασιν εἰς οὐδὲν ἡ Ῥώμη μεῖζον ἐπέδωκε τῶν ὑπαρχόντων, ἐκ δὲ ὧν ὁ Κλεομένης ἔπραξεν, ὀλίγου χρόνου τὴν Σπάρτην τῆς Πελοποννήσου κρατοῦσαν ἡ Ἑλλὰς ἐπεῖδε καὶ τοῖς τότε μέγιστον δυναμένοις διαγωνιζομένην ἀγῶνα τὸν περὶ τῆς ἡγεμονίας, οὗ τέλος ἦν ἀπαλλαγεῖσαν Ἰλλυρικῶν ὅπλων καὶ Γαλατικῶν τὴν Ἑλλάδα κοσμεῖσθαι πάλιν ὑφ’ Ἡρακλείδαις.", "st": "Comp. Ag.–Cleom.–Gracch. 2.1"}, {"sp": "N", "t": "οἶμαι δὲ καὶ τὰς τελευτὰς τῶν ἀνδρῶν ἐμφαίνειν τινὰ τῆς ἀρετῆς διαφοράν. ἐκεῖνοι μὲν γὰρ μαχόμενοι πρὸς τοὺς πολίτας, εἶτα φεύγοντες ἐτελεύτησαν· τούτων δὲ Ἆγις μὲν ὑπὲρ τοῦ μηδένα κτεῖναι τῶν πολιτῶν ὀλίγου δεῖν ἑκὼν ἀπέθανε, Κλεομένης δὲ προπηλακισθεὶς καὶ ἀδικηθεὶς ὥρμησε μέν ἀμύνασθαι, τοῦ δὲ καιροῦ μὴ παρασχόντος αὑτὸν εὐτόλμως ἀνεῖλε. πάλιν δὲ τἀναντία σκοποῦσιν Ἆγις μὲν οὐδὲν ἀπεδείξατο στρατηγίας ἔργον, ἀλλὰ προανῃρέθη, ταῖς δὲ Κλεομένους νίκαις πολλαῖς καὶ καλαῖς γενομέναις παραβαλεῖν ἔστι Τιβερίου τὴν ἐν Καρχηδόνι τοῦ τείχους κατάληψιν, οὐ μικρὸν ἔργον, καὶ τὰς ἐν Νομαντίᾳ σπονδάς, αἷς δισμυρίους Ῥωμαίων στρατιώτας οὐκ ἔχοντας ἄλλην ἐλπίδα σωτηρίας περιεποίησε καὶ Γάιος δὲ πολλὴν μὲν αὐτόθι, πολλὴν δὲ ἐν Σαρδόνι στρατευόμενος ἀνδραγαθίαν ἔφηνεν, ὥστε τοῖς πρώτοις ἂν ἐναμίλλους Ῥωμαίων γενέσθαι στρατηγοῖς, εἰ μὴ προανῃρέθησαν.", "st": "Comp. Ag.–Cleom.–Gracch. 3.1"}, {"sp": "N", "t": "τῆς δὲ πολιτείας ὁ μὲν Ἆγις ἔοικεν ἅψασθαι μαλακώτερον, ἐκκρουσθεὶς ὑπὸ Ἀγησιλάου καὶ ψευσάμενος τὸν ἀναδασμὸν τοῖς πολίταις, καὶ ὅλως ἐλλιπὴς καὶ ἀτελὴς ὧν προείλετο καὶ κατήγγειλεν ὑπὸ ἀτολμίας διὰ τὴν ἡλικίαν γενόμενος· ὁ δὲ Κλεομένης τοὐναντίον θρασύτερον καὶ βιαιότερον ἐπὶ τὴν μεταβολὴν ἦλθε τῆς πολιτείας, ἀποκτείνας τοὺς ἐφόρους παρανόμως, οὓς καὶ προσαγαγέσθαι τοῖς ὅπλοις κρατοῦντα καὶ μεταστῆσαι ῥᾴδιον ἦν, ὥσπερ οὐκ ὀλίγους ἄλλους μετέστησεν ἐκ τῆς πόλεως. τὸ γὰρ ἄνευ τῆς ἐσχάτης ἀνάγκης ἐπιφέρειν σίδηρον οὔτε ἰατρικὸν οὔτε πολιτικόν, ἀλλ’ ἀτεχνίας μὲν ἀμφότερα, τούτῳ δὲ καὶ τὸ ἀδικεῖν μετ’ ὠμότητος πρόσεστι. τῶν δὲ Γράγχων οὐδέτερος μὲν ἤρξατο σφαγῆς ἐμφυλίου, Γάιος δὲ λέγεται μηδὲ βαλλόμενος ὁρμῆσαι πρὸς ἄμυναν, ἀλλὰ λαμπρότατος ὢν ἐν τοῖς πολεμικοῖς ἀργότατος ἐν τῇ στάσει γενέσθαι. καὶ γὰρ προῆλθεν ἄοπλος καὶ μαχομένων ἀνεχώρησε, καὶ ὅλως πλείονα τοῦ μή τι δρᾶσαι πρόνοιαν ἢ τοῦ μὴ παθεῖν ἔχων ἑωρᾶτο. διὸ καὶ τὴν φυγὴν αὐτῶν οὐκ ἀτολμίας σημεῖον, ἀλλ’ εὐλαβείας ποιητέον. ἔδει γὰρ ὑπεῖξαι τοῖς ἐπιφερομένοις ἢ μένοντας ὑπὲρ τοῦ μὴ παθεῖν τῷ δρᾶν ἀμύνασθαι.", "st": "Comp. Ag.–Cleom.–Gracch. 4.1"}, {"sp": "N", "t": "τῶν τοίνυν ἐγκλημάτων τῶν κατὰ Τιβερίου μέγιστόν ἐστιν ὅτι τὸν συνάρχοντα τῆς δημαρχίας ἐξέβαλε καὶ δευτέραν αὐτὸς δημαρχίαν μετῄει· Γαΐῳ δὲ τὸν Ἀντυλλίου φόνον οὐ δικαίως οὐδὲ ἀληθῶς προσετρίβοντο διεφθάρη γὰρ ἄκοντος αὑτοῦ καὶ ἀγανακτοῦντος. Κλεομένης δέ, ἵνα τὰς σφαγὰς τῶν ἐφόρων ἐάσωμεν, ἠλευθέρωσε μὲν ἅπαντας τοὺς οἰκέτας, ἐβασίλευσε δὲ τῷ μὲν ἔργῳ μόνος, τῶ δὲ ὀνόματι δεύτερος, Εὐκλείδαν τὸν ἀδελφὸν ἐκ μιᾶς οἰκίας αὑτῷ προσελόμενος, Ἀρχίδαμον δέ, ᾧ προσῆκον ἦν ἀπὸ τῆς ἑτέρας οἰκίας ὄντι συμβασιλεύειν, ἔπεισε μὲν ἐκ Μεσσήνης κατελθεῖν, ἀποθανόντος δὲ τὸν φόνον οὐκ ἐπεξελθών ἐβεβαίωσε τὴν αἰτίαν καθ’ αὑτοῦ τῆς ἀναιρέσεως. καίτοι Λυκοῦργος, ὃν προσεποιεῖτο μιμεῖσθαι, τὴν μὲν βασιλείαν ἑκὼν ἀπέδωκε τῷ παιδὶ τοῦ ἀδελφοῦ Χαρίλλῳ, φοβούμενος δὲ μή, κἂν ἄλλως ἀποθάνῃ τὸ μειράκιον, αἰτία τις ἐπ’ αὐτὸν ἔλθῃ, πολὺν χρόνον ἔξω πλανηθεὶς οὐ πρότερον ἐπανῆλθεν ἢ παῖδα τῷ Χαρίλλῳ γενέσθαι διάδοχον τῆς ἀρχῆς, ἀλλὰ Λυκούργῳ μὲν οὐδὲ ἄλλος τις Ἑλλήνων παραβλητὸς οὐδείς· ὅτι δὲ τοῖς Κλεομένους πολιτεύμασι καινοτομίαι καὶ παρανομίαι μείζονες ἔνεισι, δεδήλωται. καὶ μὴν οἵ γε τὸν τρόπον αὑτῶν ψέγοντες τούτοις μὲν ἐξ ἀρχῆς τυραννικὸν καὶ πολεμοποιὸν αἰτιῶνται γενέσθαι, τῇ δὲ ἐκείνων φύσει φιλοτιμίας ἀμετρίαν, ἄλλο δὲ οὐδέν οἱ φθονοῦντες ἐπικαλεῖν εἶχον ἐκριπισθέντας δὲ τῷ πρὸς τοὺς ἐνισταμένους ἀγῶνι καὶ θυμῷ παρὰ τὴν αὑτῶν φύσιν ὥσπερ πνοαῖς, ἐφεῖναι περὶ τὰ ἔσχατα τὴν πολιτείαν ὡμολόγουν. ἐπεὶ τῆς γε πρώτης ὑποθέσεως τί κάλλιον ἢ δικαιότερον ἦν, εἰ μὴ κατὰ βίαν καὶ δυναστείαν ἐπιχειρήσαντες ἐξῶσαι τὸν νόμον οἱ πλούσιοι περιέστησαν ἀμφοτέροις ἀγῶνας, τῷ μὲν φοβουμένῳ ὑπὲρ αὑτοῦ, τῷ δὲ ἐκδικοῦντι τὸν ἀδελφόν ἄνευ δίκης καὶ δόγματος οὐδὲ ὑπ’ ἄρχοντος ἀναιρεθέντα;", "st": "Comp. Ag.–Cleom.–Gracch. 5.1"}, {"sp": "N", "t": "Συνορᾷς μὲν οὖν καὶ αὐτὸς ἐκ τῶν εἰρημένων τὴν διαφοράν εἰ δὲ δεῖ καὶ καθ’ ἕκαστον ἀποφήνασθαι, Τιβέριον μὲν ἀρετῇ πεπρωτευκέναι τίθημι πάντων, ἐλάχιστα δὲ ἡμαρτηκέναι τὸ μειράκιον Ἆγιν, πράξει δὲ καὶ τόλμῃ Γάϊον οὐκ ὀλίγῳ Κλεομένους ὕστερον γεγονέναι.", "st": "Comp. Ag.–Cleom.–Gracch. 5.6"}], []);})();
